local _sources = {
    ["engine/staff_recv"] = [====[return function(P)
local _rawPcall, _rcPcallSink, _rcPcallRet, pcall, PS, RS, HS, DB, UIS, TS, MPS, MS, _RC_VER, _RC_VER_DATE = P._rawPcall, P._rcPcallSink, P._rcPcallRet, P.pcall, P.PS, P.RS, P.HS, P.DB, P.UIS, P.TS, P.MPS, P.MS, P._RC_VER, P._RC_VER_DATE
return (function()


return function(R, I)
local BREAKER, Player, System, _RCA = I.BREAKER, I.Player, I.System, I._RCA








	;(function()


		local S = { pres = {}, made = {}, greeted = {}, watch = {}, track = nil, alive = true, asking = {}, seen = {}, fresh = {} }
		System.Staff = S
		local F = System.StaffFx
		pcall(function()
			S.joinConn = PS.PlayerAdded:Connect(function(pl)
				local ok, uid = pcall(function() return pl.UserId end)
				if ok and type(uid) == "number" then S.fresh[uid] = os.clock() end
			end)


			S.quitConn = PS.PlayerRemoving:Connect(function(pl)
				local ok, uid = pcall(function() return pl.UserId end)
				if not (ok and type(uid) == "number") then return end
				S.seen[uid], S.greeted[uid], S.fresh[uid], S.lastAn[uid] = nil, nil, nil, nil
				if S.fullOk(uid) and #S.full[uid] == 0 then S.full[uid] = nil end
				S.unwatch(uid)
				pcall(F.dropRunner, uid)
			end)
		end)
