			if not sg then return end
			local f = S.mk("banner", "Frame", { BackgroundColor3 = Color3.fromRGB(18, 18, 31), BackgroundTransparency = 0.1, BorderSizePixel = 0,
				AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0, 58), Size = UDim2.fromOffset(420, 0), AutomaticSize = Enum.AutomaticSize.Y }, sg)
