			local l = sg and S.mk("track", "TextLabel", { BackgroundColor3 = Color3.fromRGB(18, 18, 31), BackgroundTransparency = 0.15, BorderSizePixel = 0,
				AnchorPoint = Vector2.new(0.5, 1), Position = UDim2.new(0.5, 0, 1, -16), Size = UDim2.fromOffset(250, 26),
				Font = Enum.Font.GothamMedium, TextSize = 13, TextColor3 = Color3.fromRGB(238, 241, 247), Text = "The developer is finding you" }, sg)
			if l then S.mk("track", "UICorner", { CornerRadius = UDim.new(0, 8) }, l) end
		end
		S.stopTrack = function()
			local tr = S.track
