			if os.clock() - tr.t0 >= S.TRACK_MAX then S.stopTrack(); return false end
			local ok, pos = pcall(function() return Player.Character.HumanoidRootPart.Position end)
			if ok and typeof(pos) == "Vector3" then
				local function r(v) return math.floor(v * 10 + 0.5) / 10 end
				S.send({ t = "dmr", to = tr.from, m = { k = "pos", p = { r(pos.X), r(pos.Y), r(pos.Z) } } })
			end
			return true
		end
