System.StaffThemes.TAGS.error404 = function(K, head, C1, C2)
	local W = Color3.new(1, 1, 1)
	local INK = Color3.fromRGB(8, 10, 20)
	local VIO = Color3.fromRGB(130, 70, 255)
	local CS, CK = ColorSequence.new, ColorSequenceKeypoint.new
	local function c01(x) return math.clamp(x, 0, 1) end
	local MONO = Font.new("rbxasset://fonts/families/RobotoMono.json", Enum.FontWeight.Bold)
	local Wd, Hd = 7.2, 3.5
	local bb = K.board(head, Wd, Hd, 3.6)
	bb:SetAttribute("RCBadgeTop", 0.3)
	local function P(x, y) return UDim2.fromScale(x / Wd, y / Hd) end
	local function Z(w, h) return UDim2.fromScale(w / Wd, h / Hd) end
	local X0, Y0, WW, WH, TB = 0.6, 0.35, 6.0, 2.2, 0.42

	local fade = {}
	local function F(o, prop, base) fade[#fade + 1] = { o, prop, base } return o end
	F(K.img(bb, { Image = K.T("glowui.png"), ImageColor3 = C2, ImageTransparency = 1, AnchorPoint = Vector2.new(0.5, 0.5),
		Position = P(3.6, 1.45), Size = Z(7.6, 3.2), ZIndex = 0 }), "ImageTransparency", 0.8)
