	F(K.frame(bb, { BackgroundColor3 = INK, Position = P(X0, Y0), Size = Z(WW, WH), ZIndex = 2 }), "BackgroundTransparency", 0.08)
	local bar = F(K.frame(bb, { BackgroundColor3 = W, Position = P(X0, Y0), Size = Z(WW, TB), ZIndex = 3 }), "BackgroundTransparency", 0)
	K.new("UIGradient", { Color = CS({ CK(0, C1), CK(0.5, VIO), CK(1, C2) }) }, bar)

	local grey = K.frame(bb, { BackgroundColor3 = Color3.fromRGB(70, 70, 84), Position = P(X0, Y0), Size = Z(WW, TB), ZIndex = 4 })
	local title = F(K.text(bb, { Position = P(X0 + 0.15, Y0 + 0.07), Size = Z(3.8, TB - 0.14), Text = "ERROR_404.EXE", FontFace = MONO, TextColor3 = W,
		TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 5 }), "TextTransparency", 0)
	for i, s in ipairs({ "_", "o", "x" }) do
		local f = F(K.frame(bb, { BackgroundColor3 = i == 3 and Color3.fromRGB(205, 30, 95) or INK, Position = P(X0 + WW - 0.1 - (4 - i) * 0.37, Y0 + 0.07),
			Size = Z(0.31, 0.28), ZIndex = 5 }), "BackgroundTransparency", 0.05)
		F(K.text(f, { Size = UDim2.fromScale(1, 1), Text = s, FontFace = MONO, TextColor3 = W, ZIndex = 6 }), "TextTransparency", 0)
	end

	local NSL = 5
	local MY0, MH = Y0 + TB + 0.12, 1.1
	local sl = {}
	for i = 1, NSL do
		local y0, h = MY0 + (i - 1) / NSL * MH, MH / NSL
		local f = K.frame(bb, { ClipsDescendants = true, Position = P(X0, y0), Size = Z(WW, h), ZIndex = 6 })
		local hold = K.frame(f, { Size = UDim2.fromScale(1, MH / h), Position = UDim2.fromScale(0, -(y0 - MY0) / h), ZIndex = 6 })
		local function word(col, z)
			return F(K.text(hold, { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromScale(0.9, 0.86), Text = "ERROR 404",
				FontFace = MONO, TextColor3 = col, ZIndex = z }), "TextTransparency", z == 8 and 0 or 0.15)
		end
		sl[i] = { hold = hold, y0 = y0, h = h, a = word(C1, 7), b = word(C2, 7), w = word(W, 8), x = 0 }
	end
	local sub = F(K.text(bb, { Position = P(X0 + 0.25, MY0 + MH + 0.1), Size = Z(WW - 0.5, 0.36), Text = "> PAGE NOT FOUND", FontFace = MONO,
		TextColor3 = C1:Lerp(W, 0.45), TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 5 }), "TextTransparency", 0.1)

	local UW = math.clamp(#K.NAME * 0.26 + 0.9, 2.2, 6.4)
	local pill = F(K.frame(bb, { BackgroundColor3 = INK, AnchorPoint = Vector2.new(0.5, 0.5), Position = P(Wd / 2, 3.12), Size = Z(UW, 0.5), ZIndex = 4 }), "BackgroundTransparency", 0.25)
	K.new("UICorner", { CornerRadius = UDim.new(0.5, 0) }, pill)
	F(K.text(bb, { AnchorPoint = Vector2.new(0.5, 0.5), Position = P(Wd / 2, 3.12), Size = Z(UW - 0.4, 0.34), Text = K.NAME, FontFace = MONO,
		TextColor3 = C1:Lerp(W, 0.55), ZIndex = 5 }), "TextTransparency", 0)

	local ch = System.StaffThemes._tagCh or {}
	local TS = { beat = ch.sBeat or 0, tearT = 0, next = 3, str = 1, rr = 0, la = -1, dead = nil, txt = "", stxt = "" }
	return function(t, dt, it)
		local dead = ch.dead == true
		if (ch.sBeat or 0) ~= TS.beat then TS.beat = ch.sBeat or 0 TS.tearT, TS.str = 0.4, 2.2 end
		TS.next -= dt
		if TS.next <= 0 then TS.next = 2.5 + math.random() * 3 TS.tearT, TS.str = 0.22, 1 end
		if it < 0.7 then TS.tearT, TS.str = math.max(TS.tearT, 0.05), 0.6 + 2 * (1 - it / 0.7) end
		TS.tearT = math.max(0, TS.tearT - dt)
		local tear = TS.tearT > 0 or dead
		TS.rr -= dt
		local reroll = TS.rr <= 0
		if reroll then TS.rr = 0.05 end
		local split = 0.05 + (tear and 0.1 * (dead and 0.6 or TS.str) or 0) + 0.02 * math.sin(t * 3)
		for _, S in ipairs(sl) do
			if reroll then S.x = (tear and math.random() < 0.6) and (math.random() - 0.5) * 0.5 * (dead and 0.5 or TS.str) or 0 end
			S.hold.Position = UDim2.fromScale(S.x / WW, -(S.y0 - MY0) / S.h)
			S.a.Position = UDim2.fromScale(0.5 - split / WW, 0.5 + (tear and 0.02 or 0))
			S.b.Position = UDim2.fromScale(0.5 + split / WW, 0.5 - (tear and 0.02 or 0))
		end

		local a = c01(it / 0.3)
		if it < 0.6 and math.random() < 0.3 then a *= 0.4 end
		if a ~= TS.la then
			TS.la = a
			for _, f in ipairs(fade) do f[1][f[2]] = 1 - (1 - f[3]) * a end
		end
		if dead ~= TS.dead then
			TS.dead = dead
			grey.BackgroundTransparency = dead and 0.2 or 1
		end
		local txt = dead and "NOT RESPONDING" or (it < 0.9 and ("LOADING " .. string.rep("#", math.floor(it / 0.9 * 6)))) or (it < 2.8 and "LOADED") or "ERROR_404.EXE"
		if txt ~= TS.txt then TS.txt = txt title.Text = txt end
		local stxt = dead and "> SYSTEM HALTED" or ("> PAGE NOT FOUND" .. ((t % 1) < 0.5 and "_" or ""))
		if stxt ~= TS.stxt then TS.stxt = stxt sub.Text = stxt end
	end
end

System.StaffThemes.THEMES.error404 = function(L, C)
	local C1, C2, W = C.c1, C.c2, L.W
