			return function(tt, al)
				local j = tt < 0.5 and (1 - tt / 0.5) or (((tt % 1.3) < 0.12) and 0.7 or 0.1)
				a.Position = UDim2.fromScale(-0.012 * j + (math.random() - 0.5) * 0.004 * j, 0)
				b.Position = UDim2.fromScale(0.012 * j, 0)
				a.TextTransparency, b.TextTransparency = 1 - 0.7 * al, 1 - 0.7 * al
			end
		end,
		bar = function(B)
			local NL = 36
			local lines = {}
			for i = 1, NL do
				lines[i] = L.new("Frame", { BorderSizePixel = 0, BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 1, AnchorPoint = Vector2.new(0, 0.5),
					Position = UDim2.fromScale(0, (i - 0.5) / NL), Size = UDim2.new(1, 0, 0, 2), ZIndex = 1 }, B.layer)
			end
			local band = L.new("Frame", { BorderSizePixel = 0, BackgroundColor3 = B.c1, BackgroundTransparency = 1, Size = UDim2.fromScale(1, 0.05), ZIndex = 1 }, B.layer)
			L.new("UIGradient", { Rotation = 90, Transparency = NS({ K(0, 1), K(0.5, 0), K(1, 1) }) }, band)
			local last = -1
			return function(tt)
				local on = math.floor(c01(tt / 0.4) * (1 - c01((tt - 4.8) / 0.8)) * 20 + 0.5) / 20
				if on ~= last then
					last = on
					for _, f in ipairs(lines) do f.BackgroundTransparency = 1 - 0.2 * on end
				end
				band.Position = UDim2.fromScale(0, ((tt * 0.5) % 1.2) - 0.1)
				band.BackgroundTransparency = 1 - 0.1 * on
			end
		end }



	local PX = { list = {}, i = 0 }
	for i = 1, 40 do PX.list[i] = { p = L.part({ Material = NEON, Color = C1, Transparency = 1, Size = Vector3.one * 0.2 }), t = 99, life = 1 } end
	function PX.emit(pos, vel, size, col, life, grav, gy)
		PX.i = PX.i % #PX.list + 1
		local X = PX.list[PX.i]
		X.pos, X.vel, X.sz, X.life, X.g, X.gy, X.t, X.ls, X.lt = pos, vel, size, life, grav or 0, gy, 0, nil, nil
		if X.p.Color ~= col then X.p.Color = col end
	end
	function PX.step(dt, off)
		for _, X in ipairs(PX.list) do
			if X.t < X.life then
				X.t += dt
				if X.t >= X.life or off then
					X.t = 99
					X.p.Transparency = 1
				else
					X.vel -= Vector3.new(0, X.g * dt, 0)
					X.pos += X.vel * dt
