				end
			end
		end
	end

	local SQ = { r = {}, i = 0 }
	for i = 1, 4 do
		local seg = {}
		for j = 1, 4 do seg[j] = L.part({ Material = NEON, Color = C1, Transparency = 1 }) end
		SQ.r[i] = { seg = seg, t = 99, life = 1 }
	end
	function SQ.fire(c, col, from, to, life, th)
		SQ.i = SQ.i % #SQ.r + 1
		local Q = SQ.r[SQ.i]
