				list[#list + 1] = { p = p, cf = p.CFrame }
			end
		end
		return list
	end
	local function bodyList()
		local t = {}
		for d in pairs(L.bodyParts()) do if d:IsA("BasePart") then t[#t + 1] = d end end
		return t
	end

	local function rgbPair(amp, life, base)
		local r = camRight() * amp * sc()
		for i, col in ipairs({ C1, C2 }) do
			local g = bodyGhost(col, life, i == 1 and -r or r)
			L.fx(life, function(k)
				local f = (math.floor(k * 10) % 2 == 0) and 0 or 0.2
				for _, gp in ipairs(g) do gp.p.Transparency = math.min(1, base + (1 - base) * k + f) end
			end, {})
		end
	end


	local function render(life)
		local R = { g = { bodyGhost(W, life), bodyGhost(C1, life), bodyGhost(C2, life) } }
		local lo, hi = math.huge, -math.huge
		for _, g in ipairs(R.g) do for _, gp in ipairs(g) do gp.p.Transparency = 1 end end
		for _, gp in ipairs(R.g[1]) do
			local y, h = gp.cf.Position.Y, gp.p.Size.Y * 0.5
			lo, hi = math.min(lo, y - h), math.max(hi, y + h)
		end
		if lo > hi then local f = (ch.feet or Vector3.zero).Y lo, hi = f, f + 5 * sc() end
		R.lo, R.hi = lo, hi
		function R.set(k, amp, a)
			local y = lo + (hi - lo) * k
			local r = camRight() * amp
			for i, g in ipairs(R.g) do
				local off = i == 2 and -r or i == 3 and r or Vector3.zero
				local base = i == 1 and 0.25 or 0.5
				for _, gp in ipairs(g) do
					local shown = gp.cf.Position.Y - gp.p.Size.Y * 0.5 < y
					local jit = (shown and a > 0 and math.random() < 0.04) and camRight() * rnd(-0.3, 0.3) or Vector3.zero
					gp.p.CFrame = gp.cf + off + jit
					gp.p.Transparency = shown and (1 - (1 - base) * a) or 1
				end
			end
		end
		return R
	end



	local function shortExe()
		local o, s = L.ground(ch.feet, 3, 8), sc()
		hide(true)
		local r = camRight()
		local base = CFrame.fromMatrix(o + Vector3.new(0, 0.07, 0), r, UP)
		local BL, BD = 4 * s, 0.6 * s
		local objs = {}
		local function keep(x) objs[#objs + 1] = x return x end
		local frame = {}
		for j = 1, 4 do frame[j] = keep(L.part({ Material = NEON, Color = W, Transparency = 1 })) end
		local edge = 0.08 * s
		frame[1].Size, frame[1].CFrame = Vector3.new(BL + edge, 0.05, edge), base * CFrame.new(0, 0, BD / 2)
		frame[2].Size, frame[2].CFrame = Vector3.new(BL + edge, 0.05, edge), base * CFrame.new(0, 0, -BD / 2)
		frame[3].Size, frame[3].CFrame = Vector3.new(edge, 0.05, BD), base * CFrame.new(BL / 2, 0, 0)
		frame[4].Size, frame[4].CFrame = Vector3.new(edge, 0.05, BD), base * CFrame.new(-BL / 2, 0, 0)
		local fill = keep(L.part({ Material = NEON, Color = C1, Transparency = 1, Size = Vector3.new(0.1, 0.06, BD - edge * 2) }))
		local lp = keep(L.part({ CFrame = CFrame.new(o + Vector3.new(0, 0.9 * s, 0)) }))
		local gui = L.new("BillboardGui", { Size = UDim2.new(6 * s, 0, 0.7 * s, 0), LightInfluence = 0, MaxDistance = 200, Adornee = lp }, lp)
		local txt = L.new("TextLabel", { BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), TextScaled = true, FontFace = MONO, TextColor3 = C1:Lerp(W, 0.4),
			TextTransparency = 1, Text = "" }, gui)
		local R = render(2.9)
		local lf = -1
		L.timeline(2.8, function(t, once)
			if held and once("late", 0.2) then hide(true) end
			local on = c01(t / 0.15) * (1 - c01((t - 2.2) / 0.3))
			for _, p in ipairs(frame) do p.Transparency = 1 - 0.9 * on end

			local pr = t < 0.9 and 0.65 * t / 0.9 or t < 1.1 and (math.random() < 0.5 and 0.3 or 0.65) or 0.3 + 0.7 * c01((t - 1.1) / 0.7)
			pr = math.floor(pr * 16) / 16
			if pr ~= lf then
				lf = pr
				local w = math.max(0.05, (BL - edge * 2) * pr)
				fill.Size = Vector3.new(w, 0.06, BD - edge * 2)
				fill.CFrame = base * CFrame.new(-BL / 2 + edge + w / 2, 0, 0)
				fill.Color = C1:Lerp(C2, pr)
			end
			fill.Transparency = 1 - 0.95 * on
			local glitch = t > 0.9 and t < 1.1
			txt.Text = glitch and "RESPAWN.EXE  [ ERR ]" or ("RESPAWN.EXE  [ " .. math.floor(pr * 100) .. "% ]")
			txt.TextColor3 = glitch and C2 or C1:Lerp(W, 0.4)
			txt.TextTransparency = 1 - on
			if once("tick", 0.9) then SQ.fire(o, C2, 0.5 * s, 2.5 * s, 0.3, 0.06 * s) end

			if t > 1.8 then R.set(math.floor(c01((t - 1.8) / 0.5) * 8) / 8, 0.35 * s * (1 - c01((t - 2.15) / 0.2)), 1 - c01((t - 2.4) / 0.3)) end
			if once("show", 2.35) then hide(false) SQ.fire(o, C1, 0.6 * s, 4.5 * s, 0.45, 0.1 * s) end
		end, objs, function() hide(false) end)
	end

	local function shortRain()
		local o, s = L.ground(ch.feet, 3, 8), sc()
		local parts = bodyList()
		hide(true)
		local N = 44
		local tg = {}
		for i = 1, N do
			local p = parts[math.random(1, math.max(1, #parts))]
			if p then
				tg[i] = p.CFrame:PointToWorldSpace(Vector3.new(rnd(-0.5, 0.5) * p.Size.X, rnd(-0.5, 0.5) * p.Size.Y, rnd(-0.5, 0.5) * p.Size.Z))
			else
				tg[i] = o + Vector3.new(rnd(-0.8, 0.8), rnd(0.2, 5), rnd(-0.4, 0.4)) * s
			end
		end
		table.sort(tg, function(a, b) return a.Y < b.Y end)
		local cubes = {}
		for i = 1, N do
			local col = pick()
			cubes[i] = { p = L.part({ Material = NEON, Color = col, Transparency = 1, Size = Vector3.one * 0.42 * s }), at = 0.15 + (i / N) * 1.25, x = tg[i] }
		end
		local objs = {}
		for i, c in ipairs(cubes) do objs[i] = c.p end
		L.timeline(2.5, function(t, once)
			if held and once("late", 0.2) then hide(true) end
			for _, c in ipairs(cubes) do
				local u = c01((t - (c.at - 0.35)) / 0.35)
				if u <= 0 or t > 1.95 then
					c.p.Transparency = 1
				else
					c.p.CFrame = CFrame.new(c.x + Vector3.new(0, 22 * s * (1 - u * u), 0))
					c.p.Transparency = t > 1.6 and 0.1 + 0.9 * math.floor(c01((t - 1.6) / 0.35) * 3) / 3 or 0.08
				end
			end
			if once("snap", 1.6) then
				hide(false)
				rgbPair(0.35, 0.35, 0.35)
				SQ.fire(o, C1, 0.6 * s, 5 * s, 0.5, 0.1 * s)
				for _ = 1, 8 do PX.emit(o + Vector3.new(rnd(-1, 1), rnd(0.5, 4), rnd(-1, 1)) * s, Vector3.new(rnd(-4, 4), rnd(2, 6), rnd(-4, 4)) * s, 0.25 * s, pick(), 0.8, 25, o.Y) end
			end
		end, objs, function() hide(false) end)
	end
	local shorts = { shortExe, shortRain }





	local function arriveFull()
		local o, s = L.ground(ch.feet, 3, 8), sc()
		local parts = bodyList()
		hide(true)
		local DUR = 6
		local S = L.screen(DUR)
		S.style, S.c1, S.c2 = "error404", C1, C2
		S.boxFn = function(t) return c01((t - 0.2) / 0.4) * (1 - c01((t - 5.0) / 0.6)) end
		S.dimFn = function(t) return 0.6 * c01(t / 0.6) * (1 - c01((t - 4.2) / 1.2)) end
		S.tintFn = function(t) return C1:Lerp(W, 0.55), 0.3 * c01(t / 0.6) * (1 - c01((t - 4.2) / 1.2)) end
		local objs = {}
		local function keep(x) objs[#objs + 1] = x return x end

		local boxes = {}
		for i, p in ipairs(parts) do
			if i > 30 then break end
			boxes[#boxes + 1] = { b = keep(L.new("SelectionBox", { Adornee = p, Color3 = C1, SurfaceTransparency = 1, LineThickness = 0.03 * s, Transparency = 1 }, L.root)),
				y = p.Position.Y - p.Size.Y * 0.5 }
		end
		local R = render(DUR)
		local plane = keep(L.part({ Material = NEON, Color = C1, Transparency = 1, Size = Vector3.new(3.6 * s, 0.05, 3.6 * s) }))
		local dp = keep(L.mesh("disc.mesh", "darkdisc.png", L.BACK, 1, Vector3.new(9 * s, 1, 9 * s)))
		dp.CFrame = CFrame.new(o + Vector3.new(0, 0.04, 0))
		dp.Transparency = 1
		local spT, ly = 0, nil
		L.timeline(DUR, function(t, once)
			local dt = L.lastDt or 0.016
			if held and once("late", 0.3) then hide(true) end
			dp.Transparency = 1 - 0.5 * c01(t / 0.4) * (1 - c01((t - 4.6) / 0.8))

			local wy = R.lo + (R.hi - R.lo) * c01((t - 0.1) / 1.1)

			local far = plane.LocalTransparencyModifier >= 1
			for _, B in ipairs(boxes) do
				local on = B.y < wy and t < 3.75 and not far
				B.b.Transparency = on and ((math.random() < 0.1) and 0.6 or 0.15) or 1
				B.b.Color3 = (t > 1.4 and math.random() < 0.05) and C2 or C1
			end

			if t > 1.4 and t < 3.75 then
				local k = math.floor(c01((t - 1.4) / 2.0) * 12) / 12
				local amp = 0.6 * s * (1 - c01((t - 3.0) / 0.6))
				R.set(k, amp, 1)
				local y = R.lo + (R.hi - R.lo) * k
				if y ~= ly then ly = y plane.CFrame = CFrame.new(o.X, y, o.Z) end
				plane.Transparency = (t < 3.4) and 0.35 or 1
				spT -= dt
				if spT <= 0 and t < 3.4 then
					spT = 0.04
					local a = rnd(0, math.pi * 2)
					PX.emit(Vector3.new(o.X, y, o.Z) + Vector3.new(math.cos(a), 0, math.sin(a)) * 1.6 * s, Vector3.new(math.cos(a), rnd(0.5, 2), math.sin(a)) * 2 * s,
						rnd(0.12, 0.25) * s, pick(), 0.7, 0)
				end
			end

			if once("snap", 3.6) then
				hide(false)
				S:flash(C1:Lerp(W, 0.5), 0.35)
				SQ.fire(o, C1, 0.6 * s, 8 * s, 0.7, 0.14 * s)
				SQ.fire(o, C2, 0.3 * s, 5 * s, 0.55, 0.1 * s)
				for _ = 1, 12 do PX.emit(o + Vector3.new(rnd(-1, 1), rnd(0.5, 4.5), rnd(-1, 1)) * s, Vector3.new(rnd(-6, 6), rnd(2, 8), rnd(-6, 6)) * s, 0.25 * s, pick(), 0.9, 25, o.Y) end
			end
			if t >= 3.6 then R.set(1, 0, 1 - c01((t - 3.6) / 0.3)) end
			if once("card", 3.9) then S:title(L.name(), C1, C2) end
		end, objs, function() hide(false) end)
	end




	local function death(preview)
		if not ch.char then return end
		local s = sc()
		local pos = L.ground(ch.feet or ch.pos, 3, 8)
		local g = { bodyGhost(W, 1.1), bodyGhost(C1, 1.1), bodyGhost(C2, 1.1) }
		local gone = {}
		deathGone = gone
		dying = true
		for d in pairs(L.bodyParts()) do gone[d] = true d.LocalTransparencyModifier = 1 end
		for i = 2, 3 do for _, gp in ipairs(g[i]) do gp.p.Transparency = 1 end end
		local r = camRight()
		local cubes = {}
		local objs = {}
		L.timeline(2.4, function(t, once)

			if t < 0.3 then for _, gp in ipairs(g[1]) do gp.p.Transparency = (math.random() < 0.15) and 0.5 or 0.15 end end

			if t >= 0.3 and t < 0.95 then
				local amp = 1.4 * s * L.outQuad(c01((t - 0.3) / 0.5))
				for _, gp in ipairs(g[1]) do gp.p.Transparency = 0.15 + 0.85 * c01((t - 0.3) / 0.4) end
				for i = 2, 3 do
					local off = r * amp * (i == 2 and -1 or 1)
					for _, gp in ipairs(g[i]) do
						gp.p.CFrame = gp.cf + off + ((math.random() < 0.06) and UP * rnd(-0.2, 0.2) or Vector3.zero)
						gp.p.Transparency = 0.3
					end
				end
			end

			if once("burst", 0.95) then
				local c = pos + Vector3.new(0, 2.5 * s, 0)
				for i = 2, 3 do
					for _, gp in ipairs(g[i]) do
						gp.p.Transparency = 1
						for _ = 1, 2 do
							if #cubes < 56 then
								local p = gp.p
								local at = p.CFrame:PointToWorldSpace(Vector3.new(rnd(-0.4, 0.4) * p.Size.X, rnd(-0.4, 0.4) * p.Size.Y, rnd(-0.4, 0.4) * p.Size.Z))
								local d = at - c
								d = d.Magnitude > 0.05 and d.Unit or UP
								local q = L.part({ Material = NEON, Color = i == 2 and C1 or C2, Transparency = 0.05, Size = Vector3.one * rnd(0.25, 0.45) * s, CFrame = CFrame.new(at) })
								objs[#objs + 1] = q
								cubes[#cubes + 1] = { p = q, x = at, v = (d * rnd(4, 9) + UP * rnd(3, 8)) * s, s0 = q.Size.X }
							end
						end
					end
				end
			end
			if t > 0.95 then
				local dt = L.lastDt or 0.016
				local k = c01((t - 0.95) / 1.4)
				local q = math.floor(k * 4) / 4
				for _, cb in ipairs(cubes) do
					cb.v -= Vector3.new(0, 40 * dt, 0)
					cb.x += cb.v * dt
					if cb.x.Y < pos.Y + cb.s0 * 0.5 then cb.x = Vector3.new(cb.x.X, pos.Y + cb.s0 * 0.5, cb.x.Z) cb.v *= Vector3.new(0.5, 0, 0.5) end
					cb.p.CFrame = CFrame.new(cb.x)
					local z = cb.s0 * (1 - 0.7 * q)
					if math.abs(cb.p.Size.X - z) > 0.01 then cb.p.Size = Vector3.one * z end
					cb.p.Transparency = 0.05 + 0.95 * q
				end
			end
		end, objs, function()
			deathGone = nil
			dying = false
			if preview then for d in pairs(gone) do if d.Parent then pcall(function() d.LocalTransparencyModifier = 0 end) end end end
		end)

		local N, TS = 4, 0.75 * s
		local base = CFrame.new(pos + Vector3.new(0, 0.05, 0)) * CFrame.Angles(0, rnd(0, math.pi), 0)
		local tiles = {}
		for x = 1, N do
			for z = 1, N do
				local col = ((x + z) % 2 == 0) and MAG or INK
				tiles[#tiles + 1] = { p = L.part({ Material = col == MAG and NEON or Enum.Material.SmoothPlastic, Color = col, Transparency = 1, Size = Vector3.new(TS, 0.06, TS),
					CFrame = base * CFrame.new((x - (N + 1) / 2) * TS, 0, (z - (N + 1) / 2) * TS) }), x = x, z = z }
			end
		end
		local lobj = {}
		for i, tl in ipairs(tiles) do lobj[i] = tl.p end
		local gT = 0
		L.fx(6.5, function(k, tt)
			local on = c01((tt - 1) / 0.15)
			gT -= L.lastDt or 0.016
			local shift = 0
			if gT <= 0 then gT = rnd(0.4, 1.2) shift = math.random(1, N) end
			for _, tl in ipairs(tiles) do
				tl.p.Transparency = 1 - on * (1 - c01((k - 0.6) / 0.4)) * ((math.random() < 0.03) and 0.4 or 0.9)
				if shift > 0 then
					local dx = tl.z == shift and rnd(-0.3, 0.3) * TS or 0
					tl.p.CFrame = base * CFrame.new((tl.x - (N + 1) / 2) * TS + dx, 0, (tl.z - (N + 1) / 2) * TS)
				end
			end
		end, lobj)
	end


	local ST = { agT = rnd(1, 3), shT = 0.3, dpT = rnd(3, 6), lagT = 0, d = 0, lp = nil, beat = 0, side = 1 }
	local function shoulderPx(s)
		local t = ch.torso
		if not (t and t.Parent) then return end
		local side = math.random() < 0.5 and -1 or 1
		local p = t.CFrame:PointToWorldSpace(Vector3.new(side * t.Size.X * 0.5, t.Size.Y * 0.45, rnd(-0.2, 0.2)))
		local v = t.CFrame.RightVector * side * rnd(0.3, 1) + Vector3.new(0, rnd(0.6, 1.4), 0)
		PX.emit(p, v * s, rnd(0.12, 0.22) * s, pick(), rnd(0.8, 1.2), 0)
	end
	local function step(dt)
		local s, iw, on, swim, sit, dead = sc(), ch.iw or 0, ch.on, ch.swim == true, ch.sit == true, ch.dead == true
		local off = dead or dying
		local pause = off or sit
		PX.step(dt, off)
		SQ.step(dt)
		L.motion(dt, s, off)
		if (ch.sBeat or 0) ~= ST.beat then
			ST.beat = ch.sBeat or 0
			if not pause and not swim then
				rgbPair(0.45, 0.3, 0.45)
				SQ.fire(L.ground(ch.feet, 2, 4), C2, 0.5 * s, 3 * s, 0.4, 0.08 * s)
			end
		end
		if not pause then

			ST.agT -= dt
			if ST.agT <= 0 then ST.agT = rnd(1, 3) rgbPair(0.22, 0.32, swim and 0.8 or 0.55) end

			ST.shT -= dt * (swim and 0.3 or 1)
			if ST.shT <= 0 then ST.shT = rnd(0.15, 0.35) shoulderPx(s) end

			ST.dpT -= dt
			if ST.dpT <= 0 and iw > 0.3 and not swim then
				ST.dpT = rnd(3, 6)
				local a = rnd(0, math.pi * 2)
				local gp = L.ground(ch.feet + Vector3.new(math.cos(a), 0, math.sin(a)) * rnd(2, 4.5) * s, 3, 6)
				local z = 0.5 * s
				if math.abs(DP.p.Size.X - z) > 0.01 then DP.p.Size = Vector3.new(z, 0.05, z) end
				DP.p.CFrame = CFrame.new(gp + Vector3.new(0, 0.05, 0))
				DP.p.Color = pick()
				DP.t = 0
			end
		end
		if DP.t < 1.2 then
			DP.t += dt
			DP.p.Transparency = (pause or DP.t >= 1.2) and 1 or ((math.floor(DP.t / 0.15) % 2 == 0) and 0.05 or 1)
		end

		if on and not pause and not swim and not ch.air and ch.feet then
			ST.lagT -= dt
			if ST.lagT <= 0 then
				ST.lagT = (ch.sprint or 0) > 0.3 and 0.16 or 0.3
				ST.side = -ST.side
				local g = bodyGhost(ST.side > 0 and C1 or C2, 0.36)
				L.fx(0.36, function(k) local q = math.floor(k * 3) / 3 for _, gp in ipairs(g) do gp.p.Transparency = 0.5 + 0.5 * q end end, {})
			end
			if ST.lp then ST.d += ((ch.pos - ST.lp) * Vector3.new(1, 0, 1)).Magnitude end
			if ST.d > 0.7 * s then
				ST.d = 0
				local gy = L.ground(ch.feet, 2, 4).Y
				PX.emit(ch.feet + Vector3.new(rnd(-0.4, 0.4), rnd(0.3, 0.9), rnd(-0.4, 0.4)) * s, Vector3.new(0, rnd(0, 1.5), 0) * s, rnd(0.18, 0.28) * s, pick(), 0.9, 20, gy)
			end
		end
		ST.lp = ch.pos

		if ch.jumped and not off and not swim then
			local g = bodyGhost(W, 0.22, UP * 5.5 * s)
			L.fx(0.22, function(k) for _, gp in ipairs(g) do gp.p.Transparency = (math.floor(k * 8) % 2 == 0) and 0.35 or 0.8 end end, {})
			local gp = L.ground(ch.feet, 2, 6)
			for _ = 1, 5 do PX.emit(ch.feet + Vector3.new(rnd(-0.5, 0.5), 0.2, rnd(-0.5, 0.5)) * s, Vector3.new(rnd(-3, 3), rnd(1, 4), rnd(-3, 3)) * s, 0.2 * s, pick(), 0.7, 20, gp.Y) end
		end
		if ch.landed and not off and not swim then
			local gp = L.ground(ch.feet, 2, 4)
			SQ.fire(gp, C1, 0.5 * s, 4 * s, 0.45, 0.09 * s)
			SQ.fire(gp, C2, 0.3 * s, 2.6 * s, 0.4, 0.07 * s)
		end
		tag.step(dt)
	end

	return {
		arrive = function(short) if short then shorts[math.random(1, #shorts)]() else arriveFull() end end,
		short = function(n) n = math.floor(tonumber(n) or 1) shorts[(n - 1) % #shorts + 1]() end,
		step = step, rebind = rebind, death = death,
		hidden = function() return held or deathGone end,
		rig = function() return rig end,
		stop = function() hide(false) end,
	}
end
end
end)()
end
