    ["engine/character_connection"] = [====[return function(P)
local _rawPcall, _rcPcallSink, _rcPcallRet, pcall, PS, RS, HS, DB, UIS, TS, MPS, MS, _RC_VER, _RC_VER_DATE = P._rawPcall, P._rcPcallSink, P._rcPcallRet, P.pcall, P.PS, P.RS, P.HS, P.DB, P.UIS, P.TS, P.MPS, P.MS, P._RC_VER, P._RC_VER_DATE
return (function()


return function(R, I)
local Clothes, Function, GlobalMaid, MaxArmType, MaxBreastsType, MaxButtType, MaxLegsType, MaxTorsoType, Player, PlayerData, System, _PEER_ALLOWED_PRESET_KEYS = I.Clothes, I.Function, I.GlobalMaid, I.MaxArmType, I.MaxBreastsType, I.MaxButtType, I.MaxLegsType, I.MaxTorsoType, I.Player, I.PlayerData, I.System, I._PEER_ALLOWED_PRESET_KEYS
	function Function.CharacterConnection(Player)
		local CharacterConnect = Player.CharacterAdded:Connect(function(Character)

			do
