		elseif bundleData.GizmoOffset then

			local _gizSan = _sanitizeGizmoOffsets({_single = bundleData.GizmoOffset})
			if _gizSan and _gizSan._single then pd.GizmoOffset = _gizSan._single end
		end
		if System.applyMyEdits then System.applyMyEdits(pd) end

		if Function.IsNaked and Function.IsNaked(pd) and Function.NakedStripCats then pd.StripCategories = Function.NakedStripCats(pd.StripCategories) end
	end

