				local _gizSan = _sanitizeGizmoOffsets({_single = tweaks.gizmoOffset})
				if _gizSan and _gizSan._single then pd.GizmoOffset = _gizSan._single end
			end
			if type(tweaks.clothingList) == "table" then
				local newClothing = {}
				local _seen = {}


				local _idx = {}
				local _odd = {}
				for k in pairs(tweaks.clothingList) do
					if type(k) == "number" then _idx[#_idx + 1] = k else _odd[#_odd + 1] = k end
				end
				table.sort(_idx)
				for _, k in ipairs(_odd) do _idx[#_idx + 1] = k end
				for _, _k in ipairs(_idx) do
					local n = tweaks.clothingList[_k]
					if type(n) == "string" and #n <= 128 and not _seen[n] and #newClothing < 256 then
						_seen[n] = true
						table.insert(newClothing, n)
					end
				end
				pd.CurrentClothes = newClothing
			end
			if type(tweaks.clothesHP) == "table" then


				local _safe = {}
				for cloth, entry in pairs(tweaks.clothesHP) do
					if type(cloth) == "string" and #cloth <= 128 and type(entry) == "table" then
						local _hp = entry.HP
						if (_hp == "TopHP" or _hp == "BottomHP") and type(entry.Inverse) == "boolean" then
							_safe[cloth] = {HP = _hp, Inverse = entry.Inverse}
						end
					end
				end
				pd.ClothesHP = _safe
			end
			if type(tweaks.presetOverlay) == "table" then



				for k, v in pairs(tweaks.presetOverlay) do
					if _PEER_ALLOWED_PRESET_KEYS[k] then
						local _ok = true
						if type(v) == "number" then
							_ok = _isFiniteNum(v)


							if _ok and (k:find("Scale$") or k:find("Stiffness$") or k:find("Damping$") or k == "Volume") then
								_ok = v >= 0 and v <= (k:find("Stiffness$") and 30 or 10)
							end
						end
						if _ok and _validatePresetValue(k, v) then pd[k] = v end
					end
				end
			end

			local function _asColor3(v)
				if typeof(v) == "Color3" then return v end
				if type(v) == "table" then
					local r, g, b = v.R or v.r, v.G or v.g, v.B or v.b
					if type(r) == "number" and type(g) == "number" and type(b) == "number" then
						return Color3.new(math.clamp(r, 0, 1), math.clamp(g, 0, 1), math.clamp(b, 0, 1))
					end
				end
			return nil
			end
			if tweaks.nippleColor ~= nil then local _c = _asColor3(tweaks.nippleColor); if _c then pd.NippleColor = _c end end
			if tweaks.skinTone    ~= nil then local _c = _asColor3(tweaks.skinTone);    if _c then pd.SkinTone    = _c end end
		end


		System._avsyncLiveMeshEdit = function(pd)
			if type(pd) ~= "table" or type(pd.PartList) ~= "table" or not Function.PartListDefault then return nil end
			if not System._avsPLDefault then
				local okD, d = pcall(Function.PartListDefault)
				if not okD or type(d) ~= "table" then return nil end
				System._avsPLDefault = d
			end
			local def, out, n = System._avsPLDefault, {}, 0
			for partName, entry in pairs(pd.PartList) do
				local d = def[partName]
				if type(partName) == "string" and type(entry) == "table" and type(d) == "table" then
					local diff
					for prop, v in pairs(entry) do
						if type(prop) == "string" then
							local dv, tv = d[prop], typeof(v)
							if prop == "Color" then
								local c = type(v) == "table" and v.Color
								if typeof(c) == "Color3" and not (type(dv) == "table" and dv.Color == c) then diff = diff or {}; diff.Color = c end
							elseif (tv == "number" or tv == "string" or tv == "boolean" or tv == "Vector3" or tv == "CFrame" or tv == "Color3") and v ~= dv then
								diff = diff or {}; diff[prop] = v
							end
						end
					end
					if diff then
						out[partName] = diff
						n = n + 1
						if n >= 64 then break end
					end
				end
			end
			return out
		end
		System._avsyncTailSettings = function(pd)
			local t = type(pd) == "table" and pd.tailSettings
			if type(t) ~= "table" then return nil end
			local out = {}
			for k, v in pairs(t) do
				local tv = typeof(v)
				if type(k) == "string" and k ~= "isTailCurrentlyEnabled" and (tv == "number" or tv == "boolean" or tv == "Vector3") then out[k] = v end
			end
			return out
		end




		System._avsyncAnimSlots = { idle = true, walk = true, run = true, jump = true, fall = true, climb = true, swim = true, swimidle = true }
		System._avsyncAnimWire = function()
			local live = Function._catLive
			if not (type(live) == "table" and Player.Character and System.animRT.isR6(Player.Character)) then return nil end
			local out, n = {}, 0
			local a = live.anim
			if type(a) == "table" and type(a.slots) == "table" then
				for slot, list in pairs(a.slots) do
					local e = type(list) == "table" and list[1]
					local id = type(e) == "table" and System.animRT.idOf(e[2])
					if System._avsyncAnimSlots[slot] and id then out[slot] = id; n += 1 end
				end
			end



			local em = live.emote
			if type(em) == "table" and em.id and type(em.track) == "table" and em.track.IsPlaying then out.emote = em.id; out.emoteN = em.n or 0; n += 1 end
			return n > 0 and out or nil
		end

		System._avsyncAnimRepublish = function()
			local AS = System.AvatarSync
			if AS and AS.enabled and Function.AvatarSyncPublish then task.defer(pcall, Function.AvatarSyncPublish, true, AS.forceClear == true) end
		end

		System._avsyncEmotePeers = System._avsyncEmotePeers or {}
		System._avsyncEmotePeer = function(uid, wire)
			local id = type(wire) == "table" and tonumber(wire.emote) or nil
			if id and not (id > 0 and id < 1e15 and id == math.floor(id)) then id = nil end
			local n = type(wire) == "table" and tonumber(wire.emoteN) or 0
			local sig = id and (string.format("%d", id) .. "#" .. tostring(n)) or nil
			local E = System._avsyncEmotePeers
			local st = E[uid]
			if st and st.sig == sig then return end
			if st then E[uid] = nil; if st.track then pcall(function() st.track:Stop() end) end end
			if not sig then return end
			local plr = game:GetService("Players"):GetPlayerByUserId(uid)
			local c = plr and plr.Character
			st = { sig = sig }
			E[uid] = st
			if c and System.animRT.isR6(c) then
				task.spawn(function()
					local tr = System.animRT.emote(c, "rbxassetid://" .. string.format("%d", id))
					if E[uid] == st then st.track = tr elseif tr then tr:Stop() end
				end)
			end
		end
		System._avsyncAnimPeers = System._avsyncAnimPeers or {}

		System._avsyncAnimPeer = function(uid, wire)
			uid = tonumber(uid)
			if not uid or uid == Player.UserId then return end
			pcall(System._avsyncEmotePeer, uid, wire)
			local slots, sig = nil, {}
			if type(wire) == "table" then
				for slot, id in pairs(wire) do
					id = tonumber(id)
					if System._avsyncAnimSlots[slot] and id and id > 0 and id < 1e15 and id == math.floor(id) then
						slots = slots or {}
						slots[slot] = { { slot, "rbxassetid://" .. string.format("%d", id) } }
						sig[#sig + 1] = slot .. "=" .. string.format("%d", id)
					end
				end
			end
			table.sort(sig)
			sig = table.concat(sig, ",")
			local st = System._avsyncAnimPeers[uid]
			if not slots then
				if st then System._avsyncAnimDrop(uid, true) end
				return
			end
			local plr = game:GetService("Players"):GetPlayerByUserId(uid)
			if not plr then return end
			if not st then
				st = {}
				System._avsyncAnimPeers[uid] = st
				st.conn = plr.CharacterAdded:Connect(function(c)
					st.char = nil

					pcall(function() c:WaitForChild("Humanoid", 15) end)
					task.wait(0.5)
					if System._avsyncAnimPeers[uid] == st and st.slots and c.Parent and System.animRT.isR6(c) then
						st.char = c
						task.spawn(System.animRT.setPack, c, st.slots)
					end
				end)
			end
			local c = plr.Character
			if st.sig == sig and st.char == c then return end


			st.sig, st.slots, st.char = sig, slots, nil
			if c and System.animRT.isR6(c) then st.char = c; task.spawn(System.animRT.setPack, c, slots) end
		end
		System._avsyncAnimDrop = function(uid, packOnly)
			uid = tonumber(uid)
			if uid and packOnly ~= true then
				local es = System._avsyncEmotePeers[uid]
				System._avsyncEmotePeers[uid] = nil
				if es and es.track then pcall(function() es.track:Stop() end) end
			end
			local st = uid and System._avsyncAnimPeers[uid]
			if not st then return end
			System._avsyncAnimPeers[uid] = nil
			if st.conn then pcall(function() st.conn:Disconnect() end) end
			if st.char then pcall(System.animRT.clearPack, st.char) end
		end
		System._avsyncHeldGear = function()
			local live = Function._catLive
			local held = Player.Character and Player.Character:FindFirstChildOfClass("Tool")
			if not (held and type(live) == "table" and type(live.gear) == "table") then return nil end
			for id, tool in pairs(live.gear) do
				if tool == held then return tonumber(id) end
			end
			return nil
		end



		System._lookPrev = System._lookPrev or {}
		System._lookPh = System._lookPh or {}
		System.lookPreviewClear = function(slot, keepPh)
			for s, ph in pairs(System._lookPh) do
				if (slot == nil or s == slot) and not keepPh then pcall(function() ph:Destroy() end); System._lookPh[s] = nil end
			end
			if slot == nil and System._lookTpl then pcall(function() System._lookTpl.rig:Destroy() end); System._lookTpl = nil end
			for s, e in pairs(System._lookPrev) do
				if slot == nil or s == slot then
					local pd = PlayerData[e.key]
					if pd then pd.LastRequestID = (pd.LastRequestID or 0) + 1 end
					if pd and pd.ExecutionMaid then pcall(function() pd.ExecutionMaid:DoCleaning() end) end
					PlayerData[e.key] = nil; Bundle[e.key] = nil
					if System.NPCs then System.NPCs[e.key] = nil end
					if e.rig then pcall(function() e.rig:Destroy() end) end
					System._lookPrev[s] = nil
				end
			end
		end
		System.lookPreviewTurn = function(slot, degrees)
			local e = System._lookPrev[slot]
			if e and e.rig and e.rig.Parent then pcall(function() e.rig:PivotTo(e.rig:GetPivot() * CFrame.Angles(0, math.rad(degrees or 45), 0)) end) end
		end



		System.lookPreviewSpot = function(slot)
			if slot <= 3 then return (slot - 2) * 4.5, -7 end
			local i = slot - 4
			return ((i % 4) - 1.5) * 7, -15 - math.floor(i / 4) * 8
		end



		System._lookRaySkip = function(extra)
			local skip = {}
			for _, pl in ipairs(game:GetService("Players"):GetPlayers()) do if pl.Character then skip[#skip + 1] = pl.Character end end
			for _, m in pairs(System.NPCs or {}) do if typeof(m) == "Instance" then skip[#skip + 1] = m end end
			for _, o in pairs(System._lookPrev) do if o.rig then skip[#skip + 1] = o.rig end end
			for _, o in pairs(System._lookPh) do skip[#skip + 1] = o end
			if extra then skip[#skip + 1] = extra end
			return skip
		end
		System.lookPlaceholder = function(slot, label, onTap)
			slot = math.clamp(math.floor(tonumber(slot) or 1), 1, 15)
			local me = Player.Character
			local root = me and me:FindFirstChild("HumanoidRootPart")
			if not root then return false, "Spawn first: the markers stand behind you." end
			System.lookPreviewClear(slot)
			local ok, err = pcall(function()
				local base = root.CFrame
				local sx, sz = System.lookPreviewSpot(slot)
				local pos = (base * CFrame.new(sx, 0, sz)).Position
				local rp = RaycastParams.new(); rp.FilterType = Enum.RaycastFilterType.Exclude; rp.RespectCanCollide = true
				rp.FilterDescendantsInstances = System._lookRaySkip()
				local hit = workspace:Raycast(pos + Vector3.new(0, 4, 0), Vector3.new(0, -60, 0), rp)
				local floorY = hit and hit.Position.Y or (pos.Y - 3)
				local p = Instance.new("Part")
				p.Name = "_lookph_" .. slot; p.Anchored = true; p.CanCollide = false; p.CanTouch = false; p.CastShadow = false
				p.Size = Vector3.new(2, 5, 1); p.Material = Enum.Material.ForceField; p.Color = Color3.fromRGB(150, 160, 255); p.Transparency = 0.2
				p.CFrame = CFrame.lookAt(Vector3.new(pos.X, floorY + 2.5, pos.Z), Vector3.new(base.Position.X, floorY + 2.5, base.Position.Z))
				local bb = Instance.new("BillboardGui")
				bb.Name = "RC_LookTag"; bb.Size = UDim2.fromOffset(220, 46); bb.StudsOffset = Vector3.new(0, 3.4, 0); bb.AlwaysOnTop = true; bb.MaxDistance = 80
				bb.Active = true
				local b = Instance.new("TextButton")
				b.BackgroundTransparency = 0.25; b.BackgroundColor3 = Color3.fromRGB(12, 12, 18); b.Size = UDim2.fromScale(1, 1); b.AutoButtonColor = true
				b.Text = tostring(label or ""):gsub("[^\32-\126]", ""):sub(1, 60) .. "\nTap to build"; b.TextColor3 = Color3.fromRGB(253, 253, 255); b.TextScaled = true; b.Font = Enum.Font.GothamBold
				local c = Instance.new("UICorner"); c.CornerRadius = UDim.new(0, 8); c.Parent = b
				local busy = false
				local idle = b.Text
				local function tap()
					if busy then return end
					busy = true; b.Text = "Building..."
					task.spawn(function()
						local okT, built = pcall(onTap, slot)
						if not (okT and built) and b.Parent then busy = false; b.Text = idle:gsub("Tap to build$", "Failed - tap to retry") end
					end)
				end
				b.Activated:Connect(tap)
				b.Parent = bb; bb.Adornee = p

				local holder = nil
				pcall(function() if type(gethui) == "function" then holder = gethui() end end)
				holder = holder or Player:FindFirstChildOfClass("PlayerGui")
				local cd = Instance.new("ClickDetector"); cd.MaxActivationDistance = 80; cd.Parent = p
				cd.MouseClick:Connect(tap)
				p.Parent = workspace
				p.Destroying:Connect(function() pcall(function() bb:Destroy() end) end)
				bb.Parent = holder or p
				System._lookPh[slot] = p
			end)
			if not ok then return false, "Couldn't place a marker: " .. tostring(err):sub(1, 60) end
			return true
		end
		System.lookPreview = function(slot, rec, label)
			slot = math.clamp(math.floor(tonumber(slot) or 1), 1, 15)
			if System._sessionAlive == false then return false, "RoClothes is closing." end
			if type(rec) ~= "table" or type(rec.bundle) ~= "table" then return false, "That look has no bundle data." end
			local me = Player.Character
			local root = me and me:FindFirstChild("HumanoidRootPart")
			if not root then return false, "Spawn first: the preview stands in front of you." end
			System.lookPreviewClear(slot, true)
			local key = "_lookprev_" .. slot



			local tpl = System._lookTpl
			if tpl and (tpl.char ~= me or os.clock() - tpl.at > 120 or not tpl.rig) then
				pcall(function() tpl.rig:Destroy() end); System._lookTpl = nil; tpl = nil
			end
			local rig
			if tpl then
				local okC, c = pcall(function() return tpl.rig:Clone() end)
				if okC and c then c.Name = key; c.Parent = workspace; rig = c end
			end
			if not rig then
				rig = System._buildCloneRig(key, me)
				if rig then
					pcall(function()
						rig.Archivable = true
						local copy = rig:Clone()
						if copy then System._lookTpl = { char = me, rig = copy, at = os.clock() } end
					end)
				end
			end
			if not rig then return false, "Couldn't build a mannequin." end
			local e = { key = key, rig = rig }
			System._lookPrev[slot] = e
			pcall(function()
				local hrp = rig:FindFirstChild("HumanoidRootPart"); if hrp then hrp.Anchored = true end
				local base = root.CFrame
				local sx, sz = System.lookPreviewSpot(slot)
				local pos = (base * CFrame.new(sx, 0, sz)).Position
				rig:PivotTo(CFrame.lookAt(pos, Vector3.new(base.Position.X, pos.Y, base.Position.Z)))

				local skip = System._lookRaySkip(rig)
				local rp = RaycastParams.new(); rp.FilterType = Enum.RaycastFilterType.Exclude; rp.FilterDescendantsInstances = skip; rp.RespectCanCollide = true
				local hit = workspace:Raycast(pos + Vector3.new(0, 4, 0), Vector3.new(0, -60, 0), rp)
					or workspace:Raycast(base.Position, Vector3.new(0, -60, 0), rp)
				if hit then e.floorY = hit.Position.Y end
				local hum = rig:FindFirstChildOfClass("Humanoid")
				if hum then hum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None end
				if type(label) == "string" and label ~= "" then
					local head = rig:FindFirstChild("Head") or hrp
					local bb = Instance.new("BillboardGui")
					bb.Name = "RC_LookTag"; bb.Size = UDim2.fromOffset(220, 26); bb.StudsOffset = Vector3.new(0, 2.6, 0); bb.AlwaysOnTop = true; bb.MaxDistance = 60
					local t = Instance.new("TextLabel")
					t.BackgroundTransparency = 0.35; t.BackgroundColor3 = Color3.fromRGB(12, 12, 18); t.Size = UDim2.fromScale(1, 1)
					t.Text = label:gsub("[^\32-\126]", ""):sub(1, 60); t.TextColor3 = Color3.fromRGB(253, 253, 255); t.TextScaled = true; t.Font = Enum.Font.GothamBold
					local c = Instance.new("UICorner"); c.CornerRadius = UDim.new(0, 8); c.Parent = t
					t.Parent = bb; bb.Adornee = head; bb.Parent = rig
				end
			end)
			System.NPCs[key] = rig
			local okA = pcall(Function.PlayerDataAdd, key)
			local pd = PlayerData[key]
			if not (okA and pd) then System.lookPreviewClear(slot, true); return false, "Couldn't set up the mannequin." end
			pd.IsClone = true; pd.Character = rig; pd.RealCharacter = nil
			local okB, err = pcall(function()
				local bundle = rehydrate(rec.bundle)
				local tweaks = (type(rec.tweaks) == "table" and rehydrate(rec.tweaks)) or nil
				bundle = System._avsyncPrepBundle(bundle, tweaks)
				Bundle[key] = bundle
				pd.CurrentBundle, pd.CurrentPreset, pd.CurrentClothingBundles = key, nil, {}
				Function.ApplyBundleToPeerData(key, bundle)
				_overlayTweaks(key, tweaks)
			end)
			if not okB then System.lookPreviewClear(slot, true); return false, "Couldn't read that look: " .. tostring(err):sub(1, 80) end
			pd.LastRequestID = (pd.LastRequestID or 0) + 1
			local rid = pd.LastRequestID
			pcall(Function.CharacterReset, rig)
			local called, ticket = pcall(Function.CharacterExecute, rig, key, nil, rid)
			local deadline = os.clock() + 60
			while called and type(ticket) == "table" and not ticket.done and pd.LastRequestID == rid and os.clock() < deadline do task.wait(0.1) end
			if System._lookPrev[slot] ~= e then return false, "Replaced by a newer preview." end
			if not (called and type(ticket) == "table" and ticket.done == true and ticket.ok == true) then
				pcall(System._lookPrevGround, e)
				if System._lookPh[slot] then pcall(function() System._lookPh[slot]:Destroy() end); System._lookPh[slot] = nil end
				local why = (not called and tostring(ticket)) or (type(ticket) == "table" and ticket.error ~= nil and tostring(ticket.error)) or "the build did not finish"
				return false, "Built with problems: " .. why:sub(1, 80)
			end
			pcall(System._cloneIdle, rig, true, true)



			pcall(System._lookPrevGround, e)
			for _, t in ipairs({ 0.6, 2 }) do task.delay(t, function() if System._lookPrev[slot] == e then pcall(System._lookPrevGround, e) end end) end
			if System._lookPh[slot] then pcall(function() System._lookPh[slot]:Destroy() end); System._lookPh[slot] = nil end
			return true
		end
		System._lookPrevGround = function(e)
			local rig = e and e.rig
			if not (rig and rig.Parent and e.floorY) then return end
			local low = math.huge



			for _, p in ipairs(rig:GetDescendants()) do
				if p:IsA("BasePart") and p.Name ~= "HumanoidRootPart" and p.Transparency < 1 and p.LocalTransparencyModifier < 1
					and not p:FindFirstAncestorWhichIsA("Accessory") and not p:FindFirstAncestorWhichIsA("Tool") then
					local cf, sz = p.CFrame, p.Size
					local ext = math.abs(cf.RightVector.Y) * sz.X / 2 + math.abs(cf.UpVector.Y) * sz.Y / 2 + math.abs(cf.LookVector.Y) * sz.Z / 2
					low = math.min(low, p.Position.Y - ext)
				end
			end
			if low == math.huge then return end
			local dy = e.floorY - low
			if math.abs(dy) > 0.05 and math.abs(dy) < 40 then rig:PivotTo(rig:GetPivot() + Vector3.new(0, dy, 0)) end
		end
		System._avsyncPrepBundle = function(bundle, tweaks)
			if type(bundle) ~= "table" then return bundle end
			if Function._liftPresetTweaks then
				local okL, lifted = pcall(Function._liftPresetTweaks, bundle)
				if okL and type(lifted) == "table" then bundle = lifted end
			end
			if type(tweaks) == "table" then
				if tweaks.community ~= nil then bundle.Community = type(tweaks.community) == "table" and tweaks.community or nil end
				if type(tweaks.meshEdit) == "table" then bundle.MeshEdit = tweaks.meshEdit end
				if type(tweaks.tailSettings) == "table" then
					local p = {}
					if type(bundle.Preset) == "table" then for k, v in pairs(bundle.Preset) do p[k] = v end end
					p.tailSettings = tweaks.tailSettings
					bundle.Preset = p
				end
			end
			return bundle
		end
		System._avsGearState = System._avsGearState or {}
		System._avsGearTpl = System._avsGearTpl or {}






		System._avsGearSanitize = function(tpl)
			local parts, lights = 0, 0
			for _, d in ipairs(tpl:GetDescendants()) do
				if d:IsA("LuaSourceContainer") or d:IsA("Sound") or d:IsA("ParticleEmitter") or d:IsA("Fire") or d:IsA("Smoke")
					or d:IsA("Sparkles") or d:IsA("Explosion") or d:IsA("LayerCollector") or d:IsA("Beam") or d:IsA("Highlight")
					or d:IsA("ProximityPrompt") or d:IsA("ClickDetector") or d.ClassName == "DragDetector" then
					pcall(function() d:Destroy() end)
				elseif d:IsA("Light") then
					lights = lights + 1
					if lights > 4 then pcall(function() d:Destroy() end)
					else pcall(function() d.Shadows = false; d.Brightness = math.clamp(d.Brightness, 0, 2) end) end
				elseif d:IsA("Trail") then
					pcall(function() d.Lifetime = math.min(d.Lifetime, 2); d.FaceCamera = false end)
				elseif d:IsA("BasePart") then
					parts = parts + 1
					local sz = d.Size
					if parts > 150 or sz.X > 24 or sz.Y > 24 or sz.Z > 24 then return false end
				elseif d:IsA("SpecialMesh") then
					local sc = d.Scale
					if math.abs(sc.X) > 12 or math.abs(sc.Y) > 12 or math.abs(sc.Z) > 12 then return false end
				end
			end
			local h = tpl:FindFirstChild("Handle")
			return (h ~= nil and h:IsA("BasePart"))
		end
		System._avsyncGear = function(name, char, gearId)
			local G = System._avsGearState
			local id = tonumber(gearId)
			if id and (id <= 0 or id % 1 ~= 0 or id > 1e12) then id = nil end
			local st = G[name]
			if st and st.id == id and st.char == char and st.model and st.model.Parent == char then return end
			if st and st.model then pcall(function() st.model:Destroy() end) end
			G[name] = nil
			if not (id and char and char.Parent) then return end
			st = { id = id, char = char }
			G[name] = st
			local tpl = System._avsGearTpl[id]
			if tpl == nil then
				tpl = false
				local okO, objs = pcall(function() return game:GetObjects("rbxassetid://" .. tostring(id)) end)
				if okO and type(objs) == "table" then
					for _, o in ipairs(objs) do
						local t = (typeof(o) == "Instance") and ((o:IsA("Tool") and o) or o:FindFirstChildWhichIsA("Tool", true))
						if t then tpl = t; break end
					end
				end
				if tpl and not System._avsGearSanitize(tpl) then tpl = false end

				if okO then
				System._avsGearTplN = (System._avsGearTplN or 0) + 1
				if System._avsGearTplN > 48 then
					for _, old in pairs(System._avsGearTpl) do if typeof(old) == "Instance" then pcall(function() old:Destroy() end) end end
					System._avsGearTpl, System._avsGearTplN = {}, 1
				end
				System._avsGearTpl[id] = tpl
				end
			end
			if G[name] ~= st or not tpl or not char.Parent then return end
			local hand = char:FindFirstChild("RightHand") or char:FindFirstChild("Right Arm")
			if not (hand and hand:IsA("BasePart")) then return end
			local att = hand:FindFirstChild("RightGripAttachment")
			local c0 = (att and att:IsA("Attachment")) and att.CFrame or CFrame.new(0, -1, 0, 1, 0, 0, 0, 0, 1, 0, -1, 0)
			local ok = pcall(function()
				local tool = tpl:Clone()
				local grip = tool.Grip

				local model = Instance.new("Model")
				model.Name = "_RC_PeerGear"
				for _, c in ipairs(tool:GetChildren()) do c.Parent = model end
				tool:Destroy()
				local handle = model:FindFirstChild("Handle")
				for _, d in ipairs(model:GetDescendants()) do
					if d:IsA("BasePart") then
						d.Anchored = false; d.CanCollide = false; d.Massless = true
						pcall(function() d.CanTouch = false; d.CanQuery = false end)
					end
				end
				handle.CFrame = hand.CFrame * c0 * grip:Inverse()
				local w = Instance.new("Weld")
				w.Name = "RightGrip"; w.Part0 = hand; w.Part1 = handle; w.C0 = c0; w.C1 = grip
				w.Parent = handle
				model.Parent = char
				st.model = model
			end)
			if not ok and G[name] == st then G[name] = nil end
		end


		local function _runExecuteForPeer(foreign, dataKey, bundleData, tweaks, current)

			local _stillLive = function() return foreign and foreign.Parent == PS and (not current or current()) end
			if not _stillLive() then return false, "peer left before apply" end
			local _safeBundle = bundleData


			pcall(function() _safeBundle = Function.DeepClone(bundleData) end)
			if System._avsyncPrepBundle then _safeBundle = System._avsyncPrepBundle(_safeBundle, tweaks) end
			Bundle[dataKey] = _safeBundle
			Function.PlayerDataAdd(foreign.Name)
			if not _stillLive() then return false, "peer left during PlayerDataAdd" end
			local pd = PlayerData[foreign.Name]
			if not pd then return false, "PlayerData add failed" end
			pd.CurrentBundle           = dataKey
			pd.CurrentPreset           = nil
			pd.CurrentClothingBundles  = {}
			Function.ApplyBundleToPeerData(foreign.Name, _safeBundle)
			if not _stillLive() then return false, "peer left during ApplyBundleToPeerData" end
			_overlayTweaks(foreign.Name, tweaks)
			pd.LastRequestID = (pd.LastRequestID or 0) + 1
			local rid = pd.LastRequestID
			pcall(Function.CharacterReset, foreign.Name)
			if not _stillLive() then return false, "peer left during CharacterReset" end
			local called, ticket = pcall(Function.CharacterExecute, foreign.Character, foreign.Name, nil, rid)
			if not called then return false, ticket end
			if type(ticket) ~= "table" then return false, "missing build completion" end
			local deadline = os.clock() + 30
			while not ticket.done and _stillLive() and pd.LastRequestID == rid and os.clock() < deadline do task.wait(0.05) end
			if not _stillLive() or pd.LastRequestID ~= rid then
				if pd.LastRequestID == rid then pd.LastRequestID = rid + 1 end
				return false, "superseded"
			end
			if not ticket.done then
				pd.LastRequestID = rid + 1
				return false, "build completion timeout"
			end
			if ticket.ok == true and System._avsyncGear then
				task.spawn(System._avsyncGear, foreign.Name, foreign.Character, tweaks and tweaks.gearId)
			end
			return ticket.ok == true, ticket.error
		end



		System._avsyncBackoff = function(fails, base, cap)
			local n = math.max(1, tonumber(fails) or 1)
			return math.min((base or 3) * 2 ^ (n - 1), cap or 60)
		end

		local function _syncApplyToPeer(userId, bundleData, updatedAt, tweaks)
			local AS = System.AvatarSync
			if not AS.enabled or (System.isOff and System.isOff("avatarSync")) or not _isActiveSession() or userId == Player.UserId then return end
			local foreign = PS:GetPlayerByUserId(userId)
			if not foreign then return end
			local entry = AS.syncedPeers[userId]
			if System.Ext and System.Ext.onPeerState and not (entry and entry.lastUpdatedMs == updatedAt) then pcall(System.Ext.onPeerState, userId, type(tweaks) == "table" and tweaks.ext or nil) end
			if System.getSelectPlayer() == foreign.Name then
				if entry and entry.characterAddedConn then entry.characterAddedConn:Disconnect() end
				AS.syncedPeers[userId] = nil
				if System._avsyncGear then pcall(System._avsyncGear, foreign.Name, nil, nil) end
				return
			end
			if not entry then
				entry = {dataKey = "_peer_" .. foreign.Name, playerName = foreign.Name, generation = 0}
				AS.syncedPeers[userId] = entry
				entry.characterAddedConn = foreign.CharacterAdded:Connect(function()
					if AS.syncedPeers[userId] ~= entry then return end
					entry.generation = entry.generation + 1
					entry.applied, entry.pending, entry.retryAt, entry.fails = false, false, nil, nil
				end)
			end
			if entry.applied and entry.lastUpdatedMs ~= updatedAt and System.Ext and System.Ext.sameLook and System.Ext.sameLook(entry.bundleData, entry.tweaks, bundleData, tweaks) then entry.lastUpdatedMs, entry.tweaks = updatedAt, tweaks; return end
			if entry.lastUpdatedMs ~= updatedAt then
				entry.generation = entry.generation + 1
				entry.lastUpdatedMs, entry.bundleData, entry.tweaks = updatedAt, bundleData, tweaks
				entry.applied, entry.pending, entry.retryAt, entry.fails = false, false, nil, nil
			end
			if entry.applied or entry.pending or not foreign.Character then return end
			if entry.buildingAt and os.clock() - entry.buildingAt < 90 then return end
			if entry.retryAt and os.clock() < entry.retryAt then return end
			entry.pending = true
			local generation = entry.generation
			local character = foreign.Character
			local function current()
				return AS.enabled and _isActiveSession() and AS.syncedPeers[userId] == entry
					and entry.generation == generation and foreign.Character == character
					and foreign.Parent == PS and System.getSelectPlayer() ~= foreign.Name
			end
			task.spawn(function()
				if not current() then return end
				entry.buildingAt = os.clock()
				local ran, ok, err = pcall(_runExecuteForPeer, foreign, entry.dataKey, entry.bundleData, entry.tweaks, current)
				entry.buildingAt = nil
				if not current() then return end
				entry.pending = false
				entry.applied = ran and ok == true
				if not entry.applied then
					entry.fails = (entry.fails or 0) + 1
					entry.retryAt = os.clock() + System._avsyncBackoff(entry.fails)
					AS.lastError = "apply " .. foreign.Name .. ": " .. tostring(ran and (err or "build failed") or ok):sub(1,60)
					AS.lastErrorAt = (tick and tick()) or os.clock()
				else
					entry.fails = nil
				end
			end)
		end

		local function _syncRemovePeer(userId, force)
			local AS = System.AvatarSync
			local entry = AS.syncedPeers[userId]
			if not entry then return end


			if entry.playerName == System.getSelectPlayer() and not force then
				return
			end
			if entry.characterAddedConn then
				pcall(function() entry.characterAddedConn:Disconnect() end)
			end
			if System._avsyncGear then pcall(System._avsyncGear, entry.playerName, nil, nil) end


			if PlayerData[entry.playerName] then
				PlayerData[entry.playerName].LastRequestID = (PlayerData[entry.playerName].LastRequestID or 0) + 1
				pcall(Function.CharacterReset, entry.playerName)

				if PlayerData[entry.playerName].ExecutionMaid then
					pcall(function() PlayerData[entry.playerName].ExecutionMaid:DoCleaning() end)
				end
				PlayerData[entry.playerName] = nil
			end
			Bundle[entry.dataKey] = nil
			if Method2CharacterFolder then
				local m = Method2CharacterFolder:FindFirstChild(entry.playerName)
				if m then pcall(function() m:Destroy() end) end
			end
			AS.syncedPeers[userId] = nil
		end






		System._avsyncCloneCfg = function()
			local c = (System._cloneCfg and System._cloneCfg()) or {}
			return c.share ~= false, c.show ~= false, math.clamp(tonumber(c.max) or 5, 1, 30)
		end
		System._avsyncCfArr = function(cf)
			local t = { cf:GetComponents() }
			for i = 1, 12 do t[i] = math.floor(t[i] * 1000 + 0.5) / 1000 end
			return t
		end



		local _poseJoints = setmetatable({}, { __mode = "k" })
		local function _jointsOf(rig)
			local e = _poseJoints[rig]
			if e and not e.dirty then return e.list end
			if not e then
				e = { dirty = true, conns = {} }
				_poseJoints[rig] = e
				local function dirty() e.dirty = true end
				e.conns[1] = rig.DescendantAdded:Connect(dirty)
				e.conns[2] = rig.DescendantRemoving:Connect(dirty)
				e.conns[3] = rig.Destroying:Connect(function() for _, c in ipairs(e.conns) do c:Disconnect() end; _poseJoints[rig] = nil end)
			end
			local list = {}
			for _, j in ipairs(rig:GetDescendants()) do
				if j:IsA("Motor6D") or j:IsA("AnimationConstraint") then list[#list + 1] = j end
			end
			e.list, e.dirty = list, false
			return list
		end
		System._avsyncJointsOf = _jointsOf
		System._avsyncPoseOf = function(rig)
			local out = {}
			for _, j in ipairs(_jointsOf(rig)) do
				local isM = j:IsA("Motor6D")
				if isM or j:IsA("AnimationConstraint") then
					local p1 = isM and j.Part1 or (j.Attachment1 and j.Attachment1.Parent)
					local c0 = isM and j.C0 or (j.Attachment0 and j.Attachment0.CFrame)
					local c1 = isM and j.C1 or (j.Attachment1 and j.Attachment1.CFrame)
					if p1 and c0 and c1 then out[j.Name .. "|" .. p1.Name] = System._avsyncCfArr(c0 * c1:Inverse()) end
				end
			end
			return out
		end


		System._avsyncCloneFp = function(key, rig, pd, cfStr)
			local parts = { cfStr, tostring(pd.LastRequestID), tostring(System._cloneDisplayName and System._cloneDisplayName(key)) }
			for k, v in pairs(System._avsyncPoseOf(rig)) do parts[#parts + 1] = k .. "=" .. table.concat(v, ",") end
			for k, go in pairs(pd.GizmoOffsets or {}) do
				if type(go) == "table" then
					local r = (typeof(go.RotCF) == "CFrame") and table.concat(System._avsyncCfArr(go.RotCF), ",") or ""
					parts[#parts + 1] = tostring(k) .. ":" .. tostring(go.PosX) .. "," .. tostring(go.PosY) .. "," .. tostring(go.PosZ) .. "," .. tostring(go.Scale) .. "," .. r
				end
			end
			table.sort(parts)
			return table.concat(parts, ";")
		end





		System._avsyncCanon = function(v, depth)
			depth = depth or 0
			if type(v) ~= "table" then return typeof(v) .. ":" .. tostring(v) end
			if depth > 16 then return "{...}" end
			local keys = {}
			for k in pairs(v) do keys[#keys + 1] = k end
			table.sort(keys, function(a, b) return tostring(a) < tostring(b) end)
			local out = {}
			for _, k in ipairs(keys) do out[#out + 1] = tostring(k) .. "=" .. System._avsyncCanon(v[k], depth + 1) end
			return "{" .. table.concat(out, ",") .. "}"
		end
		System._avsyncLookSig = function(rec)
			local tw = {}
			if type(rec.tweaks) == "table" then for k, v in pairs(rec.tweaks) do if k ~= "gizmoOffsets" and k ~= "gizmoOffset" and k ~= "ext" then tw[k] = v end end end
			return System._avsyncCanon({ rec.bundle, tw, rec.name })
		end

		System._rcDeadline = System._rcDeadline or function(secs, fn)
			local done, ok, a, b = false, false, nil, nil
			task.spawn(function() ok, a, b = pcall(fn); done = true end)
			local t0 = os.clock()
			while not done and os.clock() - t0 < secs do task.wait() end
			if not done then return true end
			return false, ok, a, b
		end
		System._avsyncPostClone = function(slot, data)
			local AS = System.AvatarSync
			local _W = System._avsWs
			if _W and _W.stopped then return false end
			if _W and _W.mode == "ws" then return _W.clone(slot, data) end
			if _W and (_W.mode == "connecting" or _W.mode == "backoff") then return false end
			local req = _httpReq(); if not req then return false end
			local payload = {
				placeId = AS.placeId, jobId = AS.jobId, userId = Player.UserId, displayName = Player.DisplayName,
				scriptVersion = VersionInternal, updatedAt = _syncNowMs(),
				bundle = data and data.bundle or nil, tweaks = data and data.tweaks or nil,
				clone = (data and data.clone) or { slot = slot, remove = true },
			}
			local okB, body = pcall(HS.JSONEncode, HS, payload); if not okB then return false end
			local _to, okR, res = System._rcDeadline(30, function() return req({ Url = PUBLISH_URL, Method = "POST", Headers = { ["Content-Type"] = "application/json", ["X-RC-Token"] = (System._rcaTok and System._rcaTok()) or "" }, Body = body }) end)
			if _to then AS.publishError = "clone publish timed out"; AS.publishErrorAt = (tick and tick()) or os.clock(); return false end
			local code = (okR and res and tonumber(res.StatusCode)) or 0
			if code >= 200 and code < 300 then
				local okJ, parsed = _safeDecodeJsonBody(res)
				if okJ and parsed.error == "not_present" then


					if data == nil then return true end

					AS.userActed = true
					if Function.AvatarSyncPublish then pcall(Function.AvatarSyncPublish, true, AS.forceClear == true) end
					return false
				end
				return okJ and parsed.ok == true
			end
			AS.publishError = "clone publish " .. tostring(code)
			AS.publishErrorAt = (tick and tick()) or os.clock()
			return false
		end
		System._avsyncPostClonePos = function(pos)
			local AS = System.AvatarSync
			local _W = System._avsWs
			if _W and _W.mode == "ws" then _W.cpos(pos); return end
			if _W and (_W.stopped or _W.mode == "connecting" or _W.mode == "backoff") then return end
			local req = _httpReq(); if not req then return end
			local okB, body = pcall(HS.JSONEncode, HS, { placeId = AS.placeId, jobId = AS.jobId, userId = Player.UserId, pos = pos })
			if okB then task.spawn(System._rcDeadline, 30, function() return req({ Url = "https://krulhub.dev/avatar/clonepos", Method = "POST", Headers = { ["Content-Type"] = "application/json", ["X-RC-Token"] = (System._rcaTok and System._rcaTok()) or "" }, Body = body }) end) end
		end


		System._avsyncCloneTick = function()
			local AS = System.AvatarSync
			if not (AS and AS.enabled and AS.placeId) then return end
			local share = System._avsyncCloneCfg()
			AS._clonePub = AS._clonePub or {}
			if not AS._clonePubInit then
				AS._clonePubInit = true
				for slot = 1, 8 do if not AS._clonePub[slot] then AS._clonePub[slot] = { key = "?stale" } end end
			end
			local want = {}
			if share then
				for i, key in ipairs(System.CloneOrder or {}) do
					if i > 8 then break end
					local rig = System.NPCs and System.NPCs[key]
					if rig and rig.Parent and PlayerData[key] and not (System.Ext and System.Ext.isPrivateRig and System.Ext.isPrivateRig(rig)) then want[i] = { key = key, rig = rig, pd = PlayerData[key] } end
				end
			end
			local now, posBatch = os.clock(), {}
			for slot = 1, 8 do
				local w, pub = want[slot], AS._clonePub[slot]
				if not w then
					if pub and System._avsyncPostClone(slot, nil) then AS._clonePub[slot] = nil end
				else
					local cfArr = System._avsyncCfArr(w.rig:GetPivot())
					local cfStr = table.concat(cfArr, ",")
					if pub and pub.key == w.key and System._possessed == w.key then
						if pub.cfStr ~= cfStr then posBatch[tostring(slot)] = cfArr; pub.cfStr = cfStr end
					else



						local _skipFp = pub and pub.key == w.key and pub.fpChk and now - pub.fpChk < 2
						local fp = (not _skipFp) and System._avsyncCloneFp(w.key, w.rig, w.pd, cfStr) or nil
						if pub and fp then pub.fpChk = now end
						if not _skipFp and (not pub or pub.key ~= w.key or pub.fp ~= fp) then
						local ok, dehyd, tweaks = pcall(System._avsyncBuildPayload, w.pd, w.rig, false)
						if ok and dehyd then
							local name = (System._cloneDisplayName and System._cloneDisplayName(w.key)) or w.key
							local clone = { slot = slot, name = tostring(name):sub(1, 32), cf = cfArr, pose = System._avsyncPoseOf(w.rig) }
							local okE, enc = pcall(HS.JSONEncode, HS, { dehyd, tweaks or false, clone })
							local h = okE and enc
							if h and (not pub or pub.hash ~= h) then
								if System._avsyncPostClone(slot, { bundle = dehyd, tweaks = tweaks, clone = clone }) then
									AS._clonePub[slot] = { hash = h, key = w.key, at = now, cfStr = cfStr, fp = fp, fpChk = now }
								end
							elseif pub then
								pub.fp = fp
							end
						end
						end
					end
				end
			end
			if next(posBatch) then System._avsyncPostClonePos(posBatch) end
		end

		System._avsyncDropClone = function(id, keepRecord)
			local AS = System.AvatarSync
			local e = AS.peerClones and AS.peerClones[id]; if not e then return end
			if e.key then
				local pd = PlayerData[e.key]
				if pd and pd.ExecutionMaid then pcall(function() pd.ExecutionMaid:DoCleaning() end) end
				PlayerData[e.key] = nil; Bundle[e.key] = nil
				if System.NPCs then System.NPCs[e.key] = nil end
			end
			if e.rig then pcall(function() e.rig:Destroy() end) end
			e.rig, e.walkTrack, e.lookSig = nil, nil, nil
			if keepRecord then e.dirty = true else AS.peerClones[id] = nil end
		end
		System._avsyncTargetOf = function(e)
			local AS = System.AvatarSync
			local live = AS.clonePos and AS.clonePos[tostring(e.owner)]
			local arr = (type(live) == "table" and live[tostring(e.slot)]) or (e.rec and e.rec.cf)
			if type(arr) == "table" and #arr == 12 then
				local ok, cf = pcall(CFrame.new, table.unpack(arr)); if ok then return cf end
			end
		end


		System._avsyncCloneWalk = function(e, moving)
			if moving then
				if not e.walkTrack and e.walkId and not e.walkFailed then
					local hum = e.rig:FindFirstChildOfClass("Humanoid")
					if hum then
						local an = hum:FindFirstChildOfClass("Animator") or Instance.new("Animator", hum)
						local a = Instance.new("Animation"); a.AnimationId = e.walkId
						local ok, t = pcall(an.LoadAnimation, an, a)
						if ok and t then t.Looped = true; t.Priority = Enum.AnimationPriority.Movement; e.walkTrack = t else e.walkFailed = true end
					end
				end
				local t = e.walkTrack
				if t then
					if not t.IsPlaying then t:Play(0.2) end
					local _sp = math.clamp((e.pace or 16) / 14, 0.4, 2)
					if e.walkSpeed ~= _sp then e.walkSpeed = _sp; t:AdjustSpeed(_sp) end
				end
			elseif e.walkTrack and e.walkTrack.IsPlaying then
				e.walkTrack:Stop(0.25)
			end
		end
		System._avsyncPoseApply = function(rig, pose)
			if type(pose) ~= "table" then return end
			for _, j in ipairs(System._avsyncJointsOf(rig)) do
				local isM = j:IsA("Motor6D")
				if isM or j:IsA("AnimationConstraint") then
					local p1 = isM and j.Part1 or (j.Attachment1 and j.Attachment1.Parent)
					local arr = p1 and pose[j.Name .. "|" .. p1.Name]
					if type(arr) == "table" and #arr == 12 then
						pcall(function()
							local J = CFrame.new(table.unpack(arr))
							local nc = isM and (J * j.C1) or (J * j.Attachment1.CFrame)
							if not isM then pcall(function() j.IsKinematic = true end) end
							local cur = isM and j.C0 or j.Attachment0.CFrame

							if (cur.Position - nc.Position).Magnitude < 1e-3 and cur.LookVector:Dot(nc.LookVector) > 0.99999 and cur.UpVector:Dot(nc.UpVector) > 0.99999 then return end
							if isM then j.C0 = nc else j.Attachment0.CFrame = nc end
						end)
					end
				end
			end
		end
		System._avsyncBuildClone = function(id)
			local AS = System.AvatarSync
			local e = AS.peerClones and AS.peerClones[id]
			if not e or e.building then return end
			if e.retryAt and os.clock() < e.retryAt then return end
			e.building, e.dirty = true, false
			e.buildOk, e.buildErr = nil, nil
			local _noOwner = false
			local sig = e.pendingSig
			e.buildingSig = sig
			local ok, err = pcall(function()
				local owner = PS:GetPlayerByUserId(e.owner)
				local ownerChar = owner and owner.Character
				if not ownerChar then e.dirty = true; _noOwner = true; return end
				local key = "_pclone_" .. e.owner .. "_" .. e.slot
				e.key = key
				do
					local am = ownerChar:FindFirstChild("Animate")
					for _, folder in ipairs({ "walk", "run" }) do
						local f = am and am:FindFirstChild(folder)
						local a = f and f:FindFirstChildOfClass("Animation")
						if a and a.AnimationId ~= "" then e.walkId = a.AnimationId; break end
					end
				end
				if not (e.rig and e.rig.Parent) then
					local rig = System._buildCloneRig(key, ownerChar)
					if not rig then e.buildOk, e.buildErr = false, "clone rig could not be built"; return end
					e.rig, e.walkTrack, e.walkFailed = rig, nil, nil
					pcall(function() local hrp = rig:FindFirstChild("HumanoidRootPart"); if hrp then hrp.Anchored = true end end)
				end
				local rig = e.rig
				System.NPCs[key] = rig
				Function.PlayerDataAdd(key)
				local pd = PlayerData[key]
				pd.IsClone = true; pd.Character = rig; pd.RealCharacter = nil
				local bundle = rehydrate(e.rec.bundle)
				local tweaks = (type(e.rec.tweaks) == "table" and rehydrate(e.rec.tweaks)) or nil
				if System._avsyncPrepBundle then bundle = System._avsyncPrepBundle(bundle, tweaks) end
				Bundle[key] = bundle
				pd.CurrentBundle, pd.CurrentPreset, pd.CurrentClothingBundles = key, nil, {}
				Function.ApplyBundleToPeerData(key, bundle)
				_overlayTweaks(key, tweaks)
				pd.LastRequestID = (pd.LastRequestID or 0) + 1
				local rid = pd.LastRequestID
				pcall(Function.CharacterReset, rig)
				local called, ticket = pcall(Function.CharacterExecute, rig, key, nil, rid)
				local deadline = os.clock() + 60
				while called and type(ticket) == "table" and not ticket.done and pd.LastRequestID == rid and os.clock() < deadline do task.wait(0.1) end


				if not (called and type(ticket) == "table" and ticket.done == true and ticket.ok == true) then
						e.buildOk = false

						e.buildErr = (not called and tostring(ticket)) or (type(ticket) == "table" and ticket.error ~= nil and tostring(ticket.error)) or nil
						return
				end
				local t = System._avsyncTargetOf(e)
				if t then pcall(function() rig:PivotTo(t) end) end
				System._avsyncPoseApply(rig, e.rec.pose)
				System._cloneIdle(rig, true, true)
				e.lookSig = sig
			end)
			e.building = false
			if not ok or e.buildOk == false then


				e.buildOk = nil; e.dirty = true
				e.fails = (e.fails or 0) + 1
				e.retryAt = os.clock() + System._avsyncBackoff(e.fails)
				AS.lastError = ok and ("clone build failed" .. (e.buildErr and (": " .. e.buildErr:sub(1, 40)) or "")) or ("clone: " .. tostring(err):sub(1, 50))
				AS.lastErrorAt = (tick and tick()) or os.clock()
			elseif _noOwner then
				e.buildOk = nil
			else
				e.buildOk = nil; e.fails, e.retryAt = nil, nil
			end
		end



		System._avsyncCloneOk = function(c, counts)
			if type(c) ~= "table" then return nil end
			local owner, slot = tonumber(c.ownerId), tonumber(c.slot)
			if not owner or owner % 1 ~= 0 or owner == 0 or math.abs(owner) > 1e12 then return nil end
			if not slot or slot % 1 ~= 0 or slot < 1 or slot > 8 then return nil end
			if type(c.bundle) ~= "table" then return nil end

			local _bt = c.bundle.__t
			if _bt == "V3" or _bt == "CF" or _bt == "C3" or _bt == "C3n" or _bt == "E" then return nil end
			local function _finite(n) return type(n) == "number" and n == n and n ~= math.huge and n ~= -math.huge end
			local function _cfOk(t)
				if type(t) ~= "table" or #t ~= 12 then return false end
				for i = 1, 12 do if not _finite(t[i]) then return false end end
				return true
			end
			if c.cf ~= nil and not _cfOk(c.cf) then return nil end
			if c.pose ~= nil then
				if type(c.pose) ~= "table" then return nil end
				for _, arr in pairs(c.pose) do if not _cfOk(arr) then return nil end end
			end
			if counts then
				local n = (counts[owner] or 0) + 1
				if n > 8 then return nil end
				counts[owner] = n
			end
			return owner, slot
		end


		System._avsyncClonesOnPoll = function(parsed, delta)
			local AS = System.AvatarSync
			AS.peerClones = AS.peerClones or {}
			local _, show, maxN = System._avsyncCloneCfg()
			if type(parsed.clones) == "table" then
				local _perOwner = {}
				for _, c in ipairs(parsed.clones) do
					local owner, slot = System._avsyncCloneOk(c, _perOwner)


					local joined = AS._ownerJoinMs and owner and AS._ownerJoinMs[owner]
					local stale = joined and (tonumber(c.updatedAt) or 0) < joined - 3000
					if owner and owner ~= Player.UserId and not stale then
						local id = owner .. ":" .. slot
						local e = AS.peerClones[id] or { owner = owner, slot = slot }
						local sig = System._avsyncLookSig(c)
						if e.rig and e.rig.Parent and not e.building and e.lookSig == sig then

							e.rec = c
							System._avsyncPoseApply(e.rig, c.pose)
							if e.key and type(c.tweaks) == "table" and type(c.tweaks.gizmoOffsets) == "table" then
								pcall(_overlayTweaks, e.key, { gizmoOffsets = rehydrate(c.tweaks.gizmoOffsets) })
							end
						elseif e.building and e.buildingSig == sig then
							e.rec = c
						else
							if e.pendingSig ~= sig then e.retryAt, e.fails = nil, nil end
							e.rec, e.dirty, e.pendingSig = c, true, sig
						end
						AS.peerClones[id] = e
					end
				end
			end
			local presentSet
			if type(parsed.clonePresent) == "table" then
				presentSet = {}
				for _, id in ipairs(parsed.clonePresent) do presentSet[tostring(id)] = true end
			end
			if delta then
				AS.clonePos = AS.clonePos or {}
				if type(parsed.clonePos) == "table" then for k, v in pairs(parsed.clonePos) do AS.clonePos[tostring(k)] = v end end
			else
				AS.clonePos = (type(parsed.clonePos) == "table" and parsed.clonePos) or {}
			end
			local ids = {}
			for id, e in pairs(AS.peerClones) do
				if (not presentSet or presentSet[id]) and PS:GetPlayerByUserId(e.owner) then ids[#ids + 1] = id else System._avsyncDropClone(id) end
			end
			table.sort(ids)
			if #ids ~= (AS.cloneServerCount or 0) then
				AS.cloneServerCount = #ids
				if #ids > 0 and System.uiToast then
					local msg = #ids .. " shared clone" .. (#ids == 1 and "" or "s") .. " in this server"
					if not show then msg = msg .. " (hidden in Settings)" elseif #ids > maxN then msg = msg .. " - showing " .. maxN end
					pcall(System.uiToast, "Shared clones", msg, "info")
				end
			end
			for i, id in ipairs(ids) do
				local e = AS.peerClones[id]
				if show and i <= maxN then
					if e.dirty and not e.building then task.spawn(System._avsyncBuildClone, id) end
					if e.rig and not e.building then
						local t = System._avsyncTargetOf(e)
						if t and e.target and (t.Position - e.target.Position).Magnitude > 0.05 then
							local d = (t.Position - e.rig:GetPivot().Position).Magnitude
							e.pace = (d > 60) and 1e4 or math.clamp(d / 1.5, 2, 40)
						end
						e.target = t
					end
				elseif e.rig then
					System._avsyncDropClone(id, true)
				end
			end
		end

		System._avsyncCloneLoop = function()
			local AS = System.AvatarSync
			local RS = game:GetService("RunService")

			AS._ownerJoinMs = AS._ownerJoinMs or {}
			local joinConn = PS.PlayerAdded:Connect(function(pl)
				AS._ownerJoinMs[pl.UserId] = _syncNowMs()
				for id, e in pairs(AS.peerClones or {}) do if e.owner == pl.UserId then System._avsyncDropClone(id) end end
			end)

			local glide = nil
			local function glideStep(dt)
				for _, e in pairs(AS.peerClones or {}) do
					if e.rig and e.target and not e.building then
						local cur = e.rig:GetPivot()
						local dist = (cur.Position - e.target.Position).Magnitude
						local moving = false
						if dist > 0.02 then

							local stepLen = math.min(dist, (e.pace or 16) * dt)
							if e.rig.Parent then e.rig:PivotTo(cur:Lerp(e.target, stepLen / dist)) end
							moving = dist > 0.15
							if moving then e.movedAt = os.clock() end
						end
						pcall(System._avsyncCloneWalk, e, moving or (os.clock() - (e.movedAt or 0)) < 0.5)
					end
				end
			end
			while _isActiveSession() and System._sessionAlive ~= false do
				task.wait(1)
				if AS.enabled then pcall(System._avsyncCloneTick) end
				local any = next(AS.peerClones or {}) ~= nil
				if any and not glide then glide = RS.RenderStepped:Connect(glideStep)
				elseif not any and glide then glide:Disconnect(); glide = nil end
			end
			if glide then glide:Disconnect() end
			joinConn:Disconnect()
			for id in pairs(AS.peerClones or {}) do pcall(System._avsyncDropClone, id) end
			AS._cloneLoop = false
		end
		Function.AvatarSyncPoll = function()
			local AS = System.AvatarSync
			if not AS.enabled or (System.isOff and System.isOff("avatarSync")) or AS.jobId == "" then return end
			local retryPeers = System._avsyncRetryPeers

			if not AS.nextFullPoll or os.clock() >= AS.nextFullPoll then
				AS.pollCursor = nil
				AS.nextFullPoll = os.clock() + 30
			end
			local req = _httpReq()
			if not req then return end
			local url = POLL_URL .. "?placeId=" .. tostring(AS.placeId)
				.. "&jobId=" .. HS:UrlEncode(AS.jobId)
				.. "&self=" .. tostring(Player.UserId)
				.. "&protocol=2&clones=1"
			if not AS._cloneLoop then AS._cloneLoop = true; task.spawn(System._avsyncCloneLoop) end
			if AS.pollCursor then url = url .. "&since=" .. tostring(AS.pollCursor) end
			local _toP, okReq, res = System._rcDeadline(30, function() return req({Url = url, Method = "GET", Headers = { ["X-RC-Token"] = (System._rcaTok and System._rcaTok()) or "" }}) end)
			if not AS.enabled or (System.isOff and System.isOff("avatarSync")) or not _isActiveSession() then return end
			if _toP or not okReq or not res then
				AS.lastError = _toP and "poll timed out" or "poll network error"
				AS.lastErrorAt = (tick and tick()) or os.clock()
				AS._pollFails = (AS._pollFails or 0) + 1
				return
			end
			local code = tonumber(res.StatusCode) or 0
			if code == 304 then AS.lastError = nil; AS._pollFails = nil; retryPeers(); return end
			if code < 200 or code >= 300 then
				AS.lastError = (code == 429) and "poll rate-limited" or ("poll " .. tostring(code))
				AS.lastErrorAt = (tick and tick()) or os.clock()
				AS._pollFails = (AS._pollFails or 0) + 1

				local _ra = type(res.Headers) == "table" and tonumber(res.Headers["Retry-After"] or res.Headers["retry-after"]) or nil
				if _ra or code == 429 then AS._pollRetryAfter = math.clamp(_ra or 10, 1, 300) end
				return
			end
			AS.lastError = nil
			AS._pollFails = nil


			local okJson, parsed = _safeDecodeJsonBody(res)
			if not okJson or not parsed.ok then


				AS.lastError = "poll: bad response"
				AS.lastErrorAt = (tick and tick()) or os.clock()
				return
			end

			AS.lastSeenCount = (type(parsed.entries) == "table") and #parsed.entries or 0
			pcall(System._avsyncClonesOnPoll, parsed)
			local present
			if parsed.protocol == 2 and type(parsed.present) == "table" then
				present = System._avsyncApplyRoster(parsed.present)
			end
			local nowMs = tonumber(parsed.now) or (os.time() * 1000)
			if type(parsed.entries) == "table" then
				for _, e in ipairs(parsed.entries) do System._avsyncApplyEntry(e, nowMs, present) end
			end
			if type(parsed.removed) == "table" then
				for _, uid in ipairs(parsed.removed) do
					local _uid = tonumber(uid)
					if _uid and _uid ~= Player.UserId then _syncRemovePeer(_uid) end
				end
			end



			if tonumber(parsed.now) then AS.clockOffsetMs = tonumber(parsed.now) - os.time() * 1000 end
			local _stale = {}
			for uid, entry in pairs(AS.syncedPeers) do
				if not present and nowMs - (entry.lastSeenMs or nowMs) > FOREIGN_STALE_MS then
					_stale[#_stale+1] = uid
				end
			end
			for _, uid in ipairs(_stale) do _syncRemovePeer(uid) end
			if tonumber(parsed.cursor) then AS.pollCursor = tonumber(parsed.cursor) end
			retryPeers()
		end





		System._avsyncApplyRoster = function(ids)
			local AS = System.AvatarSync
			local present = {}
			for _, uid in ipairs(type(ids) == "table" and ids or {}) do if tonumber(uid) then present[tonumber(uid)] = true end end
			AS.lastSeenCount = type(ids) == "table" and #ids or 0
			local removed = {}
			for uid in pairs(AS.syncedPeers) do if not present[uid] then removed[#removed+1] = uid end end
			for _, uid in ipairs(removed) do _syncRemovePeer(uid) end
			if System.Lights then for uid in pairs(System.Lights.peers) do if not present[uid] then System.Lights.dropPeer(uid) end end end
			for uid in pairs(System._avsyncAnimPeers or {}) do if not present[uid] then pcall(System._avsyncAnimDrop, uid) end end
			for uid in pairs(System._avsyncEmotePeers or {}) do if not present[uid] then pcall(System._avsyncAnimDrop, uid) end end
			return present
		end

		System._avsyncApplyEntry = function(e, nowMs, present)
			local AS = System.AvatarSync
			if not (type(e) == "table" and tonumber(e.userId) and type(e.bundle) == "table") then return end
			if present and not present[tonumber(e.userId)] then return end


			do
				local _s0 = AS.syncedPeers[tonumber(e.userId)]
				local _u0 = tonumber(e.updatedAt)
				if _s0 and _s0.applied == true and _u0 and _u0 > 0 and _s0.lastUpdatedMs == _u0 then
					_s0.lastSeenMs = tonumber(nowMs) or os.time()*1000
					if System.Lights then pcall(System.Lights.applyPeer, tonumber(e.userId), type(e.tweaks) == "table" and e.tweaks.lightRig or nil) end
					pcall(System._avsyncAnimPeer, tonumber(e.userId), type(e.tweaks) == "table" and e.tweaks.animPack or nil)
					return
				end
			end
			local rehydrated = rehydrate(e.bundle)
			if type(rehydrated) ~= "table" then return end




			local isEmptyBundle = rehydrated.ClearClothing == true or not (
				rehydrated.Clothing or rehydrated.Accessory or rehydrated.Clothes or
				rehydrated.Preset or rehydrated.MeshEdit or rehydrated.Recolor or
				rehydrated.NippleColor or rehydrated["Body Color"] or rehydrated.HPClothes
			)

			local tweaksHaveContent = false
			if type(e.tweaks) == "table" then
				tweaksHaveContent =
					(type(e.tweaks.clothingList)  == "table" and next(e.tweaks.clothingList)  ~= nil) or
					(type(e.tweaks.presetOverlay) == "table" and next(e.tweaks.presetOverlay) ~= nil) or
					(type(e.tweaks.clothesHP)     == "table" and next(e.tweaks.clothesHP)     ~= nil) or
					(type(e.tweaks.clothesRecolor)== "table" and next(e.tweaks.clothesRecolor)~= nil) or
					(e.tweaks.nippleColor ~= nil) or
					(e.tweaks.skinTone ~= nil) or
					(tonumber(e.tweaks.gearId) ~= nil) or
					(type(e.tweaks.community) == "table" and next(e.tweaks.community) ~= nil) or
					(type(e.tweaks.meshEdit) == "table" and next(e.tweaks.meshEdit) ~= nil)
			end

			local function _lights()
				if System.Lights then pcall(System.Lights.applyPeer, tonumber(e.userId), type(e.tweaks) == "table" and e.tweaks.lightRig or nil) end
				pcall(System._avsyncAnimPeer, tonumber(e.userId), type(e.tweaks) == "table" and e.tweaks.animPack or nil)
			end
			if isEmptyBundle and not tweaksHaveContent then
				_syncRemovePeer(tonumber(e.userId))
				_lights()
				return
			end


			local _okSig, _lookSig = pcall(function()
				local t = {}
				if type(e.tweaks) == "table" then for k, v in pairs(e.tweaks) do if k ~= "lightRig" and k ~= "animPack" and k ~= "gearId" then t[k] = v end end end
				return HS:JSONEncode(e.bundle) .. "|" .. HS:JSONEncode(t)
			end)
			do
				local _ent = AS.syncedPeers[tonumber(e.userId)]
				if _okSig and _ent and _ent.lookSig == _lookSig and _ent.lastUpdatedMs ~= nil then
					_ent.lastUpdatedMs = tonumber(e.updatedAt) or 0

					local _newG = type(e.tweaks) == "table" and tonumber(e.tweaks.gearId) or nil
					local _oldG = type(_ent.tweaks) == "table" and _ent.tweaks.gearId or nil
					if _newG ~= _oldG and type(_ent.tweaks) == "table" then
						_ent.tweaks.gearId = _newG
						local _fp = PS:GetPlayerByUserId(tonumber(e.userId))
						if _ent.applied and _fp and _fp.Character and System._avsyncGear then task.spawn(System._avsyncGear, _fp.Name, _fp.Character, _newG) end
					end
				end
			end
			local tweaks = nil
			if type(e.tweaks) == "table" then
				tweaks = {
					clothesRecolor = type(e.tweaks.clothesRecolor) == "table" and rehydrate(e.tweaks.clothesRecolor) or nil,
					gizmoOffsets   = type(e.tweaks.gizmoOffsets)   == "table" and rehydrate(e.tweaks.gizmoOffsets)   or nil,
					gizmoOffset    = type(e.tweaks.gizmoOffset)    == "table" and rehydrate(e.tweaks.gizmoOffset)    or nil,
					clothingList   = type(e.tweaks.clothingList)   == "table" and rehydrate(e.tweaks.clothingList)   or nil,
					clothesHP      = type(e.tweaks.clothesHP)      == "table" and rehydrate(e.tweaks.clothesHP)      or nil,
					presetOverlay  = type(e.tweaks.presetOverlay)  == "table" and rehydrate(e.tweaks.presetOverlay)  or nil,
					nippleColor    = e.tweaks.nippleColor and rehydrate(e.tweaks.nippleColor) or nil,
					skinTone       = e.tweaks.skinTone and rehydrate(e.tweaks.skinTone) or nil,
					meshEdit       = type(e.tweaks.meshEdit)       == "table" and rehydrate(e.tweaks.meshEdit)       or nil,
					tailSettings   = type(e.tweaks.tailSettings)   == "table" and rehydrate(e.tweaks.tailSettings)   or nil,
					gearId         = tonumber(e.tweaks.gearId),
					community      = System.Community and System.Community.wireCommunity(e.tweaks.community),
					ext            = type(e.tweaks.ext) == "table" and e.tweaks.ext or nil,
				}
			end

			local _aOk, _aErr = pcall(_syncApplyToPeer, tonumber(e.userId), rehydrated, tonumber(e.updatedAt) or 0, tweaks)
			local seen = AS.syncedPeers[tonumber(e.userId)]
			if seen then seen.lastSeenMs = tonumber(nowMs) or os.time()*1000; if _okSig then seen.lookSig = _lookSig end end
			_lights()
			if not _aOk then
				AS.lastError = "applyfn: " .. tostring(_aErr):sub(1, 40)
				AS.lastErrorAt = (tick and tick()) or os.clock()
			end
		end

		System._avsyncRetryPeers = function()
			local AS = System.AvatarSync
			for uid, entry in pairs(AS.syncedPeers) do
				if not entry.applied and entry.bundleData then
					_syncApplyToPeer(uid, entry.bundleData, entry.lastUpdatedMs, entry.tweaks)
				end
			end
		end

		System._avsyncApplyLeave = function(uid)
			local AS = System.AvatarSync
			uid = tonumber(uid)
			if not uid or uid == Player.UserId then return end
			_syncRemovePeer(uid)
			if System.Lights then System.Lights.dropPeer(uid) end
			pcall(System._avsyncAnimDrop, uid)
			if AS.clonePos then AS.clonePos[tostring(uid)] = nil end
			local ids = {}
			for id, e in pairs(AS.peerClones or {}) do if e.owner == uid then ids[#ids + 1] = id end end
			for _, id in ipairs(ids) do pcall(System._avsyncDropClone, id) end
			if System._avsyncClonesOnPoll then pcall(System._avsyncClonesOnPoll, {}, true) end
		end

		Function.AvatarSyncStart = function()
			local AS = System.AvatarSync
			if AS.pollHandle then return end
			AS.clearToken = (AS.clearToken or 0) + 1

			do
				local _ok_genv, _genv = pcall(function() return (getgenv and getgenv()) or nil end)
				local _prior = _ok_genv and _genv and _genv._RC_avsync_poll_task or nil
				if _prior then pcall(task.cancel, _prior) end
			end



			System._avsWs.begin()
			AS.pollHandle = task.spawn(function()
				pcall(System._avsWs.drive)
				AS.pollHandle = nil
			end)

			do
				local _ok_genv, _genv = pcall(function() return (getgenv and getgenv()) or nil end)
				if _ok_genv and _genv then _genv._RC_avsync_poll_task = AS.pollHandle end
			end

			if not AS.heartbeatHandle then

				do
					local _ok_genv, _genv = pcall(function() return (getgenv and getgenv()) or nil end)
					local _prior = _ok_genv and _genv and _genv._RC_avsync_hb_task or nil
					if _prior then pcall(task.cancel, _prior) end
				end
				AS.heartbeatHandle = task.spawn(function()
					while AS.enabled do
						task.wait(30)

						if AS.enabled and System._avsWs.mode == "http" then
							AS.lastPublishedHash = nil
							pcall(Function.AvatarSyncPublish)
						end
					end
					AS.heartbeatHandle = nil
				end)

				do
					local _ok_genv, _genv = pcall(function() return (getgenv and getgenv()) or nil end)
					if _ok_genv and _genv then _genv._RC_avsync_hb_task = AS.heartbeatHandle end
				end
			end
		end


		local _playerRemovingConn = PS.PlayerRemoving:Connect(function(player)
			if System.getSelectPlayer() == player.Name and player ~= Player and System.setSelect then
				pcall(System.setSelect, nil)
				if System.uiToast then pcall(System.uiToast, tostring(player.Name) .. " left. Editing yourself again.") end
			end

			if System.Lights then pcall(System.Lights.dropPeer, player.UserId) end
			pcall(System._avsyncAnimDrop, player.UserId)
			_syncRemovePeer(player.UserId, true)

			pcall(function()
				local _pd = PlayerData[player.Name]
				if _pd then
					if _pd.ExecutionMaid then pcall(function() _pd.ExecutionMaid:DoCleaning() end) end
					PlayerData[player.Name] = nil
				end
			end)
		end)
		System.GlobalMaid:Give(_playerRemovingConn)

		Function.AvatarSyncStop = function()
			local AS = System.AvatarSync

			AS.enabled = false
			if AS.debounceHandle then pcall(task.cancel, AS.debounceHandle); AS.debounceHandle = nil end


			local _wsBye = System._avsWs.stop(true)




			if AS.userActed and not _wsBye and _isActiveSession() then
				AS.clearToken = (AS.clearToken or 0) + 1
				local _tok = AS.clearToken
				task.delay(0.3, function()
					if AS.clearToken ~= _tok then return end
					if not _isActiveSession() then return end
					_publishClearedSync()
				end)
			end
			AS.userActed = false
			if AS.pollHandle then pcall(task.cancel, AS.pollHandle); AS.pollHandle = nil end
			if AS.heartbeatHandle then pcall(task.cancel, AS.heartbeatHandle); AS.heartbeatHandle = nil end
			local _peers = {}
			for uid in pairs(AS.syncedPeers) do _peers[#_peers+1] = uid end
			if System.Lights then pcall(System.Lights.dropAllPeers) end
			for uid in pairs(System._avsyncAnimPeers or {}) do pcall(System._avsyncAnimDrop, uid) end
			for uid in pairs(System._avsyncEmotePeers or {}) do pcall(System._avsyncAnimDrop, uid) end
			for _, uid in ipairs(_peers) do _syncRemovePeer(uid, true) end
			AS.lastPublishedHash = nil
			AS.pollCursor = nil
			AS.nextFullPoll = nil


			if AS.peerClones and System._avsyncDropClone then
				local _ids = {}
				for id in pairs(AS.peerClones) do _ids[#_ids + 1] = id end
				for _, id in ipairs(_ids) do pcall(System._avsyncDropClone, id) end
			end


			if type(AS._clonePub) == "table" and System._avsyncPostClone and not _wsBye then
				local _slots = {}
				for slot, pub in pairs(AS._clonePub) do if pub and pub.key ~= "?stale" then _slots[#_slots + 1] = slot end end
				if #_slots > 0 then task.spawn(function() for _, slot in ipairs(_slots) do pcall(System._avsyncPostClone, slot, nil) end end) end
			end
			AS._clonePub = nil
			AS._clonePubInit = nil
		end







		System._avsWs = {
			URL = "wss://krulhub.dev/avatar/ws",
			CONNECT_S = 8,
			WELCOME_S = 20,
			PING_S = 27,
			SILENCE_S = 70,
			MAX_S = 30,
			RETRY_WS_S = 240,
			POLL_S = 3,
			MAX_FRAME = 65536,
			MAX_RX = 1048576,
			LIMITS = { pub = 18, clone = 55, cpos = 110 },



			PUB_BURST = 3,
			PUB_GAP_S = 3.8,
			GRACE_S = 20,
			mode = "off", gen = 0, epoch = 0, fails = 0, forbid = 0, hard = 0, owned = 0,



			HINT = {
				hello_timeout = "hello", hello_required = "hello", bad_place_id = "hello", bad_job_id = "hello", bad_user_id = "hello",
				bad_script_version = "hello", bad_identity = "hello", version_outdated = "hello",
				identity = "forbidden", banned = "forbidden", owner = "owner",
				room_full = "full", room_ip_cap = "full", replaced = "replaced",
