		System._avsWs.rand = function() return math.random() end

		System._avsWs.api = function()
			local out = {}
			local ok1, c1 = pcall(function() return WebSocket.connect end)
			if ok1 and type(c1) == "function" then out[#out + 1] = c1 end
			local ok2, c2 = pcall(function() return syn.websocket.connect end)
			if ok2 and type(c2) == "function" and c2 ~= c1 then out[#out + 1] = c2 end
			return out
		end
		System._avsWs.valid = function(s)
			if s == nil then return false end
			local ok, good = pcall(function()
				return type(s.Send) == "function" and type(s.Close) == "function"
					and s.OnMessage ~= nil and type(s.OnMessage.Connect) == "function"
					and s.OnClose ~= nil and type(s.OnClose.Connect) == "function"
			end)
			return ok and good == true
		end

		System._avsWs.connect = function(url)
			local W = System._avsWs
			if (System.isOff and System.isOff("avatarSync")) then return nil, "off" end
			local fns = W.api()
			if #fns == 0 then return nil, "no_api" end
			local epoch, why = W.epoch, "connect_failed"
			for _, fn in ipairs(fns) do
				local box = {}
				task.spawn(function()
					local ok, s = pcall(fn, url)
					if box.late or W.epoch ~= epoch then
						if ok and s ~= nil then pcall(function() s:Close() end) end
						return
					end
					box.ok, box.s, box.done = ok, s, true
				end)
				local deadline = os.clock() + W.CONNECT_S
				while not box.done and os.clock() < deadline and W.epoch == epoch do task.wait(0.1) end
				if not box.done then box.late = true; return nil, (W.epoch ~= epoch) and "stopped" or "timeout" end
				if box.ok and W.valid(box.s) then return box.s end
				if box.ok and box.s ~= nil then pcall(function() box.s:Close() end) end
				why = box.ok and "bad_object" or "connect_failed"
			end
			return nil, why
		end
		System._avsWs.send = function(msg)
			local W = System._avsWs
			local s = W.sock
			if not s then return false, "closed" end
			local str = msg
			if type(msg) == "table" then
				local ok, enc = pcall(HS.JSONEncode, HS, msg)
				if not ok or type(enc) ~= "string" then return false, "encode" end
				str = enc
			end
			if #str > W.MAX_FRAME then return false, "too_large" end
			if not pcall(function() s:Send(str) end) then return false, "send" end
			return true
		end

		System._avsyncSend = function(msg)
			local W = System._avsWs
			if not (W and W.ready and W.sock) then return false end
			return (W.send(msg)) == true
		end

		System._avsWs.take = function(kind)
			local W = System._avsWs
			local now = os.clock()
			W.sent = W.sent or {}
			local q = W.sent[kind] or {}
			W.sent[kind] = q
			while q[1] and now - q[1] >= 60 do table.remove(q, 1) end
			if #q >= W.LIMITS[kind] then return false, 60 - (now - q[1]) end
			q[#q + 1] = now
			return true
		end

		System._avsWs.retryPub = function(d, floor)
			local W = System._avsWs
			if W.pubRetry then return end
			W.pubRetry = true
			task.delay(math.max(floor or 1, tonumber(d) or 5), function()
				W.pubRetry = false
				if System.AvatarSync.enabled then pcall(Function.AvatarSyncPublish) end
			end)
		end

		System._avsWs.pubTokens = function(now)
			local W = System._avsWs
			if W.pubTok == nil then return W.PUB_BURST end
			return math.min(W.PUB_BURST, W.pubTok + math.max(0, (now or os.clock()) - (W.pubTokAt or 0)) / W.PUB_GAP_S)
		end

		System._avsWs.pubWait = function()
			local W = System._avsWs
			local now = os.clock()
			local tok = W.pubTokens(now)
			local w = (tok >= 1 - 1e-6) and 0 or (1 - tok) * W.PUB_GAP_S
			local q, cap = W.sent and W.sent.pub, W.LIMITS.pub
			if q and #q >= cap then w = math.max(w, 60 - (now - q[#q - cap + 1])) end
			return math.max(0, w)
		end



		System._avsWs.pub = function(bundle, tweaks, pre)
			local W, AS = System._avsWs, System.AvatarSync
			local now0 = os.clock()
			local tok = W.pubTokens(now0)
			if tok < 1 - 1e-6 then W.retryPub((1 - tok) * W.PUB_GAP_S, 0.05); return false end
			local can, wait = W.take("pub")
			if not can then W.retryPub(wait); return false end
			W.pubTok, W.pubTokAt = math.max(0, tok - 1), now0
			W.pubAt = now0
			local now = _syncNowMs()
			local msg = pre and System._avsyncSpliceJson({ t = "pub", updatedAt = now }, pre[1], pre[2])
			local ok, why = W.send(msg or { t = "pub", updatedAt = now, bundle = bundle, tweaks = tweaks })
			if not ok then
				AS.publishError = (why == "too_large") and "look too large to sync" or ("publish " .. tostring(why))
				AS.publishErrorAt = (tick and tick()) or os.clock()
			end
			return ok
		end
		System._avsWs.clone = function(slot, data)
			local W = System._avsWs
			if not W.take("clone") then return false end
			if data == nil then return (W.send({ t = "cloneRemove", slot = slot, updatedAt = _syncNowMs() })) end
			return (W.send({ t = "clone", updatedAt = _syncNowMs(), bundle = data.bundle, tweaks = data.tweaks, clone = data.clone }))
		end
		System._avsWs.cpos = function(pos)
