			System.AvatarSync.lastSeenCount = n
		end

		System._avsWs.resend = function()
			local AS = System.AvatarSync
			AS.lastPublishedHash = nil
			AS._staleRetries = 0
			if type(AS._clonePub) == "table" then
				for slot, pub in pairs(AS._clonePub) do if pub and pub.key ~= "?stale" then AS._clonePub[slot] = nil end end
			end
			if AS.userActed and Function.AvatarSyncPublish then pcall(Function.AvatarSyncPublish) end
			if not AS._cloneLoop and System._avsyncCloneLoop then AS._cloneLoop = true; task.spawn(System._avsyncCloneLoop) end
		end
		System._avsWs.dispatch = function(m)
			local W, AS = System._avsWs, System.AvatarSync
			local t = m.t
			if t == "err" then return W.onErr(m) end
			if t == "welcome" then
				W.ready, W.mode, W.everOk, W.welcomedAt = true, "ws", true, os.clock()
				W.forbid, W.hard, W.owned = 0, 0, 0
				W.rmTries = nil

				if W.rmLost then W.rmLost = nil; AS._clonePubInit = nil end
				AS.lastError = nil
				local now = tonumber(m.now)
				if now then AS.clockOffsetMs = now - os.time() * 1000 end

				W.present = System._avsyncApplyRoster(m.present)
				for _, e in ipairs(type(m.peers) == "table" and m.peers or {}) do System._avsyncApplyEntry(e, now, W.present) end
				local pos = {}
				for _, c in ipairs(type(m.cpos) == "table" and m.cpos or {}) do
					if type(c) == "table" and tonumber(c.ownerId) and type(c.pos) == "table" then pos[tostring(tonumber(c.ownerId))] = c.pos end
				end
				pcall(System._avsyncClonesOnPoll, { clones = m.clones, clonePresent = type(m.clonePresent) == "table" and m.clonePresent or {}, clonePos = pos })
if System.Staff then pcall(System.Staff.reset) end
				W.resend()
				return
			end
			if not W.ready then return end
			if t == "snap" then
				for _, e in ipairs(type(m.peers) == "table" and m.peers or {}) do System._avsyncApplyEntry(e, _syncNowMs(), W.present) end
				pcall(System._avsyncClonesOnPoll, { clones = m.clones }, true)
elseif t == "peer" then
				local e = m.peer
				if type(e) == "table" and tonumber(e.userId) and tonumber(e.userId) ~= Player.UserId then
					if W.present then W.present[tonumber(e.userId)] = true end
					W.count()
					System._avsyncApplyEntry(e, _syncNowMs())
				end
			elseif t == "clone" then
				if type(m.clone) == "table" then pcall(System._avsyncClonesOnPoll, { clones = { m.clone } }, true) end
			elseif t == "cloneRemove" then
				local o, sl = tonumber(m.ownerId), tonumber(m.slot)
				if o and sl then pcall(System._avsyncDropClone, o .. ":" .. sl) end
				pcall(System._avsyncClonesOnPoll, {}, true)
			elseif t == "cpos" then
				local o = tonumber(m.ownerId)
				if o and type(m.pos) == "table" then pcall(System._avsyncClonesOnPoll, { clonePos = { [tostring(o)] = m.pos } }, true) end
			elseif t == "leave" then
				local uid = tonumber(m.userId)
				if uid then
					if W.present then W.present[uid] = nil end
					W.count()
					System._avsyncApplyLeave(uid)
					if System.Staff then pcall(System.Staff.onLeave, uid) end
				end
			elseif t == "staff" then
				if System.Staff then pcall(System.Staff.onPresence, m.userId, m.p) end
			elseif t == "dm" then
				if System.Staff then pcall(System.Staff.onDm, m.from, m.m) end
			elseif t == "dmr" then
				if _RCA.onStaffReply then pcall(_RCA.onStaffReply, m.from, m.m) end
			end
		end
		System._avsWs.onErr = function(m)
			local W, AS = System._avsWs, System.AvatarSync
			local code, of = tostring(m.code), m.of
			W.lastErr, W.lastErrAt, W.lastErrRetry = code, os.clock(), tonumber(m.retryAfter)
			local slot = tonumber(m.slot)



			if of == "cloneRemove" and slot and code ~= "not_present" then
				AS._clonePub = AS._clonePub or {}
				W.rmTries = W.rmTries or {}
				W.rmTries[slot] = (W.rmTries[slot] or 0) + 1
				if W.rmTries[slot] > 3 then W.rmLost = true
				elseif not AS._clonePub[slot] then AS._clonePub[slot] = { key = "?stale" } end
				return
			end
			if code == "stale" then
				if of == "pub" then
					AS.lastPublishedHash = nil

					if os.clock() - (AS._staleAt or -1e9) > 60 then AS._staleRetries = 0 end
					AS._staleAt = os.clock()
					AS._staleRetries = (AS._staleRetries or 0) + 1
					if AS._staleRetries <= 3 then W.retryPub(2.5) end
				elseif of == "clone" and slot and AS._clonePub then AS._clonePub[slot] = nil end
			elseif code == "not_present" then


				if of == "clone" and slot and AS._clonePub then AS._clonePub[slot] = nil end
				if of == "clone" or of == "cpos" then
					AS.lastPublishedHash = nil
					AS._staleRetries = 0
					AS.userActed = true
					if Function.AvatarSyncPublish then pcall(Function.AvatarSyncPublish, true, AS.forceClear == true) end
				end
			elseif code == "rate" or code == "internal" then
				if of == "pub" or of == "clear" then
					AS.lastPublishedHash = nil
					W.retryPub(W.lastErrRetry or 5)
				elseif of == "clone" and slot and AS._clonePub then AS._clonePub[slot] = nil end
			elseif of == "pub" or of == "clone" then
				if of == "pub" then AS.lastPublishedHash = nil end
				AS.publishError = "publish " .. code .. (m.detail and (" " .. tostring(m.detail):sub(1, 50)) or "")
				AS.publishErrorAt = (tick and tick()) or os.clock()
				local _now = os.clock()
				if System.uiToast and (AS._toastedErr ~= AS.publishError or _now - (AS._toastedAt or -1e9) > 60) then
					AS._toastedErr, AS._toastedAt = AS.publishError, _now
					pcall(System.uiToast, "Avatar Sync", "Others can't see your avatar: " .. tostring(AS.publishError), "warn")
				end
			end
		end
		System._avsWs.onMessage = function(gen, raw)
			local W, AS = System._avsWs, System.AvatarSync
			if not W.current(gen) then return end
			W.lastRx = os.clock()
			if type(raw) ~= "string" or raw == "pong" or #raw > W.MAX_RX then return end
			local ok, m = pcall(HS.JSONDecode, HS, raw)
			if not ok or type(m) ~= "table" or type(m.t) ~= "string" then return end
			local okD, err = pcall(W.dispatch, m)
			if not okD then
				AS.lastError = "sync: " .. tostring(err):sub(1, 50)
				AS.lastErrorAt = (tick and tick()) or os.clock()
			end
		end


		System._avsWs.kind = function(code)
			local W = System._avsWs
			local h = W.lastErr and os.clock() - (W.lastErrAt or -1e9) < 10 and W.HINT[W.lastErr] or nil
			local k = W.CODES[tonumber(code) or 0]
			if k == "forbidden" and h == "owner" then return "owner" end
			return k or h or "drop"
		end
		System._avsWs.jitter = function(d)
			local W = System._avsWs
			return math.clamp(d * (0.75 + 0.25 * W.rand()), 1, W.MAX_S)
		end

		System._avsWs.backoff = function(n)
			local W = System._avsWs
			return W.jitter(math.min(W.MAX_S, 2 ^ (math.max(1, tonumber(n) or 1) - 1)))
		end
		System._avsWs.pollDelay = function()
			local W, AS = System._avsWs, System.AvatarSync
			local f = AS._pollFails or 0
			local d = (f > 0) and System._avsyncBackoff(f + 1, W.POLL_S, W.MAX_S) or W.POLL_S
			if AS._pollRetryAfter then d = math.max(d, AS._pollRetryAfter); AS._pollRetryAfter = nil end
			return d
		end

		System._avsWs.maintain = function()
			pcall(System._avsyncRetryPeers)
			if System._avsyncClonesOnPoll then pcall(System._avsyncClonesOnPoll, {}, true) end
		end
		System._avsWs.wait = function(d)
			local W, AS = System._avsWs, System.AvatarSync
			W.lastWait = d
			local t0, maintAt = os.clock(), os.clock()
			while os.clock() - t0 < d and AS.enabled and _isActiveSession() and not W.stopped do
				task.wait(0.5)
				if os.clock() - maintAt >= 2 then maintAt = os.clock(); W.maintain() end
			end
		end
		System._avsWs.genv = function(s, clear)
			pcall(function()
				local g = getgenv and getgenv()
				if not g then return end
				if not clear then g._RC_avsync_ws = s elseif g._RC_avsync_ws == s then g._RC_avsync_ws = nil end
			end)
		end

		System._avsWs.toHttp = function()
			local W, AS = System._avsWs, System.AvatarSync
			local was = W.mode
			W.mode = "http"
			W.retryAt = os.clock() + W.RETRY_WS_S
			if was ~= "http" then
				AS.pollCursor, AS.nextFullPoll = nil, nil
				W.resend()
			end
		end
		System._avsWs.release = function()
			local W = System._avsWs
			local s = W.sock
			W.sock, W.ready = nil, false
			if s then
				if not W.closed then pcall(function() s:Close() end) end
