			end
		end

		System._avsWs.after = function(kind, got, fromHttp)
			local W, AS = System._avsWs, System.AvatarSync
			if not (AS.enabled and _isActiveSession()) then W.mode = "off"; return end
			if kind == "replaced" then
				W.stopped, W.mode = true, "off"
				AS.lastError = "sync moved to your newer session"
				AS.lastErrorAt = (tick and tick()) or os.clock()
				return
			end
			if kind == "owner" then



				W.owned += 1
				if W.owned >= 5 then W.owned = 0; return W.toHttp() end
				W.mode = "backoff"
				return W.wait(W.GRACE_S + 2 + 3 * W.rand())
			end
			if kind == "forbidden" then
				W.forbid += 1
				if W.forbid >= 3 then W.disabled = true; return W.toHttp() end
			else
				W.forbid = 0
			end
			if kind == "hello" or kind == "full" then
				W.hard += 1
				if W.hard >= 3 then return W.toHttp() end
			end
			if got and os.clock() - (W.welcomedAt or 0) >= 60 then W.fails = 0 end
			W.fails += 1
			if fromHttp and not got then return W.toHttp() end

			if not got and W.fails >= (W.everOk and 5 or 3) then return W.toHttp() end
			local d = W.backoff(W.fails)
			if kind == "forbidden" or kind == "hello" or kind == "abuse" then d = W.jitter(W.MAX_S) end
			if kind == "full" then d = math.max(30 + 5 * W.rand(), W.lastErrRetry or 30) end
			W.mode = "backoff"
			W.wait(d)
		end

		System._avsWs.session = function(fromHttp)
			local W, AS = System._avsWs, System.AvatarSync
			local url = W.URL .. "?placeId=" .. tostring(AS.placeId) .. "&jobId=" .. HS:UrlEncode(AS.jobId)
			if not fromHttp then W.mode = "connecting" end
			local s, why = W.connect(url)
			if not (AS.enabled and _isActiveSession()) or W.stopped then
				if s then pcall(function() s:Close() end) end
				return
			end
			if not s then
				W.lastWhy = why
				if why == "no_api" then W.disabled = true; return W.toHttp() end
				W.fails += 1

				if fromHttp or not W.everOk or W.fails >= 3 then return W.toHttp() end
				W.mode = "backoff"
				return W.wait(W.backoff(W.fails))
			end
			W.gen += 1
			local gen = W.gen
			W.sock, W.ready, W.closed, W.closeCode, W.lastErr, W.sent, W.present = s, false, false, nil, nil, {}, nil
			W.lastRx = os.clock()
			W.genv(s)
			local okH = pcall(function()
				s.OnMessage:Connect(function(raw) W.onMessage(gen, raw) end)
				s.OnClose:Connect(function(code)
					if W.gen ~= gen then return end
					W.closed, W.closeCode = true, tonumber(code)
				end)
			end)
			local hello = { t = "hello", userId = Player.UserId, displayName = Player.DisplayName, scriptVersion = VersionInternal }
			local okT, tok = pcall(function() return System._rcaTok and System._rcaTok() end)
			if okT and type(tok) == "string" and tok ~= "" then hello.token = tok end
			if not okH or not W.send(hello) then W.closed = true end
			local helloAt, pingAt, maintAt = os.clock(), os.clock(), os.clock()
			while W.gen == gen and not W.closed do
				task.wait(0.5)
				if W.gen ~= gen or W.closed or not (AS.enabled and _isActiveSession()) then break end
				local now = os.clock()
				if not W.ready and now - helloAt > W.WELCOME_S then break end
				if now - (W.lastRx or now) > W.SILENCE_S then break end
				if now - pingAt >= W.PING_S then pingAt = now; W.send("ping") end
				if W.ready and now - maintAt >= 2 then maintAt = now; W.maintain() end
			end
			if W.gen ~= gen then return end
			local got, kind = W.ready, W.kind(W.closeCode)
			W.release()
			return W.after(kind, got, fromHttp)
