	function Function.NewWomanTorsoShirtClothing(ObjectInstance, Character, Extra, Data)
		local DataDetail = PlayerData[Data]
		if Extra.Shirt and table.find(DataDetail.CurrentClothes, "New Woman") and not ObjectInstance:FindFirstChildOfClass("SurfaceAppearance") then
