	function Function.NewWomanPantsClothing(ObjectInstance, Character, Extra, Data)
		local DataDetail = PlayerData[Data]
		if Extra.Pants and table.find(DataDetail.CurrentClothes, "New Woman") and not ObjectInstance:FindFirstChildOfClass("SurfaceAppearance") then
			Function._newSA(ObjectInstance, Extra.Pants.PantsTemplate)
		end
	end

	function Function.BreastsType2Mesh(ObjectInstance, Character, Extra, Data)
		local DataDetail = PlayerData[Data]
		local SpecialMesh = Instance.new("SpecialMesh")
		local Scale = DataDetail["BreastsScale"]

		SpecialMesh.MeshType = Enum.MeshType.FileMesh

		if ObjectInstance.Name == "Left Breast" then
			SpecialMesh.MeshId = Function.GetAsset("rbxasset://RClothesContent/99196487433776.mesh")
		else
			SpecialMesh.MeshId = Function.GetAsset("rbxasset://RClothesContent/135832822984550.mesh")
		end

		if Scale ~= nil then
			SpecialMesh.Scale = Function.Vector3Multiply(Vector3.new(1, 1, 1), {X = Scale, Y = Scale, Z = Scale})
		else
			SpecialMesh.Scale = Vector3.new(1, 1, 1)
		end

		SpecialMesh.Parent = ObjectInstance
	end

	function Function.BreastsType3Mesh(ObjectInstance, Character, Extra, Data)
		local DataDetail = PlayerData[Data]
		local SpecialMesh = Instance.new("SpecialMesh")
		local Scale = DataDetail["BreastsScale"]

		SpecialMesh.MeshType = Enum.MeshType.FileMesh

		if ObjectInstance.Name == "Left Breast" then
			SpecialMesh.MeshId = Function.GetAsset("rbxasset://RClothesContent/5270415437.mesh")
		else
			SpecialMesh.MeshId = Function.GetAsset("rbxasset://RClothesContent/5270413797.mesh")
		end

		if Scale ~= nil then
			SpecialMesh.Scale = Function.Vector3Multiply(Vector3.new(0.541, 0.541, 0.541), {X = Scale, Y = Scale, Z = Scale})
		else
			SpecialMesh.Scale = Vector3.new(0.541, 0.541, 0.541)
