			Atmosphere = { "Color", "Decay", "Density", "Glare", "Haze", "Offset" },
			Sky = { "CelestialBodiesShown", "MoonAngularSize", "MoonTextureId", "SkyboxBk", "SkyboxDn", "SkyboxFt", "SkyboxLf",
				"SkyboxRt", "SkyboxUp", "StarCount", "SunAngularSize", "SunTextureId" },
			SunRaysEffect = { "Enabled", "Intensity", "Spread" },
			ColorCorrectionEffect = { "Enabled", "Brightness", "Contrast", "Saturation", "TintColor" },
			BloomEffect = { "Enabled", "Intensity", "Size", "Threshold" },
			BlurEffect = { "Enabled", "Size" },
			DepthOfFieldEffect = { "Enabled", "FarIntensity", "FocusDistance", "InFocusRadius", "NearIntensity" },
		}
		local function readProps(o, list)
			local t = {}
			for _, k in ipairs(list) do
				local ok, v = pcall(function() return o[k] end)
				if ok then t[k] = v end
			end
			return t
		end
		local function writeProps(o, t)
			for k, v in pairs(t) do pcall(function() if o[k] ~= v then o[k] = v end end) end
		end

		local function placeLight(d)
			return d:IsA("Light") and not OWN[d] and d:FindFirstAncestor("RCTheme") == nil
		end
		local function placeSnap()
			local Lt = game:GetService("Lighting")
			local s = { lt = readProps(Lt, LT_PROPS), kids = {}, lights = {} }
			for _, c in ipairs(Lt:GetChildren()) do
				if not OWN[c] then s.kids[c] = readProps(c, KID_PROPS[c.ClassName] or { "Enabled" }) end
			end
			for _, d in ipairs(workspace:GetDescendants()) do
				if placeLight(d) then s.lights[d] = d.Enabled end
			end
			return s
		end
		local function placeRestore(s)
			local Lt = game:GetService("Lighting")
			for _, c in ipairs(Lt:GetChildren()) do
				if OWN[c] and s.kids[c] == nil then pcall(function() c:Destroy() end) end
			end
			for c, t in pairs(s.kids) do
				if c.Parent == Lt then writeProps(c, t) end
			end
			writeProps(Lt, s.lt)
			for d, v in pairs(s.lights) do
				pcall(function() if d.Parent and d.Enabled ~= v then d.Enabled = v end end)
			end
		end

		local function placeClaim(R)
			if R.placed then return end
			R.placed = true
			if PLACE.n == 0 then
				local ok, s = pcall(placeSnap)
				PLACE.snap = ok and s or nil
			end
			PLACE.n += 1
		end
		local function placeRelease(R)
			if not R.placed then return end
			R.placed = false
			PLACE.n -= 1
			if PLACE.n > 0 then return end
			PLACE.n = 0
			local s = PLACE.snap
			PLACE.snap = nil
			if s then pcall(placeRestore, s) end
		end
		TH.place = PLACE

		local function dummyScreen()
			local W = Color3.new(1, 1, 1)
			local S = { t = 0, b = 0, dim = 0, flashA = 0, shakeAmp = 0, shakeT = 0, inert = true,
				cc = { TintColor = W, Brightness = 0, Contrast = 0, Saturation = 0, Enabled = false },
				fl = { BackgroundColor3 = W, BackgroundTransparency = 1, Visible = false } }
			S.flash, S.shake, S.title, S.finish = nop, nop, nop, nop
			S.edge = function(top) return top and 0 or 1 end
			return S
		end

		TH.lib = function(uid, player, R)
		local L = {}
		L.uid, L.player = uid, player
		L.plr = Players.LocalPlayer
		L.NS, L.CS, L.NR = NumberSequence.new, ColorSequence.new, NumberRange.new
		L.K, L.CK = NumberSequenceKeypoint.new, ColorSequenceKeypoint.new
		L.W = Color3.new(1, 1, 1)
		L.T = function(n) local F = System.StaffFx return F and F.asset and F.asset(n) or nil end
		L.c01 = function(x) return math.clamp(x, 0, 1) end
		L.outQuad = function(x) x = L.c01(x) return 1 - (1 - x) * (1 - x) end
		L.inQuad = function(x) x = L.c01(x) return x * x end
		L.outBack = function(x) x = L.c01(x) local c = 1.7 return 1 + (c + 1) * (x - 1) ^ 3 + c * (x - 1) ^ 2 end
		L.rnd = function(a, b) return a + math.random() * (b - a) end
		L.HEAVY = Font.new("rbxasset://fonts/families/GothamSSm.json", Enum.FontWeight.Heavy)
		L.BOLD = Font.new("rbxasset://fonts/families/GothamSSm.json", Enum.FontWeight.Bold)

		L.name = function()
			local c = L.C and L.C.card
			if type(c) == "string" and c ~= "" then return c end
			return player and player.DisplayName or ""
		end

		L.new = function(cls, props, parent)
			if L.dead then return INERT end
			local o = Instance.new(cls)
			OWN[o] = true
			o:SetAttribute("_rcfx", true)
			for k, v in pairs(props or {}) do o[k] = v end
			if parent then o.Parent = parent end
			return o
		end
		L.part = function(props, parent)
			if L.dead then return INERT end
			local p = Instance.new("Part")
			p.Anchored, p.CanCollide, p.CanQuery, p.CanTouch, p.CastShadow = true, false, false, false, false
			p.Size, p.Transparency = Vector3.new(0.1, 0.1, 0.1), 1
			p.CFrame = CFrame.new(L.ch.feet or Vector3.zero)
			for k, v in pairs(props or {}) do p[k] = v end
			p.Parent = parent or L.root
			return p
		end

		L.GCAP = 1.3
		L.BACK = Color3.fromRGB(5, 7, 20)
		L.gain = function(col, gain) return math.min(gain or 1, L.GCAP / math.max(col.R, col.G, col.B, 0.05)) end


		L.noMesh = setmetatable({}, { __mode = "k" })
		L.mesh = function(mesh, tex, col, gain, scale)
			local p = L.part()
			local id = L.T(mesh)
			local m = L.new("SpecialMesh", { MeshType = Enum.MeshType.FileMesh, MeshId = id, TextureId = tex and L.T(tex) or "",
				VertexColor = Vector3.new(col.R, col.G, col.B) * L.gain(col, gain), Scale = scale or Vector3.one }, p)
			if not tex then p.Color = col end
			if not id then L.noMesh[p] = true p.LocalTransparencyModifier = 1 end
			return p, m
		end
		L.tint = function(m, col, gain)
			m.VertexColor = Vector3.new(col.R, col.G, col.B) * L.gain(col, gain)
			if m.TextureId == "" and m.Parent and m.Parent:IsA("BasePart") then m.Parent.Color = col end
		end
		L.pe = function(parent, props)
			if L.dead then return INERT end
			local e = Instance.new("ParticleEmitter")
			e:SetAttribute("_rcfx", true)
			e.Rate, e.LightEmission = 0, 1
			for k, v in pairs(props) do e[k] = v end
			e.Parent = parent
			return e
		end

		L.att = function(pos) if L.dead then return INERT end local a = Instance.new("Attachment") a.Parent = L.host if pos then a.WorldPosition = pos end return a end
		L.beam = function(a0, a1, props)
			if L.dead then return INERT end
			local b = Instance.new("Beam")
			b.Attachment0, b.Attachment1 = a0, a1
			b.Texture, b.LightEmission, b.FaceCamera, b.Segments = L.T("beamb.png") or "", 1, true, 1
			for k, v in pairs(props or {}) do b[k] = v end
			b.Parent = L.host
			return b
		end



		L.live = {}


		L.fx = function(life, fn, objs)
			if L.dead then return end
			table.insert(L.live, { t = 0, life = life, fn = fn, objs = objs or {}, tok = R.ctx })
			local ok, err = pcall(fn, 0, 0)
			if not ok then warn("fx " .. tostring(err)) end
		end
		L.after = function(delay, fn) if L.dead then return end L.fx(delay, function() end, {}) L.live[#L.live].done = fn end


		L.ends = {}
		L.onEnd = function(fn)
			if L.dead then pcall(fn) return end
			L.ends[#L.ends + 1] = fn
		end
		L.runEnds = function()
			local list = L.ends
			L.ends = {}
			for _, fn in ipairs(list) do pcall(fn) end
			if L.sg then pcall(function() L.sg:Destroy() end) L.sg = nil end
		end


		L.bolt = function(p0, p1, o)
			o = o or {}
			local segs, jit = o.segs or 8, o.jit or ((p1 - p0).Magnitude * 0.12)
			local dir = (p1 - p0)
			local side = dir:Cross(Vector3.yAxis)
			if side.Magnitude < 0.01 then side = Vector3.xAxis end
			side = side.Unit
			local up = side:Cross(dir.Unit)
			local pts = { p0 }
			for i = 1, segs - 1 do
				local t = i / segs
				local env = math.sin(t * math.pi)
				pts[#pts + 1] = p0 + dir * t + (side * L.rnd(-1, 1) + up * L.rnd(-1, 1)) * jit * env
			end
			pts[#pts + 1] = p1
			local atts, beams = {}, {}
			for i, p in ipairs(pts) do atts[i] = L.att(p) end
			local w = o.w or 0.5
			for i = 1, #pts - 1 do
				beams[#beams + 1] = L.beam(atts[i], atts[i + 1], { Width0 = w, Width1 = w, Brightness = o.bright or 8,
					Color = L.CS(o.col or L.W), Transparency = L.NS(0) })
				if o.glow then
					beams[#beams + 1] = L.beam(atts[i], atts[i + 1], { Width0 = w * 4, Width1 = w * 4, Brightness = 2,
						Color = L.CS(o.glow), Transparency = L.NS(0.55) })
				end
			end
			local objs = {}
			for _, a in ipairs(atts) do objs[#objs + 1] = a end
			for _, b in ipairs(beams) do objs[#objs + 1] = b end
			local life = o.life or 0.15
			L.fx(life, function(k)
				local tr = L.c01((k - 0.3) / 0.7)
				if o.flicker ~= false and math.random() < 0.25 then tr = math.max(tr, 0.6) end
				for _, b in ipairs(beams) do b.Transparency = L.NS(tr) end
			end, objs)
			return pts
		end

		L.strike = function(p0, p1, o)
			local pts = L.bolt(p0, p1, o)
			for _ = 1, o.forks or 3 do
				local i = math.random(2, #pts - 1)
				local q = pts[i]
				local d = (p1 - p0).Magnitude * L.rnd(0.15, 0.35)
				L.bolt(q, q + Vector3.new(L.rnd(-1, 1), -L.rnd(0.3, 1), L.rnd(-1, 1)).Unit * d,
					{ col = o.col, w = (o.w or 0.5) * 0.5, segs = 5, life = o.life, glow = o.glow })
			end
		end


		L.ch = { on = false, spd = 0, sprint = 0, iw = 0, stillT = 0, clock = 0 }
		L.bind = function(char)
			local c = L.ch
			c.char = char
			c.hrp = char:WaitForChild("HumanoidRootPart", 5)
			c.head = char:FindFirstChild("Head")
			c.hum = char:FindFirstChildOfClass("Humanoid")

			if c.hrp then
				local h, legs = c.hum, 2
				if h and h.RigType == Enum.HumanoidRigType.R15 and h.HipHeight > 0 then legs = h.HipHeight
				else local leg = char:FindFirstChild("Left Leg") or char:FindFirstChild("Right Leg") if leg and leg:IsA("BasePart") then legs = leg.Size.Y end end
				c.fy = -(c.hrp.Size.Y / 2 + legs) + 0.12
				c.sc = math.clamp(c.hrp.Size.Y / 2, 0.4, 4)
			end
			c.torso = char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso") or c.hrp
			c.wasAir, c.air, c.state, c.emote, c.emoteT = false, false, nil, false, 0
		end


		local HST = Enum.HumanoidStateType
		local CORE_ANIM = { idle = true, walk = true, run = true, jump = true, fall = true, climb = true, sit = true, swim = true,
			swimidle = true, toolnone = true, toolslash = true, toollunge = true }
		local EMOTE_ANIM = { dance = true, dance2 = true, dance3 = true, wave = true, point = true, cheer = true, laugh = true }
		L.stepState = function(c, dt, vy)
			local h = c.hum
			if not (h and h.Parent) then return end
			local ok, st = pcall(function() return h:GetState() end)
			st = ok and st or nil
			c.state = st
			c.dead = h.Health <= 0 or st == HST.Dead
			c.swim = st == HST.Swimming
			c.sit = h.Sit == true or st == HST.Seated
			c.climb = st == HST.Climbing
			local floorAir = h.FloorMaterial == Enum.Material.Air
			c.air = not c.swim and not c.sit and not c.climb and (st == HST.Freefall or st == HST.Jumping or (floorAir and math.abs(vy) > 3))
			c.jumped = c.air and not c.wasAir and (vy > 4 or st == HST.Jumping)
			c.landed = c.wasAir and not c.air and not c.swim
			c.fallV = c.air and vy or 0
			c.wasAir = c.air

			c.emoteT -= dt
			if c.emoteT <= 0 then
				c.emoteT = 0.3
				local e = false
				local an = not c.on and not c.air and h:FindFirstChildOfClass("Animator")
				if an then
					local okT, tracks = pcall(function() return an:GetPlayingAnimationTracks() end)
					for _, tr in ipairs(okT and tracks or {}) do
						local a = tr.Animation
						local pn = a and a.Parent and string.lower(a.Parent.Name) or ""
						if EMOTE_ANIM[pn] then e = tr break end
						if not CORE_ANIM[pn] and tr.Priority.Value >= Enum.AnimationPriority.Action.Value and tr.Length >= 1 and tr.WeightCurrent > 0.5 then e = tr break end
					end
				end

				if not e and not c.on and not c.air and System.animRT and System.animRT.emoting then e = System.animRT.emoting(c.char) or false end

				c.emoteObj = e or nil
				c.emote = e ~= false
			end
		end
		L.stepChar = function(dt)
			local c = L.ch
			c.clock += dt
			if not (c.hrp and c.hrp.Parent) then return false end

			if not (c.head and c.head.Parent) then c.head = c.char and c.char:FindFirstChild("Head") if not c.head then return false end end
			local v = c.hrp.AssemblyLinearVelocity
			c.vel = Vector3.new(v.X, 0, v.Z)
			c.spd = c.vel.Magnitude
			c.wasOn = c.on
			if c.spd > 3 then c.on = true elseif c.spd < 1.5 then c.on = false end
			c.sprint = L.c01((c.spd - 18) / 10)
			c.dashStart = c.on and not c.wasOn and c.stillT > 0.5
			c.stillT = c.on and 0 or c.stillT + dt
			local target = (not c.on and c.stillT > 0.4) and 1 or 0
			c.iw += (target - c.iw) * L.c01(dt * (target > c.iw and 3 or 10))
			c.pos = c.hrp.Position
			c.feet = (c.hrp.CFrame * CFrame.new(0, c.fy, 0)).Position
			c.yaw = select(2, c.hrp.CFrame:ToEulerAnglesYXZ())
			c.flat = CFrame.new(c.feet) * CFrame.Angles(0, c.yaw, 0)
			c.breathe = 0.5 + 0.5 * math.sin(c.clock * 2.2)
			L.stepState(c, dt, v.Y)
			return true
		end





		local MLIMBS = { "RightHand", "LeftHand", "RightFoot", "LeftFoot", "Right Arm", "Left Arm", "Right Leg", "Left Leg" }
		L.motion = function(dt, s, hidden, phrases, any)
			local c, M = L.ch, L.MS
			if not M then M = { e = 0, slow = 0, cd = 0, was = false } L.MS = M end
			local root, char = c.hrp, c.char
			if not root or not char then return end
			local inv = root.CFrame:Inverse()
			local emote = c.emote == true
			if emote and not hidden then M.off = 0 else M.off = (M.off or 0) + dt end
			if M.was and M.off < 0.8 and not hidden then emote = true end
			if emote and M.was and c.emoteObj and M.obj and c.emoteObj ~= M.obj then M.was = false end
			if c.emoteObj then M.obj = c.emoteObj end
			if not emote or hidden then
				if c.torso then M.rest = (inv * c.torso.Position).Y end
				if M.was then M.was, M.obj, c.sPhrase, c.mCur, c.mOn = false, nil, nil, nil, false end
				M.last, M.yaw = nil, nil
				return
			end
			if not M.was then
				M.was, M.t, M.votes, M.said, M.calm = true, 0, { dance = 0, spin = 0, cheer = 0, low = 0, pose = 0, sway = 0 }, false, 0
				c.sEmoteN = (c.sEmoteN or 0) + 1
			end
			c.mOn = true
			M.t += dt
			local pts, sum, k = {}, 0, 0
			for _, n in ipairs(MLIMBS) do
				local p = char:FindFirstChild(n)
				if p and p:IsA("BasePart") then
					local v = inv * p.Position
					pts[n] = v
					local o = M.last and M.last[n]
					if o then sum += (v - o).Magnitude k += 1 end
				end
			end
			M.last = pts
			local energy = k > 0 and sum / k / math.max(dt, 1 / 240) / s or 0
			M.e += (energy - M.e) * L.c01(dt * 10)
			M.slow += (M.e - M.slow) * L.c01(dt * 1.2)
			M.cd -= dt
			if M.e > 5 and M.e > M.slow * 1.4 and not M.hi and M.cd <= 0 then M.hi, M.cd = true, 0.3 c.sBeat = (c.sBeat or 0) + 1
			elseif M.e < M.slow * 1.1 then M.hi = false end
			local yr = 0
			if c.torso then
				local lv = inv:VectorToObjectSpace(c.torso.CFrame.LookVector)
				local wl = root.CFrame.LookVector
				local yaw = math.atan2(-lv.X, -lv.Z) + math.atan2(-wl.X, -wl.Z)
				if M.yaw then yr = math.abs((yaw - M.yaw + math.pi) % (2 * math.pi) - math.pi) / math.max(dt, 1 / 240) end
				M.yaw = yaw
			end
			M.spin = (M.spin or 0) + (yr - (M.spin or 0)) * L.c01(dt * 6)
			local head = char:FindFirstChild("Head")
			local hy = head and (inv * head.Position).Y or 1.5 * s
			local rh, lh = pts.RightHand or pts["Right Arm"], pts.LeftHand or pts["Left Arm"]
			local up = rh and lh and rh.Y > hy - (pts.RightHand and 0.1 or 0.5) * s and lh.Y > hy - (pts.LeftHand and 0.1 or 0.5) * s
			local low = c.torso and M.rest and (inv * c.torso.Position).Y < M.rest - 0.9 * s
			M.calm = M.e < 3.2 and M.calm + dt or 0
			local cur = M.spin > 5 and "spin" or up and "cheer" or low and "low" or M.e > 6 and "dance" or M.calm > 1.5 and "pose" or M.e > 3.2 and "sway" or nil
			c.mCur = cur
			if cur then M.votes[cur] += dt end
			if not M.said and M.t > 1.2 and (phrases or any) then
				M.said = true
				local best, bv = nil, 0.15
				for n, v in pairs(M.votes) do if v > bv then best, bv = n, v end end
				c.sPhrase = (best and phrases and phrases[best]) or (any and any[math.random(1, #any)]) or nil
				local me = c.sEmoteN
				task.delay(3.5, function() if c.sEmoteN == me then c.sPhrase = nil end end)
			end
		end





		L.ground = function(p, up, down)
			local G = L.gnd
			if not G then G = { rp = RaycastParams.new() } G.rp.FilterType = Enum.RaycastFilterType.Exclude G.rp.IgnoreWater = false L.gnd = G end
			local clk = L.ch.clock
			if G.clk == clk and G.p == p and G.u == up and G.d == down then return G.r end
			if G.root ~= L.root or G.char ~= L.ch.char then G.root, G.char = L.root, L.ch.char G.rp.FilterDescendantsInstances = { L.root, L.ch.char } end
			local from = p + Vector3.new(0, up or 6, 0)
			local ok, hit = pcall(function() return workspace:Raycast(from, Vector3.new(0, -((up or 6) + (down or 40)), 0), G.rp) end)
			local r = (ok and hit) and hit.Position or p
			G.clk, G.p, G.u, G.d, G.r = clk, p, up, down, r
			return r
		end

		L.bodyParts = function()
			local t = {}
			local char = L.ch.char
			if not char then return t end
			local function add(root)
				for _, d in ipairs(root:GetDescendants()) do
					if ((d:IsA("BasePart") and d.Name ~= "HumanoidRootPart") or d:IsA("Decal")) and d.Transparency < 1 and d:GetAttribute("_rcfx") == nil then t[d] = true end
				end
			end
			add(char)

			local m2f = System.M2FName and workspace:FindFirstChild(System.M2FName)
			local shadow = m2f and m2f:FindFirstChild(char.Name)
			if shadow then add(shadow) end
			return t
		end


		L.timeline = function(dur, fn, objs, done)
			local fired = {}
			local tt = 0
			local function once(key, at) if fired[key] or tt < at then return false end fired[key] = true return true end
			if L.dead then if done then pcall(done) end return end
			local e = { t = 0, life = dur, fn = function(_, t) tt = t fn(t, once) end, objs = objs or {}, tok = R.ctx, done = done }
			table.insert(L.live, e)
			local ok, err = pcall(e.fn, 0, 0)
			if not ok then warn("timeline " .. tostring(err)) end
		end


		L.ghost = function(col, mat, life, keep)
			if L.dead then return INERT end
			local c = L.ch
			local m = Instance.new("Model")
			for _, p in ipairs(c.char:GetChildren()) do
				if p:IsA("BasePart") and p.Name ~= "HumanoidRootPart" and p.Transparency < 1 then
					local g = p:Clone()
					for _, d in ipairs(g:GetChildren()) do if not d:IsA("DataModelMesh") then d:Destroy() end end
					g.Anchored, g.CanCollide, g.CanQuery, g.CanTouch, g.CastShadow = true, false, false, false, false
					g.Material, g.Color = mat or Enum.Material.ForceField, col
					if g:IsA("MeshPart") then g.TextureID = "" end
					g.Transparency = 0
					g.Parent = m
				end
			end
			m.Parent = L.root
			L.fx(life or 0.4, keep and function() end or function(k) for _, g in ipairs(m:GetChildren()) do g.Transparency = 0.1 + 0.9 * k end end, { m })
			return m
		end


		L.groundWave = function(pos, tex, col, from, to, life, gain)
			local p, m = L.mesh("disc.mesh", tex or "ring_c.png", col, gain or 2.2)
			p.CFrame = CFrame.new(pos + Vector3.new(0, 0.1, 0))
			L.fx(life, function(k)
				local s = from + (to - from) * L.outQuad(k)
				m.Scale = Vector3.new(s, 1, s)
				p.Transparency = 0.06 + 0.94 * k
			end, { p })
			return p, m
		end


		L.handoff = function(o, tex, col, from, to, dur, gain)
			dur = dur or 2.4
			local p, m = L.mesh("disc.mesh", tex, col, gain or 2)
			local bp, bm = L.mesh("disc.mesh", "darkdisc.png", L.BACK, 1)
			p.Transparency, bp.Transparency = 1, 1
			local rot, landed = math.random() * 6, false
			L.fx(dur, function(k, t)
				local u = (1 - math.cos(math.pi * L.c01(t / (dur * 0.8)))) / 2
				local pos = o:Lerp(L.ch.feet, u)
				local s = from + (to - from) * u
				local a = L.c01(t / 0.3) * (1 - L.c01((k - 0.8) / 0.2))
				m.Scale = Vector3.new(s, 1, s)
				p.CFrame = CFrame.new(pos + Vector3.new(0, 0.09, 0)) * CFrame.Angles(0, rot + t * (1.5 - u), 0)
				p.Transparency = 1 - 0.94 * a
				bm.Scale = Vector3.new(s * 1.15, 1, s * 1.15)
				bp.CFrame = CFrame.new(pos + Vector3.new(0, 0.035, 0))
				bp.Transparency = 1 - 0.6 * a
				if not landed and k >= 0.8 then landed = true L.groundWave(L.ch.feet, tex, col, to, to * 1.7, 0.45, gain or 2) end
			end, { p, bp })
		end



		L.gui = function()
			if L.sg and L.sg.Parent then return L.sg end
			L.sg = L.new("ScreenGui", { Name = "RCThemeScreen", IgnoreGuiInset = true, DisplayOrder = 50, ResetOnSpawn = false }, L.plr.PlayerGui)
			return L.sg
		end



		L.fam = function(n, w) return Font.new("rbxasset://fonts/families/" .. n .. ".json", w or Enum.FontWeight.Bold) end
		L.vp = function() return workspace.CurrentCamera.ViewportSize end

		L.segPx = function(parent, col, z)
			local f = L.new("Frame", { BorderSizePixel = 0, BackgroundColor3 = col, AnchorPoint = Vector2.new(0.5, 0.5), ZIndex = z or 4 }, parent)
			return f, function(x1, y1, x2, y2, th)
				local dx, dy = x2 - x1, y2 - y1
				f.Position = UDim2.fromOffset((x1 + x2) / 2, (y1 + y2) / 2)
				f.Size = UDim2.fromOffset(math.sqrt(dx * dx + dy * dy) + th * 0.5, th)
				f.Rotation = math.deg(math.atan2(dy, dx))
			end
		end

		L.cineDrip = function(parent, col, w, len, per)
			local stem = L.new("Frame", { BorderSizePixel = 0, BackgroundColor3 = col, AnchorPoint = Vector2.new(0.5, 0), ZIndex = 5 }, parent)
			L.new("UICorner", { CornerRadius = UDim.new(0.5, 0) }, stem)
			local drop = L.new("ImageLabel", { BackgroundTransparency = 1, Image = L.T("drop.png"), ImageColor3 = col, AnchorPoint = Vector2.new(0.5, 0.35), Size = UDim2.fromOffset(w * 2.2, w * 3.2), ZIndex = 5 }, parent)
			local t0 = L.rnd(0, per)
			return function(x, ey, tt, on)
				local a = (tt - t0) % per
				local grow = L.c01(a / 0.9)
				local fall = a - 0.9
				local l = len * (fall < 0 and L.outQuad(grow) or math.max(0.4, 1 - fall * 1.2))
				stem.Position = UDim2.fromOffset(x, ey - 1)
				stem.Size = UDim2.fromOffset(w, l + 1)
				stem.BackgroundTransparency = on and 0 or 1
				if fall < 0 then
					drop.Position = UDim2.fromOffset(x, ey + l)
					drop.ImageTransparency = (on and grow > 0.5) and 0 or 1
				else
					drop.Position = UDim2.fromOffset(x, ey + len + 700 * fall * fall)
					drop.ImageTransparency = on and L.c01(fall / 0.7) or 1
				end
			end
		end

		L.cineEmbers = function(parent, n, col1, col2)
			local es = {}
			for i = 1, n do
				local f = L.new("Frame", { BorderSizePixel = 0, BackgroundColor3 = col1, AnchorPoint = Vector2.new(0.5, 0.5), ZIndex = 5, Visible = false }, parent)
				L.new("UICorner", { CornerRadius = UDim.new(0.5, 0) }, f)
				es[i] = { f = f, age = 0, life = L.rnd(0, 1.2) }
			end
			return function(dt, spawn, on)
				for _, e in ipairs(es) do
					e.age += dt
					if e.age >= e.life then
						if on then
							e.x, e.y = spawn()
							e.vx, e.vy, e.life, e.age, e.s = L.rnd(-20, 20), -L.rnd(40, 110), L.rnd(0.8, 1.6), 0, L.rnd(2, 5)
						else e.x = nil end
					end
					if e.x and e.age < e.life then
						local k = e.age / e.life
						e.x += (e.vx + 25 * math.sin(e.age * 5 + e.s)) * dt
						e.y += e.vy * dt
						local s = e.s * (1 - k * 0.6)
						e.f.Position, e.f.Size = UDim2.fromOffset(e.x, e.y), UDim2.fromOffset(s, s)
						e.f.BackgroundColor3 = col2:Lerp(col1, k)
						e.f.BackgroundTransparency = k * k
						e.f.Visible = true
					else e.f.Visible = false end
				end
			end
		end


		L.cine = {}
		L.screen = function(dur)


			if not L.root or not R.scr then return dummyScreen() end
			local sg = L.gui()
			local BLK = Color3.new(0, 0, 0)
			local cc = L.new("ColorCorrectionEffect", {}, workspace.CurrentCamera)
			local layer = L.new("Frame", { BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), ZIndex = 2 }, sg)
			local function mkBar(top)
				local f = L.new("Frame", { BorderSizePixel = 0, BackgroundColor3 = BLK, AnchorPoint = Vector2.new(0, top and 1 or 0), Position = UDim2.fromScale(0, top and 0 or 1),
					Size = UDim2.fromScale(1, CINE_BH), ZIndex = 2 }, layer)
				local fade = L.new("Frame", { BorderSizePixel = 0, BackgroundColor3 = BLK, AnchorPoint = Vector2.new(0, top and 0 or 1), Position = UDim2.fromScale(0, top and 1 or 0),
					Size = UDim2.fromScale(1, 0.7), ZIndex = 2 }, f)
				L.new("UIGradient", { Rotation = top and 90 or -90, Transparency = L.NS({ L.K(0, 0.15), L.K(1, 1) }) }, fade)
				local glow = L.new("ImageLabel", { BackgroundTransparency = 1, Image = L.T("glowui.png"), ImageColor3 = L.W, ImageTransparency = 1, AnchorPoint = Vector2.new(0.5, 0.5),
					Position = UDim2.fromScale(0.5, top and 1 or 0), Size = UDim2.fromScale(1.1, 0.9), ZIndex = 3 }, f)
				local ln = L.new("Frame", { BorderSizePixel = 0, BackgroundColor3 = L.W, BackgroundTransparency = 1, AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.fromScale(0, top and 1 or 0),
					Size = UDim2.new(1, 0, 0, 2), ZIndex = 4 }, f)
				L.new("UIGradient", { Transparency = L.NS({ L.K(0, 1), L.K(0.12, 0), L.K(0.88, 0), L.K(1, 1) }) }, ln)
				return { f = f, ln = ln, glow = glow, top = top }
			end
			local bars = { mkBar(true), mkBar(false) }
			local fl = L.new("Frame", { BorderSizePixel = 0, BackgroundColor3 = L.W, BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), ZIndex = 5 }, sg)
			local S = { t = 0, dim = 0, flashA = 0, shakeAmp = 0, shakeT = 0, cc = cc, fl = fl, b = 0 }
			S.flash = function(_, col, a) fl.BackgroundColor3 = col or L.W S.flashA = math.max(S.flashA, a or 1) end
			S.shake = function(_, amp, d) S.shakeAmp = math.max(S.shakeAmp, amp) S.shakeT = math.max(S.shakeT, d) S.shakeD = d end
			S.edge = function(top) return top and CINE_BH * S.b or 1 - CINE_BH * S.b end
			S.title = function(_, name, c1, c2)
				name = L.name()
				local st = L.cine[S.style] or {}
				local FN, FS, LIFE = st.font or L.HEAVY, st.sub or L.BOLD, st.life or 3.8
				local CY = 0.79
				local card = L.new("Frame", { BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), ZIndex = 6 }, sg)
				local box = L.new("Frame", { BackgroundTransparency = 1, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, CY), Size = UDim2.fromScale(0.62, 0.085), ZIndex = 6 }, card)
				local txt = st.upper == false and name or string.upper(name)
				local function lbl(parent, props)
					local t = L.new("TextLabel", { BackgroundTransparency = 1, TextScaled = true, TextColor3 = L.W, TextTransparency = 1, ZIndex = 7 }, parent)
					for k, v in pairs(props) do t[k] = v end
					return t
				end
				local nm = lbl(box, { Size = UDim2.fromScale(1, 1), Text = txt, FontFace = FN })
				local nst = L.new("UIStroke", { Color = st.stroke or BLK, Thickness = 2, Transparency = 1 }, nm)
				local ng = L.new("UIGradient", { Rotation = 90, Color = st.grad and st.grad(c1, c2) or L.CS({ L.CK(0, L.W), L.CK(0.55, c2:Lerp(L.W, 0.5)), L.CK(1, c1) }) }, nm)
				local kick = lbl(card, { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, CY - 0.06), Size = UDim2.fromScale(0.3, 0.024), Text = st.kick or "S  T  A  F  F", FontFace = FS,
					TextColor3 = c2:Lerp(L.W, 0.4) })
				local sub = lbl(card, { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, CY + 0.077), Size = UDim2.fromScale(0.3, 0.024), Text = st.subText or "H A S   A R R I V E D",
					FontFace = FS, TextColor3 = c2:Lerp(L.W, 0.6) })
				local ks = L.new("UIStroke", { Color = BLK, Thickness = 1.2, Transparency = 1 }, kick)
				local ss = L.new("UIStroke", { Color = BLK, Thickness = 1.2, Transparency = 1 }, sub)
				local rule = L.new("Frame", { BorderSizePixel = 0, BackgroundColor3 = c1:Lerp(L.W, 0.3), AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, CY + 0.054),
					Size = UDim2.new(0, 0, 0, 2), ZIndex = 6 }, card)
				L.new("UIGradient", { Transparency = L.NS({ L.K(0, 1), L.K(0.2, 0), L.K(0.8, 0), L.K(1, 1) }) }, rule)
				local Cd = { S = S, card = card, box = box, nm = nm, ng = ng, nst = nst, kick = kick, sub = sub, rule = rule, c1 = c1, c2 = c2, CY = CY, txt = txt, FN = FN, life = LIFE }
				Cd.copy = function(col, z) return lbl(box, { Size = UDim2.fromScale(1, 1), Text = txt, FontFace = FN, TextColor3 = col, ZIndex = z or 6 }) end
				local upd = st.card and st.card(Cd)
				L.fx(LIFE, function(k, tt)
					local out = 1 - L.c01((tt - (LIFE - 0.5)) / 0.5)
					local a = L.c01(tt / 0.35) * out
					card.Position = UDim2.fromScale(0, -0.012 * (1 - out))
					nm.TextTransparency = 1 - a
					nst.Transparency = 1 - a * 0.9
					local ka = L.c01((tt - 0.25) / 0.3) * out
					local sa = L.c01((tt - 0.45) / 0.3) * out
					kick.TextTransparency, ks.Transparency = 1 - ka, 1 - ka * 0.6
					sub.TextTransparency, ss.Transparency = 1 - sa, 1 - sa * 0.6
					rule.Size = UDim2.new(0.34 * L.outQuad((tt - 0.2) / 0.5), 0, 0, 2)
					rule.BackgroundTransparency = 1 - out
					if upd then
						local ok, err = pcall(upd, tt, a, out)
						if not ok then warn("cine card", err) upd = nil end
					end
				end, { card })
			end
			local camOff = CFrame.identity
			L.shakeN = (L.shakeN or 0) + 1

			local bindName = "RCThemeShake" .. uid .. "_" .. L.shakeN .. "_" .. math.floor(os.clock() * 1000) % 1000000


			local deadline = os.clock() + dur + 1
			L.binds = L.binds or {}
			L.binds[bindName] = true
			L.binds[bindName .. "u"] = true

			RS:BindToRenderStep(bindName .. "u", Enum.RenderPriority.Camera.Value - 1, function()
				local cam = workspace.CurrentCamera
				cam.CFrame = cam.CFrame * camOff:Inverse()
			end)


			RS:BindToRenderStep(bindName, Enum.RenderPriority.Camera.Value + 1, function()
				local cam = workspace.CurrentCamera
				if os.clock() > deadline and os.clock() > (L.frozenUntil or 0) + 1 then S.finish() return end
				if cam.CameraType == Enum.CameraType.Scriptable then camOff = CFrame.identity return end
				if os.clock() < (L.frozenUntil or 0) then cam.CFrame = cam.CFrame * camOff return end
				camOff = CFrame.identity
				if S.shakeT > 0 then
					local a = S.shakeAmp * (S.shakeT / (S.shakeD or 1))
					camOff = camOff * CFrame.Angles(L.rnd(-1, 1) * a * 0.02, L.rnd(-1, 1) * a * 0.02, 0) * CFrame.new(L.rnd(-1, 1) * a * 0.1, L.rnd(-1, 1) * a * 0.1, 0)
				end
				cam.CFrame = cam.CFrame * camOff
			end)

			S.finish = function()
				if S.finished then return end
				S.finished = true
				RS:UnbindFromRenderStep(bindName)
				RS:UnbindFromRenderStep(bindName .. "u")
				local cam = workspace.CurrentCamera
				cam.CFrame = cam.CFrame * camOff:Inverse() camOff = CFrame.identity
				L.binds[bindName] = nil
				L.binds[bindName .. "u"] = nil
				cc:Destroy() layer:Destroy() fl:Destroy()
			end
			L.fx(dur, function(k, tt)
				S.t = tt
				local d = S.dimFn and S.dimFn(tt) or 0
				cc.Brightness, cc.Contrast, cc.Saturation = -0.35 * d, 0.15 * d, -0.5 * d
				if S.tintFn then local col, amt = S.tintFn(tt) cc.TintColor = L.W:Lerp(col, L.c01(amt)) end
				local b = L.outQuad(S.boxFn and S.boxFn(tt) or 0)
				S.b = b
				bars[1].f.Position = UDim2.fromScale(0, CINE_BH * b)
				bars[2].f.Position = UDim2.fromScale(0, 1 - CINE_BH * b)
				if S.style and S.deco == nil then
					local st = L.cine[S.style] or {}
					local c1, c2 = S.c1 or L.W, S.c2 or L.W
					for _, br in ipairs(bars) do br.ln.BackgroundColor3 = c1:Lerp(L.W, 0.35) br.glow.ImageColor3 = c1 end
					S.deco = st.bar and st.bar({ S = S, layer = layer, bars = bars, c1 = c1, c2 = c2, edge = S.edge }) or false
				end
				for _, br in ipairs(bars) do br.ln.BackgroundTransparency = 1 - b br.glow.ImageTransparency = 1 - 0.5 * b end
				if S.deco then
					local ok, err = pcall(S.deco, tt, b)
					if not ok then warn("cine bar", err) S.deco = false end
				end
				S.flashA = math.max(0, S.flashA - (L.lastDt or 0.016) * 2.2)
				fl.BackgroundTransparency = 1 - S.flashA
				S.shakeT = math.max(0, S.shakeT - (L.lastDt or 0.016))
			end, {})
			L.live[#L.live].done = S.finish
			return S
		end


		L.cine.void = {
			font = L.fam("Zekton"), sub = L.fam("Zekton"),
			grad = function(c1, c2) return L.CS({ L.CK(0, L.W), L.CK(0.5, c2:Lerp(L.W, 0.6)), L.CK(1, c1:Lerp(L.W, 0.3)) }) end,

			bar = function(B)
				local cr = {}
				local function reroll(c, now)
					c.x = L.rnd(0.04, 0.96) * L.vp().X
					c.pts = {}
					local x, y = 0, 0
					for j = 1, 3 do x += L.rnd(-14, 14) y += L.rnd(8, 18) * (1.1 - j * 0.25) c.pts[j] = Vector2.new(x, y) end
					c.t0, c.life = now, L.rnd(0.6, 1.4)
				end
				for i = 1, 8 do
					local c = { top = i % 2 == 1, segs = {} }
					for j = 1, 3 do local f, set = L.segPx(B.layer, B.c1:Lerp(L.W, 0.6), 5) c.segs[j] = { f = f, set = set } end
					reroll(c, 0)
					c.t0 = -L.rnd(0, 1.2)
					cr[i] = c
				end
				return function(tt, b)
					local V = L.vp()
					for _, c in ipairs(cr) do
						if tt > c.t0 + c.life then reroll(c, tt) end
						local g = L.c01((tt - c.t0) / 0.12) * (1 - L.c01((tt - c.t0 - c.life + 0.2) / 0.2))
						local ey = B.edge(c.top) * V.Y
						local sd = c.top and 1 or -1
						local px, py = c.x, ey
						for j, s in ipairs(c.segs) do
							local q = c.pts[j]
							local nx, ny = c.x + q.X * g, ey + sd * q.Y * g
							s.set(px, py, nx, ny, 2.2 - j * 0.5)
							s.f.Visible = b > 0.3 and g > 0.02 and math.random() > 0.08
							px, py = nx, ny
						end
					end
					local a = tt % 1.4
					local p = math.max(L.c01(1 - a / 0.18), 0.7 * L.c01(1 - math.abs(a - 0.28) / 0.14))
					for _, br in ipairs(B.bars) do br.ln.BackgroundTransparency = 1 - b * (0.45 + 0.55 * p) end
				end
			end,

			card = function(Cd)
				local g1, g2 = Cd.copy(Color3.fromRGB(90, 230, 255), 6), Cd.copy(Cd.c2, 6)
				Cd.rule.Visible = false
				local N, pts, sg = 12, {}, {}
				for i = 0, N do pts[i] = (i == 0 or i == N) and 0 or L.rnd(-4, 4) end
				for i = 1, N do
					local f, s = L.segPx(Cd.card, L.W, 7)
					local gf, gs = L.segPx(Cd.card, Cd.c1, 6)
					sg[i] = { f = f, s = s, gf = gf, gs = gs }
				end
				local nextG, gEnd = 1.2, 0
				return function(tt, a)
					local V = L.vp()
					local w = 0.36 * V.X
					local x0, y = V.X / 2 - w / 2, (Cd.CY + 0.054) * V.Y
					local prog = L.outQuad((tt - 0.3) / 0.45)
					for i = 1, N do
						local u0, u1 = (i - 1) / N, i / N
						local vis = math.abs((u0 + u1) / 2 - 0.5) < prog / 2
						local s = sg[i]
						s.s(x0 + u0 * w, y + pts[i - 1], x0 + u1 * w, y + pts[i], 1.6)
						s.gs(x0 + u0 * w, y + pts[i - 1], x0 + u1 * w, y + pts[i], 6)
						s.f.Visible, s.gf.Visible = vis, vis
						s.f.BackgroundTransparency, s.gf.BackgroundTransparency = 1 - a, 1 - a * 0.4
					end
					if tt >= nextG then gEnd = tt + 0.12 nextG = tt + L.rnd(1.2, 2) end
					if (tt < 0.45 and math.random() < 0.5) or tt < gEnd then
						Cd.nm.TextTransparency = math.random() < 0.3 and 1 or 0.1
						local j = L.rnd(-0.012, 0.012)
						Cd.nm.Position = UDim2.fromScale(j, L.rnd(-0.05, 0.05))
						g1.Position, g2.Position = UDim2.fromScale(j - 0.01, 0), UDim2.fromScale(j + 0.01, 0)
						g1.TextTransparency, g2.TextTransparency = 1 - 0.8 * a, 1 - 0.7 * a
					else
						Cd.nm.Position = UDim2.new()
						g1.TextTransparency, g2.TextTransparency = 1, 1
					end
				end
			end,
		}

		L.cine.vampire = {
			font = L.fam("GrenzeGotisch", Enum.FontWeight.Heavy), sub = L.fam("GrenzeGotisch", Enum.FontWeight.Bold), upper = false, stroke = Color3.fromRGB(8, 0, 2),
			grad = function(c1, c2) return L.CS({ L.CK(0, c2:Lerp(L.W, 0.55)), L.CK(0.5, c2), L.CK(1, c1) }) end,

			bar = function(B)
				local dr = {}
				for i = 1, 10 do dr[i] = { x = (i - 0.5) / 10 + L.rnd(-0.03, 0.03), d = L.cineDrip(B.layer, Color3.fromRGB(135, 0, 16), L.rnd(3, 6), L.rnd(10, 30), L.rnd(2.2, 3.8)) } end
				return function(tt, b)
					local V = L.vp()
					local ey = B.edge(true) * V.Y
					for _, d in ipairs(dr) do d.d(d.x * V.X, ey, tt, b > 0.6) end
				end
			end,

			card = function(Cd)
				Cd.rule.BackgroundColor3 = Color3.fromRGB(160, 0, 20)
				local dr = {}
				for i = 1, 3 do dr[i] = { x = 0.5 + (i - 2) * 0.09 + L.rnd(-0.02, 0.02), d = L.cineDrip(Cd.card, Color3.fromRGB(150, 0, 18), L.rnd(2.5, 4), L.rnd(6, 14), L.rnd(1.6, 2.6)) } end
				local bat = L.new("ImageLabel", { BackgroundTransparency = 1, Image = L.T("bat_fb.png"), ImageRectSize = Vector2.new(256, 256), ImageColor3 = Color3.fromRGB(22, 0, 5),
					AnchorPoint = Vector2.new(0.5, 0.5), ImageTransparency = 1, ZIndex = 8 }, Cd.card)
				return function(tt, a, out)
					local V = L.vp()
					for _, d in ipairs(dr) do d.d(d.x * V.X, (Cd.CY + 0.054) * V.Y, tt, tt > 0.8 and out > 0.5) end
					local u = L.c01((tt - 0.25) / 1.4)
					if u > 0 and u < 1 then
						local s = 0.075 * V.Y
						bat.Size = UDim2.fromOffset(s, s)
						bat.Position = UDim2.fromScale(-0.08 + 1.16 * u, Cd.CY - 0.1 - 0.05 * math.sin(u * math.pi) + 0.008 * math.sin(tt * 22))
						bat.ImageRectOffset = BAT_CELLS[math.floor(tt * 14) % 4 + 1]
						bat.ImageTransparency = 0.05
					else bat.ImageTransparency = 1 end
				end
			end,
		}

		L.cine.inferno = {
			font = L.fam("Sarpanch", Enum.FontWeight.Heavy), sub = L.fam("Sarpanch", Enum.FontWeight.Bold), stroke = Color3.fromRGB(30, 3, 0),
			grad = function(c1, c2) return L.CS({ L.CK(0, L.W), L.CK(0.3, Color3.fromRGB(255, 244, 170)), L.CK(0.55, c2), L.CK(0.8, c1), L.CK(1, Color3.fromRGB(110, 10, 0)) }) end,

			bar = function(B)
				local em = L.cineEmbers(B.layer, 26, B.c1, Color3.fromRGB(255, 230, 140))
				return function(tt, b)
					local V = L.vp()
					em(L.lastDt or 0.016, function() return L.rnd(0, 1) * V.X, B.edge(false) * V.Y end, b > 0.5)
					for i, br in ipairs(B.bars) do
						local f = 0.5 + 0.5 * math.sin(tt * 7 + i * 2) * math.sin(tt * 3.3 + i)
						br.ln.BackgroundColor3 = B.c1:Lerp(B.c2:Lerp(L.W, 0.3), f)
						br.glow.ImageTransparency = 1 - b * (0.35 + 0.3 * f)
					end
				end
			end,

			card = function(Cd)
				local flow = Cd.copy(Color3.fromRGB(255, 250, 215), 8)
				local fg = L.new("UIGradient", { Rotation = 12, Transparency = L.NS({ L.K(0, 1), L.K(0.4, 1), L.K(0.5, 0.2), L.K(0.6, 1), L.K(1, 1) }) }, flow)
				local em = L.cineEmbers(Cd.card, 14, Cd.c1, Color3.fromRGB(255, 230, 140))
				return function(tt, a, out)
					local V = L.vp()
					local heat = L.outQuad((tt - 0.1) / 0.9)
					Cd.ng.Offset = Vector2.new(0, 0.85 * (1 - heat) + 0.04 * math.sin(tt * 9))
					fg.Offset = Vector2.new(-0.8 + ((tt * 0.6) % 1.6), 0)
					flow.TextTransparency = heat < 1 and 1 or (1 - out)
					em(L.lastDt or 0.016, function() return (0.5 + L.rnd(-0.28, 0.28)) * V.X, (Cd.CY + 0.03) * V.Y end, tt > 0.3 and out > 0.6)
				end
			end,
		}

		L.cine.storm = {
			font = L.fam("Oswald", Enum.FontWeight.Bold), sub = L.fam("Oswald", Enum.FontWeight.Bold),
			grad = function(c1, c2) return L.CS({ L.CK(0, L.W), L.CK(0.6, c1:Lerp(L.W, 0.5)), L.CK(1, c2) }) end,

			bar = function(B)
				local N, segs, pts = 10, {}, {}
				for i = 1, N do
					local f, s = L.segPx(B.layer, L.W, 5)
					local gf, gs = L.segPx(B.layer, B.c1, 4)
					gf.BackgroundTransparency = 0.55
					segs[i] = { f = f, s = s, gf = gf, gs = gs }
				end
				local nextS, sEnd, top, x0, w = 0.6, 0, true, 0, 0
				return function(tt, b)
					local V = L.vp()
					if tt >= nextS and b > 0.8 then
						sEnd, nextS, top = tt + 0.18, tt + L.rnd(0.7, 1.8), math.random() < 0.5
						w = L.rnd(0.18, 0.35) * V.X
						x0 = L.rnd(0, V.X - w)
						for i = 0, N do pts[i] = (i == 0 or i == N) and 0 or L.rnd(-7, 7) end
					end
					local on = tt < sEnd
					local ey = B.edge(top) * V.Y
					for i = 1, N do
						local s = segs[i]
						if on then
							local xa, xb = x0 + (i - 1) / N * w, x0 + i / N * w
							s.s(xa, ey + pts[i - 1], xb, ey + pts[i], 2)
							s.gs(xa, ey + pts[i - 1], xb, ey + pts[i], 7)
						end
						s.f.Visible, s.gf.Visible = on and math.random() > 0.1, on
					end
					for _, br in ipairs(B.bars) do
						local lit = on and br.top == top
						br.ln.BackgroundTransparency = 1 - b * (lit and 1 or 0.4 + 0.1 * math.sin(tt * 3))
						br.glow.ImageTransparency = 1 - b * (lit and 0.85 or 0.35)
					end
				end
			end,

			card = function(Cd)
				Cd.nm.Visible = false
				local halves = {}
				for side = 0, 1 do
					local clip = L.new("Frame", { BackgroundTransparency = 1, ClipsDescendants = true, Position = UDim2.fromScale(side * 0.5, 0), Size = UDim2.fromScale(0.5, 1), ZIndex = 7 }, Cd.box)
					local t = L.new("TextLabel", { BackgroundTransparency = 1, TextScaled = true, Text = Cd.txt, FontFace = Cd.FN, TextColor3 = L.W, Position = UDim2.fromScale(-side, 0),
						Size = UDim2.fromScale(2, 1), ZIndex = 7, TextTransparency = 1 }, clip)
					L.new("UIGradient", { Rotation = 90, Color = L.CS({ L.CK(0, L.W), L.CK(0.6, Cd.c1:Lerp(L.W, 0.5)), L.CK(1, Cd.c2) }) }, t)
					local stc = L.new("UIStroke", { Color = Color3.new(0, 0, 0), Thickness = 2, Transparency = 1 }, t)
					halves[side + 1] = { clip = clip, t = t, st = stc, sd = side == 0 and -1 or 1 }
				end
				local N, bolt, pts = 9, {}, {}
				for i = 1, N do
					local f, s = L.segPx(Cd.card, L.W, 9)
					local gf, gs = L.segPx(Cd.card, Cd.c1, 8)
					gf.BackgroundTransparency = 0.5
					bolt[i] = { f = f, s = s, gf = gf, gs = gs }
				end
				local strikeT, amp, nextS, flashed = 0.15, 1, 2.6, false
				local function newBolt() for i = 0, N do pts[i] = (i == 0 or i == N) and 0 or L.rnd(-14, 14) end end
				newBolt()
				return function(tt, a, out)
					local V = L.vp()
					if tt >= nextS and out > 0.8 then strikeT, amp, nextS = tt, 0.45, tt + 99 newBolt() end
					if not flashed and tt >= strikeT then flashed = true Cd.S:flash(Cd.c1:Lerp(L.W, 0.6), 0.3) end
					local k = tt - strikeT
					local on = k >= 0 and k < 0.2
					local x, y0, y1 = V.X * 0.5, (Cd.CY - 0.11) * V.Y, (Cd.CY + 0.07) * V.Y
					for i = 1, N do
						local s = bolt[i]
						if on then
							local ya, yb = y0 + (i - 1) / N * (y1 - y0), y0 + i / N * (y1 - y0)
							s.s(x + pts[i - 1], ya, x + pts[i], yb, 3)
							s.gs(x + pts[i - 1], ya, x + pts[i], yb, 10)
						end
						s.f.Visible, s.gf.Visible = on and math.random() > 0.15, on
					end
					local d = k < 0 and 1 or (1 - L.outBack(k / 0.45)) * amp
					local vis = tt >= 0.15 and out or 0
					for _, h in ipairs(halves) do
						h.clip.Position = UDim2.fromScale((h.sd < 0 and 0 or 0.5) + h.sd * 0.04 * d, -h.sd * 0.12 * d)
						h.clip.Rotation = h.sd * 4 * d
						h.t.TextTransparency = 1 - vis
						h.st.Transparency = 1 - vis * 0.9
					end
				end
			end,
		}

		L.cine.lightborn = {
			font = L.fam("Merriweather", Enum.FontWeight.Heavy), sub = L.fam("Merriweather", Enum.FontWeight.Bold),
			grad = function(c1, c2) return L.CS({ L.CK(0, L.W), L.CK(0.5, c2), L.CK(1, c1) }) end,

			bar = function(B)
				local gl = {}
				for i = 1, 2 do
					gl[i] = L.new("ImageLabel", { BackgroundTransparency = 1, Image = L.T("flare.png"), ImageColor3 = B.c2:Lerp(L.W, 0.4), AnchorPoint = Vector2.new(0.5, 0.5),
						Size = UDim2.fromOffset(90, 36), ImageTransparency = 1, ZIndex = 5 }, B.layer)
				end
				return function(tt, b)
					local V = L.vp()
					for i, br in ipairs(B.bars) do
						local u = (tt * 0.32 + (i - 1) * 0.5) % 1
						gl[i].Position = UDim2.fromOffset((i == 1 and u or 1 - u) * V.X, B.edge(br.top) * V.Y)
						gl[i].ImageTransparency = 1 - b * math.sin(u * math.pi)
						br.ln.BackgroundColor3 = B.c1:Lerp(B.c2, 0.5 + 0.5 * math.sin(tt * 2 + i))
					end
				end
			end,

			card = function(Cd)
				local rays = {}
				for i = 1, 15 do
					local f = L.new("Frame", { BorderSizePixel = 0, BackgroundColor3 = Cd.c2:Lerp(L.W, 0.3), AnchorPoint = Vector2.new(0.5, 1), ZIndex = 5 }, Cd.card)
					L.new("UIGradient", { Rotation = 90, Transparency = L.NS({ L.K(0, 1), L.K(0.6, 0.55), L.K(1, 0.8) }) }, f)
					rays[i] = { f = f, ang = -75 + (i - 1) / 14 * 150, len = L.rnd(0.7, 1.15), w = L.rnd(2, 5), ph = L.rnd(0, 6) }
				end
				local shine = Cd.copy(L.W, 8)
				local sg = L.new("UIGradient", { Rotation = 20, Transparency = L.NS({ L.K(0, 1), L.K(0.42, 1), L.K(0.47, 0.4), L.K(0.5, 0), L.K(0.53, 0.4), L.K(0.58, 1), L.K(1, 1) }) }, shine)
				return function(tt, a, out)
					local V = L.vp()
					local grow = L.outQuad((tt - 0.1) / 0.7)
					local cx, cy = V.X * 0.5, (Cd.CY + 0.03) * V.Y
					for _, r in ipairs(rays) do
						local l = r.len * 0.16 * V.Y * grow * (0.85 + 0.15 * math.sin(tt * 2 + r.ph))
						r.f.Position = UDim2.fromOffset(cx, cy)
						r.f.Size = UDim2.fromOffset(r.w, l)
						r.f.Rotation = r.ang + 3 * math.sin(tt * 0.7 + r.ph)
						r.f.BackgroundTransparency = 1 - out * grow
					end
					local k = ((tt - 0.4) % 2.4) / 0.7
					sg.Offset = Vector2.new(k <= 1 and (-1 + 2 * k) or -1, 0)
					shine.TextTransparency = (tt > 0.4 and k <= 1) and (1 - out) or 1
				end
			end,
		}

		L.cine.frost = {
			font = L.fam("Michroma", Enum.FontWeight.Regular), sub = L.fam("Michroma", Enum.FontWeight.Regular), stroke = Color3.fromRGB(10, 30, 50),
			grad = function(c1, c2) return L.CS({ L.CK(0, L.W), L.CK(0.6, c2), L.CK(1, c1) }) end,

			bar = function(B)
				local ic = {}
				for i = 1, 30 do
					local top = i <= 17
					local x = top and (i - 0.5) / 17 or (i - 17.5) / 13
					x = L.c01(x + L.rnd(-0.02, 0.02))
					local f = L.new("Frame", { BorderSizePixel = 0, BackgroundColor3 = L.W:Lerp(B.c2, 0.3), AnchorPoint = Vector2.new(0.5, top and 0 or 1), ZIndex = 4 }, B.layer)
					L.new("UICorner", { CornerRadius = UDim.new(0.5, 0) }, f)
					L.new("UIGradient", { Rotation = top and 90 or -90, Transparency = L.NS({ L.K(0, 0.05), L.K(1, 0.85) }) }, f)
					local edgeD = math.min(x, 1 - x)
					ic[i] = { f = f, top = top, x = x, len = (top and 1 or 0.6) * L.rnd(8, 30) * (1.3 - edgeD), w = L.rnd(2, 4), delay = edgeD * 2 }
				end
				local tw = {}
				for i = 1, 3 do
					tw[i] = { f = L.new("ImageLabel", { BackgroundTransparency = 1, Image = L.T("flare.png"), ImageColor3 = L.W, AnchorPoint = Vector2.new(0.5, 0.5), ImageTransparency = 1,
						ZIndex = 5 }, B.layer), t0 = L.rnd(0, 1.5), ic = ic[math.random(#ic)] }
				end
				return function(tt, b)
					local V = L.vp()
					for _, c in ipairs(ic) do
						local g = L.outQuad((tt - 0.3 - c.delay) / 0.6) * b
						local ey = B.edge(c.top) * V.Y
						c.f.Position = UDim2.fromOffset(c.x * V.X, ey)
						c.f.Size = UDim2.fromOffset(c.w, c.len * g)
						c.f.Visible = g > 0.02
					end
					for _, s in ipairs(tw) do
						local a = (tt - s.t0) % 1.6
						if a < 0.05 then s.ic = ic[math.random(#ic)] end
						local c = s.ic
						local g = math.sin(L.c01(a / 0.5) * math.pi)
						local ey = B.edge(c.top) * V.Y + (c.top and 1 or -1) * c.len
						s.f.Position = UDim2.fromOffset(c.x * V.X, ey)
						s.f.Size = UDim2.fromOffset(26 * g, 26 * g)
						s.f.ImageTransparency = 1 - g * b
					end
				end
			end,

			card = function(Cd)
				local sl = {}
				for i = 1, 12 do
					local f = L.new("Frame", { BorderSizePixel = 0, BackgroundColor3 = L.W:Lerp(Cd.c2, 0.2), AnchorPoint = Vector2.new(0.5, 0.5), ZIndex = 8, Visible = false }, Cd.card)
					local ang = (i / 12) * math.pi * 2 + L.rnd(-0.2, 0.2)
					sl[i] = { f = f, dx = math.cos(ang) * L.rnd(80, 200), dy = math.sin(ang) * L.rnd(30, 90), spin = L.rnd(-400, 400), w = L.rnd(3, 6), h = L.rnd(10, 22),
						ox = math.cos(ang) * 0.24, oy = math.sin(ang) * 0.03 }
				end
				local SH = 0.75
				return function(tt, a, out)
					local V = L.vp()
					local p = L.outQuad(tt / 0.7)
					local e = math.min(p * 0.5, 0.49)
					if p < 1 then
						Cd.ng.Transparency = L.NS({ L.K(0, 0), L.K(e, 0), L.K(e + 0.01, 1), L.K(0.99 - e, 1), L.K(1 - e, 0), L.K(1, 0) })
					else Cd.ng.Transparency = L.NS(0) end
					local k = tt - SH
					for _, s in ipairs(sl) do
						if k > 0 and k < 0.7 then
							local u = k / 0.7
							s.f.Visible = true
							s.f.Position = UDim2.new(0.5 + s.ox, s.dx * L.outQuad(u), Cd.CY + s.oy, s.dy * L.outQuad(u) + 120 * u * u)
							s.f.Size = UDim2.fromOffset(s.w, s.h)
							s.f.Rotation = s.spin * u
							s.f.BackgroundTransparency = u
						else s.f.Visible = false end
					end
				end
			end,
		}

		L.cine.mage = {
			font = L.fam("Fondamento", Enum.FontWeight.Regular), sub = L.fam("Fondamento", Enum.FontWeight.Regular),
			grad = function(c1, c2) return L.CS({ L.CK(0, L.W), L.CK(0.5, c2:Lerp(L.W, 0.4)), L.CK(1, c1) }) end,

			bar = function(B)
				local rows = {}
				for r = 1, 2 do
					rows[r] = {}
					for i = 1, 24 do
						local g = math.random(0, 15)
						rows[r][i] = L.new("ImageLabel", { BackgroundTransparency = 1, Image = L.T("glyphs.png"), ImageRectSize = Vector2.new(128, 128),
							ImageRectOffset = Vector2.new(g % 4 * 128, math.floor(g / 4) * 128), ImageColor3 = B.c1:Lerp(L.W, 0.3), AnchorPoint = Vector2.new(0.5, 0.5), ZIndex = 4 }, B.layer)
					end
				end
				return function(tt, b)
					local V = L.vp()
					local s = CINE_BH * 0.42 * V.Y
					local gap = V.X / 22
					for r, row in ipairs(rows) do
						local top = r == 1
						local cy = (B.edge(top) + (top and -1 or 1) * CINE_BH * 0.5) * V.Y
						local dir = top and -1 or 1
						for i, g in ipairs(row) do
							local x = ((i - 1) * gap + dir * tt * 28) % (gap * 24) - gap
							g.Position = UDim2.fromOffset(x, cy)
							g.Size = UDim2.fromOffset(s, s)
							g.ImageTransparency = 1 - b * (0.45 + 0.2 * math.sin(tt * 3 + i))
							if math.random() < 0.004 then local n = math.random(0, 15) g.ImageRectOffset = Vector2.new(n % 4 * 128, math.floor(n / 4) * 128) end
						end
					end
				end
			end,

			card = function(Cd)
				local CH = "ABCDEFGHJKLMNPQRSTUVWXYZ0123456789"
				local target, n = Cd.txt, #Cd.txt
				local last = -1
				local side = {}
				for i = 1, 2 do
					local g = (i == 1) and 5 or 10
					side[i] = L.new("ImageLabel", { BackgroundTransparency = 1, Image = L.T("glyphs.png"), ImageRectSize = Vector2.new(128, 128),
						ImageRectOffset = Vector2.new(g % 4 * 128, math.floor(g / 4) * 128), ImageColor3 = Cd.c1:Lerp(L.W, 0.3), AnchorPoint = Vector2.new(0.5, 0.5), ImageTransparency = 1, ZIndex = 7 }, Cd.card)
				end
				return function(tt, a, out)
					local V = L.vp()
					local step = math.floor(tt * 24)
					if step ~= last then
						last = step
						local o = table.create(n)
						for i = 1, n do
							local c = string.sub(target, i, i)
							if tt >= 0.15 + i * 0.05 or c == " " then o[i] = c else local r = math.random(1, #CH) o[i] = string.sub(CH, r, r) end
						end
						Cd.nm.Text = table.concat(o)
					end
					local s = 0.06 * V.Y
					for i, g in ipairs(side) do
						g.Position = UDim2.fromScale(0.5 + (i == 1 and -0.34 or 0.34), Cd.CY)
						g.Size = UDim2.fromOffset(s, s)
						g.Rotation = (i == 1 and 1 or -1) * tt * 50
						g.ImageTransparency = 1 - a * 0.8
					end
				end
			end,
		}

		L.punch = function(amp, dur, col, a)
			local S = L.screen((dur or 0.3) + 0.25)
			S:shake(amp, dur or 0.3)
			if col then S:flash(col, a or 0.3) end
			return S
		end





		L.camTilt = function(dur, fn)
			if L.dead or not L.root or L.player ~= L.plr then return end
			local off = CFrame.identity
			L.tiltN = (L.tiltN or 0) + 1
			local name = "RCThemeTilt" .. uid .. "_" .. L.tiltN .. "_" .. math.floor(os.clock() * 1000) % 1000000
			local t0, deadline, done = os.clock(), os.clock() + dur + 1, false
			L.binds = L.binds or {}
			L.binds[name], L.binds[name .. "u"] = true, true
			local function finish()
				if done then return end
				done = true
				pcall(function() RS:UnbindFromRenderStep(name) end)
				pcall(function() RS:UnbindFromRenderStep(name .. "u") end)
				L.binds[name], L.binds[name .. "u"] = nil, nil
				local cam = workspace.CurrentCamera
				if cam then cam.CFrame = cam.CFrame * off:Inverse() end
				off = CFrame.identity
			end
			RS:BindToRenderStep(name .. "u", Enum.RenderPriority.Camera.Value - 1, function()
				local cam = workspace.CurrentCamera
				cam.CFrame = cam.CFrame * off:Inverse()
				off = CFrame.identity
			end)
			RS:BindToRenderStep(name, Enum.RenderPriority.Camera.Value + 1, function()
				local cam = workspace.CurrentCamera
				if os.clock() > deadline then finish() return end
				if cam.CameraType == Enum.CameraType.Scriptable then off = CFrame.identity return end
				local ok, p = pcall(fn, os.clock() - t0)

				off = (ok and typeof(p) == "CFrame") and p or CFrame.Angles(math.clamp(ok and tonumber(p) or 0, -0.8, 0.8), 0, 0)
				cam.CFrame = cam.CFrame * off
			end)
			local e = { t = 0, life = dur, fn = function() end, objs = {}, tok = R.ctx, done = finish }
			table.insert(L.live, e)
		end



		L.tags = {}
		L.tag = function(o)
			if L.dead then return INERT end
			local bb = L.new("BillboardGui", { Name = "RCThemeTag", Size = UDim2.new(9, 0, 2.6, 0), StudsOffset = Vector3.new(0, o.y or 3.9, 0),
				LightInfluence = 0, AlwaysOnTop = true, MaxDistance = 200, ResetOnSpawn = false }, L.plr.PlayerGui)
			L.tags[#L.tags + 1] = bb
			local T = { bb = bb }
			T.glow = L.new("ImageLabel", { BackgroundTransparency = 1, Image = L.T("glowui.png"), ImageColor3 = o.glow or o.c1, ImageTransparency = 0.55,
				AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.42), Size = UDim2.fromScale(1.1, 1.5) }, bb)
			T.box = L.new("Frame", { BackgroundTransparency = 1, AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.fromScale(0.5, 0.02), Size = UDim2.fromScale(1, 0.6) }, bb)
			T.name = L.new("TextLabel", { BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), Text = string.upper(L.name()),
				FontFace = o.font or L.HEAVY, TextScaled = true, TextColor3 = L.W, ZIndex = 2 }, T.box)
			T.stroke = L.new("UIStroke", { Color = o.stroke or o.c1, Thickness = 2.5, Transparency = 0.25 }, T.name)
			T.grad = L.new("UIGradient", { Color = o.grad or L.CS({ L.CK(0, o.c2), L.CK(0.25, L.W), L.CK(0.5, o.c1), L.CK(0.75, L.W), L.CK(1, o.c2) }) }, T.name)
			T.shine = L.new("TextLabel", { BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), Text = T.name.Text, FontFace = o.font or L.HEAVY,
				TextScaled = true, TextColor3 = L.W, ZIndex = 3, TextTransparency = 1 }, T.box)
			T.shineG = L.new("UIGradient", { Rotation = 20, Transparency = L.NS({ L.K(0, 1), L.K(0.42, 1), L.K(0.47, 0.4), L.K(0.5, 0), L.K(0.53, 0.4), L.K(0.58, 1), L.K(1, 1) }) }, T.shine)
			T.row = L.new("Frame", { BackgroundTransparency = 1, AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.fromScale(0.5, 0.64), Size = UDim2.fromScale(0.9, 0.26) }, bb)
			T.role = L.new("TextLabel", { BackgroundTransparency = 1, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
