		local function skyReal(o, dur, p)
			if SKY.owner then return nil end
			local Lt = game:GetService("Lighting")
			local objs = {}
			local atm = Lt:FindFirstChildOfClass("Atmosphere")
			local made = false
			if not atm then atm = L.new("Atmosphere", { Density = 0, Haze = 0, Glare = 0, Offset = 0 }, Lt) objs[#objs + 1] = atm made = true end
			local sv = { c = atm.Color, d = atm.Decay, den = atm.Density, hz = atm.Haze, gl = atm.Glare, oa = Lt.OutdoorAmbient, am = Lt.Ambient }




			local dome, DR, H, NB, NW = {}, 0, 0, 8, 16
			local BANDF = { 0.6, 0.8, 0.95, 1, 1, 1, 1, 1 }
			local hc = p.atmC or p.oa
			local haze = Color3.new(hc.R * 0.75, hc.G * 0.75, hc.B * 0.75)
			local BANDC = { 0, 0.35, 0.7, 1, 1, 1, 1, 1 }
			local fk = {}
			for i = 1, NW * NB + 4 do
				local b = (i - 1) % NB + 1
