			for _, d in ipairs(dome) do objs[#objs + 1] = d end
			local function place()
				local cp = workspace.CurrentCamera.CFrame.Position
				local c = Vector3.new(cp.X, math.min(o.Y, cp.Y) - 30, cp.Z)
				local need = 320
				if math.abs(need - DR) > 25 then
					DR = need H = math.min(2048, DR * 1.3)
					for i = 1, NW * NB do dome[i].Size = Vector3.new(2 * DR * math.tan(math.pi / NW), H / NB + 0.05, 0.2) end
					for i = NW * NB + 1, NW * NB + 4 do dome[i].Size = Vector3.new(DR + 10, 0.2, DR + 10) end
				end
				for w = 1, NW do
					local a = w / NW * math.pi * 2
					for b = 1, NB do
						local pos = c + Vector3.new(math.cos(a) * DR, (b - 0.5) * H / NB, math.sin(a) * DR)
						dome[(w - 1) * NB + b].CFrame = CFrame.lookAt(pos, Vector3.new(c.X, pos.Y, c.Z))
					end
				end
				local q, L0 = (DR + 10) / 2, NW * NB
				dome[L0 + 1].CFrame = CFrame.new(c + Vector3.new(q, H, q)) dome[L0 + 2].CFrame = CFrame.new(c + Vector3.new(-q, H, q))
				dome[L0 + 3].CFrame = CFrame.new(c + Vector3.new(q, H, -q)) dome[L0 + 4].CFrame = CFrame.new(c + Vector3.new(-q, H, -q))
			end
			local released = false
			local function set(a)
				if released then return end
				place()
				for i, d in ipairs(dome) do d.Transparency = 1 - (p.domeA or 0.6) * a * fk[i] end

				Lt.OutdoorAmbient = sv.oa:Lerp(p.oa, a)
				Lt.Ambient = sv.am:Lerp(p.am, a)
				if not atm.Parent then return end
				atm.Color = sv.c:Lerp(p.atmC, a)
				atm.Decay = sv.d:Lerp(p.decay, a)
				atm.Density = sv.den + (p.den - sv.den) * a
				atm.Haze = sv.hz + (p.haze - sv.hz) * a
				atm.Glare = sv.gl + (p.glare - sv.gl) * a
			end
			local w = { objs = objs, set = set }

			w.release = function()
				if released then return end
				released = true
				if SKY.owner == w then SKY.owner = nil end
				for _, d in ipairs(dome) do pcall(function() d.Transparency = 1 end) end
