			Lifetime = NR(2, 3), Speed = NR(1, 2), Rotation = NR(0, 360), RotSpeed = NR(-90, 90), SpreadAngle = Vector2.new(30, 30),
			Acceleration = Vector3.new(0, -2, 0), Drag = 0.6 }
		for k, v in pairs(props or {}) do p[k] = v end
		return L.pe(parent, p)
	end
	local function mistE(parent, props)
		local p = { Texture = L.T("smoke.png"), Color = CS(W, C2), LightEmission = 0.25, Brightness = 1.4,
			Transparency = NS({ K(0, 1), K(0.3, 0.7), K(1, 1) }), Size = NS({ K(0, 1.5), K(1, 4) }), Lifetime = NR(1.5, 2.5),
			Speed = NR(0.5, 1.5), RotSpeed = NR(-20, 20), Rotation = NR(0, 360), Acceleration = Vector3.new(0, 0.2, 0) }
		for k, v in pairs(props or {}) do p[k] = v end
		return L.pe(parent, p)
	end
	local function glintE(parent, props)
		local p = { Texture = L.T("star.png"), Color = CS(W, C2), LightEmission = 1, Brightness = 4,
			Size = NS({ K(0, 0), K(0.5, 0.35), K(1, 0) }), Lifetime = NR(0.3, 0.6), Speed = NR(0, 0.2), Rotation = NR(0, 90) }
		for k, v in pairs(props or {}) do p[k] = v end
		return L.pe(parent, p)
	end

	local function crystal(base, w, lean, col)
		local p, m = L.mesh("shard.mesh", nil, col or C1, 1.5, Vector3.new(w, 0.01, w))
		p.Material = Enum.Material.Glass
		p.Transparency = 1
		local root = CFrame.new(base) * lean
		local function set(h, tr, gain)
			h = math.max(h, 0.01)
			m.Scale = Vector3.new(w, h, w)
			p.CFrame = root * CFrame.new(0, h / 2, 0)
			p.Transparency = tr
			if gain then L.tint(m, col or C1, gain) end
		end
		return p, m, set, root
	end
	local function leanOut(dir, ang)

		local axis = Vector3.yAxis:Cross(dir)
		if axis.Magnitude < 0.01 then return CFrame.Angles(0, rnd(0, 6), 0) end
		return CFrame.fromAxisAngle(axis.Unit, ang) * CFrame.Angles(0, rnd(0, 6), 0)
	end

	local function shatterBits(pos, n, spd, s)
		for i = 1, n do
			local p, m = L.mesh("shard.mesh", nil, i % 3 == 0 and W or C1, 1.8, Vector3.new(0.35, 0.9, 0.35) * rnd(0.6, 1.5) * s)
			p.Material = Enum.Material.Glass
			p.Transparency = 0.15
			local v = Vector3.new(rnd(-1, 1), rnd(0.2, 1.1), rnd(-1, 1)).Unit * rnd(0.5, 1) * spd
			local p0 = pos + Vector3.new(rnd(-1, 1), rnd(0, 2), rnd(-1, 1)) * s
			local spin = CFrame.Angles(rnd(0, 6), rnd(0, 6), rnd(0, 6))
			local sx, sy = rnd(-8, 8), rnd(-8, 8)
			local floor = ch.feet.Y + 0.2
			p.CFrame = CFrame.new(p0)
			L.fx(rnd(1.1, 1.6), function(k, t)
				local pp = p0 + v * t + Vector3.new(0, -40 * t * t, 0)
				if pp.Y < floor then pp = Vector3.new(pp.X, floor, pp.Z) end
				p.CFrame = CFrame.new(pp) * spin * CFrame.Angles(t * sx, t * sy, 0)
				p.Transparency = 0.15 + 0.85 * c01((k - 0.6) / 0.4)
			end, { p })
		end
	end


	local feetP = L.part({ Size = Vector3.new(6, 0.2, 6) })
	local skyP = L.part({ Size = Vector3.new(12, 0.2, 12) })
	local burstP = L.part({ Size = Vector3.one * 2 })
	local auraSnow = snowE(skyP, { Shape = Enum.ParticleEmitterShape.Box, EmissionDirection = Enum.NormalId.Bottom, Speed = NR(1.5, 2.5),
		Lifetime = NR(2.5, 3.2), Acceleration = Vector3.new(0.6, -0.8, 0) })
	local auraMist = mistE(feetP, { Shape = Enum.ParticleEmitterShape.Box, EmissionDirection = Enum.NormalId.Top, Speed = NR(0.3, 0.8),
		Size = NS({ K(0, 1.5), K(1, 3.5) }), Acceleration = Vector3.new(0, -0.1, 0) })
	local auraGlint = glintE(feetP, { Shape = Enum.ParticleEmitterShape.Box, EmissionDirection = Enum.NormalId.Top })
	local burst = snowE(burstP, { Shape = Enum.ParticleEmitterShape.Sphere, Speed = NR(10, 22), Lifetime = NR(0.7, 1.1), Drag = 3,
		Size = NS({ K(0, 0.4), K(1, 0.1) }), Acceleration = Vector3.new(0, -3, 0), SpreadAngle = Vector2.new(180, 180) })
	local gFrost, gFrostM = L.mesh("disc.mesh", "cracks_b.png", C2, 1.5, Vector3.new(10, 1, 10))
	local gHex, gHexM = L.mesh("disc.mesh", "hex.png", C1, 1.2, Vector3.new(7, 1, 7))
	local gRing, gRingM = L.mesh("disc.mesh", "ring_c.png", C1, 2, Vector3.new(6, 1, 6))

	local orbs = {}
	for i = 1, 5 do
		local p, m = L.mesh("shard.mesh", nil, i % 2 == 0 and C2 or C1, 1.6, Vector3.new(0.35, 1.1, 0.35))
		p.Material = Enum.Material.Glass
		local ge = glintE(p, { Rate = 3 })
		orbs[i] = { p = p, m = m, ge = ge, ph = i / 5 * math.pi * 2, r = 3.2 + (i % 2) * 0.5, h = 0.6 + i * 0.5, sp = 0.45 }
	end

	local halo, haloM = L.mesh("disc.mesh", "ring_c.png", C2, 2.2, Vector3.new(2.6, 1, 2.6))
	local crownP = L.part({ Size = Vector3.new(2.6, 0.2, 2.6) })
	local crown = {}
	for i = 1, 8 do
		local p, m = L.mesh("shard.mesh", nil, i % 2 == 0 and W or C1, 1.7, Vector3.new(0.22, i % 2 == 0 and 0.75 or 0.5, 0.22))
		p.Material = Enum.Material.Glass
		crown[i] = { p = p, m = m, a = i / 8 * math.pi * 2, h = i % 2 == 0 and 0.75 or 0.5 }
	end
	local crownGlint = glintE(crownP, { Shape = Enum.ParticleEmitterShape.Box, Rate = 10, Size = NS({ K(0, 0), K(0.5, 0.25), K(1, 0) }) })
	local crownSnow = snowE(crownP, { Shape = Enum.ParticleEmitterShape.Box, EmissionDirection = Enum.NormalId.Bottom, Rate = 6, Speed = NR(0.4, 0.8),
		Lifetime = NR(1.2, 1.8), Size = NS({ K(0, 0.12), K(1, 0.05) }), Acceleration = Vector3.new(0, -0.5, 0) })
	local crownLight = L.new("PointLight", { Color = C1, Range = 10, Brightness = 1.5, Shadows = false }, crownP)

	local rig, light, hl = {}, nil, nil
	local function rebind()
		for _, o in ipairs(rig) do o:Destroy() end
		rig = {}
		local hrp = ch.hrp
		local function att(pos) local a = L.new("Attachment", { Position = pos }, hrp) rig[#rig + 1] = a return a end
		local function trail(a0, a1, props) local t = L.new("Trail", props, hrp) t.Attachment0, t.Attachment1 = a0, a1 rig[#rig + 1] = t return t end
		rig.main = trail(att(Vector3.new(0, 1.2, 0.3)), att(Vector3.new(0, -1.5, 0.3)), { Texture = L.T("beamb.png"), LightEmission = 0.5, Brightness = 2,
			Lifetime = 0.5, FaceCamera = true, Enabled = false, Color = CS({ CK(0, W), CK(0.3, C2), CK(1, C1) }),
			Transparency = NS({ K(0, 0.3), K(1, 1) }), WidthScale = NS({ K(0, 1), K(1, 0.3) }) })
		local back = att(Vector3.new(0, -1.6, 0.6))
		rig.mist = mistE(back, { Speed = NR(0.5, 1.5), Lifetime = NR(1, 1.6), Size = NS({ K(0, 1), K(1, 3) }) })
		rig.snow = snowE(att(Vector3.new(0, 0, 0.5)), { Speed = NR(1, 3), Lifetime = NR(0.8, 1.2), EmissionDirection = Enum.NormalId.Back })
		for _, e in ipairs({ rig.mist, rig.snow }) do rig[#rig + 1] = e end
		light = L.new("PointLight", { Color = C1, Range = 14, Brightness = 0, Shadows = false }, hrp) rig[#rig + 1] = light
		hl = L.new("Highlight", { FillTransparency = 1, OutlineColor = C2, Adornee = ch.char, DepthMode = Enum.HighlightDepthMode.Occluded }, L.root)
		rig[#rig + 1] = hl
	end
	rebind()
	local tag = System.StaffThemes.headTag(L, "frost", C1, C2, { c1 = C1, c2 = C2, grad = CS({ CK(0, C1), CK(0.35, C2), CK(0.5, W), CK(0.65, C2), CK(1, C1) }) })


	local function arriveFull(short)
		local o = ch.feet
		local sc = short and 0.6 or 1
		local DUR = short and 2.6 or 7.6
		local ENC, SHAT = short and 0.35 or 2.7, short and 0.85 or 3.7
		local S
		if not short then
			S = L.screen(DUR)
			S.dimFn = function(t) return 0.35 * c01(t / 0.8) * (1 - c01((t - SHAT - 1) / 1.5)) end
			S.style, S.c1, S.c2 = "frost", C1, C2 S.boxFn = function(t) return c01((t - 0.2) / 0.6) * (1 - c01((t - (DUR - 1)) / 0.8)) end
			S.tintFn = function(t) return C1, 0.4 * c01(t / 1.2) * (1 - c01((t - SHAT - 0.5) / 2)) end
			L.after(SHAT + 0.4, function() S:title(L.name(), C1, C2) end)
		end

		local gf, gfm = L.mesh("disc.mesh", "cracks_b.png", C2, 1.8)
		local gh, ghm = L.mesh("disc.mesh", "hex.png", C1, 1.4)

		local vort = {}
		local VR = 16 * sc
		for i = 1, (short and 6 or 10) do
			local a = i / (short and 6 or 10) * math.pi * 2
			local pos = o + Vector3.new(math.cos(a) * VR, 3 * sc, math.sin(a) * VR)
			local tan = Vector3.new(-math.sin(a), 0.05, math.cos(a))
			local vp = L.part({ Size = Vector3.new(2, 5 * sc, 0.2), CFrame = CFrame.lookAt(pos, pos + tan) })
			local streak = L.pe(vp, { Texture = L.T("spark.png"), Color = CS(W, C2), LightEmission = 0.6, Brightness = 2, Shape = Enum.ParticleEmitterShape.Box,
				EmissionDirection = Enum.NormalId.Front, Speed = NR(30, 45), Lifetime = NR(0.5, 0.8), Orientation = Enum.ParticleOrientation.VelocityParallel,
				Size = NS(0.25), Squash = NS(-3), Transparency = NS({ K(0, 1), K(0.2, 0.3), K(1, 1) }), Acceleration = Vector3.new(-math.cos(a), 0, -math.sin(a)) * 40 })
			local sn = snowE(vp, { Shape = Enum.ParticleEmitterShape.Box, EmissionDirection = Enum.NormalId.Front, Speed = NR(18, 28), Lifetime = NR(0.8, 1.2),
				Acceleration = Vector3.new(-math.cos(a), -0.3, -math.sin(a)) * 25, Size = NS({ K(0, 0.35), K(1, 0.2) }) })
			local mi = mistE(vp, { EmissionDirection = Enum.NormalId.Front, Speed = NR(10, 16), Lifetime = NR(1, 1.5), Size = NS({ K(0, 3 * sc), K(1, 6 * sc) }),
				Acceleration = Vector3.new(-math.cos(a), 0, -math.sin(a)) * 12 })
			vort[i] = { p = vp, e = { streak, sn, mi }, base = { 60, 40, 6 } }
		end

		local rings = short and { { 4.5, 8, 0.15 } } or { { 6, 8, 0.8 }, { 11, 12, 1.3 }, { 17, 16, 1.8 } }
		local crys = {}
		for ri, r in ipairs(rings) do
			local R, n, at = r[1] * sc, r[2], r[3]
			for i = 1, n do
				local a = i / n * math.pi * 2 + ri * 0.3
				local dir = Vector3.new(math.cos(a), 0, math.sin(a))
				local base = o + dir * (R + rnd(-0.8, 0.8) * sc)
				local h = (rnd(3, 6) + ri * 1.5) * sc
				local w = (rnd(0.9, 1.5) + ri * 0.25) * sc
				local p, m, set = crystal(base, w, leanOut(dir, math.rad(rnd(18, 35))), i % 3 == 0 and C2 or C1)
				crys[#crys + 1] = { p = p, set = set, h = h, at = at + rnd(0, 0.25), base = base, popped = false }
			end
		end

		local cas, casM, casSet = crystal(o - Vector3.new(0, 0.5, 0), 4.2 * sc, CFrame.identity, C2)
		local cas2, cas2M, cas2Set = crystal(o - Vector3.new(0, 0.5, 0), 3.4 * sc, CFrame.Angles(0, math.rad(30), 0), C1)
		local cLight = L.new("PointLight", { Color = C1, Range = 40, Brightness = 0, Shadows = false }, cas)
		local shattered = false
		local objs = { gf, gh, cas, cas2 }
		for _, v in ipairs(vort) do objs[#objs + 1] = v.p end
		for _, c in ipairs(crys) do objs[#objs + 1] = c.p end
		L.fx(DUR, function(k, t)
			local spread = c01(t / (short and 0.5 or 2.5))
			local after = c01((t - SHAT) / 3)
			local fs = (4 + 36 * L.outQuad(spread)) * sc
			gfm.Scale = Vector3.new(fs, 1, fs)
			gf.CFrame = CFrame.new(o + Vector3.new(0, 0.06, 0))
			gf.Transparency = 1 - 0.85 * c01(t / 0.3) * (1 - c01((t - DUR + 1.5) / 1.5))
			L.tint(gfm, C2:Lerp(W, shattered and (1 - after) * 0.6 or 0), shattered and 2.6 - after or 1.5 + 0.5 * spread)
			local hs = fs * 0.6
			ghm.Scale = Vector3.new(hs, 1, hs)
			gh.CFrame = CFrame.new(o + Vector3.new(0, 0.09, 0)) * CFrame.Angles(0, t * 0.1, 0)
			gh.Transparency = 1 - 0.6 * c01(t / 0.6) * (1 - c01((t - DUR + 1.5) / 1.5))

			local storm = c01(t / 0.6) * (1 - c01((t - SHAT - 0.6) / 1.5))
			for _, v in ipairs(vort) do for i, e in ipairs(v.e) do e.Rate = v.base[i] * storm * (short and 0.6 or 1) end end
			if S and not shattered then S:shake(0.1 + 0.3 * storm, 0.2) end

			for _, c in ipairs(crys) do
				if not c.gone then
					local g = c01((t - c.at) / 0.18)
					if g > 0 then
						local e = 1 - (1 - g) ^ 3
						c.set(c.h * e * (1 + 0.15 * math.sin(math.min(g, 1) * math.pi)), 0.12, 1.5 + 1.2 * (1 - g))
						if not c.popped then
							c.popped = true
							burstP.CFrame = CFrame.new(c.base) burst:Emit(short and 3 or 6)
							if S then S:shake(0.6, 0.15) end
						end
					else
						c.set(0.01, 1)
					end
				end
			end

			local enc = c01((t - ENC) / (short and 0.35 or 0.7))
			if not shattered then
				local e = 1 - (1 - enc) ^ 3
				casSet(7.5 * sc * e, enc > 0 and 0.35 or 1, 1.6 + 1.2 * enc)
				cas2Set(8.5 * sc * e, enc > 0 and 0.45 or 1, 1.4 + 1.2 * enc)
				cLight.Brightness = 4 * enc

				if t > SHAT - 0.4 then
					local s = c01((t - (SHAT - 0.4)) / 0.4)
					L.tint(casM, C2:Lerp(W, s), 1.6 + 2.5 * s)
					if S then S:shake(0.4 + 1.2 * s, 0.15) end
				end
			end
			if not shattered and t >= SHAT then
				shattered = true
				cas.Transparency, cas2.Transparency, cLight.Brightness = 1, 1, 0
				if S then S:flash(C2:Lerp(W, 0.6), 0.8) S:shake(3, 1.3) end
				shatterBits(o + Vector3.new(0, 2, 0), short and 14 or 30, 38 * sc, sc)
				for _, c in ipairs(crys) do
					c.gone = true
					c.p.Transparency = 1
					shatterBits(c.base + Vector3.new(0, c.h * 0.4, 0), short and 1 or 2, 26 * sc, sc * 0.8)
				end
				burstP.CFrame = CFrame.new(o + Vector3.new(0, 2, 0)) burst:Emit(short and 40 or 120)
				L.groundWave(o, "ring_c.png", W, 4, 70 * sc, 0.6)
				L.groundWave(o, "ring_c.png", C2, 4, 46 * sc, 0.9)
				L.groundWave(o, "hex.png", C1, 6, 40 * sc, 1.4, 2)
				if not short then L.groundWave(o, "ring_c.png", C1, 10, 1400, 5.4, 2.6) end

				local ringObjs = {}
				for j = 1, 16 do
					local a = j / 16 * math.pi * 2
					local p0 = o + Vector3.new(math.cos(a) * 2, 0.8, math.sin(a) * 2)
					local rp = L.part({ Size = Vector3.new(1.5, 1, 0.2), CFrame = CFrame.lookAt(p0, p0 + Vector3.new(math.cos(a), 0, math.sin(a))) })
					mistE(rp, { EmissionDirection = Enum.NormalId.Front, Speed = NR(30, 50), Drag = 2.5, Lifetime = NR(1.2, 1.8), SpreadAngle = Vector2.new(10, 6),
						Size = NS({ K(0, 3 * sc), K(1, 8 * sc) }), Transparency = NS({ K(0, 0.3), K(1, 1) }) }):Emit(short and 2 or 4)
					ringObjs[#ringObjs + 1] = rp
				end
				L.fx(2.2, function() end, ringObjs)
				light.Brightness = 8
			end
		end, objs)

		if not short then
			L.after(SHAT, function()
				local sp = L.part({ Size = Vector3.new(40, 0.2, 40), CFrame = CFrame.new(o + Vector3.new(0, 18, 0)) })
				local se = snowE(sp, { Shape = Enum.ParticleEmitterShape.Box, EmissionDirection = Enum.NormalId.Bottom, Speed = NR(2, 4), Lifetime = NR(4, 5),
					Size = NS({ K(0, 0.35), K(1, 0.25) }), Acceleration = Vector3.new(0.5, -1.5, 0) })
				local gl = glintE(sp, { Shape = Enum.ParticleEmitterShape.Box, EmissionDirection = Enum.NormalId.Bottom, Speed = NR(3, 5), Lifetime = NR(3, 4) })
				L.fx(4, function(kk) se.Rate = 120 * (1 - kk) gl.Rate = 30 * (1 - kk) end, { sp })
			end)
		end
	end

	local function implode(pos, col, from, to, life, gain, tex)
		local p, m = L.mesh("disc.mesh", tex or "ring_c.png", col, gain or 2.4)
		p.CFrame = CFrame.new(pos + Vector3.new(0, 0.1, 0))
		L.fx(life, function(k)
			local e = k * k
			local s = from + (to - from) * e
			m.Scale = Vector3.new(s, 1, s)
			p.Transparency = 1 - 0.9 * c01(k / 0.4) * (1 - c01((k - 0.85) / 0.15))
		end, { p })
		return p, m
	end



	local savedLTM, hideChar, hideOwner, hideGen, dashTok = nil, nil, nil, 0, nil
	local function setHidden(on, tok)
		if on then
			hideGen += 1
			local my = hideGen
			hideOwner = my
			task.delay(15, function() setHidden(false, my) end)
			if savedLTM and hideChar == ch.char then return my end
			if not ch.char then return my end
			savedLTM, hideChar = {}, ch.char
			for _, d in ipairs(ch.char:GetDescendants()) do
				if d:IsA("BasePart") or d:IsA("Decal") then savedLTM[d] = d.LocalTransparencyModifier d.LocalTransparencyModifier = 1 end
			end
			return my
		elseif savedLTM then
			if tok and tok ~= hideOwner then return end
			for d, v in pairs(savedLTM) do if d.Parent then d.LocalTransparencyModifier = v end end
			if tok and tok ~= dashTok then L.punch(1.1, 0.3) end
			savedLTM, hideChar, hideOwner = nil, nil, nil
		end
	end
	local function mistRing(o, n, s)
		local ringObjs = {}
		for j = 1, n do
			local a = j / n * math.pi * 2
			local p0 = o + Vector3.new(math.cos(a) * 1.5, 0.8, math.sin(a) * 1.5)
			local rp = L.part({ Size = Vector3.new(1.5, 1, 0.2), CFrame = CFrame.lookAt(p0, p0 + Vector3.new(math.cos(a), 0, math.sin(a))) })
			mistE(rp, { EmissionDirection = Enum.NormalId.Front, Speed = NR(25, 40), Drag = 2.5, Lifetime = NR(1, 1.5), SpreadAngle = Vector2.new(10, 6),
				Size = NS({ K(0, 2.5 * s), K(1, 6 * s) }), Transparency = NS({ K(0, 0.3), K(1, 1) }) }):Emit(3)
			ringObjs[#ringObjs + 1] = rp
		end
		L.fx(1.8, function() end, ringObjs)
	end
	local function finale(o, s)
		burstP.CFrame = CFrame.new(o + Vector3.new(0, 2, 0)) burst:Emit(45)
		L.groundWave(o, "ring_c.png", W, 3, 40 * s, 0.55)
		L.groundWave(o, "ring_c.png", C2, 3, 28 * s, 0.85)
		L.groundWave(o, "hex.png", C1, 4, 24 * s, 1.3, 2)
		mistRing(o, 12, s)
		light.Brightness = 8
	end

	local shorts = {}

	shorts[1] = function() arriveFull(true) end

	shorts[2] = function()
		local o = ch.feet
		local DUR, BREAK = 2.4, 1.3
		local g = L.ghost(C2, Enum.Material.Glass, BREAK, true)
		local hideTok = setHidden(true)
		local body = L.part({ Size = Vector3.new(2.5, 5, 1.5), CFrame = CFrame.new(ch.pos) })
		local gl = glintE(body, { Shape = Enum.ParticleEmitterShape.Box, Rate = 0, Size = NS({ K(0, 0), K(0.5, 0.3), K(1, 0) }) })
		local cold = mistE(body, { Shape = Enum.ParticleEmitterShape.Box, Rate = 0, Speed = NR(0.2, 0.6), Size = NS({ K(0, 1), K(1, 2.5) }), Acceleration = Vector3.new(0, -0.8, 0) })
		local gc, gcm = L.mesh("disc.mesh", "cracks_b.png", C2, 2, Vector3.new(8, 1, 8))
		local gh, ghm = L.mesh("disc.mesh", "hex.png", C1, 1.6, Vector3.new(6, 1, 6))
		local broke = false
		L.fx(DUR, function(k, t)
			local frost = c01(t / 1)
			local strain = c01((t - 1) / (BREAK - 1))
			gc.CFrame = CFrame.new(o + Vector3.new(0, 0.06, 0))
			gcm.Scale = Vector3.new(3 + 9 * L.outQuad(frost), 1, 3 + 9 * L.outQuad(frost))
			gc.Transparency = 1 - 0.85 * c01(t / 0.2) * (1 - c01((t - DUR + 0.8) / 0.8))
			gh.CFrame = CFrame.new(o + Vector3.new(0, 0.08, 0)) * CFrame.Angles(0, t * 0.3, 0)
			gh.Transparency = 1 - 0.5 * frost * (1 - c01((t - DUR + 0.8) / 0.8))
			if not broke then
				for _, p in ipairs(g:GetChildren()) do
					p.Transparency = 0.15
					p.Color = C2:Lerp(C1, 0.4 * frost):Lerp(W, strain)

					if strain > 0 then p.CFrame = p.CFrame * CFrame.new(rnd(-1, 1) * 0.04 * strain, 0, rnd(-1, 1) * 0.04 * strain) end
				end
				gl.Rate = 25 + 60 * strain
				cold.Rate = 10
				if t >= BREAK then
					broke = true
					for _, p in ipairs(g:GetChildren()) do p.Transparency = 1 end
					gl.Rate, cold.Rate = 0, 0
					setHidden(false, hideTok)
					hl.FillColor, hl.FillTransparency = W, 0.15
					shatterBits(ch.pos, 22, 30, 0.6)
					finale(o, 0.7)
				end
			else
				hl.FillTransparency = math.min(1, hl.FillTransparency + 0.03)
			end
		end, { body, gc, gh })
		task.delay(DUR + 0.1, function() setHidden(false, hideTok) end)
	end

	shorts[3] = function()
		local o = ch.feet
		local DUR, CLOSE, BLOW = 2.6, 1.1, 1.45
		local arms = {}
		for lvl = 1, 4 do
			for j = 1, 3 do
				local ph = j / 3 * math.pi * 2 + lvl * 0.7
				local y = 0.6 + (lvl - 1) * 1.8
				local start = o + Vector3.new(math.cos(ph) * 7, y, math.sin(ph) * 7)
				local p = L.part({ Size = Vector3.one * 1.5, CFrame = CFrame.new(start) })
				local a0 = L.new("Attachment", { Position = Vector3.new(0, 0.35, 0) }, p)
				local a1 = L.new("Attachment", { Position = Vector3.new(0, -0.35, 0) }, p)
				local tr = L.new("Trail", { Attachment0 = a0, Attachment1 = a1, Texture = L.T("beamb.png"), LightEmission = 0.7, Brightness = 3, Lifetime = 0.35,
					FaceCamera = true, Color = CS(W, C2), Transparency = NS({ K(0, 0.2), K(1, 1) }), WidthScale = NS(1, 0.3) }, p)
				local sn = snowE(p, { Rate = 40, Speed = NR(0.5, 1.5), Lifetime = NR(0.5, 0.8), Size = NS({ K(0, 0.3), K(1, 0.15) }), Acceleration = Vector3.zero })
				local mi = mistE(p, { Rate = 10, Speed = NR(0, 0.5), Lifetime = NR(0.5, 0.8), Size = NS({ K(0, 2), K(1, 3.5) }) })
				arms[#arms + 1] = { p = p, tr = tr, sn = sn, mi = mi, ph = ph, y = y }
			end
		end
		local blown = false
		local objs = {} for _, a in ipairs(arms) do objs[#objs + 1] = a.p end
		local ang = 0
		L.fx(DUR, function(k, t, dt)
			local close = L.outQuad(c01(t / CLOSE))
			local blow = c01((t - BLOW) / 0.5)
			ang += (4 + 10 * close) * 0.016
			local R = (7 - 5 * close) + 16 * L.outQuad(blow)
			for _, a in ipairs(arms) do
				local th = ang + a.ph
				a.p.CFrame = CFrame.new(ch.feet + Vector3.new(math.cos(th) * R, a.y + 2 * blow, math.sin(th) * R))
				local on = blow < 0.9
				a.tr.Enabled = on
				a.sn.Rate = on and 40 * (1 - blow) or 0
				a.mi.Rate = on and 10 * (1 - blow) or 0
			end
			if not blown and t >= BLOW then
				blown = true
				finale(o, 0.75)
				shatterBits(ch.pos, 10, 24, 0.5)
				hl.FillColor, hl.FillTransparency = C2, 0.25
			end
			if blown then hl.FillTransparency = math.min(1, hl.FillTransparency + 0.03) end
		end, objs)
	end

	shorts[4] = function()
		local o = ch.feet
		local DUR, NOVA = 2.6, 0.55
		implode(o, C2, 26, 1, NOVA, 2.6)
		implode(o, C1, 20, 1, NOVA * 0.9, 2, "hex.png")
		local sp = L.part({ Size = Vector3.one * 16, CFrame = CFrame.new(o + Vector3.new(0, 1, 0)) })
		local inS = snowE(sp, { Shape = Enum.ParticleEmitterShape.Sphere, ShapeInOut = Enum.ParticleEmitterShapeInOut.Inward,
			ShapeStyle = Enum.ParticleEmitterShapeStyle.Surface, Speed = NR(14, 18), Lifetime = NR(0.45, 0.55), Acceleration = Vector3.zero, Drag = 0 })
		local cry = {}
		local yaw = rnd(0, 6)
		for arm = 0, 5 do
			local a = yaw + arm * math.pi / 3
			local d = Vector3.new(math.cos(a), 0, math.sin(a))
			for i = 1, 6 do
				local dist = 1.4 + i * 1.9
				local h = 3.4 - i * 0.4
				local p, m, set = crystal(o + d * dist, 0.75 - i * 0.06, leanOut(d, math.rad(28)), i % 2 == 0 and C2 or C1)
				cry[#cry + 1] = { p = p, set = set, h = h, at = NOVA + i * 0.04 }
				if i == 3 or i == 5 then
					for _, sgn in ipairs({ -1, 1 }) do
						local b = a + sgn * math.pi / 3
						local bd = Vector3.new(math.cos(b), 0, math.sin(b))
						local p2, m2, set2 = crystal(o + d * dist + bd * 1.6, 0.4, leanOut(bd, math.rad(35)), C2)
						cry[#cry + 1] = { p = p2, set = set2, h = h * 0.6, at = NOVA + i * 0.04 + 0.08 }
					end
				end
			end
		end
		local nova = false
		local objs = { sp } for _, c in ipairs(cry) do objs[#objs + 1] = c.p end
		L.fx(DUR, function(k, t)
			inS.Rate = t < NOVA and 220 or 0
			local crumble = c01((t - 1.7) / 0.5)
			for _, c in ipairs(cry) do
				local g = c01((t - c.at) / 0.14)
				if g > 0 then
					c.set(c.h * (1 - (1 - g) ^ 3) * (1 - crumble), 0.12 + 0.88 * crumble, 1.6 + 1.6 * (1 - g))
				else
					c.set(0.01, 1)
				end
			end
			if not nova and t >= NOVA then
				nova = true
				finale(o, 0.8)
				hl.FillColor, hl.FillTransparency = W, 0.2
			end
			if nova then hl.FillTransparency = math.min(1, hl.FillTransparency + 0.03) end
			if crumble > 0 and not cry.broke then
				cry.broke = true
				for i = 1, #cry, 3 do shatterBits(cry[i].p.Position, 1, 14, 0.5) end
			end
		end, objs)
	end

	shorts[5] = function()
		local o = ch.feet
		local DUR, BREAK = 2.8, 1.9
		local back = ch.hrp.CFrame.LookVector
		back = -Vector3.new(back.X, 0, back.Z).Unit
		local ice = {}
		for i = 1, 11 do
			local big = i == 11
			local a = rnd(0, 6.28)
			local land = big and (o + back * 3.2) or (o + Vector3.new(math.cos(a), 0, math.sin(a)) * rnd(4.5, 9))
			local len = big and 7 or rnd(2.6, 4.2)
			local w = big and 1.6 or rnd(0.55, 0.85)
			local tilt = CFrame.Angles(rnd(-0.15, 0.15), rnd(0, 6), rnd(-0.15, 0.15))
			local p, m = L.mesh("shard.mesh", nil, big and W or (i % 2 == 0 and C2 or C1), 1.7, Vector3.new(w, len, w))
			p.Material = Enum.Material.Glass
			local sky = land + Vector3.new(0, 45, 0)
			p.CFrame = CFrame.new(sky) * tilt * CFrame.Angles(math.pi, 0, 0)
			local a0 = L.new("Attachment", { Position = Vector3.new(0, len * 0.5, 0) }, p)
			local a1 = L.new("Attachment", { Position = Vector3.new(0, len * 0.2, 0) }, p)
			local tr = L.new("Trail", { Attachment0 = a0, Attachment1 = a1, Texture = L.T("beamb.png"), LightEmission = 0.8, Brightness = 4, Lifetime = 0.18,
				FaceCamera = true, Color = CS(W, C1), Transparency = NS({ K(0, 0.2), K(1, 1) }) }, p)
			ice[i] = { p = p, m = m, land = land, sky = sky, tilt = tilt, len = len, at = big and 1.15 or (0.05 + (i - 1) * 0.085), fall = big and 0.32 or 0.38,
				big = big, tr = tr }
		end
		local broke = false
		local objs = {} for _, c in ipairs(ice) do objs[#objs + 1] = c.p end
		L.fx(DUR, function(k, t)
			for _, c in ipairs(ice) do
				if not broke then
					local u = c01((t - c.at) / c.fall)
					local e = u * u

					local stop = c.land + Vector3.new(0, c.len * 0.15, 0)
					c.p.CFrame = CFrame.new(c.sky:Lerp(stop, e)) * c.tilt * CFrame.Angles(math.pi, 0, 0)
					c.p.Transparency = t < c.at and 1 or 0.1
					c.tr.Enabled = u > 0 and u < 1
					if u >= 1 and not c.hit then
						c.hit = true
						burstP.CFrame = CFrame.new(c.land) burst:Emit(c.big and 30 or 8)
						L.groundWave(c.land, "cracks_b.png", C2, 1, c.big and 14 or 5, c.big and 1.2 or 0.8, 2.2)
						if c.big then
							L.groundWave(c.land, "ring_c.png", W, 2, 22, 0.6)
							mistRing(c.land, 10, 0.6)
							light.Brightness = 8
						end
					end
				end
			end
			if not broke and t >= BREAK then
				broke = true
				for _, c in ipairs(ice) do
					c.p.Transparency = 1
					shatterBits(c.land + Vector3.new(0, c.len * 0.3, 0), c.big and 10 or 3, c.big and 26 or 16, c.big and 0.8 or 0.5)
				end
				finale(o, 0.7)
			end
		end, objs)
	end




	local function arriveGlacier()
		local o = ch.feet
		local DUR = 11.2
		local STAGES = { 1.5, 2.35, 3.2 }
		L.after(DUR - 2.6, function() L.handoff(o, "ring_c.png", C1, 30, 6, 2.4) end)
		local THRONE, FREEZE, FORM, REVEAL, BLAST = 4.0, 5.0, 5.7, 6.9, 7.25
		local hideTok = setHidden(true)
		local fwd = L.facing()
		local right = fwd:Cross(Vector3.yAxis)
		local S = L.screen(DUR)
		S.dimFn = function(t) return (0.3 * c01(t / 1) + 0.35 * c01((t - FREEZE) / 0.2) * (1 - c01((t - FORM) / 0.5))) * (1 - c01((t - BLAST - 1.2) / 1.8)) end
		S.style, S.c1, S.c2 = "frost", C1, C2 S.boxFn = function(t) return c01((t - 0.2) / 0.6) * (1 - c01((t - (DUR - 1.2)) / 0.9)) end
		S.tintFn = function(t) return C1:Lerp(W, 0.35), (0.45 * c01(t / 1.4) + 0.4 * c01((t - FREEZE) / 0.2) * (1 - c01((t - FORM) / 0.6))) * (1 - c01((t - BLAST - 0.8) / 2.5)) end
		L.after(REVEAL + 0.5, function() S:title(L.name(), C1, C2) end)
		local objs = {}
		local function own(x) objs[#objs + 1] = x return x end


		local Lt = game:GetService("Lighting")
		local scr = L.scr()
		local oaBack, amBack = Lt.OutdoorAmbient, Lt.Ambient
		if scr then L.onEnd(function() Lt.OutdoorAmbient, Lt.Ambient = oaBack, amBack end) end
		local NIGHT = Color3.fromRGB(14, 26, 58)
		local PALE = Color3.fromRGB(190, 215, 240)

		local wsky = L.worldSky(o, DUR, { dome = PALE, atmC = Color3.fromRGB(205, 228, 255), decay = Color3.fromRGB(120, 160, 215),
			den = 0.3, haze = 0.7, glare = 0.2, oa = Color3.fromRGB(170, 195, 225), am = Color3.fromRGB(120, 140, 175), domeA = 0.75 })
		for _, x in ipairs(wsky.objs) do objs[#objs + 1] = x end
		local domeParts = {} for _, x in ipairs(wsky.objs) do if x:IsA("BasePart") then domeParts[#domeParts + 1] = x end end
		local paleSun = own(L.part({ Shape = Enum.PartType.Ball, Material = Enum.Material.Neon, Color = W, Transparency = 1, Size = Vector3.one * 34,
			CFrame = CFrame.new(o + fwd * 280 + right * 70 + Vector3.new(0, 120, 0)) }))
		local wideSnowP = own(L.part({ Size = Vector3.new(260, 0.5, 260), CFrame = CFrame.new(o + Vector3.new(0, 60, 0)) }))
		local wideSnow = snowE(wideSnowP, { Shape = Enum.ParticleEmitterShape.Box, EmissionDirection = Enum.NormalId.Bottom, Speed = NR(7, 10), Lifetime = NR(6, 7.5),
			SpreadAngle = Vector2.new(8, 8), Acceleration = Vector3.zero, Drag = 0, Size = NS({ K(0, 0.6), K(1, 0.45) }), Rate = 0 })
		local function skyA(t) return c01(t / 1.4) * (1 - c01((t - DUR + 1.8) / 1.6)) end

		local ia, iam = L.mesh("disc.mesh", "hex.png", C2, 1.4) own(ia)
		local ib, ibm = L.mesh("disc.mesh", "cracks_b.png", C1, 1.5) own(ib)
		local ICE_T = 4.2
		local iceFront = 0
		local function iceR(t) return 150 * L.outQuad(c01(t / ICE_T)) end
		local function frontCrystal(t)
			local rr = iceR(t)
			if rr < 8 then return end
			local a = rnd(0, math.pi * 2)
			local base = o + Vector3.new(math.cos(a) * rr, -0.3, math.sin(a) * rr)
			local h, w = rnd(1.2, 3.4), rnd(0.5, 1)
			local p, m, set = crystal(base, w, CFrame.fromAxisAngle(Vector3.new(-math.sin(a), 0, math.cos(a)), math.rad(rnd(-25, 25))) * CFrame.Angles(0, rnd(0, 6), 0), C1:Lerp(W, rnd(0.1, 0.5)))
			local life = DUR - t - 0.3
			L.fx(life, function(k, tt)
				local g = L.outBack(c01(tt / 0.25))
				local melt = c01((tt - (life - 1.6)) / 1.4)
				set(h * g * (1 - 0.8 * melt), 0.25 + 0.75 * melt, 1.6)
			end, { p })
		end

		local mq = {}
		do
			local root = ch.hrp.CFrame
			local tmpl = {}
			for _, p in ipairs(ch.char:GetDescendants()) do
				local ltm = savedLTM and savedLTM[p] or (p:IsA("BasePart") and p.LocalTransparencyModifier) or 1
				if p:IsA("BasePart") and p.Name ~= "HumanoidRootPart" and p.Transparency < 1 and ltm < 1 then
					local rel = root:ToObjectSpace(p.CFrame)
					local n = p.Name

					local limb = p.Parent == ch.char and ((n:find("Leg") or n:find("Foot")) and "leg" or ((n:find("Arm") or n:find("Hand")) and "arm")) or nil
					local sgn = n:find("Left") and 1 or -1
					local pivot = limb and (rel * CFrame.new(0, p.Size.Y * 0.45, 0)).Position or nil
					tmpl[#tmpl + 1] = { src = p, rel = rel, limb = limb, sgn = sgn, pivot = pivot }
				end
			end
			local MQ_N, RUN0 = 60, FORM - 0.3
			for i = 1, MQ_N do

				local a = rnd(0, math.pi * 2)
				local a1 = a + rnd(-0.45, 0.45)
				local dir = (fwd * math.cos(a) + right * math.sin(a)).Unit
				local dir1 = (fwd * math.cos(a1) + right * math.sin(a1)).Unit
				local r0, r1 = rnd(26, 72), rnd(7, 26)
				local m = Instance.new("Model")
				local parts = {}
				for _, tp in ipairs(tmpl) do
					local g = tp.src:Clone()
					for _, d in ipairs(g:GetChildren()) do if not d:IsA("DataModelMesh") then d:Destroy() end end
					g.Anchored, g.CanCollide, g.CanQuery, g.CanTouch, g.CastShadow = true, false, false, false, false
					g.Material, g.Color = Enum.Material.Glass, C1:Lerp(W, 0.35)
					if g:IsA("MeshPart") then g.TextureID = "" end
					g.Transparency = 1
					g.Parent = m
					parts[#parts + 1] = { g = g, tp = tp }
				end
				m.Parent = L.root
				own(m)
				local t0 = RUN0 + rnd(-0.7, 0.45)
				mq[i] = { m = m, parts = parts, dir = dir, dir1 = dir1, r0 = r0, r1 = r1, t0 = t0, up = t0 - 0.6, ph = rnd(0, 6), gone = false, broke = false,
					big = i % 4 == 0, ex = rnd(1.1, 1.7), sp = rnd(10, 16), lean = math.rad(rnd(-24, -8)) }
			end
			function mq.pose(q, t)
				if t < q.up then for _, pp in ipairs(q.parts) do pp.g.Transparency = 1 end return end

				local spawn = o + q.dir * q.r0
				if not q.broke then
					q.broke = true
					L.groundWave(spawn, "cracks_b.png", C1, 2, 22, 1.1, 2.8)
					L.groundWave(spawn, "hex.png", C2, 2, 14, 0.8, 2.4)

					for j = 1, q.big and 5 or 0 do
						local ja = j / 5 * math.pi * 2 + rnd(-0.3, 0.3)
						local jd = Vector3.new(math.cos(ja), 0, math.sin(ja))
						local jb = spawn + jd * 1.6 - Vector3.new(0, 0.4, 0)
						local jh = rnd(3, 5.5)
						local sp, _, sset = crystal(jb, rnd(0.7, 1.1), leanOut(jd, math.rad(rnd(20, 40))), C1:Lerp(W, 0.3))
						local crumbled = false
						L.fx(0.75, function(k, tt)
							sset(jh * L.outBack(c01(tt / 0.16)), crumbled and 1 or 0.2, 2)
							if not crumbled and tt >= 0.6 then crumbled = true shatterBits(jb + Vector3.new(0, jh * 0.4, 0), 2, 10, 0.6) end
						end, { sp })
					end
					L.groundWave(spawn, "ring_c.png", W, 1, 7, 0.4, 2.6)
					shatterBits(spawn + Vector3.new(0, 0.5, 0), 4, q.big and 16 or 6, 0.7)
					burstP.CFrame = CFrame.new(spawn + Vector3.new(0, 1, 0)) burst:Emit(q.big and 12 or 4)
				end
				local rise = c01((t - q.up) / 0.45)
				local sink = (1 - L.outBack(rise)) * 6.5
				local crouch = (1 - c01((t - q.t0 + 0.1) / 0.2)) * math.rad(-30)
				local u = c01((t - q.t0) / (BLAST - q.t0))
				local e = u ^ q.ex
				local rr = q.r0 + (q.r1 - q.r0) * e
				local dnow = q.dir:Lerp(q.dir1, e).Unit
				local pos = o + dnow * rr + Vector3.new(0, root.Y - o.Y - sink, 0)
				local cf = CFrame.lookAt(pos, pos - dnow) * CFrame.Angles(q.lean + crouch, 0, 0)
				local run = c01((t - q.t0) / 0.25)
				local sw = math.sin(t * q.sp + q.ph) * 0.95 * run
				local tr = 1 - 0.7 * c01((t - q.up) / 0.25)
				for _, pp in ipairs(q.parts) do
					local tp = pp.tp
					local rel = tp.rel
					if tp.limb then
						local ang = sw * tp.sgn * (tp.limb == "arm" and -0.8 or 1)
						rel = CFrame.new(tp.pivot) * CFrame.Angles(ang, 0, 0) * CFrame.new(-tp.pivot) * rel
					end
					pp.g.CFrame = cf * rel
					pp.g.Transparency = tr
				end
				return pos
			end
		end

		local function skyPin(a, p0, p1)
			local q0, k0 = L.skyProj(p0, 230)
			local q1, k1 = L.skyProj(p1, 230)
			a.a0.WorldPosition, a.a1.WorldPosition = q0, q1
			a.b.Width0, a.b.Width1 = a.w0 * k0, a.w1 * k1
		end

		local aur2 = {}
		for ci, cfg in ipairs({ { d = -60, h = 55, w = 110, col = Color3.fromRGB(170, 110, 255) }, { d = 5, h = 75, w = 130, col = Color3.fromRGB(80, 230, 255) }, { d = 90, h = 60, w = 150, col = Color3.fromRGB(110, 255, 170) } }) do
			for i = 1, 30 do
				local u = (i - 1) / 29 * 2 - 1
				local foot = o + fwd * (cfg.d + 14 * math.sin(u * 2.1 + ci)) + right * (u * cfg.w) + Vector3.new(0, cfg.h + 5 * math.cos(u * 2.6), 0)
				local a0, a1 = L.att(foot), L.att(foot + Vector3.new(0, 34, 0))
				local b = L.beam(a0, a1, { Texture = L.T("softbeam.png"), TextureMode = Enum.TextureMode.Stretch, Width0 = 14, Width1 = 18, Segments = 4,
					Brightness = 3.5, LightEmission = 1, FaceCamera = true, Color = CS({ CK(0, W), CK(0.12, cfg.col), CK(0.6, cfg.col:Lerp(C2, 0.5)), CK(1, C2) }), Transparency = NS(1) })
				aur2[#aur2 + 1] = { b = b, a0 = a0, a1 = a1, foot = foot, ph = u * 4 + ci * 2, w0 = 14, w1 = 18 }
				own(a0) own(a1) own(b)
			end
		end


		local skyBox = own(L.part({ Size = Vector3.new(70, 0.2, 70), CFrame = CFrame.new(o + Vector3.new(0, 24, 0)) }))
		local fall = snowE(skyBox, { Shape = Enum.ParticleEmitterShape.Box, EmissionDirection = Enum.NormalId.Bottom, Speed = NR(5, 7), Lifetime = NR(4, 5),
			SpreadAngle = Vector2.new(2, 2), Acceleration = Vector3.zero, Drag = 0, Size = NS({ K(0, 0.4), K(1, 0.3) }), Rate = 0 })
		local fallG = glintE(skyBox, { Shape = Enum.ParticleEmitterShape.Box, EmissionDirection = Enum.NormalId.Bottom, Speed = NR(5, 7), Lifetime = NR(4, 5), Rate = 0 })

		local gf, gfm = L.mesh("disc.mesh", "cracks_b.png", C2, 1.6) own(gf)
		local gh, ghm = L.mesh("disc.mesh", "hex.png", C1, 1.3) own(gh)




		local wall = {}
		local WC = o + fwd * 95
		local face = CFrame.lookAt(WC, WC - fwd)
		local KX, KY = 1, 1
		local ICE = C1:Lerp(W, 0.3)
