					p.Size = Vector3.new(w, hh, d) p.CFrame = face * CFrame.new(x, y0 - 0.3 + hh / 2, z)
					rim.Size = Vector3.new(w + 0.5, 0.7, d + 0.5) rim.CFrame = face * CFrame.new(x, y0 - 0.3 + hh, z)
					p.Transparency = tr < 1 and math.max(tr, 0.35) or 1
					rim.Transparency = tr < 1 and 0.25 or 1
				end
			elseif kind == "spire" then
				local p, m, cset = crystal(base, w, CFrame.Angles(0, math.rad(45), 0), C1:Lerp(DEEP, 0.35))
				p.Material = Enum.Material.Ice
				own(p) parts[1] = p
				ent.p = p
				function ent.set(hh, tr) cset(hh, tr < 1 and 0.08 or 1, 1.2) end
			elseif kind == "glow" then
				local p, m, cset = crystal(base, w, CFrame.Angles(0, 0, 0), C2:Lerp(W, 0.5))
				p.Material = Enum.Material.Neon
				own(p) parts[1] = p
				ent.p = p
				function ent.set(hh, tr)
					local glow = 0.3 + 0.7 * ent.pulse
					m.Scale = Vector3.new(w, math.max(hh, 0.01), d)
					p.CFrame = face * CFrame.new(x, y0 - 0.3 + math.max(hh, 0.01) / 2, z)
					p.Transparency = tr < 1 and (1 - 0.9 * glow) or 1
				end
			else
