					local glow = 0.4 + 0.6 * ent.pulse
					p.Transparency = tr < 1 and (1 - 0.95 * glow) or 1
					g.Transparency = tr < 1 and (1 - 0.5 * glow) or 1
				end
			end
			function ent.hide() for _, x2 in ipairs(parts) do x2.Transparency = 1 end end
			ent.parts = parts
			ent.set(0.01, 1)
			wall[#wall + 1] = ent
			return ent
		end

