				local side2 = Vector3.new(-d.Z, 0, d.X) * rnd(-1.6, 1.6)
				local base = ch.feet - Vector3.new(d.X, 0, d.Z) * (1.5 + i * 0.6) + side2
				local p, m, set = crystal(base, rnd(0.5, 0.8), leanOut(-Vector3.new(d.X, 0, d.Z).Unit, math.rad(rnd(20, 40))), i % 2 == 0 and C2 or C1)
				local hh = rnd(1.8, 3)
				L.fx(1, function(k) local g = c01(k / 0.15) set(hh * (1 - (1 - g) ^ 3) * (1 - c01((k - 0.7) / 0.3)), 0.15 + 0.85 * c01((k - 0.75) / 0.25), 2) end, { p })
			end
			burstP.CFrame = CFrame.new(ch.feet) burst:Emit(25)
			L.groundWave(ch.feet, "ring_c.png", C2, 2, 14, 0.5)
		end
		if on then
			local dir = ch.spd > 0.1 and ch.vel.Unit or Vector3.zAxis
