			if travel >= 4 then
				travel = 0 side = -side

				local fp = ch.feet + ch.hrp.CFrame.RightVector * 0.6 * side
				local p, m = L.mesh("disc.mesh", "cracks_b.png", C2, 2, Vector3.new(2.4, 1, 2.4))
				local hx, hxm = L.mesh("disc.mesh", "hex.png", C1, 1.6, Vector3.new(1.6, 1, 1.6))
