		gFrost.Transparency = 1 - iw * 0.75
		gHex.CFrame = ch.flat * CFrame.new(0, 0.07, 0) * CFrame.Angles(0, -ch.clock * 0.1, 0)
		gHex.Transparency = 1 - iw * 0.45
		gRing.CFrame = ch.flat * CFrame.new(0, 0.09, 0) * CFrame.Angles(0, ch.clock * 0.4, 0)
		gRing.Transparency = 1 - iw * 0.5
		for _, ob in ipairs(orbs) do
			local a = ch.clock * ob.sp + ob.ph
			ob.p.CFrame = CFrame.new(ch.pos + Vector3.new(math.cos(a) * ob.r, ob.h - 2 + 0.25 * math.sin(ch.clock + ob.ph), math.sin(a) * ob.r))
				* CFrame.Angles(0.3 * math.sin(ch.clock + ob.ph), a, 0.25)
			ob.p.Transparency = 1 - iw * 0.85
			L.tint(ob.m, C1:Lerp(W, 0.5 + 0.5 * math.sin(ch.clock * 2.5 + ob.ph * 3)), 1.6)
