					local a = off + i / 6 * math.pi * 2
					local d = Vector3.new(math.cos(a), 0, math.sin(a))
					local p, m, set = crystal(o + d * rnd(2.6, 3.4), rnd(0.35, 0.55), leanOut(d, math.rad(rnd(20, 35))), i % 2 == 0 and C2 or C1)
					local hh, dl = rnd(1, 1.8), i * 0.04
					L.fx(1.3, function(k, t)
						local g = c01((t - dl) / 0.15)
						local fall = c01((k - 0.65) / 0.35)
						set(hh * (1 - (1 - g) ^ 3) * (1 - fall), g > 0 and (0.15 + 0.85 * fall) or 1, 1.6 + 1.5 * (1 - g))
						if fall > 0 and not m:GetAttribute("b") then m:SetAttribute("b", true) burstP.CFrame = p.CFrame burst:Emit(3) end
					end, { p })
				end
				L.groundWave(o, "hex.png", C2, 2, 12, 0.9, 2)
				light.Brightness = 5
			end
