		local hp = ch.head.Position + Vector3.new(0, 1.2 + 0.08 * math.sin(ch.clock * 1.6), 0)
		local a = 0.55 + 0.45 * iw
		local rot = ch.clock * 0.5
		halo.CFrame = CFrame.new(hp) * CFrame.Angles(0, -rot, 0)
		halo.Transparency = 1 - a * 0.85
