			local ca = c.a + rot
			local pos = hp + Vector3.new(math.cos(ca) * 1.25, c.h * 0.5, math.sin(ca) * 1.25)
			c.p.CFrame = CFrame.new(pos) * CFrame.Angles(0, -ca, 0) * CFrame.Angles(0, 0, math.rad(-12))
			c.p.Transparency = 1 - a * 0.9
			L.tint(c.m, C1:Lerp(W, 0.5 + 0.5 * math.sin(ch.clock * 3 + c.a * 2)), 1.7)
		end
		crownGlint.Rate = 10 * a
		crownSnow.Rate = 6 * a * (on and 0.5 or 1)
		crownLight.Brightness = 1 + 1.2 * a

		tag.step(dt)
	end
