		follow[#follow + 1] = v:GetPropertyChangedSignal("Size"):Connect(function() if s.Parent then s.Size = v.Size * 1.002 end end)
		s.Destroying:Connect(function() for _, c in ipairs(follow) do c:Disconnect() end end)
		local w = Instance.new("WeldConstraint"); w.Part0 = s; w.Part1 = v; w.Parent = s
		s.Parent = v
		DataDetail.CurrentPartList.Link[s] = { T = v, Define = 0.8 }
		local function gone() if s.Parent then s:Destroy() end end
		if ObjectInstance then
			ObjectInstance.AncestryChanged:Connect(function(_, p) if not p then gone() end end)
			if not ObjectInstance.Parent then gone() end
		end
	end
	function Function.OilUp(ObjectInstance, Character, Extra, Data)
		local DataDetail = PlayerData[Data]
		local function oil(v)
			if not RS:IsStudio() then return Function._oilGloss(v, ObjectInstance, DataDetail) end
			if RS:IsStudio() then
				local mat

				if MS and MS:FindFirstChild("wetSmoothROCLOTHES") then
					mat = MS["wetSmoothROCLOTHES"]
				elseif MS then
					mat = Instance.new("MaterialVariant", MS)
					mat.Name="wetSmoothROCLOTHES"
					mat.BaseMaterial = Enum.Material.SmoothPlastic
					mat.MaterialPattern = Enum.MaterialPattern.Organic
					mat.RoughnessMap = "rbxassetid://14142895952"
					mat:AddTag(System.RCTag)
				end

				v.Material = Enum.Material.SmoothPlastic
				v.MaterialVariant = "wetSmoothROCLOTHES"
				local sa = v:FindFirstChildOfClass("SurfaceAppearance")
				if sa and not v:HasTag("ImportantSurfaceAppearance") then
					if sa.AlphaMode == Enum.AlphaMode.Transparency then
						v.TextureID = sa.ColorMap
						v.Transparency = 0.011
						v:SetAttribute("Alpha",0.011)
					elseif sa.AlphaMode == Enum.AlphaMode.Overlay then
						local overlay = v:Clone()
						overlay.Name = v.Name.."OILOVERLAY"
						overlay:ClearAllChildren()
						overlay.Parent = v
						local overlayWeld = Instance.new("Weld",overlay)
						overlayWeld.Part0 = overlay
						overlayWeld.Part1 = v
						overlay.Size = v.Size + Vector3.new(.001,.001,.001)
						overlay.Transparency = 0.01
						DataDetail.CurrentPartList.Link[overlay] = {T=v,Define=.01}
						if v.Parent and v.Parent:IsA("BasePart") then DataDetail.CurrentPartList.RealtimeUpdateList.Mesh[overlay] = {Base=v.Parent,Size=overlay.Size,CFrame=CFrame.new(0,0,0),CFrame1=CFrame.new(0,0,0),Weld=overlayWeld} end
						overlay.TextureID = sa.ColorMap
					end
					sa:Destroy()
				end
			else
				v.Material = Enum.Material.Glass
				if v.Transparency >= 1 then
					v:AddTag("RCGlassMat")
					v.Material = Enum.Material.Neon
				end
				local sa = v:FindFirstChildOfClass("SurfaceAppearance")
				if sa and not v:HasTag("ImportantSurfaceAppearance") then
					if sa.AlphaMode == Enum.AlphaMode.Transparency then
						v.TextureID = sa.ColorMap
						v.Transparency = 0.011
						v:SetAttribute("Alpha",0.011)
					elseif sa.AlphaMode == Enum.AlphaMode.Overlay then
						local overlay = v:Clone()
						overlay.Name = v.Name.."OILOVERLAY"
						overlay:ClearAllChildren()
						overlay.Parent = v
						local overlayWeld = Instance.new("Weld",overlay)
						overlayWeld.Part0 = overlay
						overlayWeld.Part1 = v
						overlay.Size = v.Size + Vector3.new(.001,.001,.001)
						overlay.Transparency = 0.01
						DataDetail.CurrentPartList.Link[overlay] = {T=v,Define=.01}
						if v.Parent and v.Parent:IsA("BasePart") then DataDetail.CurrentPartList.RealtimeUpdateList.Mesh[overlay] = {Base=v.Parent,Size=overlay.Size,CFrame=CFrame.new(0,0,0),CFrame1=CFrame.new(0,0,0),Weld=overlayWeld} end
						overlay.TextureID = sa.ColorMap
					end
					sa:Destroy()
				end
			end
		end
		task.delay(0,function()
			for i, v in pairs(DataDetail.CurrentPartList.Organ) do
				oil(v)
			end
		end)
	end
	function Function.OilUp2(ObjectInstance, Character, Extra, Data)
		local DataDetail = PlayerData[Data]

		local function saToOil(v, sa, setTex)
			if sa.AlphaMode == Enum.AlphaMode.Transparency then
				if setTex then v.TextureID = sa.ColorMap end
				v.Transparency = 0.011
				v:SetAttribute("Alpha",0.011)
			elseif sa.AlphaMode == Enum.AlphaMode.Overlay then
				local overlay = v:Clone()
				overlay.Name = v.Name.."OILOVERLAY"
				overlay:ClearAllChildren()
				overlay.Parent = v
				overlay.TextureID = sa.ColorMap
				local overlayWeld = Instance.new("Weld",overlay)
				overlayWeld.Part0 = overlay
				overlayWeld.Part1 = v
				overlay.Size = v.Size + Vector3.new(.001,.001,.001)
				overlay.Transparency = 0.01
				DataDetail.CurrentPartList.Link[overlay] = {T=v,Define=.01}
				if v.Parent and v.Parent:IsA("BasePart") then DataDetail.CurrentPartList.RealtimeUpdateList.Mesh[overlay] = {Base=v.Parent,Size=overlay.Size,CFrame=CFrame.new(0,0,0),CFrame1=CFrame.new(0,0,0),Weld=overlayWeld} end
			end
			sa:Destroy()
		end
		local function oil(v)
			if RS:IsStudio() then
				v.Material = Enum.Material.Glass
				local sa = v:FindFirstChildOfClass("SurfaceAppearance")
				if sa and not v:HasTag("ImportantSurfaceAppearance") then
					saToOil(v, sa, true)
				end
			else

				local matOk = MS ~= nil and MS:FindFirstChild("wetSmoothROCLOTHES") ~= nil
				if not matOk and MS ~= nil then
					matOk = pcall(function()
						local mat = Instance.new("MaterialVariant", MS)
						mat.Name="wetSmoothROCLOTHES"
						mat.BaseMaterial = Enum.Material.SmoothPlastic
						mat.MaterialPattern = Enum.MaterialPattern.Organic
						mat.RoughnessMap = "rbxassetid://14142895952"
						mat:AddTag(System.RCTag)
					end)
				end

				local sa = v:FindFirstChildOfClass("SurfaceAppearance")
				if matOk then
					v.Material = Enum.Material.SmoothPlastic
					v.MaterialVariant = "wetSmoothROCLOTHES"
					if sa and not v:HasTag("ImportantSurfaceAppearance") then
						saToOil(v, sa, true)
					end
				else
					v.Material = Enum.Material.Glass
					if sa and not v:HasTag("ImportantSurfaceAppearance") then
						saToOil(v, sa, false)
					end
				end
			end
		end
		task.delay(0,function()
			if not PlayerData[Data] then return end
			for i, v in pairs(DataDetail.CurrentPartList.Organ) do
				oil(v)
			end
		end)
	end
