	function Function._areolaDecals(ObjectInstance, Extra, Data, url, face, count)
		local DataDetail = PlayerData[Data]
		if not DataDetail then return end
		Extra = Extra or {}
		local _bc = table.find(DataDetail.CurrentClothes, "Roblox Breasts Clothing")
		local shown = ObjectInstance.Transparency ~= 1 and (not _bc or (ObjectInstance.Name ~= "Left Breast" and ObjectInstance.Name ~= "Right Breast"))
		for i = 1, count do
			local Decal = Instance.new("Decal", ObjectInstance)
			if not shown then Decal.Transparency = 1 end
			Decal.Color3 = Color3.fromRGB(255, 167, 169)
			Decal.Texture = Function.GetAsset(url)
			Decal.Face = face
			Decal.Name = count > 1 and ("Areola Decal " .. tostring(i)) or "Areola Decal"
			DataDetail.CurrentPartList.AreolaDecal[Decal] = ObjectInstance

			if Extra.Tone == "Dark" then
				local H,S,V = ObjectInstance.Color:ToHSV()
				Decal.Color3 = Color3.fromHSV(H,S,V+(-DarkerColorPercentage * V/100))
			elseif Extra.Tone == "Use NippleColor" then
				if Extra.NippleColor ~= nil then
					Decal.Color3 = Extra.NippleColor
				end
			end
		end
	end
	function Function.AreolaDecalCreate(ObjectInstance, Character, Extra, Data)
		Function._areolaDecals(ObjectInstance, Extra, Data, "rbxasset://RClothesContent/6667257628.png", "Left", 2)
	end


	function Function.AreolaDecalCreateVNS(ObjectInstance, Character, Extra, Data)
		local DataDetail = PlayerData[Data]
		if not DataDetail then return end

		local texture = Function.GetAsset("rbxasset://RClothesContent/_vns/model/breast/1/areola.png")
		if type(texture) ~= "string" or texture == "" or texture == "rbxasset://RClothesContent/_vns/model/breast/1/areola.png" then texture = Function.GetAsset("rbxasset://RClothesContent/6667257628.png") end
		do

			local Decal = Instance.new("Decal", ObjectInstance)
			if ObjectInstance.Transparency == 1 then Decal.Transparency = 1 end
			Decal.Texture = texture
			Decal.Face = Enum.NormalId.Back
			Decal.Name = "Areola Decal"

			Decal.Color3 = Color3.fromRGB(255, 167, 169)
			if Extra and Extra.Tone == "Dark" then
				local H, S, V = ObjectInstance.Color:ToHSV()
				Decal.Color3 = Color3.fromHSV(H, S, V + (-DarkerColorPercentage * V / 100))
			elseif Extra and Extra.Tone == "Use NippleColor" and Extra.NippleColor ~= nil then
