		L.new("Frame", { BorderSizePixel = 0, BackgroundColor3 = col, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.6), Size = UDim2.fromScale(0.5, 0.5), Rotation = 45, ZIndex = z or 1 }, g)
		circle(g, col, 0.33, 0.42, 0.42, 0.42, z) circle(g, col, 0.67, 0.42, 0.42, 0.42, z)
		return g
	end
	local function flower(parent, col)
		local g = L.new("CanvasGroup", { BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), GroupTransparency = 1 }, parent)
		for i = 1, 5 do
			local a = (i - 1) / 5 * math.pi * 2 - math.pi / 2
			circle(g, col, 0.5 + math.cos(a) * 0.24, 0.5 + math.sin(a) * 0.24, 0.36)
		end
		circle(g, GOLD, 0.5, 0.5, 0.26)
		return g
	end

