	local function bloom(pos, size, life)
		fi = fi % #flowers + 1
		local f = flowers[fi]
		f.t, f.life, f.s, f.ph = 0, math.max(life or 1.2, 1.8), (size or 0.6) * sc() * 1.3, rnd(0, 6)
		f.sp, f.bob, f.taken = false, 0, nil
		if math.abs(f.s - f.D) > 0.02 then
			f.D = f.s
			for _, p in ipairs(f.pet) do p.Size = Vector3.new(0.32, 0.07, 0.5) * f.D end
			for _, p in ipairs(f.leaf) do p.Size = Vector3.new(0.24, 0.04, 0.55) * f.D end
			f.core.Size = Vector3.new(0.3, 0.18, 0.3) * f.D
		end
		f.base = CFrame.new(pos + Vector3.new(0, 0.04, 0)) * CFrame.Angles(0, rnd(0, 6.3), 0)
	end



	local function flowerSet(f, tr, open, rise, t, wilt)
		local D = f.D
		wilt = wilt or 0
		local cf = f.base * CFrame.new(0, (rise - 1) * 0.35 * D - 0.15 * D * math.sin((f.bob or 0) * math.pi), 0) * CFrame.Angles(0.07 * math.sin(t * 3 + f.ph) + 0.5 * wilt, 0, 0.07 * math.cos(t * 2.4 + f.ph))
		for k, p in ipairs(f.pet) do
			local pitch = 1.35 - 1.15 * c01(open * 1.5 - (k - 1) * 0.12) + 0.8 * wilt
			p.CFrame = cf * CFrame.Angles(0, k / 5 * 2 * math.pi + t * 0.3, 0) * CFrame.new(0, 0.1 * D, 0.04 * D) * CFrame.Angles(-pitch, 0, 0) * CFrame.new(0, 0, 0.24 * D)
		end
		for k, p in ipairs(f.leaf) do p.CFrame = cf * CFrame.Angles(0, k * math.pi + 0.6, 0) * CFrame.new(0, 0.02 * D, 0.05 * D) * CFrame.Angles(-0.2, 0, 0) * CFrame.new(0, 0, 0.3 * D) end
		f.core.CFrame = cf * CFrame.new(0, 0.14 * D, 0)
		if math.abs(f.tr - tr) > 0.004 then
			f.tr = tr
			for _, p in ipairs(f.pet) do p.Transparency = tr end
			for _, p in ipairs(f.leaf) do p.Transparency = tr end
			f.core.Transparency = tr
		end
	end




	local function newSprite(col)
		local a = L.part()
		local bb = L.new("BillboardGui", { Adornee = a, Size = UDim2.new(1, 0, 1, 0), LightInfluence = 0, MaxDistance = 160, ResetOnSpawn = false }, a)
		local glowI = L.new("ImageLabel", { BackgroundTransparency = 1, Image = L.T("glowui.png") or "", ImageColor3 = col, ImageTransparency = 0.55, AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromScale(2.2, 2.2) }, bb)
		local light = L.new("PointLight", { Color = col, Range = 6, Brightness = 0.7, Shadows = false }, a)
		local sp = { a = a, bb = bb, glow = glowI, light = light, pos = nil, nap = 0, parts = {}, k = 1, ph = rnd(0, 6), closed = false }
		local function add(V, pos, c, mat) local e = { p = L.part({ Size = V, Color = c, Material = mat or SMOOTH, Transparency = 1 }), pos = pos, V = V } sp.parts[#sp.parts + 1] = e return e end
		sp.body = add(Vector3.new(0.6, 0.56, 0.5), Vector3.new(0, 0, 0), col:Lerp(W, 0.4))
		sp.cheek = add(Vector3.new(0.64, 0.12, 0.54), Vector3.new(0, -0.24, 0), col:Lerp(W, 0.15))
		sp.eyes = { add(Vector3.new(0.09, 0.15, 0.03), Vector3.new(-0.13, 0.05, -0.26), PLUM), add(Vector3.new(0.09, 0.15, 0.03), Vector3.new(0.13, 0.05, -0.26), PLUM) }
		add(Vector3.new(0.11, 0.06, 0.03), Vector3.new(-0.21, -0.07, -0.26), Color3.fromRGB(255, 160, 190))
		add(Vector3.new(0.11, 0.06, 0.03), Vector3.new(0.21, -0.07, -0.26), Color3.fromRGB(255, 160, 190))
		add(Vector3.new(0.08, 0.04, 0.03), Vector3.new(0, -0.08, -0.26), PLUM)
		sp.star = { add(Vector3.new(0.22, 0.22, 0.08), Vector3.new(0, 0.48, 0), GOLD:Lerp(W, 0.2), NEON), add(Vector3.new(0.22, 0.22, 0.08), Vector3.new(0, 0.48, 0), col, NEON) }
		sp.wing = { add(Vector3.new(0.3, 0.04, 0.22), Vector3.zero, W), add(Vector3.new(0.3, 0.04, 0.22), Vector3.zero, W) }
		return sp
	end

	local function spriteDraw(sp, pos, tr, t, closed, spin, k)
		if math.abs(k - sp.k) > 0.01 then
			sp.k = k
			for _, e in ipairs(sp.parts) do e.p.Size = e.V * k end
			sp.closed = nil
		end
		if closed ~= sp.closed then
			sp.closed = closed
			for _, e in ipairs(sp.eyes) do e.p.Size = Vector3.new(e.V.X, closed and 0.03 or e.V.Y, e.V.Z) * k end
		end
		local cam = workspace.CurrentCamera
		local cp = cam and cam.CFrame.Position or pos + Vector3.new(0, 0, 5)
		local flat = sp.face and (pos + sp.face) or Vector3.new(cp.X, pos.Y, cp.Z)
		local cf = ((flat - pos).Magnitude > 0.05 and CFrame.lookAt(pos, flat) or CFrame.new(pos)) * CFrame.Angles(0.1 * math.sin(t * 2.3 + sp.ph), 0, 0.14 * math.sin(t * 1.7 + sp.ph) + (sp.wave or 0) * 0.45 * math.sin(t * 12))
		for _, e in ipairs(sp.parts) do
			if e ~= sp.wing[1] and e ~= sp.wing[2] and e ~= sp.star[1] and e ~= sp.star[2] then e.p.CFrame = cf * CFrame.new(e.pos * k) end
			if math.abs(e.p.Transparency - tr) > 0.004 then e.p.Transparency = tr end
		end
		local sa = t * spin
		sp.star[1].p.CFrame = cf * CFrame.new(0, 0.48 * k + 0.04 * k * math.sin(t * 3 + sp.ph), 0) * CFrame.Angles(0, 0, sa)
		sp.star[2].p.CFrame = cf * CFrame.new(0, 0.48 * k + 0.04 * k * math.sin(t * 3 + sp.ph), 0.01 * k) * CFrame.Angles(0, 0, sa + math.pi / 4)
		local fl = 0.25 + 0.7 * math.abs(math.sin(t * (sp.wave == 1 and 22 or 14) + sp.ph))
		for q, sd in ipairs({ -1, 1 }) do sp.wing[q].p.CFrame = cf * CFrame.new(sd * 0.3 * k, 0.08 * k, 0.12 * k) * CFrame.Angles(0, 0, sd * fl) * CFrame.new(sd * 0.15 * k, 0, 0) end
	end
