	local WING_SPEC = {
		{ V = Vector3.new(0.6, 0.12, 0.12), x = 0.28, y = 0.32, z = 0, r = 0.5, c = W, core = true },
		{ V = Vector3.new(0.8, 0.11, 0.11), x = 0.9, y = 0.62, z = 0, r = 0.42, c = W, core = true },
