	}
	local function armY(x) return x < 0.54 and 0.17 + (x - 0.02) * 0.56 or 0.46 + (x - 0.54) * 0.45 end
	local function hang(ax, len, r) return ax + math.sin(r) * len / 2, armY(ax) - math.cos(r) * len / 2 end
	for i = 0, 6 do
		local ax, len, r = 0.15 + i * 0.16, 0.55 + 0.11 * i, 0.05 + 0.09 * i
		local x, y = hang(ax, len, r)
		WING_SPEC[#WING_SPEC + 1] = { V = Vector3.new(0.17, len, 0.05), x = x, y = y, z = 0.02, r = r, c = W:Lerp(C1, 0.06 + 0.06 * i), core = true }
		if i >= 4 then
			local tx, ty = ax + math.sin(r) * (len + 0.05), armY(ax) - math.cos(r) * (len + 0.05)
			WING_SPEC[#WING_SPEC + 1] = { V = Vector3.new(0.17, 0.12, 0.06), x = tx, y = ty, z = 0.02, r = r, c = C2:Lerp(W, 0.35), mat = Enum.Material.Neon }
		end
	end
	for i = 0, 4 do
		local ax, len, r = 0.1 + i * 0.2, 0.35 + 0.05 * i, 0.05 * i
		local x, y = hang(ax, len, r)
		WING_SPEC[#WING_SPEC + 1] = { V = Vector3.new(0.2, len, 0.05), x = x, y = y, z = 0.06, r = r, c = i % 2 == 0 and C1:Lerp(W, 0.45) or W:Lerp(C2, 0.3) }
	end
	for i = 0, 2 do
		local ax = 0.2 + i * 0.3
		WING_SPEC[#WING_SPEC + 1] = { V = Vector3.new(0.26, 0.17, 0.05), x = ax, y = armY(ax) - 0.1, z = 0.1, r = 0.3, c = W }
	end
	local function newWings(lite)
		local list = {}
		for _, side in ipairs({ 1, -1 }) do
			for _, sp in ipairs(WING_SPEC) do
				if sp.core or lite ~= true then
					local p = L.part({ Size = sp.V, Color = sp.c, Material = sp.mat or SMOOTH, Transparency = 1, Reflectance = sp.gold and 0.25 or 0 })
					list[#list + 1] = { p = p, side = side, sp = sp, S = 1 }
				end
			end
		end
		return list
	end

	local function wingPlace(w, pivot, S, tr)
		local sp = w.sp
		if math.abs(S - w.S) > 0.01 * S then w.S = S w.p.Size = sp.V * S end
		w.p.CFrame = pivot * CFrame.new(w.side * sp.x * S, sp.y * S, sp.z * S) * CFrame.Angles(0, 0, w.side * sp.r)
		if math.abs(w.p.Transparency - tr) > 0.004 then w.p.Transparency = tr end
	end

	local wings = newWings()

	local function setWings(at, open, flap, S, tr, list)
		for _, w in ipairs(list or wings) do
			local sweep = (1 - open) * math.rad(70) + math.rad(15)
			local pivot = at * CFrame.Angles(0, -w.side * sweep, 0) * CFrame.Angles(0, 0, w.side * (flap + (1 - open) * math.rad(-35)))
			wingPlace(w, pivot, S, tr)
		end
	end
	local function wingRoot()
		local t = ch.torso
		if not (t and t.Parent) then return nil end
		return t.CFrame * CFrame.new(0, t.Size.Y * 0.25, t.Size.Z / 2 + 0.08)
	end


	local rig, ribbon = {}, nil
	local rA0, rA1, rS, rSpark
	local function rebind()
		for _, o in ipairs(rig) do pcall(function() o:Destroy() end) end
		rig = {}
		local hrp = ch.hrp
		if not hrp then return end
		local fy = ch.fy or -3

		rA0 = L.new("Attachment", { Position = Vector3.new(0, fy + 0.2, 0.9) }, hrp)
		rA1 = L.new("Attachment", { Position = Vector3.new(0, fy + 0.8, 0.9) }, hrp)

		rS = L.new("Attachment", { Position = Vector3.new(0, fy + 0.5, 0.9) }, hrp)
		rSpark = L.new("ParticleEmitter", { Texture = L.T("star.png") or "", Rate = 10, Enabled = false, Lifetime = NR(0.3, 0.6), Speed = NR(0.2, 0.6), SpreadAngle = Vector2.new(180, 180),
			Size = NS({ K(0, 0), K(0.3, 0.18), K(1, 0) }), Color = CS(W, C1), LightEmission = 1, Rotation = NR(0, 360), RotSpeed = NR(-120, 120) }, rS)
		ribbon = L.new("Trail", { Attachment0 = rA0, Attachment1 = rA1, Texture = L.T("beamb.png") or "", LightEmission = 0.6, Brightness = 2, Lifetime = 0.7,
			FaceCamera = true, Enabled = false, Color = CS({ CK(0, C1), CK(0.33, BLUE), CK(0.66, MINT), CK(1, C2) }), Transparency = NS({ K(0, 1), K(0.15, 0.25), K(0.7, 0.5), K(1, 1) }), WidthScale = NS({ K(0, 0.15), K(0.2, 1), K(1, 0.3) }) }, hrp)
		rig = { rA0, rA1, ribbon, rS, rSpark }
	end
	rebind()

	System.StaffThemes._tagCh = ch
	local tag = System.StaffThemes.headTag(L, "seraph", C1, C2, { c1 = C1, c2 = C2, role = "PASTEL SERAPH" })
	System.StaffThemes._tagCh = nil

	local held = nil
	local function hide(on)
		if on then
			held = held or {}
			for d in pairs(L.bodyParts()) do if not held[d] then held[d] = true d.LocalTransparencyModifier = 1 end end
		elseif held then
			for d in pairs(held) do if d.Parent then pcall(function() d.LocalTransparencyModifier = 0 end) end end
			held = nil
		end
	end
	local function bodyGhost(col, mat)
		if not ch.char then return nil end
		local g = L.ghost(col, mat or NEON, 99, true)
		local list = {}
		for _, p in ipairs(g:GetChildren()) do
			if p:IsA("BasePart") then p.LocalTransparencyModifier = 0 p.Transparency = 1 list[#list + 1] = { p = p, cf = p.CFrame } end
		end
		return list, g
	end
	local function headPos() return (ch.head and ch.head.Parent and ch.head.Position) or (ch.pos + Vector3.new(0, 1.5 * sc(), 0)) end

	local function tempHalo(scale)
		local a, am = L.mesh("disc.mesh", "ring_c.png", C1, 2.4, Vector3.new(scale, 1, scale))
		local b, bm = L.mesh("disc.mesh", "ring_c.png", C2, 2.0, Vector3.new(scale * 1.2, 1, scale * 1.2))
		a.Transparency, b.Transparency = 1, 1
		return { a = a, b = b, set = function(pos, sz, tr, spin)
			am.Scale, bm.Scale = Vector3.new(sz, 1, sz), Vector3.new(sz * 1.2, 1, sz * 1.2)
			a.CFrame = CFrame.new(pos) * CFrame.Angles(0, spin, 0)
			b.CFrame = CFrame.new(pos - Vector3.new(0, 0.03, 0)) * CFrame.Angles(0, -spin * 0.7, 0)
			a.Transparency, b.Transparency = tr, math.min(1, tr + 0.25)
		end }
	end
	local function cloudBall(col, size) return L.part({ Shape = Enum.PartType.Ball, Material = SMOOTH, Color = col or W, Transparency = 1, Size = Vector3.one * size }) end




	local V3n, CFn, ANGn = Vector3.new, CFrame.new, CFrame.Angles
	local function rp(size, col, mat) return L.part({ Size = size, Color = col, Material = mat or SMOOTH, Transparency = 1 }) end
	local function setT(p, v) if math.abs(p.Transparency - v) > 0.004 then p.Transparency = v end end
	local function sm(x) x = c01(x) return x * x * (3 - 2 * x) end
	local function addAll(objs, list) for _, p in ipairs(list) do objs[#objs + 1] = p end end

	local function rPad(o, s, n)
		local tiles, objs, ts = {}, {}, 1.25 * s
		for x = -n, n do
			for z = -n, n do
				local d = math.max(math.abs(x), math.abs(z))


				local hue = (math.atan2(z, x) / (2 * math.pi) + 0.5 + d * 0.11) % 1
				local col = d == 0 and GOLD or Color3.fromHSV(hue, (x + z) % 2 == 0 and 0.5 or 0.38, 1)
				local p = rp(V3n(ts * 0.94, 0.16 * s, ts * 0.94), col, (d == 0 or (x * 7 + z * 3) % 5 == 0) and NEON or SMOOTH)
				tiles[#tiles + 1] = { p = p, base = CFn(o + V3n(x * ts, 0.08 * s, z * ts)), d = d + math.abs(x - z) * 0.04 }
				objs[#objs + 1] = p
			end
		end
		return { objs = objs, set = function(t, tin, tout)
			for _, ti in ipairs(tiles) do
				local u = (t - tin - ti.d * 0.08) / 0.35
				if u > 0 then
					local k, m = L.outBack(c01(u)), sm((t - tout - ti.d * 0.06) / 0.4)
					ti.p.CFrame = ti.base * CFn(0, -0.6 * s * (1 - k) - 0.5 * s * m, 0) * ANGn((1 - k) * math.pi, 0, 0)
					setT(ti.p, math.max(1 - c01(u / 0.35), m))
				end
			end
		end }
	end

	local function rHalo(d, col)
		local p, m = L.mesh("disc.mesh", "ring_c.png", col, 2.4, Vector3.new(d, 1, d))
		p.Transparency = 1
		return { p, m = m, d = d }
	end
	local function rHaloSet(h, cf, d, tr)
		if math.abs(d - h.d) > 0.03 then h.d = d h.m.Scale = V3n(d, 1, d) end
		h[1].CFrame = cf
		setT(h[1], tr)
	end

	local function rSqWave(o, col, r0, r1, dur) L.groundWave(o, "ring_c.png", col, r0, r1, dur, 2) end

	local function rShards(from, floorY, n, s, spd, life)
		local list, objs = {}, {}
		for i = 1, n do
			local p = rp(Vector3.one * rnd(0.18, 0.42) * s, PASTEL[(i - 1) % #PASTEL + 1]:Lerp(W, 0.15), i % 3 == 0 and NEON or SMOOTH)
			local a = rnd(0, 2 * math.pi)
			list[i] = { p = p, pos = from, v = V3n(math.cos(a) * rnd(0.4, 1), rnd(0.7, 1.5), math.sin(a) * rnd(0.4, 1)) * spd * s, rv = V3n(rnd(-7, 7), rnd(-7, 7), rnd(-7, 7)) }
			objs[i] = p
		end
		L.timeline(life, function(t)
			local dt = math.clamp(L.lastDt or 0.016, 0, 0.05)
			for _, c in ipairs(list) do
				c.v -= V3n(0, 26 * dt, 0)
				c.pos += c.v * dt
				if c.pos.Y < floorY + 0.15 then c.pos = V3n(c.pos.X, floorY + 0.15, c.pos.Z) c.v = V3n(c.v.X * 0.6, math.abs(c.v.Y) * 0.42, c.v.Z * 0.6) c.rv *= 0.6 end
				c.p.CFrame = CFn(c.pos) * ANGn(c.rv.X * t, c.rv.Y * t, c.rv.Z * t)
				setT(c.p, math.max(1 - c01(t / 0.08), c01((t - life + 0.6) / 0.6)))
			end
		end, objs)
	end

	local function ghostScan(g, y0, yScan, fade)
		if not g then return end
		for _, gp in ipairs(g) do
			local k = c01((yScan - (gp.cf.Position.Y - y0)) / 0.8)
			setT(gp.p, 1 - 0.8 * k * (1 - fade))
		end
	end
	local function trail2(p, half, col, life)
		local a0 = L.new("Attachment", { Position = V3n(0, half, 0) }, p)
		local a1 = L.new("Attachment", { Position = V3n(0, -half, 0) }, p)
		return L.new("Trail", { Attachment0 = a0, Attachment1 = a1, Texture = L.T("beamb.png") or "", LightEmission = 1, Lifetime = life, FaceCamera = true,
			Color = CS(W, col), Transparency = NS({ K(0, 0.1), K(1, 1) }), WidthScale = NS({ K(0, 1), K(1, 0.1) }) }, p)
	end





	local RSP = { busy = 0 }
	function RSP.sprite(col, objs)
		local sp = newSprite(col)
		for _, e in ipairs(sp.parts) do objs[#objs + 1] = e.p end
		objs[#objs + 1] = sp.a
		return sp
	end
	function RSP.draw(sp, pos, tr, t, spin)
		sp.a.CFrame = CFn(pos)
		sp.bb.Enabled = tr < 0.95
		local z = 0.95 * sc()
		sp.bb.Size = UDim2.new(z, 0, z, 0)
		sp.light.Brightness = tr < 0.95 and 0.6 or 0
		spriteDraw(sp, pos, tr, t, false, spin or 2, z)
	end

	function RSP.ghost(g, cf0, cf, tr)
		if not g then return end
		local m = cf * cf0:Inverse()
		for _, gp in ipairs(g) do gp.p.CFrame = m * gp.cf setT(gp.p, tr) end
	end
	function RSP.burst(pos, s, n)
		for q = 1, n do heartAt(pos + V3n(rnd(-1.2, 1.2), rnd(-0.3, 0.9), rnd(-1.2, 1.2)) * s, rnd(1.2, 2.2), rnd(1.2, 1.8), rnd(0.4, 0.65)) end
		auraP.CFrame = CFn(pos)
		aura:Emit(20)
		petals:Emit(12)
	end
	function RSP.face()
		local h = ch.hrp
		local v = h and h.CFrame.LookVector * V3n(1, 0, 1)
		return (v and v.Magnitude > 0.1) and v.Unit or V3n(0, 0, -1)
	end

	function RSP.disc(d, th, col, mat) return L.part({ Shape = Enum.PartType.Cylinder, Size = V3n(th, d, d), Color = col, Material = mat or SMOOTH, Transparency = 1 }) end
	function RSP.puff(size, col, mat)
		local p = L.part({ Size = size, Color = col, Material = mat or SMOOTH, Transparency = 1 })
		L.new("SpecialMesh", { MeshType = Enum.MeshType.Sphere }, p)
		return p
	end
	function RSP.ring(objs, d, col)
		local h = rHalo(d, col)
		objs[#objs + 1] = h[1]
		return h
	end




	local function shortGift()
		local o, s = L.ground(ch.feet, 3, 8), sc()
		hide(true)
		RSP.busy = os.clock() + 4.4
		local objs = {}
		local BW, BH = 3.4 * s, 3 * s
		local wallC, ribC = C1:Lerp(W, 0.3), C2:Lerp(W, 0.05)
		local fw = RSP.face()
		local rot = CFrame.lookAt(Vector3.zero, fw)
		local base = rp(V3n(BW, 0.2 * s, BW), wallC:Lerp(PLUM, 0.06))
		objs[1] = base
		local walls = {}
		for i = 1, 4 do
			local w = { p = rp(V3n(BW, BH, 0.18 * s), wallC), a = (i - 1) * math.pi / 2, rib = rp(V3n(0.5 * s, BH, 0.05 * s), ribC, NEON), dots = {}, col = PASTEL[(i - 1) % #PASTEL + 1] }
			for d = 1, 3 do w.dots[d] = RSP.disc(0.55 * s, 0.05 * s, W) objs[#objs + 1] = w.dots[d] end
			objs[#objs + 1] = w.p
			objs[#objs + 1] = w.rib
			walls[i] = w
		end
		local DOT = { { -0.95, 0.8 }, { 0.95, 1.6 }, { -0.85, 2.4 } }
		local lid = rp(V3n(BW + 0.3 * s, 0.45 * s, BW + 0.3 * s), wallC:Lerp(W, 0.2))
		local lr = { rp(V3n(BW + 0.34 * s, 0.06 * s, 0.5 * s), ribC, NEON), rp(V3n(0.5 * s, 0.06 * s, BW + 0.34 * s), ribC, NEON) }
		local loops = { RSP.ring(objs, 1.4 * s, ribC), RSP.ring(objs, 1.4 * s, ribC) }
		local knot = RSP.puff(V3n(0.5, 0.45, 0.5) * s, ribC:Lerp(PLUM, 0.15))
		local tails = { rp(V3n(0.3 * s, 0.04 * s, 1.1 * s), ribC, NEON), rp(V3n(0.3 * s, 0.04 * s, 1.1 * s), ribC, NEON) }
		addAll(objs, { lid, lr[1], lr[2], knot, tails[1], tails[2] })
		local sps = { RSP.sprite(GOLD, objs), RSP.sprite(BLUE, objs) }
		local g, gm = bodyGhost(C1:Lerp(W, 0.45))
		objs[#objs + 1] = gm
		local spEnd = {}
		L.timeline(4.4, function(t, once)
			if held and once("late", 0.2) then hide(true) end
			local by = t < 1.2 and 13 * s * (1 - L.outQuad(t / 1.2)) or 0
			if t > 1.2 and t < 1.5 then by = -0.25 * s * math.sin((t - 1.2) / 0.3 * math.pi) end
			by -= 1.2 * s * sm((t - 3.5) / 0.8)
			local swing = t < 1.2 and 0.07 * math.sin(t * 5) * (1 - t / 1.2) or 0
			local box = CFn(o + V3n(0, by, 0)) * rot * ANGn(0, 0, swing)
			local fade = c01((t - 3.6) / 0.7)
			base.CFrame = box * CFn(0, 0.1 * s, 0)
			setT(base, math.max(1 - c01(t / 0.15), fade))
			local fold = (math.pi / 2 + 0.2) * L.outBack(c01((t - 2.1) / 0.5))
			for i, w in ipairs(walls) do
				local wcf = box * ANGn(0, w.a, 0) * CFn(0, 0.2 * s, BW / 2) * ANGn(fold, 0, 0) * CFn(0, BH / 2, 0)
				w.p.CFrame = wcf
				w.p.Color = wallC:Lerp(w.col, c01((t - 2.1) / 0.5))
				setT(w.p, math.max(1 - c01(t / 0.15), fade))
				w.rib.CFrame = wcf * CFn(0, 0, 0.1 * s)
				setT(w.rib, math.max(1 - c01(t / 0.15), c01((t - 1.6) / 0.3)))
				for d, dp in ipairs(w.dots) do
					dp.CFrame = wcf * CFn(DOT[d][1] * s, DOT[d][2] * s - BH / 2, 0.11 * s) * ANGn(0, math.pi / 2, 0)
					setT(dp, math.max(1 - c01(t / 0.15), fade))
				end
			end

			local pk = c01((t - 1.9) / 0.8)
			local lcf = box * CFn(0, 0.2 * s + BH + 0.22 * s + 6 * s * math.sin(pk * math.pi * 0.8), 0) * ANGn(0.6 * pk, pk * 9, 0.3 * pk)
			lid.CFrame = lcf
			setT(lid, math.max(1 - c01(t / 0.15), c01((t - 2.4) / 0.4)))
			lr[1].CFrame, lr[2].CFrame = lcf * CFn(0, 0.24 * s, 0), lcf * CFn(0, 0.24 * s, 0)
			local ribT = math.max(1 - c01(t / 0.15), c01((t - 1.6) / 0.3))
			setT(lr[1], ribT) setT(lr[2], ribT)

			local untie = c01((t - 1.3) / 0.6)
			local top = lcf * CFn(0, 0.3 * s, 0)
			for q, h in ipairs(loops) do
				local sd = q == 1 and -1 or 1
				rHaloSet(h, top * ANGn(0, 0, sd * (0.5 + 0.9 * untie)) * CFn(sd * 0.6 * s, 0.15 * s, 0) * ANGn(math.pi / 2, 0, 0), 1.4 * s * (1 - 0.9 * untie), math.max(1 - c01(t / 0.15), untie))
			end
			knot.CFrame = top * CFn(0, 0.15 * s, 0)
			setT(knot, math.max(1 - c01(t / 0.15), untie))
			for q, tp in ipairs(tails) do
				local sd = q == 1 and -1 or 1
				tp.CFrame = top * ANGn(0, sd * 0.5, 0) * CFn(sd * 0.4 * s * (1 + 3 * untie), -0.1 * s, 0.5 * s) * ANGn(0.5, 0, sd * 0.3)
				setT(tp, math.max(1 - c01(t / 0.15), untie))
			end

			for q, sp in ipairs(sps) do
				local sd = q == 1 and -1 or 1
				local pos
				if t < 1.3 then pos = (box * CFn(sd * (BW / 2 + 0.3 * s), BH + 1.1 * s + 0.15 * s * math.sin(t * 8 + q), 0)).Position
				elseif t < 2.2 then pos = (box * CFn(sd * (BW / 2 + 0.3 * s + 1.6 * s * untie), BH + 1.1 * s + 0.6 * s * untie, 0)).Position spEnd[q] = pos
				else
					local u = t - 2.2
					pos = (spEnd[q] or o) + V3n(sd * 1.2 * math.sin(u * 4) * s, 3 * u * s, sd * 1.2 * (1 - math.cos(u * 4)) * s)
				end
				RSP.draw(sp, pos, math.max(1 - c01(t / 0.2), c01((t - 3) / 0.4)), t, t > 1.3 and t < 2.2 and 8 or 2)
			end
			ghostScan(g, o.Y, t < 2.1 and 0 or (t - 2.1) * 9 * s, c01((t - 2.5) / 0.4))
			if once("land", 1.2) then rSqWave(o, C1, 1 * s, 7 * s, 0.8) end
			if once("pop", 2) then RSP.burst(o + V3n(0, BH, 0), s, 8) end
			if once("show", 2.45) then
				hide(false)
				for q = 1, 6 do local a = q / 6 * 6.283 bloom(L.ground(o + (CFn(Vector3.zero) * ANGn(0, a, 0)).LookVector * BW * 1.1, 2, 4), rnd(0.6, 0.85), 1.8) end
			end
		end, objs, function() hide(false) RSP.busy = 0 end)
	end




	local function shortBook()
		local o, s = L.ground(ch.feet, 3, 8), sc()
		hide(true)
		RSP.busy = os.clock() + 4.4
		local objs = {}
		local CW, CD, CT = 3.4 * s, 4.6 * s, 0.25 * s
		local rot = CFrame.lookAt(Vector3.zero, RSP.face()) * ANGn(0, math.pi / 2, 0)
		local coverC, pageC = C1:Lerp(PLUM, 0.12), W:Lerp(GOLD, 0.12)
		local coverR, coverL = rp(V3n(CW, CT, CD), coverC), rp(V3n(CW, CT, CD), coverC)
		local spine = rp(V3n(0.5 * s, CT * 1.6, CD), GOLD, NEON)
		local emblem = RSP.disc(1.3 * s, 0.05 * s, GOLD, NEON)
		local pages = {}
		for i = 1, 5 do pages[i] = rp(V3n(CW - 0.15 * s, 0.04 * s, CD - 0.25 * s), pageC) end
		addAll(objs, { coverR, coverL, spine, emblem }) addAll(objs, pages)
		local bows = {}
		for i = 1, 4 do bows[i] = RSP.ring(objs, (4.4 - i * 0.6) * s, PASTEL[(i - 1) % #PASTEL + 1]) end
		local clouds = {}
		for c = 1, 2 do for k = 1, 3 do local d = RSP.disc(({ 1.1, 1.5, 1 })[k] * s, 0.08 * s, W) clouds[#clouds + 1] = { p = d, c = c, k = k } objs[#objs + 1] = d end end
		local stars = {}
		for q = 1, 2 do
			local st = { stick = rp(V3n(0.06 * s, 1, 0.06 * s), GOLD), a = rp(V3n(0.6, 0.6, 0.06) * s, GOLD, NEON), b = rp(V3n(0.6, 0.6, 0.06) * s, W:Lerp(GOLD, 0.3), NEON) }
			addAll(objs, { st.stick, st.a, st.b })
			stars[q] = st
		end
		local g, gm = bodyGhost(C2:Lerp(W, 0.45))
		objs[#objs + 1] = gm
		L.timeline(4.4, function(t, once)
			if held and once("late", 0.2) then hide(true) end
			local by = t < 0.7 and 10 * s * (1 - L.inQuad(t / 0.7)) or 0
			if t > 0.7 and t < 0.95 then by = 0.3 * s * math.sin((t - 0.7) / 0.25 * math.pi) end
			by -= 1 * s * sm((t - 3.7) / 0.6)
			local book = CFn(o + V3n(0, by, 0)) * rot * ANGn(0, t < 0.7 and (0.7 - t) * 2 or 0, 0)
			local fade = math.max(1 - c01(t / 0.15), c01((t - 3.6) / 0.6))
			local sy = CT * 1.5 + 0.2 * s
			local spineCF = book * CFn(0, sy, 0)

			local open = math.pi * L.outQuad(c01((t - 0.85) / 0.6))
			coverR.CFrame = book * CFn(CW / 2, CT / 2, 0)
			coverL.CFrame = spineCF * ANGn(0, 0, open) * CFn(CW / 2, 0.15 * s, 0)
			spine.CFrame = book * CFn(0, CT * 0.8, 0)
			emblem.CFrame = coverL.CFrame * CFn(0, 0.15 * s, 0) * ANGn(0, 0, math.pi / 2)
			setT(coverR, fade) setT(coverL, fade) setT(spine, fade) setT(emblem, math.max(fade, c01((open - 2.6) / 0.4)))
			for i, pg in ipairs(pages) do
				local pk = math.pi * L.outQuad(c01((t - 1.3 - (i - 1) * 0.16) / 0.38))
				pg.CFrame = spineCF * ANGn(0, 0, pk) * CFn(CW / 2 - 0.05 * s, -0.04 * s * i, 0) * ANGn(0, 0, -0.25 * math.sin(pk))
				setT(pg, fade)
			end

			local pop = L.outBack(c01((t - 1.6) / 0.55)) * (1 - sm((t - 3.2) / 0.45))
			local spread = book * CFn(0, sy + 0.06 * s, 0)
			for i, h in ipairs(bows) do
				rHaloSet(h, spread * CFn(0, 0, 0.9 * s) * ANGn(0, math.pi / 2, 0) * ANGn(math.pi / 2 * pop, 0, 0), (4.4 - i * 0.6) * s, math.max(1 - c01(pop / 0.2), fade))
			end
			for _, cl in ipairs(clouds) do
				local sd = cl.c == 1 and -1 or 1
				local base = spread * CFn(0, 0, sd * 2 * s) * ANGn(0, math.pi / 2, 0) * ANGn(math.pi / 2 * pop - math.pi / 2, 0, 0)
				local off = ({ -0.6, 0, 0.6 })[cl.k] * s
				cl.p.CFrame = base * CFn(off, 0.55 * s + (cl.k == 2 and 0.3 * s or 0), 0) * ANGn(0, math.pi / 2, 0)
				setT(cl.p, math.max(1 - c01(pop / 0.2), fade))
			end
			for q, st in ipairs(stars) do
				local sd = q == 1 and -1 or 1
				local hgt = (2.4 + 0.5 * q) * s * pop
				local b0 = (spread * CFn(0, 0, sd * 1.1 * s)).Position
				if math.abs(st.stick.Size.Y - math.max(0.05, hgt)) > 0.04 then st.stick.Size = V3n(0.06 * s, math.max(0.05, hgt), 0.06 * s) end
				st.stick.CFrame = CFn(b0 + V3n(0, hgt / 2, 0))
				local top = CFn(b0 + V3n(0, hgt + 0.1 * s, 0)) * rot * ANGn(0, math.pi / 2, t * 2.5 * sd)
				st.a.CFrame, st.b.CFrame = top, top * ANGn(0, 0, math.pi / 4)
				local tr = math.max(1 - c01(pop / 0.2), fade)
				setT(st.stick, tr) setT(st.a, tr) setT(st.b, tr)
			end
			ghostScan(g, o.Y, t < 2.1 and 0 or (t - 2.1) * 9 * s, c01((t - 2.6) / 0.4))
			if once("land", 0.7) then rSqWave(o, C1, 1 * s, 7 * s, 0.8) petals:Emit(6) end
			if once("rise", 2.15) then RSP.burst(o + V3n(0, 1.5 * s, 0), s, 6) end
			if once("show", 2.55) then hide(false) end
			if once("petals", 3.6) then
				auraP.CFrame = CFn(o + V3n(0, 0.6 * s, 0))
				petals:Emit(24)
				for q = 1, 5 do local a = q / 5 * 6.283 bloom(L.ground(o + V3n(math.cos(a), 0, math.sin(a)) * 3 * s, 2, 4), rnd(0.6, 0.85), 1.6) end
			end
		end, objs, function() hide(false) RSP.busy = 0 end)
	end




	local function shortSlide()
		local o, s = L.ground(ch.feet, 3, 8), sc()
		hide(true)
		local objs = {}
		local fw = RSP.face()
		local rt = fw:Cross(Vector3.yAxis).Unit
		local P0, P1, P2 = o - fw * 13 * s + V3n(0, 15 * s, 0), o - fw * 4 * s + V3n(0, 1 * s, 0), o + V3n(0, 0.25 * s, 0)
		local function B(u) return P0 * (1 - u) ^ 2 + P1 * 2 * (1 - u) * u + P2 * u * u end
		local function Bd(u) return (P1 - P0) * 2 * (1 - u) + (P2 - P1) * 2 * u end
		local N, BAND = 22, 0.55 * s
		local HUE = { 0.97, 0.07, 0.15, 0.36, 0.58 }
		local segs = {}
		for i = 1, N do
			local u0, u1 = (i - 1) / N, i / N
			local a, b = B(u0), B(u1)
			local mid, len = (a + b) / 2, (b - a).Magnitude
			local cf = CFrame.lookAt(mid, b)
			for k = 1, 5 do
				local p = rp(V3n(BAND * 0.98, 0.14 * s, len * 1.06), Color3.fromHSV(HUE[k], 0.42, 1), (i + k) % 6 == 0 and NEON or SMOOTH)
				p.CFrame = cf * CFn((k - 3) * BAND, 0, 0)
				segs[#segs + 1] = { p = p, u = u0 }
				objs[#objs + 1] = p
			end
		end
		local topCloud = {}
		for q = 1, 5 do local p = RSP.puff(V3n(rnd(2.4, 3.4), rnd(1.2, 1.6), rnd(2, 2.8)) * s, W) topCloud[q] = { p = p, off = V3n(rnd(-1.6, 1.6), rnd(-0.4, 0.4), rnd(-1.2, 1.2)) * s } objs[#objs + 1] = p end
		local ride = { RSP.puff(V3n(2.2, 0.7, 1.7) * s, W), RSP.puff(V3n(1.4, 0.6, 1.2) * s, C1:Lerp(W, 0.5)), RSP.puff(V3n(1.3, 0.55, 1.1) * s, BLUE:Lerp(W, 0.4)) }
		addAll(objs, ride)
		trail2(ride[1], 0.3 * s, C1, 0.5)
		local tip = RSP.puff(V3n(0.6, 0.6, 0.6) * s, GOLD, NEON)
		objs[#objs + 1] = tip
		local g, gm = bodyGhost(C1:Lerp(W, 0.4))
		objs[#objs + 1] = gm
		local cf0 = CFn(o)
		L.timeline(3.8, function(t, once)
			if held and once("late", 0.2) then hide(true) end
			local build = c01(t / 0.85)
			local gone = c01((t - 2.4) / 1.2)
			for _, sg in ipairs(segs) do setT(sg.p, (sg.u > build or sg.u < gone) and 1 or 0.05) end
			tip.CFrame = CFn(B(math.min(build, 0.999)) + V3n(0, 0.3 * s, 0))
			setT(tip, build >= 1 and 1 or 0.1)
			for _, c in ipairs(topCloud) do
				c.p.CFrame = CFn(P0 + c.off + V3n(0, 0.5 * s + 0.15 * s * math.sin(t * 2), 0))
				setT(c.p, math.max(1 - c01(t / 0.3), c01((t - 3) / 0.6)))
			end

			local u = L.inQuad(c01((t - 0.8) / 1.35)) * 0.7 + 0.3 * c01((t - 0.8) / 1.35)
			local bounce = t > 2.15 and 0.6 * s * math.max(0, math.sin((t - 2.15) / 0.35 * math.pi)) * (t < 2.5 and 1 or 0) or 0
			local pos = t < 0.8 and P0 + V3n(0, 0.4 * s, 0) or B(u) + V3n(0, bounce, 0)
			local d = Bd(math.min(u, 0.99))
			local look = CFrame.lookAt(pos, pos + V3n(d.X, 0, d.Z))
			local rideT = math.max(1 - c01((t - 0.4) / 0.3), c01((t - 2.5) / 0.35))
			ride[1].CFrame = look
			ride[2].CFrame = look * CFn(-0.7 * s, 0.1 * s, 0.3 * s)
			ride[3].CFrame = look * CFn(0.7 * s, 0.08 * s, 0.25 * s)
			for _, p in ipairs(ride) do setT(p, rideT) end
			local gt = math.max(1 - c01((t - 0.4) / 0.3), c01((t - 2.4) / 0.35)) * 0.8 + 0.2
			RSP.ghost(g, cf0, CFn(pos + V3n(0, 0.3 * s, 0)), t < 0.4 and 1 or gt)
			if once("land", 2.15) then
				rSqWave(o, C1, 1 * s, 7 * s, 0.8)
				RSP.burst(o + V3n(0, 1 * s, 0), s, 5)
				for q = 1, 6 do local a = q / 6 * 6.283 bloom(L.ground(o + V3n(math.cos(a), 0, math.sin(a)) * 2.2 * s, 2, 4), rnd(0.55, 0.8), 1.8) end
			end
			if once("show", 2.4) then hide(false) end
		end, objs, function() hide(false) end)
	end




	local function shortBubble()
		local o, s = L.ground(ch.feet, 3, 8), sc()
		hide(true)
		RSP.busy = os.clock() + 4.2
		local objs = {}
		local R = 3.4 * s
		local shell = L.part({ Shape = Enum.PartType.Ball, Size = Vector3.one * R * 2, Color = C1:Lerp(BLUE, 0.5), Material = Enum.Material.ForceField, Transparency = 1 })
		local tint = L.part({ Shape = Enum.PartType.Ball, Size = Vector3.one * R * 1.96, Color = W:Lerp(C1, 0.3), Material = Enum.Material.Glass, Transparency = 1 })
		local shine = RSP.puff(V3n(0.9, 0.5, 0.1) * s, W, NEON)
		addAll(objs, { shell, tint, shine })
		local smalls = {}
		for i = 1, 10 do
			local p = L.part({ Shape = Enum.PartType.Ball, Size = Vector3.one * rnd(0.35, 0.8) * s, Color = PASTEL[(i - 1) % #PASTEL + 1], Material = Enum.Material.ForceField, Transparency = 1 })
			smalls[i] = { p = p, a = rnd(0, 6.3), r = rnd(R + 0.6 * s, R + 1.6 * s), y = rnd(-1.5, 1.5) * s, sp = rnd(0.8, 1.6), v = nil, pos = nil }
			objs[#objs + 1] = p
		end
		local sps = { RSP.sprite(GOLD, objs), RSP.sprite(BLUE, objs) }
		local g, gm = bodyGhost(C1:Lerp(W, 0.45))
		objs[#objs + 1] = gm
		local cf0 = CFn(o)
		local fw = RSP.face()
		local rt = fw:Cross(Vector3.yAxis).Unit
		local popPos
		L.timeline(4.2, function(t, once)
			if held and once("late", 0.2) then hide(true) end
			local down = L.outQuad(c01(t / 1.9))
			local c = o + V3n(0, (R + 0.2 * s) + 12 * s * (1 - down), 0) + rt * 0.6 * s * math.sin(t * 1.6) * (1 - down)
			local wob = (t > 1.95 and t < 2.4) and 0.07 * math.sin((t - 1.95) * 40) or 0
			local popK = c01((t - 2.4) / 0.12)
			local sz = R * 2 * (1 + wob + 0.15 * popK)
			if math.abs(shell.Size.X - sz) > 0.02 then shell.Size = Vector3.one * sz tint.Size = Vector3.one * sz * 0.98 end
			shell.CFrame, tint.CFrame = CFn(c), CFn(c)
			local st = math.max(1 - c01(t / 0.3), popK)
			setT(shell, st * 0.85 + 0.15 * (st > 0.99 and 1 or 0))
			setT(tint, math.max(0.82, st))
			shine.CFrame = CFrame.lookAt(c + (fw * -1 + V3n(0, 0.8, 0) + rt * 0.5).Unit * R * 0.92, c)
			setT(shine, math.max(0.3, st))

			if t < 2.4 then
				RSP.ghost(g, cf0, CFn(c - V3n(0, R * 0.55, 0)) * ANGn(0.25 * math.sin(t), t * 0.8, 0.2), math.max(0.25, 1 - c01((t - 0.2) / 0.4)))
			else
				local fall = L.inQuad(c01((t - 2.4) / 0.35))
				popPos = popPos or c
				RSP.ghost(g, cf0, CFn(o:Lerp(popPos - V3n(0, R * 0.55, 0), 1 - fall)), 0.25 + 0.75 * c01((t - 2.8) / 0.35))
			end

			local dt = math.clamp(L.lastDt or 0.016, 0, 0.05)
			for _, b in ipairs(smalls) do
				if t < 2.4 then
					b.a += dt * b.sp
					b.pos = c + V3n(math.cos(b.a) * b.r, b.y + 0.3 * s * math.sin(t * 2 + b.a), math.sin(b.a) * b.r)
					setT(b.p, math.max(1 - c01((t - 0.3) / 0.4), 0.35))
				else
					b.v = b.v or ((b.pos - c).Unit * rnd(6, 10) * s + V3n(0, 3 * s, 0))
					b.v *= (1 - dt * 1.5)
					b.pos += b.v * dt
					setT(b.p, math.max(0.35, c01((t - 2.9) / 0.8)))
				end
				b.p.CFrame = CFn(b.pos)
			end

			for q, sp in ipairs(sps) do
				local sd = q == 1 and -1 or 1
				local side = c + rt * sd * (R + 0.7 * s)
				local pos
				if t < 1.9 then pos = side + rt * sd * 8 * s * (1 - L.outQuad(c01((t - 0.9) / 1))) + V3n(0, 0.6 * s, 0)
				elseif t < 2.4 then pos = side - rt * sd * 0.5 * s * math.abs(math.sin((t - 1.9) * 12)) + V3n(0, 0.6 * s, 0)
				else pos = side + rt * sd * 2.5 * s * L.outQuad(c01((t - 2.4) / 0.6)) + V3n(0, 0.6 * s + 1.5 * s * c01((t - 2.4) / 1.2), 0) end
				RSP.draw(sp, pos, math.max(1 - c01((t - 0.9) / 0.3), c01((t - 3.5) / 0.5)), t, t > 1.9 and t < 2.6 and 7 or 2)
			end
			if once("pop", 2.42) then RSP.burst(c, s, 10) end
			if once("land", 2.75) then
				rSqWave(o, C1, 1 * s, 6 * s, 0.7)
				for q = 1, 5 do local a = q / 5 * 6.283 bloom(L.ground(o + V3n(math.cos(a), 0, math.sin(a)) * 2 * s, 2, 4), rnd(0.55, 0.8), 1.6) end
			end
			if once("show", 2.95) then hide(false) end
		end, objs, function() hide(false) RSP.busy = 0 end)
	end




	local function shortMusic()
		local o, s = L.ground(ch.feet, 3, 8), sc()
		hide(true)
		local objs = {}
		local BW, BH = 4.8 * s, 1.3 * s
		local rot = CFrame.lookAt(Vector3.zero, RSP.face())
		local boxC = C2:Lerp(W, 0.35)
		local body = rp(V3n(BW, BH, BW * 0.8), boxC)
		local trimT, trimB = rp(V3n(BW + 0.12 * s, 0.14 * s, BW * 0.8 + 0.12 * s), GOLD, NEON), rp(V3n(BW + 0.16 * s, 0.16 * s, BW * 0.8 + 0.16 * s), GOLD)
		local lid = rp(V3n(BW + 0.1 * s, 0.35 * s, BW * 0.8 + 0.1 * s), C1:Lerp(W, 0.3))
		local mirror = rp(V3n(BW * 0.7, 0.04 * s, BW * 0.5), W:Lerp(BLUE, 0.25), Enum.Material.Glass)
		local disc = RSP.disc(3 * s, 0.25 * s, C1:Lerp(W, 0.15))
		local rim = RSP.ring(objs, 3.2 * s, GOLD)
		local feet = {}
		for q = 1, 4 do feet[q] = RSP.puff(V3n(0.6, 0.45, 0.6) * s, GOLD) end
		local teeth = {}
		for q = 1, 8 do teeth[q] = rp(V3n(0.14 * s, 0.08 * s, 0.7 * s), GOLD:Lerp(W, 0.2), NEON) end
		addAll(objs, { body, trimT, trimB, lid, mirror, disc }) addAll(objs, feet) addAll(objs, teeth)
		local notes = {}
		for q = 1, 9 do
			local col = PASTEL[(q - 1) % #PASTEL + 1]
			local n = { head = RSP.puff(V3n(0.5, 0.38, 0.2) * s, col, NEON), stem = rp(V3n(0.07 * s, 0.75 * s, 0.07 * s), col), flag = rp(V3n(0.3 * s, 0.12 * s, 0.06 * s), col), t0 = 0.9 + q * 0.22, a = q * 1.3 }
			addAll(objs, { n.head, n.stem, n.flag })
			notes[q] = n
		end
		local g, gm = bodyGhost(C2:Lerp(W, 0.45))
		objs[#objs + 1] = gm
		local cf0 = CFn(o)
		L.timeline(4.4, function(t, once)
			if held and once("late", 0.2) then hide(true) end
			local up = L.outBack(c01(t / 0.6)) - sm((t - 2.6) / 0.55)
			local by = -BH * 1.2 * (1 - up)
			local box = CFn(o + V3n(0, by, 0)) * rot
			local fade = math.max(1 - c01(t / 0.1), c01((t - 3.4) / 0.6))
			body.CFrame = box * CFn(0, BH / 2, 0)
			trimB.CFrame, trimT.CFrame = box * CFn(0, 0.08 * s, 0), box * CFn(0, BH - 0.05 * s, 0)
			for q, f in ipairs(feet) do f.CFrame = box * CFn((q <= 2 and -1 or 1) * BW * 0.42, 0.05 * s, (q % 2 == 0 and -1 or 1) * BW * 0.32) end

			local la = 1.9 * (L.outBack(c01((t - 0.5) / 0.6)) - sm((t - 2.6) / 0.5))
			local hinge = box * CFn(0, BH, BW * 0.4)
			lid.CFrame = hinge * ANGn(-la, 0, 0) * CFn(0, 0.18 * s, -BW * 0.4)
			mirror.CFrame = lid.CFrame * CFn(0, -0.2 * s, 0)

			local rise = L.outQuad(c01((t - 1) / 0.7))
			local spin = (t - 1) * 5 * c01((t - 1) / 0.4) * (1 - c01((t - 2.8) / 0.4))
			local dTop = box * CFn(0, BH + 0.15 * s, -0.2 * s) * ANGn(0, spin, 0)
			disc.CFrame = dTop * ANGn(0, 0, math.pi / 2)
			rHaloSet(rim, dTop * CFn(0, 0.14 * s, 0), 3.2 * s, math.max(fade, 1 - c01((t - 0.6) / 0.3)))
			for q, th in ipairs(teeth) do
				local pl = (t * 6 + q * 0.7) % 1 < 0.12 and 0.06 * s or 0
				th.CFrame = box * CFn((q - 4.5) * 0.24 * s, BH + 0.05 * s + pl, -BW * 0.32)
				setT(th, fade)
			end
			for _, p in ipairs({ body, trimT, trimB, lid, mirror, disc }) do setT(p, fade) end
			for _, f in ipairs(feet) do setT(f, fade) end
			local dancer = (dTop * CFn(0, -(1 - rise) * 2.2 * s, 0)).Position
			local landed = t > 2.6 and (CFn(o:Lerp(dancer, 1 - sm((t - 2.6) / 0.55)))) or nil
			RSP.ghost(g, cf0, landed or (CFn(dancer) * ANGn(0, spin, 0)), t < 1 and 1 or (0.25 + 0.75 * c01((t - 3.15) / 0.35)))

			for _, n in ipairs(notes) do
				local u = t - n.t0
				local tr = (u < 0 or t > 3.4 + 0.5) and 1 or math.max(1 - c01(u / 0.2), c01((u - 1.4) / 0.5))
				local base = (box * CFn(0, BH + 0.4 * s, -BW * 0.32)).Position
				local p = base + V3n(math.cos(n.a + u * 2) * (0.8 + u) * s, u * 2.4 * s, math.sin(n.a + u * 2) * (0.8 + u) * s)
				local cf = CFn(p) * rot * ANGn(0, 0, 0.3 * math.sin(u * 5))
				n.head.CFrame = cf * ANGn(0, 0, 0.4)
				n.stem.CFrame = cf * CFn(0.2 * s, 0.38 * s, 0)
				n.flag.CFrame = cf * CFn(0.33 * s, 0.68 * s, 0) * ANGn(0, 0, -0.5)
				setT(n.head, tr) setT(n.stem, tr) setT(n.flag, tr)
			end
			if once("open", 0.6) then rSqWave(o, GOLD, 1 * s, 6 * s, 0.7) end
			if once("twirl", 1.7) then RSP.burst(dancer + V3n(0, 2 * s, 0), s, 5) end
			if once("show", 3.2) then
				hide(false)
				for q = 1, 6 do local a = q / 6 * 6.283 bloom(L.ground(o + V3n(math.cos(a), 0, math.sin(a)) * 2.6 * s, 2, 4), rnd(0.55, 0.8), 1.6) end
			end
		end, objs, function() hide(false) end)
	end
	local shorts = { shortGift, shortBook, shortSlide, shortBubble, shortMusic }



















	local function arriveFull()
		local o, s = L.ground(ch.feet, 3, 8), sc()
		local f = L.facing()
		local function ss(x) x = c01(x) return x * x * (3 - 2 * x) end
		local function fyaw(v) return math.atan2(-v.X, -v.Z) end
		local V3, CF, ANG = Vector3.new, CFrame.new, CFrame.Angles
		local PI = math.pi
		local UPR = ANG(0, 0, PI / 2)
		local MARBLE, GRASS, SLATE = Enum.Material.Marble, Enum.Material.Grass, Enum.Material.Slate
		hide(true)
		local DUR = 28
		local S = L.screen(DUR)
		S.style, S.c1, S.c2 = "seraph", C1, C2
		S.tintFn = function(t) return C1, 0.05 * c01(t / 4) * (1 - c01((t - 25) / 3)) end
		local sky = L.worldSky(o, DUR, { dome = Color3.fromRGB(255, 222, 236), atmC = Color3.fromRGB(255, 228, 222), decay = Color3.fromRGB(255, 204, 228),
			den = 0.05, haze = 0.1, glare = 0.1, oa = Color3.fromRGB(246, 224, 238), am = Color3.fromRGB(214, 198, 230), domeA = 0.45 })
		local objs = {}
		local function own(x) objs[#objs + 1] = x return x end
		for _, x in ipairs(sky.objs or {}) do own(x) end
		local function mk(props) return own(L.part(props)) end
		local function tp(p, v) if math.abs(p.Transparency - v) > 0.004 then p.Transparency = v end end

		local BP, BC = {}, {}
		local function mv(p, cf) BP[#BP + 1] = p BC[#BC + 1] = cf end
		local function flush()
			if #BP == 0 then return end
			if not pcall(function() workspace:BulkMoveTo(BP, BC, Enum.BulkMoveMode.FireCFrameChanged) end) then
				for i, p in ipairs(BP) do pcall(function() p.CFrame = BC[i] end) end
			end
			table.clear(BP)
			table.clear(BC)
		end
		local function trailOn(p, half, col, life, w1)
			local a0 = L.new("Attachment", { Position = V3(0, half, 0) }, p)
			local a1 = L.new("Attachment", { Position = V3(0, -half, 0) }, p)
			return L.new("Trail", { Attachment0 = a0, Attachment1 = a1, Texture = L.T("beamb.png") or "", LightEmission = 0.7, Brightness = 1.5, Lifetime = life, FaceCamera = true,
				MinLength = 0, Enabled = false, Color = CS(col, W), Transparency = NS({ K(0, 0.15), K(1, 1) }), WidthScale = NS({ K(0, 1), K(1, w1 or 0.2) }) }, p)
		end
		local function oval(size, col, mat)
			local p = mk({ Size = size, Color = col, Material = mat or SMOOTH, Transparency = 1 })
			L.new("SpecialMesh", { MeshType = Enum.MeshType.Sphere }, p)
			return p
		end
