		local function cherubSet(c, pos, look, t, tr, bow, blow)
			local cf = CFrame.lookAt(pos, V3(look.X, pos.Y, look.Z)) * ANG(-(bow or 0), 0, 0)
			local cs = c.cs
			mv(c.body, cf)
			mv(c.head, cf * CF(0, 0.55 * cs, -0.03 * cs))
			mv(c.hair, cf * CF(0, 0.84 * cs, -0.03 * cs))
			sqHaloSet(c.halo, cf * CF(0, 0.98 * cs, 0) * ANG(0.15, t * 0.8 + c.ph, 0), tr)
			for k, sd in ipairs({ -1, 1 }) do
				mv(c.eyes[k], cf * CF(sd * 0.11 * cs, 0.57 * cs, -0.29 * cs))
				tp(c.eyes[k], tr)
			end
			local arm = c.horn and 1.25 or 0.55 + 0.5 * math.sin(t * 5 + c.ph)
			for k, sd in ipairs({ -1, 1 }) do
				mv(c.arms[k], cf * CF(sd * 0.3 * cs, 0.16 * cs, -0.06 * cs) * ANG(arm + (c.horn and 0 or sd * 0.25 * math.sin(t * 3)), 0, sd * 0.3) * CF(0, -0.18 * cs, 0))
				tp(c.arms[k], tr)
			end
			if c.horn then
				local hcf = cf * CF(0, 0.52 * cs, -0.28 * cs) * ANG(0.2 + 0.35 * (blow or 0), 0, 0) * CF(0, 0, -0.32 * cs)
				mv(c.horn[1], hcf)
				mv(c.horn[2], hcf * CF(0, 0, -0.32 * cs))
				c.bell = (hcf * CF(0, 0, -0.36 * cs)).Position
				c.hdir = hcf.LookVector
				tp(c.horn[1], tr) tp(c.horn[2], tr)
			end
			tp(c.body, tr) tp(c.head, tr) tp(c.hair, tr)
			setWings(cf * CF(0, 0.12 * cs, 0.24 * cs), 1, math.sin(t * 13 + c.ph) * 0.35, 0.75 * cs, math.max(tr, 0.1), c.wl)
		end

