					local p = GD.pd + V3(math.cos(a) * 2.1 * s, 0.6 * s + 0.05 * math.sin(t * 2 + i), math.sin(a) * 2.1 * s)
					local look = p + V3(-math.sin(a), 0, math.cos(a))
					local tr = math.max(1 - ss((t - 4.4 - i * 0.3) / 0.8), melt)
					if tr < 1 or not sw.hid then
						setGroup(sw.parts, CFrame.lookAt(p, look) * ANG(0, 0, 0.05 * math.sin(t * 1.5 + i)), tr)
						sw.hid = tr >= 1 and t > 5
					end
				end
			end

			GA.fdt = fdt
			for _, it in ipairs(GA.items) do
