					if k < 1 or melt > 0 or it.bob or it.anim or it.st == 0 then
						local cur = it.base * CF(0, -(1 - k) * it.h - it.h * 1.1 * melt, 0)
						if it.bob then cur = cur * it.bob(t) end
						it.cur = cur
						local tr = math.max(1 - c01((t - it.t0) / 0.15), melt)
						setGroup(it.parts, cur, tr)
						if it.anim then it.anim(it, t, tr) end
						if k >= 1 and melt <= 0 then it.st = 1 end
						if melt >= 1 then it.st = 2 end
					end
					if it.h > 1 and not it.popped and t >= it.t0 + 0.3 then it.popped = true pop(it.base.Position + V3(0, 0.5 * s, 0), 2, 5, 0) end
