			end
			for _, lp in ipairs(GA.lamps) do lp.Brightness = (1.2 + 0.3 * math.sin(t * 2.4)) * ss((t - 4) / 1) * (1 - melt) end
			GA.ff.Rate = 30 * env
			for i, b in ipairs(GA.flies) do
				local tr = math.max(1 - ss((t - 3 - i * 0.12) / 0.6), melt)
