					local p, q = at(t), at(t + 0.1)
					local cf = CFrame.lookAt(p, (q - p).Magnitude > 0.001 and q or p + tc)
					mv(b.body, cf)
					tp(b.body, tr)
					local fl = 0.2 + 1.1 * math.abs(math.sin(t * 16 + b.ph))
					for _, w in ipairs(b.w) do
						mv(w.p, cf * ANG(0, 0, w.sd * fl) * CF(w.sd * 0.22 * s, 0, 0))
						tp(w.p, tr)
