					local a, d = rnd(0, 2 * PI), rnd(13.5, 26) * s
					b.from, b.t, b.life, b.sz = o + V3(math.cos(a) * d, rnd(0.3, 1.2), math.sin(a) * d), 0, rnd(3.5, 5.5), rnd(0.6, 1.5) * s
					if math.abs(b.p.Size.X - b.sz) > 0.03 then b.p.Size = Vector3.one * b.sz end
				end
				if b.t >= 0 and b.from then
