					local top = bl.anchor + V3(0.4 * math.sin(t * 1.3 + i), 3.4 * s * ba + 0.15 * math.sin(t * 2 + i), 0.4 * math.cos(t * 1.1 + i))
					mv(bl.a, CF(top))
					bl.hg.GroupTransparency = 1 - ba
					local mid = (top + bl.anchor) / 2
					local len = (top - bl.anchor).Magnitude
					if math.abs(bl.str.Size.Y - len) > 0.05 then bl.str.Size = V3(0.04, math.max(0.05, len), 0.04) end
					mv(bl.str, CFrame.lookAt(mid, top) * ANG(PI / 2, 0, 0))
					tp(bl.str, 1 - 0.7 * ba)
