				mv(SH.mc1, CF(GB.Position + V3(0, 0.06, 0)) * ANG(0, spin, 0))
				mv(SH.mc2, CF(GB.Position + V3(0, 0.08, 0)) * ANG(0, -spin * 1.4, 0))
				local mca = c01((t - 9.2) / 0.5) * (1 - melt)
				tp(SH.mc1, 1 - 0.85 * mca)
