				SH.halo.set(hp, 10 * s + (2.3 * s - 10 * s) * hk, 1 - 0.85 * ss((t - 8) / 3) * (1 - c01((t - 24.2) / 0.5)), t * 0.3)
			end
			if once("crown", 24.2) then pop(headPos() + V3(0, 1.1 * s, 0), 3, 26, 10) end


			for _, pc in ipairs(GT.pcs) do
