						local k = ss((t - pc.t0) / 1.1)
						if k < 1 or melt > 0 or not pc.settled then
							setGroup(pc.parts, pc.at * CF(0, -(1 - k) * (HD + 0.5 * s) + 4 * s * melt, 0), math.max(1 - c01(k / 0.2), melt))
							pc.settled = k >= 1
							if melt >= 1 then pc.gone = true end
