			if once("keystone", 14.3) then S:shake(0.04, 0.2) L.groundWave(GB.Position, "ring_c.png", GOLD, 1, 14 * s, 0.9, 2) end

			local tug = 0.09 * math.sin(c01((t - 15.6) / 0.35) * PI) + 0.11 * math.sin(c01((t - 16.5) / 0.35) * PI)
			st.open = tug + math.rad(108) * L.outBack(c01((t - 17.6) / 1.4))
			local dfade = math.max(1 - ss((t - 13.9) / 0.9), ss((t - 23.6) / 1.6))
			for _, dr in ipairs(doors) do
