				end
				PT.light.Brightness = 2 * pa
				PT.swirl.Rate = 5 * pa
				PT.cloud.Rate = 6 * pa
				local ok = lk * (1 - ss((t - 23.4) / 2))
				PT.rays.Rate = 30 * ok
				PT.pet.Rate = 14 * ok
				for i, fb in ipairs(GT.fans) do
