			do
				local vk = c01((t - 14.4) / 1.4)
				for _, v in ipairs(GT.vines) do
					local n = #v.beams
					for q, b in ipairs(v.beams) do
						local w = 0.22 * s * c01(vk * n - (q - 1)) * (1 - melt)
						if math.abs(b.Width0 - w) > 0.005 then b.Width0, b.Width1 = w, w end
					end
				end
				for _, r in ipairs(GT.roses) do
