				GT.emB.Enabled = ek > 0 and melt < 1
				if ek > 0 then
					local esz = 3.4 * s * L.outBack(ek) * (1 + 0.05 * math.sin(t * 3)) * (1 - melt)
					GT.emB.Size = UDim2.new(esz, 0, esz, 0)
					GT.emH.GroupTransparency = 1 - c01(ek / 0.3) + melt
					GT.emH.Rotation = 8 * math.sin(t * 1.6)
