					for _, sd in ipairs({ -1, 1 }) do bloom(q + RT * sd * 1.6 * s + V3(0, 0.3 * s, 0), 0.8, 8 - n * 0.3) end
				end
			end

			for i, sp in ipairs(flyers) do
				local dr = doors[i]
				local hf = handle(dr, doorCF(dr, 0)) + tc * 1.1 * s + V3(0, 0.2 * s, 0)
				local orbR, a0 = MCD / 2, i * PI
				local function orbit(u) local a = a0 + u * PI * 2 return GB.Position + V3(math.cos(a) * orbR, 0.5 * s, math.sin(a) * orbR) end
				local pos
				if t > 7 and t < 9.2 then
					local k = c01((t - 7) / 2.2)
					pos = (G + V3(math.cos(a0) * 10, CY, math.sin(a0) * 10)):Lerp(orbit(0), L.outQuad(k)) + V3(0, 2 * s * math.sin(k * PI), 0)
				elseif t >= 9.2 and t < 11 then
