					local pull = L.outQuad(c01((t - 17.5) / 1.4))
					local hNow = handle(dr, doorCF(dr, st.open))
					pos = hf:Lerp(hNow + tc * 1.4 * s + RT * dr.sd * 0.6 * s, pull) + tc * lean * 0.3 * s + V3(0, 0.18 * s * math.sin(t * 3 + i), 0)
				elseif t >= 19.2 then
					local wait = o + RT * dr.sd * 1.7 * s + V3(0, 2.4 * s + 0.25 * math.sin(t * 3 + i), 0)
					pos = (sp.last or wait):Lerp(wait, c01(fdt * 4))
				end
				sp.bb.Enabled = pos ~= nil and t < 22.4
				sp.tr.Enabled = t > 7 and t < 11.8
				sp.e.Rate = (t > 7 and t < 11.8) and 18 or 0
				if pos then sp.last = pos mv(sp.a, CF(pos)) sp.rA.WorldPosition = pos end
				if sp.last then spriteDraw(sp, sp.last, (pos ~= nil and t < 22.4) and 0 or 1, t, false, 3, 0.95 * s) end
				sp.rb.Transparency = NS(1 - 0.85 * ss((t - 15) / 0.3) * (1 - ss((t - 19) / 0.3)))
			end

			if once("ghost", 18.6) then
				local g, gm2 = bodyGhost(C1:Lerp(W, 0.6), Enum.Material.ForceField)
				GL.ghost = g
				if gm2 then own(gm2) end
			end
			local gliding = GL.ghost ~= nil and t < 22.2
			GL.feat.Rate, GL.spk.Rate = gliding and 10 or 0, gliding and 25 or 0
			if GL.ghost and t < 22.6 then
				local k = ss((t - 18.7) / 3.3)
				local off = (GL.from - o) * (1 - k) + V3(0, (1 * s + 0.25 * s * math.sin(t * 2.2)) * (1 - k), 0)
				GL.pos = o + off
				local M = glide(off, 1 - ss((t - 21.4) / 0.7))
				for _, gp2 in ipairs(GL.ghost) do
					mv(gp2.p, M * gp2.cf)
					tp(gp2.p, 1 - 0.75 * ss((t - 18.6) / 0.8) * (1 - c01((t - 22.1) / 0.4)))
				end
				local root = wingRoot()
				if root then
					setWings(M * root, 1, math.sin(t * 2.6) * 0.14, 2.2 * s, 0.1 + 0.9 * math.max(1 - ss((t - 18.8) / 0.8), c01((t - 22.1) / 0.4)), GL.wl)
					mv(GL.fp, M * root)
				end
			end



			for i, c in ipairs(cherubs) do
				local side = i <= 3 and 1 or 2
				local j = (i - 1) % 3 + 1
				local a = (i - 1) / 8 * PI * 2
				local goal, look, bow, blow = nil, GB.Position, 0, 0
				local R0 = MCD / 2 + 2 * s
				if t < 7 then
					local k = ss((t - 3 - i * 0.12) / 3.6)
					local orbitP = GB.Position + V3(math.cos(a + t * 0.6) * R0, 3 * s, math.sin(a + t * 0.6) * R0)
					goal = (G + V3(math.cos(a) * 45, 16, math.sin(a) * 45)):Lerp(orbitP, k)
				elseif t < 11 then
					local aa = a + t * 0.6
					goal = GB.Position + V3(math.cos(aa) * R0, (2.6 + 0.7 * math.abs(math.sin(t * 4 + i))) * s, math.sin(aa) * R0)
				elseif c.horn and t < 24.4 then
					local sd = i == 7 and -1 or 1
					goal = GB * V3(sd * (XC + 2.4 * s), CH + 0.6 * s + 0.2 * s * math.sin(t * 2.4 + i), -0.9 * s)
					look = goal + tc
					for _, bt in ipairs({ 17.75, 18.3, 18.85 }) do blow = math.max(blow, math.sin(c01((t - bt) / 0.45) * PI)) end
				elseif t < 15 then
					local sd = i % 2 == 0 and 1 or -1
					local h = math.min(CH + 2 * s, (t - 11) / 3.4 * (CH + 2 * s))
					goal = GB * V3(sd * (XC + 2.8 * s), math.max(1.5 * s, h - (j - 1) * 1.8 * s), -1.6 * s - (j - 1) * 0.6 * s) + V3(0, 0.3 * s * math.sin(t * 3 + i), 0)
				elseif t < 19.2 then
					local sp = flyers[side]
					local dr = doors[side]
					local sp0 = sp.last or G
					local back = sp0 - dr.hA.WorldPosition
					back = back.Magnitude > 0.01 and back.Unit or tc
					goal = sp0 + back * j * 1.2 * s + V3(0, -0.2 * s, 0)
					look = dr.hA.WorldPosition
				elseif t < 22.2 then
					local aa = a + t * 0.9
					goal = GL.pos + V3(math.cos(aa) * 3.2 * s, (1.8 + 0.4 * math.sin(t * 3 + i)) * s, math.sin(aa) * 3.2 * s)
					look = GL.pos
				elseif t < 24.4 then
					goal = o + V3(math.cos(a) * 4 * s, 1.8 * s, math.sin(a) * 4 * s)
					look = o
					bow = 0.55 * math.sin(c01((t - 22.6) / 1.4) * PI)
				else
					local k = ss((t - 24.4 - i * 0.08) / 3)
					local aa = a + k * 2
					goal = o + V3(math.cos(aa) * (4 * s + k * 8), 1.8 * s + k * 24, math.sin(aa) * (4 * s + k * 8))
					look = o
				end
				if not c.pos or (goal - c.pos).Magnitude > 60 then c.pos = goal end
				c.pos = c.pos:Lerp(goal, c01(fdt * (t < 7 and 30 or 6)))
				local tr = math.max(1 - ss((t - 3 - i * 0.12) / 0.6), ss((t - 26.2) / 1.2))
				cherubSet(c, c.pos, look, t, tr, bow, blow)
				c.tr.Enabled = (t > 3 and t < 7) or t > 24.4
				c.pet.Rate = (not c.horn and t > 17.8 and t < 22.4 and tr < 1) and 6 or 0
			end
			for _, bt in ipairs({ 17.75, 18.3, 18.85 }) do
				if once("horn" .. bt, bt + 0.1) then
					for i = 7, 8 do
						local c = cherubs[i]
						if c.bell then
							chime(c.bell, c.hdir, 4 * s)
							FX.noteP.CFrame = CFrame.lookAt(c.bell, c.bell + c.hdir)
							FX.note:Emit(10)
						end
					end
				end
			end

			for i, d in ipairs(doves) do
				local tr = 1 - ss((t - 1 - i * 0.1) / 0.8)
				local pos, look
				local sw0 = 17.9 + i * 0.06
				if t < sw0 then
					local a = d.a + t * 0.45
					pos = G + V3(math.cos(a) * d.r, d.y + math.sin(t * 1.3 + i), math.sin(a) * d.r)
					look = pos + V3(-math.sin(a), 0, math.cos(a))
				else
					local k = c01((t - sw0) / 2.6)
					local a = d.a + sw0 * 0.45
					local p0 = G + V3(math.cos(a) * d.r, d.y, math.sin(a) * d.r)
					local p1 = GB * V3((i - 8.5) * 0.35 * s, DH * 0.5, 0)
					local p2 = o + tc * 10 + V3(0, 18, 0) + RT * (i - 8.5) * 1.5
					local q0, q1 = p0:Lerp(p1, k), p1:Lerp(p2, k)
					pos = q0:Lerp(q1, k)
					look = pos + (q1 - q0)
					tr = math.max(tr, ss((k - 0.75) / 0.25))
				end
				if (look - pos).Magnitude < 0.01 then look = pos + tc end
				if tr < 1 or not d.hid then
					doveSet(d, CFrame.lookAt(pos, look), 0.6 * math.sin(t * 12 + i * 2), tr)
					d.hid = tr >= 1 and t > 3
				end
			end

			if once("land", 22.1) then
				hide(false)
				L.groundWave(o, "ring_c.png", C1, 1, 18 * s, 1.2, 1.8)
				L.groundWave(o, "ring_c.png", GOLD, 1, 10 * s, 0.8, 2)
				pop(o + V3(0, 1.5 * s, 0), 8, 40, 20)
				featherP.CFrame = CF(o + V3(0, 2 * s, 0))
				feathers:Emit(20)
				for _ = 1, 8 do heartAt(o + V3(rnd(-3, 3), rnd(0.5, 3), rnd(-3, 3)) * s, 2.2, 2.6, rnd(0.5, 0.9)) end
			end
			for ring = 1, 4 do
				if once("wave" .. ring, 22.2 + ring * 0.35) then
					local n = 4 + ring * 3
					for jj = 1, n do
						local aa = jj / n * 2 * PI + ring
						bloom(o + V3(math.cos(aa), 0, math.sin(aa)) * ring * 2.8 * s + V3(0, 0.3 * s, 0), 0.9 + ring * 0.1, 4.5 - ring * 0.4)
					end
				end
			end
			if once("card", 23.4) then S:title(L.name(), C1, C2) end
			if once("melt", 23.6) then PT.pet:Emit(60) pop(GB * V3(0, DH * 0.6, 0), 12, 30, 60) end
			for n = 1, 5 do
				if once("meltpet" .. n, 24 + n * 0.5) then pop(o + V3(rnd(-10, 10), 1, rnd(-10, 10)) * s, 0, 0, 30) end
			end
			flush()
		end, objs, function()
			hide(false)
			sky.release()
			for _, x in pairs(GR) do pcall(function() x:Destroy() end) end
		end)
	end






	local deadHalo = false
	local function death(preview)
		if not ch.char then return end
		local s = sc()
		local pos = L.ground(ch.feet or ch.pos, 3, 8)
		local gone = {}
		local g, gm = bodyGhost(C1:Lerp(W, 0.55))
		local wl = newWings()
		local halo = rHalo(1.6 * s, GOLD)
		local objs = { gm }
		addAll(objs, halo)
		for _, w in ipairs(wl) do objs[#objs + 1] = w.p end
		local burstP = L.part({ Size = V3n(2, 4, 1.2) })
		local bPet = L.pe(burstP, { Texture = L.T("petal.png"), Shape = Enum.ParticleEmitterShape.Box, Lifetime = NR(2.5, 4), Speed = NR(1, 3), SpreadAngle = Vector2.new(180, 180),
			Acceleration = V3n(0, 1.6, 0), Drag = 0.6, Size = NS({ K(0, 0.35), K(1, 0.2) }), Color = CS(C1, C2), Rotation = NR(0, 360), RotSpeed = NR(-90, 90), LightEmission = 0.3 })
		objs[#objs + 1] = burstP
		local HEART = { ".XX.XX.", "XXXXXXX", "XXXXXXX", ".XXXXX.", "..XXX..", "...X..." }
		local vox = {}
		for row, line in ipairs(HEART) do
			for col = 1, 7 do
				if line:sub(col, col) == "X" then
					local p = rp(Vector3.one * 0.34 * s, (row + col) % 3 == 0 and W:Lerp(C1, 0.3) or C1:Lerp(C2, (col - 1) / 6), NEON)
					vox[#vox + 1] = { p = p, gx = (col - 4) * 0.36 * s, gy = (3.5 - row) * 0.36 * s, d = rnd(0, 0.5) }
					objs[#objs + 1] = p
				end
			end
		end
		local core = vox[math.floor(#vox / 2)].p
		local hlt = L.new("PointLight", { Color = C1, Range = 14, Brightness = 0, Shadows = false }, core)
		local htr = trail2(core, 0.5 * s, C1, 0.8)
		htr.Enabled = false
		local root0 = wingRoot() or CFn(pos + V3n(0, 2.2 * s, 0))
		local headY = headPos().Y - pos.Y
		local center = pos + V3n(0, headY + 2.4 * s, 0)
		local cam = workspace.CurrentCamera
		local cp = cam and cam.CFrame.Position or center + V3n(0, 0, 10)
		local hcf = CFrame.lookAt(center, V3n(cp.X, center.Y, cp.Z))
		for i, v in ipairs(vox) do
			local gp = g and g[(i - 1) % #g + 1]
			v.from = (gp and gp.cf.Position or pos + V3n(0, headY * 0.5, 0)) + V3n(rnd(-0.3, 0.3), rnd(-0.3, 0.3), rnd(-0.3, 0.3))
		end
		deadHalo = true
		L.timeline(8, function(t, once)
			if once("hide", 0) then for d in pairs(L.bodyParts()) do gone[d] = true d.LocalTransparencyModifier = 1 end end
			local lift = 2.2 * s * L.outQuad(c01(t / 2.2))
			if g then
				local gt = t < 2 and 0.2 + 0.8 * (1 - c01(t / 0.4)) or 0.2 + 0.8 * c01((t - 2) / 0.8)
				for _, gp in ipairs(g) do gp.p.CFrame = gp.cf + V3n(0, lift, 0) setT(gp.p, gt) end
			end
			if t < 3.5 then
				local open = L.outBack(c01((t - 0.3) / 0.9))
				local flap = math.sin(t * 2.4) * 0.12 + 0.5 * sm((t - 2.2) / 0.6)
				local sweep = (1 - open) * math.rad(70) + math.rad(10)
				local trW = math.max(1 - c01((t - 0.3) / 0.4), c01((t - 2.5) / 0.8))
				for _, w in ipairs(wl) do
					local pivot = (root0 + V3n(0, lift, 0)) * ANGn(0, -w.side * sweep, 0) * ANGn(0, 0, w.side * (flap - (1 - open) * 0.6))
					wingPlace(w, pivot, 2.6 * s, trW)
				end
			end
			local beat = math.max(0, math.sin((t - 3.4) * math.pi * 2.4)) ^ 6 * c01((t - 3.4) / 0.05) * (1 - c01((t - 4.5) / 0.1))
			local rise = c01((t - 4.6) / 2.4) ^ 2 * 16 * s
			local hc = hcf * CFn(0, rise, 0) * ANGn(0, 0.25 * math.sin(t * 2), 0)
			local vt = c01((t - 6.2) / 1.2)
			for _, v in ipairs(vox) do
				local u = c01((t - 2.1 - v.d) / 0.9)
				if u > 0 then
					local tg = hc * CFn(v.gx * (1 + 0.18 * beat), v.gy * (1 + 0.18 * beat), 0)
					local p = (v.from + V3n(0, lift, 0)):Lerp(tg.Position, sm(u)) + V3n(0, math.sin(u * math.pi) * 1.2 * s, 0)
					v.p.CFrame = (u < 1 and CFn(p) * ANGn(u * 6, u * 4, 0)) or tg
					setT(v.p, math.max(1 - c01(u / 0.15), vt))
				end
			end
			hlt.Brightness = c01((t - 2.8) / 0.5) * (2 + 3 * beat) * (1 - vt)
			local hY = t < 2.6 and (pos + V3n(0, headY + 0.9 * s + lift, 0)) or (pos + V3n(0, headY + 0.9 * s + lift, 0)):Lerp((hc * CFn(0, 1.7 * s, 0)).Position, sm((t - 2.6) / 0.8))
			rHaloSet(halo, CFn(hY) * ANGn(0.15, t * 1.5, 0), (1.6 + 0.6 * sm((t - 2.6) / 0.8)) * s, math.max(1 - c01((t - 0.2) / 0.4), vt))
			if once("burst", 2) then
				burstP.CFrame = CFn(pos + V3n(0, 2.6 * s + lift, 0))
				bPet:Emit(50)
				featherP.CFrame = burstP.CFrame
				feathers:Emit(30)
				for i = 1, 3 do heartAt(pos + V3n(rnd(-1.5, 1.5), rnd(2, 4), rnd(-1.5, 1.5)) * s, 3, 3, 0.6) end
			end
			if once("rise", 4.6) then
				htr.Enabled = true
				rSqWave(pos, GOLD, 1 * s, 11 * s, 1.6)
				for i = 1, 8 do local a = i / 8 * 6.283 bloom(L.ground(pos + V3n(math.cos(a), 0, math.sin(a)) * 2.6 * s, 3, 6), 0.8, 7) end
			end
		end, objs, function()
			deadHalo = false
			if preview then for d in pairs(gone) do if d.Parent then pcall(function() d.LocalTransparencyModifier = 0 end) end end end
		end)

		local R1, R2 = rHalo(2.6 * s, GOLD), rHalo(1.8 * s, C1:Lerp(W, 0.3))
		local rem = {}
		addAll(rem, R1) addAll(rem, R2)
		L.fx(10, function(k, t)
			local a = c01((t - 5) / 0.6) * (1 - c01((k - 0.85) / 0.15))
			local y = 0.3 + 0.06 * math.sin(t * 2)
			rHaloSet(R1, CFn(pos + V3n(0, y, 0)) * ANGn(0, t * 0.3, 0), 2.6 * s, 1 - 0.9 * a)
			rHaloSet(R2, CFn(pos + V3n(0, y + 0.05, 0)) * ANGn(0, -t * 0.5, 0), 1.8 * s, 1 - 0.8 * a)
		end, rem)
	end





	local GD = { prints = {}, pi = 0, blades = {}, bi = 0, ring = {}, flies = {}, travel = 0, side = 1, patchT = 1, gustCD = 0 }
	function GD.oval(size, col, mat)
		local p = L.part({ Size = size, Color = col, Material = mat or SMOOTH, Transparency = 1 })
		L.new("SpecialMesh", { MeshType = Enum.MeshType.Sphere }, p)
		return p
	end
	GD.sparkP = L.part({ Size = Vector3.new(0.6, 0.6, 0.6) })
	GD.spark = L.pe(GD.sparkP, { Texture = L.T("star.png"), Rate = 0, Lifetime = NR(0.4, 0.8), Speed = NR(0.6, 1.6), SpreadAngle = Vector2.new(180, 180),
		Size = NS({ K(0, 0), K(0.3, 0.22), K(1, 0) }), Color = CS(GOLD, W), LightEmission = 1, Brightness = 2 })
	function GD.sparkAt(p, n) GD.sparkP.CFrame = CFrame.new(p) GD.spark:Emit(n or 3) end
	GD.gustP = L.part({ Size = Vector3.new(1, 1.5, 0.4) })
	GD.gust = L.pe(GD.gustP, { Texture = L.T("petal.png"), Rate = 0, EmissionDirection = Enum.NormalId.Front, Lifetime = NR(0.8, 1.4), Speed = NR(9, 15), Drag = 3,
		SpreadAngle = Vector2.new(30, 30), Acceleration = Vector3.new(0, -1, 0), Size = NS({ K(0, 0.3), K(1, 0.18) }), Color = CS(C1, C2), Rotation = NR(0, 360),
		RotSpeed = NR(-200, 200), Transparency = NS({ K(0, 0), K(0.7, 0.2), K(1, 1) }), LightEmission = 0.2 })
	for i = 1, 12 do GD.prints[i] = { p = GD.oval(Vector3.new(0.5, 0.04, 0.7), i % 2 == 0 and BLUE or C1:Lerp(W, 0.2), NEON), t = 99 } end
	local GRASS = { Color3.fromRGB(150, 214, 160), Color3.fromRGB(176, 230, 170), Color3.fromRGB(130, 204, 178) }
	for i = 1, 60 do GD.blades[i] = { p = L.part({ Size = Vector3.new(0.08, 0.6, 0.03), Color = GRASS[(i - 1) % 3 + 1], Material = SMOOTH, Transparency = 1 }), t = 99, life = 1, h = 0.6, ph = 0 } end
	for i = 1, 10 do GD.ring[i] = GD.oval(Vector3.new(0.32, 0.05, 0.5), PASTEL[(i - 1) % #PASTEL + 1]:Lerp(W, 0.15)) end
	for i = 1, 3 do
		local col = PASTEL[(i - 1) % #PASTEL + 1]
		local bf = { ph = rnd(0, 6), a = rnd(0, 6.3), mode = "fly", t = rnd(2, 5), w = {} }
		bf.body = L.part({ Size = Vector3.new(0.08, 0.08, 0.4), Color = PLUM, Material = SMOOTH, Transparency = 1 })
		for q = 1, 4 do
			local upper = q % 2 == 1
			bf.w[q] = L.part({ Size = upper and Vector3.new(0.36, 0.02, 0.3) or Vector3.new(0.26, 0.02, 0.22), Color = upper and col or col:Lerp(W, 0.45), Material = upper and SMOOTH or NEON, Transparency = 1 })
		end
		GD.flies[i] = bf
	end
	function GD.openFlower(near, maxD)
		local best, bd
		for _, fl in ipairs(flowers) do
			if fl.t > 0.8 and fl.t < fl.life - 2 and not fl.taken then
				local d = (fl.core.Position - near).Magnitude
				if d < maxD and (not bd or d < bd) then best, bd = fl, d end
			end
		end
		return best
	end
	function GD.tuft(pos, s, life)
		for q = 1, 3 do
			GD.bi = GD.bi % #GD.blades + 1
			local b = GD.blades[GD.bi]
			local h = rnd(0.45, 0.8) * s
			if math.abs(b.p.Size.Y - h) > 0.03 then b.p.Size = Vector3.new(0.08 * s, h, 0.03 * s) end
			b.t, b.life, b.h, b.ph = 0, life, h, rnd(0, 6)
			b.base = CFrame.new(pos) * CFrame.Angles(0, rnd(0, 6.3), 0) * CFrame.Angles((q - 2) * 0.3 + rnd(-0.1, 0.1), 0, 0)
		end
	end
	function GD.step(dt, s, age, on, run, still, hidden, air, swim)
		local feet = ch.feet or ch.pos
		local g0 = L.ground(feet, 2, 4)

		local fr = (hidden or air or swim) and 1 or (0.45 - 0.3 * c01((still - 1) / 2))
		local rr = (1.5 + 0.4 * c01((still - 1) / 2)) * s
		for i, p in ipairs(GD.ring) do
			local a = age * 0.5 + i / #GD.ring * 6.283
			if math.abs(p.Size.Z - 0.5 * s) > 0.02 then p.Size = Vector3.new(0.32, 0.05, 0.5) * s end
			p.CFrame = CFrame.new(g0 + Vector3.new(math.cos(a) * rr, 0.1 + 0.04 * math.sin(age * 3 + i), math.sin(a) * rr)) * CFrame.Angles(0, -a, 0.15)
			setT(p, fr)
		end

		if on and not air and not swim and not hidden and GD.last then
			GD.travel += ((ch.pos - GD.last) * Vector3.new(1, 0, 1)).Magnitude
			if GD.travel > 1.6 * s then
				GD.travel, GD.side = 0, -GD.side
				local dir = ch.vel.Magnitude > 0.1 and ch.vel.Unit or Vector3.zAxis
				GD.pi = GD.pi % #GD.prints + 1
				local pr = GD.prints[GD.pi]
				local gp = L.ground(feet + dir:Cross(Vector3.yAxis) * GD.side * 0.35 * s, 2, 4) + Vector3.new(0, 0.06, 0)
				pr.t, pr.cf = 0, CFrame.lookAt(gp, gp + dir)
				if math.abs(pr.p.Size.Z - 0.7 * s) > 0.02 then pr.p.Size = Vector3.new(0.5, 0.04, 0.7) * s end
			end
		end
		GD.last = ch.pos
		for _, pr in ipairs(GD.prints) do
			if pr.t < 1.6 then pr.t += dt pr.p.CFrame = pr.cf setT(pr.p, 0.25 + 0.75 * (pr.t / 1.6))
			elseif pr.p.Transparency < 1 then pr.p.Transparency = 1 end
		end

		GD.patchT -= dt
		if not on and not hidden and not swim and not air and still > 1.5 and GD.patchT <= 0 then
			GD.patchT = rnd(1, 1.8)
			local a, d = rnd(0, 6.3), rnd(2.5, 7) * s
			local c = feet + Vector3.new(math.cos(a) * d, 0, math.sin(a) * d)
			for q = 1, math.random(3, 5) do local b, r = rnd(0, 6.3), rnd(0.2, 0.9) * s bloom(L.ground(c + Vector3.new(math.cos(b) * r, 0, math.sin(b) * r), 3, 6), rnd(0.55, 0.95), rnd(4, 6)) end
			for q = 1, 3 do local b, r = rnd(0, 6.3), rnd(0.5, 1.3) * s GD.tuft(L.ground(c + Vector3.new(math.cos(b) * r, 0, math.sin(b) * r), 3, 6), s, rnd(4.5, 6.5)) end
		end
		for _, b in ipairs(GD.blades) do
			if b.t < b.life then
				b.t += dt
				local k = b.t / b.life
				local rise = L.outBack(c01(b.t / 0.3)) * (1 - c01((k - 0.85) / 0.15))
				b.p.CFrame = b.base * CFrame.Angles(0.12 * math.sin(age * 2.5 + b.ph), 0, 0.1 * math.cos(age * 2 + b.ph)) * CFrame.new(0, b.h * (rise - 0.5), 0)
				setT(b.p, math.max(1 - c01(b.t / 0.15), c01((k - 0.85) / 0.15)))
			elseif b.p.Transparency < 1 then b.p.Transparency = 1 end
		end

		GD.gustCD -= dt
		local v = ch.vel
		if v.Magnitude > 8 and not hidden and not swim then
			local d = v.Unit
			if GD.dir and GD.gustCD <= 0 and (d:Dot(GD.dir) < 0.5 or (run and not GD.wasRun)) then
				GD.gustCD = 0.8
				GD.gustP.CFrame = CFrame.lookAt(ch.pos, ch.pos - d + Vector3.new(0, 0.25, 0))
				GD.gust:Emit(18)
			end
			GD.dir = GD.dir and GD.dir:Lerp(d, c01(dt * 4)).Unit or d
		elseif v.Magnitude < 1 then GD.dir = nil end
		GD.wasRun = run

		for _, bf in ipairs(GD.flies) do
			bf.t -= dt
			if run and bf.mode == "land" then bf.mode, bf.t = "scatter", 1.4 if bf.f then bf.f.taken = nil bf.f = nil end end
			local goal, cap
			if bf.mode == "land" and bf.f and bf.f.t < bf.f.life - 0.6 then
				goal, cap = bf.f.core.Position + Vector3.new(0, 0.12 * s, 0), 6
				if bf.t <= 0 then bf.mode, bf.t = "fly", rnd(3, 6) bf.f.taken = nil bf.f = nil end
			elseif bf.mode == "scatter" then
				bf.sd = bf.sd or Vector3.new(rnd(-1, 1), 0, rnd(-1, 1)).Unit
				goal, cap = ch.pos + bf.sd * 9 * s + Vector3.new(0, 4 * s, 0), 14
				if bf.t <= 0 then bf.mode, bf.t, bf.sd = "fly", rnd(2, 4), nil end
			else
				if bf.mode == "land" then bf.mode = "fly" if bf.f then bf.f.taken = nil bf.f = nil end end
				bf.a += dt * (0.6 + 0.3 * math.sin(age * 0.8 + bf.ph))
				local r = (3.5 + 1.5 * math.sin(age * 0.7 + bf.ph)) * s
				goal = ch.pos + Vector3.new(math.cos(bf.a) * r, (1 + 1.2 * math.abs(math.sin(age * 0.9 + bf.ph)) + 0.25 * math.sin(age * 9 + bf.ph)) * s, math.sin(bf.a) * r)
				cap = 6
				if bf.t <= 0 then
					bf.t = rnd(3, 6)
					local fl = not on and GD.openFlower(ch.pos, 9 * s)
					if fl then bf.mode, bf.f, bf.t = "land", fl, rnd(2.5, 4.5) fl.taken = bf end
				end
			end
			if not bf.pos or (goal - bf.pos).Magnitude > 40 then bf.pos = goal end
			local nx = bf.pos:Lerp(goal, c01(dt * 3))
			local mv, lim = nx - bf.pos, (cap * s + ch.vel.Magnitude) * dt
			local prev = bf.pos
			bf.pos = mv.Magnitude > lim and bf.pos + mv.Unit * lim or nx
			local fl = (bf.pos - prev) * Vector3.new(1, 0, 1)
			if fl.Magnitude > 0.002 then bf.fw = fl.Unit end
			local landed = bf.mode == "land" and (bf.pos - goal).Magnitude < 0.2
			local cf = CFrame.lookAt(bf.pos, bf.pos + (bf.fw or Vector3.zAxis)) * CFrame.Angles(landed and 0 or 0.25, 0, 0)
			local flap = landed and (0.25 + 0.45 * math.abs(math.sin(age * 3 + bf.ph))) or (0.15 + 1.1 * math.abs(math.sin(age * 20 + bf.ph)))
			local tr = (hidden or swim or RSP.busy > os.clock()) and 1 or 0
			bf.body.CFrame = cf
			setT(bf.body, tr)
			for q, w in ipairs(bf.w) do
				local sd = q <= 2 and -1 or 1
				w.CFrame = cf * CFrame.new(0, 0, q % 2 == 1 and -0.06 or 0.1) * CFrame.Angles(0, 0, sd * flap) * CFrame.new(sd * (w.Size.X / 2 + 0.03), 0, 0)
				setT(w, tr == 1 and 1 or (q % 2 == 1 and 0 or 0.2))
			end
		end
	end







	local PER = { playT = 5, moodT = 0, len = 0, who = 1, wasNap = false, scanT = 1, greeted = {}, startle = 0, P = game:GetService("Players") }
	function PER.tick(dt, on, sit, longIdle, hidden)
		if longIdle then PER.wasNap = true
		elseif PER.wasNap and (on or sit) then
			PER.wasNap = false
			if on and not hidden then PER.startle = 0.9 aura:Emit(12) end
		end
		PER.startle = math.max(0, PER.startle - dt)
		local idle = not on and not sit and not longIdle and not hidden and not ch.emote
		if PER.mood then
			PER.moodT += dt
			if not idle or PER.moodT > PER.len then PER.mood = nil PER.playT = rnd(4, 8) end
		elseif idle then
			PER.playT -= dt
			if PER.playT <= 0 then
				local r = math.random(1, 4)
				PER.bf = r == 4 and GD.openFlower(ch.pos, 8) or nil
				if r == 4 and not PER.bf then r = math.random(1, 3) end
				PER.mood, PER.len = ({ "chase", "peek", "nuzzle", "boing" })[r], ({ 4.5, 3.2, 2.6, 4 })[r]
				PER.moodT, PER.who, PER.popped, PER.landT = 0, math.random(1, 2), false, nil
			end
		else PER.playT = math.max(PER.playT, 3) end
		PER.scanT -= dt
		if PER.scanT <= 0 and not hidden and ch.hrp then
			PER.scanT = 0.5
			local now = os.clock()
			for _, pl in ipairs(PER.P:GetPlayers()) do
				local c = pl.Character
				local r = c and c:FindFirstChild("HumanoidRootPart")
				if r and r ~= ch.hrp and (r.Position - ch.pos).Magnitude < 14 and now - (PER.greeted[pl.UserId] or -1e9) > 60 then
					local free
					for _, sp in ipairs(sprites) do if not sp.greet then free = sp end end
					if free then PER.greeted[pl.UserId] = now free.greet = { r = r, head = c:FindFirstChild("Head"), t = 0 } end
					break
				end
			end
		end
	end

	function PER.goal(i, sp, goal, dt, on, run, hidden, s)
		local side = i == 1 and -1 or 1
		sp.wave = 0
		if hidden then sp.greet, sp.loopT = nil, nil return goal end
		local g = sp.greet
		if g then
			g.t += dt
			local hd = (g.head and g.head.Parent) and g.head or g.r
			if not hd.Parent or g.t > 3.4 then sp.greet = nil
			elseif g.t < 2.5 then
				local over = hd.Position + Vector3.new(side * 0.4, 2.3 + 0.15 * math.sin(g.t * 5), 0)
				if g.t > 0.7 then sp.wave = 1 end
				if g.t > 0.9 and not g.popped then
					g.popped = true
					for q = 1, 3 do heartAt(over + Vector3.new(rnd(-0.6, 0.6), rnd(-0.2, 0.3), rnd(-0.6, 0.6)), 1.6, 1.8, 0.5) end
				end
				return over, 3
			else return goal, 3 end
		end
		if PER.five and ch.hrp then
			local meet = ch.pos + (ch.hrp.CFrame.LookVector * 1.6 + Vector3.yAxis * 1.3) * s
			return meet + ch.hrp.CFrame.RightVector * side * (PER.five < 0.75 and 0.6 or 0.24) * s, 5
		end
		if sp.dizzy and sp.pos then
			if sp.dizzy < 1.3 then return sp.pos, 1 end
			local cf = ch.hrp and ch.hrp.CFrame or CFrame.new(ch.pos)
			return ch.pos + (-cf.LookVector * 1.1 + Vector3.yAxis * 0.5 + cf.RightVector * side * 0.45) * s, 5
		end
		if sp.hold and sp.hold.pet and sp.pos then sp.wave = 0.35 return sp.pos, 1 end
		local M = PER.M
		if M.was and M.cur == "spin" then
			local a = os.clock() * 6 + i * math.pi
			return ch.pos + Vector3.new(math.cos(a) * 1.9 * s, 1 * s, math.sin(a) * 1.9 * s), 12
		elseif M.was and M.cur == "pose" and ch.hrp then
			return headPos() + (ch.hrp.CFrame.RightVector * side * 1.3 + ch.hrp.CFrame.LookVector * 0.3) * s, 4
		end
		if PER.startle > 0 then return goal + Vector3.new(0, 1.4 * s * math.sin(PER.startle / 0.9 * math.pi), 0), 10 end
		local m = PER.mood
		if m == "chase" then
			local a = PER.moodT * 2.2 + i * 1.1
			return ch.pos + Vector3.new(math.cos(a) * 2.4 * s, (0.9 + 0.6 * math.sin(a * 2)) * s, math.sin(a) * 2.4 * s), 5
		elseif m == "peek" and i == PER.who then
			local cam = workspace.CurrentCamera
			if cam then
				local d = (cam.CFrame.Position - ch.pos) * Vector3.new(1, 0, 1)
				d = d.Magnitude > 0.1 and d.Unit or Vector3.zAxis
				local k = math.sin(c01(PER.moodT / PER.len) * math.pi)
				if PER.moodT > 0.8 and PER.moodT < 2.4 then sp.wave = 1 end
				return ch.pos + d * (2 + 3 * k) * s + Vector3.new(0, (1.3 + 0.15 * math.sin(PER.moodT * 6)) * s, 0), 6
			end
		elseif m == "nuzzle" and i == PER.who then
			local hp = headPos()
			local right = ch.hrp and ch.hrp.CFrame.RightVector or Vector3.xAxis
			if PER.moodT > 0.8 and not PER.popped then PER.popped = true heartAt(hp + Vector3.new(0, 0.9 * s, 0), 1.6, 1.6, 0.5) end
			return hp + right * side * (0.55 + 0.12 * math.abs(math.sin(PER.moodT * 10))) * s, 6
		end

		if m == "boing" and i == PER.who and PER.bf then
			local fl = PER.bf
			local top = fl.core.Position + Vector3.new(0, 0.45 * s, 0)
			if fl.t >= fl.life - 0.4 then PER.len = 0 return goal end
			if not PER.landT then
				if (sp.pos - top).Magnitude < 0.5 * s then PER.landT = PER.moodT sp.tapT = 0 fl.bob = 1
				elseif PER.moodT > 2.6 then PER.len = 0 end
				return top, 6
			end
			local lt = PER.moodT - PER.landT
			if lt < 0.45 then return top, 10 end
			if not PER.popped then PER.popped = true sp.tapT = 0 fl.bob = 1 GD.sparkAt(top, 4) end
			if lt > 1.2 then PER.len = 0 end
			return top + Vector3.new(0, 2.6 * s * math.sin(c01((lt - 0.45) / 0.7) * math.pi), 0), 14
		end

		if run and not sp.loopT and math.random() < dt * 0.2 then sp.loopT = 0 end
		if sp.loopT then
			sp.loopT += dt
			if sp.loopT > 0.7 or not on then sp.loopT = nil
			else
				local a = sp.loopT / 0.7 * math.pi * 2
				local fwd = ch.vel.Magnitude > 0.1 and ch.vel.Unit or Vector3.zAxis
				return goal + (Vector3.yAxis * (1 - math.cos(a)) + fwd * math.sin(a)) * 1.2 * s, 14
			end
		end
		return goal
	end






	PER.UIS = game:GetService("UserInputService")
	function PER.hit(p2, inset)
		local cam = workspace.CurrentCamera
		if not cam then return end
		local best, bd
		for i, sp in ipairs(sprites) do
			if sp.pos and sp.bb.Enabled then
				local v = inset and cam:WorldToViewportPoint(sp.pos) or cam:WorldToScreenPoint(sp.pos)
				if v.Z > 0 then
					local px = cam.ViewportSize.Y / (2 * math.tan(math.rad(cam.FieldOfView) / 2) * v.Z)
					local d = (Vector2.new(v.X, v.Y) - p2).Magnitude
					if d < math.max(26, px * 0.8 * sc()) and (not bd or d < bd) then best, bd = i, d end
				end
			end
		end
		return best
	end
	L.conns = L.conns or {}
	table.insert(L.conns, PER.UIS.InputBegan:Connect(function(io, gp)
		if gp or (io.UserInputType ~= Enum.UserInputType.MouseButton1 and io.UserInputType ~= Enum.UserInputType.Touch) then return end
		local i = PER.hit(Vector2.new(io.Position.X, io.Position.Y))
		if not i then return end
		local sp, now = sprites[i], os.clock()



		if sp.dizzy or PER.five then return end
		sp.combo = (now - (sp.lastTap or -9) < 0.6) and (sp.combo or 0) + 1 or 1
		sp.lastTap, sp.tapT = now, 0
		sp.hold = { io = io, t0 = now, h = 0 }
		local o = sprites[3 - i]
		if sp.combo >= 3 then
			sp.combo, sp.dizzy, sp.hold, PER.last = 0, 0, nil, nil
		elseif sp.combo == 1 and PER.last and PER.last.i ~= i and now - PER.last.t < 1 and o.combo == 1 and not o.dizzy then
			PER.five, PER.last, sp.combo, o.combo, sp.hold = 0, nil, 0, 0, nil
		else
			PER.last = sp.combo == 1 and { i = i, t = now } or nil
			heartAt(sp.pos + Vector3.new(0, 0.5 * sc(), 0), 1.2, 1.2, 0.3 + 0.1 * sp.combo)
		end
	end))
	table.insert(L.conns, PER.UIS.InputEnded:Connect(function(io)
		for _, sp in ipairs(sprites) do
			if sp.hold and (sp.hold.io == io or (io.UserInputType == Enum.UserInputType.MouseButton1 and sp.hold.io.UserInputType == io.UserInputType)) then sp.hold = nil end
		end
	end))
	function PER.taps(dt, s)
		local hv = PER.UIS.MouseEnabled and PER.hit(PER.UIS:GetMouseLocation(), true)
		for i, sp in ipairs(sprites) do
			sp.hover = hv == i
			if sp.tapT then sp.tapT += dt if sp.tapT > 0.45 then sp.tapT = nil end end
			if sp.dizzy then sp.dizzy += dt if sp.dizzy > 4.3 then sp.dizzy = nil end end
			local h = sp.hold
			if h and os.clock() - h.t0 > 0.45 and sp.pos then
				if not h.pet then h.pet, sp.combo, PER.last = true, 0, nil end
				h.h -= dt
				if h.h <= 0 then h.h = 0.35 heartAt(sp.pos + Vector3.new(rnd(-0.3, 0.3), 0.4, rnd(-0.3, 0.3)) * s, 1, 1.1, 0.3) end
			end
		end
		if PER.five then
			local was = PER.five
			PER.five += dt
			if was < 0.9 and PER.five >= 0.9 and ch.hrp then
				local meet = ch.pos + (ch.hrp.CFrame.LookVector * 1.6 + Vector3.yAxis * 1.3) * s
				for q = 1, 6 do local a = q / 6 * 6.283 heartAt(meet + Vector3.new(math.cos(a) * 0.5, math.sin(a) * 0.5, 0) * s, 1.3, 1.3, 0.4) end
				aura:Emit(10)
			end
			if PER.five > 1.7 then PER.five = nil end
		end
	end








	PER.M = { e = 0, slow = 0, cd = 0, was = false }
	PER.PHRASE = { dance = "LET'S DANCE", spin = "WHEEE!", cheer = "YAY!", low = "SO CUTE", pose = "SO PRETTY", sway = "LOVELY!" }
	PER.ANY = { "SPARKLE!", "HEHE!", "SO PRETTY", "LOVELY!" }
	PER.LIMBS = { "RightHand", "LeftHand", "RightFoot", "LeftFoot", "Right Arm", "Left Arm", "Right Leg", "Left Leg" }
	function PER.beat(s)
		ch.sBeat = (ch.sBeat or 0) + 1
		L.groundWave(L.ground(ch.feet or ch.pos, 2, 4), "ring_c.png", PASTEL[math.random(1, #PASTEL)], 1 * s, 5 * s, 0.5, 1.5)
		for q = 1, 2 do heartAt(ch.pos + Vector3.new(rnd(-1.4, 1.4), rnd(0, 1.6), rnd(-1.4, 1.4)) * s, 1.3, 1.2, 0.4) end
		for _, sp in ipairs(sprites) do sp.bop = 0.3 end
	end
	function PER.motion(dt, s, emote, hidden)
		local M, root, c = PER.M, ch.hrp, ch.char
		if not root or not c then return end
		local inv = root.CFrame:Inverse()


		if emote and not hidden then M.off = 0 else M.off = (M.off or 0) + dt end
		if M.was and M.off < 0.8 and not hidden then emote = true end
		if emote and M.was and ch.emoteObj and M.obj and ch.emoteObj ~= M.obj then M.was = false end
		if ch.emoteObj then M.obj = ch.emoteObj end
		if not emote or hidden then
			if ch.torso then M.rest = (inv * ch.torso.Position).Y end
			if M.was then M.was, M.style, M.cur, M.obj, ch.sPhrase = false, nil, nil, nil, nil end
			M.last, M.yaw = nil, nil
			return
		end
		if not M.was then
			M.was, M.t, M.votes, M.said, M.calm, M.cheerOn, M.lowOn = true, 0, { dance = 0, spin = 0, cheer = 0, low = 0, pose = 0, sway = 0 }, false, 0, false, false
			ch.sEmoteN = (ch.sEmoteN or 0) + 1
			for _, sp in ipairs(sprites) do sp.tapT = 0 end
		end
		M.t += dt
		local pts, sum, k = {}, 0, 0
		for _, n in ipairs(PER.LIMBS) do
			local p = c:FindFirstChild(n)
			if p and p:IsA("BasePart") then
				local v = inv * p.Position
				pts[n] = v
				local o = M.last and M.last[n]
				if o then sum += (v - o).Magnitude k += 1 end
			end
		end
		M.last = pts
		local energy = k > 0 and sum / k / math.max(dt, 1 / 240) / s or 0
		M.e += (energy - M.e) * c01(dt * 10)
		M.slow += (M.e - M.slow) * c01(dt * 1.2)
		M.cd -= dt

		if M.e > 5 and M.e > M.slow * 1.4 and not M.hi and M.cd <= 0 then M.hi, M.cd = true, 0.3 PER.beat(s)
		elseif M.e < M.slow * 1.1 then M.hi = false end

		local yr = 0
		if ch.torso then
			local lv = inv:VectorToObjectSpace(ch.torso.CFrame.LookVector)
			local wl = root.CFrame.LookVector
			local yaw = math.atan2(-lv.X, -lv.Z) + math.atan2(-wl.X, -wl.Z)
			if M.yaw then
				local d = (yaw - M.yaw + math.pi) % (2 * math.pi) - math.pi
				yr = math.abs(d) / math.max(dt, 1 / 240)
			end
			M.yaw = yaw
		end
		M.spin = (M.spin or 0) + (yr - (M.spin or 0)) * c01(dt * 6)
		local head = c:FindFirstChild("Head")
		local hy = head and (inv * head.Position).Y or 1.5 * s
		local rh, lh = pts.RightHand or pts["Right Arm"], pts.LeftHand or pts["Left Arm"]
		local up = rh and lh and rh.Y > hy - (pts.RightHand and 0.1 or 0.5) * s and lh.Y > hy - (pts.LeftHand and 0.1 or 0.5) * s
		local low = ch.torso and M.rest and (inv * ch.torso.Position).Y < M.rest - 0.9 * s
		M.calm = M.e < 3.2 and M.calm + dt or 0
		local cur = M.spin > 5 and "spin" or up and "cheer" or low and "low" or M.e > 6 and "dance" or M.calm > 1.5 and "pose" or M.e > 3.2 and "sway" or nil
		M.cur = cur
		if cur then M.votes[cur] += dt end

		if up and not M.cheerOn then
			for q = 1, 6 do heartAt(headPos() + Vector3.new(rnd(-1, 1), rnd(0.3, 1), rnd(-1, 1)) * s, 2.4, 1.6, 0.5) end
			aura:Emit(18)
		end
		M.cheerOn = up
		if low and not M.lowOn then
			local a0 = rnd(0, 6.3)
			for q = 1, 8 do local a = a0 + q / 8 * 6.283 bloom(L.ground(ch.feet + Vector3.new(math.cos(a), 0, math.sin(a)) * 2 * s, 2, 4), rnd(0.55, 0.8), 2) end
		end
		M.lowOn = low
		if cur == "sway" then
			M.pw = (M.pw or 0) - dt
			if M.pw <= 0 then M.pw = 0.4 auraP.CFrame = CFrame.new(ch.pos + Vector3.new(0, 1.5 * s, 0)) petals:Emit(1) end
		end
		if cur == "spin" then
			M.sw = (M.sw or 0) - dt
			if M.sw <= 0 then M.sw = 0.12 auraP.CFrame = CFrame.new(ch.pos) petals:Emit(2) end
		end

		if not M.said and M.t > 1.2 then
			M.said = true

			local best, bv = nil, 0.15
			for n, v in pairs(M.votes) do if v > bv then best, bv = n, v end end
			do
				M.style = best
				ch.sPhrase = best and PER.PHRASE[best] or PER.ANY[math.random(1, #PER.ANY)]
				local me = ch.sEmoteN
				task.delay(3.5, function() if ch.sEmoteN == me then ch.sPhrase = nil end end)
			end
		end
	end


	local age, travel, lastPos, ringT, still, blinkT, flapT, wasSwim = 0, 0, nil, 0, 0, 2, 0, false
	local function inVehicle() local h = ch.hum local sp = h and h.SeatPart return sp ~= nil and sp:IsA("VehicleSeat") end
	local function step(dt)
		age += dt
		local s, iw, on, swim, sit, dead, emote, air = sc(), ch.iw, ch.on, ch.swim == true, ch.sit == true, ch.dead == true, ch.emote == true, ch.air == true
		local hidden = dead or deadHalo
		local run = (ch.sprint or 0) > 0.2 or ch.spd > 18
		still = on and 0 or still + dt
		local longIdle = still > 10 and not sit and not swim and not air

		local hp = headPos() + Vector3.new(0, (1.1 + (swim and 0.5 or 0)) * s + 0.07 * math.sin(age * 1.6), 0)

		if not HL.p or (HL.p - hp).Magnitude > 8 * s then HL.p, HL.v = hp, Vector3.zero end
		local hdt = math.min(dt, 1 / 30)

		local np = HL.p:Lerp(hp, 1 - math.exp(-dt * 30))
		HL.v = (np - HL.p) / math.max(dt, 1e-3)
		HL.p = np
		local lag = HL.p - hp

		local hv = ch.vel * Vector3.new(1, 0, 1)
		local tiltAx = hv.Magnitude > 0.5 and hv.Unit:Cross(Vector3.yAxis) or Vector3.xAxis
		local tilt = -math.min(hv.Magnitude / 22, 1) * 0.2
		local tiltCF = hv.Magnitude > 0.5 and CFrame.fromAxisAngle(tiltAx, tilt) or CFrame.identity

