		local e = flameE(at, { EmissionDirection = Enum.NormalId.Top, Speed = NR(3, 4.5), Lifetime = NR(0.25, 0.38), Brightness = 2.5,
			Size = NS({ K(0, 0.6), K(0.35, 1.0), K(1, 0.1) }), Acceleration = Vector3.new(0, 4, 0), Squash = NS(-0.6), SpreadAngle = Vector2.new(4, 4),
			LockedToPart = true, Rotation = NR(-5, 5), RotSpeed = NR(0, 0) })
