	local crownEmb = emberE(L.new("Attachment", {}, crown), { Shape = Enum.ParticleEmitterShape.Sphere, Speed = NR(2, 4), Lifetime = NR(0.6, 1.1),
		SpreadAngle = Vector2.new(30, 30), Size = NS({ K(0, 0.18), K(1, 0) }), Acceleration = Vector3.new(0, 3, 0) })
	crownE[#crownE + 1] = { e = crownEmb, base = 16, ember = true }
	local crownLight = L.new("PointLight", { Color = C2, Range = 12, Brightness = 2, Shadows = false }, crown)
	local rig, light, hl = {}, nil, nil
	local function rebind()
		for _, o in ipairs(rig) do o:Destroy() end
		rig = {}
		local hrp = ch.hrp
		local function att(pos) local a = L.new("Attachment", { Position = pos }, hrp) rig[#rig + 1] = a return a end
		local function trail(a0, a1, props) local t = L.new("Trail", props, hrp) t.Attachment0, t.Attachment1 = a0, a1 rig[#rig + 1] = t return t end
		rig.main = trail(att(Vector3.new(0, 1.2, 0.3)), att(Vector3.new(0, -1.5, 0.3)), { Texture = L.T("beamb.png"), LightEmission = 1, Brightness = 3,
			Lifetime = 0.4, FaceCamera = true, Enabled = false, Color = CS({ CK(0, W), CK(0.2, C2), CK(0.6, C1), CK(1, Color3.fromRGB(50, 15, 5)) }),
			Transparency = NS({ K(0, 0.15), K(1, 1) }), WidthScale = NS({ K(0, 1), K(1, 0.2) }) })
		local back = att(Vector3.new(0, -1.6, 0.6))
		rig.wake = flameE(back, { EmissionDirection = Enum.NormalId.Back, Speed = NR(2, 5), Lifetime = NR(0.4, 0.7), Size = NS({ K(0, 1), K(0.3, 2), K(1, 0.3) }) })
		rig.smoke = smokeE(back, { Size = NS({ K(0, 1.5), K(1, 4) }), Lifetime = NR(0.8, 1.4), Speed = NR(1, 2) })
		rig.emb = emberE(back, {})
		rig.lines = flameE(hrp, { Shape = Enum.ParticleEmitterShape.Box, EmissionDirection = Enum.NormalId.Back, Speed = NR(25, 40), Lifetime = NR(0.12, 0.22),
			Orientation = Enum.ParticleOrientation.VelocityParallel, Size = NS(0.5), Squash = NS(-2), Acceleration = Vector3.zero })
		for _, e in ipairs({ rig.wake, rig.smoke, rig.emb, rig.lines }) do rig[#rig + 1] = e end
		light = L.new("PointLight", { Color = C1, Range = 16, Brightness = 0, Shadows = false }, hrp) rig[#rig + 1] = light
		hl = L.new("Highlight", { FillTransparency = 1, OutlineColor = C2, Adornee = ch.char, DepthMode = Enum.HighlightDepthMode.Occluded }, L.root) rig[#rig + 1] = hl
	end
	rebind()
	local tag = System.StaffThemes.headTag(L, "inferno", C1, C2, { c1 = C1, c2 = C2, grad = CS({ CK(0, C1), CK(0.3, C2), CK(0.5, W), CK(0.7, C2), CK(1, C1) }) })




	local savedLTM, hideChar, hideOwner, hideGen, dashTok, quietTok = nil, nil, nil, 0, nil, nil
	local function setHidden(on, tok)
		if on then
			hideGen += 1
			local my = hideGen
			hideOwner = my
			task.delay(15, function() setHidden(false, my) end)
			if savedLTM and hideChar == ch.char then return my end
			if not ch.char then return my end
			savedLTM, hideChar = {}, ch.char
			for _, d in ipairs(ch.char:GetDescendants()) do
				if d:IsA("BasePart") or d:IsA("Decal") then savedLTM[d] = d.LocalTransparencyModifier d.LocalTransparencyModifier = 1 end
			end
			return my
		elseif savedLTM then
			if tok and tok ~= hideOwner then return end
			for d, v in pairs(savedLTM) do if d.Parent then d.LocalTransparencyModifier = v end end
			if tok and tok ~= dashTok and tok ~= quietTok then L.punch(1.1, 0.3) end
			savedLTM, hideChar, hideOwner = nil, nil, nil
		end
	end
	local function appear(col, tok)
		setHidden(false, tok)
		hl.FillColor = col or W
		L.fx(0.8, function(k) hl.FillTransparency = 0.06 + 0.94 * k end)
	end
	local function camBasis() return L.facing() end

	local function impact(p, s)
		L.groundWave(p, "ring_c.png", C2, 1, 10 * s, 0.5)
		L.groundWave(p, "cracks_b.png", C1, 2, 6 * s, 1.4, 2)
		local ip = L.part({ Size = Vector3.new(1.5 * s, 0.2, 1.5 * s), CFrame = CFrame.new(p) })
		local fe = flameE(ip, { Shape = Enum.ParticleEmitterShape.Box, EmissionDirection = Enum.NormalId.Top, Speed = NR(8, 18), SpreadAngle = Vector2.new(35, 35),
			Lifetime = NR(0.4, 0.7), Size = NS({ K(0, 1.5 * s), K(0.3, 3 * s), K(1, 0.4) }) })
		local se = smokeE(ip, { EmissionDirection = Enum.NormalId.Top, Speed = NR(4, 8), Size = NS({ K(0, 2 * s), K(1, 6 * s) }), Lifetime = NR(1.2, 2) })
		fe:Emit(14) se:Emit(4)
		L.fx(1.8, function(kk) fe.Rate = 25 * (1 - kk) end, { ip })
	end

	local function fireball(from, to, size, travel, onHit)
		local b = L.part({ Shape = Enum.PartType.Ball, Material = Enum.Material.Neon, Color = C2:Lerp(W, 0.4), Transparency = 0, Size = Vector3.one * size })
		local fe = flameE(b, { Rate = 90, Speed = NR(0, 2), Lifetime = NR(0.3, 0.5), Acceleration = Vector3.zero, LightEmission = 0.8,
			Size = NS({ K(0, size * 1.8), K(1, size * 0.6) }), Brightness = 3 })
		local a0 = L.new("Attachment", { Position = Vector3.new(0, size * 0.45, 0) }, b)
		local a1 = L.new("Attachment", { Position = Vector3.new(0, -size * 0.45, 0) }, b)
		L.new("Trail", { Attachment0 = a0, Attachment1 = a1, Texture = L.T("beamb.png"), LightEmission = 1, Brightness = 4, Lifetime = 0.3,
			FaceCamera = true, Color = CS({ CK(0, W), CK(0.3, C2), CK(1, C1) }), Transparency = NS(0, 1), WidthScale = NS(1, 0.2) }, b)
		local done = false
		L.fx(travel + 0.3, function(k, t)
			if done then return end
			local u = c01(t / travel)
			b.CFrame = CFrame.new(from:Lerp(to, u ^ 1.3))
			if u >= 1 then done = true b.Transparency = 1 fe.Rate = 0 if onHit then onHit(to) end end
		end, { b })
	end


	local function meteor(short)
		local o = ch.feet
		local hideTok = setHidden(true)
		task.delay(short and 3 or 7.8, function() setHidden(false, hideTok) end)
		local showerT = 0.9
		local DUR, CL = short and 2.8 or 7.6, short and 0.95 or 3.0
		local T0 = short and 0.15 or 0.7
		local sc = short and 0.45 or 1
		if not short then L.after(DUR - 2.6, function() L.handoff(o, "ring_c.png", C2, 26, 6, 2.4) end) end
		local S
		if not short then
			S = L.screen(DUR)
			S.dimFn = function(t) return c01(t / 0.8) * (1 - c01((t - (CL + 1.8)) / 1.6)) end
			S.style, S.c1, S.c2 = "inferno", C1, C2 S.boxFn = function(t) return c01((t - 0.2) / 0.6) * (1 - c01((t - (DUR - 1)) / 0.8)) end
			S.tintFn = function(t) return C1, 0.45 * c01((t - 1) / (CL - 1)) * (1 - c01((t - CL - 0.4) / 1.4)) end
			L.after(CL + 0.3, function() S:title(L.name(), C1, C2) end)
		end

		local gc, gcm = L.mesh("disc.mesh", "cracks_b.png", C1, 1.6)
		local tgt, tgtM = L.mesh("disc.mesh", "glyph.png", C2, 1.8)

		local ringParts, ringE = {}, {}
		local R = 12 * sc
		for i = 1, 16 do
			local a = i / 16 * math.pi * 2
			local p = L.part({ Size = Vector3.new(2.2, 0.2, 2.2), CFrame = CFrame.new(o + Vector3.new(math.cos(a) * R, 0.2, math.sin(a) * R)) })
			ringParts[i] = p
			ringE[i] = flameE(p, { Shape = Enum.ParticleEmitterShape.Box, EmissionDirection = Enum.NormalId.Top, Speed = NR(6, 12),
				Size = NS({ K(0, 1), K(0.3, 3), K(1, 0.4) }), Lifetime = NR(0.5, 0.9) })
		end

		local fwd, right = L.facing()
		local D = short and 70 or 380
		local from = o + right * D * 0.75 + fwd * D * 0.3 + Vector3.new(0, D * 1.15, 0)
		local dir = (o - from).Unit
		local MS = short and 3 or 8
		local core = L.part({ Transparency = 1, Material = Enum.Material.Neon, Color = C2:Lerp(W, 0.55) })
		local coreM = L.new("SpecialMesh", { MeshType = Enum.MeshType.Sphere, Scale = Vector3.one * MS * 10 }, core)
		local shell, shellM = L.mesh("sphere.mesh", "smoke.png", C1, 2.6)
		local cone, coneM = L.mesh("swirl.mesh", "smoke.png", C2, 2.2)
		local headA, tailA, hazeA = L.att(from), L.att(from), L.att(from)
		local streak = L.beam(headA, tailA, { Width0 = MS * 1.3, Width1 = MS * 0.7, Brightness = 5, Segments = 2,
			Color = CS({ CK(0, W), CK(0.15, C2), CK(1, C1) }), Transparency = NS({ K(0, 1), K(0.03, 0), K(1, 1) }) })
		local haze = L.beam(headA, hazeA, { Width0 = MS * 3, Width1 = MS * 0.8, Brightness = 2, Segments = 2,
			Color = CS(C2, C1), Transparency = NS({ K(0, 1), K(0.05, 0.45), K(1, 1) }) })
		local fireE = flameE(shell, { Rate = 0, Speed = NR(0, 3), Lifetime = NR(0.5, 0.8), Acceleration = Vector3.zero, LightEmission = 0.8,
			Size = NS({ K(0, MS * 0.8), K(1, MS * 1.4) }), Brightness = 3 })
		local smokeT = smokeE(shell, { Rate = 0, Speed = NR(0, 1), Lifetime = NR(3, 4.5), Acceleration = Vector3.new(0, 0.5, 0),
			Size = NS({ K(0, MS * 0.9), K(1, MS * 2.6) }), Transparency = NS({ K(0, 1), K(0.1, 0.5), K(1, 1) }) })
		local mLight = L.new("PointLight", { Color = C2, Range = 80, Brightness = 0, Shadows = false }, shell)
		local hit = false
		local lastT = 0
		L.fx(DUR, function(k, t)
			local dt = t - lastT lastT = t
			local heat = c01(t / CL)
			local cool = c01((t - CL - 0.5) / 3.5)

			local gs = hit and (34 * sc) or (6 + 22 * L.outQuad(heat)) * sc
			gcm.Scale = Vector3.new(gs, 1, gs)
			gc.CFrame = CFrame.new(o + Vector3.new(0, 0.07, 0))
			L.tint(gcm, C1:Lerp(C2, hit and (1 - cool) * 0.6 or 0), (hit and 3.2 * (1 - cool) or 1.4 * heat) + 0.4)
			gc.Transparency = 1 - (0.85 * c01(t / 0.4)) * (1 - c01((t - DUR + 1.2) / 1.2))
			local ts = (30 - 22 * L.outQuad(heat)) * sc
			tgtM.Scale = Vector3.new(ts, 1, ts)
			tgt.CFrame = CFrame.new(o + Vector3.new(0, 0.12, 0)) * CFrame.Angles(0, -t * (1 + 3 * heat), 0)
			tgt.Transparency = hit and 1 or (1 - 0.8 * c01(t / 0.5) * (0.6 + 0.4 * math.abs(math.sin(t * 8 * heat))))
			for i, e in ipairs(ringE) do
				local lit = t > 0.4 + i * 0.05 and t < DUR - 1.4
				e.Rate = lit and (hit and 30 or 18) * (1 - 0.6 * cool) or 0
			end

			if not short and not hit and t >= showerT and t < CL - 0.4 then
				showerT = t + rnd(0.07, 0.2) * (1.3 - 0.9 * heat)
				local a, r = rnd(0, 6.28), rnd(10, 45)
				local to = o + Vector3.new(math.cos(a) * r, 0, math.sin(a) * r)
				local s = rnd(0.9, 1.8)
				fireball(to - dir * rnd(90, 140) + Vector3.new(rnd(-15, 15), 0, rnd(-15, 15)), to, s, rnd(0.45, 0.7), function(p)
					impact(p, s)
					if S then S:shake(0.5, 0.15) end
				end)
			end
			if not hit then
				local u = c01((t - T0) / (CL - T0))
				local vis = t >= T0
				local pos = from:Lerp(o + Vector3.new(0, MS * 0.3, 0), u ^ 1.6)
				local spin = CFrame.Angles(t * 3, t * 2, 0)
				core.CFrame = CFrame.new(pos)
				core.Transparency = vis and 0 or 1
				shell.CFrame = CFrame.new(pos) * spin
				shellM.Scale = Vector3.one * MS * 1.5
				shell.Transparency = vis and 0.15 or 1
				coneM.Scale = Vector3.new(MS * 1.7, MS * 3.2, MS * 1.7)
				cone.CFrame = CFrame.lookAt(pos, pos + dir) * CFrame.Angles(math.rad(90), 0, t * 4) * CFrame.new(0, MS * 1.1, 0)
				cone.Transparency = vis and 0.3 or 1
				headA.WorldPosition = pos
				local len = (short and 40 or 170) * c01((t - T0) / 0.5) * (1 - 0.75 * c01((u - 0.8) / 0.2))
				tailA.WorldPosition = pos - dir * len
				hazeA.WorldPosition = pos - dir * len * 0.7
				streak.Enabled, haze.Enabled = vis, vis
				fireE.Rate = vis and (short and 120 or 320) or 0
				smokeT.Rate = vis and (short and 25 or 70) or 0
				mLight.Brightness = vis and 3 + 9 * u or 0
				if S and vis then S:shake(0.25 + 1.1 * u * u, 0.2) end
				if t >= CL then
					hit = true
					core:Destroy() shell.Transparency = 1 cone:Destroy() streak:Destroy() haze:Destroy()
					fireE.Rate, smokeT.Rate, mLight.Brightness = 0, 0, 0

					if S then S:flash(C2:Lerp(W, 0.5), 0.65) S:shake(3.6, 1.5) end
					L.after(0.25, function() appear(C2, hideTok) end)
					local fb = L.part({ Transparency = 0, Material = Enum.Material.Neon, Color = W, CFrame = CFrame.new(o) })
					local fbm = L.new("SpecialMesh", { MeshType = Enum.MeshType.Sphere }, fb)
					L.fx(0.55, function(kk) local s = (2 + 30 * L.outQuad(kk / 0.5)) * sc * 10 fbm.Scale = Vector3.new(s, s * 0.8, s)
						fb.Color = W:Lerp(C2, kk) fb.Transparency = c01(kk * 1.6 - 0.2) end, { fb })
					L.groundWave(o, "ring_c.png", W, 4, 80 * sc, 0.7)
					L.groundWave(o, "ring_c.png", C2, 4, 50 * sc, 0.9)
					L.groundWave(o, "ring_c.png", C1, 4, 30 * sc, 1.2)
					if not short then L.groundWave(o, "ring_c.png", C1, 10, 1400, 5.4, 2.6) end
					burst:Emit(short and 40 or 140)

					local dome, domeM = L.mesh("sphere.mesh", "smoke.png", C1, 2.4)
					L.fx(1.1, function(kk) local s = (6 + 46 * L.outQuad(kk)) * sc domeM.Scale = Vector3.new(s, s * 0.7, s) dome.CFrame = CFrame.new(o)
						L.tint(domeM, C2:Lerp(C1, kk), 2.4 - kk) dome.Transparency = 0.1 + 0.9 * kk end, { dome })

					local pil = L.part({ Size = Vector3.new(5 * sc, 0.2, 5 * sc), CFrame = CFrame.new(o) })
					local pe = flameE(pil, { Shape = Enum.ParticleEmitterShape.Box, EmissionDirection = Enum.NormalId.Top, Speed = NR(45, 70),
						Lifetime = NR(0.5, 0.9), Size = NS({ K(0, 3 * sc), K(0.3, 6 * sc), K(1, 2 * sc) }), Acceleration = Vector3.new(0, 20, 0), Rate = 260 * sc })
					local col, colTop = L.att(o), L.att(o + Vector3.new(0, 90 * sc, 0))
					local bm = L.beam(col, colTop, { Width0 = 10 * sc, Width1 = 4 * sc, Brightness = 6, Color = CS({ CK(0, W), CK(0.4, C2), CK(1, C1) }), Segments = 2 })
					local plight = L.new("PointLight", { Color = C2, Range = 60, Brightness = 10, Shadows = false }, pil)
					L.fx(1.6, function(kk)
						pe.Rate = (260 * sc) * (1 - c01((kk - 0.4) / 0.6))
						bm.Transparency = NS(c01(kk * 1.3))
						bm.Width0 = 10 * sc * (1 - kk * 0.7)
						plight.Brightness = 10 * (1 - kk)
					end, { pil, col, colTop, bm })

					local ringObjs = {}
					for j = 1, 20 do
						local a = j / 20 * math.pi * 2
						local p0 = o + Vector3.new(math.cos(a) * 2, 0.8, math.sin(a) * 2)
						local rp = L.part({ Size = Vector3.new(1.5, 1, 0.2), CFrame = CFrame.lookAt(p0, p0 + Vector3.new(math.cos(a), 0, math.sin(a))) })
						local se = smokeE(rp, { EmissionDirection = Enum.NormalId.Front, Speed = NR(35, 55) , Drag = 2.5, Lifetime = NR(1, 1.6),
							SpreadAngle = Vector2.new(10, 6), Acceleration = Vector3.new(0, 2, 0), Size = NS({ K(0, 3 * sc), K(1, 7 * sc) }) })
						local fe = flameE(rp, { EmissionDirection = Enum.NormalId.Front, Speed = NR(30, 50), Drag = 3, Lifetime = NR(0.5, 0.8),
							SpreadAngle = Vector2.new(10, 6), Size = NS({ K(0, 2 * sc), K(0.3, 3.5 * sc), K(1, 0.5) }) })
						se:Emit(short and 2 or 4) fe:Emit(short and 3 or 6)
						ringObjs[#ringObjs + 1] = rp
					end
					L.fx(2, function() end, ringObjs)

					for j = 1, short and 6 or 20 do
						local a = rnd(0, 6.28)
						local v = Vector3.new(math.cos(a) * rnd(20, 50), rnd(30, 65), math.sin(a) * rnd(20, 50)) * sc
						local rock = L.part({ CFrame = CFrame.new(o + Vector3.new(0, 1, 0)), Size = Vector3.new(1, 1, 1) * rnd(0.6, 1.4) * (short and 0.6 or 1), Transparency = 0, Color = Color3.fromRGB(35, 25, 22), Material = Enum.Material.Basalt })
						local b0 = L.new("Attachment", { Position = Vector3.new(0, 0.3, 0) }, rock)
						local b1 = L.new("Attachment", { Position = Vector3.new(0, -0.3, 0) }, rock)
						L.new("Trail", { Attachment0 = b0, Attachment1 = b1, Texture = L.T("beamb.png"), LightEmission = 1, Brightness = 4, Lifetime = 0.35,
							FaceCamera = true, Color = CS({ CK(0, C2), CK(1, C1) }), Transparency = NS(0, 1), WidthScale = NS(1, 0) }, rock)
						flameE(rock, { Rate = 40, Speed = NR(0, 1), Lifetime = NR(0.2, 0.4), Size = NS({ K(0, 1.2), K(1, 0.2) }) })
						local p0, spin = o + Vector3.new(0, 1, 0), CFrame.Angles(rnd(0, 6), rnd(0, 6), rnd(0, 6))
						L.fx(1.4, function(kk, tt)
							local pp = p0 + v * tt + Vector3.new(0, -60 * tt * tt, 0)
							if pp.Y < o.Y then pp = Vector3.new(pp.X, o.Y, pp.Z) end
							rock.CFrame = CFrame.new(pp) * spin * CFrame.Angles(tt * 6, tt * 4, 0)
						end, { rock })
					end

					local mush = L.part({ Size = Vector3.new(10 * sc, 1, 10 * sc), CFrame = CFrame.new(o + Vector3.new(0, 2, 0)) })
					local me = smokeE(mush, { Shape = Enum.ParticleEmitterShape.Box, EmissionDirection = Enum.NormalId.Top, Speed = NR(10, 20),
						Size = NS({ K(0, 6 * sc), K(1, 16 * sc) }), Lifetime = NR(2, 3), Drag = 1.2 })
					me:Emit(short and 6 or 18)
					L.fx(3.2, function() end, { mush })

					for j = 1, short and 3 or 7 do
						local a, r = rnd(0, 6.28), rnd(3, 11) * sc
						local vp = L.part({ Size = Vector3.new(1.2, 0.2, 1.2), CFrame = CFrame.new(o + Vector3.new(math.cos(a) * r, 0.1, math.sin(a) * r)) })
						local ve = flameE(vp, { Shape = Enum.ParticleEmitterShape.Box, EmissionDirection = Enum.NormalId.Top, Speed = NR(4, 8),
							Size = NS({ K(0, 0.8), K(0.3, 2), K(1, 0.2) }), Lifetime = NR(0.4, 0.8) })
						local life = rnd(2.5, 4)
						L.fx(life, function(kk) ve.Rate = 30 * (1 - kk) end, { vp })
					end
				end
			end
			if hit then light.Brightness = math.max(light.Brightness, 3 * (1 - cool)) end
		end, { gc, tgt, shell, headA, tailA, hazeA, table.unpack(ringParts) })
	end


	local ASH = Color3.fromRGB(38, 37, 40)







	local function featherWings()
		local fw = { objs = {}, w = {} }
		for si, side in ipairs({ 1, -1 }) do
			local wing = { side = side, f = {} }
			for i = 1, 10 do
				local a0, a1 = L.att(), L.att()
				local b = L.beam(a0, a1, { Texture = L.T("plumev.png"), TextureMode = Enum.TextureMode.Stretch, TextureLength = 1, TextureSpeed = 0, Segments = 12,
					LightEmission = 0.3, Brightness = 3, Transparency = NS(1) })
				wing.f[i] = { a0 = a0, a1 = a1, b = b }
				fw.objs[#fw.objs + 1] = a0 fw.objs[#fw.objs + 1] = a1 fw.objs[#fw.objs + 1] = b
			end
			wing.sp = L.part({ Size = Vector3.one })
			wing.fe = flameE(wing.sp, { Shape = Enum.ParticleEmitterShape.Box, Rate = 0, Speed = NR(1, 3), Lifetime = NR(0.3, 0.6), Size = NS({ K(0, 1.2), K(0.3, 2), K(1, 0.3) }) })
			wing.ee = emberE(wing.sp, { Shape = Enum.ParticleEmitterShape.Box, Rate = 0, Speed = NR(1, 4), Lifetime = NR(0.8, 1.4) })
			fw.objs[#fw.objs + 1] = wing.sp
			fw.w[si] = wing
		end
		local function draw(wing, frame, open, R, tr, glow, t, pal, flat)
			local X, Z, N, O = frame.RightVector, -frame.LookVector, frame.UpVector, frame.Position
			local function dir(th) return X * math.cos(th) + Z * math.sin(th) end
			local fold = 1 - open
			local armTh = math.rad(-8) + fold * math.rad(55)
			local armLen = R * 0.42 * (1 - 0.35 * fold)
			local hot = pal and pal[1] or C2:Lerp(W, 0.25 + 0.65 * glow)
			local mid = pal and pal[2] or C2:Lerp(C1, 0.2 * (1 - glow)):Lerp(W, 0.5 * glow)
			local tip = pal and pal[3] or C1:Lerp(Color3.fromRGB(90, 15, 5), 0.3 * (1 - glow))
			local cs = CS({ CK(0, hot), CK(0.45, mid), CK(1, tip) })
			local ns = NS({ K(0, math.min(1, tr + 0.15)), K(0.15, tr), K(0.8, tr), K(1, math.min(1, tr + 0.35)) })

			local view = O - workspace.CurrentCamera.CFrame.Position
			local wmul = flat and 1 or 1 + 1.3 * (1 - math.abs(view.Unit:Dot(N)))
			for i, f in ipairs(wing.f) do
				local root, th, len, w0, w1
				if i <= 7 then
					local k = (i - 1) / 6
					root = O + dir(armTh) * armLen * (1 - 0.8 * k)
					th = armTh + math.rad(8 + 78 * k) + fold * math.rad(25 * (1 - k)) + (flat and 0 or math.rad(2.5) * math.sin(t * 11 + i))
					len = R * (0.66 - 0.26 * k) * (1 - 0.3 * fold)
					w0, w1 = R * 0.16, R * 0.12
				else
					local k = (i - 8) / 2
					root = O + dir(armTh) * armLen * (0.85 - 0.6 * k)
					th = armTh + math.rad(50 + 25 * k)
					len = R * 0.32
					w0, w1 = R * 0.2, R * 0.15
				end
				local tipP = root + dir(th) * len - N * (flat and 0 or len * 0.12)

				local ta, tb = dir(th - math.rad(14)), dir(th + math.rad(18))
				f.a0.WorldCFrame = CFrame.fromMatrix(root, ta, flat and N:Cross(ta) or N)
				f.a1.WorldCFrame = CFrame.fromMatrix(tipP, tb, flat and N:Cross(tb) or N)
				f.b.CurveSize0, f.b.CurveSize1 = len * 0.3, len * 0.3
				f.b.Width0, f.b.Width1 = w0 * wmul, w1 * wmul
				f.b.Color, f.b.Transparency = cs, ns
				f.b.FaceCamera = not flat
				f.b.Brightness = 1.5 + 3 * glow
			end
			wing.sp.CFrame = CFrame.fromMatrix(O + dir(armTh + 0.5) * R * 0.45, X, N)
			wing.sp.Size = Vector3.new(R * 0.7, 0.4, R * 0.5)
			local on = tr < 0.6 and not flat
			wing.fe.Rate, wing.ee.Rate = on and 40 or 0, on and 25 or 0
		end

		function fw.bird(bcf, flap, open, R, tr, glow, t, pal, flat)
			for _, wing in ipairs(fw.w) do
				local s = wing.side
				local u = bcf.RightVector * s * math.cos(flap) + bcf.UpVector * math.sin(flap)
				local v = -bcf.LookVector
				local O = bcf.Position + bcf.RightVector * s * R * 0.05 + bcf.UpVector * 0.3 + bcf.LookVector * R * 0.06
				draw(wing, CFrame.fromMatrix(O, u, v:Cross(u), v), open, R, tr, glow, t, pal, flat)
			end
		end

		function fw.back(cf, open, lift, R, tr, glow, t)
			for _, wing in ipairs(fw.w) do
				local s = wing.side
				local up = math.rad(30) + lift
				local u = (cf.RightVector * s * math.cos(up) + cf.UpVector * math.sin(up) - cf.LookVector * 0.35 * (1 - open)).Unit
				local v0 = -cf.UpVector
				local v = (v0 - u * u:Dot(v0)).Unit
				local O = cf.Position + cf.UpVector * 1.1 - cf.LookVector * 0.7 + cf.RightVector * s * 0.3
				draw(wing, CFrame.fromMatrix(O, u, v:Cross(u), v), open, R, tr, glow, t)
			end
		end
		return fw
	end






	local function dragon3D(NJ, sc)
		local dg = { objs = {}, NJ = NJ, fire = {}, eyes = {} }
		local function keep(x) dg.objs[#dg.objs + 1] = x return x end
		function dg.width(i)
			local f = (i - 1) / (NJ - 1)
			return sc * (f < 0.1 and (2.9 + 15 * f) or (4.4 * (1 - ((f - 0.1) / 0.9) ^ 1.3) + 0.3))
		end
		local HORN = C1:Lerp(Color3.new(0, 0, 0), 0.88)
		local mv, mvCF = {}, {}
		local function part(props)
			local p = keep(L.part(props))
			p.Transparency = 1
			mv[#mv + 1] = p
			return p, #mv
		end

		local rockMeshes = {}
		local function rockMesh(scale)
			local p, ix = part({ Size = Vector3.one, Material = Enum.Material.SmoothPlastic })
			local m = L.new("SpecialMesh", { MeshType = Enum.MeshType.FileMesh, MeshId = L.T("sphere.mesh"), TextureId = L.T("lavarock3.png"), Scale = scale }, p)
			rockMeshes[#rockMeshes + 1] = m
			return p, ix, m
		end
		local function spike(len, col, mat)
			local p, ix = part({ Size = Vector3.one * 0.2, Material = mat or Enum.Material.Neon, Color = col })
			local m = L.new("SpecialMesh", { MeshType = Enum.MeshType.FileMesh, MeshId = L.T("shard.mesh") }, p)
			return p, ix, m
		end

		local balls, cyls, belly, spines = {}, {}, {}, {}
		for i = 1, NJ do
			local w = dg.width(i)
			local p, ix = rockMesh(Vector3.one * w)
			balls[i] = { p = p, ix = ix }
		end
		for i = 1, NJ - 1 do
			local w = (dg.width(i) + dg.width(i + 1)) * 0.5
			local p, ix, m = rockMesh(Vector3.new(w, w, 1))
			cyls[i] = { p = p, ix = ix, w = w, len = 1, m = m }
			local bp, bix = part({ Shape = Enum.PartType.Cylinder, Material = Enum.Material.Neon, Color = C2, Size = Vector3.new(1, w * 0.62, w * 0.62) })
			belly[i] = { p = bp, ix = bix, w = w * 0.62, len = 1 }
		end
		for i = 2, NJ - 2 do
			local w = dg.width(i)
			local p, ix, m = spike(w, HORN, Enum.Material.Slate)
			m.Scale = Vector3.new(0.14, 0.5, 0.14) * w
			spines[#spines + 1] = { j = i, p = p, ix = ix, w = w }
		end


		local SCUTE, OBS, IVORY = Color3.fromRGB(30, 21, 19), Color3.fromRGB(15, 11, 10), Color3.fromRGB(230, 212, 180)
		local scutes = {}
		for i = 1, NJ - 1 do
			local w = cyls[i].w
			local p, ix = part({ Material = Enum.Material.Slate, Color = SCUTE, Size = Vector3.new(1, 0.09, 0.5) * w })
			scutes[i] = { p = p, ix = ix, w = w }
		end
		for _, sp in ipairs(spines) do
			sp.p.Color = OBS
			local p, ix, m = spike(1, C1:Lerp(Color3.new(0, 0, 0), 0.2), Enum.Material.Neon)
			m.Scale = Vector3.new(0.05, 0.16, 0.05) * sp.w
			sp.tix = ix
		end
		local legs = {}
		if sc >= 0.2 then
			for li, j in ipairs({ math.max(3, math.floor(NJ * 0.17) + 1), math.floor(NJ * 0.5) }) do
				for s = -1, 1, 2 do
					local w = dg.width(j) * (li == 1 and 1 or 0.95)
					local lg = { j = j, s = s, w = w, L1 = 0.38 * w, L2 = 0.3 * w, ph = li * 1.9 + (s + 1) * 0.6, talons = {} }
					local _, a = rockMesh(Vector3.new(0.3 * w, 0.3 * w, lg.L1 * 1.2)) lg.upix = a
					local _, b = rockMesh(Vector3.new(0.24 * w, 0.24 * w, lg.L2 * 1.2)) lg.foix = b
					local _, c = rockMesh(Vector3.one * 0.32 * w) lg.elix = c
					local _, f = rockMesh(Vector3.new(0.3 * w, 0.17 * w, 0.36 * w)) lg.ftix = f
					local _, e, em = spike(1, OBS, Enum.Material.Slate) em.Scale = Vector3.new(0.08, 0.3, 0.08) * w lg.espix = e
					for k = -1, 1 do
						local _, tix, tm = spike(1, IVORY, Enum.Material.SmoothPlastic)
						tm.Scale = Vector3.new(0.07, 0.3 - 0.05 * math.abs(k), 0.07) * w
						lg.talons[#lg.talons + 1] = { ix = tix, k = k }
					end
					legs[#legs + 1] = lg
				end
			end
		end
		local blade = {}
		for k = -1, 1 do
			local _, ix, m = spike(1, k == 0 and C1:Lerp(Color3.new(0, 0, 0), 0.2) or OBS, k == 0 and Enum.Material.Neon or Enum.Material.Slate)
			m.Scale = Vector3.new(0.35, k == 0 and 1.6 or 1.2, 0.12) * sc
			blade[#blade + 1] = { ix = ix, k = k }
		end



		local hw = sc * 4.4 * 1.1
		local head, jawG, hot = {}, {}, {}
		local function H(x, y, z) return Vector3.new(x, y, z) * hw end
		local DARK, PLATE, HORN2, BONE = Color3.fromRGB(24, 16, 14), Color3.fromRGB(17, 12, 11), Color3.fromRGB(15, 11, 10), Color3.fromRGB(230, 212, 180)
		local EYE = Color3.fromRGB(255, 196, 70)
		local SEAM = C1:Lerp(C2, 0.3)
		local function mk(cls, size, mat, col)
			local p = Instance.new(cls)
			p.Anchored, p.CanCollide, p.CanQuery, p.CanTouch, p.CastShadow = true, false, false, false, false
			p.Size, p.Material, p.Color, p.Transparency = size * hw, mat, col, 1
			p.CFrame = CFrame.new(L.ch.feet or Vector3.zero)
			p.Parent = L.root
			keep(p)
			mv[#mv + 1] = p
			return p, #mv
		end
		local function C(x, y, z, rx, ry, rz) return CFrame.new(x * hw, y * hw, z * hw) * CFrame.Angles(rx or 0, ry or 0, rz or 0) end
		local function at(grp, cf, p, ix) grp[#grp + 1] = { p = p, ix = ix, cf = cf } return p end
		local function box(grp, cls, size, cf, mat, col)
			local p, ix = mk(cls, size, mat, col)
			if mat == Enum.Material.Neon then hot[#hot + 1] = { p = p, col = col } end
			return at(grp, cf, p, ix)
		end
		local function ball(grp, size, cf, mat, col)
			local p, ix = mk("Part", size, mat, col)
			L.new("SpecialMesh", { MeshType = Enum.MeshType.Sphere }, p)
			if mat == Enum.Material.Neon then hot[#hot + 1] = { p = p, col = col } end
			return at(grp, cf, p, ix)
		end

		local function shardAt(grp, root, dir, len, w, mat, col)
			local p, ix = mk("Part", Vector3.one * 0.05, mat, col)
			L.new("SpecialMesh", { MeshType = Enum.MeshType.FileMesh, MeshId = L.T("shard.mesh"), Scale = Vector3.new(w, len, w) * hw }, p)
			if mat == Enum.Material.Neon then hot[#hot + 1] = { p = p, col = col } end
			dir = dir.Unit
			local mid = root + dir * len * 0.5
			local r = CFrame.lookAt(Vector3.zero, dir, math.abs(dir.Y) > 0.98 and Vector3.zAxis or Vector3.yAxis) * CFrame.Angles(-math.pi / 2, 0, 0)
			return at(grp, CFrame.new(mid * hw) * r, p, ix)
		end

		local function horn(root, d0, d1, lens, wids)
			local p, n = root, #lens
			for k = 1, n do
				local d = d0:Lerp(d1, (k - 1) / math.max(1, n - 1)).Unit
				if k < n then
					local q, ix = mk("Part", Vector3.new(lens[k] * 1.15, wids[k], wids[k]), Enum.Material.Slate, HORN2)
					q.Shape = Enum.PartType.Cylinder
					local mid = p + d * lens[k] * 0.5
					at(head, CFrame.lookAt(mid * hw, (mid + d) * hw) * CFrame.Angles(0, math.pi / 2, 0), q, ix)
				else
					shardAt(head, p - d * 0.03, d, lens[k], wids[k], Enum.Material.Slate, HORN2)
					shardAt(head, p + d * lens[k] * 0.62, d, lens[k] * 0.4, wids[k] * 0.45, Enum.Material.Neon, C1:Lerp(Color3.new(0, 0, 0), 0.25))
				end
				p += d * lens[k]
			end
		end
		local B, S, N = Enum.Material.Basalt, Enum.Material.Slate, Enum.Material.Neon

		box(head, "Part", Vector3.new(0.8, 0.42, 0.75), C(0, 0.12, 0.2), B, DARK)
		box(head, "WedgePart", Vector3.new(0.8, 0.22, 0.75), C(0, 0.44, 0.2), B, DARK)
		box(head, "Part", Vector3.new(0.52, 0.24, 0.9), C(0, 0.02, -0.62), B, DARK)
		box(head, "WedgePart", Vector3.new(0.52, 0.16, 0.9), C(0, 0.22, -0.62), B, DARK)
		box(head, "WedgePart", Vector3.new(0.52, 0.24, 0.2), C(0, 0.02, -1.17), B, DARK)
		box(head, "Part", Vector3.new(0.72, 0.5, 0.22), C(0, 0.2, 0.62, 0.35, 0, 0), S, PLATE)

		local function seamLine(a, b, w)
			local mid, d = (a + b) * 0.5, b - a
			box(head, "Part", Vector3.new(w, 0.018, d.Magnitude), CFrame.lookAt(mid * hw, (mid + d.Unit) * hw), N, SEAM)
		end
		seamLine(Vector3.new(0, 0.145, -1.06), Vector3.new(0, 0.305, -0.18), 0.035)
		seamLine(Vector3.new(0, 0.335, -0.17), Vector3.new(0, 0.555, 0.57), 0.045)
		box(head, "Part", Vector3.new(0.4, 0.02, 0.85), C(0, -0.105, -0.6), N, SEAM)
		for s = -1, 1, 2 do

			local tilt = -0.25
			box(head, "Part", Vector3.new(0.035, 0.08, 0.28), C(s * 0.405, 0.2, -0.01, tilt, 0, 0), Enum.Material.SmoothPlastic, Color3.fromRGB(12, 6, 5))
			local e = ball(head, Vector3.new(0.05, 0.06, 0.24), C(s * 0.418, 0.2, -0.01, tilt, 0, 0), N, EYE)
			dg.eyes[#dg.eyes + 1] = e
			box(head, "Part", Vector3.new(0.02, 0.058, 0.025), C(s * 0.442, 0.2, -0.02, tilt, 0, 0), Enum.Material.SmoothPlastic, Color3.new(0, 0, 0))

			box(head, "Part", Vector3.new(0.16, 0.09, 0.44), C(s * 0.37, 0.31, -0.03, tilt, 0, s * -0.4), S, PLATE)
			box(head, "WedgePart", Vector3.new(0.14, 0.1, 0.3), C(s * 0.3, 0.37, -0.18, 0, s * 0.15, 0), S, PLATE)
			box(head, "Part", Vector3.new(0.09, 0.32, 0.55), C(s * 0.43, 0.0, 0.32, 0, s * 0.3, 0), S, PLATE)

			box(head, "WedgePart", Vector3.new(0.12, 0.08, 0.2), C(s * 0.17, 0.17, -0.98), B, DARK)
			ball(head, Vector3.new(0.07, 0.045, 0.09), C(s * 0.16, 0.15, -1.09), N, C1)

			box(head, "Part", Vector3.new(0.022, 0.03, 0.95), C(s * 0.262, -0.085, -0.6), N, SEAM)
			for k, z in ipairs({ -0.3, -0.5, -0.68, -0.85 }) do
				local l = 0.07 + 0.012 * k
				shardAt(head, Vector3.new(s * 0.235, -0.095, z), Vector3.new(0, -1, 0.1), l, 0.045, Enum.Material.SmoothPlastic, BONE)
			end
			shardAt(head, Vector3.new(s * 0.232, -0.09, -0.99), Vector3.new(0, -1, 0.22), 0.22, 0.065, Enum.Material.SmoothPlastic, BONE)

			horn(Vector3.new(s * 0.27, 0.46, 0.3), Vector3.new(s * 0.28, 0.35, 1), Vector3.new(s * 0.12, 1, 0.45), { 0.3, 0.26, 0.22, 0.24 }, { 0.15, 0.12, 0.09, 0.08 })
			horn(Vector3.new(s * 0.36, 0.26, 0.45), Vector3.new(s * 0.65, 0.05, 1), Vector3.new(s * 0.45, 0.35, 0.8), { 0.2, 0.17, 0.18 }, { 0.09, 0.07, 0.06 })

			for k, y in ipairs({ 0.12, -0.02, -0.15 }) do
				shardAt(head, Vector3.new(s * 0.44, y, 0.5), Vector3.new(s * 0.7, 0.15 - 0.2 * k, 1), 0.36 - 0.06 * k, 0.07, S, HORN2)
			end
		end

		for k, z in ipairs({ 0.12, 0.32, 0.52 }) do
			local top = 0.33 + 0.22 * (z + 0.175) / 0.75
			shardAt(head, Vector3.new(0, top - 0.02, z), Vector3.new(0, 1, 0.9), 0.24 - 0.04 * k, 0.07, S, HORN2)
		end

		box(jawG, "Part", Vector3.new(0.42, 0.12, 1), C(0, -0.04, -0.75), B, DARK)
		box(jawG, "Part", Vector3.new(0.46, 0.15, 0.32), C(0, -0.03, -0.12), B, DARK)
		box(jawG, "WedgePart", Vector3.new(0.42, 0.12, 0.2), C(0, -0.04, -1.35, 0, 0, math.pi), B, DARK)
		box(jawG, "Part", Vector3.new(0.34, 0.02, 0.95), C(0, 0.025, -0.75), N, SEAM)
		for s = -1, 1, 2 do
			box(jawG, "Part", Vector3.new(0.02, 0.025, 1), C(s * 0.212, 0.012, -0.75), N, SEAM)
			for k, z in ipairs({ -0.55, -0.78, -1.0, -1.18 }) do
				shardAt(jawG, Vector3.new(s * 0.17, 0.0, z), Vector3.new(0, 1, -0.05), 0.075 + 0.008 * k, 0.04, Enum.Material.SmoothPlastic, BONE)
			end
			shardAt(jawG, Vector3.new(s * 0.14, 0.0, -1.34), Vector3.new(0, 1, -0.15), 0.15, 0.05, Enum.Material.SmoothPlastic, BONE)
		end
		for k, x in ipairs({ -0.12, 0, 0.12 }) do
			shardAt(jawG, Vector3.new(x, -0.09, -0.55 + 0.1 * math.abs(x) / 0.12), Vector3.new(x, -1, 0.7), 0.22 - 0.04 * math.abs(x) / 0.12, 0.05, S, HORN2)
		end

		local whisk = {}
		for s = -1, 1, 2 do
			local a0, a1 = keep(L.att()), keep(L.att())
			local b = keep(L.beam(a0, a1, { Texture = L.T("softbeam.png"), Width0 = 0.16 * hw, Width1 = 0.02, Segments = 12, Brightness = 3, LightEmission = 1,
				FaceCamera = true, Color = CS(C2:Lerp(W, 0.3), C1), Transparency = NS(1) }))
			whisk[#whisk + 1] = { s = s, a0 = a0, a1 = a1, b = b }
		end

		dg.hp = keep(L.part({ Size = Vector3.one }))
		dg.light = L.new("PointLight", { Color = C2, Range = 50 * sc / 1.3, Brightness = 0, Shadows = false }, dg.hp)
		local mo = L.new("Attachment", { Position = Vector3.new(0, -0.1, -1.25) * hw }, dg.hp)
		dg.breath = flameE(mo, { EmissionDirection = Enum.NormalId.Front, Rate = 0, Speed = NR(30, 45), SpreadAngle = Vector2.new(10, 10),
			Lifetime = NR(0.3, 0.5), Size = NS({ K(0, 1.5 * sc / 1.3), K(0.4, 5 * sc / 1.3), K(1, 8 * sc / 1.3) }), Acceleration = Vector3.zero, Brightness = 3 })
		local glints = {}
		for s = -1, 1, 2 do
			local ea = L.new("Attachment", { Position = Vector3.new(s * 0.46, 0.2, -0.01) * hw }, dg.hp)
			glints[#glints + 1] = L.pe(ea, { Texture = L.T("flare.png"), Color = CS(EYE), LightEmission = 1, Brightness = 3, Rate = 0, Speed = NR(0),
				Lifetime = NR(0.05, 0.08), Size = NS(0.32 * hw), LockedToPart = true })
		end
		local crestA = L.new("Attachment", { Position = Vector3.new(0, 0.55, 0.45) * hw }, dg.hp)
		local crest = flameE(crestA, { Rate = 0, Speed = NR(1, 3), Lifetime = NR(0.3, 0.5), SpreadAngle = Vector2.new(25, 25),
			Size = NS({ K(0, 0.5 * hw), K(0.4, 0.7 * hw), K(1, 0.1) }), Acceleration = Vector3.new(0, 4, 0) })
		for _, j in ipairs({ 3, 7, 11, 15, 19, 23 }) do
			if j < NJ - 1 then
				local p = keep(L.part({ Size = Vector3.new(1, 0.4, 1) * dg.width(j) }))
				dg.fire[#dg.fire + 1] = { j = j, p = p,
					fe = flameE(p, { Shape = Enum.ParticleEmitterShape.Box, EmissionDirection = Enum.NormalId.Top, Rate = 0, Speed = NR(1, 3), Lifetime = NR(0.3, 0.55),
						Size = NS({ K(0, 1.4 * sc), K(0.4, 1.9 * sc), K(1, 0.3 * sc) }), Acceleration = Vector3.new(0, 3, 0) }),
					ee = emberE(p, { Shape = Enum.ParticleEmitterShape.Box, Rate = 0, Speed = NR(1, 4), Lifetime = NR(0.8, 1.6) }) }
			end
		end
		local tailP = keep(L.part({ Size = Vector3.one * 0.5 }))
		local tailF = flameE(tailP, { Rate = 0, Speed = NR(2, 4), Lifetime = NR(0.3, 0.5), SpreadAngle = Vector2.new(30, 30), EmissionDirection = Enum.NormalId.Back,
			Size = NS({ K(0, 1.2 * sc), K(0.4, 1.8 * sc), K(1, 0.2) }), Acceleration = Vector3.new(0, 2, 0) })

		local lastTr = -1
		local function setTr(tr)
			if math.abs(tr - lastTr) < 0.005 and math.abs(mv[1].Transparency - tr) < 0.005 then return end
			lastTr = tr
			for _, p in ipairs(mv) do p.Transparency = tr end
		end
		local function bodyUp(d)
			local side = d:Cross(Vector3.yAxis)
			return side.Magnitude > 0.01 and side:Cross(d).Unit or Vector3.xAxis
		end
		local lastGlow = -1

		function dg.set(J, tr, glow, t, jaw, breath)
			setTr(tr)
			if math.abs(glow - lastGlow) > 0.01 then
				lastGlow = glow
