			end
			for i = 1, NJ do mvCF[balls[i].ix] = CFrame.new(J[i]) end
			for i = 1, NJ - 1 do
				local a, b = J[i], J[i + 1]
				local d = a - b
				local len = d.Magnitude
				local c, bl = cyls[i], belly[i]
				if len < 0.02 then
					mvCF[c.ix], mvCF[bl.ix], mvCF[scutes[i].ix] = CFrame.new(a), CFrame.new(a), CFrame.new(a)
				else
					local dn = d / len
					local up = bodyUp(dn)
					local axis = CFrame.lookAt((a + b) * 0.5, a, up) * CFrame.Angles(0, math.pi / 2, 0)
					mvCF[c.ix] = CFrame.lookAt((a + b) * 0.5, a, up)
					mvCF[bl.ix] = axis - up * c.w * 0.22
					if math.abs(len - c.len) > 0.05 then
						c.len, bl.len = len, len
						c.m.Scale = Vector3.new(c.w, c.w, len * 1.3 + c.w * 0.55)
						bl.p.Size = Vector3.new(len, bl.w, bl.w)
						scutes[i].p.Size = Vector3.new(len * 0.62, scutes[i].w * 0.07, scutes[i].w * 0.46)
					end
					mvCF[scutes[i].ix] = axis - up * c.w * 0.45

					local wave = math.max(0, math.sin(t * 7 - i * 0.45)) ^ 10
					local f = (i - 0.5) / (NJ - 1)
					bl.p.Color = C2:Lerp(C1, f * 0.8):Lerp(W, 0.45 * glow + 0.4 * wave)
				end
			end
			for _, sp in ipairs(spines) do
				local j = sp.j
				local d = J[j - 1] - J[j + 1]
				if d.Magnitude < 0.02 then mvCF[sp.ix], mvCF[sp.tix] = CFrame.new(J[j]), CFrame.new(J[j]) else
					d = d.Unit
					local up = bodyUp(d)
					local tip = (up * 0.85 - d * 0.5).Unit
					local cf = CFrame.fromMatrix(J[j] + up * sp.w * 0.38 + tip * sp.w * 0.3, d:Cross(tip).Unit, tip)
					mvCF[sp.ix], mvCF[sp.tix] = cf, cf + tip * sp.w * 0.2
				end
			end

			local fwdD = J[1] - J[2]
			if fwdD.Magnitude < 0.02 then fwdD = Vector3.zAxis end
			fwdD = fwdD.Unit
			local upHint = math.abs(fwdD.Y) > 0.97 and Vector3.zAxis or Vector3.yAxis
			local hO = J[1] + fwdD * 0.35 * hw
			local hcf = CFrame.lookAt(hO, hO + fwdD, upHint)
			dg.hp.CFrame = hcf
			for _, hp in ipairs(head) do mvCF[hp.ix] = hcf * hp.cf end
			local ja = -(jaw or 0) * 0.65
			local hinge = hcf * C(0, -0.12, 0.25) * CFrame.Angles(ja, 0, 0)
			for _, jp in ipairs(jawG) do mvCF[jp.ix] = hinge * jp.cf end
			for _, wk in ipairs(whisk) do
				local wv = math.sin(t * 3 + wk.s)
				wk.a0.WorldPosition = (hcf * CFrame.new(H(wk.s * 0.17, 0.14, -1.1))).Position
				wk.a1.WorldPosition = (hcf * CFrame.new(H(wk.s * 1.6, -0.7 + 0.35 * wv, 2.6))).Position
				wk.b.CurveSize0, wk.b.CurveSize1 = 0.8 * hw, -0.8 * hw * wv
				wk.b.Transparency = NS(math.max(tr, 0.15))
			end

			for _, lg in ipairs(legs) do
				local j = lg.j
				local d = J[j - 1] - J[j + 1]
				d = d.Magnitude > 0.02 and d.Unit or Vector3.zAxis
				local up = bodyUp(d)
				local side = d:Cross(up).Unit * lg.s
				local w = lg.w
				local pad = math.sin(t * 3 + lg.ph)
				local S0 = J[j] + side * w * 0.34 - up * w * 0.2
				local E = S0 + (side * 0.5 - up * 0.72 - d * (0.3 - 0.35 * pad)).Unit * lg.L1
				local Wr = E + (-up * 0.75 + d * (0.5 + 0.3 * pad) + side * 0.12).Unit * lg.L2
				mvCF[lg.upix] = CFrame.lookAt((S0 + E) * 0.5, E, up)
				mvCF[lg.foix] = CFrame.lookAt((E + Wr) * 0.5, Wr, up)
				mvCF[lg.elix] = CFrame.new(E)
				local back = (-d + up * 0.3).Unit
				mvCF[lg.espix] = CFrame.lookAt(E + back * w * 0.15, E + back * w * 0.15 + back, side) * CFrame.Angles(-math.pi / 2, 0, 0)
				local fd = (d - up * 0.2).Unit
				mvCF[lg.ftix] = CFrame.lookAt(Wr + fd * w * 0.1, Wr + fd * w, up)
				for _, tl in ipairs(lg.talons) do
					local td = (d * 0.8 - up * 0.6 + side * tl.k * 0.4).Unit
					local root = Wr + fd * w * 0.22 + side * tl.k * w * 0.08
					local c = root + td * w * 0.13
					mvCF[tl.ix] = CFrame.lookAt(c, c + td, up) * CFrame.Angles(-math.pi / 2, 0, 0)
				end
			end

			do
				local d = J[NJ] - J[NJ - 1]
				d = d.Magnitude > 0.02 and d.Unit or Vector3.xAxis
				local up = bodyUp(d)
				local side = d:Cross(up).Unit
				for _, bd in ipairs(blade) do
					local dir = (d + side * bd.k * 0.55).Unit
					local c = J[NJ] + dir * sc * (bd.k == 0 and 0.7 or 0.5)
					mvCF[bd.ix] = CFrame.fromMatrix(c, dir:Cross(up).Unit, dir)
				end
			end
			local tailD = J[NJ] - J[NJ - 1]
			tailP.CFrame = tailD.Magnitude > 0.02 and CFrame.lookAt(J[NJ], J[NJ] - tailD) or CFrame.new(J[NJ])
			workspace:BulkMoveTo(mv, mvCF, Enum.BulkMoveMode.FireCFrameChanged)
			local on = tr < 0.6
			dg.breath.Rate = (on and breath) and 160 or 0
			dg.light.Brightness = on and (5 + 8 * glow) or 0
			dg.light.Color = C2:Lerp(W, glow)
			local fireOn = on and not dg.noFire
			crest.Rate = fireOn and 26 or 0
			for _, g in ipairs(glints) do g.Rate = on and 50 or 0 end
			tailF.Rate = fireOn and 20 or 0
			for _, fp in ipairs(dg.fire) do
				local d = J[fp.j] - J[fp.j + 1]
				local up = d.Magnitude > 0.02 and bodyUp(d.Unit) or Vector3.yAxis
				fp.p.CFrame = d.Magnitude > 0.02 and CFrame.lookAt(J[fp.j] + up * dg.width(fp.j) * 0.3, J[fp.j] + up * dg.width(fp.j) * 0.3 + d, up) or CFrame.new(J[fp.j])
				fp.fe.Rate, fp.ee.Rate = fireOn and 30 or 0, fireOn and 14 or 0
			end
		end
		return dg
	end
