			coreP.Size = Vector3.one * (0.5 + 4.5 * cg * cg)
			coreP.CFrame = CFrame.new(P0)
			coreP.Transparency = (t >= GATHER and t < FORM + 0.15) and (0.2 + 0.8 * c01((t - FORM) / 0.15)) or 1
			coreL.Brightness = (t < FORM + 0.15) and 6 * cg or 0

			local td = t < FREEZE and t or FREEZE
			local glow = t >= DIVE and c01((t - DIVE) / (FREEZE - DIVE)) ^ 2 or 0
			local holding = t >= FREEZE and t < HIT
			if holding ~= held then
				held = holding
				for _, e in ipairs(frozen) do e.TimeScale = holding and 0 or 1 end
			end
			local flying = t >= FORM and t < HIT
			if flying then
				local J = { pathAt(td) }
				local prev, acc, tt, steps = J[1], 0, td, 0
				while #J < NJ and steps < 4000 and tt > FORM - 0.02 do
					tt -= 0.004
					steps += 1
					local p = pathAt(tt)
					acc += (p - prev).Magnitude
					prev = p
					if acc >= SEG then J[#J + 1] = p acc = 0 end
				end
				while #J < NJ do J[#J + 1] = prev end
				headPos, lastJ = J[1], J
				local su = (t - SWOOP) / (CIRC - SWOOP)
				dragon.set(J, 0.05, glow, t, holding and 1 or 0.2 + 0.12 * math.sin(t * 3), su > 0.25 and su < 0.65)
			end

