				streak.Transparency, streak2.Transparency = NS(1 - 0.9 * sv0), NS(1 - 0.55 * sv0)
			end

			for i, e in ipairs(ringE) do e.Rate = (t > CIRC + i * 0.12 and t < BURST + 1.6) and 18 or 0 end
