			gcm.Scale = Vector3.new(gs, 1, gs)
			gc.CFrame = CFrame.new(o + Vector3.new(0, 0.07, 0))
			gc.Transparency = 1 - 0.85 * c01((t - CIRC) / 0.6) * (1 - c01((t - DUR + 1.4) / 1.2))

			if not hit and t >= HIT then
				hit = true
				S:flash(C2:Lerp(W, 0.6), 0.8) S:shake(1.6, 0.5)
				L.groundWave(o, "ring_c.png", W, 4, 60, 0.7)
				L.groundWave(o, "ring_c.png", C2, 4, 36, 0.9)
				L.groundWave(o, "cracks_b.png", C1, 4, 26, 2.2, 2.4)
				burst:Emit(120)
				local fb = own(L.part({ Transparency = 0, Material = Enum.Material.Neon, Color = W, CFrame = CFrame.new(o) }))
				local fbm = L.new("SpecialMesh", { MeshType = Enum.MeshType.Sphere }, fb)
				L.fx(0.55, function(kk) local s = (2 + 26 * L.outQuad(kk / 0.5)) * 10 fbm.Scale = Vector3.new(s, s * 0.8, s)
					fb.Color = W:Lerp(C2, kk) fb.Transparency = c01(kk * 1.6 - 0.2) end, {})
