				for _, b in ipairs(blocks) do b.p.Transparency = 0 end
				coilFrom = lastJ
				mk = {}
				local prevP
				for i = 0, 18 do
					local f = i / 18
					local a = f * math.pi * 3.2
					local rr = 3 + 11 * f
					local p = o + Vector3.new(math.cos(a) * rr, 0.06, math.sin(a) * rr)
					if prevP then
						local ax = (p - prevP).Unit
						local a0, a1 = own(L.att()), own(L.att())
						a0.WorldCFrame = CFrame.fromMatrix(prevP, ax, Vector3.yAxis:Cross(ax))
						a1.WorldCFrame = CFrame.fromMatrix(p, ax, Vector3.yAxis:Cross(ax))
						mk[#mk + 1] = own(L.beam(a0, a1, { Texture = L.T("dragonbody.png"), TextureMode = Enum.TextureMode.Wrap, TextureLength = 5, TextureSpeed = 0, FaceCamera = false,
							Width0 = 4.6 * (1 - 0.8 * (f - 1 / 18)), Width1 = 4.6 * (1 - 0.8 * f), LightEmission = 0.35, Brightness = 2, Segments = 2 }))
					end
					prevP = p
				end
			end
			if mk then
