				wisp.Rate = 6
				local heat = c01((t - HIT - 0.6) / (BURST - HIT - 0.6))
				local pulse0 = math.exp(-(t - lastBeat) * 7)

				local CJ = { o + Vector3.new(0, PH + 9, 0) - fwd * 2, o + Vector3.new(0, PH + 7.6, 0) - fwd * 3.2 }
