					b.p.Color = C2:Lerp(ASH, cool)
					b.p.Material = cool < 0.5 and Enum.Material.Neon or Enum.Material.Basalt
					b.p.CFrame = b.cf0 + b.n * (0.06 * heat + 0.12 * pulse0 * heat) * math.sin(t * 40 + b.cf0.Position.Y)
				end
				leak.Rate = 30 * heat
				for _, c in ipairs(cracks) do
					local g = c01((t - c.at) / 0.35)
					c.p.Size = Vector3.new(math.max(0.05, c.len * L.outQuad(g)), 0.18 + 0.1 * heat, 0.06)
					c.p.CFrame = c.cf
					c.p.Transparency = g > 0 and 0 or 1
					c.p.Color = C2:Lerp(W, 0.2 * heat)
				end
				if t >= lastBeat + 0.55 - 0.3 * heat and t > HIT + 0.9 then
					lastBeat = t
					L.punch(0.25, 0.12, C1, 0.1 + 0.15 * heat)
					leak:Emit(10)
				end
				pilL.Brightness = 1 + 5 * heat + 6 * math.exp(-(t - lastBeat) * 7)
			end

			if hit and not burstD and t >= BURST then
				burstD = true
				S:flash(W, 0.85) S:shake(2.4, 0.6)
				appear(C2, hideTok)
				pil.Transparency, cap.Transparency, wisp.Rate, leak.Rate = 1, 1, 0, 0
				for _, c in ipairs(cracks) do c.p.Transparency = 1 end
				for i, b in ipairs(blocks) do
					chunks[i] = { p = b.p, p0 = b.p.Position, rot = b.p.CFrame.Rotation, v = b.n * rnd(18, 32) + Vector3.new(0, rnd(6, 20), 0), sp = Vector3.new(rnd(-9, 9), rnd(-9, 9), rnd(-9, 9)), hot = b.hot }
					if b.hot then b.p.Material, b.p.Color = Enum.Material.Neon, C2 end
				end
				burst:Emit(160)
				for _, fp in ipairs(dragon.fire) do fp.fe:Emit(25) fp.ee:Emit(20) end
				L.groundWave(o, "ring_c.png", W, 4, 70, 0.7)
				L.groundWave(o, "ring_c.png", C2, 4, 40, 1)
				L.groundWave(o + Vector3.new(0, 5, 0), "ring_c.png", C2:Lerp(W, 0.4), 6, 130, 1.1, 2.6)
				L.groundWave(o, "ring_c.png", C1, 10, 1400, 5.4, 2.6)
				local col, colTop = own(L.att(o)), own(L.att(o + Vector3.new(0, 70, 0)))
				local bm = own(L.beam(col, colTop, { Width0 = 9, Width1 = 3, Brightness = 5, Color = CS({ CK(0, W), CK(0.4, C2), CK(1, C1) }), Segments = 2 }))
				L.fx(1.3, function(kk) bm.Transparency = NS(c01(kk * 1.2)) bm.Width0 = 9 * (1 - kk * 0.7) end, {})
				wg = featherWings()
				for _, x in ipairs(wg.objs) do own(x) end
			end
			if burstD then
				local q = t - BURST

				if lastCoil and not dragonGone then
					local top = lastCoil[1]
					local function H(qq) local k = c01(qq / 0.3) return top + Vector3.new(math.sin(qq * 4) * 5 * k, 22 * qq + 18 * qq * qq, (math.cos(qq * 4) - 1) * 5 * k) end
					local pts = {}
					local qq = q
					while qq > 0 and #pts < 600 do pts[#pts + 1] = H(qq) qq -= 0.01 end
					for i = 1, NJ do pts[#pts + 1] = lastCoil[i] end
					local J3, acc, prev = { pts[1] }, 0, pts[1]
					for i = 2, #pts do
						if #J3 >= NJ then break end
						local p = pts[i]
						acc += (p - prev).Magnitude
						prev = p
						if acc >= SEG then J3[#J3 + 1] = p acc = 0 end
					end
					while #J3 < NJ do J3[#J3 + 1] = prev end
					local dtr = c01((q - 2) / 0.7)
					dragon.set(J3, 0.05 + 0.95 * dtr, 0.4 + 0.6 * math.exp(-q * 2.5), t, 1, q < 1.8)
					if dtr >= 1 then dragonGone = true end
				end
				for _, c in ipairs(chunks) do
					local pos = c.p0 + c.v * q + Vector3.new(0, -45 * q * q, 0)
					if pos.Y < o.Y + 0.2 then pos = Vector3.new(pos.X, o.Y + 0.2, pos.Z) end
					c.p.CFrame = CFrame.new(pos) * c.rot * CFrame.Angles(c.sp.X * q, c.sp.Y * q, c.sp.Z * q)
					c.p.Transparency = c01((q - 1) / 0.6)
					if c.hot then c.p.Color = C2:Lerp(ASH, c01(q / 0.8)) end
				end
				local openW = L.outBack(c01(q / 0.35))
				local fade = c01((t - (DUR - 1.6)) / 1)
				wg.back(ch.hrp.CFrame, openW, math.sin(q * 5) * 0.25 * math.exp(-q * 0.8), 8 * (1 - 0.3 * fade), 0.06 + 0.94 * fade, 1 - c01(q / 0.4), t)
				light.Brightness = math.max(light.Brightness, 4 * (1 - fade))
			end
		end, objs)
	end






