		local D = o - fwd * 170 + rt * 25
		local Dg = Vector3.new(D.X, o.Y - DEPTH - 40, D.Z)
		local Rp = o + fwd * 45
		local tunA, tunC = Vector3.new(D.X, o.Y - DEPTH, D.Z), o - fwd * 40 + rt * 55
		local tunB = Vector3.new(Rp.X, o.Y - DEPTH, Rp.Z)
		local towerTop = Rp + Vector3.new(0, 125, 0)
		local loomP = o + fwd * 24 + Vector3.new(0, 58, 0)
		local strikeDir = (o + Vector3.new(0, 3, 0) - loomP).Unit
		local roarP = loomP + strikeDir * 3
		local function bez(a, c, b, u) local v = 1 - u return a * v * v + c * 2 * u * v + b * u * u end
		local function pathAt(tt)
			if tt < EMERGE then return crater - Vector3.new(0, 30 + 70 * (EMERGE - tt), 0) end
			if tt < ARC then
				local u = (tt - EMERGE) / (ARC - EMERGE)
				local h = -30 + 125 * L.outQuad(c01(u / 0.55))
				local sway = c01((u - 0.45) / 0.3) * math.sin((u - 0.45) * 9) * 14
				return crater + Vector3.new(0, h, 0) + rt * sway - fwd * 10 * c01((u - 0.4) / 0.6)
			end
			if tt < TUNNEL then
				local u = (tt - ARC) / (TUNNEL - ARC)
				return bez(skyTop, o + Vector3.new(0, 230, 0), Dg, u)
			end
			if tt < RISE then
				local u = (tt - TUNNEL) / (RISE - TUNNEL)
				local p = bez(tunA, Vector3.new(tunC.X, o.Y - DEPTH, tunC.Z), tunB, u)
				return p - Vector3.new(0, 30 * (1 - c01(u / 0.12)), 0)
			end
			if tt < LOOM then
				local u = L.outQuad((tt - RISE) / (LOOM - RISE))
				return Vector3.new(Rp.X, o.Y - DEPTH, Rp.Z):Lerp(towerTop, u)
			end
			if tt < ROAR then
				local u = L.outQuad((tt - LOOM) / (ROAR - LOOM))
				return bez(towerTop, towerTop + Vector3.new(0, 25, 0) - fwd * 25, loomP, u)
			end
			if tt < DIVE then
				local u = (tt - ROAR) / (DIVE - ROAR)
				return loomP:Lerp(roarP, u)
			end
			local u = L.inQuad(c01((tt - DIVE) / (REVEAL - DIVE)))
			return roarP:Lerp(o + Vector3.new(0, 2, 0), u)
		end
		local function bodyAt(tt)
			local J = { pathAt(tt) }
			local prev, acc, q, steps = J[1], 0, tt, 0
			while #J < NJ and steps < 6000 do
				q -= 0.004
				steps += 1
				local p = pathAt(q)
				acc += (p - prev).Magnitude
				prev = p
				if acc >= SEG then J[#J + 1] = p acc = 0 end
			end
			while #J < NJ do J[#J + 1] = prev end
			return J
		end

		local vent = own(L.part({ Size = Vector3.new(14, 0.2, 14) }))
		local ventF = flameE(vent, { Shape = Enum.ParticleEmitterShape.Box, EmissionDirection = Enum.NormalId.Top, Rate = 0, Speed = NR(18, 34),
			Lifetime = NR(0.5, 0.8), Size = NS({ K(0, 4), K(0.3, 9), K(1, 1.5) }) })
		local ventS = smokeE(vent, { EmissionDirection = Enum.NormalId.Top, Rate = 0, Speed = NR(10, 18), Size = NS({ K(0, 8), K(1, 24) }), Lifetime = NR(1.5, 2.2) })
		local ventE = emberE(vent, { Shape = Enum.ParticleEmitterShape.Box, Rate = 0, Speed = NR(14, 26), Lifetime = NR(0.8, 1.4) })
		local seams = {}
		local function seam(p)
			local sp, sm = L.mesh("disc.mesh", "cracks_b.png", W, 3, Vector3.new(26, 1, 26))
			own(sp)
			sp.CFrame = CFrame.new(p) * CFrame.Angles(0, rnd(0, 6.28), 0)
			seams[#seams + 1] = { p = sp, m = sm, t0 = 0 }
			return seams[#seams]
		end
		local plates, plateI = {}, 0
		for i = 1, 30 do plates[i] = { p = wedge(Vector3.new(rnd(9, 15), rnd(3.5, 6), rnd(9, 13)), BASALT, Enum.Material.Basalt), t0 = -9 } end

		local pillars = {}
		for i = 1, 16 do
			local a = math.atan2(-fwd.Z, -fwd.X) + 0.75 + (i - 0.5) / 16 * (math.pi * 2 - 1.5)
			local h = rnd(9, 18)
			local p = own(L.part({ Material = Enum.Material.Basalt, Color = Color3.fromRGB(32, 22, 19), Size = Vector3.new(rnd(2.5, 4), h, rnd(2.5, 4)) }))
			local cap = own(L.part({ Material = Enum.Material.Neon, Color = C2, Size = Vector3.new(p.Size.X * 0.9, 0.5, p.Size.Z * 0.9) }))
			local dir = Vector3.new(math.cos(a), 0, math.sin(a))
			pillars[i] = { p = p, cap = cap, base = o + dir * rnd(7, 15), axis = UP:Cross(dir).Unit, h = h, lean = rnd(0.25, 0.5), d = rnd(0, 0.15), yaw = rnd(0, 6.28) }
		end
		local colP = own(L.part({ Size = Vector3.new(4, 0.2, 4), CFrame = CFrame.new(o + Vector3.new(0, 1, 0)) }))
		local colS = smokeE(colP, { Shape = Enum.ParticleEmitterShape.Box, EmissionDirection = Enum.NormalId.Top, Rate = 0, Speed = NR(7, 11), Lifetime = NR(3, 4),
			Size = NS({ K(0, 3), K(1, 12) }), Acceleration = Vector3.new(0.6, 1.5, 0), Transparency = NS({ K(0, 1), K(0.15, 0.55), K(1, 1) }) })
		local split, emerged, skyRoar, dived, risen, roared, revealed = false, false, false, false, false, false, false
		local dragonGone, wg, lastJ, revealJ = false, nil, nil, nil
		local seamClock, plateClock = 0, 0
		L.fx(DUR, function(k, t)
			local dt = L.lastDt or 0.016
			local sa = skyA(t)
			sky(sa)
			for _, d in ipairs(dome) do d.Transparency = 1 - 0.6 * sa end
			ashE.Rate, skyEmb.Rate = 300 * sa, 80 * sa

			local arcU = c01((t - ARC) / (TUNNEL - ARC))

			local grow = L.outQuad(c01((t - SPLIT) / 1.1))
			local cool = c01((t - COOL) / 2.2)
			local fade = c01((t - (DUR - 1.4)) / 1.2)
			local R = POOL * (0.12 + 0.88 * grow)
			poolM.Scale = Vector3.new(R * 2, 1, R * 2)
			pool.CFrame = CFrame.new(o + Vector3.new(0, 0.06, 0)) * CFrame.Angles(0, t * 0.05, 0)
			L.tint(poolM, W:Lerp(Color3.fromRGB(120, 60, 50), cool), (1.8 + 0.4 * math.sin(t * 5)) * (1 - 0.65 * cool))
			pool.Transparency = grow > 0 and (0.05 + 0.95 * fade) or 1
			poolGM.Scale = Vector3.new(R * 2.3, 1, R * 2.3)
			poolG.CFrame = CFrame.new(o + Vector3.new(0, 0.1, 0))
			poolG.Transparency = grow > 0 and (0.45 + 0.55 * math.max(cool, fade)) or 1
			rimM.Scale = Vector3.new(R * 2.6, 1, R * 2.6)
			rim.CFrame = CFrame.new(o + Vector3.new(0, 0.08, 0)) * CFrame.Angles(0, -t * 0.03, 0)
			rim.Transparency = grow > 0 and (0.15 + 0.85 * math.max(fade, 0.6 * cool)) or 1
			scorchM.Scale = Vector3.new(R * 3.4, 1, R * 3.4)
			scorch.CFrame = CFrame.new(o + Vector3.new(0, 0.03, 0))
			scorch.Transparency = grow > 0 and (0.2 + 0.8 * fade) or 1
			bubble.Rate = (t > SPLIT + 0.4 and t < COOL + 0.6) and 40 or 0
			poolSmoke.Rate = (t > SPLIT and t < DUR - 2) and 10 or 0
			poolL.Brightness = (4 + 2 * math.sin(t * 6)) * grow * (1 - cool)
			if not split and t >= SPLIT then
				split = true
				S:shake(1.6, 1.4)
				L.groundWave(o, "cracks_b.png", W, 3, POOL * 2.4, 1.2, 3)
				L.groundWave(o, "ring_c.png", C2, 2, POOL * 2, 0.8)
			end
			if t > SPLIT and t < EMERGE then S:shake(0.5 + 0.7 * c01((t - SPLIT) / (EMERGE - SPLIT)), 0.1) end

			local erA = 0.6 + 0.4 * (t >= ROAR and 1 or 0)
			for _, v in ipairs(vols) do
				local rise = L.outQuad(c01((t - v.t0) / 1.2))
				local sink = L.inQuad(c01((t - (DUR - 2.2)) / 1.6))
				local y = -v.H * 1.05 * (1 - rise + sink) + (rise < 1 and 0.6 * math.sin(t * 40) or 0)
				v.p.CFrame = CFrame.new(v.base + Vector3.new(0, y, 0)) * CFrame.Angles(0, v.yaw, 0)
				v.p.Transparency = (t >= v.t0 and sink < 1) and 0 or 1
				v.top.CFrame = CFrame.new(v.base + Vector3.new(0, y + v.H * 0.95, 0))
				local on = rise > 0.85 and sink < 0.3 and t < DUR - 1.5
				v.fount.Rate = on and (v.big and 70 or 30) * erA or 0
				v.plume.Rate = on and (v.big and 12 or 5) or 0
				v.emb.Rate = on and (v.big and 60 or 20) * erA or 0
				v.lt.Brightness = on and (5 + 2 * math.sin(t * 7 + v.yaw)) or 0
				if on and not v.blown then v.blown = true v.fount:Emit(v.big and 60 or 25) v.emb:Emit(80) S:shake(v.big and 2 or 0.8, 0.5) end
			end

			if t >= nextBomb and t < REVEAL + 1.2 then launch(t) nextBomb = t + rnd(0.1, 0.22) end
			for _, b in ipairs(bombs) do
				if b.on then
					local u = (t - b.t0) / b.T
					if u >= 1 then
						b.on = false
						b.p.Transparency, b.f.Rate, b.e.Rate = 1, 0, 0
						dropP.CFrame = CFrame.new(b.B)
						drops:Emit(math.floor(8 * b.s))
						L.groundWave(b.B, "cracks_b.png", C1, 1, 4 * b.s, 0.9, 2.2)
						L.groundWave(b.B, "ring_c.png", C2, 0.5, 5 * b.s, 0.4)
					else
						b.p.CFrame = CFrame.new(b.A:Lerp(b.B, u) + UP * b.H * 4 * u * (1 - u))
						b.p.Transparency, b.f.Rate, b.e.Rate = 0, 50, 20
					end
				end
			end

			if not dragonGone and t >= EMERGE - 0.3 then
				local J
				if t < REVEAL then J = bodyAt(t) lastJ = J else revealJ = revealJ or lastJ J = revealJ end
				local glow = 0.15
				if t >= ROAR then glow = 0.5 + 0.5 * c01((t - ROAR) / 0.8) end
				local jaw = 0.25 + 0.15 * math.sin(t * 3)
				if t >= EMERGE + 0.7 and t < EMERGE + 1.35 then jaw = 1 end
				if t >= ROAR - 0.15 and t < DIVE then jaw = 1 elseif t >= DIVE then jaw = 0.75 end
				local tr = 0
				if t >= REVEAL then
					tr = c01((t - REVEAL) / 0.5)
					glow = 1
					if tr >= 1 then dragonGone = true end
				end
				local breath = (t >= EMERGE + 0.75 and t < EMERGE + 1.35) or (arcU > 0.15 and arcU < 0.5)
				dragon.set(J, tr, glow, t, jaw, breath)
			end
			if not emerged and t >= EMERGE + 0.25 then
				emerged = true
				splash(crater, 4)
				MV.fount:Emit(120) MV.emb:Emit(150)
				S:shake(2.4, 0.8)
				L.punch(0.5, 0.2, C1, 0.15)
			end
			if not skyRoar and t >= EMERGE + 0.75 then skyRoar = true S:shake(1.8, 0.7) S:flash(C2, 0.25) end
			if t > ARC and t < TUNNEL then S:shake(0.6 + 0.8 * math.sin(math.pi * arcU), 0.1) end
			if not dived and t >= TUNNEL - 0.15 then dived = true S:shake(2.2, 0.8) L.groundWave(o, "cracks_b.png", C1, 8, 120, 1.6, 2.4) end

			local swim = t >= TUNNEL + 0.1 and t < RISE
			if swim then
				local hp = pathAt(t)
				local hd = hp - pathAt(t - 0.03)
				hd = Vector3.new(hd.X, 0, hd.Z)
				hd = hd.Magnitude > 0.01 and hd.Unit or fwd
				local side = hd:Cross(UP)
				local gp = Vector3.new(hp.X, o.Y + 0.15, hp.Z)
				vent.CFrame = CFrame.new(gp)
				seamClock += dt
				if seamClock > 0.05 then seamClock = 0 seam(gp).t0 = t end
				plateClock += dt
				if plateClock > 0.045 then
					plateClock = 0
					plateI = plateI % #plates + 1
					local pl = plates[plateI]
					local sgn = (plateI % 2 == 0) and 1 or -1
					pl.t0 = t
					pl.cf = CFrame.lookAt(gp + side * sgn * rnd(13, 22), gp + side * sgn * 40) * CFrame.Angles(rnd(0.35, 0.7), rnd(-0.4, 0.4), 0)
				end
				local near = 1 - c01(((gp - o).Magnitude - 20) / 120)
				S:shake(0.5 + 1.6 * near, 0.08)
			end
			ventF.Rate, ventS.Rate, ventE.Rate = swim and 70 or 0, swim and 16 or 0, swim and 30 or 0
			for _, pl in ipairs(plates) do
				local q = t - pl.t0
				if q >= 0 and q < 2.4 and pl.cf then
					local lift = L.outBack(c01(q / 0.25))
					local sink = c01((q - 1.4) / 0.9)
					pl.p.CFrame = pl.cf + Vector3.new(0, -4 + 5 * lift - 7 * sink, 0)
					pl.p.Transparency = 0
				else
					pl.p.Transparency = 1
				end
			end
			for _, s in ipairs(seams) do
				local q = t - s.t0
				local col = q < 0.4 and W:Lerp(C2, q / 0.4) or C2:Lerp(C1, c01((q - 0.4) / 1.6)):Lerp(Color3.fromRGB(40, 12, 4), c01((q - 2) / 2))
				L.tint(s.m, col, 3 * (1 - 0.7 * c01(q / 3)))
				s.p.Transparency = 0.05 + 0.95 * math.max(c01((q - 3.5) / 1.2), fade)
			end

			if not risen and t >= RISE then
				risen = true
				splash(Vector3.new(Rp.X, o.Y, Rp.Z), 4)
				L.groundWave(Rp, "cracks_b.png", W, 10, 90, 1.4, 3)
				S:flash(C2, 0.35) S:shake(3, 0.9)
			end
			if t >= RISE and t < ROAR then S:shake(0.9, 0.1) end

			if not roared and t >= ROAR then
				roared = true
				S:flash(C2:Lerp(W, 0.4), 0.55)
				S:shake(3.6, 1.0)
				local hp = dragon.hp.Position
				local rp, rm = L.mesh("disc.mesh", "ring_c.png", C2, 3)
				local rp2, rm2 = L.mesh("disc.mesh", "ring_c.png", W, 3)
				L.fx(0.8, function(kk)
					local s1, s2 = 10 + 200 * L.outQuad(kk), 6 + 130 * L.outQuad(c01(kk * 1.3))
					rm.Scale, rm2.Scale = Vector3.new(s1, 1, s1), Vector3.new(s2, 1, s2)
					rp.CFrame = CFrame.lookAt(hp, hp - strikeDir) * CFrame.Angles(math.pi / 2, 0, 0)
					rp2.CFrame = rp.CFrame
					rp.Transparency, rp2.Transparency = 0.1 + 0.9 * kk, 0.2 + 0.8 * c01(kk * 1.3)
				end, { rp, rp2 })
				L.groundWave(o, "ring_c.png", C2, 4, 90, 0.8)
				L.groundWave(o, "cracks_b.png", W, 6, 60, 1.2, 3)
			end
			if t >= ROAR and t < DIVE then S:shake(1.4, 0.1) end
			if t >= DIVE and t < REVEAL then S:shake(1.8 * c01((t - DIVE) / (REVEAL - DIVE)) + 0.5, 0.1) end

			if not revealed and t >= REVEAL then
				revealed = true
				revealJ = lastJ
				S:flash(W, 0.95) S:shake(4, 1.0)
				appear(C2, hideTok)
				burst:Emit(200)
				splash(o, 2.2)
				impact(o, 3)
				for _, fp in ipairs(dragon.fire) do fp.fe:Emit(40) fp.ee:Emit(50) end
				for i = 1, NJ, 3 do dropP.CFrame = CFrame.new(revealJ[i]) drops:Emit(10) end
				L.groundWave(o, "ring_c.png", W, 4, 120, 0.7)
				L.groundWave(o, "ring_c.png", C1, 10, 1400, 5.4, 2.6)
				for i = 1, 3 do
					L.after(0.22 * i, function() L.groundWave(o, "ring_c.png", i % 2 == 1 and C2 or C1, 3, 26 + 18 * i, 1.0, 2.6) end)
				end
				local col, colTop = own(L.att(o)), own(L.att(o + Vector3.new(0, 140, 0)))
				local bm = own(L.beam(col, colTop, { Width0 = 14, Width1 = 5, Brightness = 6, Color = CS({ CK(0, W), CK(0.4, C2), CK(1, C1) }), Segments = 2 }))
				L.fx(1.3, function(kk) bm.Transparency = NS(c01(kk * 1.2)) bm.Width0 = 14 * (1 - kk * 0.7) end, {})
				wg = featherWings()
				for _, x in ipairs(wg.objs) do own(x) end
			end
			for _, pl in ipairs(pillars) do
				local q = t - REVEAL - pl.d
				if q >= 0 then
					local up = L.outBack(c01(q / 0.22))
					local sink = L.inQuad(c01((q - 1.7) / 1.0))
					local cfb = CFrame.new(pl.base) * CFrame.fromAxisAngle(pl.axis, pl.lean) * CFrame.Angles(0, pl.yaw, 0)
					local yy = pl.h * 0.5 - pl.h * (1 - up + sink) - 0.3
					pl.p.CFrame = cfb * CFrame.new(0, yy, 0)
					pl.cap.CFrame = cfb * CFrame.new(0, yy + pl.h * 0.5 + 0.2, 0)
					pl.cap.Color = W:Lerp(C2, c01(q / 0.3)):Lerp(C1, c01((q - 0.6) / 1))
					pl.p.Transparency = sink < 1 and 0 or 1
					pl.cap.Transparency = sink < 1 and 0.05 or 1
				else
					pl.p.Transparency, pl.cap.Transparency = 1, 1
				end
			end
			if wg then
				local q = t - REVEAL
				local openW = L.outBack(c01(q / 0.35))
				local wf = c01((t - (DUR - 1.6)) / 1)
				wg.back(ch.hrp.CFrame, openW, math.sin(q * 5) * 0.25 * math.exp(-q * 0.8), 8 * (1 - 0.3 * wf), 0.06 + 0.94 * wf, 1 - c01(q / 0.4), t)
				light.Brightness = math.max(light.Brightness, 4 * (1 - wf))
			end
			colS.Rate = (t > COOL and t < DUR - 1.2) and 14 * c01((t - COOL) / 0.8) or 0
		end, objs)
	end



	local shorts = {}

	local function ghostOf(col, mat)
		local g = L.ghost(col, mat or Enum.Material.Neon, 6, true)
		local parts, hs = {}, {}
		local lo, hi = math.huge, -math.huge
		for _, p in ipairs(g:GetChildren()) do
			if p:IsA("BasePart") then
				parts[#parts + 1] = p
				p.Transparency = 1
				lo, hi = math.min(lo, p.Position.Y - p.Size.Y / 2), math.max(hi, p.Position.Y + p.Size.Y / 2)
			end
		end
		for i, p in ipairs(parts) do hs[i] = (p.Position.Y - lo) / math.max(0.1, hi - lo) end
		return g, parts, hs
	end


	shorts[1] = function()
		local o = ch.feet
		local DUR, IN, OUT, SHOW = 2.9, 0.15, 1.45, 1.75
		local hideTok = setHidden(true)
		local fwd, rt = camBasis()
		local objs = {}
		local function own(x) objs[#objs + 1] = x return x end
		local NJ, SEG = 16, 0.75
		local dg = dragon3D(NJ, 0.45)
		for _, x in ipairs(dg.objs) do own(x) end
		local A = o - rt * 28 + fwd * 5 + Vector3.new(0, 13, 0)
		local B = o + rt * 28 + fwd * 5 + Vector3.new(0, 13, 0)
		local M = o + fwd * 2.5 + Vector3.new(0, 3.2, 0)
		local Ctl = M * 2 - (A + B) / 2
		local function pathAt(tt)
			local u = c01((tt - IN) / (OUT - IN))
			local v = 1 - u
			return A * v * v + Ctl * 2 * u * v + B * u * u
		end

		local line = {}
		for i = -6, 6 do
			local p = own(L.part({ Size = Vector3.new(2.2, 0.2, 2.2), CFrame = CFrame.new(o + rt * (i * 2.1) + Vector3.new(0, 0.2, 0)) }))
			line[#line + 1] = { p = p, x = i * 2.1, lit = -1,
				f = flameE(p, { Shape = Enum.ParticleEmitterShape.Box, EmissionDirection = Enum.NormalId.Top, Rate = 0, Speed = NR(5, 10), Lifetime = NR(0.4, 0.7),
					Size = NS({ K(0, 1.6), K(0.3, 3.2), K(1, 0.5) }) }),
				s = smokeE(p, { EmissionDirection = Enum.NormalId.Top, Rate = 0, Speed = NR(3, 6), Size = NS({ K(0, 2), K(1, 5) }), Lifetime = NR(1, 1.6) }) }
		end
		local scar, scarM = L.mesh("disc.mesh", "cracks_b.png", C2, 2.4) own(scar)
		local shown = false
		L.fx(DUR, function(k, t)
			if t < OUT + 0.4 then
				local J = { pathAt(t) }
				local prev, acc, q = J[1], 0, t
				while #J < NJ and q > IN - 0.5 do
					q -= 0.004
					local p = pathAt(q)
					acc += (p - prev).Magnitude
					prev = p
					if acc >= SEG then J[#J + 1] = p acc = 0 end
				end
				while #J < NJ do J[#J + 1] = prev end
				local hx = (J[1] - o):Dot(rt)
				dg.set(J, c01((t - OUT) / 0.35), 0.4, t, 0.9, math.abs(hx) < 15)
			end
			local hp = pathAt(t)
			local hx = (hp - o):Dot(rt)
			for _, s in ipairs(line) do
				if s.lit < 0 and hx >= s.x - 1 and t > IN then s.lit = t s.f:Emit(10) end
				local q = s.lit >= 0 and t - s.lit or -1
				s.f.Rate = (q >= 0 and t < SHOW) and 60 or (q >= 0 and 60 * (1 - c01((t - SHOW) / 0.5)) or 0)
				s.s.Rate = q >= 0 and 8 or 0
			end
			scarM.Scale = Vector3.new(26, 1, 6)
			scar.CFrame = CFrame.lookAt(o + Vector3.new(0, 0.07, 0), o + Vector3.new(0, 0.07, 0) + fwd)
			local sl = c01((t - 0.5) / 0.5)
			L.tint(scarM, C2:Lerp(C1, c01((t - SHOW) / 0.8)), 2.4 * (1 - 0.6 * c01((t - SHOW) / 0.9)))
			scar.Transparency = 1 - 0.9 * sl * (1 - c01((t - DUR + 0.6) / 0.6))
			if not shown and t >= SHOW then
				shown = true
				appear(C2, hideTok)
				burst:Emit(40)
				L.groundWave(o, "ring_c.png", C2, 2, 14, 0.5)
			end
		end, objs)
		task.delay(DUR + 0.1, function() setHidden(false, hideTok) end)
	end


	shorts[2] = function()
		local o = ch.feet
		local DUR = 2.9
		local HITS = { 0.45, 1.0, 1.55 }
		local hideTok = setHidden(true)
		local fwd, rt = camBasis()
		local objs = {}
		local function own(x) objs[#objs + 1] = x return x end
		local g, gp, gh = ghostOf(W)
		own(g)

		local piv = o + rt * 4.2 + Vector3.new(0, 7.2, 0) - fwd * 0.5
		local haft = own(L.part({ Shape = Enum.PartType.Cylinder, Material = Enum.Material.Wood, Color = Color3.fromRGB(60, 35, 25), Transparency = 1, Size = Vector3.new(5.4, 0.45, 0.45) }))
		local head = own(L.part({ Material = Enum.Material.Basalt, Color = Color3.fromRGB(40, 30, 28), Transparency = 1, Size = Vector3.new(1.6, 1.6, 3) }))
		local face = own(L.part({ Material = Enum.Material.Neon, Color = C2, Transparency = 1, Size = Vector3.new(1.65, 1.65, 0.25) }))
		local hf = flameE(head, { Rate = 0, Speed = NR(1, 3), Lifetime = NR(0.25, 0.45), Size = NS({ K(0, 1.4), K(1, 0.3) }), Acceleration = Vector3.new(0, 5, 0) })
		local sparkP = own(L.part({ Size = Vector3.one }))
		local sparks = L.pe(sparkP, { Texture = L.T("spark.png"), Color = CS(W, C2), LightEmission = 1, Brightness = 6, Rate = 0, Speed = NR(14, 30),
			SpreadAngle = Vector2.new(70, 70), EmissionDirection = Enum.NormalId.Top, Lifetime = NR(0.4, 0.8), Size = NS({ K(0, 0.3), K(1, 0) }),
			Acceleration = Vector3.new(0, -40, 0), Orientation = Enum.ParticleOrientation.VelocityParallel, Squash = NS(-1.5) })
		local strikeP = o + rt * 1.6 + fwd * 0.6
		local done = 0
		L.fx(DUR, function(k, t)

			local ang = math.rad(-110)
			for i, h in ipairs(HITS) do
				local q = t - h
				if q > -0.35 and q < 0.2 then
					ang = q < 0 and math.rad(-110) * (1 - c01((q + 0.35) / 0.35) ^ 3) or math.rad(-12) * math.sin(c01(q / 0.2) * math.pi)
				end
			end
			if t > HITS[3] + 0.2 then ang = math.rad(-110) * c01((t - HITS[3] - 0.2) / 0.3) end
			local vis = (t < HITS[3] + 0.55) and 0 or 1
			local hcf = CFrame.lookAt(piv, strikeP) * CFrame.Angles(ang, 0, 0)
			local reach = (strikeP - piv).Magnitude
			haft.CFrame = hcf * CFrame.new(0, 0, -reach / 2) * CFrame.Angles(0, math.pi / 2, 0)
			head.CFrame = hcf * CFrame.new(0, 0, -reach) * CFrame.Angles(math.pi / 2, 0, 0)
			face.CFrame = head.CFrame * CFrame.new(0, 0, -1.55)
			local ht = math.max(c01(1 - t / 0.25), vis)
			haft.Transparency, head.Transparency, face.Transparency = ht, ht, ht
			hf.Rate = ht < 1 and 20 or 0
			for i, h in ipairs(HITS) do
				if done < i and t >= h then
					done = i
					sparkP.CFrame = CFrame.new(strikeP)
					sparks:Emit(40 + 10 * i)
					L.punch(0.8 + 0.4 * i, 0.2)
					L.groundWave(strikeP, "ring_c.png", W, 1, 10 + 4 * i, 0.4)
					L.groundWave(o, "cracks_b.png", C2, 2, 6 + 3 * i, 1.4, 2.4)
					L.punch(0.4 + 0.2 * i, 0.15, C2, 0.15)
				end
			end

			local lvl = done / 3
			local cool = c01((t - HITS[3] - 0.25) / 0.9)
			for i, p in ipairs(gp) do
				local on = gh[i] <= lvl + 0.02
				p.Color = W:Lerp(C2, cool):Lerp(C1, c01((cool - 0.5) / 0.5))
				p.Transparency = on and (0.05 + 0.95 * c01((cool - 0.35) / 0.65)) or 1
			end
			if done == 3 and cool > 0.3 and hideTok then appear(C2, hideTok) hideTok = nil end
		end, objs)
		task.delay(DUR + 0.1, function() if hideTok then setHidden(false, hideTok) end end)
	end


	shorts[3] = function()
		local o = ch.feet
		local DUR, TEAR, OPEN, STEP, SHUT = 2.8, 0.1, 0.55, 1.0, 1.75
		local hideTok = setHidden(true)
		local fwd, rt = camBasis()
		local objs = {}
		local function own(x) objs[#objs + 1] = x return x end
		local hipH = ch.hrp.Position.Y - o.Y
		local PC = o - rt * 4.5 + Vector3.new(0, hipH + 0.4, 0)
		local RAD = 3.4
		local n = rt
		local ring, ringM = L.mesh("disc.mesh", "ring_c.png", C2, 3) own(ring)
		local inner, innerM = L.mesh("disc.mesh", "glowui.png", C2:Lerp(W, 0.3), 2.4) own(inner)
		local swirl, swirlM = L.mesh("disc.mesh", "swirl.png", C1, 2.2) own(swirl)
		local function face(p, rot) return CFrame.lookAt(p, p + n) * CFrame.Angles(math.pi / 2, rot, 0) end
		local rim = {}
		for i = 1, 14 do
			local p = own(L.part({ Size = Vector3.one * 0.6 }))
			rim[i] = { p = p, a = i / 14 * math.pi * 2, f = flameE(p, { Rate = 0, Speed = NR(1, 3), Lifetime = NR(0.3, 0.5), Size = NS({ K(0, 1.2), K(0.3, 1.9), K(1, 0.3) }),
				Acceleration = Vector3.new(0, 5, 0) }) }
		end

		local s0, s1 = own(L.att(PC)), own(L.att(PC))
		local seam = own(L.beam(s0, s1, { Width0 = 0.5, Width1 = 0.5, Brightness = 6, Segments = 2, Color = CS(W, C2), Transparency = NS(1) }))
		local g, gp = ghostOf(C2)
		own(g)
		local g0 = {}
		for i, p in ipairs(gp) do g0[i] = p.CFrame end
		local stepped, shut = false, false
		L.fx(DUR, function(k, t)
			local tear = c01((t - TEAR) / (OPEN - TEAR))
			local op = L.outBack(c01((t - OPEN) / 0.35)) * (1 - L.inQuad(c01((t - SHUT) / 0.3)))
			local up = Vector3.new(0, RAD * 1.1 * L.outQuad(tear) * (1 - c01((t - OPEN) / 0.2)), 0)
			s0.WorldPosition, s1.WorldPosition = PC - up, PC + up
			seam.Transparency = NS((t > TEAR and t < OPEN + 0.2) and 0 or 1)
			local r = RAD * op
			ringM.Scale = Vector3.new(r * 2.3, 1, r * 2.3)
			ring.CFrame = face(PC, t * 2)
			ring.Transparency = op > 0.02 and 0.05 or 1
			innerM.Scale = Vector3.new(r * 2, 1, r * 2)
			inner.CFrame = face(PC + n * 0.05, 0)
			inner.Transparency = op > 0.02 and 0.25 or 1
			swirlM.Scale = Vector3.new(r * 2, 1, r * 2)
			swirl.CFrame = face(PC + n * 0.08, -t * 5)
			swirl.Transparency = op > 0.02 and 0.2 or 1
			local up2 = Vector3.yAxis
			local side = n:Cross(up2)
			for _, e in ipairs(rim) do
				e.p.CFrame = CFrame.new(PC + (up2 * math.cos(e.a + t) + side * math.sin(e.a + t)) * r * 1.1)
				e.f.Rate = op > 0.1 and 25 or 0
			end

			local w = c01((t - STEP) / 0.6)
			local off = -rt * 4.5 * (1 - L.outQuad(w))
			for i, p in ipairs(gp) do
				p.CFrame = g0[i] + off
				p.Transparency = (t >= STEP - 0.05 and not stepped) and (0.1 + 0.9 * c01((t - STEP - 0.6) / 0.25)) or 1
				p.Color = C2:Lerp(W, 0.5 * (1 - w))
			end
			if not stepped and t >= STEP + 0.62 then
				stepped = true
				appear(C2, hideTok)
				burst:Emit(30)
			end
			if not shut and t >= SHUT + 0.3 then
				shut = true
				L.punch(1.2, 0.2)
				do local bp = L.part({ Size = Vector3.one, CFrame = CFrame.new(PC) }) local be = flameE(bp, { Rate = 0, Speed = NR(8, 18), SpreadAngle = Vector2.new(180, 180) }) be:Emit(60) task.delay(1.5, function() bp:Destroy() end) end
				L.groundWave(o - rt * 4.5, "ring_c.png", C2, 1, 12, 0.5)
			end
		end, objs)
		task.delay(DUR + 0.1, function() setHidden(false, hideTok) end)
	end


	shorts[4] = function()
		local o = ch.feet
		local DUR, RISE0, RISE1, CRACK, BREAK = 2.9, 0.35, 1.25, 1.45, 1.85
		local hideTok = setHidden(true)
		local objs = {}
		local function own(x) objs[#objs + 1] = x return x end
		local pool, poolM = L.mesh("disc.mesh", "lavarock2.png", W, 1.8) own(pool)
		local glow, glowM = L.mesh("disc.mesh", "glowui.png", C2, 2) own(glow)
		local g, gp, gh = ghostOf(Color3.fromRGB(28, 22, 22), Enum.Material.Basalt)
		own(g)
		local g0 = {}
		for i, p in ipairs(gp) do g0[i] = p.CFrame end
		local dripP = own(L.part({ Size = Vector3.new(2, 4, 1.2) }))
		local drips = L.pe(dripP, { Texture = L.T("drop.png"), Color = CS(W:Lerp(C2, 0.3), C1), LightEmission = 1, Brightness = 4, Shape = Enum.ParticleEmitterShape.Box,
			Rate = 0, Speed = NR(0, 1), Lifetime = NR(0.4, 0.7), Size = NS({ K(0, 0.35), K(1, 0.2) }), Acceleration = Vector3.new(0, -35, 0) })
		local chunks, crackPunch
		L.fx(DUR, function(k, t)
			local pg = L.outQuad(c01(t / 0.35)) * (1 - c01((t - DUR + 0.7) / 0.6))
			local cool = c01((t - BREAK) / 0.8)
			poolM.Scale = Vector3.new(9 * pg, 1, 9 * pg)
			pool.CFrame = CFrame.new(o + Vector3.new(0, 0.06, 0)) * CFrame.Angles(0, t * 0.2, 0)
			L.tint(poolM, W:Lerp(Color3.fromRGB(110, 60, 50), cool), 1.8 * (1 - 0.6 * cool))
			pool.Transparency = pg > 0.02 and 0.05 or 1
			glowM.Scale = Vector3.new(11 * pg, 1, 11 * pg)
			glow.CFrame = CFrame.new(o + Vector3.new(0, 0.1, 0))
			glow.Transparency = pg > 0.02 and (0.4 + 0.6 * cool) or 1

			local rise = L.outQuad(c01((t - RISE0) / (RISE1 - RISE0)))
			local sink = (1 - rise) * 6
			dripP.CFrame = CFrame.new(ch.hrp.Position - Vector3.new(0, sink, 0))
			drips.Rate = (t > RISE0 and t < BREAK) and 70 or 0
			if not chunks then
				local crack = c01((t - CRACK) / 0.3)
				for i, p in ipairs(gp) do
					p.CFrame = g0[i] - Vector3.new(0, sink, 0)
					p.Transparency = t > RISE0 and 0 or 1
					local lava = 1 - c01((t - RISE0 - 0.2) / 0.6)
					p.Material = (lava > 0.3 or crack > 0.5) and Enum.Material.Neon or Enum.Material.Basalt
					p.Color = Color3.fromRGB(28, 22, 22):Lerp(C2, math.max(lava, crack * (0.6 + 0.4 * math.sin(t * 40))))
				end
				if t >= CRACK and not chunks and not crackPunch then crackPunch = true L.punch(0.4, BREAK - CRACK) end
			end
			if not chunks and t >= BREAK then
				chunks = {}
				appear(C2, hideTok)
				burst:Emit(50)
				L.groundWave(o, "ring_c.png", W, 2, 16, 0.5)
				L.groundWave(o, "cracks_b.png", C2, 2, 9, 1.2, 2.4)
				for i, p in ipairs(gp) do
					local c = p.Position
					local out = (c - ch.hrp.Position) * Vector3.new(1, 0, 1)
					out = out.Magnitude > 0.05 and out.Unit or Vector3.new(rnd(-1, 1), 0, rnd(-1, 1)).Unit
					p.Material, p.Color = Enum.Material.Basalt, Color3.fromRGB(40, 30, 28)
					chunks[i] = { p = p, p0 = c, rot = p.CFrame.Rotation, v = out * rnd(10, 18) + Vector3.new(0, rnd(8, 16), 0), sp = Vector3.new(rnd(-8, 8), rnd(-8, 8), rnd(-8, 8)) }
				end
			end
			if chunks then
				local q = t - BREAK
				for _, c in ipairs(chunks) do
					local pos = c.p0 + c.v * q + Vector3.new(0, -50 * q * q, 0)
					if pos.Y < o.Y + 0.2 then pos = Vector3.new(pos.X, o.Y + 0.2, pos.Z) end
					c.p.CFrame = CFrame.new(pos) * c.rot * CFrame.Angles(c.sp.X * q, c.sp.Y * q, c.sp.Z * q)
					c.p.Transparency = c01((q - 0.6) / 0.4)
				end
			end
		end, objs)
		task.delay(DUR + 0.1, function() setHidden(false, hideTok) end)
	end


	shorts[5] = function()
