			end
			fire.Rate = (t >= LAND and t < SHOW + 0.3) and 70 or 0

			local up = c01((t - SHAPE) / (SHOW - SHAPE))
			for i, p in ipairs(gp) do
				local on = gh[i] <= up * 1.05
				p.Transparency = on and (0.15 + 0.85 * c01((t - SHOW) / 0.35)) or 1
				p.Color = C2:Lerp(W, 0.5 * up)
			end
			if not shown and t >= SHOW then
				shown = true
