	local cur = 1
	local function arrive(short)
		if short then return shorts[cur]() end
		return volcanoWyrm()
	end


	local travel, ghostT, boomT, flareT, age, side = 0, 0, 0, 0, 0, 1




	local FNJ, FSEG = 16, 0.7
	local fam = dragon3D(FNJ, 0.36)
	fam.light.Range = 14
	fam.breath.Speed, fam.breath.Lifetime = NR(7, 11), NR(0.25, 0.4)
	fam.breath.Size = NS({ K(0, 0.5), K(0.4, 1.8), K(1, 3) })
	for _, fp in ipairs(fam.fire) do fp.fe.Size = NS({ K(0, 1), K(1, 0.2) }) fp.ee.Size = NS({ K(0, 0.15), K(1, 0) }) end
	local function famOff(t)
		local cyc = t % 16
		local cw = c01((cyc - 9) / 1.2) * (1 - c01((cyc - 13.5) / 1.2))
		local a = t * 0.85 + cw * 1.2 * math.sin(t * 0.3)
		local r = 4.4 + 0.7 * math.sin(t * 0.53)
		r += (2.2 - r) * cw
		local h = 1.4 + 0.9 * math.sin(t * 0.71)
		h += ((0.2 + 1.8 * math.sin(t * 0.9)) - h) * cw
		return Vector3.new(math.cos(a) * r, h, math.sin(a) * r)
	end
	local famJ = table.create(FNJ)
	local roarT, ouroPulse = 99, 0

	local ONJ = 18
	local ouro = dragon3D(ONJ, 0.1)
	ouro.light.Enabled = false
	ouro.noFire = true
	local ouroJ = table.create(ONJ)

	local crackT = 0
	local haze = smokeE(feetP, { Shape = Enum.ParticleEmitterShape.Box, Rate = 0, Color = CS(C2:Lerp(W, 0.4)), LightEmission = 0.4,
		Transparency = NS({ K(0, 1), K(0.3, 0.9), K(1, 1) }), Speed = NR(3, 5), Size = NS({ K(0, 1.5), K(1, 4) }), Lifetime = NR(1, 1.6),
		Acceleration = Vector3.new(0, 3, 0) })
	local function crack()
		local ang, rr, sz, rot = rnd(0, math.pi * 2), rnd(2, 6), rnd(3.2, 5.5), rnd(0, 6)
		local fp = ch.feet + Vector3.new(math.cos(ang) * rr, 0.07, math.sin(ang) * rr)
		local p, m = L.mesh("disc.mesh", "cracks_b.png", C2, 2.6, Vector3.new(0.1, 1, 0.1))
		p.CFrame = CFrame.new(fp) * CFrame.Angles(0, rot, 0)

		local sp, sm = L.mesh("disc.mesh", "darkdisc.png", Color3.fromRGB(25, 10, 5), 1, Vector3.new(0.1, 1, 0.1))
		sp.CFrame = CFrame.new(fp - Vector3.new(0, 0.02, 0)) * CFrame.Angles(0, rot, 0)
		local fpart = L.part({ Size = Vector3.new(sz * 0.5, 0.2, sz * 0.5), CFrame = CFrame.new(fp) })
		local fe = flameE(fpart, { Shape = Enum.ParticleEmitterShape.Box, EmissionDirection = Enum.NormalId.Top, Rate = 0, Speed = NR(1.5, 3),
			Size = NS({ K(0, 0.3), K(0.3, 0.8), K(1, 0.1) }), Lifetime = NR(0.3, 0.5) })
		L.fx(3.2, function(k)
			local g = L.outQuad(k / 0.25)
			m.Scale = Vector3.new(sz * g + 0.1, 1, sz * g + 0.1)
			sm.Scale = Vector3.new(sz * 1.25 * g + 0.1, 1, sz * 1.25 * g + 0.1)
			sp.Transparency = 0.25 + 0.75 * c01((k - 0.5) / 0.5)
			local col = k < 0.2 and W:Lerp(C2, k / 0.2) or C2:Lerp(C1, c01((k - 0.2) / 0.4)):Lerp(Color3.fromRGB(40, 12, 4), c01((k - 0.6) / 0.4))
			L.tint(m, col, 4.5 * (1 - k) + 0.8)
			p.Transparency = 0.1 + 0.9 * c01((k - 0.55) / 0.45)
			fe.Rate = 16 * (1 - c01(k / 0.5))
		end, { p, sp, fpart })
	end

	local function flameRing()
		for i = 0, 15 do
			local a = i / 16 * math.pi * 2
