				AlwaysOnTop = false, MaxDistance = 4000, ResetOnSpawn = false }, L.root)
			e.halo = L.new("ImageLabel", { Image = L.T("flare.png"), BackgroundTransparency = 1, AnchorPoint = Vector2.new(0.5, 0.5),
				Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromScale(1, 0.6), ImageColor3 = C1, ImageTransparency = 1, ZIndex = 1 }, e.bb)
			e.lid = L.new("Frame", { BackgroundTransparency = 1, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
				Size = UDim2.fromScale(1 / 1.8, 0), ClipsDescendants = true, ZIndex = 2 }, e.bb)
			e.alm = L.new("ImageLabel", { Image = L.T("seye_alm2.png"), BackgroundTransparency = 1, AnchorPoint = Vector2.new(0.5, 0.5),
				Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromScale(1, 1), ImageColor3 = C1:Lerp(W, 0.2), ZIndex = 2 }, e.lid)
			e.iris = L.new("ImageLabel", { Image = L.T("seye_iris.png"), BackgroundTransparency = 1, AnchorPoint = Vector2.new(0.5, 0.5),
				Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromScale(0.36, 0.72), ImageColor3 = C2:Lerp(W, 0.25), ZIndex = 3 }, e.alm)
			objs[#objs + 1] = e.att objs[#objs + 1] = e.bb
			if light then
				e.light = L.new("PointLight", { Color = C1, Range = 90, Brightness = 0, Shadows = false }, L.part({ CFrame = CFrame.new(pos) }))
				objs[#objs + 1] = e.light.Parent
			end
			return e
		end

		local function eyeUpd(e, t, dt, op, look, red, pulse)
			local opc = math.max(op, 0.002)
			local P, k = L.skyProj(e.pos, 230)
			e.att.WorldPosition = P
			e.bb.Size = UDim2.new(e.ew * 1.8 * k, 0, e.ew * 1.8 * k, 0)
			e.lid.Size = UDim2.fromScale(1 / 1.8, 0.5 / 1.8 * opc)
			e.alm.Size = UDim2.fromScale(1, 1 / opc)
			local calm = t >= CALM0 and t < CL - 0.2
			e.halo.ImageTransparency = 1 - 0.75 * c01(op) * (calm and 1 or (0.8 + 0.2 * math.sin(t * 9)))
			e.halo.ImageColor3 = C1:Lerp(RED, red)
			if e.light then e.light.Brightness = 6 * c01(op) e.light.Color = C1:Lerp(RED, red) end
			local want
			if look < 0.5 then
				want = Vector2.new(math.sin(t * 2.3 + e.pos.X) * 0.8, math.cos(t * 1.7 + e.pos.Z) * 0.4)
			else
				local cam = workspace.CurrentCamera
				local a = cam:WorldToViewportPoint(e.pos)
				local b = cam:WorldToViewportPoint(ch.pos)
				local d = Vector2.new(b.X - a.X, b.Y - a.Y)
				want = d.Magnitude > 1 and d.Unit or Vector2.zero
			end
			e.gaze = e.gaze:Lerp(want, math.min(1, dt * (look < 0.5 and 4 or 14)))
			e.iris.Position = UDim2.fromScale(0.5 + e.gaze.X * 0.2, 0.5 + e.gaze.Y * 0.2)

			local nx = 1 - 0.3 * red
			e.iris.Size = UDim2.fromScale(0.36 * nx * (1 - 0.15 * pulse), 0.72 * (1 - 0.1 * pulse))
			e.iris.ImageColor3 = C2:Lerp(W, 0.25):Lerp(REDI, red)
			e.alm.ImageColor3 = C1:Lerp(W, 0.2):Lerp(RED:Lerp(W, 0.3), red):Lerp(W, 0.6 * pulse)
			e.bb.Brightness = 3 + 4 * red
		end
		local eye = makeEye(eyeP, 62, true)
		local function eyeOpen(t) return L.outBack(c01((t - EO) / 0.55)) * (1 - L.inQuad(c01((t - EC) / 0.35))) end

		local smallEyes = {}
		for i = 1, 12 do
			local yaw = (i % 2 == 0 and 1 or -1) * rnd(0.3, 1.25)
			local dir = fwd * math.cos(yaw) + rgt * math.sin(yaw)
			local pos = o + dir * rnd(60, 105) + Vector3.new(0, rnd(16, 52), 0)
			local se = makeEye(pos, rnd(9, 17), false)
			se.t0 = EL + 0.05 + (i - 1) * 0.055 + rnd(0, 0.03)
			se.tc = EC - 0.25 + rnd(0, 0.3)
			smallEyes[i] = se
		end

		local mark, markM = L.mesh("disc.mesh", "mcircle.png", RED, 2.2, Vector3.new(16, 1, 16))
		local mark2, mark2M = L.mesh("disc.mesh", "ring_c.png", RED, 2.4, Vector3.new(8, 1, 8))
		mark.Transparency, mark2.Transparency = 1, 1
		objs[#objs + 1] = mark objs[#objs + 1] = mark2

		local rays = {}
		for i = 1, 6 do rays[i] = i / 6 * 6.28 + rnd(-0.35, 0.35) end
		local PULSES = { { t = 1.0, r0 = 46, r1 = 32 }, { t = 1.75, r0 = 32, r1 = 20 }, { t = 2.4, r0 = 20, r1 = 9 } }
		local pulseI = 0
		local function crack(pos, born)
			local c, cm = L.mesh("disc.mesh", "cracks_b.png", W, 3, Vector3.new(rnd(5, 8), 1, rnd(5, 8)))
			c.CFrame = CFrame.new(pos + Vector3.new(0, 0.06, 0)) * CFrame.Angles(0, rnd(0, 6.28), 0)
			L.fx(DUR - born + 0.5, function(_, tt)
				local hot = math.exp(-tt / 0.35)
				local tg = born + tt
				local col = C1:Lerp(RED, c01((tg - EL) / 0.3)):Lerp(W, hot * 0.8)
				L.tint(cm, col, 1.2 + 3 * hot)
				c.Transparency = 1 - (0.85 * c01(tt / 0.06)) * (1 - c01((tg - CL - 1.5) / 2))
			end, { c })
		end
		local function thunderPulse(p)
			for _, a in ipairs(rays) do
				local n = math.floor((p.r0 - p.r1) / 3.2)
				for j = 0, n do
					local rr = p.r0 - (p.r0 - p.r1) * j / math.max(n, 1)
					local aa = a + rnd(-0.08, 0.08)
					L.after(j * 0.035, function() crack(o + Vector3.new(math.cos(aa) * rr, 0, math.sin(aa) * rr), p.t + j * 0.035) end)
				end
			end
			S:shake(1.6, 0.4) skyFl = 1 cFlash(14) fLight.Brightness = math.max(fLight.Brightness, 6)
		end

		local worldLights, savedBright, lightsOut = {}, Lt.Brightness, scr
		if scr then
			for _, d in ipairs(workspace:GetDescendants()) do
				if d:IsA("Light") and not d:IsDescendantOf(L.root) and not (ch.char and d:IsDescendantOf(ch.char)) then worldLights[d] = d.Enabled end
			end
		end
		local function lightsBack()
			if not lightsOut then return end
			lightsOut = false
			for d, v in pairs(worldLights) do if d.Parent then d.Enabled = v end end
			Lt.Brightness = savedBright
		end
		task.delay(DUR + 0.3, lightsBack)
		if scr then L.onEnd(lightsBack) end
		local oldDim = S.dimFn
		local function calmA(t) return (t >= CALM0 and t < CL - 0.2) and c01((t - CALM0) / 0.15) or 0 end
		S.dimFn = function(t) return math.min(1.2, oldDim(t) + 0.4 * calmA(t)) end
		local rainFrozen = false

		local scarRot = rnd(0, 6.28)
		local function scar()
			local sb, sbm = L.mesh("disc.mesh", "fork_b.png", Color3.new(0, 0, 0), 1, Vector3.new(26, 1, 26))
			local sg, sgm = L.mesh("disc.mesh", "fork_g.png", C1, 3, Vector3.new(26, 1, 26))
			sb.CFrame = CFrame.new(o + Vector3.new(0, 0.05, 0)) * CFrame.Angles(0, scarRot, 0)
			sg.CFrame = CFrame.new(o + Vector3.new(0, 0.07, 0)) * CFrame.Angles(0, scarRot, 0)
			L.fx(11, function(_, tt)
				sb.Transparency = 0.15 + 0.85 * c01((tt - 8.5) / 2.5)
				local heat = math.exp(-tt / 3.5) * (0.75 + 0.25 * math.sin(tt * 11))
				L.tint(sgm, C1:Lerp(W, 0.6 * heat), 0.6 + 3 * heat)
				sg.Transparency = 1 - c01(heat * 1.6) * (1 - c01((tt - 8.5) / 2.5))
			end, { sb, sg })
		end
		local sparkT = 0
		local cloudArcT, strikeT, arcT, crackleT, cageI, struck, lastT = 0, 0.9, 0, 0, 0, false, 0
		L.fx(DUR, function(k, t)
			local dt = t - lastT lastT = t

			local sa = skyA(t)
			wsky.set(sa)
			rainW.Rate = (t >= CALM0 and t < CL - 0.2) and 0 or 900 * sa
			skyFl = math.max(0, skyFl - dt * 5)
			for _, d in ipairs(domeP) do d.Color = SKYC:Lerp(SKYF, skyFl) end
			if scr and skyFl > 0.01 then Lt.OutdoorAmbient = Lt.OutdoorAmbient:Lerp(OAF, skyFl * 0.7 * sa) end
			local calm = t >= CALM0 and t < CL - 0.2

			local red = c01((t - EL) / 0.3)
			local lockPulse = c01(1 - (t - EL) / 0.4) * (t >= EL and 1 or 0)
			eyeUpd(eye, t, dt, eyeOpen(t), t >= EL and 1 or 0, red, lockPulse)
			for _, se in ipairs(smallEyes) do
				local sop = L.outBack(c01((t - se.t0) / 0.3)) * (1 - L.inQuad(c01((t - se.tc) / 0.3)))
				eyeUpd(se, t, dt, sop, (t - se.t0) > 0.18 and 1 or 0, 1, 0)
			end
			if t >= EL and t - dt < EL then cFlash(12) skyFl = 1 S:shake(1.2, 0.4) end

			local ma = c01((t - EL) / 0.25) * (1 - c01((t - (CL - 0.2)) / 0.1))
			local ms = 16 - 9 * L.inQuad(c01((t - EL) / (CL - 0.2 - EL)))
			markM.Scale = Vector3.new(ms, 1, ms)
			mark.CFrame = CFrame.new(o + Vector3.new(0, 0.1, 0)) * CFrame.Angles(0, -t * 1.6, 0)
			mark.Transparency = 1 - 0.85 * ma
			local m2 = ms * 0.55 * (1 + 0.08 * math.sin(t * 20))
			mark2M.Scale = Vector3.new(m2, 1, m2)
			mark2.CFrame = CFrame.new(o + Vector3.new(0, 0.11, 0))
			mark2.Transparency = 1 - 0.7 * ma

			if pulseI < #PULSES and t >= PULSES[pulseI + 1].t then pulseI += 1 thunderPulse(PULSES[pulseI]) end

			if lightsOut then
				local fl = c01((t - 1.9) / 0.5)
				if t >= CALM0 and t < CL then
					for d in pairs(worldLights) do if d.Parent and d.Enabled then d.Enabled = false end end
					Lt.Brightness = savedBright * (1 - calmA(t))
				elseif fl > 0 and t < CALM0 then
					for d, v in pairs(worldLights) do if d.Parent then local e = v and math.random() > 0.55 * fl if d.Enabled ~= e then d.Enabled = e end end end
				end
			end

			if calm and not rainFrozen then rainFrozen = true rainW.TimeScale = 0 end
			local fade = c01((t - CL - 1.8) / 2.4)
			cUpdate(t, dt, L.outQuad(c01(t / 1.1)) * (1 + 0.3 * c01((t - CL) / 2)), fade, 0.8 + 1.6 * c01((t - CL + 1) / 1.5))

			cloudArcT -= dt
			if cloudArcT <= 0 and t > 0.3 and t < CL + 2.6 and not calm then
				cloudArcT = rnd(0.03, 0.11)
				for _ = 1, (t > CL - 1.2 and t < CL + 1) and 3 or 2 do
					local a, r = rnd(0, 6.28), rnd(8, 60)
					local p0 = top + Vector3.new(math.cos(a) * r, rnd(-5, 3), math.sin(a) * r)
					local p1 = p0 + Vector3.new(rnd(-22, 22), rnd(-6, 2), rnd(-22, 22))
					zap(p0, p1, 0.5, 0.14, W, (math.random() < 0.5) and C1 or C2)
				end
				cFlash(rnd(2, 5))
				if math.random() < 0.15 then skyFl = math.max(skyFl, rnd(0.3, 0.6)) end
			end

			strikeT -= dt
			if strikeT <= 0 and t > 0.9 and t < CL + 2.3 and math.abs(t - CL) > 0.35 and not calm then
				local ramp = t < CL and c01((t - 0.9) / (CL - 0.9)) or (1 - c01((t - CL) / 2.3))
				strikeT = rnd(0.1, 0.32) * (1.2 - 0.85 * ramp)
				local a, r = rnd(0, 6.28), rnd(12, 60)
				local to = o + Vector3.new(math.cos(a) * r, 0, math.sin(a) * r)
				local from = top + Vector3.new(math.cos(a) * r * 0.5 + rnd(-10, 10), rnd(-6, 0), math.sin(a) * r * 0.5 + rnd(-10, 10))
				skyStrike(from, to, rnd(0.6, 1.1), 3)
				L.groundWave(to, "ring_c.png", C1, 1, rnd(8, 14), 0.45)
				L.groundWave(to, "cracks_b.png", C1, 2, 7, 0.9, 1.8)
				fLight.Brightness = math.max(fLight.Brightness, 4)
				cFlash(10)
				skyFl = math.max(skyFl, 0.7)
				if S then S:shake(0.4, 0.12) end
			end

			local cageAt = CL - 1.55 + cageI * 0.07
			if cageI < 8 and t >= cageAt then
				cageI += 1
				local a = cageI / 8 * 6.28
				local to = o + Vector3.new(math.cos(a) * 6, 0, math.sin(a) * 6)
				skyStrike(top + Vector3.new(math.cos(a) * 12, -4, math.sin(a) * 12), to, 0.9, 2)
				L.groundWave(to, "ring_c.png", W, 1, 7, 0.4)
				cFlash(10)
			end

			local gs = 4 + 30 * L.outQuad(c01(t / CL))
			gcm.Scale = Vector3.new(gs, 1, gs)
			gc.CFrame = CFrame.new(o + Vector3.new(0, 0.08, 0)) * CFrame.Angles(0, t * 0.15, 0)
			L.tint(gcm, C1, 1.4 + (t > CL and 2 * c01(1 - (t - CL) / 0.6) or 0))
			gc.Transparency = 1 - (0.7 * c01(t / 0.5)) * (1 - c01((t - CL - 1) / 2))
			if t > 0.5 and t < CL + 2.5 then
				arcT -= dt
				if arcT <= 0 and not calm then
					local ramp = t < CL and c01(t / CL) or (1 - c01((t - CL) / 2.5))
					arcT = 0.18 - 0.15 * ramp
					local a, r = rnd(0, 6.28), rnd(3, 16)
					local a2 = a + rnd(-0.8, 0.8)
					zap(o + Vector3.new(math.cos(a) * r, 0.3, math.sin(a) * r), o + Vector3.new(math.cos(a2) * r * rnd(0.4, 1.3), 0.3, math.sin(a2) * r * rnd(0.4, 1.3)), 0.3, 0.14)
				end
			end

			if struck and t > CL then
				local ag = 1 - c01((t - CL - 1) / (DUR - CL - 1.5))
				crackleT -= dt
				if crackleT <= 0 then crackleT = 0.05 + 0.25 * (1 - ag) zap(bodyPt(1.2), bodyPt(1.6), 0.18, 0.08) end
				sparkT -= dt
				if sparkT <= 0 and t > CL + 0.4 and ag > 0.05 then
					sparkT = rnd(0.1, 0.25) + 0.4 * (1 - ag)
					local a, r = rnd(0, 6.28), rnd(2.5, 6)
					zap(bodyPt(1.1), ch.feet + Vector3.new(math.cos(a) * r, 0.1, math.sin(a) * r), 0.22, 0.12, W, C1)
				end
				flashP.CFrame = CFrame.new(ch.pos)
				fLight.Brightness = math.max(fLight.Brightness, ag * rnd(1.5, 4))
			end
			convE.Rate = (t < CALM0) and (40 + 260 * c01(t / CL)) or 0
			if t > 1.2 and t < CALM0 then S:shake(0.7 * c01((t - 1.2) / (CL - 1.2)), 0.2) end

			if not struck and t >= CL - 0.2 then
				struck = true
				local tgt = o + Vector3.new(0, 1.5, 0)
				rainW.TimeScale = 1 rainFrozen = false
				local src = eyeP - Vector3.new(0, 2, 0)
				L.bolt(src, tgt, { w = 0.3, life = 0.2, col = W, glow = C1, segs = 24, jit = 12 })
				for i, d in ipairs({ 0.2, 0.3, 0.42, 0.56, 0.74 }) do
					L.after(d, function()
						L.strike(o + Vector3.new(0, 62, 0) + fwd * 6, tgt, { w = ({ 2.4, 1.6, 1.3, 1.1, 0.9 })[i], life = 0.45, col = W, glow = C1, segs = 30, jit = 14, forks = 6, flicker = i ~= 1 })
						fLight.Brightness = 14 cFlash(14) skyFl = 1
						if i > 1 then S:flash(W, 0.55) end S:shake(i == 1 and 3.2 or 1.4, 1.0)
						if i == 1 then
							scar()
							appear(W, hideTok)
							L.groundWave(o, "ring_c.png", W, 4, 70, 0.7)
							L.groundWave(o, "ring_c.png", C2, 4, 42, 0.9)
							L.groundWave(o, "ring_c.png", C1, 10, 1400, 5.4, 2.6)
							burst:Emit(170)
							radialArcs(o, 16, 14, 26)

							for _, d in ipairs(domeP) do d.Color = Color3.fromRGB(4, 5, 10) d.Transparency = 0.05 end
							cDark() fLight.Brightness = 3
							if scr and L.scr() then Lt.OutdoorAmbient, Lt.Ambient = Color3.fromRGB(14, 16, 24), Color3.fromRGB(10, 12, 18) end
							S.cc.Contrast, S.cc.Saturation, S.cc.Brightness, S.cc.TintColor = 0.6, -1, -0.18, Color3.fromRGB(220, 232, 255)
							L.hitStop(0.26)
							task.delay(0.26, function() S.cc.TintColor = W S:flash(W, 0.9) S:shake(3.6, 0.8) lightsBack() end)
						end
					end)
				end
			end
			fLight.Brightness = math.max(0, fLight.Brightness - dt * 18)
		end, objs)

		for i = #L.live, 1, -1 do
			if L.live[i].objs == objs then L.live[i].done = function() wsky.set(0) lightsBack() end break end
		end
		task.delay(DUR + 0.1, function() setHidden(false, hideTok) end)
	end


	local shorts = {}

	shorts[1] = function()
		local o = ch.feet
		local top = o + Vector3.new(0, 30, 0)
		local DUR, ST = 2.4, 0.75
		local hideTok = setHidden(true)
		local cObjs, cUpdate, cFlash = stormCloud(top, 50)
		local conv = L.part({ Shape = Enum.PartType.Ball, Size = Vector3.new(14, 14, 14), CFrame = CFrame.new(ch.pos) })
		local convE = L.pe(conv, { Texture = L.T("spark.png"), Shape = Enum.ParticleEmitterShape.Sphere, ShapeInOut = Enum.ParticleEmitterShapeInOut.Inward,
			Speed = NR(14, 20), Lifetime = NR(0.4, 0.5), Orientation = Enum.ParticleOrientation.VelocityParallel, Squash = NS(-2.5),
			Size = NS({ K(0, 0.1), K(0.7, 0.22), K(1, 0) }), Color = CS(C1, W), Brightness = 6 })
		cObjs[#cObjs + 1] = conv
		local arcT, struck, lastT = 0, false, 0
		L.fx(DUR, function(k, t)
			local dt = t - lastT lastT = t
			cUpdate(t, dt, L.outQuad(c01(t / 0.5)), c01((t - ST - 0.6) / 0.9), 2.4)
			arcT -= dt
			if arcT <= 0 and t < ST + 0.6 then
				arcT = rnd(0.04, 0.1)
				local a, r = rnd(0, 6.28), rnd(3, 22)
				local p0 = top + Vector3.new(math.cos(a) * r, rnd(-2, 2), math.sin(a) * r)
				zap(p0, p0 + Vector3.new(rnd(-9, 9), rnd(-2, 1), rnd(-9, 9)), 0.35, 0.12)
				cFlash(8)
			end
			convE.Rate = t < ST and 220 or 0
			if not struck and t >= ST then
				struck = true
				local tgt = o + Vector3.new(0, 1.5, 0)
				L.strike(top, tgt, { w = 1.5, life = 0.4, col = W, glow = C1, segs = 16, jit = 3.5, forks = 4 })
				L.after(0.12, function() L.strike(top, tgt, { w = 1, life = 0.35, col = W, glow = C1, segs = 16, jit = 3.5, forks = 3 }) end)
				cFlash(14)
				appear(W, hideTok)
				burst:Emit(60)
				L.groundWave(o, "ring_c.png", W, 3, 28, 0.6)
				L.groundWave(o, "ring_c.png", C2, 3, 18, 0.8)
				radialArcs(o, 8, 7, 12)
			end
		end, cObjs)
		task.delay(DUR + 0.1, function() setHidden(false, hideTok) end)
	end

	shorts[2] = function()
		local o = ch.feet
		local DUR, HOP = 2.2, 0.1
		local hideTok = setHidden(true)
		local pts = {}
		local a0, r = rnd(0, 6.28), 16
		for i = 1, 7 do
			pts[i] = o + Vector3.new(math.cos(a0 + i * 0.95) * r, 0.5, math.sin(a0 + i * 0.95) * r)
			r *= 0.66
		end
		pts[#pts + 1] = o + Vector3.new(0, 1.5, 0)
		local i, done = 0, false
		L.fx(DUR, function(k, t)
			while not done and t >= 0.1 + i * HOP do
				i += 1
				if i == 1 then
					skyStrike(pts[1] + Vector3.new(rnd(-6, 6), 40, rnd(-6, 6)), pts[1], 0.9, 2)
				else
					zap(pts[i - 1], pts[i], 0.7 + 0.08 * i, 0.3, W, (i % 2 == 0) and C1 or C2)
					zap(pts[i - 1], pts[i], 0.3, 0.2, W, C2)
				end
				if i < #pts then
					L.groundWave(pts[i] - Vector3.new(0, 0.5, 0), "ring_c.png", C1, 1, 6, 0.4)
					L.groundWave(pts[i] - Vector3.new(0, 0.5, 0), "cracks_b.png", C1, 1.5, 4, 0.8, 1.6)
				end
				if i == #pts then
					done = true
					appear(W, hideTok)
					burst:Emit(55)
					L.groundWave(o, "ring_c.png", W, 3, 24, 0.55)
					radialArcs(o, 10, 6, 12)
				end
			end
		end, {})
