	return { arrive = arrive, step = step, rebind = rebind, short = function(n) cur = n shorts[n]() end, hidden = function() return hideOwner ~= dashTok and savedLTM or nil end, rig = function() return rig end, stop = function() pcall(function() tag.bb:Destroy() end) setHidden(false) end }
end
end
end)()
end
