		local mo = moteE(p, { Rate = 0, Speed = NR(0.2, 0.5), Lifetime = NR(0.6, 1), Size = NS({ K(0, 0.15), K(1, 0) }), Acceleration = Vector3.zero })
		orbs[i] = { p = p, img = img, bb = bb, mo = mo, ph = i / 4 * math.pi * 2, r = 2.6 + (i % 2) * 0.4, h = 0.4 + (i % 2) * 0.7 }
	end

	local halo, haloM = mmesh("disc.mesh", "runering.png", C2, 2.4, Vector3.new(2.6, 1, 2.6))
	local haloIn, haloInM = mmesh("disc.mesh", "mcircle.png", C1, 2.2, Vector3.new(1.5, 1, 1.5))
	local haloP = L.part({ Size = Vector3.new(2, 0.2, 2) })
	local haloDrip = glyphE(haloP, { Shape = Enum.ParticleEmitterShape.Disc, ShapeStyle = Enum.ParticleEmitterShapeStyle.Surface, EmissionDirection = Enum.NormalId.Bottom,
		Rate = 3, Speed = NR(0.3, 0.6), Acceleration = Vector3.new(0, -0.6, 0), Lifetime = NR(1, 1.4), Size = NS({ K(0, 0), K(0.2, 0.28), K(1, 0) }) })
	local haloLight = L.new("PointLight", { Color = C1, Range = 10, Brightness = 1.5, Shadows = false }, haloP)

	local rig, light, hl = {}, nil, nil
	local function rebind()
		for _, o in ipairs(rig) do o:Destroy() end
		rig = {}
		local hrp = ch.hrp
		local function att(pos) local a = L.new("Attachment", { Position = pos }, hrp) rig[#rig + 1] = a return a end
		local function trail(a0, a1, props) local t = L.new("Trail", props, hrp) t.Attachment0, t.Attachment1 = a0, a1 rig[#rig + 1] = t return t end
		rig.main = trail(att(Vector3.new(0, 1.1, 0.3)), att(Vector3.new(0, -1.4, 0.3)), { Texture = L.T("beamb.png"), LightEmission = 1, Brightness = 3,
			Lifetime = 0.35, FaceCamera = true, Enabled = false, Color = CS({ CK(0, W), CK(0.3, C2), CK(1, C1) }),
			Transparency = NS({ K(0, 0.25), K(1, 1) }), WidthScale = NS({ K(0, 1), K(1, 0.2) }) })
		local back = att(Vector3.new(0, -0.3, 0.6))
		rig.glyphs = glyphE(back, { Speed = NR(0.5, 1.5), Lifetime = NR(0.7, 1.1), EmissionDirection = Enum.NormalId.Back, SpreadAngle = Vector2.new(40, 40),
			Acceleration = Vector3.new(0, 0.6, 0) })
		rig.motes = moteE(back, { Speed = NR(1, 3), Lifetime = NR(0.5, 0.9), EmissionDirection = Enum.NormalId.Back, SpreadAngle = Vector2.new(50, 50) })
		for _, e in ipairs({ rig.glyphs, rig.motes }) do rig[#rig + 1] = e end
		light = L.new("PointLight", { Color = C1, Range = 14, Brightness = 0, Shadows = false }, hrp) rig[#rig + 1] = light
		hl = L.new("Highlight", { FillTransparency = 1, OutlineColor = C2, Adornee = ch.char, DepthMode = Enum.HighlightDepthMode.Occluded }, L.root)
		rig[#rig + 1] = hl
	end
	rebind()
	local tag = System.StaffThemes.headTag(L, "mage", C1, C2, { c1 = C1, c2 = C2, grad = CS({ CK(0, C1), CK(0.35, C2), CK(0.5, W), CK(0.65, C2), CK(1, C1) }) })


	local savedLTM, hideChar, hideOwner, hideGen, dashTok = nil, nil, nil, 0, nil
	local function setHidden(on, tok)
		if on then
			hideGen += 1
			local my = hideGen
			hideOwner = my
			task.delay(15, function() setHidden(false, my) end)
			if savedLTM and hideChar == ch.char then return my end
			if not ch.char then return my end
			savedLTM, hideChar = {}, ch.char
			for _, d in ipairs(ch.char:GetDescendants()) do
				if d:IsA("BasePart") or d:IsA("Decal") then savedLTM[d] = d.LocalTransparencyModifier d.LocalTransparencyModifier = 1 end
			end
			return my
		elseif savedLTM then
			if tok and tok ~= hideOwner then return end
			for d, v in pairs(savedLTM) do if d.Parent then d.LocalTransparencyModifier = v end end
			if tok and tok ~= dashTok then L.punch(1.1, 0.3) end
			savedLTM, hideChar, hideOwner = nil, nil, nil
		end
	end
	local function appear(col, tok)
		setHidden(false, tok)
		hl.FillColor, hl.FillTransparency = col or W, 0.15
		light.Brightness = 8
		burstP.CFrame = CFrame.new(ch.pos) burst:Emit(40) burstG:Emit(14)
		L.fx(0.9, function(k) hl.FillTransparency = 0.15 + 0.85 * k end, {})
	end

	local function summonBody(col, life)
		local g = L.ghost(col, Enum.Material.Neon, life, true)
		local start = {}
		for _, p in ipairs(g:GetChildren()) do start[p] = p.CFrame p.Transparency = 1 end
		return function(off, tr, c)
			for p, cf in pairs(start) do
				if p.Parent then p.CFrame = cf + off p.Transparency = tr if c then p.Color = c end end
			end
		end
	end






	local function arriveFull()
		local o = ch.feet
		local DUR = 11.6
		local CONST, LINES, DROP, LAND, TOWER, SIDES, LOCK, ERUPT, REVEAL, BREAK, SHRINK, SETTLE =
			0.2, 0.85, 1.85, 2.3, 2.8, 3.3, 5.3, 6.0, 7.2, 7.45, 7.9, 10.7
		local hideTok = setHidden(true)
		local S = L.screen(DUR)
		S.dimFn = function(t) return (0.4 * c01(t / 0.8) + 0.25 * c01((t - LOCK) / 0.4) * (1 - c01((t - ERUPT) / 0.3))) * (1 - c01((t - BREAK - 1) / 2)) end
		S.style, S.c1, S.c2 = "mage", C1, C2 S.boxFn = function(t) return c01((t - 0.2) / 0.6) * (1 - c01((t - (DUR - 1.2)) / 0.9)) end
		S.tintFn = function(t) return C1, 0.3 * c01(t / 1.2) * (1 - c01((t - BREAK - 0.5) / 2.5)) end
		L.after(REVEAL + 0.4, function() S:title(L.name(), C1, C2) end)
		local objs = {}
		local function own(x) objs[#objs + 1] = x return x end
		local R, SKY = 20, 30
		local RH = R * 0.8

		local stars, lines = {}, {}
		for i = 0, 6 do
			local p = own(L.part({ Size = Vector3.one * 0.3 }))
			local f = flareE(p, { Rate = 0, Lifetime = NR(0.2), LightEmission = 0.5, Color = CS(C2:Lerp(W, 0.4), C2), Size = NS({ K(0, 4), K(0.5, 6.5), K(1, 0) }) })
			stars[i] = { p = p, f = f, a = i / 7 * math.pi * 2 - math.pi / 2, t0 = CONST + i * 0.09, on = false }
		end
		for i = 0, 6 do
			local a0, a1 = own(L.att(o)), own(L.att(o))
			local b = own(L.beam(a0, a1, { Width0 = 0.7, Width1 = 0.7, Brightness = 3, LightEmission = 0.35, Color = CS(C2:Lerp(W, 0.25), C1), Transparency = NS(1) }))
			lines[i] = { a0 = a0, a1 = a1, b = b, j = (i + 3) % 7, t0 = LINES + i * 0.13 }
		end
		local function starPos(i, t)
			local u = L.inQuad((t - DROP) / (LAND - DROP))
			local h = (SKY - 4) + (0.4 - (SKY - 4)) * u
			local rr = 11 + (RH - 11) * u
			local a = stars[i].a + t * 0.15
			return o + Vector3.new(math.cos(a) * rr, h, math.sin(a) * rr)
		end

		local bk, bkSet = backing() own(bk)
		local gc, gcm, gcSet = circle("mcircle.png", C1, 1.6) own(gc)
		local gr, grm, grSet = circle("runering.png", C2, 1.8) own(gr)
		local gi, gim, giSet = circle("runering.png", C2, 2) own(gi)
		local pens = {}
		for i = 1, 2 do
			local p = own(L.part({ Size = Vector3.one * 0.3, CFrame = CFrame.new(o + Vector3.new(R, 0.3, 0)) }))
			local a0 = L.new("Attachment", { Position = Vector3.new(0, 0.25, 0) }, p)
			local a1 = L.new("Attachment", { Position = Vector3.new(0, -0.25, 0) }, p)
			local tr = L.new("Trail", { Attachment0 = a0, Attachment1 = a1, Texture = L.T("beamb.png"), LightEmission = 1, Brightness = 6, Lifetime = 0.4,
				FaceCamera = true, Enabled = false, Color = CS(W, C2), Transparency = NS(0, 1), WidthScale = NS(1, 0.4) }, p)
			local f = flareE(p, { Rate = 0, Lifetime = NR(0.12), Size = NS(3) })
			pens[i] = { p = p, tr = tr, f = f, r = ({ R * 1.0, R * 0.38 })[i], t0 = LAND + 0.05, dur = 0.6 }
		end

		local skB, skBSet = backing() own(skB)
		local sc, scm, scSet = circle("mcircle.png", C1, 1.6) own(sc)
		local sr, srm, srSet = circle("runering.png", C2, 1.8) own(sr)
		local skyP = own(L.part({ Size = Vector3.new(R * 1.6, 0.2, R * 1.6), CFrame = CFrame.new(o + Vector3.new(0, SKY, 0)) }))
		local skyG = glyphE(skyP, { Shape = Enum.ParticleEmitterShape.Disc, ShapeStyle = Enum.ParticleEmitterShapeStyle.Surface, EmissionDirection = Enum.NormalId.Bottom,
			Speed = NR(2, 4), Lifetime = NR(1.2, 1.8), Acceleration = Vector3.new(0, -2, 0), Size = NS({ K(0, 0), K(0.15, 1), K(0.8, 0.8), K(1, 0) }) })
		local skyF = flareE(skyP, { Rate = 0, Lifetime = NR(0.3), Size = NS({ K(0, 6), K(0.2, 26), K(1, 0) }) })

		local PAL = { Color3.fromRGB(255, 70, 80), Color3.fromRGB(255, 170, 40), Color3.fromRGB(70, 235, 120),
			Color3.fromRGB(60, 215, 255), Color3.fromRGB(165, 95, 255), Color3.fromRGB(255, 95, 205) }
		local casters = {}
		do
			local root = ch.hrp.CFrame
			local tmpl = {}
			local pivots = {}
			for _, p in ipairs(ch.char:GetChildren()) do
				if p:IsA("BasePart") and p.Name ~= "HumanoidRootPart" and p.Transparency < 1 then
					local rel = root:ToObjectSpace(p.CFrame)
					local n = p.Name
					local side = (n:find("Arm") or n:find("Hand")) and (n:find("Left") and "L" or "R") or nil
					if side and (n:find("UpperArm") or n == "Left Arm" or n == "Right Arm") then
						pivots[side] = (rel * CFrame.new(0, p.Size.Y * 0.4, 0)).Position
					end
					tmpl[#tmpl + 1] = { src = p, rel = rel, side = side }
				end
			end
			local HY = root.Position.Y - o.Y
			for j = 0, 5 do
				local col = PAL[j + 1]
				local a = j / 6 * math.pi * 2 + math.pi / 6
				local spot = o + Vector3.new(math.cos(a) * (R + 6), 0, math.sin(a) * (R + 6))
				local m = own(Instance.new("Model"))
				local parts = {}
				for _, tp in ipairs(tmpl) do
					local g = tp.src:Clone()
					for _, d in ipairs(g:GetChildren()) do if not d:IsA("DataModelMesh") then d:Destroy() end end
					g.Anchored, g.CanCollide, g.CanQuery, g.CanTouch, g.CastShadow = true, false, false, false, false
					g.Material, g.Color = Enum.Material.SmoothPlastic, col:Lerp(Color3.new(0, 0, 0), 0.55)
					if g:IsA("MeshPart") then g.TextureID = "" end
					g.Transparency = 1
					g.Parent = m
					parts[#parts + 1] = { g = g, tp = tp }
				end
				m.Parent = L.root
				local hlx = L.new("Highlight", { FillColor = col, FillTransparency = 0.7, OutlineColor = col:Lerp(W, 0.35), OutlineTransparency = 0.15,
					DepthMode = Enum.HighlightDepthMode.Occluded, Enabled = false, Adornee = m }, m)

				local dark = col:Lerp(Color3.new(0, 0, 0), 0.4)
				local cvL = own(L.part({ Material = Enum.Material.SmoothPlastic, Color = dark, Size = Vector3.new(0.75, 0.08, 1) }))
				local cvR = own(L.part({ Material = Enum.Material.SmoothPlastic, Color = dark, Size = Vector3.new(0.75, 0.08, 1) }))
				local pgL = own(L.part({ Material = Enum.Material.Neon, Color = W:Lerp(col, 0.25), Size = Vector3.new(0.68, 0.06, 0.92) }))
				local pgR = own(L.part({ Material = Enum.Material.Neon, Color = W:Lerp(col, 0.25), Size = Vector3.new(0.68, 0.06, 0.92) }))
				local bookP = own(L.part({ Size = Vector3.new(1.2, 0.2, 1) }))
				local bG = glyphE(bookP, { Color = CS(col:Lerp(W, 0.3), col), Rate = 0, EmissionDirection = Enum.NormalId.Top, Speed = NR(1.5, 3),
					Size = NS({ K(0, 0), K(0.15, 0.45), K(0.8, 0.35), K(1, 0) }) })
				local bM = moteE(bookP, { Color = CS(W, col), Rate = 0, Shape = Enum.ParticleEmitterShape.Sphere, Speed = NR(1, 3) })
				local bF = flareE(bookP, { Color = CS(W, col), Rate = 0, Size = NS({ K(0, 1), K(0.15, 5), K(1, 0) }) })
				local bLight = L.new("PointLight", { Color = col, Range = 12, Brightness = 0, Shadows = false }, bookP)
				local vc, vcm, vcSet = vcircle("mcircle.png", col, 2.2) own(vc)
				local vr, vrm, vrSet = vcircle("runering.png", col:Lerp(W, 0.3), 2.2) own(vr)

				local orbit = {}
				for q = 1, 3 do
					local p = own(L.part({ Size = Vector3.one * 0.2 }))
					local bb = L.new("BillboardGui", { Size = UDim2.fromScale(0.9, 0.9), LightInfluence = 0, Adornee = p, MaxDistance = 200, Enabled = false }, p)
					local cell = (j * 3 + q * 5) % 16
					L.new("ImageLabel", { BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), Image = L.T("glyphs2.png"),
						ImageRectOffset = Vector2.new((cell % 4) * 128, math.floor(cell / 4) * 128), ImageRectSize = Vector2.new(128, 128), ImageColor3 = col:Lerp(W, 0.2) }, bb)
					orbit[q] = { p = p, bb = bb, ph = q / 3 * math.pi * 2 }
				end
				casters[j] = { m = m, parts = parts, hl = hlx, col = col, spot = spot, HY = HY, cvL = cvL, cvR = cvR, pgL = pgL, pgR = pgR, bookP = bookP,
					bG = bG, bM = bM, bF = bF, bLight = bLight, vcSet = vcSet, vrSet = vrSet, orbit = orbit, pivots = pivots,
					up = SIDES - 1.1 + j * 0.08, ph = rnd(0, 6), gone = false }
			end
		end

		local function casterStep(c, t, litT, broke)
			if c.gone then return nil end
			if broke then
				c.gone = true
				for _, pp in ipairs(c.parts) do pp.g.Transparency = 1 end
				c.hl.Enabled = false
				for _, x in ipairs({ c.cvL, c.cvR, c.pgL, c.pgR }) do x.Transparency = 1 end
				c.vcSet(c.bookP.Position, Vector3.xAxis, 0.01, 0, 1) c.vrSet(c.bookP.Position, Vector3.xAxis, 0.01, 0, 1)
				for _, ob in ipairs(c.orbit) do ob.bb.Enabled = false end
				c.bG.Rate, c.bM.Rate, c.bLight.Brightness = 0, 0, 0
				c.bG:Emit(24) c.bM:Emit(40) c.bF:Emit(1)
				L.groundWave(c.spot, "runering.png", c.col, 4, 16, 0.7, 2.4)
				return nil
			end
			local rise = c01((t - c.up) / 0.55)
			if rise <= 0 then return nil end
			local sink = (1 - L.outBack(rise)) * 6
			local pos = c.spot + Vector3.new(0, c.HY - sink + 0.25 * math.sin(t * 1.6 + c.ph) * c01((t - c.up - 0.6) / 0.4), 0)
			local cf = CFrame.lookAt(pos, Vector3.new(o.X, pos.Y, o.Z))
			local lit = t >= litT
			local raise = math.rad(80) * L.outBack(c01((t - (c.up + 0.35)) / 0.35))
			local chant = lit and math.rad(6) * math.sin(t * 9 + c.ph) or 0
			local tr = 1 - c01((t - c.up) / 0.3)
			for _, pp in ipairs(c.parts) do
				local tp = pp.tp
				local rel = tp.rel
				local pv = tp.side and c.pivots[tp.side]
				if pv then
					local inward = tp.side == "L" and -0.28 or 0.28
					rel = CFrame.new(pv) * CFrame.Angles(raise + chant, 0, inward * c01(raise)) * CFrame.new(-pv) * rel
				end
				pp.g.CFrame = cf * rel
				pp.g.Transparency = tr
			end
			c.hl.Enabled = tr < 0.9

			local open = lit and L.outBack(c01((t - litT) / 0.3)) or 0
			local bcf = cf * CFrame.new(0, 0.35, -1.55) * CFrame.Angles(math.rad(35), 0, 0)
			local ang = math.rad(80) * (1 - open) + math.rad(8)
			local flap = lit and math.rad(4) * math.sin(t * 14 + c.ph) or 0
			c.cvL.CFrame = bcf * CFrame.Angles(0, 0, ang + flap) * CFrame.new(-0.38, 0, 0)
			c.cvR.CFrame = bcf * CFrame.Angles(0, 0, -ang - flap) * CFrame.new(0.38, 0, 0)
			c.pgL.CFrame = bcf * CFrame.Angles(0, 0, ang + flap) * CFrame.new(-0.36, 0.07, 0)
			c.pgR.CFrame = bcf * CFrame.Angles(0, 0, -ang - flap) * CFrame.new(0.36, 0.07, 0)
			for _, x in ipairs({ c.cvL, c.cvR }) do x.Transparency = tr end
			for _, x in ipairs({ c.pgL, c.pgR }) do x.Transparency = math.max(tr, 1 - 0.95 * open) end
			c.bookP.CFrame = bcf
			local bp = bcf.Position
			c.bG.Rate = 10 * open
			c.bM.Rate = 18 * open
			c.bLight.Brightness = 3 * open
			if lit and not c.flared then c.flared = true c.bF:Emit(1) c.bG:Emit(10) end

			local toC = (Vector3.new(o.X, bp.Y, o.Z) - bp).Unit
			local cp = bp + Vector3.new(0, 2.1, 0) + toC * 0.4
			local vs = 3.4 * L.outBack(math.min(open, 1))
			c.vcSet(cp, toC, math.max(0.01, vs), t * 1.6, open > 0 and 0.08 or 1, open > 0 and (1 - c01((t - litT) / 0.5)) or nil)
			c.vrSet(cp + toC * 0.05, toC, math.max(0.01, vs * 1.25), -t * 2.4, open > 0 and 0.15 or 1)
			for q, ob in ipairs(c.orbit) do
				local oa = ob.ph + t * 1.8
				ob.p.CFrame = CFrame.new(pos + Vector3.new(math.cos(oa) * 2.2, 0.8 + 0.4 * math.sin(t * 2 + q), math.sin(oa) * 2.2))
				ob.bb.Enabled = open > 0.2
			end
			return open > 0 and cp or nil
		end

		local function mainCol(t, off, nLit, sh)
			if nLit == 0 then return nil end
			local x = (t * 1.3 + off) % nLit
			local i = math.floor(x)
			local c = PAL[i + 1]:Lerp(PAL[(i + 1) % nLit + 1], x - i)
			return c:Lerp(C1, sh)
		end

		local CORE = o + Vector3.new(0, 10, 0)
		local sides = {}
		for j = 0, 5 do
			local a = j / 6 * math.pi * 2 + math.pi / 6
			local pos = o + Vector3.new(math.cos(a) * (R + 6), 0, math.sin(a) * (R + 6))
			local p, m, set = circle("mcircle.png", PAL[j + 1], 1.8) own(p)
			local bp, bset = backing() own(bp)
			local a0, a1 = own(L.att(pos + Vector3.new(0, 0.5, 0))), own(L.att(CORE))
			local b = own(L.beam(a0, a1, { TextureMode = Enum.TextureMode.Wrap, TextureLength = 4, TextureSpeed = 3, Width0 = 1, Width1 = 0.4,
				Brightness = 5, Color = CS(PAL[j + 1], W), Transparency = NS(1) }))
			local fp = own(L.part({ Size = Vector3.new(6, 0.2, 6), CFrame = CFrame.new(pos + Vector3.new(0, 0.3, 0)) }))
			local f = flareE(fp, { Rate = 0, Color = CS(W, PAL[j + 1]), Size = NS({ K(0, 3), K(0.15, 14), K(1, 0) }), Lifetime = NR(0.35) })
			local g = glyphE(fp, { Color = CS(PAL[j + 1]:Lerp(W, 0.3), PAL[j + 1]), Shape = Enum.ParticleEmitterShape.Disc, EmissionDirection = Enum.NormalId.Top, Speed = NR(3, 6), Lifetime = NR(0.8, 1.2) })
			sides[j] = { pos = pos, set = set, bset = bset, b = b, f = f, g = g, a0 = a0, t0 = SIDES + j * 0.3, lit = false, rot = rnd(0, 6) }
		end

		local tower = {}
		for slot, i in ipairs({ 1, 5, 2, 4, 3 }) do
			local p, m, set = circle(i % 2 == 0 and "mcircle.png" or "runering.png", PAL[i], 2)
			own(p)
			tower[i] = { p = p, set = set, y = 3.5 + (i - 1) * 5.5, size = 10 + 3.5 * math.abs(i - 3), t0 = TOWER + (slot - 1) * 0.32, dir = i % 2 == 0 and -1 or 1, slammed = false }
		end
		local spineA, spineB = own(L.att(o + Vector3.new(0, 0.3, 0))), own(L.att(o + Vector3.new(0, 0.3, 0)))
		local spine = own(L.beam(spineA, spineB, { Texture = L.T("softbeam.png"), TextureMode = Enum.TextureMode.Stretch, Width0 = 1.2, Width1 = 1.2,
			Brightness = 4, Segments = 2, Color = CS(W, C2), Transparency = NS(1) }))
		local core = own(L.part({ Size = Vector3.one * 16, CFrame = CFrame.new(CORE) }))
		local coreE = moteE(core, { Shape = Enum.ParticleEmitterShape.Sphere, ShapeStyle = Enum.ParticleEmitterShapeStyle.Surface, Speed = NR(-16, -12),
			Lifetime = NR(0.5, 0.6), Acceleration = Vector3.zero, Drag = 0, Rate = 0, Size = NS({ K(0, 0.35), K(1, 0.1) }) })
		local coreF = flareE(core, { Rate = 0, Lifetime = NR(0.15), Size = NS(10) })
		local coreLight = L.new("PointLight", { Color = C2, Range = 40, Brightness = 0, Shadows = false }, core)

		local pA, pB = own(L.att(o - Vector3.new(0, 1, 0))), own(L.att(o + Vector3.new(0, SKY, 0)))
		local pillar = own(L.beam(pA, pB, { Texture = L.T("softbeam.png"), TextureMode = Enum.TextureMode.Stretch, Width0 = 0.1, Width1 = 0.1,
			Brightness = 5, Segments = 2, Color = CS({ CK(0, W), CK(0.5, C2), CK(1, W) }), Transparency = NS(1) }))
		local pillar2 = own(L.beam(pA, pB, { Width0 = 0.1, Width1 = 0.1, Brightness = 6, Segments = 2, Color = CS(W), Transparency = NS(1) }))

		local letters
		local function nameRing()
			local nm = string.upper(L.name())
			local txt = nm .. " - "
			while #txt < 22 do txt = txt .. nm .. " - " end
			letters = {}
			local rad = math.max(7, #txt * 1.75 / (math.pi * 2))
			for i = 1, #txt do
				local p = own(L.part({ Size = Vector3.one * 0.2 }))
				local bb = L.new("BillboardGui", { Size = UDim2.new(0, 0, 0, 0), LightInfluence = 0, Brightness = 2.5, Adornee = p, MaxDistance = 300 }, p)
				local tl = L.new("TextLabel", { BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), Text = txt:sub(i, i), FontFace = Font.fromEnum(Enum.Font.Fantasy),
					TextScaled = true, TextColor3 = C2:Lerp(W, 0.35), TextStrokeColor3 = BACK, TextStrokeTransparency = 1, TextTransparency = 1 }, bb)
				letters[i] = { p = p, bb = bb, tl = tl, a = i / #txt * math.pi * 2, t0 = REVEAL + 0.15 + i * 0.035, rad = rad }
			end
		end
		local function easeIO(x) x = c01(x) return (1 - math.cos(math.pi * x)) / 2 end
		local body
		local landed, locked, erupted, revealed, broke = false, false, false, false, false
		local lastGc, lastGr = 0, 0
		L.fx(DUR, function(k, t)

			for i = 0, 6 do
				local s = stars[i]
				s.p.CFrame = CFrame.new(starPos(i, t))
				if not s.on and t >= s.t0 then s.on = true s.f:Emit(3) end
				s.f.Rate = (s.on and t < LAND) and 14 or 0
			end
			for i = 0, 6 do
				local ln = lines[i]
				local u = c01((t - ln.t0) / 0.14)
				local p0, p1 = starPos(i, t), starPos(ln.j, t)
				ln.a0.WorldPosition = p0
				ln.a1.WorldPosition = p0:Lerp(p1, u)
				ln.b.Transparency = NS((u > 0 and t < LAND) and 0.1 or 1)
			end
			if not landed and t >= LAND then
				landed = true
				S:flash(C2, 0.45) S:shake(2, 0.5)
				L.groundWave(o, "ring_c.png", W, 6, R * 2.6, 0.6)
				burstP.CFrame = CFrame.new(o + Vector3.new(0, 1, 0)) burst:Emit(40) burstG:Emit(14)
			end
			for i, pn in ipairs(pens) do
				local u = (t - pn.t0) / pn.dur
				if u >= 0 and u <= 1.05 then
					local a = (i == 2 and -1 or 1) * u * math.pi * 2
					pn.p.CFrame = CFrame.new(o + Vector3.new(math.cos(a) * pn.r, 0.3, math.sin(a) * pn.r))
					pn.tr.Enabled, pn.f.Rate = true, 30
				else
					pn.tr.Enabled, pn.f.Rate = false, 0
				end
			end
			local glowUp = c01((t - LOCK) / 0.5) * (1 - c01((t - ERUPT - 0.4) / 0.6))
			local spin = locked and t < BREAK and 0 or 1

			local sh = easeIO((t - SHRINK) / (SETTLE - SHRINK))
			local cen = o:Lerp(ch.feet, sh)
			local idleA = math.max(0.06, 1 - ch.iw * 0.75)
			local endFade = c01((t - SETTLE) / 0.6)
			local landHot = landed and (1 - c01((t - LAND) / 0.6)) or 0
			local breakHot = broke and (1 - c01((t - BREAK) / 0.5)) or 0
			local hotG = math.max(landHot, 0.45 * glowUp, breakHot * 0.8)
			lastGc += (L.lastDt or 0.016) * 0.05 * spin
			lastGr -= (L.lastDt or 0.016) * 0.12 * spin
			local gcRot = lastGc + (ch.clock * 0.12 - lastGc) * sh
			local grRot = lastGr + (-ch.clock * 0.25 - lastGr) * sh
			local trG = landed and math.max(0.06, 0.06 + (idleA - 0.06) * sh) or 1
			local nLit = 0 for j = 0, 5 do if sides[j].lit then nLit += 1 end end
			gcSet(cen + Vector3.new(0, 0.08, 0), R * 2 + (7.5 - R * 2) * sh, gcRot, endFade > 0 and math.max(trG, endFade) or trG, 1.6, mainCol(t, 0, nLit, sh), hotG)
			local u1, u2 = c01((t - pens[1].t0) / pens[1].dur), c01((t - pens[2].t0) / pens[2].dur)
			local trR = u1 > 0 and math.max(0.06, 1 - 0.94 * u1) or 1
			trR = math.max(trR, math.max(0.06, 1 - ch.iw * 0.6) * sh)
			grSet(cen + Vector3.new(0, 0.1, 0), R * 2.08 + (9 - R * 2.08) * sh, grRot, math.max(trR, endFade), 1.8, mainCol(t, 2, nLit, sh) or C2, hotG)
			giSet(cen + Vector3.new(0, 0.12, 0), R * 0.8 * (1 - 0.6 * sh), t * 0.3 * spin, u2 > 0 and math.max(0.06, 1 - 0.94 * u2, c01((t - SHRINK) / 0.8)) or 1, 2, mainCol(t, 4, nLit, sh) or C2, hotG)
			bkSet(CFrame.new(cen + Vector3.new(0, 0.04, 0)), R * 2.3 + (8.6 - R * 2.3) * sh, landed and math.max(0.3 + 0.7 * c01((t - SHRINK) / (SETTLE - SHRINK)), 1 - c01((t - LAND) / 0.4)) or 1)

			local skA = L.outBack((t - (TOWER - 0.3)) / 0.6)
			local skOut = c01((t - BREAK) / 0.4)
			local skPos = o + Vector3.new(0, SKY, 0)
			local skTr = (t > TOWER - 0.3) and math.max(0.06, 0.06 + 0.94 * skOut) or 1
			scSet(skPos, math.max(0.01, R * 1.6 * skA * (1 + 0.3 * skOut)), -t * 0.08 * spin, skTr, 1.6, mainCol(t, 1, nLit, 0) or C1, math.max(0.5 * glowUp, erupted and (1 - c01((t - ERUPT) / 0.8)) or 0), true)
			srSet(skPos + Vector3.new(0, -0.05, 0), math.max(0.01, R * 1.7 * skA * (1 + 0.3 * skOut)), t * 0.15 * spin, skTr, 1.8, mainCol(t, 3, nLit, 0) or C2, 0.45 * glowUp, true)
			skBSet(CFrame.new(skPos + Vector3.new(0, 0.15, 0)) * CFrame.Angles(math.pi, 0, 0), math.max(0.01, R * 1.8 * skA), (t > TOWER - 0.3) and math.max(0.3, skOut) or 1)
			skyG.Rate = (t > TOWER and t < BREAK) and 14 or 0

			local charge = 0
			for j = 0, 5 do
				local sd = sides[j]
				local u = c01((t - sd.t0) / 0.2)
				if not sd.lit and t >= sd.t0 then
					sd.lit = true
					sd.f:Emit(1) sd.g:Emit(10)
					S:shake(0.5, 0.15)
					L.groundWave(sd.pos, "ring_c.png", C2, 2, 12, 0.4, 2)
				end
				if sd.lit then charge += 1 end
				local out = c01((t - BREAK) / 0.3)
				if broke and not sd.burst then sd.burst = true sd.g:Emit(16) burstP.CFrame = CFrame.new(sd.pos + Vector3.new(0, 1, 0)) burst:Emit(12) end
				local hot = sd.lit and math.max(1 - c01((t - sd.t0) / 0.4), 0.5 * glowUp) or 0
				sd.set(sd.pos + Vector3.new(0, 0.1, 0), 8 * L.outBack(u) * (1 + 0.3 * out), sd.rot + t * 0.6 * spin, u > 0 and math.max(0.06, 0.06 + 0.94 * out) or 1, 1.8, nil, hot)
				sd.bset(CFrame.new(sd.pos + Vector3.new(0, 0.05, 0)), 9.5 * L.outBack(u), u > 0 and math.max(0.35, out) or 1)
				local cp = casterStep(casters[j], t, sd.t0, broke)
				if cp then sd.a0.WorldPosition = cp end
				local bu = c01((t - sd.t0 - 0.1) / 0.2) * (1 - out)
				sd.b.Transparency = NS(1 - 0.75 * bu)
				sd.b.Width0 = 0.8 + 0.6 * glowUp
			end

			for i, tw in ipairs(tower) do
				local g = c01((t - tw.t0) / 0.25)
				if g > 0 and not tw.slammed then
					tw.slammed = true
					S:shake(0.6 + 0.15 * i, 0.25)
					burstP.CFrame = CFrame.new(o + Vector3.new(0, tw.y, 0)) burst:Emit(12)
				end
				if not tw.gone then
					local fromY = tw.y < SKY / 2 and -3 or 3
					tw.set(o + Vector3.new(0, tw.y + (1 - g) * fromY, 0), math.max(0.01, tw.size * L.outBack(g)), tw.dir * t * (locked and 0 or (1.2 + 0.25 * charge)),
						g > 0 and 0.06 or 1, 2, nil, math.max(0.08 * charge, 0.6 * glowUp))
				end
			end
			spineB.WorldPosition = o + Vector3.new(0, 0.3 + SKY * c01((t - TOWER) / 1.4), 0)
			local fade = c01((t - BREAK) / 0.25)
			spine.Transparency = NS(1 - 0.7 * c01((t - TOWER) / 0.3) * (1 - fade))
			spine.Width0, spine.Width1 = 1 + 0.15 * charge + 1.5 * glowUp, 1 + 0.15 * charge + 1.5 * glowUp

			if not locked and t >= LOCK then
				locked = true
				S:flash(C2, 0.35) S:shake(1.2, 0.3)
			end
			local charging = t >= LOCK and t < ERUPT
			coreE.Rate = charging and 260 or 0
			coreF.Rate = charging and 25 or 0
			coreLight.Brightness = 6 * glowUp
			if charging then S:shake(0.3 + 0.9 * c01((t - LOCK) / (ERUPT - LOCK)), 0.1) end

			if not erupted and t >= ERUPT then
				erupted = true
				S:flash(W, 0.8) S:shake(3, 1)
				skyF:Emit(1)
				L.groundWave(o, "ring_c.png", W, 4, 50, 0.6)
				burstP.CFrame = CFrame.new(o + Vector3.new(0, 2, 0)) burst:Emit(80) burstG:Emit(30)
				body = summonBody(C2, REVEAL - ERUPT + 0.05)
			end
			local pu = c01((t - ERUPT) / 0.15) * (1 - c01((t - REVEAL - 0.2) / 0.8))
			pillar.Width0, pillar.Width1 = 12 * pu, 12 * pu
			pillar2.Width0, pillar2.Width1 = 3 * pu, 3 * pu
			pillar.Transparency = NS(1 - 0.8 * pu)
			pillar2.Transparency = NS(1 - 0.85 * pu)
			if body then
				local ru = L.outQuad((t - ERUPT) / (REVEAL - ERUPT))
				body(Vector3.new(0, -5 * (1 - ru), 0), 1 - 0.7 * c01((t - ERUPT) / 0.4), C2:Lerp(W, ru))
			end
			if not revealed and t >= REVEAL then
				revealed = true
				appear(C2, hideTok)
				S:flash(C2:Lerp(W, 0.5), 0.6) S:shake(1.6, 0.5)
				nameRing()
			end
			if letters then
				local c = ch.pos
				local out = c01((t - (DUR - 2.4)) / 0.8)
				for i, lt in ipairs(letters) do
					local a = lt.a + t * 0.45
					lt.p.CFrame = CFrame.new(c + Vector3.new(math.cos(a) * lt.rad, 0.6 + 0.25 * math.sin(t * 2 + lt.a * 3), math.sin(a) * lt.rad))
					local u = c01((t - lt.t0) / 0.25)
					local s = 1.8 * L.outBack(u) * (1 - 0.5 * out)
					lt.bb.Size = UDim2.new(s, 0, s, 0)
					lt.tl.TextTransparency = u > 0 and math.max(0, out, 1 - u * 1.5) or 1
					lt.tl.TextStrokeTransparency = u > 0 and math.max(0.15, out) or 1
					lt.tl.TextColor3 = C2:Lerp(W, 0.35 + 0.65 * (1 - c01((t - lt.t0) / 0.4)))
				end
			end

			if not broke and t >= BREAK then
				broke = true
				S:shake(2.2, 0.9)
				for _, tw in ipairs(tower) do
					tw.gone = true
					tw.p.Transparency = 1
					burstP.CFrame = CFrame.new(o + Vector3.new(0, tw.y, 0)) burstG:Emit(14) burst:Emit(16)
				end
				skyG:Emit(40)
				L.groundWave(o, "runering.png", C2, R * 2, R * 3.4, 1.1, 2.4)
				L.groundWave(o, "ring_c.png", C1, 10, 1400, 5.4, 2.6)
				light.Brightness = 8
			end
		end, objs)

		L.after(BREAK, function()
			local sp = L.part({ Size = Vector3.new(34, 0.2, 34), CFrame = CFrame.new(o + Vector3.new(0, SKY - 3, 0)) })
			local ge = glyphE(sp, { Shape = Enum.ParticleEmitterShape.Box, EmissionDirection = Enum.NormalId.Bottom, Speed = NR(3, 5), Lifetime = NR(3, 4),
				Acceleration = Vector3.new(0, -2.5, 0), Size = NS({ K(0, 0), K(0.1, 0.8), K(0.85, 0.7), K(1, 0) }) })
			local me = moteE(sp, { Shape = Enum.ParticleEmitterShape.Box, EmissionDirection = Enum.NormalId.Bottom, Speed = NR(3, 6), Lifetime = NR(3, 4), Acceleration = Vector3.new(0, -2, 0) })
			L.fx(3.2, function(kk) ge.Rate = 40 * (1 - kk) me.Rate = 60 * (1 - kk) end, { sp })
		end)
		task.delay(DUR + 0.1, function() setHidden(false, hideTok) end)
	end

	local shorts = {}


	shorts[1] = function()
		local o = ch.feet
		local DUR, LANDB, SNAP0, OPEN, CYC, FORM, BURN, BEND = 3.7, 0.4, 0.62, 1.05, 1.15, 2.25, 2.6, 3.05
		local hideTok = setHidden(true)
		local fwd = camBasis()
		local bookC = o + Vector3.new(0, 7.5, 0)
		local objs = {}
		local function own(x) objs[#objs + 1] = x return x end
		local PAPER = Color3.fromRGB(240, 226, 196)
		local CHAR = Color3.fromRGB(35, 22, 18)
		local covers = {}
		for s = 1, 2 do
			local cv = own(L.part({ Size = Vector3.new(2.2, 0.16, 3), Material = Enum.Material.Fabric, Color = Color3.fromRGB(28, 18, 45), Transparency = 1 }))
			local trim = own(L.part({ Size = Vector3.new(2.36, 0.1, 3.16), Material = Enum.Material.Neon, Color = C1, Transparency = 1 }))
			local pg = own(L.part({ Size = Vector3.new(2.05, 0.12, 2.8), Material = Enum.Material.SmoothPlastic, Color = Color3.fromRGB(240, 226, 196), Transparency = 1 }))
			covers[s] = { p = cv, pg = pg, trim = trim }
		end
		local lockP, lockM = mmesh("disc.mesh", "mcircle.png", C2, 1.3, Vector3.new(1.4, 1, 1.4)) own(lockP)
		local chains = {}
		for kk = 1, 3 do
			local A, B, Cc = own(L.att(bookC)), own(L.att(bookC)), own(L.att(bookC))
			local props = { Texture = L.T("chain.png"), TextureMode = Enum.TextureMode.Wrap, TextureLength = 0.75, Width0 = 0.55, Width1 = 0.55, LightEmission = 0.1,
				Brightness = 1.5, Color = CS(Color3.fromRGB(170, 180, 205)), Transparency = NS(1) }
			chains[kk] = { A = A, B = B, C = Cc, b1 = own(L.beam(A, B, props)), b2 = own(L.beam(B, Cc, props)), z = (kk - 2) * 0.95, t = SNAP0 + (kk - 1) * 0.16 }
		end
		local bookP = own(L.part({ Size = Vector3.new(3, 0.5, 3), CFrame = CFrame.new(bookC) }))
		local glow = flareE(bookP, { Rate = 0, Lifetime = NR(0.2), Size = NS(6) })
		local pagesE = L.pe(bookP, { Texture = L.T("page.png"), Color = CS(PAPER), LightEmission = 0.3, Brightness = 1.5, Shape = Enum.ParticleEmitterShape.Box,
			Speed = NR(4, 8), SpreadAngle = Vector2.new(70, 70), Lifetime = NR(0.8, 1.2), RotSpeed = NR(-300, 300), Rotation = NR(0, 360),
			Size = NS({ K(0, 0.6), K(1, 0.45) }), Transparency = NS({ K(0, 0), K(0.8, 0), K(1, 1) }), Acceleration = Vector3.new(0, -14, 0), Rate = 0 })
		local pourA, pourB = own(L.att(bookC)), own(L.att(bookC + Vector3.new(0, 14, 0)))
		local pour = own(L.beam(pourA, pourB, { Texture = L.T("softbeam.png"), TextureMode = Enum.TextureMode.Stretch, Width0 = 0.1, Width1 = 0.1, Brightness = 4,
			Segments = 2, Color = CS(W, C2), Transparency = NS({ K(0, 1), K(1, 1) }) }))
		local pages = {}
		for i = 1, 26 do
			local p, m = mmesh("quad.mesh", "page.png", PAPER:Lerp(C2, 0.15), 1.1, Vector3.new(0.9, 1, 1.2))
			own(p) p.Transparency = 1
			pages[i] = { p = p, ph = i * 2.39996, h = (i - 1) / 25, r0 = rnd(3.2, 4.3), t0 = CYC + i * 0.025, spin = rnd(0.85, 1.2) }
		end
		local fireP = own(L.part({ Size = Vector3.new(3.2, 0.5, 2.2), CFrame = CFrame.new(o) }))
		local fire = L.pe(fireP, { Texture = L.T("flame.png"), Color = CS(W, C1), LightEmission = 1, Brightness = 4, Shape = Enum.ParticleEmitterShape.Box,
			Speed = NR(2, 4), Lifetime = NR(0.35, 0.55), Size = NS({ K(0, 0.9), K(1, 0) }), Transparency = NS({ K(0, 0.2), K(1, 1) }), Acceleration = Vector3.new(0, 6, 0), Rate = 0 })
		local fireG = glyphE(fireP, { Shape = Enum.ParticleEmitterShape.Box, Speed = NR(2, 4), Lifetime = NR(0.6, 0.9), Rate = 0 })
		local paper
		local closedBurst, opened, done = false, false, false
		L.fx(DUR, function(k, t)

			local u = L.inQuad(t / LANDB)
			local pos = bookC + Vector3.new(0, 10 * (1 - u), 0)
			if t > LANDB and t < OPEN then pos += Vector3.new(rnd(-1, 1), rnd(-1, 1), rnd(-1, 1)) * 0.07 * c01((t - LANDB) / 0.3) end
			local base = CFrame.lookAt(pos, pos - fwd) * CFrame.Angles(math.rad(-60), 0, 0)
			local open = L.outBack((t - OPEN) / 0.25)
			local appearA = c01(t / 0.15) * (1 - c01((t - FORM) / 0.25))
			local spX = -1.1 * (1 - c01(open))
			for s, c in ipairs(covers) do
				local phi = s == 1 and math.rad(14 * open) or math.rad(4 + 162 * open)
				local hinge = base * CFrame.new(spX, 0.3 * (s - 1) * (1 - c01(open)), 0) * CFrame.Angles(0, 0, phi)
				c.p.CFrame = hinge * CFrame.new(1.1, 0, 0)
				c.pg.CFrame = hinge * CFrame.new(1.05, s == 1 and 0.12 or -0.12, 0)
				c.p.Transparency = 1 - appearA
				c.trim.CFrame = hinge * CFrame.new(1.1, s == 1 and -0.04 or 0.04, 0)
				c.trim.Transparency = 1 - appearA * 0.75
				c.pg.Transparency = 1 - appearA * (open > 0 and 0.9 or 0.5)
			end
			lockP.CFrame = base * CFrame.new(0, 0.48, 0) * CFrame.Angles(0, t * 2, 0)
			lockP.Transparency = t < OPEN and (1 - 0.9 * appearA) or 1
			capTint(lockM, C2, 1.3, 0.5 + 0.5 * math.sin(t * 25) * c01((t - LANDB) / 0.2))
			for _, c in ipairs(chains) do
				c.A.WorldPosition = base:PointToWorldSpace(Vector3.new(-1.35, -0.15, c.z))
				c.B.WorldPosition = base:PointToWorldSpace(Vector3.new(0, 0.6, c.z))
				c.C.WorldPosition = base:PointToWorldSpace(Vector3.new(1.35, -0.15, c.z))
				if not c.snapped and t >= c.t then
					c.snapped = true
					burstP.CFrame = CFrame.new(c.B.WorldPosition) burst:Emit(12) burstG:Emit(3)
