				end
				local tr = c.snapped and 1 or (1 - appearA * 0.95)
				c.b1.Transparency, c.b2.Transparency = NS(tr), NS(tr)
			end
			if not opened and t >= OPEN then
				opened = true
				glow:Emit(2)
				burstP.CFrame = CFrame.new(pos) burst:Emit(30)
