			end
			glow.Rate = (t > OPEN and t < FORM) and 15 or 0
			bookP.CFrame = CFrame.new(pos)
			pagesE.Rate = (t > OPEN and t < FORM - 0.2) and 40 or 0
			local pu = c01((t - OPEN) / 0.1) * (1 - c01((t - OPEN - 0.3) / 0.5))
			pourA.WorldPosition, pourB.WorldPosition = pos, pos + Vector3.new(0, 16, 0)
			pour.Width0, pour.Width1 = 3 * pu, 6 * pu
			pour.Transparency = NS({ K(0, 1 - 0.8 * pu), K(1, 1) })
			if not closedBurst and t >= FORM then
				closedBurst = true
				burstP.CFrame = CFrame.new(pos) burstG:Emit(16) burst:Emit(20)
			end

			local cen = ch.pos
			local foot, headY = ch.feet.Y, ch.head.Position.Y + 0.6
			local tight = L.inQuad((t - FORM) / (BURN - FORM))
			for _, pg in ipairs(pages) do
				local e = c01((t - pg.t0) / 0.3)
				if e > 0 then
					local a = pg.ph + t * 7 * pg.spin * (1 + tight)
					local r = pg.r0 * (1 - 0.75 * tight)
					local hh = foot + 0.3 + pg.h * ((headY - foot + 4) * (1 - tight) + (headY - foot - 0.4) * tight)
					local slot = Vector3.new(cen.X + math.cos(a) * r, hh, cen.Z + math.sin(a) * r)
					local pp = pos:Lerp(slot, L.outQuad(e))
					pg.p.CFrame = CFrame.lookAt(pp, Vector3.new(cen.X, pp.Y, cen.Z)) * CFrame.Angles(math.rad(90), 0, 0) * CFrame.Angles(0, 0, math.sin(t * 9 + pg.ph) * 0.4)
					pg.p.Transparency = math.max(0.06, c01((t - BURN + 0.1) / 0.15))
				end
			end
			if not paper and t >= FORM then
				paper = {}
				for _, gp in ipairs(L.ghost(PAPER, Enum.Material.SmoothPlastic, BEND - FORM + 0.2, true):GetChildren()) do gp.Transparency = 1 paper[#paper + 1] = gp end
			end
			local line = foot - 0.3 + (headY + 0.9 - foot) * c01((t - BURN) / (BEND - BURN))
			if paper then
				local fin = c01((t - FORM - 0.1) / (BURN - FORM - 0.1))
				for _, gp in ipairs(paper) do
					if gp.Parent then
						local d = gp.Position.Y - line
						if t < BURN then gp.Transparency = 1 - fin
						elseif d < 0 then gp.Transparency = 1
						elseif d < 0.5 then gp.Transparency, gp.Material, gp.Color = 0, Enum.Material.Neon, C1:Lerp(W, 0.3)
						elseif d < 1.2 then gp.Transparency, gp.Material, gp.Color = 0, Enum.Material.SmoothPlastic, CHAR
						else gp.Transparency, gp.Material, gp.Color = 0, Enum.Material.SmoothPlastic, PAPER end
					end
				end
			end
			fireP.CFrame = CFrame.new(cen.X, line, cen.Z)
			local burning = t >= BURN and t < BEND
			fire.Rate = burning and 240 or 0
			fireG.Rate = burning and 25 or 0
			if not done and t >= BEND then
				done = true
				appear(C1, hideTok)
				L.groundWave(o, "runering.png", C2, 2, 12, 0.6, 2.4)
			end
		end, objs)
		task.delay(DUR + 0.1, function() setHidden(false, hideTok) end)
	end


	shorts[2] = function()
		local o = ch.feet
		local DUR, OPEN, WALK, OUT = 3.4, 1.35, 1.55, 2.5
		local hideTok = setHidden(true)
		local fwd, right = camBasis()
		local G = o + Vector3.new(0, 3.4, 0) + fwd * 3
		local face = -fwd
		local objs = {}
		local function own(x) objs[#objs + 1] = x return x end
		local spec = {
			{ tex = "runering.png", col = C2, size = 9, lock = 0.7 },
			{ tex = "mcircle.png", col = C1, size = 6.8, lock = 0.95 },
			{ tex = "runering.png", col = C2, size = 4.6, lock = 1.2 },
			{ tex = "mcircle.png", col = C1, size = 6, deep = true },
			{ tex = "runering.png", col = C2, size = 5, deep = true },
		}
		local rings = {}
		for i, sp in ipairs(spec) do
			local p, m, set = vcircle(sp.tex, sp.col, 1.6) own(p)
			rings[i] = { p = p, set = set, sp = sp, rot0 = (i % 2 == 0 and -1 or 1) * rnd(2.5, 4) }
		end
		local keyP, keyM, keySet = vcircle("mcircle.png", W, 1.3) own(keyP)
		local bkP, bkSet = backing() own(bkP)
		local endP = own(L.part({ Size = Vector3.new(4, 4, 0.2) }))
		local stream = moteE(endP, { Shape = Enum.ParticleEmitterShape.Box, EmissionDirection = Enum.NormalId.Front, Speed = NR(8, 14), Lifetime = NR(0.6, 0.9),
			Acceleration = Vector3.zero, Drag = 0, SpreadAngle = Vector2.new(15, 15) })
		local streamG = glyphE(endP, { Shape = Enum.ParticleEmitterShape.Box, EmissionDirection = Enum.NormalId.Front, Speed = NR(5, 9), Lifetime = NR(0.7, 1),
			Acceleration = Vector3.zero, SpreadAngle = Vector2.new(20, 20) })
		local body, bodyD
		local opened, out = false, false
		L.fx(DUR, function(k, t)
			local inA = L.outBack(t / 0.3)
			local openU = L.outQuad((t - OPEN) / 0.35)
			for i, r in ipairs(rings) do
				local sp = r.sp
				if not r.gone then
					local depth = (i - 1) * 2.4 * openU
					local size, rot, tr, hot
					if sp.deep then
						local a = c01((t - OPEN - 0.05 * i) / 0.3)
						size, rot, tr, hot = sp.size * L.outBack(a), t * (i % 2 == 0 and -0.8 or 0.8), a > 0 and 0.06 or 1, 0
					else

						local u = c01(t / sp.lock)
						rot = r.rot0 * (1 - u) ^ 2
						if t >= sp.lock then rot = 0.06 * math.sin((t - sp.lock) * 30) * math.exp(-(t - sp.lock) * 8) end
						if not r.locked and t >= sp.lock then
							r.locked = true
							burstP.CFrame = CFrame.new(G + Vector3.new(0, sp.size * 0.45, 0)) burst:Emit(10) burstG:Emit(3)
							L.groundWave(o + fwd * 3, "ring_c.png", sp.col, 2, 9, 0.35, 1.8)
							light.Brightness = 5
						end
						if opened then rot += (t - OPEN) * 0.6 * (i % 2 == 0 and -1 or 1) end
						size, tr = sp.size * inA, 0.06
						hot = r.locked and 0.9 * (1 - c01((t - sp.lock) / 0.3)) or 0
					end

					if bodyD then hot = math.max(hot, 0.8 * (1 - c01(math.abs(bodyD - depth) / 1.2))) end
					r.set(G + fwd * depth, face, math.max(0.01, size), rot, tr, hot)
				end
			end
			keySet(G - fwd * 0.05, face, math.max(0.01, 2.4 * inA), t * 3, t < OPEN and 0.06 or 1)
			if not opened and t >= OPEN then
				opened = true
				burstP.CFrame = CFrame.new(G) burstG:Emit(14) burst:Emit(24)
				L.groundWave(o, "runering.png", C2, 3, 14, 0.6, 2)
			end

			local endD = 10.8 * openU + 0.15
			local fadeOut = c01((t - OUT) / 0.3)
			bkSet(orient(G + fwd * endD, face), math.max(0.01, (8.6 - 3 * openU) * inA), math.max(0.3 - 0.15 * openU, fadeOut))
			endP.CFrame = CFrame.lookAt(G + fwd * endD, G + fwd * endD + face)
			stream.Rate = (opened and not out) and 60 or 0
			streamG.Rate = (opened and not out) and 10 or 0

			if not body and t >= WALK then body = summonBody(C2, OUT - WALK + 0.05) end
			if body and not out then
				local u = L.outQuad((t - WALK) / (OUT - WALK))
				local off = 12 * (1 - u)
				bodyD = off - 3
				body(fwd * off, 1 - 0.75 * c01((t - WALK) / 0.3), C1:Lerp(C2, u):Lerp(W, u * u))
			end

			if not out and t >= OUT then
				out = true
				bodyD = nil
				appear(C2, hideTok)
				for i, r in ipairs(rings) do
					r.gone = true
					r.p.Transparency = 1
					local depth = (i - 1) * 2.4
					local rad = r.sp.size * 0.45
					for q = 1, 6 do
						local a = q / 6 * math.pi * 2 + i
						shards(G + fwd * depth + (right * math.cos(a) + Vector3.yAxis * math.sin(a)) * rad, 1, 16, 0.8, r.sp.col)
					end
					burstP.CFrame = CFrame.new(G + fwd * depth) burstG:Emit(6)
				end
				L.groundWave(o, "ring_c.png", C2, 3, 16, 0.5, 2)
			end
		end, objs)
		task.delay(DUR + 0.1, function() setHidden(false, hideTok) end)
	end


	shorts[3] = function()
		local o = ch.feet
		local SNAP, DONE, DUR = 0.85, 1.05, 1.5
		local hideTok = setHidden(true)
		local fwd, right = camBasis()
		local spots = { o + right * 5 + fwd * 2, o - right * 5 + fwd * 3, o - fwd * 3 + right * 1.5 }
		local objs = {}
		local function own(x) objs[#objs + 1] = x return x end
		local marks = {}
		for i, sp in ipairs(spots) do
			local p, m, set = vcircle("mcircle.png", i % 2 == 0 and C2 or C1, 1.6) own(p)
			local bp, bset = backing() own(bp)
			local a0, a1 = own(L.att(sp)), own(L.att(sp))
			local b = own(L.beam(a0, a1, { Width0 = 0.35, Width1 = 0.35, Brightness = 4, LightEmission = 0.6, Color = CS(C2, C1), Transparency = NS(1) }))
			marks[i] = { sp = sp, set = set, bset = bset, a0 = a0, a1 = a1, b = b, t0 = (i - 1) * 0.22, rot = rnd(0, 6) }
		end
		local done = false
		L.fx(DUR, function(k, t)
			local snap = L.inQuad((t - SNAP) / (DONE - SNAP))
			local home = o + Vector3.new(0, 2.6, 0)
			local prev = home
			for _, mk in ipairs(marks) do
				local on = t >= mk.t0
				if on and not mk.fired then
					mk.fired = true
					burstP.CFrame = CFrame.new(mk.sp + Vector3.new(0, 2.6, 0)) burst:Emit(14) burstG:Emit(4)
					L.groundWave(mk.sp, "runering.png", C2, 2, 7, 0.4, 1.8)
					mk.ghost = summonBody(C1, DONE + 0.05 - mk.t0)
				end
				local c = (mk.sp + Vector3.new(0, 2.6, 0)):Lerp(home, snap)
				local fd = workspace.CurrentCamera.CFrame.Position - c
				fd = Vector3.new(fd.X, 0, fd.Z)
				fd = fd.Magnitude > 0.01 and fd.Unit or -fwd
				local a = c01((t - mk.t0) / 0.15)
				local sz = math.max(0.01, 4 * L.outBack(a) * (1 - 0.8 * snap))
				mk.set(c, fd, sz, mk.rot + t * 3, (on and t < DONE) and 0.06 or 1, (1 - a) + snap)
				mk.bset(orient(c - fd * 0.05, fd), sz * 1.1, (on and t < DONE) and 0.4 or 1)
				if mk.ghost then
					local d = (mk.sp - o) * (1 - snap)
					mk.ghost(Vector3.new(d.X, 0, d.Z), math.min(1, 0.35 + 0.4 * c01((t - mk.t0) / 0.6) + 0.25 * snap), C1:Lerp(W, snap))
				end

				local lu = c01((t - mk.t0) / 0.12)
				mk.a0.WorldPosition = prev
				mk.a1.WorldPosition = prev:Lerp(c, lu)
				mk.b.Transparency = NS((on and t < DONE) and 0.15 or 1)
				prev = c
			end
			if not done and t >= DONE then
				done = true
				appear(C2, hideTok)
				burstP.CFrame = CFrame.new(home) burst:Emit(40) burstG:Emit(12)
				L.groundWave(o, "runering.png", C2, 2, 12, 0.5, 2)
				L.groundWave(o, "ring_c.png", W, 2, 9, 0.35, 1.8)
			end
		end, objs)
		task.delay(DUR + 0.1, function() setHidden(false, hideTok) end)
	end


	shorts[4] = function()
		local o = ch.feet
		local DUR, BEAM, FIRE, ICE, BOLT = 2.8, 0.95, 1.35, 1.6, 1.85
		local hideTok = setHidden(true)
		local fwd, right = camBasis()
		local cols = { Color3.fromRGB(255, 90, 20), Color3.fromRGB(80, 185, 255), Color3.fromRGB(255, 210, 50) }
		local objs = {}
		local function own(x) objs[#objs + 1] = x return x end
		local CEN = o + Vector3.new(0, 3, 0)
		local nodes = {}
		for i = 1, 3 do
			local a = i / 3 * math.pi * 2 + math.pi / 2
			local pos = o + (right * math.cos(a) + fwd * math.sin(a)) * 5.5
			local orb = own(L.part({ Shape = Enum.PartType.Ball, Material = Enum.Material.Neon, Color = cols[i], Size = Vector3.one * 0.9, Transparency = 1, CFrame = CFrame.new(CEN) }))
			local oa0 = L.new("Attachment", { Position = Vector3.new(0, 0.3, 0) }, orb)
			local oa1 = L.new("Attachment", { Position = Vector3.new(0, -0.3, 0) }, orb)
			L.new("Trail", { Attachment0 = oa0, Attachment1 = oa1, Texture = L.T("beamb.png"), LightEmission = 1, Brightness = 5, Lifetime = 0.3,
				FaceCamera = true, Color = CS(W, cols[i]), Transparency = NS(0, 1), WidthScale = NS(1, 0.2) }, orb)
			local f = flareE(orb, { Rate = 0, Lifetime = NR(0.12), Size = NS(3.5), Color = CS(cols[i]) })
			local cp, cm, cset = circle("mcircle.png", cols[i], 1.5) own(cp)
			local bp, bset = backing() own(bp)
			local ep = own(L.part({ Size = Vector3.new(4, 0.2, 4), CFrame = CFrame.new(pos + Vector3.new(0, 0.2, 0)) }))
			local em
			if i == 1 then
				em = L.pe(ep, { Texture = L.T("flame.png"), Color = CS(W, cols[1]), LightEmission = 1, Brightness = 3, Shape = Enum.ParticleEmitterShape.Disc,
					EmissionDirection = Enum.NormalId.Top, Speed = NR(2, 4), Lifetime = NR(0.4, 0.7), Size = NS({ K(0, 0.9), K(1, 0) }),
					Transparency = NS({ K(0, 0.2), K(1, 1) }), Acceleration = Vector3.new(0, 5, 0) })
			elseif i == 2 then
				em = L.pe(ep, { Texture = L.T("snow.png"), Color = CS(W, cols[2]), LightEmission = 0.6, Brightness = 2, Shape = Enum.ParticleEmitterShape.Disc,
					EmissionDirection = Enum.NormalId.Top, Speed = NR(0.5, 1.5), Lifetime = NR(0.8, 1.2), Size = NS({ K(0, 0.4), K(1, 0) }),
					Transparency = NS({ K(0, 0.2), K(1, 1) }), Acceleration = Vector3.new(0, 1, 0) })
			else
				em = moteE(ep, { Color = CS(W, cols[3]), Shape = Enum.ParticleEmitterShape.Disc, EmissionDirection = Enum.NormalId.Top, Speed = NR(3, 6),
					Lifetime = NR(0.2, 0.35), Drag = 3, Acceleration = Vector3.zero })
			end
			local a0, a1 = own(L.att(pos + Vector3.new(0, 0.5, 0))), own(L.att(CEN))
			local b = own(L.beam(a0, a1, { TextureMode = Enum.TextureMode.Wrap, TextureLength = 3, TextureSpeed = 4, Width0 = 1.2, Width1 = 0.5, LightEmission = 0.4,
				Brightness = 4, Color = CS(cols[i], cols[i]:Lerp(W, 0.4)), Transparency = NS(1) }))
			nodes[i] = { pos = pos, orb = orb, f = f, cset = cset, bset = bset, em = em, b = b, t0 = 0.15 + (i - 1) * 0.18, rot = rnd(0, 6) }
		end
		local core = own(L.part({ Size = Vector3.one, CFrame = CFrame.new(CEN) }))
		local coreF = flareE(core, { Rate = 0, Lifetime = NR(0.15), Size = NS(6) })

		local pillarP = own(L.part({ Size = Vector3.new(2.5, 1, 2.5), CFrame = CFrame.new(o + Vector3.new(0, 0.5, 0)) }))
		local pillarE = L.pe(pillarP, { Texture = L.T("flame.png"), Color = CS(W, cols[1]), LightEmission = 1, Brightness = 4, Shape = Enum.ParticleEmitterShape.Box,
			EmissionDirection = Enum.NormalId.Top, Speed = NR(14, 22), Lifetime = NR(0.35, 0.6), SpreadAngle = Vector2.new(8, 8), Size = NS({ K(0, 1.6), K(1, 0.3) }),
			Transparency = NS({ K(0, 0.1), K(1, 1) }) })
		local fA, fB = own(L.att(o)), own(L.att(o + Vector3.new(0, 16, 0)))
		local fBeam = own(L.beam(fA, fB, { Texture = L.T("softbeam.png"), TextureMode = Enum.TextureMode.Stretch, Width0 = 0.1, Width1 = 0.1, Brightness = 5,
			Segments = 2, Color = CS(W, cols[1]), Transparency = NS(1) }))
		local fired, iced, struck = false, false, false
		local zapT = 0
		L.fx(DUR, function(k, t)
			local out = c01((t - BOLT - 0.3) / 0.5)
			for i, nd in ipairs(nodes) do

				local u = c01((t - nd.t0) / 0.35)
				local target = nd.pos + Vector3.new(0, 0.6, 0)
				nd.orb.CFrame = CFrame.new(CEN:Lerp(target, L.outQuad(u)) + Vector3.new(0, 3 * math.sin(math.pi * u), 0))
				nd.orb.Transparency = (u < 1) and 0 or 1
				nd.f.Rate = (u > 0 and u < 1) and 20 or 0
				if u >= 1 and not nd.landed then
					nd.landed = true
					L.groundWave(nd.pos, "ring_c.png", cols[i], 1, 8, 0.4, 2)
					burstP.CFrame = CFrame.new(target) burst:Emit(12)
					if i == 2 then shards(target, 5, 12, 0.5, cols[2]) end
				end
				local ca = nd.landed and c01((t - nd.t0 - 0.35) / 0.2) or 0
				local beamOn = t >= BEAM + (i - 1) * 0.06 and t < BOLT + 0.1
				nd.cset(nd.pos + Vector3.new(0, 0.1, 0), math.max(0.01, 6 * L.outBack(ca) * (1 + 0.2 * out)), nd.rot + t * 1.2, ca > 0 and math.max(0.06, out) or 1, 1.5, nil,
					(1 - ca) + (beamOn and 0.12 or 0))
				nd.bset(CFrame.new(nd.pos + Vector3.new(0, 0.05, 0)), math.max(0.01, 6.8 * L.outBack(ca)), ca > 0 and math.max(0.4, out) or 1)
				nd.em.Rate = (nd.landed and out < 1) and (i == 3 and 40 or 25) or 0
				nd.b.Transparency = NS(beamOn and 0.15 or 1)
				nd.b.Width0 = 1 + 0.35 * math.sin(t * 30 + i)
			end

			zapT += L.lastDt or 0.016
			if nodes[3].landed and t < BOLT and zapT > 0.1 then
				zapT = 0
				local c = nodes[3].pos + Vector3.new(0, 0.3, 0)
				local a1, a2 = rnd(0, 6.28), rnd(0, 6.28)
				L.bolt(c + Vector3.new(math.cos(a1), 0, math.sin(a1)) * 2.3, c + Vector3.new(math.cos(a2), 0.6, math.sin(a2)) * 2.3, { w = 0.15, life = 0.1, col = W, glow = cols[3], segs = 5 })
			end
			coreF.Rate = (t >= BEAM and t < FIRE) and 30 or 0

			if not fired and t >= FIRE then
				fired = true
				L.groundWave(o, "ring_c.png", cols[1], 2, 12, 0.45, 2.2)
				light.Brightness = 6
			end
			pillarE.Rate = (t >= FIRE and t < FIRE + 0.25) and 320 or 0
			local fu = c01((t - FIRE) / 0.08) * (1 - c01((t - FIRE - 0.2) / 0.4))
			fBeam.Width0, fBeam.Width1 = 5 * fu, 3 * fu
			fBeam.Transparency = NS({ K(0, 1 - 0.85 * fu), K(1, 1) })
			if not iced and t >= ICE then
				iced = true
				shards(o + Vector3.new(0, 1, 0), 14, 22, 0.7, cols[2])
				L.groundWave(o, "cracks_b.png", cols[2], 2, 13, 0.7, 2)
				burstP.CFrame = CFrame.new(o + Vector3.new(0, 1, 0)) burst:Emit(20)
			end
			if not struck and t >= BOLT then
				struck = true
				L.strike(o + Vector3.new(rnd(-2, 2), 30, rnd(-2, 2)), o + Vector3.new(0, 0.2, 0), { col = W, glow = cols[3], w = 0.7, life = 0.3, forks = 4 })
				appear(W, hideTok)
				for i = 1, 3 do L.groundWave(o, "ring_c.png", cols[i], 2 + i, 14 + i * 5, 0.5 + i * 0.12, 2.2) end
				burstP.CFrame = CFrame.new(o + Vector3.new(0, 2, 0)) burst:Emit(50)
			end
		end, objs)
		task.delay(DUR + 0.1, function() setHidden(false, hideTok) end)
	end


	shorts[5] = function()
		local o = ch.feet
		local DUR, RISE0, RISE = 3.0, 1.4, 2.0
		local hideTok = setHidden(true)
		local S = L.screen(DUR)
		local objs = {}
		local function own(x) objs[#objs + 1] = x return x end
		local spec = {
			{ size = 13, h = 16, fall = 0.45, t0 = 0, tex = "mcircle.png", col = C1 },
			{ size = 9.5, h = 18, fall = 0.33, t0 = 0.55, tex = "runering.png", col = C2 },
			{ size = 6.5, h = 20, fall = 0.24, t0 = 0.95, tex = "mcircle.png", col = C2 },
		}
		local seals = {}
		for i, sp in ipairs(spec) do
			local p, m, set = circle(sp.tex, sp.col, 1.6) own(p)
			seals[i] = { p = p, sp = sp, set = set, land = sp.t0 + sp.fall, rot = rnd(0, 6), y0 = 0.1 + i * 0.03 }
		end

		local crB, crBSet = backing()
		local crP, crM = mmesh("disc.mesh", "cracks_b.png", C2, 1.6)
		crP.Transparency = 1
		local crHot = 0
		local function startCrater()
			L.fx(DUR + 1.5, function(k, t)
				local g = L.outQuad(t / 0.25)
				crBSet(CFrame.new(o + Vector3.new(0, 0.03, 0)), 5 + 19 * g, math.max(0.3, c01((t - DUR - 0.5) / 1)))
				crM.Scale = Vector3.new(4 + 18 * g, 1, 4 + 18 * g)
				crP.CFrame = CFrame.new(o + Vector3.new(0, 0.06, 0))
				crP.Transparency = math.max(0.06, c01((t - DUR - 0.3) / 1.2))
				capTint(crM, C2:Lerp(C1, c01((t - 0.5) / 1.5)), 1.6, math.max(1 - c01(t / 0.4), 1 - c01((os.clock() - crHot) / 0.35)))
			end, { crB, crP })
		end
		local body, risen = nil, false
		L.fx(DUR, function(k, t)
			for i, s in ipairs(seals) do
				local sp = s.sp
				local u = L.inQuad((t - sp.t0) / sp.fall)
				local y = s.y0 + sp.h * (1 - u)
				if not s.landed and t >= s.land then
					s.landed = true
					S:shake(0.8 + i * 0.5, 0.25)
					L.groundWave(o, "ring_c.png", i == 3 and W or sp.col, sp.size * 0.5, sp.size * 2, 0.45, 2)
					burstP.CFrame = CFrame.new(o + Vector3.new(0, 0.5, 0)) burst:Emit(14 + i * 8) burstG:Emit(4 + i * 3)
					light.Brightness = 4 + i * 2
