			local chest = ch.pos + Vector3.new(0, 0.6, 0)
			local form = c01((t - 0.05) / FORM)
			local drain = c01((t - DRAIN) / (END - DRAIN))
			local size = 2.4 * L.outQuad(form) * (1 - drain * drain)
			h.set(top, size, t, not done)
			fa.WorldPosition, fb.WorldPosition = top, chest
			local fun = (not done) and drain > 0
			fDark.Enabled, fLit.Enabled = fun, fun
			fDark.Width0, fLit.Width0 = 0.5 + size * 1.4, 0.3 + size
			for i, q in ipairs(strands) do
				local a = i / #strands * math.pi * 2
				local ra = a + t * 7
				q.a0.WorldPosition = top + Vector3.new(math.cos(ra), 0, math.sin(ra)) * size * 0.9
				q.a1.WorldPosition = chest + Vector3.new(math.cos(ra + 2.4), 0, math.sin(ra + 2.4)) * 0.5
				q.b.Enabled = fun
			end
			body.CFrame = CFrame.new(chest)
			bodyS.Rate = fun and 160 or 0
			hl.FillColor = C2
			hl.FillTransparency = done and math.min(1, hl.FillTransparency + 0.04) or 1 - 0.55 * drain
			if not done and t >= END then
				done = true
				pop(chest, 0.7)
			end
		end, objs)
	end


	shorts[2] = function()
		local DUR, SHAKE, BREAK = 2.4, 0.6, 1.0
		local hideTok = setHidden(true)
		local cen = ch.pos + Vector3.new(0, 0.2, 0)
		local R, N = 3.4, 46
		local sh, objs = {}, {}
		local inner = blackBall(0.1) objs[1] = inner
		for i = 1, N do

			local y = 1 - (i - 0.5) / N * 2
			local rr = math.sqrt(1 - y * y)
			local th = i * 2.39996
			local n = Vector3.new(math.cos(th) * rr, y, math.sin(th) * rr)
			local pos = cen + Vector3.new(n.X * R, n.Y * R * 1.3, n.Z * R)
			local nn = Vector3.new(n.X, n.Y / 1.3, n.Z).Unit
			local w, hh = rnd(1.5, 2.1), rnd(1.2, 1.9)
			local cf = CFrame.lookAt(pos, pos + nn) * CFrame.Angles(0, 0, rnd(0, 6.28))
			local face = L.part({ Material = Enum.Material.SmoothPlastic, Reflectance = 0.1, Color = BLACK, Transparency = 1, Size = Vector3.new(w, hh, 0.1) })
			local seam = L.part({ Material = Enum.Material.Neon, Color = C2, Transparency = 1, Size = Vector3.new(w + 0.22, hh + 0.22, 0.05) })
			objs[#objs + 1] = face objs[#objs + 1] = seam
			sh[i] = { face = face, seam = seam, cf = cf, n = nn, at = 0.04 + (1 - y) * 0.2 + rnd(0, 0.12),
				v = nn * rnd(16, 28) + Vector3.new(0, rnd(4, 10), 0), spin = Vector3.new(rnd(-9, 9), rnd(-9, 9), rnd(-9, 9)) }
		end
		local broke = false
		L.fx(DUR, function(k, t)
			local tremble = c01((t - SHAKE) / (BREAK - SHAKE))
			local fill = c01((t - 0.15) / 0.35) * (broke and 0 or 1)
			inner.Size = Vector3.new(R * 1.85, R * 2.45, R * 1.85) * math.max(fill, 0.02)
			inner.CFrame = CFrame.new(cen)
			inner.Transparency = fill > 0.05 and 0 or 1
			for _, q in ipairs(sh) do
				if not broke then
					local u = L.outQuad(c01((t - q.at) / 0.22))
					local jit = tremble > 0 and Vector3.new(rnd(-1, 1), rnd(-1, 1), rnd(-1, 1)) * 0.09 * tremble or Vector3.zero
					local cf = q.cf + q.n * 3.5 * (1 - u) + jit
					q.face.CFrame = cf q.seam.CFrame = cf * CFrame.new(0, 0, 0.06)
					q.face.Transparency = u > 0 and 0 or 1
					q.seam.Transparency = u > 0 and 0.1 or 1
					q.seam.Color = C2:Lerp(W, tremble ^ 3)
				else
					local tt = t - BREAK
					local p = q.cf.Position + q.v * tt + Vector3.new(0, -40 * tt * tt, 0)
					local rot = CFrame.Angles(q.spin.X * tt, q.spin.Y * tt, q.spin.Z * tt)
					local cf = CFrame.new(p) * q.cf.Rotation * rot
					q.face.CFrame = cf q.seam.CFrame = cf * CFrame.new(0, 0, 0.06)
					local fade = c01((tt - 0.35) / 0.7)
					q.face.Transparency = fade
					q.seam.Transparency = 0.1 + 0.9 * c01(tt / 0.4)
					q.seam.Color = W:Lerp(C1, c01(tt / 0.3))
				end
			end
			if not broke and t >= BREAK then
				broke = true
				setHidden(false, hideTok)
				pop(cen, 0.6)
				hl.FillColor, hl.FillTransparency = W, 0.2
			end
			if broke then hl.FillTransparency = math.min(1, hl.FillTransparency + 0.03) end
		end, objs)
		task.delay(DUR + 0.1, function() setHidden(false, hideTok) end)
	end


	shorts[3] = function()
		local DUR, GROW, STEP, CLOSE = 2.4, 0.18, 0.6, 1.15
		local fwd, right = L.facing()
		local up = Vector3.yAxis
		local c = ch.feet + right * 4.6 + Vector3.new(0, 4.3, 0)
		local H, NP = 8, 10
		local xs, ys, wp = {}, {}, {}
		for i = 1, NP do
			local u = (i - 1) / (NP - 1)
			ys[i] = (u - 0.5) * H
			xs[i] = (i == 1 or i == NP) and 0 or rnd(-0.75, 0.75)
			wp[i] = math.sin(u * math.pi) ^ 0.7 * rnd(0.7, 1.1)
		end
		local function at(x, y) return c + right * x + up * y end
		local function tri(w1, w2, a, b, cc)
			local ab, ac, bc = b - a, cc - a, cc - b
			local abd, acd, bcd = ab:Dot(ab), ac:Dot(ac), bc:Dot(bc)
			if abd > acd and abd > bcd then cc, a = a, cc elseif acd > bcd and acd > abd then a, b = b, a end
			ab, ac, bc = b - a, cc - a, cc - b
			local cr = ac:Cross(ab)
			if cr.Magnitude < 1e-4 or bc.Magnitude < 1e-3 then w1.Transparency, w2.Transparency = 1, 1 return end
			local rv = cr.Unit
			local uv = bc:Cross(rv).Unit
			local bv = bc.Unit
			local h = math.abs(ab:Dot(uv))
			w1.Size = Vector3.new(0.05, h, math.abs(ab:Dot(bv))) w1.CFrame = CFrame.fromMatrix((a + b) / 2, rv, uv, bv)
			w2.Size = Vector3.new(0.05, h, math.abs(ac:Dot(bv))) w2.CFrame = CFrame.fromMatrix((a + cc) / 2, -rv, uv, -bv)
			w1.Transparency, w2.Transparency = 0, 0
		end
		local objs = {}
		local function att() local a = L.att(c) objs[#objs + 1] = a return a end
		local la, ra, fills, eL, eR = {}, {}, {}, {}, {}
		for i = 1, NP do la[i], ra[i] = att(), att() end
		local edgeCol = CS(C2:Lerp(W, 0.7))
		for i = 1, NP - 1 do
			fills[i] = {}
			for q = 1, 4 do
				local wdg = Instance.new("WedgePart")
				wdg.Anchored, wdg.CanCollide, wdg.CanQuery, wdg.CanTouch, wdg.CastShadow = true, false, false, false, false
				wdg.Material, wdg.Color, wdg.Transparency, wdg.CFrame = Enum.Material.Neon, BLACK, 1, CFrame.new(c)
				wdg.Parent = L.root
				fills[i][q] = wdg objs[#objs + 1] = wdg
			end
			eL[i] = L.beam(la[i], la[i + 1], { Width0 = 0, Width1 = 0, Brightness = 7, Segments = 1, Color = edgeCol })
			eR[i] = L.beam(ra[i], ra[i + 1], { Width0 = 0, Width1 = 0, Brightness = 7, Segments = 1, Color = edgeCol })
			objs[#objs + 1] = eL[i] objs[#objs + 1] = eR[i]
		end

		local br = {}
		for n = 1, 6 do
			local sd = n % 2 == 0 and 1 or -1
			local i = math.random(3, NP - 2)
			local chain, p = { Vector2.zero }, Vector2.zero
			for _ = 1, 3 do p = p + Vector2.new(sd * rnd(0.5, 1.1), rnd(-0.8, 0.8)) chain[#chain + 1] = p end
			local as, bs = {}, {}
			for k = 1, #chain do as[k] = att() end
			for k = 1, #chain - 1 do
				bs[k] = L.beam(as[k], as[k + 1], { Width0 = 0, Width1 = 0, Brightness = 5, Segments = 1, Color = CS(C2) })
				objs[#objs + 1] = bs[k]
			end
			br[n] = { i = i, sd = sd, chain = chain, as = as, bs = bs, t0 = GROW + rnd(0, 0.2) }
		end
		local cp = L.part({ Size = Vector3.new(1.6, H * 0.8, 0.3), CFrame = CFrame.lookAt(c, c + fwd) })
		local suck = suckE(cp, { Shape = Enum.ParticleEmitterShape.Box, Speed = NR(5, 9), Lifetime = NR(0.3, 0.45), Rate = 0 })
		local bleed = darkE(cp, { Shape = Enum.ParticleEmitterShape.Box, Speed = NR(0.5, 2), Lifetime = NR(0.8, 1.2), Size = NS({ K(0, 1.2), K(1, 3.2) }),
			Acceleration = Vector3.new(0, -3, 0), Rate = 0 })
		local pl = L.new("PointLight", { Color = C2, Range = 14, Brightness = 0, Shadows = false }, cp)
		objs[#objs + 1] = cp
		local com = blackBall(1.8) com.Transparency = 1
		local cr, crm = rim(C2, 3)
		local ca0 = L.new("Attachment", { Position = Vector3.new(0, 0.8, 0) }, com)
		local ca1 = L.new("Attachment", { Position = Vector3.new(0, -0.8, 0) }, com)
		local comTr = L.new("Trail", { Enabled = false, Attachment0 = ca0, Attachment1 = ca1, Texture = L.T("beamb.png"), LightEmission = 1, Brightness = 4, Lifetime = 0.22,
			FaceCamera = true, Color = CS({ CK(0, W), CK(0.3, C2), CK(1, C1) }), Transparency = NS(0, 1), WidthScale = NS(1, 0.3) }, com)
		local comSmoke = darkE(com, { Speed = NR(0, 1), Lifetime = NR(0.35, 0.5), Size = NS({ K(0, 1.8), K(1, 3.4) }), LockedToPart = false, Rate = 0 })
		objs[#objs + 1] = com objs[#objs + 1] = cr
		local stepped, nextCrack = false, 0
		local hideTok = setHidden(true)
		L.fx(DUR, function(k, t)
			local grow = L.outQuad(c01(t / GROW))
			local open = math.max(L.outBack(c01((t - GROW) / 0.3)), 0) * (1 - L.inQuad(c01((t - CLOSE) / 0.22)))
			local glow = 1 - c01((t - CLOSE - 0.22) / 0.45)
			local hwid = 1.15 * open * (1 + 0.05 * math.sin(t * 32))
			for i = 1, NP do
				local x, y, hw = xs[i] * grow, ys[i] * grow, hwid * wp[i]
				la[i].WorldPosition, ra[i].WorldPosition = at(x - hw, y), at(x + hw, y)
			end
			for i = 1, NP - 1 do
				local p1l, p1r, p2l, p2r = la[i].WorldPosition, ra[i].WorldPosition, la[i + 1].WorldPosition, ra[i + 1].WorldPosition
				local f = fills[i]
				if hwid < 0.03 then for _, wdg in ipairs(f) do wdg.Transparency = 1 end else
					tri(f[1], f[2], p1l, p1r, p2r)
					tri(f[3], f[4], p1l, p2r, p2l)
				end
				local ew = 0.4 * glow * (grow > 0 and 1 or 0)
				eL[i].Width0, eL[i].Width1, eR[i].Width0, eR[i].Width1 = ew, ew, ew, ew
			end
			for _, q in ipairs(br) do
				local g = L.outQuad(c01((t - q.t0) / 0.25))
				local o = Vector2.new(xs[q.i] * grow + q.sd * hwid * wp[q.i], ys[q.i] * grow)
				for kk, a in ipairs(q.as) do local v = o + q.chain[kk] * g a.WorldPosition = at(v.X, v.Y) end
				for _, bm in ipairs(q.bs) do bm.Width0, bm.Width1 = 0.16 * g * glow, 0.07 * g * glow end
			end
			local oc = c01(open)
			suck.Rate, bleed.Rate, pl.Brightness = 90 * oc, 24 * oc, 1.2 * oc
			if oc > 0.3 and t >= nextCrack and t < CLOSE then
				nextCrack = t + 0.07
				local i = math.random(2, NP - 1)
				local sd = math.random() < 0.5 and -1 or 1
				local from = (sd < 0 and la or ra)[i].WorldPosition
				L.bolt(from, from + right * sd * rnd(1.2, 2.4) + up * rnd(-1.2, 1.2), { col = C2, w = 0.15, life = 0.12, segs = 4, glow = C1 })
			end
			if not stepped and t >= STEP then
				stepped = true
				local dest = ch.pos
				comTr.Enabled = true comSmoke.Rate = 80
				L.fx(0.24, function(kk)
					local u = kk * kk
					com.CFrame = CFrame.new(c:Lerp(dest, u) + Vector3.new(0, math.sin(u * math.pi) * 0.8, 0))
					com.Transparency = 0
					crm.Scale = Vector3.new(4, 1, 4) cr.CFrame = faceCam(com.Position) cr.Transparency = 0.15
				end, {})
				L.after(0.24, function()
					com.Transparency, cr.Transparency = 1, 1 comTr.Enabled = false comSmoke.Rate = 0
					setHidden(false, hideTok)
					pop(dest, 0.5)
					hl.FillColor, hl.FillTransparency = C2, 0.2
				end)
			end
			if hl.FillTransparency < 1 then hl.FillTransparency = math.min(1, hl.FillTransparency + 0.025) end
		end, objs)
		task.delay(DUR + 0.1, function() setHidden(false, hideTok) end)
	end


	shorts[4] = function()
		local DUR, GAZE, REVEAL = 2.6, 0.7, 1.3
		local hideTok = setHidden(true)
		local cen = ch.pos
		local ca = L.att(cen)
		local eyes, objs = {}, { ca }
		local N = 10
		for i = 1, N do
			local a = i / N * math.pi * 2
			local pos = cen + Vector3.new(math.cos(a) * 7.5, rnd(-1, 2.6), math.sin(a) * 7.5)
			local ep = L.part({ Size = Vector3.one * 0.2, CFrame = CFrame.new(pos) })
			local bb = L.new("BillboardGui", { Size = UDim2.fromScale(4.2, 1.3), LightInfluence = 0, Brightness = 4 }, ep)

			local dk = L.new("ImageLabel", { Image = L.T("glowui.png"), BackgroundTransparency = 1, ImageColor3 = BLACK, AnchorPoint = Vector2.new(0.5, 0.5),
				Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromScale(1.5, 3.2), ImageTransparency = 1, ZIndex = 0 }, bb)
			local labs, pups = {}, {}
			for sd = -1, 1, 2 do
				local al = L.new("ImageLabel", { Image = L.T("seye_alm2.png"), BackgroundTransparency = 1, ImageColor3 = C2:Lerp(W, 0.25), AnchorPoint = Vector2.new(0.5, 0.5),
					Position = UDim2.fromScale(0.5 + sd * 0.26, 0.5), Size = UDim2.fromScale(0.42, 0) }, bb)
				local pu = L.new("ImageLabel", { Image = L.T("glowui.png"), BackgroundTransparency = 1, ImageColor3 = BLACK, AnchorPoint = Vector2.new(0.5, 0.5),
					Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromScale(0.18, 0.9) }, al)
				labs[#labs + 1], pups[#pups + 1] = al, pu
			end
			local ea = L.att(pos)
			local bm = L.beam(ea, ca, { Width0 = 0, Width1 = 0, Brightness = 5, Segments = 1, Color = CS(C2:Lerp(W, 0.35), C1), Transparency = NS({ K(0, 0.15), K(1, 0.55) }) })
			objs[#objs + 1] = ep objs[#objs + 1] = ea objs[#objs + 1] = bm
			eyes[i] = { pos = pos, labs = labs, pups = pups, bm = bm, dk = dk, t0 = (i - 1) / N * 0.4 + rnd(0, 0.08), sh = REVEAL + 0.15 + rnd(0, 0.15) }
		end

		local core, coreM = L.mesh("disc.mesh", "glowui.png", C2, 3)
		local cring, cringM = L.mesh("disc.mesh", "ring_c.png", C2:Lerp(W, 0.4), 3.2)
		local pool, poolM = L.mesh("disc.mesh", "smoke.png", BLACK, 1)
		objs[#objs + 1] = pool
		local cp = L.part({ Size = Vector3.one * 1.5, CFrame = CFrame.new(cen) })
		local cs = suckE(cp, { Speed = NR(6, 9), Lifetime = NR(0.25, 0.35), Rate = 0 })
		objs[#objs + 1] = core objs[#objs + 1] = cring objs[#objs + 1] = cp
		local revealed = false
		L.fx(DUR, function(k, t)
			local cam = workspace.CurrentCamera.CFrame
			for _, e in ipairs(eyes) do
				local op = L.outBack(c01((t - e.t0) / 0.22))
				local shut = c01((t - e.sh) / 0.09)
				local h = math.max(op, 0) * (1 - shut)

				local d = cen - e.pos
				local sx, sy = d:Dot(cam.RightVector), d:Dot(cam.UpVector)
				local m = math.max(math.sqrt(sx * sx + sy * sy), 0.01)
				local look = L.outQuad(c01((t - e.t0 - 0.2) / 0.25))
				e.dk.ImageTransparency = 1 - 0.85 * c01((t - e.t0 + 0.15) / 0.25) * (1 - c01((t - e.sh) / 0.3))
				for j, al in ipairs(e.labs) do
					al.Size = UDim2.fromScale(0.42, 0.95 * h)
					e.pups[j].Position = UDim2.fromScale(0.5 + 0.22 * sx / m * look, 0.5 - 0.22 * sy / m * look)
				end
				local g = c01((t - GAZE - e.t0 * 0.3) / 0.2) * (1 - c01((t - REVEAL) / 0.12))
				e.bm.Width0, e.bm.Width1 = 0.35 * g, 0.1 * g
			end
			local cg = c01((t - GAZE) / (REVEAL - GAZE))
			local fade = revealed and c01((t - REVEAL) / 0.3) or 0
			local sz = 0.5 + 6 * cg * cg
			coreM.Scale = Vector3.new(sz, 1, sz) core.CFrame = faceCam(cen)
			core.Transparency = 1 - 0.95 * cg * (1 - fade)
			local rs = 1 + 4 * cg
			cringM.Scale = Vector3.new(rs, 1, rs) cring.CFrame = faceCam(cen) * CFrame.Angles(0, t * 6, 0)
			cring.Transparency = 1 - 0.9 * cg * (1 - fade)
			cs.Rate = (cg > 0 and not revealed) and 120 or 0
			local pa = c01(t / 0.3) * (1 - c01((t - REVEAL - 0.2) / 0.8))
			local ps = 6 + 14 * L.outQuad(c01(t / 0.5))
			poolM.Scale = Vector3.new(ps, 1, ps) pool.CFrame = CFrame.new(ch.feet + Vector3.new(0, 0.05, 0)) * CFrame.Angles(0, -t * 0.6, 0)
			pool.Transparency = 1 - 0.8 * pa
			if not revealed and t >= REVEAL then
				revealed = true
				setHidden(false, hideTok)
				pop(cen, 0.6)
				hl.FillColor, hl.FillTransparency = C2:Lerp(W, 0.5), 0.15
			end
			if revealed then hl.FillTransparency = math.min(1, hl.FillTransparency + 0.03) end
		end, objs)
		task.delay(DUR + 0.1, function() setHidden(false, hideTok) end)
	end

	shorts[5] = function()
		local o = ch.feet
		local DUR, OPEN, DROP, LAND = 2.6, 0.45, 0.65, 1.0
		local top = o + Vector3.new(0, 10.5, 0)
		local nextCrack = 0
		local hideTok = setHidden(true)
		local hole = L.part({ Shape = Enum.PartType.Cylinder, Material = Enum.Material.Neon, Color = BLACK, Transparency = 1, Size = Vector3.new(0.15, 0.1, 0.1) })
		local r1, r1m = rim(C2, 3.2)
		local r2, r2m = rim(C1, 2.6)
		local acc, accM = L.mesh("swirl.mesh", "swirl.png", C2, 2.4)
		local drip = L.part({ Size = Vector3.new(6, 0.2, 6), CFrame = CFrame.new(top - Vector3.new(0, 0.3, 0)) })
		local dripE = darkE(drip, { Shape = Enum.ParticleEmitterShape.Box, EmissionDirection = Enum.NormalId.Bottom, Speed = NR(3, 7), Rate = 0,
			Size = NS({ K(0, 1.5), K(1, 3.5) }), Lifetime = NR(0.6, 1) })
		local suck = suckE(drip, { LockedToPart = false, Shape = Enum.ParticleEmitterShape.Box, ShapeInOut = Enum.ParticleEmitterShapeInOut.Outward,
			EmissionDirection = Enum.NormalId.Top, Speed = NR(10, 16), Rate = 0, Size = NS({ K(0, 0.15), K(0.7, 0.5), K(1, 0) }), Squash = NS(-3) })
		local pl = L.new("PointLight", { Color = C2, Range = 26, Brightness = 0, Shadows = false }, drip)
		local fall = blackBall(2)
		fall.Transparency = 1
		local fa0 = L.new("Attachment", { Position = Vector3.new(0, 0.9, 0) }, fall)
		local fa1 = L.new("Attachment", { Position = Vector3.new(0, -0.9, 0) }, fall)
		local fallTr = L.new("Trail", { Enabled = false, Attachment0 = fa0, Attachment1 = fa1, Texture = L.T("beamb.png"), LightEmission = 1, Brightness = 4, Lifetime = 0.25,
			FaceCamera = true, Color = CS({ CK(0, W), CK(0.3, C2), CK(1, C1) }), Transparency = NS(0, 1), WidthScale = NS(1, 0.3) }, fall)
		local fr, frm = rim(C2, 3)
		local fallSmoke = darkE(fall, { Speed = NR(0, 1), Lifetime = NR(0.4, 0.6), Size = NS({ K(0, 2), K(1, 4) }), LockedToPart = false, Rate = 0 })
		local landed = false
		L.fx(DUR, function(k, t)
			local open = L.outQuad(c01(t / OPEN)) * (1 - c01((t - LAND - 0.3) / 0.5))
			local D = 9 * open
			hole.Size = Vector3.new(0.15, math.max(D, 0.1), math.max(D, 0.1))
			hole.CFrame = CFrame.new(top) * CFrame.Angles(0, 0, math.rad(90))
			hole.Transparency = D < 0.3 and 1 or 0
			r1m.Scale = Vector3.new(D * 1.15, 1, D * 1.15) r1.CFrame = CFrame.new(top - Vector3.new(0, 0.1, 0)) * CFrame.Angles(0, t * 2, 0)
			r2m.Scale = Vector3.new(D * 1.5, 1, D * 1.5) r2.CFrame = CFrame.new(top - Vector3.new(0, 0.12, 0)) * CFrame.Angles(0, -t * 3, 0)
			r1.Transparency, r2.Transparency = 1 - 0.95 * c01(open * 3), 1 - 0.7 * c01(open * 3)
			accM.Scale = Vector3.new(D * 1.8, 0.4, D * 1.8)
			acc.CFrame = CFrame.new(top + Vector3.new(0, 0.1, 0)) * CFrame.Angles(0, -t * 6, 0)
			acc.Transparency = 1 - 0.85 * open
			dripE.Rate = 40 * open
			if open > 0.3 and t >= nextCrack and t < LAND + 0.3 then
				nextCrack = t + 0.045
				local a = rnd(0, math.pi * 2)
				local d = Vector3.new(math.cos(a), 0, math.sin(a))
				L.bolt(top + d * D * 0.6, top + d * D * rnd(0.95, 1.35) + Vector3.new(0, rnd(-1, 1), 0), { col = C2, w = 0.16, life = 0.13, segs = 4, glow = C1 })
			end
			suck.Rate = 120 * open
			pl.Brightness = 5 * open
			if t >= DROP and not landed then
				local u = c01((t - DROP) / (LAND - DROP))
				local pos = top:Lerp(o + Vector3.new(0, 2.5, 0), u * u)
				fall.CFrame = CFrame.new(pos)
				fall.Transparency = 0
				fallTr.Enabled = true
				fallSmoke.Rate = 90
				fr.CFrame = faceCam(pos)
				frm.Scale = Vector3.new(4.5, 1, 4.5)
				fr.Transparency = 0.15
			end
			if not landed and t >= LAND then
				landed = true
				fall.Transparency, fr.Transparency = 1, 1
				fallSmoke.Rate = 0
				pop(o + Vector3.new(0, 1, 0), 0.8)

				local cr, crM = L.mesh("disc.mesh", "smoke.png", BLACK, 1)
				local ck, ckM = L.mesh("disc.mesh", "cracks_b.png", C2, 2.6)
				L.fx(1.5, function(kk)
					crM.Scale = Vector3.new(9, 1, 9) cr.CFrame = CFrame.new(o + Vector3.new(0, 0.04, 0))
					ckM.Scale = Vector3.new(12, 1, 12) ck.CFrame = CFrame.new(o + Vector3.new(0, 0.07, 0))
					cr.Transparency = 0.1 + 0.9 * c01((kk - 0.5) / 0.5)
					ck.Transparency = 0.1 + 0.9 * kk
				end, { cr, ck })
				setHidden(false, hideTok)
				hl.FillColor, hl.FillTransparency = C2, 0.15
			end
			if landed then hl.FillTransparency = math.min(1, hl.FillTransparency + 0.03) end
		end, { hole, r1, r2, acc, drip, fall, fr })
		task.delay(DUR + 0.1, function() setHidden(false, hideTok) end)
	end
	local cur = 1


	local function arrive(short)
		if short then return shorts[cur]() end
		local o = ch.feet
		local sc = short and 0.65 or 1
		local DUR = short and 2.8 or 10.5
		L.after(DUR - 2.6, function() L.handoff(o, "ring_c.png", C2, 24, 6, 2.4) end)
		local FORM, COL = short and 0.05 or 0.5, short and 0.75 or 5.6
		local BANG = COL + (short and 0.16 or 0.4)
		local S
		if not short then
			S = L.screen(DUR)
			S.dimFn = function(t) return math.max(c01(t / 0.8) * 0.75, c01((t - COL) / 0.35) * (1 - c01((t - BANG) / 0.1))) * (1 - c01((t - (BANG + 2)) / 1.5)) end
			S.style, S.c1, S.c2 = "void", C1, C2 S.boxFn = function(t) return c01((t - 0.2) / 0.6) * (1 - c01((t - (DUR - 1)) / 0.8)) end
			S.tintFn = function(t) return C1, 0.35 * c01(t / 1.5) * (1 - c01((t - BANG - 1) / 2)) end
			L.after(BANG + 0.4, function() S:title(L.name(), C1, C2) end)
		end


		if not short then
			local fwd = L.facing()
			local right = fwd:Cross(Vector3.yAxis)
			local uo = {}
			local function own(x) uo[#uo + 1] = x return x end

			local wsky = L.worldSky(o, DUR, { dome = Color3.fromRGB(16, 6, 30), atmC = Color3.fromRGB(60, 25, 110), decay = Color3.fromRGB(20, 8, 40),
				den = 0.25, haze = 0.3, glare = 0, oa = Color3.fromRGB(55, 40, 85), am = Color3.fromRGB(35, 25, 60), domeA = 0.93 })
			for _, x in ipairs(wsky.objs) do own(x) end
			local function skyA(t) return c01(t / 1.2) * (1 - c01((t - DUR + 2) / 1.8)) end

			local stars = {}
			for i = 1, 90 do
				local a, el = rnd(0, math.pi * 2), rnd(0.03, 0.75)
				local d = Vector3.new(math.cos(a) * math.cos(el), math.sin(el), math.sin(a) * math.cos(el))
				local sp = own(L.part({ Shape = Enum.PartType.Ball, Material = Enum.Material.Neon, Color = W:Lerp(C2, rnd(0, 0.4)), Transparency = 1,
					Size = Vector3.one * rnd(3, 6), CFrame = CFrame.new(o + d * 300) }))
				stars[i] = { p = sp, d = d, off = rnd(0.9, 4.6), s0 = sp.Size.X, done = false }
			end


			local BR = 70
			local BC = o + fwd * 170 + Vector3.new(0, 46, 0)
			local bh = own(L.part({ Shape = Enum.PartType.Ball, Material = Enum.Material.Neon, Color = BLACK, Transparency = 1, Size = Vector3.one, CFrame = CFrame.new(BC) }))
			local back, backM = L.mesh("disc.mesh", "glowui.png", C2, 2.2) own(back)
			local halo, haloM = L.mesh("disc.mesh", "glowui.png", C2:Lerp(C1, 0.4), 3) own(halo)
			local pr, prM = L.mesh("disc.mesh", "ring_c.png", C2:Lerp(W, 0.35), 3.2) own(pr)
			local lr, lrM = L.mesh("disc.mesh", "ring_c.png", C1, 2.4) own(lr)
			local tiltCF = CFrame.new(BC) * CFrame.fromAxisAngle(right, math.rad(20))
			local dk, dkM = L.mesh("disc.mesh", "accdisc2.png", C2, 2.8) own(dk)
			local dk2, dk2M = L.mesh("disc.mesh", "ring_c.png", C1, 2.6) own(dk2)
			local dk3, dk3M = L.mesh("disc.mesh", "ring_c.png", W, 3.2) own(dk3)
			local dkHot, dkHotM = L.mesh("disc.mesh", "accdisc2.png", W:Lerp(C2, 0.3), 3.4) own(dkHot)
			local dkOut, dkOutM = L.mesh("disc.mesh", "accdisc2.png", C1, 2.2) own(dkOut)
			local lens, lensM = L.mesh("disc.mesh", "accdisc2.png", W:Lerp(C2, 0.45), 3.2) own(lens)
			local dop, dopM = L.mesh("disc.mesh", "glowui.png", W:Lerp(C2, 0.4), 3.2) own(dop)
			local deb = {}
			for i = 1, 44 do
				local r = rnd(0.42, 1.05)
				deb[i] = { p = own(L.part({ Shape = Enum.PartType.Ball, Material = Enum.Material.Neon, Color = W:Lerp(C2, rnd(0.2, 0.8)), Transparency = 1, Size = Vector3.one, CFrame = CFrame.new(BC) })),
					r = r, a = rnd(0, math.pi * 2), w = 0.5 / (r ^ 1.5), s = rnd(0.006, 0.016), lift = rnd(-0.012, 0.012) }
			end
			local jets = {}
			for sd = -1, 1, 2 do
				local ja, jb = own(L.att(BC)), own(L.att(BC))
				local jb1 = own(L.beam(ja, jb, { Texture = L.T("softbeam.png"), Width0 = 20, Width1 = 70, Brightness = 4, Segments = 2,
					Color = CS({ CK(0, W), CK(0.3, C2), CK(1, C1) }), Transparency = NS(1) }))
				jets[#jets + 1] = { a = ja, b = jb, beam = jb1, sd = sd }
			end
			local bhLight = L.new("PointLight", { Color = C2, Range = 60, Brightness = 0, Shadows = false }, bh)

			local chunks = {}
			for i = 1, 54 do
				local a, r = rnd(-1.35, 1.35), rnd(18, 95)
				local dir = (CFrame.fromAxisAngle(Vector3.yAxis, a) * fwd)
				local p0 = o + dir * r + Vector3.new(0, 0.3, 0)
				local sz = Vector3.new(rnd(1, 4), rnd(0.6, 2.2), rnd(1, 4))
				local cp2 = own(L.part({ Material = Enum.Material.Basalt, Color = DUSK:Lerp(C1, rnd(0, 0.25)), Transparency = 1, Size = sz, CFrame = CFrame.new(p0) }))
				chunks[i] = { p = cp2, p0 = p0, sz = sz, t0 = rnd(1.2, 3.4), lift = rnd(3, 9), ph = rnd(0, 6), spin = CFrame.Angles(rnd(0, 6), rnd(0, 6), rnd(0, 6)),
					T = rnd(2, 2.8), torn = false }
			end
			local dustP = own(L.part({ Size = Vector3.new(170, 0.2, 170), CFrame = CFrame.new(o) }))
			local dust = darkE(dustP, { Shape = Enum.ParticleEmitterShape.Box, EmissionDirection = Enum.NormalId.Top, Speed = NR(2, 5), Lifetime = NR(2, 3),
				Acceleration = Vector3.new(0, 2, 0), Size = NS({ K(0, 2), K(1, 6) }), Rate = 0 })

			local tears = {}
			for i = 1, 7 do
				local a = (i / 7) * math.pi * 2 + rnd(-0.3, 0.3)
				local c = o + Vector3.new(math.cos(a), 0, math.sin(a)) * rnd(14, 30) + Vector3.new(0, rnd(6, 16), 0)
				local frame = CFrame.lookAt(c, Vector3.new(o.X, c.Y, o.Z)) * CFrame.Angles(0, 0, rnd(-0.6, 0.6))
				local len = rnd(8, 15)
				local atts = {}
				for j = 0, 6 do
					local u = j / 6 - 0.5
					local jit = (j == 0 or j == 6) and 0 or rnd(-1.4, 1.4)
					atts[#atts + 1] = own(L.att((frame * CFrame.new(jit, u * len, 0)).Position))
				end
				local segs = {}
				for j = 1, #atts - 1 do
					local taper = math.sin((j - 0.5) / (#atts - 1) * math.pi)
					local dkB = own(L.beam(atts[j], atts[j + 1], { Width0 = 0, Width1 = 0, Brightness = 1, LightEmission = 0, Segments = 1, Color = CS(BLACK), Transparency = NS(0.1) }))
					local lt = own(L.beam(atts[j], atts[j + 1], { Width0 = 0, Width1 = 0, Brightness = 7, Segments = 1, Color = CS(C2:Lerp(W, 0.4), C1), Transparency = NS(0) }))
					segs[j] = { d = dkB, l = lt, w = taper }
				end
				local tp = own(L.part({ Size = Vector3.new(1, len * 0.7, 1), CFrame = frame }))
				local bleed = darkE(tp, { Shape = Enum.ParticleEmitterShape.Box, Speed = NR(1, 3), Lifetime = NR(1.2, 2), Size = NS({ K(0, 1.5), K(1, 5) }),
					Acceleration = Vector3.new(0, -1.5, 0), Rate = 0 })
				local spk = suckE(tp, { Shape = Enum.ParticleEmitterShape.Box, ShapeInOut = Enum.ParticleEmitterShapeInOut.Outward, Speed = NR(2, 5), LockedToPart = false, Rate = 0 })
				tears[i] = { segs = segs, bleed = bleed, spk = spk, tp = tp, t0 = 1.6 + (i - 1) * 0.42, closed = false }
			end

			local eyes = {}
			for i = 1, 36 do
				local a = rnd(0, math.pi * 2)
				local pos = o + Vector3.new(math.cos(a), 0, math.sin(a)) * rnd(55, 140) + Vector3.new(0, rnd(3, 45), 0)
				local ep = own(L.part({ Size = Vector3.one * 0.2, CFrame = CFrame.new(pos) }))
				local s = rnd(0.8, 1.6)
				local bb = L.new("BillboardGui", { Size = UDim2.fromScale(9 * s, 2.4 * s), LightInfluence = 0, Brightness = 4, MaxDistance = 2000, AlwaysOnTop = false }, ep)
				local labs = {}
				for sd = -1, 1, 2 do
					local al = L.new("ImageLabel", { Image = L.T("seye_alm2.png"), BackgroundTransparency = 1, ImageColor3 = C2:Lerp(W, 0.25), AnchorPoint = Vector2.new(0.5, 0.5),
						Position = UDim2.fromScale(0.5 + sd * 0.27, 0.5), Size = UDim2.fromScale(0.4, 0), ImageTransparency = 0 }, bb)
					L.new("ImageLabel", { Image = L.T("glowui.png"), BackgroundTransparency = 1, ImageColor3 = BLACK, AnchorPoint = Vector2.new(0.5, 0.5),
						Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromScale(0.16, 0.9) }, al)
					labs[#labs + 1] = al
				end
				eyes[i] = { labs = labs, t0 = rnd(2.0, 4.9), blinkAt = rnd(0.8, 2.5), shut = BANG + rnd(0, 0.12) }
			end
			local froze = false
			local CT, bhPopped = DUR - 2.9, false
			L.fx(DUR, function(k, t)
				local sa = skyA(t)
				wsky.set(sa)

				local camNow = workspace.CurrentCamera.CFrame.Position
				for _, st in ipairs(stars) do
					if not st.done then
						st.p.CFrame = CFrame.new(camNow + st.d * 300)
						if t < st.off then
							st.p.Transparency = 1 - 0.95 * sa
						else
							local u = c01((t - st.off) / 0.18)
							st.p.Size = Vector3.one * st.s0 * (1 + 1.5 * math.sin(u * math.pi))
							st.p.Transparency = u >= 1 and 1 or 0.05
							if u >= 1 then st.done = true end
						end
					end
				end



				local open = L.outQuad(c01((t - 0.6) / 2.6))
				local crush = c01((t - CT) / 1.0)
				local cr = crush ^ 2.6
				local live = bhPopped and 0 or 1
				local flare = t >= BANG and (1 - c01((t - BANG) / 1.4)) or 0
				flare = math.max(flare, 0.8 * crush)
				local bc0 = crush > 0 and (BC + Vector3.new(rnd(-1, 1), rnd(-1, 1), rnd(-1, 1)) * 5 * crush) or BC

				local camP0 = workspace.CurrentCamera.CFrame.Position
				local vk = math.min(1, 295 / ((bc0 - camP0).Magnitude + BR * 2.7))
				local bc = camP0 + (bc0 - camP0) * vk
				local BR = BR * vk
				local whip = crush ^ 3 * 45
				local camP = workspace.CurrentCamera.CFrame.Position
				local away = (bc - camP).Unit
				local D = 2 * BR * open * (1 - cr)
				bh.Size = Vector3.one * math.max(D, 0.1) bh.CFrame = CFrame.new(bc)
				bh.Transparency = (open > 0.01 and live > 0) and 0 or 1
				haloM.Scale = Vector3.new(D * 2.1, 1, D * 2.1) halo.CFrame = faceCam(bc + away * BR * 0.2)
				halo.Transparency = 1 - (0.8 + 0.2 * flare) * open * live
				local bD = 2 * BR * open * (1 - cr * 0.85)
				backM.Scale = Vector3.new(bD * 2.4, 1, bD * 2.4) back.CFrame = faceCam(bc + away * BR * 0.15)
				L.tint(backM, C2:Lerp(W, 0.12 + 0.6 * flare), 2.2)
				back.Transparency = 1 - (0.75 + 0.25 * flare) * open * live
				local ps = D * 1.16 * (1 + 0.06 * math.sin(t * 3)) * (1 + 0.15 * flare)
				prM.Scale = Vector3.new(ps, 1, ps) pr.CFrame = faceCam(bc + away * BR * 0.2) * CFrame.Angles(0, t * 0.4 + whip, 0)
				pr.Transparency = 1 - (0.85 + 0.15 * flare) * open * live
				L.tint(prM, C2:Lerp(W, 0.35 + 0.65 * flare), 3.2)
				local ls = D * 1.45
				lrM.Scale = Vector3.new(ls, 1, ls) lr.CFrame = faceCam(bc + away * BR * 0.4) * CFrame.Angles(0, -t * 0.25 - whip, 0)
				lr.Transparency = 1 - 0.45 * open * live
				local dD = 2 * BR * open * 1.8 * (1 - crush ^ 1.8)
				local tcf = CFrame.new(bc) * tiltCF.Rotation
				dkM.Scale = Vector3.new(dD * 1.12, 1, dD * 1.12) dk.CFrame = tcf * CFrame.Angles(0, -t * 0.35 - whip, 0)
				dk.Transparency = 1 - 0.95 * open * live
				dkHotM.Scale = Vector3.new(dD * 0.98, 1, dD * 0.98) dkHot.CFrame = tcf * CFrame.Angles(0, -t * 0.9 - whip * 1.5, 0)
				dkHot.Transparency = 1 - (0.9 + 0.1 * flare) * open * live
				dkOutM.Scale = Vector3.new(dD * 1.15, 1, dD * 1.15) dkOut.CFrame = tcf * CFrame.Angles(0, t * 0.12 - whip * 0.5, math.rad(1.5))
				dkOut.Transparency = 1 - 0.6 * open * live
				local upT = tcf.UpVector
				dopM.Scale = Vector3.new(dD * 0.5, 1, dD * 0.16)
				dop.CFrame = CFrame.fromMatrix(bc - right * dD * 0.3 - away * BR * 0.05, right, upT)
				dop.Transparency = 1 - (0.55 + 0.25 * math.sin(t * 2.3)) * open * live
				for _, d in ipairs(deb) do
					d.a -= (d.w * (1 + whip * 0.3)) * (L.lastDt or 0.016)
					local rr = d.r * dD * 0.5 * (1 - crush ^ 1.5 * 0.7)
					local lp = Vector3.new(math.cos(d.a) * rr, d.lift * dD, math.sin(d.a) * rr)
					d.p.CFrame = CFrame.new(tcf * lp)
					d.p.Size = Vector3.one * math.max(d.s * dD, 0.1)
					d.p.Transparency = 1 - 0.9 * open * live
				end
				dk2M.Scale = Vector3.new(dD * 1.08, 1, dD * 1.08) dk2.CFrame = tcf * CFrame.Angles(0, -t * 0.2 - whip * 0.8, 0)
				dk2.Transparency = 1 - 0.3 * open * live
				local lz = 2 * BR / 0.55 * 1.02 * open * (1 - cr) * (1 + 0.04 * math.sin(t * 2.5))
				lensM.Scale = Vector3.new(lz, 1, lz) lens.CFrame = faceCam(bc + away * BR * 0.1) * CFrame.Angles(0, -t * 0.5 - whip, 0)
				lens.Transparency = 1 - (0.85 + 0.15 * flare) * open * live
				dk3M.Scale = Vector3.new(D * 1.3, 1, D * 1.3) dk3.CFrame = tcf * CFrame.Angles(0, -t * 0.6 - whip * 1.3, 0)
				dk3.Transparency = 1 - (0.7 + 0.3 * flare) * open * live
				bhLight.Brightness = 3 * open * live
				local jA = c01((t - 2.4) / 1) * live
				for _, j in ipairs(jets) do
					local up = Vector3.yAxis * j.sd
					local tilted = (CFrame.fromAxisAngle(right, math.rad(20)) * up)
					local flick = crush > 0 and (math.random() < 0.5 and 1 or 0.3) or 1
					j.a.WorldPosition = bc + tilted * BR * 0.7 * (1 - cr)
					j.b.WorldPosition = bc + tilted * (BR * 0.7 + 420 * vk * (0.4 + 0.6 * jA) * (1 + 0.4 * flare))
					j.beam.Width0, j.beam.Width1 = (20 + 30 * flare) * (1 - cr) * vk, (70 + 90 * flare) * (1 - cr * 0.7) * vk
					j.beam.Transparency = NS({ K(0, 1 - 0.85 * jA * flick), K(1, 1) })
				end
				if S and crush > 0 and not bhPopped then S:shake(0.5 + 2.5 * crush, 0.12) end
				if crush >= 1 and not bhPopped then
					bhPopped = true

					if S then S:flash(W, 0.7) S:shake(4, 1.3) end
					local pf = L.part({ Shape = Enum.PartType.Ball, Material = Enum.Material.Neon, Color = W, Transparency = 0, CFrame = CFrame.new(BC) })
					L.fx(0.45, function(kk) local pc, pk = L.skyProj(BC, 230) pf.CFrame = CFrame.new(pc) pf.Size = Vector3.one * (6 + 110 * L.outQuad(kk)) * pk pf.Color = W:Lerp(C2, kk) pf.Transparency = 0.15 + 0.85 * kk end, { pf })
					for ri, rc in ipairs({ W, C2 }) do
						local sw, swM = L.mesh("disc.mesh", "ring_c.png", rc, 3.4)
						L.fx(1.3 + ri * 0.35, function(kk)
							local pc, pk = L.skyProj(BC, 230)
							local sz = (40 + (ri == 1 and 1500 or 1100) * L.outQuad(kk)) * pk
							swM.Scale = Vector3.new(sz, 1, sz) sw.CFrame = faceCam(pc)
							sw.Transparency = c01(kk * 1.1)
						end, { sw })
					end
					L.groundWave(o, "ring_c.png", C2, 20, 420, 1.4, 2.6)
				end

				dust.Rate = t > 1.2 and t < COL and 50 or 0
				for _, c in ipairs(chunks) do
					if not c.gone then
						local tt = t - c.t0
						if tt < 0 then
							c.p.Transparency = 1
						else
							if not c.torn then
								c.torn = true
								if math.random() < 0.4 then L.groundWave(c.p0, "cracks_b.png", C1, 1, 7, 0.8, 1.8) end
							end
							local liftU = L.outQuad(c01(tt / 0.8))
							local hover = c.p0 + Vector3.new(0, c.lift * liftU + 0.5 * math.sin(tt * 4 + c.ph), 0)
							local e = c01((tt - 0.8) / c.T) ^ 2.2
							local axis = (BC - hover).Unit
							local side = axis:Cross(Vector3.yAxis).Unit
							local sw = (1 - e) * 14 * math.sin(e * 9 + c.ph)
							local pos = hover:Lerp(BC, e) + side * sw * e
							local stretch = 1 + 6 * e
							c.p.Size = Vector3.new(c.sz.X / math.sqrt(stretch), c.sz.Y / math.sqrt(stretch), c.sz.Z * stretch)
							c.p.CFrame = e > 0.02 and CFrame.lookAt(pos, BC) or CFrame.new(pos) * c.spin * CFrame.Angles(tt, tt * 0.7, 0)
							c.p.Transparency = e > 0.9 and 1 or 0
							if e >= 1 then c.gone = true c.p.Transparency = 1 end
						end
					end
				end

				for _, tr in ipairs(tears) do
					local u = c01((t - tr.t0) / 0.3)
					local shut = t >= BANG and c01((t - BANG) / 0.15) or 0
					local w = L.outBack(u) * (1 - shut)
