			mp3 = true, ogg = true, wav = true, lua = true, json = true }
		local ROLE_EXT = { mesh = false, mesh_right = false, texture = false, texture_right = false,
			model = { rbxm = true, rbxmx = true }, script = { lua = true } }

		function C._log(msg) pcall(warn, "[RoClothes] community: " .. tostring(msg)) end
		local function finite(n) return type(n) == "number" and n == n and n ~= math.huge and n ~= -math.huge end
		local function extOf(name) return (name:match("%.([^%.]+)$") or ""):lower() end

		function C.isValidFileName(name)
			if type(name) ~= "string" or #name < 1 or #name > 64 or name:find("..", 1, true) or name:find("[^%w_%.%-]") then return false end
			return EXT[extOf(name)] == true
		end
		local function vec3(v, check)
			if type(v) ~= "table" or v[4] ~= nil then return false end
			for i = 1, 3 do if not finite(v[i]) or not check(v[i]) then return false end end
			return true
		end


		function C.validateItem(t)
			if type(t) ~= "table" then return false, "bad_item" end
			if t.schema ~= 1 then return false, "bad_schema" end
			if type(t.name) ~= "string" or not t.name:find("%S") or #t.name > L.maxName then return false, "bad_name" end
			if t.credit ~= nil and (type(t.credit) ~= "string" or #t.credit > L.maxCredit) then return false, "bad_credit" end
			if not SLOT_SET[t.slot] then return false, "bad_slot" end
			if t.fork_only ~= nil and type(t.fork_only) ~= "boolean" then return false, "bad_fork_flag" end
			if type(t.files) ~= "table" then return false, "bad_files" end
			local any = false
			for role, name in pairs(t.files) do
				local allowed = ROLE_EXT[role]
				if allowed == nil then return false, "bad_file_role" end
				if not C.isValidFileName(name) then return false, "bad_file_name" end
				if allowed and not allowed[extOf(name)] then return false, "bad_file_type" end
				any = true
			end
			if not any then return false, "no_files" end
			local p = t.placement
			if type(p) ~= "table" then return false, "bad_placement" end
			if not vec3(p.offset, function(n) return math.abs(n) <= L.maxOffset end) then return false, "bad_offset" end
			if not vec3(p.rotation, function(n) return n >= -L.maxRotation and n <= L.maxRotation end) then return false, "bad_rotation" end
			if not vec3(p.scale, function(n) return n >= L.minScale and n <= L.maxScale end) then return false, "bad_scale" end
			local settings = t.settings or {}
			if type(settings) ~= "table" or #settings > L.maxSettings then return false, "bad_settings" end
			for k in pairs(settings) do if type(k) ~= "number" or k < 1 or k > #settings or k % 1 ~= 0 then return false, "bad_settings" end end
			local keys = {}
			for _, s in ipairs(settings) do
				if type(s) ~= "table" or type(s.key) ~= "string" or #s.key < 1 or #s.key > 24 or s.key:find("[^%w_]") or keys[s.key] then return false, "bad_setting_key" end
				if type(s.label) ~= "string" or #s.label < 1 or #s.label > L.maxName then return false, "bad_setting_label" end
				keys[s.key] = true
				if s.type == "slider" then
					if not (finite(s.min) and finite(s.max) and finite(s.default)) or s.min > s.max or s.default < s.min or s.default > s.max
						or math.abs(s.min) > 1e6 or math.abs(s.max) > 1e6 then return false, "bad_slider" end
				elseif s.type == "toggle" then
					if type(s.default) ~= "boolean" then return false, "bad_toggle" end
				else
					return false, "bad_setting_type"
				end
			end
			return true
		end

		local UUID_PAT = "^(" .. string.rep("%x", 8) .. "%-" .. string.rep("%x", 4) .. "%-" .. string.rep("%x", 4) .. "%-"
			.. string.rep("%x", 4) .. "%-" .. string.rep("%x", 12) .. ")@(%d+)$"
		function C.parseRef(s)
			if type(s) ~= "string" or #s > 64 then return nil end
			local id, ver = s:match(UUID_PAT)
			ver = tonumber(ver)
			if not id or not ver or ver < 1 or ver > 1e9 then return nil end
			return id:lower(), ver
		end
		function C.ref(id, ver) return tostring(id) .. "@" .. tostring(ver) end


		C.MANIFEST_URL = "https://krulhub.dev/roclothes/community-manifest.json"
		C.CONTENT_BASE = "https://krulhub.dev/roclothes/content/"
		C.ROOT = "RClothesContent/community"
		C.items = {}
		local HS = game:GetService("HttpService")
		local function env() return System.Env or {} end
		function C.sha256Ok(raw, hex)
			if type(raw) ~= "string" or type(hex) ~= "string" or not hex:match("^%x+$") or #hex ~= 64 then return false end
			return hashOk(raw, hex) == true
		end
		function C.manifestUrl() return (C.FORK and C.FORK.manifestUrl) or C.MANIFEST_URL end

		System._rcDeadline = System._rcDeadline or function(secs, fn)
			local done, ok, a, b = false, false, nil, nil
			task.spawn(function() ok, a, b = pcall(fn); done = true end)
			local t0 = os.clock()
			while not done and os.clock() - t0 < secs do task.wait() end
			if not done then return true end
			return false, ok, a, b
		end
		local function _httpGetRaw(url)
			local ok, data = pcall(function() return game:HttpGet(url) end)
			if ok and type(data) == "string" and #data > 0 then return data end
			local req = env().request or env().http_request
			if not req then return nil, "no_request_fn" end
			local rok, res = pcall(req, { Url = url, Method = "GET", Headers = { ["X-RC-Token"] = (System._rcaTok and System._rcaTok()) or "" } })
			if rok and type(res) == "table" and tonumber(res.StatusCode) == 200 and type(res.Body) == "string" then return res.Body end
			return nil, "http_" .. tostring(rok and type(res) == "table" and res.StatusCode or "error")
		end
		function C.httpGet(url)
			local to, ok, a, b = System._rcDeadline(30, function() return _httpGetRaw(url) end)
			if to then return nil, "timeout" end
			if not ok then return nil, "error" end
			return a, b
		end
		local function readLocal(path)
			local E = env()
			if not (E.isfile and E.readfile) then return nil end
			local okF, isF = pcall(E.isfile, path)
			if not (okF and isF) then return nil end
			local okR, raw = pcall(E.readfile, path)
			return okR and type(raw) == "string" and raw or nil
		end
		local function ensureFolder(path)
			local E = env()
			if not E.makefolder then return end
			local acc = ""
			for part in path:gmatch("[^/]+") do
				acc = acc == "" and part or (acc .. "/" .. part)
				local okI, isD = pcall(function() return E.isfolder and E.isfolder(acc) end)
				if not (okI and isD) then pcall(E.makefolder, acc) end
			end
		end



		local function checkEntry(e)
			if type(e) ~= "table" or type(e.id) ~= "string" or type(e.ver) ~= "number" then return nil end
			local id, ver = C.parseRef(e.id .. "@" .. string.format("%d", e.ver))
			if not id or id ~= e.id:lower() or ver ~= e.ver then return nil end
			if type(e.assets) ~= "table" or type(e.files) ~= "table" then return nil end
			local count, total = 0, 0
			for name, a in pairs(e.assets) do
				if not C.isValidFileName(name) or type(a) ~= "table" then return nil end
				if a.path ~= "community/" .. id .. "/" .. ver .. "/" .. name then return nil end
				if type(a.sha256) ~= "string" or #a.sha256 ~= 64 or not a.sha256:match("^%x+$") then return nil end
				if type(a.size) ~= "number" or a.size < 0 or a.size > L.maxFileBytes then return nil end
				count += 1; total += a.size
			end
			if count < 1 or count > L.maxFiles or total > L.maxItemBytes then return nil end
			local roleNames = {}
			for role, a in pairs(e.files) do
				if type(a) ~= "table" or type(a.path) ~= "string" then return nil end
				local name = a.path:match("[^/]+$")
				if not name or not e.assets[name] or e.assets[name].sha256 ~= a.sha256 then return nil end
				roleNames[role] = name
			end
			local ok = C.validateItem({ schema = 1, name = e.name, credit = e.credit, slot = e.slot, files = roleNames,
				placement = e.placement, settings = e.settings, fork_only = e.fork_only })
			if not ok then return nil end
			e.id = id
			e.roles = roleNames
			return e
		end



		function C.sync(manifestJson, opts)
			opts = opts or {}
			local stats = { added = 0, removed = 0, failed = 0 }
			local okJ, m = pcall(function() return HS:JSONDecode(manifestJson) end)
			if not okJ or type(m) ~= "table" or m.schema ~= 1 or type(m.items) ~= "table" then stats.invalid = true; return stats end
			local E = env()
			local nextItems = {}
			local failedIds, cachedById = {}, nil

			local function olderVersion(e)
				local prev = C.items[e.id]
				if prev then return prev.ver ~= e.ver and prev or nil end
				if opts.offline then return nil end
				if not cachedById then
					cachedById = {}
					local okC, cm = pcall(function() return HS:JSONDecode(readLocal(C.ROOT .. "/manifest.json") or "") end)
					if okC and type(cm) == "table" and type(cm.items) == "table" then
						for _, r in ipairs(cm.items) do
							local ce = checkEntry(r)
							if ce and (not ce.fork_only or C.FORK ~= nil) then cachedById[ce.id] = ce end
						end
					end
				end
				local ce = cachedById[e.id]
				if not ce or ce.ver == e.ver then return nil end
				for _, a in pairs(ce.assets) do
					local bytes = readLocal("RClothesContent/" .. a.path)
					if not (bytes and #bytes == a.size and C.sha256Ok(bytes, a.sha256)) then return nil end
				end
				return ce
			end
			for _, raw in ipairs(m.items) do
				local e = checkEntry(raw)
				if e and (not e.fork_only or C.FORK ~= nil) and not nextItems[e.id] then
					local good = true
					for name, a in pairs(e.assets) do
						local path = "RClothesContent/" .. a.path
						local bytes = readLocal(path)


						if bytes and #bytes == a.size and C.verifiedHit(path, bytes, a.sha256) then

						elseif not (bytes and #bytes == a.size and C.sha256Ok(bytes, a.sha256)) then
							bytes = nil
							if not opts.offline and E.writefile then
								local body = C.httpGet(C.CONTENT_BASE .. a.path)
								if body and #body == a.size and C.sha256Ok(body, a.sha256) then
									ensureFolder(path:match("^(.*)/[^/]+$"))
									if pcall(E.writefile, path, body) then bytes = body; C.seedVerified(path, body, a.sha256) end
								end
							end
						else
							C.seedVerified(path, bytes, a.sha256)
						end
						if not bytes then good = false; break end
					end
					if good then
						local prev = C.items[e.id]
						if not prev or prev.ver ~= e.ver then stats.added += 1 end
						nextItems[e.id] = e
					else
						stats.failed += 1
						C._log("item " .. e.id .. "@" .. e.ver .. " did not verify; skipped")
						failedIds[e.id] = true
						nextItems[e.id] = olderVersion(e)
					end
				end
			end
			if not opts.offline then

				ensureFolder(C.ROOT)
				if E.writefile and stats.failed == 0 then pcall(E.writefile, C.ROOT .. "/manifest.json", manifestJson) end
				local listed = {}
				for _, raw in ipairs(m.items) do
					if type(raw) == "table" and type(raw.id) == "string" then listed[raw.id:lower()] = tonumber(raw.ver) end
				end
				local okL, dirs = pcall(function() return E.listfiles and E.listfiles(C.ROOT) or {} end)
				for _, dir in ipairs(okL and dirs or {}) do
					local id = tostring(dir):gsub("\\", "/"):match("([^/]+)$")
					if id and id ~= "manifest.json" and id ~= "state" then
						if not listed[id] then
							if E.delfolder and pcall(E.delfolder, C.ROOT .. "/" .. id) then stats.removed += 1 end
						elseif not failedIds[id] then
							local okV, vers = pcall(function() return E.listfiles(C.ROOT .. "/" .. id) end)
							for _, vdir in ipairs(okV and vers or {}) do
								local v = tostring(vdir):gsub("\\", "/"):match("([^/]+)$")
								if tonumber(v) ~= listed[id] and E.delfolder then pcall(E.delfolder, C.ROOT .. "/" .. id .. "/" .. v) end
							end
						end
					end
				end
			end
			C.items = nextItems
			if not opts.offline then

				local okM, mirrors = pcall(function() return E.listfiles and E.listfiles(C.UNIQ) or {} end)
				for _, f in ipairs(okM and mirrors or {}) do
					local id, ver = tostring(f):gsub("\\", "/"):match("/RClothesContent_community_([%x%-]+)_(%d+)_[^/]+$")
					if id and not failedIds[id] and not (nextItems[id] and nextItems[id].ver == tonumber(ver)) and E.delfile then pcall(E.delfile, f) end
				end
			end
			return stats
		end




		function C.prehashCached(stop)
			local okC, cm = pcall(function() return HS:JSONDecode(readLocal(C.ROOT .. "/manifest.json") or "") end)
			if not (okC and type(cm) == "table" and type(cm.items) == "table") then return end
			for _, r in ipairs(cm.items) do
				if stop() then return end
				local ce = checkEntry(r)
				if ce and (not ce.fork_only or C.FORK ~= nil) then
					for _, a in pairs(ce.assets) do
						if stop() then return end
						local path = "RClothesContent/" .. a.path
						local bytes = readLocal(path)
						if bytes and #bytes == a.size and not C.verifiedHit(path, bytes, a.sha256) and C.sha256Ok(bytes, a.sha256) then
							C.seedVerified(path, bytes, a.sha256)
						end
					end
				end
			end
		end
		function C.refresh()
			if System.isOff and System.isOff("community") then C._log("off (server switch)"); return { added = 0, removed = 0, failed = 0 } end



			local fetched, body = false, nil
			task.spawn(function()
				local okF, b = pcall(C.httpGet, C.manifestUrl())
				body = okF and b or nil
				fetched = true
			end)
			if not fetched then
				pcall(C.prehashCached, function() return fetched end)
				while not fetched do task.wait() end
			end
			if body then
				local r = C.sync(body)
				if not r.invalid then return r end
			end
			local cached = readLocal(C.ROOT .. "/manifest.json")
			if cached then return C.sync(cached, { offline = true }) end
			return { added = 0, removed = 0, failed = 0 }
		end

		C._onSynced = {}
		function C.onSynced(fn) C._onSynced[#C._onSynced + 1] = fn end

		function C.start()
			local ok, err = pcall(C.refresh)
			if not ok then C._log("sync failed: " .. tostring(err)) end
			C.synced = true
			for _, fn in ipairs(C._onSynced) do pcall(fn) end
		end

		function C.bySlot(slot)
			local out = {}
			for _, e in pairs(C.items) do if e.slot == slot then out[#out + 1] = e end end
			table.sort(out, function(a, b)
				local an, bn = a.name:lower(), b.name:lower()
				if an ~= bn then return an < bn end
				return a.id < b.id
			end)
			return out
		end


		function C.loadFile(e, roleOrName)
			if type(e) ~= "table" or type(e.assets) ~= "table" then return nil end
			local name = (e.roles and e.roles[roleOrName]) or roleOrName
			local bytes = C.readVerified(e, name)
			if not bytes then
				C._log("file " .. tostring(name) .. " of " .. tostring(e.id) .. " failed its fingerprint; refused")
				return nil
			end
			return Function.GetAsset(C.uniq(C.filePath(e, name), bytes))
		end



		C.UNIQ = "RClothesContent/_community_uniq"
		function C.uniq(path, bytes)
			local flat = C.UNIQ .. "/" .. (tostring(path):gsub("[/\\]", "_"))
			if readLocal(flat) ~= bytes then
				ensureFolder(C.UNIQ)
				local E = env()
				if not (E.writefile and pcall(E.writefile, flat, bytes)) then return path end
			end
			return flat
		end

		function C.filePath(e, name)
			local a = type(e) == "table" and type(e.assets) == "table" and e.assets[name]
			if not a then return nil end
			return a.localPath or ("RClothesContent/" .. a.path)
		end





		C._verified, C._verifiedBytes = {}, 0
		function C.readVerified(e, name)
			local a = type(e) == "table" and type(e.assets) == "table" and e.assets[name]
			if not a then return nil end
			local path = C.filePath(e, name)
			local bytes = readLocal(path)
			if not bytes then return nil end
			if a.localPath then return bytes end
			local hit = C._verified[path]
			if hit and hit.size == #bytes and hit.sha == a.sha256 and hit.bytes == bytes then return bytes end
			if not C.sha256Ok(bytes, a.sha256) then return nil end
			if C._verifiedBytes + #bytes > 16777216 then C._verified, C._verifiedBytes = {}, 0 end
			C._verified[path] = { size = #bytes, sha = a.sha256, bytes = bytes }
			C._verifiedBytes = C._verifiedBytes + #bytes
			return bytes
		end


		function C.verifiedHit(path, bytes, sha)
			local hit = C._verified[path]
			return hit ~= nil and hit.size == #bytes and hit.sha == sha and hit.bytes == bytes
		end


		function C.seedVerified(path, bytes, sha)
			local old = C._verified[path]
			local nb = C._verifiedBytes - (old and old.size or 0) + #bytes
			if nb > 16777216 then return end
			C._verified[path] = { size = #bytes, sha = sha, bytes = bytes }
			C._verifiedBytes = nb
		end






		local STATE_MAX = 4096
		local frameSubs, frameConn = {}, nil
		function C._step(dt)
			for i = #frameSubs, 1, -1 do
				local s = frameSubs[i]
				if s.h.stopped then
					table.remove(frameSubs, i)
				else
					local ok, err = pcall(s.fn, dt)
					if ok then s.errors = 0 end
					if not ok then
						s.errors += 1
						if s.errors >= 5 then
							table.remove(frameSubs, i)
							C._log("onFrame handler of " .. tostring(s.h.id) .. " disconnected after 5 errors: " .. tostring(err))
						end
					end
				end
			end
			if #frameSubs == 0 and frameConn then pcall(function() frameConn:Disconnect() end); frameConn = nil end
		end
		local function ensureFrame()
			if frameConn then return end
			frameConn = game:GetService("RunService").RenderStepped:Connect(function(dt) C._step(dt) end)
			if System.GlobalMaid and System.GlobalMaid.Give then pcall(System.GlobalMaid.Give, System.GlobalMaid, frameConn) end
		end
		local function compile(src, name)
			local ls = System.Env and System.Env.loadstring
			if ls == nil then ls = loadstring end
			if type(ls) ~= "function" then return nil, "no_loadstring" end
			local okC, chunk = pcall(ls, src, "=community:" .. tostring(name))
			if not okC or type(chunk) ~= "function" then return nil, "compile_error" end
			return chunk
		end

		local function newHandle(e, asset, character, seed)
			local h = { id = e.id, entry = e, stopped = false, wear = {}, remove = {}, setting = {}, requireCache = {}, settings = {} }
			for _, s in ipairs(e.settings or {}) do
				local v = seed and seed[s.key]
				if s.type == "slider" and not (type(v) == "number" and v == v and v >= s.min and v <= s.max) then v = s.default end
				if s.type == "toggle" and type(v) ~= "boolean" then v = s.default end
				h.settings[s.key] = v
			end
			local function fnOnly(fn) if type(fn) ~= "function" then error("function expected", 3) end; return fn end
			local statePath = "RClothesLerp/Community/state/" .. tostring(e.id):gsub("[^%w%-]", "_") .. ".json"
			h.api = {
				character = character,
				root = asset,
				onWear = function(fn) h.wear[#h.wear + 1] = fnOnly(fn) end,
				onRemove = function(fn) h.remove[#h.remove + 1] = fnOnly(fn) end,
				onSetting = function(fn) h.setting[#h.setting + 1] = fnOnly(fn) end,
				onFrame = function(fn)
					frameSubs[#frameSubs + 1] = { h = h, fn = fnOnly(fn), errors = 0 }
					ensureFrame()
				end,
				getSetting = function(key) return h.settings[key] end,
				saveState = function(tbl)
					if type(tbl) ~= "table" then return false end
					local okE, json = pcall(function() return HS:JSONEncode(tbl) end)
					if not okE or type(json) ~= "string" or #json > STATE_MAX then return false end
					local E = env()
					if not E.writefile then return false end
					ensureFolder("RClothesLerp/Community/state")
					return pcall(E.writefile, statePath, json) == true
				end,
				loadState = function()
					local raw = readLocal(statePath)
					local okD, t = pcall(function() return HS:JSONDecode(raw) end)
					return (raw and okD and type(t) == "table") and t or {}
				end,
				registerSmartBone = function(part, opts)
					if typeof(part) ~= "Instance" or not part:IsA("BasePart") or type(opts) ~= "table" then return false end
					for _, k in ipairs({ "Stiffness", "Elasticity", "Inertia", "Damping" }) do if type(opts[k]) == "number" then part:SetAttribute(k, opts[k]) end end
					if C.smartBoneHook then return pcall(C.smartBoneHook, part, opts) == true end
					return true
				end,

				asset = function(name)
					local id = C.loadFile(e, name)
					if not id then error("api.asset: no verified file " .. tostring(name), 2) end
					return id
				end,
				require = function(name)
					if type(name) ~= "string" or not C.isValidFileName(name) or not name:lower():match("%.lua$") or not e.assets[name] then
						error("api.require: unknown file " .. tostring(name), 2)
					end

					local cached = h.requireCache[name]
					if cached ~= nil then if cached == h.requireCache then return nil end return cached end
					local src = C.readVerified(e, name)
					if not src then error("api.require: " .. name .. " failed its fingerprint", 2) end
					local chunk, err = compile(src, name)
					if not chunk then error("api.require: " .. tostring(err), 2) end
					local v = chunk()
					if v == nil then h.requireCache[name] = h.requireCache else h.requireCache[name] = v end
					return v
				end,
			}
			function h:setSetting(key, value)
				local decl
				for _, s in ipairs(e.settings or {}) do if s.key == key then decl = s end end
				if not decl then return false end
				if decl.type == "slider" and not (type(value) == "number" and value == value and value >= decl.min and value <= decl.max) then return false end
				if decl.type == "toggle" and type(value) ~= "boolean" then return false end
				self.settings[key] = value
				for _, fn in ipairs(self.setting) do pcall(fn, key, value) end
				return true
			end
			function h:stop()
				if self.stopped then return end
				for _, fn in ipairs(self.remove) do pcall(fn) end
				self.stopped = true
			end
			return h
		end



		function C.runScript(e, asset, character, seed)
			local name = type(e) == "table" and e.roles and e.roles.script
			if not name then return nil, "no_script" end
			local src = C.readVerified(e, name)
			if not src then return nil, "script_unverified" end
			local chunk, err = compile(src, name)
			if not chunk then
				C._log("script of " .. tostring(e.id) .. " skipped: " .. tostring(err))
				return nil, err
			end
			local h = newHandle(e, asset, character, seed)
			local okM, main = pcall(chunk)
			if not okM then C._log("script of " .. tostring(e.id) .. " failed: " .. tostring(main)); return nil, "script_error: " .. tostring(main) end
			if type(main) ~= "function" then return nil, "script_must_return_function" end
			local okR, errR = pcall(main, h.api, asset)
			if not okR then
				h:stop()
				C._log("script of " .. tostring(e.id) .. " failed: " .. tostring(errR))
				return nil, "script_error: " .. tostring(errR)
			end
			for _, fn in ipairs(h.wear) do pcall(fn) end
			return h
		end






		local BODY = {
			["body.breasts"] = { field = "BreastsType", left = "Left Breast", right = "Right Breast", hide = { "Left Nipple", "Right Nipple" } },
			["body.butt"] = { field = "ButtType", left = "Left Butt", right = "Right Butt" },
			["body.torso"] = { field = "TorsoType", left = "Torso" },
			["body.arms"] = { field = "ArmType", left = "Left Arm", right = "Right Arm" },
			["body.legs"] = { field = "LegsType", left = "Left Leg", right = "Right Leg" },
		}
		C.BODY = BODY
		function C.slotForField(field)
			for slot, spec in pairs(BODY) do if spec.field == field then return slot end end
			return nil
		end
		local SKIN_NAMES = { ["Torso"] = true, ["Left Arm"] = true, ["Right Arm"] = true, ["Left Leg"] = true, ["Right Leg"] = true,
			["Left Breast"] = true, ["Right Breast"] = true, ["Left Butt"] = true, ["Right Butt"] = true }
		local CLOTHES_ANCHOR = { ["clothes.shirt"] = "Torso", ["clothes.pants"] = "Torso", ["clothes.accessory"] = "Head" }
		local CLOTHES_PREFIX = "community:"


		function C.entryFor(pd, slot)
			local ref = type(pd) == "table" and type(pd.Community) == "table" and pd.Community[slot]
			if type(ref) == "string" and ref:sub(1, 6) == "local:" then
				local le = C.localItems[ref:sub(7)]
				return (le and le.slot == slot) and le or nil
			end
			local id, ver = C.parseRef(ref)
			if not id then return nil end
			local e = C.items[id]
			if not e or e.ver ~= ver or e.slot ~= slot then return nil end
			return e
		end
		local function contentPath(e, role)
			local name = e.roles and e.roles[role]
			local bytes = name and C.readVerified(e, name)
			if not bytes then return nil end
			return "rbxasset://" .. C.uniq(C.filePath(e, name), bytes)
		end
		local function copy(t) local o = {}; for k, v in pairs(t) do o[k] = v end; return o end

		local function placed(baseEntry, e, meshPath, texPath, mirror)
			local d = copy(baseEntry)
			d.MeshId = meshPath
			d.TextureId = texPath
			local p, sx = e.placement, mirror and -1 or 1
			local off = Vector3.new(p.offset[1] * sx, p.offset[2], p.offset[3])
			d.Offset = baseEntry.Offset and (baseEntry.Offset + off) or off
			local r0 = type(baseEntry.Rotation) == "table" and baseEntry.Rotation or { X = 0, Y = 0, Z = 0 }
			d.Rotation = { X = (r0.X or 0) + p.rotation[1], Y = (r0.Y or 0) + p.rotation[2] * sx, Z = (r0.Z or 0) + p.rotation[3] * sx }
			if baseEntry.Size then d.Size = baseEntry.Size * Vector3.new(p.scale[1], p.scale[2], p.scale[3]) end
			d.CommunityId = e.id
			return d
		end


		function C.overlayPartList(base, pd)
			if type(base) ~= "table" or type(pd) ~= "table" or type(pd.Community) ~= "table" or next(pd.Community) == nil then return base end
			local over, hidden, skin = {}, {}, nil
			for slot, spec in pairs(BODY) do
				local e = C.entryFor(pd, slot)
				if e and pd[spec.field] == 1 then
					local lm = contentPath(e, "mesh")
					if lm and base[spec.left] then
						local lt = contentPath(e, "texture")
						over[spec.left] = placed(base[spec.left], e, lm, lt, false)
						if spec.right and base[spec.right] then
							over[spec.right] = placed(base[spec.right], e, contentPath(e, "mesh_right") or lm, contentPath(e, "texture_right") or lt, true)
						end
						for _, k in ipairs(spec.hide or {}) do hidden[k] = true end
					end
				end
			end
			local te = C.entryFor(pd, "body.texture")
			if te then skin = contentPath(te, "texture") end
			for slot, anchor in pairs(CLOTHES_ANCHOR) do
				local e = C.entryFor(pd, slot)
				local m = e and contentPath(e, "mesh")
				if m then
					over[CLOTHES_PREFIX .. e.id] = placed({ Instance = "Mesh", Name = e.name, Parent = { [1] = anchor },
						Size = Vector3.new(1, 1, 1), Transparency = 0, Reflectance = 0 }, e, m, contentPath(e, "texture"), false)
				end
			end
			if next(over) == nil and next(hidden) == nil and not skin then return base end
			return setmetatable({}, { __index = function(_, k)
				if hidden[k] then return nil end
				local o = over[k]
				if o == nil then o = base[k] end
				if skin and type(o) == "table" and o.Instance == "Mesh" and SKIN_NAMES[o.Name] and not o.CommunityId then
					o = copy(o); o.TextureId = skin
				end
				return o
			end, __newindex = function(_, k, v) base[k] = v end })
		end

		C.NAKED_OFF = { ["clothes.shirt"] = true, ["clothes.pants"] = true }
		function C.clothingNames(pd)
			local out = {}
			local naked = Function.IsNaked and Function.IsNaked(pd)
			for _, slot in ipairs(C.SLOTS) do
				if CLOTHES_ANCHOR[slot] and not (naked and C.NAKED_OFF[slot]) then
					local e = C.entryFor(pd, slot)
					if e and e.roles and e.roles.mesh then out[#out + 1] = CLOTHES_PREFIX .. e.id end
				end
			end
			return out
		end
		function C.clothesDef(name)
			if type(name) ~= "string" or name:sub(1, #CLOTHES_PREFIX) ~= CLOTHES_PREFIX then return nil end
			return { Weld = { name } }
		end

		function C.pickerOptions(slot, builtins)
			local opts, toRef = {}, {}
			for _, o in ipairs(builtins or {}) do opts[#opts + 1] = o end
			for _, e in ipairs(C.bySlot(slot)) do
				local label = e.name .. ((type(e.credit) == "string" and e.credit ~= "") and (" - " .. e.credit) or "")
				while toRef[label] or table.find(builtins or {}, label) do label = label .. " " end
				opts[#opts + 1] = label
				toRef[label] = C.ref(e.id, e.ver)
			end
			return opts, toRef
		end



		function C.stripScripts(inst)
			local n = 0
			if typeof(inst) ~= "Instance" then return 0 end
			for _, d in ipairs(inst:GetDescendants()) do
				if d:IsA("LuaSourceContainer") then pcall(function() d:Destroy() end); n += 1 end
			end
			return n
		end

		function C.loadModel(e)
			local name = e and e.roles and e.roles.model
			if not name or not C.readVerified(e, name) then return nil end
			local gca = (System.Env and System.Env.getcustomasset) or getcustomasset
			if not gca then return nil end
			local okU, url = pcall(gca, C.uniq(C.filePath(e, name), C.readVerified(e, name)))
			if not okU or type(url) ~= "string" then return nil end
			local okG, objs = pcall(function() return game:GetObjects(url) end)
			local root = okG and type(objs) == "table" and objs[1]
			if typeof(root) ~= "Instance" then return nil end
			C.stripScripts(root)
			if root:IsA("LuaSourceContainer") then
				local m = Instance.new("Model")
				for _, c in ipairs(root:GetChildren()) do c.Parent = m end
				pcall(function() root:Destroy() end)
				root = m
			end
			return root
		end

		function C.apply(pd, slot, ref)
			if type(pd) ~= "table" or not SLOT_SET[slot] then return false end
			local id, ver = C.parseRef(ref)
			local e = id and C.items[id]
			if not e or e.ver ~= ver or e.slot ~= slot then return false end
			pd.Community = type(pd.Community) == "table" and pd.Community or {}
			pd.Community[slot] = C.ref(id, ver)
			if BODY[slot] then pd[BODY[slot].field] = 1 end
			return true
		end
		function C.clear(pd, slot)
			if type(pd) == "table" and type(pd.Community) == "table" then pd.Community[slot] = nil end
		end



		C._live = setmetatable({}, { __mode = "k" })
		function C.afterBuild(pd, character, partFor)
			for _, live in ipairs(C._live[pd] or {}) do
				if live.handle then pcall(function() live.handle:stop() end) end
				if live.model then pcall(function() live.model:Destroy() end) end
			end
			C._live[pd] = nil
			if type(pd) ~= "table" or type(pd.Community) ~= "table" then return end
			local lives = {}
			C._live[pd] = lives
			local naked = Function.IsNaked and Function.IsNaked(pd)
			for _, slot in ipairs(C.SLOTS) do
				local e = not (naked and C.NAKED_OFF[slot]) and C.entryFor(pd, slot) or nil
				if e and (e.roles.script or e.roles.model) then
					local anchorName = (BODY[slot] and BODY[slot].left) or (e.roles.mesh and (CLOTHES_PREFIX .. e.id)) or CLOTHES_ANCHOR[slot] or "Torso"
					local okP, anchor = pcall(partFor, anchorName)
					anchor = okP and anchor or nil
					local live = { id = e.id }
					if e.roles.model and anchor then
						local m = C.loadModel(e)
						if m then m.Name = CLOTHES_PREFIX .. e.id .. ":model"; m.Parent = anchor; live.model = m end
					end
					if e.roles.script and anchor then
						local saved = type(pd.CommunitySettings) == "table" and pd.CommunitySettings[e.id] or nil
						live.handle = C.runScript(e, live.model or anchor, character, saved)
					end
					lives[#lives + 1] = live
				end
			end
		end


		function C.stopAll()
			for pd, lives in pairs(C._live) do
				for _, live in ipairs(lives) do
					if live.handle then pcall(function() live.handle:stop() end) end
					if live.model then pcall(function() live.model:Destroy() end) end
				end
				C._live[pd] = nil
			end
		end

		function C.afterBuildPD(pd, character)
			local cpl = type(pd) == "table" and pd.CurrentPartList or {}
			C.afterBuild(pd, character, function(name)
				return (cpl.Organ and cpl.Organ[name]) or (cpl.Clothes and cpl.Clothes[name])
					or (character and character:FindFirstChild(name, true)) or nil
			end)
		end

		function C.appendClothing(order, pd)
			for _, n in ipairs(C.clothingNames(pd)) do order[#order + 1] = n end
		end



		function C.bundleField(pd)
			if type(pd) ~= "table" or type(pd.Community) ~= "table" then return nil end
			local out, any = {}, false
			for slot, ref in pairs(pd.Community) do
				if SLOT_SET[slot] and C.parseRef(ref) then out[slot] = ref; any = true end
			end
			return any and out or nil
		end



		function C.wireCommunity(v)
			if type(v) == "table" or v == false then return v end
			return nil
		end
		function C.sanitizeRefs(t)
			if type(t) ~= "table" then return nil end
			local n = 0
			for _ in pairs(t) do n += 1; if n > #C.SLOTS then return nil end end
			local out, any = {}, false
			for slot, ref in pairs(t) do
				if type(slot) == "string" and SLOT_SET[slot] then
					local id, ver = C.parseRef(ref)
					if id then out[slot] = C.ref(id, ver); any = true end
				end
			end
			return any and out or nil
		end

		function C.handleFor(pd, id) for _, l in ipairs(C._live[pd] or {}) do if l.id == id then return l.handle end end end



		C.LOCAL_ROOT = "RClothesLerp/Community"
		C.API = "https://krulhub.dev/roclothes/community/"
		C.localItems = {}
		local B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
		local B64DEC = {}
		for i = 1, 64 do B64DEC[B64:byte(i)] = i - 1 end

		function C.base64encode(s)
			local out, n = table.create(math.ceil(#s / 3)), 0
			for i = 1, #s, 3 do
				local a, b, c = s:byte(i, i + 2)
				local v = a * 65536 + (b or 0) * 256 + (c or 0)
				local c1, c2, c3, c4 = bit32.rshift(v, 18), bit32.band(bit32.rshift(v, 12), 63), bit32.band(bit32.rshift(v, 6), 63), bit32.band(v, 63)
				n += 1
				out[n] = B64:sub(c1 + 1, c1 + 1) .. B64:sub(c2 + 1, c2 + 1) .. (b and B64:sub(c3 + 1, c3 + 1) or "=") .. (c and B64:sub(c4 + 1, c4 + 1) or "=")
				if n % 100000 == 0 and coroutine.isyieldable() then task.wait() end
			end
			return table.concat(out)
		end
		function C.base64decode(s)
			local out, n = {}, 0
			s = tostring(s):gsub("[^%w%+/]", "")
			for i = 1, #s, 4 do
				local a, b, c, d = B64DEC[s:byte(i)], B64DEC[s:byte(i + 1) or 0], B64DEC[s:byte(i + 2) or 0], B64DEC[s:byte(i + 3) or 0]
				local v = (a or 0) * 262144 + (b or 0) * 4096 + (c or 0) * 64 + (d or 0)
				n += 1
				out[n] = string.char(bit32.rshift(v, 16)) .. (c and string.char(bit32.band(bit32.rshift(v, 8), 255)) or "") .. (d and string.char(bit32.band(v, 255)) or "")
			end
			return table.concat(out)
		end

		local function lastPart(p) return (tostring(p):gsub("\\", "/"):match("([^/]+)$")) end

		function C.scanLocal()
			local E = env()
			local result = {}
			C.localItems = {}
			local okL, dirs = pcall(function() return E.listfiles and E.listfiles(C.LOCAL_ROOT) or {} end)
			for _, dir in ipairs(okL and dirs or {}) do
				local folder = lastPart(dir)
				local okD, isD = pcall(function() return E.isfolder and E.isfolder(C.LOCAL_ROOT .. "/" .. folder) end)
				if folder and folder:sub(1, 1) ~= "." and folder ~= "state" and okD and isD then
					local r = { files = {}, errors = {} }
					result[folder] = r
					local raw = readLocal(C.LOCAL_ROOT .. "/" .. folder .. "/item.json")
					local okJ, t = pcall(function() return HS:JSONDecode(raw) end)
					if not raw then table.insert(r.errors, "item.json is missing")
					elseif not okJ or type(t) ~= "table" then table.insert(r.errors, "item.json is not valid JSON")
					else
						r.item = t
						local ok, err = C.validateItem(t)
						if not ok then table.insert(r.errors, "item.json: " .. tostring(err)) end
					end
					local total, count = 0, 0
					local okF, files = pcall(function() return E.listfiles(C.LOCAL_ROOT .. "/" .. folder) end)
					for _, f in ipairs(okF and files or {}) do
						local name = lastPart(f)
						if name ~= "item.json" and C.isValidFileName(name) then
							local bytes = readLocal(C.LOCAL_ROOT .. "/" .. folder .. "/" .. name)
							if bytes then
								r.files[name] = bytes; total += #bytes; count += 1
								if #bytes > L.maxFileBytes then table.insert(r.errors, name .. " is over 2 MB") end
							end
						end
					end
					if count > L.maxFiles then table.insert(r.errors, "more than " .. L.maxFiles .. " files") end
					if total > L.maxItemBytes then table.insert(r.errors, "files add up to more than 8 MB") end
					if r.item and type(r.item.files) == "table" then
						for role, name in pairs(r.item.files) do
							if type(name) == "string" and not r.files[name] then table.insert(r.errors, role .. ": " .. name .. " is not in the folder") end
						end
					end
					if #r.errors == 0 then
						local assets = {}
						for name in pairs(r.files) do assets[name] = { localPath = C.LOCAL_ROOT .. "/" .. folder .. "/" .. name } end
						local t2 = r.item
						C.localItems[folder] = { id = "local:" .. folder, ver = 0, isLocal = true, name = t2.name, credit = t2.credit,
							slot = t2.slot, placement = t2.placement, settings = t2.settings or {}, roles = t2.files, assets = assets }
					end
				end
			end
			return result
		end
		function C.wearLocal(pd, folder)
			local le = C.localItems[folder]
			if not le then C.scanLocal(); le = C.localItems[folder] end
			if not le or type(pd) ~= "table" then return false end
			pd.Community = type(pd.Community) == "table" and pd.Community or {}
			pd.Community[le.slot] = "local:" .. folder
			if BODY[le.slot] then pd[BODY[le.slot].field] = 1 end
			return true
		end
		function C.saveTuning(folder, placement)
			local path = C.LOCAL_ROOT .. "/" .. tostring(folder) .. "/item.json"
			local raw = readLocal(path)
			local okJ, t = pcall(function() return HS:JSONDecode(raw) end)
			if not raw or not okJ or type(t) ~= "table" then return false end
			t.placement = placement
			if not C.validateItem(t) then return false end
			local E = env()
			if not (E.writefile and pcall(E.writefile, path, HS:JSONEncode(t))) then return false end
			if C.localItems[folder] then C.localItems[folder].placement = placement end
			return true
		end

		function C.token()
			local path = C.LOCAL_ROOT .. "/.token"
			local t = readLocal(path)
			if type(t) == "string" and #t >= 64 and not t:find("[^%w%-]") then return t end
			t = HS:GenerateGUID(false) .. HS:GenerateGUID(false)
			ensureFolder(C.LOCAL_ROOT)
			local E = env()
			if E.writefile then pcall(E.writefile, path, t) end
			return t
		end
		local function post(path, payload)
			local req = env().request or env().http_request
			if not req then return nil, "no_request_fn" end
			local okE, body = pcall(function() return HS:JSONEncode(payload) end)
			if not okE then return nil, "encode_failed" end
			local _to, ok, res = System._rcDeadline(30, function() return req({ Url = C.API .. path, Method = "POST", Headers = { ["Content-Type"] = "application/json" }, Body = body }) end)
			if _to then return nil, "timeout" end
			if not ok or type(res) ~= "table" then return nil, "no_connection" end
			local okD, j = pcall(function() return HS:JSONDecode(tostring(res.Body or "")) end)
			j = okD and type(j) == "table" and j or {}
			local code = tonumber(res.StatusCode) or 0
			if code >= 200 and code < 300 then return j end
			return nil, tostring(j.error or ("http_" .. code)) .. (j.detail and (" (" .. tostring(j.detail) .. ")") or "")
		end

		function C.submit(folder, opts)
			opts = opts or {}
			local r = C.scanLocal()[folder]
			if not r then return false, "no such folder" end
			if #r.errors > 0 then return false, r.errors[1] end
			local it = {}
			for k, v in pairs(r.item) do it[k] = v end
			if opts.credit ~= nil then it.credit = (opts.credit ~= "" and opts.credit) or nil end
			it.fork_only = (C.FORK ~= nil and opts.forkOnly == true) or false
			if type(it.settings) == "table" and #it.settings == 0 then it.settings = nil end
			local ok, err = C.validateItem(it)
			if not ok then return false, err end
			local files = {}
			for name, bytes in pairs(r.files) do files[name] = C.base64encode(bytes) end
			local j, perr = post("submit", { item = it, files = files, token = C.token(), scriptVersion = opts.scriptVersion,
				updateOf = opts.updateOf, submitter = { userId = opts.userId, displayName = opts.displayName } })
			if not j then return false, perr end
			return true, j.subId
		end
		function C.mine()
			local j = post("mine", { token = C.token() })
			return (j and type(j.items) == "table") and j.items or {}
		end
		function C.withdraw(subId)
			return post("withdraw", { token = C.token(), subId = subId }) ~= nil
		end
		local STATUS = { pending = "Pending review", spam = "Rejected as spam", withdrawn = "Withdrawn",
			superseded = "Replaced by a newer version", unpublished = "Removed" }
		function C.statusText(row)
			if type(row) ~= "table" then return "" end
			if row.status == "approved" then return "Approved (v" .. tostring(row.ver) .. ")" end
			if row.status == "rejected" then return (type(row.reason) == "string" and row.reason ~= "") and ("Rejected: " .. row.reason) or "Rejected" end
			return STATUS[row.status] or tostring(row.status)
		end

		return C
	end)(Function, _vnsIntegrityOk)

