return function(R, I)
local Player, System = I.Player, I.System





	System.animRT = (function()
		local clips, drivers, paused, conn = {}, {}, setmetatable({}, { __mode = "k" }), nil
		local FADE, RATE = 0.2, 1 / 30

		local COVER = {
