			tr[#tr + 1] = k
		end

		local function parseKeyframes(seq)
			local tracks, len = {}, 0
			for _, kf in ipairs(seq:GetKeyframes()) do
				local t = kf.Time
				if t > len then len = t end
				local function walk(pose)
					if pose.Weight > 0 then
						local style, dir = pose.EasingStyle.Name, pose.EasingDirection.Name


						local es
						if style == "CubicV2" then es = Enum.EasingStyle.Cubic
						elseif style ~= "Linear" and style ~= "Constant" then
							local ok, v = pcall(function() return Enum.EasingStyle[style] end); es = ok and v or nil
						end
