			end
			return tracks, len
		end


		local function curveEnd(c)
			local e = 0
			for _, axis in ipairs({ "X", "Y", "Z" }) do
				local ok, sub = pcall(function() return c[axis](c) end)
				if ok and sub then
					for _, k in ipairs(sub:GetKeys()) do if k.Time > e then e = k.Time end end
				end
			end
			if c:IsA("RotationCurve") then
				for _, k in ipairs(c:GetKeys()) do if k.Time > e then e = k.Time end end
			end
			return e
		end
		local function parseCurves(seq)
			local tracks, len = {}, 0
			local function walk(folder)
				for _, f in ipairs(folder:GetChildren()) do
					if f:IsA("Folder") then
						local pos, rot = f:FindFirstChild("Position"), f:FindFirstChild("Rotation")
						if pos or rot then
							local e = math.max(pos and curveEnd(pos) or 0, rot and curveEnd(rot) or 0)

							if e ~= e then e = 0 end
							e = math.clamp(e, 0, 60)
