				T.an = math.floor(os.clock() * 1000 + T.nonce) % 2 ^ 31
			end
			return true
		end



		T.COL = {
			void = { { 150, 70, 255 }, { 255, 90, 210 } }, vampire = { { 170, 10, 30 }, { 255, 60, 80 } },
			inferno = { { 255, 85, 25 }, { 255, 200, 60 } }, storm = { { 90, 200, 255 }, { 185, 125, 255 } },
			lightborn = { { 255, 190, 70 }, { 255, 248, 220 } }, frost = { { 110, 200, 255 }, { 220, 245, 255 } },
			mage = { { 150, 90, 255 }, { 90, 220, 255 } },

			starfall = { { 42, 29, 92 }, { 255, 138, 61 } }, radius = { { 63, 215, 255 }, { 30, 75, 255 } },
			ninelives = { { 242, 166, 90 }, { 255, 241, 220 } }, seraph = { { 255, 200, 221 }, { 205, 180, 219 } },

			error404 = { { 51, 255, 255 }, { 255, 51, 255 } }, playerone = { { 255, 210, 63 }, { 192, 24, 42 } },
			bigspender = { { 255, 212, 71 }, { 46, 204, 113 } },
		}
		T.colours = function(id)
			local c = T.COL[id]
			if not c then return nil end
			return { c[1][1], c[1][2], c[1][3] }, { c[2][1], c[2][2], c[2][3] }
		end

		T.wire = function()
			local th = T.worn()
			local p = { look = { theme = th, short = T.short(), respawn = "short" } }
			local c1, c2 = T.colours(th)
			if c1 then p.look.c1, p.look.c2 = c1, c2 end
			if T.an then p.an = T.an end
			if T.extend then
				local ok, q = pcall(T.extend, p)
				if ok and type(q) == "table" then p = q end
			end
			return p
		end

		T.active = function()
			return T.worn() ~= "none" or (T.lastTheme ~= nil and T.lastTheme ~= "none") or T.extend ~= nil
		end

		T.showLocal = function()
			local p = T.wire()
			if System.Staff and System.Staff.onPresence then pcall(System.Staff.onPresence, Player.UserId, (not p.incog) and p or nil) end
			return p
		end
		T.send = function()
			local p = T.showLocal()
			local send = System._avsyncSend
			if type(send) == "function" and send({ t = "staff", p = p }) == true then
				T.lastTheme = p.look and p.look.theme or "none"
				if p.an ~= nil then T.arr[#T.arr + 1] = os.clock() end
				T.an = nil
				return true
			end
			return false
		end
		T.tick = function()
			if System._sessionAlive == false then
				if T.conn then pcall(function() T.conn:Disconnect() end); T.conn = nil end
				return
			end
			local t = os.clock()
			local W = System._avsWs
			local ready = W ~= nil and W.ready == true
			if ready and not T.wasReady and T.active() then T.due = t end
			T.wasReady = ready
