		end
		if _RCA then _RCA.onThemes = T.onThemes end
		if _RCA and _RCA.themeInfo then T.onThemes() end
		for _, f in ipairs(type(System._themesHooks) == "table" and System._themesHooks or {}) do pcall(f) end
		if type(System._themesDot) == "function" then pcall(System._themesDot) end
