	local UW = math.clamp(#K.NAME * 0.26 + 0.9, 2.2, 6.4)
	local uPill = K.frame(bb, { BackgroundTransparency = 1, BackgroundColor3 = Color3.fromRGB(8, 18, 58), AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.84),
		Size = UDim2.fromScale(UW / Wd, 0.5 / Hd), ZIndex = 4 })
	K.new("UICorner", { CornerRadius = UDim.new(0.5, 0) }, uPill)
	local nm = K.text(bb, { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.84), Size = UDim2.fromScale(0.7, 0.2),
		Text = K.NAME, FontFace = Font.new("rbxasset://fonts/families/Sarpanch.json", Enum.FontWeight.Bold), TextColor3 = WB, ZIndex = 5 })
	K.new("UIStroke", { Color = Color3.fromRGB(6, 14, 50), Thickness = 1.4, Transparency = 0.3 }, nm)

	local bolt, setBolt = K.seg(bb, Wd, Hd, WB, 1, 7)
	local flash = K.img(bb, { Image = K.T("glowui.png"), ImageColor3 = WB, ImageTransparency = 1, AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.36), Size = UDim2.fromScale(1.3, 1.6), ZIndex = 7 })

	K.emitterAt(Vector3.new(0, 3.0, 0), { Texture = K.T("spark.png"), Rate = 4, Lifetime = NR(0.3, 0.6), Speed = NR(1, 2.5), EmissionDirection = Enum.NormalId.Bottom,
		Acceleration = Vector3.new(0, -6, 0), Size = NS({ NK(0, 0.1), NK(1, 0) }), Color = CS(WB, C1), Orientation = Enum.ParticleOrientation.VelocityParallel,
		box = Vector3.new(5.5, 0.1, 0.2) })
	local flick, nextFlick = 0, 3

	local NB = 6
	local lb, setLb = {}, {}
	for i = 1, NB do lb[i], setLb[i] = K.seg(bb, Wd, Hd, WB, 1, 8) end
	local lbT, lbOn, lbY = 3, 0, {}


	local CX, CY, RD = Wd * 0.5, Hd * 0.4, Hd * 0.46
	local dial = K.img(bb, { Image = K.T("ring_c.png"), ImageColor3 = C1, ImageTransparency = 1, AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(CX / Wd, CY / Hd), Size = UDim2.fromScale(RD * 2.1 / Wd, RD * 2.1 / Hd), ZIndex = 1 })
	local NTK = 24
	local tks = {}
	for i = 1, NTK do
		local a = (i - 1) / NTK * math.pi * 2
		local long = (i - 1) % 6 == 0
		local r = RD * (long and 0.86 or 0.9)
		tks[i] = K.frame(bb, { BackgroundTransparency = 1, BackgroundColor3 = long and WB or C1, AnchorPoint = Vector2.new(0.5, 0.5), ZIndex = 1, Rotation = math.deg(a),
			Position = UDim2.fromScale((CX + math.cos(a) * r) / Wd, (CY + math.sin(a) * r) / Hd), Size = UDim2.fromScale((long and 0.22 or 0.12) / Wd, 0.03 / Hd) })
	end
	local NW = 5
	local sw, setSw = {}, {}
	for i = 1, NW do sw[i], setSw[i] = K.seg(bb, Wd, Hd, i == 1 and WB or C1, 1, 2) end
	local hi = K.text(bb, { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.36), Size = UDim2.fromScale(0.9, 0.5),
		Text = "Radius.", FontFace = FONT, TextColor3 = W, TextTransparency = 1, ZIndex = 6 })
	local hiG = K.new("UIGradient", { Transparency = NS({ NK(0, 1), NK(0.42, 1), NK(0.5, 0), NK(0.58, 1), NK(1, 1) }) }, hi)


	local ch = System.StaffThemes._tagCh or {}
	local RB = { b = {}, beat = ch.sBeat or 0, bk = 0, scanT = 0, list = {} }
	for i = 1, 8 do
		local f = K.frame(bb, { BackgroundTransparency = 1, BackgroundColor3 = WB, AnchorPoint = Vector2.new(0.5, 0.5), ZIndex = 2, Size = UDim2.fromScale(0.16 / Wd, 0.16 / Hd) })
		K.new("UICorner", { CornerRadius = UDim.new(0.5, 0) }, f)
		RB.b[i] = { f = f, k = 0 }
	end
	local PLRS = game:GetService("Players")
	return function(t, dt, it)

		RB.scanT -= dt
		local root = ch.hrp
		if RB.scanT <= 0 and root and root.Parent then
			RB.scanT = 0.25
			table.clear(RB.list)
			local inv = root.CFrame:Inverse()
			for _, p in ipairs(PLRS:GetPlayers()) do
				local c = p.Character
				local r = c and c:FindFirstChild("HumanoidRootPart")
				if r and r ~= root then
					local v = inv * r.Position
					local d = Vector2.new(v.X, v.Z)
					if d.Magnitude < 60 and #RB.list < #RB.b then RB.list[#RB.list + 1] = d / 60 end
				end
			end
		end
		local saN = (t * 1.6) % (math.pi * 2)
		local prevN = ((t - dt) * 1.6) % (math.pi * 2)
		for i, B in ipairs(RB.b) do
			local d = RB.list[i]
			if d then
				local bx, by = CX + d.X * RD * 0.9, CY + d.Y * RD * 0.9
				local ab = math.atan2(by - CY, bx - CX) % (math.pi * 2)
				local passed = (prevN <= saN) and (ab > prevN and ab <= saN) or (prevN > saN and (ab > prevN or ab <= saN))
				if passed then B.k = 1 end
				B.f.Position = UDim2.fromScale(bx / Wd, by / Hd)
				local z = 0.14 + 0.12 * B.k
				B.f.Size = UDim2.fromScale(z / Wd, z / Hd)
			end
			B.k = math.max(0, B.k - dt * 0.8)
			B.f.BackgroundTransparency = d and 1 - c01((it - 0.6) / 0.5) * (0.15 + 0.75 * B.k) or 1
		end
		if (ch.sBeat or 0) ~= RB.beat then RB.beat, RB.bk = ch.sBeat or 0, 1 lbT = 0 end
