		for _, f in ipairs(tks) do f.BackgroundTransparency = 1 - 0.45 * on end
		for i = 1, NW do
			local a = sa - (i - 1) * 0.12
			setSw[i](CX, CY, CX + math.cos(a) * RD * 0.95, CY + math.sin(a) * RD * 0.95, i == 1 and 0.05 or 0.04)
			sw[i].BackgroundTransparency = 1 - on * (i == 1 and 0.75 or 0.4 * (1 - (i - 1) / NW))
		end

		local tipX = CX + math.cos(sa) * RD * 0.95
		local near = c01(1 - math.abs(math.sin(sa)) / 0.35)
		hiG.Offset = Vector2.new((tipX / Wd - 0.05) / 0.9 - 0.5, 0)
		hi.TextTransparency = 1 - 0.75 * near * on
