			lbOn = 0.32
			for i = 0, NB do lbY[i] = Hd * 0.36 + ((i == 0 or i == NB) and 0 or (math.random() - 0.5) * 0.7) end
		end
		lbOn = math.max(0, lbOn - dt)
		local lk = lbOn > 0 and c01(lbOn / 0.32) or 0
		for i = 1, NB do
			local x0, x1 = 0.7 + (i - 1) / NB * (Wd - 1.4), 0.7 + i / NB * (Wd - 1.4)
			if lk > 0 then
				local jx = (math.random() - 0.5) * 0.06
				setLb[i](x0, lbY[i - 1] + jx, x1, lbY[i] - jx, 0.07 + 0.05 * lk)
				lb[i].BackgroundTransparency = (math.random() < 0.15) and 0.6 or (1 - lk)
			else lb[i].BackgroundTransparency = 1 end
		end

		local bk = c01(it / 0.12)
		local bx = Wd * 0.5 + 0.3 * math.sin(it * 40)
		setBolt(bx, -0.2, bx + 0.15, -0.2 + 1.3 * bk, 0.08)
		bolt.BackgroundTransparency = (it < 0.3) and 0 or 1
		local on = c01((it - 0.1) / 0.06)
		flash.ImageTransparency = 1 - 0.8 * c01(1 - math.abs(it - 0.14) / 0.25)

		nextFlick -= dt
		if nextFlick <= 0 then nextFlick = 2.5 + math.random() * 3 flick = 0.22 end
		flick = math.max(0, flick - dt)
		local fk = (flick > 0 and math.floor(flick * 40) % 2 == 0) and 0.55 or 0
		word.TextTransparency = 1 - on + fk
		wst.Transparency = 1 - 0.9 * on + fk
		wg.Offset = Vector2.new(0.08 * math.sin(t * 1.3), 0)
		glow.ImageTransparency = math.max(0, 0.72 + 0.1 * math.sin(t * 2) + fk * 0.3 - 0.35 * lk - 0.4 * RB.bk)
