System.StaffThemes.THEMES.radius = function(L, C)
	local C1, C2, W = C.c1, C.c2, L.W
	local NS, CS, NR, K, CK = L.NS, L.CS, L.NR, L.K, L.CK
	local ch, rnd, c01 = L.ch, L.rnd, L.c01
	local WB = Color3.fromRGB(205, 240, 255)
	local NEON = Enum.Material.Neon
	local BALL = Enum.PartType.Ball
	local TAU = math.pi * 2
	local function sc() return ch.sc or 1 end

	L.cine.radius = { font = L.fam("Sarpanch", Enum.FontWeight.Heavy), sub = L.fam("Sarpanch"), kick = "R A D I U S .", subText = "H A S   A R R I V E D",
		stroke = Color3.fromRGB(6, 14, 50), upper = false, grad = function(c1, c2) return CS({ CK(0, WB), CK(0.4, c1), CK(1, c2) }) end,


		card = function(Cd)
			local HIT = 0.16
			local NB = 7
			local bs = {}
			for i = 1, NB do bs[i] = { L.segPx(Cd.card, WB, 9) } end
			local fl = L.new("Frame", { BorderSizePixel = 0, BackgroundColor3 = WB, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, Cd.CY),
				Size = UDim2.fromScale(0.75, 0.18), BackgroundTransparency = 1, ZIndex = 5 }, Cd.card)
			L.new("UICorner", { CornerRadius = UDim.new(1, 0) }, fl)
			L.new("UIGradient", { Transparency = NS({ K(0, 1), K(0.5, 0), K(1, 1) }) }, fl)
			local NT = 21
			local ticks = {}
			for i = 1, NT do
				ticks[i] = L.new("Frame", { BorderSizePixel = 0, BackgroundColor3 = (i - 1) % 5 == 0 and W or WB, AnchorPoint = Vector2.new(0.5, 0),
					Size = UDim2.fromOffset(2, (i - 1) % 5 == 0 and 12 or 6), BackgroundTransparency = 1, ZIndex = 6 }, Cd.card)
			end
			local xs = {}
			return function(tt, a, out)
				local V = L.vp()
				local ex, ey = 0.5 * V.X, Cd.CY * V.Y
				if #xs == 0 then for i = 0, NB do xs[i] = (i == 0 or i == NB) and 0 or rnd(-1, 1) * 0.03 * V.X end end

				local bk = c01(tt / HIT)
				for i = 1, NB do
					local f, set = bs[i][1], bs[i][2]
					local y0, y1 = (i - 1) / NB * ey * bk, i / NB * ey * bk
					set(ex + xs[i - 1], y0, ex + xs[i], y1, 5 + 4 * (1 - c01((tt - HIT) / 0.2)))
					f.BackgroundTransparency = tt < 0.35 and ((math.random() < 0.2) and 0.5 or 0) or 1
				end
				if tt < HIT then
					Cd.nm.TextTransparency, Cd.nst.Transparency = 1, 1
				else
					local k = tt - HIT
					Cd.nm.TextTransparency = (1 - c01(k / 0.06)) + (1 - out)
					local z = 1 + 0.35 * (1 - L.outBack(c01(k / 0.25)))
					Cd.box.Size = UDim2.fromScale(0.62 * z, 0.085 * z)
					fl.BackgroundTransparency = 0.1 + 0.9 * c01(k / 0.45)
					for i = 1, NT do
						local tk = c01((k - 0.2 - math.abs(i - (NT + 1) / 2) * 0.025) / 0.1)
						ticks[i].Position = UDim2.fromScale(0.5 + (i - (NT + 1) / 2) / (NT - 1) * 0.5, Cd.CY + 0.05)
						ticks[i].BackgroundTransparency = 1 - tk * 0.9 * out
					end
				end
			end
		end }


	local function ray(p0, p1, w, life)
		local a0, a1 = L.att(p0), L.att(p1)
		local core = L.beam(a0, a1, { Width0 = w * 0.35, Width1 = w * 0.35, Brightness = 10, Color = CS(WB), Transparency = NS(0) })
		local soft = L.beam(a0, a1, { Texture = L.T("softbeam.png") or "", Width0 = w * 3, Width1 = w * 3, Brightness = 3, Color = CS(C1, C2), Transparency = NS(0.3) })
		L.bolt(p0, p1, { col = W, w = w * 0.16, segs = 6, jit = (p1 - p0).Magnitude * 0.03, life = life * 0.7, bright = 8 })
		L.fx(life, function(k)
			core.Transparency = NS(k * k)
			soft.Transparency = NS(0.3 + 0.7 * k)
			local cw = w * 0.35 * (1 - 0.6 * k)
			core.Width0, core.Width1 = cw, cw
		end, { a0, a1, core, soft })
	end

	local function arc(p0, p1, w, life) L.bolt(p0, p1, { col = WB, w = w, segs = 4, jit = (p1 - p0).Magnitude * 0.25, life = life, bright = 6 }) end



	local function beamRing(n, w, col, bright, glow)
		local R = { a = {}, c = {}, g = {}, tr = -1, objs = {} }
		for i = 1, n do R.a[i] = L.att() R.objs[#R.objs + 1] = R.a[i] end
		for i = 1, n do
			local j = i % n + 1
			R.c[i] = L.beam(R.a[i], R.a[j], { Width0 = w, Width1 = w, Brightness = bright, FaceCamera = true, Color = CS(col), Transparency = NS(1) })
			R.objs[#R.objs + 1] = R.c[i]
			if glow then
				R.g[i] = L.beam(R.a[i], R.a[j], { Texture = L.T("softbeam.png") or "", Width0 = w * 6, Width1 = w * 6, Brightness = 1.6, FaceCamera = true, Color = CS(glow), Transparency = NS(1) })
				R.objs[#R.objs + 1] = R.g[i]
			end
		end
		function R.set(cf, r, tr)
			for i = 1, n do
				local a = (i - 1) / n * TAU
				R.a[i].WorldPosition = cf:PointToWorldSpace(Vector3.new(math.cos(a) * r, 0, math.sin(a) * r))
			end
			tr = math.floor(tr * 50 + 0.5) / 50
			if tr ~= R.tr then
				R.tr = tr
				local ns, gs = NS(tr), NS(0.45 + 0.55 * tr)
				for i = 1, n do R.c[i].Transparency = ns if R.g[i] then R.g[i].Transparency = gs end end
			end
		end
		function R.width(w2) w2 = math.floor(w2 * 200 + 0.5) / 200 if w2 == R.w then return end R.w = w2 for i = 1, n do R.c[i].Width0, R.c[i].Width1 = w2, w2 if R.g[i] then R.g[i].Width0, R.g[i].Width1 = w2 * 6, w2 * 6 end end end
		return R
	end

	local function flat(col) return L.part({ Material = NEON, Color = col, Transparency = 1, Size = Vector3.new(0.1, 0.05, 0.1) }) end
	local function setFlat(p, a, b, w)
		local d = b - a
		local len = d.Magnitude
		if len < 0.05 then p.Transparency = 1 return false end
		p.Size = Vector3.new(w, 0.05, len)
		p.CFrame = CFrame.lookAt(a + d / 2, b)
		return true
	end
	local function hexPt(o, r, rot, i) local a = rot + (i - 1) / 6 * TAU return o + Vector3.new(math.cos(a) * r, 0, math.sin(a) * r) end



	local haloR = beamRing(20, 0.07, WB, 8, C1)
	local nodes = {}
	for i = 1, 3 do nodes[i] = L.part({ Shape = BALL, Material = NEON, Color = WB, Transparency = 1, Size = Vector3.one * 0.18 }) end
	local haloP = L.part()
	local haloL = L.new("PointLight", { Color = C1, Range = 8, Brightness = 0.9, Shadows = false }, haloP)
	local haloSp = L.pe(haloP, { Texture = L.T("spark.png"), Shape = Enum.ParticleEmitterShape.Disc, ShapePartial = 0.9, EmissionDirection = Enum.NormalId.Top,
		Rate = 6, Lifetime = NR(0.15, 0.3), Speed = NR(0.5, 1.5), Size = NS({ K(0, 0.12), K(1, 0) }), Color = CS(WB, C1), Brightness = 6, LockedToPart = true })


	local NTRK = 12
	local trk = {}
	for i = 1, NTRK do
		local a = {}
		for j = 1, 4 do a[j] = L.att() end
		local b = {}
		for j = 1, 3 do b[j] = L.beam(a[j], a[j + 1], { Texture = L.T("softbeam.png") or "", Width0 = 0, Width1 = 0, Brightness = 5, FaceCamera = true, Color = CS(WB), Transparency = NS(1) }) end
		trk[i] = { a = a, b = b, t = 99, life = 1, w = 0.05, nseg = 1, col = WB }
	end
	local trkI, trkT = 0, 0.3
	local function track(s)
		trkI = trkI % NTRK + 1
		local T = trk[trkI]
		local c = (ch.pos or Vector3.zero) + Vector3.new(rnd(-7, 7), rnd(-2, 6), rnd(-7, 7)) * s
		local dir = Vector3.new(rnd(-1, 1), rnd(-0.6, 0.6), rnd(-1, 1))
		dir = dir.Magnitude > 0.05 and dir.Unit or Vector3.xAxis
		local kind = math.random()
		local len
		if kind < 0.4 then len, T.w, T.nseg, T.life, T.col = rnd(1, 2.2) * s, 0.14 * s, 1, rnd(0.5, 0.8), W
		elseif kind < 0.85 then len, T.w, T.nseg, T.life, T.col = rnd(4, 8) * s, 0.05 * s, 3, rnd(0.7, 1.1), WB
		else len, T.w, T.nseg, T.life, T.col = rnd(10, 16) * s, 0.035 * s, 1, rnd(0.6, 0.9), C1:Lerp(WB, 0.5) end
		local p0 = c - dir * len / 2
		local side = dir:Cross(Vector3.yAxis)
		side = side.Magnitude > 0.05 and side.Unit or Vector3.zAxis
		for j = 1, 4 do
			local u = (j - 1) / 3
			local wob = (T.nseg == 3 and j > 1 and j < 4) and side * rnd(-0.12, 0.12) * len or Vector3.zero
			T.a[j].WorldPosition = p0 + dir * len * u + wob
		end
		for j = 1, 3 do T.b[j].Color = CS(T.col, C1) end
		T.t, T.lw, T.ltr = 0, nil, nil
	end

	local gP = L.part({ Size = Vector3.new(0.6, 0.2, 0.6) })
	local gSp = L.pe(gP, { Texture = L.T("spark.png"), EmissionDirection = Enum.NormalId.Top, Lifetime = NR(0.2, 0.5), Speed = NR(5, 12), SpreadAngle = Vector2.new(80, 80),
		Acceleration = Vector3.new(0, -30, 0), Size = NS({ K(0, 0.18), K(1, 0) }), Color = CS(WB, C1), Orientation = Enum.ParticleOrientation.VelocityParallel,
		Squash = NS(-1.5), Brightness = 7 })
	local flashL = L.new("PointLight", { Color = C1, Range = 12, Brightness = 0, Shadows = false }, gP)


	local rig, trail, hands = {}, nil, {}
	local function rebind()
		for _, o in ipairs(rig) do pcall(function() o:Destroy() end) end
		rig, hands = {}, {}
		local hrp, char = ch.hrp, ch.char
		if not (hrp and char) then return end

		for _, n in ipairs({ "LeftHand", "RightHand" }) do local p = char:FindFirstChild(n) if p then hands[#hands + 1] = { p = p, off = Vector3.zero } end end
		if #hands == 0 then
			for _, n in ipairs({ "Left Arm", "Right Arm" }) do
				local p = char:FindFirstChild(n)
				if p and p:IsA("BasePart") then hands[#hands + 1] = { p = p, off = Vector3.new(0, -p.Size.Y * 0.45, 0) } end
			end
		end
	end
	rebind()

	System.StaffThemes._tagCh = ch
	local tag = System.StaffThemes.headTag(L, "radius", C1, C2, { c1 = C1, c2 = C2, role = "R A D I U S ." })
	System.StaffThemes._tagCh = nil

	local held = nil
	local deathGone = nil
	local dying = false
	local function hide(on)
		if on then
			held = held or {}
			for d in pairs(L.bodyParts()) do if not held[d] then held[d] = true d.LocalTransparencyModifier = 1 end end
		elseif held then
			for d in pairs(held) do if d.Parent then pcall(function() d.LocalTransparencyModifier = 0 end) end end
			held = nil
		end
	end
	local function bodyGhost(col, life)
		if not ch.char then return nil end
		local g = L.ghost(col, NEON, life, true)
		local list = {}
		for _, p in ipairs(g:GetChildren()) do
			if p:IsA("BasePart") then p.LocalTransparencyModifier = 0 list[#list + 1] = { p = p, cf = p.CFrame } end
		end
		return list
	end
	local function fadeGhost(g, life, from)
		if not g then return end
		L.fx(life, function(k) for _, gp in ipairs(g) do gp.p.Transparency = (from or 0.1) + (1 - (from or 0.1)) * k end end, {})
	end
	local function bodyList()
		local t = {}
		for d in pairs(L.bodyParts()) do if d:IsA("BasePart") then t[#t + 1] = d end end
		return t
	end
	local function haloHeight() return (ch.head and ch.head.Parent and ch.head.Position or ch.pos + Vector3.new(0, 1.5, 0)) + Vector3.new(0, 1.15 * sc(), 0) end

	local function hitGround(p, s, big)
		L.groundWave(p, "ring_c.png", WB, 0.6 * s, (big and 16 or 5) * s, big and 0.6 or 0.35, 2.4)
		if big then L.groundWave(p, "ring_c.png", C2, 1 * s, 10 * s, 0.9, 2.2) end
		gP.CFrame = CFrame.new(p + Vector3.new(0, 0.15, 0))
		gSp:Emit(big and 50 or 10)
		flashL.Range = (big and 26 or 12) * s
		flashL.Brightness = big and 9 or 4
	end

	local function haloSnap(s)
		local R = beamRing(20, 0.09 * s, WB, 9, C1)
		L.fx(0.3, function(k) R.set(CFrame.new(haloHeight()), (3 - 1.8 * L.outQuad(k)) * s, 0.05 + 0.95 * k) end, R.objs)
	end



	local function shortSingle()
		local o, s = L.ground(ch.feet, 3, 8), sc()
		hide(true)
		L.timeline(1.6, function(t, once)
			if held and once("late", 0.2) then hide(true) end
			if once("strike", 0.25) then
				ray(o + Vector3.new(rnd(-2, 2), 60, rnd(-2, 2)), o, 0.9 * s, 0.35)
				hitGround(o, s, true)
				hide(false)
				fadeGhost(bodyGhost(WB, 0.6), 0.6)
				haloSnap(s)
			end
		end, {}, function() hide(false) end)
	end


	local function shortTriple()
		local o, s = L.ground(ch.feet, 3, 8), sc()
		hide(true)
		local rot = rnd(0, TAU)
		local pts = {}
		for i = 1, 3 do
			local a = rot + (i - 1) * TAU / 3
			pts[i] = L.ground(o + Vector3.new(math.cos(a), 0, math.sin(a)) * 4.5 * s, 3, 8)
		end
		local mid = o + Vector3.new(0, 1.4 * s, 0)
		local edges = {}
		for i = 1, 3 do edges[i] = flat(WB) end
		local arcT = 0
		L.timeline(2.2, function(t, once)
			if held and once("late", 0.2) then hide(true) end
			for i = 1, 3 do
				if once("s" .. i, 0.12 + (i - 1) * 0.2) then
					ray(pts[i] + Vector3.new(0, 50, 0), pts[i], 0.5 * s, 0.3)
					hitGround(pts[i], s, false)
				end
			end

			local join = c01((t - 0.6) / 0.15)
			local shrink = L.inQuad(c01((t - 0.8) / 0.25))
			for i = 1, 3 do
				local a, b = pts[i]:Lerp(o, shrink), pts[i % 3 + 1]:Lerp(o, shrink)
				a, b = a + Vector3.new(0, 0.08, 0), b + Vector3.new(0, 0.08, 0)
				if join > 0 and t < 1.05 then
					setFlat(edges[i], a, a:Lerp(b, join), 0.14 * s)
					edges[i].Transparency = 0.05
				else edges[i].Transparency = 1 end
			end
			arcT -= L.lastDt or 0.016
			if t > 0.6 and t < 1.05 and arcT <= 0 then
				arcT = 0.05
				local i = math.random(1, 3)
				local a, b = pts[i]:Lerp(o, shrink), pts[i % 3 + 1]:Lerp(o, shrink)
				arc(a + Vector3.new(0, 0.3, 0), b + Vector3.new(0, 0.3, 0), 0.08, 0.08)
			end
			if once("meet", 0.95) then
				for i = 1, 3 do ray(pts[i]:Lerp(o, 0.8) + Vector3.new(0, 0.3, 0), mid, 0.3 * s, 0.3) end
			end
			if once("show", 1.05) then
				hitGround(o, s, true)
				hide(false)
				fadeGhost(bodyGhost(WB, 0.7), 0.7)
				haloSnap(s)
			end
		end, edges, function() hide(false) end)
	end

	local function shortHalo()
		local o, s = L.ground(ch.feet, 3, 8), sc()
		hide(true)
		local hp = haloHeight()
		local R1 = beamRing(20, 0.08 * s, WB, 8, C1)
		local R2 = beamRing(20, 0.05 * s, C1, 6, C2)
		local objs = {}
		for _, x in ipairs(R1.objs) do objs[#objs + 1] = x end
		for _, x in ipairs(R2.objs) do objs[#objs + 1] = x end
		local g = nil
		L.timeline(2.8, function(t, once)
			if held and once("late", 0.2) then hide(true) end
			if once("strike", 0.2) then ray(hp + Vector3.new(0, 55, 0), hp, 0.7 * s, 0.35) hitGround(o, s, false) end
			if t > 0.2 then
				local on = c01((t - 0.2) / 0.1) * (1 - c01((t - 2.2) / 0.4))
				R1.set(CFrame.new(hp) * CFrame.Angles(0, t * 2, 0), 1.2 * s, 1 - 0.95 * on)
				R2.set(CFrame.new(hp - Vector3.new(0, 0.03, 0)) * CFrame.Angles(0, -t * 1.2, 0), 1.55 * s, 1 - 0.6 * on)
				if math.random() < 0.15 then
					local a = rnd(0, 6.3)
					local q = hp + Vector3.new(math.cos(a), 0, math.sin(a)) * 1.2 * s
					arc(q, q + Vector3.new(0, -rnd(0.5, 1.2), 0) * s, 0.05, 0.08)
				end
			end
			if once("ghost", 0.5) then g = bodyGhost(WB, 1.6) end
			if g then
				local k = c01((t - 0.5) / 1.1)
				for _, gp in ipairs(g) do gp.p.Transparency = 1 - 0.7 * k * (0.9 + 0.1 * math.sin(t * 30)) end
			end
			if once("show", 1.6) then hide(false) L.groundWave(o, "ring_c.png", C1, 1, 6 * s, 0.4, 2.2) end
		end, objs, function() hide(false) end)
	end


	local function shortOrbital()
		local o, s = L.ground(ch.feet, 3, 8), sc()
		hide(true)
		local rot = rnd(0, TAU)
		local pts, glows = {}, {}
		for i = 1, 6 do
			pts[i] = L.ground(hexPt(o, 5.5 * s, rot, i), 3, 8)
			glows[i] = L.part({ Shape = BALL, Material = NEON, Color = WB, Transparency = 1, Size = Vector3.one * 0.5 * s, CFrame = CFrame.new(pts[i] + Vector3.new(0, 0.2, 0)) })
		end
		L.timeline(2.4, function(t, once)
			if held and once("late", 0.2) then hide(true) end
			for i = 1, 6 do
				local ti = 0.1 + (i - 1) * 0.09
				if once("s" .. i, ti) then
					ray(pts[i] + Vector3.new(rnd(-1, 1), 45, rnd(-1, 1)), pts[i], 0.35 * s, 0.25)
					hitGround(pts[i], s * 0.8, false)
				end
				glows[i].Transparency = t < ti and 1 or (0.1 + 0.9 * c01((t - 1.05) / 0.15)) * (math.random() < 0.15 and 0.5 or 1)
			end
			if t > 0.75 and t < 1.05 then
				for i = 1, 6 do if math.random() < 0.35 then arc(pts[i] + Vector3.new(0, 0.3, 0), o + Vector3.new(0, 1 * s, 0), 0.07, 0.07) end end
			end
			if once("show", 1.05) then
				ray(o + Vector3.new(0, 80, 0), o, 1.2 * s, 0.45)
				hitGround(o, s, true)
				L.groundWave(o, "ring_c.png", W, 6 * s, 1 * s, 0.3, 2.4)
				hide(false)
				fadeGhost(bodyGhost(WB, 0.7), 0.7)
				haloSnap(s)
			end
		end, glows, function() hide(false) end)
	end
	local shorts = { shortSingle, shortTriple, shortHalo, shortOrbital }








	local function arriveFull()
		local o, s = L.ground(ch.feet, 3, 8), sc()
		hide(true)
		local DUR = 10.5
		local S = L.screen(DUR)
		S.style, S.c1, S.c2 = "radius", C1, C2
		S.boxFn = function(t) return c01((t - 3.8) / 0.4) * (1 - c01((t - 8.6) / 0.6)) end
		S.tintFn = function(t) return WB, 0.09 * c01(t / 1.5) * (1 - c01((t - 8.8) / 1.4)) end

		local sky = L.worldSky(o, DUR, { dome = Color3.fromRGB(150, 192, 240), atmC = Color3.fromRGB(205, 228, 255), decay = Color3.fromRGB(150, 195, 250),
			den = 0.3, haze = 0.9, glare = 0.25, oa = Color3.fromRGB(190, 215, 255), am = Color3.fromRGB(150, 180, 230), domeA = 0.45 })
		local objs = {}
		local function keep(x) objs[#objs + 1] = x return x end
		local function keepAll(list) for _, x in ipairs(list) do objs[#objs + 1] = x end end
		local rot = rnd(0, TAU)
		local HR = 6 * s
		local dp = keep(L.mesh("disc.mesh", "darkdisc.png", L.BACK, 1, Vector3.new(15 * s, 1, 15 * s)))
		dp.CFrame = CFrame.new(o + Vector3.new(0, 0.04, 0))
		dp.Transparency = 1

		local orbR, tops, hexL, corners = {}, {}, {}, {}
		for i = 1, 6 do
			orbR[i] = beamRing(12, 0.06 * s, WB, 8, C1)
			keepAll(orbR[i].objs)
			tops[i] = keep(L.part({ Shape = BALL, Material = NEON, Color = W, Transparency = 1, Size = Vector3.one * 0.7 * s }))
			hexL[i] = keep(flat(WB))
			corners[i] = L.ground(hexPt(o, HR, rot, i), 3, 8)
		end
		local chP = keep(L.part({ Size = Vector3.new(HR * 1.6, 0.2, HR * 1.6), CFrame = CFrame.new(o + Vector3.new(0, 0.2, 0)) }))
		local chSp = L.pe(chP, { Texture = L.T("spark.png"), Shape = Enum.ParticleEmitterShape.Box, EmissionDirection = Enum.NormalId.Top, Lifetime = NR(0.1, 0.3),
			Speed = NR(2, 6), Size = NS({ K(0, 0.14), K(1, 0) }), Color = CS(WB, C1), Brightness = 7, Orientation = Enum.ParticleOrientation.VelocityParallel })
		local lp = keep(L.part({ CFrame = CFrame.new(o + Vector3.new(0, 2, 0)) }))
		local lt = L.new("PointLight", { Color = C1, Range = 22 * s, Brightness = 0, Shadows = false }, lp)

		local AY, AR = 28, 48
		local ac = o + Vector3.new(0, AY, 0)
		local arr = beamRing(48, 0.5, C1:Lerp(WB, 0.25), 9, C2)
		local arr2 = beamRing(48, 0.25, C2, 7, C2)
		keepAll(arr.objs) keepAll(arr2.objs)
		local an = {}
		for i = 1, 6 do an[i] = keep(L.part({ Shape = BALL, Material = NEON, Color = C1:Lerp(W, 0.35), Transparency = 1, Size = Vector3.one * 2.4 })) end
		local function nodePos(i, t) local a = rot + (i - 1) / 6 * TAU + t * 0.25 return ac + Vector3.new(math.cos(a) * AR, 0, math.sin(a) * AR) end

		local fr = {}
		for i = 1, 6 do
			local a0, a1 = keep(L.att(ac)), keep(L.att(o))
			fr[i] = { a0 = a0, a1 = a1,
				c = keep(L.beam(a0, a1, { Width0 = 0, Width1 = 0, Brightness = 9, FaceCamera = true, Color = CS(W, WB), Transparency = NS(0) })),
				g = keep(L.beam(a0, a1, { Texture = L.T("softbeam.png") or "", Width0 = 0, Width1 = 0, Brightness = 2.5, FaceCamera = true, Color = CS(C1), Transparency = NS(0.3) })) }
		end

		local pa0, pa1 = keep(L.att(ac)), keep(L.att(o))
		local pCore = keep(L.beam(pa0, pa1, { Width0 = 0, Width1 = 0, Brightness = 10, FaceCamera = true, Color = CS(W, WB), Transparency = NS(0) }))
		local pSoft = keep(L.beam(pa0, pa1, { Texture = L.T("softbeam.png") or "", Width0 = 0, Width1 = 0, Brightness = 3, FaceCamera = true, Color = CS(C1, C2), Transparency = NS(0.25) }))

		local RR = { 4, 7.5, 11, 14.5 }
		local rings = {}
		for i = 1, #RR do
			rings[i] = beamRing(i == 3 and 44 or 36, (i == 3 and 0.16 or 0.1) * s, i % 2 == 1 and WB or C1, 7, C1)
			keepAll(rings[i].objs)
		end

		local swA, swB = keep(L.att(o)), keep(L.att(o))
		local swC = keep(L.beam(swA, swB, { Width0 = 0, Width1 = 0, Brightness = 9, FaceCamera = true, Color = CS(W, WB), Transparency = NS(0) }))
		local swS = keep(L.beam(swA, swB, { Texture = L.T("softbeam.png") or "", Width0 = 0, Width1 = 0, Brightness = 3, FaceCamera = true, Color = CS(C1), Transparency = NS(0.3) }))
		local NBURN = 40
		local burn = {}
		for i = 1, NBURN do burn[i] = keep(flat(WB)) end
		local sweep0 = rnd(0, TAU)

		local CR = 3.6 * s
		local cells = {}
		local QN = math.ceil(42 / (CR * 1.5))
		for q = -QN * 2, QN * 2 do
			for r = -QN, QN do
				local x, z = CR * math.sqrt(3) * (q + r / 2), CR * 1.5 * r
				local d = math.sqrt(x * x + z * z)
				if d < 42 and d > HR * 0.6 then cells[#cells + 1] = { c = o + Vector3.new(x, 0.06, z), d = d } end
			end
		end
		table.sort(cells, function(a, b) return a.d < b.d end)
		local cellI = 1
		local TS = game:GetService("TweenService")
		local cellTI = TweenInfo.new(1.3, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
		local function lightCell(cl)
			for e = 0, 2 do
				local a0, a1 = math.rad(30 + 60 * e), math.rad(30 + 60 * (e + 1))
				local p = keep(flat(W))
				setFlat(p, cl.c + Vector3.new(math.cos(a0), 0, math.sin(a0)) * CR, cl.c + Vector3.new(math.cos(a1), 0, math.sin(a1)) * CR, 0.12 * s)
				p.Transparency = 0.05
				TS:Create(p, cellTI, { Transparency = 1, Color = C2 }):Play()
			end
		end

		local trkAcc = 0
		local function chamberTrack(t)
			local a, d = rnd(0, TAU), rnd(4, 30) * s
			local c = o + Vector3.new(math.cos(a) * d, rnd(0.5, 12) * s, math.sin(a) * d)
			local dir
			if t > 3.6 and t < 4.6 then dir = (o + Vector3.new(0, 1.5 * s, 0) - c).Unit
			else
				dir = Vector3.new(rnd(-1, 1), rnd(-0.6, 0.6), rnd(-1, 1))
				dir = dir.Magnitude > 0.05 and dir.Unit or Vector3.xAxis
			end
			local len = (math.random() < 0.3 and rnd(1, 2.4) or rnd(4, 11)) * s
			local w = (len < 3 * s and 0.14 or 0.05) * s
			local a0, a1 = L.att(c - dir * len / 2), L.att(c + dir * len / 2)
			local b = L.beam(a0, a1, { Texture = L.T("softbeam.png") or "", Width0 = w, Width1 = w, Brightness = 5, FaceCamera = true, Color = CS(W, C1), Transparency = NS(0.05) })
			L.fx(rnd(0.6, 1), function(k)
				local ww = w * (1 + 2.5 * k)
				b.Width0, b.Width1 = ww, ww
				b.Transparency = NS(0.05 + 0.95 * k ^ 0.7)
			end, { a0, a1, b })
		end

		local scanP = keep(L.part({ Shape = Enum.PartType.Cylinder, Material = NEON, Color = WB, Transparency = 1, Size = Vector3.new(0.06, 4.2 * s, 4.2 * s) }))
		local scanR = beamRing(24, 0.1 * s, W, 9, C1)
		keepAll(scanR.objs)
		local reveal = nil
		local g, parts = nil, {}
		local arcT, crawlT = 0, 0
		L.timeline(DUR, function(t, once)
			local dt = L.lastDt or 0.016
			if held and once("late", 0.3) then hide(true) end
			sky.set(c01(t / 1.5) * (1 - c01((t - 8.8) / 1.5)))

			local rate = 0
			if t > 0.2 and t < 4.6 then rate = 6 + 50 * c01((t - 0.2) / 4) elseif t > 7.2 and t < 10 then rate = 12 * (1 - c01((t - 7.2) / 2.8)) end
			trkAcc += rate * dt
			while trkAcc >= 1 do trkAcc -= 1 chamberTrack(t) end

			local sink = L.inQuad(c01((t - 8.6) / 0.8))
			for i = 1, 6 do
				local k0 = L.outBack(c01((t - 0.5 - (i - 1) * 0.16) / 0.4)) * (1 - sink)
				local c = corners[i]
				if k0 > 0.02 then
					local op = c + Vector3.new(0, (0.6 + 1.4 * k0) * s + 0.15 * s * math.sin(t * 3 + i), 0)
					tops[i].CFrame = CFrame.new(op)
					tops[i].Size = Vector3.one * 0.7 * s * k0 * (1 + 0.25 * c01((t - 3) / 1.5))
					tops[i].Transparency = (math.random() < 0.12) and 0.5 or 0.05
					orbR[i].set(CFrame.new(op) * CFrame.Angles(0.5 + i, t * 3, 0.3), 0.75 * s * k0, 0.1)
				else
					tops[i].Transparency = 1
					orbR[i].set(CFrame.new(c), 0.1, 1)
				end
				local k = c01((t - 1.6 - (i - 1) * 0.13) / 0.13)
				local a, b = c + Vector3.new(0, 0.08, 0), corners[i % 6 + 1] + Vector3.new(0, 0.08, 0)
				if k > 0 and setFlat(hexL[i], a, a:Lerp(b, k), 0.2 * s) then
					hexL[i].Transparency = 0.05 + 0.95 * c01((t - 8.4) / 1.4)
					hexL[i].Color = WB:Lerp(C2, c01((t - 5.5) / 2.5))
				end
			end
			arcT -= dt
			if t > 1.5 and t < 8.6 and arcT <= 0 then
				arcT = t < 4.5 and 0.05 or 0.12
				local i = math.random(1, 6)
				arc(tops[i].Position, tops[i % 6 + 1].Position, 0.08, 0.08)
				if t < 4.5 and math.random() < 0.4 then arc(tops[i].Position, o + Vector3.new(0, 0.3, 0), 0.06, 0.08) end
			end
			local charge = c01(t / 4.4)
			chSp.Rate = t < 4.5 and 10 + 110 * charge or 0
			dp.Transparency = 1 - 0.55 * c01(t / 2) * (1 - c01((t - 9.2) / 0.8))
			if t < 4.5 then lt.Brightness = 3 * charge * ((math.random() < 0.2) and 0.4 or 1) end

			local ak = L.outBack(c01((t - 1) / 0.9))
			local aOut = c01((t - 7.2) / 1)
			local spinA = t * (0.25 + 1.2 * c01((t - 2.6) / 1.8))
			if ak > 0.01 then
				arr.set(CFrame.new(ac) * CFrame.Angles(0, spinA, 0), AR * ak, 0.05 + 0.95 * aOut)
				arr2.set(CFrame.new(ac + Vector3.new(0, -0.6, 0)) * CFrame.Angles(0, -spinA * 0.7, 0), AR * 1.12 * ak, 0.3 + 0.7 * aOut)
				arr.width(0.5 + 0.6 * c01((t - 2.6) / 1.8))
			end
			for i = 1, 6 do
				local nk = c01((t - 1.7 - (i - 1) * 0.12) / 0.2)
				an[i].CFrame = CFrame.new(nodePos(i, spinA * 4 / 4))
				an[i].Size = Vector3.one * (2.4 + 1.6 * c01((t - 2.6) / 1.8)) * (1 + 0.15 * math.sin(t * 30 + i))
				an[i].Transparency = nk > 0 and (0.05 + 0.95 * aOut) or 1
			end
			if t > 2.4 and t < 4.5 and math.random() < 0.5 then
				local i = math.random(1, 6)
				L.bolt(nodePos(i, spinA), nodePos(i % 6 + 1, spinA), { col = WB, w = 0.35, segs = 6, jit = 4, life = 0.08, bright = 8 })
			end

			local cw, sw = 0, 0
			if t >= 3.6 and t < 4.1 then cw, sw = 0.1 * s, 0.6 * s
			elseif t >= 4.1 and t < 4.55 then cw, sw = 0.35 * s, 2 * s
			elseif t >= 4.55 and t < 7 then
				local pulse = 1 + 0.12 * math.sin(t * 40) + 0.1 * math.sin(t * 13)
				cw, sw = 1.1 * s * pulse, 6 * s * pulse
			elseif t >= 7 and t < 7.15 then
				local k = 1 - (t - 7) / 0.15
				cw, sw = 1.1 * s * k, 6 * s * k
			end
			pCore.Width0, pCore.Width1, pSoft.Width0, pSoft.Width1 = cw, cw, sw, sw
			if once("aim", 3.6) then L.groundWave(o, "ring_c.png", WB, 0.5 * s, 5 * s, 0.4, 2.4) end
			if once("med", 4.1) then hitGround(o, s, false) S:shake(1.5, 0.3) end

			local fk = c01((t - 4.2) / 0.3) * (1 - c01((t - 4.6) / 0.4))
			for i = 1, 6 do
				local f = fr[i]
				f.a0.WorldPosition = nodePos(i, spinA)
				f.a1.WorldPosition = o + Vector3.new(0, 0.5, 0)
				f.c.Width0, f.c.Width1 = 0.5 * fk, 0.25 * fk * s
				f.g.Width0, f.g.Width1 = 3 * fk, 1.5 * fk * s
			end

			if once("freeze", 4.5) then L.hitStop(0.3) end
			if once("strike", 4.55) then
				ray(ac, o, 2.2 * s, 0.6)
				S:flash(W, 0.9)
				S:shake(5, 0.7)
				hitGround(o, s, true)
				L.groundWave(o, "ring_c.png", W, 2, 34 * s, 0.8, 2.4)
				lt.Brightness = 9
				parts = bodyList()
				reveal = {}
				for _, d in ipairs(parts) do reveal[#reveal + 1] = { d = d, y = d.Position.Y - d.Size.Y * 0.5 } end
				g = bodyGhost(WB, 3.4)
				if g then for _, gp in ipairs(g) do gp.p.Transparency = 1 end end
			end
			if t > 4.55 then lt.Brightness = math.max(t < 7 and 4 + 1.5 * math.sin(t * 30) or 0, 9 * (1 - c01((t - 4.55) / 0.5)), t > 7 and 9 * (1 - c01((t - 7) / 0.6)) or 0) end

			if t > 4.55 then
				local rw = 42 * L.outQuad(c01((t - 4.55) / 1.35))
				local n = 0
				while cellI <= #cells and cells[cellI].d <= rw and n < 30 do lightCell(cells[cellI]) cellI += 1 n += 1 end
			end

			for i, R in ipairs(rings) do
				local k = L.outBack(c01((t - 4.55 - (i - 1) * 0.09) / 0.32))
				local fade = c01((t - 8 - (i - 1) * 0.1) / 0.9)
				local on = k > 0.01 and not (i == 3 and t > 6.6)
				R.set(CFrame.new(o + Vector3.new(0, 0.12, 0)) * CFrame.Angles(0, t * (i % 2 == 0 and -0.15 or 0.15), 0), math.max(RR[i] * s * k, 0.1), on and (0.08 + 0.92 * fade) or 1)
			end

			if reveal and t < 6.2 then
				local feetY, headY = o.Y, haloHeight().Y - 1 * s
				local sk = L.inOutQuad and L.inOutQuad(c01((t - 4.7) / 1.2)) or c01((t - 4.7) / 1.2)
				local y = feetY + (headY - feetY) * sk
				local on = t > 4.7 and t < 6
				scanP.CFrame = CFrame.new(o.X, y, o.Z) * CFrame.Angles(0, 0, math.pi / 2)
				scanP.Transparency = on and 0.35 or 1
				scanR.set(CFrame.new(o.X, y, o.Z) * CFrame.Angles(0, t * 4, 0), 2.1 * s, on and 0.05 or 1)
				for _, rv in ipairs(reveal) do
					if not rv.done and t > 4.7 and y >= rv.y then
						rv.done = true
						if held and held[rv.d] then held[rv.d] = nil if rv.d.Parent then rv.d.LocalTransparencyModifier = 0 end end
					end
				end
				if g then
					for _, gp in ipairs(g) do
						local by = gp.p.Position.Y - gp.p.Size.Y * 0.5
						gp.p.Transparency = (t > 4.7 and y >= by) and ((math.random() < 0.3) and 0.3 or 0.65) or 1
					end
				end
			end
			if once("shown", 6) then hide(false) end

			if g and t > 6 and t < 7 then
				for _, gp in ipairs(g) do gp.p.Transparency = (math.random() < 0.3) and 0.35 or 0.75 end
			end
			if t > 5 and t < 7 then
				crawlT -= dt
				if crawlT <= 0 and #parts > 1 then
					crawlT = 0.035
					local a, b = parts[math.random(1, #parts)], parts[math.random(1, #parts)]
					if a ~= b and a.Parent and b.Parent then arc(a.Position, b.Position, 0.06, 0.06) end
				end
			end

			local swk = c01((t - 5.3) / 1.3)
			if t >= 5.3 and t < 6.6 then
				local a = sweep0 + swk * TAU
				local q = o + Vector3.new(math.cos(a), 0, math.sin(a)) * RR[3] * s
				swA.WorldPosition = ac + (q - o) * 0.3
				swB.WorldPosition = q
				swC.Width0, swC.Width1, swS.Width0, swS.Width1 = 0.3, 0.45 * s, 1.6, 2.4 * s
				gP.CFrame = CFrame.new(q + Vector3.new(0, 0.15, 0))
				gSp:Emit(2)
			else swC.Width0, swC.Width1, swS.Width0, swS.Width1 = 0, 0, 0, 0 end
			for i = 1, NBURN do
				local u0 = (i - 1) / NBURN
				if swk > u0 and t > 5.3 then
					local a0, a1 = sweep0 + u0 * TAU, sweep0 + i / NBURN * TAU
					local ag = c01(t - (5.3 + u0 * 1.3))
					local p0 = o + Vector3.new(math.cos(a0) * RR[3] * s, 0.1, math.sin(a0) * RR[3] * s)
					local p1 = o + Vector3.new(math.cos(a1) * RR[3] * s, 0.1, math.sin(a1) * RR[3] * s)
					if setFlat(burn[i], p0, p0:Lerp(p1, c01((swk - u0) * NBURN) * 1.05), (0.35 - 0.15 * ag) * s) then
						burn[i].Color = W:Lerp(WB, ag):Lerp(C2, c01((t - 7) / 1.5))
						burn[i].Transparency = 0.02 + 0.98 * c01((t - 8.2) / 1.4)
					end
				end
			end

			if once("cut", 7) then
				S:flash(W, 0.7)
				S:shake(2.5, 0.35)
				L.groundWave(o, "ring_c.png", W, 2, 160, 1.6, 2.6)
				L.groundWave(o, "ring_c.png", C1, 2, 90, 1.3, 2.4)
				gP.CFrame = CFrame.new(o + Vector3.new(0, 0.3, 0))
				gSp:Emit(40)
				if g then fadeGhost(g, 0.35, 0.05) end
				haloSnap(s)
			end
			if once("card", 7.2) then S:title(L.name(), C1, C2) end
		end, objs, function() hide(false) sky.release() end)
	end




	local function death(preview)
		if not ch.char then return end
		local s = sc()
		local pos = L.ground(ch.feet or ch.pos, 3, 8)
		local parts = bodyList()
		local g = bodyGhost(WB, 1.2)
		local gone, arcT = {}, 0
		deathGone = gone
		dying = true
		local hp0 = haloHeight()
		local HRd = haloR and 1.2 * s or 1.2
		local fall = beamRing(20, 0.07 * s, WB, 8, C1)
		local gy = pos.Y + 0.1
		local tl = math.sqrt(math.max(2 * (hp0.Y - gy) / 60, 0.01))
		local spin = 0
		L.timeline(2.6, function(t, once)
			local dt = L.lastDt or 0.016

			local k = c01(t / 1)
			if g and t < 1 then
				for _, gp in ipairs(g) do gp.p.Transparency = 0.85 - 0.8 * k * ((math.random() < 0.3) and 0.6 or 1) end
			end
			arcT -= dt
			if t < 1 and arcT <= 0 and #parts > 1 then
				arcT = 0.09 - 0.07 * k
				local a = parts[math.random(1, #parts)]
				if a.Parent then
					if math.random() < 0.5 then
						local b = parts[math.random(1, #parts)]
						if b.Parent and b ~= a then arc(a.Position, b.Position, 0.07, 0.07) end
					else
						local an, d = rnd(0, TAU), rnd(1, 3) * s
						arc(a.Position, L.ground(pos + Vector3.new(math.cos(an) * d, 0, math.sin(an) * d), 3, 6), 0.08, 0.08)
					end
				end
			end
			flashL.Range = 14 * s
			if t < 1 then gP.CFrame = CFrame.new(pos + Vector3.new(0, 1.5 * s, 0)) flashL.Brightness = 1 + 4 * k end

			if once("burst", 1) then
				for _, d in ipairs(parts) do if d.Parent then gone[d] = true d.LocalTransparencyModifier = 1 end end
				for d in pairs(L.bodyParts()) do if not gone[d] then gone[d] = true d.LocalTransparencyModifier = 1 end end
				local c = pos + Vector3.new(0, 1.5 * s, 0)
				for i = 1, 12 do
					local an, d = i / 12 * TAU + rnd(-0.2, 0.2), rnd(4, 7) * s
					L.bolt(c, L.ground(pos + Vector3.new(math.cos(an) * d, 0, math.sin(an) * d), 3, 6), { col = WB, w = 0.1, segs = 6, jit = d * 0.2, life = 0.3, bright = 8 })
				end
				ray(c, c + Vector3.new(0, 90, 0), 0.9 * s, 0.5)
				hitGround(pos, s, true)
				gSp:Emit(30)
				if g then fadeGhost(g, 0.25, 0) end
			end

			local cf
			if t < 1 then
				cf = CFrame.new(hp0) * CFrame.Angles(0, t * 3, 0)
			else
				local u = t - 1
				if u < tl then
					spin += dt * 4
					cf = CFrame.new(hp0.X, hp0.Y - 30 * u * u, hp0.Z) * CFrame.Angles(spin * 0.6, 0, spin * 0.35)
				else
					if once("clatter", 1 + tl) then
						gP.CFrame = CFrame.new(Vector3.new(hp0.X, gy, hp0.Z))
						gSp:Emit(14)
						L.groundWave(Vector3.new(hp0.X, gy, hp0.Z), "ring_c.png", WB, 1 * s, 4 * s, 0.3, 2.4)
					end
					local v = u - tl
					local wob = 0.5 * math.exp(-v * 4) * math.sin(v * 22)
					cf = CFrame.new(hp0.X, gy + 0.3 * s * math.abs(math.sin(v * 12)) * math.exp(-v * 6), hp0.Z) * CFrame.Angles(wob, 0, wob * 0.6)
				end
			end
			fall.set(cf, HRd, 0.05 + 0.95 * c01((t - 2) / 0.6))
		end, fall.objs, function()
			deathGone = nil
			dying = false
			if preview then for d in pairs(gone) do if d.Parent then pcall(function() d.LocalTransparencyModifier = 0 end) end end end
		end)

		local sp = L.mesh("disc.mesh", "darkdisc.png", L.BACK, 1, Vector3.new(7 * s, 1, 7 * s))
		sp.CFrame = CFrame.new(pos + Vector3.new(0, 0.04, 0))
		local rot = rnd(0, TAU)
		local lines = {}
		for i = 1, 6 do
			local a, b = hexPt(pos, 2.6 * s, rot, i) + Vector3.new(0, 0.08, 0), hexPt(pos, 2.6 * s, rot, i % 6 + 1) + Vector3.new(0, 0.08, 0)
			lines[#lines + 1] = { p = flat(WB), a = a, b = b, w = 0.18 * s }
			lines[#lines + 1] = { p = flat(C1), a = pos + Vector3.new(0, 0.07, 0), b = a, w = 0.08 * s }
		end
		local lobj = { sp }
		for _, ln in ipairs(lines) do lobj[#lobj + 1] = ln.p end
		local spk = 0
		L.fx(7, function(k, tt)
			sp.Transparency = 0.25 + 0.75 * c01((k - 0.6) / 0.4)
			for i, ln in ipairs(lines) do
				local dk = L.outQuad(c01((tt - 1 - i * 0.03) / 0.2))
				if dk > 0 and setFlat(ln.p, ln.a, ln.a:Lerp(ln.b, dk), ln.w * (1 - 0.4 * k)) then
					ln.p.Color = W:Lerp(WB, c01((tt - 1) / 0.5)):Lerp(C2, c01((tt - 2) / 3))
					ln.p.Transparency = 0.05 + 0.95 * c01((k - 0.55) / 0.45)
				end
			end
			spk -= L.lastDt or 0.016
			if spk <= 0 and tt > 1 and k < 0.85 then
				spk = rnd(0.12, 0.4) + k * 0.5
				local i = math.random(1, 6)
				local a, b = hexPt(pos, 2.6 * s, rot, i), hexPt(pos, 2.6 * s, rot, i % 6 + 1)
				local q = a:Lerp(b, rnd(0, 1)) + Vector3.new(0, 0.1, 0)
				arc(q, q + Vector3.new(rnd(-0.8, 0.8), rnd(0.2, 0.7), rnd(-0.8, 0.8)) * s, 0.05, 0.07)
			end
		end, lobj)
	end


	local age, boltT, crackT, flare = 0, rnd(1.5, 3), 0.3, 0
	local lastFoot, aiT = nil, 0



	local RX = { pr = {}, pi = 0, d = 0, side = 1, still = 0, chg = 0, beat = 0, arcT = 0 }
	for i = 1, 6 do
		local P = { seg = {}, t = 99 }
		for q = 1, 6 do P.seg[q] = flat(WB) end
		RX.pr[i] = P
	end
	function RX.hex(gp, r, th)
		RX.pi = RX.pi % #RX.pr + 1
		local P = RX.pr[RX.pi]
		local rot = math.random() * TAU
		for q = 1, 6 do setFlat(P.seg[q], hexPt(gp, r, rot, q), hexPt(gp, r, rot, q % 6 + 1), th) end
		P.t = 0
	end
	local function step(dt)
		age += dt
		local s, iw, on, swim, sit, dead = sc(), ch.iw, ch.on, ch.swim == true, ch.sit == true, ch.dead == true
		local off = dead or dying

		flare = math.max(0, flare - dt * 3)
		local hp = haloHeight() + Vector3.new(0, 0.06 * math.sin(age * 1.7), 0)
		local hr = (1.2 + 0.3 * flare) * s
		local hcf = CFrame.new(hp) * CFrame.Angles(0, age * 0.8, 0)
		haloR.set(hcf, hr, off and 1 or 0.05)
		haloR.width((0.07 + 0.05 * flare) * s)
		for i, nd in ipairs(nodes) do
			local a = age * 2.2 + i * TAU / 3
			nd.CFrame = CFrame.new(hp + Vector3.new(math.cos(a) * hr, 0.02, math.sin(a) * hr))
			nd.Transparency = off and 1 or 0.05
		end
		haloP.CFrame = CFrame.new(hp)
		haloL.Brightness = off and 0 or (0.8 + 2 * flare) * (swim and 0.6 or 1)
		haloSp.Rate = (off or swim) and 0 or 6

		trkT -= dt * ((swim or sit) and 0.5 or 1)
		if trkT <= 0 and not off then
			trkT = rnd(0.12, 0.45)
			track(s)
		end
		for _, T in ipairs(trk) do
			if T.t < T.life + 0.1 then
				T.t += dt
				local k = c01(T.t / T.life)
				local on = c01(T.t / 0.05)

				local w = math.floor(T.w * (1 + 2.5 * k) * 100 + 0.5) / 100
				local tr = math.floor((1 - on * (1 - k) ^ 1.5 * 0.95) * 50 + 0.5) / 50
				if w ~= T.lw or tr ~= T.ltr then
					T.lw, T.ltr = w, tr
					local ns = NS(tr)
					for j = 1, 3 do

						local b = T.b[j]
						b.Width0, b.Width1 = w, w
						b.Transparency = ns
					end
				end
			end
		end

		L.motion(dt, s, off)
		if (ch.sBeat or 0) ~= RX.beat then
			RX.beat = ch.sBeat or 0
			if not off then flare = math.max(flare, 0.7) RX.hex(L.ground(ch.feet, 2, 4) + Vector3.new(0, 0.1, 0), 1.4 * s, 0.12 * s) end
		end
		RX.still = (on or off or swim or ch.air) and 0 or RX.still + dt
		local chW = RX.still > 3 and not sit
		if on and RX.chg > 0.6 and not off then
			local gp = L.ground(ch.feet, 2, 6)
			for i = 1, 8 do
				local a = i / 8 * TAU
				ray(ch.feet + Vector3.new(0, 0.1, 0), gp + Vector3.new(math.cos(a), 0, math.sin(a)) * 3.4 * s, 0.1 * s, 0.22)
			end
			hitGround(gp, s * 0.8, false)
			flare = 1
			RX.chg = 0
		end
		RX.chg += ((chW and 1 or 0) - RX.chg) * c01(dt * (chW and 0.8 or 4))
		if RX.chg > 0.3 and not off then
			RX.arcT -= dt
			if RX.arcT <= 0 then
				RX.arcT = rnd(0.25, 0.5) / RX.chg
				local a = nodes[math.random(1, #nodes)].Position
				local b = nodes[math.random(1, #nodes)].Position
				if (a - b).Magnitude > 0.2 then arc(a, b, 0.03, 0.12) end
			end
		end
		local nz = (0.18 + 0.14 * RX.chg) * s
		for _, nd in ipairs(nodes) do if math.abs(nd.Size.X - nz) > 0.01 then nd.Size = Vector3.one * nz end end
		if on and not off and not swim and not ch.air and ch.feet then
			if RX.lp then RX.d += ((ch.pos - RX.lp) * Vector3.new(1, 0, 1)).Magnitude end
			if RX.d > 2.2 * s then
				RX.d, RX.side = 0, -RX.side
				local dir = ch.vel.Magnitude > 0.1 and ch.vel.Unit or Vector3.zAxis
				RX.hex(L.ground(ch.feet + dir:Cross(Vector3.yAxis) * RX.side * 0.4 * s, 2, 4) + Vector3.new(0, 0.08, 0), 0.42 * s, 0.07 * s)
			end
		end
		RX.lp = ch.pos
		for _, P in ipairs(RX.pr) do
			if P.t < 1.2 then
				P.t += dt
				local k = c01(P.t / 1.2)
				for _, sg in ipairs(P.seg) do sg.Transparency = off and 1 or 0.05 + 0.95 * k sg.Color = W:Lerp(C1, c01(k * 2)) end
			elseif P.t < 98 then P.t = 99 for _, sg in ipairs(P.seg) do sg.Transparency = 1 end end
		end

		if on and not off and not swim and ch.feet then
			local fp = ch.feet + Vector3.new(0, 0.15 * s, 0)
			if not lastFoot or (fp - lastFoot).Magnitude > 4 * s then lastFoot = fp end
			if (fp - lastFoot).Magnitude > 0.9 * s then
				arc(lastFoot, fp, 0.06, 0.2)
				if math.random() < 0.35 then arc(fp, fp + Vector3.new(rnd(-0.7, 0.7), rnd(0, 0.4), rnd(-0.7, 0.7)) * s, 0.04, 0.08) end
				lastFoot = fp
			end
			aiT -= dt
			if (ch.spd or 0) > 20 and aiT <= 0 then
				aiT = 0.11
				fadeGhost(bodyGhost(C1:Lerp(WB, 0.4), 0.4), 0.4, 0.55)
			end
		else lastFoot = nil end

		if ch.jumped and not off then
			flare = 1
			local gp = L.ground(ch.feet, 2, 8)
			ray(ch.feet, gp - Vector3.new(0, 0.2, 0), 0.3 * s, 0.22)
			for i = 1, 6 do
				local a = i / 6 * TAU + rnd(-0.2, 0.2)
				ray(ch.feet + Vector3.new(0, 0.1, 0), gp + Vector3.new(math.cos(a), 0, math.sin(a)) * 2.4 * s, 0.1 * s, 0.18)
			end
			hitGround(gp, s * 0.7, false)
		end
		if ch.landed and not off then
			local gp = L.ground(ch.feet, 2, 4) + Vector3.new(0, 0.1, 0)
			local rot0 = rnd(0, TAU)
			local hx = {}
			for i = 1, 6 do hx[i] = flat(WB) end
			L.fx(0.45, function(k)
				local r = (1.6 + 1.2 * L.outQuad(k)) * s
				for i = 1, 6 do
					setFlat(hx[i], hexPt(gp, r, rot0, i), hexPt(gp, r, rot0, i % 6 + 1), 0.16 * s * (1 - 0.5 * k))
					hx[i].Transparency = 0.05 + 0.95 * k
					hx[i].Color = W:Lerp(C1, k)
				end
			end, hx)
			gP.CFrame = CFrame.new(gp)
			gSp:Emit(10)
		end

		if not swim and not off and iw > 0.3 then
			boltT -= dt * (sit and 0.5 or 1)
			if boltT <= 0 then
				boltT = rnd(1.5, 3)
				local a = rnd(0, TAU)
				local gp = L.ground(ch.feet + Vector3.new(math.cos(a), 0, math.sin(a)) * rnd(3, 8) * s, 6, 12)
				ray(gp + Vector3.new(rnd(-1, 1), rnd(14, 18), rnd(-1, 1)) * s, gp, 0.22 * s, 0.2)
				hitGround(gp, s, false)
			end
		end
		flashL.Brightness = math.max(0, flashL.Brightness - dt * 18)
		tag.step(dt)
	end

	return {
		arrive = function(short) if short then shorts[math.random(1, #shorts)]() else arriveFull() end end,
		short = function(n) n = math.floor(tonumber(n) or 1) shorts[(n - 1) % #shorts + 1]() end,
		step = step, rebind = rebind, death = death,
		hidden = function() return held or deathGone end,
		rig = function() return rig end,
		stop = function() hide(false) end,
	}
end
end
end)()
end
