    ["engine/themes/bigspender"] = [====[return function(P)
local _rawPcall, _rcPcallSink, _rcPcallRet, pcall, PS, RS, HS, DB, UIS, TS, MPS, MS, _RC_VER, _RC_VER_DATE = P._rawPcall, P._rcPcallSink, P._rcPcallRet, P.pcall, P.PS, P.RS, P.HS, P.DB, P.UIS, P.TS, P.MPS, P.MS, P._RC_VER, P._RC_VER_DATE
return (function()


return function(R, I)
local System = I.System












System.StaffThemes.TAGS.bigspender = function(K, head, C1, C2)
	local W = Color3.new(1, 1, 1)
	local BLK, BLK2 = Color3.fromRGB(14, 14, 16), Color3.fromRGB(34, 34, 38)
	local GOLD2 = Color3.fromRGB(176, 120, 30)
	local RED = Color3.fromRGB(225, 40, 50)
	local CS, CK, NS, NK = ColorSequence.new, ColorSequenceKeypoint.new, NumberSequence.new, NumberSequenceKeypoint.new
	local function c01(x) return math.clamp(x, 0, 1) end
	local FONT = Font.new("rbxasset://fonts/families/Montserrat.json", Enum.FontWeight.Heavy)
	local FONT2 = Font.new("rbxasset://fonts/families/Montserrat.json", Enum.FontWeight.Bold)
	local Wd, Hd = 7.0, 3.6
	local bb = K.board(head, Wd, Hd, 3.7)
	bb:SetAttribute("RCBadgeTop", 0.3)
	local function P(x, y) return UDim2.fromScale(x / Wd, y / Hd) end
	local function Z(w, h) return UDim2.fromScale(w / Wd, h / Hd) end
	local CX, CY, CWd, CHd = Wd / 2, 1.45, 5.4, 2.3

	local card = K.frame(bb, { BackgroundColor3 = BLK, BackgroundTransparency = 0, AnchorPoint = Vector2.new(0.5, 0.5), Position = P(CX, CY), Size = Z(CWd, CHd), ClipsDescendants = true, ZIndex = 1 })
	K.new("UICorner", { CornerRadius = UDim.new(0.07, 0) }, card)
	K.new("UIGradient", { Rotation = 35, Color = CS(BLK2, BLK) }, card)
	local front = K.frame(card, { Size = UDim2.fromScale(1, 1), ZIndex = 2 })
	local function at(parent, x, y, w, h) return UDim2.fromScale(x / CWd, y / CHd), UDim2.fromScale(w / CWd, h / CHd), parent end
	local chipP, chipS = at(front, 0.5, 0.75, 0.8, 0.6)
	local chip = K.frame(front, { BackgroundColor3 = W, BackgroundTransparency = 0, Position = chipP, Size = chipS, ZIndex = 3 })
	K.new("UICorner", { CornerRadius = UDim.new(0.2, 0) }, chip)
	K.new("UIGradient", { Rotation = 45, Color = CS({ CK(0, C1), CK(0.5, GOLD2), CK(1, C1) }) }, chip)
	for i = 1, 2 do K.frame(chip, { BackgroundColor3 = GOLD2, BackgroundTransparency = 0.2, Position = UDim2.fromScale(0, i / 3), Size = UDim2.new(1, 0, 0.06, 0), ZIndex = 4 }) end
	local wp, ws = at(front, 0.3, 1.25, CWd - 0.6, 0.62)
	local word = K.text(front, { Position = wp, Size = ws, Text = "BIG SPENDER", FontFace = FONT, TextColor3 = W, TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 4 })
	local wg = K.new("UIGradient", { Rotation = 90, Color = CS({ CK(0, C1:Lerp(W, 0.45)), CK(0.5, C1), CK(1, GOLD2) }) }, word)
	local nlP, nlS = at(front, 0.3, 1.88, 2.0, 0.28)
	K.text(front, { Position = nlP, Size = nlS, Text = "NO LIMIT", FontFace = FONT2, TextColor3 = C2, TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 4 })
	local dP, dS = at(front, CWd - 1.5, 1.88, 1.2, 0.28)
	K.text(front, { Position = dP, Size = dS, Text = "12/99", FontFace = FONT2, TextColor3 = C1:Lerp(BLK, 0.35), TextXAlignment = Enum.TextXAlignment.Right, ZIndex = 4 })

	local shine = K.frame(card, { BackgroundColor3 = W, BackgroundTransparency = 0, Size = UDim2.fromScale(0.35, 1.2), AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(-0.3, 0.5), ZIndex = 6 })
	K.new("UIGradient", { Rotation = 0, Transparency = NS({ NK(0, 1), NK(0.5, 0.75), NK(1, 1) }) }, shine)

	local back = K.frame(card, { Size = UDim2.fromScale(1, 1), ZIndex = 2, Visible = false })
	local sP, sS = at(back, 0, 0.3, CWd, 0.5)
	K.frame(back, { BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 0, Position = sP, Size = sS, ZIndex = 3 })
	local blP, blS = at(back, 0.35, 1.0, 2.5, 0.3)
	K.text(back, { Position = blP, Size = blS, Text = "BALANCE", FontFace = FONT2, TextColor3 = C1:Lerp(W, 0.3), TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 4 })
	local bvP, bvS = at(back, 0.35, 1.35, CWd - 0.7, 0.6)
	local bal = K.text(back, { Position = bvP, Size = bvS, Text = "$0", FontFace = FONT, TextColor3 = C2, TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 4 })

	local stamp = K.text(bb, { AnchorPoint = Vector2.new(0.5, 0.5), Position = P(CX, CY), Size = Z(4.6, 0.8), Rotation = -8, Text = "", FontFace = FONT, TextColor3 = RED, TextTransparency = 1, ZIndex = 8 })
	local UW = math.clamp(#K.NAME * 0.27 + 0.9, 2.2, 6.4)
	local pill = K.frame(bb, { BackgroundColor3 = BLK, BackgroundTransparency = 0.15, AnchorPoint = Vector2.new(0.5, 0.5), Position = P(CX, 3.05), Size = Z(UW, 0.5), ZIndex = 3 })
	K.new("UICorner", { CornerRadius = UDim.new(0.5, 0) }, pill)
	K.text(bb, { AnchorPoint = Vector2.new(0.5, 0.5), Position = P(CX, 3.05), Size = Z(UW - 0.4, 0.32), Text = K.NAME, FontFace = FONT2, TextColor3 = C1:Lerp(W, 0.35), ZIndex = 4 })

	local ch = System.StaffThemes._tagCh or {}
	local function money(n)
		local s = tostring(math.floor(n))
		local out = s:reverse():gsub("(%d%d%d)", "%1,"):reverse()
		if out:sub(1, 1) == "," then out = out:sub(2) end
		return "$" .. out
	end
	local TS = { emo = ch.sEmoteN or 0, flipT = 0, showBack = false, face = false, bal = 1000000 + math.random(0, 899999), lb = nil, wasDead = false, ok = 0, lw = nil, st = nil }
	return function(t, dt, it)
		local dead = ch.dead == true
		if TS.wasDead and not dead then TS.ok = 2.6 end
		TS.wasDead = dead
		TS.ok = math.max(0, TS.ok - dt)

		if ch.on then TS.bal += (ch.spd or 16) * 137 * dt end
		local bs = money(TS.bal)
		if bs ~= TS.lb then TS.lb = bs bal.Text = bs end

		if (ch.sEmoteN or 0) ~= TS.emo then TS.emo = ch.sEmoteN or 0 TS.showBack = true end
		if TS.showBack and not ch.mOn then TS.flipT += dt if TS.flipT > 1.2 then TS.showBack, TS.flipT = false, 0 end else TS.flipT = 0 end
		local wantBack = TS.showBack and not dead
		TS.fk = TS.fk or 0
		if wantBack ~= TS.face then
			TS.fk += dt / 0.3
			if TS.fk >= 0.5 then front.Visible, back.Visible = not wantBack, wantBack end
			if TS.fk >= 1 then TS.face, TS.fk = wantBack, 0 end
		end

		local ik = c01(it / 0.4)
		local wx = math.abs(math.cos(math.min(TS.fk, 1) * math.pi))
		local w = math.floor(CWd * wx * 50 + 0.5) / 50
		if w ~= TS.lw then TS.lw = w card.Size = Z(math.max(0.02, w), CHd) end
		card.Position = P(CX, CY + 0.6 * (1 - ik) * (1 - ik))
		card.BackgroundTransparency = 1 - ik
		local sk = ((t + 2) % 4) / 0.7
		shine.Position = UDim2.fromScale(sk <= 1 and -0.3 + 1.6 * sk or -0.4, 0.5)
		wg.Offset = Vector2.new(0, 0.08 * math.sin(t * 1.5))

		local st = dead and "DECLINED" or TS.ok > 0 and "APPROVED" or ""
		if st ~= TS.st then
			TS.st = st
			stamp.Text = st
			stamp.TextColor3 = dead and RED or C2
		end
		stamp.TextTransparency = st == "" and 1 or 0.05
		stamp.Size = Z(4.6 * (st ~= "" and (1 + 0.3 * c01(1 - (2.6 - TS.ok) / 0.2) * (dead and 0 or 1)) or 1), 0.8)
	end
end

System.StaffThemes.THEMES.bigspender = function(L, C)
	local C1, C2, W = C.c1, C.c2, L.W
	local NS, CS, K, NR = L.NS, L.CS, L.K, L.NR
	local ch, rnd, c01 = L.ch, L.rnd, L.c01
	local NEON, PLASTIC, METAL = Enum.Material.Neon, Enum.Material.SmoothPlastic, Enum.Material.Metal
	local UP = Vector3.yAxis
	local GOLD = Color3.fromRGB(235, 185, 45)
	local CASH = C2:Lerp(Color3.fromRGB(40, 110, 60), 0.35)
	local RED = Color3.fromRGB(150, 14, 26)
	local function sc() return ch.sc or 1 end
	local function camRight()
		local cam = workspace.CurrentCamera
		local r = cam and cam.CFrame.RightVector or Vector3.xAxis
		r = Vector3.new(r.X, 0, r.Z)
		return r.Magnitude > 0.05 and r.Unit or Vector3.xAxis
	end
	local function label(text, col, w, h)
		local p = L.part()
		local g = L.new("BillboardGui", { Size = UDim2.new(w, 0, h, 0), LightInfluence = 0, MaxDistance = 200, AlwaysOnTop = true, Adornee = p }, p)
		local t = L.new("TextLabel", { BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), TextScaled = true, FontFace = L.fam("Montserrat", Enum.FontWeight.Heavy),
			TextColor3 = col, TextTransparency = 1, Text = text }, g)
		return p, t
	end

	L.cine.bigspender = { font = L.fam("Montserrat", Enum.FontWeight.Heavy), sub = L.fam("Montserrat"), kick = "B I G   S P E N D E R", subText = "H A S   A R R I V E D",
		stroke = Color3.fromRGB(30, 20, 4), life = 2.4,
		grad = function(c1) return CS({ L.CK(0, c1:Lerp(W, 0.5)), L.CK(0.5, c1), L.CK(1, Color3.fromRGB(176, 120, 30)) }) end }



	local MON = { notes = {}, coins = {}, ni = 0, ci = 0 }
	for i = 1, 16 do MON.notes[i] = { p = L.part({ Material = PLASTIC, Color = CASH, Transparency = 1, Size = Vector3.new(0.9, 0.03, 0.42) }), t = 99, life = 1 } end
	for i = 1, 16 do MON.coins[i] = { p = L.part({ Shape = Enum.PartType.Cylinder, Material = METAL, Color = GOLD, Reflectance = 0.15, Transparency = 1, Size = Vector3.new(0.08, 0.5, 0.5) }), t = 99, life = 1 } end
	function MON.note(x, v, life, gy)
		MON.ni = MON.ni % #MON.notes + 1
		local N = MON.notes[MON.ni]
		N.x, N.v, N.t, N.life, N.gy, N.sp, N.ph, N.ls = x, v, 0, life, gy, rnd(-4, 4), rnd(0, 6), nil
	end
	function MON.coin(x, v, life, gy)
		MON.ci = MON.ci % #MON.coins + 1
		local N = MON.coins[MON.ci]
		N.x, N.v, N.t, N.life, N.gy, N.sp, N.ls = x, v, 0, life, gy, rnd(8, 16), nil
	end
	function MON.step(dt, s, off)
		local z = math.floor(s * 20 + 0.5) / 20
		for _, N in ipairs(MON.notes) do
			if N.t < N.life then
				N.t += dt
				if N.t >= N.life or off then N.t = 99 N.p.Transparency = 1
				else

					N.v += (Vector3.new(0, -6, 0) - N.v * 1.8) * dt
					N.x += (N.v + Vector3.new(math.sin(N.t * 5 + N.ph) * 1.2, 0, 0) * s) * dt
					local onGround = N.gy and N.x.Y <= N.gy + 0.03
					if onGround then N.x = Vector3.new(N.x.X, N.gy + 0.03, N.x.Z) N.v *= Vector3.new(0.9, 0, 0.9) end
					if z ~= N.ls then N.ls = z N.p.Size = Vector3.new(0.9 * z, 0.03, 0.42 * z) end
					local tilt = onGround and 0 or math.sin(N.t * 6 + N.ph) * 0.7
					N.p.CFrame = CFrame.new(N.x) * CFrame.Angles(tilt, N.ph + N.t * N.sp * (onGround and 0 or 1), tilt * 0.5)
					N.p.Transparency = 0.02 + 0.98 * c01((N.t / N.life - 0.75) / 0.25)
				end
			end
		end
		for _, N in ipairs(MON.coins) do
			if N.t < N.life then
				N.t += dt
				if N.t >= N.life or off then N.t = 99 N.p.Transparency = 1
				else
					N.v -= Vector3.new(0, 40 * dt, 0)
					N.x += N.v * dt
					local flat = false
					if N.gy and N.x.Y < N.gy + 0.05 then
						N.x = Vector3.new(N.x.X, N.gy + 0.05, N.x.Z)
						if math.abs(N.v.Y) > 3 then N.v = Vector3.new(N.v.X * 0.6, -N.v.Y * 0.4, N.v.Z * 0.6) else N.v, flat = Vector3.zero, true end
						N.sp *= 0.8
					end
					if z ~= N.ls then N.ls = z N.p.Size = Vector3.new(0.08 * z, 0.5 * z, 0.5 * z) end
					N.p.CFrame = CFrame.new(N.x) * (flat and CFrame.Angles(0, 0, math.pi / 2) or CFrame.Angles(N.t * N.sp, N.t * N.sp * 0.6, math.pi / 2))
					N.p.Transparency = c01((N.t / N.life - 0.8) / 0.2)
				end
			end
		end
	end

	local FT = { list = {}, i = 0, d = 0, side = 1, lp = nil }
	for i = 1, 10 do FT.list[i] = { p = L.part({ Material = NEON, Color = GOLD, Transparency = 1, Size = Vector3.new(0.4, 0.04, 0.75) }), t = 99 } end

	local glP = L.part()
	local glE = L.pe(glP, { Texture = L.T("star.png"), Lifetime = NR(0.35, 0.55), Speed = NR(0, 0), Size = NS({ K(0, 0), K(0.4, 0.55), K(1, 0) }), Rotation = NR(0, 90), RotSpeed = NR(-90, 90),
		Color = CS(W, GOLD), Brightness = 4, LockedToPart = false })
	local fxP = L.part()
	local fxE = L.pe(fxP, { Texture = L.T("flare.png"), Lifetime = NR(0.12, 0.18), Speed = NR(0, 0), Size = NS({ K(0, 3), K(1, 1) }), Color = CS(W), Brightness = 6 })
	local fxL = L.new("PointLight", { Color = W, Range = 14, Brightness = 0, Shadows = false }, fxP)

	local FAN = { list = {}, t = 0, flick = 0, on = 0 }
	for i = 1, 5 do FAN.list[i] = L.part({ Material = PLASTIC, Color = CASH:Lerp(W, (i - 1) * 0.04), Transparency = 1, Size = Vector3.new(0.85, 0.03, 0.4) }) end


	local rig = {}
	local function rebind() end
	System.StaffThemes._tagCh = ch
	local tag = System.StaffThemes.headTag(L, "bigspender", C1, C2, { c1 = C1, c2 = C2, role = "B I G   S P E N D E R" })
	System.StaffThemes._tagCh = nil

	local held = nil
	local deathGone = nil
	local dying = false
	local function hide(on)
		if on then
			held = held or {}
			for d in pairs(L.bodyParts()) do if not held[d] then held[d] = true d.LocalTransparencyModifier = 1 end end
		elseif held then
			for d in pairs(held) do if d.Parent then pcall(function() d.LocalTransparencyModifier = 0 end) end end
			held = nil
		end
	end
	local function bodyGhost(col, mat, life)
		if not ch.char then return {} end
		local g = L.ghost(col, mat, life, true)
		local list = {}
		for _, p in ipairs(g:GetChildren()) do if p:IsA("BasePart") then p.LocalTransparencyModifier = 0 list[#list + 1] = { p = p, cf = p.CFrame } end end
		return list
	end
	local function bodyList()
		local t = {}
		for d in pairs(L.bodyParts()) do if d:IsA("BasePart") then t[#t + 1] = d end end
		return t
	end
	local function hand(right)
		local c = ch.char
		if not c then return nil end
		local p = c:FindFirstChild(right and "RightHand" or "LeftHand")
		if p then return p.Position end
		p = c:FindFirstChild(right and "Right Arm" or "Left Arm")
		return p and p:IsA("BasePart") and (p.CFrame * CFrame.new(0, -p.Size.Y * 0.45, 0)).Position or nil
	end
	local function glint(at, n) glP.CFrame = CFrame.new(at) glE:Emit(n or 1) end
	local function cashBurst(at, n, s, sp, gy)
		for _ = 1, n do MON.note(at + Vector3.new(rnd(-0.4, 0.4), rnd(0, 0.6), rnd(-0.4, 0.4)) * s, Vector3.new(rnd(-1, 1) * sp, rnd(0.6, 1.4) * sp, rnd(-1, 1) * sp) * s, rnd(1.6, 2.6), gy) end
	end
	local function flash(at, big)
		fxP.CFrame = CFrame.new(at)
		fxE:Emit(1)
		fxL.Brightness = big and 7 or 4
	end



	local function shortApproved()
		local o, s = L.ground(ch.feet, 3, 8), sc()
		hide(true)
		local top = o + UP * 6.2 * s
		local r = camRight()
		local base = CFrame.fromMatrix(Vector3.zero, r, UP)
		local cd = L.part({ Material = PLASTIC, Color = Color3.fromRGB(16, 16, 18), Transparency = 1, Size = Vector3.new(3.4 * s, 0.07, 2.1 * s) })
		local stripe = L.part({ Material = NEON, Color = GOLD, Transparency = 1, Size = Vector3.new(3.4 * s, 0.08, 0.14 * s) })
		local scan = L.part({ Material = NEON, Color = C2, Transparency = 1, Size = Vector3.new(3.2 * s, 0.04, 1.9 * s) })
		local lp, lt = label("APPROVED", C2, 5 * s, 1.1 * s)
		lp.CFrame = CFrame.new(o + UP * 3.6 * s)
		L.timeline(2.5, function(t, once)
			if held and once("late", 0.2) and t < 0.25 then hide(true) end
			local u = L.inQuad(c01((t - 0.15) / 0.85))
			local y = top:Lerp(o + UP * 0.05, u)
			local on = c01(t / 0.15) * (1 - c01((t - 1.4) / 0.3))
			cd.CFrame = base + y
			stripe.CFrame = base + y + UP * 0.01 + base.LookVector * -0.6 * s
			scan.CFrame = base + y - UP * 0.06
			cd.Transparency, stripe.Transparency = 1 - on, 1 - on
			scan.Transparency = 1 - 0.6 * on * ((math.random() < 0.2) and 0.5 or 1)

			if held and t > 0.15 then
				for d in pairs(held) do
					if d.Parent and d:IsA("BasePart") and d.Position.Y > y.Y then held[d] = nil d.LocalTransparencyModifier = 0 end
				end
			end
			if once("ok", 1.0) then
				hide(false)
				glint(o + UP * 2.5 * s, 6)
				for _ = 1, 6 do MON.coin(o + UP * 0.5 * s, Vector3.new(rnd(-4, 4), rnd(4, 8), rnd(-4, 4)) * s, 1.6, o.Y) end
			end
			lt.TextTransparency = t < 1 and 1 or (1 - c01((t - 1) / 0.1)) + c01((t - 2.1) / 0.3)
			lp.CFrame = CFrame.new(o + UP * (3.6 + 0.4 * c01((t - 1) / 1.2)) * s)
		end, { cd, stripe, scan, lp }, function() hide(false) end)
	end

	local function shortVault()
		local o, s = L.ground(ch.feet, 3, 8), sc()
		hide(true)
		local r = camRight()
		local fwd = r:Cross(UP)
		local cam = workspace.CurrentCamera
		if cam and fwd:Dot(cam.CFrame.Position - o) < 0 then fwd = -fwd end
		local SZ = 2.6 * s
		local body = L.part({ Material = METAL, Color = Color3.fromRGB(150, 112, 30), Reflectance = 0.1, Transparency = 1, Size = Vector3.new(SZ, SZ * 1.15, SZ) })
		local door = L.part({ Material = METAL, Color = GOLD, Reflectance = 0.15, Transparency = 1, Size = Vector3.new(SZ * 0.86, SZ * 0.98, 0.12 * s) })
		local dial = L.part({ Shape = Enum.PartType.Cylinder, Material = METAL, Color = Color3.fromRGB(60, 60, 66), Transparency = 1, Size = Vector3.new(0.14 * s, 0.8 * s, 0.8 * s) })
		local spoke = L.part({ Material = NEON, Color = W, Transparency = 1, Size = Vector3.new(0.06 * s, 0.55 * s, 0.06 * s) })
		local face = CFrame.lookAt(Vector3.zero, -fwd)
		L.timeline(2.6, function(t, once)
			if held and once("late", 0.2) and t < 1.5 then hide(true) end
			local fall = c01(t / 0.4)
			local bounce = t > 0.4 and 0.35 * s * math.max(0, math.sin((t - 0.4) / 0.25 * math.pi)) * (t < 0.65 and 1 or 0) or 0
			local shrink = c01((t - 2.1) / 0.4)
			local c = o + UP * (SZ * 0.575 + 9 * s * (1 - fall * fall) + bounce)
			local cf = face + c
			local tr = (1 - c01(t / 0.08)) + shrink
			body.CFrame, body.Transparency = cf, tr

			local sw = L.outBack(c01((t - 1.3) / 0.3)) * 1.9
			local hinge = cf * CFrame.new(-SZ * 0.43, 0, SZ * 0.5 + 0.07 * s)
			door.CFrame = hinge * CFrame.Angles(0, -sw, 0) * CFrame.new(SZ * 0.43, 0, 0)
			door.Transparency = tr
			local dcf = door.CFrame * CFrame.new(0, 0.1 * SZ, 0.1 * s) * CFrame.Angles(0, math.pi / 2, 0)
			local spin = t < 0.5 and 0 or math.min(t, 1.3) * 12 - 6
			dial.CFrame, dial.Transparency = dcf, tr
			spoke.CFrame, spoke.Transparency = door.CFrame * CFrame.new(0, 0.1 * SZ, 0.17 * s) * CFrame.Angles(0, 0, spin), tr
			if once("land", 0.4) then for _ = 1, 4 do MON.coin(o + UP * 0.3, Vector3.new(rnd(-5, 5), rnd(3, 6), rnd(-5, 5)) * s, 1.4, o.Y) end end
			if once("open", 1.45) then
				hide(false)
				cashBurst(o + UP * 2 * s, 10, s, 4, o.Y)
				glint(o + UP * 2 * s, 5)
			end
		end, { body, door, dial, spoke }, function() hide(false) end)
	end
	local shorts = { shortApproved, shortVault }


	local function arriveFull()
		local o, s = L.ground(ch.feet, 3, 8), sc()
		hide(true)
		local DUR = 6
		local S = L.screen(DUR)
		S.style, S.c1, S.c2 = "bigspender", C1, C2
		S.boxFn = function(t) return c01((t - 0.1) / 0.4) * (1 - c01((t - 5.0) / 0.6)) end
		S.tintFn = function(t) return Color3.fromRGB(255, 220, 150), 0.32 * c01(t / 0.6) * (1 - c01((t - 4.4) / 1.2)) end
		local objs = {}
		local function keep(x) objs[#objs + 1] = x return x end

		local cam = workspace.CurrentCamera
		local fwd = cam and Vector3.new(cam.CFrame.Position.X - o.X, 0, cam.CFrame.Position.Z - o.Z) or Vector3.zAxis
		fwd = fwd.Magnitude > 0.1 and fwd.Unit or Vector3.zAxis
		local side = fwd:Cross(UP)
		local LEN, WID = 13 * s, 3 * s
		local far = o + fwd * LEN
		local base = CFrame.fromMatrix(Vector3.zero, side, UP, -fwd)
		local carpet = keep(L.part({ Material = Enum.Material.Fabric, Color = RED, Transparency = 1, Size = Vector3.new(WID, 0.06, 0.1) }))
		local trims = { keep(L.part({ Material = NEON, Color = GOLD, Transparency = 1, Size = Vector3.new(0.12 * s, 0.07, 0.1) })), keep(L.part({ Material = NEON, Color = GOLD, Transparency = 1, Size = Vector3.new(0.12 * s, 0.07, 0.1) })) }
		local roll = keep(L.part({ Shape = Enum.PartType.Cylinder, Material = Enum.Material.Fabric, Color = RED, Transparency = 1, Size = Vector3.new(WID, 0.7 * s, 0.7 * s) }))

		local posts = {}
		for sd = -1, 1, 2 do
			for i = 1, 4 do
				local at = L.ground(o + fwd * (1.5 + (i - 1) * 3.2) * s + side * sd * (WID / 2 + 0.6 * s), 3, 6)
				local P = { at = at, t0 = 0.35 + (i - 1) * 0.12 + (sd > 0 and 0.06 or 0) }
				P.pole = keep(L.part({ Shape = Enum.PartType.Cylinder, Material = METAL, Color = GOLD, Reflectance = 0.2, Transparency = 1, Size = Vector3.new(1.6 * s, 0.16 * s, 0.16 * s) }))
				P.ball = keep(L.part({ Shape = Enum.PartType.Ball, Material = METAL, Color = GOLD, Reflectance = 0.2, Transparency = 1, Size = Vector3.one * 0.34 * s }))
				P.a = keep(L.att(at + UP * 1.4 * s))
				posts[#posts + 1] = P
			end
		end
		local ropes = {}
		for i = 1, #posts do
			if i % 4 ~= 0 then
				ropes[#ropes + 1] = keep(L.beam(posts[i].a, posts[i + 1].a, { Texture = "", Width0 = 0.12 * s, Width1 = 0.12 * s, Brightness = 1, LightEmission = 0, FaceCamera = true,
					CurveSize0 = -0.8 * s, CurveSize1 = 0.8 * s, Segments = 10, Color = CS(Color3.fromRGB(120, 10, 24)), Transparency = NS(1) }))
			end
		end
		local flT, lastU = 0, -1
		L.timeline(DUR, function(t, once)
			local dt = L.lastDt or 0.016
			if held and once("late", 0.3) then hide(true) end

			local u = L.outQuad(c01((t - 0.2) / 1.2))
			local fadeK = c01((t - 5.0) / 0.9)
			local len = math.max(0.1, LEN * u)
			local q = math.floor(len * 20) / 20
			if q ~= lastU then
				lastU = q
				local mid = far - fwd * (q / 2)
				carpet.Size = Vector3.new(WID, 0.06, q)
				carpet.CFrame = base + mid + UP * 0.03
				for i, tr in ipairs(trims) do
					tr.Size = Vector3.new(0.12 * s, 0.07, q)
					tr.CFrame = base + mid + side * (i == 1 and -1 or 1) * WID / 2 + UP * 0.035
				end
			end
			carpet.Transparency = t < 0.2 and 1 or fadeK
			for _, tr in ipairs(trims) do tr.Transparency = t < 0.2 and 1 or fadeK end
			roll.CFrame = base + far - fwd * len + UP * 0.35 * s * (1 - u * 0.6)
			roll.Transparency = (t < 0.2 or u >= 1) and 1 or 0

			for _, P in ipairs(posts) do
				local k = L.outBack(c01((t - P.t0 - (1 - (P.at - o).Magnitude / LEN) * 0.9) / 0.25))
				local h = 1.6 * s * math.max(0.01, k)
				P.pole.CFrame = CFrame.new(P.at + UP * h / 2) * CFrame.Angles(0, 0, math.pi / 2)
				if math.abs(P.pole.Size.X - h) > 0.02 then P.pole.Size = Vector3.new(h, 0.16 * s, 0.16 * s) end
				P.ball.CFrame = CFrame.new(P.at + UP * (h + 0.1 * s))
				P.a.WorldPosition = P.at + UP * (h - 0.15 * s)
				local tr = k <= 0.01 and 1 or fadeK
				P.pole.Transparency, P.ball.Transparency = tr, tr
			end
			local rt = NS(c01((t - 1.9) / 0.2) > 0 and (0.05 + 0.95 * fadeK) or 1)
			if t > 1.9 then for _, b in ipairs(ropes) do b.Transparency = rt end end

			flT -= dt
			if t > 1.2 and t < 4.6 and flT <= 0 then
				flT = rnd(0.12, 0.32)
				local d = rnd(0.2, 1) * LEN
				local at = o + fwd * d + side * (math.random() < 0.5 and -1 or 1) * rnd(3.5, 6) * s + UP * rnd(2, 4.5) * s
				flash(at, math.random() < 0.3)
				if math.random() < 0.25 then S:flash(W, 0.12) end
			end
			fxL.Brightness = math.max(0, fxL.Brightness - dt * 40)

			if once("show", 3.6) then
				hide(false)
				local g = bodyGhost(GOLD, NEON, 0.5)
				L.fx(0.5, function(k) for _, gp in ipairs(g) do gp.p.Transparency = 0.2 + 0.8 * k end end, {})
				glint(o + UP * 2.6 * s, 10)
				flash(o + UP * 3 * s + fwd * 1.5 * s, true)
				S:flash(GOLD:Lerp(W, 0.5), 0.35)
				cashBurst(o + UP * 4 * s, 14, s, 5, o.Y)
			end
			if once("card", 3.9) then S:title(L.name(), C1, C2) end
		end, objs, function() hide(false) end)
	end


	local function death(preview)
		if not ch.char then return end
		local s = sc()
		local pos = L.ground(ch.feet or ch.pos, 3, 8)
		local g = bodyGhost(GOLD, METAL, 1.4)
		for _, gp in ipairs(g) do gp.p.Reflectance = 0.25 end
		local gone = {}
		deathGone = gone
		dying = true
		for d in pairs(L.bodyParts()) do gone[d] = true d.LocalTransparencyModifier = 1 end
		local coins, objs = {}, {}
		local gT = 0
		L.timeline(5.2, function(t, once)
			local dt = L.lastDt or 0.016

			if t < 1.1 then
				gT -= dt
				if gT <= 0 and #g > 0 then gT = 0.18 glint(g[math.random(1, #g)].p.Position, 1) end
			end
			if once("break", 1.1) then
				for _, gp in ipairs(g) do gp.p.Transparency = 1 end
				local c = pos + UP * 2.5 * s
				for i = 1, 36 do
					local src = g[math.random(1, math.max(1, #g))]
					local at = src and src.p.Position + Vector3.new(rnd(-0.4, 0.4), rnd(-0.4, 0.4), rnd(-0.4, 0.4)) * s or c
					local d = (at - c) * Vector3.new(1, 0, 1)
					d = d.Magnitude > 0.05 and d.Unit or Vector3.xAxis
					local q = L.part({ Shape = Enum.PartType.Cylinder, Material = METAL, Color = GOLD, Reflectance = 0.15, Transparency = 0, Size = Vector3.new(0.08, 0.5, 0.5) * s, CFrame = CFrame.new(at) })
					objs[#objs + 1] = q
					coins[#coins + 1] = { p = q, x = at, v = (d * rnd(2, 6) + UP * rnd(3, 8)) * s, sp = rnd(8, 18), flat = false, yaw = rnd(0, 6) }
				end
				glint(c, 8)
			end
			if t > 1.1 then
				local fk = c01((t - 4.2) / 1.0)
				for _, cb in ipairs(coins) do
					if not cb.flat then
						cb.v -= UP * 40 * dt
						cb.x += cb.v * dt
						if cb.x.Y < pos.Y + 0.05 then
							cb.x = Vector3.new(cb.x.X, pos.Y + 0.05, cb.x.Z)
							if math.abs(cb.v.Y) > 3 then cb.v = Vector3.new(cb.v.X * 0.5, -cb.v.Y * 0.35, cb.v.Z * 0.5) else cb.flat = true end
						end
						cb.p.CFrame = CFrame.new(cb.x) * CFrame.Angles(t * cb.sp, cb.yaw, math.pi / 2)
					elseif not cb.laid then
						cb.laid = true
						cb.p.CFrame = CFrame.new(cb.x) * CFrame.Angles(0, cb.yaw, math.pi / 2)
					end
					cb.p.Transparency = fk
				end
			end
		end, objs, function()
			deathGone = nil
			dying = false
			if preview then for d in pairs(gone) do if d.Parent then pcall(function() d.LocalTransparencyModifier = 0 end) end end end
		end)
	end


	local ST = { beat = 0, glT = 0.5, noteT = rnd(3, 6), whipT = 0 }
	local function step(dt)
		local s, iw, on, swim, sit, dead = sc(), ch.iw or 0, ch.on, ch.swim == true, ch.sit == true, ch.dead == true
		local off = dead or dying
		local pause = off or sit or swim
		MON.step(dt, s, false)
		L.motion(dt, s, off)
		fxL.Brightness = math.max(0, fxL.Brightness - dt * 40)

		if (ch.sBeat or 0) ~= ST.beat then
			ST.beat = ch.sBeat or 0
			if not pause then
				local gy = L.ground(ch.feet, 2, 4).Y
				for _, rh in ipairs({ true, false }) do
					local h = hand(rh)
					if h then cashBurst(h, 2, s, 4, gy) end
				end
			end
		end
		if not pause then

			ST.glT -= dt
			if ST.glT <= 0 then
				ST.glT = rnd(0.25, 0.6)
				local list = bodyList()
				if #list > 0 then
					local p = list[math.random(1, #list)]
					glint(p.CFrame:PointToWorldSpace(Vector3.new(rnd(-0.5, 0.5) * p.Size.X, rnd(-0.5, 0.5) * p.Size.Y, -0.5 * p.Size.Z)), 1)
				end
			end

			ST.noteT -= dt
			if ST.noteT <= 0 then
				ST.noteT = rnd(3, 6)
				local a = rnd(0, math.pi * 2)
				local at = ch.feet + Vector3.new(math.cos(a), 0, math.sin(a)) * rnd(2, 4) * s
				MON.note(at + UP * rnd(5, 7) * s, Vector3.new(rnd(-0.5, 0.5), 0, rnd(-0.5, 0.5)) * s, 5, L.ground(at, 3, 6).Y)
			end
		end

		local want = (not pause and not on and (ch.stillT or 0) > 8 and not ch.mOn) and 1 or 0
		FAN.on += (want - FAN.on) * c01(dt * 5)
		local h = FAN.on > 0.02 and hand(true)
		if h and ch.hrp then
			FAN.t += dt
			if FAN.t > 0.4 then FAN.t, FAN.flick = 0, (FAN.flick % 5) + 1 end
			local rcf = ch.hrp.CFrame.Rotation
			for i, p in ipairs(FAN.list) do
				local slot = (i - FAN.flick) % 5
				local a = math.rad(-30 + slot * 15)
				local lift = (slot == 4 and FAN.t < 0.15) and 0.25 or 0
				p.CFrame = CFrame.new(h + rcf.LookVector * -0.25 * s + UP * (0.1 + lift) * s) * rcf * CFrame.Angles(math.rad(70), 0, 0) * CFrame.Angles(0, a, 0) * CFrame.new(0, slot * 0.01, -0.25 * s)
				p.Transparency = 1 - 0.98 * FAN.on
			end
		elseif FAN.on <= 0.02 and FAN.list[1].Transparency < 1 then
			for _, p in ipairs(FAN.list) do p.Transparency = 1 end
		end

		if on and not pause and not ch.air and ch.feet then
			if FT.lp then FT.d += ((ch.pos - FT.lp) * Vector3.new(1, 0, 1)).Magnitude end
			if FT.d > 1.6 * s then
				FT.d, FT.side = 0, -FT.side
				FT.i = FT.i % #FT.list + 1
				local F = FT.list[FT.i]
				local rot = ch.flat and ch.flat.Rotation or CFrame.identity
				local gp = L.ground(ch.feet + rot.RightVector * FT.side * 0.4 * s, 2, 4)
				if math.abs(F.p.Size.X - 0.4 * s) > 0.01 then F.p.Size = Vector3.new(0.4 * s, 0.04, 0.75 * s) end
				F.p.CFrame = rot + gp + UP * 0.04
				F.t = 0
			end

			if (ch.sprint or 0) > 0.3 then
				ST.whipT -= dt
				if ST.whipT <= 0 then
					ST.whipT = 0.12
					local back = ch.vel.Magnitude > 0.1 and -ch.vel.Unit or Vector3.zero
					MON.note(ch.pos + UP * rnd(-0.5, 1) * s, (back * rnd(4, 8) + UP * rnd(1, 3)) * s, 1.3, L.ground(ch.feet, 2, 4).Y)
				end
			end
		end
		FT.lp = ch.pos
		for _, F in ipairs(FT.list) do
			if F.t < 1.3 then
				F.t += dt
				F.p.Transparency = F.t >= 1.3 and 1 or 0.1 + 0.9 * (F.t / 1.3) + ((math.random() < 0.08) and -0.1 or 0)
			end
		end

		if ch.jumped and not off and not swim then
			local gy = L.ground(ch.feet, 2, 8).Y
			for _ = 1, 5 do MON.coin(ch.pos + UP * 0.5 * s, Vector3.new(rnd(-4, 4), rnd(3, 7), rnd(-4, 4)) * s, 1.6, gy) end
		end
		if ch.landed and not off and not swim then
			local gp = L.ground(ch.feet, 2, 4)
			cashBurst(gp + UP * 0.3 * s, 4, s, 3, gp.Y)
		end
		tag.step(dt)
	end

	return {
		arrive = function(short) if short then shorts[math.random(1, #shorts)]() else arriveFull() end end,
		short = function(n) n = math.floor(tonumber(n) or 1) shorts[(n - 1) % #shorts + 1]() end,
		step = step, rebind = rebind, death = death,
		hidden = function() return held or deathGone end,
		rig = function() return rig end,
		stop = function() hide(false) end,
	}
end
end
end)()
end
