    ["engine/cam_shift"] = [====[return function(P)
local _rawPcall, _rcPcallSink, _rcPcallRet, pcall, PS, RS, HS, DB, UIS, TS, MPS, MS, _RC_VER, _RC_VER_DATE = P._rawPcall, P._rcPcallSink, P._rcPcallRet, P.pcall, P.PS, P.RS, P.HS, P.DB, P.UIS, P.TS, P.MPS, P.MS, P._RC_VER, P._RC_VER_DATE
return (function()


return function(R, I)
local Function, PlayerData, System, _isActiveSession = I.Function, I.PlayerData, I.System, I._isActiveSession













	Function.camShiftPlan = function(rects, vpX, ch)
		local hgt = ch.bot - ch.top
		if hgt <= 0 or vpX <= 0 then return nil end
		local spans, hit = {}, false
		for _, r in ipairs(rects) do
			local a, b = math.max(0, r.x), math.min(vpX, r.x + r.w)
			local ov = math.min(r.y + r.h, ch.bot) - math.max(r.y, ch.top)
			if b > a and b - a < vpX * 0.9 and r.h > 0 and ov >= hgt * 0.25 then
				spans[#spans + 1] = { a, b }
				if a < ch.cx + ch.hw and b > ch.cx - ch.hw then hit = true end
			end
		end
		if not hit then return nil end
		table.sort(spans, function(p, q) return p[1] < q[1] end)
		local bestW, bestC, edge = 0, nil, 0
		for _, sp in ipairs(spans) do
			if sp[1] - edge > bestW then bestW, bestC = sp[1] - edge, (edge + sp[1]) / 2 end
			edge = math.max(edge, sp[2])
		end
		if vpX - edge > bestW then bestW, bestC = vpX - edge, (edge + vpX) / 2 end
		if bestW < math.max(vpX * 0.15, ch.hw * 2) then return nil end
		return bestC
	end






	Function.camShiftStep = function(st, off, target, dt, now)
		if st.seen ~= nil and off ~= st.seen then st.foreignAt = now end
		if st.foreignAt and now - st.foreignAt < 1 then
			st.cur, st.base, st.last, st.seen = Vector3.zero, nil, nil, off
			return nil
		end
		st.cur = st.cur:Lerp(target, 1 - math.exp(-math.min(dt, 0.25) * 8))
		if target == Vector3.zero and st.cur.Magnitude < 0.01 then
			local out = st.last and st.base or nil
			st.cur, st.base, st.last = Vector3.zero, nil, nil
			st.seen = out or off
			return out
		end
		if not st.last then st.base = off end
		st.last = st.base + st.cur
		st.seen = st.last
		return st.last
	end

	Function._camShiftStop = function()

		local st = Function._camShiftState
		Function._camShiftState = nil
		Function._camShiftCur = nil
		if st and Function._camShiftThaw then pcall(Function._camShiftThaw, st, nil) end
		if st and st.hum and st.last and st.base then pcall(function() if st.hum.Parent then st.hum.CameraOffset = st.base end end) end
		if _isActiveSession() then pcall(function() RS:UnbindFromRenderStep("RCCamShift") end) end
	end

	Function._camShiftStart = function()
		Function._camShiftStop()
		pcall(function() RS:UnbindFromRenderStep("RCCamShift") end)
		local st = { cur = Vector3.zero, rects = {}, rn = 0, keepT = {}, chT = {} }
		Function._camShiftState = st
		local LAYERS = { "RoClothesNewUI", "RoClothesPanel", "RoClothesMulti" }
		local function shown(o, vp)
			if not (o:IsA("GuiObject") and o.Visible) then return false end
			local sz = o.AbsoluteSize
			return o.BackgroundTransparency < 1 and sz.X > 0 and sz.Y > 0 and not (sz.X >= vp.X * 0.9 and sz.Y >= vp.Y * 0.9)
		end

		local function anyLayer(pg)
			for i = 1, #LAYERS do
				local g = pg:FindFirstChild(LAYERS[i])
				if g and g:IsA("ScreenGui") and g.Enabled then return true end
			end
			return false
		end
		local function add(o)
			local p, sz = o.AbsolutePosition, o.AbsoluteSize
			local n = st.rn + 1
			st.rn = n
			local row = st.rects[n]
			if not row then row = {}; st.rects[n] = row end
			row.x, row.y, row.w, row.h = p.X, p.Y, sz.X, sz.Y
		end
		local function windows(pg, vp)
			local out = st.rects
			st.rn = 0
			for _, nm in ipairs(LAYERS) do
				local g = pg:FindFirstChild(nm)
				if g and g:IsA("ScreenGui") and g.Enabled then
					for _, c in ipairs(g:GetChildren()) do
						if shown(c, vp) then add(c)
						elseif c:IsA("GuiObject") and c.Visible and c.BackgroundTransparency >= 1 then

							local sz = c.AbsoluteSize
							if sz.X >= vp.X * 0.9 and sz.Y >= vp.Y * 0.9 then
								for _, k in ipairs(c:GetChildren()) do if shown(k, vp) then add(k) end end
							end
						end
					end
				end
			end
			for i = #out, st.rn + 1, -1 do out[i] = nil end
			return out
		end
		local function release(h)
			if h and st.last and st.base then pcall(function() if h.Parent then h.CameraOffset = st.base end end) end
			st.last, st.base, st.cur, st.seen, st.foreignAt = nil, nil, Vector3.zero, nil, nil
		end



		Function._camShiftThaw = function(s, keep)
			for sf in pairs(s.frozen or {}) do
				if not (keep and keep[sf]) then
					s.frozen[sf] = nil
					pcall(function() if sf.Parent then sf.ScrollingEnabled = true end end)
				end
			end
		end
		local function lockedWheel(pg, cam)

			if UIS.MouseBehavior ~= Enum.MouseBehavior.LockCenter and next(st.frozen) == nil then return end
			local keep = st.keepT
			table.clear(keep)
			if UIS.MouseBehavior == Enum.MouseBehavior.LockCenter and pg and cam then
				local inset = Vector2.zero
				pcall(function() inset = game:GetService("GuiService"):GetGuiInset() end)
				local c = cam.ViewportSize / 2 - Vector2.new(0, inset.Y)
				for _, o in ipairs(pg:GetGuiObjectsAtPosition(c.X, c.Y)) do
					if o:IsA("ScrollingFrame") then
						local g = o:FindFirstAncestorWhichIsA("LayerCollector")
						if g and table.find(LAYERS, g.Name) and (o.ScrollingEnabled or st.frozen[o]) then
							keep[o] = true
							if o.ScrollingEnabled then st.frozen[o] = true; o.ScrollingEnabled = false end
						end
					end
				end
			end
			Function._camShiftThaw(st, keep)
		end
		st.frozen = {}



		local function holds(h) if not h then return false end for i = 1, #LAYERS do if h:FindFirstChild(LAYERS[i]) then return true end end return false end
		local function layerHost(pg)
			local c = st.host
			if c and c.Parent ~= nil and holds(c) then return c end
			st.host = nil
			local hui = nil
			if gethui then pcall(function() hui = gethui() end) end
			local cg = nil
			pcall(function() cg = game:GetService("CoreGui") end)
			for _, h in ipairs({ pg or false, hui or false, cg or false }) do
				if h and select(2, pcall(holds, h)) == true then st.host = h; return h end
			end
			return pg
		end

		local function wheelStep()
			local lP = PS.LocalPlayer
			lockedWheel(lP and lP:FindFirstChildOfClass("PlayerGui"), workspace.CurrentCamera)
		end
		local function mainStep(dt)
			do
				local lP = PS.LocalPlayer
				local char = lP and lP.Character
				local hum = char and char:FindFirstChildOfClass("Humanoid")
				local root = char and char:FindFirstChild("HumanoidRootPart")
				if st.hum ~= hum then release(st.hum); st.hum = hum end
				if not (hum and root) then Function._camShiftCur = nil; return end
				local cam = workspace.CurrentCamera
				local target = Vector3.zero
				if cam and not System._photoExit and cam.CameraType == Enum.CameraType.Custom and cam.CameraSubject == hum
					and UIS.MouseBehavior ~= Enum.MouseBehavior.LockCenter then
					local dist = (cam.CFrame.Position - cam.Focus.Position).Magnitude
					local pg = layerHost(lP:FindFirstChildOfClass("PlayerGui"))
					local vp = cam.ViewportSize
					if dist >= 2 and pg and vp.X > 0 and vp.Y > 0 and anyLayer(pg) then
						local pps = vp.Y / (2 * dist * math.tan(math.rad(cam.FieldOfView) / 2))
						local head = char:FindFirstChild("Head")
						local topW = head and (head.Position + Vector3.new(0, head.Size.Y / 2, 0)) or (root.Position + Vector3.new(0, 2.5, 0))
						local legs = (hum.RigType == Enum.HumanoidRigType.R6) and 2 or hum.HipHeight
						local botW = root.Position - Vector3.new(0, root.Size.Y / 2 + legs, 0)
						local a = cam:WorldToScreenPoint(topW)
						local b = cam:WorldToScreenPoint(botW)
						if a.Z > 0 and b.Z > 0 then
							local ch = st.chT
							ch.cx, ch.top, ch.bot, ch.hw = vp.X / 2, math.min(a.Y, b.Y), math.max(a.Y, b.Y), 1.5 * pps
							local tx = Function.camShiftPlan(windows(pg, vp), vp.X, ch)
							local right = Vector3.new(cam.CFrame.RightVector.X, 0, cam.CFrame.RightVector.Z)
							if tx and right.Magnitude > 1e-3 then

								target = root.CFrame:VectorToObjectSpace(right.Unit * (-(tx - vp.X / 2) / pps))
							end
						end
					end
				end



				if PlayerData[lP.Name] and PlayerData[lP.Name].FPerson then
					st.cur = st.cur:Lerp(target, 1 - math.exp(-math.min(dt, 0.25) * 8))
					st.last, st.base, st.seen, st.foreignAt = nil, nil, hum.CameraOffset, os.clock()
					Function._camShiftCur = st.cur
					return
				end
				local w = Function.camShiftStep(st, hum.CameraOffset, target, dt, os.clock())
				if w then hum.CameraOffset = w end
				Function._camShiftCur = st.cur
			end
		end
		RS:BindToRenderStep("RCCamShift", Enum.RenderPriority.Camera.Value - 1, function(dt)
			pcall(wheelStep)
			local ok = pcall(mainStep, dt)
			if not ok then st.cur = Vector3.zero; Function._camShiftCur = nil end
		end)
	end
	Function._camShiftStart()
end
end)()
end
]====],
    ["engine/weld_helpers"] = [====[return function(P)
local _rawPcall, _rcPcallSink, _rcPcallRet, pcall, PS, RS, HS, DB, UIS, TS, MPS, MS, _RC_VER, _RC_VER_DATE = P._rawPcall, P._rcPcallSink, P._rcPcallRet, P.pcall, P.PS, P.RS, P.HS, P.DB, P.UIS, P.TS, P.MPS, P.MS, P._RC_VER, P._RC_VER_DATE
return (function()


return function(R, I)
local Function, Player, PlayerData, RECLONE_MAX_PER_WINDOW, RECLONE_WINDOW_SECONDS, System, reCloneBudget = I.Function, I.Player, I.PlayerData, I.RECLONE_MAX_PER_WINDOW, I.RECLONE_WINDOW_SECONDS, I.System, I.reCloneBudget







	function Function.BlockyProxyOffset(New, BasePart)
		local char = BasePart and BasePart.Parent
		if not char then return nil end
		local function att(partName, attName)
			local p = char:FindFirstChild(partName)
			local a = p and p:FindFirstChild(attName)
			if not (a and a:IsA("Attachment") and p:IsA("BasePart")) then return nil end
			local os = p:FindFirstChild("OriginalSize")
			local s = (os and os.Value.X > 0 and os.Value.Y > 0 and os.Value.Z > 0) and (p.Size / os.Value) or Vector3.one
			return a.Position / s, p, s
		end
		local side = (New == "Left Arm" or New == "Left Leg") and "Left" or ((New == "Right Arm" or New == "Right Leg") and "Right") or nil
		local sx = (side == "Left") and -1 or 1
		local d
		if New == "Torso" then
			local nk = att("UpperTorso", "NeckRigAttachment")
			if not nk then return nil end
			d = nk - Vector3.new(0, 0.8, 0)
		elseif side and New == side .. " Arm" then
			local nk = att("UpperTorso", "NeckRigAttachment")
			local sh = att("UpperTorso", side .. "ShoulderRigAttachment")
			local uSh = att(side .. "UpperArm", side .. "ShoulderRigAttachment")
			local uEl = att(side .. "UpperArm", side .. "ElbowRigAttachment")
			local lEl = att(side .. "LowerArm", side .. "ElbowRigAttachment")
			if not (nk and sh and uSh and uEl and lEl) then return nil end

			d = (Vector3.new(sx, -0.24, 0) - (sh - nk)) + (Vector3.new(0.5 * sx, -0.72, 0) - (uEl - uSh)) + (lEl - Vector3.new(0, 0.26, 0))
		elseif side then
			local hp = att("LowerTorso", side .. "HipRigAttachment")
			local uHp = att(side .. "UpperLeg", side .. "HipRigAttachment")
			local uKn = att(side .. "UpperLeg", side .. "KneeRigAttachment")
			local lKn = att(side .. "LowerLeg", side .. "KneeRigAttachment")
			if not (hp and uHp and uKn and lKn) then return nil end
			local chain = (Vector3.new(0.5 * sx, -0.2, 0) - hp) + (Vector3.new(0, -0.82, 0) - (uKn - uHp)) + (lKn - Vector3.new(0, 0.38, 0))

			local dy = 0
			local lAn = att(side .. "LowerLeg", side .. "AnkleRigAttachment")
			local fAn, foot, fs = att(side .. "Foot", side .. "AnkleRigAttachment")
			if lAn and fAn then dy = (lAn.Y - fAn.Y - foot.Size.Y / fs.Y / 2) + 0.8 end
			d = Vector3.new(chain.X, dy, chain.Z)
		end
		if not d or d.Magnitude < 0.05 or d.Magnitude > 3 then return nil end
		return d
	end



	function Function._accApplyScale(handle, scale)
		scale = math.clamp(tonumber(scale) or 1, 0.2, 5)
		local base = handle:GetAttribute("RCBaseSize")
		if typeof(base) ~= "Vector3" then
			if scale == 1 then return end
			base = handle.Size; handle:SetAttribute("RCBaseSize", base)
		end
		local want = base * scale
		if (handle.Size - want).Magnitude > 1e-3 then handle.Size = want end
		local sm = handle:FindFirstChildOfClass("SpecialMesh")
		if sm then
			local bm = handle:GetAttribute("RCBaseMeshScale")
			if typeof(bm) ~= "Vector3" then bm = sm.Scale; handle:SetAttribute("RCBaseMeshScale", bm) end
			local wm = bm * scale
			if (sm.Scale - wm).Magnitude > 1e-3 then sm.Scale = wm end
		end
	end

	function Function.MultiplyCalculate(Base, Default)

		if not (Base and Default) then return 1, 1, 1 end
		local X = (Default.X and Default.X ~= 0) and (Base.X / Default.X) or 1
		local Y = (Default.Y and Default.Y ~= 0) and (Base.Y / Default.Y) or 1
		local Z = (Default.Z and Default.Z ~= 0) and (Base.Z / Default.Z) or 1

		return X,Y,Z
	end

	function Function.UIStrokeCreate(Parent)
		if typeof(Parent) ~= "Instance" then return end
		local UIStroke = Instance.new("UIStroke")
		UIStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
		UIStroke.Color = Color3.fromRGB(255, 255, 255)
		UIStroke.Thickness = 1
		UIStroke.Transparency = 0
