		return not (type(pd.FullBodyMesh) == "table" and pd.FullBodyMesh[field])
	end




	function Function._catBodyPaint(c, name, Character, Extra, Data)
		local pd = PlayerData[Data]
		if not (pd and type(pd.CurrentClothes) == "table" and type(Extra) == "table") then return end
		local sa = c:FindFirstChildOfClass("SurfaceAppearance")
		if sa and not (sa:GetAttribute("RoClothesShirt") or sa:GetAttribute("RoClothesPants")) then return end
		local region = Function._catBodyRegion[name]
		local pants = region == "Left Leg" or region == "Right Leg"
		if name == "LowerTorso" then
			pants = Extra.Pants ~= nil and (Extra.Pants.PantsTemplate or "") ~= "" and table.find(pd.CurrentClothes, "Roblox Pants") ~= nil
