		local model = Function._catBodyModels[key]
		if not model then
			local okM, m = pcall(function() return game:GetService("Players"):CreateHumanoidModelFromDescription(hd, Enum.HumanoidRigType.R15) end)
			hd:Destroy()
			if not okM or not m then
				warn("[RoClothes] catalog Full Body could not be built:", tostring(m))


				Function._catBodyFail[Function._catBodyIdsKey(ids)] = os.clock()
				if Data == ((System.getSelectPlayer and System.getSelectPlayer()) or Player.Name) and System.hotSwap then task.defer(System.hotSwap) end
