local System = I.System










System.StaffThemes.TAGS.starfall = function(K, head, C1, C2)
	local W, BLACK = Color3.new(1, 1, 1), Color3.new(0, 0, 0)
	local STAR, VIO = Color3.fromRGB(255, 236, 200), Color3.fromRGB(150, 110, 255)
	local NS, NK, CS, CK, NR = NumberSequence.new, NumberSequenceKeypoint.new, ColorSequence.new, ColorSequenceKeypoint.new, NumberRange.new
	local function c01(x) return math.clamp(x, 0, 1) end
	local function outQ(x) x = c01(x) return 1 - (1 - x) * (1 - x) end
	local L_outQ = outQ
	local function rnd(a, b) return a + math.random() * (b - a) end
	local ch = System.StaffThemes._tagCh or {}
	local FONT = Font.new("rbxasset://fonts/families/Michroma.json", Enum.FontWeight.Bold)
	local Wd, Hd, OFF = 10, 4.2, 4.1
	local bb = K.board(head, Wd, Hd, OFF)
	bb:SetAttribute("RCBadgeTop", 0.4)
	local function at(x, y, w, h) return UDim2.fromScale(x / Wd, y / Hd), UDim2.fromScale(w / Wd, (h or w) / Hd) end
	local A5 = Vector2.new(0.5, 0.5)

	local PX, PY, PW, PH = 5, 2.5, 8.4, 1.3
	local glow = K.img(bb, { Image = K.T("glowui.png"), ImageColor3 = C2, ImageTransparency = 1, AnchorPoint = A5, ZIndex = 0 })
	local rim = K.frame(bb, { BackgroundTransparency = 0, BackgroundColor3 = W, AnchorPoint = A5, ZIndex = 1 })
	K.new("UICorner", { CornerRadius = UDim.new(0.5, 0) }, rim)
	local rimG = K.new("UIGradient", { Color = CS({ CK(0, C2), CK(0.45, STAR), CK(0.55, STAR), CK(1, C2) }) }, rim)
	local plate = K.frame(bb, { BackgroundTransparency = 0, BackgroundColor3 = W, AnchorPoint = A5, ZIndex = 2, ClipsDescendants = true })
	K.new("UICorner", { CornerRadius = UDim.new(0.5, 0) }, plate)
	K.new("UIGradient", { Color = CS({ CK(0, C1:Lerp(BLACK, 0.5)), CK(0.5, C1:Lerp(VIO, 0.3)), CK(1, C1:Lerp(BLACK, 0.5)) }) }, plate)

	local neb = {}
	for i, col in ipairs({ C2, VIO, C1:Lerp(VIO, 0.6) }) do
		neb[i] = K.img(plate, { Image = K.T("glowui.png"), ImageColor3 = col, ImageTransparency = 1, AnchorPoint = A5, ZIndex = 2, Size = UDim2.fromScale(0.45, 1.7) })
	end

	local cMet = {}
	for i = 1, 3 do local f, set = K.seg(bb, Wd, Hd, STAR, 1, 3) cMet[i] = { f = f, set = set, t = -1 } end
	local nextC, jf, eb, wasE = 1.5, 0, 0, false

	local field = {}
	for n = 1, 22 do
		field[n] = { f = K.frame(plate, { BackgroundTransparency = 1, BackgroundColor3 = n % 4 == 0 and C2:Lerp(STAR, 0.4) or W, AnchorPoint = A5, ZIndex = 3 }),
			x = rnd(0, 1), y = rnd(0.12, 0.88), v = rnd(0.12, 0.35), s = rnd(0.035, 0.08), ph = rnd(0, 6) }
		K.new("UICorner", { CornerRadius = UDim.new(0.5, 0) }, field[n].f)
	end

	local sTail, sSet = K.seg(plate, PW, PH, STAR, 1, 4)
	K.new("UIGradient", { Transparency = NS({ NK(0, 1), NK(1, 0) }), Color = CS(C2, STAR) }, sTail)
	local sHead = K.img(plate, { Image = K.T("flare.png"), ImageColor3 = STAR, AnchorPoint = A5, ZIndex = 5, ImageTransparency = 1 })
	local nextS, sT, sY = 3, -1, 0.3





	local BASE = "STARFALL"
	local NL = #BASE
	local LW, LH = PW * 0.84 / NL, PH * 0.6
	local GL = {}
	for i = 1, NL do
		local g = { ch = BASE:sub(i, i), fl = -1, ph = i * 0.7 }
		g.echo = K.text(bb, { AnchorPoint = A5, Text = g.ch, FontFace = FONT, TextColor3 = VIO, ZIndex = 5, TextTransparency = 1 })
		g.l = K.text(bb, { AnchorPoint = A5, Text = g.ch, FontFace = FONT, TextColor3 = W, ZIndex = 6, TextTransparency = 1 })
		K.new("UIGradient", { Rotation = 90, Color = CS({ CK(0, W), CK(0.55, STAR), CK(1, C2:Lerp(STAR, 0.35)) }) }, g.l)
		g.st = K.new("UIStroke", { Color = C2, Thickness = 2, Transparency = 1 }, g.l)
		GL[i] = g
	end
	local EM = { en = ch.sEmoteN or 0, beat = ch.sBeat or 0, beatK = 0, beatT = 0, roll = -1, glint = -3 }
	local function padP(str)
		str = str:sub(1, NL)
		local l = math.floor((NL - #str) / 2)
		return string.rep(" ", l) .. str .. string.rep(" ", NL - #str - l)
	end
	local UW = math.clamp(#K.NAME * 0.3 + 1, 2.4, 7)
	local uPill = K.frame(bb, { BackgroundTransparency = 1, BackgroundColor3 = W, AnchorPoint = A5, ZIndex = 3 })
	uPill.Position, uPill.Size = at(PX, 3.62, UW, 0.56)
	K.new("UICorner", { CornerRadius = UDim.new(0.5, 0) }, uPill)
	K.new("UIGradient", { Color = CS({ CK(0, C1:Lerp(BLACK, 0.55)), CK(0.5, C1:Lerp(VIO, 0.25):Lerp(BLACK, 0.3)), CK(1, C1:Lerp(BLACK, 0.55)) }) }, uPill)
	local role = K.text(uPill, { AnchorPoint = A5, Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromScale(0.84, 0.62), Text = K.NAME,
		FontFace = Font.new("rbxasset://fonts/families/Michroma.json", Enum.FontWeight.Regular), TextColor3 = STAR, ZIndex = 4, TextTransparency = 1 })

	local uStar = {}
	for i = 1, 2 do uStar[i] = K.img(bb, { Image = K.T("star.png"), ImageColor3 = C2:Lerp(STAR, 0.4), AnchorPoint = A5, ZIndex = 4, ImageTransparency = 1 }) end

	local N = 5
	local stars, glows, segP, segS = {}, {}, {}, {}
	for i = 1, N do
		glows[i] = K.img(bb, { Image = K.T("glowui.png"), ImageColor3 = C2, AnchorPoint = A5, ZIndex = 1, ImageTransparency = 1 })
		stars[i] = K.img(bb, { Image = K.T("star.png"), ImageColor3 = STAR, AnchorPoint = A5, ZIndex = 4, ImageTransparency = 1 })
		segP[i] = { K.seg(bb, Wd, Hd, STAR, 1, 3) }
		segS[i] = { K.seg(bb, Wd, Hd, C2, 1, 2) }
	end

	local eP = K.emitterAt(Vector3.new(0, OFF - (PY - Hd / 2), 0), { Texture = K.T("star.png"), Rate = 16, Lifetime = NR(0.6, 1.1), Speed = NR(0.3, 0.9),
		SpreadAngle = Vector2.new(180, 180), Size = NS({ NK(0, 0), NK(0.3, 0.22), NK(1, 0) }), Color = CS(STAR, C2), Brightness = 4, ZOffset = 1,
		Rotation = NR(0, 360), box = Vector3.new(PW + 0.2, PH + 0.2, 0.2) })
	K.emitterAt(Vector3.new(0, OFF + (Hd / 2 - 0.95), 0), { Texture = K.T("star.png"), Rate = 8, Lifetime = NR(0.8, 1.4), Speed = NR(0.1, 0.4),
		SpreadAngle = Vector2.new(180, 180), Size = NS({ NK(0, 0), NK(0.5, 0.3), NK(1, 0) }), Color = CS(STAR), Brightness = 3, Rotation = NR(0, 360),
		box = Vector3.new(6, 0.8, 0.2) })

	return function(t, dt, it)

		local span = math.max(outQ(it / 0.45), 0.02)
		plate.Position, plate.Size = at(PX, PY, PW * span, PH)
		rim.Position, rim.Size = at(PX, PY, PW * span + 0.18, PH + 0.18)
		glow.Position, glow.Size = at(PX, PY, (PW + 2.4) * span, PH + 1.8)
		glow.ImageTransparency = 1 - 0.55 * span * (0.85 + 0.15 * math.sin(t * 2))
		rimG.Offset = Vector2.new(((t * 0.35) % 2) - 1, 0)

		if ch.jumped then jf = 1 end
		if ch.emote and not wasE then eb = 1 eP:Emit(40) end
		wasE = ch.emote == true
		jf = math.max(0, jf - dt * 2)
		eb = math.max(0, eb - dt * 0.8)
		glow.ImageColor3 = C2:Lerp(STAR, jf)
		local fa = c01((it - 0.35) / 0.4)
		for i, g in ipairs(neb) do
			g.Position = UDim2.fromScale(0.5 + 0.38 * math.sin(t * 0.13 * i + i * 2), 0.5 + 0.25 * math.sin(t * 0.21 * i + i))
			g.ImageTransparency = 1 - fa * (0.4 + 0.15 * math.sin(t * 0.7 + i))
		end
		for _, s in ipairs(field) do
			s.x -= s.v * dt / PW * (1 + 4 * eb)
			if s.x < -0.02 then s.x = 1.02 s.y = rnd(0.12, 0.88) end
			local tw = 0.5 + 0.5 * math.sin(t * 3 + s.ph)
			local sz = s.s * (0.7 + 0.5 * tw) * (1 + 1.5 * eb)
			s.f.Position, s.f.Size = UDim2.fromScale(s.x, s.y), UDim2.fromScale(sz / PW, sz / PH)
			s.f.BackgroundTransparency = 1 - fa * math.min(1, 0.35 + 0.65 * tw + eb)
		end
		nextS -= dt
		if nextS <= 0 and it > 1.5 then nextS = rnd(4.5, 6) sT = 0 sY = rnd(0.15, 0.45) end
		if sT >= 0 then
			sT += dt
			local k = sT / 0.8
			if k > 1 then sT = -1 sHead.ImageTransparency, sTail.BackgroundTransparency = 1, 1
			else
				local x0, y0, x1, y1 = -0.5, sY * PH, PW + 0.5, (sY + 0.45) * PH
				local hx, hy = x0 + (x1 - x0) * k, y0 + (y1 - y0) * k
				local dx, dy = x1 - x0, y1 - y0
				local d = math.sqrt(dx * dx + dy * dy)
				sSet(hx - dx / d * 2.4, hy - dy / d * 2.4, hx, hy, 0.08)
				sHead.Position, sHead.Size = UDim2.fromScale(hx / PW, hy / PH), UDim2.fromScale(0.6 / PW, 0.6 / PH)
				local a = math.sin(k * math.pi)
				sHead.ImageTransparency, sTail.BackgroundTransparency = 1 - a, 1 - a * 0.9
			end
		end

		if (ch.sEmoteN or 0) ~= EM.en then EM.en, EM.roll = ch.sEmoteN or 0, 0 eP:Emit(20) end
		if (ch.sBeat or 0) ~= EM.beat then EM.beat, EM.beatK, EM.beatT = ch.sBeat or 0, 1, 0 end
		EM.beatK = math.max(0, EM.beatK - dt * 3)
		EM.beatT += dt
		if EM.roll >= 0 then EM.roll += dt if EM.roll > 1.2 then EM.roll = -1 end end
		EM.glint += dt
		if EM.glint > 4.5 then EM.glint = -rnd(0, 1.5) end
		local want = ch.sPhrase and padP(ch.sPhrase) or BASE
		for i, g in ipairs(GL) do
			local wc = want:sub(i, i)
			if g.fl == -1 and wc ~= g.ch then g.fl = -(i - 1) * 0.045 - 0.0001 g.to = wc end
			local sy = 1
			if g.fl ~= -1 then
				g.fl += dt
				if g.fl >= 0 then
					local f = g.fl / 0.22
					if f >= 0.5 and g.ch ~= g.to then g.ch = g.to g.l.Text, g.echo.Text = g.ch, g.ch end
					sy = math.abs(math.cos(math.min(f, 1) * math.pi))
					if f >= 1 then g.fl = -1 end
				end
			end
			local lIn = c01((it - 0.55 - i * 0.05) / 0.25)
			local pop = 1 + 0.35 * math.sin(lIn * math.pi)
			local wv = math.sin(c01(EM.beatT * 3 - (i - 1) * 0.08) * math.pi) * EM.beatK
			local x = PX - PW * 0.42 + (i - 0.5) * LW
			local y = PY - 0.16 * wv + 0.025 * math.sin(t * 2.4 + g.ph)
			local rot = EM.roll >= 0 and 360 * L_outQ(c01((EM.roll - i * 0.05) / 0.6)) or 0
			local gk = math.max(0, 1 - math.abs(EM.glint * 2.2 - i * 0.35) * 2)
			g.l.Position, g.l.Size = at(x, y, LW * pop * (1 + 0.15 * wv), LH * pop * sy * (1 + 0.15 * wv))
			g.l.Rotation = rot
			g.l.TextTransparency = 1 - lIn
			g.st.Transparency = 1 - lIn * (0.8 + 0.2 * math.sin(t * 3))
			g.st.Color, g.st.Thickness = C2:Lerp(STAR, math.max(jf, gk)), 2 + 2 * jf + 1.5 * gk
			g.echo.Position, g.echo.Size = at(x + 0.06 + 0.03 * math.sin(t * 1.3), y + 0.05, LW * pop, LH * pop * sy)
			g.echo.Rotation = rot
			g.echo.TextTransparency = 1 - 0.55 * lIn
		end
		local ua = c01((it - 0.8) / 0.4)
		role.TextTransparency = 1 - ua
		uPill.BackgroundTransparency = 1 - 0.85 * ua
		for i, st in ipairs(uStar) do
			st.Position, st.Size = at(PX + (i == 1 and -1 or 1) * (UW / 2 + 0.05), 3.62, 0.42 * (0.85 + 0.15 * math.sin(t * 4 + i * 2)))
			st.Rotation = t * 40 * (i == 1 and 1 or -1)
			st.ImageTransparency = 1 - ua * (0.6 + 0.3 * math.sin(t * 3 + i))
		end

		local spin = t * 0.45
		local cx, cy, rx, ry = Wd / 2, 0.95, 2.9, 0.34
		local pts = {}
		for i = 1, N do
			local a = spin + (i - 1) * math.pi * 2 / N
			local depth = math.sin(a)
			local x, y = cx + math.cos(a) * rx, cy + depth * ry + 0.06 * math.sin(t * 2 + i)
			local lit = c01((it - 0.3 - (i - 1) * 0.15) / 0.22)
			local pop = math.sin(lit * math.pi) * 0.8
			local tw = 0.75 + 0.25 * math.sin(t * 5.3 + i * 1.7)
			local s = (0.62 + 0.18 * depth) * (0.4 + 0.6 * lit + pop)
			stars[i].Position, stars[i].Size = at(x, y, s)
			stars[i].ImageTransparency = 1 - lit * (0.6 + 0.4 * tw) * (0.8 + 0.2 * depth)
			stars[i].Rotation = t * 20 + i * 30
			stars[i].ZIndex = depth > 0 and 4 or 2
			glows[i].Position, glows[i].Size = at(x, y, s * 3.4)
			glows[i].ImageTransparency = 1 - lit * 0.55 * tw
			pts[i] = { x, y }
		end
		local la = c01((it - 1.1) / 0.5)
		local pulse = (t * 1.6) % N
		for i = 1, N do
			local p, q, r = pts[i], pts[i % N + 1], pts[(i + 1) % N + 1]
			local d = math.abs(pulse - (i - 0.5))
			local hot = math.max(0, 1 - math.min(d, N - d))
			segP[i][2](p[1], p[2], q[1], q[2], 0.06 + 0.04 * hot)
			segP[i][1].BackgroundTransparency = 1 - la * (0.55 + 0.45 * hot)
			segS[i][2](p[1], p[2], r[1], r[2], 0.035)
			segS[i][1].BackgroundTransparency = 1 - 0.3 * la * (0.7 + 0.3 * math.sin(t * 3 + i))
		end

		nextC -= dt
		if nextC <= 0 and la >= 1 then
			nextC = rnd(1.4, 2.6)
			for _, m in ipairs(cMet) do
				if m.t < 0 then
					local p = pts[math.random(1, N)]
					m.t, m.x, m.y = 0, p[1], p[2]
					m.dx, m.dy = (p[1] < Wd / 2 and -1 or 1) * rnd(0.6, 1.2), rnd(0.5, 0.9)
					break
				end
			end
		end
		for _, m in ipairs(cMet) do
			if m.t >= 0 then
				m.t += dt
				local k = m.t / 0.5
				if k > 1 then m.t = -1 m.f.BackgroundTransparency = 1
				else
					local hx, hy = m.x + m.dx * k, m.y + m.dy * k
					m.set(hx - m.dx * 0.35, hy - m.dy * 0.35, hx, hy, 0.05)
					m.f.BackgroundTransparency = 1 - math.sin(k * math.pi) * 0.9
				end
			end
		end
	end
end

System.StaffThemes.THEMES.starfall = function(L, C)
	local C1, C2, W = C.c1, C.c2, L.W
	local NS, CS, NR, K, CK = L.NS, L.CS, L.NR, L.K, L.CK
	local ch, rnd, c01 = L.ch, L.rnd, L.c01
	local STAR, VIO, GREY = Color3.fromRGB(255, 236, 200), Color3.fromRGB(150, 110, 255), Color3.fromRGB(85, 85, 95)
	local NEON, BALL = Enum.Material.Neon, Enum.PartType.Ball
	local function sc() return ch.sc or 1 end


	L.cine.starfall = { font = L.fam("Michroma"), sub = L.fam("Michroma"), kick = "S T A R F A L L", subText = "H A S   L A N D E D", stroke = C1,
		grad = function(_, c2) return CS({ CK(0, W), CK(0.5, STAR), CK(1, c2) }) end,
		card = function(Cd)
			local HIT = 0.38
			local head = L.new("Frame", { BorderSizePixel = 0, BackgroundColor3 = W, AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(14, 14), ZIndex = 9 }, Cd.card)
			L.new("UICorner", { CornerRadius = UDim.new(1, 0) }, head)
			local tail, setTail = L.segPx(Cd.card, C2, 8)
			L.new("UIGradient", { Color = CS(VIO, C2), Transparency = NS({ K(0, 1), K(1, 0) }) }, tail)
			local fl = L.new("Frame", { BorderSizePixel = 0, BackgroundColor3 = STAR, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, Cd.CY),
				Size = UDim2.fromScale(0.7, 0.16), BackgroundTransparency = 1, ZIndex = 5 }, Cd.card)
			L.new("UICorner", { CornerRadius = UDim.new(1, 0) }, fl)
			L.new("UIGradient", { Transparency = NS({ K(0, 1), K(0.5, 0), K(1, 1) }) }, fl)
			local sparks = {}
			for i = 1, 14 do
				local f = L.new("Frame", { BorderSizePixel = 0, BackgroundColor3 = i % 2 == 0 and STAR or C2, AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(5, 5),
					BackgroundTransparency = 1, ZIndex = 9 }, Cd.card)
				L.new("UICorner", { CornerRadius = UDim.new(1, 0) }, f)
				local a = rnd(-math.pi, 0)
				sparks[i] = { f = f, vx = math.cos(a) * rnd(160, 420), vy = math.sin(a) * rnd(120, 300) }
			end
			local stamped = false
			return function(tt, a, out)
				local V = L.vp()
				local ex, ey = 0.5 * V.X, Cd.CY * V.Y
				local sx, sy = 1.05 * V.X, (Cd.CY - 0.45) * V.Y
				if tt < HIT then
					local u = L.inQuad(tt / HIT)
					local x, y = sx + (ex - sx) * u, sy + (ey - sy) * u
					head.Position = UDim2.fromOffset(x, y)
					local bx, by = sx + (ex - sx) * math.max(0, u - 0.35), sy + (ey - sy) * math.max(0, u - 0.35)
					setTail(bx, by, x, y, 8)
					Cd.nm.TextTransparency, Cd.nst.Transparency = 1, 1
					Cd.box.Size = UDim2.fromScale(0.62, 0.085)
				else
					if not stamped then
						stamped = true
						Cd.S:shake(2.5, 0.35)
						for _, sp in ipairs(sparks) do sp.f.Position = UDim2.fromOffset(ex, ey) end
					end
					local k = tt - HIT
					head.BackgroundTransparency, tail.BackgroundTransparency = 1, 1

					local z = 1 + 0.6 * (1 - L.outBack(k / 0.3))
					Cd.box.Size = UDim2.fromScale(0.62 * z, 0.085 * z)
					Cd.nm.TextTransparency = (1 - c01(k / 0.08)) + (1 - out)
					fl.BackgroundTransparency = 0.1 + 0.9 * c01(k / 0.5)
					fl.Size = UDim2.fromScale(0.7 + 0.5 * L.outQuad(c01(k / 0.5)), 0.16 * (1 - 0.5 * c01(k / 0.5)))
					local d = L.lastDt or 0.016
					for _, sp in ipairs(sparks) do
						sp.vy += 700 * d
						sp.f.Position = sp.f.Position + UDim2.fromOffset(sp.vx * d, sp.vy * d)
						sp.f.BackgroundTransparency = c01(k / 0.8)
					end
				end
			end
		end }



	local ringA, ringAm = L.mesh("disc.mesh", "ring_c.png", C2, 2.6, Vector3.new(4.4, 1, 4.4))
	local ringB, ringBm = L.mesh("disc.mesh", "ring_c.png", STAR, 2.2, Vector3.new(5.3, 1, 5.3))
	local ringP = L.part({ Size = Vector3.new(4.8, 0.2, 4.8) })
	local DUST = { Texture = L.T("star.png"), LockedToPart = true, Speed = NR(0, 0.15), Acceleration = Vector3.zero, Lifetime = NR(1.2, 2.2),
		Size = NS({ K(0, 0), K(0.2, 0.32), K(0.5, 0.16), K(0.8, 0.3), K(1, 0) }), Transparency = NS(0), Color = CS(STAR, C2:Lerp(STAR, 0.4)) }

	local BUBBLE = { Texture = L.T("ring_b.png"), LockedToPart = false, Speed = NR(0.6, 1.4), Acceleration = Vector3.new(0, 1.2, 0), Lifetime = NR(1.4, 2.4),
		Size = NS({ K(0, 0.12), K(1, 0.5) }), Transparency = NS({ K(0, 0.2), K(1, 1) }), Color = CS(STAR, VIO) }
	local dust = L.pe(ringP, { Shape = Enum.ParticleEmitterShape.Disc, ShapePartial = 0.8, ShapeStyle = Enum.ParticleEmitterShapeStyle.Volume,
		EmissionDirection = Enum.NormalId.Top, Rate = 45, Rotation = NR(0, 360), RotSpeed = NR(-40, 40), Brightness = 4 })
	for k, v in pairs(DUST) do dust[k] = v end

	local comets = {}
	for i, d in ipairs({ { r = 2.8, w = 2.2, h = 0.05 }, { r = 3.3, w = -1.6, h = -0.1 }, { r = 3.05, w = 2.9, h = 0.14 } }) do
		local head = L.part({ Shape = BALL, Material = NEON, Color = i == 2 and C2:Lerp(STAR, 0.5) or STAR, Transparency = 0, Size = Vector3.one * 0.32 })
		local a0 = L.new("Attachment", { Position = Vector3.new(0, 0.14, 0) }, head)
		local a1 = L.new("Attachment", { Position = Vector3.new(0, -0.14, 0) }, head)
