	local rig, trail, edgeT, edgeB, glow = {}, nil, nil, nil, nil
	local function rebind()
		for _, o in ipairs(rig) do pcall(function() o:Destroy() end) end
		rig = {}
		local hrp = ch.hrp
		if not hrp then return end
		local s, fy = sc(), ch.fy or -3
		local function att(y) return L.new("Attachment", { Position = Vector3.new(0, y, 0.2) }, hrp) end
		local a0, a1 = att(fy + 0.25 * s), att(fy + 1.3 * s)
		local e0, e1 = att(fy + 1.25 * s), att(fy + 1.45 * s)
		local b0, b1 = att(fy + 0.1 * s), att(fy + 0.3 * s)
		local function trl(x0, x1, p) p.Attachment0, p.Attachment1 = x0, x1 return L.new("Trail", p, hrp) end
		trail = trl(a0, a1, { Texture = L.T("beamb.png") or "", LightEmission = 1, Brightness = 3, Lifetime = 0.55, FaceCamera = true, Enabled = false,
			Color = CS({ CK(0, STAR), CK(0.4, C2), CK(1, VIO) }), Transparency = NS({ K(0, 0.35), K(1, 1) }), WidthScale = NS({ K(0, 1), K(1, 0.2) }) })

		local EDGE = { Texture = L.T("beamb.png") or "", LightEmission = 1, Brightness = 6, Lifetime = 0.4, FaceCamera = true, Enabled = false,
			Color = CS(STAR, C2), Transparency = NS({ K(0, 0), K(1, 1) }) }
		edgeT = trl(e0, e1, table.clone(EDGE))
		edgeB = trl(b0, b1, table.clone(EDGE))
		glow = L.new("PointLight", { Color = STAR, Range = 12 * s, Brightness = 1.2, Shadows = false }, ch.torso or hrp)

		local k0 = L.new("Attachment", { Position = Vector3.new(0, 1.4 * s, 0.55) }, hrp)
		local k1 = L.new("Attachment", { Position = Vector3.new(0, -0.7 * s, 0.55) }, hrp)
		local cape = trl(k0, k1, { Texture = L.T("beamb.png") or "", LightEmission = 0.8, Brightness = 2, Lifetime = 0.8, FaceCamera = true, Enabled = false,
			Color = CS({ CK(0, VIO:Lerp(STAR, 0.3)), CK(0.5, VIO), CK(1, C1) }), Transparency = NS({ K(0, 0.45), K(1, 1) }) })
		rig = { a0, a1, e0, e1, b0, b1, k0, k1, trail, edgeT, edgeB, cape, glow }
		rig.cape = cape

		chain = {}
		local c = ch.char
		if c then
			local R15 = { { "UpperTorso", "LeftUpperArm", "LeftLowerArm", "LeftHand" }, { "UpperTorso", "RightUpperArm", "RightLowerArm", "RightHand" },
				{ "LowerTorso", "LeftUpperLeg", "LeftLowerLeg", "LeftFoot" }, { "LowerTorso", "RightUpperLeg", "RightLowerLeg", "RightFoot" } }
			local R6 = { { "Torso", "Left Arm" }, { "Torso", "Right Arm" }, { "Torso", "Left Leg" }, { "Torso", "Right Leg" }, { "Torso", "Head" } }
			for _, list in ipairs(c:FindFirstChild("UpperTorso") and R15 or R6) do
				for i = 1, #list - 1 do
					local pa, pb = c:FindFirstChild(list[i]), c:FindFirstChild(list[i + 1])
					if pa and pb and pa:IsA("BasePart") and pb:IsA("BasePart") and #chain < #cDots then chain[#chain + 1] = { pa, pb } end
				end
			end
		end
	end
	rebind()

