	System.StaffThemes._tagCh = nil



	local held = nil
	local spiralT = 99
	local dying = false
	local deathGone = nil
	local haloFlare = 0
	local asmT, asmPrev = 99, 99
	local function hide(on)
		if on then
			held = held or {}
			for d in pairs(L.bodyParts()) do if not held[d] then held[d] = true d.LocalTransparencyModifier = 1 end end
		elseif held then
			for d in pairs(held) do if d.Parent then pcall(function() d.LocalTransparencyModifier = 0 end) end end
			held = nil
			spiralT = 0
		end
	end


	local function fly(path, dur, s, hit, tailLife, tailCol)
		tailLife = tailLife or 0.4
		local p0 = path(0)
		local head = L.part({ Shape = BALL, Material = NEON, Color = W, Transparency = 0, Size = Vector3.one * s * 0.45, CFrame = CFrame.new(p0) })
		local glowE = L.pe(head, { Texture = L.T("smoke.png"), LockedToPart = true, Rate = 14, Lifetime = NR(0.15, 0.25), Speed = NR(0), Size = NS(2.6 * s),
			Transparency = NS(0.6), Color = CS(C2, C2:Lerp(VIO, 0.5)), LightEmission = 1, Brightness = 1.2, Rotation = NR(0, 360) })
		local flameE = L.pe(head, { Texture = L.T("flamefb.png"), FlipbookLayout = Enum.ParticleFlipbookLayout.Grid4x4, FlipbookMode = Enum.ParticleFlipbookMode.OneShot,
			Rate = 28, Lifetime = NR(0.25, 0.45), Speed = NR(0.5, 1.5), SpreadAngle = Vector2.new(180, 180), Size = NS({ K(0, 1.1 * s), K(0.4, 2 * s), K(1, 1.2 * s) }),
			Transparency = NS({ K(0, 0.3), K(0.15, 0), K(0.75, 0.2), K(1, 1) }), Color = CS({ CK(0, STAR), CK(0.4, C2), CK(1, Color3.fromRGB(140, 40, 60)) }),
			LightEmission = 0.8, Brightness = 3, Rotation = NR(-20, 20), RotSpeed = NR(-30, 30) })
		local a0 = L.new("Attachment", { Position = Vector3.new(0, s * 0.5, 0) }, head)
		local a1 = L.new("Attachment", { Position = Vector3.new(0, -s * 0.5, 0) }, head)
		local tr = L.new("Trail", { Attachment0 = a0, Attachment1 = a1, Texture = L.T("beamb.png") or "", LightEmission = 1, Brightness = 6, FaceCamera = true,
			Lifetime = tailLife, MinLength = 0, Color = tailCol or CS({ CK(0, STAR), CK(0.3, C2), CK(1, VIO) }), Transparency = NS({ K(0, 0), K(1, 1) }),
			WidthScale = NS({ K(0, 1.8), K(1, 0) }) }, head)
		local hitDone, last = false, p0
		L.fx(dur + tailLife, function(_, t)
			if t < dur then
				local p = path(t / dur)
				local dir = p - last
				head.CFrame = dir.Magnitude > 1e-3 and CFrame.lookAt(p, p + dir) or CFrame.new(p)
				last = p
			elseif not hitDone then
				hitDone = true
				head.Transparency = 1
				glowE.Rate, flameE.Rate = 0, 0
				glowE:Clear()

				if hit then hit(path(1)) end
			end
		end, { head })
		return head
	end
	local function line(p0, p1) return function(u) return p0:Lerp(p1, u) end end

	local function impact(p, s, light, life)
		L.groundWave(p, "ring_c.png", C2, 0.8 * s, 10 * s, 0.6, 2.4)
		L.groundWave(p, "ring_c.png", STAR, 0.5 * s, 5.5 * s, 0.35, 2.6)
		embP.CFrame = CFrame.new(p + Vector3.new(0, 0.2, 0))
		embers:Emit(math.floor(16 * math.min(s, 3)))
		local rot = rnd(0, 6)
		local sp = L.mesh("disc.mesh", "darkdisc.png", L.BACK, 1, Vector3.new(3.6 * s, 1, 3.6 * s))
		local cr, crm = L.mesh("disc.mesh", "cracks_b.png", C2, 2.4, Vector3.new(3.4 * s, 1, 3.4 * s))
		local gp, gm = L.mesh("disc.mesh", "ring_c.png", C2, 2.4, Vector3.new(2.6 * s, 1, 2.6 * s))
		sp.CFrame = CFrame.new(p + Vector3.new(0, 0.04, 0)) * CFrame.Angles(0, rot, 0)
		cr.CFrame = CFrame.new(p + Vector3.new(0, 0.06, 0)) * CFrame.Angles(0, -rot * 2, 0)
		gp.CFrame = CFrame.new(p + Vector3.new(0, 0.08, 0)) * CFrame.Angles(0, -rot, 0)
		L.fx(life or 3.5, function(k)
			sp.Transparency = 0.25 + 0.75 * c01((k - 0.3) / 0.7)
			cr.Transparency = 0.05 + 0.95 * c01(k * 1.2)
			gp.Transparency = 0.05 + 0.95 * c01(k * 1.5)
			L.tint(crm, C2:Lerp(GREY, k), 2.4 - k)
			L.tint(gm, STAR:Lerp(C2, c01(k * 3)):Lerp(GREY, k), 2.4)
		end, { sp, cr, gp })
		if light then
			flashP.CFrame = CFrame.new(p + Vector3.new(0, 1.5, 0))
			flash.Range = 10 * s
			flash.Brightness = 3
		end
	end

	local function bodyGhost(col, life)
		if not ch.char then return nil end
		local g = L.ghost(col, NEON, life, true)
		local list = {}
		for _, p in ipairs(g:GetChildren()) do
			if p:IsA("BasePart") then p.LocalTransparencyModifier = 0 list[#list + 1] = { p = p, cf = p.CFrame } end
		end
		return list
	end




	local function shortStrike()
		local o, s = L.ground(ch.feet, 3, 8), sc()
		hide(true)
		local f, r = L.facing()
		local from = o - f * 14 * s + r * 8 * s + Vector3.new(0, 55, 0)
		local lp = L.part({ CFrame = CFrame.new(o + Vector3.new(0, 2, 0)) })
		local lt = L.new("PointLight", { Color = C2, Range = 12 * s, Brightness = 0, Shadows = false }, lp)
		local smP = L.part({ Size = Vector3.new(3 * s, 0.4, 3 * s), CFrame = CFrame.new(o + Vector3.new(0, 0.3, 0)) })
		local smoke = L.pe(smP, { Texture = L.T("smoke.png"), Shape = Enum.ParticleEmitterShape.Box, EmissionDirection = Enum.NormalId.Top, Rate = 0,
			Lifetime = NR(1.2, 2), Speed = NR(1.5, 4), Size = NS({ K(0, 2), K(1, 5) }), Transparency = NS({ K(0, 0.45), K(1, 1) }), Color = CS(C2:Lerp(GREY, 0.4), GREY),
			LightEmission = 0.3, Rotation = NR(0, 360), RotSpeed = NR(-30, 30) })
		local debris = L.pe(smP, { Texture = L.T("spark.png"), EmissionDirection = Enum.NormalId.Top, Lifetime = NR(0.7, 1.3), Speed = NR(14, 26),
			SpreadAngle = Vector2.new(60, 60), Acceleration = Vector3.new(0, -40, 0), Size = NS({ K(0, 0.5), K(1, 0) }), Color = CS(STAR, C2),
			Orientation = Enum.ParticleOrientation.VelocityParallel, Squash = NS(-1.4), Brightness = 7 })
		L.timeline(3, function(t, once)
			if held and once("late", 0.3) then hide(true) end

			if once("lock", 0) then L.groundWave(o, "ring_c.png", C2, 12 * s, 2 * s, 0.6, 2.6) L.groundWave(o, "ring_c.png", STAR, 8 * s, 1.5 * s, 0.5, 2.6) end
			if once("m", 0.35) then fly(line(from, o), 0.5, 3 * s, nil, 0.8) end
			if once("hit", 0.85) then
				impact(o, 2.4 * s, false, 4)
				L.groundWave(o, "ring_c.png", W, 1, 20 * s, 0.7, 2.6)
				L.groundWave(o, "ring_c.png", C2, 1, 12 * s, 0.9, 2.4)
				debris:Emit(50)
				smoke.Rate = 30
				lt.Brightness = 4
			end
			if t > 1.4 then smoke.Rate = 0 end
			if once("show", 1.25) then hide(false) burst:Emit(20) end
			lt.Brightness = math.max(0, lt.Brightness - (L.lastDt or 0.016) * 5)
		end, { lp, smP }, function() hide(false) end)
	end


	local function shortForge()
		local s = sc()
		hide(true)
		local N = 20
		local cen = ch.pos + Vector3.new(0, 0.3 * s, 0)
		local pts, objs = {}, {}
		local bodies = {}
		for d in pairs(L.bodyParts()) do if d:IsA("BasePart") then bodies[#bodies + 1] = d end end
		for i = 1, N do

			local y = 1 - (i - 0.5) / N * 2
			local rr = math.sqrt(1 - y * y)
			local th = i * 2.39996
			local d = L.part({ Shape = BALL, Material = NEON, Color = i % 3 == 0 and C2 or STAR, Transparency = 1, Size = Vector3.one * 0.45 * s })
			local sky = cen + Vector3.new(rnd(-30, 30), rnd(35, 55), rnd(-30, 30))
			pts[i] = { d = d, dir = Vector3.new(math.cos(th) * rr, y, math.sin(th) * rr), sky = sky, body = bodies[(i - 1) % math.max(#bodies, 1) + 1], v = Vector3.zero }
			objs[#objs + 1] = d
		end
		local lines = {}
		for i = 1, N do
			local a0, a1 = L.att(), L.att()
			lines[i] = { a0 = a0, a1 = a1, j = (i % N) + 1, k = ((i + 6) % N) + 1,
				b = L.beam(a0, a1, { Width0 = 0.16 * s, Width1 = 0.16 * s, Brightness = 7, FaceCamera = true, Color = CS(STAR, C2), Transparency = NS(1) }) }
			objs[#objs + 1] = a0 objs[#objs + 1] = a1 objs[#objs + 1] = lines[i].b
		end
		local shattered = false
		L.timeline(3, function(t, once)
			if held and once("late", 0.3) then hide(true) end
			local spin = CFrame.Angles(0, t * 3, 0) * CFrame.Angles(t * 0.7, 0, 0)
			local R = 3 * s
			for i, p in ipairs(pts) do
				local onS = cen + spin:VectorToWorldSpace(p.dir) * R
				local pos
				if t < 1 then
					pos = p.sky:Lerp(onS, L.inQuad(c01((t - i * 0.02) / 0.8)))
				elseif t < 2 then
					local k = L.inQuad(c01((t - 1.4) / 0.6))
					local bp = (p.body and p.body.Parent) and p.body.Position or cen
					pos = onS:Lerp(bp, k)
				elseif not shattered then
					pos = p.d.Position
				else
					p.v += Vector3.new(0, -6, 0) * (L.lastDt or 0.016)
					pos = p.d.Position + p.v * (L.lastDt or 0.016)
				end
				p.d.CFrame = CFrame.new(pos)
				p.d.Transparency = shattered and c01((t - 2) / 0.9) or (t < 0.05 and 1 or 0.05)
			end
			for li, ln in ipairs(lines) do
				ln.a0.WorldPosition, ln.a1.WorldPosition = pts[li].d.Position, pts[ln.j].d.Position
				local a = c01((t - 0.7) / 0.4) * (1 - c01((t - 1.9) / 0.1))
				ln.b.Transparency = NS(1 - 0.85 * a)
			end
			if once("flash", 2) then
				shattered = true
				hide(false)
				for _, p in ipairs(pts) do p.v = (p.d.Position - ch.pos).Unit * rnd(6, 12) * s + Vector3.new(0, rnd(2, 6), 0) end
				L.ghost(STAR, NEON, 0.5)
				burst:Emit(30)
				haloFlare = 1
				flashP.CFrame = CFrame.new(ch.pos)
				flash.Range, flash.Brightness = 11 * s, 3.5
				L.groundWave(L.ground(ch.feet, 3, 8), "ring_c.png", STAR, 1, 12 * s, 0.6, 2.6)
			end
		end, objs, function() hide(false) end)
	end


	local function shortRider()
		local o, s = L.ground(ch.feet, 3, 8), sc()
		hide(true)
		local R, H = 7 * s, 2.6 * s
		local a0 = rnd(0, 6.3)
		local function path(u)
			if u < 0.75 then
				local k = u / 0.75
				local a = a0 + k * math.pi * 2.1
				local rr = R * (1.3 - 0.3 * k)
				return o + Vector3.new(math.cos(a) * rr, H + 6 * (1 - k) * s, math.sin(a) * rr)
			end
			local k = (u - 0.75) / 0.25
			local a = a0 + math.pi * 2.1
			local p0 = o + Vector3.new(math.cos(a) * R, H, math.sin(a) * R)
			return p0:Lerp(o + Vector3.new(0, 1.2 * s, 0), L.inQuad(k))
		end
		L.timeline(3, function(t, once)
			if held and once("late", 0.3) then hide(true) end
			if once("c", 0) then fly(path, 1.8, 1 * s, nil, 1.6, CS({ CK(0, STAR), CK(0.3, C2), CK(1, VIO) })) end
			if once("in", 1.8) then
				hide(false)
				L.groundWave(o, "ring_c.png", C2, R * 2.2, 1, 0.45, 2.6)
				L.groundWave(o, "ring_c.png", STAR, R * 1.6, 1, 0.35, 2.6)
				embP.CFrame = CFrame.new(o + Vector3.new(0, 0.6, 0))
				embers:Emit(40)
				burst:Emit(24)
				L.ghost(C2:Lerp(STAR, 0.5), NEON, 0.7)
				flashP.CFrame = CFrame.new(o + Vector3.new(0, 1.5, 0))
				flash.Range, flash.Brightness = 11 * s, 3.5
			end
			if once("wave", 2.05) then L.groundWave(o, "ring_c.png", W, 1, 12 * s, 0.5, 2.6) end
		end, {}, function() hide(false) end)
	end
	local shorts = { shortStrike, shortForge, shortRider }







	local function arriveFull()
		local o, s = L.ground(ch.feet, 3, 8), sc()

		local f, r = L.facing()
		local cam = workspace.CurrentCamera
		local cl = cam and Vector3.new(cam.CFrame.LookVector.X, 0, cam.CFrame.LookVector.Z)
		if cl and cl.Magnitude > 0.1 then f = cl.Unit r = f:Cross(Vector3.yAxis) end
		hide(true)
		local DUR = 10.5
		local S = L.screen(DUR)
		S.style, S.c1, S.c2 = "starfall", C1, C2
		S.dimFn = function(t) return 0.3 * c01(t / 1.2) * (1 - c01((t - 9) / 1.4)) end
		S.tintFn = function(t) return VIO, 0.22 * c01(t / 1.2) * (1 - c01((t - 9) / 1.4)) end
		local sky = L.worldSky(o, DUR, { dome = Color3.fromRGB(12, 9, 34), atmC = Color3.fromRGB(36, 26, 80), decay = Color3.fromRGB(90, 50, 130),
