		local bandN = L.pe(bandP, { Texture = L.T("smoke.png"), Shape = Enum.ParticleEmitterShape.Box, LockedToPart = true, Rate = 0, Lifetime = NR(9, 10), Speed = NR(0),
			Size = NS({ K(0, 14), K(1, 20) }), Transparency = NS({ K(0, 1), K(0.15, 0.6), K(0.85, 0.6), K(1, 1) }), Color = CS(VIO, C2), LightEmission = 1, Brightness = 2,
			Rotation = NR(0, 360) })


		local tearC = o + f * 60 + Vector3.new(0, 55, 0)

		local HW = 34
		local tSegs, tears = {}, {}

		local function makeTear(c, rv, fv, hw, d, k)
			local NT = hw > 25 and 13 or 8
			local q = hw / 34
			local tPts, y = {}, 0
			for i = 0, NT do
				local u = (i == 0 or i == NT) and i / NT or i / NT + rnd(-0.025, 0.025)
				y = (i == 0 or i == NT) and 0 or y * 0.45 + rnd(-1, 1) * (math.random() < 0.3 and 4 or 1.4) * q
				tPts[i] = { u = u, p = c + rv * (u * 2 - 1) * hw + Vector3.new(0, y + 2.5 * q * math.sin(u * math.pi * 1.2 + 0.4), 0) + fv * rnd(-2, 2) }
			end
			local function tseg(p0, p1, w0, w1)
				local a0, a1 = keep(L.att(p0)), keep(L.att(p1))
				tSegs[#tSegs + 1] = { w0 = w0, w1 = w1, d = d, k = k,
					g = keep(L.beam(a0, a1, { Texture = L.T("softbeam.png") or "", Width0 = 0, Width1 = 0, Brightness = 2.5, FaceCamera = true, Color = CS(C2), Transparency = NS(0.3) })),
					c = keep(L.beam(a0, a1, { Texture = L.T("softbeam.png") or "", Width0 = 0, Width1 = 0, Brightness = 8, FaceCamera = true, Color = CS(W, STAR) })) }
			end
			for i = 1, NT do tseg(tPts[i - 1].p, tPts[i].p, math.sin(tPts[i - 1].u * math.pi) ^ 0.8, math.sin(tPts[i].u * math.pi) ^ 0.8) end
			for _, bi in ipairs({ math.floor(NT * 0.3), math.floor(NT * 0.7) }) do
				local b0 = tPts[bi].p
				local dir = (rv * rnd(-0.6, 0.6) + Vector3.new(0, bi < NT / 2 and 1 or -1, 0)).Unit
				local b1 = b0 + dir * rnd(4, 7) * q + rv * rnd(-1, 1)
				local b2 = b1 + (dir + rv * rnd(-0.8, 0.8)).Unit * rnd(3, 5) * q
				tseg(b0, b1, 0.35, 0.18)
				tseg(b1, b2, 0.18, 0)
			end
			local tp = keep(L.part({ Size = Vector3.new(hw * 1.6, 3, 3), CFrame = CFrame.fromMatrix(c, rv, Vector3.yAxis) }))
			tears[#tears + 1] = { c = c, rv = rv, hw = hw, d = d }
