		for i = 1, 9 do
			local a = (i - 1) / 9 * math.pi * 2 + rnd(-0.25, 0.25)
			local p0, segs = o + Vector3.new(0, 0.09, 0), {}
			local total = rnd(6, 11) * s
			for j = 1, 3 do
				a += rnd(-0.45, 0.45)
				local len = total * ({ 0.42, 0.33, 0.25 })[j]
				local p1 = p0 + Vector3.new(math.cos(a), 0, math.sin(a)) * len
				segs[j] = { p = keep(L.part({ Material = NEON, Color = C2, Transparency = 1, Size = Vector3.new(0.1, 0.06, 0.1) })), a = p0, b = p1, w = ({ 0.55, 0.36, 0.2 })[j] * s }
				p0 = p1
			end
			cracks[i] = segs
		end
		local rocks = {}
		for i = 1, 12 do
			local a = rnd(0, math.pi * 2)
			local z = rnd(0.8, 1.6) * s
			local rp = L.mesh("sphere.mesh", "lavarock3.png", C2:Lerp(GREY, 0.25), 1.3, Vector3.new(z, z * rnd(0.6, 0.9), z * rnd(0.7, 1)))
			rp.Transparency = 1
			rocks[i] = { p = keep(rp), z = z,
				v = Vector3.new(math.cos(a) * rnd(8, 18), rnd(16, 30), math.sin(a) * rnd(8, 18)) * math.sqrt(s), w = Vector3.new(rnd(-6, 6), rnd(-6, 6), rnd(-6, 6)), pos = o, gone = false }
		end

		local frags = {}
		for i = 1, 10 do frags[i] = keep(L.part({ Material = NEON, Color = i % 2 == 0 and STAR or C2, Transparency = 1, Size = Vector3.new(0.35, 0.6, 0.2) * s })) end
		local showerT, rose, sigPh, heroN = 0, nil, 0, 0

		local SLANT = (Vector3.new(0, -1, 0) + r * 0.6 + f * 0.15).Unit
		local function streak(p0, p1, dur, w)
			local head = L.part({ Shape = BALL, Material = NEON, Color = W, Transparency = 0, Size = Vector3.one * w * 1.4, CFrame = CFrame.lookAt(p0, p1) })
			local a0 = L.new("Attachment", { Position = Vector3.new(0, w, 0) }, head)
			local a1 = L.new("Attachment", { Position = Vector3.new(0, -w, 0) }, head)
			local tr = L.new("Trail", { Attachment0 = a0, Attachment1 = a1, Texture = L.T("beamb.png") or "", LightEmission = 1, Brightness = 6, FaceCamera = true,
				Lifetime = 0.45, MinLength = 0, Color = CS({ CK(0, W), CK(0.25, STAR), CK(1, C2) }), Transparency = NS({ K(0, 0), K(1, 1) }), WidthScale = NS({ K(0, 1), K(1, 0) }) }, head)
			L.fx(dur + 0.4, function(_, tt)
				local u = math.min(tt / dur, 1)
				local fade = c01((u - 0.55) / 0.45)
				head.CFrame = CFrame.lookAt(p0:Lerp(p1, u), p1 + (p1 - p0))
				head.Transparency = fade
				tr.Brightness = 6 * (1 - fade)
			end, { head })
		end
		local hit = false

		L.camTilt(6.2, function(t) return 0.5 * L.outQuad(t / 2.4) * (1 - L.inQuad((t - 3.2) / 2.6)) end)
		L.timeline(DUR, function(t, once)
			local dt = L.lastDt or 0.016
			if held and once("late", 0.4) then hide(true) end
			sky.set(c01(t / 1.2) * (1 - c01((t - 9.2) / 1.3)))
			field.Rate = t < 1.6 and 90 or 0
			band.Rate, bandN.Rate = t < 1.2 and 350 or 0, t < 1.2 and 40 or 0
			bandP.CFrame = CFrame.new(o + Vector3.new(0, 75, 0)) * CFrame.Angles(0, yaw0 + t * 0.06, 0) * CFrame.Angles(0, 0, math.rad(12))

			local tw = L.outBack((t - 0.9) / 0.9) * (1 - L.inQuad((t - 9.3) / 1))

			local br = 1 + 0.08 * math.sin(t * 5)
			for _, sg in ipairs(tSegs) do
				local w = sg.d == 0 and tw or L.outBack(c01((t - 0.9 - sg.d) / 0.9)) * (1 - L.inQuad(c01((t - 9.3) / 1)))
				local z0 = sg.w0 * c01(w * 1.6 - (1 - sg.w0) * 0.6) * br * sg.k
				local z1 = sg.w1 * c01(w * 1.6 - (1 - sg.w1) * 0.6) * br * sg.k
				sg.c.Width0, sg.c.Width1 = 2.2 * z0 * w, 2.2 * z1 * w
				sg.g.Width0, sg.g.Width1 = 11 * z0 * w, 11 * z1 * w
			end
			rift.Rate = (t > 1 and t < 9) and 30 or 0
			pour.Rate = (t > 1.2 and t < 6.5) and 120 or 0
			for i = 1, #sideRift do
				sideRift[i].Rate = (t > 1.4 and t < 9) and 12 or 0
				sidePour[i].Rate = (t > 1.6 and t < 6.5) and 45 or 0
			end
			if once("close", 9.3) then pour:Emit(120) end




			if t > 1 and t < 5.5 then
				showerT -= dt
				while showerT <= 0 do
					showerT += rnd(0.012, 0.025)
					local p0, dir
					local tr0 = tears[math.random(#tears)]
					if math.random() < 0.5 and t > 1.2 + tr0.d then
						local out = tr0.c - o
						out = Vector3.new(out.X, 0, out.Z).Unit
						p0 = tr0.c + tr0.rv * rnd(-tr0.hw, tr0.hw) + Vector3.new(0, rnd(-3, 4), 0)
						dir = (Vector3.new(0, -1, 0) + tr0.rv * rnd(-0.7, 0.7) - out * rnd(0, 0.3)).Unit
					else
						local a = rnd(0, math.pi * 2)
						p0 = o + Vector3.new(math.cos(a), 0, math.sin(a)) * rnd(30, 110) + Vector3.new(0, rnd(60, 85), 0)
						dir = (SLANT + Vector3.new(rnd(-0.08, 0.08), 0, rnd(-0.08, 0.08))).Unit
					end
					heroN += 1
					local land = p0 + dir * ((p0.Y - o.Y) / math.max(-dir.Y, 0.3))
					if heroN % 6 == 0 and (land - o).Magnitude > 20 and t < 5 then
						fly(line(p0, land), rnd(0.7, 1), rnd(1.6, 2.4), function(p) impact(p, 1.4, false, 2) end, 0.6)
					else
						streak(p0, p0 + dir * rnd(45, 75), rnd(0.45, 0.7), rnd(0.35, 0.65))
					end
				end
			end

			local sOut = 1 - c01((t - 5.6) / 0.4)
			sigPh += dt * (1 + 9 * c01((t - 3) / 2.6)) * math.pi * 2
			local pulse = 0.5 + 0.5 * math.sin(sigPh)
			for i, d in ipairs(sDots) do
				local k = c01((t - 0.5 - (i - 1) * 0.12) / 0.2)
				d.Transparency = 1 - k * sOut * (0.6 + 0.4 * pulse)
			end
			for i, ln in ipairs(sLines) do
				local k = L.outQuad((t - 0.9 - (i - 1) * 0.1) / 0.3)
				ln.a1.WorldPosition = ln.from:Lerp(ln.to, k)
				ln.b.Transparency = NS(k > 0 and 1 - sOut * (0.5 + 0.4 * pulse) or 1)
			end
			sRing.Transparency = 1 - 0.85 * c01((t - 0.5) / 1) * sOut * (0.6 + 0.4 * pulse)

			if t >= 3 and t < 5.6 then
				local u = c01((t - 3) / 2.6)
				local p = mFrom:Lerp(mTo, L.inQuad(u))
				local cf = CFrame.lookAt(p, p + mDir)
				local flare = c01((t - 4.4) / 0.25) * (1 - 0.4 * c01((t - 4.8) / 0.6))
				core.CFrame = cf
				core.Transparency = 0
				fire.Enabled = true
				mGlow.Rate = 40
				mGlow.Size = NS(13 * s * (1 + 0.6 * flare))
				mFlame.Rate = 45 + 60 * flare
				mSmoke.Rate, mFire.Rate = 40, 30 + 60 * flare
				mLight.Brightness = 2 + 2 * flare
				for i, cmk in ipairs(chunks) do
					local a = t * 5 + i * 1.05
					cmk.CFrame = cf * CFrame.new(math.cos(a) * 5 * s, math.sin(a * 1.3) * 1.5 * s, math.sin(a) * 5 * s) * CFrame.Angles(a, a * 0.7, 0)
					cmk.Transparency = 0
				end

				local sk = L.inQuad(u)
				shadowM.Scale = Vector3.new((2 + 12 * sk) * s, 1, (2 + 12 * sk) * s)
				shadow.Transparency = 0.85 - 0.6 * sk
			end

			if once("flare", 4.4) then
				cone:Emit(45)
				mFlame:Emit(25)
				mFire:Emit(60)
			end

			if once("sh1", 4.2) then S:shake(1, 0.5) end
			if once("sh2", 4.8) then S:shake(2, 0.5) end
			if once("sh3", 5.25) then S:shake(3, 0.4) end

			if once("hit", 5.6) then
				hit = true
				core.Transparency = 1
				fire.Enabled = false
				mSmoke.Rate, mFire.Rate, mLight.Brightness, mGlow.Rate, mFlame.Rate = 0, 0, 0, 0, 0
				mGlow:Clear()
				for _, cmk in ipairs(chunks) do cmk.Transparency = 1 end
				shadow.Transparency = 1
				S:flash(W, 1)
				S:shake(6, 0.7)
				impact(o, 4 * s, false, 5)
				L.groundWave(o, "ring_c.png", W, 2, 44 * s, 0.9, 2.6)
				L.groundWave(o, "ring_c.png", C2, 2, 28 * s, 1.2, 2.4)
				blast:Emit(60)
				lt.Brightness = 6
			end
			if hit then
				local ht = t - 5.6

				local dk = c01(ht / 0.9)
				dome.Size = Vector3.one * (2 + 58 * L.outQuad(dk)) * s
				domeN.Size = Vector3.one * (2 + 36 * L.outQuad(c01(ht / 0.6))) * s
				dome.Transparency = dk >= 1 and 1 or 0.1 + 0.9 * dk
				domeN.Transparency = 0.8 + 0.2 * c01(ht / 0.5)

				local cool2 = c01((ht - 1) / 2.5)
				for i, segs in ipairs(cracks) do
					for j, sg in ipairs(segs) do
						local k = L.outQuad(c01((ht - i * 0.02 - (j - 1) * 0.1) / 0.14))
						local d = sg.b - sg.a
						local len = d.Magnitude * k
						if len > 0.05 then
							sg.p.Size = Vector3.new(sg.w * (1 - 0.3 * cool2), 0.06, len)
							sg.p.CFrame = CFrame.lookAt(sg.a + d.Unit * len / 2, sg.a + d.Unit * len)
						end
						sg.p.Transparency = k > 0 and 0.05 + 0.95 * c01((ht - 2.5) / 1.5) or 1
						sg.p.Color = STAR:Lerp(C2, c01(ht / 0.6)):Lerp(Color3.fromRGB(120, 40, 50), cool2)
					end
				end


				local endA = c01((t - 9.7) / 0.8)
				for _, rk in ipairs(rocks) do
					if not rk.gone then
						rk.v += Vector3.new(0, -50, 0) * dt
						rk.pos += rk.v * dt
						if rk.pos.Y < o.Y + rk.z * 0.25 and rk.v.Y < 0 then
							rk.gone = true
							rk.pos = Vector3.new(rk.pos.X, o.Y + rk.z * 0.25, rk.pos.Z)
							rk.p.CFrame = CFrame.new(rk.pos) * CFrame.Angles(0, rk.w.Y * ht, 0)
						else
							rk.p.CFrame = CFrame.new(rk.pos) * CFrame.Angles(rk.w.X * ht, rk.w.Y * ht, rk.w.Z * ht)
						end
					end
					rk.p.Transparency = endA
				end

				local rk2 = L.outBack(c01(ht / 0.35))
				for _, rr in ipairs(rim) do
					rr.p.CFrame = rr.cf * CFrame.new(0, rr.z * 0.75 * (rk2 - 1) * 0.6, 0)
					rr.p.Transparency = endA
				end
				local rimCool = c01(ht / 4.5)
				if math.floor(ht * 10) ~= math.floor((ht - dt) * 10) then
					for _, rr in ipairs(rim) do L.tint(rr.m, C2:Lerp(STAR, 0.35 * (1 - rimCool)):Lerp(Color3.fromRGB(80, 34, 44), rimCool), 2.2 - 1.4 * rimCool) end
				end

				local pw = (1 - c01((ht - 2.5) / 2)) * (ht < 0.2 and ht / 0.2 or 1)
				pillarG.Width0, pillarG.Width1 = 4.5 * s * pw, 2.5 * s * pw
				pillarC.Width0, pillarC.Width1 = 1.1 * s * pw, 0.5 * s * pw
				local cool = c01(ht / 4.9)
				cp.Transparency = 0.05 + 0.6 * cool + 0.35 * c01((t - 9.7) / 0.8)
				kp.Transparency = 0.05 + 0.5 * cool + 0.45 * c01((t - 9.7) / 0.8)
				L.tint(cm, C2:Lerp(STAR, 0.3 * (1 - cool)), 2.6 - cool)
				L.tint(km, C2:Lerp(VIO, cool * 0.7), 2.6 - cool)
				dp.Transparency = 0.2 + 0.8 * c01((t - 9.5) / 1)
				rise.Rate = 60 * (1 - cool)
				smoke.Rate = ht < 2 and 8 or 0
				lt.Brightness = math.max(1.2 * (1 - c01((t - 9) / 1.5)), 6 * (1 - c01(ht / 1.2)))
			end

			if once("rise", 7) then
				rose = bodyGhost(STAR, 1.8)
				L.groundWave(o, "ring_c.png", STAR, 1, 10 * s, 0.6, 2.6)
			end
			local dy = 0
			if t >= 7 then
				local k = c01((t - 7) / 1)
				dy = t < 8 and (-3.5 + 4.3 * L.outQuad(k)) * s or (0.8 * (1 - L.outQuad(c01((t - 8) / 0.4)))) * s
			end
			if rose then
				for _, gp in ipairs(rose) do
					gp.p.CFrame = gp.cf + Vector3.new(0, dy, 0)
					gp.p.Transparency = 0.15 + 0.85 * c01((t - 8.4) / 0.6)
				end
			end
			for i, fr in ipairs(frags) do
				if t >= 7 and t < 8.9 then
					local a = t * 7 + i / #frags * math.pi * 2
					local k = c01((t - 8.4) / 0.5)
					local rr = (2.3 - 0.4 * k) * s
					local y = (0.3 + 0.6 * math.sin(a * 0.5 + i)) * s * (1 - k) + dy - 0.2 * s * k
					fr.CFrame = CFrame.new(o + Vector3.new(0, (ch.pos.Y - o.Y), 0) + Vector3.new(math.cos(a) * rr, y, math.sin(a) * rr)) * CFrame.Angles(a, a * 1.3, 0)
					fr.Transparency = k
				else fr.Transparency = 1 end
			end

			if once("show", 8.4) then hide(false) asmT, asmPrev = -0.02, -0.02 end
			if once("card", 8.2) then S:title(L.name(), C1, C2) end
		end, objs, function() hide(false) sky.release() end)
	end


	local function death(preview)
		if not ch.char then return end
		local s = sc()
		local pos = L.ground(ch.feet or ch.pos, 3, 8)
		local parts = {}
		for d in pairs(L.bodyParts()) do if d:IsA("BasePart") then parts[#parts + 1] = d end end
		local g = bodyGhost(C2, 0.6)
		local gone = {}
		deathGone = gone
		local fold = L.new("Folder", { Name = "Shards" }, L.root)
		local shards = {}
		dying = true

		for _, pl in ipairs(planets) do pl.drop = { p = pl.b.Position, v = Vector3.new(rnd(-4, 4), rnd(3, 6), rnd(-4, 4)) * s, t = 0, roll = 0, gy = pos.Y } end

		for i, cm in ipairs(comets) do
			local from = cm.head.Position
			local a = rnd(0, 6.3)
			local to = L.ground(pos + Vector3.new(math.cos(a), 0, math.sin(a)) * rnd(3, 6) * s, 4, 10)
			L.after(0.15 + i * 0.12, function() fly(line(from, to), 0.5, 0.45 * s, function(p) impact(p, 0.9 * s, i == 1) end, 0.35) end)
		end

		local ringCF = ringA.CFrame
		for i = 1, 14 do
			local a = i / 14 * math.pi * 2
			local cf = ringCF * CFrame.new(math.cos(a) * 3 * s, 0, math.sin(a) * 3 * s) * CFrame.Angles(rnd(0, 6), rnd(0, 6), rnd(0, 6))
			local p = L.part({ Material = NEON, Color = i % 2 == 0 and STAR or C2, Transparency = 0, Size = Vector3.new(0.5, 0.12, 0.25) * s, CFrame = cf }, fold)
			local out = (cf.Position - ringCF.Position)
			shards[#shards + 1] = { p = p, cf = cf, v = (out.Magnitude > 0 and out.Unit or Vector3.xAxis) * rnd(5, 9) * s + Vector3.new(0, rnd(2, 5), 0), w = Vector3.new(rnd(-6, 6), rnd(-6, 6), rnd(-6, 6)), g = -14, t0 = 0 }
		end

		local chest = (ch.torso and ch.torso.Parent and ch.torso.Position) or pos + Vector3.new(0, 2.5 * s, 0)


		local novaP = L.part({ CFrame = CFrame.new(chest) }, fold)
		local core = L.part({ Shape = BALL, Material = NEON, Color = W, Transparency = 1, Size = Vector3.one * 0.5 * s, CFrame = CFrame.new(chest) }, fold)
		local nGlow = L.pe(novaP, { Texture = L.T("smoke.png"), LockedToPart = true, Rate = 0, Lifetime = NR(0.12, 0.2), Speed = NR(0), Size = NS(6 * s),
			Transparency = NS(0.35), Color = CS(C2, VIO), LightEmission = 1, Brightness = 3, Rotation = NR(0, 360) })
		local nSuck = L.pe(novaP, { Texture = L.T("spark.png"), Shape = Enum.ParticleEmitterShape.Sphere, ShapeStyle = Enum.ParticleEmitterShapeStyle.Surface,
			ShapeInOut = Enum.ParticleEmitterShapeInOut.Inward, Rate = 0, Lifetime = NR(0.3, 0.4), Speed = NR(8, 12), Size = NS({ K(0, 0.5), K(1, 0) }),
			Color = CS(STAR, C2), Brightness = 6, Orientation = Enum.ParticleOrientation.VelocityParallel, Squash = NS(-1.2) })
		local nShell = L.pe(novaP, { Texture = L.T("star.png"), Rate = 0, Lifetime = NR(0.6, 1.1), Speed = NR(16, 30), SpreadAngle = Vector2.new(180, 180), Drag = 2.5,
			Size = NS({ K(0, 1), K(1, 0) }), Color = CS(W, STAR), Brightness = 6, Rotation = NR(0, 360) })
		local nGas = L.pe(novaP, { Texture = L.T("smoke.png"), Rate = 0, Lifetime = NR(0.8, 1.3), Speed = NR(10, 16), SpreadAngle = Vector2.new(180, 180), Drag = 2.2,
			Size = NS({ K(0, 2 * s), K(1, 6 * s) }), Transparency = NS({ K(0, 0.3), K(1, 1) }), Color = CS(C2, VIO), LightEmission = 0.8, Brightness = 2, Rotation = NR(0, 360) })
		novaP.Size = Vector3.one * 2 * s
		L.timeline(3, function(t, once)
			if t >= 0.1 and t < 0.5 then
				local k = c01((t - 0.1) / 0.4)
				nGlow.Rate, nSuck.Rate = 50, 60
				nGlow.Size = NS((6 - 4.5 * L.inQuad(k)) * s)
				core.Transparency = 0.1
				core.Size = Vector3.one * (0.5 + 0.3 * k) * s
			end
			if once("blow", 0.5) then
				nGlow.Rate, nSuck.Rate = 0, 0
				nGlow:Clear()
				core.Transparency = 1
				nShell:Emit(70)
				nGas:Emit(36)
				L.groundWave(pos, "ring_c.png", W, 1, 14 * s, 0.5, 2.6)
			end
			if once("flash", 0.5) then
				flashP.CFrame = CFrame.new(chest)
				flash.Range, flash.Brightness = 14 * s, 4
			end

			if g and t < 0.55 then
				for _, gp in ipairs(g) do gp.p.Transparency = 1 - 0.8 * c01(t / 0.45) * ((math.random() < 0.25) and 0.4 or 1) end
			end

			if once("break", 0.5) then
				for _, d in ipairs(parts) do if d.Parent then gone[d] = true d.LocalTransparencyModifier = 1 end end
				for d in pairs(L.bodyParts()) do if not gone[d] then gone[d] = true d.LocalTransparencyModifier = 1 end end
				for i = 1, math.min(#parts, 20) do
					local bp = parts[i]
					for j = 1, 3 do
						local cf = bp.CFrame * CFrame.new(rnd(-0.35, 0.35) * bp.Size.X, rnd(-0.35, 0.35) * bp.Size.Y, 0) * CFrame.Angles(rnd(0, 6), rnd(0, 6), rnd(0, 6))
						local p = L.part({ Material = NEON, Color = (i + j) % 2 == 0 and STAR or C2, Transparency = 0, Size = Vector3.new(0.3, 0.6, 0.12) * s, CFrame = cf }, fold)
						shards[#shards + 1] = { p = p, cf = cf, v = Vector3.new(rnd(-2.5, 2.5), rnd(2.5, 5.5), rnd(-2.5, 2.5)) * s, w = Vector3.new(rnd(-3, 3), rnd(-3, 3), rnd(-3, 3)), g = 0.8, t0 = 0.5 }
					end
				end
				embP.CFrame = CFrame.new((ch.torso and ch.torso.Parent and ch.torso.Position) or pos + Vector3.new(0, 2, 0))
				embers:Emit(36)
				burst:Emit(20)
				L.groundWave(pos, "ring_c.png", C2, 1, 10 * s, 0.6, 2.4)
				L.groundWave(pos, "ring_c.png", STAR, 1, 6 * s, 0.4, 2.6)
			end
			for _, sh in ipairs(shards) do
				local u = t - sh.t0
				if u >= 0 then
					local spin = CFrame.Angles(sh.w.X * u, sh.w.Y * u, sh.w.Z * u)
					sh.p.CFrame = (sh.cf + sh.v * u + Vector3.new(0, 0.5 * sh.g * u * u, 0) * s) * spin
					sh.p.Transparency = c01((u - (sh.t0 > 0 and 1.1 or 0.6)) / 1.2)
				end
			end
		end, { fold }, function()
			dying = false
			deathGone = nil
			for _, pl in ipairs(planets) do pl.drop = nil end

			if preview then for d in pairs(gone) do if d.Parent then pcall(function() d.LocalTransparencyModifier = 0 end) end end spiralT = 0 end
		end)

		local cp, cm = L.mesh("disc.mesh", "ring_c.png", C2, 2.4, Vector3.new(4.5 * s, 1, 4.5 * s))
		local kp, km = L.mesh("disc.mesh", "cracks_b.png", C2, 2.4, Vector3.new(6 * s, 1, 6 * s))
		local dp = L.mesh("disc.mesh", "darkdisc.png", L.BACK, 1, Vector3.new(6.5 * s, 1, 6.5 * s))
		local rot = rnd(0, 6)
		cp.CFrame = CFrame.new(pos + Vector3.new(0, 0.1, 0)) * CFrame.Angles(0, rot, 0)
		kp.CFrame = CFrame.new(pos + Vector3.new(0, 0.07, 0)) * CFrame.Angles(0, -rot, 0)
		dp.CFrame = CFrame.new(pos + Vector3.new(0, 0.04, 0))

		local nebP = L.part({ Size = Vector3.new(4 * s, 3 * s, 4 * s), CFrame = CFrame.new(pos + Vector3.new(0, 2.5 * s, 0)) })
		local nebE = L.pe(nebP, { Texture = L.T("smoke.png"), Shape = Enum.ParticleEmitterShape.Box, Rate = 0, Lifetime = NR(3, 4.5), Speed = NR(0.2, 0.6),
			SpreadAngle = Vector2.new(180, 180), Size = NS({ K(0, 2.5), K(1, 6) }), Transparency = NS({ K(0, 1), K(0.25, 0.55), K(1, 1) }),
			Color = CS(C2, VIO), LightEmission = 0.6, Brightness = 2, Rotation = NR(0, 360), RotSpeed = NR(-15, 15) })
		local nebS = L.pe(nebP, { Texture = L.T("star.png"), Shape = Enum.ParticleEmitterShape.Box, Rate = 0, Lifetime = NR(1, 2), Speed = NR(0, 0.3),
			Size = NS({ K(0, 0), K(0.4, 0.3), K(1, 0) }), Color = CS(STAR, C2), Brightness = 4 })
		L.fx(8, function(k, t)
			nebE.Rate = (t > 0.7 and t < 5) and 7 or 0
			nebS.Rate = (t > 0.7 and t < 5.5) and 14 or 0
			L.tint(cm, C2:Lerp(GREY, c01(k * 1.25)), 2.4 - 1.2 * k)
			L.tint(km, C2:Lerp(GREY, c01(k * 1.1)), 2.4 - 1.2 * k)
			cp.Transparency = 0.1 + 0.5 * k + 0.4 * c01((k - 0.75) / 0.25)
			kp.Transparency = 0.05 + 0.6 * k + 0.35 * c01((k - 0.75) / 0.25)
			dp.Transparency = 0.25 + 0.75 * c01((k - 0.7) / 0.3)
		end, { cp, kp, dp, nebP })
	end


	local age, meteorT, farT, wasSwim, runK, flare, comOn = 0, rnd(1.5, 3), rnd(4, 8), false, 0, 0, true
	local fallT, wasMeteor, still, idleK, lastP, stepD, bigT = 0, false, 0, 0, nil, 0, rnd(10, 18)
	local sitK, dayT, day, wishT, wishK = 0, 0, 0, rnd(20, 30), 99

	local ASM = { 0, 0.35, 0.7, 1.05, 1.4 }
	local function asmBeat(at)
		local s, feet = sc(), ch.feet or ch.pos
		if at == 0 then flare = 0.8 L.groundWave(feet, "ring_c.png", C2, 1, 9 * s, 0.45, 2.6)
		elseif at == 0.35 then spiralT = 0 embP.CFrame = CFrame.new(feet + Vector3.new(0, 0.4, 0)) embers:Emit(18)
		elseif at == 0.7 then burst:Emit(14) L.groundWave(feet, "ring_c.png", STAR, 1, 6 * s, 0.35, 2.6)
		elseif at == 1.05 then haloFlare = 0.7
		else haloFlare = 1 flashP.CFrame = CFrame.new(ch.pos + Vector3.new(0, 2.5 * s, 0)) flash.Range, flash.Brightness = 9 * s, 3 end
	end



	local SF = { beat = 0, en = 0, lean = Vector3.zero, cheer = false,
		PH = { dance = "STARDUST", spin = "NOVA!", cheer = "SHINE ON", low = "COMET!", pose = "STELLAR", sway = "COSMIC" },
		ANY = { "STARLIT", "ORBIT", "WISH!" } }

	local SFW = { t = setmetatable({}, { __mode = "k" }) }
	function SFW.ns(b, v) v = math.floor(v * 50 + 0.5) / 50 if SFW.t[b] ~= v then SFW.t[b] = v b.Transparency = NS(v) end end
	function SFW.sc(m, v) if (m.Scale - v).Magnitude > 0.01 then m.Scale = v end end
	local function step(dt)
		age += dt
		local s, iw, on, swim, sit, dead, emote = sc(), ch.iw, ch.on, ch.swim == true, ch.sit == true, ch.dead == true, ch.emote == true
		local gone = dead or dying
		L.motion(dt, s, gone, SF.PH, SF.ANY)
		emote = emote or ch.mOn == true
		asmPrev, asmT = asmT, asmT + dt
		local function asm(at) return asmT >= at end
		for _, at in ipairs(ASM) do if asmPrev < at and asmT >= at and not gone then asmBeat(at) end end
		local run = (ch.sprint or 0) > 0.2 or (ch.spd or 0) > 18

		flare = math.max(0, flare - dt * 2.2)
		local wy = sit and -0.9 or (swim and 1.0 or -0.2)
		local tilt = swim and 0 or math.rad(16 + 4 * math.sin(age * 0.7))
		local lv = (ch.vel or Vector3.zero) / 25
		if lv.Magnitude > 1 then lv = lv.Unit end
		SF.lean = SF.lean:Lerp((swim or sit) and Vector3.zero or lv, c01(dt * 3))
		local bank = SF.lean.Magnitude > 0.03 and CFrame.fromAxisAngle(Vector3.yAxis:Cross(SF.lean.Unit), SF.lean.Magnitude * 0.35) or CFrame.identity
