				L.groundWave(ch.feet, "ring_c.png", C2, 1 * s, 6 * s, 0.4, 2.2)
			end
		end
		local cheer = ch.mCur == "cheer"
		if cheer and not SF.cheer and not gone then burst:Emit(30) haloFlare = 1 end
		SF.cheer = cheer
		if ch.mCur == "pose" then haloFlare = math.max(haloFlare, 0.45) end
		local ringCF = CFrame.new(ch.pos + Vector3.new(0, wy * s, 0)) * bank * CFrame.Angles(0, age * 0.35, 0) * CFrame.Angles(tilt, 0, 0)
		local fs = 1 + 0.7 * L.outQuad(flare)
		ringAm.Scale, ringBm.Scale = Vector3.new(6 * s * fs, 1, 6 * s * fs), Vector3.new(7.2 * s * fs, 1, 7.2 * s * fs)
		ringA.CFrame = ringCF * CFrame.Angles(0, age * 0.9, 0)
		ringB.CFrame = ringCF * CFrame.Angles(0, -age * 0.6, 0) + Vector3.new(0, -0.02, 0)
		ringA.Transparency = (gone or not asm(0)) and 1 or 0.05 + 0.5 * flare
		ringB.Transparency = (gone or not asm(0)) and 1 or 0.35 + 0.5 * flare
