		if math.abs(ringP.Size.X - rs) > 0.05 then ringP.Size = Vector3.new(rs, 0.2, rs) end
		ringP.CFrame = ringCF
		if swim ~= wasSwim then
			wasSwim = swim
			for k, v in pairs(swim and BUBBLE or DUST) do dust[k] = v end
		end
		dust.Rate = gone and 0 or (swim and 10 or (sit and 20 or 45 * (0.5 + 0.5 * iw)))


		runK += ((on and not sit and 1 or 0) - runK) * c01(dt * 4)
		spiralT += dt
		local spd = (sit and 0.4 or 1) * (ch.mCur == "spin" and 5 or emote and 3 or 1)
		local back = (ch.vel and ch.vel.Magnitude > 0.1) and -ch.vel.Unit or (ch.hrp and -ch.hrp.CFrame.LookVector or Vector3.zAxis)
		local side = back:Cross(Vector3.yAxis)
		local showC = not gone and asm(0.35)
		if showC ~= comOn then comOn = showC for _, cm in ipairs(comets) do cm.tr:Clear() end end
		for i, cm in ipairs(comets) do
			cm.a += dt * cm.w * spd
			local r = cm.r * s * (emote and 0.75 or 1)
			local p = ringCF * Vector3.new(math.cos(cm.a) * r, cm.h * s, math.sin(cm.a) * r)
			if runK > 0.01 then
				local behind = ch.pos + back * (1.6 + i * 1.1) * s + side * (i - 2) * 0.7 * s + Vector3.new(0, (0.2 + 0.25 * math.sin(age * 5 + i * 2)) * s, 0)
				p = p:Lerp(behind, runK * 0.85)
			end
			if spiralT < 1.4 then
				local k = spiralT / 1.4
				local a = cm.a * 2 + k * 9
				local sp = (ch.feet or ch.pos) + Vector3.new(math.cos(a) * 1.4 * s, (ch.pos.Y - (ch.feet or ch.pos).Y + wy * s) * L.outQuad(k), math.sin(a) * 1.4 * s)
				p = sp:Lerp(p, c01((k - 0.7) / 0.3))
			end
			cm.head.CFrame = CFrame.new(p)
			cm.head.Transparency = showC and 0 or 1
			cm.tr.Enabled = showC
			cm.tr.Lifetime = run and 0.9 or (on and 0.65 or 0.45)
		end

		local hp = ((ch.head and ch.head.Parent) and ch.head.Position or ch.pos + Vector3.new(0, 1.5 * s, 0)) + Vector3.new(0, (1.05 + 0.06 * math.sin(age * 1.6)) * s, 0)
		local hs = 2.3 * s * (1 + (emote and 0.15 * math.abs(math.sin(age * 6)) or 0) + 1.2 * L.outQuad(haloFlare))
		halom.Scale = Vector3.new(hs, 1, hs)
		halo.CFrame = CFrame.new(hp) * CFrame.Angles(math.rad(6), age * 0.5, 0)
		halo.Transparency = (gone or not asm(1.05)) and 1 or 0.05
		for i, sp in ipairs(sparks) do
			local a = age * 0.5 + (i - 1) / 5 * math.pi * 2
			sp.p.CFrame = CFrame.new(hp + Vector3.new(math.cos(a) * hs * 0.47, 0.08 * math.sin(age * 3 + i), math.sin(a) * hs * 0.47))
			local tw = 0.7 + 0.3 * math.sin(age * 5 + i * 1.3)
			local z = 0.75 * s * tw * (emote and 1.3 or 1)
			sp.g.Size = UDim2.new(z, 0, z, 0)
			sp.g.Enabled = not gone and asm(1.05)
			sp.im.Rotation = age * 40 + i * 20
		end

		local gp = ch.air and L.ground(ch.feet or ch.pos, 1, 14) or (ch.feet or ch.pos)
		local sigOn = not gone and not swim
		sigD.CFrame = CFrame.new(gp + Vector3.new(0, 0.05, 0))
		sigR.CFrame = CFrame.new(gp + Vector3.new(0, 0.08, 0)) * CFrame.Angles(0, age * 0.4, 0)
		sigI.CFrame = CFrame.new(gp + Vector3.new(0, 0.1, 0)) * CFrame.Angles(0, -age * 0.7, 0)
		SFW.sc(sigRm, Vector3.new(6 * s, 1, 6 * s)) SFW.sc(sigIm, Vector3.new(4.2 * s, 1, 4.2 * s))
		sigD.Transparency = 1
		sigR.Transparency = 1
		sigI.Transparency = 1
		sigP.CFrame = CFrame.new(gp + Vector3.new(0, 0.15, 0))
		sigE.Rate = sigOn and 18 or 0

		hazeP.CFrame = CFrame.new((ch.feet or ch.pos) + Vector3.new(0, 0.2, 0))
		haze.Rate = (swim or gone) and 0 or 4 * (0.3 + 0.7 * iw)

		feetP.CFrame = ch.flat or CFrame.new(ch.pos)
		if trail then
			trail.Enabled = on and not swim and not gone
			edgeT.Enabled = run and not swim and not gone
			edgeB.Enabled = run and not swim and not gone
		end
		walkDust.Rate = (on and not swim and not ch.air and not gone) and 26 or 0
		if ch.jumped and not gone then
			L.groundWave(ch.feet, "ring_c.png", STAR, 1 * s, 8 * s, 0.45, 2.6)
			burst:Emit(26)
			flare = 1
			L.ghost(STAR, NEON, 0.6)
		end

		fallT = (ch.air and (ch.fallV or 0) < -35) and fallT + dt or 0
		local meteorOn = fallT > 0.35 and not gone and not swim
		if meteorOn then wasMeteor = true end
		shell.CFrame = CFrame.new(ch.pos)
		if math.abs(shell.Size.X - 4 * s) > 0.05 then shell.Size = Vector3.one * 4 * s end
		shell.Transparency = meteorOn and 0.55 + 0.1 * math.sin(age * 30) or 1
		if ch.landed and not gone and not swim then
			local lp = L.ground(ch.feet, 2, 4)
			if wasMeteor then
				impact(lp, 2.6 * s, true, 5)
				L.groundWave(lp, "ring_c.png", W, 1, 18 * s, 0.7, 2.6)
				burst:Emit(40)
			else
				impact(lp, 1.3 * s, true)
				L.groundWave(lp, "ring_c.png", C2, 1, 9 * s, 0.5, 2.4)
				burst:Emit(12)
			end
		end
		if not ch.air then wasMeteor = false end

		local tor = (ch.torso and ch.torso.Parent) and ch.torso or nil
		tailP.CFrame = tor and tor.CFrame or CFrame.new(ch.pos)
		tailE.Rate = gone and 0 or (meteorOn and 140 or (run and not swim and 70 or 0))
		if rig.cape then rig.cape.Enabled = on and not swim and not gone end

		if tor then cloakP.CFrame = tor.CFrame * CFrame.new(0, tor.Size.Y * 0.4, tor.Size.Z / 2 + 0.25) end
		cloak.Rate = (gone or swim) and 0 or (on and 40 or 22)

		still = on and 0 or still + dt
		local idleOn = still > 10 and not sit and not swim and not ch.air and not gone
		idleK += ((idleOn and 1 or 0) - idleK) * c01(dt * 1.5)
		local cs = 4 * s * (1 + 0.4 * L.outQuad(flare))
		ringCm.Scale = Vector3.new(cs, 1, cs)
		ringC.CFrame = CFrame.new(ch.pos + Vector3.new(0, 0.9 * s, 0)) * CFrame.Angles(0, -age * 0.8, 0) * CFrame.Angles(-tilt * 0.8, 0, 0)
		ringC.Transparency = (gone or swim or not asm(0)) and 1 or 0.15
		for i, a in ipairs(arms) do
			SFW.sc(a.m, Vector3.new(6 * s, 1, 6 * s))
