			a.p.Transparency = gone and 1 or 1 - 0.85 * idleK
		end
		local alignA = age * 0.15
		sitK += ((sit and not gone and 1 or 0) - sitK) * c01(dt * 3)
		local rightV = ch.hrp and ch.hrp.CFrame.RightVector or Vector3.xAxis
		for i, pl in ipairs(planets) do
			if math.abs(pl.b.Size.X - pl.sz * s) > 0.02 then pl.b.Size = Vector3.one * pl.sz * s end
			SFW.sc(pl.rm, Vector3.new(pl.sz * 2.4 * s, 1, pl.sz * 2.4 * s))
			local dd = pl.drop
			if dd then

				dd.t += dt
				dd.v += Vector3.new(0, -30, 0) * dt
				local np = dd.p + dd.v * dt
				local rad = pl.sz * s / 2
				if np.Y < dd.gy + rad then
					np = Vector3.new(np.X, dd.gy + rad, np.Z)
					dd.v = Vector3.new(dd.v.X * 0.97, math.abs(dd.v.Y) > 2 and math.abs(dd.v.Y) * 0.35 or 0, dd.v.Z * 0.97)
				end
				dd.p = np
				dd.roll += Vector3.new(dd.v.X, 0, dd.v.Z).Magnitude * dt / math.max(rad, 0.05)
				pl.b.CFrame = CFrame.new(np) * CFrame.Angles(dd.roll, 0, 0)
				pl.rp.CFrame = CFrame.new(np) * CFrame.Angles(dd.roll + math.rad(25), 0, 0)
				local fade = c01((dd.t - 2.2) / 0.6)
				pl.b.Transparency, pl.rp.Transparency = fade, math.max(0.1, fade)
			else
