				local d = ((alignA - pl.a + math.pi) % (math.pi * 2)) - math.pi
				local ang = pl.a + d * idleK
				local pp = ch.pos + Vector3.new(math.cos(ang) * pl.r * s, (0.6 + 0.25 * math.sin(age * 0.8 + i)) * s, math.sin(ang) * pl.r * s)

				if sitK > 0.01 then pp = pp:Lerp(ch.pos + rightV * (i == 1 and -1.7 or 1.7) * s + Vector3.new(0, (-0.5 + 0.08 * math.sin(age * 2 + i)) * s, 0), sitK) end
				pl.b.CFrame = CFrame.new(pp)
				pl.rp.CFrame = CFrame.new(pp) * CFrame.Angles(math.rad(25), age * 1.2, 0)
				local pg = gone or not asm(0.7)
				pl.b.Transparency, pl.rp.Transparency = pg and 1 or 0, pg and 1 or 0.1
			end
		end

		local lap = ch.pos + (ch.hrp and ch.hrp.CFrame.LookVector * 0.6 * s or Vector3.zero) + Vector3.new(0, 0.1 * s, 0)
		moon.CFrame = CFrame.new(lap + Vector3.new(math.cos(age * 1.5) * 0.8 * s, 0.35 * s, math.sin(age * 1.5) * 0.8 * s))
		if math.abs(moon.Size.X - 0.35 * s) > 0.02 then moon.Size = Vector3.one * 0.35 * s end
		moon.Transparency = 1 - sitK

		dayT -= dt
		if dayT <= 0 then
			dayT = 2
			local ct = game:GetService("Lighting").ClockTime
			day = (ct > 6.5 and ct < 17.5) and 1 or 0
		end
		backM.Scale = Vector3.new(7.6 * s * fs, 1, 7.6 * s * fs)
		backD.CFrame = ringCF * CFrame.new(0, -0.04, 0)
		backD.Transparency = (gone or swim) and 1 or 1 - 0.55 * day
		for _, cm in ipairs(comets) do cm.dark.Enabled = showC and day > 0 cm.dark.Lifetime = cm.tr.Lifetime end

		for i, cr in ipairs(crown) do
			local a = -age * 0.6 + (i - 1) / 5 * math.pi * 2
			cr.p.CFrame = CFrame.new(hp + Vector3.new(math.cos(a) * 0.8 * s, (0.55 + 0.05 * math.sin(age * 2 + i)) * s, math.sin(a) * 0.8 * s))
			local z = 0.8 * s * (0.8 + 0.2 * math.sin(age * 5 + i * 1.4)) * (1 + 0.8 * haloFlare)
			cr.g.Size = UDim2.new(z, 0, z, 0)
			cr.g.Enabled = not gone and asm(1.4)
			cr.im.Rotation = age * 30 + i * 40
		end
		for i, ln in ipairs(crownL) do
			ln.a0.WorldPosition, ln.a1.WorldPosition = crown[i].p.Position, crown[i % 5 + 1].p.Position
			ln.b.Enabled = not gone and asm(1.4)
		end

		wishT -= dt
		if wishT <= 0 and not gone and not swim then
			wishT, wishK = rnd(25, 35), 0
			local a = rnd(0, math.pi * 2)
			local c = ch.pos + Vector3.new(math.cos(a), 0, math.sin(a)) * rnd(50, 80) + Vector3.new(0, rnd(40, 55), 0)
			local d = Vector3.new(-math.sin(a), -0.25, math.cos(a)).Unit * 90
			fly(line(c - d * 0.5, c + d * 0.5), 1.6, 2.4, nil, 1.2, CS({ CK(0, W), CK(0.3, STAR), CK(1, C2) }))
