			wishI.ImageTransparency, wishTx.TextTransparency, wishTx.TextStrokeTransparency = 1 - a, 1 - a, 1 - 0.6 * a
			wishI.Rotation = wishK * 90
		end

		local cam = workspace.CurrentCamera
		local camP = cam and cam.CFrame.Position or ch.pos
		local function face(p) local d = camP - p.Position return p.Position + (d.Magnitude > 0 and d.Unit or Vector3.zero) * (math.min(p.Size.X, p.Size.Z) / 2 + 0.06) end
		for i = 1, #cDots do
			local lk, dt2, ln = chain[i], cDots[i], cLines[i]
			if lk and lk[1].Parent and lk[2].Parent and not gone and not held then
				local hot = 0.5 + 0.5 * math.sin(age * 4 - i * 0.9)
				local pa, pb = face(lk[1]), face(lk[2])
				dt2.CFrame = CFrame.new(pb)
				dt2.Transparency = 0.1 + 0.5 * (1 - hot)
				ln.a0.WorldPosition, ln.a1.WorldPosition = pa, pb
				SFW.ns(ln.b, 1 - 0.6 * hot)
			else
				dt2.Transparency = 1
				SFW.ns(ln.b, 1)
			end
		end

		if lastP and on and not swim and not ch.air and not gone then
			stepD += ((ch.pos - lastP) * Vector3.new(1, 0, 1)).Magnitude
			if stepD >= 2.5 * s then
				stepD = 0
				stepI = stepI % #steps + 1
				local st = steps[stepI]
				local p = L.ground(ch.feet, 2, 4) + Vector3.new(0, 0.12, 0)
				st.d.CFrame, st.t = CFrame.new(p), 0
				st.a1.WorldPosition, st.a0.WorldPosition = p, lastDot or p
				lastDot = p
			end
		elseif not on then lastDot = nil end
		lastP = ch.pos
		for _, st in ipairs(steps) do
			st.t += dt
			local a = gone and 0 or 1 - c01(st.t / 3)
			st.d.Transparency = 1 - 0.9 * a
			SFW.ns(st.b, 1 - 0.7 * a)
		end

		airP.CFrame = CFrame.new(ch.pos + Vector3.new(0, 3, 0))
		airE.Rate = gone and 0 or 22
		tintL.Brightness = gone and 0 or 0.8
		mapE.Rate = sigOn and 30 or 0

		bigT -= dt
		if bigT <= 0 and not swim and not gone and iw > 0.3 then
			bigT = rnd(15, 25)
			local a = rnd(0, math.pi * 2)
			local target = L.ground(ch.feet + Vector3.new(math.cos(a), 0, math.sin(a)) * rnd(8, 14) * s, 6, 14)
			local from = target + Vector3.new(rnd(-25, 25), rnd(55, 70), rnd(-25, 25))
			fly(line(from, target), 0.9, 1.6 * s, function(p) impact(p, 2.6 * s, true, 5) L.groundWave(p, "ring_c.png", W, 1, 16 * s, 0.7, 2.6) end, 0.8)
		end
		haloFlare = math.max(0, haloFlare - dt * 1.2)

		if not swim and not gone and iw > 0.3 then
			meteorT -= dt * (sit and 0.5 or 1)
			if meteorT <= 0 then
				meteorT = rnd(2, 4)
				local a = rnd(0, math.pi * 2)
				local target = L.ground(ch.feet + Vector3.new(math.cos(a), 0, math.sin(a)) * rnd(5, 11) * s, 6, 12)
				local from = target + Vector3.new(rnd(-14, 14), rnd(32, 40), rnd(-14, 14))
				fly(line(from, target), 0.55, 0.6 * s, function(p) impact(p, 1.3 * s, true) end)
			end
		end
		farT -= dt
		if farT <= 0 and not gone then
			farT = rnd(6, 10)
			local a = rnd(0, math.pi * 2)
			local c = ch.pos + Vector3.new(math.cos(a), 0, math.sin(a)) * rnd(70, 110) + Vector3.new(0, rnd(45, 70), 0)
			local d = Vector3.new(-math.sin(a), -0.35, math.cos(a)).Unit * rnd(45, 65)
			fly(line(c - d * 0.5, c + d * 0.5), rnd(0.9, 1.3), 1.4, nil, 0.7)
		end
		flash.Brightness = math.max(0, flash.Brightness - dt * 10)
		if glow then glow.Brightness = gone and 0 or 0.8 + 0.6 * iw end
		tag.step(dt)
	end

	return {
		arrive = function(short) if short then shorts[math.random(1, #shorts)]() else arriveFull() end end,
		short = function(n) n = math.floor(tonumber(n) or 1) shorts[(n - 1) % #shorts + 1]() end,
		step = step, rebind = rebind, death = death,
		hidden = function() return held or deathGone end,
		rig = function() return rig end,
		stop = function() hide(false) end,
	}
end
end
end)()
end
