return (function()


return function(R, I)
local System = I.System


System.StaffThemes.THEMES.vampire = function(L, C)
	local C1, C2, W = C.c1, C.c2, L.W
	local NS, CS, NR, K, CK = L.NS, L.CS, L.NR, L.K, L.CK
	local ch = L.ch
	local rnd, c01 = L.rnd, L.c01
	local BLACK = Color3.fromRGB(12, 2, 5)
	local GORE = C1:Lerp(BLACK, 0.45)

	local function batE(parent, props)
		local p = { Texture = L.T("bat_fb.png"), FlipbookLayout = Enum.ParticleFlipbookLayout.Grid2x2, FlipbookMode = Enum.ParticleFlipbookMode.Loop,
			FlipbookFramerate = NR(12, 18), FlipbookStartRandom = true, Color = CS(BLACK, GORE), LightEmission = 0, Brightness = 1,
			Size = NS(0.9), Lifetime = NR(0.8, 1.3), Speed = NR(4, 8), SpreadAngle = Vector2.new(180, 180), Drag = 1,
			Transparency = NS({ K(0, 1), K(0.1, 0), K(0.85, 0), K(1, 1) }) }
		for k, v in pairs(props or {}) do p[k] = v end
		return L.pe(parent, p)
	end
	local function mistE(parent, props)
		local p = { Texture = L.T("smoke.png"), Color = CS(C1, GORE), LightEmission = 0.25, Brightness = 1.2,
			Transparency = NS({ K(0, 1), K(0.3, 0.55), K(1, 1) }), Size = NS({ K(0, 1.5), K(1, 4) }), Lifetime = NR(1.4, 2.2),
			Speed = NR(0.4, 1.2), RotSpeed = NR(-25, 25), Rotation = NR(0, 360) }
		for k, v in pairs(props or {}) do p[k] = v end
		return L.pe(parent, p)
	end
	local function dropE(parent, props)
		local p = { Texture = L.T("drop.png"), Color = CS(C2, C1), LightEmission = 0.2, Brightness = 1.5, Size = NS({ K(0, 0.22), K(1, 0.16) }),
			Lifetime = NR(0.6, 0.9), Speed = NR(0, 1), Acceleration = Vector3.new(0, -30, 0), Orientation = Enum.ParticleOrientation.FacingCameraWorldUp, Rotation = NR(0, 0),
			Transparency = NS({ K(0, 0), K(0.85, 0), K(1, 1) }) }
		for k, v in pairs(props or {}) do p[k] = v end
		return L.pe(parent, p)
	end
	local function faceCam(pos)
		local cp = workspace.CurrentCamera.CFrame.Position
		if (cp - pos).Magnitude < 0.05 then return CFrame.new(pos) end
		return CFrame.lookAt(pos, cp) * CFrame.Angles(math.rad(90), 0, 0)
	end


	local savedLTM, hideChar, hideOwner, hideGen, dashTok = nil, nil, nil, 0, nil
	local function setHidden(on, tok)
		if on then
			hideGen += 1
			local my = hideGen
			hideOwner = my
			task.delay(15, function() setHidden(false, my) end)
			if savedLTM and hideChar == ch.char then return my end
			if not ch.char then return my end
			savedLTM, hideChar = {}, ch.char
			for _, d in ipairs(ch.char:GetDescendants()) do
				if d:IsA("BasePart") or d:IsA("Decal") then savedLTM[d] = d.LocalTransparencyModifier d.LocalTransparencyModifier = 1 end
			end
			return my
		elseif savedLTM then
			if tok and tok ~= hideOwner then return end
			for d, v in pairs(savedLTM) do if d.Parent then d.LocalTransparencyModifier = v end end
			if tok and tok ~= dashTok then L.punch(1.1, 0.3) end
			savedLTM, hideChar, hideOwner = nil, nil, nil
		end
	end

	local function swarm(start, rate)
		local p = L.part({ Size = Vector3.one * 2, CFrame = CFrame.new(start) })
		local e = batE(p, { Rate = rate or 40, Speed = NR(1, 3), Lifetime = NR(0.5, 0.8), Shape = Enum.ParticleEmitterShape.Box })
		return p, e
	end


	local feetP = L.part({ Size = Vector3.new(5, 0.2, 5) })
	local burstP = L.part({ Size = Vector3.one * 2 })
	local auraMist = mistE(feetP, { Shape = Enum.ParticleEmitterShape.Box, EmissionDirection = Enum.NormalId.Top, Speed = NR(0.2, 0.6),
		Acceleration = Vector3.new(0, -0.15, 0), Size = NS({ K(0, 2), K(1, 4.5) }) })
	local batBurst = batE(burstP, { Speed = NR(10, 18), Lifetime = NR(0.9, 1.4), Drag = 1.5 })
	local dropBurst = dropE(burstP, { Speed = NR(8, 16), SpreadAngle = Vector2.new(70, 70), EmissionDirection = Enum.NormalId.Top, Lifetime = NR(0.7, 1.1) })
	local gSig, gSigM = L.mesh("disc.mesh", "glyph.png", C1, 1.8, Vector3.new(8, 1, 8))
	local gRing, gRingM = L.mesh("disc.mesh", "ring_c.png", C2, 2, Vector3.new(6, 1, 6))
	local gPool, gPoolM = L.mesh("disc.mesh", "glowui.png", GORE, 1, Vector3.new(6, 1, 6))
	local drip = dropE(L.new("Attachment", {}, burstP), { Rate = 0 })
	local dripP = L.part({ Size = Vector3.new(1.4, 0.2, 0.8) })
	local dripE = dropE(dripP, { Shape = Enum.ParticleEmitterShape.Box, Rate = 0, Speed = NR(0, 0.5) })

	local bats = {}
