	local crownIn, crownInM = L.mesh("disc.mesh", "ring_c.png", GORE, 1.2, Vector3.new(2.0, 1, 2.0))
	local crownG, crownGM = L.mesh("disc.mesh", "glowui.png", C1, 1.1, Vector3.new(3.2, 1, 3.2))
	local hang = {}
	for i = 1, 8 do
		local p, m = L.mesh("quad.mesh", "drop.png", C1, 1.25, Vector3.new(0.15, 1, 0.3))
		hang[i] = { p = p, m = m, a = i / 8 * math.pi * 2 + rnd(-0.15, 0.15), g = rnd(0, 1), sp = rnd(0.35, 0.6) }
	end
