	local fallE = dropE(fallP, { Rate = 0, Speed = NR(0, 0), SpreadAngle = Vector2.zero, Acceleration = Vector3.new(0, -26, 0), Lifetime = NR(0.5, 0.6),
		Size = NS({ K(0, 0.16), K(1, 0.1) }) })
	local haloLight = L.new("PointLight", { Color = C1, Range = 10, Brightness = 1.5, Shadows = false }, crown)

	local rig, light, hl = {}, nil, nil
	local function rebind()
		for _, o in ipairs(rig) do o:Destroy() end
		rig = {}
		local hrp = ch.hrp
		local function att(pos) local a = L.new("Attachment", { Position = pos }, hrp) rig[#rig + 1] = a return a end
		local function trail(a0, a1, props) local t = L.new("Trail", props, hrp) t.Attachment0, t.Attachment1 = a0, a1 rig[#rig + 1] = t return t end
		rig.main = trail(att(Vector3.new(0, 1.2, 0.3)), att(Vector3.new(0, -1.5, 0.3)), { Texture = L.T("beamb.png"), LightEmission = 0.2, Brightness = 1.5,
			Lifetime = 0.45, FaceCamera = true, Enabled = false, Color = CS({ CK(0, C2), CK(0.4, C1), CK(1, BLACK) }),
			Transparency = NS({ K(0, 0.2), K(1, 1) }), WidthScale = NS({ K(0, 1), K(1, 0.35) }) })
		local back = att(Vector3.new(0, -0.8, 0.6))
		rig.mist = mistE(back, { Speed = NR(0.5, 1.5), Lifetime = NR(0.9, 1.4), Size = NS({ K(0, 1.4), K(1, 3) }) })
		rig.bats = batE(att(Vector3.new(0, 0.5, 0.6)), { Speed = NR(4, 8), Lifetime = NR(0.6, 0.9), EmissionDirection = Enum.NormalId.Back, SpreadAngle = Vector2.new(50, 50) })
		for _, e in ipairs({ rig.mist, rig.bats }) do rig[#rig + 1] = e end
		light = L.new("PointLight", { Color = C1, Range = 14, Brightness = 0, Shadows = false }, hrp) rig[#rig + 1] = light
		hl = L.new("Highlight", { FillColor = C1, FillTransparency = 1, OutlineColor = C1, Adornee = ch.char, DepthMode = Enum.HighlightDepthMode.Occluded }, L.root)
		rig[#rig + 1] = hl
