	local function bodySet(base, off, tr, col)
		for g, cf in pairs(base) do
			if g.Parent then
				g.CFrame = cf - Vector3.new(0, off, 0)
				g.Transparency = tr
				if col then g.Color = col end
			end
		end
	end

	local function eyes(head, life)
		local ps, ms = {}, {}
		for i = 1, 2 do ps[i], ms[i] = L.mesh("disc.mesh", "glowui.png", C2, 4) end
