	end

	local function thorn(base, dir, w)
		if Vector3.new(dir.X, 0, dir.Z).Magnitude < 0.01 then dir = (dir + Vector3.new(0.02, 0, 0)).Unit end
		local p, m = L.mesh("shard.mesh", nil, GORE, 1.5, Vector3.new(w, 0.01, w))
		p.Color, p.Material, p.Transparency = GORE, Enum.Material.SmoothPlastic, 0 m.VertexColor = Vector3.one
		local cf0 = CFrame.lookAt(base, base + dir) * CFrame.Angles(-math.pi / 2, 0, 0)
		local function set(h, tr)
			h = math.max(h, 0.01)
			m.Scale = Vector3.new(w, h, w)
			p.CFrame = cf0 * CFrame.new(0, h / 2, 0)
			p.Transparency = tr or 0
		end
		set(0, 1)
		return p, set
	end
	local function shatter(pos, n, spd, s)
		for i = 1, n do
			local sc = i % 3 == 0 and C1 or GORE
			local p, m = L.mesh("shard.mesh", nil, sc, 1, Vector3.new(0.3, 0.8, 0.3) * rnd(0.6, 1.4) * s)
			p.Color, p.Material, p.Transparency = sc, Enum.Material.SmoothPlastic, 0 m.VertexColor = Vector3.one
			local v = Vector3.new(rnd(-1, 1), rnd(0.2, 1.1), rnd(-1, 1)).Unit * rnd(0.5, 1) * spd
			local p0 = pos + Vector3.new(rnd(-1, 1), rnd(0, 2), rnd(-1, 1)) * s
			local spin = CFrame.Angles(rnd(0, 6), rnd(0, 6), rnd(0, 6))
			local sx, sy = rnd(-8, 8), rnd(-8, 8)
