			end, { p })
		end
	end

	local function pillar(base, w)
		local outer = L.part({ Shape = Enum.PartType.Cylinder, Material = Enum.Material.Neon, Color = C1, Transparency = 0.35 })
		local inner = L.part({ Shape = Enum.PartType.Cylinder, Material = Enum.Material.SmoothPlastic, Color = GORE, Transparency = 0.06 })
		local top = L.part({ Size = Vector3.new(w, 0.2, w) })
