			inner.Size, inner.CFrame, inner.Transparency = Vector3.new(h, w * 0.7, w * 0.7), cf, on and 0.06 or 1
			top.CFrame = CFrame.new(base + Vector3.new(0, h, 0))
			sp.Rate = on and (rate or 0) or 0
		end
		set(0)
		return { outer, inner, top }, set
	end


	local function crossPillar(base, look, H)
		local w, bar, barY = H * 0.14, H * 0.6, H * 0.34
		local f = Vector3.new(look.X, 0, look.Z).Unit
		local rot = CFrame.lookAt(Vector3.zero, f)
