	end

	local function pool(o, size, life, grow)
		local p, m = L.mesh("disc.mesh", "glowui.png", GORE, 1.2)
		local q, qm = L.mesh("disc.mesh", "cracks_b.png", C1, 1.6)
		L.fx(life, function(k, t)
