		end, { p, q })
	end
	local function camBasis() return L.facing() end



	local function giant(G)
		local m = Instance.new("Model")
		local hrp = ch.hrp
		local parts = {}
		for _, p in ipairs(ch.char:GetDescendants()) do
			local ltm = savedLTM and savedLTM[p] or (p:IsA("BasePart") and p.LocalTransparencyModifier) or 1
			if p:IsA("BasePart") and p.Name ~= "HumanoidRootPart" and p.Transparency < 1 and ltm < 1 then
				local g = p:Clone()
				for _, d in ipairs(g:GetChildren()) do


					if d:IsA("SpecialMesh") then if d.MeshType == Enum.MeshType.FileMesh then d.Scale = d.Scale * G end elseif not d:IsA("DataModelMesh") then d:Destroy() end
				end
				g.Anchored, g.CanCollide, g.CanQuery, g.CanTouch, g.CastShadow = true, false, false, false, false
				g.Material, g.Color = Enum.Material.SmoothPlastic, BLACK
				if g:IsA("MeshPart") then g.TextureID = "" end
				g.Size = p.Size * G
				g.Transparency = 1
				g.Parent = m
				parts[g] = hrp.CFrame:ToObjectSpace(p.CFrame)
			end
		end
		local headRel = ch.head and hrp.CFrame:ToObjectSpace(ch.head.CFrame) or CFrame.new(0, 1.5, 0)
		m.Parent = L.root
		local cur = CFrame.identity
		local function set(anchor, tr)
			cur = anchor
			for g, rel in pairs(parts) do
				if g.Parent then g.CFrame = anchor * CFrame.new(rel.Position * G) * rel.Rotation g.Transparency = tr end
			end
		end
		local function head() return cur * CFrame.new(headRel.Position * G) * headRel.Rotation end
		return m, set, head
	end



	local function gravestone(base, out, s, kind)
		local STONE = Color3.fromRGB(38 + math.random(-6, 6), 30 + math.random(-5, 5), 34 + math.random(-5, 5))
		local lean = kind == 5 and 0.32 or 0.14
		local rot = CFrame.lookAt(Vector3.zero, out) * CFrame.Angles(rnd(-lean, lean * 0.5), 0, rnd(-lean, lean))
		local list, total = {}, 0
		local function add(props, rel, top)
			local p = L.part(props)
			list[#list + 1] = { p, rel }
			total = math.max(total, top or 0)
			return p
		end
		local function stone(sz, rel, top, shape)
			return add({ Shape = shape or Enum.PartType.Block, Material = Enum.Material.Slate, Color = STONE, Size = sz }, rel, top)
		end
		local function cross(y, k, z)
			add({ Material = Enum.Material.Neon, Color = C1, Size = Vector3.new(0.14 * k, 1.3 * k, 0.06) }, CFrame.new(0, y, -z - 0.02))
			add({ Material = Enum.Material.Neon, Color = C1, Size = Vector3.new(0.7 * k, 0.14 * k, 0.06) }, CFrame.new(0, y - 0.18 * k, -z - 0.02))
		end
		local cyl = Enum.PartType.Cylinder
		if kind == 1 then
			local W, H, D = 1.7 * s, 2.3 * s, 0.45 * s
			stone(Vector3.new(W, H, D), CFrame.new(0, H / 2, 0), H)
			stone(Vector3.new(D, W, W), CFrame.new(0, H, 0) * CFrame.Angles(0, math.pi / 2, 0), H + W / 2, cyl)
			cross(H * 0.6, s, D / 2)
		elseif kind == 2 then
			local P, Hh = 0.55 * s, 3.6 * s
			stone(Vector3.new(1.4 * s, 0.4 * s, 0.9 * s), CFrame.new(0, 0.2 * s, 0), 0.4 * s)
			stone(Vector3.new(P, Hh, P), CFrame.new(0, Hh / 2, 0), Hh)
			stone(Vector3.new(2 * s, P, P), CFrame.new(0, Hh * 0.33, 0), Hh)
			add({ Material = Enum.Material.Neon, Color = C1, Size = Vector3.new(0.1 * s, Hh * 0.8, 0.06) }, CFrame.new(0, Hh * 0.52, -P / 2 - 0.02))
			add({ Material = Enum.Material.Neon, Color = C1, Size = Vector3.new(1.6 * s, 0.1 * s, 0.06) }, CFrame.new(0, Hh * 0.33, -P / 2 - 0.02))
		elseif kind == 3 then
			local Sh, Hh = 0.8 * s, 3.4 * s
			stone(Vector3.new(1.4 * s, 0.5 * s, 1.4 * s), CFrame.new(0, 0.25 * s, 0), 0.5 * s)
			stone(Vector3.new(Sh, Hh, Sh), CFrame.new(0, 0.5 * s + Hh / 2, 0), 0.5 * s + Hh)
			stone(Vector3.new(Sh * 0.71, Sh * 0.71, Sh), CFrame.new(0, 0.5 * s + Hh, 0) * CFrame.Angles(0, 0, math.pi / 4), 0.5 * s + Hh + Sh * 0.5)
			cross(0.5 * s + Hh * 0.62, s * 0.75, Sh / 2)
		elseif kind == 4 then
			local W, H, D = 2 * s, 1.8 * s, 0.5 * s
			stone(Vector3.new(W, H, D), CFrame.new(0, H / 2, 0), H)
			stone(Vector3.new(W * 0.62, 0.38 * s, D), CFrame.new(0, H + 0.19 * s, 0), H + 0.38 * s)
			stone(Vector3.new(W * 1.1, 0.16 * s, D * 1.2), CFrame.new(0, H - 0.08 * s, 0), H)
			cross(H * 0.5, s * 0.85, D / 2)
		elseif kind == 5 then
			local W, H, D = 1.7 * s, 1.5 * s, 0.45 * s
			stone(Vector3.new(W, H, D), CFrame.new(0, H / 2, 0), H)
			stone(Vector3.new(W * 0.5, 0.35 * s, D), CFrame.new(-W * 0.25, H + 0.17 * s, 0) * CFrame.Angles(0, 0, 0.35), H + 0.4 * s)
			stone(Vector3.new(W, W * 0.7, D), CFrame.new(W * 0.35, D / 2, -W * 0.75) * CFrame.Angles(math.pi / 2 - 0.15, 0.6, 0), H)
			add({ Material = Enum.Material.Neon, Color = C1, Size = Vector3.new(W * 0.9, 0.08 * s, D + 0.04) }, CFrame.new(0, H - 0.05, 0) * CFrame.Angles(0, 0, -0.12))
			cross(H * 0.55, s * 0.8, D / 2)
		else
			local W, H, D = 1.1 * s, 0.75 * s, 0.35 * s
			stone(Vector3.new(W, H, D), CFrame.new(0, H / 2, 0), H)
			stone(Vector3.new(D, W, W), CFrame.new(0, H, 0) * CFrame.Angles(0, math.pi / 2, 0), H + W / 2, cyl)
			cross(H * 0.75, s * 0.55, D / 2)
		end
		local ps = {}
		for i, e in ipairs(list) do ps[i] = e[1] end
		local function set(h)
			local root = CFrame.new(base + Vector3.new(0, -total + total * h, 0)) * rot
			for _, e in ipairs(list) do
				e[1].CFrame = root * e[2]
				e[1].Transparency = h > 0.01 and 0 or 1
			end
		end
		set(0)
		return ps, set
	end

	local function arriveFull()
		local o = ch.feet



		local DUR, BLEED, FLARE, BEAT0, GATHER, FORM, OPEN, EYES, DIVE, RISE, FIN = 10.6, 0.6, 2.5, 1.5, 3.4, 4.0, 4.9, 5.2, 5.8, 6.5, 7.4
		local DRAIN = FIN + 1.2
		L.after(DUR - 2.6, function() L.handoff(o, "glyph.png", C1, 28, 8, 2.4, 1.8) end)
		local hideTok = setHidden(true)
		local S = L.screen(DUR)
		S.dimFn = function(t) return 0.18 * c01(t / 1) * (1 - c01((t - FIN - 1.2) / 1.5)) end
		S.style, S.c1, S.c2 = "vampire", C1, C2 S.boxFn = function(t) return c01((t - 0.2) / 0.6) * (1 - c01((t - (DUR - 1)) / 0.8)) end
		S.tintFn = function(t) return C1, 0.2 * c01(t / 1.2) * (1 - c01((t - FIN - 0.6) / 2)) end
		L.after(FIN + 0.35, function() S:title(L.name(), C1, C2) end)
		local fwd, right = camBasis()
		local mLow, mHigh = o + fwd * 110 + Vector3.new(0, 18, 0), o + fwd * 110 + Vector3.new(0, 52, 0)
		local MD = 30

		local moonB = L.part({ Shape = Enum.PartType.Ball, Material = Enum.Material.Neon, Color = W, Transparency = 1, Size = Vector3.one * MD })
		local bleed, bleedM = L.mesh("disc.mesh", "ring_b.png", C1, 2.2)
		local cor, corM = L.mesh("disc.mesh", "ring_c.png", C2, 3)
		local halo, haloM = L.mesh("disc.mesh", "glowui.png", C1, 1.8)
		local mDripP = L.part({ Size = Vector3.new(10, 0.5, 2) })
		local mDrip = dropE(mDripP, { Shape = Enum.ParticleEmitterShape.Box, Rate = 0, Speed = NR(0, 0.5), Acceleration = Vector3.new(0, -16, 0), Size = NS({ K(0, 1.6), K(1, 1.1) }),
			Lifetime = NR(1.6, 2.2), Color = CS(C1, GORE) })
		local fogP = L.part({ Size = Vector3.new(150, 0.2, 150), CFrame = CFrame.new(o) })
		local fog = mistE(fogP, { Shape = Enum.ParticleEmitterShape.Box, EmissionDirection = Enum.NormalId.Top, Speed = NR(0.2, 0.6), Lifetime = NR(3, 4),
			Size = NS({ K(0, 6), K(1, 14) }), Acceleration = Vector3.new(0, -0.1, 0) })
		local objs = { moonB, bleed, cor, halo, mDripP, fogP }

		local poolD, poolDM = L.mesh("disc.mesh", "glowui.png", GORE, 1.3)
		local poolC, poolCM = L.mesh("disc.mesh", "cracks_b.png", C1, 1.6)
		local sg, sgm = L.mesh("disc.mesh", "glyph.png", C1, 2)
		for _, x in ipairs({ poolD, poolC, sg }) do objs[#objs + 1] = x end
		local beats = {}
		for n = 0, 5 do beats[#beats + 1] = BEAT0 + n * 0.72 end

		local crosses = {}
		for i = 1, 18 do
			local a, d = i / 18 * math.pi * 2 * 5 + rnd(-0.2, 0.2), rnd(9, 50)
			local bp = o + Vector3.new(math.cos(a) * d, 0, math.sin(a) * d)
			local H = rnd(8, 15) * (1 + d / 80)
			local po, set = crossPillar(bp, o - bp, H)
			crosses[i] = { po = po, set = set, H = H, bp = bp, land = beats[(i - 1) % 6 + 1] + rnd(-0.04, 0.04), hit = false, drop = rnd(70, 100) }
			for _, x in ipairs(po) do objs[#objs + 1] = x end
		end


		local graves, spots, tries = {}, {}, 0
		while #spots < 55 and tries < 1500 do
			tries += 1
			local a, d = rnd(0, math.pi * 2), 5 + math.sqrt(rnd(0, 1)) * 70
			local pos = o + Vector3.new(math.cos(a) * d, 0, math.sin(a) * d)
			local sc = rnd(1.2, 1.8) * (1 + d / 45)
			local ok = true
			for _, q in ipairs(spots) do if (q.pos - pos).Magnitude < 1.7 * (q.sc + sc) + 1 then ok = false break end end
			if ok then spots[#spots + 1] = { pos = pos, sc = sc, d = d, a = a } end
		end
		for j, q in ipairs(spots) do
			local ya = q.a + rnd(-0.75, 0.75)
			local kind = math.random(1, 6)
			local po, set = gravestone(q.pos, Vector3.new(math.cos(ya), 0, math.sin(ya)), q.sc, kind)
			graves[j] = { po = po, set = set, pos = q.pos, at = 0.7 + (1 - q.d / 75) * 2.2 + rnd(0, 0.12), out = DRAIN + rnd(0, 0.8), bats = math.random() < 0.35, up = false, kind = kind, sc = q.sc }
			local moon = Color3.fromRGB(96, 88, 98):Lerp(Color3.fromRGB(70, 64, 72), rnd(0, 1))
			for _, x in ipairs(po) do objs[#objs + 1] = x if x.Material ~= Enum.Material.Neon then x.Color = moon end end
		end

		local thorns = {}
		local ASH = Color3.fromRGB(70, 62, 60)
		for c = 1, 14 do
			local a, d = c / 14 * math.pi * 2 + rnd(-0.15, 0.15), rnd(24, 60)
			local cen = o + Vector3.new(math.cos(a) * d, 0, math.sin(a) * d)
			local outv = (cen - o).Unit
			local t0 = 2.0 + rnd(0, 2.2)
			for n = 1, math.random(3, 5) do
				local base = cen + Vector3.new(rnd(-3, 3), -0.5, rnd(-3, 3))
				local dir = (Vector3.yAxis * 2.2 + outv * rnd(0.1, 0.9) + Vector3.new(rnd(-0.5, 0.5), 0, rnd(-0.5, 0.5))).Unit
				local w = rnd(1.4, 3) * (n == 1 and 1.4 or 1)
				local p, set = thorn(base, dir, w)
				local th = { p = p, set = set, base = base, dir = dir, h = rnd(10, 26) * (n == 1 and 1.3 or 1), t0 = t0 + n * 0.07 }
				if n <= 2 then
					th.rose = L.part({ Shape = Enum.PartType.Ball, Material = Enum.Material.Neon, Color = C1, Transparency = 1, Size = Vector3.one })
					th.rs = rnd(1.6, 2.6)
					objs[#objs + 1] = th.rose
				end
				thorns[#thorns + 1] = th
				objs[#objs + 1] = p
			end
		end


		local vines = {}
		local VINEC = Color3.fromRGB(78, 16, 26)
		local function vine(host, base, r, hgt, at, dur, th0, bud)
			local pts = {}
			local a0, spin = rnd(0, math.pi * 2), math.random() < 0.5 and 1 or -1
			local foot = base + Vector3.new(math.cos(a0) * r, 0.12, math.sin(a0) * r)
			local ra = a0 + rnd(-1.2, 1.2)
			local far = base + Vector3.new(math.cos(ra), 0, math.sin(ra)) * (r + rnd(4, 8)) + Vector3.new(0, 0.12, 0)
			local d = foot - far
			local m = (far + foot) / 2 + Vector3.new(-d.Z, 0, d.X).Unit * rnd(-2.5, 2.5)
			for j = 0, 4 do local u = j / 4 pts[#pts + 1] = far:Lerp(m, u):Lerp(m:Lerp(foot, u), u) end
			local turns = rnd(1.6, 2.4)
			local n = math.floor(turns * 7)
			for j = 1, n do
				local q = j / n
				local a = a0 + spin * q * turns * math.pi * 2
				local rr = r * (1 + 0.08 * math.sin(j * 1.7))
				pts[#pts + 1] = base + Vector3.new(math.cos(a) * rr, 0.12 + q * hgt, math.sin(a) * rr)
			end
			local len, cum = 0, { 0 }
			for j = 2, #pts do len += (pts[j] - pts[j - 1]).Magnitude cum[j] = len end
			local v = { host = host, at = at, dur = dur, segs = {} }
			for j = 1, #pts - 1 do
				local th = th0 * (1 - 0.55 * cum[j] / len)
				local p = L.part({ Shape = Enum.PartType.Cylinder, Material = Enum.Material.SmoothPlastic, Color = VINEC, Transparency = 1, Size = Vector3.new(0.1, th, th) })
				v.segs[j] = { p = p, a = pts[j], b = pts[j + 1], s0 = cum[j] / len, s1 = cum[j + 1] / len, th = th, f = -1 }
				host.po[#host.po + 1] = p
				objs[#objs + 1] = p
			end
			if bud then
				v.bud = L.part({ Shape = Enum.PartType.Ball, Material = Enum.Material.Neon, Color = C1, Transparency = 1, Size = Vector3.one * th0 * 2.4, CFrame = CFrame.new(pts[#pts]) })
				host.po[#host.po + 1] = v.bud
				objs[#objs + 1] = v.bud
			end
			vines[#vines + 1] = v
		end
		for _, c in ipairs(crosses) do
			local w = c.H * 0.14
			vine(c, c.bp, w * 0.78, c.H * 0.74, c.land + 0.08 + rnd(0, 0.2), rnd(0.55, 0.8), math.max(0.4, w * 0.42), true)
		end
		local GH, GR = { 3.0, 3.6, 3.9, 2.2, 1.5 }, { 0.95, 0.75, 0.75, 1.1, 0.95 }
		local nG = 0
		for _, g in ipairs(graves) do
			if g.kind <= 5 and nG < 16 and math.random() < 0.4 then
				nG += 1
				vine(g, g.pos, GR[g.kind] * g.sc, GH[g.kind] * g.sc * 0.85, g.at + 0.3 + rnd(0, 0.3), rnd(0.5, 0.75), math.max(0.3, 0.28 * g.sc), math.random() < 0.5)
			end
		end

		local batSkyP = L.part({ Size = Vector3.new(200, 1, 200), CFrame = CFrame.new(o + Vector3.new(0, 30, 0)) })
		local batSky = batE(batSkyP, { Shape = Enum.ParticleEmitterShape.Box, Rate = 0, Speed = NR(6, 12), Lifetime = NR(2.5, 4), Size = NS(2.2), SpreadAngle = Vector2.new(180, 40), Drag = 0.3 })
		objs[#objs + 1] = batSkyP

		local fig = mHigh - fwd * 14 - Vector3.new(0, 18, 0)
		local sw = {}
		local function wideAt(i, t) local a = i / 16 * math.pi * 2 + t * (i % 2 == 0 and 0.5 or -0.4) local r = 30 + (i % 4) * 9 return o + Vector3.new(math.cos(a) * r, 6 + (i % 3) * 6, math.sin(a) * r) end
		for i = 1, 16 do
			local p, e = swarm(o, 0)
			sw[i] = { p = p, e = e, a0 = i / 16 * math.pi * 2, s0 = wideAt(i, GATHER) }
			objs[#objs + 1] = p
		end

		local G = 9
		local gM, gSet, gHead = giant(G)
		objs[#objs + 1] = gM
		local gw = {}
		for i, side in ipairs({ 1, -1 }) do
			local p, m = L.mesh("quad.mesh", "batwing_b.png", BLACK, 1)
			p.Transparency = 1
			gw[i] = { p = p, m = m, side = side }
			objs[#objs + 1] = p
		end
		local gEyes = {}
		for i = 1, 2 do local p, m = L.mesh("disc.mesh", "glowui.png", C2, 4) p.Transparency = 1 gEyes[i] = { p = p, m = m } objs[#objs + 1] = p end
		local gAnchor = CFrame.lookAt(fig, Vector3.new(o.X, fig.Y, o.Z))

		local wsky = L.worldSky(o, DUR, { dome = Color3.fromRGB(55, 6, 14), atmC = Color3.fromRGB(120, 15, 30), decay = Color3.fromRGB(30, 0, 8),
			den = 0.32, haze = 1.8, glare = 0.3, oa = Color3.fromRGB(160, 70, 82), am = Color3.fromRGB(105, 45, 55), domeA = 0.7 })
		for _, x in ipairs(wsky.objs) do objs[#objs + 1] = x end
		local rainBig = L.part({ Size = Vector3.new(260, 1, 260), CFrame = CFrame.new(o + Vector3.new(0, 60, 0)) })
		local rainW = dropE(rainBig, { Shape = Enum.ParticleEmitterShape.Box, EmissionDirection = Enum.NormalId.Bottom, Speed = NR(55, 70), SpreadAngle = Vector2.zero,
			Acceleration = Vector3.new(0, -20, 0), Size = NS(0.4), Lifetime = NR(1, 1.3), Rate = 0 })
		objs[#objs + 1] = rainBig
		local function skyA(t) return c01(t / 1.2) * (1 - c01((t - FIN - 1) / 2)) end

		local capeP = L.part({ Size = Vector3.new(2.2, 0.3, 1.4) })
		local cape = dropE(capeP, { Shape = Enum.ParticleEmitterShape.Box, Rate = 0, Speed = NR(0, 0.6), Acceleration = Vector3.new(0, -26, 0), Size = NS({ K(0, 0.35), K(1, 0.22) }),
			Lifetime = NR(0.4, 0.7) })
		objs[#objs + 1] = capeP
		local riseOff = 3.4
		local bodyM, bodyB
		local flared, dove, eyesDone, fin, bi = false, false, false, false, 1
		local poolS = 0
		local debris, blasted = {}, false
		L.fx(DUR, function(k, t)
			local camP = workspace.CurrentCamera.CFrame.Position
			local rise = L.outQuad(c01(t / 1.6))
			local mpos = mLow:Lerp(mHigh, rise)
			local fade = c01((t - DRAIN) / 1.6)
			local vis = c01(t / 0.6) * (1 - fade)
			local toCam = (camP - mpos).Unit
			local sa = skyA(t)
			wsky.set(sa)
			rainW.Rate = 300 * sa
			fog.Rate = 14 * c01(t / 0.8) * (1 - c01((t - FIN) / 2))

			local bl = L.outQuad(c01((t - BLEED) / 1.8))
			moonB.CFrame = CFrame.new(mpos)
			moonB.Color = W:Lerp(C2, 0.35):Lerp(C1, bl)
			moonB.Transparency = math.max(0.06, 1 - vis)
			local bs = MD * (1.06 - 0.5 * bl)
			bleedM.Scale = Vector3.new(bs, 1, bs) bleed.CFrame = faceCam(mpos + toCam * (MD / 2 + 0.5))
			bleed.Transparency = 1 - 0.85 * vis * math.sin(math.min(bl, 0.999) * math.pi)
			mDripP.CFrame = CFrame.new(mpos - Vector3.new(0, MD * 0.47, 0) + toCam * 2)
			mDrip.Rate = bl > 0.6 and 5 * (1 - fade) or 0
			local fl = t >= FLARE and math.exp(-(t - FLARE) * 2.5) or 0
			if not flared and t >= FLARE then flared = true S:flash(C1, 0.25) S:shake(0.6, 0.3) end
			local cs = 36 + 4 * math.sin(t * 5) + 30 * fl
			cor.CFrame = faceCam(mpos - toCam * 3) corM.Scale = Vector3.new(cs, 1, cs)
			cor.Transparency = 1 - 0.9 * vis * c01((t - FLARE + 0.3) / 0.3)
			L.tint(corM, C2:Lerp(C1, 0.4 + 0.3 * math.sin(t * 5)):Lerp(W, 0.5 * fl), 3)
			local hs = 80 + 30 * bl + 60 * fl
			halo.CFrame = faceCam(mpos - toCam * 4) haloM.Scale = Vector3.new(hs, 1, hs)
			halo.Transparency = 1 - 0.55 * vis

			if bi <= #beats and t >= beats[bi] then
				local n = bi
				bi += 1
				poolS = math.min(14, 4 + n * 2)
				L.groundWave(o, "ring_c.png", C1, poolS * 0.6, poolS * 1.5, 0.5)
				S:shake(0.45 + 0.1 * n, 0.12)
			end
			local pk = 0
			if bi > 1 then pk = math.exp(-(t - beats[bi - 1]) * 6) end
			local ps = poolS * (1 + 0.12 * pk) * (1 - L.inQuad(c01((t - DRAIN) / 1.3)))
			poolDM.Scale = Vector3.new(ps, 1, ps) poolCM.Scale = Vector3.new(ps * 0.9, 1, ps * 0.9)
			poolD.CFrame = CFrame.new(o + Vector3.new(0, 0.05, 0)) poolC.CFrame = CFrame.new(o + Vector3.new(0, 0.07, 0)) * CFrame.Angles(0, t * 0.3, 0)
			poolD.Transparency = ps > 0.1 and 0.06 or 1
			poolC.Transparency = ps > 0.1 and (0.35 - 0.3 * pk) or 1
			local sgs = 30 * L.outQuad(c01((t - 0.5) / 2.2))
			sgm.Scale = Vector3.new(sgs, 1, sgs) sg.CFrame = CFrame.new(o + Vector3.new(0, 0.09, 0)) * CFrame.Angles(0, -t * 0.3, 0)
			sg.Transparency = 1 - (0.6 + 0.3 * pk) * c01(t / 0.6) * (1 - fade)
			L.tint(sgm, C1:Lerp(C2, fin and (1 - fade) or pk * 0.5), fin and 3 or 2)
			batSky.Rate = (t > 0.8 and t < FIN + 0.5) and 70 or 0
			local drainK = L.inQuad(c01((t - DRAIN) / 1.2))

			local function arm(obj, parts, pos)
				obj.bt = FIN + (Vector3.new(pos.X, o.Y, pos.Z) - o).Magnitude / 75
				obj.bparts, obj.bpos = parts, pos
			end
			if fin and not blasted then
				blasted = true
				for _, c in ipairs(crosses) do arm(c, c.po, c.bp) c.n = 4 c.set(c.H * 0.8, 0) end
				for _, g in ipairs(graves) do arm(g, g.po, g.pos) g.n = 2 end
				for _, th in ipairs(thorns) do arm(th, { th.p, th.rose }, th.base + th.dir * th.h * 0.4) th.n = 1 end
			end
			local function blast(obj)
				if obj.gone or not obj.bt or t < obj.bt then return obj.gone end
				obj.gone = true
				local out = Vector3.new(obj.bpos.X - o.X, 0, obj.bpos.Z - o.Z)
				out = out.Magnitude > 0.1 and out.Unit or Vector3.xAxis
				for _, p in ipairs(obj.bparts) do
					if p and p.Parent and p.Transparency < 1 then
						debris[#debris + 1] = { p = p, cf = p.CFrame, t0 = t, tr = p.Transparency,
							v = out * rnd(28, 55) + Vector3.new(rnd(-6, 6), rnd(14, 30), rnd(-6, 6)), sp = Vector3.new(rnd(-7, 7), rnd(-7, 7), rnd(-7, 7)) }
					end
				end
				shatter(obj.bpos + Vector3.new(0, 1.5, 0), obj.n, 24, 1.3)
				return true
			end
			for _, d in ipairs(debris) do
				local q = t - d.t0
				d.p.CFrame = CFrame.new(d.cf.Position + d.v * q + Vector3.new(0, -45 * q * q, 0)) * d.cf.Rotation * CFrame.Angles(d.sp.X * q, d.sp.Y * q, d.sp.Z * q)
				d.p.Transparency = math.max(d.tr, c01((q - 0.9) / 0.6))
			end
			for _, c in ipairs(crosses) do
				if blast(c) then continue end
				local u = (t - (c.land - 0.5)) / 0.5
				if u < 0 then c.set(0)
				elseif u < 1 then c.set(c.H * 0.8 + c.drop * (1 - u * u), 0)
				else
					if not c.hit then
						c.hit = true
						L.groundWave(c.bp, "cracks_b.png", C1, 1, c.H * 1.3, 0.9, 2)
						L.groundWave(c.bp, "ring_c.png", C2, 1, c.H * 1.6, 0.4)
						S:shake(0.5, 0.15)
					end
					c.set(c.H * 0.8 * (1 - drainK), (t - c.land) < 0.5 and 70 or 0)
				end
			end
			for _, g in ipairs(graves) do
				if blast(g) then continue end
				local u = c01((t - g.at) / 0.3)
				g.set(L.outBack(u) * (1 - L.inQuad(c01((t - g.out) / 0.7))))
				if not g.up and u > 0.3 then
					g.up = true
					if g.bats then burstP.CFrame = CFrame.new(g.pos + Vector3.new(0, 1.5, 0)) batBurst:Emit(10) end
				end
			end
			local wither = c01((t - FIN - 0.6) / 1.2)
			for _, th in ipairs(thorns) do
				if blast(th) then continue end
				local u = c01((t - th.t0) / 0.35)
				local h = th.h * L.outBack(u) * (1 - L.inQuad(c01((t - DRAIN - 0.3) / 1.1)))
				th.set(h, u > 0 and 0 or 1)
				th.p.Color = C1:Lerp(BLACK, 0.35):Lerp(ASH, wither)
				if th.rose then
					local b = L.outBack(c01((t - th.t0 - 0.45) / 0.4)) * (1 - wither)
					th.rose.Size = Vector3.one * math.max(0.05, th.rs * b)
					th.rose.CFrame = CFrame.new(th.base + th.dir * h)
					th.rose.Transparency = b > 0.02 and 0 or 1
				end
				if u > 0 and not th.shook then th.shook = true S:shake(0.35, 0.12) end
			end
			for _, v in ipairs(vines) do
				if v.host.gone then continue end
				local g = L.outQuad(c01((t - v.at) / v.dur))
				for _, sg in ipairs(v.segs) do
					local f = c01((g - sg.s0) / (sg.s1 - sg.s0))
					if math.abs(f - sg.f) > 0.001 then
						sg.f = f
						if f <= 0 then sg.p.Transparency = 1
						else
							local e = sg.a:Lerp(sg.b, f)
							local mid = (sg.a + e) / 2
							sg.p.Size = Vector3.new((e - sg.a).Magnitude + sg.th * 0.6, sg.th, sg.th)
							sg.p.CFrame = CFrame.lookAt(mid, mid + (sg.b - sg.a)) * CFrame.Angles(0, math.pi / 2, 0)
							sg.p.Transparency = 0
						end
					end
				end
				if v.bud and not v.budOn and t > v.at + v.dur then v.budOn = true v.bud.Transparency = 0 end
			end

			local gIn = c01((t - FORM) / 0.8) * (1 - c01((t - DIVE) / 0.12))
			gSet(gAnchor * CFrame.new(0, 0.6 * math.sin(t * 1.3) * G * 0.1, 0), gIn > 0 and math.max(0.06, 1 - gIn) or 1)
			local open = L.outBack(c01((t - OPEN) / 0.45))
			local flap = t > OPEN and 12 * math.sin((t - OPEN) * 2.6) or 0
			local wrap = 1 - open
			local yaw, roll = math.rad(-25 + 190 * wrap), math.rad(20 - 80 * wrap + flap)
			local S2 = (5.2 + 3.8 * open) * G * 0.9
			for _, w in ipairs(gw) do
				local piv = gAnchor * CFrame.new(w.side * (0.45 + 0.6 * wrap) * G, (1.3 + 0.4 * wrap) * G, (0.35 - 1.1 * wrap) * G) * CFrame.Angles(0, w.side == 1 and 0 or math.pi, 0)
				w.p.CFrame = piv * CFrame.Angles(0, w.side * yaw, 0) * CFrame.Angles(0, 0, roll) * CFrame.Angles(math.rad(-90), 0, 0) * CFrame.new(0.47 * S2, 0, -0.10 * S2)
				w.m.Scale = Vector3.new(S2, 1, S2)
				w.p.Transparency = gIn > 0 and math.max(0.06, 1 - gIn) or 1
			end
			local eA = c01((t - EYES) / 0.25) * (1 - c01((t - DIVE) / 0.1))
			local hc = gHead()
			for i, e in ipairs(gEyes) do
				e.p.CFrame = faceCam((hc * CFrame.new((i == 1 and -1 or 1) * 0.22 * G, 0.1 * G, -0.64 * G)).Position)
				local s = (0.4 + 0.08 * math.sin(t * 9)) * G
				e.m.Scale = Vector3.new(s * 1.7, 1, s * 0.8)
				e.p.Transparency = eA > 0 and math.max(0.06, 1 - eA) or 1
			end
			if not eyesDone and t >= EYES then eyesDone = true S:flash(C2, 0.2) S:shake(0.8, 0.3) end

			for i, s in ipairs(sw) do
				if t > 0.8 and t < GATHER then
					s.p.CFrame = CFrame.new(wideAt(i, t))
					s.e.Rate = 60
				elseif t >= GATHER and t < FORM + 0.6 then
					local u = c01((t - GATHER) / (FORM + 0.6 - GATHER))
					local a = s.a0 + u * 6
					local c = s.s0:Lerp(fig + Vector3.new(0, 0.5 * G, 0), L.inQuad(u))
					s.p.CFrame = CFrame.new(c + Vector3.new(math.cos(a), 0, math.sin(a)) * 18 * (1 - u))
					s.e.Rate = 90
				elseif t >= DIVE and t < RISE then
					local u = c01((t - DIVE) / (RISE - DIVE))
					local from = fig + Vector3.new(0, 0.5 * G, 0)
					local mid = from:Lerp(o, 0.5) + Vector3.new(0, 25, 0) + right * ((i % 2 == 0) and 25 or -25)
					local p1 = from:Lerp(mid, u):Lerp(mid:Lerp(o + Vector3.new(0, 2, 0), u), u)
					s.p.CFrame = CFrame.new(p1)
					s.e.Rate = 140
				elseif t >= RISE and t < FIN then
					local a = s.a0 + t * 7
					s.p.CFrame = CFrame.new(o + Vector3.new(math.cos(a) * 2.6, 1.5 + (i % 3) * 1.2, math.sin(a) * 2.6))
					s.e.Rate = 50
				else
					s.e.Rate = 0
				end
			end
			if not dove and t >= DIVE then
				dove = true
				burstP.CFrame = CFrame.new(fig + Vector3.new(0, 0.5 * G, 0)) batBurst:Emit(60)
				S:shake(1.4, 0.5)
				eyes(function() return ch.head.CFrame - Vector3.new(0, riseOff, 0) end, FIN - DIVE + 0.35)
				bodyM, bodyB = body(BLACK)
				objs[#objs + 1] = bodyM
			end

			if bodyB and not fin then
				local u = c01((t - RISE) / 0.85)
				riseOff = 3.4 * (1 - (1 - (1 - u) ^ 2))
				bodySet(bodyB, riseOff, 0.06, BLACK:Lerp(C1, 0.35 * u))
				if t >= RISE then S:shake(0.25 + 0.5 * u, 0.12) end
				capeP.CFrame = CFrame.new(o + Vector3.new(0, 4.4 - riseOff, 0))
				cape.Rate = t >= RISE and 90 or 0
			end
			if not fin and t >= FIN then
				fin = true
				cape.Rate = 0
				if bodyM then bodyM:Destroy() end
				appear(C2, 0.1, hideTok)
				S:flash(C2, 0.85) S:shake(2.8, 1.2)
				burstP.CFrame = CFrame.new(o + Vector3.new(0, 3, 0)) batBurst:Emit(80) dropBurst:Emit(50)
				L.groundWave(o, "ring_c.png", C2, 3, 46, 0.7)
				L.groundWave(o, "ring_c.png", C1, 3, 30, 1)
				L.groundWave(o, "ring_c.png", C1, 10, 1400, 5.4, 2.6)
				L.after(1.3, function() shatter(o + Vector3.new(0, 0.5, 0), 22, 26, 1.2) end)
			end
			if fin then hl.FillTransparency = math.min(1, hl.FillTransparency + 0.012) end
		end, objs)
		task.delay(DUR + 0.1, function() setHidden(false, hideTok) end)
	end


	local shorts = {}
	local function fadeHl() hl.FillTransparency = math.min(1, hl.FillTransparency + 0.025) end
	local function headCF() return ch.head and ch.head.CFrame or CFrame.new(ch.feet + Vector3.new(0, 4.5, 0)) end


	local WRX, WRZ = 0.47, -0.10
	local function batWings()
		local ws = {}
		for i, side in ipairs({ 1, -1 }) do
			local p, m = L.mesh("quad.mesh", "batwing_b.png", GORE, 1.6)
			p.Transparency = 1
			ws[i] = { p = p, m = m, side = side }
		end
		function ws.set(cf, wrap, S, tr, flap, col)
			local yaw, roll = math.rad(-25 + 190 * wrap), math.rad(20 - 80 * wrap + (flap or 0))
			for _, w in ipairs(ws) do
				local piv = cf * CFrame.new(w.side * (0.45 + 0.6 * wrap), 1.3 + 0.4 * wrap, 0.35 - 1.1 * wrap) * CFrame.Angles(0, w.side == 1 and 0 or math.pi, 0)
				w.p.CFrame = piv * CFrame.Angles(0, w.side * yaw, 0) * CFrame.Angles(0, 0, roll) * CFrame.Angles(math.rad(-90), 0, 0) * CFrame.new(WRX * S, 0, WRZ * S)
				w.m.Scale = Vector3.new(S, 1, S)
				w.p.Transparency = tr
				if col then L.tint(w.m, col, 1.6) end
			end
		end
		return ws
	end


	shorts[1] = function()
		local o = ch.feet
		local DUR, WRAP, SNAP = 2.9, 0.75, 1.6
		local hideTok = setHidden(true)
		local sw, objs = {}, {}
		for i = 1, 3 do
			local p, e = swarm(o + Vector3.new(0, 34, 0), 90)
			sw[i] = { p = p, e = e, a0 = i / 3 * math.pi * 2 }
			objs[#objs + 1] = p
		end
		local sh, shM = L.mesh("disc.mesh", "darkdisc.png", BLACK, 1)
		local rg, rgM = L.mesh("disc.mesh", "ring_c.png", C1, 2)
		local wings = batWings()
		for _, x in ipairs({ sh, rg, wings[1].p, wings[2].p }) do objs[#objs + 1] = x end
		local bM, bB
		local wrapped, snapped, shed = false, false, false
		L.fx(DUR, function(k, t)
			local u = c01(t / WRAP)
			for _, s in ipairs(sw) do
				local a = s.a0 + t * 9
				local R = wrapped and 1.4 or (1.2 + 2.6 * (1 - u))
				local H = wrapped and (2.6 + math.sin(t * 6 + s.a0)) or (3 + 31 * (1 - L.inQuad(u)))
				s.p.CFrame = CFrame.new(o + Vector3.new(math.cos(a) * R, H, math.sin(a) * R))
				s.e.Rate = snapped and 0 or (wrapped and 25 or 90)
			end
			local sz = 2 + 7 * u
			shM.Scale, rgM.Scale = Vector3.new(sz, 1, sz), Vector3.new(sz * 0.8, 1, sz * 0.8)
			sh.CFrame = CFrame.new(o + Vector3.new(0, 0.04, 0))
			rg.CFrame = CFrame.new(o + Vector3.new(0, 0.07, 0)) * CFrame.Angles(0, t * 2, 0)
			sh.Transparency = 1 - 0.7 * u * (1 - c01((t - SNAP) / 0.6))
			rg.Transparency = 1 - 0.8 * u * (1 - c01((t - WRAP) / 0.4))
			if not wrapped and t >= WRAP then
				wrapped = true
				bM, bB = body(BLACK)
				objs[#objs + 1] = bM
				bodySet(bB, 0, 0.06)
				eyes(headCF, SNAP - WRAP + 0.15)
				L.punch(1.4, 0.3, C1, 0.25)
				L.groundWave(o, "ring_c.png", C1, 2, 12, 0.45)
				burstP.CFrame = CFrame.new(o + Vector3.new(0, 3, 0)) batBurst:Emit(25)
			end
			if wrapped then
				local sn = snapped and L.outBack(c01((t - SNAP) / 0.22)) or 0
				local flap = snapped and math.sin((t - SNAP) * 7) * 10 * math.exp(-(t - SNAP) * 2) or 0
				local wt = snapped and c01((t - (DUR - 0.6)) / 0.4) or 1 - c01((t - WRAP) / 0.12)
				wings.set(ch.hrp.CFrame, (1 - sn) + (snapped and 0 or 0.04 * math.sin(t * 5)), 5.2 + 3.8 * sn, 0.04 + 0.96 * wt, flap, snapped and C1:Lerp(GORE, 0.35) or C1:Lerp(GORE, 0.75))
			else
				wings.set(ch.hrp.CFrame, 1, 5.2, 1)
			end
			if not snapped and t >= SNAP then
				snapped = true
				if bM then bM:Destroy() end
				appear(C1, 0.3, hideTok)
				L.punch(1.7, 0.35, C1, 0.35)
				burstP.CFrame = CFrame.new(o + Vector3.new(0, 3.5, 0)) batBurst:Emit(50)
				L.groundWave(o, "ring_c.png", C2, 3, 20, 0.55)
				L.groundWave(o, "glyph.png", C1, 4, 13, 1, 1.8)
			end
			if snapped and not shed and t >= DUR - 0.6 then
				shed = true
				for _, w in ipairs(wings) do burstP.CFrame = w.p.CFrame batBurst:Emit(18) end
			end
			if snapped then fadeHl() end
		end, objs)
		task.delay(DUR + 0.1, function() setHidden(false, hideTok) if bM and bM.Parent then bM:Destroy() end end)
	end


	shorts[2] = function()
		local o = ch.feet
		local DUR, RISE, CHAIN, STRAIN, RIP = 2.9, 0.15, 0.55, 1.0, 1.55
		local hideTok = setHidden(true)
		local STEEL = Color3.fromRGB(205, 150, 160)
		local sg, sgM = L.mesh("disc.mesh", "glyph.png", C1, 1.8)
		local bk, bkM = L.mesh("disc.mesh", "darkdisc.png", BLACK, 1)
		local bM, bB = body(BLACK)
		local gh = L.new("Highlight", { FillTransparency = 1, OutlineColor = C1, OutlineTransparency = 0.4, Adornee = bM, DepthMode = Enum.HighlightDepthMode.Occluded }, L.root)
		local objs = { sg, bk, bM, gh }
		local chains = {}
		for i = 1, 6 do
			local a = i / 6 * math.pi * 2 + 0.25
			local A = o + Vector3.new(math.cos(a) * 5.2, 0.1, math.sin(a) * 5.2)
			local B = o + Vector3.new(math.cos(a + 2.4) * 0.6, (i % 2 == 0) and 3.8 or 2.3, math.sin(a + 2.4) * 0.6)
			local a0, a1 = L.att(A), L.att(A)
			local bm = L.beam(a0, a1, { Texture = L.T("chain.png"), TextureMode = Enum.TextureMode.Wrap, TextureLength = 1.5, LightEmission = 0, Brightness = 2,
				Width0 = 0.95, Width1 = 0.95, Color = CS(STEEL), Transparency = NS(0) })
			for _, x in ipairs({ a0, a1, bm }) do objs[#objs + 1] = x end
			chains[i] = { A = A, B = B, a1 = a1, bm = bm, at = CHAIN + (i - 1) * 0.07, ph = rnd(0, 6) }
		end
		local glowP = L.part({ Size = Vector3.one, CFrame = CFrame.new(o + Vector3.new(0, 3, 0)) })
		local glow = L.new("PointLight", { Color = C1, Range = 14, Brightness = 0, Shadows = false }, glowP)
		objs[#objs + 1] = glowP
		local ripped, rAt, hits, fly = false, 0, 0, {}
		L.fx(DUR, function(k, t)
			local open = L.outBack(c01(t / 0.3))
			local fade = ripped and c01((t - rAt - 0.4) / 0.6) or 0
			sgM.Scale, bkM.Scale = Vector3.new(10 * open, 1, 10 * open), Vector3.new(11.5 * open, 1, 11.5 * open)
			sg.CFrame = CFrame.new(o + Vector3.new(0, 0.08, 0)) * CFrame.Angles(0, -t * 0.8, 0)
			bk.CFrame = CFrame.new(o + Vector3.new(0, 0.04, 0))
			sg.Transparency = 0.15 + 0.85 * fade
			bk.Transparency = 0.4 + 0.6 * fade
			local strain = c01((t - STRAIN) / (RIP - STRAIN))
			if not ripped then
				local off = 5 * (1 - L.outQuad(c01((t - RISE) / 0.4)))
				local sh = 0.12 * strain * math.sin(t * 55)
				for g, cf in pairs(bB) do
					if g.Parent then g.CFrame = cf * CFrame.new(sh, -off, 0) g.Transparency = 0.06 g.Color = BLACK:Lerp(GORE, strain) end
				end
				gh.OutlineTransparency = 0.4 - 0.4 * strain
				L.tint(sgM, C1:Lerp(W, 0.3 * strain), 1.8)
				for _, cn in ipairs(chains) do
					local grow = L.outQuad(c01((t - cn.at) / 0.15))
					cn.a1.WorldPosition = cn.A:Lerp(cn.B, grow) + Vector3.new(0, 0.08 * strain * math.sin(t * 60 + cn.ph), 0)
					cn.bm.Transparency = NS(grow > 0 and 0 or 1)
					if grow >= 1 and not cn.hit then
						cn.hit = true hits += 1
						if hits % 2 == 1 then L.punch(0.6, 0.15, C1, 0.12) end
					end
					if strain > 0 then cn.bm.Color = CS(STEEL:Lerp(C1, strain)) cn.bm.LightEmission = 0.5 * strain end
				end
				glow.Brightness = 1 + 4 * strain
			end
			if not ripped and t >= RIP then
				ripped, rAt = true, t
				local c = o + Vector3.new(0, 3, 0)
				for g in pairs(bB) do
					if g.Parent then
						local d = Vector3.new(g.Position.X - c.X, 0, g.Position.Z - c.Z)
						d = d.Magnitude > 0.05 and d.Unit or Vector3.new(rnd(-1, 1), 0, rnd(-1, 1)).Unit
						fly[g] = { cf0 = g.CFrame, v = d * rnd(16, 26) + Vector3.new(0, rnd(4, 12), 0), sp = Vector3.new(rnd(-9, 9), rnd(-9, 9), rnd(-9, 9)) }
						g.Material, g.Color = Enum.Material.Neon, C1
					end
				end
				gh.OutlineTransparency = 1
				appear(C2, 0.15, hideTok)
				L.punch(2, 0.4, C1, 0.45)
				burstP.CFrame = CFrame.new(c) batBurst:Emit(30) dropBurst:Emit(40)
				L.groundWave(o, "ring_c.png", C2, 3, 24, 0.55)
				L.groundWave(o, "glyph.png", C1, 4, 13, 1, 2.2)
				glow.Brightness = 10
			end
			if ripped then
				local q = t - rAt
				for g, d in pairs(fly) do
					if g.Parent then
						local pos = d.cf0.Position + d.v * q + Vector3.new(0, -40 * q * q, 0)
						if pos.Y < o.Y + 0.15 then pos = Vector3.new(pos.X, o.Y + 0.15, pos.Z) end
						g.CFrame = CFrame.new(pos) * d.cf0.Rotation * CFrame.Angles(d.sp.X * q, d.sp.Y * q, d.sp.Z * q)
						g.Color = C1:Lerp(BLACK, c01(q / 0.35))
						g.Transparency = math.max(0.06, c01((q - 0.4) / 0.5))
					end
				end
				for _, cn in ipairs(chains) do
					local r = L.inQuad(c01(q / 0.25))
					local dir = (cn.B - cn.A)
					cn.a1.WorldPosition = cn.A + dir * (1 + 0.6 * (1 - r)) * (1 - r)
					cn.bm.Transparency = NS(r)
				end
				glow.Brightness = math.max(0, glow.Brightness - 0.4)
				fadeHl()
			end
		end, objs)
		task.delay(DUR + 0.1, function() setHidden(false, hideTok) if bM and bM.Parent then bM:Destroy() end end)
	end



	shorts[3] = function()
		local o = ch.feet
		local DUR, FALL, LID, TIP = 3.2, 0.45, 1.4, 1.75
		local KNOCKS = { 0.85, 1.1 }
		local hideTok = setHidden(true)

		local f0, r0 = L.facing()
		local fwd, rt = -f0, -r0
		local face = CFrame.lookAt(o, o - fwd)
		local WOOD, LIDC = Color3.fromRGB(18, 7, 9), Color3.fromRGB(28, 10, 12)
		local D, SC = 1.8, 1.35
		local pieces, lid = {}, {}
		local function add(l, size, mat, col, isLid)
			l, size = CFrame.new(l.Position * SC) * l.Rotation, size * SC
			local pc = { p = L.part({ Size = size, Material = mat, Color = col, Transparency = 0 }), l = l }
			pieces[#pieces + 1] = pc
			if isLid then lid[#lid + 1] = pc end
			return pc.p
		end
		local outline = { Vector2.new(-0.8, 0), Vector2.new(-1.55, 5), Vector2.new(-1, 7.2), Vector2.new(1, 7.2), Vector2.new(1.55, 5), Vector2.new(0.8, 0) }
		local function half(y) if y <= 5 then return 0.8 + 0.75 * y / 5 end return 1.55 - 0.55 * (y - 5) / 2.2 end
		for i = 1, #outline do
			local a, b = outline[i], outline[i % #outline + 1]
			local mid, len = (a + b) / 2, (b - a).Magnitude
			add(CFrame.new(mid.X, mid.Y, 0) * CFrame.Angles(0, 0, math.atan2(b.Y - a.Y, b.X - a.X)), Vector3.new(len + 0.2, 0.2, D), Enum.Material.Wood, WOOD)
		end
		local N = 12
		for i = 1, N do
			local yc = (i - 0.5) * 7.2 / N
			local w = 2 * half(yc)
			add(CFrame.new(0, yc, -D / 2), Vector3.new(w, 7.2 / N + 0.02, 0.15), Enum.Material.Wood, LIDC, true)
			add(CFrame.new(0, yc, D / 2), Vector3.new(w, 7.2 / N + 0.02, 0.15), Enum.Material.Wood, WOOD)
		end

		add(CFrame.new(0, 3.6, D / 2 - 0.1), Vector3.new(2.2, 6.6, 0.05), Enum.Material.Fabric, GORE)
		add(CFrame.new(0, 4.1, -D / 2 - 0.1), Vector3.new(0.24, 3.4, 0.06), Enum.Material.Neon, C1, true)
		add(CFrame.new(0, 3.2, -D / 2 - 0.1), Vector3.new(1.5, 0.24, 0.06), Enum.Material.Neon, C1, true)
		local cracks = {}
		for i = 1, 6 do
			local y = rnd(0.8, 6.6)
			local hw = half(y) * 0.75
			local p = add(CFrame.new(rnd(-hw, hw), y, -D / 2 - 0.09) * CFrame.Angles(0, 0, rnd(-1.3, 1.3)), Vector3.new(rnd(0.7, 1.5), 0.07, 0.04), Enum.Material.Neon, C2, true)
			p.Transparency = 1
			cracks[i] = p
		end
		local glowP = L.part({ Size = Vector3.one, CFrame = CFrame.new(o + Vector3.new(0, 4, 0)) })
		local glow = L.new("PointLight", { Color = C1, Range = 10, Brightness = 0, Shadows = false }, glowP)
		local puffP = L.part({ Size = Vector3.new(5, 0.2, 3), CFrame = CFrame.new(o + Vector3.new(0, 0.1, 0)) })
		local puff = mistE(puffP, { Shape = Enum.ParticleEmitterShape.Box, EmissionDirection = Enum.NormalId.Top, Speed = NR(3, 7), Lifetime = NR(0.6, 1),
			Color = CS(GORE, BLACK), Size = NS({ K(0, 1.5), K(1, 3.5) }) })

		local mistP = L.part({ Size = Vector3.new(2.4, 6, 0.4) })
		local pour = mistE(mistP, { Shape = Enum.ParticleEmitterShape.Box, Speed = NR(3, 7), Lifetime = NR(1.2, 1.8), Drag = 1.2, Acceleration = Vector3.new(0, -2.5, 0),
			Color = CS(C1, GORE), LightEmission = 0.35, Size = NS({ K(0, 2), K(1, 5) }), Transparency = NS({ K(0, 1), K(0.2, 0.35), K(1, 1) }) })
		local objs = { glowP, puffP, mistP }
		for _, pc in ipairs(pieces) do objs[#objs + 1] = pc.p end
		local landed, ki, lastK, lidOff, lAt, lidCF0, revealed = false, 1, nil, false, 0, nil, false
		local lv = -fwd * 6 + rt * (math.random() < 0.5 and -7 or 7) + Vector3.new(0, 24, 0)
		L.fx(DUR, function(k, t)
			local base
			if t < FALL then
				local u = L.inQuad(c01(t / FALL))
				base = face * CFrame.new(0, 34 * (1 - u), 0) * CFrame.Angles(0, (1 - u) * 4, 0)
			else
				if not landed then
					landed, lastK = true, t
					L.punch(2, 0.35, C1, 0.3)
					puff:Emit(30)
					L.groundWave(o, "cracks_b.png", C1, 3, 16, 1.2, 1.8)
					L.groundWave(o, "ring_c.png", C2, 2, 18, 0.5)
				end
				if KNOCKS[ki] and t >= KNOCKS[ki] then
					lastK = t
					for j = 1, math.min(#cracks, ki * 3) do cracks[j].Transparency = 0 end
					burstP.CFrame = CFrame.new(o + Vector3.new(0, 3.5, 0) - fwd * 1.2) dropBurst:Emit(6 + ki * 3)
					L.punch(0.7, 0.15, C1, 0.12)
					ki += 1
				end
				local jx = lastK and math.exp(-(t - lastK) * 9) or 0
				local wob = CFrame.new(math.sin(t * 60) * 0.14 * jx, -0.25 * jx, 0) * CFrame.Angles(math.sin(t * 38) * 0.04 * jx, 0, math.sin(t * 45) * 0.07 * jx)

				local tp = L.inQuad(c01((t - TIP) / 0.55))
				local hinge = CFrame.new(0, 0, D / 2 * SC)
				base = face * wob * CFrame.new(0, -2.5 * c01((t - TIP - 0.45) / 0.6), 0) * hinge * CFrame.Angles(math.rad(85) * tp, 0, 0) * hinge:Inverse()
				glow.Brightness = lidOff and math.max(0, 10 - (t - lAt) * 12) or 0.4 + 2.5 * jx
			end
			if not lidOff and t >= LID then
				lidOff, lAt = true, t
				lidCF0 = base * CFrame.new(0, 3.6 * SC, -D / 2 * SC)
				for _, pc in ipairs(lid) do pc.rel = lidCF0:Inverse() * (base * pc.l) end
				L.punch(1.6, 0.35, C1, 0.35)
				mistP.CFrame = face * CFrame.new(0, 3.6 * SC, -D / 2 * SC)
				pour:Emit(30) pour.Rate = 45
				burstP.CFrame = mistP.CFrame batBurst:Emit(30)
			end
			if lidOff and not revealed and t >= LID + 0.12 then revealed = true appear(C1, 0.3, hideTok) end
			if lidOff and t >= LID + 0.6 then pour.Rate = 0 end
			local q = t - lAt
			local lidCF = lidOff and CFrame.new(lidCF0.Position + lv * q + Vector3.new(0, -34 * q * q, 0)) * lidCF0.Rotation * CFrame.Angles(q * 14, q * 3, q * 6) or nil
			for _, pc in ipairs(pieces) do
				if lidOff and pc.rel then
					pc.p.CFrame = lidCF * pc.rel
					if pc.p.Transparency < 1 then pc.p.Transparency = math.max(0, c01((q - 0.7) / 0.4)) end
				else
					pc.p.CFrame = base * pc.l
					if t > TIP + 0.6 then pc.p.Transparency = c01((t - TIP - 0.6) / 0.5) end
				end
			end
			if revealed then fadeHl() end
		end, objs)
		task.delay(DUR + 0.1, function() setHidden(false, hideTok) end)
	end


	shorts[4] = function()
		local o = ch.feet
		local DUR, GROW, BLOOM, BURST = 3.1, 0.9, 0.95, 1.85
		local BEATS = { 1.35, 1.6 }
		local hideTok = setHidden(true)
		local H, NV, SEG = 6.6, 8, 16
		local VINE = Color3.fromRGB(34, 10, 14)
		local function R(y) return 0.5 + 1.7 * math.sin(math.pi * c01(y / H)) ^ 0.8 end
		local function P(v, s)
			local y = s * H
			local a = v / NV * math.pi * 2 + s * 3.2 * (v % 2 == 0 and 1 or -1)
			return o + Vector3.new(math.cos(a) * R(y), y, math.sin(a) * R(y))
		end
		local segs, thorns, roses, objs = {}, {}, {}, {}
		for v = 1, NV do
			for j = 1, SEG do
				local s0, s1 = (j - 1) / SEG, j / SEG
				local p0, p1 = P(v, s0), P(v, s1)
				local th = 0.34 - 0.16 * s0
				local p = L.part({ Shape = Enum.PartType.Cylinder, Material = Enum.Material.SmoothPlastic, Color = VINE, Transparency = 1,
					Size = Vector3.new((p1 - p0).Magnitude + 0.08, th, th), CFrame = CFrame.lookAt((p0 + p1) / 2, p1) * CFrame.Angles(0, math.pi / 2, 0) })
				segs[#segs + 1] = { p = p, s = s0, at = (v - 1) * 0.04 }
				objs[#objs + 1] = p
				if j % 2 == 0 and j < SEG then
					local out = Vector3.new(p0.X - o.X, 0, p0.Z - o.Z).Unit + Vector3.new(0, 0.5, 0)
					local tp, tset = thorn(p0, out.Unit, 0.22)
					thorns[#thorns + 1] = { p = tp, set = tset, s = s0, at = (v - 1) * 0.04 }
					objs[#objs + 1] = tp
				end
			end
		end
		for i = 1, 12 do
			local v, s = (i * 3 - 1) % NV + 1, 0.2 + 0.62 * ((i * 0.618) % 1)
			local c = P(v, s)
			local n = Vector3.new(c.X - o.X, 0, c.Z - o.Z).Unit
			local F = CFrame.lookAt(c + n * 0.15, c + n * 1.15) * CFrame.Angles(-math.pi / 2, 0, 0)
			local rose = { F = F, at = BLOOM + i * 0.05, pet = {} }
			for j = 1, 6 do
				local pp, pm = L.mesh("quad.mesh", "petal.png", j % 2 == 0 and C1 or GORE, 1.4)
				pp.Transparency = 1
				rose.pet[j] = { p = pp, m = pm, a = j / 6 * math.pi * 2 }
				objs[#objs + 1] = pp
			end
			roses[i] = rose
		end

		local shell = L.part({ Material = Enum.Material.SmoothPlastic, Color = BLACK, Transparency = 1 })
		local shM = L.new("SpecialMesh", { MeshType = Enum.MeshType.Sphere }, shell)
		objs[#objs + 1] = shell
		local cP = L.part({ Size = Vector3.new(4, 5, 4), CFrame = CFrame.new(o + Vector3.new(0, 3.3, 0)) })
		local glow = L.new("PointLight", { Color = C1, Range = 12, Brightness = 0, Shadows = false }, cP)
		local storm = L.pe(cP, { Texture = L.T("petal.png"), Shape = Enum.ParticleEmitterShape.Box, Color = CS(C2, GORE), LightEmission = 0.2, Size = NS({ K(0, 0.6), K(1, 0.4) }),
			Lifetime = NR(1.2, 1.8), Speed = NR(14, 26), SpreadAngle = Vector2.new(180, 180), Drag = 2.2, Rotation = NR(0, 360), RotSpeed = NR(-300, 300), Acceleration = Vector3.new(0, -3, 0),
			Transparency = NS({ K(0, 0), K(0.75, 0), K(1, 1) }) })
		objs[#objs + 1] = cP
		local burst, bAt, bi, bloomed, fly = false, 0, 1, false, {}
		L.fx(DUR, function(k, t)
			if not burst then
				for _, sg in ipairs(segs) do sg.p.Transparency = (L.outQuad(c01((t - sg.at) / GROW)) >= sg.s) and 0 or 1 end
				for _, th in ipairs(thorns) do
					local g = c01((t - th.at - th.s * GROW) / 0.15)
					th.set(0.75 * L.outBack(g), g > 0 and 0 or 1)
				end
				for _, rs in ipairs(roses) do
					local g = L.outBack(c01((t - rs.at) / 0.25))
					for _, pt in ipairs(rs.pet) do
						local len = 0.9 * g
						pt.p.CFrame = rs.F * CFrame.Angles(0, pt.a, 0) * CFrame.Angles(math.rad(40), 0, 0) * CFrame.new(0, 0, -len / 2)
						pt.m.Scale = Vector3.new(0.95 * g, 1, len)
						pt.p.Transparency = g > 0.01 and 0.04 or 1
					end
				end
				if not bloomed and t >= BLOOM then bloomed = true L.punch(0.6, 0.2, C1, 0.15) end
				local beat = 0
				if BEATS[bi] and t >= BEATS[bi] then L.punch(0.9, 0.18, C1, 0.2) bi += 1 end
				for _, b in ipairs(BEATS) do if t >= b then beat = math.max(beat, math.exp(-(t - b) * 8)) end end
				glow.Brightness = 0.5 * c01(t / GROW) + 5 * beat
				local sg = L.outQuad(c01((t - 0.15) / GROW)) * (1 + 0.05 * beat)
				local sh = H * 0.92 * sg
				shell.Size = Vector3.new(3.4 * math.min(1, sg * 1.6) * (1 + 0.05 * beat), math.max(0.05, sh), 3.4 * math.min(1, sg * 1.6) * (1 + 0.05 * beat))
				shell.CFrame = CFrame.new(o + Vector3.new(0, sh / 2 + 0.1, 0))
				shell.Transparency = sg > 0.02 and 0.12 or 1
				shell.Color = BLACK:Lerp(C1, 0.7 * beat)
				if beat > 0.3 then shell.Material = Enum.Material.Neon else shell.Material = Enum.Material.SmoothPlastic end
			end
			if not burst and t >= BURST then
				burst, bAt = true, t
				local c = o + Vector3.new(0, 3.3, 0)
				local function fling(p)
					local d = p.Position - c
					d = Vector3.new(d.X, 0, d.Z).Magnitude > 0.05 and Vector3.new(d.X, 0, d.Z).Unit or Vector3.xAxis
					fly[p] = { cf0 = p.CFrame, v = d * rnd(14, 24) + Vector3.new(0, rnd(3, 10), 0), sp = Vector3.new(rnd(-9, 9), rnd(-9, 9), rnd(-9, 9)), hid = p.Transparency >= 1 }
				end
				shell.Transparency = 1
				for _, sg in ipairs(segs) do fling(sg.p) end
				for _, th in ipairs(thorns) do fling(th.p) end
				for _, rs in ipairs(roses) do for _, pt in ipairs(rs.pet) do pt.p.Transparency = 1 end end
				storm:Emit(140)
				appear(C1, 0.25, hideTok)
				L.punch(1.8, 0.4, C1, 0.4)
				burstP.CFrame = CFrame.new(c) dropBurst:Emit(30)
				L.groundWave(o, "ring_c.png", C2, 3, 22, 0.55)
				L.groundWave(o, "glyph.png", C1, 4, 13, 1, 1.8)
				glow.Brightness = 9
			end
			if burst then
				local q = t - bAt
				for p, d in pairs(fly) do
					local pos = d.cf0.Position + d.v * q + Vector3.new(0, -40 * q * q, 0)
					if pos.Y < o.Y + 0.15 then pos = Vector3.new(pos.X, o.Y + 0.15, pos.Z) end
					p.CFrame = CFrame.new(pos) * d.cf0.Rotation * CFrame.Angles(d.sp.X * q, d.sp.Y * q, d.sp.Z * q)
					p.Transparency = d.hid and 1 or c01((q - 0.6) / 0.5)
				end
				glow.Brightness = math.max(0, glow.Brightness - 0.4)
				fadeHl()
			end
		end, objs)
		task.delay(DUR + 0.1, function() setHidden(false, hideTok) end)
	end





	shorts[5] = function()
		local o = ch.feet
		local DUR, LIGHT0, SPOKE, HEX, SEAL, SPIRAL, BURST = 3.9, 0.3, 0.95, 1.3, 1.95, 2.35, 2.85
		local hideTok = setHidden(true)
		local RAD = 6.5
		local bk, bkM = L.mesh("disc.mesh", "darkdisc.png", BLACK, 1, Vector3.new(RAD * 2.5, 1, RAD * 2.5))
		local sg, sgM = L.mesh("disc.mesh", "glyph.png", GORE, 1, Vector3.new(RAD * 1.9, 1, RAD * 1.9))
		local rg, rgM = L.mesh("disc.mesh", "ring_c.png", GORE, 1, Vector3.new(RAD * 2.2, 1, RAD * 2.2))
		bk.CFrame = CFrame.new(o + Vector3.new(0, 0.04, 0))
		local objs = { bk, sg, rg }
		local cand, pts = {}, {}
		for i = 1, 6 do
			local a = i / 6 * math.pi * 2
			pts[i] = o + Vector3.new(math.cos(a) * RAD, 0, math.sin(a) * RAD)
			local c = L.part({ Shape = Enum.PartType.Cylinder, Material = Enum.Material.SmoothPlastic, Color = Color3.fromRGB(26, 10, 12), Transparency = 1,
				Size = Vector3.new(2, 0.6, 0.6), CFrame = CFrame.new(pts[i] + Vector3.new(0, 1, 0)) * CFrame.Angles(0, 0, math.pi / 2) })
			local tip = L.part({ Size = Vector3.new(0.2, 0.2, 0.2), CFrame = CFrame.new(pts[i] + Vector3.new(0, 2.15, 0)) })
			local fl = L.pe(tip, { Texture = L.T("flame.png"), Color = CS(C2, C1), LightEmission = 0.6, Rate = 0, Speed = NR(0.5, 1), SpreadAngle = Vector2.new(8, 8),
				Lifetime = NR(0.3, 0.45), Size = NS({ K(0, 0.8), K(1, 0.15) }), Transparency = NS({ K(0, 0.1), K(1, 1) }) })
			local smoke = L.pe(tip, { Texture = L.T("smoke.png"), Color = CS(Color3.fromRGB(70, 60, 62)), LightEmission = 0, Rate = 0, Speed = NR(1.2, 2), SpreadAngle = Vector2.new(6, 6),
				Lifetime = NR(1, 1.5), Size = NS({ K(0, 0.25), K(1, 1.2) }), Transparency = NS({ K(0, 0.5), K(1, 1) }), RotSpeed = NR(-60, 60), Acceleration = Vector3.new(0, 1, 0) })
			local lt = L.new("PointLight", { Color = C1, Range = 6, Brightness = 0, Shadows = false }, tip)
			cand[i] = { c = c, fl = fl, smoke = smoke, lt = lt, at = LIGHT0 + (i - 1) * 0.1, lit = false, tipP = pts[i] + Vector3.new(0, 2.15, 0) }
			objs[#objs + 1] = c objs[#objs + 1] = tip
		end

		local spark = L.part({ Shape = Enum.PartType.Ball, Material = Enum.Material.Neon, Color = C2:Lerp(W, 0.4), Transparency = 1, Size = Vector3.one * 0.35 })
		local sa0, sa1 = L.new("Attachment", { Position = Vector3.new(0, 0.15, 0) }, spark), L.new("Attachment", { Position = Vector3.new(0, -0.15, 0) }, spark)
		local sTrail = L.new("Trail", { Attachment0 = sa0, Attachment1 = sa1, Texture = L.T("beamb.png"), LightEmission = 1, Lifetime = 0.2, FaceCamera = true,
			Color = CS(C2, C1), Transparency = NS({ K(0, 0), K(1, 1) }), WidthScale = NS({ K(0, 1), K(1, 0.2) }) }, spark)
		objs[#objs + 1] = spark

		local runs = {}
		local function groove(A, B, at, dur)
			local p = L.part({ Material = Enum.Material.Neon, Color = C1, Transparency = 1, Size = Vector3.new(0.24, 0.05, 0.1) })
			local h = L.part({ Shape = Enum.PartType.Ball, Material = Enum.Material.Neon, Color = C2:Lerp(W, 0.3), Transparency = 1, Size = Vector3.one * 0.42 })
			runs[#runs + 1] = { p = p, h = h, A = A + Vector3.new(0, 0.1, 0), B = B + Vector3.new(0, 0.1, 0), at = at, dur = dur }
			objs[#objs + 1] = p objs[#objs + 1] = h
		end
		for i = 1, 6 do groove(pts[i], o, SPOKE + rnd(0, 0.06), 0.35) end
		for i = 1, 6 do groove(pts[i], pts[(i + 1) % 6 + 1], HEX + (i - 1) * 0.1, 0.16) end

		local streams = {}
		for i = 1, 2 do
			local p = L.part({ Shape = Enum.PartType.Ball, Material = Enum.Material.Neon, Color = C1, Transparency = 1, Size = Vector3.one * 0.6 })
			local a0, a1 = L.new("Attachment", { Position = Vector3.new(0.45, 0, 0) }, p), L.new("Attachment", { Position = Vector3.new(-0.45, 0, 0) }, p)
			local tr = L.new("Trail", { Attachment0 = a0, Attachment1 = a1, Texture = L.T("beamb.png"), LightEmission = 0.4, Brightness = 2, Lifetime = 0.55, FaceCamera = true,
				Color = CS({ CK(0, C2), CK(0.5, C1), CK(1, GORE) }), Transparency = NS({ K(0, 0), K(0.8, 0.3), K(1, 1) }), WidthScale = NS({ K(0, 1.2), K(1, 0.5) }), Enabled = false }, p)
			local dr = dropE(p, { Rate = 0, Speed = NR(0, 2), SpreadAngle = Vector2.new(180, 180), Lifetime = NR(0.4, 0.7) })
			streams[i] = { p = p, tr = tr, dr = dr, a0 = i * math.pi }
			objs[#objs + 1] = p
		end
		local rainP = L.part({ Size = Vector3.new(16, 1, 16), CFrame = CFrame.new(o + Vector3.new(0, 15, 0)) })
		local rain = dropE(rainP, { Shape = Enum.ParticleEmitterShape.Box, EmissionDirection = Enum.NormalId.Bottom, Speed = NR(4, 10), Lifetime = NR(1.1, 1.4),
			Acceleration = Vector3.new(0, -30, 0), Size = NS({ K(0, 0.3), K(1, 0.2) }) })
		local petals = L.pe(rainP, { Texture = L.T("petal.png"), Shape = Enum.ParticleEmitterShape.Box, EmissionDirection = Enum.NormalId.Bottom, Color = CS(C1, GORE), LightEmission = 0.1,
			Rate = 0, Speed = NR(2, 5), SpreadAngle = Vector2.new(60, 60), Lifetime = NR(2, 2.8), Acceleration = Vector3.new(0, -3, 0), Drag = 0.6,
			Size = NS({ K(0, 0.45), K(1, 0.35) }), Rotation = NR(0, 360), RotSpeed = NR(-200, 200), Transparency = NS({ K(0, 0), K(0.8, 0), K(1, 1) }) })
		objs[#objs + 1] = rainP

		local st, stM = L.mesh("disc.mesh", "glyph.png", C1, 2.4)
		local stC, stCM = L.mesh("disc.mesh", "cracks_b.png", C1, 1.8)
		st.Transparency, stC.Transparency = 1, 1
		objs[#objs + 1] = st objs[#objs + 1] = stC
		local lastLit, burst, stamped, out = 0, false, false, false
		L.fx(DUR, function(k, t)
			local fade = c01((t - (DUR - 0.6)) / 0.5)

			local up = L.outBack(c01(t / 0.3))
			for i, c in ipairs(cand) do
