		gSig.CFrame = ch.flat * CFrame.new(0, 0.05, 0) * CFrame.Angles(0, -ch.clock * 0.2, 0)
		L.tint(gSigM, C1:Lerp(C2, 0.3 * ch.breathe), 1.6 + 0.6 * ch.breathe)
		gSig.Transparency = 1 - iw * 0.7
		gRing.CFrame = ch.flat * CFrame.new(0, 0.08, 0) * CFrame.Angles(0, ch.clock * 0.5, 0)
		gRing.Transparency = 1 - iw * 0.5
		gPool.CFrame = ch.flat * CFrame.new(0, 0.03, 0)
		gPool.Transparency = 1 - iw * 0.6
		for _, b in ipairs(bats) do
			local a = ch.clock * b.sp + b.ph
			b.p.CFrame = CFrame.new(ch.pos + Vector3.new(math.cos(a) * b.r, b.h - 2 + 0.5 * math.sin(a * 3), math.sin(a) * b.r))
			b.e.Rate = iw > 0.3 and 4 or 0
		end
		dripP.CFrame = ch.hrp.CFrame * CFrame.new(0, -0.6, -0.2)
		dripE.Rate = 1.2 * iw

		if iw > 0.8 then
			pulseT += dt
			if pulseT >= 3.5 then
