		local beat = 0.85 + 0.15 * math.max(0, math.sin(ch.clock * 5)) ^ 8
		light.Brightness = math.max(on and (1 + sprint) * beat or iw * 1.5 * beat, light.Brightness - dt * 8)
		hl.OutlineTransparency = 0.7 - 0.4 * iw * beat
		if hl.FillTransparency < 1 then hl.FillTransparency = math.min(1, hl.FillTransparency + dt * 0.8) end

		local hp = ch.head.Position + Vector3.new(0, 1.1 + 0.05 * math.sin(ch.clock * 1.6), 0)
		local a = 0.6 + 0.4 * iw
		local spin = ch.clock * 0.35
		local tilt = CFrame.Angles(math.rad(6) * math.sin(ch.clock * 0.7), 0, math.rad(6) * math.cos(ch.clock * 0.7))
		local base = CFrame.new(hp) * tilt
		crown.CFrame = base * CFrame.Angles(0, spin, 0) crown.Transparency = 1 - a * 0.95
		L.tint(crownM, C1:Lerp(C2, 0.35 * (beat - 0.85) / 0.15), 1.8 * beat)
		crownIn.CFrame = base * CFrame.new(0, -0.02, 0) * CFrame.Angles(0, -spin * 0.6, 0) crownIn.Transparency = 1 - a * 0.85
		crownG.CFrame = base * CFrame.new(0, -0.04, 0) crownG.Transparency = 1 - a * 0.4
		local cam = workspace.CurrentCamera.CFrame.Position
		for _, d in ipairs(hang) do
			d.g += dt * d.sp
			if d.g >= 1 then
				d.g = 0 d.sp = rnd(0.35, 0.6)
				fallP.CFrame = CFrame.new(d.pos or hp) fallE:Emit(1)
			end
			local th = d.a + spin
			local rim = (base * CFrame.new(math.cos(th) * 1.05, 0, math.sin(th) * 1.05)).Position
			local sw = L.outQuad(c01(d.g / 0.85))
			local len = 0.12 + 0.3 * sw
			local pos = rim - Vector3.new(0, len * 0.5 + 0.05 * sw, 0)
			d.pos = rim - Vector3.new(0, len, 0)

			local flat = Vector3.new(cam.X - pos.X, 0, cam.Z - pos.Z)
			local look = flat.Magnitude > 0.01 and CFrame.lookAt(pos, pos + flat) or CFrame.new(pos)
			d.p.CFrame = look * CFrame.Angles(math.rad(-90), 0, 0)
			d.m.Scale = Vector3.new(0.08 + 0.08 * sw, 1, len)
			d.p.Transparency = math.max(0.06, 1 - a * (0.4 + 0.6 * sw))
