System.StaffThemes.TAGS.playerone = function(K, head, C1, C2)
	local W = Color3.new(1, 1, 1)
	local NAVY, NAVY2 = Color3.fromRGB(34, 56, 178), Color3.fromRGB(12, 22, 96)
	local CS, CK = ColorSequence.new, ColorSequenceKeypoint.new
	local function c01(x) return math.clamp(x, 0, 1) end
	local AR = Font.fromEnum(Enum.Font.Arcade)
	local Wd, Hd = 7.4, 3.4
	local bb = K.board(head, Wd, Hd, 3.6)
	bb:SetAttribute("RCBadgeTop", 0.25)
	local function P(x, y) return UDim2.fromScale(x / Wd, y / Hd) end
	local function Z(w, h) return UDim2.fromScale(w / Wd, h / Hd) end
	local X0, Y0, BW, BH = 0.5, 0.3, 6.4, 2.0
	local fade = {}
	local function F(o, prop, base) fade[#fade + 1] = { o, prop, base } return o end
	local rim = F(K.frame(bb, { BackgroundColor3 = W, Position = P(X0, Y0), Size = Z(BW, BH), ZIndex = 1 }), "BackgroundTransparency", 0)
	K.new("UICorner", { CornerRadius = UDim.new(0.08, 0) }, rim)
	local box = F(K.frame(bb, { BackgroundColor3 = W, Position = P(X0 + 0.1, Y0 + 0.1), Size = Z(BW - 0.2, BH - 0.2), ZIndex = 2 }), "BackgroundTransparency", 0.05)
	K.new("UICorner", { CornerRadius = UDim.new(0.07, 0) }, box)
	K.new("UIGradient", { Rotation = 90, Color = CS(NAVY, NAVY2) }, box)
	local lv = F(K.text(bb, { Position = P(X0 + 0.3, Y0 + 0.22), Size = Z(1.6, 0.3), Text = "LV 1", FontFace = AR, TextColor3 = C1, TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 4 }), "TextTransparency", 0)
	F(K.text(bb, { Position = P(X0 + BW - 2.55, Y0 + 0.22), Size = Z(0.5, 0.3), Text = "HP", FontFace = AR, TextColor3 = W, ZIndex = 4 }), "TextTransparency", 0)
	F(K.frame(bb, { BackgroundColor3 = NAVY2, Position = P(X0 + BW - 2.0, Y0 + 0.26), Size = Z(1.65, 0.22), ZIndex = 3 }), "BackgroundTransparency", 0)
	local hp = F(K.frame(bb, { BackgroundColor3 = C2, Position = P(X0 + BW - 1.97, Y0 + 0.29), Size = Z(1.59, 0.16), ZIndex = 4 }), "BackgroundTransparency", 0)
	local line = F(K.text(bb, { AnchorPoint = Vector2.new(0.5, 0.5), Position = P(Wd / 2, Y0 + 1.12), Size = Z(BW - 0.9, 0.6), Text = "PLAYER ONE", FontFace = AR, TextColor3 = W, ZIndex = 4 }), "TextTransparency", 0)

	local arrow = F(K.frame(bb, { BackgroundColor3 = C1, AnchorPoint = Vector2.new(0.5, 0.5), Position = P(X0 + BW - 0.45, Y0 + BH - 0.32), Size = Z(0.2, 0.2), Rotation = 45, ZIndex = 4 }), "BackgroundTransparency", 0)
	local UW = math.clamp(#K.NAME * 0.3 + 0.9, 2.2, 6.6)
	local pill = F(K.frame(bb, { BackgroundColor3 = NAVY2, AnchorPoint = Vector2.new(0.5, 0.5), Position = P(Wd / 2, 2.85), Size = Z(UW, 0.5), ZIndex = 3 }), "BackgroundTransparency", 0.2)
	K.new("UICorner", { CornerRadius = UDim.new(0.5, 0) }, pill)
	F(K.text(bb, { AnchorPoint = Vector2.new(0.5, 0.5), Position = P(Wd / 2, 2.85), Size = Z(UW - 0.4, 0.3), Text = K.NAME, FontFace = AR, TextColor3 = C1:Lerp(W, 0.5), ZIndex = 4 }), "TextTransparency", 0)

	local ch = System.StaffThemes._tagCh or {}
	local TS = { beat = ch.sBeat or 0, emo = ch.sEmoteN or 0, combo = 0, comboT = 0, cont = 0, wasDead = false, cur = nil, typeT = 0, shown = nil, la = -1, lv = nil, hpw = nil }
	return function(t, dt, it)
		local dead = ch.dead == true
		if TS.wasDead and not dead then TS.cont = 2.6 end
		TS.wasDead = dead
		TS.cont = math.max(0, TS.cont - dt)
		if (ch.sEmoteN or 0) ~= TS.emo then TS.emo, TS.combo = ch.sEmoteN or 0, 0 end
		if (ch.sBeat or 0) ~= TS.beat then
			TS.beat = ch.sBeat or 0
			if ch.mOn then TS.combo += 1 TS.comboT = 1.6 end
		end
		TS.comboT = math.max(0, TS.comboT - dt)
		local want = dead and "GAME OVER" or TS.cont > 0 and "CONTINUE? > YES" or TS.comboT > 0 and ("COMBO x" .. TS.combo .. "!") or it < 2.6 and "PLAYER JOINED THE PARTY" or "PLAYER ONE"

		if want ~= TS.cur then
			local sameKind = TS.cur and TS.cur:sub(1, 5) == "COMBO" and want:sub(1, 5) == "COMBO"
			TS.cur = want
			if not sameKind then TS.typeT = 0 end
		end
		TS.typeT += dt
		local txt = want:sub(1, math.floor(TS.typeT * 22))
		if txt ~= TS.shown then TS.shown = txt line.Text = txt end
		line.TextColor3 = dead and C2 or (TS.comboT > 0 and C1 or W)
		local lvTxt = "LV " .. math.min(99, 1 + (ch.sEmoteN or 0))
		if lvTxt ~= TS.lv then TS.lv = lvTxt lv.Text = lvTxt end
		local hw = dead and 0.02 or 1.59
		if hw ~= TS.hpw then TS.hpw = hw hp.Size = Z(hw, 0.16) end
		arrow.Position = P(X0 + BW - 0.45, Y0 + BH - 0.32 + ((t % 0.6) < 0.3 and 0 or 0.07))

		local a = math.floor(c01(it / 0.3) * 4) / 4
		if a ~= TS.la then
			TS.la = a
			for _, f in ipairs(fade) do f[1][f[2]] = 1 - (1 - f[3]) * a end
		end
	end
end

