		end }



	local PX = { list = {}, i = 0 }
	for i = 1, 30 do PX.list[i] = { p = L.part({ Material = NEON, Color = C1, Transparency = 1, Size = Vector3.one * 0.2 }), t = 99, life = 1 } end
	function PX.emit(pos, vel, size, col, life, grav, gy)
		PX.i = PX.i % #PX.list + 1
		local X = PX.list[PX.i]
		X.pos, X.vel, X.sz, X.life, X.g, X.gy, X.t, X.ls, X.lt = pos, vel, size, life, grav or 0, gy, 0, nil, nil
		if X.p.Color ~= col then X.p.Color = col end
	end
	function PX.step(dt, off)
		for _, X in ipairs(PX.list) do
			if X.t < X.life then
				X.t += dt
				if X.t >= X.life or off then
					X.t = 99
					X.p.Transparency = 1
				else
					X.vel -= Vector3.new(0, X.g * dt, 0)
					X.pos += X.vel * dt
					if X.gy and X.pos.Y < X.gy + X.sz * 0.5 then X.pos = Vector3.new(X.pos.X, X.gy + X.sz * 0.5, X.pos.Z) X.vel *= Vector3.new(0.5, 0, 0.5) end
					if X.sz ~= X.ls then X.ls = X.sz X.p.Size = Vector3.one * X.sz end
					local tr = 0.05 + 0.9 * math.floor(X.t / X.life * 3) / 3
					if tr ~= X.lt then X.lt = tr X.p.Transparency = tr end
					X.p.CFrame = CFrame.new(X.pos)
				end
			end
		end
	end

	local SPK = { list = {}, i = 0, t = 0.3 }
	for i = 1, 10 do SPK.list[i] = { p = L.part({ Material = NEON, Color = C1, Transparency = 1, Size = Vector3.one * 0.18 }), t = 99, ci = 1, lz = nil } end

	local TL = { list = {}, i = 0, d = 0, lp = nil, n = 0 }
	for i = 1, 14 do TL.list[i] = { p = L.part({ Material = NEON, Color = C1, Transparency = 1, Size = Vector3.new(0.9, 0.05, 0.9) }), t = 99 } end

	local GEM = { list = {}, i = 0 }
	for i = 1, 2 do
		local lp, lt = label("+1", C1, 1.6, 0.8)
		GEM.list[i] = { p = L.part({ Material = NEON, Color = C1:Lerp(W, 0.25), Transparency = 1, Size = Vector3.one * 0.45 }), lp = lp, lt = lt, t = 99 }
	end


	local PET = { B = 1, hop = nil, pos = nil, yaw = 0, mood = "happy", inT = rnd(2.5, 4), glT = rnd(4, 7), glance = 0, sq = 0, zT = 1, beat = 0, emo = 0, vis = false, ls = nil }
	PET.body = L.part({ Material = PLASTIC, Color = C1, Transparency = 1 })
	PET.bits = {
		{ p = L.part({ Material = PLASTIC, Color = INK, Transparency = 1 }), o = Vector3.new(-0.22, 0.12, -0.5), s = Vector3.new(0.16, 0.22, 0.04), eye = true },
		{ p = L.part({ Material = PLASTIC, Color = INK, Transparency = 1 }), o = Vector3.new(0.22, 0.12, -0.5), s = Vector3.new(0.16, 0.22, 0.04), eye = true },
		{ p = L.part({ Material = PLASTIC, Color = C2, Transparency = 1 }), o = Vector3.new(-0.36, -0.12, -0.5), s = Vector3.new(0.14, 0.08, 0.04) },
		{ p = L.part({ Material = PLASTIC, Color = C2, Transparency = 1 }), o = Vector3.new(0.36, -0.12, -0.5), s = Vector3.new(0.14, 0.08, 0.04) },
		{ p = L.part({ Material = PLASTIC, Color = C1, Transparency = 1 }), o = Vector3.new(-0.32, 0.6, 0.05), s = Vector3.new(0.22, 0.22, 0.22) },
		{ p = L.part({ Material = PLASTIC, Color = C1, Transparency = 1 }), o = Vector3.new(0.32, 0.6, 0.05), s = Vector3.new(0.22, 0.22, 0.22) },
	}

	function PET.goal(s)
		local f = ch.flat or CFrame.new(ch.feet or Vector3.zero)
		return f:PointToWorldSpace(Vector3.new(2.4 * s, 0, 1.4 * s))
	end
	function PET.place(s, vis)
		if vis ~= PET.vis then
			PET.vis = vis
			local tr = vis and 0 or 1
			PET.body.Transparency = tr
			for _, b in ipairs(PET.bits) do b.p.Transparency = tr end
		end
		if not vis or not PET.pos then return end
		local B = PET.B * s * 0.9
		local sy = 1 - 0.25 * PET.sq + (PET.mood == "nap" and -0.25 or 0)
		local sx = 1 + 0.15 * PET.sq
		local q = math.floor(sy * 20 + 0.5) / 20 .. "," .. math.floor(sx * 20 + 0.5) / 20 .. "," .. B
		local hy = 0
		if PET.hop then local u = c01(PET.hop.t / PET.hop.dur) hy = PET.hop.h * 4 * u * (1 - u) end
		local cf = CFrame.new(PET.pos + UP * (B * sy * 0.5 + hy)) * CFrame.Angles(0, PET.yaw, 0)
		if PET.spin then cf *= CFrame.Angles(0, PET.spin, 0) end
		if q ~= PET.ls then
			PET.ls = q
			PET.body.Size = Vector3.new(B * sx, B * sy, B * sx)
			for _, b in ipairs(PET.bits) do
				local s2 = b.s * B
				if b.eye and PET.mood == "nap" then s2 = Vector3.new(s2.X, 0.04 * B, s2.Z) end
				b.p.Size = s2
			end
		end
		PET.body.CFrame = cf
		for _, b in ipairs(PET.bits) do b.p.CFrame = cf * CFrame.new(b.o.X * B * sx, b.o.Y * B * sy, b.o.Z * B * sx) end
	end

	function PET.jump(to, dur, h)
		PET.hop = { from = PET.pos, to = to, t = 0, dur = dur, h = h }
		local d = (to - PET.pos) * Vector3.new(1, 0, 1)
		if d.Magnitude > 0.05 then PET.yaw = math.atan2(-d.X, -d.Z) end
	end
	function PET.step(dt, s, vis, still)
		if not vis then PET.place(s, false) return end
		local goal = PET.goal(s)
		if not PET.pos or (PET.pos - goal).Magnitude > 30 * s then PET.pos, PET.hop = L.ground(goal, 4, 10), nil end
		PET.sq = math.max(0, PET.sq - dt * 6)
		if PET.spin then PET.spin += dt * 14 end

		PET.mood = ch.mOn and "excited" or (still and (ch.stillT or 0) > 12) and "nap" or "happy"
		if PET.hop then
			local H = PET.hop
			H.t += dt
			local u = c01(H.t / H.dur)
			PET.pos = H.from:Lerp(H.to, u)
			if u >= 1 then PET.hop, PET.sq, PET.spin = nil, 1, nil end
		else
			local d = (goal - PET.pos) * Vector3.new(1, 0, 1)
			local far = d.Magnitude

			local drop
			PET.gT = (PET.gT or 0) - dt
			if far <= 1.1 * s and PET.gT <= 0 then
				PET.gT = 0.2
				local pr = PET.pos + UP * s
				local g = L.ground(pr, 0.5 * s, 60)
				if g ~= pr and math.abs(g.Y - PET.pos.Y) > 0.4 * s then drop = g end
			end
			if drop then
				PET.jump(drop, 0.3, 0.4 * s)
			elseif far > 1.1 * s then

				local cap = ((ch.sprint or 0) > 0.3 or far > 8 * s) and 4.2 or 2.4
				local to = L.ground(PET.pos + d.Unit * math.min(far, cap * s) + UP * 2 * s, 4, 10)
				PET.jump(to, far > 8 * s and 0.24 or 0.32, (0.6 + 0.08 * math.min(far, cap)) * s)
			elseif PET.mood == "excited" then
				PET.inT -= dt
				if PET.inT <= 0 then PET.inT = 0.45 PET.jump(PET.pos, 0.3, 0.9 * s) PET.spin = 0 end
			elseif PET.mood == "happy" then
				PET.inT -= dt
				if PET.inT <= 0 then PET.inT = rnd(2.5, 4) PET.jump(PET.pos, 0.28, 0.45 * s) end

				PET.glT -= dt
				if PET.glT <= 0 then PET.glT, PET.glance = rnd(4, 7), 1.2 end
				PET.glance = math.max(0, PET.glance - dt)
				local cam = workspace.CurrentCamera
				local to = (PET.glance > 0 and cam) and (cam.CFrame.Position - PET.pos) or (ch.flat and ch.flat.LookVector or Vector3.zAxis)
				if (to * Vector3.new(1, 0, 1)).Magnitude > 0.05 then PET.yaw = math.atan2(-to.X, -to.Z) end
			else

				PET.zT -= dt
				if PET.zT <= 0 then
					PET.zT = 1.1
					PET.emit(PET.pos + UP * PET.B * s + Vector3.new(rnd(-0.2, 0.2), 0, rnd(-0.2, 0.2)) * s)
				end
			end
		end
		PET.place(s, true)
	end
	function PET.emit(p) PX.emit(p, UP * 0.9 * sc() + Vector3.new(0.3, 0, 0) * sc(), 0.16 * sc(), W, 1.4, 0) end


	local rig = {}
	local function rebind() end
	System.StaffThemes._tagCh = ch
	local tag = System.StaffThemes.headTag(L, "playerone", C1, C2, { c1 = C1, c2 = C2, role = "PLAYER ONE" })
	System.StaffThemes._tagCh = nil

	local held = nil
	local deathGone = nil
	local dying = false
	local function hide(on)
		if on then
			held = held or {}
			for d in pairs(L.bodyParts()) do if not held[d] then held[d] = true d.LocalTransparencyModifier = 1 end end
		elseif held then
			for d in pairs(held) do if d.Parent then pcall(function() d.LocalTransparencyModifier = 0 end) end end
			held = nil
		end
	end
	local function bodyGhost(col, life, off)
		if not ch.char then return {} end
		local g = L.ghost(col, NEON, life, true)
		local list = {}
		for _, p in ipairs(g:GetChildren()) do
			if p:IsA("BasePart") then
				p.LocalTransparencyModifier = 0
				if off then p.CFrame = p.CFrame + off end
				list[#list + 1] = { p = p, cf = p.CFrame }
			end
		end
		return list
	end
	local function bodyList()
		local t = {}
		for d in pairs(L.bodyParts()) do if d:IsA("BasePart") then t[#t + 1] = d end end
		return t
	end

	local function voxels(parts, v, cap)
		local base = ch.flat or CFrame.new(ch.feet or Vector3.zero)
		local seen, list = {}, {}
		for _, p in ipairs(parts) do
			local sz = p.Size
			local nx, ny, nz = math.max(1, math.ceil(sz.X / v)), math.max(1, math.ceil(sz.Y / v)), math.max(1, math.ceil(sz.Z / v))
			for i = 1, nx do
				for j = 1, ny do
					for k = 1, nz do
						local w = p.CFrame:PointToWorldSpace(Vector3.new(((i - 0.5) / nx - 0.5) * sz.X, ((j - 0.5) / ny - 0.5) * sz.Y, ((k - 0.5) / nz - 0.5) * sz.Z))
						local l = base:PointToObjectSpace(w)
						local gx, gy, gz = math.floor(l.X / v), math.floor(l.Y / v), math.floor(l.Z / v)
						local key = gx .. "," .. gy .. "," .. gz
						if not seen[key] then
							seen[key] = true
							list[#list + 1] = { c = base:PointToWorldSpace(Vector3.new((gx + 0.5) * v, (gy + 0.5) * v, (gz + 0.5) * v)), col = p.Color }
						end
					end
				end
			end
		end
		if #list > cap then
			local keep, step = {}, #list / cap
			for i = 1, cap do keep[i] = list[math.floor((i - 1) * step) + 1] end
			list = keep
		end
		return list, base
	end

	local function sprite(rows, c, v, col)
		local r = camRight()
		local cubes = {}
		local h, w = #rows, #rows[1]
		for y, row in ipairs(rows) do
			for x = 1, w do
				if row:sub(x, x) == "X" then
					local off = r * (x - (w + 1) / 2) * v + UP * ((h + 1) / 2 - y) * v
					cubes[#cubes + 1] = { p = L.part({ Material = NEON, Color = col, Transparency = 1, Size = Vector3.one * v * 0.94 }), o = off, x = x }
				end
			end
		end
		return cubes, r
	end



	local HEART = { ".XX.XX.", "XXXXXXX", "XXXXXXX", ".XXXXX.", "..XXX..", "...X..." }
	local function shortLife()
		local o, s = L.ground(ch.feet, 3, 8), sc()
		hide(true)
		PET.hidden = true
		local v = 0.4 * s
		local cubes, r = sprite(HEART, Vector3.zero, v, C2)
		local mid = o + UP * 1.6 * s
		local lp, lt = label("+1 LIFE", C1, 4 * s, 1 * s)
		lp.CFrame = CFrame.new(mid + UP * 2 * s)
		local objs = { lp }
		for i, cb in ipairs(cubes) do objs[i + 1] = cb.p end
		L.timeline(2.8, function(t, once)
			if held and once("late", 0.2) and t < 1.2 then hide(true) end

			local y = t < 0.45 and 10 * s * (1 - (t / 0.45) ^ 2) or (t < 0.7 and 0.4 * s * math.sin((t - 0.45) / 0.25 * math.pi) or 0)
			local ck = c01((t - 1.0) / 0.5)
			for _, cb in ipairs(cubes) do
				local side = cb.x <= 4 and -1 or 1
				local p = mid + cb.o + UP * y + r * side * 1.2 * s * ck - UP * 3 * s * ck * ck
				cb.p.CFrame = CFrame.new(p) * CFrame.Angles(0, 0, side * ck * 1.2)
				cb.p.Transparency = t < 1.0 and 0.05 or 0.05 + 0.95 * math.floor(ck * 3) / 3
			end
			if once("land", 0.45) then for _ = 1, 6 do PX.emit(o + Vector3.new(rnd(-1, 1), 0.2, rnd(-1, 1)) * s, Vector3.new(rnd(-3, 3), rnd(1, 3), rnd(-3, 3)) * s, 0.22 * s, W, 0.5, 20, o.Y) end end

			local lk = c01((t - 1.0) / 0.15)
			lp.CFrame = CFrame.new(mid + UP * (1.5 + 0.6 * c01((t - 1) / 1.5)) * s)
			lt.TextTransparency = 1 - lk * (1 - c01((t - 2.3) / 0.4))

			if t >= 1.1 and t < 2.2 then
				local on = math.floor((t - 1.1) / 0.08) % 2 == 0
				if on and held then hide(false) elseif not on and not held then hide(true) end
			end
			if once("show", 2.2) then hide(false) PET.hidden = false end
		end, objs, function() hide(false) PET.hidden = false end)
	end

	local DIG = {
		{ ".X.", "XX.", ".X.", ".X.", "XXX" },
		{ "XXX", "..X", "XXX", "X..", "XXX" },
		{ "XXX", "..X", "XXX", "..X", "XXX" },
	}
	local function shortContinue()
		local o, s = L.ground(ch.feet, 3, 8), sc()
		hide(true)
		PET.hidden = true
		local v = 0.32 * s
		local top = o + UP * 3.4 * s
		local digits = {}
		local objs = {}
		for n = 3, 1, -1 do
			local cubes = sprite(DIG[n], Vector3.zero, v, n == 1 and C1 or W)
			digits[#digits + 1] = cubes
			for _, cb in ipairs(cubes) do objs[#objs + 1] = cb.p end
		end
		local slot = L.part({ Material = NEON, Color = INK, Transparency = 1, Size = Vector3.new(1.6 * s, 0.08, 0.6 * s), CFrame = CFrame.fromMatrix(o + UP * 0.05, camRight(), UP) })
		objs[#objs + 1] = slot
		local lp, lt = label("CONTINUE!", C1, 5 * s, 1.1 * s)
		lp.CFrame = CFrame.new(o + UP * 3.4 * s)
		objs[#objs + 1] = lp
		local g = nil
		L.timeline(2.6, function(t, once)
			if held and once("late", 0.2) and t < 1.5 then hide(true) end
			slot.Transparency = 1 - 0.85 * c01(t / 0.15) * (1 - c01((t - 2.0) / 0.3))

			for i, cubes in ipairs(digits) do
				local t0 = (i - 1) * 0.42
				local u = t - t0
				local drop = c01((u - 0.3) / 0.12)
				for _, cb in ipairs(cubes) do
					cb.p.CFrame = CFrame.new(top + cb.o - UP * 3.2 * s * drop * drop)
					cb.p.Transparency = (u < 0 or u > 0.42) and 1 or 0.05
				end
			end
			for i = 1, 3 do if once("in" .. i, (i - 1) * 0.42 + 0.42) then for _ = 1, 3 do PX.emit(o + UP * 0.2, Vector3.new(rnd(-2, 2), rnd(2, 4), rnd(-2, 2)) * s, 0.16 * s, C1, 0.4, 20, o.Y) end end end
			local ck = c01((t - 1.3) / 0.1)
			lt.TextTransparency = (t > 1.3 and t < 2.2) and (((t * 8) % 1 < 0.7) and 0 or 0.6) or 1
			lt.TextColor3 = ck > 0 and C1 or W

			if once("ghost", 1.35) then g = bodyGhost(C1:Lerp(W, 0.5), 0.5, UP * 4 * s) end
			if g and t < 1.6 then
				local d = c01((t - 1.35) / 0.2)
				for _, gp in ipairs(g) do gp.p.CFrame = gp.cf - UP * 4 * s * d * d gp.p.Transparency = 0.3 end
			end
			if once("show", 1.55) then
				hide(false)
				PET.hidden = false
				if g then for _, gp in ipairs(g) do gp.p.Transparency = 1 end end
				for side = -1, 1, 2 do for _ = 1, 4 do PX.emit(o + camRight() * side * 0.6 * s + UP * 0.2, (camRight() * side * rnd(3, 6) + UP * rnd(1, 3)) * s, 0.28 * s, W, 0.5, 15, o.Y) end end
			end
		end, objs, function() hide(false) PET.hidden = false end)
	end
	local shorts = { shortLife, shortContinue }


	local function arriveFull()
		local o, s = L.ground(ch.feet, 3, 8), sc()
		local parts = bodyList()
		hide(true)
		PET.hidden = true
		local DUR = 6
		local S = L.screen(DUR)
		S.style, S.c1, S.c2 = "playerone", C1, C2
		S.boxFn = function(t) return c01((t - 0.1) / 0.4) * (1 - c01((t - 5.0) / 0.6)) end
		S.dimFn = function(t) return 0.25 * c01(t / 0.5) * (1 - c01((t - 4.4) / 1.0)) end
		S.tintFn = function(t) return Color3.fromRGB(255, 225, 150), 0.35 * c01(t / 0.5) * (1 - c01((t - 4.4) / 1.0)) end
		local objs = {}
		local function keep(x) objs[#objs + 1] = x return x end

		local col = {}
		local CV = 0.8 * s
		local cb0 = o + camRight() * -2.2 * s
		for i = 1, 9 do col[i] = keep(L.part({ Material = NEON, Color = (i % 2 == 0) and C2 or C1, Transparency = 1, Size = Vector3.one * CV * 0.95 })) end

		local passes = {}
		for pi, v in ipairs({ 2.0, 1.0, 0.5 }) do
			local list = voxels(parts, v * s, pi == 3 and 130 or 60)
			local cubes = {}
			for _, vx in ipairs(list) do
				local colr = pi == 1 and C1 or (pi == 2 and C1:Lerp(vx.col, 0.5) or vx.col)
				cubes[#cubes + 1] = { p = keep(L.part({ Material = pi == 3 and PLASTIC or NEON, Color = colr, Transparency = 1, Size = Vector3.one * v * s * 0.92,
					CFrame = (ch.flat and ch.flat.Rotation or CFrame.identity) + vx.c })), c = vx.c, d = math.random() * 0.12 }
			end
			passes[pi] = { cubes = cubes, t0 = 1.5 + (pi - 1) * 0.75 }
		end
		L.timeline(DUR, function(t, once)
			if held and once("late", 0.3) then hide(true) end

			for i, p in ipairs(col) do
				local ti = 0.3 + (i - 1) * 0.12
				local u = c01((t - ti) / 0.12)
				local gone = t > 4 + i * 0.03
				p.CFrame = CFrame.new(cb0 + UP * ((i - 0.5) * CV + 2 * s * (1 - u)))
				p.Transparency = (u <= 0 or gone) and 1 or 0.05
			end
			if once("colTop", 1.4) then for _ = 1, 6 do PX.emit(cb0 + UP * 9 * CV, Vector3.new(rnd(-3, 3), rnd(3, 6), rnd(-3, 3)) * s, 0.25 * s, C1, 0.7, 25) end end

			for pi, P in ipairs(passes) do
				local u = t - P.t0
				local last = pi == #passes
				local out = last and 3.9 or (passes[pi + 1].t0)
				for _, cb in ipairs(P.cubes) do
					local on = u >= cb.d and t < out
					cb.p.Transparency = on and 0 or 1
					if on and u - cb.d < 0.1 then
						local k = L.outBack(c01((u - cb.d) / 0.1))
						cb.p.Size = Vector3.one * math.max(0.05, (pi == 1 and 2 or pi == 2 and 1 or 0.5) * s * 0.92 * k)
					end
				end
				if once("pass" .. pi, P.t0) then S:shake(0.4, 0.15) end
			end

			if once("show", 3.9) then
				hide(false)
				S:flash(W, 0.4)
				local last = passes[#passes].cubes
				for i = 1, math.min(14, #last) do
					local cb = last[math.random(1, #last)]
					PX.emit(cb.c, (((cb.c - o) * Vector3.new(1, 0, 1)).Unit * rnd(2, 5) + UP * rnd(2, 6)) * s, 0.3 * s, cb.p.Color, 0.8, 25, o.Y)
				end
			end

			if once("pet", 4.1) then
				PET.hidden = false
				PET.pos, PET.hop = L.ground(cb0, 3, 8), nil
			end
			if once("card", 4.2) then S:title(L.name(), C1, C2) end
		end, objs, function() hide(false) PET.hidden = false end)
	end


	local GRAVE = { ".XX.", "XXXX", "XXXX", "XXXX", "XXXX" }
	local function death(preview)
		if not ch.char then return end
		local s = sc()
		local pos = L.ground(ch.feet or ch.pos, 3, 8)
		local parts = bodyList()
		local g = bodyGhost(W, 0.5)
		local gone = {}
		deathGone = gone
		dying = true
		for d in pairs(L.bodyParts()) do gone[d] = true d.LocalTransparencyModifier = 1 end
		local bits, objs = {}, {}
		L.timeline(2.4, function(t, once)

			for _, gp in ipairs(g) do gp.p.Transparency = t < 0.3 and ((math.floor(t / 0.06) % 2 == 0) and 0.1 or 0.5) or 1 end
			if once("pop", 0.3) then
				local c = pos + UP * 2.5 * s
				for i = 1, 36 do
					local p = parts[math.random(1, math.max(1, #parts))]
					local at = p and p.Parent and p.Position + Vector3.new(rnd(-0.5, 0.5), rnd(-0.5, 0.5), rnd(-0.5, 0.5)) * s or c
					local d = (at - c) * Vector3.new(1, 0, 1)
					d = d.Magnitude > 0.05 and d.Unit or Vector3.xAxis
					local q = L.part({ Material = NEON, Color = (i % 3 == 0) and C1 or (p and p.Color or C2), Transparency = 0.05, Size = Vector3.one * 0.38 * s, CFrame = CFrame.new(at) })
					objs[#objs + 1] = q
					bits[#bits + 1] = { p = q, x = at, v = (d * rnd(2, 6) + UP * rnd(6, 11)) * s }
				end
			end
			if t > 0.3 then
				local dt = L.lastDt or 0.016
				local k = c01((t - 1.4) / 1.0)
				for _, b in ipairs(bits) do
					b.v -= UP * 38 * dt
					b.x += b.v * dt
					if b.x.Y < pos.Y + 0.19 * s then b.x = Vector3.new(b.x.X, pos.Y + 0.19 * s, b.x.Z) b.v = Vector3.new(b.v.X * 0.5, -b.v.Y * 0.35, b.v.Z * 0.5) end
					b.p.CFrame = CFrame.new(b.x)
					b.p.Transparency = 0.05 + 0.95 * math.floor(k * 3) / 3
				end
