		end, objs, function()
			deathGone = nil
			dying = false
			if preview then for d in pairs(gone) do if d.Parent then pcall(function() d.LocalTransparencyModifier = 0 end) end end end
		end)

		local v = 0.45 * s
		local stone, r = sprite(GRAVE, Vector3.zero, v, Color3.fromRGB(150, 150, 165))
		local gc = pos + UP * (#GRAVE * v * 0.5)
		local lobj = {}
		for i, cb in ipairs(stone) do cb.p.Material = PLASTIC lobj[i] = cb.p end
		local cross = {}
		for i, o in ipairs({ Vector3.new(0, 0.5, 0), Vector3.new(0, 0, 0), Vector3.new(0, -0.5, 0), Vector3.new(-0.5, 0.25, 0), Vector3.new(0.5, 0.25, 0) }) do
			cross[i] = { p = L.part({ Material = PLASTIC, Color = Color3.fromRGB(70, 70, 82), Transparency = 1, Size = Vector3.one * v * 0.4 }), o = r * o.X * v + UP * o.Y * v }
			lobj[#lobj + 1] = cross[i].p
		end
