			local look = CFrame.fromMatrix(Vector3.zero, r, UP)
			for _, cb in ipairs(stone) do cb.p.CFrame = look + gc + cb.o - UP * (1 - rise) * #GRAVE * v cb.p.Transparency = tr end
			for _, x in ipairs(cross) do x.p.CFrame = look + gc + UP * 0.2 * v + x.o - (look.LookVector * v * 0.5) - UP * (1 - rise) * #GRAVE * v x.p.Transparency = tr end
		end, lobj)
	end


