	local function step(dt)
		local s, iw, on, swim, sit, dead = sc(), ch.iw or 0, ch.on, ch.swim == true, ch.sit == true, ch.dead == true
		local off = dead or dying
		local pause = off or sit or swim
		PX.step(dt, false)
		L.motion(dt, s, off)

		PET.step(dt, s, not (PET.hidden or held or swim or off), not on)

		if (ch.sBeat or 0) ~= ST.beat then
			ST.beat = ch.sBeat or 0
			if not pause and PET.pos then for _ = 1, 4 do PX.emit(PET.pos + UP * 1 * s, Vector3.new(rnd(-2, 2), rnd(2, 4), rnd(-2, 2)) * s, 0.16 * s, PAL[math.random(1, #PAL)], 0.6, 8) end end
		end

		SPK.t -= dt * (on and 0.5 or 1)
		if SPK.t <= 0 and not pause then
			SPK.t = rnd(0.25, 0.5)
			SPK.i = SPK.i % #SPK.list + 1
			local X = SPK.list[SPK.i]
			local a = rnd(0, math.pi * 2)
			X.pos = (ch.feet or Vector3.zero) + Vector3.new(math.cos(a) * rnd(1, 2.6), rnd(0.5, 5), math.sin(a) * rnd(1, 2.6)) * s
			X.t, X.ci = 0, math.random(1, #PAL)
		end
