				local st = math.floor(X.t / 0.1)
				local z = (st == 0 or st >= 6) and 0.1 or (st == 1 or st == 5) and 0.18 or 0.26
				z *= s
				if z ~= X.lz then X.lz = z X.p.Size = Vector3.one * z end
				local ci = (X.ci + st - 1) % #PAL + 1
				if X.p.Color ~= PAL[ci] then X.p.Color = PAL[ci] end
				X.p.CFrame = CFrame.new(X.pos)
				X.p.Transparency = (X.t >= 0.8 or pause) and 1 or 0.05
			end
		end

