				TL.n += 1
				TL.i = TL.i % #TL.list + 1
				local T = TL.list[TL.i]
				local gp = L.ground(ch.feet, 2, 4)
				local z = 0.9 * s
				if math.abs(T.p.Size.X - z) > 0.01 then T.p.Size = Vector3.new(z, 0.05, z) end
				T.p.CFrame = CFrame.new(gp + UP * 0.05) * (ch.flat and ch.flat.Rotation or CFrame.identity)
				T.p.Color = (TL.n % 2 == 0) and C1 or C1:Lerp(W, 0.45)
				T.t = 0
			end
		end
		TL.lp = ch.pos
		for _, T in ipairs(TL.list) do
			if T.t < 1.1 then
