			local G = GEM.list[GEM.i]
			G.t, G.at = 0, ch.head.Position + UP * 1.4 * s
			local z = 0.45 * s
			if math.abs(G.p.Size.X - z) > 0.01 then G.p.Size = Vector3.one * z end
		end
		for _, G in ipairs(GEM.list) do
			if G.t < 0.8 then
				G.t += dt
				local k = c01(G.t / 0.8)
				local p = G.at + UP * 1.2 * sc() * L.outQuad(k)
				G.p.CFrame = CFrame.new(p) * CFrame.Angles(0, G.t * 9, 0) * CFrame.Angles(math.rad(45), 0, math.rad(45))
				G.p.Transparency = k >= 1 and 1 or (k < 0.7 and 0.05 or 0.05 + 0.95 * math.floor((k - 0.7) / 0.3 * 3) / 3)
				G.lp.CFrame = CFrame.new(p + UP * 0.7 * sc())
				G.lt.TextTransparency = k >= 1 and 1 or (k < 0.7 and 0 or 0.6)
			end
		end

