			local r = ch.flat and ch.flat.RightVector or Vector3.xAxis
			for side = -1, 1, 2 do for _ = 1, 3 do PX.emit(gp + r * side * 0.5 * s + UP * 0.2 * s, (r * side * rnd(2, 4) + UP * rnd(0.5, 2)) * s, 0.26 * s, W, 0.45, 10, gp.Y) end end
		end

