function RP.splitGender(name)
	local base, tag = string.match(name, "^(.-)%s*([MF])$")
	if not base or base == "" then return name, nil end
	return base, tag
end

function RP.clipKey(name)
	local base, tag = RP.splitGender(name)
	return tag and base or name
end

function RP.soften(name)
	local base, tag = RP.splitGender(name)
	local alias = RP.ALIASES[string.lower(base)]
	if not alias then return name end
	return tag and (alias .. " " .. tag) or alias
end



