function RP.fingerprint(s)
	local h, n, i = 0x811C9DC5, #s, 1
	local canYield = coroutine.isyieldable() and task ~= nil and task.wait ~= nil
	while i + 3 <= n do
		h = bit32.band(bit32.bxor(bit32.lrotate(h, 5), (string.unpack("<I4", s, i))) + 0x9E3779B9, 0xFFFFFFFF)
		i += 4
		if canYield and i % 262144 == 1 then task.wait() end
	end
	if i <= n then
		local tail = string.sub(s, i) .. string.rep("\0", 4 - (n - i + 1))
		h = bit32.band(bit32.bxor(bit32.lrotate(h, 5), (string.unpack("<I4", tail, 1))) + 0x9E3779B9, 0xFFFFFFFF)
	end
	return bit32.band(bit32.bxor(bit32.lrotate(h, 3), n) + 0x9E3779B9, 0xFFFFFFFF)
end

