	if isfile(path) then
		local ok, body = pcall(readfile, path)
		if ok and fileOk(f, body) then return true end
	end
	local legacy = RP.PACKS.legacyDir .. "/" .. f.name
	if isfile(legacy) then
		local ok, body = pcall(readfile, legacy)
		if ok and fileOk(f, body) and pcall(writefile, path, body) then return true end
	end
	local why = "download failed"
	for _, base in ipairs(RP.PACKS.bases) do
		local ok, body = pcall(function() return game:HttpGet(base .. "/" .. f.name) end)
		if ok and type(body) == "string" and #body == f.size and RP.fingerprint(body) == f.fp then
			if not pcall(writefile, path, body) then return false, "could not save" end
			return true
		end
		why = (ok and type(body) == "string") and "download corrupted" or ("download failed (" .. string.sub(tostring(body), 1, 60) .. ")")
	end
	return false, why
end


local function keyframesOf(seq)
	local out = {}
	for _, c in ipairs(seq:GetChildren()) do if c:IsA("Keyframe") then out[#out + 1] = c end end
	table.sort(out, function(a, b) return a.Time < b.Time end)
	return out
end
local function sameNum(a, b) if a ~= a then return b ~= b end if b ~= b then return false end return math.abs(a - b) <= 1e-4 end
local function sameCF(a, b)
	local ca, cb = { a:GetComponents() }, { b:GetComponents() }
	for i = 1, 12 do if not sameNum(ca[i], cb[i]) then return false end end
	return true
end
