	for i = 1, #ka do
		if math.abs(ka[i].Time - kb[i].Time) > 1e-4 then return false end
		local pa, pb = {}, {}
		for _, d in ipairs(ka[i]:GetDescendants()) do if d:IsA("Pose") then pa[d.Name] = d.CFrame end end
		for _, d in ipairs(kb[i]:GetDescendants()) do if d:IsA("Pose") then pb[d.Name] = d.CFrame end end
