	end
	return out
end



local loadInner
function RP.loadPacks(onProgress)
	local st = RP.packState
	if st.state == "ready" then return true end
	if st.state == "loading" then return false, "loading" end
	local okCall, ok, err = pcall(loadInner, onProgress)
	if not okCall then st.state, st.err = "failed", "error: " .. string.sub(tostring(ok), 1, 80); ok, err = false, st.err end
	if st.state == "failed" and RP.changed then pcall(RP.changed) end
	return ok, err
end

loadInner = function(onProgress)
	local st = RP.packState
	if type(isfile) ~= "function" or type(readfile) ~= "function" or type(writefile) ~= "function" then
		st.state, st.err = "failed", "no file access"
		return false, st.err
	end
	st.state, st.err = "loading", nil
	pcall(function() if not isfolder(RP.PACKS.dir) then makefolder(RP.PACKS.dir) end end)
	local total = #RP.PACKS.files
	local roots = {}
	if onProgress then pcall(onProgress, 0, total) end
	for i, f in ipairs(RP.PACKS.files) do
		local ok, why = ensureFile(f)
		if not ok then st.state, st.err = "failed", f.name .. ": " .. why return false, st.err end
		local okL, root = pcall(function() return game:GetObjects(getcustomasset(RP.PACKS.dir .. "/" .. f.name))[1] end)
		if not okL or not root then strict[f.name] = true; st.state, st.err = "failed", f.name .. ": could not load" return false, st.err end
		roots[i] = root
		if onProgress then pcall(onProgress, i, total) end
		yield()
	end
	local clips = {}
	for _, pack in ipairs({ 1, 2 }) do
		local descs = {}
		for i, f in ipairs(RP.PACKS.files) do
			if f.pack == pack then for _, d in ipairs(RP.describe(roots[i], pack)) do descs[#descs + 1] = d end end
		end
		for _, c in ipairs(RP.buildIndex(descs, pack, RP.sameAnimation)) do clips[#clips + 1] = c end
	end
	RP.clips = clips
	st.state = "ready"
	if RP.changed then pcall(RP.changed) end
	return true
end






