local function tsv(a, s, d) return TweenService:GetValue(a, Enum.EasingStyle[s], Enum.EasingDirection[d]) end
RP.ease = function(a, style, dir)
	dir = dir or "In"
	if style == nil or style == "Linear" then return a end
	if style == "Constant" then
		if dir == "In" then return 1 elseif dir == "Out" then return 0 end
		return a < 0.5 and 0 or 1
	end
	if style == "Cubic" then return tsv(a, "Cubic", dir == "In" and "Out" or dir == "Out" and "In" or "InOut") end
	if style == "CubicV2" then return tsv(a, "Cubic", dir) end
	if style == "Bounce" and dir == "InOut" then
		if a < 0.5 then return 0.5 * tsv(a * 2, "Bounce", "In") end
		return 0.5 + 0.5 * tsv(a * 2 - 1, "Bounce", "In")
	end
	local ok, v = pcall(tsv, a, style, dir)
	return ok and v or a
end
