local LN2 = 0.69314718056



local BASE_TIME = 0.18
local TIME_PER_BIT = 0.12
local ANGLE_UNIT = 0.15
local MIN_TIME, MAX_TIME = 0.18, 0.7

local DURATION_WEIGHT: { [string]: number } = {
	Torso = 1,
	["Left Leg"] = 0.9,
	["Right Leg"] = 0.9,
	["Left Arm"] = 0.75,
	["Right Arm"] = 0.75,
	Head = 0.6,
}
local DEFAULT_DURATION_WEIGHT = 0.5
local TRANSLATION_WEIGHT = 0.7

local STAGGER: { [string]: number } = {
	Torso = 0,
	Head = 0.05,
	["Left Leg"] = 0.05,
	["Right Leg"] = 0.08,
	["Left Arm"] = 0.1,
	["Right Arm"] = 0.15,
}
local DEFAULT_STAGGER = 0.08

local HALFLIFE_SCALE = 0.3
local HALFLIFE_MIN, HALFLIFE_MAX = 0.08, 0.6
local POSITION_HALFLIFE = 0.12
local MAX_ANGULAR_SPEED = 25
local MAX_LINEAR_SPEED = 30




type JointState = {
	sourceQ: Quat,
	sourceP: Vector3,
	angular: Vector3,
	linear: Vector3,
	decay: Vector3,
	path: Quat,
	delay: number,
}

type State = {
	elapsed: number,
	duration: number,
	rate: number,
	joints: { [string]: JointState },
}

type Source = {
	pose: CFrame,
	angular: Vector3?,
	linear: Vector3?,
}

local function maxMagnitude(x: number, eps: number): number
	if x >= 0 and x < eps then
		return eps
	elseif x < 0 and x > -eps then
		return -eps
	end
	return x
end

local function clampSpeed(v: Vector3, limit: number): Vector3
	local m = v.Magnitude
	return if m > limit then v * (limit / m) else v
end

function Transition.Begin(
	sources: { [string]: Source },
	targets: { [string]: CFrame },
	speedScale: number?
): State
	local joints: { [string]: JointState } = {}
	local weightiest = 0

	for name, source in sources do
		local sourceQ = Transition.QuatFromCFrame(source.pose)
		local target = targets[name] or CFrame.identity
		local targetQ = Transition.QuatFromCFrame(target)
		local toward = toRotationVector(Transition.Delta(sourceQ, targetQ))
		local angular = clampSpeed(source.angular or Vector3.zero, MAX_ANGULAR_SPEED)
		local linear = clampSpeed(source.linear or Vector3.zero, MAX_LINEAR_SPEED)

		local function halflife(diff: number, speed: number): number
			return math.clamp(HALFLIFE_SCALE * diff / maxMagnitude(speed, 1e-4), HALFLIFE_MIN, HALFLIFE_MAX)
		end
		local decay = Vector3.new(
			LN2 / halflife(toward.X, angular.X),
			LN2 / halflife(toward.Y, angular.Y),
			LN2 / halflife(toward.Z, angular.Z)
		)

		local change = toward.Magnitude + (target.Position - source.pose.Position).Magnitude * TRANSLATION_WEIGHT
		weightiest = math.max(weightiest, change * (DURATION_WEIGHT[name] or DEFAULT_DURATION_WEIGHT))

		joints[name] = {
			sourceQ = sourceQ,
			sourceP = source.pose.Position,
			angular = angular,
			linear = linear,
			decay = decay,
			path = IDENTITY,
			delay = STAGGER[name] or DEFAULT_STAGGER,
		}
	end

	local duration = BASE_TIME + TIME_PER_BIT * math.log(1 + weightiest / ANGLE_UNIT, 2)
	duration = math.clamp(duration, MIN_TIME, MAX_TIME) / math.sqrt(math.clamp(speedScale or 1, 0.5, 2))
	return { elapsed = 0, duration = duration, rate = 1, joints = joints }
end

local function extrapolate(joint: JointState, t: number): (Quat, Vector3)
	local w, y = joint.angular, joint.decay
	local rotation = Vector3.new(
		w.X / y.X * (1 - math.exp(-y.X * t)),
		w.Y / y.Y * (1 - math.exp(-y.Y * t)),
		w.Z / y.Z * (1 - math.exp(-y.Z * t))
	)
	local q = mul(fromRotationVector(rotation), joint.sourceQ)
	local py = LN2 / POSITION_HALFLIFE
	local p = joint.sourceP + joint.linear * ((1 - math.exp(-py * t)) / py)
	return q, p
