local function weightOf(state: State, joint: JointState): number
	local start = joint.delay * state.duration
	local span = state.duration - start
	return Transition.MinimumJerk((state.elapsed - start) / math.max(span, 1e-3))
end

function Transition.Pose(state: State, name: string, target: CFrame): CFrame
	local joint = state.joints[name]
	if not joint then
		return target
	end
	local alpha = weightOf(state, joint)
	if alpha >= 1 then
		return target
	end
