	state.elapsed += dt * state.rate
end

function Transition.IsDone(state: State): boolean
	return state.elapsed >= state.duration
end

function Transition.Hurry(state: State, remaining: number)
	local left = state.duration - state.elapsed
	if left > remaining and remaining > 0 then
		state.rate = math.max(state.rate, left / remaining)
	end
end

