local PostureBridge = {}



local LN2 = 0.69314718056
local minimumJerk = Transition.MinimumJerk

local function smooth(x: number): number
	x = math.clamp(x, 0, 1)
	return x * x * (3 - 2 * x)
end

local function limit(v: Vector3, max: number): Vector3
	local m = v.Magnitude
	return if m > max then v * (max / m) else v
end

local function rotationVector(cf: CFrame): Vector3
	return Transition.ToRotationVector(Transition.QuatFromCFrame(cf))
end

local function fromRotationVector(v: Vector3): CFrame
	local angle = v.Magnitude
	if angle < 1e-9 then
		return CFrame.identity
	end
	return CFrame.fromAxisAngle(v / angle, angle)
end

local function soft(x: number, limit: number): number
	local knee = limit * 0.8
	local a = math.abs(x)
	if a <= knee then
		return x
	end
	local span = limit - knee
	local over = (a - knee) / span
	local e = math.exp(-2 * over)
	return math.sign(x) * (knee + span * (1 - e) / (1 + e))
end

local function softRange(x: number, low: number, high: number): number
	if x >= 0 then
		return soft(x, high)
	end
	return -soft(-x, -low)
end



local function decayRate(halflife: number): number
	return 2 * LN2 / math.max(halflife, 1e-4)
end

local function springRotation(x: CFrame, w: Vector3, goal: CFrame, halflife: number, dt: number): (CFrame, Vector3)
	local y = decayRate(halflife)
	local j0 = rotationVector(x * goal:Inverse())
	local j1 = w + j0 * y
	local e = math.exp(-y * dt)
	return fromRotationVector((j0 + j1 * dt) * e) * goal, (w - j1 * (y * dt)) * e
end

local function springRotationLoose(x: CFrame, w: Vector3, goal: CFrame, frequency: number, ratio: number, dt: number): (CFrame, Vector3)
	local omega = 2 * math.pi * frequency
	local k, c = omega * omega, 2 * ratio * omega
	local steps = math.max(1, math.ceil(dt * 240))
	local h = dt / steps
	local offset = rotationVector(x * goal:Inverse())
	for _ = 1, steps do
		w += (-offset * k - w * c) * h
		offset += w * h
	end
	return fromRotationVector(offset) * goal, w
end


local function quintic(x0: number, v0: number, t1: number, t: number): number
	if x0 < 1e-6 or t >= t1 then
		return 0
	end
	if v0 > 0 then
		v0 = 0
	end
	local t2 = t1
	if v0 < 0 then
		t2 = math.min(t1, -5 * x0 / v0)
	end
	if t >= t2 then
		return 0
	end
	local a0 = (-8 * v0 * t2 - 20 * x0) / (t2 * t2)
	local A = -(a0 * t2 * t2 + 6 * v0 * t2 + 12 * x0) / (2 * t2 ^ 5)
	local B = (3 * a0 * t2 * t2 + 16 * v0 * t2 + 30 * x0) / (2 * t2 ^ 4)
	local C = -(3 * a0 * t2 * t2 + 12 * v0 * t2 + 20 * x0) / (2 * t2 ^ 3)
	return ((((A * t + B) * t + C) * t + 0.5 * a0) * t + v0) * t + x0
end

local function decayVector(x0: Vector3, v0: Vector3, t1: number, t: number): Vector3
	local m = x0.Magnitude
	if m < 1e-6 then
		return Vector3.zero
	end
	local dir = x0 / m
	return dir * quintic(m, v0:Dot(dir), t1, t)
end

type Offset = { r: Vector3, p: Vector3, wr: Vector3, wp: Vector3 }

local function offsetOf(from: CFrame, to: CFrame): (Vector3, Vector3)
	return rotationVector(from.Rotation * to.Rotation:Inverse()), from.Position - to.Position
end

local function withOffset(pose: CFrame, r: Vector3, p: Vector3): CFrame
