end



type JointGeometry = {
	c0: CFrame,
	rest: CFrame,
	reach: Vector3,
	up: Vector3?,
}

type Geometry = {
	root: JointGeometry,
	limbs: { [string]: JointGeometry },
	head: JointGeometry?,
	sizes: { [string]: Vector3 },
}

local LIMBS = { "Left Arm", "Right Arm", "Left Leg", "Right Leg" }
local NAMES = { "Torso", "Head", "Left Arm", "Right Arm", "Left Leg", "Right Leg" }

local MASS: { [string]: number } = {
	Torso = 0.5,
	Head = 0.08,
	["Left Arm"] = 0.05,
	["Right Arm"] = 0.05,
	["Left Leg"] = 0.16,
	["Right Leg"] = 0.16,
}

function PostureBridge.Geometry(rig: { [string]: { motor: Motor6D, originC1: CFrame } }): Geometry?
	local torso = rig.Torso
	if not torso or not torso.motor.Part0 or torso.motor.Part0.Name ~= "HumanoidRootPart" or not torso.motor.Part1 then
		return nil
	end
	local limbs: { [string]: JointGeometry } = {}
	local sizes: { [string]: Vector3 } = { Torso = (torso.motor.Part1 :: BasePart).Size }
	for _, name in LIMBS do
		local joint = rig[name]
		if not joint or not joint.motor.Part0 or joint.motor.Part0.Name ~= "Torso" or not joint.motor.Part1 then
			return nil
		end
		local size = (joint.motor.Part1 :: BasePart).Size
		sizes[name] = size
		limbs[name] = {
			c0 = joint.motor.C0,
			rest = joint.originC1,
			reach = joint.originC1:Inverse() * Vector3.new(0, -size.Y / 2, 0),
		}
	end
	local head: JointGeometry? = nil
	local neck = rig.Head
	if neck and neck.motor.Part0 and neck.motor.Part0.Name == "Torso" and neck.motor.Part1 then
		sizes.Head = (neck.motor.Part1 :: BasePart).Size
		head = {
			c0 = neck.motor.C0,
			rest = neck.originC1,
			reach = neck.originC1:Inverse():VectorToWorldSpace(Vector3.new(0, 0, -1)),
			up = neck.originC1:Inverse():VectorToWorldSpace(Vector3.new(0, 1, 0)),
		}
	end
	return {
		root = { c0 = torso.motor.C0, rest = torso.originC1, reach = Vector3.zero },
		limbs = limbs,
		head = head,
		sizes = sizes,
	}
end

local function torsoFrame(g: Geometry, pose: CFrame): CFrame
	return g.root.c0 * pose * g.root.rest:Inverse()
end
local function torsoPose(g: Geometry, frame: CFrame): CFrame
	return g.root.c0:Inverse() * frame * g.root.rest
end

local function partFrame(joint: JointGeometry, torso: CFrame, pose: CFrame): CFrame
	return torso * joint.c0 * pose * joint.rest:Inverse()
end

local function arc(a: Vector3, b: Vector3): CFrame
	local u, v = a.Unit, b.Unit
	local d = math.clamp(u:Dot(v), -1, 1)
	if d > 0.99999 then
		return CFrame.identity
	end
	local axis = u:Cross(v)
	if axis.Magnitude < 1e-6 then
		axis = if math.abs(u.X) < 0.9 then u:Cross(Vector3.xAxis) else u:Cross(Vector3.yAxis)
	end
	return CFrame.fromAxisAngle(axis.Unit, math.acos(d))
end

local function flat(v: Vector3, fallback: Vector3): Vector3
	local f = Vector3.new(v.X, 0, v.Z)
	return if f.Magnitude > 1e-3 then f.Unit else fallback
end

local function swingTwist(rotation: CFrame, axis: Vector3): (CFrame, number)
	local q = Transition.QuatFromCFrame(rotation)
	if q.w < 0 then
		q = { w = -q.w, x = -q.x, y = -q.y, z = -q.z }
	end
	local along = Vector3.new(q.x, q.y, q.z):Dot(axis)
	local angle = 2 * math.atan2(along, q.w)
	local twist = CFrame.fromAxisAngle(axis, angle)
	return rotation * twist:Inverse(), angle
end



local NECK_TURN = math.rad(70)
local NECK_DOWN = math.rad(50)
local NECK_UP = math.rad(45)
local NECK_TILT = math.rad(30)

local function limitHead(head: JointGeometry, pose: CFrame): CFrame
	local up = head.up or Vector3.yAxis
	local forward = head.reach.Unit
	local right = forward:Cross(up).Unit
	local swing, turn = swingTwist(pose.Rotation, up)
	turn = soft(turn, NECK_TURN)
	local s = rotationVector(swing)
	local nod = softRange(-s:Dot(right), -NECK_UP, NECK_DOWN)
	local tilt = soft(s:Dot(forward), NECK_TILT)
	local limited = fromRotationVector(-right * nod + forward * tilt) * CFrame.fromAxisAngle(up, turn)
	return CFrame.new(pose.Position) * limited
end

local LIMB_TWIST: { [string]: number } = {
	["Left Leg"] = math.rad(50),
	["Right Leg"] = math.rad(50),
	["Left Arm"] = math.rad(90),
	["Right Arm"] = math.rad(90),
}

local function limitLimb(joint: JointGeometry, name: string, pose: CFrame): CFrame
	local limit = LIMB_TWIST[name]
	if not limit then
		return pose
	end
	local axis = joint.reach.Unit
	local swing, twist = swingTwist(pose.Rotation, axis)
	local _, swung = swing:ToAxisAngle()
	if swung > math.pi then
		swung = 2 * math.pi - swung
	end
	local hold = smooth((math.rad(150) - swung) / math.rad(40))
	local limited = twist + (soft(twist, limit) - twist) * hold
	if math.abs(limited - twist) < 1e-4 then
		return pose
	end
	return CFrame.new(pose.Position) * swing * CFrame.fromAxisAngle(axis, limited)
end

local MAX_TWIST = math.rad(50)
local function orient(joint: JointGeometry, torso: CFrame, direction: Vector3, front: Vector3): CFrame
	local frame = torso * joint.c0
	local pose = arc(joint.reach, frame:VectorToObjectSpace(direction))
	local part = frame * pose * joint.rest:Inverse()
	local axis = direction.Unit
	local wanted = front - axis * front:Dot(axis)
	local current = part.LookVector - axis * part.LookVector:Dot(axis)
	local reliable = smooth((wanted.Magnitude - 0.15) / 0.3)
	if reliable <= 0 or current.Magnitude < 1e-3 then
		return pose
	end
	wanted, current = wanted.Unit, current.Unit
	local raw = math.atan2(current:Cross(wanted):Dot(axis), current:Dot(wanted))
	local angle = reliable * smooth((math.pi - math.abs(raw)) / 0.6) * math.clamp(raw, -MAX_TWIST, MAX_TWIST)
	local swing = CFrame.fromAxisAngle(axis, angle)
	return frame.Rotation:Inverse() * swing * frame.Rotation * pose
end



type Posture = "Stand" | "Low" | "Prone" | "Supine" | "Other"

local REST_HIP_Y = -1
local LOW_HIP_DROP = 0.8

local function classify(frame: CFrame): Posture
	local up, front = frame.UpVector, frame.LookVector
	local hipY = (frame * CFrame.new(0, -1, 0)).Y
	if up.Y < -0.4 then
		return "Other"
	elseif up.Y >= 0.6 then
		return if hipY <= REST_HIP_Y - LOW_HIP_DROP then "Low" else "Stand"
	end
	return if front.Y < 0 then "Prone" else "Supine"
end
local function lying(posture: Posture): boolean
	return posture == "Prone" or posture == "Supine"
end

local function facingOf(frame: CFrame, posture: Posture): Vector3
	if posture == "Prone" then
		return flat(frame.UpVector, Vector3.new(0, 0, -1))
	elseif posture == "Supine" then
		return flat(-frame.UpVector, Vector3.new(0, 0, -1))
	end
	return flat(frame.LookVector, Vector3.new(0, 0, -1))
end

local function yawFrame(direction: Vector3): CFrame
	return CFrame.lookAt(Vector3.zero, direction)
end

local function yawBetween(a: Vector3, b: Vector3): number
	return math.atan2(a:Cross(b).Y, a:Dot(b))
end



type LimbSpec = {
