	balance: ("both" | "stance")?,
	sway: number?,

	origin: Vector3?,
	facing: CFrame?,
	previousFacing: CFrame?,
	lookFacing: CFrame?,
	step: number?,
}

type Context = {
	g: Geometry,
	floorY: number,
	restY: number,
	sourceTorso: CFrame,
	destTorso: CFrame,
	step: number,
}

local function side(name: string): number
	return if string.find(name, "Right") then 1 else -1
end

local function mirrored(v: Vector3, name: string): Vector3
	return Vector3.new(v.X * side(name), v.Y, v.Z)
end

local function buildTorso(ctx: Context, spec: KeySpec, facing: CFrame, step: number): CFrame
	if spec.torso then
		return spec.torso
	end
	if spec.torsoFrom then
		local base = if spec.torsoFrom == "source" then ctx.sourceTorso else ctx.destTorso
		return base + Vector3.new(0, spec.lift or 0, 0)
	end
	local hipY = spec.hipY or (ctx.floorY + (spec.hipYFromFloor or 1))
	local origin = spec.origin or Vector3.zero
	local hip = Vector3.new(origin.X, hipY, origin.Z)
		+ facing:VectorToWorldSpace(Vector3.new((spec.hipSide or 0) * step, 0, spec.hipBack or 0))
	return CFrame.new(hip) * facing.Rotation
		* CFrame.Angles(-math.rad(spec.lean or 0), 0, -math.rad((spec.roll or 0) * step))
		* CFrame.new(0, 1, 0)
end

local function contactFor(ctx: Context, joint: JointGeometry, torso: CFrame, spec: LimbSpec, name: string, facing: CFrame): Vector3
	local frame = torso * joint.c0
	local pivot = frame.Position
	local surface = if spec.surface == "rest" then ctx.restY else ctx.floorY
	local length = joint.reach.Magnitude
	local height = pivot.Y - surface
	local base = Vector3.new(pivot.X, surface, pivot.Z)
	if height >= length then
		return base
	end
	local radius = math.sqrt(length * length - height * height)
	local right = flat(torso.RightVector, Vector3.xAxis)
	local lateral = right * frame:VectorToWorldSpace(joint.reach):Dot(right)
	local wanted = if spec.absolute then spec.plant :: Vector3 else mirrored(spec.plant :: Vector3, name)
	local direction = flat(facing:VectorToWorldSpace(wanted), facing.LookVector)
	local along = lateral:Dot(direction)
	local discriminant = along * along - (lateral:Dot(lateral) - radius * radius)
	local t = if discriminant >= 0 then -along + math.sqrt(discriminant) else -1
	if t < 0 then
		return base + (if lateral.Magnitude > 1e-3 then lateral.Unit else direction) * radius
	end
	return base + lateral + direction * t
end

local function fromOwnLine(joint: JointGeometry, torso: CFrame, wanted: Vector3): Vector3
	local down = Vector3.new(0, -1, 0)
	local reach = (torso * joint.c0):VectorToWorldSpace(joint.reach)
	local right = flat(torso.RightVector, Vector3.xAxis)
	local sideways = reach:Dot(right)
	local length = reach.Magnitude
	local hang = right * sideways + down * math.sqrt(math.max(length * length - sideways * sideways, 0))
	return arc(down, wanted) * hang
end

local function lowestPoint(frame: CFrame, size: Vector3): number
	return frame.Y
		- (math.abs(frame.RightVector.Y) * size.X + math.abs(frame.UpVector.Y) * size.Y + math.abs(frame.LookVector.Y) * size.Z) / 2
end


local function lowestOfPose(g: Geometry, torso: CFrame, poseOf: (string) -> CFrame?): number
	local low = lowestPoint(torso, g.sizes.Torso)
	local head = g.head
	if head and g.sizes.Head then
		low = math.min(low, lowestPoint(partFrame(head, torso, poseOf("Head") or CFrame.identity), g.sizes.Head))
	end
	for name, joint in g.limbs do
		low = math.min(low, lowestPoint(partFrame(joint, torso, poseOf(name) or CFrame.identity), g.sizes[name]))
	end
	return low
end

local function levelHead(head: JointGeometry, torso: CFrame, pose: CFrame, weight: number): CFrame
	if weight <= 0 then
		return pose
	end
	local frame = torso * head.c0
	local part = frame * pose * head.rest:Inverse()
	local look = part.LookVector
	if math.abs(look.Y) > 0.95 then
		return pose
	end
	local current = part.Rotation
	local turn = current:Lerp(CFrame.lookAt(Vector3.zero, look), math.min(weight, 1)) * current:Inverse()
	local pivot = frame.Position
	local levelled = CFrame.new(pivot) * turn * CFrame.new(-pivot) * part
	return frame:Inverse() * levelled * head.rest
end

local function centreOfMass(g: Geometry, torso: CFrame, poses: { [string]: CFrame }): Vector3
	local sum = torso.Position * MASS.Torso
	local total = MASS.Torso
	for name, joint in g.limbs do
		local pose = poses[name]
		if pose then
			sum += partFrame(joint, torso, pose).Position * MASS[name]
			total += MASS[name]
		end
	end
	local head = g.head
	if head then
		sum += partFrame(head, torso, poses.Head or CFrame.identity).Position * MASS.Head
		total += MASS.Head
	end
	return sum / total
end

type Built = { poses: { [string]: CFrame }, contacts: { [string]: Vector3 } }
type Placed = { t: number, speed: number, poses: { [string]: CFrame }, contacts: { [string]: Vector3 } }
type Hold = { name: string, contact: Vector3, t0: number, t1: number, last: boolean }

local function buildKey(ctx: Context, spec: KeySpec, facing: CFrame, previous: Built?): Built
	local g = ctx.g
	local step = spec.step or ctx.step
	local torso = buildTorso(ctx, spec, facing, step)

	if spec.torsoFrom and spec.lift then
		local over = 0
		for name, limb in spec.arms do
			local joint = g.limbs[name]
			if joint and limb.plant then
				local surface = if limb.surface == "rest" then ctx.restY else ctx.floorY
				local pivot = (torso * joint.c0).Position
				over = math.max(over, pivot.Y - surface - joint.reach.Magnitude * 0.97)
			end
		end
		if over > 0 then
			torso -= Vector3.new(0, over, 0)
		end
	end

	local function limbFacing(limb: LimbSpec): CFrame
		return if limb.previous and spec.previousFacing then spec.previousFacing else facing
	end

	local contacts: { [string]: Vector3 } = {}
	for name, joint in g.limbs do
		local limb = spec.arms[name] or spec.legs[name]
		if limb and limb.plant then
			local kept = if limb.keep and previous then previous.contacts[name] else nil
			contacts[name] = kept or contactFor(ctx, joint, torso, limb, name, limbFacing(limb))
		end
	end

	local function solveLimbs(): { [string]: CFrame }
		local poses: { [string]: CFrame } = { Torso = torsoPose(g, torso) }
		for name, joint in g.limbs do
			local limb = spec.arms[name] or spec.legs[name]
			if limb then
				local heading = if limb.relative then torso else limbFacing(limb)
				local front = heading.LookVector
				local contact = contacts[name]
				local direction = if contact
					then contact - (torso * joint.c0).Position
					else fromOwnLine(joint, torso, heading:VectorToWorldSpace(
						if limb.absolute then (limb.point :: Vector3).Unit else mirrored((limb.point :: Vector3).Unit, name)))
				poses[name] = orient(joint, torso, direction, front)
			end
		end
		if g.head and spec.look then
			local lookFrame = spec.lookFacing or facing
			local head = g.head :: JointGeometry
			poses.Head = arc(head.reach, (torso * head.c0):VectorToObjectSpace(lookFrame:VectorToWorldSpace(spec.look.Unit)))
			poses.Head = limitHead(head, levelHead(head, torso, poses.Head, 0.7))
		end
		return poses
	end

	if spec.balance and next(contacts) then
		local stanceLeg = if step > 0 then "Left Leg" else "Right Leg"
		local target: Vector3? = nil
		for _ = 1, 8 do
			local poses = solveLimbs()
			local com = centreOfMass(g, torso, poses)
			if not target then
				local weighted, total = Vector3.zero, 0
				for name, point in contacts do
					local w = if string.find(name, "Arm") then 0.8
						elseif spec.balance == "stance" then (if name == stanceLeg then 0.7 else 0.3)
						else 1
					weighted += point * w
					total += w
				end
				target = com:Lerp(weighted / total, spec.sway or 1)
			end
			local support = target :: Vector3
			local shift = Vector3.new(support.X - com.X, 0, support.Z - com.Z)
			if shift.Magnitude > 0.6 then
				shift = shift.Unit * 0.6
			end
			torso += shift * 0.85

			local drop = math.huge
			for name, point in contacts do
				if string.find(name, "Leg") then
					local joint = g.limbs[name]
					local pivot = (torso * joint.c0).Position
					local length = joint.reach.Magnitude
					local r = Vector3.new(point.X - pivot.X, 0, point.Z - pivot.Z).Magnitude
					local wantY = if r < length then point.Y + math.sqrt(length * length - r * r) else point.Y
					drop = math.min(drop, wantY - pivot.Y)
				end
			end
			if drop < math.huge then
				torso += Vector3.new(0, drop, 0)
			end

			local hip = torso * Vector3.new(0, -1, 0)
			local worst, worstPivot, worstPoint = 0.02, Vector3.zero, Vector3.zero
			for name, point in contacts do
				local joint = g.limbs[name]
				if string.find(name, "Arm") and joint then
					local pivot = (torso * joint.c0).Position
					local over = (point - pivot).Magnitude - joint.reach.Magnitude
					if over > worst then
						worst, worstPivot, worstPoint = over, pivot, point
					end
				end
			end
			if worst > 0.02 then
				local axis = (worstPivot - hip):Cross(worstPoint - hip)
				local radius = (worstPivot - hip).Magnitude
				if axis.Magnitude > 1e-4 and radius > 1e-3 then
					local angle = math.min(worst / radius, math.rad(15))
					torso = CFrame.new(hip) * CFrame.fromAxisAngle(axis.Unit, angle) * CFrame.new(-hip) * torso
				end
			end
		end
	end

	return { poses = solveLimbs(), contacts = contacts }
end



local FWD, BACK = Vector3.new(0, 0, -1), Vector3.new(0, 0, 1)
local STAND = Vector3.new(-1, 0, 0)

local function legs(stepLeg: LimbSpec, otherLeg: LimbSpec, step: number): { [string]: LimbSpec }
	if step > 0 then
		return { ["Right Leg"] = stepLeg, ["Left Leg"] = otherLeg }
	end
	return { ["Left Leg"] = stepLeg, ["Right Leg"] = otherLeg }
end

local function arms(stepArm: LimbSpec, otherArm: LimbSpec, step: number): { [string]: LimbSpec }
	if step > 0 then
		return { ["Right Arm"] = stepArm, ["Left Arm"] = otherArm }
	end
	return { ["Left Arm"] = stepArm, ["Right Arm"] = otherArm }
end

local function bothArms(spec: LimbSpec): { [string]: LimbSpec }
	return { ["Right Arm"] = spec, ["Left Arm"] = spec }
end

type Phase = { duration: number, keys: { KeySpec }, facing: CFrame }

local function standKey(at: number, step: number, keepFeet: boolean?): KeySpec
	return {
		at = at, speed = 0.5, hipY = -1, lean = 1.5, roll = 1, balance = "stance", sway = if keepFeet then 1 else 0.5,
		legs = legs({ plant = STAND, keep = keepFeet }, { plant = STAND, keep = keepFeet }, step),
		arms = arms({ point = Vector3.new(0.12, -1, -0.06) }, { point = Vector3.new(0.08, -1, 0.03) }, step),
		look = Vector3.new(0, -0.05, -1),
	}
end



local function upFromProne(step: number): Phase
	return {
		duration = 2.4,
		facing = CFrame.identity,
		keys = {
			{ at = 0.12, speed = 0.8, torsoFrom = "source", lift = 0.3,
				legs = legs({ plant = BACK, surface = "rest" }, { plant = BACK, surface = "rest" }, step),
				arms = bothArms({ plant = Vector3.new(0.9, 0, -0.3), surface = "rest" }),
				look = Vector3.new(0, -0.3, -1) },
			{ at = 0.26, speed = 0.9, torsoFrom = "source", lift = 0.7,
				legs = legs({ plant = BACK, surface = "rest", keep = true }, { plant = BACK, surface = "rest", keep = true }, step),
				arms = bothArms({ plant = Vector3.new(0.8, 0, -0.3), surface = "rest", keep = true }),
				look = Vector3.new(0, -0.3, -1) },
			{ at = 0.44, speed = 0.6, hipYFromFloor = 0.9, hipBack = 0.5, lean = 70, balance = "both",
				legs = legs({ plant = BACK }, { plant = BACK }, step),
				arms = bothArms({ plant = Vector3.new(0.1, 0, -1) }),
				look = Vector3.new(0, -0.5, -0.9) },
			{ at = 0.62, speed = 0.9, hipYFromFloor = 1.95, hipBack = 0.45, lean = 80, balance = "both",
				legs = legs({ plant = BACK }, { plant = BACK }, step),
				arms = bothArms({ plant = Vector3.new(0.05, 0, -1), keep = true }),
				look = Vector3.new(0, -0.8, -0.6) },
			{ at = 0.8, speed = 1.2, hipY = -1.15, lean = 30, balance = "both",
				legs = legs({ plant = FWD, keep = true }, { plant = FWD, keep = true }, step),
				arms = bothArms({ point = Vector3.new(0.15, -0.95, -0.3) }),
				look = Vector3.new(0, -0.2, -1) },
			standKey(1, step, true),
		},
	}
end

