local function upFromLow(step: number, sourceHipY: number, kneeling: boolean): Phase
	local base: LimbSpec = if kneeling then { plant = BACK, keep = true } else { plant = FWD, keep = true }
	return {
		duration = 1.4,
		facing = CFrame.identity,
		keys = {
			{ at = 0.3, speed = 0.9, hipY = sourceHipY, lean = 30, balance = "both",
				legs = legs(base, base, step),
				arms = bothArms({ point = Vector3.new(0.2, -0.5, -0.8) }),
				look = Vector3.new(0, -0.2, -1) },
			{ at = 0.66, speed = 1.2, hipY = -1.2, lean = 22, balance = "both",
				legs = legs({ plant = STAND }, { plant = STAND }, step),
				arms = bothArms({ point = Vector3.new(0.15, -0.95, -0.25) }),
				look = Vector3.new(0, -0.15, -1) },
			standKey(1, step),
		},
