		return {
			duration = 1.3,
			facing = CFrame.identity,
			keys = {
				{ at = 0.15, speed = 0.8, hipY = -1.02, hipSide = -0.16, lean = 3, roll = -4, balance = "stance",
					legs = legs({ plant = STAND, keep = true }, { plant = STAND, keep = true }, step),
