					legs = legs({ point = Vector3.new(0, -0.88, 0.45) }, { plant = STAND, keep = true }, step),
					arms = bothArms({ point = Vector3.new(0.15, -0.9, -0.35) }),
					look = Vector3.new(0, -0.3, -1) },
				{ at = 0.58, speed = 0.6, hipY = REST_HIP_Y + (destHipY - REST_HIP_Y) * 0.5, lean = 12, balance = "both",
					legs = legs({ plant = BACK }, { plant = STAND, keep = true }, step),
					arms = bothArms({ point = Vector3.new(0.2, -0.7, -0.6) }),
					look = Vector3.new(0, -0.25, -1) },
