	RPUI._ringGui = g
	new("TextButton", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 0.45, AutoButtonColor = false, Text = "", Parent = g })
	local card = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromOffset(300, 390), BackgroundColor3 = Color3.fromRGB(24, 24, 32), Parent = g }); corner(card, 16)
	local who = (cur.partner and cur.partner.name) or "Partner"
	lbl({ Position = UDim2.fromOffset(0, 14), Size = UDim2.new(1, 0, 0, 20), Text = cur.role == "a" and ("You challenged " .. who) or (who .. " challenged you"), Font = FONTB, TextSize = 15, Parent = card })
	lbl({ Position = UDim2.fromOffset(0, 36), Size = UDim2.new(1, 0, 0, 16), Text = "Tap when the needle is in the pink. 5 hits wins.", TextSize = 12, TextColor3 = Color3.fromRGB(170, 170, 185), Parent = card })
	local R, CX, CY, N = 100, 150, 178, 120
	local PINK, GREEN, RED, TRACK = Color3.fromRGB(255, 111, 174), Color3.fromRGB(80, 230, 140), Color3.fromRGB(255, 80, 80), Color3.fromRGB(44, 44, 58)
	local segs, len = {}, 2 * math.pi * R / N + 1.5
	for i = 1, N do
		local a = (i - 0.5) / N * 2 * math.pi
		local pos = UDim2.fromOffset(CX + R * math.sin(a), CY - R * math.cos(a))
		local glow = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = pos, Size = UDim2.fromOffset(len, 20), Rotation = math.deg(a), BackgroundColor3 = PINK, BackgroundTransparency = 1, BorderSizePixel = 0, Parent = card })
		local d = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = pos, Size = UDim2.fromOffset(len, 10), Rotation = math.deg(a), BackgroundColor3 = TRACK, BorderSizePixel = 0, ZIndex = 2, Parent = card })
		segs[i] = { f = d, g = glow, a = a }
	end

	local needle = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(5, 34), BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0, ZIndex = 4, Parent = card }); corner(needle, 2)
	local big = lbl({ AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromOffset(CX, CY - 10), Size = UDim2.fromOffset(140, 44), Text = "0/5", Font = FONTB, TextSize = 40, Parent = card })
	local flash = lbl({ AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromOffset(CX, CY + 24), Size = UDim2.fromOffset(140, 18), Text = "", Font = FONTB, TextSize = 14, Parent = card })

	lbl({ Position = UDim2.fromOffset(20, 304), Size = UDim2.fromOffset(60, 14), Text = "Misses", TextSize = 11, TextXAlignment = Enum.TextXAlignment.Left, Parent = card })
	local pips = {}
	for i = 1, CH.MISSES do
		pips[i] = new("Frame", { Position = UDim2.fromOffset(80 + (i - 1) * 22, 305), Size = UDim2.fromOffset(12, 12), BackgroundColor3 = TRACK, Parent = card }); corner(pips[i], 6)
	end
	local them = lbl({ Position = UDim2.fromOffset(20, 332), Size = UDim2.new(1, -40, 0, 16), Text = who .. ": 0/5 hits", TextSize = 12, TextXAlignment = Enum.TextXAlignment.Left, TextColor3 = Color3.fromRGB(122, 167, 255), TextTruncate = Enum.TextTruncate.AtEnd, Parent = card })
	local s = CH.needleNew()
	local flashT = 0
	local UIS, RS = game:GetService("UserInputService"), game:GetService("RunService")
	local function tap()
		local r = RP.CH.needleClick(s)
		if not r then return end
		flashT = os.clock()
		flash.Text, flash.TextColor3 = r == "hit" and "HIT" or "MISS", r == "hit" and GREEN or RED
		pcall(CH.report, s.hits, s.miss)
	end
	RPUI._ringConns = {
		UIS.InputBegan:Connect(function(i, gp)

			if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch or (i.KeyCode == Enum.KeyCode.Space and not gp) then tap() end
		end),
	}
	RPUI._ringConns[2] = RS.RenderStepped:Connect(function(dt)
		if System._sessionAlive == false or CH.cur ~= cur then RPUI.ringClose() return end
		RP.CH.needleStep(s, math.min(dt, 0.1))
		pcall(CH.report, s.hits, s.miss)
		if not RPUI._ringGui then return end
		local P0 = RP.peers and RP.peers[cur.peer]
		if CH.over(cur.id, s.hits, s.miss, P0 and P0.ch) and os.clock() - flashT > 0.35 then

			RPUI.ringClose()
			if CH.cur == cur then
				cur.lastPub = nil; pcall(CH.report, s.hits, s.miss)
				toast("Roleplay", "Deciding...", "info")
			end
			return
		end
		local recent = os.clock() - flashT < 0.25
		local zc = recent and flash.TextColor3 or PINK
		for _, d in ipairs(segs) do
			local x = (d.a - s.z) % (2 * math.pi)
			if x > math.pi then x = x - 2 * math.pi end
			local on = math.abs(x) <= CH.ZONE_W / 2
			d.f.BackgroundColor3 = on and zc or TRACK
			d.g.BackgroundColor3 = zc
			d.g.BackgroundTransparency = on and 0.7 or 1
		end
		needle.Position = UDim2.fromOffset(CX + R * math.sin(s.a), CY - R * math.cos(s.a))
		needle.Rotation = math.deg(s.a)
		big.Text = s.hits .. "/" .. CH.HITS
		for i, p in ipairs(pips) do p.BackgroundColor3 = i <= s.miss and RED or TRACK end
		if not recent then
			local done = s.hits >= CH.HITS or s.miss >= CH.MISSES
			flash.Text, flash.TextColor3 = done and "Waiting..." or "", Color3.fromRGB(170, 170, 185)
		end
		local P = RP.peers and RP.peers[cur.peer]
		local o = P and P.ch
		if o and o.id == cur.id and type(o.pr) == "number" then
			them.Text = string.format("%s: %d/%d hits, %d missed", who, math.floor(o.pr * CH.HITS + 0.5), CH.HITS, o.m or 0)
		end
	end)
end


