RPUI.BB_IDLE = 6

function RPUI.bbView(st, running, name)
	if running then return "Ring Challenge running...", {} end
	local role = st and st.role

	if role == "winner" and not st.shared and (st.lockLeft or 0) > 0 then return "You control " .. tostring(name), { { "Give control", "give" } } end
	if role == "loser" and not st.shared and (st.lockLeft or 0) > 0 then
		local s = math.ceil(st.lockLeft)
		return string.format("Locked %d:%02d", s // 60, s % 60), {}
	end
	if role == nil then return tostring(name), { { "Challenge", "challenge" } } end
	if st.canRematch then return "Shared control", { { "Rematch", "challenge" } } end
	return "Shared control", {}
end
function RPUI.bbHide(now, lastT, dist) return dist == nil or dist > RPUI.RANGE or now - lastT > RPUI.BB_IDLE end
function RPUI.bbClose()
	local b = RPUI._bb
	RPUI._bb = nil
	if b then
		if b.conn then pcall(function() b.conn:Disconnect() end) end
		pcall(function() b.gui:Destroy() end)
	end
end

function RPUI.bbPlayerAt(part)
	local RP = System.RP
	local Players = game:GetService("Players")
	local m = part
	for _ = 1, 4 do
		m = m and m:FindFirstAncestorOfClass("Model")
		local pl = m and Players:GetPlayerFromCharacter(m)
		if pl then
			for _, q in ipairs(RP.partners()) do if q.id == pl.UserId then return q, m end end
			return nil, m
		end
	end

	local body = part and part:FindFirstAncestorOfClass("Model")
	while body and not body:FindFirstChildOfClass("Humanoid") do body = body:FindFirstAncestorOfClass("Model") end
	return nil, body
end
function RPUI.bbShow(q, char)
