	local okP = pcall(function() g.Parent = game:GetService("CoreGui") end)
	if not okP or not g.Parent then okP = pcall(function() local h = gethui(); g.Parent = h:IsA("LayerCollector") and h.Parent or h end) end
	if not okP or not g.Parent then g.Parent = game:GetService("Players").LocalPlayer:WaitForChild("PlayerGui") end
	local card = new("Frame", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.fromRGB(24, 24, 32), BackgroundTransparency = 0.08, Parent = g }); corner(card, 10)
	local line = lbl({ Position = UDim2.fromOffset(8, 5), Size = UDim2.new(1, -16, 0, 18), Text = "", Font = FONTB, TextSize = 13, TextTruncate = Enum.TextTruncate.AtEnd, Parent = card })
	local b = { gui = g, q = q, char = char, t = os.clock(), line = line, card = card, sig = nil }
	RPUI._bb = b
	local function act(what)
		b.t = os.clock()
		if what == "give" then RP.CH.giveControl(q.id)
		else
			local ok, err = RP.challenge(q, nil)
			if ok then RPUI.partner = q; if RP.changed then pcall(RP.changed) end end
			toast("Roleplay", ok and ("Challenge sent to " .. (q.name or "them")) or ("Couldn't challenge: " .. tostring(err)), ok and "info" or "warn")
		end
		b.sig = nil
	end
	local acc = 1
	b.conn = game:GetService("RunService").Heartbeat:Connect(function(dt)
		acc = acc + dt
		if acc < 0.25 then return end
		acc = 0
		if RPUI._bb ~= b or System._sessionAlive == false then RPUI.bbClose() return end
		local me = game:GetService("Players").LocalPlayer
		local a, c = RP._rootPos(me and me.Character), RP._rootPos(char.Parent and char or nil)
		local d = a and c and RPUI.flatDist(a, c) or nil
		if not RP.playerById(q.id) or RPUI.bbHide(os.clock(), b.t, d) then RPUI.bbClose() return end
		local text, btns = RPUI.bbView(RP.CH.state(q.id), RP.CH.cur ~= nil, q.name)
		line.Text = text
		local sig = #btns > 0 and btns[1][1] or ""
		if sig == b.sig then return end
		b.sig = sig
		if b.btn then b.btn:Destroy(); b.btn = nil end
		if btns[1] then
			local bt = new("TextButton", { Position = UDim2.fromOffset(8, 28), Size = UDim2.new(1, -16, 0, 28), BackgroundColor3 = Color3.fromRGB(255, 111, 174), AutoButtonColor = true, Text = btns[1][1], Font = FONTB, TextSize = 14, TextColor3 = Color3.new(1, 1, 1), Parent = card }); corner(bt, 8)
			local what = btns[1][2]
			bt.MouseButton1Click:Connect(function() act(what) end)
			b.btn = bt
		end
		g.Size = UDim2.fromOffset(160, btns[1] and 64 or 30)
	end)
end
function RPUI.bbTap(pos)
	local RP = System and System.RP
	if not (RP and RP.partners and RP.CH) then return end
	local cam = workspace.CurrentCamera
	local me = game:GetService("Players").LocalPlayer
	if not cam then return end
	local ray = cam:ScreenPointToRay(pos.X, pos.Y)
	local params = RaycastParams.new()
	params.FilterType = Enum.RaycastFilterType.Exclude

	local skip, q, char = { me and me.Character }, nil, nil
	for _ = 1, 5 do
		params.FilterDescendantsInstances = skip
		local hit = workspace:Raycast(ray.Origin, ray.Direction * 300, params)
		if not hit then break end
		local m
		q, m = RPUI.bbPlayerAt(hit.Instance)
		if q then char = m break end
		if not m then break end
		skip[#skip + 1] = m
	end
	if not q then return end
	if RPUI._bb and RPUI._bb.q.id == q.id then RPUI.bbClose() return end
	local a, c = RP._rootPos(me and me.Character), RP._rootPos(char)
	local d = a and c and RPUI.flatDist(a, c) or nil
	if RPUI.tooFar(d) then toast("Roleplay", q.name .. " is too far (" .. math.floor(d) .. " studs). Walk closer to challenge.", "info") return end
	RPUI.bbShow(q, char)
end
if System and System.RP and game and not RPUI._bbConns then
	local UIS = game:GetService("UserInputService")
	RPUI._bbConns = {
