			if System._sessionAlive == false then RPUI.bbClose() return end
			if gp or i.UserInputType ~= Enum.UserInputType.MouseButton1 or RPUI._ringGui then return end
			pcall(RPUI.bbTap, i.Position)
		end),
		UIS.TouchTapInWorld:Connect(function(p, gp)
			if System._sessionAlive == false then RPUI.bbClose() return end
			if gp or RPUI._ringGui then return end
			pcall(RPUI.bbTap, p)
		end),
	}
	if System.GlobalMaid then for _, c in ipairs(RPUI._bbConns) do pcall(function() System.GlobalMaid:Give(c) end) end end
end



