function PAGES.roleplay(h, sticky)



	if h and h.Parent == nil then return end
	local RP = System and System.RP
	local box = new("Frame", { Name = "Roleplay", BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 1, Parent = h }); vlist(box, 10)
	local render
	local function me() return LocalPlayer and LocalPlayer.Character end
	local function cloneName(k) return System._cloneDisplayName and System._cloneDisplayName(k) or nil end
	local function cloneListed(k) return not System.CloneOrder or table.find(System.CloneOrder, k) ~= nil end
	local function hrpOf(m) return typeof(m) == "Instance" and m.Parent and (m:FindFirstChild("HumanoidRootPart") or m.PrimaryPart) or nil end
	local function modelOf(q)
		if not q then return nil end
		if q.kind == "clone" then return q.model end
		local pl = RP.playerById and RP.playerById(q.id)
		return pl and pl.Character or nil
	end

	local function distModel(m, centre)
		local a, b = hrpOf(centre or (RPUI.performer and RPUI.performer.model) or me()), hrpOf(m)
		return a and b and RPUI.flatDist(a.Position, b.Position) or nil
	end
	local function farToast(q, centre)
		local d = q and distModel(modelOf(q), centre)
		if not RPUI.tooFar(d) then return false end
		toast("Roleplay", (q.name or "Partner") .. " is too far (" .. math.floor(d) .. " studs). Bring them inside the ring.", "warn")
		if RPUI._flash then pcall(RPUI._flash, 4) end
		return true
	end




	function RPUI._fresh(p)
		if not p or p.kind ~= "clone" then return p end
		local m = System.NPCs and System.NPCs[p.id]
		if typeof(m) ~= "Instance" or not m.Parent then return nil end
		p.model, p.name = m, cloneName(p.id) or m.Name
		return p
	end
	function RPUI._freshPartner() RPUI.partner = RPUI._fresh(RPUI.partner) return RPUI.partner end
	local function performer()
		RPUI.performer = RPUI._fresh(RPUI.performer)
		return RPUI.performer
	end
	RPUI._farToast = farToast

	function RPUI.equipPair()
		if RPUI.swap == nil then return end
		local perf = performer()
		pcall(RPUI.equipDefault, RPUI.swap, perf)
		local p = RPUI._freshPartner()
		if p and p.kind == "clone" and p.model and p.model.Parent and not (perf and perf.id == p.id) then
			pcall(RPUI.equipDefault, not RPUI.swap, p)
		end
	end

	function RPUI.needSide()
		local perf = performer()
		local shown = perf == nil or (RPUI.partner ~= nil and RPUI.partner.kind == "clone")
		if shown and RPUI.swap == nil then toast("Roleplay", "Pick Male or Female first (Plays as).", "info") return true end
		return false
	end




	local QU = { pluses = {} }
	function QU.partner(peek)


		if RPUI._freshPartner() then return RPUI.partner end
		local cur = RP.session and RP.session()
		if cur and cur.partner then return cur.partner end


		local auto = RPUI.autoPartner(System.NPCs, cloneName, cloneListed, function(m) return distModel(m, me()) end)
		if auto and not peek then RPUI.partner = auto; pcall(RPUI.equipPair) end
		return auto
	end
	if RP and RP.Q then RP.Q.partner = QU.partner end
	function QU.lockedToast(holder) toast("Roleplay", RP.Q.nameOf(holder) .. " is editing the queue", "info") end

	function QU.act(fn, ...)
		if RPUI.lockToast() then return false end
		local ok, err = fn(...)
		if ok then return true end
		if err == "locked" then local _, h = RP.Q.canEdit(); QU.lockedToast(h)
		elseif err == "not playing" then toast("Roleplay", "Nothing from the queue is playing yet.", "info")
		elseif err then toast("Roleplay", "Queue: " .. tostring(err), "warn") end
		return false
	end
	function QU.put(clip, insert, opts)
		local Q = RP.Q
		local ok, err, pos = (insert and Q.insertNext or Q.add)(clip.key, opts)
		if ok then toast("Roleplay", "Added " .. tostring(clip.name) .. ", #" .. tostring(pos), "info")
		else QU.act(function() return false, err end) end
	end



	function QU.who(card, onAdd, pick0)
		local old = card:FindFirstChild("RPWho"); if old then old:Destroy() end
		local st = { key = card:GetAttribute("rpKey"), onAdd = onAdd, pick = pick0 or "me" }
		QU.whoOpen = st
		local f = new("TextButton", { Name = "RPWho", AutoButtonColor = false, Text = "", BackgroundColor3 = T.bg, BackgroundTransparency = 0.04, Size = UDim2.fromScale(1, 1), ZIndex = card.ZIndex + 5, Parent = card }); corner(f, 10)
		local z = f.ZIndex + 1
		lbl({ Position = UDim2.fromOffset(8, 6), Size = UDim2.new(1, -16, 0, 16), Text = "Who plays?", Font = FONTB, TextSize = 12, TextXAlignment = Enum.TextXAlignment.Left, ZIndex = z, Parent = f })
		local pick, btns = st.pick, {}
		local function paint() st.pick = pick; for _, b in ipairs(btns) do b.BackgroundColor3 = (b:GetAttribute("rpWho") == pick) and T.accentD or T.card end end
		for i, o in ipairs({ { "me", "Me" }, { "partner", "Partner" }, { "both", "Both" } }) do
			local b = new("TextButton", { AutoButtonColor = false, Text = o[2], Font = FONTB, TextSize = 11, TextColor3 = T.txt, Position = UDim2.new((i - 1) / 3, 3, 0, 28), Size = UDim2.new(1 / 3, -6, 0, 30), ZIndex = z, Parent = f }); corner(b, 8)
			b:SetAttribute("rpWho", o[1]); btns[i] = b
			b.MouseButton1Click:Connect(function() pick = o[1]; paint() end)
		end
		paint()
		local add = new("TextButton", { AutoButtonColor = false, Text = "Add", Font = FONTB, TextSize = 12, TextColor3 = T.txt, BackgroundColor3 = T.accentD, Position = UDim2.new(0, 3, 0, 66), Size = UDim2.new(0.5, -5, 0, 30), ZIndex = z, Parent = f }); corner(add, 8)
		local no = new("TextButton", { AutoButtonColor = false, Text = "Cancel", Font = FONTB, TextSize = 12, TextColor3 = T.txt2, BackgroundColor3 = T.card, Position = UDim2.new(0.5, 2, 0, 66), Size = UDim2.new(0.5, -5, 0, 30), ZIndex = z, Parent = f }); corner(no, 8)
		local function close() if QU.whoOpen == st then QU.whoOpen = nil end; f:Destroy() end
		add.MouseButton1Click:Connect(function() close(); onAdd(pick) end)
		no.MouseButton1Click:Connect(close)
	end

	function QU.add(clip, insert, card)
		local Q = RP and RP.Q
		if not Q or RPUI.lockToast() then return end
		local okE, holder = Q.canEdit()
		if not okE then QU.lockedToast(holder) return end
		if RPUI.needSide() then return end

		if clip.kind == "pair" then QU.put(clip, insert, { s = (RPUI.swap and not performer()) and "b" or "a" }) return end
		if not QU.partner(true) or not card then QU.put(clip, insert, { w = "me" }) return end
		QU.who(card, function(w) QU.put(clip, insert, { w = w }) end)
	end

	function QU.paintPlus()
		local off = RP.Q and not RP.Q.canEdit()
		for _, b in ipairs(QU.pluses) do
			if b.Parent then b.BackgroundTransparency = off and 0.6 or 0; b.TextTransparency = off and 0.5 or 0 end
		end
	end
	function QU.sig()
		local Q = RP.Q
		local _, h = Q.canEdit()
		return table.concat({ tostring(Q.q.v), tostring(Q.q.ni), tostring(Q.q.n), tostring(Q.q.sk), tostring(h), tostring(Q.mine()), tostring(#Q.q.e) }, "|")
	end
	QU.MAX_ROWS = 100

	function QU.tile(parent, order)
		local Q = RP and RP.Q
		if not Q then return end
		local qt = tile(parent, "Queue", order)
		local body = new("Frame", { Name = "RPQueue", BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 1, Parent = qt }); vlist(body, 4)
		local open, live, lastSig, clearArm = {}, {}, nil, 0
		local draw
		local function locked() local ok, h = Q.canEdit() if not ok then QU.lockedToast(h) end return not ok end


		local function durPicker(holder, value, onPick)
			local tok = 0
			UI.slider(holder, "Seconds", math.floor((tonumber(value) or Q.DEF_D) + 0.5), Q.MIN_D, Q.MAX_D, 1, function(v)
				QU.dragAt = os.clock()
				tok += 1
				local mine = tok
				task.delay(0.5, function() if mine == tok then onPick(v) end end)
			end, nil, true)
		end
		local function sub(orderN)
			local f = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = orderN, Parent = body }); vlist(f, 4)
			return f
		end
		draw = function()
			if not body.Parent then return end
			for _, ch in ipairs(body:GetChildren()) do if ch:IsA("GuiObject") then ch:Destroy() end end
			live = {}
			lastSig = QU.sig()
			local q = Q.q
			if #q.e == 0 then UI.hint(body, "Tap + on an animation to queue it", 1) return end
			local canE, holder = Q.canEdit()

			if not canE then UI.hint(body, Q.nameOf(holder) .. " is editing the queue", 2)
			else UI.hint(body, #q.e .. " queued, loops. Tap one for options.", 2) end
			local lp = RP.localPlayer and RP.localPlayer()
			local myId = lp and lp.UserId or 0
			for i, e in ipairs(q.e) do
				if i > QU.MAX_ROWS then UI.hint(body, "and " .. (#q.e - QU.MAX_ROWS) .. " more", 10 + i * 3) break end
				local isNow = q.ni == e.id
				local c = RP.clipByKey and RP.clipByKey(e.k)
				local name = RPUI.rowLabel(c and c.name or e.k, e.w and Q.bodies(e, myId) or nil)


				local row = new("TextButton", { AutoButtonColor = false, Text = "", Size = UDim2.new(1, 0, 0, isNow and 56 or 32), BackgroundColor3 = (isNow or open[e.id] == "menu") and T.cardHi or T.card, LayoutOrder = 10 + i * 3, Parent = body }); corner(row, 8)
				local nb = lbl({ Position = UDim2.fromOffset(10, 0), Size = UDim2.new(1, -80, 0, 32), Text = (isNow and "> " or (i .. ". ")) .. name, Font = isNow and FONTB or FONT, TextSize = 13, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd, TextColor3 = isNow and T.txt or T.txt2, Parent = row })
				local chip = new("TextButton", { AutoButtonColor = false, AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -8, 0, 4), Size = UDim2.fromOffset(54, 24), Text = RPUI.fmtDur(e.d), Font = FONTB, TextSize = 12, TextColor3 = T.accent, BackgroundColor3 = T.bg, Parent = row }); corner(chip, 12)
				if not canE then for _, b in ipairs({ nb, chip }) do b.TextTransparency = 0.5 end end
				row.MouseButton1Click:Connect(function() if locked() then return end open[e.id] = open[e.id] ~= "menu" and "menu" or nil; draw() end)
				chip.MouseButton1Click:Connect(function() if locked() then return end open[e.id] = open[e.id] ~= "dur" and "dur" or nil; draw() end)
				if isNow then
					local bar = new("Frame", { Position = UDim2.fromOffset(8, 33), Size = UDim2.new(1, -16, 0, 4), BackgroundColor3 = T.bg, BorderSizePixel = 0, Parent = row }); corner(bar, 2)
					live.fill = new("Frame", { Size = UDim2.fromScale(0, 1), BackgroundColor3 = T.accent, BorderSizePixel = 0, Parent = bar }); corner(live.fill, 2)
					live.line = lbl({ Position = UDim2.fromOffset(8, 39), Size = UDim2.new(1, -16, 0, 14), Text = "", TextSize = 11, TextColor3 = T.txt3, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd, Parent = row })
				end
				if open[e.id] == "menu" then
					local m = sub(11 + i * 3)
					local r1, r2 = cols(m, 1, 2, 4), cols(m, 2, 2, 4)
					UI.button(r1[1], isNow and "Restart" or "Play from here", "primary", 1, function() open[e.id] = nil; QU.act(Q.startFrom, e.id) end, 30)
					UI.button(r1[2], "Remove", nil, 1, function() open[e.id] = nil; QU.act(Q.remove, e.id) end, 30)
					UI.button(r2[1], "Move up", nil, 1, function() QU.act(Q.move, e.id, -1) end, 30)
					UI.button(r2[2], "Move down", nil, 1, function() QU.act(Q.move, e.id, 1) end, 30)
				elseif open[e.id] == "dur" then
					durPicker(sub(11 + i * 3), e.d, function(s) if not locked() then QU.act(Q.setDuration, e.id, s) end end)
				end
			end
			local mine = Q.mine()

			local ft = cols(body, 100000, mine and 3 or 2, 4)
			UI.button(ft[1], q.sk and "Skipping" or "Skip", nil, 1, function() if locked() then return end QU.act(Q.skip) end, 32)
			UI.button(ft[2], os.clock() < clearArm and "Sure?" or "Clear", nil, 1, function()
				if locked() then return end
				if os.clock() < clearArm then clearArm = 0; QU.act(Q.clear) else clearArm = os.clock() + 3; draw() end
			end, 32)
			if mine then UI.button(ft[3], "Done", "primary", 1, function() Q.done() end, 32) end
		end


		local drawTok = 0
		Q.changed = function()
			if not body.Parent then return end
			drawTok += 1
			local mine = drawTok
			local function go()
				if mine ~= drawTok or not body.Parent then return end
				local left = 0.8 - (os.clock() - (QU.dragAt or -1e9))
				if left > 0 then task.delay(left, go) return end
				pcall(draw)
			end
			go()
		end
		draw()
		task.spawn(function()
			while body.Parent do
				task.wait(0.25)
				if not body.Parent then break end
				if QU.sig() ~= lastSig or (clearArm > 0 and os.clock() > clearArm) then
					if clearArm > 0 and os.clock() > clearArm then clearArm = 0 end
					pcall(draw)
				elseif live.fill and live.fill.Parent then
					local i = Q.nowInfo()
					if i then
						live.fill.Size = UDim2.fromScale(i.waiting and 0 or math.clamp(i.elapsed / math.max(1e-3, i.total), 0, 1), 1)
						live.line.Text = RPUI.nowLine(i)
					end
				end
				pcall(QU.paintPlus)
			end
		end)
	end

	local function start(clip, card)

		if RPUI.lockToast() then return end

		if RP.Q and RP.Q.running() then QU.add(clip, true, card) return end
		if RPUI.needSide() then return end
		if _KR and _KR.count then _KR.count(clip.kind == "pair" and "act:rp_pair" or "act:rp_solo") end
		RPUI._freshPartner()
		local perf = performer()
		if perf then
			local what, key, x = RPUI.cloneStartArgs(clip, perf, RPUI.partner, RPUI.swap)
			if what == "need_partner" then

				local auto = RPUI.autoPartner(System.NPCs, cloneName, function(k) return k ~= perf.id and cloneListed(k) end,
					function(m) return distModel(m, perf.model) end)
				if not auto then auto = RPUI.spawnPartner(System.spawnClone, System.NPCs, cloneName) end
				if not auto then toast("Roleplay", "Couldn't make a clone partner.", "warn") return end
				RPUI.partner = auto
				toast("Roleplay", "Partner: " .. auto.name, "info")
				if RPUI._flash then pcall(RPUI._flash, 3) end


				if RPUI.swap == nil then RPUI.swap = false end
				pcall(RPUI.equipPair)
				what, key, x = RPUI.cloneStartArgs(clip, perf, RPUI.partner, RPUI.swap)
			end
			if x and x.partner and farToast(RPUI.partner, perf.model) then return end
			if RP.stopSession then RP.stopSession() end
			local ok, err = RP.play(key, x)
			if not ok then toast("Roleplay", "Couldn't play: " .. tostring(err), "warn") end
			return
		end

		local cur = RP.session and RP.session()
		if not RPUI.partner and cur and cur.partner and cur.partner.kind == "player" then RPUI.partner = cur.partner end
		local what, key, x, y = RPUI.startArgs(clip, RPUI.partner, RPUI.swap, me())

		if what == "need_partner" then

			local auto = RPUI.autoPartner(System.NPCs, cloneName, cloneListed, function(m) return distModel(m, me()) end)
			if not auto then auto = RPUI.spawnPartner(System.spawnClone, System.NPCs, cloneName) end
			if not auto then toast("Roleplay", "Couldn't make a clone partner.", "warn") return end
			RPUI.partner = auto
			RPUI.equipPair()
			toast("Roleplay", "Partner: " .. auto.name, "info")
			if RPUI._flash then pcall(RPUI._flash, 3) end
			render()
			what, key, x, y = RPUI.startArgs(clip, RPUI.partner, RPUI.swap, me())
		end

		if clip.kind == "pair" then
			local q = (what == "pick") and y or RPUI.partner
			local same = cur and cur.partner and q and cur.partner.kind == q.kind and cur.partner.id == q.id
			if not same and farToast(q, me()) then return end
		end


		if what == "pick" and y and y.kind == "player" and RP.challenge and RP.CH then
			if RP.CH.state(y.id).role == nil then
				local okC, errC = RP.challenge(y, key, x)
				toast("Roleplay", okC and ("Challenge sent to " .. (y.name or "them")) or ("Couldn't challenge: " .. tostring(errC)), okC and "info" or "warn")
				return
			end
		end
		local ok, err
		if what == "pick" then ok, err = RP.pick(y, key, x)
		elseif x.partner and RP.pick then ok, err = RP.pick(RPUI.partner, key, x.side)
		else if RP.stopSession then RP.stopSession() end; ok, err = RP.play(key, x) end
		if not ok then toast("Roleplay", "Couldn't play: " .. tostring(err), "warn") end
	end

	local listFrame, gridConn, cards = nil, nil, {}
	local renderListBody
	local function freeCards()
		if gridConn then gridConn:Disconnect(); gridConn = nil end
		for _, cd in ipairs(cards) do pcall(cd.st.free) end
		cards = {}
	end




	local function keepScroll(from)
		local sc = from and from:FindFirstAncestorWhichIsA("ScrollingFrame")
		if not sc then return function() end end
		local want = sc.CanvasPosition
		return function()
			if want.Y <= 0 or not sc.Parent then return end
			sc.CanvasPosition = want
			task.spawn(function()
				local RS = game:GetService("RunService")
				for _ = 1, 10 do
					RS.Heartbeat:Wait()
					if not sc.Parent then return end
					local y = sc.CanvasPosition.Y
					local maxY = math.max(0, sc.AbsoluteCanvasSize.Y - sc.AbsoluteWindowSize.Y)
					if math.abs(y - want.Y) < 0.5 then
						if maxY >= want.Y - 0.5 then return end
					elseif y < want.Y and y >= maxY - 0.5 then
						sc.CanvasPosition = want
					else
						return
					end
				end
			end)
		end
	end

	local function renderList()
		local restore = keepScroll(listFrame and listFrame.Parent and listFrame)
		renderListBody()
		restore()
	end
	renderListBody = function()
		freeCards()
		QU.pluses = {}
		local w0 = QU.whoOpen; QU.whoOpen = nil
		if not (listFrame and listFrame.Parent) then return end
		for _, c in ipairs(listFrame:GetChildren()) do if not c:IsA("UIGridLayout") then c:Destroy() end end
		local playing = RP.playing and RP.playing()
		local rows = RPUI.filter(RP.clips, RPUI.tab, RPUI.query)
		if #rows == 0 then UI.hint(listFrame, "Nothing matches.", 1) end
		for i, c in ipairs(rows) do
			local on = playing and playing.key == c.key
			local card = new("TextButton", { BackgroundColor3 = on and T.cardHi or T.card, AutoButtonColor = false, Text = "", LayoutOrder = i, Parent = listFrame }); corner(card, 10)
			local vp = new("ViewportFrame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 1, -40), Ambient = Color3.fromRGB(140, 140, 150), LightDirection = Vector3.new(-0.6, -0.8, 0.9), Parent = card })
			lbl({ Position = UDim2.new(0, 8, 1, -38), Size = UDim2.new(1, -16, 0, 18), Text = c.name, Font = FONTB, TextSize = 12, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd, TextColor3 = on and T.txt or T.txt2, Parent = card })
			lbl({ Position = UDim2.new(0, 8, 1, -20), Size = UDim2.new(1, -16, 0, 14), Text = on and "playing" or RPUI.meta(c), TextSize = 11, TextXAlignment = Enum.TextXAlignment.Left, TextColor3 = on and T.accent or T.txt3, Parent = card })
			card.MouseButton1Click:Connect(function() start(c, card) end)
			if RP.Q then
				local plus = new("TextButton", { Name = "RPQueueAdd", AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -6, 0, 6), Size = UDim2.fromOffset(26, 26), Text = "+", Font = FONTB, TextSize = 18, TextColor3 = T.txt, BackgroundColor3 = T.accentD, AutoButtonColor = false, ZIndex = card.ZIndex + 2, Parent = card }); corner(plus, 13)
				plus.MouseButton1Click:Connect(function() QU.add(c, false, card) end)
				QU.pluses[#QU.pluses + 1] = plus
			end
			card:SetAttribute("rpKey", c.key)
			cards[#cards + 1] = { frame = card, st = cardPreview(RP, c, vp) }
			if w0 and w0.key == c.key then pcall(QU.who, card, w0.onAdd, w0.pick) end
		end
		local scroller = listFrame:FindFirstAncestorWhichIsA("ScrollingFrame")
		local acc = 0
		gridConn = game:GetService("RunService").RenderStepped:Connect(function(dt)
			if not listFrame.Parent then freeCards() return end
			acc += dt
			if acc < 1 / 30 then return end
			acc = 0
			local live = shown(listFrame)
			local vTop = scroller and scroller.AbsolutePosition.Y or 0
			local vH = scroller and scroller.AbsoluteSize.Y or 1e6
			local now, built = os.clock(), 0
			for _, cd in ipairs(cards) do
				local f = cd.frame
				if live and RPUI.onScreen(f.AbsolutePosition.Y, f.AbsoluteSize.Y, vTop, vH) then
					if not cd.st.figA and built < 2 then cd.st.build(); built += 1 end
					if cd.st.figA then cd.st.step(now) end
				elseif cd.st.figA then
					cd.st.free()
				end
			end
		end)
	end

	local renderBody
	render = function()
		if not box.Parent then return end
		local restore = RPUI._scrollTop and function() end or keepScroll(box)
		RPUI._scrollTop = nil
		renderBody()
		restore()
	end
	renderBody = function()
		if not box.Parent then return end
		for _, c in ipairs(box:GetChildren()) do if not c:IsA("UIListLayout") then c:Destroy() end end
		local v = RPUI.view(RP)
		if v == "missing" then UI.hint(tile(box, "Roleplay", 1), "Roleplay is not available in this build.", 1) return end
		if v ~= "ready" then
			local tl = tile(box, "Animations", 1)
			if v == "failed" then
				UI.hint(tl, "Couldn't load animations: " .. tostring(RP.packState.err), 1)
				UI.button(tl, "Retry", "primary", 2, function() RP.packState.state = "idle"; render() end)
				return
			end
			local hint = UI.hint(tl, "Loading animations...", 1)
			if RP.packState.state == "idle" then
				task.spawn(function()
					RP.loadPacks(function(d, t) local l = hint:FindFirstChildWhichIsA("TextLabel"); if l and l.Parent then l.Text = string.format("Loading animations... %d/%d", d, t) end end)
					if RP.changed then RP.changed() end
				end)
			end


			task.spawn(function()
				while hint.Parent and RP.packState.state == "loading" do task.wait(1) end
				if hint.Parent and box.Parent then render() end
			end)
			return
		end

		local ctl
		if sticky then
			local old = sticky:FindFirstChild("RPControls"); if old then old:Destroy() end
			ctl = new("Frame", { Name = "RPControls", BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, Parent = sticky }); pad(ctl, 14, 10, 4, 8); vlist(ctl, 6)
		else
			ctl = tile(box, "Roleplay", 1)
		end
		UI.seg(ctl, { "Roleplay", "Emotes" }, 1, function(o, i)
			RPUI.tab = RPUI.segTab(o, i)
			RPUI._scrollTop = true
			local sc = box:FindFirstAncestorWhichIsA("ScrollingFrame")
			render()
			if sc then sc.CanvasPosition = Vector2.zero end
		end, RPUI.tab == "emotes" and 2 or 1)
		do
			local rs = cols(ctl, 2, 2)
			local _, sb = UI.field(rs[1], "Search", RPUI.query, 1, true, nil, "Search animations...")
			if sb then sb:GetPropertyChangedSignal("Text"):Connect(function() RPUI.query = sb.Text; renderList() end) end
			UI.button(rs[2], "Stop", "primary", 1, function() if RPUI.lockToast() then return end; if RP.Q then RP.Q.halt() end; if RP.stopSession then RP.stopSession() elseif RP.stop then RP.stop() end end)
		end

		local function buildControls(parent, baseOrder)

		local st = tile(parent, "Play", baseOrder + 1)
		local wlist = new("Frame", { Name = "RPPerformers", BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 0, Parent = st }); vlist(wlist, 4)



		local sideBox = new("Frame", { Name = "RPSide", BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 1, Parent = st }); vlist(sideBox, 0)
		local sideArgs = nil
		local function drawSide(perf, partner)
			sideArgs = { perf, partner, RPUI.swap }


			if RPUI.swap == nil and not perf then
				local s = RPUI.sideFromSession(RP and RP.playing and RP.playing(), me())
				if s ~= nil then RPUI.swap = s end
			end
			for _, c in ipairs(sideBox:GetChildren()) do if c:IsA("GuiObject") then c:Destroy() end end
			local cloneOnClone = perf ~= nil and partner ~= nil and partner.kind == "clone"
			sideBox.Visible = perf == nil or cloneOnClone
			if not sideBox.Visible then return end
			local cap = perf and ((perf.name or "Clone") .. " plays as") or "You play as"
			if RPUI.swap == nil then cap = cap .. " (pick one to play)" end
			UI.seg(sideBox, { "Male", "Female" }, 1, function(_, i)

				if RPUI.lockToast() then task.defer(drawSide, perf, partner) return end
				local first = RPUI.swap == nil
				RPUI.swap = (i == 2)
				local pq = RPUI.partner
				if pq and pq.kind == "player" and RP.CH and RP.CH.touch then RP.CH.touch(pq.id) end
				RPUI.equipPair()
				if first then drawSide(perf, partner) end
			end, RPUI.swap == nil and 0 or (RPUI.swap and 2 or 1), nil, nil, cap)
		end
		if RP and RP.onChanged then
			local offSide = RP.onChanged(function()
				if sideArgs and sideBox.Parent and (RPUI.swap == nil or RPUI.swap ~= sideArgs[3]) then drawSide(sideArgs[1], sideArgs[2]) end
			end)
			sideBox.Destroying:Connect(offSide)
		end



		QU.tile(parent, baseOrder + 2)
		local pt = tile(parent, "Partner", baseOrder + 3)
		if not (System.getAvatarSync and System.getAvatarSync()) then UI.hint(pt, "Turn on Avatar Sync (Settings) to see other Himeros players here.", 0) end
		local plist = new("Frame", { Name = "RPPartners", BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 1, Parent = pt }); vlist(plist, 4)
		RPUI.chBox = new("Frame", { Name = "RPChallenge", BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 2, Parent = pt }); vlist(RPUI.chBox, 4)
		local function same(a, b) return (a == nil and b == nil) or (a ~= nil and b ~= nil and a.kind == b.kind and a.id == b.id) end
		local tags = {}
		local function rows(frame, opts, cur, pick, withRange)
			for _, c in ipairs(frame:GetChildren()) do if c:IsA("GuiObject") then c:Destroy() end end
			if withRange then tags = {} end
			for i, o in ipairs(opts) do
				local q = o.partner
				local on = same(q, cur)
				local row = new("TextButton", { Size = UDim2.new(1, 0, 0, 30), LayoutOrder = i, BackgroundColor3 = on and T.cardHi or T.card, AutoButtonColor = false, Text = "", Parent = frame }); corner(row, 8)
				lbl({ Position = UDim2.fromOffset(10, 0), Size = UDim2.new(1, -100, 1, 0), Text = o.label, Font = on and FONTB or nil, TextSize = 13, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd, TextColor3 = on and T.txt or T.txt2, Parent = row })
				local tg = lbl({ AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -10, 0, 0), Size = UDim2.new(0, 84, 1, 0), Text = on and "on" or (q and q.kind == "player" and "player" or ""), TextSize = 11, TextXAlignment = Enum.TextXAlignment.Right, TextColor3 = on and T.accent or T.txt3, Parent = row })
				if withRange and q then tags[#tags + 1] = { label = tg, q = q, on = on } end
				row.MouseButton1Click:Connect(function() pick(q) end)
			end
		end
		local lastSig
		local drawLists
		drawLists = function(force)
			local perf = performer()
			RPUI._freshPartner()
			if perf and RPUI.partner and (RPUI.partner.kind ~= "clone" or RPUI.partner.id == perf.id) then RPUI.partner = nil end
			local wopts = RPUI.performerOptions(System.NPCs, cloneName, cloneListed)

			local popts = RPUI.partnerOptions(System.NPCs, perf and {} or (RP.partners and RP.partners() or {}), cloneName,
				function(k) return cloneListed(k) and not (perf and k == perf.id) end)
			local key = function(x) return x and (x.kind .. tostring(x.id)) or "-" end
			local sig = RPUI.partnerSig(wopts) .. "#" .. RPUI.partnerSig(popts) .. "#" .. key(perf) .. key(RPUI.partner)
			if sig == lastSig and not force then return end
			lastSig = sig
			drawSide(perf, RPUI.partner)
			rows(wlist, wopts, perf, function(q) RPUI.performer = q; if q then RPUI.equipPair() end; drawLists(true); if RPUI._flash then pcall(RPUI._flash, 3) end end)
			rows(plist, popts, RPUI.partner, function(q)
				RPUI.partner = q; if q and q.kind == "clone" then RPUI.equipPair() end; drawLists(true); if RPUI._flash then pcall(RPUI._flash, 3) end
			end, true)
			pcall(RPUI.drawCh, RPUI.chBox)
		end





		local marks = { a = 0, target = 0, showTill = 0 }
		local BASE = { ring = 0.25, halo = 0.1, perf = 0.2, bg = 0.25 }
		local function alpha(a)
			marks.a = a
			local function tr(b) return b + (1 - b) * (1 - a) end
			marks.ring.Transparency, marks.halo.Transparency, marks.perf.Transparency = tr(BASE.ring), tr(BASE.halo), tr(BASE.perf)
			marks.text.BackgroundTransparency, marks.text.TextTransparency = tr(BASE.bg), tr(0)
			marks.tag.Enabled = a > 0 and marks.tag.Adornee ~= nil
		end
		local function fade()
			if marks.conn or marks.a == marks.target then return end
			marks.conn = game:GetService("RunService").Heartbeat:Connect(function(dt)
				if not (marks.folder and marks.folder.Parent) then marks.conn:Disconnect(); marks.conn = nil return end
				local a = marks.a + (marks.target > marks.a and 1 or -1) * dt / 0.3
				if (marks.target - a) * (marks.target - marks.a) <= 0 then a = marks.target end
				alpha(a)
				if a == marks.target then marks.conn:Disconnect(); marks.conn = nil end
			end)
		end
		local function adorn(r, inner, color, tr)
			local a = Instance.new("CylinderHandleAdornment")
			a.Radius, a.InnerRadius, a.Height, a.Color3, a.Transparency = r, inner, 0.12, color, tr
			a.AlwaysOnTop, a.ZIndex = false, 1
			a.Parent = marks.folder
			return a
		end
		local GREEN, RED, WHITE = Color3.fromRGB(90, 230, 140), Color3.fromRGB(255, 90, 90), Color3.fromRGB(240, 240, 245)
		local function makeMarks()
			local cam = workspace.CurrentCamera
			if not cam then return false end
			marks.folder = new("Folder", { Name = "RCRPMarks", Parent = cam })
			marks.ring = adorn(RPUI.RANGE, RPUI.RANGE - 0.35, T.accent, 0.25)
			marks.halo = adorn(2.4, 1.9, GREEN, 0.1)
			marks.perf = adorn(2.4, 1.9, WHITE, 0.2)
			marks.tag = new("BillboardGui", { Name = "RCRPTag", Size = UDim2.fromOffset(170, 24), StudsOffset = Vector3.new(0, 3.4, 0), AlwaysOnTop = true, LightInfluence = 0, ResetOnSpawn = false, Enabled = false, Parent = marks.folder })
			marks.text = lbl({ Size = UDim2.fromScale(1, 1), BackgroundTransparency = 0.25, BackgroundColor3 = Color3.fromRGB(20, 20, 26), Text = "", Font = FONTB, TextSize = 13, TextColor3 = GREEN, Parent = marks.tag }); corner(marks.text, 8)
			alpha(0)
			return true
		end

		local function dropOf(m, hrp)
			local hum = m and m:FindFirstChildOfClass("Humanoid")
			local hip = (hum and hum.RigType == Enum.HumanoidRigType.R15) and hum.HipHeight or 2
			return hip + hrp.Size.Y / 2 - 0.05
		end
		local function place(a, m)
			local hrp = hrpOf(m)
			a.Adornee = hrp
			if hrp then a.CFrame = CFrame.new(0, -dropOf(m, hrp), 0) * CFrame.Angles(math.rad(90), 0, 0) end
		end
		local function shown(g)
			local o = g
			while o do
				if o:IsA("GuiObject") and not o.Visible then return false end
				if o:IsA("LayerCollector") then return o.Enabled end
				o = o.Parent
			end
			return false
		end
		local function updateMarks()
			if not (marks.folder and marks.folder.Parent) and not makeMarks() then return end
			local vis = shown(plist)
			marks.target = (vis and os.clock() < marks.showTill) and 1 or 0
			fade()
			local perf = performer()
			local centre = perf and perf.model or me()
			place(marks.ring, vis and centre or nil)
			place(marks.perf, vis and perf and perf.model or nil)
			local q = RPUI.partner
			local pm = vis and modelOf(q) or nil
			local d = pm and distModel(pm, centre)
			local far = RPUI.tooFar(d)
			place(marks.halo, pm)
			marks.halo.Color3 = far and RED or GREEN
			marks.tag.Adornee = hrpOf(pm)
			marks.tag.Enabled = marks.a > 0 and marks.tag.Adornee ~= nil
			if pm then
				marks.text.Text = (q.name or "Partner") .. (d and ("  " .. RPUI.rangeTag(d)) or "")
				marks.text.TextColor3 = far and RED or GREEN
			end
			for _, t in ipairs(tags) do
				local td = distModel(modelOf(t.q), centre)
				local tag = RPUI.rangeTag(td)
				if tag == "" then tag = t.on and "on" or (t.q.kind == "player" and "player" or "") end
				t.label.Text = tag
				t.label.TextColor3 = RPUI.tooFar(td) and RED or (t.on and T.accent or T.txt3)
			end
		end
		RPUI._flash = function(sec)
			marks.showTill = math.max(marks.showTill, os.clock() + (sec or 3))
			updateMarks()
		end
		drawLists(true)
		pcall(updateMarks)
		task.spawn(function()
			while plist.Parent do
				task.wait(0.25)
				if plist.Parent then pcall(drawLists, false); pcall(updateMarks) end
			end
			if marks.conn then marks.conn:Disconnect(); marks.conn = nil end
			if marks.folder then pcall(function() marks.folder:Destroy() end) end
		end)

		local ct = tile(parent, "Clone", baseOrder + 4)
		UI.button(ct, "Spawn clone", nil, 1, function()
			local p = RPUI.spawnPartner(System.spawnClone, System.NPCs, cloneName)
			if not p then toast("Roleplay", "Couldn't spawn a clone.", "warn") return end
			RPUI.partner = p
			RPUI.equipPair()
			drawLists(true)
			if RPUI._flash then pcall(RPUI._flash, 3) end
		end)
		do
			local sr = UI.slider(st, "Speed %", math.floor((RP.speed or 1) * 100 + 0.5), 25, 200, 2, function(v) if RPUI.lockToast() then return end; if RP.setSpeed then RP.setSpeed(v / 100) end end, 100)

			if sr then
				local cover = new("TextButton", { Name = "RPLockCover", Size = UDim2.fromScale(1, 1), BackgroundColor3 = T.bg, BackgroundTransparency = 0.5, AutoButtonColor = false, Text = "", ZIndex = 20, Visible = RPUI.lockedBy() ~= nil, Parent = sr })
				cover.MouseButton1Down:Connect(function() RPUI.lockToast() end)
				task.spawn(function()
					while cover.Parent and System._sessionAlive ~= false do
						cover.Visible = RPUI.lockedBy() ~= nil
						task.wait(0.5)
					end
				end)
			end
		end
		end


		local root = UI.panelRootOf(box)
		local screen = root and root:FindFirstAncestorWhichIsA("LayerCollector")
		local function spot()
			if not (root and screen and root.Parent and root.Visible) then return nil end
			local rs = root:FindFirstChildOfClass("UIScale")
			local s = (rs and rs.Scale > 0) and rs.Scale or 1
			local rp = root.AbsolutePosition - screen.AbsolutePosition
			local x = RPUI.sideSpot(screen.AbsoluteSize.X, rp.X, root.AbsoluteSize.X, RPUI.sideW(screen.AbsoluteSize.X, s), 10)
			return x, rp.Y, root.AbsoluteSize.Y, s
		end
		RPUI.closeSide()


		if RPUI._inlineCs then for _, c in ipairs(RPUI._inlineCs) do pcall(function() c:Disconnect() end) end; RPUI._inlineCs = nil end
		local sx = spot()
		RPUI.sideMode = sx ~= nil
		if sx then
			local f = new("Frame", { Name = "RPSide", BackgroundColor3 = T.bg, BorderSizePixel = 0, Size = UDim2.fromOffset(math.floor(RPUI.sideW(screen.AbsoluteSize.X, 1)), 300), ZIndex = 20, Active = true, Parent = screen })
			corner(f, 14); pcall(_KR.addShadow, f)
			local us = new("UIScale", { Parent = f })
			lbl({ Position = UDim2.fromOffset(14, 10), Size = UDim2.new(1, -28, 0, 18), Text = "Roleplay controls", Font = FONTB, TextSize = 15, TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 21, Parent = f })
			local sc = new("ScrollingFrame", { BackgroundTransparency = 1, BorderSizePixel = 0, Position = UDim2.fromOffset(6, 36), Size = UDim2.new(1, -12, 1, -42), CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y, ScrollBarThickness = 3, ZIndex = 21, Parent = f })
			local layout = vlist(sc, 8) or sc:FindFirstChildOfClass("UIListLayout")
			buildControls(sc, 1)
			local side = { frame = f, conns = {}, box = box }

			local barRef
			local function cloneBar()
				if barRef and barRef.Parent then return barRef end
				barRef = nil
				for _, g in ipairs(screen.Parent and screen.Parent:GetChildren() or {}) do
					local b = g:FindFirstChild("CloneBar")
					if b and b:IsA("GuiObject") then
						barRef = b
						side.conns[#side.conns + 1] = b:GetPropertyChangedSignal("Visible"):Connect(function() task.defer(function() if RPUI._side == side then side.place() end end) end)
						break
					end
				end
				return barRef
			end
			RPUI._side = side
			local function place()
				if RPUI._side ~= side then return end
				local x, y, h, s = spot()
				if (x ~= nil) ~= RPUI.sideMode or not box.Parent then RPUI.closeSide(); if box.Parent then task.defer(render) end return end
				us.Scale = s
				local ss = screen.AbsoluteSize
				local bar = cloneBar()
				local barBottom = (bar and bar.Visible) and (bar.AbsolutePosition.Y - screen.AbsolutePosition.Y + bar.AbsoluteSize.Y) or nil
				local contentH = (layout and layout.AbsoluteContentSize.Y or 400 * s) + 48 * s
				local top, hh = RPUI.sideBox(y, h, contentH, barBottom, ss.Y)
				f.Position = UDim2.fromOffset(math.floor(x), math.floor(math.max(6, top)))
				f.Size = UDim2.fromOffset(math.floor(RPUI.sideW(ss.X, s) / s), math.floor(hh / s))
			end
			side.place = place
			place()
			for _, sig in ipairs({ root:GetPropertyChangedSignal("AbsolutePosition"), root:GetPropertyChangedSignal("AbsoluteSize"), root:GetPropertyChangedSignal("Visible"), screen:GetPropertyChangedSignal("AbsoluteSize"), box.AncestryChanged,
				layout and layout:GetPropertyChangedSignal("AbsoluteContentSize") or nil }) do
				side.conns[#side.conns + 1] = sig:Connect(place)
			end
		else
			buildControls(box, 2)


			if root and screen then
				local cs = {}
				RPUI._inlineCs = cs
				local function check()
					if not box.Parent or spot() then
						for _, c in ipairs(cs) do c:Disconnect() end
						if box.Parent then render() end
					end
				end
				cs[1] = screen:GetPropertyChangedSignal("AbsoluteSize"):Connect(check)
				cs[2] = root:GetPropertyChangedSignal("Visible"):Connect(check)
				cs[3] = root:GetPropertyChangedSignal("AbsolutePosition"):Connect(check)
				cs[4] = box.AncestryChanged:Connect(check)
			end
		end
		local lt = tile(box, RPUI.tab == "emotes" and "Emotes" or "Animations", 7)
		UI.hint(lt, RP.Q and "Tap a card to play it, + to queue it." or "Tap a card to play it.", 0)
		listFrame = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 1, Parent = lt })
		local grid = new("UIGridLayout", { CellPadding = UDim2.fromOffset(6, 6), SortOrder = Enum.SortOrder.LayoutOrder, Parent = listFrame })
		local function fit()
			local n = RPUI.columns(listFrame.AbsoluteSize.X)
			grid.CellSize = UDim2.new(1 / n, -6 * (n - 1) / n, 0, RPUI.CARD_H)
		end
		fit()
		listFrame:GetPropertyChangedSignal("AbsoluteSize"):Connect(fit)
		renderList()
	end

	if RP then RP.changed = function()
		if not box.Parent then return end

		local fb = game:GetService("UserInputService"):GetFocusedTextBox()
		if fb then
			if not RPUI._renderAfterFocus then
				RPUI._renderAfterFocus = true


				local done = false
				local function after() if done then return end done = true; RPUI._renderAfterFocus = nil; if box.Parent then render() end end
				fb.FocusLost:Once(after)
				fb.AncestryChanged:Connect(function() if not fb.Parent then after() end end)
			end
			return
		end
		render()
	end end
	box.Destroying:Connect(function() RPUI.closeSide(box) end)
	box.AncestryChanged:Connect(function() if not box.Parent then RPUI.closeSide(box) end end)
	if RP and RP.onChanged then
		local off = RP.onChanged(function() renderList() end)
		box.Destroying:Connect(function() off(); freeCards(); local c = sticky and sticky:FindFirstChild("RPControls"); if c then c:Destroy() end end)
	end
	render()
end
end)






