do
	local LP = game:GetService("Players").LocalPlayer
	local function hookChar(char)
		local hum = char:WaitForChild("Humanoid", 10)
		local animator = hum and hum:WaitForChild("Animator", 10)
		if not animator then return end
		local function isHoldPose(track)
			local animate = char:FindFirstChild("Animate")
			local tn = animate and animate:FindFirstChild("toolnone")
			local id = track.Animation and track.Animation.AnimationId
			if not (tn and id) then return false end
			for _, a in ipairs(tn:GetChildren()) do if a:IsA("Animation") and a.AnimationId == id then return true end end
			return false
		end
		_KR.foreignConns = _KR.foreignConns or {}

		local prev = _KR._gearPoseConn
		if prev then
			pcall(function() prev:Disconnect() end)
			for i, c in ipairs(_KR.foreignConns) do if c == prev then table.remove(_KR.foreignConns, i) break end end
		end
		_KR._gearPoseConn = animator.AnimationPlayed:Connect(function(track)
			if SET.gearHoldPose == true then return end
			if isHoldPose(track) then track:Stop(0) end
		end)
		table.insert(_KR.foreignConns, _KR._gearPoseConn)
	end
	if LP then
		if LP.Character then task.spawn(hookChar, LP.Character) end
		_KR.foreignConns = _KR.foreignConns or {}
		table.insert(_KR.foreignConns, LP.CharacterAdded:Connect(hookChar))
	end
end


_KR.regionDone, _KR.regionCbs = false, nil
_KR.regionFetch = function(cb)
	if _KR.regionDone then if cb then pcall(cb, _serverRegion) end; return end
	if cb then _KR.regionCbs = _KR.regionCbs or {}; table.insert(_KR.regionCbs, cb) end
	if _KR.regionBusy then return end
	_KR.regionBusy = true
	task.spawn(function()
		local res
		local req = request or http_request
		if req then local ok, out = pcall(req, { Url = "https://ipinfo.io/json", Method = "GET" }); if ok and type(out) == "table" then res = out.Body end end
		if not res then pcall(function() res = game:HttpGet("https://ipinfo.io/json") end) end
		if res then pcall(function()
			local d = game:GetService("HttpService"):JSONDecode(res)
			local parts = {}
			if d.city and d.city ~= "" then parts[#parts + 1] = d.city end
			if d.country and d.country ~= "" then parts[#parts + 1] = d.country end
			if #parts > 0 then _serverRegion = table.concat(parts, ", ") end
		end) end
		_KR.regionDone = true
		for _, f in ipairs(_KR.regionCbs or {}) do pcall(f, _serverRegion) end
		_KR.regionCbs = nil
	end)
end
