_KR.textMatch = function(text, query)
	local function norm(s) return (string.gsub(string.lower(s or ""), "[^%w]+", " ")) end
	local q = norm(query)
	if not q:find("%w") then return (query or ""):find("%S") == nil end
	local t = norm(text)
	if (t:gsub(" ", "")):find((q:gsub(" ", "")), 1, true) then return true end
	for w in q:gmatch("%S+") do if not (#w > 1 and t:find(w, 1, true) or (" " .. t .. " "):find(" " .. w .. " ", 1, true)) then return false end end
	return true
end

