	local opts = { "None" }; for _, n in ipairs(names) do opts[#opts + 1] = n end
	local function worn() for i, n in ipairs(names) do if System.hasPussyType and System.hasPussyType(i) then return n end end; return "None" end
	S[_curPage .. "\1d:Pussy"] = worn()
	local function sketch(name)
		return function(fr)
			if not (System and System.getClothPreview) then return end

			local vp = new("ViewportFrame", { BackgroundColor3 = T.bg, BackgroundTransparency = 0.35, BorderSizePixel = 0, Size = UDim2.fromScale(1, 1), Ambient = Color3.fromRGB(170, 170, 178), LightColor = Color3.fromRGB(255, 255, 255), LightDirection = Vector3.new(-0.4, -1, 0.6), ZIndex = fr.ZIndex, Parent = fr }); corner(vp, 7)
			task.spawn(function()
				local ok, m = pcall(System.getClothPreview, name)
				if not (ok and m) then return end
				if not vp.Parent then m:Destroy(); return end
				m.Parent = vp
				local lo, hi
				for _, bp in ipairs(m:GetChildren()) do
					if bp:IsA("BasePart") and not ({ Head = 1, Torso = 1, ["Left Arm"] = 1, ["Right Arm"] = 1, ["Left Leg"] = 1, ["Right Leg"] = 1 })[bp.Name] then
						local h2 = bp.Size / 2
						lo = lo and lo:Min(bp.Position - h2) or (bp.Position - h2); hi = hi and hi:Max(bp.Position + h2) or (bp.Position + h2)
					end
				end
				local centre, d
				if lo then centre = (lo + hi) / 2; local ext = hi - lo; d = math.max(ext.X, ext.Y, ext.Z, 0.2) * 1.9 + 0.3
				else local cf, size = m:GetBoundingBox(); centre = cf.Position; d = math.max(size.X, size.Y) * 1.3 + 0.5 end
				local cam = Instance.new("Camera"); cam.FieldOfView = 40
				cam.CFrame = CFrame.lookAt(centre + Vector3.new(d * 0.45, d * 0.2, -d), centre)
				cam.Parent = vp; vp.CurrentCamera = cam
			end)
		end
	end
	local function rich()
		local items = { None = { name = "None", desc = "No mesh" } }
		for _, n in ipairs(names) do items[n] = { name = n, desc = "", sketch = sketch(n) } end
		return { items = items }
	end
	return UI.dropdown(parent, "Pussy", opts, order, function(o)
		if o == worn() then return end
		if o == "None" then
			for i in ipairs(names) do if System.hasPussyType(i) then System.togglePussyType(i) end end
		else
			for i, n in ipairs(names) do if n == o then System.togglePussyType(i) end end
		end
	end, rich)
end
