_KR.physTuning = function(h, order, _gp, _sd, _wr, embed)
	local box = embed and new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = order, Parent = h }) or tile(h, "Physics Tuning", order)
	if embed then vlist(box, 7) end
	local GROUPS = { { "Breasts", "Breasts", 10, 0.207 }, { "Butt", "Butts", 10, 0.1 }, { "Cock", "Cock", 8, 0.207 } }
	local PRESETS = {
		{ "Soft", 6, 0.15, 1.4, 0, 0.3 }, { "Bouncy", 10, 0.08, 1.8, 0, 0.1 },
		{ "Firm", 20, 0.4, 0.7, 0.6, 0 }, { "Heavy", 5, 0.3, 1.2, 1.2, 0.6 },
	}
	local gi, advOpen = 1, false
	local body
	local function setF(f, v) if System and System.setPhysicsField then System.setPhysicsField(f, v) elseif System and System.setPD then System.setPD(f, v) end end
	local render
	render = function()
		if body then body:Destroy() end
		body = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 2, Parent = box }); vlist(body, 7)
		local g = GROUPS[gi]; local k = g[2]
		local r1 = cols(body, 2, 2)
		UI.slider(r1[1], "Motion Response %", _sd(k .. "Motion", 0, 3, 0, 300, 100), 0, 300, 1, _wr(k .. "Motion", 0, 3, 0, 300), 100)
		UI.slider(r1[2], "Bounce Limit (0 = off)", _sd(k .. "Bounce", 0, 3, 0, 100, 0), 0, 100, 1, _wr(k .. "Bounce", 0, 3, 0, 100), 0)
		local r2 = cols(body, 3, 2)
		UI.slider(r2[1], "Sag %", _sd(k .. "Sag", 0, 1, 0, 100, 0), 0, 100, 1, _wr(k .. "Sag", 0, 1, 0, 100), 0)
		if k == "Cock" then
			UI.slider(r2[2], "Erection Angle", _sd("CockAngle", -60, 60, -60, 60, 0), -60, 60, 1, _wr("CockAngle", -60, 60, -60, 60), 0)
		end
		local r3 = cols(body, 1, #PRESETS + 1, 6)
		for i, pr in ipairs(PRESETS) do
			UI.button(r3[i], pr[1], nil, 1, function()
				setF(k .. "Stiffness", pr[2]); setF(k .. "Damping", pr[3])
				setF(k .. "Motion", pr[4]); setF(k .. "Bounce", pr[5]); setF(k .. "Sag", pr[6])
				render()
			end)
		end
		UI.button(r3[#PRESETS + 1], "Default", "primary", 1, function()
			setF(k .. "Stiffness", g[3]); setF(k .. "Damping", g[4])
			setF(k .. "Motion", 1); setF(k .. "Bounce", 0); setF(k .. "Sag", 0)
			if k == "Cock" then setF("CockAngle", 0) end
			render()
		end)
		UI.button(cols(body, 4, 1)[1], advOpen and "Hide advanced" or "Advanced: stiffness + damping", nil, 1, function() advOpen = not advOpen; render() end)
		if advOpen then
			local r5 = cols(body, 5, 2)
			UI.slider(r5[1], k .. " Stiffness", _sd(k .. "Stiffness", 0.5, 30, 1, 30, 12), 1, 30, 1, _wr(k .. "Stiffness", 0.5, 30, 1, 30, true))
			UI.slider(r5[2], k .. " Damping", _sd(k .. "Damping", 0.01, 1.5, 1, 150, 40), 1, 150, 1, _wr(k .. "Damping", 0.01, 1.5, 1, 150, true))
		end
	end
	UI.seg(box, { "Breasts", "Butt", "Cock" }, 1, function(_, i) gi = i; render() end, 1)
	render()

	local sbh = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 3, Parent = box }); vlist(sbh, 7)
	UI.hint(sbh, "SmartBone (soft-body parts) - 100% = the model's own setting. Needs SmartBone on.", 1)
	local queued = false
	local function sbWr(f)
		return function(v)
			if System and System.setPD then System.setPD(f, v / 100) end
			if queued then return end
			queued = true
			task.delay(0.3, function() queued = false; if System and System.applySmartBoneTuning then pcall(System.applySmartBoneTuning) end end)
		end
	end
	local s1 = cols(sbh, 2, 2)
	UI.slider(s1[1], "SB Stiffness %", _sd("SBStiffness", 0, 3, 0, 300, 100), 0, 300, 1, sbWr("SBStiffness"), 100)
	UI.slider(s1[2], "SB Damping %", _sd("SBDamping", 0, 3, 0, 300, 100), 0, 300, 1, sbWr("SBDamping"), 100)
	local s2 = cols(sbh, 3, 2)
	UI.slider(s2[1], "SB Elasticity %", _sd("SBElasticity", 0, 3, 0, 300, 100), 0, 300, 1, sbWr("SBElasticity"), 100)
	UI.slider(s2[2], "SB Gravity %", _sd("SBGravity", 0, 3, 0, 300, 100), 0, 300, 1, sbWr("SBGravity"), 100)
end

function PAGES.body(h)





	local function _gp(f) return System and System.getPD and System.getPD(f) end
	local function _sd(field, lo, hi, dmin, dmax, ddefault)
		local cur = _gp(field)
		if type(cur) ~= "number" then return ddefault end
		local span = (hi - lo); if span == 0 then span = 1 end
		return math.clamp(math.floor(dmin + (cur - lo) / span * (dmax - dmin) + 0.5), dmin, dmax)
	end
	local function _wr(field, lo, hi, dmin, dmax, phys)
		return function(v)
			local span = (dmax - dmin); if span == 0 then span = 1 end
			local eng = lo + (v - dmin) / span * (hi - lo)
			if phys then if System and System.setPhysicsField then System.setPhysicsField(field, eng) end
			elseif System and System.setPD then System.setPD(field, eng) end
		end
	end





	local _BTL = (System and System.getBodyTypeLabels and System.getBodyTypeLabels()) or {}
	local _BTM = (System and System.getBodyTypeMax and System.getBodyTypeMax()) or {}
	local function _bodyDrop(parent, text, field, order, onPickType)
		local labels = _BTL[field] or {}
		local maxT = _BTM[field] or 1
		local function nameFor(v) if v == 0 then return "Type 0 (none)" end; local l = labels[v]; if l == nil or l == false then return "Type " .. tostring(v) end; return l end
		local opts, toType = {}, {}
		opts[1] = "Type 0 (none)"; toType[opts[1]] = 0
		for t = 1, maxT do
			if labels[t] ~= false then local nm = nameFor(t); opts[#opts + 1] = nm; toType[nm] = t end
		end
		local cur = (System and System.getPD and System.getPD(field)); if type(cur) ~= "number" then cur = 1 end
		S[_curPage .. "\1d:" .. text] = nameFor(cur)

		local _cSlot = System and System.Community and System.Community.slotForField(field)
		local _cRef = {}
		if _cSlot then
			opts, _cRef = System.Community.pickerOptions(_cSlot, opts)
			local sel = System.communitySelected and System.communitySelected(_cSlot)
			for lbl, r in pairs(_cRef) do if r == sel and cur == 1 then S[_curPage .. "\1d:" .. text] = lbl end end
		end


		local function _rich()
			local items = {}
			for _, nm in ipairs(opts) do
				local t = toType[nm]
				items[nm] = { name = nm:gsub("%s+%[SmartBone%]", ""), desc = _cRef[nm] and "Community" or (nm:find("SmartBone", 1, true) and "SmartBone physics" or ""),
					sketch = (t ~= nil and t ~= 0) and function(fr) UI._meshSketch(fr, field, t) end or nil }
			end
			return { items = items }
		end
		UI.dropdown(parent, text, opts, order, function(o)
			if _cRef[o] then
				if System and System.communityPick then System.communityPick(_cSlot, _cRef[o]) end
				if onPickType then onPickType(1) end
				return
			end
			if _cSlot and System and System.communitySelected and System.communitySelected(_cSlot) then System.communityPick(_cSlot, nil) end
			local n = toType[o]

			if n and System and System.fullBodyMeshPick then pcall(System.fullBodyMeshPick, field) end
			if n and System and System.setPD then System.setPD(field, n) end
			if onPickType then onPickType(n) end
		end, (System and System.getBodyTypePreview) and _rich or nil)
		return cur
	end

	local bt = tile(h, "Body Types", 1)

	local braWrap = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 1, Parent = bt }); vlist(braWrap, 7)
	local braRow
	local _curBreasts = _bodyDrop(braWrap, "Breasts", "BreastsType", 1, function(n) if braRow then UI.reveal(braRow, n == 6, true) end end)

	do
		local _bs = (System and System.getBraState and System.getBraState()) or "none"
		local _braInit = (_bs == "bra1" and "Bra 1") or (_bs == "bra2" and "Bra 2") or "None"
		braRow = UI.cyc(braWrap, "Bra", { "None", "Bra 1", "Bra 2" }, 2, function() if System and System.cycleBra then System.cycleBra() end end, _braInit)
	end
	braRow.Visible = (_curBreasts == 6)
	local bt1 = cols(bt, 2, 2); _bodyDrop(bt1[1], "Torso", "TorsoType", 1); _bodyDrop(bt1[2], "Arm", "ArmType", 1)
	local bt2 = cols(bt, 3, 2); _bodyDrop(bt2[1], "Legs", "LegsType", 1); _bodyDrop(bt2[2], "Butt", "ButtType", 1)
	do

		local names = (System and System.COCK_TYPES) or {}
		local cw = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 5, Parent = bt }); vlist(cw, 6)
		lbl({ Size = UDim2.new(1, 0, 0, 16), Text = "Cock (tap to wear, several allowed)", Font = FONTB, TextSize = 12, TextColor3 = T.txt2, TextXAlignment = Enum.TextXAlignment.Left, LayoutOrder = 1, Parent = cw })
		local gb = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 2, Parent = cw })
		new("UIGridLayout", { CellSize = UDim2.new(0.5, -3, 0, 30), CellPadding = UDim2.fromOffset(6, 6), SortOrder = Enum.SortOrder.LayoutOrder, Parent = gb })
		local btns = {}
		local function paint()
			for i, b in pairs(btns) do
				local on = System and System.hasCockType and System.hasCockType(i)
				b.BackgroundColor3 = on and T.accentD or T.card; b.TextColor3 = on and T.txt or T.txt2
			end
		end
		for i, n in ipairs(names) do
			local b = new("TextButton", { AutoButtonColor = false, Text = n, Font = FONTB, TextSize = 12, TextColor3 = T.txt2, TextTruncate = Enum.TextTruncate.AtEnd, BackgroundColor3 = T.card, BorderSizePixel = 0, LayoutOrder = i, Parent = gb })
			corner(b, 8); _KR.press(b)
			btns[i] = b
			b.MouseButton1Click:Connect(function()
				if System and System.toggleCockType then System.toggleCockType(i) end
				paint()
			end)
		end
		paint()
		UI.toggle(cw, "Cock Twitching", (System and System.getCockTwitch and System.getCockTwitch()) and true or false, 3, function(st) if System and System.setCockTwitch then System.setCockTwitch(st) end end)
	end
	_KR.pussyDrop(new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 4, Parent = bt }), 1)

	local sc = tile(h, "Scale", 2)
	local sc1 = cols(sc, 1, 2); UI.slider(sc1[1], "Breasts Scale", _sd("BreastsScale", 0.5, 2.5, 50, 250, 100), 50, 250, 1, _wr("BreastsScale", 0.5, 2.5, 50, 250)); UI.slider(sc1[2], "Butts Scale", _sd("ButtsScale", 0.5, 2.5, 50, 250, 100), 50, 250, 1, _wr("ButtsScale", 0.5, 2.5, 50, 250))
	UI.slider(sc, "Legs Scale", _sd("LegsScale", 0.5, 2.5, 50, 250, 100), 50, 250, 2, _wr("LegsScale", 0.5, 2.5, 50, 250))
	UI.slider(sc, "Cock Scale", _sd("CockScale", 0.5, 2.5, 50, 250, 100), 50, 250, 3, _wr("CockScale", 0.5, 2.5, 50, 250))

	do local cs = cols(sc, 4, 2); UI.slider(cs[1], "Cock Length", _sd("CockLength", 0.3, 3, 30, 300, 100), 30, 300, 1, _wr("CockLength", 0.3, 3, 30, 300), 100); UI.slider(cs[2], "Cock Girth", _sd("CockGirth", 0.3, 3, 30, 300, 100), 30, 300, 1, _wr("CockGirth", 0.3, 3, 30, 300), 100) end
	do local cs = cols(sc, 5, 2); UI.slider(cs[1], "Cock Head", _sd("CockHead", 0.3, 3, 30, 300, 100), 30, 300, 1, _wr("CockHead", 0.3, 3, 30, 300), 100); UI.slider(cs[2], "Balls Size", _sd("CockBalls", 0.3, 3, 30, 300, 100), 30, 300, 1, _wr("CockBalls", 0.3, 3, 30, 300), 100) end



	local fit = tile(h, "Fit & Visibility", 3)
	local ft1 = cols(fit, 1, 2); UI.toggle(ft1[1], "Accessory Size Lock", (_gp("AccessorySizeLock") and true) or false, 1, function(st) if System and System.setPD then System.setPD("AccessorySizeLock", st) end end); UI.toggle(ft1[2], "Mesh Size Lock", (_gp("MeshSizeLock") and true) or false, 1, function(st) if System and System.setPD then System.setPD("MeshSizeLock", st) end end)
	local ft2 = cols(fit, 2, 2); UI.toggle(ft2[1], "Hide Mesh Base Parts", (_gp("MeshBasePartInvisible") and true) or false, 1, function(st) if System and System.setPD then System.setPD("MeshBasePartInvisible", st) end end); UI.toggle(ft2[2], "Realtime Transparency", (_gp("RealtimeBodyTransparency") and true) or false, 1, function(st) if System and System.setPD then System.setPD("RealtimeBodyTransparency", st) end end)

	local ph = tile(h, "Physics", 4)
	local pt1 = cols(ph, 1, 2); UI.toggle(pt1[1], "Body Part Physics", (_gp("BodyPartPhysics") and true) or false, 1, function(st) if System and System.setPD then System.setPD("BodyPartPhysics", st) end end); UI.toggle(pt1[2], "SmartBone Physics", (_gp("SmartBoneEnabled") and true) or false, 1, function(st) if System and System.setPD then System.setPD("SmartBoneEnabled", st) end end)
	local pt2 = cols(ph, 2, 2); UI.toggle(pt2[1], "Physics Obey Gravity", (_gp("PhysicsObeyGravity") and true) or false, 1, function(st) if System and System.setPD then System.setPD("PhysicsObeyGravity", st) end end)
	do local _ts = _gp("tailSettings"); UI.toggle(pt2[2], "Tail Physics", (type(_ts) == "table" and _ts.tailPhysicsEnabled and true) or false, 1, function(st) if System and System.setPDNested then System.setPDNested("tailSettings", "tailPhysicsEnabled", st) end end) end
	_KR.physTuning(ph, 3, _gp, _sd, _wr, true)
	local pm1 = cols(ph, 6, 2)
