			renderGrid(false); renderEquipped()
		end)
		paintTile(t)
		return t
	end

	local function fetchPage(gen, cursor)
		_catFetching = gen
		if cursor == "" then statusLbl.Text = "Loading…"; statusLbl.Visible = true; footLbl.Text = "" else footLbl.Text = "Loading more…" end
		task.spawn(function()
			task.wait()

			local items, nxtCur, err
			if System and System.catalogLoadPage then
				items, nxtCur, err = System.catalogLoadPage(_catCatRow, _catSearch, cursor, _catFilters)
			end
			if gen ~= _catGen or not grid.Parent then return end
			_catFetching = false
			if not items then
				if cursor == "" then statusLbl.Text = "Fetch failed - try again" .. (err and (" (" .. tostring(err) .. ")") or ""); statusLbl.Visible = true
				else footLbl.Text = "Couldn't load more - scroll to retry" end
				return
			end
			_catNextCursor = nxtCur
			_catPages += 1
			local needs = {}
			for _, it in ipairs(items) do
				local key = tostring(it.itemType) .. ":" .. tostring(it.id)
				if it.id and not _catSeen[key] then
					_catSeen[key] = true
					local t = buildTile(it, #_catTiles + 1)
					_catTiles[#_catTiles + 1] = t

					if it.itemType ~= "Bundle" and ((not it.name) or it.name == ("ID " .. tostring(it.id)) or (not it.assetType)) then needs[#needs + 1] = t end
				end
			end
			statusLbl.Visible = (#_catTiles == 0)
			if #_catTiles == 0 then statusLbl.Text = "No results." end
			local more = (_catNextCursor ~= nil and _catNextCursor ~= "") and _catPages < CAT_MAX_PAGES
			footLbl.Text = more and "" or ((#_catTiles > 0) and "End of results" or "")


			task.spawn(function()
				for _, t in ipairs(needs) do
					if gen ~= _catGen or not t.cell.Parent then return end
					local d = System and System.catalogItemDetails and System.catalogItemDetails(t.item.id)
					if gen ~= _catGen then return end
					if d then
						if d.name then t.item.name = d.name; if t.nameLbl.Parent then t.nameLbl.Text = d.name end end
						if d.assetType then t.item.assetType = d.assetType end
					end
					task.wait()
				end
			end)
			task.defer(function() if loadMore then loadMore() end end)
		end)
	end
	loadMore = function()
		if not grid.Parent or _catPages == 0 or _catFetching == _catGen then return end
		if not (_catNextCursor and _catNextCursor ~= "") or _catPages >= CAT_MAX_PAGES then return end
		if (catRight.CanvasPosition.Y + catRight.AbsoluteWindowSize.Y) < (catRight.AbsoluteCanvasSize.Y - 400) then return end
		fetchPage(_catGen, _catNextCursor)
	end


	renderGrid = function(newSearch)
		if not grid or not grid.Parent then return end
		if not newSearch and _catPages > 0 then
			for _, t in ipairs(_catTiles) do if t.cell.Parent then paintTile(t) end end
			return
		end
		if not newSearch and _catFetching == _catGen then return end
		_catGen += 1
		for _, ch in ipairs(grid:GetChildren()) do if not ch:IsA("UIGridLayout") then ch:Destroy() end end
		_catTiles, _catSeen, _catPages, _catNextCursor = {}, {}, 0, nil
		fetchPage(_catGen, "")
	end


	local eqAll = new("TextButton", { AutoButtonColor = false, Text = "Remove all", Size = UDim2.new(1, 0, 0, 30), BackgroundColor3 = T.card, BorderSizePixel = 0, Font = FONTB, TextSize = 12, TextColor3 = T.bad, LayoutOrder = 1, Visible = false, Parent = eqDrawer.body }); corner(eqAll, 8)
	local eqBox = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 2, Parent = eqDrawer.body }); vlist(eqBox, 8)
	eqAll.MouseButton1Click:Connect(function()
		showModal("Remove all?", "Take off every catalog item you equipped.", {
			{ text = "Cancel" },
			{ text = "Remove all", kind = "primary", onClick = function()
				if System and System.catalogRemoveAllEquipped then System.catalogRemoveAllEquipped() end
				renderEquipped(); renderGrid(false)
			end },
		})
	end)


	renderEquipped = function()
		if not eqBox or not eqBox.Parent then return end
		local list = (System and System.getCatalogEquipped and System.getCatalogEquipped()) or {}



		local _sigT = {}
		for _, e in ipairs(list) do _sigT[#_sigT + 1] = tostring(e.id) .. "\1" .. tostring(e.kind) .. "\1" .. tostring(e.slot) .. "\1" .. tostring(e.bundleId) end
		local _sig = table.concat(_sigT, "\0")
		local eb = UI._eqBuilt
		local cards
		if eb and eb.sig == _sig and eb.box == eqBox and eb.grid and eb.grid.Parent == eqBox and #eb.cards == #list then
			cards = eb.cards
			for ci, e in ipairs(list) do cards[ci].e = e end
		else
			for _, ch in ipairs(eqBox:GetChildren()) do if not ch:IsA("UIListLayout") then ch:Destroy() end end
			local eqGrid = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 1, Parent = eqBox })
			new("UIGridLayout", { CellSize = UDim2.new(1 / 3, -6, 0, 112), CellPadding = UDim2.fromOffset(8, 8), SortOrder = Enum.SortOrder.LayoutOrder, Parent = eqGrid })
			cards = {}
			for ci, e in ipairs(list) do
				local nm0 = "ID " .. tostring(e.id)

				local _kind = tostring(e.kind or "")
				local _isBundle = string.find(string.lower(_kind), "bundle", 1, true) ~= nil
				local card = new("Frame", { BackgroundColor3 = T.card, BorderSizePixel = 0, LayoutOrder = ci, Parent = eqGrid }); corner(card, 9); stroke(card, T.lineSoft, 1)
				new("ImageLabel", { BackgroundTransparency = 1, Position = UDim2.fromOffset(6, 6), Size = UDim2.new(1, -12, 1, -38), ScaleType = Enum.ScaleType.Fit,
					Image = "rbxthumb://type=" .. (_isBundle and "BundleThumbnail" or "Asset") .. "&id=" .. tostring(e.id) .. "&w=150&h=150", Parent = card })
				local nameLbl = lbl({ AnchorPoint = Vector2.new(0, 1), Position = UDim2.new(0, 6, 1, -4), Size = UDim2.new(1, -12, 0, 28), Text = nm0, TextSize = 11, TextWrapped = true,
					TextXAlignment = Enum.TextXAlignment.Center, TextYAlignment = Enum.TextYAlignment.Top, TextTruncate = Enum.TextTruncate.AtEnd, Parent = card })
				local rm = new("TextButton", { AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -4, 0, 4), Size = UDim2.fromOffset(22, 22), BackgroundColor3 = T.bg, AutoButtonColor = false, Text = "X", Font = FONTB, TextColor3 = T.bad, TextSize = 12, Parent = card }); corner(rm, 11)
				local c = { e = e, nameLbl = nameLbl, nm0 = nm0, src = nil }
				cards[ci] = c
				rm.MouseButton1Click:Connect(function()
					local _e = c.e
					if System and System.catalogRemoveEquipped then System.catalogRemoveEquipped(_e.id, _e.slot) end
					renderEquipped(); renderGrid(false)
				end)
			end
			if #list == 0 then UI.hint(eqBox, "Nothing from the catalog.", 1) end
			UI._eqBuilt = { sig = _sig, box = eqBox, grid = eqGrid, cards = cards }
		end
		local _needs = {}
		for _, c in ipairs(cards) do
			if c.e.name then c.nameLbl.Text = tostring(c.e.name); c.src = "e"
			else
				if c.src == "e" then c.nameLbl.Text = c.nm0; c.src = nil end
				if c.src ~= "fill" then _needs[#_needs + 1] = c end
			end
		end
		local i = #list
		UI._catalogCount = i
		if UI._renderAvatarItems then UI._renderAvatarItems() elseif UI._paintWearing then UI._paintWearing() end
		eqAll.Visible = i > 1

		local _tok = {}; _equippedFillToken = _tok
		task.spawn(function()
			for _, nd in ipairs(_needs) do
				if _equippedFillToken ~= _tok then return end
				if nd.nameLbl and nd.nameLbl.Parent then
					local d = System and System.catalogItemDetails and (nd.e.kind ~= "Bundle" or nd.e.bundleId) and System.catalogItemDetails(nd.e.id, nd.e.bundleId ~= nil)
					if _equippedFillToken ~= _tok then return end
					if d and d.name and nd.nameLbl and nd.nameLbl.Parent then nd.nameLbl.Text = d.name; nd.src = "fill" end
				end
				task.wait()
			end
		end)
	end

	if System then System.renderEquipped = renderEquipped end
	paintCats()


	local _catFirstOpen = false
	local function _catFirstPaint()
		if _catFirstOpen or not browser:FindFirstAncestorWhichIsA("ScreenGui") then return end
		_catFirstOpen = true
		renderGrid(true); renderEquipped()
	end
	_catFirstPaint()
	browser:GetPropertyChangedSignal("Visible"):Connect(function()
		if browser.Visible then _catFirstPaint() end
	end)
end






local _bp = {}
local function _bpClose()
	if System then System._bundleLookWant = nil end
	if _bp.conns then for _, c in ipairs(_bp.conns) do pcall(function() c:Disconnect() end) end end
	if _bp.frame then pcall(function() _bp.frame:Destroy() end) end
	_bp = {}
end
_KR.bpClose = _bpClose
local function _bpActive(nm)
	local g = System and System.getPD
	if not g then return false end
	if g("CurrentBundle") == nm or g("CurrentPreset") == nm then return true end
	local cb = g("CurrentClothingBundles")
	return type(cb) == "table" and table.find(cb, nm) ~= nil
end
UI._bundlePreviewDialog = function(nm, active, onWear, anchor)
	if _bp.frame and _bp.name == nm then _bpClose(); return end
	_bpClose()
	local info = System and System.getBundlePreview and System.getBundlePreview(nm)
	local root = anchor and UI.panelRootOf(anchor)
	local screen = root and root:FindFirstAncestorWhichIsA("LayerCollector")
	if not (info and root and screen) then if onWear then onWear() end return end
	local KIND = { community = "Community bundle", mine = "My bundle", clothing = "Clothing bundle", preset = "Preset (body settings only)" }
	local function num(x) return tostring(math.floor(x * 100 + 0.5) / 100) end
	local facts = {}
	local function fact(s) facts[#facts + 1] = s end
	local function typeScale(label, ty, sc)
		if ty or sc then fact(label .. (ty and (" type " .. ty) or "") .. (sc and ("  x" .. num(sc)) or "")) end
	end
	typeScale("Breasts", info.breastsType, info.breastsScale)
	typeScale("Butt", info.buttType, info.buttsScale)
	typeScale("Legs", info.legsType, info.legsScale)
	if info.armType then fact("Arms type " .. info.armType) end
	if info.torsoType then fact("Torso type " .. info.torsoType) end
	if info.physics or info.smartBone then fact("Physics: " .. ((info.physics and info.smartBone) and "body + SmartBone" or (info.smartBone and "SmartBone" or "body"))) end
	if #info.clothing > 0 then
		local shown = {}
		for i = 1, math.min(#info.clothing, 6) do shown[i] = info.clothing[i] end
		fact("Clothing: " .. table.concat(shown, ", ") .. (#info.clothing > 6 and (" +" .. (#info.clothing - 6) .. " more") or ""))
	end
	if info.meshEdits > 0 then fact("Custom mesh edits: " .. info.meshEdits) end
	if info.outfitId then fact("Includes a Roblox outfit") end
	if info.username then
		fact(info.userFrozen and ("Look copied from " .. info.username .. " (saved, never changes)") or ("Copies " .. info.username .. "'s CURRENT avatar: it changes when they change it"))
	end
	local thumbs = {}
	local function addThumb(id, cap) if id then thumbs[#thumbs + 1] = { id = id, cap = cap } end end
	addThumb(info.shirt, "Shirt"); addThumb(info.pants, "Pants"); addThumb(info.graphic, "Graphic")
	for _, id in ipairs(info.accessories) do addThumb(id, "Accessory") end
	for _, id in ipairs(info.tail) do addThumb(id, "Tail") end
	for _, id in ipairs(info.catalogAccessories) do addThumb(id, "Catalog") end
	for _, id in ipairs(info.catalogTail) do addThumb(id, "Tail") end
	local MAXT, W, HEAD, FOOT = 12, 270, 50, 52


	local f = new("TextButton", { Name = "BundlePreview", Text = "", AutoButtonColor = false, BackgroundColor3 = T.bg, BorderSizePixel = 0, Size = UDim2.fromOffset(W, 420), ZIndex = 20, Active = true, Parent = screen })
	corner(f, 14); pcall(stroke, f, T.line, 1); pcall(_KR.addShadow, f)
	local us = new("UIScale", { Parent = f })
	local tok = {}
	_bp = { frame = f, name = nm, conns = {}, tok = tok }
	local function conn(sig, fn) _bp.conns[#_bp.conns + 1] = sig:Connect(fn) end

	lbl({ Position = UDim2.fromOffset(14, 10), Size = UDim2.new(1, -52, 0, 18), Text = nm, Font = FONTB, TextSize = 15, TextTruncate = Enum.TextTruncate.AtEnd, TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 21, Parent = f })
	lbl({ Position = UDim2.fromOffset(14, 29), Size = UDim2.new(1, -52, 0, 14), Text = KIND[info.tab] or "Bundle", TextColor3 = T.txt2, TextSize = 11.5, TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 21, Parent = f })
	local xb = new("TextButton", { AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -10, 0, 10), Size = UDim2.fromOffset(28, 28), BackgroundColor3 = T.card, AutoButtonColor = false, Text = "x", Font = FONTB, TextSize = 14, TextColor3 = T.txt2, ZIndex = 21, Parent = f }); corner(xb, 8)
	xb.MouseButton1Click:Connect(_bpClose)

	local sc = new("ScrollingFrame", { BackgroundTransparency = 1, BorderSizePixel = 0, Position = UDim2.fromOffset(10, HEAD), Size = UDim2.new(1, -20, 1, -(HEAD + FOOT)), CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y, ScrollBarThickness = 3, ZIndex = 21, Parent = f })
	vlist(sc, 8)
	local vp = new("ViewportFrame", { BackgroundColor3 = T.card, BackgroundTransparency = 0.2, BorderSizePixel = 0, Size = UDim2.new(1, -6, 0, 230), LayoutOrder = 1, Ambient = Color3.fromRGB(170, 170, 178), LightColor = Color3.new(1, 1, 1), LightDirection = Vector3.new(-0.4, -1, -0.6), ZIndex = 21, Parent = sc }); corner(vp, 10)
	local status = lbl({ Size = UDim2.fromScale(1, 1), Text = "Building your look...", TextColor3 = T.txt3, TextSize = 12, TextXAlignment = Enum.TextXAlignment.Center, ZIndex = 22, Parent = vp })
	local hint = lbl({ AnchorPoint = Vector2.new(0.5, 1), Position = UDim2.new(0.5, 0, 1, -4), Size = UDim2.new(1, -8, 0, 12), Text = "", TextColor3 = T.txt3, TextSize = 10, TextXAlignment = Enum.TextXAlignment.Center, ZIndex = 22, Parent = vp })
	if #facts > 0 then
		lbl({ Size = UDim2.new(1, -6, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 2, Text = table.concat(facts, "\n"), TextColor3 = T.txt2, TextSize = 12, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 21, Parent = sc })
	end
	if info.username and not info.userFrozen and info.tab == "mine" and System.freezeBundleUser then
		local fz = new("TextButton", { Size = UDim2.new(1, -6, 0, 30), LayoutOrder = 3, BackgroundColor3 = T.card, AutoButtonColor = false, Text = "Freeze this look (keep " .. info.username .. "'s avatar as it is today)", TextWrapped = true, Font = FONTB, TextSize = 11, TextColor3 = T.txt, ZIndex = 21, Parent = sc }); corner(fz, 8)
		local busy = false
		fz.MouseButton1Click:Connect(function()
			if busy then return end
			busy = true; fz.Text = "Saving..."
			task.spawn(function()
				local ok, msg = System.freezeBundleUser(nm)
				toast("Bundles", tostring(msg or (ok and "Saved." or "Failed.")), ok and "ok" or "warn")
				if ok and _bp.tok == tok then _bpClose(); UI._bundlePreviewDialog(nm, active, onWear, anchor) elseif fz.Parent then busy = false; fz.Text = "Freeze this look" end
			end)
		end)
	end
	if #thumbs > 0 then
		local grid = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, -6, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 4, ZIndex = 21, Parent = sc })
		new("UIGridLayout", { CellSize = UDim2.new(1 / 4, -6, 0, 70), CellPadding = UDim2.fromOffset(6, 6), SortOrder = Enum.SortOrder.LayoutOrder, Parent = grid })
		for i = 1, math.min(#thumbs, MAXT) do
			local t = thumbs[i]
			local cell = new("Frame", { BackgroundColor3 = T.card, BorderSizePixel = 0, LayoutOrder = i, ZIndex = 21, Parent = grid }); corner(cell, 8)
			new("ImageLabel", { BackgroundTransparency = 1, Position = UDim2.fromOffset(3, 3), Size = UDim2.new(1, -6, 1, -20), ScaleType = Enum.ScaleType.Fit, Image = "rbxthumb://type=Asset&id=" .. t.id .. "&w=150&h=150", ZIndex = 22, Parent = cell })
			lbl({ AnchorPoint = Vector2.new(0, 1), Position = UDim2.new(0, 3, 1, -2), Size = UDim2.new(1, -6, 0, 14), Text = t.cap, TextColor3 = T.txt2, TextSize = 10, TextTruncate = Enum.TextTruncate.AtEnd, ZIndex = 22, Parent = cell })
		end
		if #thumbs > MAXT then
			lbl({ Size = UDim2.new(1, -6, 0, 16), LayoutOrder = 5, Text = "+" .. (#thumbs - MAXT) .. " more items", TextColor3 = T.txt3, TextSize = 11, TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 21, Parent = sc })
		end
	end

	local wear = new("TextButton", { AnchorPoint = Vector2.new(0, 1), Position = UDim2.new(0, 10, 1, -10), Size = UDim2.new(0.5, -15, 0, 34), BackgroundColor3 = T.accentD, AutoButtonColor = false, Text = "", Font = FONTB, TextSize = 13, TextColor3 = T.txt, ZIndex = 21, Parent = f }); corner(wear, 9)
	local close = new("TextButton", { AnchorPoint = Vector2.new(1, 1), Position = UDim2.new(1, -10, 1, -10), Size = UDim2.new(0.5, -15, 0, 34), BackgroundColor3 = T.bg2, AutoButtonColor = false, Text = "Close", Font = FONTB, TextSize = 13, TextColor3 = T.txt2, ZIndex = 21, Parent = f }); corner(close, 9); pcall(stroke, close, T.line, 1)
	local function paintWear() wear.Text = _bpActive(nm) and "Remove" or "Wear" end
	paintWear()
	wear.MouseButton1Click:Connect(function()
		if onWear then onWear() end
		task.delay(0.15, function() if _bp.tok == tok then paintWear() end end)
	end)
	close.MouseButton1Click:Connect(_bpClose)

	local function place()
		if _bp.tok ~= tok then return end
		if not (root.Parent and root.Visible and anchor.Parent and anchor:IsDescendantOf(root)) then _bpClose(); return end
		local rs = root:FindFirstChildOfClass("UIScale")
		local s = (rs and rs.Scale > 0) and rs.Scale or 1
		us.Scale = s
		local sp, ss = screen.AbsolutePosition, screen.AbsoluteSize
		local rp, rsz = root.AbsolutePosition - sp, root.AbsoluteSize
		local w, gap = W * s, 10
		local x, y, h
		if rp.X >= w + gap + 6 then x, y, h = rp.X - w - gap, rp.Y, rsz.Y
		elseif ss.X - (rp.X + rsz.X) >= w + gap + 6 then x, y, h = rp.X + rsz.X + gap, rp.Y, rsz.Y
		else x, y, h = rp.X + 8, rp.Y + 8, rsz.Y - 16 end


		local wpx = math.min(w, math.max(160 * s, ss.X - 12))
		h = math.min(math.clamp(h, 260 * s, 560 * s), math.max(200 * s, ss.Y - 12))
		x = math.clamp(x, 6, math.max(6, ss.X - wpx - 6))
		y = math.clamp(y, 6, math.max(6, ss.Y - h - 6))
		f.Position = UDim2.fromOffset(math.floor(x), math.floor(y))
		f.Size = UDim2.fromOffset(math.floor(wpx / s), math.floor(h / s))
	end
	place()
	conn(root:GetPropertyChangedSignal("AbsolutePosition"), place)
	conn(root:GetPropertyChangedSignal("AbsoluteSize"), place)
	conn(root:GetPropertyChangedSignal("Visible"), place)
	conn(screen:GetPropertyChangedSignal("AbsoluteSize"), place)
	conn(anchor.AncestryChanged, place)

	task.spawn(function()

		local ok, m = false, nil
		local why
		if System.getBundleLook then ok, m, why = pcall(System.getBundleLook, nm) end
		if ok and not m and (why == "cancelled" or why == "busy") and _bp.tok == tok then
			status.Text = "Waiting for your outfit to finish..."
			local t0 = os.clock()
			repeat task.wait(0.2) until _bp.tok ~= tok or not (System._realBuildActive and System._realBuildActive()) or os.clock() - t0 > 30
			if _bp.tok == tok then status.Text = "Building your look..."; ok, m, why = pcall(System.getBundleLook, nm) end
		end
		local plain = false
		if not (ok and m) and _bp.tok == tok then ok, m = pcall(System.getBundleMannequin, nm); plain = true end
		if _bp.tok ~= tok or not vp.Parent then if ok and m then m:Destroy() end; return end
		if not (ok and m) then status.Text = "Couldn't build the preview."; return end
		status.Visible = false

		local function noteFor(model)
			local n = tonumber(model:GetAttribute("rcLoadFails"))
			if plain then return "Couldn't build your look, showing a plain preview. Drag to turn" end
			if n and n > 0 then return "Some items couldn't load (" .. n .. "). Drag to turn" end
			return "Drag to turn"
		end
		hint.Text = noteFor(m)
		local wm = Instance.new("WorldModel"); wm.Parent = vp
		local function show(model)
			model.Parent = wm
			local idle = model:GetAttribute("rcIdleAnim")
			if type(idle) == "string" and idle ~= "" then pcall(function()
				local h = model:FindFirstChildOfClass("Humanoid")
				local animator = h:FindFirstChildOfClass("Animator") or Instance.new("Animator", h)
				local a = Instance.new("Animation"); a.AnimationId = idle
				local tr = animator:LoadAnimation(a); tr.Looped = true; tr:Play(0.1)
			end) end
		end
		show(m)
		if why == "stale" then
			task.spawn(function()
				local ok2, m2 = pcall(System.getBundleLook, nm, { force = true })
				if ok2 and m2 and _bp.tok == tok and wm.Parent then m:Destroy(); m = m2; show(m2); hint.Text = noteFor(m2) elseif ok2 and m2 then m2:Destroy() end
			end)
		end
		local cf, size = m:GetBoundingBox()
		local centre = cf.Position
		local d = math.max(size.Y, size.X * 1.25) * 1.5 + 1.5
		local cam = Instance.new("Camera"); cam.FieldOfView = 40; cam.Parent = vp; vp.CurrentCamera = cam
		local yaw = 0.3
		local function aim() cam.CFrame = CFrame.lookAt(centre + Vector3.new(math.sin(yaw) * d, d * 0.12, -math.cos(yaw) * d), centre) end
		aim()
		local dragging, lastX = false, 0
		local function isPress(io) return io.UserInputType == Enum.UserInputType.MouseButton1 or io.UserInputType == Enum.UserInputType.Touch end
		conn(vp.InputBegan, function(io) if isPress(io) then dragging = true; lastX = io.Position.X; sc.ScrollingEnabled = false end end)
		conn(UserInputService.InputChanged, function(io)
			if dragging and (io.UserInputType == Enum.UserInputType.MouseMovement or io.UserInputType == Enum.UserInputType.Touch) then
				yaw -= (io.Position.X - lastX) * 0.012; lastX = io.Position.X; aim()
			end
		end)
		conn(UserInputService.InputEnded, function(io) if dragging and isPress(io) then dragging = false; sc.ScrollingEnabled = true end end)
	end)
end
function PAGES.bundles(h, sticky)






	local TAB_IDS = { "community", "mine", "clothing", "preset" }
	local TAB_LABELS = { community = "Community", mine = "Mine", clothing = "Clothing", preset = "Presets" }
	local render
	local _tabIdx = 1
	do
		local at = System and System.getActiveBundleTab and System.getActiveBundleTab()
		if at then for i, id in ipairs(TAB_IDS) do if id == at then _tabIdx = i; break end end end
	end
	local _tab = TAB_IDS[_tabIdx]
	local _search = ""
	if System and System.setBundleTab then System.setBundleTab(_tab) end

	local _counts = (System and System.getBundleCounts and System.getBundleCounts()) or {}
	local bcounts = { _counts.community or 0, _counts.mine or 0, _counts.clothing or 0, _counts.preset or 0 }

	local sw = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, Parent = sticky }); pad(sw, 14, 10, 4, 8); vlist(sw, 8)
	local hint = new("Frame", { BackgroundColor3 = Color3.fromRGB(40, 30, 18), BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 1, Visible = false, Parent = sw }); corner(hint, 8); stroke(hint, T.warn, 1); pad(hint, 10, 10, 7, 7)
	local hintLbl = lbl({ Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, Text = "", TextColor3 = T.warn, TextSize = 11.5, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, Parent = hint })
	UI.seg(sw, { "Community", "Mine", "Clothing", "Presets" }, 2, function(o, i) _tab = TAB_IDS[i] or "community"; if System and System.setBundleTab then System.setBundleTab(_tab) end; if render then render() end end, _tabIdx, nil, bcounts)
	local _bsegCounts = UI._lastSegSetCounts
	UI.field(sw, "Search bundles", "", 3, true, function(t) _search = t or ""; if render then render() end end, nil, false)

	local ab = cols(h, 1, 3)
	UI.button(ab[1], "Save Outfit", "primary", 1, saveOutfitDialog)
	UI.button(ab[2], "Export Bundle", nil, 1, exportBundleDialog)
	UI.button(ab[3], "Manage Deleted", nil, 1, function() if UI._manageDeletedDialog then UI._manageDeletedDialog() end end)


	local mine = cols(h, 2, 2)
	local mineRow = mine[1].Parent
	local function _activeMine()
		local n = System and System.getPD and System.getPD("CurrentBundle")
		if type(n) ~= "string" or n == "" or n == "nil" then n = System and System.getPD and System.getPD("CurrentPreset") end
		return (type(n) == "string" and n ~= "" and n ~= "nil") and n or nil
	end
	UI.button(mine[1], "Rename", nil, 1, function()
		local n = _activeMine()
		if not n then toast("Rename", "Apply one of your bundles first, then press Rename.", "warn"); return end
		showModal("Rename Bundle", 'New name for "' .. n .. '"', {
			{ text = "Cancel" },
			{ text = "Rename", kind = "primary", onClick = function(t)
				local ok, msg = System.renameBundle(n, t)
				toast("Rename", tostring(msg), ok and "ok" or "warn"); if render then render() end
			end },
		}, true, n)
	end)
	UI.button(mine[2], "Update with my look", nil, 1, function()
		local n = _activeMine()
		if not n then toast("Update", "Apply one of your bundles first, change your look, then press Update.", "warn"); return end
		showModal("Update Bundle", 'Replace "' .. n .. '" with the look you are wearing now?', {
			{ text = "Cancel" },
			{ text = "Update", kind = "primary", onClick = function()
				local ok, msg = System.updateBundle(n)
				toast("Update", tostring(msg), ok and "ok" or "warn"); if render then render() end
			end },
		})
	end)

	local emptyLbl = lbl({ Name = "Empty", Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 4, Text = "", TextColor3 = T.txt3, TextSize = 11.5, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, Visible = false, Parent = h })
	local gridWrap = new("Frame", { Name = "BundlesGridWrap", BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 3, Parent = h })
	render = function()
		do local _c = (System and System.getBundleCounts and System.getBundleCounts()) or {}; _bsegCounts({ _c.community or 0, _c.mine or 0, _c.clothing or 0, _c.preset or 0 }) end
		if not (gridWrap and gridWrap.Parent) then return end
		mineRow.Visible = (_tab == "mine")

		local armed = UI._detectingBundle
		if armed == "delete" then hintLbl.Text = "Click a bundle below to DELETE it."; hint.Visible = true
		elseif armed == "export_copy" then hintLbl.Text = "Click a bundle below to COPY its template to the clipboard."; hint.Visible = true
		else hint.Visible = false end
		local list = (System and System.getBundleList and System.getBundleList(_tab, _search)) or {}
		local items = {}
		UI._bndLive = {}; for _, e in ipairs(list) do UI._bndLive[e.name] = e end
		for _, e in ipairs(list) do
			local nm = e.name
			items[#items + 1] = {
				name = nm,
				sub = TAB_LABELS[e.tab] or e.tab,
				badge = e.active and "ACTIVE" or nil,
				badgeColor = T.accent,
				tag = nm,
				onPress = (not UserInputService.TouchEnabled) and function()
					if not UI._detectingBundle and System and System.getBundleLook then task.spawn(pcall, System.getBundleLook, nm, { warm = true }) end
				end or nil,

				onClick = function()
					local mode = UI._detectingBundle
					if mode == "export_copy" then
						UI._detectingBundle = nil
						if System and System.exportBundle then
							task.spawn(function()
								local msg = System.exportBundle(nm, "clipboard")
								toast("Copy Template", tostring(msg or "Copied."), _exportKind(msg or "Copied."))
							end)
						end
						if render then render() end
					elseif mode == "delete" then
						UI._detectingBundle = nil
						if System and System.deleteBundle then
							System.deleteBundle(nm)

							if System.getPD and System.clearBundle and (System.getPD("CurrentBundle") == nm or System.getPD("CurrentPreset") == nm) then
								System.clearBundle()
							end
							toast("Delete Bundle", 'Deleted "' .. nm .. '".', "warn")
						end
						if render then render() end
					elseif System and System.applyBundle then

						UI._bundlePreviewDialog(nm, ((UI._bndLive and UI._bndLive[nm]) or e).active, function()
							System.applyBundle(nm)
							if render then render() end
						end, gridWrap)
					end
				end,
			}
		end


		local _sigT = {}; for _, e in ipairs(list) do _sigT[#_sigT + 1] = e.name .. "\1" .. tostring(e.tab) end
		local _sig = table.concat(_sigT, "\0")
		local _bb = UI._bndBuilt
		if _bb and _bb.sig == _sig and _bb.grid and _bb.grid.Parent == gridWrap and _bb.setBadge then
			for i, it in ipairs(items) do _bb.setBadge(i, it.badge, it.badgeColor) end
		else
			for _, c in ipairs(gridWrap:GetChildren()) do c:Destroy() end
			local _g, _, _sb = UI.tiles(gridWrap, items, 1, 64)
			UI._bndBuilt = { sig = _sig, grid = _g, setBadge = _sb }
		end



		if System and System.getBundleLook and not gridWrap:GetAttribute("rcPrefetch") then
			gridWrap:SetAttribute("rcPrefetch", true)
			task.spawn(function()
				local phone = UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled
				local lastCanvas, built = nil, false
				while gridWrap.Parent do
					task.wait(built and (phone and 1.5 or 0.25) or (phone and 2.5 or 1))
					local justBuilt = built
					built = false
					local root = UI.panelRootOf(gridWrap)
					local sf = gridWrap:FindFirstAncestorWhichIsA("ScrollingFrame")
					if root and root.Visible and sf and gridWrap.AbsoluteSize.X > 0 and not UI._detectingBundle then
						local canvas = sf.CanvasPosition
						local still = (lastCanvas and (canvas - lastCanvas).Magnitude < 1) or justBuilt
						lastCanvas = canvas
						if still then
							local top, bot = sf.AbsolutePosition.Y, sf.AbsolutePosition.Y + sf.AbsoluteSize.Y
							local done, tried = 0, false
							for _, c in ipairs(gridWrap:GetDescendants()) do
								local tnm = c:GetAttribute("rcTile")
								if tnm and c.AbsolutePosition.Y + c.AbsoluteSize.Y > top and c.AbsolutePosition.Y < bot then
									if System.bundleLookCached(tnm) then done += 1
									elseif not tried and done < (phone and 4 or 10) then
										tried = true
										local okB, mB = pcall(System.getBundleLook, tnm, { background = true, warm = true })
										if okB and mB then built = true end
									end
								end
							end
						end
					end
				end
			end)
		end
		if #list == 0 then
			emptyLbl.Text = (_search ~= "" and ('No bundles match "' .. _search .. '".')) or ("No " .. (TAB_LABELS[_tab] or _tab) .. " bundles yet.")
			emptyLbl.Visible = true
		else
			emptyLbl.Visible = false
		end
	end
	UI._renderBundles = render
	if System then System.renderBundles = render end
	render()
end

function PAGES._clones(h, order)
	local Sy = System
	do
		local ct = tile(h, "Clones", order or 9)
		UI.hint(ct, "Spawn a frozen 1:1 copy of your current look; tap one to edit it (the whole hub retargets to it). Your own avatar is never touched.", 1)
		local cbtns = cols(ct, 2, 2)
		local _renderClones
		UI.button(cbtns[1], "Spawn Clone", "primary", 1, function()
			_KR.count("act:spawn_clone")
			local key = Sy and Sy.spawnClone and Sy.spawnClone()
			toast("Clones", key and ("Spawned " .. key .. ".") or "Couldn't spawn (no character?).", key and "ok" or "warn")
			if _renderClones then _renderClones() end
		end)
		UI.button(cbtns[2], "Clear All", nil, 1, function()
			if Sy and Sy.clearClones then Sy.clearClones() end
			if _renderClones then _renderClones() end
			toast("Clones", "Cleared all clones.", "info")
		end)
		local clist = new("Frame", { Name = "CloneList", BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 3, Parent = ct }); vlist(clist, 6)
		local _selCtl = new("Frame", { Name = "CloneSelCtl", BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 4, Parent = ct }); vlist(_selCtl, 6)
		_renderClones = function()
			if not (clist and clist.Parent) then return end
			for _, c in ipairs(clist:GetChildren()) do if c:IsA("Frame") or c:IsA("TextButton") then c:Destroy() end end
			for _, c in ipairs(_selCtl:GetChildren()) do if not c:IsA("UIListLayout") then c:Destroy() end end
			local rows = (Sy and Sy.getCloneList and Sy.getCloneList()) or {}
			for i, e in ipairs(rows) do
				local r = rowShell(clist, 32, i)
				local isClone = (e.label ~= "Self")
				local hit = new("TextButton", { AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 0, 0.5, 0), Size = UDim2.new(1, isClone and -34 or -4, 1, 0), BackgroundColor3 = e.selected and T.cardHi or T.card, AutoButtonColor = false, Text = "", Parent = r }); corner(hit, 7); stroke(hit, e.selected and T.accent or T.line, e.selected and 1.5 or 1)
				lbl({ AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 10, 0.5, 0), Size = UDim2.new(1, -14, 1, 0), Text = e.label .. (e.selected and "  (editing)" or ""), TextXAlignment = Enum.TextXAlignment.Left, TextColor3 = e.selected and T.txt or T.txt2, Parent = hit })
				hit.MouseButton1Click:Connect(function()
					if Sy and Sy.setSelect then Sy.setSelect(e.key) end
					if _renderClones then _renderClones() end
				end)
				if isClone then
					local xb = new("TextButton", { AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -2, 0.5, 0), Size = UDim2.fromOffset(28, 28), BackgroundColor3 = T.card, AutoButtonColor = false, Text = "x", Font = FONTB, TextColor3 = T.txt2, TextSize = 13, Parent = r }); corner(xb, 7); stroke(xb, T.line, 1)
					xb.MouseButton1Click:Connect(function()
						if Sy and Sy.removeClone then Sy.removeClone(e.key) end
						if _renderClones then _renderClones() end
					end)
				end
			end

			local selKey, selHidden, selName
			for _, e in ipairs(rows) do if e.selected and e.label ~= "Self" then selKey, selHidden, selName = e.key, e.nameHidden, e.label end end
			if selKey then
				local rr = rowShell(_selCtl, 34, 1)
				local tb = new("TextBox", { AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 0, 0.5, 0), Size = UDim2.new(1, -4, 1, 0), BackgroundColor3 = T.card, Text = selName or "", PlaceholderText = "Rename this clone...", ClearTextOnFocus = false, Font = FONTB, TextSize = 13, TextColor3 = T.txt, TextXAlignment = Enum.TextXAlignment.Left, Parent = rr }); corner(tb, 7); stroke(tb, T.line, 1)
				local _pad = Instance.new("UIPadding"); _pad.PaddingLeft = UDim.new(0, 10); _pad.Parent = tb
				tb.FocusLost:Connect(function()
					if Sy and Sy.renameClone then Sy.renameClone(selKey, tb.Text) end
					if _renderClones then _renderClones() end
				end)
				local possessing = Sy and Sy.isPossessing and Sy.isPossessing(selKey)
				local br = cols(_selCtl, 2, 2)
				local nb = new("TextButton", { Size = UDim2.new(1, 0, 0, 30), BackgroundColor3 = selHidden and T.card or T.cardHi, AutoButtonColor = false, Text = selHidden and "Name: hidden" or "Name: shown", Font = FONTB, TextSize = 12, TextColor3 = T.txt2, Parent = br[1] }); corner(nb, 7); stroke(nb, selHidden and T.line or T.accent, 1)
				nb.MouseButton1Click:Connect(function()
					if Sy and Sy.setCloneNameHidden then Sy.setCloneNameHidden(selKey, not selHidden) end
					if _renderClones then _renderClones() end
				end)

				local pb = new("TextButton", { Size = UDim2.new(1, 0, 0, 30), BackgroundColor3 = possessing and T.cardHi or T.card, AutoButtonColor = false, Text = possessing and "Release control" or "Possess (WASD)", Font = FONTB, TextSize = 12, TextColor3 = possessing and T.txt or T.txt2, Parent = br[2] }); corner(pb, 7); stroke(pb, possessing and T.accent or T.line, possessing and 1.5 or 1)
				pb.MouseButton1Click:Connect(function()
					if not Sy then return end
					if possessing then if Sy.releaseClone then Sy.releaseClone() end
					else if Sy.possessClone then Sy.possessClone(selKey) end end
					if _renderClones then _renderClones() end
				end)

				local cr = rowShell(_selCtl, 32, 3)
				local cb = new("TextButton", { Size = UDim2.new(1, 0, 1, 0), BackgroundColor3 = T.cardHi, AutoButtonColor = false, Text = "Copy my look onto this clone", Font = FONTB, TextSize = 12, TextColor3 = T.txt, Parent = cr }); corner(cb, 7); stroke(cb, T.accent, 1)
				cb.MouseButton1Click:Connect(function()
					local ok = Sy and Sy.syncCloneFromSelf and Sy.syncCloneFromSelf(selKey)
					toast("Edit", ok and "Clone updated to your current look." or "Couldn't copy look.", ok and "ok" or "warn")
					if _renderClones then _renderClones() end
				end)
			end
		end
		if Sy then Sy.renderCloneList = _renderClones end
		_renderClones()
	end
end
function PAGES.edit(h)

	if _KR.editBar then _KR.editBar.attach(h) else UI.hint(h, "Edit is not available.", 1) end
end



function PAGES._myContent(mc)
	local C = System and System.Community
	if not C then UI.hint(mc, "Community content is not available on this executor.", 1); return end
	UI.hint(mc, "Make your own item in the RClothesLerp/Community/<folder> folder (item.json + your files), test it here, then submit it. krul reviews every item before anyone else sees it. Nothing about you is shown publicly, only the optional credit name.", 1)
	local body = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 3, Parent = mc }); vlist(body, 8)
	local status = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 5, Parent = mc }); vlist(status, 6)
	local render
	local function clear(f) for _, c in ipairs(f:GetChildren()) do if c:IsA("GuiObject") then c:Destroy() end end end
	local function tuneSheet(parent, folder, item, order)
		local p = item.placement
		local w = { offset = { p.offset[1], p.offset[2], p.offset[3] }, rotation = { p.rotation[1], p.rotation[2], p.rotation[3] }, scale = { p.scale[1], p.scale[2], p.scale[3] } }
		local axes = { "X", "Y", "Z" }


		for i = 1, 3 do local v0 = math.floor(w.offset[i] * 100 + 0.5); local lim = math.min(1000, math.max(200, math.abs(v0)))
			UI.slider(parent, "Offset " .. axes[i], v0, -lim, lim, order + i, function(v) w.offset[i] = v / 100 end, 0) end
		for i = 1, 3 do local v0 = math.floor(w.rotation[i] + 0.5); local lim = math.min(360, math.max(180, math.abs(v0)))
			UI.slider(parent, "Rotation " .. axes[i], v0, -lim, lim, order + 3 + i, function(v) w.rotation[i] = v end, 0) end
		for i = 1, 3 do local v0 = math.floor(w.scale[i] * 100 + 0.5)
			UI.slider(parent, "Scale " .. axes[i], v0, 5, math.min(1000, math.max(300, v0)), order + 6 + i, function(v) w.scale[i] = v / 100 end, 100) end
		UI.button(parent, "Save placement and re-wear", "primary", order + 10, function()
			if C.saveTuning(folder, w) then System.communityWearLocal(folder); toast("My Content", "Placement saved to item.json.", "info")
			else toast("My Content", "Those values are out of range.", "warn") end
		end)
	end
	local function itemCard(folder, r, order)
		local card = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = order, Parent = body }); vlist(card, 6)
		local it = r.item or {}
		UI.hint(card, (it.name or folder) .. "  (" .. folder .. ", " .. tostring(it.slot or "?") .. ")", 1)
		if #r.errors > 0 then UI.hint(card, "Fix before testing: " .. table.concat(r.errors, "; "), 2); return end
		local row = cols(card, 3, 2)
		UI.button(row[1], "Wear", nil, 1, function() if System.communityWearLocal(folder) then toast("My Content", "Wearing " .. it.name .. " (only you see it).", "info") end end)
		UI.button(row[2], "Take off", nil, 1, function() System.communityWearLocal(folder, false) end)
		local tuneWrap = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, Visible = false, LayoutOrder = 5, Parent = card }); vlist(tuneWrap, 6)
		local subWrap = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, Visible = false, LayoutOrder = 7, Parent = card }); vlist(subWrap, 6)
		local row2 = cols(card, 4, 2)
		UI.button(row2[1], "Tune placement", nil, 1, function()
			if not tuneWrap:GetAttribute("built") then tuneWrap:SetAttribute("built", true); tuneSheet(tuneWrap, folder, it, 1) end
			UI.reveal(tuneWrap, not tuneWrap.Visible, true)
		end)
		UI.button(row2[2], "Submit...", nil, 1, function()
			if not subWrap:GetAttribute("built") then
				subWrap:SetAttribute("built", true)
				local opts = { credit = it.credit or "" }
				UI.field(subWrap, "Credit name (optional, fictional)", opts.credit, 1, true, function(t) opts.credit = tostring(t or ""):sub(1, 24) end, "Leave empty for no credit")
				UI.field(subWrap, "Update of item id (optional)", "", 2, true, function(t) t = tostring(t or ""); opts.updateOf = (t ~= "" and t) or nil end, "Only to replace your own approved item")
				if C.FORK and C.FORK.onlyLabel then UI.toggle(subWrap, C.FORK.onlyLabel, false, 3, function(st) opts.forkOnly = st end) end
				local armed = false
				UI.button(subWrap, "Send for review", "primary", 4, function()
					if not armed then armed = true; toast("My Content", "Press again to send " .. it.name .. " for review.", "info"); task.delay(4, function() armed = false end); return end
					armed = false
					toast("My Content", "Sending...", "info")
					task.spawn(function()
						local ok, res = System.communitySubmit(folder, opts)
						toast("My Content", ok and "Sent! Follow it under My submissions." or ("Not sent: " .. tostring(res)), ok and "info" or "warn")
						if ok and render then render() end
					end)
				end)
			end
			UI.reveal(subWrap, not subWrap.Visible, true)
		end)
	end
	local function worn(order)
		local any = false
		for _, slot in ipairs(C.SLOTS) do
			local ref = System.communitySelected and System.communitySelected(slot)
			local id = C.parseRef(ref)
			local e = (id and C.items[id]) or (type(ref) == "string" and ref:sub(1, 6) == "local:" and C.localItems[ref:sub(7)]) or nil
			if e and type(e.settings) == "table" and #e.settings > 0 then
				if not any then UI.hint(body, "Settings of worn items", order); any = true end
				for i, s in ipairs(e.settings) do
					local cur = System.communitySettingValue and System.communitySettingValue(e.id, s.key)
					if s.type == "slider" then
						local span = s.max - s.min; if span == 0 then span = 1 end
						if type(cur) ~= "number" or cur ~= cur then cur = s.default end
						UI.slider(body, e.name .. ": " .. s.label, math.clamp(math.floor((cur - s.min) / span * 100 + 0.5), 0, 100), 0, 100, order + i, function(v) System.communitySetting(e.id, s.key, s.min + v / 100 * span) end)
					else
						if type(cur) ~= "boolean" then cur = s.default == true end
						UI.toggle(body, e.name .. ": " .. s.label, cur, order + i, function(st) System.communitySetting(e.id, s.key, st) end)
					end
				end
				order += #e.settings + 1
			end
		end
	end
	local function renderStatus()
		clear(status)
		UI.hint(status, "Loading your submissions...", 1)
		task.spawn(function()
			local list = C.mine()
			if not status.Parent then return end
			clear(status)
			if #list == 0 then UI.hint(status, "No submissions yet.", 1); return end
			for i, row in ipairs(list) do
				UI.hint(status, tostring(row.name) .. " (v" .. tostring(row.ver) .. "): " .. C.statusText(row), i * 2)
				if row.status == "pending" then
					UI.button(status, "Withdraw " .. tostring(row.name), nil, i * 2 + 1, function()
						task.spawn(function() toast("My Content", C.withdraw(row.subId) and "Withdrawn." or "Could not withdraw.", "info"); renderStatus() end)
					end)
				end
			end
		end)
	end
	render = function()
		clear(body)
		local scan = C.scanLocal()
		local folders = {}
		for f in pairs(scan) do folders[#folders + 1] = f end
		table.sort(folders)
		if #folders == 0 then UI.hint(body, "No items yet. Make a folder in RClothesLerp/Community with an item.json.", 1) end
		for i, f in ipairs(folders) do itemCard(f, scan[f], i) end
		worn(#folders + 10)
	end
	local top = cols(mc, 2, 2)
	UI.button(top[1], "Reload my items", nil, 1, function() render(); toast("My Content", "Reloaded from disk.", "info") end)
	UI.button(top[2], "My submissions", nil, 1, renderStatus)
	render()
end

function PAGES.settings(h)



	local L, R = bentoCols(h, 1, 0.5)
	local function _save() if System and System.persistLoadup then System.persistLoadup() end end




	local ol = tile(L, "Startup & Execute", 1)


	do
		local st0 = System and System.getLoadup and System.getLoadup("Execute")
		local re0 = System and System.getSelfPD and System.getSelfPD("AutoExecute")
		UI.cyc(ol, "Apply my look", { "Off", "On start", "On every respawn" }, 2, function(v)
			local onStart, onRespawn = v ~= "Off", v == "On every respawn"
			if System and System.setLoadupExecute then System.setLoadupExecute(onStart) end
			if System and System.setAutoExecute then System.setAutoExecute(onRespawn) end
			_save()
