	end)
	local b2 = cols(bc, 5, 2)
	UI.button(b2[1], "Check Content", nil, 1, function()
		if not (System and System.doContentCheck) then return end
		if Function and Function._redlInProgress then toast("Downloading content", "Already downloading -- please wait.", "warn"); return end
		toast("Checking content", "Looking for missing or damaged files...", "info")
		local lastTotal, lastFailed, clean = 0, 0, false
		System.doContentCheck(function(done, total, failed, file, size, stage, files, sized)
			if type(total) == "number" and total > 0 then lastTotal = total end
			if type(failed) == "number" then lastFailed = failed end
			if stage == "uptodate" then
				clean = true
				toast("Content ready", string.format(sized and "All %d files are present and the right size." or "All %d files are present.", files or 0), "ok")
			elseif stage == "complete" then
				if clean then return end
				if lastTotal > 0 and lastFailed == 0 then toast("Content repaired", string.format("Downloaded %d missing or damaged files.", lastTotal), "ok")
				elseif lastTotal > 0 then toast("Content check finished", string.format("%d of %d files failed - see the error window, then try again.", lastFailed, lastTotal), "warn") end

			elseif stage == "error" then
				toast("Content check failed", "Couldn't finish checking - check your connection and try again.", "err")
			elseif type(done) == "number" and lastTotal > 0 then
				toast("Checking content", string.format("Repairing: %d / %d files", done, lastTotal), "info", true)
			end
		end)
	end)
	UI.button(b2[2], "Redownload All", nil, 1, function()
		if not (System and System.doRedownload) then return end
		if Function and Function._redlInProgress then toast("Downloading content", "Already downloading -- please wait.", "warn"); return end
		toast("Downloading content", "Starting download...", "info")
		local lastTotal, lastFailed = 0, 0
		System.doRedownload(function(done, total, failed, file, size, stage)
			if type(total) == "number" and total > 0 then lastTotal = total end
			if type(failed) == "number" then lastFailed = failed end
			if stage == "complete" then
				if lastTotal > 0 and lastFailed == 0 then toast("Content ready", string.format("Re-downloaded %d files.", lastTotal), "ok")
				elseif lastTotal > 0 then toast("Redownload finished", string.format("%d of %d files failed - try again.", lastFailed, lastTotal), "warn") end

			elseif stage == "error" then
				toast("Redownload failed", "Couldn't complete the download - check your connection and try again.", "err")
			elseif type(done) == "number" and lastTotal > 0 then
				toast("Downloading content", string.format("%d / %d files  (%d%%)", done, lastTotal, math.floor(done / lastTotal * 100)), "info", true)
