	UI.button(db[2], "Send Now", nil, 1, function() local n = (System and System.diagPendingCount and System.diagPendingCount()) or 0; if n == 0 then toast("Telemetry", "Nothing to send.", "info") else local sent = (System and System.diagSendNow) and System.diagSendNow(); toast("Telemetry", sent and ("Sent " .. n .. " event(s).") or "Couldn't send - try again later.", sent and "ok" or "warn") end end)
