		if dPress >= 3 then
			local p, s = dBtn.AbsolutePosition, dBtn.AbsoluteSize
			if destroyUI then destroyUI(p.X + s.X / 2, p.Y + s.Y / 2) end
			if System and System.doDestroy then System.doDestroy() end
		else
			if lb then lb.Text = "PRESS " .. (3 - dPress) .. " MORE" end
			task.delay(2.5, function() if myTok == dTok and dPress < 3 then dPress = 0; if lb then lb.Text = "DESTROY" end end end)
		end
	end)
end
_RCR.hook("ui", { System = System, PAGES = PAGES, UI = UI, T = T, _KR = _KR, FONT = FONT, FONTB = FONTB, LocalPlayer = LocalPlayer, new = new, lbl = lbl, corner = corner, pad = pad, vlist = vlist, cols = cols, bentoCols = bentoCols, rowShell = rowShell, tile = tile, toast = toast, screen = screen })
function PAGES.player(h)


