	UI.button(ac, "Reset", nil, 2, function() if System and System.doReset then System.doReset() end end)
	UI.button(ac, "Photo mode", nil, 4, function() if _KR.photo then _KR.photo() end end)


	local hi = tile(L, "History", 3)
	local hc = cols(hi, 1, 2)
