		UI.field(ff[1], "Bundle", _blab or (_bcur and _bcur ~= "nil" and tostring(_bcur)) or "None", 1, false)
	end
	local RM = { { "Method 1", "Standard", "Direct swap. Fastest; best for most avatars." }, { "Method 2", "Proxy", "Rig proxy. Best fidelity for layered meshes." }, { "Method 3", "First Person", "First-person view; hides your own head." } }
	local mdesc

	local _curMethod = (System and System.getMethod and System.getMethod()) or 1
	if _curMethod < 1 or _curMethod > 3 then _curMethod = 1 end
	_KR.segTag(UI.seg(lo, { RM[1][1], RM[2][1], RM[3][1] }, 2, function(o, i) if mdesc then mdesc.Text = RM[i][2] .. " - " .. RM[i][3] end; if System and System.setMethod then System.setMethod(i) end end, _curMethod), "Render method", "Method 1 Standard, Method 2 Proxy, Method 3 First Person")
	mdesc = lbl({ Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, Text = RM[_curMethod][2] .. " - " .. RM[_curMethod][3], TextColor3 = T.txt3, TextSize = 11, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, LayoutOrder = 3, Parent = lo }); pad(mdesc, 12, 12, 0, 0)

	UI.toggle(lo, "Bundle Body Color", (System and System.getPD and System.getPD("BundleBodyColor")) and true or false, 4, function(st) if System and System.setPD then System.setPD("BundleBodyColor", st) end end)
	UI.toggle(lo, "Show Face", (System and System.getPD and System.getPD("Face")) and true or false, 5, function(st) if System and System.setPD then System.setPD("Face", st) end end)

	if PAGES._clones then PAGES._clones(h, 2) end
	if PAGES._recent then PAGES._recent(h, 3) end
end


function PAGES._recent(h, order)
	local rt = tile(h, "Recent Looks", order)
	local box = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 1, Parent = rt }); vlist(box, 6)
	local function ago(t)
		local d = os.time() - (tonumber(t) or 0)
		if d < 60 then return "just now" elseif d < 3600 then return math.floor(d / 60) .. " min ago" elseif d < 86400 then return math.floor(d / 3600) .. " h ago" end
		return math.floor(d / 86400) .. " d ago"
	end
	local function fill()
		for _, ch in ipairs(box:GetChildren()) do if not ch:IsA("UIListLayout") then ch:Destroy() end end
		local list = (System and System.lookRecent and System.lookRecent()) or {}
		if #list == 0 then
			lbl({ Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, Text = "Looks you keep on for a little while show up here, so you can put them back on with one tap.", TextColor3 = T.txt3, TextSize = 11.5, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, LayoutOrder = 1, Parent = box })
			return
		end
		for i, e in ipairs(list) do
			local r = rowShell(box, 48, i); _KR.press(r)
			lbl({ Position = UDim2.fromOffset(0, 7), Size = UDim2.new(1, -70, 0, 17), Text = e.n, Font = FONTB, TextSize = 13, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd, Parent = r })
			lbl({ Position = UDim2.fromOffset(0, 26), Size = UDim2.new(1, -70, 0, 14), Text = ago(e.t) .. "  ·  " .. tostring(e.c) .. ((e.c == 1) and " item" or " items"), TextColor3 = T.txt3, TextSize = 11, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd, Parent = r })
			lbl({ AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, 0, 0.5, 0), Size = UDim2.fromOffset(60, 20), Text = "Wear", Font = FONTB, TextSize = 13, TextColor3 = T.accent, TextXAlignment = Enum.TextXAlignment.Right, Parent = r })
			r.MouseButton1Click:Connect(function()
				if not (System and System.lookWearRecent) then return end
				local ok, res = System.lookWearRecent(i)
				toast("Recent Looks", ok and ("Wearing " .. tostring(res)) or tostring(res), ok and "ok" or "warn")
				if ok then fill() end
			end)
		end
		UI.button(box, "Clear recent looks", nil, #list + 1, function() if System and System.lookClearRecent then System.lookClearRecent() end; fill() end)
	end
	fill()
	if System then System.renderRecent = function() if box.Parent then fill() end end end
end
function PAGES.recolor(h)





	UI.hint(h, "Auto-fills from equipped clothes; tap a swatch to recolour a part, or x to reset it.", 1)
	local list = new("Frame", { Name = "RecolorList", BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 2, Parent = h }); vlist(list, 8)
	local empty = lbl({ Name = "Empty", Visible = false, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 9999, Text = "", TextColor3 = T.txt3, TextSize = 11.5, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, Parent = list })
	local render


	local function _row(cloth, slot, curCol, order)
		local r = rowShell(list, 42, order)
		local chip = new("Frame", { AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 0, 0.5, 0), Size = UDim2.fromOffset(26, 26), BackgroundColor3 = curCol or T.accent, BorderSizePixel = 0, Parent = r }); corner(chip, 7); stroke(chip, T.line, 1)
		lbl({ AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 36, 0.5, 0), Size = UDim2.new(1, -36 - 34, 1, 0), Text = cloth .. " " .. slot, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd, Parent = r })
		local xb = new("TextButton", { AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -4, 0.5, 0), Size = UDim2.fromOffset(24, 24), BackgroundColor3 = T.card, AutoButtonColor = false, Text = "x", Font = FONTB, TextColor3 = T.txt2, TextSize = 13, Parent = r }); corner(xb, 7); local xs = stroke(xb, T.line, 1)
		xb.MouseEnter:Connect(function() tween(xb, 0.18, { BackgroundColor3 = T.cardHi }); tween(xs, 0.18, { Color = T.bad }) end)
		xb.MouseLeave:Connect(function() tween(xb, 0.18, { BackgroundColor3 = T.card }); tween(xs, 0.18, { Color = T.line }) end)

		local hit = new("TextButton", { AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 0, 0.5, 0), Size = UDim2.fromOffset(40, 42), BackgroundTransparency = 1, AutoButtonColor = false, Text = "", Parent = r })
		hit.MouseButton1Click:Connect(function()
			openColorPicker(chip.BackgroundColor3, function(c)
				chip.BackgroundColor3 = c
				if System and System.setRecolor then System.setRecolor(cloth, slot, c) end
			end)
		end)
		xb.MouseButton1Click:Connect(function()
			if System and System.resetRecolor then System.resetRecolor(cloth, slot) end
			if render then render() end
		end)
	end
	render = function()
		if not (list and list.Parent) then return end
		for _, c in ipairs(list:GetChildren()) do
			if c:IsA("Frame") or c:IsA("TextButton") then c:Destroy() end
		end
		local rows = (System and System.getRecolorRows and System.getRecolorRows()) or {}
		if #rows == 0 then
			empty.Text = "Nothing to recolour. Equip a cloth that has recolourable parts."
			empty.Visible = true
			return
		end
		empty.Visible = false
		for i, row in ipairs(rows) do
			_row(row.cloth, row.slot, row.current or row.default, i)
		end
	end
	if System then System.renderRecolorList = render end
	render()
end
function PAGES.damage(h)


	local L, R = bentoCols(h, 1, 0.5)

	local function _gp(f) return System and System.getPD and System.getPD(f) end
	local function _num(f, d) local v = _gp(f); return (type(v) == "number") and v or d end
	local function _seed(f) local v = _gp(f); return (v ~= nil and v ~= "") and tostring(v) or "" end

	local function _hpSeed(k) local hp = _gp("HPClothesUser"); local v = type(hp) == "table" and hp[k]; if v == nil or v == false then local ht = _gp("HPClothesTemplates"); v = type(ht) == "table" and ht[k] end; return ((type(v) == "string" or type(v) == "number") and v ~= "" and tostring(v)) or "" end

	local md = tile(h, "Mode", 0)
	UI.toggle(md, "Clothing Hardcore HP", (_gp("HardcoreHP") and true) or false, 1, function(st) if System and System.setPD then System.setPD("HardcoreHP", st) end end)
	UI.hint(md, "Off: clothes tear when your health drops past the % below, and come back when you heal. On: clothes get their own durability - taking damage wears it down and only the Heal key repairs it.", 2)
	local sh = tile(L, "Shirt", 1)
	UI.slider(sh, "Shirt tears at % HP", _num("TopHP", 50), 0, 150, 1, function(v) if System and System.setPDNum then System.setPDNum("TopHP", v) end end)
	UI.field(sh, "Ripped Shirt Id", _hpSeed("Shirt"), 2, true, function(t) if System and System.setHPClothes then System.setHPClothes("Shirt", t) end end)
	local pt = tile(R, "Pants", 1)
	UI.slider(pt, "Pants tear at % HP", _num("BottomHP", 50), 0, 150, 1, function(v) if System and System.setPDNum then System.setPDNum("BottomHP", v) end end)
	UI.field(pt, "Ripped Pants Id", _hpSeed("Pants"), 2, true, function(t) if System and System.setHPClothes then System.setHPClothes("Pants", t) end end)
	local sx = tile(h, "Damage SFX & Particles", 2)
	local sf = cols(sx, 1, 2)
	UI.field(sf[1], "Damage SFX Id", _seed("DamageSFX"), 1, true, function(t) if System and System.setPDNum then System.setPDNum("DamageSFX", t) end end)
	UI.field(sf[2], "Volume", (_seed("Volume") ~= "" and _seed("Volume")) or "1", 1, true, function(t) if tonumber(t) and System and System.setPD then System.setPD("Volume", tonumber(t)) end end)
	local tp = cols(sx, 2, 2)
	UI.toggle(tp[1], "Tear Particles", (_gp("TearParticles") and true) or false, 1, function(st) if System and System.setPD then System.setPD("TearParticles", st) end end)
	UI.toggle(tp[2], "Heal Particles", (_gp("HealParticles") and true) or false, 1, function(st) if System and System.setPD then System.setPD("HealParticles", st) end end)
	local as = tile(h, "Auto-Strip on Rip", 3)
	local ar = cols(as, 1, 2)


	do
		local _asOn = (System and System.getAutoStripOnRip and System.getAutoStripOnRip()) or false
		UI.cyc(ar[1], "Auto-Strip", { "OFF", "ON" }, 1, function() if System and System.toggleAutoStripOnRip then System.toggleAutoStripOnRip() end end, _asOn and "ON" or "OFF")
	end
	local cfgG = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, Visible = false, LayoutOrder = 2, Parent = as }); vlist(cfgG, 7)




	local _stripEmpty = lbl({ Name = "Empty", Visible = false, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 9999, Text = "", TextColor3 = T.txt3, TextSize = 11.5, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, Parent = cfgG })
	local function _renderStrip()
		if not (cfgG and cfgG.Parent) then return end
		for _, c in ipairs(cfgG:GetChildren()) do if c:IsA("Frame") then c:Destroy() end end
		local rows = (System and System.getStripRows and System.getStripRows()) or {}
		if #rows == 0 then _stripEmpty.Text = "Equip a cloth to configure auto-strip."; _stripEmpty.Visible = true; return end
		_stripEmpty.Visible = false
		for i = 1, #rows, 2 do
			local cc = cols(cfgG, i, 2)
			for k = 0, 1 do
				local row = rows[i + k]
				if row then local _cl = row.cloth; UI.cyc(cc[k + 1], "Strip " .. _cl, { "None", "Top", "Bottom", "Both" }, 1, function() if System and System.cycleStrip then System.cycleStrip(_cl) end end, row.mode) end
			end
		end
	end
	if System then System.renderStripList = _renderStrip end
	UI.button(ar[2], "Configure…", nil, 1, function()
		local willShow = not cfgG.Visible
		if willShow then _renderStrip() end
		UI.reveal(cfgG, willShow, true)
	end)
	_renderStrip()
	local hp = tile(h, "Per-cloth HP", 4)
	UI.hint(hp, "Cycle each equipped item (and accessory): None -> TopHP -> BottomHP -> InverseTop -> InverseBottom.", 1)
	local HP_MODES = { "None", "TopHP", "BottomHP", "InverseTop", "InverseBottom" }




	local hpG = new("Frame", { Name = "HPList", BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 2, Parent = hp }); vlist(hpG, 7)
	local _hpEmpty = lbl({ Name = "Empty", Visible = false, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 9999, Text = "", TextColor3 = T.txt3, TextSize = 11.5, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, Parent = hpG })
	local function _renderHP()
		if not (hpG and hpG.Parent) then return end
		for _, c in ipairs(hpG:GetChildren()) do if c:IsA("Frame") then c:Destroy() end end
		local rows = (System and System.getHPRows and System.getHPRows()) or {}
		if #rows == 0 then _hpEmpty.Text = "Equip a cloth or wear an accessory to set per-item HP."; _hpEmpty.Visible = true; return end
		_hpEmpty.Visible = false
		for i = 1, #rows, 2 do
			local hc = cols(hpG, i, 2)
			for k = 0, 1 do
				local row = rows[i + k]
				if row then local _lb, _acc = row.label, row.accessory; local _disp = tostring(_lb):match("^Accessory %((.+)%)$") or tostring(_lb); _disp = _disp:match("^Meshes/(.+)$") or _disp; UI.cyc(hc[k + 1], _disp, HP_MODES, 1, function() if System and System.cycleClothHP then System.cycleClothHP(_lb, _acc) end end, HP_MODES[(row.state or 0) + 1]) end
			end
		end
	end
	if System then System.renderHPList = _renderHP end
	_renderHP()

	local ky = tile(h, "Keys", 5)
	local function kcur(n, d) return (System and System.getKeybindName and System.getKeybindName(n)) or d end
	local function kset(n) return function(k)
		if not (System and System.setKeybind) then return end
		if k == "Off" then System.setKeybind(n, false) return end
		local ok, kc = pcall(function() return Enum.KeyCode[k] end); if ok and kc then System.setKeybind(n, kc) end
	end end
	UI.keybind(ky, "Heal", kcur("Heal", "="), 1, kset("Heal"))
	UI.keybind(ky, "Damage", kcur("Dmg", "-"), 2, kset("Dmg"))
	UI.hint(ky, SET.keybindsOff == true and "All keybinds are off (Settings > Keybinds)." or "Tap a key, then press the new key. Delete or Backspace turns it off.", 3)
end










UI._tpv = UI._tpv or {}
UI._tpvClose = function()
	local P = UI._tpv
	UI._tpv = {}
	for _, c in ipairs(P.conns or {}) do pcall(function() c:Disconnect() end) end
	if P.frame then P.frame:Destroy() end
end

UI._themeStyle = function(info)
	local B = System.Staff and System.Staff.BADGE
	return B and B[math.clamp(tonumber(info and info.tierRank) or 1, 1, #B)]
end
UI._themeTint = function(lb, st)
	if not st then return end
	lb.TextColor3 = st.c
	if st.grad then
		local kp = {}
		for i, g in ipairs(st.grad) do kp[i] = ColorSequenceKeypoint.new((i - 1) / (#st.grad - 1), g) end
		new("UIGradient", { Color = ColorSequence.new(kp), Parent = lb })
	end
end
UI._themeCols = function(id)
	local TH = System and System.Themes
	local a, b = nil, nil
	if TH and TH.colours then a, b = TH.colours(id) end
	local function c3(t) return t and Color3.fromRGB(t[1], t[2], t[3]) or Color3.new(1, 1, 1) end
	return c3(a), c3(b)
end
UI._themeTier = function(info)
	return (tostring(info.tierLabel or "") .. "  -  " .. tostring(info.editionLabel or "")):upper()
end


UI._themePanel = function(id, anchor)
	local TH = System and System.Themes
	if UI._tpv.frame and UI._tpv.id == id then UI._tpvClose() return end
	UI._tpvClose()
	local info = TH and TH.info(id)
	local root = anchor and UI.panelRootOf(anchor)
	local screen = root and root:FindFirstAncestorWhichIsA("LayerCollector")
	if not (info and root and screen) then return end
	local W, HEAD, FOOT = 270, 50, 52
	local st = UI._themeStyle(info)
	local c1, c2 = UI._themeCols(id)
	local f = new("TextButton", { Name = "ThemePanel", Text = "", AutoButtonColor = false, BackgroundColor3 = T.bg, BorderSizePixel = 0, Size = UDim2.fromOffset(W, 420), ZIndex = 20, Active = true, Parent = screen })
	corner(f, 14); pcall(stroke, f, T.line, 1); pcall(_KR.addShadow, f)
	local us = new("UIScale", { Parent = f })
	local tok = {}
	local P = { frame = f, id = id, conns = {}, tok = tok }
	UI._tpv = P
	local function conn(sig, fn) P.conns[#P.conns + 1] = sig:Connect(fn) end

	lbl({ Position = UDim2.fromOffset(14, 10), Size = UDim2.new(1, -52, 0, 18), Text = tostring(info.name or id), Font = FONTB, TextSize = 15, TextTruncate = Enum.TextTruncate.AtEnd, TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 21, Parent = f })
	UI._themeTint(lbl({ Position = UDim2.fromOffset(14, 29), Size = UDim2.new(1, -52, 0, 14), Text = UI._themeTier(info), Font = st and Enum.Font[st.f] or FONTB, TextColor3 = T.txt2, TextSize = 11.5, TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 21, Parent = f }), st)
	local xb = new("TextButton", { AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -10, 0, 10), Size = UDim2.fromOffset(28, 28), BackgroundColor3 = T.card, AutoButtonColor = false, Text = "x", Font = FONTB, TextSize = 14, TextColor3 = T.txt2, ZIndex = 21, Parent = f }); corner(xb, 8)
	xb.MouseButton1Click:Connect(UI._tpvClose)
	local sc = new("ScrollingFrame", { BackgroundTransparency = 1, BorderSizePixel = 0, Position = UDim2.fromOffset(10, HEAD), Size = UDim2.new(1, -20, 1, -(HEAD + FOOT)), CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y, ScrollBarThickness = 3, ZIndex = 21, Parent = f })

	local wear = new("TextButton", { AnchorPoint = Vector2.new(0, 1), Position = UDim2.new(0, 10, 1, -10), Size = UDim2.new(0.5, -15, 0, 34), BackgroundColor3 = T.accentD, AutoButtonColor = false, Text = "", Font = FONTB, TextSize = 13, TextColor3 = T.txt, ZIndex = 21, Parent = f }); corner(wear, 9)
	local close = new("TextButton", { AnchorPoint = Vector2.new(1, 1), Position = UDim2.new(1, -10, 1, -10), Size = UDim2.new(0.5, -15, 0, 34), BackgroundColor3 = T.bg2, AutoButtonColor = false, Text = "Close", Font = FONTB, TextSize = 13, TextColor3 = T.txt2, ZIndex = 21, Parent = f }); corner(close, 9)
	close.MouseButton1Click:Connect(UI._tpvClose)
	wear.MouseButton1Click:Connect(function()
		if TH.worn() == id then TH.remove() else TH.wear(id) end
	end)

	local function chip(parent, text, on, order, fn)
		local b = new("TextButton", { AutoButtonColor = false, Text = text, Font = FONTB, TextSize = 12, TextColor3 = on and T.txt or T.txt2, BackgroundColor3 = on and T.accentD or T.card, BorderSizePixel = 0, LayoutOrder = order, ZIndex = 22, Parent = parent }); corner(b, 8)
		pcall(_KR.press, b)
		b.MouseButton1Click:Connect(fn)
		return b
	end
	local function grid(order, n)
		local g = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, -6, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = order, ZIndex = 21, Parent = sc })
		new("UIGridLayout", { CellSize = UDim2.new(1 / n, -6, 0, 30), CellPadding = UDim2.fromOffset(6, 6), SortOrder = Enum.SortOrder.LayoutOrder, Parent = g })
		return g
	end
	local function note(text, order, col)
		return lbl({ Size = UDim2.new(1, -6, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = order, Text = text, TextColor3 = col or T.txt2, TextSize = 12, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 21, Parent = sc })
	end
	local function caption(text, order)
		return lbl({ Size = UDim2.new(1, -6, 0, 16), LayoutOrder = order, Text = text, Font = FONTB, TextColor3 = T.txt, TextSize = 12.5, TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 21, Parent = sc })
	end

	local function preview(kind)
		local F = System.StaffFx
		local a, b = TH.colours(id)
		local ok = F and F.previewTheme and F.previewTheme(LocalPlayer.UserId, kind, { theme = id, c1 = a, c2 = b, respawn = "short" })
		if not ok then toast("Themes", "Can't preview right now. Wait for the current effect to finish, then try again.", "warn") end
	end
	local function render()
		if UI._tpv.tok ~= tok or not f.Parent then return end
		if not TH.info(id) or not TH.has(TH.wearable(), id) then UI._tpvClose() return end
		for _, c in ipairs(sc:GetChildren()) do c:Destroy() end
		vlist(sc, 8)
		local worn = TH.worn() == id
		wear.Text = worn and "Remove" or "Wear"

		local hero = new("Frame", { BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0, Size = UDim2.new(1, -6, 0, 118), LayoutOrder = 1, ZIndex = 21, Parent = sc }); corner(hero, 10)
		new("UIGradient", { Rotation = 35, Color = ColorSequence.new(c1:Lerp(Color3.new(0, 0, 0), 0.45), c2:Lerp(Color3.new(0, 0, 0), 0.62)), Parent = hero })
		lbl({ AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.36), Size = UDim2.new(1, -20, 0, 30), Text = tostring(info.name or id):upper(), Font = st and Enum.Font[st.f] or FONTB, TextScaled = true, TextColor3 = Color3.new(1, 1, 1), TextStrokeTransparency = 0.55, TextXAlignment = Enum.TextXAlignment.Center, ZIndex = 22, Parent = hero })
		UI._themeTint(lbl({ AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.fromScale(0.5, 0.6), Size = UDim2.new(1, -20, 0, 16), Text = tostring(info.tierLabel or ""):upper(), Font = st and Enum.Font[st.f] or FONTB, TextSize = 15, TextXAlignment = Enum.TextXAlignment.Center, ZIndex = 22, Parent = hero }), st)
		lbl({ AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.fromScale(0.5, 0.78), Size = UDim2.new(1, -20, 0, 12), Text = tostring(info.editionLabel or ""):upper(), TextColor3 = Color3.fromRGB(225, 225, 235), TextSize = 11, TextXAlignment = Enum.TextXAlignment.Center, ZIndex = 22, Parent = hero })

		if worn then
			note("You are wearing this theme.", 2, T.good)
			if not TH.syncOn() then note("Avatar Sync is off, so only you can see it. Turn it on in Settings.", 3, T.warn) end
		else
			note("Not worn. Tap Wear to put it on.", 2, T.txt3)
		end

		local n = TH.slots(id)
		if n > 0 then
			caption("Respawn effect", 4)
			if worn then
				local g = grid(5, math.min(n + 1, 3))
				local cur = TH.short()
				chip(g, "Random", cur == 0, 0, function() TH.setShort(0) end)
				for i = 1, n do chip(g, "Short " .. i, cur == i, i, function() TH.setShort(i) end) end
			else
				note("Wear this theme to choose which respawn effect plays.", 5, T.txt3)
			end
		end

		caption("Preview on you", 6)
		note("Only you see a preview. It plays once on your character.", 7, T.txt3)
		local g = grid(8, 2)
		chip(g, "Arrival", false, 0, function() preview("full") end)
		for i = 1, n do chip(g, "Respawn " .. i, false, i, function() preview("short:" .. i) end) end
		if info.death or id == "seraph" or id == "starfall" or id == "radius" or id == "ninelives" or id == "error404" or id == "playerone" or id == "bigspender" then
			chip(g, "Death", false, 99, function() preview("death") end)
		end
	end
	render()
	if UI._tpv.tok ~= tok then return end
	P.render = render
	local tc = TH.changed:Connect(function() task.defer(render) end)
	P.conns[#P.conns + 1] = tc

	local function place()
		if UI._tpv.tok ~= tok then return end
		if not (root.Parent and root.Visible and anchor.Parent and anchor:IsDescendantOf(root)) then UI._tpvClose() return end
		local rs = root:FindFirstChildOfClass("UIScale")
		local s = (rs and rs.Scale > 0) and rs.Scale or 1
		us.Scale = s
		local sp, ss = screen.AbsolutePosition, screen.AbsoluteSize
		local rp, rsz = root.AbsolutePosition - sp, root.AbsoluteSize
		local w, gap = W * s, 10
		local x, y, h
		if rp.X >= w + gap + 6 then x, y, h = rp.X - w - gap, rp.Y, rsz.Y
		elseif ss.X - (rp.X + rsz.X) >= w + gap + 6 then x, y, h = rp.X + rsz.X + gap, rp.Y, rsz.Y
		else x, y, h = rp.X + 8, rp.Y + 8, rsz.Y - 16 end
		local wpx = math.min(w, math.max(160 * s, ss.X - 12))
		h = math.min(math.clamp(h, 260 * s, 560 * s), math.max(200 * s, ss.Y - 12))
		x = math.clamp(x, 6, math.max(6, ss.X - wpx - 6))
		y = math.clamp(y, 6, math.max(6, ss.Y - h - 6))
		f.Position = UDim2.fromOffset(math.floor(x), math.floor(y))
		f.Size = UDim2.fromOffset(math.floor(wpx / s), math.floor(h / s))
	end
	place()
	conn(root:GetPropertyChangedSignal("AbsolutePosition"), place)
	conn(root:GetPropertyChangedSignal("AbsoluteSize"), place)
	conn(root:GetPropertyChangedSignal("Visible"), place)
	conn(screen:GetPropertyChangedSignal("AbsoluteSize"), place)
	conn(anchor.AncestryChanged, place)
	pcall(_KR.skinPass, f)
end

function PAGES.themes(h)
	local TH = System and System.Themes
	if not TH then return end
	local TP = TH.ui or { failed = {}, busy = {} }
	TH.ui = TP
	local box = new("Frame", { Name = "ThemesBox", BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 1, Parent = h }); vlist(box, 9)
	local conn
	local function line(parent, text, order, col)
		return lbl({ Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, Text = text, TextColor3 = col or T.txt2, TextSize = 13, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, LayoutOrder = order, Parent = parent })
	end
	local redraw
	redraw = function()
		if not box.Parent then if conn then conn.Disconnect() end return end
		for _, c in ipairs(box:GetChildren()) do if not c:IsA("UIListLayout") then c:Destroy() end end
		local o = 0
		local function nx() o += 1 return o end
		if not TH.syncOn() then line(box, "Turn on Avatar Sync in Settings so others can see your theme.", nx(), T.txt3) end

		local ask = TP.ask and TH.info(TP.ask) and TP.ask
		if ask then
			local tl = tile(box, "New theme", nx())
			line(tl, "Equip now?", 1, T.txt)
			local yn = cols(tl, 2, 2)
			UI.button(yn[1], "Yes", "primary", 1, function() TP.ask = nil; TH.equipNow(ask); redraw() end)
			UI.button(yn[2], "No", nil, 1, function() TP.ask = nil; redraw() end)
		else

			local id = TH.noteId()
			local info = id and TH.info(id)
			if id then
				local tl = tile(box, "Giveaway", nx())
				local tier = info and info.tierLabel or "special"
				line(tl, "Congratulations! You won a giveaway and received a " .. tostring(tier) .. " personal theme.", 1, T.txt)
				local txt = TP.busy[id] and "Claiming..." or (TP.failed[id] and "Claim failed - tap to retry" or "Claim")
				UI.button(tl, txt, "primary", 2, function()
					if TP.busy[id] then return end
					TP.busy[id] = true; redraw()
					TH.claim(id, function(ok)
						TP.busy[id] = nil
						TP.failed[id] = not ok or nil
						if ok then TP.ask = id end
						redraw()
					end)
				end)
			end
		end

		local pending = {}
		for _, u in ipairs(TH.unclaimed()) do pending[u] = true end
		local worn = TH.worn()
		local ids = {}
		for _, id in ipairs(TH.wearable()) do if TH.info(id) and not pending[id] then ids[#ids + 1] = id end end
		table.sort(ids, function(a, b)
			if (a == worn) ~= (b == worn) then return a == worn end
			local ra, rb = TH.rank(a), TH.rank(b)
			if ra ~= rb then return ra > rb end
			return tostring(TH.info(a).name or a) < tostring(TH.info(b).name or b)
		end)
		local owned = #ids
		if owned > 0 then
			lbl({ Size = UDim2.new(1, 0, 0, 18), Text = "Your themes", Font = FONTB, TextSize = 14, TextColor3 = T.txt, TextXAlignment = Enum.TextXAlignment.Left, LayoutOrder = nx(), Parent = box })


			local function vals(field)
				local seen, out = {}, { "All" }
				for _, id in ipairs(ids) do
					local v = tostring(TH.info(id)[field] or "")
					if v ~= "" and not seen[v] then seen[v] = true out[#out + 1] = v end
				end
				return out
			end
			local tiers, eds = vals("tierLabel"), vals("editionLabel")
			if TP.fTier and not table.find(tiers, TP.fTier) then TP.fTier = nil end
			if TP.fEd and not table.find(eds, TP.fEd) then TP.fEd = nil end
			if #tiers > 2 then UI.dropdown(box, "Tier", tiers, nx(), function(v) TP.fTier = v ~= "All" and v or nil redraw() end) end
			if #eds > 2 then UI.dropdown(box, "Edition", eds, nx(), function(v) TP.fEd = v ~= "All" and v or nil redraw() end) end
			if TP.fTier or TP.fEd then
				local keep = {}
				for _, id in ipairs(ids) do
					local info = TH.info(id)
					if id == worn or ((not TP.fTier or tostring(info.tierLabel) == TP.fTier) and (not TP.fEd or tostring(info.editionLabel) == TP.fEd)) then keep[#keep + 1] = id end
				end
				ids = keep
			end
			local items = {}
			for _, id in ipairs(ids) do
				local info = TH.info(id)
				local sub = tostring(info.tierLabel or ""):upper()
				items[#items + 1] = {
					name = tostring(info.name or id), sub = sub,
					preview = function(c)
						local st = UI._themeStyle(info)
						for _, l in ipairs(c:GetChildren()) do if l:IsA("TextLabel") and l.Text == sub then l.Font = st and Enum.Font[st.f] or l.Font UI._themeTint(l, st) end end

						lbl({ Position = UDim2.new(0, 0, 0, 36), Size = UDim2.new(1, 0, 0, 14), Text = tostring(info.editionLabel or ""):upper(), Font = FONTB, TextColor3 = T.txt3, TextSize = 10.5, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd, Parent = c })

						if id == worn then
							local hl = new("Frame", { Name = "WornGlow", Position = UDim2.new(0, -11, 0, -8), Size = UDim2.new(1, 22, 1, 16), BackgroundColor3 = Color3.new(1, 1, 1), BackgroundTransparency = 0.8, BorderSizePixel = 0, ZIndex = 0, Parent = c }); corner(hl, 9)
							local ca, cb = UI._themeCols(id)
							new("UIGradient", { Rotation = 20, Color = ColorSequence.new(ca, cb), Transparency = NumberSequence.new(0.1, 0.6), Parent = hl })
						end

						local a, b = UI._themeCols(id)
						local strip = new("Frame", { AnchorPoint = Vector2.new(0, 1), Position = UDim2.new(0, 0, 1, 0), Size = UDim2.new(0.42, 0, 0, 4), BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0, Parent = c }); corner(strip, 2)
						new("UIGradient", { Color = ColorSequence.new(a, b), Parent = strip })
					end,
					onClick = function() UI._themePanel(id, box) end,
				}
			end
			UI.tiles(box, items, nx(), 80)
		end

		if owned == 0 and not TH.noteId() and not ask then line(box, "No themes yet. Themes come from giveaways; when you win one it shows up here to claim.", nx(), T.txt3) end

		if TH.pageExtras then
			local ok, err = pcall(TH.pageExtras, box, nx())
			if not ok then warn("[RoClothes] themes extras: " .. tostring(err)) end
		end
		pcall(_KR.skinPass, box)
	end
	redraw()
	conn = TH.changed:Connect(function() task.defer(redraw) end)
end



