	player = "Target, actions, current look, clones.", body = "Types, scale, fit, physics, first person.", clothes = "Equip, search, recolour.",
	damage = "HP mode, clothing tear and SFX.",
	catalog = "Roblox marketplace.", bundles = "Saved outfits and community.",
