_KR.sideColW = function(vpX) return math.max(160, math.min(math.clamp(math.floor(vpX * 0.24), 220, 460), math.floor((vpX - 2 * 12 - 140) / 2))) end




_KR.soloTab = function(id) return id == "admin" end
_KR.soloColW = function(vpX)
	local narrow = _KR.sideColW(vpX)
	if vpX < 1000 then return narrow end
	return math.max(narrow, math.min(math.floor(vpX * 0.66), vpX - 2 * 12 - 320))
end
local function panelOpenRect(pw, dockOverride)
	local dock = dockOverride or SET._panelDock or "bar"
	local off = BAR_Y + math.floor(BAR_H * UISCALE * (SET.barSize or 1)) + 6 + math.floor(PANEL_H * UISCALE / 2) + _KR.topInset()
	pw = pw or _KR._panelFullW or PANEL_W
	if dock == "left" or dock == "right" then
		local vp2 = (workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize) or Vector2.new(1280, 720)
		local margin, gap = 12, 10
		local topInset = 0; pcall(function() topInset = game:GetService("GuiService"):GetGuiInset().Y end)
		local topMargin = math.max(margin, topInset + gap)
		local sideW = _KR.soloTab(_KR._panelTab) and _KR.soloColW(vp2.X) or _KR.sideColW(vp2.X)
		local barClear = BAR_Y + math.ceil(BAR_H * UISCALE * (SET.barSize or 1)) + gap + _KR.topInset() + ((SET.barStyle ~= "Minimal") and math.floor(18 * UISCALE) or 0)
		if SET.barStyle == "Minimal" then barClear = margin end
		local cTop, cBot
		if SET.barTop then cTop, cBot = math.max(barClear, topMargin), vp2.Y - margin
		else cTop, cBot = topMargin, vp2.Y - barClear end
		local h = math.max(120, cBot - cTop)
		local shiftL = (SET.barStyle == "Minimal" and dock == "left") and (_KR.colW() + 14) or 0
		sideW = math.max(160, sideW - shiftL)
		local cx = (dock == "left") and (margin + shiftL) or (vp2.X - margin - sideW)
		return UDim2.fromOffset(math.floor(cx + sideW / 2), math.floor(cTop + h / 2)),
		       UDim2.fromOffset(math.floor(sideW / UISCALE), math.floor(h / UISCALE))
	end
	local pos = (dock == "top") and UDim2.new(0.5, 0, 0, off) or (SET.barTop and UDim2.new(0.5, 0, 0, off) or UDim2.new(0.5, 0, 1, -off))
	if dock == "bar" and SET.barStyle == "Taskbar" then
		local o2 = off + math.floor(18 * UISCALE)
		pos = UDim2.new(0, 14 + math.floor(pw * UISCALE / 2), SET.barTop and 0 or 1, SET.barTop and o2 or -o2)
	elseif dock == "bar" and SET.barStyle == "Minimal" then
		pos = UDim2.new(0, 14 + _KR.colW() + 12 + math.floor(pw * UISCALE / 2), 0.5, 0)
	end
	return pos, UDim2.fromOffset(pw, PANEL_H)
end
