end
local function buildPageInto(host, sticky, id)
	local editStays = host ~= pageHost and MP.panels.edit ~= nil
	if not editStays then
		if _curPage == "edit" and id ~= "edit" and System and System.hideGizmo3D then pcall(System.hideGizmo3D) end
		if id ~= "edit" and _KR.editBar then pcall(_KR.editBar.hide) end
