	end
	activeTab = id; _KR._panelTab = id; activeBtn = btn; activeColor = color or T.accent; setActive(id); pTitle.Text = label or id; pDesc.Text = SECTION_DESC[id] or ""; setHeadIcon(id); _KR.headLay(); buildPage(id)
