	if SET.cardAnims and not SET.reduceMotion then
		local _op, _os = panelOpenRect(pw); _KR.spring(panel, "Position", _op, 2.4, 1); _KR.spring(panel, "Size", _os, 2.4, 1); tween(panel, 0.6, { BackgroundColor3 = T.bg }, QUINT)
		tween(panelCorner, 0.6, { CornerRadius = UDim.new(0, math.floor(_KR.skin().panelR * _KR.cornerScale + 0.5)) }, QUINT); tween(panel, 0.6, { BackgroundTransparency = math.max(_KR.skin().panelT, _KR.glass) }, QUINT)
		tween(panelStroke, 0.55, { Transparency = 0 })
