			tween(panelStroke, 0.28, { Transparency = 1 })
			task.delay(0.45 * SPEED + 0.05, function() if not panelOpen then panel.Visible = false; dropPage() end end)
		end)
	else
		_KR.springStop(panel, "Position", "Size"); panel.Visible = false; dropPage()
	end
end
local function onTabClick(id, label, color, btn)
