				end
			end
		end)
		f.Destroying:Connect(function() pcall(function() mc:Disconnect() end) pcall(function() me:Disconnect() end) if MP.userZone then MP.userZone[id] = nil end if MP._dragging == id then MP._dragging = nil; MP.dragGhost(nil) end end)
