local function refreshPreview()
	if _KR.saveCfg then _KR.saveCfg() end
	if not _KR._prevKey or _KR._prevPend then return end
	local function go() _KR._prevPend = nil; _KR._prevLast = os.clock(); if _KR._prevKey then local k, l = _KR._prevKey, _KR._prevLabel; _KR._prevKey = nil; renderPreview(k, l) end end
	local wait = 0.15 - (os.clock() - (_KR._prevLast or 0))
	if wait <= 0 then go() else _KR._prevPend = true; task.delay(wait, go) end
end
