_KR.lookStep = function(dir)
	local title = (dir < 0) and "Look undo" or "Look redo"
	local f = System and ((dir < 0) and System.lookUndo or System.lookRedo)
	if not f then toast(title, "RoClothes is still loading.", "warn"); return end
	local ok, res = f()
	toast(title, ok and (((dir < 0) and "Back to: " or "Forward to: ") .. tostring(res)) or tostring(res), ok and "ok" or "info")
end






_KR.freecamStep = function(pos, yaw, pitch, vel, dt)
	local cf = CFrame.new(pos) * CFrame.fromOrientation(pitch, yaw, 0)
	local p = pos + cf:VectorToWorldSpace(vel) * dt
	return p, CFrame.new(p) * CFrame.fromOrientation(pitch, yaw, 0)
end

_KR.isOverheadGui = function(g)
	local a = g.Adornee or g.Parent
	if a and a:IsA("Attachment") then a = a.Parent end
	if not a then return false end
	local m = a:IsA("Model") and a or a:FindFirstAncestorOfClass("Model")
	return m ~= nil and m:FindFirstChildOfClass("Humanoid") ~= nil
end







do

	local H = { others = false, names = false, ltm = {}, tag = {}, bb = {}, pend = {}, t = 0 }
	_KR.photoHide = H
	local NONE = Enum.HumanoidDisplayDistanceType.None
	local function LP() return game:GetService("Players").LocalPlayer end
	local function hideTag(d)
		if d:IsA("Humanoid") then
			if H.tag[d] == nil or d.DisplayDistanceType ~= NONE then H.tag[d] = d.DisplayDistanceType end
			d.DisplayDistanceType = NONE
		elseif d:IsA("BillboardGui") then
			if not _KR.isOverheadGui(d) then H.pend[d] = true return end
			H.pend[d] = nil
			if H.bb[d] == nil or d.Enabled then H.bb[d] = d.Enabled end
			d.Enabled = false
		end
	end

	function H.prune(t) for k in pairs(t) do if not k:IsDescendantOf(game) then t[k] = nil end end end
	local function hideOtherRoot(root)
		for _, d in ipairs(root:GetDescendants()) do
			if d:IsA("BasePart") or d:IsA("Decal") then
				if H.ltm[d] == nil or d.LocalTransparencyModifier ~= 1 then H.ltm[d] = d.LocalTransparencyModifier end
				d.LocalTransparencyModifier = 1
			else
				hideTag(d)
			end
		end
	end
	local function sweepOthers()
		local lp = LP()
		local m2f = System and System.M2FName and workspace:FindFirstChild(System.M2FName)
		for _, plr in ipairs(game:GetService("Players"):GetPlayers()) do
			if plr ~= lp then
				for _, root in ipairs({ plr.Character or false, (m2f and m2f:FindFirstChild(plr.Name)) or false }) do
					if root then hideOtherRoot(root) end
				end
			end
		end
		for key, rig in pairs(System and System.NPCs or {}) do
			if type(key) == "string" and key:sub(1, 8) == "_pclone_" and typeof(rig) == "Instance" then hideOtherRoot(rig) end
		end
	end
	local function giveBackTags()
		for g, v in pairs(H.bb) do pcall(function() g.Enabled = v end) end
		for h, v in pairs(H.tag) do pcall(function() h.DisplayDistanceType = v end) end
		H.bb, H.tag, H.pend = {}, {}, {}
	end

	local function wire()
		local on = H.others or H.names
		if on and System then System._photoHideRestore = H.restoreAll end
		if H.namesW then H.namesW:Disconnect(); H.namesW = nil end
		if H.namesP then H.namesP:Disconnect(); H.namesP = nil end
		if H.names then
			local gameGui = LP():FindFirstChildOfClass("PlayerGui")
			local function added(d)
				if d:IsA("Humanoid") or d:IsA("BillboardGui") then task.defer(function() if H.names then pcall(hideTag, d) end end) end
			end
			H.namesW = workspace.DescendantAdded:Connect(added)
			if gameGui then H.namesP = gameGui.DescendantAdded:Connect(added) end
		end
		if on and not H.loop then
			H.loop = game:GetService("RunService").Heartbeat:Connect(function(dt)
				H.t += dt
				if H.t < 0.5 then return end
				H.t = 0
				H.n = (H.n or 0) + 1
				if H.n % 10 == 0 then H.prune(H.bb); H.prune(H.tag); H.prune(H.ltm); H.prune(H.pend) end
				if H.names then
					for g in pairs(H.pend) do pcall(hideTag, g) end
					for g in pairs(H.bb) do if g.Parent and g.Enabled then H.bb[g] = true; g.Enabled = false end end
					for h in pairs(H.tag) do if h.Parent and h.DisplayDistanceType ~= NONE then H.tag[h] = h.DisplayDistanceType; h.DisplayDistanceType = NONE end end
				end
				if H.others then pcall(sweepOthers) end
			end)
		elseif not on and H.loop then
			H.loop:Disconnect(); H.loop = nil
		end
	end
	function H.setNames(on)
		H.names = on and true or false
		if H.names then
			local gameGui = LP():FindFirstChildOfClass("PlayerGui")
			for _, root in ipairs({ workspace, gameGui or false }) do
				if root then for _, d in ipairs(root:GetDescendants()) do pcall(hideTag, d) end end
			end
		else
			giveBackTags()
			if H.others then pcall(sweepOthers) end
		end
		wire()
	end
	function H.setOthers(on)
		H.others = on and true or false
		if H.others then
			pcall(sweepOthers)
		else
			for d, v in pairs(H.ltm) do pcall(function() d.LocalTransparencyModifier = v end) end
			H.ltm = {}
			if not H.names then giveBackTags() end
		end
		wire()
	end
	function H.restoreAll()
		H.names = false
		pcall(H.setOthers, false)
		giveBackTags()
		wire()
	end
end
_KR.photo = function()
