		if subject then cam.CameraSubject = subject end
		if st.camCF then cam.CFrame = st.camCF end
	end

	local fc, fcPos, fcYaw, fcPitch, fcLook, fcTouch, fcPadTouch = false, nil, 0, 0, false, nil, nil
	local fcVel, fcPadVec, fcVert, fcMouse = Vector3.zero, Vector2.zero, 0, nil
	local setS, setFcBtn
	local lv = { on = false }
	local CAS, GS = game:GetService("ContextActionService"), game:GetService("GuiService")
	local K = Enum.KeyCode
	local FC_KEYS = { K.W, K.A, K.S, K.D, K.Q, K.E, K.Up, K.Down, K.Left, K.Right, K.Space, K.LeftShift, K.Thumbstick1, K.ButtonA }
	local fcUi = new("Frame", { Name = "FreeCamControls", BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), Visible = false, Parent = sg })
	local fcPad = new("Frame", { BackgroundColor3 = T.bg, BackgroundTransparency = 0.45, BorderSizePixel = 0, Active = true, AnchorPoint = Vector2.new(0, 1), Position = UDim2.new(0, vert and 26 + 150 * tbScale or 22, 1, -96), Size = UDim2.fromOffset(120, 120), Parent = fcUi }); corner(fcPad, 60)
	local fcKnob = new("Frame", { BackgroundColor3 = T.accent, BackgroundTransparency = 0.2, BorderSizePixel = 0, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromOffset(44, 44), Parent = fcPad }); corner(fcKnob, 22)
	for i, d in ipairs({ { "Up", 1 }, { "Down", -1 } }) do
		local b = new("TextButton", { AutoButtonColor = false, Text = d[1], Font = FONTB, TextSize = 13, TextColor3 = T.txt, BackgroundColor3 = T.bg, BackgroundTransparency = 0.35, BorderSizePixel = 0, AnchorPoint = Vector2.new(1, 1), Position = UDim2.new(1, -22, 1, -96 - (2 - i) * 62), Size = UDim2.fromOffset(72, 54), Parent = fcUi }); corner(b, 14)
		b.MouseButton1Down:Connect(function() fcVert = d[2] end)
