	local fcHint = lbl({ AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0, 58), Size = UDim2.new(1, -40, 0, 20), Visible = false, Font = FONTB, TextSize = 13, TextColor3 = Color3.new(1, 1, 1), Text = UserInputService.TouchEnabled and "Drag to look. Use the pad to move." or "Hold right mouse to look. WASD moves, Q and E go down and up, Shift is faster.", Parent = sg })
	new("UIStroke", { Thickness = 1, Transparency = 0.4, Parent = fcHint })
	local function fcPadTo(pos)
		local c = fcPad.AbsolutePosition + fcPad.AbsoluteSize / 2
		local v = Vector2.new(pos.X, pos.Y) - c
		if v.Magnitude > 50 then v = v.Unit * 50 end
		fcPadVec = v / 50
		fcKnob.Position = UDim2.new(0.5, v.X, 0.5, v.Y)
	end
	fcPad.InputBegan:Connect(function(i)
		if i.UserInputType == Enum.UserInputType.Touch then fcPadTouch = i; fcPadTo(i.Position) end
	end)
	local function setFree(on)
		if on == fc or not cam then return end
		fc = on
		if on then
			if spin then setSpin(false); if setS then setS(false) end end
			fcPos = cam.CFrame.Position
			fcPitch, fcYaw = cam.CFrame:ToOrientation()
			fcVel, fcPadVec, fcVert = Vector3.zero, Vector2.zero, 0
