			pcall(function() CAS:BindActionAtPriority("RCPhotoFreeCam", function() return Enum.ContextActionResult.Sink end, false, 3000, table.unpack(FC_KEYS)) end)
			pcall(function() st.touchControls = GS.TouchControlsEnabled; GS.TouchControlsEnabled = false end)
			fcUi.Visible = UserInputService.TouchEnabled and tb.Visible
			fcHint.Visible = tb.Visible
		else
