	conns.fcEnded = UserInputService.InputEnded:Connect(function(i)
		if i == fcPadTouch then fcPadTouch = nil; fcPadVec = Vector2.zero; fcKnob.Position = UDim2.fromScale(0.5, 0.5)
		elseif i == fcTouch then fcTouch = nil
