			fcLook = false
			if fcMouse then UserInputService.MouseBehavior = fcMouse; fcMouse = nil end
		end
	end)
	local function fcStep(dt)
		local U = UserInputService
		if fcLook then
			local d = U:GetMouseDelta()
			local f = 0.004 * (cam.FieldOfView / 70)
			fcYaw -= d.X * f
			fcPitch = math.clamp(fcPitch - d.Y * f, -1.5, 1.5)
		end
		local function k(c) return U:IsKeyDown(c) and 1 or 0 end
		local mv = Vector3.new(
			k(K.D) + k(K.Right) - k(K.A) - k(K.Left) + fcPadVec.X,
			k(K.E) - k(K.Q) + fcVert,
			k(K.S) + k(K.Down) - k(K.W) - k(K.Up) + fcPadVec.Y)
		local want = mv * (U:IsKeyDown(K.LeftShift) and 48 or 16) * (lv.on and 0.35 or 1)
		fcVel = fcVel:Lerp(want, math.min(1, dt * 10))
		local cf
		fcPos, cf = _KR.freecamStep(fcPos, fcYaw, fcPitch, fcVel, dt)
