		if lv.on and System and System.Lights and not System.Lights.viewApply(cf) then lv.stop(false) end
	end


	lv.bar = new("Frame", { Name = "LightView", AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0, 86), Size = UDim2.fromOffset(0, 44), AutomaticSize = Enum.AutomaticSize.X, BackgroundColor3 = T.bg, BackgroundTransparency = 0.12, BorderSizePixel = 0, Visible = false, Parent = sg })
	corner(lv.bar, square and 4 or 22); pad(lv.bar, 14, 6, 6, 6)
