		if lv.wasFree then fcPos = lv.prev.Position; fcPitch, fcYaw = lv.prev:ToOrientation(); fcVel = Vector3.zero
		else pcall(setFree, false); pcall(function() cam.CFrame = lv.prev end) end
		local pl = _KR.photoLights
		if pl and pl.f then pl.f.Visible = pl.open and SET.photoTab == "Look" and tb.Visible end
	end
	_KR.lightView = lv.start
	local FILTERS = {
		Warm = { Brightness = 0.02, Contrast = 0.08, Saturation = 0.1, TintColor = Color3.fromRGB(255, 236, 214) },
		Cool = { Brightness = 0.01, Contrast = 0.08, Saturation = 0.05, TintColor = Color3.fromRGB(214, 230, 255) },
		Vivid = { Contrast = 0.15, Saturation = 0.45 },
		Mono = { Contrast = 0.1, Saturation = -1 },
		Noir = { Brightness = -0.04, Contrast = 0.45, Saturation = -1 },
	}
	local FORDER = { "None", "Warm", "Cool", "Vivid", "Mono", "Noir" }
	local function applyFilter(name)
		local f = FILTERS[name]
		if not f then if cc then cc:Destroy(); cc = nil end; return end
		cc = cc or new("ColorCorrectionEffect", { Name = "RCPhotoFilter", Parent = cam })
		cc.Brightness = f.Brightness or 0; cc.Contrast = f.Contrast or 0; cc.Saturation = f.Saturation or 0; cc.TintColor = f.TintColor or Color3.new(1, 1, 1)
	end
	local exit



	local groups, tabSet = { Camera = {}, Pose = {}, Look = {} }, {}
	local adj, adjOpen = nil, false
	local function showTab(name)
		SET.photoTab = name
		for g, list in pairs(groups) do for _, b in ipairs(list) do b.Visible = (g == name) end end
		if adj then adj.Visible = adjOpen and name == "Look" and tb.Visible end
		local pl = _KR.photoLights; if pl and pl.f then pl.f.Visible = pl.open and name == "Look" and tb.Visible and not lv.on; pcall(function() System.Lights.ghost(pl.f.Visible) end) end
		for g, set in pairs(tabSet) do set(g == name) end
	end
	local function tool(group, text, order, cb)
		local b, set = btn(text, 10 + order, cb); table.insert(groups[group], b); return b, set
	end
	for i, g in ipairs({ "Camera", "Pose", "Look" }) do
		local tb_, set = btn(g, i, function() showTab(g) end); tabSet[g] = set
		tb_.BackgroundTransparency = 0.15
	end
	for _, order in ipairs({ 5, 89 }) do
		new("Frame", { BackgroundColor3 = T.txt2, BackgroundTransparency = 0.6, BorderSizePixel = 0, LayoutOrder = order, Size = vert and UDim2.new(1, -16, 0, 1) or UDim2.fromOffset(1, 22), Parent = tb })
	end

	local _; _, setS = tool("Camera", "Spin", 1, function()
		if not spin then setFree(false) end
		setSpin(not spin); setS(spin)
	end)
	_, setFcBtn = tool("Camera", "Free cam", 5, function() setFree(not fc) end)
	tool("Camera", "Zoom in", 2, function() if cam then cam.FieldOfView = math.max(20, cam.FieldOfView - 10) end end)
	tool("Camera", "Zoom out", 3, function() if cam then cam.FieldOfView = math.min(100, cam.FieldOfView + 10) end end)
	local grid = new("Frame", { Name = "Grid", BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), Visible = false, ZIndex = 0, Parent = sg })
	for i = 1, 2 do
		new("Frame", { BackgroundColor3 = Color3.new(1, 1, 1), BackgroundTransparency = 0.55, BorderSizePixel = 0, Position = UDim2.fromScale(i / 3, 0), Size = UDim2.new(0, 1, 1, 0), Parent = grid })
		new("Frame", { BackgroundColor3 = Color3.new(1, 1, 1), BackgroundTransparency = 0.55, BorderSizePixel = 0, Position = UDim2.fromScale(0, i / 3), Size = UDim2.new(1, 0, 0, 1), Parent = grid })
	end
	local _, setG; _, setG = tool("Camera", "Grid", 4, function() grid.Visible = not grid.Visible; setG(grid.Visible) end)

	local _, setF = tool("Pose", "Freeze pose", 1, function() setFreeze(not frozen) end); setFreezeBtn = setF
	tool("Pose", "Turn me", 2, function()
