		applyFilter(FORDER[fi]); setFl(fi > 1, "Filter: " .. FORDER[fi])
	end)
	setFl(fi > 1); applyFilter(FORDER[fi])

	local PH = _KR.photoHide
	local _, setO; _, setO = tool("Look", "Hide others", 2, function()
		PH.setOthers(not PH.others); setO(PH.others)
	end)
	local _, setN; _, setN = tool("Look", "Hide names", 3, function()
		PH.setNames(not PH.names); setN(PH.names)
	end)
	setO(PH.others); setN(PH.names)
	do
