			pl.host = new("Frame", { Name = "LightsHost", BackgroundTransparency = 1, Size = UDim2.fromOffset(300, math.clamp(pl.vh / tbScale, 180, 560)), AnchorPoint = adj.AnchorPoint, Position = adj.Position, Parent = sg })
			pl.host:SetAttribute("PanelRoot", true); pl.host:SetAttribute("rcPickerW", 280)
			_KR.uis(new("UIScale", { Scale = tbScale, Parent = pl.host }), 0.85); corner(pl.host, square and 4 or 14)
			pl.f = new("ScrollingFrame", { BackgroundColor3 = T.bg, BackgroundTransparency = 0.08, BorderSizePixel = 0, Visible = false, Size = UDim2.fromScale(1, 1), CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y, ScrollBarThickness = 3, ScrollingDirection = Enum.ScrollingDirection.Y, Parent = pl.host })
			pl.f:GetPropertyChangedSignal("Visible"):Connect(function() if not pl.f.Visible and UI._dropClose then pcall(UI._dropClose) end end)
			corner(pl.f, square and 4 or 14)
