_KR.puckGeo = function(stage)
	local st = SET.barStyle or "Dock"
	local s = _KR.barPuck:FindFirstChildOfClass("UIScale"); local f = (s and s.Scale > 0) and s.Scale or UISCALE
	local g = { m = math.ceil(44 / f) }
	if st == "Taskbar" then
		local ay = SET.barTop and 0 or 1; local sg = SET.barTop and 1 or -1; local topY = SET.barTop and GUI_INSET.Y or 0
		g.ap, g.bg, g.bt, g.fr = Vector2.new(0, ay), _KR.light() and Color3.fromRGB(246, 246, 250) or Color3.fromRGB(34, 36, 44), 0.2, 6
		if stage == "start" then g.pos, g.w, g.h, g.r, g.fs, g.fy = UDim2.new(0, 0, ay, topY), BAR_H, BAR_H, 0, 22, 0
		else g.pos, g.w, g.h, g.r, g.fs, g.fy = UDim2.new(0, 8, ay, topY + sg * 8), 46, 46, 8, 26, -2 end
	elseif st == "Minimal" then
		g.ap, g.bg, g.bt, g.fy = Vector2.new(0.5, 0.5), _KR.light() and Color3.fromRGB(250, 250, 252) or Color3.fromRGB(14, 16, 22), _KR.light() and 0.25 or 0.42, 0
		g.pos = UDim2.new(0, 14 + math.floor(BAR_H * f / 2), 0.5, 0)
		if stage == "start" then g.w, g.h, g.fs = 26, 26, 20 else g.w, g.h, g.fs = 44, 44, 32 end
		g.r, g.fr = g.w / 2, g.fs / 2
	else
		local ax, pxS, pxO = 0.5, 0.5, 0
		if SET.barSide == "Left" then ax, pxS, pxO = 0, 0, 14 elseif SET.barSide == "Right" then ax, pxS, pxO = 1, 1, -14 end
		g.ap, g.bg, g.bt, g.fy = Vector2.new(ax, SET.barTop and 0 or 1), T.bg, _KR.glass or 0, 0
		g.pos = SET.barTop and UDim2.new(pxS, pxO, 0, BAR_Y) or UDim2.new(pxS, pxO, 1, -BAR_Y)
		if stage == "start" then g.w, g.h, g.fx, g.fs = BAR_H, BAR_H, 7, BAR_H - 14 else g.w, g.h, g.fx, g.fs = 72, 32, 4, 24 end
		g.r, g.fr = g.h / 2, g.fs / 2
	end
	return g
end
_KR.puckApply = function(stage, dur, ease)
	local g, P, F = _KR.puckGeo(stage), _KR.barPuck, _KR.puckFace
	local rest, st = stage == "rest", SET.barStyle or "Dock"
	P.AnchorPoint = g.ap; P.BackgroundColor3 = g.bg
	F.AnchorPoint = g.fx and Vector2.new(0, 0.5) or Vector2.new(0.5, 0.5)
	_KR.puckHit.Size = UDim2.fromOffset(math.max(g.w, g.m), math.max(g.h, g.m))
	local pp = { Position = g.pos, Size = UDim2.fromOffset(g.w, g.h) }
	local fp = { Position = g.fx and UDim2.new(0, g.fx, 0.5, g.fy) or UDim2.new(0.5, 0, 0.5, g.fy), Size = UDim2.fromOffset(g.fs, g.fs) }
	if dur then
		tween(P, dur, pp, ease); tween(F, dur, fp, ease)
		tween(_KR.puckCorner, dur, { CornerRadius = UDim.new(0, g.r) }); tween(_KR.puckFaceC, dur, { CornerRadius = UDim.new(0, g.fr) })
	else
		P.Position, P.Size, F.Position, F.Size = pp.Position, pp.Size, fp.Position, fp.Size
		_KR.puckCorner.CornerRadius = UDim.new(0, g.r); _KR.puckFaceC.CornerRadius = UDim.new(0, g.fr)
		if rest and _KR.barHidden and not bar.Visible then P.BackgroundTransparency = g.bt; F.ImageTransparency = 0 end
	end

	local up = not SET.barTop
	_KR.puckArms[1].Rotation = up and -40 or 40; _KR.puckArms[2].Rotation = up and 40 or -40
	_KR.puckArms[1].BackgroundColor3, _KR.puckArms[2].BackgroundColor3, _KR.puckInd.BackgroundColor3 = T.txt2, T.txt2, T.accent
	local at, it = (rest and st == "Dock") and 0 or 1, (rest and st == "Taskbar") and 0 or 1
	for _, a in ipairs(_KR.puckArms) do tween(a, rest and 0.25 or 0.1, { BackgroundTransparency = at }) end
	tween(_KR.puckInd, rest and 0.25 or 0.1, { BackgroundTransparency = it })
end

A.barPos = function()
	local sh = math.floor(BAR_H * UISCALE * (SET.barSize or 1))
	local ax, pxS, pxO = 0.5, 0.5, 0
	if SET.barSide == "Left" then ax, pxS, pxO = 0, 0, 14
	elseif SET.barSide == "Right" then ax, pxS, pxO = 1, 1, -14 end
	A.styleSize()
	_KR.puckApply(_KR.barHidden and "rest" or "start")
	local st = SET.barStyle or "Dock"
	if st == "Taskbar" then
		local ay = SET.barTop and 0 or 1; local sg = SET.barTop and 1 or -1
		local topY = SET.barTop and GUI_INSET.Y or 0
		bar.AnchorPoint = Vector2.new(0, ay); bar.Position = UDim2.new(0, 0, ay, topY)
		_KR.chev.AnchorPoint = Vector2.new(0, ay); _KR.chev.Position = UDim2.new(0, 14, ay, topY + sg * (sh + 7))
		_KR.sClock.AnchorPoint = Vector2.new(1, ay); _KR.sClock.Position = UDim2.new(1, -16, ay, topY + sg * math.floor((sh - 40 * UISCALE) / 2))
		if SET.multiPanel then MP.relayout(true) end
		return
	elseif st == "Minimal" then
		bar.AnchorPoint = Vector2.new(0, 0.5); bar.Position = UDim2.new(0, 14, 0.5, 0)
		_KR.chev.AnchorPoint = Vector2.new(0.5, 1); _KR.chev.Position = UDim2.new(0, 14 + math.floor(_KR.colW() / 2), 0.5, -math.floor(bar.AbsoluteSize.Y / 2) - 7)
		_KR.sClock.AnchorPoint = Vector2.new(1, 0); _KR.sClock.Position = UDim2.new(1, -20, 0, GUI_INSET.Y + 12)
		if SET.multiPanel then MP.relayout(true) end
		return
	end
	if SET.barTop then
		bar.AnchorPoint = Vector2.new(ax, 0); bar.Position = UDim2.new(pxS, pxO, 0, BAR_Y)
		_KR.chev.AnchorPoint = Vector2.new(ax, 0); _KR.chev.Position = UDim2.new(pxS, pxO, 0, BAR_Y + sh + 7)
	else
		bar.AnchorPoint = Vector2.new(ax, 1); bar.Position = UDim2.new(pxS, pxO, 1, -BAR_Y)
		_KR.chev.AnchorPoint = Vector2.new(ax, 1); _KR.chev.Position = UDim2.new(pxS, pxO, 1, -(BAR_Y + sh + 7))
	end
	if SET.multiPanel then MP.relayout(true) end
	if _KR.replacePanel then _KR.replacePanel() end
end

A.autoConn = nil; A.lastActive = os.clock()
A.stopAuto = function()
	if A.autoConn then pcall(function() A.autoConn:Disconnect() end); A.autoConn = nil end
	if A.autoInput then pcall(function() A.autoInput:Disconnect() end); A.autoInput = nil end
end
A.startAuto = function()
	A.lastActive = os.clock()
	if A.autoConn then return end
	A.autoConn = RunService.Heartbeat:Connect(function()
		if not SET.autoHide then return end
		if panelOpen or homeOpen or _KR.barHidden or _KR.photoOn then A.lastActive = os.clock(); return end
		if os.clock() - A.lastActive > 4 then _KR.hideBar() end
	end)

	A.autoInput = UserInputService.InputBegan:Connect(function(i)
		local t = i.UserInputType
		if t ~= Enum.UserInputType.Touch and t ~= Enum.UserInputType.MouseButton1 then return end
		local a, z = bar.AbsolutePosition, bar.AbsoluteSize
		local x, y = i.Position.X, i.Position.Y
		if x >= a.X - 40 and x <= a.X + z.X + 40 and y >= a.Y - 40 and y <= a.Y + z.Y + 40 then A.lastActive = os.clock() end
	end)
end
bar.MouseEnter:Connect(function() A.lastActive = os.clock() end)




_KR.fadeProps, _KR.strokeProps = { "BackgroundTransparency", "ImageTransparency", "ScrollBarImageTransparency" }, { "Transparency" }
local function _pruneFadeCache()
	local cache = _KR.fadeCache
	if not cache then _KR.fadeIn = nil; return end
	local seen, write = {}, 1
	for read = 1, #cache do
		local e, o = cache[read], cache[read][1]
		if o and o.Parent then cache[write] = e; write += 1; seen[o] = true end
	end
	for i = write, #cache do cache[i] = nil end
	_KR.fadeIn = seen
end


_KR.puckSkip = function(o) return o == _KR.barPuck or o:IsDescendantOf(_KR.barPuck) or (_KR.wall ~= nil and (o == _KR.wall or o:IsDescendantOf(_KR.wall))) end
A.applyTrans = function()
	local t = math.clamp((SET.uiTrans or 0) / 100, 0, 0.92)
	if t <= 0 then
		if _KR.fadeCache then for _, e in ipairs(_KR.fadeCache) do if e[1].Parent then e[1][e[2]] = e[3] end end; _KR.fadeCache, _KR.fadeIn = nil, nil end
		return
	end


	if _KR.fadeCache and os.clock() - (_KR.fadePrunedAt or 0) > 2 then _KR.fadePrunedAt = os.clock(); _pruneFadeCache() end
	if not _KR.fadeCache then
		local cache, seen = {}, {}
		for _, sg in ipairs({ screen, homeScreen, panelScreen, MP.screen }) do
			if sg then for _, o in ipairs(sg:GetDescendants()) do
				if _KR.puckSkip(o) then continue end
				local props = o:IsA("UIStroke") and _KR.strokeProps or (o:IsA("GuiObject") and _KR.fadeProps)
				if props then for _, p in ipairs(props) do
					local ok, cur = pcall(function() return o[p] end)
					if ok and type(cur) == "number" then cache[#cache + 1] = { o, p, cur, false }; seen[o] = true end
				end end
				if o:IsA("TextLabel") or o:IsA("TextButton") or o:IsA("TextBox") then
					cache[#cache + 1] = { o, "TextStrokeTransparency", o.TextStrokeTransparency, true }; seen[o] = true
					pcall(function() o.TextStrokeColor3 = Color3.new(0, 0, 0) end)
				end
			end end
		end
		_KR.fadeCache, _KR.fadeIn = cache, seen
	end
	for _, e in ipairs(_KR.fadeCache) do
		local o = e[1]
		if o.Parent then o[e[2]] = e[4] and math.min(e[3], 1 - t) or (e[3] + (1 - e[3]) * t) end
	end
end
_KR.fadeInto = function(root)
	local t = math.clamp((SET.uiTrans or 0) / 100, 0, 0.92)
	if t <= 0 or not _KR.fadeCache then return end
	_pruneFadeCache()
	local list = root:GetDescendants(); list[#list + 1] = root
	for _, o in ipairs(list) do
		if not _KR.fadeIn[o] and not _KR.puckSkip(o) then
			local props = o:IsA("UIStroke") and _KR.strokeProps or (o:IsA("GuiObject") and _KR.fadeProps)
			if props then for _, p in ipairs(props) do
				local ok, cur = pcall(function() return o[p] end)
				if ok and type(cur) == "number" then _KR.fadeCache[#_KR.fadeCache + 1] = { o, p, cur, false }; o[p] = cur + (1 - cur) * t; _KR.fadeIn[o] = true end
			end end
			if o:IsA("TextLabel") or o:IsA("TextButton") or o:IsA("TextBox") then
				_KR.fadeCache[#_KR.fadeCache + 1] = { o, "TextStrokeTransparency", o.TextStrokeTransparency, true }; _KR.fadeIn[o] = true
				pcall(function() o.TextStrokeColor3 = Color3.new(0, 0, 0); o.TextStrokeTransparency = math.min(o.TextStrokeTransparency, 1 - t) end)
			end
		end
	end
end
A.reset = function()
	SET.wave, SET.glow, SET.cardAnims, SET.animSpeed, SET.toastAnims, SET.hoverFx, SET.reduceMotion, SET.ambient = true, true, true, 100, true, true, false, true
	SET.uiTrans, SET.density, SET.blur, SET.barTop, SET.autoHide, SET.multiPanel, SET.barAvatar = 0, "Comfy", true, false, false, false, false
	SET.privacy, SET.hideName, SET.hideLocation, SET.blurAvatar = false, false, true, false
	SET.bg, SET.theme, SET.accent = "Blur", "Vampiric Noir", A.themes["Vampiric Noir"].accent
	SET.corner = 100; A.applyCorner()
	SET.glass = 0; A.applyGlass()
	SET.clockShow, SET.clock24, SET.barSide = true, true, "Center"; A.applyClock()
	SET.barLabels = false; A.applyBarLabels()
	SET.barSize = 1; A.applyBarSize()
	SET.hiddenTabs = {}; A.applyTabs()
	SET.notify, SET.toastPos = true, "Top-right"; A.applyToast()
	SET.toastTime, SET.dockMag, SET.dockMagAmt, SET.pressFx = 100, true, 142, true; _KR.dockMag(nil)
	if SET.uiFont ~= "Gotham" then SET.uiFont = "Gotham"; A.applyFont() end
	SET.mode, SET.contrast, SET.accentGrad, SET.accentAnim, SET.tabColours, SET.tabIntensity = "Dark", "Standard", "Off", "Off", "Colourful", 100
	SET.textScale, SET.blurAmt, SET.wallpaper, SET.wallDim, SET.panelTint, SET.shadows, SET.apSub = 100, 50, "", 45, 0, "Off", "Colour"
	SET.wallOpacity = 100
	pcall(A.applyTextScale)
	pcall(_KR.loadWall)
	pcall(_KR.applyShadows)
	pcall(_KR.accAnimSync)
	SET.custom = { accent2 = TDEF.accent2, card = TDEF.card, bg = TDEF.bg, text = TDEF.txt }
	SPEED = BASE_SPEED
	A.stopAuto(); if _KR.barHidden then _KR.showBar() end; MP.closeAll()
	SET.barStyle = "Dock"; SET.homeLayout = "Auto"; SET.panelLayout = "Auto"; A.applyStyle()
	useKrulIcon(avatar)
	densify()
	A.applyTheme(false)
	A.applyTrans()
	toast("UI Settings", "Reset to defaults.", "warn")
end
A.applyCorner = function()
	_KR.cornerScale = (SET.corner or 100) / 100
	for c, base in pairs(_KR.corners) do pcall(function() c.CornerRadius = _KR.cornerUD(c.Parent, base) end) end
end
A.applyGlass = function()
	_KR.glass = (SET.glass or 0) / 100
