			bloom = { Intensity = 0.3, Size = 22, Threshold = 1.2 },
		},
		["Noir"] = {
			cc = { Brightness = -0.02, Contrast = 0.25, Saturation = -1 },
			bloom = { Intensity = 0.2, Size = 20, Threshold = 1.3 },
		},
		["Cold Morning"] = {
			light = { ClockTime = 7.5, Brightness = 2.2, ExposureCompensation = 0.1, Ambient = C(120, 130, 150), OutdoorAmbient = C(150, 165, 190), ColorShift_Top = C(210, 225, 255), ShadowSoftness = 0.6 },
			cc = { Saturation = -0.05, TintColor = C(235, 243, 255) },
			atmos = { Density = 0.35, Offset = 0.1, Color = C(200, 215, 235), Decay = C(150, 165, 190), Glare = 0.1, Haze = 1.5 },
		},
		["Sunset Pink"] = {
			light = { ClockTime = 17.8, Brightness = 2.4, ExposureCompensation = 0.3, Ambient = C(135, 100, 120), OutdoorAmbient = C(190, 140, 160), ColorShift_Top = C(255, 170, 190), ShadowSoftness = 0.5 },
			cc = { Contrast = 0.06, Saturation = 0.12, TintColor = C(255, 232, 240) },
			bloom = { Intensity = 0.7, Size = 30, Threshold = 1.1 },
			rays = { Intensity = 0.12, Spread = 0.8 },
			atmos = { Density = 0.3, Offset = 0.2, Color = C(255, 180, 200), Decay = C(160, 90, 130), Glare = 0.6, Haze = 1.4 },
		},
		["Horror"] = {
			light = { ClockTime = 0.5, Brightness = 0.6, ExposureCompensation = -0.3, Ambient = C(40, 45, 50), OutdoorAmbient = C(55, 60, 65), ColorShift_Top = C(160, 170, 160), ShadowSoftness = 0.2 },
			cc = { Contrast = 0.2, Saturation = -0.45, TintColor = C(225, 240, 225) },
			atmos = { Density = 0.55, Offset = 0, Color = C(70, 80, 75), Decay = C(30, 35, 32), Glare = 0, Haze = 2.5 },
		},
		["Pastel"] = {
			light = { ExposureCompensation = 0.25 },
			cc = { Brightness = 0.04, Contrast = -0.1, Saturation = -0.2, TintColor = C(255, 246, 250) },
			bloom = { Intensity = 0.6, Size = 36, Threshold = 1 },
		},
	}
	W.PRESETS = PRESETS


	W.TWEAKS = { "Brightness", "Contrast", "Saturation", "Bloom", "Warmth", "Fog" }
	local function tweaksFor(name)
		local all = type(SET.worldTweaks) == "table" and SET.worldTweaks or {}
		local t = type(all[name]) == "table" and all[name] or {}
		local out = {}
		for _, k in ipairs(W.TWEAKS) do out[k] = math.clamp(tonumber(t[k]) or 0, -100, 100) / 100 end
		return out
	end
	W.getTweak = function(name, key)
		local all = type(SET.worldTweaks) == "table" and SET.worldTweaks or {}
		return math.clamp(tonumber(type(all[name]) == "table" and all[name][key]) or 0, -100, 100)
	end
	local function copy(t) local o = {}; for k, v in pairs(t) do o[k] = type(v) == "table" and copy(v) or v end; return o end
	local function mixC(a, b, k)
		if typeof and typeof(a) == "Color3" then return a:Lerp(b, k) end
		return a
	end



	W.dim = false
	local function dimmed(p)
		p.light = p.light or {}
		local black = C(0, 0, 0)
		p.light.Brightness = (p.light.Brightness or Lighting.Brightness or 2) * 0.25
		p.light.Ambient = mixC(p.light.Ambient or Lighting.Ambient, black, 0.75)
		p.light.OutdoorAmbient = mixC(p.light.OutdoorAmbient or Lighting.OutdoorAmbient, black, 0.75)
		p.light.EnvironmentDiffuseScale = (p.light.EnvironmentDiffuseScale or Lighting.EnvironmentDiffuseScale or 1) * 0.25
		p.light.EnvironmentSpecularScale = (p.light.EnvironmentSpecularScale or Lighting.EnvironmentSpecularScale or 1) * 0.25
		return p
	end
	local function resolve(name)
		local base = PRESETS[name]
		if not base then return W.dim and dimmed({}) or nil end
		local p, t = copy(base), tweaksFor(name)
		if W.dim then dimmed(p) end
		if t.Brightness ~= 0 then
			p.light = p.light or {}
			p.light.ExposureCompensation = math.clamp((p.light.ExposureCompensation or Lighting.ExposureCompensation or 0) + t.Brightness, -3, 3)
		end
		if t.Contrast ~= 0 or t.Saturation ~= 0 or t.Warmth ~= 0 then
			p.cc = p.cc or {}
			p.cc.Contrast = math.clamp((p.cc.Contrast or 0) + t.Contrast * 0.4, -1, 1)
			p.cc.Saturation = math.clamp((p.cc.Saturation or 0) + t.Saturation * 0.6, -1, 1)
			if t.Warmth ~= 0 then
				local tint = p.cc.TintColor or C(255, 255, 255)
				p.cc.TintColor = t.Warmth > 0 and mixC(tint, C(255, 214, 170), t.Warmth) or mixC(tint, C(190, 215, 255), -t.Warmth)
			end
		end
		if t.Bloom ~= 0 then
			p.bloom = p.bloom or { Intensity = 0, Size = 24, Threshold = 1.2 }
			p.bloom.Intensity = math.max(0, p.bloom.Intensity + t.Bloom)
			if p.bloom.Intensity <= 0 then p.bloom = nil end
		end
		if t.Fog ~= 0 then
			if not p.atmos and t.Fog > 0 then
				p.atmos = { Density = 0, Offset = 0, Color = C(199, 199, 199), Decay = C(106, 112, 125), Glare = 0, Haze = 0 }
			end
			if p.atmos then
				p.atmos.Density = math.clamp(p.atmos.Density + t.Fog * 0.4, 0, 1)
				p.atmos.Haze = math.clamp(p.atmos.Haze + math.max(t.Fog, 0) * 2, 0, 10)
			end
		end
		return p
	end
	W.resolve = resolve
	local ATMOS_KEYS = { "Density", "Offset", "Color", "Decay", "Glare", "Haze" }
	local lightSaved, gameAtmos, atmosSaved, effects, watch, overlay, wanted = nil, nil, nil, {}, nil, nil, nil

	local function differs(a, b)
		if type(a) == "number" and type(b) == "number" then return math.abs(a - b) > 0.02 end
		return a ~= b
	end
	local effectDefs = {}
	local function effect(cls, props)
		local ok, e = pcall(function()
			local o = Instance.new(cls)
			o.Name = "RCWorld" .. cls
			for k, v in pairs(props) do o[k] = v end
			o.Parent = Lighting
			return o
		end)
		if ok then table.insert(effects, e); effectDefs[e] = { cls, props } end
		return ok and e or nil
	end
	local function clearLook()
		if watch then watch:Disconnect(); watch = nil end
		wanted = nil
		for _, e in ipairs(effects) do pcall(function() e:Destroy() end) end
		effects = {}
		effectDefs = {}
		if gameAtmos and atmosSaved then
			for k, v in pairs(atmosSaved) do pcall(function() gameAtmos[k] = v end) end
		end
		gameAtmos, atmosSaved = nil, nil
		if lightSaved then
			for k, v in pairs(lightSaved) do pcall(function() Lighting[k] = v end) end
			lightSaved = nil
		end
	end
	local function applyAtmos(p)
		local a = Lighting:FindFirstChildOfClass("Atmosphere")
		if a then
			gameAtmos, atmosSaved = a, {}
			for _, k in ipairs(ATMOS_KEYS) do atmosSaved[k] = a[k]; a[k] = p.atmos[k] end
		else
			effect("Atmosphere", p.atmos)
		end
	end

	local function reassert(p)
		for k, v in pairs(p.light or {}) do
			if differs(Lighting[k], v) then pcall(function() Lighting[k] = v end) end
		end
		for i = #effects, 1, -1 do
			local e = effects[i]
			if e.Parent ~= Lighting and not pcall(function() e.Parent = Lighting end) then
				local d = effectDefs[e]
				table.remove(effects, i); effectDefs[e] = nil
				if d then effect(d[1], d[2]) end
			end
		end
		if p.atmos and gameAtmos then
			if gameAtmos.Parent == Lighting then
				for _, k in ipairs(ATMOS_KEYS) do
					if differs(gameAtmos[k], p.atmos[k]) then pcall(function() gameAtmos[k] = p.atmos[k] end) end
				end
			else
				gameAtmos, atmosSaved = nil, nil
				applyAtmos(p)
			end
		end
	end
	function W.setLook(name)
		clearLook()
		local p = resolve(name)
		SET.worldLook = PRESETS[name] and name or "None"
		if not p then return end
		lightSaved = {}
		for k, v in pairs(p.light or {}) do
			lightSaved[k] = Lighting[k]
			pcall(function() Lighting[k] = v end)
		end
		if p.cc then effect("ColorCorrectionEffect", p.cc) end
		if p.bloom then effect("BloomEffect", p.bloom) end
		if p.rays then effect("SunRaysEffect", p.rays) end
		if p.grade then
			local tone = Enum.TonemapperPreset and Enum.TonemapperPreset[p.grade.TonemapperPreset]
			if tone then effect("ColorGradingEffect", { TonemapperPreset = tone }) end
		end
		if p.atmos then applyAtmos(p) end
		wanted = p
		local t = 0
		watch = RunService.Heartbeat:Connect(function(dt)
			t += dt
			if t < 1 then return end
			t = 0
			pcall(reassert, wanted)
		end)
	end

	local function edge(parent, anchor, pos, size, rot, color, dark)
		local f = new("Frame", { BackgroundColor3 = color, BackgroundTransparency = 0, BorderSizePixel = 0, AnchorPoint = anchor, Position = pos, Size = size, Parent = parent })
		new("UIGradient", { Rotation = rot, Transparency = NumberSequence.new(dark, 1), Parent = f })
		return f
	end
	local function buildGrain(parent)
		local img = game:GetService("AssetService"):CreateEditableImage({ Size = Vector2.new(128, 128) })
		local b = buffer.create(128 * 128 * 4)
		for i = 0, 128 * 128 - 1 do
			local g = math.random(0, 255)
			buffer.writeu8(b, i * 4, g); buffer.writeu8(b, i * 4 + 1, g); buffer.writeu8(b, i * 4 + 2, g); buffer.writeu8(b, i * 4 + 3, 255)
		end
		img:WritePixelsBuffer(Vector2.zero, img.Size, b)
		local l = new("ImageLabel", { BackgroundTransparency = 1, ImageTransparency = 0.91, ScaleType = Enum.ScaleType.Tile, TileSize = UDim2.fromOffset(256, 256), Size = UDim2.new(1, 256, 1, 256), Position = UDim2.fromOffset(-128, -128), Parent = parent })
		l.ImageContent = Content.fromObject(img)
		return l, img
	end

	function W.setTweak(key, value)
		if not table.find(W.TWEAKS, key) then return end
		local name = SET.worldLook or "None"
		if not PRESETS[name] then return end
		if type(SET.worldTweaks) ~= "table" then SET.worldTweaks = {} end
		SET.worldTweaks[name] = type(SET.worldTweaks[name]) == "table" and SET.worldTweaks[name] or {}
		SET.worldTweaks[name][key] = math.clamp(math.floor((tonumber(value) or 0) + 0.5), -100, 100)

		if W._tPend then return end
		local wait = 0.15 - (os.clock() - (W._tLast or -1))
		local function apply()
			if W._tPend ~= (W._tTok or 0) then return end
			W._tPend = nil; W._tLast = os.clock()
			if PRESETS[SET.worldLook or ""] then W.setLook(SET.worldLook) end
		end
		if wait <= 0 then W._tPend = (W._tTok or 0); apply() else W._tPend = (W._tTok or 0); task.delay(wait, apply) end
	end
	function W.setDim(on)
		W.dim = on and true or false
		W.setLook(SET.worldLook or "None")
	end
	function W.setOverlay(name)
		if overlay then
			if overlay.conn then overlay.conn:Disconnect() end
			pcall(function() if overlay.img then overlay.img:Destroy() end end)
			pcall(function() overlay.gui:Destroy() end)
			overlay = nil
		end
		if not table.find(W.OVERLAYS, name) or name == "None" then SET.worldOverlay = "None"; return true end
		SET.worldOverlay = name
		local gui = new("ScreenGui", { Name = "RoClothesWorldOverlay", ResetOnSpawn = false, IgnoreGuiInset = true, ZIndexBehavior = Enum.ZIndexBehavior.Sibling, DisplayOrder = 990, Parent = PlayerGui })
		overlay = { gui = gui }
		local black = C(0, 0, 0)
		if name == "Vignette" or name == "Cinema bars" then
			local d = name == "Vignette" and 0.38 or 0.55
			edge(gui, Vector2.new(0, 0), UDim2.fromScale(0, 0), UDim2.fromScale(1, 0.24), 90, black, d)
			edge(gui, Vector2.new(0, 1), UDim2.fromScale(0, 1), UDim2.fromScale(1, 0.24), 270, black, d)
			edge(gui, Vector2.new(0, 0), UDim2.fromScale(0, 0), UDim2.fromScale(0.2, 1), 0, black, d)
			edge(gui, Vector2.new(1, 0), UDim2.fromScale(1, 0), UDim2.fromScale(0.2, 1), 180, black, d)
		end
		if name == "Cinema bars" then
			new("Frame", { BackgroundColor3 = black, BorderSizePixel = 0, Size = UDim2.fromScale(1, 0.1), Parent = gui })
			new("Frame", { BackgroundColor3 = black, BorderSizePixel = 0, AnchorPoint = Vector2.new(0, 1), Position = UDim2.fromScale(0, 1), Size = UDim2.fromScale(1, 0.1), Parent = gui })
		elseif name == "Light leak" then
			edge(gui, Vector2.new(1, 0), UDim2.fromScale(1, 0), UDim2.fromScale(0.5, 1), 180, C(255, 150, 70), 0.68)
			edge(gui, Vector2.new(0, 0), UDim2.fromScale(0, 0), UDim2.fromScale(1, 0.35), 90, C(255, 90, 130), 0.82)
		elseif name == "Film grain" then
			local ok, l, img = pcall(buildGrain, gui)
			if not ok then
				W.setOverlay("None")
				SET.worldOverlay = name
				return false
			end
			overlay.img = img
			local t = 0
			overlay.conn = RunService.Heartbeat:Connect(function(dt)
				t += dt
				if t < 0.07 then return end
				t = 0
				l.Position = UDim2.fromOffset(-math.random(0, 255), -math.random(0, 255))
			end)
		end
		return true
	end
	function W.exit()
		W._tTok = (W._tTok or 0) + 1; W._tPend = nil
		W.dim = false
		clearLook()
		local saved = SET.worldOverlay
		pcall(W.setOverlay, "None")
		SET.worldOverlay = saved
	end
	System._worldExit = W.exit
	task.delay(1, function()
		if not System._worldExit then return end
		if PRESETS[SET.worldLook or ""] then pcall(W.setLook, SET.worldLook) end
		if (SET.worldOverlay or "None") ~= "None" then pcall(W.setOverlay, SET.worldOverlay) end
	end)
end)()







_KR.lightDraws = {}
_KR.lightLabel = function(i, l) return tostring(i) .. ((l and l.ro) and l.ro:sub(1, 1) or "") end

_KR.LIGHT_TINTS = { { 255, 70, 70 }, { 255, 150, 40 }, { 255, 225, 80 }, { 90, 230, 120 }, { 40, 215, 255 }, { 70, 110, 255 }, { 170, 90, 255 }, { 255, 70, 190 } }





_KR.lightTags = function(on)
	_KR._ltTok = (_KR._ltTok or 0) + 1
	local tok = _KR._ltTok
	if _KR._ltFolder then pcall(function() _KR._ltFolder:Destroy() end); _KR._ltFolder = nil end
	_KR._ltOpen = nil
	if not on then return end
	local Lx = System and System.Lights
	if not Lx then return end
	local folder = new("Folder", { Name = "RCLightTags", Parent = PlayerGui })
	_KR._ltFolder = folder
	local tags = {}
	local function build(t, l, i, part)
		for _, c in ipairs(t.gui:GetChildren()) do c:Destroy() end
		local open = _KR._ltOpen == l
		local acts = open and (2 + ((not l.ai and l.sh ~= "Point") and 1 or 0)) or 0
		t.gui.Size = UDim2.fromOffset(open and 170 or 34, 34 + acts * 38)
		t.gui.Adornee = part
		local col = Lx.color3(l)
		local dark = (col.R * 0.3 + col.G * 0.59 + col.B * 0.11) > 0.6
		local chip = new("TextButton", { AutoButtonColor = false, Text = _KR.lightLabel(i, l), Font = FONTB, TextSize = 15, TextColor3 = dark and Color3.fromRGB(20, 20, 24) or Color3.fromRGB(250, 250, 252),
			BackgroundColor3 = col, BorderSizePixel = 0, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromOffset(t.gui.Size.X.Offset / 2, 15), Parent = t.gui })

		local sel = i == Lx.sel
		chip.Size = UDim2.fromOffset(sel and 30 or 24, sel and 30 or 24); chip.BackgroundTransparency = sel and 0 or 0.2
		corner(chip, 15)
		chip.MouseButton1Click:Connect(function()
			Lx.select(i)
			_KR._ltOpen = (_KR._ltOpen ~= l) and l or nil
			local ot = {}; _KR._ltOpenTok = ot
			task.delay(5, function() if _KR._ltOpenTok == ot then _KR._ltOpen = nil end end)
		end)
		if not open then return end
		local function act(y, txt, primary, fn)
			local b = new("TextButton", { AutoButtonColor = false, Text = txt, Font = FONTB, TextSize = 13, TextColor3 = primary and Color3.fromRGB(250, 250, 252) or T.txt,
				BackgroundColor3 = primary and T.accent or T.bg, BorderSizePixel = 0, Position = UDim2.fromOffset(0, y), Size = UDim2.new(1, 0, 0, 32), Parent = t.gui })
			corner(b, 9)
			b.MouseButton1Click:Connect(function() _KR._ltOpen = nil; fn() end)
		end
		act(36, "View from light", true, function() Lx.select(i); if _KR.lightView then _KR.lightView() end end)
		act(74, l.bu and "Hide bulb" or "Show bulb", false, function() Lx.edit(function(x) x.bu = not x.bu end, i) end)
		if acts > 2 then act(112, "Point at subject", false, function() Lx.select(i); Lx.setAim(true) end) end
	end
	task.spawn(function()
		while _KR._ltTok == tok and folder.Parent do
			local show = Lx.ghostOn == true and not (Lx.view)
			local list = Lx.list()
			local live = {}
			for i, l in ipairs(list) do
				local it = Lx.me and Lx.me.inst[l]
				local part = it and it.part
				if show and part and part.Parent then
					live[l] = true
					local t = tags[l]
					if not t then
						t = { gui = new("BillboardGui", { Name = "LightTag", AlwaysOnTop = true, Active = true, ResetOnSpawn = false, LightInfluence = 0,
							StudsOffsetWorldSpace = Vector3.new(0, 1.3, 0), MaxDistance = 400, Parent = folder }) }
						tags[l] = t
					end
					local c = Lx.color3(l)
					local sig = table.concat({ i, c.R, c.G, c.B, tostring(Lx.sel == i), tostring(_KR._ltOpen == l), tostring(l.ai), tostring(l.bu), l.sh, tostring(part) }, "|")
					if t.sig ~= sig then t.sig = sig; pcall(build, t, l, i, part) end
				end
			end
			for l, t in pairs(tags) do if not live[l] then pcall(function() t.gui:Destroy() end); tags[l] = nil end end
			if _KR._ltOpen and not live[_KR._ltOpen] then _KR._ltOpen = nil end
			task.wait(0.3)
		end
	end)
end
_KR.lightPanel = function(box)
	local Lx = System and System.Lights
	if not Lx then
		lbl({ Size = UDim2.new(1, 0, 0, 30), Text = "Lights are not available", TextSize = 13, Parent = box })
		return
	end
	local body = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, Parent = box }); vlist(body, 6)
	local function say(ok, why) if not ok and why then toast("Lights", why, "warn") end end
	local function presetNames() local o = {}; for _, p in ipairs(Lx.PRESETS) do o[#o + 1] = p.name end; return o end

	local function subjects()
		local names, keys = { "Me" }, { false }
		for _, k in ipairs(System.CloneOrder or {}) do
			local m = System.NPCs and System.NPCs[k]
			if typeof(m) == "Instance" and m.Parent then
				names[#names + 1] = (System._cloneDisplayName and System._cloneDisplayName(k)) or k
				keys[#keys + 1] = k
			end
		end
		return names, keys
	end
	local function round(parent, size, col, order)
		local b = new("TextButton", { AutoButtonColor = false, Text = "", BackgroundColor3 = col, BorderSizePixel = 0, Size = UDim2.fromOffset(size, size), LayoutOrder = order, Parent = parent })
		corner(b, size / 2)
		return b
	end
	local function ring(b)
		local d = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromOffset(8, 8), BackgroundColor3 = T.txt, BorderSizePixel = 0, Parent = b })
		corner(d, 4)
	end
	local CELL = 40
	local function hrow(order)
		local f = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = order, Parent = body })
		new("UIGridLayout", { CellSize = UDim2.fromOffset(CELL, CELL), CellPadding = UDim2.fromOffset(8, 8), SortOrder = Enum.SortOrder.LayoutOrder, Parent = f })
		return f
	end

	local function tempStrip(row)
		for _, tr in ipairs(row:GetChildren()) do
			local fill = tr:IsA("Frame") and tr:FindFirstChildWhichIsA("Frame")
			if fill and fill:FindFirstChildOfClass("UIGradient") then
				local kp = {}
				for i = 0, 6 do kp[#kp + 1] = ColorSequenceKeypoint.new(i / 6, Color3.fromRGB(Lx.kelvinRGB(1500 + 10500 * i / 6))) end
				tr.BackgroundColor3 = Color3.new(1, 1, 1)
				new("UIGradient", { Color = ColorSequence.new(kp), Parent = tr })
				fill.BackgroundTransparency = 1
				return
			end
		end
	end
	local draw
	local function section(name, order)
		lbl({ Size = UDim2.new(1, 0, 0, 26), Text = name, Font = FONTB, TextSize = 13, TextColor3 = T.txt, TextXAlignment = Enum.TextXAlignment.Left, LayoutOrder = order, Parent = body })
		return true
	end
	draw = function()
		if not body.Parent then _KR.lightDraws[draw] = nil; return end
		for _, c in ipairs(body:GetChildren()) do if not c:IsA("UIListLayout") then c:Destroy() end end
		local o = 0
		local function n() o = o + 1; return o end

		local top = cols(body, n(), 2)
		UI.button(top[1], "Spawn light", "primary", 1, function() say(Lx.spawn()) end)

		local delAll, armed
		delAll = UI.button(top[2], "Delete all", nil, 1, function()
			local tl = delAll and delAll:FindFirstChildWhichIsA("TextLabel")
			if armed then armed = nil; Lx.delete(true); return end
			if #Lx.list() == 0 then return end
			local tok = {}; armed = tok
			if tl then tl.Text = "Tap again"; tl.TextColor3 = T.bad end
			task.delay(3, function() if armed == tok then armed = nil; if tl and tl.Parent then tl.Text = "Delete all"; tl.TextColor3 = T.accent end end end)
		end)

		local roles = cols(body, n(), 3)
		for i, nm in ipairs(Lx.ROLE_NAMES) do UI.button(roles[i], nm .. " light", nil, 1, function() say(Lx.spawnRole(nm)) end) end
		S[_curPage .. "\1d:Preset"] = Lx.presetName or "Custom"
		UI.dropdown(body, "Preset", presetNames(), n(), function(nm) say(Lx.applyPreset(nm)) end)

		local names, keys = subjects()
		local cur = 1
		for i, k in ipairs(keys) do if k and k == Lx.subject then cur = i end end
		if cur == 1 then Lx.subject = nil end
		if #names > 1 then UI.cyc(body, "Around", names, n(), function(_, i) Lx.subject = keys[i] or nil end, names[cur]) end
		local list = Lx.list()
		if #list == 0 then
			lbl({ Size = UDim2.new(1, 0, 0, 34), Text = "No lights yet: spawn one or pick a preset. Each light shows its number in the world; tap it for View from light.", TextSize = 12, TextColor3 = T.txt2, TextWrapped = true, LayoutOrder = n(), Parent = body })
			return
		end

		local chips, chipRow = {}, hrow(n())
		for i, cl in ipairs(list) do
			local b = round(chipRow, CELL, Lx.color3(cl), i)

			local cc = Lx.color3(cl)
			b.Text, b.Font, b.TextSize = _KR.lightLabel(i, cl), FONTB, 14
			b.TextColor3 = (cc.R * 0.3 + cc.G * 0.59 + cc.B * 0.11) > 0.6 and Color3.fromRGB(20, 20, 24) or Color3.fromRGB(250, 250, 252)
			if i == Lx.sel then ring(b); b.TextYAlignment = Enum.TextYAlignment.Top end
			chips[i] = b
			b.MouseButton1Click:Connect(function() Lx.select(i) end)
		end
		local l = Lx.selected()
		if not l then return end
		local function ed(f) Lx.edit(f) end
		local function sl(key, f) Lx.edit(f, nil, key) end
		local function recolor() local c = chips[Lx.sel]; if c then c.BackgroundColor3 = Lx.color3(l) end end
		if section("Light", n()) then
			UI.cyc(body, "Shape", Lx.SHAPES, n(), function(v) ed(function(x) x.sh = v end); draw() end, l.sh)
			local tr
			tr = UI.slider(body, l.c and "Temperature (tinted)" or "Temperature K", l.k, 1500, 12000, n(), function(v)
				sl("Temperature", function(x) x.k = v; x.c = nil end)
				recolor()
				local t = tr and tr:FindFirstChildWhichIsA("TextLabel")
				if t and t.Text ~= "Temperature K" then t.Text = "Temperature K" end
			end, 6500)
			pcall(tempStrip, tr)
			local tints = hrow(n())
			for i, c in ipairs(_KR.LIGHT_TINTS) do
				local b = round(tints, CELL, Color3.fromRGB(c[1], c[2], c[3]), i)
				if l.c and l.c[1] == c[1] and l.c[2] == c[2] and l.c[3] == c[3] then ring(b) end
				b.MouseButton1Click:Connect(function() ed(function(x) x.c = { c[1], c[2], c[3] } end); draw() end)
			end
			local none = new("TextButton", { AutoButtonColor = false, Text = "None", Font = FONTB, TextSize = 11, TextColor3 = l.c and T.txt2 or T.txt, BackgroundColor3 = T.card, BorderSizePixel = 0, Size = UDim2.fromOffset(CELL, CELL), LayoutOrder = 99, Parent = tints })
			corner(none, CELL / 2)
			if not l.c then none.BackgroundColor3 = T.accentD end
			none.MouseButton1Click:Connect(function() ed(function(x) x.c = nil end); draw() end)
			UI.slider(body, "Brightness", math.floor(l.b * 10 + 0.5), 0, 100, n(), function(v) sl("Brightness", function(x) x.b = v / 10 end) end, 20)
			UI.slider(body, "Reach", math.floor(l.r + 0.5), 0, 60, n(), function(v) sl("Reach", function(x) x.r = v end) end, 16)
			if l.sh ~= "Point" then UI.slider(body, "Spread", math.floor(l.a + 0.5), 1, 180, n(), function(v) sl("Spread", function(x) x.a = v end) end, 60) end
			if l.sh == "Panel" then UI.slider(body, "Panel size", math.floor(l.sz + 0.5), 1, 12, n(), function(v) sl("Panel size", function(x) x.sz = v end) end, 4) end
		end


		if section("Motion", n()) then
			UI.toggle(body, "Orbit", l.o, n(), function(on) Lx.setOrbit(on); draw() end)
			if l.o then UI.slider(body, "Orbit speed", math.floor(l.os + 0.5), -90, 90, n(), function(v) Lx.setOrbitSpeed(v) end, 20) end
			UI.cyc(body, "Animation", Lx.ANIMS, n(), function(v) ed(function(x) x.an = v end); draw() end, l.an)
			if l.an ~= "None" then UI.slider(body, "Animation speed", math.floor(l.as * 10 + 0.5), 1, 50, n(), function(v) sl("Animation speed", function(x) x.as = v / 10 end) end, 10) end
		end
		if section("Effects", n()) then
			UI.toggle(body, "Show bulb", l.bu, n(), function(on) ed(function(x) x.bu = on end) end)
			if l.sh ~= "Point" then UI.toggle(body, "Beam", l.be, n(), function(on) ed(function(x) x.be = on end) end) end
			UI.toggle(body, "Shadows", l.sd, n(), function(on) ed(function(x) x.sd = on end) end)
		end

		local ac = cols(body, n(), 2)
		UI.button(ac[1], "Duplicate", nil, 1, function() say(Lx.duplicate()) end)
		UI.button(ac[2], "Delete", nil, 1, function() Lx.delete(false) end)
		local hi = cols(body, n(), 2)
		UI.button(hi[1], "Undo", nil, 1, function() if not (System.undoEdit and System.undoEdit()) then toast("Lights", "Nothing to undo.", "info") end end)
		UI.button(hi[2], "Redo", nil, 1, function() if not (System.redoEdit and System.redoEdit()) then toast("Lights", "Nothing to redo.", "info") end end)
		lbl({ Size = UDim2.new(1, 0, 0, 30), Text = "Others see your lights when Avatar Sync is on for both of you.", TextSize = 11, TextColor3 = T.txt3, TextWrapped = true, LayoutOrder = n(), Parent = body })
	end
	_KR.lightDraws[draw] = true
	Lx.uiRefresh = function()
		for d in pairs(_KR.lightDraws) do pcall(d) end
	end
	draw()
	return draw
end








_KR.buildCloneBar = function()
	local cb = new("Frame", { Name = "CloneBar", AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0, GUI_INSET.Y + 8), Size = UDim2.fromOffset(0, 42), AutomaticSize = Enum.AutomaticSize.X, BackgroundColor3 = T.bg, BackgroundTransparency = 0.08, BorderSizePixel = 0, Visible = false, ZIndex = 20, Parent = screen })
	corner(cb, 21); pad(cb, 6, 6, 6, 6)
	_KR.uis(new("UIScale", { Scale = math.max(UISCALE, 0.85), Parent = cb }), 0.85)
	new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 4), VerticalAlignment = Enum.VerticalAlignment.Center, SortOrder = Enum.SortOrder.LayoutOrder, Parent = cb })
	local title = lbl({ Size = UDim2.fromOffset(0, 30), AutomaticSize = Enum.AutomaticSize.X, Text = "", Font = FONTB, TextSize = 13, TextColor3 = T.accent, LayoutOrder = 0, ZIndex = 21, Parent = cb })
	pad(title, 10, 8, 0, 0)
	local key
	local function btn(text, order, fn)
		local b = new("TextButton", { AutoButtonColor = false, Text = "", BackgroundColor3 = T.card, BackgroundTransparency = 0.3, BorderSizePixel = 0, Size = UDim2.fromOffset(0, 30), AutomaticSize = Enum.AutomaticSize.X, LayoutOrder = order, ZIndex = 21, Parent = cb })
		corner(b, 15); pad(b, 12, 12, 0, 0)
		local l = lbl({ Size = UDim2.new(0, 0, 1, 0), AutomaticSize = Enum.AutomaticSize.X, Text = text, Font = FONTB, TextSize = 12, TextColor3 = T.txt, ZIndex = 22, Parent = b })
		_KR.press(b)
		b.MouseButton1Click:Connect(function() if key then pcall(fn, key) end; if System.onCloneUI then System.onCloneUI() end end)
		return b, l
	end
	local function relist() if System.renderCloneList then pcall(System.renderCloneList) end end
	btn("Edit look", 1, function() if not (panelOpen and activeTab == "clothes") then _KR.openTabId("clothes") end end)
	local moveB, moveL = btn("Move", 2, function(k) System.cloneMoveMode(System._cloneMoving ~= k) end)
	local turnB = btn("Turn", 3, function(k) System.turnClone(k, 45) end)
	local faceB = btn("Face me", 4, function(k) System.faceClone(k) end)
	local _, walkL = btn("Walk", 5, function(k)
		if System.isPossessing(k) then System.releaseClone() else System.cloneMoveMode(false); System.possessClone(k) end
		relist()
	end)
	btn("Copy my look", 6, function(k)
		local ok = System.syncCloneFromSelf and System.syncCloneFromSelf(k)
		toast("Clones", ok and "Clone updated to your current look." or "Couldn't copy look.", ok and "ok" or "warn")
	end)
	local delArmed
	local delB, delL = btn("Delete", 7, function(k)
		if delArmed ~= k then
			delArmed = k
			task.delay(2.5, function() if delArmed == k then delArmed = nil end; if System.onCloneUI then System.onCloneUI() end end)
			return
		end
		delArmed = nil
		local name = System._cloneDisplayName(k)
		System.removeClone(k); relist()
		toast("Clones", "Deleted " .. name .. ".", "info")
	end)
	local backB = btn("Back to me", 8, function() System.cloneMoveMode(false); System.setSelect(nil); relist() end)
	backB.BackgroundColor3 = T.accentD; backB.BackgroundTransparency = 0
	local function refresh()
		key = nil
		local rows = (System.getCloneList and System.getCloneList()) or {}
		for i = 2, #rows do if rows[i].selected then key = rows[i].key end end
		cb.Visible = key ~= nil
		if not key then delArmed = nil; return end
		local name = System._cloneDisplayName(key)
		local moving = System._cloneMoving == key
		title.Text = moving and ("Tap the ground to place " .. name) or ("Editing " .. name)
		moveL.Text = moving and "Cancel" or "Move"
		local walking = System.isPossessing(key)
		walkL.Text = walking and "Stop walking" or "Walk"
		moveB.Visible, turnB.Visible, faceB.Visible = not walking, not walking, not walking
		delL.Text = (delArmed == key) and "Tap again to delete" or "Delete"
		delB.BackgroundColor3 = (delArmed == key) and T.bad or T.card
	end
	System.onCloneUI = function() pcall(refresh) end
	pcall(refresh)
end
_KR.buildCloneBar()
if System then System.keepMyEdits = SET.keepEdits ~= false end












_KR.editWinClamp = function(x, y, size, vp)
	local maxX, maxY = vp.X - size.X - 8, vp.Y - size.Y - 8
	if maxX < 8 then maxX = 8 end
	if maxY < 8 then maxY = 8 end
	return math.clamp(x, 8, maxX), math.clamp(y, 8, maxY)
end
_KR.buildEditWindows = function()
	local Sy = System
	local W = 300
	local SCALE = math.max(UISCALE, 0.9)
	local E = { open = false, wins = {}, popped = {}, paints = {}, tiles = {} }
	local BUILD, ORDER, TITLE = {}, { "parts", "acc", "move", "pose" }, { parts = "Parts", acc = "Accessories", move = "Move", pose = "Pose" }
	local ws = type(SET.editWin) == "table" and SET.editWin or {}
	SET.editWin = ws; ws.pos = type(ws.pos) == "table" and ws.pos or {}; ws.pop = type(ws.pop) == "table" and ws.pop or {}
	for id, on in pairs(ws.pop) do if on == true then E.popped[id] = true end end
	local function chip(parent, text, order, fn)
		local b = new("TextButton", { AutoButtonColor = false, Text = text, Font = FONTB, TextSize = 12, TextColor3 = T.txt2, TextTruncate = Enum.TextTruncate.AtEnd, BackgroundColor3 = T.card, BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 30), LayoutOrder = order or 1, Parent = parent })
		corner(b, 8); _KR.press(b)
		b.MouseButton1Click:Connect(function()
			local ok, err = pcall(fn, b); if not ok then warn("[RoClothes] edit:", err) end
			if E.refresh then E.refresh() end
		end)
		return b
	end
	local function lit(b, on, avail)
		b.BackgroundColor3 = on and T.accentD or T.card
		b.TextColor3 = on and T.txt or ((avail == false) and T.txt3 or T.txt2)
	end
	local function grid(parent, order, n)
		local r = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = order, Parent = parent })
		new("UIGridLayout", { CellSize = UDim2.new(1 / n, -math.ceil(6 * (n - 1) / n), 0, 30), CellPadding = UDim2.fromOffset(6, 6), SortOrder = Enum.SortOrder.LayoutOrder, Parent = r })
		return r
	end
	local function pill(parent, text, fn)
		local b = new("TextButton", { AutoButtonColor = false, Size = UDim2.fromOffset(0, 22), AutomaticSize = Enum.AutomaticSize.X, Text = text, Font = FONTB, TextSize = 11.5, TextColor3 = T.txt2, BackgroundColor3 = T.card, BorderSizePixel = 0, ZIndex = 33, Parent = parent })
		corner(b, 11); pad(b, 10, 10, 0, 0); _KR.press(b); b.MouseButton1Click:Connect(fn)
		return b
	end

	local DEFAULT = { parts = { 0, 16, 0.1 }, acc = { 0, 16, 0.6 }, move = { 1, -16, 0.1 }, pose = { 1, -16, 0.45 } }


	local function clampWin(id)
		local f = E.wins[id]
		if not (f and f.Visible) then return end
		local vp = (workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize) or Vector2.new(1280, 720)
		local inset = Vector2.new(0, 0); pcall(function() inset = game:GetService("GuiService"):GetGuiInset() end)
		local scr = f:FindFirstAncestorWhichIsA("ScreenGui")
		local k = (scr and scr.IgnoreGuiInset) and inset or Vector2.new(0, 0)
		local px, py = f.AbsolutePosition.X + k.X, f.AbsolutePosition.Y + k.Y
		local x, y = _KR.editWinClamp(px, py, f.AbsoluteSize, vp)
		if math.abs(x - px) > 0.5 or math.abs(y - py) > 0.5 then
			f.AnchorPoint = Vector2.new(0, 0)
			f.Position = UDim2.fromOffset(x, y)
			ws.pos[id] = { x, y }
			pcall(_KR.saveCfg)
		end
	end
	E.resetPos = function()
		ws.pos = {}
		for id, f in pairs(E.wins) do
			local d = DEFAULT[id]
			f.AnchorPoint = Vector2.new(d[1], 0)
			f.Position = UDim2.new(d[1], d[2], d[3], 0)
		end
		pcall(_KR.saveCfg)
		toast("Edit", "Window positions reset.", "ok")
		for _, id in ipairs(ORDER) do clampWin(id) end
	end
	local function makeWindow(id)
		local d = DEFAULT[id]
		local f = new("Frame", { Name = "Edit_" .. id, AnchorPoint = Vector2.new(d[1], 0), Position = UDim2.new(d[1], d[2], d[3], 0), Size = UDim2.fromOffset(W, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundColor3 = T.bg, BackgroundTransparency = 0.04, BorderSizePixel = 0, Active = true, Visible = false, ZIndex = 30, Parent = screen })
		corner(f, 14)
		_KR.uis(new("UIScale", { Scale = SCALE, Parent = f }), 0.9)
		new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Parent = f })
		local p = ws.pos[id]
		if type(p) == "table" and tonumber(p[1]) and tonumber(p[2]) then f.AnchorPoint = Vector2.new(0, 0); f.Position = UDim2.fromOffset(p[1], p[2]) end
		local bar = new("TextButton", { AutoButtonColor = false, Text = "", BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 40), LayoutOrder = 0, ZIndex = 31, Parent = f })
		lbl({ Position = UDim2.fromOffset(14, 0), Size = UDim2.new(1, -120, 1, 0), Text = string.upper(TITLE[id]), Font = FONTB, TextSize = 12.5, TextColor3 = T.txt, TextXAlignment = Enum.TextXAlignment.Left, ZIndex = 32, Parent = bar })
		local pills = new("Frame", { AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -10, 0.5, 0), Size = UDim2.fromOffset(0, 22), AutomaticSize = Enum.AutomaticSize.X, BackgroundTransparency = 1, ZIndex = 32, Parent = bar })
		new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder, Parent = pills })
		local body = new("ScrollingFrame", { BackgroundTransparency = 1, BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 0), CanvasSize = UDim2.new(0, 0, 0, 0), AutomaticCanvasSize = Enum.AutomaticSize.Y, ScrollingDirection = Enum.ScrollingDirection.Y, ScrollBarThickness = 3, ScrollBarImageColor3 = T.txt3, LayoutOrder = 1, ZIndex = 31, Parent = f })
		pad(body, 12, 12, 0, 12)
		local lay = vlist(body, 7)
		local function fit()
			local vp = (workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize) or Vector2.new(1280, 720)
			body.Size = UDim2.new(1, 0, 0, math.floor(math.min(lay.AbsoluteContentSize.Y / SCALE + 12, vp.Y / SCALE * 0.8 - 40)))
		end
		lay:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(fit); task.defer(fit)
		local foldB = pill(pills, "-", function() body.Visible = not body.Visible end)
		foldB.LayoutOrder = 1
		body:GetPropertyChangedSignal("Visible"):Connect(function() foldB.Text = body.Visible and "-" or "+" end)
		pill(pills, "Dock", function() E.dock(id) end).LayoutOrder = 2
		pill(pills, "Reset", function() E.resetPos() end).LayoutOrder = 3

		local dragging, startM, startP
		bar.InputBegan:Connect(function(io)
			if io.UserInputType == Enum.UserInputType.MouseButton1 or io.UserInputType == Enum.UserInputType.Touch then
				local inset = Vector2.new(0, 0); pcall(function() inset = game:GetService("GuiService"):GetGuiInset() end)
				local scr = f:FindFirstAncestorWhichIsA("ScreenGui")
				local k = (scr and scr.IgnoreGuiInset) and inset or Vector2.new(0, 0)
				f.AnchorPoint = Vector2.new(0, 0); f.Position = UDim2.fromOffset(f.AbsolutePosition.X + k.X, f.AbsolutePosition.Y + k.Y)
				dragging, startM, startP = true, io.Position, f.Position
			end
		end)
		local mc = UserInputService.InputChanged:Connect(function(io)
			if dragging and io.UserInputType == Enum.UserInputType.MouseMovement and not UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) then
				dragging = false
				ws.pos[id] = { f.Position.X.Offset, f.Position.Y.Offset }; pcall(_KR.saveCfg)
				return
			end
			if dragging and (io.UserInputType == Enum.UserInputType.MouseMovement or io.UserInputType == Enum.UserInputType.Touch) then
				local dlt = io.Position - startM
				f.Position = UDim2.fromOffset(startP.X.Offset + dlt.X, startP.Y.Offset + dlt.Y)
			end
		end)
		local me = UserInputService.InputEnded:Connect(function(io)
			if dragging and (io.UserInputType == Enum.UserInputType.MouseButton1 or io.UserInputType == Enum.UserInputType.Touch) then
				dragging = false
				ws.pos[id] = { f.Position.X.Offset, f.Position.Y.Offset }; pcall(_KR.saveCfg)
			end
		end)
		f.Destroying:Connect(function() pcall(function() mc:Disconnect() end); pcall(function() me:Disconnect() end) end)
		return f, body
	end
	local function cur() return Sy.getGizmoTarget and Sy.getGizmoTarget() end
	local function pick(key)
		if Sy.setGizmoTarget and Sy.setGizmoTarget(key) ~= false and Sy.showGizmo3D then Sy.showGizmo3D() end
	end



	local SLOT = { Head = "Head", Torso = "LowerTorso", ["Left Arm"] = "LeftUpperArm", ["Right Arm"] = "RightUpperArm", ["Left Leg"] = "LeftUpperLeg", ["Right Leg"] = "RightUpperLeg" }
	local SAY = { Head = "Head", Torso = "Body", ["Left Arm"] = "Left arm", ["Right Arm"] = "Right arm", ["Left Leg"] = "Left leg", ["Right Leg"] = "Right leg" }
	local function limbOf(key)
		if not key or key:find("^acc:") then return nil end
		local kl, side = key:lower(), key:match("^Left") or key:match("^Right")
		if kl:find("head") then return "Head" end
		if kl:find("torso") then return "Torso" end
		if side and (kl:find("arm") or kl:find("hand")) then return side .. " Arm" end
		if side and (kl:find("leg") or kl:find("foot")) then return side .. " Leg" end
	end
	local function nice(key)
		if key:find("^acc:") then return (key:gsub("^acc:", "")) end
		local l = limbOf(key)
		return l and SAY[l] or key
	end

	BUILD.parts = function(b)
		local paints = {}
		local cap = lbl({ Size = UDim2.new(1, 0, 0, 18), Text = "", Font = FONTB, TextSize = 12.5, TextColor3 = T.accent, TextXAlignment = Enum.TextXAlignment.Center, LayoutOrder = 2, Parent = b })
		local figBox = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 196), LayoutOrder = 1, Parent = b })
		local fig = UI.avatarFigure(figBox, 190)
		for name in pairs(SLOT) do
			local pos, size = fig.rect(name)
			local tb = new("TextButton", { Position = pos, Size = size, BackgroundTransparency = 1, AutoButtonColor = false, Text = "", ZIndex = name == "Torso" and 3 or 4, Parent = fig.overlay })
			tb.MouseButton1Click:Connect(function()
				local keys = {}
				for _, t in ipairs((Sy.getGizmoTargets and Sy.getGizmoTargets()) or {}) do keys[t.key] = true end
				local k = (keys[name] and name) or (keys[SLOT[name]] and SLOT[name])
				if k then pick(k) else toast("Edit", SAY[name] .. " is not on this avatar.", "info") end
				if E.refresh then E.refresh() end
			end)
		end
		table.insert(paints, function()
			local c = cur()
			local on = limbOf(c)
			for name, part in pairs(fig.parts) do part.Color = (name == on) and T.accent or fig.base[name] end
			cap.Text = c and nice(c) or "Tap a part of the drawing or your avatar"
		end)
		return paints
	end

	BUILD.acc = function(b)
		local paints = {}
		local none = lbl({ Size = UDim2.new(1, 0, 0, 18), Text = "No accessories worn.", TextSize = 12, TextColor3 = T.txt3, TextXAlignment = Enum.TextXAlignment.Left, LayoutOrder = 1, Parent = b })
		local acc = grid(b, 2, 2)
		local accSig
		table.insert(paints, function()
			local c = cur()
			local list = (Sy.getAccessoryTargets and Sy.getAccessoryTargets()) or {}
			local sig = {}
			for _, t in ipairs(list) do table.insert(sig, t.key) end
			sig = table.concat(sig, "|")
			if sig ~= accSig then
				accSig = sig
				for _, ch in ipairs(acc:GetChildren()) do if ch:IsA("GuiObject") then ch:Destroy() end end
				for i, t in ipairs(list) do chip(acc, t.label, i, function() pick(t.key) end):SetAttribute("key", t.key) end
			end
			none.Visible = #list == 0
			for _, bt in ipairs(acc:GetChildren()) do if bt:IsA("TextButton") then lit(bt, bt:GetAttribute("key") == c) end end
		end)
		return paints
	end

	BUILD.move = function(b)
		local paints = {}
		local m1, m2 = grid(b, 1, 3), grid(b, 2, 2)
		local modeB = {}
		for i, m in ipairs({ { "Move", "Pos", m1 }, { "Rotate", "Rot", m1 }, { "Size", "Size", m1 }, { "Reach", "Reach", m2 }, { "Look at", "Look", m2 } }) do
			modeB[m[2]] = chip(m[3], m[1], i, function()
				if Sy.setGizmoMode3D then Sy.setGizmoMode3D(m[2]) end
				local c = cur()
				if m[2] == "Reach" and not (c and (c:find("Arm") or c:find("Hand") or c:find("Leg") or c:find("Foot")) and (c:find("^Left") or c:find("^Right"))) then toast("Edit", "Reach works on arms and legs (drag the pink ball). This part gets the move arrows.", "info") end
				if m[2] == "Size" and not (c and c:find("^acc:")) then toast("Edit", "Size works on accessories only.", "info") end
			end)
		end
		table.insert(paints, function()
			local m = (Sy.getGizmoMode3D and Sy.getGizmoMode3D()) or "Pos"
			for k, bt in pairs(modeB) do lit(bt, k == m) end
		end)
		return paints
	end

	BUILD.pose = function(b)
		local paints = {}
		local r1 = grid(b, 1, 3)
		chip(r1, "Pose undo", 1, function() if not (Sy.undoEdit and Sy.undoEdit()) then toast("Edit", "Nothing to undo.", "info") end end)
		chip(r1, "Pose redo", 2, function() if not (Sy.redoEdit and Sy.redoEdit()) then toast("Edit", "Nothing to redo.", "info") end end)
		chip(r1, "Reset part", 3, function()
			if Sy.resetGizmoPart and Sy.resetGizmoPart() then toast("Edit", "That part is back to normal (Undo brings it back).", "ok") else toast("Edit", "Tap an edited body part or accessory first.", "warn") end
		end)
		local r2 = grid(b, 2, 3)
		chip(r2, "Mirror", 1, function()
			if Sy.mirrorGizmo and Sy.mirrorGizmo() then toast("Edit", "Copied to the other side, mirrored.", "ok") else toast("Edit", "Pick a left / right arm or leg joint first.", "warn") end
		end)
		chip(r2, "Copy", 2, function()
			if Sy.copyGizmoPart and Sy.copyGizmoPart() then toast("Edit", "Copied. Pick another part, then Paste.", "ok") else toast("Edit", "Pick a body part or accessory first.", "warn") end
		end)
		chip(r2, "Paste", 3, function()
			local ok, why
			if Sy.pasteGizmoPart then ok, why = Sy.pasteGizmoPart() end
			toast("Edit", ok and "Pasted (Undo takes it back)." or tostring(why or "Couldn't paste."), ok and "ok" or "warn")
		end)
		local r3 = grid(b, 3, 2)
		chip(r3, "Look at camera", 1, function()
			task.spawn(function()
				local ok = Sy.lookAtCamera and Sy.lookAtCamera()
				toast("Edit", ok and "Looking at the camera (Undo takes it back)." or "Couldn't turn the head (no head on this rig?).", ok and "ok" or "warn")
				if E.refresh then E.refresh() end
			end)
		end)
		chip(r3, "Save into outfit", 2, function()
			local name = Sy.currentOwnOutfit and Sy.currentOwnOutfit()
			if not name then toast("Edit", "Wear one of your saved outfits first, or use Save Outfit in Bundles.", "warn"); return end
			local ok, msg = Sy.updateBundle(name)
			toast("Edit", ok and ('Saved your edits into "' .. name .. '".') or tostring(msg or "Couldn't save."), ok and "ok" or "warn")
		end)
		local r4 = grid(b, 4, 2)
		chip(r4, "Hide gizmo", 1, function()
			if Sy.hideGizmo3D then Sy.hideGizmo3D() end
			toast("Edit", "Gizmo hidden. Your pose stays; tap a part to edit again.", "info")
		end)
		chip(r4, "Reset all", 2, function()
			showModal("Reset all edits?", "Every pose and accessory move / rotate / size you made goes back to normal.", {
				{ text = "Cancel" },
				{ text = "Reset", kind = "primary", onClick = function()
					if Sy.resetGizmoPose then Sy.resetGizmoPose() end
					toast("Edit", "All edits reset + animations restored.", "ok")
					if E.refresh then E.refresh() end
				end },
			})
		end)
		local tSym = UI.toggle(b, "Symmetry (other side follows)", Sy._symmetry == true, 5, function(on) if Sy.setSymmetry then Sy.setSymmetry(on) end end)
		local tKeep = UI.toggle(b, "Keep edits on bundle switch", SET.keepEdits ~= false, 6, function(on)
			SET.keepEdits = on; pcall(_KR.saveCfg)
			Sy.keepMyEdits = on
		end)
		paints[#paints + 1] = function()
			local a, k = _KR.tgl[tSym], _KR.tgl[tKeep]
			if a then a.set(Sy._symmetry == true) end
			if k then k.set(SET.keepEdits ~= false) end
		end
		return paints
	end
	local function anyPopped() for _, id in ipairs(ORDER) do if E.popped[id] then return true end end return false end
	local function window(id)
		if E.wins[id] then return E.wins[id] end
		local f, body = makeWindow(id)
		E.paints["win:" .. id] = BUILD[id](body)
		pcall(_KR.skinPass, body)
		E.wins[id] = f
		return f
	end
	local function sync(id)
		local t = E.tiles[id]
		if t and t.docked.Parent then
			t.docked.Visible = not E.popped[id]; t.away.Visible = E.popped[id] == true; t.pop.Visible = not E.popped[id]
		end
		if E.popped[id] then
			local f = window(id)
			f.Visible = E.open
			if f.Visible then task.defer(function() clampWin(id) end) end
		elseif E.wins[id] then E.wins[id].Visible = false end
	end
	E.popOut = function(id)
		E.popped[id] = true; ws.pop[id] = true; pcall(_KR.saveCfg)
		E.open = true; Sy._editBarOpen = true
		sync(id); E.refresh()
	end
	E.dock = function(id)
		E.popped[id] = nil; ws.pop[id] = nil; pcall(_KR.saveCfg)
		sync(id)
		if not anyPopped() then Sy._editBarOpen = false end
		E.refresh()
	end

	E.attach = function(h)
		for i, id in ipairs(ORDER) do
			local t = tile(h, TITLE[id], i)
			local hd = t:FindFirstChild("TileHead")
			local pop = pill(hd or t, "Pop out", function() E.popOut(id) end)
			pop.AnchorPoint = Vector2.new(1, 0); pop.Position = UDim2.new(1, 0, 0, -3)
			local docked = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 1, Parent = t }); vlist(docked, 7)
			E.paints["panel:" .. id] = BUILD[id](docked)
			local away = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 2, Parent = t }); vlist(away, 6)
			UI.hint(away, TITLE[id] .. " is floating beside your avatar.", 1)
			chip(grid(away, 2, 1), "Dock it back here", 1, function() E.dock(id) end)
			E.tiles[id] = { docked = docked, away = away, pop = pop }
		end
		E.open = true
		Sy._editBarOpen = anyPopped()
		for _, id in ipairs(ORDER) do sync(id) end
		E.refresh()
	end
	E.refresh = function()
		for _, list in pairs(E.paints) do
			for _, p in ipairs(list) do local ok, err = pcall(p); if not ok then warn("[RoClothes] edit paint:", err) end end
		end
	end
	E.hide = function()
		E.open = false; Sy._editBarOpen = false
		for _, w in pairs(E.wins) do w.Visible = false end
	end
	E.anyPopped = anyPopped

	local vpConn = screen:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
		for _, id in ipairs(ORDER) do clampWin(id) end
	end)
	screen.Destroying:Connect(function() pcall(function() vpConn:Disconnect() end) end)
	_KR.editBar = E
	local function safeRefresh() pcall(E.refresh) end
	Sy.renderEdit = safeRefresh
	if Sy.gizmoRegisterRefresher then Sy.gizmoRegisterRefresher(safeRefresh) end
end
if System then _KR.buildEditWindows() end



bar.Position = UDim2.new(0.5, 0, 1, BAR_H + 50)
task.spawn(function() while screen.Parent do clock.Text = A.clockText(); pcall(A.styleClock); task.wait(math.clamp(60 - (os.time() % 60) + 0.05, 0.2, 5)) end end)

task.spawn(function()
	while screen.Parent do
		local t = activeTab and tabs[activeTab]
		if t and t.dot and t.dot.BackgroundTransparency < 0.5 and (SET.barStyle or "Dock") == "Dock" then
			tween(t.dot, 1.0, { Size = UDim2.fromOffset(9, 9) }, QUINT); task.wait(1.0)
			tween(t.dot, 1.0, { Size = UDim2.fromOffset(6, 6) }, QUINT); task.wait(1.0)
		else
			task.wait(0.35)
		end
	end
end)






_KR.introAlt = function(style, dim, canvas, firstRun, myName, animate)
	local V = { canvas = canvas }
	local WHITE, DARK = Color3.new(1, 1, 1), Color3.fromRGB(12, 13, 18)
	local alive, readyShown, pNow, stageName, fileName = true, false, 0, nil, ""
	local ins = {}
	local function fadeIn(o, prop, target, delay) ins[#ins + 1] = { o, prop, target, delay or 0 }; return o end
	local function L(props) props.BackgroundTransparency = 1; props.TextTransparency = 1; props.Parent = props.Parent or canvas; props.ZIndex = props.ZIndex or 5; return lbl(props) end
	local function hex(c) return string.format("#%02X%02X%02X", math.floor(c.R * 255 + 0.5), math.floor(c.G * 255 + 0.5), math.floor(c.B * 255 + 0.5)) end
	local function circ(f) new("UICorner", { CornerRadius = UDim.new(0.5, 0), Parent = f }); return f end
	local veil = new("Frame", { Name = "IntroVeil", Size = UDim2.fromScale(1, 1), BackgroundColor3 = DARK, BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 1, Parent = dim })


	local blur
	if SET.blur ~= false then pcall(function()
		blur = new("BlurEffect", { Name = "RCIntroBlur", Size = 0, Parent = workspace.CurrentCamera })
		local goal = (style == "Taskbar") and 18 or 8
		if animate then tween(blur, 0.6, { Size = goal }) else blur.Size = goal end
		local sg = dim:FindFirstAncestorOfClass("ScreenGui"); if sg then sg.Destroying:Connect(function() pcall(function() blur:Destroy() end) end) end
	end) end
	V.hit = new("TextButton", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Text = "", AutoButtonColor = false, ZIndex = 30, Parent = dim })
	local vals, status, fill, pctL, metaL, enter, dots, barG = {}, nil, nil, nil, nil, nil, nil, nil
	local who = firstRun and "Setting up for the first time" or ("Welcome back, " .. myName)
	local STEPS = { "Checking your executor", "Loading bundles", "Loading items" }
	if style == "Taskbar" then
		fadeIn(veil, "BackgroundTransparency", 0.4, 0)
		local function hhmm() local d = os.date("*t"); if SET.clock24 ~= false then return string.format("%02d:%02d", d.hour, d.min) end; local h = d.hour % 12; return string.format("%d:%02d", h == 0 and 12 or h, d.min) end
		local clock = fadeIn(L({ AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.fromOffset(640, 76), Size = UDim2.fromOffset(600, 100), Text = hhmm(), Font = FONTB, TextSize = 96, TextXAlignment = Enum.TextXAlignment.Center }), "TextTransparency", 0, 0.15)
		fadeIn(L({ AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.fromOffset(640, 180), Size = UDim2.fromOffset(600, 24), Text = os.date("%A, %B ") .. tostring(tonumber(os.date("%d"))), TextSize = 19, TextColor3 = Color3.fromRGB(227, 228, 236), TextXAlignment = Enum.TextXAlignment.Center }), "TextTransparency", 0, 0.15)
		task.spawn(function() while alive and clock.Parent do task.wait(1); clock.Text = hhmm() end end)

		local ringT = circ(new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromOffset(640, 318), Size = UDim2.fromOffset(100, 100), BackgroundColor3 = T.accent, BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 4, Parent = canvas }))
		fadeIn(ringT, "BackgroundTransparency", 0, 0.25)
		local pic = _KR.HL.avatar(canvas, 92, { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromOffset(640, 318), ZIndex = 5 })
		pic.BackgroundTransparency = 1; pic.ImageTransparency = 1
		fadeIn(pic, "BackgroundTransparency", 0, 0.28); fadeIn(pic, "ImageTransparency", 0, 0.28)
		fadeIn(L({ AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.fromOffset(640, 380), Size = UDim2.fromOffset(600, 34), RichText = true, Text = 'RoClothes:<font color="' .. hex(T.accent:Lerp(WHITE, 0.3)) .. '">Krul</font>', Font = FONTB, TextSize = 26, TextXAlignment = Enum.TextXAlignment.Center }), "TextTransparency", 0, 0.3)
		fadeIn(L({ AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.fromOffset(640, 416), Size = UDim2.fromOffset(600, 18), Text = who, TextSize = 13, TextColor3 = Color3.fromRGB(195, 197, 210), TextXAlignment = Enum.TextXAlignment.Center }), "TextTransparency", 0, 0.35)

		dots = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromOffset(640, 470), Size = UDim2.fromOffset(34, 34), BackgroundTransparency = 1, Visible = not firstRun, ZIndex = 4, Parent = canvas })
		local dd = {}
		for i = 1, 5 do dd[i] = circ(new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(0.5, 0, 0.5, -15), Size = UDim2.fromOffset(5, 5), BackgroundColor3 = WHITE, BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 4, Parent = dots })) end
		V._dots = function()
			if not animate then for _, d in ipairs(dd) do d.BackgroundTransparency = 0.6 end; return end
			task.spawn(function()
				local t0 = os.clock()
				while alive and dots.Visible and dots.Parent do
					local t = (os.clock() - t0) / SPEED
					for i, d in ipairs(dd) do
						local ph = ((t - (i - 1) * 0.12) % 2.2) / 2.2
						local e = math.clamp(ph / 0.86, 0, 1); e = (e < 0.5) and 4 * e ^ 3 or 1 - (-2 * e + 2) ^ 3 / 2
						local a = math.rad(e * 720)
						d.Position = UDim2.new(0.5, math.sin(a) * 15, 0.5, -math.cos(a) * 15); d.BackgroundTransparency = (ph < 0.86) and 0 or 1
					end
					task.wait()
				end
			end)
		end
		status = fadeIn(L({ AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.fromOffset(640, 496), Size = UDim2.fromOffset(600, 18), Text = firstRun and "" or STEPS[1], TextSize = 13, TextColor3 = Color3.fromRGB(217, 218, 227), TextXAlignment = Enum.TextXAlignment.Center, Visible = not firstRun }), "TextTransparency", 0, 0.4)
		barG = new("Frame", { AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.fromOffset(640, 458), Size = UDim2.fromOffset(300, 60), BackgroundTransparency = 1, Visible = firstRun, ZIndex = 4, Parent = canvas })
		local trk = fadeIn(new("Frame", { Size = UDim2.new(1, 0, 0, 3), BackgroundColor3 = WHITE, BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 4, Parent = barG }), "BackgroundTransparency", 0.82, 0.4); new("UICorner", { CornerRadius = UDim.new(0, 2), Parent = trk })
		fill = fadeIn(new("Frame", { Size = UDim2.fromScale(0, 1), BackgroundColor3 = T.accent, BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 5, Parent = trk }), "BackgroundTransparency", 0, 0.4); new("UICorner", { CornerRadius = UDim.new(0, 2), Parent = fill })
		local stL = fadeIn(L({ Position = UDim2.fromOffset(0, 12), Size = UDim2.new(1, -60, 0, 16), Text = "Connecting", TextSize = 12.5, TextColor3 = Color3.fromRGB(217, 218, 227), TextXAlignment = Enum.TextXAlignment.Left, Parent = barG }), "TextTransparency", 0, 0.4)
		V._stageL = stL
		pctL = fadeIn(L({ AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, 0, 0, 12), Size = UDim2.fromOffset(60, 16), Text = "0%", TextSize = 12.5, TextColor3 = Color3.fromRGB(217, 218, 227), TextXAlignment = Enum.TextXAlignment.Right, Parent = barG }), "TextTransparency", 0, 0.4)
		metaL = fadeIn(L({ Position = UDim2.fromOffset(0, 32), Size = UDim2.new(1, 0, 0, 16), Text = "", TextSize = 11.5, TextColor3 = Color3.fromRGB(170, 172, 186), TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd, Parent = barG }), "TextTransparency", 0, 0.4)
		enter = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromOffset(640, 476), Size = UDim2.fromOffset(124, 34), BackgroundColor3 = T.accent, BackgroundTransparency = 1, BorderSizePixel = 0, Visible = false, ZIndex = 6, Parent = canvas }); new("UICorner", { CornerRadius = UDim.new(0, 4), Parent = enter })
		V._enterL = L({ Size = UDim2.fromScale(1, 1), Text = "Enter", Font = FONTB, TextSize = 14, TextColor3 = Color3.fromRGB(26, 12, 18), TextXAlignment = Enum.TextXAlignment.Center, ZIndex = 7, Parent = enter })
		V.hit.AnchorPoint = Vector2.new(0.5, 0.5); V.hit.Position = UDim2.fromScale(0.5, 0.5); V.hit.Size = UDim2.new(1, 16, 1, 16); V.hit.ZIndex = 8; V.hit.Parent = enter

		local info = new("Frame", { AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.fromOffset(640, 586), Size = UDim2.fromOffset(470, 30), BackgroundColor3 = Color3.fromRGB(233, 74, 96), BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 4, Parent = canvas }); new("UICorner", { CornerRadius = UDim.new(0, 4), Parent = info })
		fadeIn(info, "BackgroundTransparency", 0.86, 0.6)
		fadeIn(new("Frame", { Size = UDim2.new(0, 3, 1, 0), BackgroundColor3 = Color3.fromRGB(233, 74, 96), BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 5, Parent = info }), "BackgroundTransparency", 0, 0.6)
		fadeIn(L({ Position = UDim2.fromOffset(14, 0), Size = UDim2.new(1, -20, 1, 0), Text = _KR.HL.WARN_SHORT, TextSize = 12, TextColor3 = Color3.fromRGB(240, 214, 220), TextXAlignment = Enum.TextXAlignment.Left, Parent = info }), "TextTransparency", 0, 0.6)
		for i, k in ipairs({ "Version", "Executor", "Bundles", "Items" }) do
			local c = new("Frame", { Position = UDim2.fromOffset(392 + (i - 1) * 126, 632), Size = UDim2.fromOffset(118, 50), BackgroundColor3 = WHITE, BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 4, Parent = canvas }); new("UICorner", { CornerRadius = UDim.new(0, 6), Parent = c })
			fadeIn(c, "BackgroundTransparency", 0.93, 0.4 + i * 0.05)
			fadeIn(L({ Position = UDim2.fromOffset(14, 8), Size = UDim2.new(1, -20, 0, 14), Text = k, TextSize = 11.5, TextColor3 = Color3.fromRGB(174, 176, 189), TextXAlignment = Enum.TextXAlignment.Left, Parent = c }), "TextTransparency", 0, 0.4 + i * 0.05)
			vals[i] = fadeIn(L({ Position = UDim2.fromOffset(14, 23), Size = UDim2.new(1, -20, 0, 20), Text = "--", Font = FONTB, TextSize = 15, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd, Parent = c }), "TextTransparency", 0, 0.4 + i * 0.05)
		end
		V.warnAt = { UDim2.fromOffset(640, 556), Enum.TextXAlignment.Center }
	else
		new("UIGradient", { Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.22), NumberSequenceKeypoint.new(0.55, 0.55), NumberSequenceKeypoint.new(1, 0.8) }), Parent = veil })
		fadeIn(veil, "BackgroundTransparency", 0, 0)
		fadeIn(L({ Position = UDim2.fromOffset(110, 150), Size = UDim2.fromOffset(600, 16), Text = "BY KRULHUB", Font = Enum.Font.Code, TextSize = 12, TextColor3 = Color3.fromRGB(178, 180, 194), TextXAlignment = Enum.TextXAlignment.Left }), "TextTransparency", 0, 0.2)
		local wmL = L({ Position = UDim2.fromOffset(104, 172), Size = UDim2.fromOffset(1080, 116), RichText = true, Text = 'RoClothes:<font color="' .. hex(T.accent) .. '">Krul</font>', TextSize = 108, TextXAlignment = Enum.TextXAlignment.Left })
		_KR.HL.light(wmL); fadeIn(wmL, "TextTransparency", 0, 0.3)
		fadeIn(L({ Position = UDim2.fromOffset(110, 300), Size = UDim2.fromOffset(900, 24), RichText = true, Text = firstRun and who or ("Welcome back, <b>" .. myName:gsub("&", "&amp;"):gsub("<", "&lt;"):gsub(">", "&gt;") .. "</b>"), TextSize = 18, TextColor3 = Color3.fromRGB(207, 208, 220), TextXAlignment = Enum.TextXAlignment.Left }), "TextTransparency", 0, 0.45)
		for i, k in ipairs({ "VERSION", "EXECUTOR", "BUNDLES", "ITEMS" }) do
			local x = 110 + (i - 1) * 196
			if i > 1 then fadeIn(new("Frame", { Position = UDim2.fromOffset(x - 28, 372), Size = UDim2.fromOffset(1, 54), BackgroundColor3 = WHITE, BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 4, Parent = canvas }), "BackgroundTransparency", 0.84, 0.55) end
			vals[i] = fadeIn(L({ Position = UDim2.fromOffset(x, 370), Size = UDim2.fromOffset(160, 34), Text = "--", TextSize = 28, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd }), "TextTransparency", 0, 0.55)
			fadeIn(L({ Position = UDim2.fromOffset(x, 408), Size = UDim2.fromOffset(160, 14), Text = k, Font = Enum.Font.Code, TextSize = 11.5, TextColor3 = Color3.fromRGB(169, 171, 185), TextXAlignment = Enum.TextXAlignment.Left }), "TextTransparency", 0, 0.55)
		end
		local trk = fadeIn(new("Frame", { Position = UDim2.fromOffset(110, 624), Size = UDim2.fromOffset(1060, 1), BackgroundColor3 = WHITE, BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 4, Parent = canvas }), "BackgroundTransparency", 0.8, 0.3)
		fill = fadeIn(new("Frame", { Position = UDim2.fromOffset(0, -0.5), Size = UDim2.new(0, 0, 0, 2), BackgroundColor3 = T.accent, BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 5, Parent = trk }), "BackgroundTransparency", 0, 0.3)
		status = fadeIn(L({ Position = UDim2.fromOffset(110, 636), Size = UDim2.fromOffset(900, 18), RichText = true, Text = firstRun and "Connecting" or STEPS[1], TextSize = 13, TextColor3 = Color3.fromRGB(196, 197, 209), TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd }), "TextTransparency", 0, 0.3)
		pctL = fadeIn(L({ AnchorPoint = Vector2.new(1, 0), Position = UDim2.fromOffset(1170, 636), Size = UDim2.fromOffset(120, 18), Text = "000%", Font = Enum.Font.Code, TextSize = 12.5, TextColor3 = Color3.fromRGB(231, 231, 239), TextXAlignment = Enum.TextXAlignment.Right }), "TextTransparency", 0, 0.3)
		V.warnAt = { UDim2.fromOffset(110, 560), Enum.TextXAlignment.Left }
	end
	function V.open()
		for _, it in ipairs(ins) do
			local o, pr, tg, dl = it[1], it[2], it[3], it[4]
			if animate then task.delay(dl * SPEED, function() if alive and o.Parent then tween(o, 0.5, { [pr] = tg }) end end) else o[pr] = tg end
		end
		if dots and not firstRun then if animate then task.delay(0.4 * SPEED, function() if alive then V._dots() end end) else V._dots() end end
	end
	local function line()
		if style ~= "Minimal" or readyShown then return end
		if firstRun then status.Text = (stageName or "Connecting") .. (fileName ~= "" and ("  ·  " .. fileName) or "") end
	end
	function V.progress(p)
		pNow = math.clamp(p, 0, 1)
		if fill then fill.Size = (style == "Minimal") and UDim2.new(pNow, 0, 0, 2) or UDim2.fromScale(pNow, 1) end
		if pctL then pctL.Text = (style == "Minimal") and string.format("%03d%%", math.floor(pNow * 100 + 0.5)) or (math.floor(pNow * 100 + 0.5) .. "%") end
		if not firstRun and not readyShown and status then status.Text = STEPS[math.clamp(math.floor(pNow * 3) + 1, 1, 3)] end
	end
	function V.stage(_, name) stageName = name; if V._stageL then V._stageL.Text = name end; line() end
	function V.meta(tc, file)
		fileName = file or ""
		if metaL then metaL.Text = (tc or "") .. ((file and file ~= "") and ("   ·   " .. file) or "") end
		line()
	end
	function V.readout(i, txt) if vals[i] then vals[i].Text = txt end end
	function V.place(o)
		o.Parent = canvas; o.Position = V.warnAt[1]; o.AnchorPoint = Vector2.new(V.warnAt[2] == Enum.TextXAlignment.Left and 0 or 0.5, 0.5); o.TextXAlignment = V.warnAt[2]; o.TextStrokeTransparency = 1
	end
	function V.error()
		if status then status.Visible = true; status.Text = "Download failed"; status.TextColor3 = Color3.fromRGB(255, 120, 130) end
		if V._stageL then V._stageL.Text = "Download failed"; V._stageL.TextColor3 = Color3.fromRGB(255, 120, 130) end
	end
	function V.ready()
		if readyShown then return end; readyShown = true
		V.progress(1)
		if style == "Taskbar" then
			if dots then dots.Visible = false end
			if status and status.Text ~= "Download failed" then status.Visible = false end
			if barG then barG.Visible = false end
			enter.Visible = true; V._enterL.TextTransparency = 1
			if animate then
				local sc = new("UIScale", { Scale = 0.9, Parent = enter }); tween(sc, 0.4, { Scale = 1 }, BACK)
				tween(enter, 0.35, { BackgroundTransparency = 0 }); tween(V._enterL, 0.35, { TextTransparency = 0 })
			else enter.BackgroundTransparency = 0; V._enterL.TextTransparency = 0 end
		else
			if status.Text ~= "Download failed" then status.Text = '<b><font color="#FFFFFF">Tap anywhere to enter</font></b>  <font color="' .. hex(T.accent) .. '">&gt;</font>' end
			if animate then task.spawn(function()
				while alive and status.Parent do tween(status, 1.1, { TextTransparency = 0.35 }, Enum.EasingStyle.Sine); task.wait(1.1 * SPEED); if not alive then break end; tween(status, 1.1, { TextTransparency = 0 }, Enum.EasingStyle.Sine); task.wait(1.1 * SPEED) end
			end) end
		end
	end
	function V.exit()
		alive = false
		if blur then tween(blur, 0.45, { Size = 0 }); local b = blur; task.delay(0.5 * SPEED, function() pcall(function() b:Destroy() end) end) end
	end
	return V
end
A.playIntro = function(previewDownload)

	pcall(function() local ex = PlayerGui:FindFirstChild("RoClothesIntro"); if ex then ex:Destroy() end end)
	if MP.introVpConn then pcall(function() MP.introVpConn:Disconnect() end); MP.introVpConn = nil end
	local function reveal()
		if _KR.cfgLoaded and not _KR.cfgApplied then
			_KR.cfgApplied = true
			SPEED = BASE_SPEED * (100 / math.max(10, SET.animSpeed))
			local sa = SET.accent
			pcall(A.applyTheme, true); if SET.accent ~= sa then SET.accent = sa; pcall(A.applyTheme, false) end
			for _, fn in ipairs({ A.applyBarSize, A.applyBarLabels, A.applyTabs, A.applyClock, A.applyCorner, A.applyGlass, A.applyTrans, A.applyToast }) do pcall(fn) end
			if SET.uiFont ~= "Gotham" then pcall(A.applyFont) end
			pcall(densify)
			if SET.autoHide then pcall(A.startAuto) end
		end
		A.applyStyle()
		_KR.barShown = true; A.applyClock()
		local rest = bar.Position
		if SET.barStyle == "Minimal" then bar.Position = rest + UDim2.new(0, -(BAR_H + 80), 0, 0)
		else bar.Position = rest + UDim2.new(0, 0, 0, SET.barTop and -(BAR_H + 50) or (BAR_H + 50)) end
		tween(bar, 0.7, { Position = rest }, QUINT)
		if SET.cardAnims and not SET.reduceMotion then
			for i, sec in ipairs(SECTIONS) do
				local t = tabs[sec.id]
				if t and t.iconScale then
					_KR.springStop(t.iconScale, "Scale"); t.iconScale.Scale = 0.2
					task.delay((0.22 + i * 0.045) * SPEED, function() if t.iconScale.Parent then _KR.spring(t.iconScale, "Scale", 0.9, 2.6, 0.6) end end)
				end
			end
		end
		task.delay(0.5, function() pcall(function() _KR.chev.Visible = true end) end)

		task.delay(1.1, function() toast("Welcome to RoClothes:Krul", "Your SmartBar is ready - tap a tab to start, or your avatar for Home.", "ok") end)
	end



	local DW, DH = 1280, 720
	local ov = new("ScreenGui", { Name = "RoClothesIntro", IgnoreGuiInset = true, ResetOnSpawn = false, DisplayOrder = 2000, Parent = PlayerGui })
	GUIObject.IntroScreen = ov
	local dim = new("Frame", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 1, Parent = ov })
	local content = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromOffset(DW, DH), BackgroundTransparency = 1, ZIndex = 2, Parent = dim })
	local introScale = new("UIScale", { Scale = 1, Parent = content })
	local AV, altScale
	local function fitIntro()
		local cam = workspace.CurrentCamera
		local vw, vh = (cam and cam.ViewportSize.X) or 1280, (cam and cam.ViewportSize.Y) or 720
		introScale.Scale = math.max(0.3, math.min((vw - 24) / DW, (vh - 24) / DH))
		if altScale then altScale.Scale = introScale.Scale end
	end
	fitIntro(); pcall(function() MP.introVpConn = workspace.CurrentCamera:GetPropertyChangedSignal("ViewportSize"):Connect(fitIntro) end)


	local FORCE_FIRST_RUN = false
	local preview = previewDownload == true
	local firstRun = preview or FORCE_FIRST_RUN or (System and System._firstRunInstallPending == true) or false

	local done = false
	local animate = SET.cardAnims and not SET.reduceMotion
	local SINE = Enum.EasingStyle.Sine
	local WHITE = Color3.new(1, 1, 1)
	local function W(t) task.wait(math.max(0.03, t * SPEED)) end
	local function circle(parent, size, z, col, tr)
		local f = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = size, BackgroundColor3 = col or WHITE, BackgroundTransparency = tr or 1, BorderSizePixel = 0, ZIndex = z, Parent = parent })
		new("UICorner", { CornerRadius = UDim.new(0.5, 0), Parent = f })
		return f
	end


	local function ringStroke(f, col, th, tr)
		return new("UIStroke", { Color = col, Thickness = th, Transparency = tr or 0, ApplyStrokeMode = Enum.ApplyStrokeMode.Border, Parent = f })
