					if GUIObject.ImageHeal.Visible ~= want then GUIObject.ImageHeal.Visible = want; GUIObject.ImageTear.Visible = want end
				end
				task.wait((G.Visible and G.GroupTransparency < 1) and 0 or 0.25)
			end
		end)
	end)()
end


