	local function rehydrate(node, _depth)
		if type(node) ~= "table" then return node end
		_depth = _depth or 0
		if _depth > 64 then
			warn("[RoClothes] rehydrate: nesting depth exceeded 64; bundle data trimmed.")
			return nil
		end
		local tag = node.__t
		if tag == "V3" then

			local _ok, _vv = pcall(function()
				local v = node.v
				return Vector3.new(v[1], v[2], v[3])
			end)
			return _ok and _vv or nil
		elseif tag == "CF" then
			local _ok, _vv = pcall(function()
				local v = node.v
				if #v == 12 then
					return CFrame.new(v[1],v[2],v[3], v[4],v[5],v[6], v[7],v[8],v[9], v[10],v[11],v[12])
				elseif #v == 3 then
					return CFrame.new(v[1], v[2], v[3])
				elseif #v == 0 then
					return CFrame.new()
				else
					error("rehydrate: bad CF arity " .. tostring(#v))
				end
			end)
			return _ok and _vv or nil
		elseif tag == "C3" then
			local _ok, _vv = pcall(function()
				local v = node.v
				return Color3.fromRGB(v[1], v[2], v[3])
			end)
			return _ok and _vv or nil
		elseif tag == "C3n" then
			local _ok, _vv = pcall(function()
				local v = node.v
				return Color3.new(v[1], v[2], v[3])
			end)
			return _ok and _vv or nil
		elseif tag == "E" then

			local _okE, _ev = pcall(function() return Enum[node.p][node.v] end)
			return (_okE and typeof(_ev) == "EnumItem") and _ev or nil
		end

		local out = {}
		for k, val in pairs(node) do
			local rk
			if type(k) == "string" and string.sub(k, 1, 1) == "#" then
				rk = tonumber(string.sub(k, 2))
				if rk == nil or rk ~= rk then rk = k end
			else
				rk = k
			end
			out[rk] = rehydrate(val, _depth + 1)
		end
		return out
	end



	System._rcRehydrateInPlace = function(node, _depth)
		if type(node) ~= "table" then return node end
		_depth = _depth or 0
		if _depth > 64 then
			warn("[RoClothes] rehydrate: nesting depth exceeded 64; bundle data trimmed.")
			return nil
		end
		if node.__t ~= nil then return rehydrate(node, _depth) end
		local renames
		for k, val in pairs(node) do
			if type(val) == "table" then
				local nv = System._rcRehydrateInPlace(val, _depth + 1)
				if nv ~= val then node[k] = nv end
			end
			if type(k) == "string" and string.sub(k, 1, 1) == "#" then
				renames = renames or {}
				renames[#renames + 1] = k
			end
		end
		if renames then
			for _, k in ipairs(renames) do
				local rk = tonumber(string.sub(k, 2))
				if rk ~= nil and rk == rk then
					local v = node[k]
					node[k] = nil
					node[rk] = v
				end
			end
		end
		return node
	end




	local function dehydrate(node, _depth, _seen)
		_depth = _depth or 0
		if _depth > 32 then return nil end
		local tv = typeof(node)
		if tv == "Vector3" then
			return {__t = "V3", v = {node.X, node.Y, node.Z}}
		elseif tv == "CFrame" then
			return {__t = "CF", v = {node:GetComponents()}}
		elseif tv == "Color3" then
			return {__t = "C3n", v = {node.R, node.G, node.B}}
		elseif tv == "EnumItem" then
			return {__t = "E", p = (tostring(node.EnumType):gsub("^Enum%.", "")), v = node.Name}
		elseif tv == "number" then
			if node ~= node or node == math.huge or node == -math.huge then return nil end
			return node
		elseif tv == "string" or tv == "boolean" then
			return node
		elseif tv ~= "table" then
			return nil
		end



		_seen = _seen or {}
		if _seen[node] then return nil end
		_seen[node] = true
		local out = {}
		for k, val in pairs(node) do
			local sk
			if type(k) == "number" then
				sk = "#" .. tostring(k)
			else
				sk = k
			end
			out[sk] = dehydrate(val, _depth + 1, _seen)
		end
		_seen[node] = nil
		return out
	end





	pcall(function()
