	Function._runContentInstall = function(force, repair, onProgress)
		if Function._redlInProgress then return "busy" end
		Function._redlInProgress = true
		System._contentInstalled = false
		System._installGen = (System._installGen or 0) + 1
		local myGen = System._installGen
		task.spawn(function()
			local ok = pcall(Function.InstallContentAssets, force, onProgress, repair)
			Function._redlInProgress = false
			if myGen == System._installGen then System._contentInstalled = (ok and _rcMarkerExists(env.isfile)) and true or false end
			if onProgress then pcall(onProgress, nil, nil, nil, nil, nil, ok and "complete" or "error") end
		end)
	end
	System.doRedownload = function(onProgress) return Function._runContentInstall(true, false, onProgress) end
	System.doContentCheck = function(onProgress) return Function._runContentInstall(false, true, onProgress) end






















	do

	local function _gizZero()
		return { PosX=0, PosY=0, PosZ=0, RotX=0, RotY=0, RotZ=0, RotCF=CFrame.new() }
	end



	System.gizmoRegisterRefresher = function(fn)
		if type(fn) == "function" then table.insert(GizmoSliderRefreshers, fn) end
	end





	System.getGizmoTargets = function()
		local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
		local out = {}
		local char = (Function.ResolveTargetChar and Function.ResolveTargetChar(sp)) or (Player and Player.Character)
		if not char then return out end
		local cur = (PlayerData[sp] and PlayerData[sp].GizmoTarget) or nil


		local names, seen = {}, {}
		for _, m in ipairs(char:GetDescendants()) do

			local p = (m:IsA("Motor6D") and m.Part1) or (m:IsA("AnimationConstraint") and m.Attachment1 and m.Attachment1.Parent)
			if p and p:IsA("BasePart") then
				local nm = p.Name
				local _l = nm:lower()
				if not seen[nm] and (_l:find("arm") or _l:find("leg") or _l:find("torso") or _l:find("head") or _l:find("hand") or _l:find("foot")) then
					seen[nm] = true; table.insert(names, nm)
				end
			end
		end
		table.sort(names, function(a, b) return a:lower() < b:lower() end)
		for _, nm in ipairs(names) do
			table.insert(out, { key = nm, label = nm, kind = "joint", selected = (cur == nm) })
		end
		return out
	end

	System.getGizmoTarget = function()
		local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
		local pd = PlayerData[sp]
		return pd and pd.GizmoTarget or nil
	end







	System.setGizmoTarget = function(key)
		local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
		local pd = PlayerData[sp]
		if not pd or type(key) ~= "string" then return false end
		pd.GizmoOffsets = pd.GizmoOffsets or {}
		if not pd.GizmoOffsets[key] then
			if key:sub(1, 4) == "acc:" then

				local char = Function.ResolveTargetChar(sp)
				local acc = char and char:FindFirstChild(key:sub(5))
				if not acc then
					local m2 = System.M2FName and workspace:FindFirstChild(System.M2FName)
					local px = m2 and m2:FindFirstChild(sp)
					acc = px and px:FindFirstChild(key:sub(5))
				end
				local handle = acc and acc:IsA("Accessory") and acc:FindFirstChild("Handle")
				local weld = handle and handle:FindFirstChildWhichIsA("Weld")
				if not weld then return false end
				local z = _gizZero()
				z.baseC0 = weld.C0
				z.baseC1 = weld.C1
				pd.GizmoOffsets[key] = z
			else
				pd.GizmoOffsets[key] = _gizZero()
			end
		end
		pd.GizmoTarget = key
		pd.GizmoOffset = pd.GizmoOffsets[key]
		return true
	end











	System._giz3dMode = System._giz3dMode or "Pos"









	local function _giz3dChar()
		local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
		return (Function.ResolveTargetChar and Function.ResolveTargetChar(sp)) or (Player and Player.Character)
	end



	local function _isPoseJoint(j) return j:IsA("Motor6D") or j:IsA("AnimationConstraint") end
	local function _jPart(j) if j:IsA("Motor6D") then return j.Part1 end local a = j.Attachment1; return a and a.Parent end
	local function _jGetC0(j) if j:IsA("Motor6D") then return j.C0 end local a = j.Attachment0; return (a and a.CFrame) or CFrame.new() end
	local function _jSetC0(j, cf) if j:IsA("Motor6D") then j.C0 = cf return end local a = j.Attachment0; if a then a.CFrame = cf end end
	local function _jGetC1(j) if j:IsA("Motor6D") then return j.C1 end local a = j.Attachment1; return (a and a.CFrame) or CFrame.new() end
	local function _jSetC1(j, cf) if j:IsA("Motor6D") then j.C1 = cf return end local a = j.Attachment1; if a then a.CFrame = cf end end
	local function _jKinematic(j) if j:IsA("AnimationConstraint") then pcall(function() j.IsKinematic = true end) end end

	local function _giz3dResolveJoint(key)
		if type(key) ~= "string" then return nil, nil end
		local char = _giz3dChar(); if not char then return nil, nil end
		local part = char:FindFirstChild(key)
		if not (part and part:IsA("BasePart")) then
			part = nil
			for _, d in ipairs(char:GetDescendants()) do if d:IsA("BasePart") and d.Name == key then part = d; break end end
		end
		if not part then return nil, nil end
		for _, m in ipairs(char:GetDescendants()) do
			if _isPoseJoint(m) and _jPart(m) == part then return m, part end
		end
		return nil, part
	end
	local function _giz3dContainer()
		return (Player and Player:FindFirstChildOfClass("PlayerGui")) or ((gethui and gethui()) or game:GetService("CoreGui"))
	end


	System._giz3dStep = System._giz3dStep or 0.001
	local function _snap(v, step) step = step or 0.001; return math.floor(v / step + 0.5) * step end
	System._giz3dOrig = System._giz3dOrig or {}


	local function _giz3dSetAnims(char, on)
		if not char then return end




		if on then
			for j, o in pairs(System._giz3dOrig) do
				if typeof(j) == "Instance" and j.Parent and j:IsDescendantOf(char) and typeof(o) == "table" and o.C1 then
					pcall(function()
						local eff = (j:IsA("Motor6D") and j.C0 or j.Attachment0.CFrame) * (j:IsA("Motor6D") and j.C1 or j.Attachment1.CFrame):Inverse()
						if j:IsA("Motor6D") then j.C1 = o.C1; j.C0 = eff * o.C1
						else j.Attachment1.CFrame = o.C1; j.Attachment0.CFrame = eff * o.C1 end
					end)
				end
			end
		end
		local an = char:FindFirstChild("Animate"); if an then pcall(function() an.Enabled = on end) end
		pcall(function() char:SetAttribute("PoseApplied", not on) end)
		if on then return end
		local hum = char:FindFirstChildOfClass("Humanoid")
		local animator = hum and hum:FindFirstChildOfClass("Animator")
		if animator then for _, tr in ipairs(animator:GetPlayingAnimationTracks()) do pcall(function() tr:Stop(0) end) end end
	end

	local function _giz3dNormalize(joint)
		if not System._giz3dOrig[joint] then System._giz3dOrig[joint] = { C0 = _jGetC0(joint), C1 = _jGetC1(joint) } end
		_jKinematic(joint)
		local c1 = _jGetC1(joint)
		if c1.Rotation == CFrame.new().Rotation then return end
		_jSetC0(joint, _jGetC0(joint) * c1.Rotation:Inverse())
		_jSetC1(joint, c1 * c1.Rotation:Inverse())
	end
	System._isPosed = function(char)
		for j, o in pairs(System._giz3dOrig) do
			if typeof(j) == "Instance" and j.Parent and j:IsDescendantOf(char) then
				local ok, d = pcall(function()

					local a = (o.C0 * o.C1:Inverse()):Inverse() * (_jGetC0(j) * _jGetC1(j):Inverse())
					local _, ra = a:ToAxisAngle()
					return a.Position.Magnitude + math.abs(ra)
				end)
				if ok and d > 1e-3 then return true end
			end
		end
		return false
	end



	do
		local holdConns = {}
		local function holdAnims(char)
			for _, c in ipairs(holdConns) do pcall(function() c:Disconnect() end) end
			holdConns = {}
			if not char then return end
			local function guard()
				task.defer(function()
					if System._giz3dFrozeChar ~= char and not (System._isPosed and System._isPosed(char)) then return end
					if not (System._isPosed and System._isPosed(char)) then return end
					local an = char:FindFirstChild("Animate")
					if an and an.Enabled then pcall(_giz3dSetAnims, char, false); System._giz3dFrozeChar = char end
				end)
			end
			local function watch(an)
				if an and an.Name == "Animate" then holdConns[#holdConns + 1] = an:GetPropertyChangedSignal("Enabled"):Connect(guard); guard() end
			end
			watch(char:FindFirstChild("Animate"))
			holdConns[#holdConns + 1] = char.ChildAdded:Connect(watch)
		end
		System.GlobalMaid:Give(Player.CharacterAdded:Connect(holdAnims))
		holdAnims(Player.Character)
	end
	System.hideGizmo3D = function(keepFrozen)
		if System._ikParts then for _, x in ipairs(System._ikParts) do pcall(function() x:Destroy() end) end System._ikParts = nil end
		System._ikBegin, System._ikEnd = nil, nil
		if System._giz3dConns then for _, c in ipairs(System._giz3dConns) do pcall(function() c:Disconnect() end) end System._giz3dConns = nil end
		if System._giz3dHandle then pcall(function() System._giz3dHandle:Destroy() end) System._giz3dHandle = nil end


		local hrp = System._giz3dHrp or (System._giz3dFrozeChar and System._giz3dFrozeChar:FindFirstChild("HumanoidRootPart"))


		local isClone = false
		if hrp and System.NPCs then for _, m in pairs(System.NPCs) do if typeof(m) == "Instance" and hrp:IsDescendantOf(m) then isClone = true; break end end end
		if hrp then pcall(function() hrp.Anchored = isClone end) end
		System._giz3dHrp = nil



		if not keepFrozen and System._giz3dFrozeChar and not (System._isPosed and System._isPosed(System._giz3dFrozeChar)) then
			pcall(_giz3dSetAnims, System._giz3dFrozeChar, true); System._giz3dFrozeChar = nil
		end
	end




	local function _giz3dAccRoots()
		local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
		local roots = { _giz3dChar() }
		local m2 = System.M2FName and workspace:FindFirstChild(System.M2FName)
		if m2 and m2:FindFirstChild(sp) then table.insert(roots, m2[sp]) end
		return roots
	end
	local function _giz3dAcc(key)
		local name = key:sub(5)
		for _, r in ipairs(_giz3dAccRoots()) do
			local acc = r and r:FindFirstChild(name)
			local h = acc and acc:IsA("Accessory") and acc:FindFirstChild("Handle")
			local w = h and h:FindFirstChildWhichIsA("Weld")
			if h and w and w.Part0 and w.Part1 then return h, w end
		end
	end
	System.getAccessoryTargets = function()
		local out, seen = {}, {}
		for _, r in ipairs(_giz3dAccRoots()) do
			for _, a in ipairs(r and r:GetChildren() or {}) do
				if a:IsA("Accessory") and not seen[a.Name] and a:FindFirstChild("Handle") then
					seen[a.Name] = true; table.insert(out, { key = "acc:" .. a.Name, label = a.Name })
				end
			end
		end
		table.sort(out, function(x, y) return x.label:lower() < y.label:lower() end)
		return out
	end





	System.markMyEdit = function(pd, key, go)
		if not (pd and type(key) == "string" and type(go) == "table") then return end
		pd.MyEdits = type(pd.MyEdits) == "table" and pd.MyEdits or {}
		pd.MyEdits[key] = go
	end
	System.applyMyEdits = function(pd)
		if not (pd and type(pd.MyEdits) == "table") then return end
		if System.keepMyEdits == false then pd.MyEdits = nil; return end
		pd.GizmoOffsets = type(pd.GizmoOffsets) == "table" and pd.GizmoOffsets or {}
		for k, go in pairs(pd.MyEdits) do pd.GizmoOffsets[k] = go end
		if pd.GizmoTarget and pd.MyEdits[pd.GizmoTarget] then pd.GizmoOffset = pd.MyEdits[pd.GizmoTarget] end
	end
	local function _accSolve(weld, handle, go, want)
		local PA = weld.C1
		local T = CFrame.new(go.PosX or 0, go.PosY or 0, go.PosZ or 0) * ((typeof(go.RotCF) == "CFrame" and go.RotCF) or CFrame.new())
		local A = weld.C0 * PA:Inverse() * T:Inverse() * PA
		local c0
		if weld.Part0 == handle then c0 = want:Inverse() * weld.Part1.CFrame * weld.C1 else c0 = weld.Part0.CFrame:Inverse() * want * weld.C1 end
		local Tn = PA * A:Inverse() * c0 * PA:Inverse()
		go.PosX, go.PosY, go.PosZ = Tn.Position.X, Tn.Position.Y, Tn.Position.Z
		go.RotCF = Tn.Rotation
		weld.C0 = c0
	end
	local function _giz3dShowAcc(key)
		local handle, weld = _giz3dAcc(key)
		if not handle then return false end
		local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
		local pd = PlayerData[sp]
		if not pd then return false end
		if not (pd.GizmoOffsets and pd.GizmoOffsets[key]) then System.setGizmoTarget(key) end
		local go = pd.GizmoOffsets and pd.GizmoOffsets[key]
		if not go then return false end
		local mode = System._giz3dMode
		local h
		if mode == "Rot" then
			h = Instance.new("ArcHandles"); h.Axes = Axes.new(Enum.Axis.X, Enum.Axis.Y, Enum.Axis.Z)
		else
			h = Instance.new("Handles"); h.Style = (mode == "Size") and Enum.HandlesStyle.Resize or Enum.HandlesStyle.Movement
			h.Faces = Faces.new(Enum.NormalId.Right, Enum.NormalId.Left, Enum.NormalId.Top, Enum.NormalId.Bottom, Enum.NormalId.Front, Enum.NormalId.Back)
		end
		h.Color3 = Color3.fromRGB(13, 105, 172); h.Adornee = handle; h.Parent = _giz3dContainer()
		System._giz3dConns = {}
		local H0, sc0, len0
		table.insert(System._giz3dConns, h.MouseButton1Down:Connect(function()
			local nh, nw = _giz3dAcc(key)
			if nh then handle, weld = nh, nw; h.Adornee = nh end
			H0 = handle.CFrame; sc0 = math.clamp(tonumber(go.Scale) or 1, 0.2, 5)
			System.markMyEdit(pd, key, go)
			System._editPush({ go = go })
			len0 = math.max(handle.Size.X, handle.Size.Y, handle.Size.Z, 0.1)
		end))
		local function step() return System._giz3dStep or 0.001 end
		if mode == "Rot" then
			table.insert(System._giz3dConns, h.MouseDrag:Connect(function(axis, ang)
				if H0 then pcall(_accSolve, weld, handle, go, H0 * CFrame.fromAxisAngle(Vector3.FromAxis(axis), math.rad(_snap(math.deg(ang or 0), step())))) end
			end))
		elseif mode == "Size" then
			table.insert(System._giz3dConns, h.MouseDrag:Connect(function(_, dist)
				if H0 then go.Scale = math.clamp(sc0 * (len0 + _snap(dist or 0, step())) / len0, 0.2, 5) end
			end))
		else
			table.insert(System._giz3dConns, h.MouseDrag:Connect(function(face, dist)
				if H0 then pcall(_accSolve, weld, handle, go, H0 + H0:VectorToWorldSpace(Vector3.FromNormalId(face) * _snap(dist or 0, step()))) end
			end))
		end
		table.insert(System._giz3dConns, h.MouseButton1Up:Connect(function() H0 = nil end))
		System._giz3dHandle = h
		return true
	end
	System.showGizmo3D = function()
		System.hideGizmo3D(true)
		local key = System.getGizmoTarget and System.getGizmoTarget()
		if not key then return false end
		if key:sub(1, 4) == "acc:" then return _giz3dShowAcc(key) end
		local joint, part = _giz3dResolveJoint(key)
		if not (joint and part) then return false end
		local char = part:FindFirstAncestorWhichIsA("Model") or _giz3dChar()


		local _prevFroze = System._giz3dFrozeChar
		if _prevFroze and _prevFroze ~= char then pcall(_giz3dSetAnims, _prevFroze, true) end
		_giz3dSetAnims(char, false)
		System._giz3dFrozeChar = char
		System._giz3dIsClone = false
		if System.NPCs then for _, m in pairs(System.NPCs) do if m == char then System._giz3dIsClone = true; break end end end
		if System._giz3dMode == "Reach" or System._giz3dMode == "Look" then


			local ok = System._ikShow(key, char)
			if ok or System._giz3dMode == "Look" then return ok end
		end
		_giz3dNormalize(joint)
		_jKinematic(joint)
		local col = Color3.fromRGB(13, 105, 172)
		System._giz3dConns = {}
		local function _anchor(on)
			local hrp = char and char:FindFirstChild("HumanoidRootPart")
			if not hrp then return end
			if on then
				System._giz3dHrp = hrp
				pcall(function() hrp.Anchored = true end)
			else
				pcall(function() hrp.Anchored = System._giz3dIsClone and true or false end)
				System._giz3dHrp = nil
			end
		end


		table.insert(System._giz3dConns, game:GetService("UserInputService").InputEnded:Connect(function(io)
			if (io.UserInputType == Enum.UserInputType.MouseButton1 or io.UserInputType == Enum.UserInputType.Touch) and System._giz3dHrp then _anchor(false); if System._symmetry then pcall(System.mirrorGizmo) end end
		end))
		if System._giz3dMode == "Rot" then
			local h = Instance.new("ArcHandles")
			h.Axes = Axes.new(Enum.Axis.X, Enum.Axis.Y, Enum.Axis.Z)
			h.Color3 = col; h.Adornee = part; h.Parent = _giz3dContainer()
			local startC0 = _jGetC0(joint)
			table.insert(System._giz3dConns, h.MouseButton1Down:Connect(function() _anchor(true); startC0 = _jGetC0(joint); System._editPush({ j = joint }) end))
			table.insert(System._giz3dConns, h.MouseDrag:Connect(function(axis, relAngle)
				pcall(function() _jSetC0(joint, startC0 * CFrame.fromAxisAngle(Vector3.FromAxis(axis), math.rad(_snap(math.deg(relAngle or 0), System._giz3dStep or 0.001)))) end)
			end))
			table.insert(System._giz3dConns, h.MouseButton1Up:Connect(function() _anchor(false); if System._symmetry then pcall(System.mirrorGizmo) end end))
			System._giz3dHandle = h
		else
			local h = Instance.new("Handles")
			h.Style = Enum.HandlesStyle.Movement
			h.Faces = Faces.new(Enum.NormalId.Right, Enum.NormalId.Left, Enum.NormalId.Top, Enum.NormalId.Bottom, Enum.NormalId.Front, Enum.NormalId.Back)
			h.Color3 = col; h.Adornee = part; h.Parent = _giz3dContainer()
			local startC0 = _jGetC0(joint)
			table.insert(System._giz3dConns, h.MouseButton1Down:Connect(function() _anchor(true); startC0 = _jGetC0(joint); System._editPush({ j = joint }) end))
			table.insert(System._giz3dConns, h.MouseDrag:Connect(function(face, distance)
				pcall(function() _jSetC0(joint, startC0 * CFrame.new(Vector3.FromNormalId(face) * _snap(distance or 0, System._giz3dStep or 0.001))) end)
			end))
			table.insert(System._giz3dConns, h.MouseButton1Up:Connect(function() _anchor(false); if System._symmetry then pcall(System.mirrorGizmo) end end))
			System._giz3dHandle = h
		end

		table.insert(System._giz3dConns, game:GetService("RunService").Heartbeat:Connect(function()
			local h = System._giz3dHandle; if not h then return end
			local ad = h.Adornee
			if (not ad) or (not ad.Parent) then
				local nj, np = _giz3dResolveJoint(key)
				if nj and np then joint = nj; part = np; h.Adornee = np end
			end
		end))
		return true
	end



	System._editUndo, System._editRedo = System._editUndo or {}, System._editRedo or {}
	System._editSnap = function(it)
		if it.lr then return { lr = true, rig = System.Lights.snapshot() } end
		if it.j then return { j = it.j, C0 = _jGetC0(it.j), C1 = _jGetC1(it.j) } end
		local c = {}; for k, v in pairs(it.go) do c[k] = v end
		return { go = it.go, f = c }
	end
	System._editPush = function(it)
		System._lastEditPress = os.clock()
		System._lastEditT = os.clock()
		local ok, s = pcall(System._editSnap, it); if not ok then return end
		table.insert(System._editUndo, s); if #System._editUndo > 50 then table.remove(System._editUndo, 1) end
		System._editRedo = {}
	end
	System._editStep = function(from, to)


		local s
		repeat
			s = table.remove(from); if not s then return false end
			local dead = false
			pcall(function() dead = s.j ~= nil and s.j.Parent == nil end)
		until not dead
		local ok, cur = pcall(System._editSnap, s); if ok then table.insert(to, cur) end
		pcall(function()
			if s.lr then System.Lights.restore(s.rig)
			elseif s.j then if s.j.Parent then _jSetC0(s.j, s.C0); _jSetC1(s.j, s.C1) end
			else for k in pairs(s.go) do s.go[k] = nil end; for k, v in pairs(s.f) do s.go[k] = v end end
		end)
		return true
	end
	System.undoEdit = function() return System._editStep(System._editUndo, System._editRedo) end
	System.redoEdit = function() return System._editStep(System._editRedo, System._editUndo) end
	System._editTarget = function()
		local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
		local pd = PlayerData[sp]
		local key = System.getGizmoTarget and System.getGizmoTarget()
		if not (pd and type(key) == "string") then return pd, nil, nil end
		if key:sub(1, 4) == "acc:" then return pd, key, nil end
		return pd, key, (_giz3dResolveJoint(key))
	end
	System.resetGizmoPart = function()
		local pd, key, j = System._editTarget(); if not key then return false end
		if not j then
			local go = pd.GizmoOffsets and pd.GizmoOffsets[key]; if not go then return false end
			System._editPush({ go = go })
			go.PosX, go.PosY, go.PosZ, go.RotX, go.RotY, go.RotZ, go.RotCF, go.Scale = 0, 0, 0, 0, 0, 0, CFrame.new(), 1
			if pd.MyEdits then pd.MyEdits[key] = nil end
			return true
		end
		local o = System._giz3dOrig[j]; if not o then return false end
		System._editPush({ j = j }); _jSetC0(j, o.C0); _jSetC1(j, o.C1)
		return true
	end



	System._jointDelta = function(j)
		local o = System._giz3dOrig[j] or { C0 = _jGetC0(j), C1 = _jGetC1(j) }
		return (o.C0 * o.C1:Inverse()):Inverse() * (_jGetC0(j) * _jGetC1(j):Inverse())
	end
	System._jointApplyDelta = function(j, d)
		_giz3dNormalize(j)
		local o = System._giz3dOrig[j]
		_jSetC0(j, (o.C0 * o.C1:Inverse()) * d * _jGetC1(j))
	end
	System._mirrorCF = function(cf)
		local x, y, z, r00, r01, r02, r10, r11, r12, r20, r21, r22 = cf:GetComponents()
		return CFrame.new(-x, y, z, r00, -r01, -r02, -r10, r11, r12, -r20, r21, r22)
	end
	System._otherSide = function(key)
		if type(key) ~= "string" then return nil end
		if key:find("Left") then return (key:gsub("Left", "Right", 1)) elseif key:find("Right") then return (key:gsub("Right", "Left", 1)) end
		return nil
	end
	System.mirrorGizmo = function()
		local _, key, j = System._editTarget(); if not (key and j) then return false end
		local okey = System._otherSide(key); if not okey then return false end
		local oj = _giz3dResolveJoint(okey); if not oj then return false end
		local ok, d = pcall(System._jointDelta, j); if not ok then return false end
		System._editPush({ j = oj })
		return (pcall(System._jointApplyDelta, oj, System._mirrorCF(d)))
	end
	System.setSymmetry = function(on) System._symmetry = on and true or false; return System._symmetry end
	System.copyGizmoPart = function()
		local pd, key, j = System._editTarget(); if not key then return false end
		if j then
			local ok, d = pcall(System._jointDelta, j); if not ok then return false end
			System._editClip = { kind = "joint", d = d, from = key }
		else
			local go = pd.GizmoOffsets and pd.GizmoOffsets[key]; if not go then return false end
			local c = {}; for k, v in pairs(go) do c[k] = v end
			System._editClip = { kind = "acc", f = c, from = key }
		end
		return true
	end
	System.pasteGizmoPart = function()
		local clip = System._editClip; if not clip then return false, "nothing copied" end
		local pd, key, j = System._editTarget(); if not key then return false, "no target" end
		if clip.kind == "joint" then
			if not j then return false, "copied a body part: pick a body part" end
			System._editPush({ j = j })
			return (pcall(System._jointApplyDelta, j, clip.d))
		end
		if j then return false, "copied an accessory: pick an accessory" end
		pd.GizmoOffsets = pd.GizmoOffsets or {}
		local go = pd.GizmoOffsets[key]
		if not go then System.setGizmoTarget(key); go = pd.GizmoOffsets[key] end
		if not go then return false, "no target" end
		System._editPush({ go = go })
		for k in pairs(go) do go[k] = nil end; for k, v in pairs(clip.f) do go[k] = v end
		System.markMyEdit(pd, key, go)
		return true
	end




	System._r6Key = function(key, names)
		local side = key:match("^Left") or key:match("^Right")
		local g = (side and (key:find("Arm") or key:find("Hand")) and side .. "UpperArm") or (side and (key:find("Leg") or key:find("Foot")) and side .. "UpperLeg")
			or ((key == "UpperTorso") and "LowerTorso") or nil
		return (g and names[g]) and g or key
	end
	System._editKeyAt = function(inst)
		if not inst then return nil end
		local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
		local char = Function.ResolveTargetChar and Function.ResolveTargetChar(sp)
		local m2 = System.M2FName and workspace:FindFirstChild(System.M2FName)
		local proxy = m2 and m2:FindFirstChild(sp)
		if not ((char and inst:IsDescendantOf(char)) or (proxy and inst:IsDescendantOf(proxy))) then return nil end
		local acc = inst:FindFirstAncestorOfClass("Accessory")
		if acc then return "acc:" .. acc.Name end
		local names = {}
		for _, t in ipairs(System.getGizmoTargets()) do names[t.key] = true end
		local p = inst
		while p and p ~= char and p ~= proxy do
			if p:IsA("BasePart") and names[p.Name] then return System._r6Key(p.Name, names) end
			p = p.Parent
		end
		return nil
	end
	System._editTapPick = function(pos)
		if os.clock() - (System._lastEditPress or 0) < 0.6 then return end
		local cam = workspace.CurrentCamera; if not cam then return end
		local ray = cam:ScreenPointToRay(pos.X, pos.Y)
		local hit = workspace:Raycast(ray.Origin, ray.Direction * 600, RaycastParams.new())
		local key = hit and System._editKeyAt(hit.Instance)
		if key and key ~= (System.getGizmoTarget and System.getGizmoTarget()) then
			System.setGizmoTarget(key)
			if System.showGizmo3D then pcall(System.showGizmo3D) end
			if System.renderEdit then pcall(System.renderEdit) end
		end
	end
	System._editTapDown = nil
	System.GlobalMaid:Give(UIS.InputBegan:Connect(function(inp, gp)
		if gp or System._photoExit or not (System._editTabOpen or System._editBarOpen or System._giz3dHandle) then return end
		if inp.UserInputType == Enum.UserInputType.MouseButton1 or inp.UserInputType == Enum.UserInputType.Touch then
			System._editTapDown = { t = os.clock(), p = Vector2.new(inp.Position.X, inp.Position.Y) }
		end
	end))
	System.GlobalMaid:Give(UIS.InputEnded:Connect(function(inp)
		local d = System._editTapDown; if not d then return end
		if inp.UserInputType ~= Enum.UserInputType.MouseButton1 and inp.UserInputType ~= Enum.UserInputType.Touch then return end
		System._editTapDown = nil
		local p = Vector2.new(inp.Position.X, inp.Position.Y)
		if System._ikGrabbing or (System._ikGrabEnd and os.clock() - System._ikGrabEnd < 0.25) then return end
		if os.clock() - d.t < 0.35 and (p - d.p).Magnitude < 12 then pcall(System._editTapPick, p) end
	end))





	System._ikShow = function(key, char)
		local hum = char and char:FindFirstChildOfClass("Humanoid")
		local hrp = char and char:FindFirstChild("HumanoidRootPart")
		if not (hum and hrp) then return false end
		local look = System._giz3dMode == "Look"
		local side = key:match("^Left") or key:match("^Right")
		local k = key:lower()
		local root, eff, names
		if look then
			eff = char:FindFirstChild("Head")


			root = char:FindFirstChild("UpperTorso") or eff
			names = char:FindFirstChild("UpperTorso") and { Head = true, UpperTorso = true } or { Head = true }
		elseif side and (k:find("arm") or k:find("hand")) then
			root, eff = char:FindFirstChild(side .. "UpperArm"), char:FindFirstChild(side .. "Hand")
			names = { [side .. "UpperArm"] = true, [side .. "LowerArm"] = true, [side .. "Hand"] = true }
		elseif side and (k:find("leg") or k:find("foot")) then
			root, eff = char:FindFirstChild(side .. "UpperLeg"), char:FindFirstChild(side .. "Foot")
			names = { [side .. "UpperLeg"] = true, [side .. "LowerLeg"] = true, [side .. "Foot"] = true }
		end
		if not (root and eff) then return false end
		local chain = {}
		for _, j in ipairs(char:GetDescendants()) do
			if _isPoseJoint(j) then local p = _jPart(j); if p and names[p.Name] then table.insert(chain, j) end end
		end
		if #chain == 0 then return false end
		local function ball(name, size, transp)
			local b = Instance.new("Part")
			b.Name = name; b.Shape = Enum.PartType.Ball; b.Size = Vector3.new(size, size, size)
			b.Anchored, b.CanCollide, b.CanQuery, b.CanTouch, b.CastShadow = true, false, false, false, false
			b.Material = Enum.Material.Neon; b.Color = Color3.fromRGB(255, 90, 150); b.Transparency = transp
			return b
		end
		local tgt = ball("RCIKTarget", look and 0.7 or 0.55, 1)


		tgt.CFrame = look and CFrame.new((eff.CFrame * CFrame.new(0, 0, -4)).Position) or CFrame.new(eff.Position + hrp.CFrame.LookVector * 0.9 + Vector3.new(0, 0.3, 0))
		local dot = Instance.new("SphereHandleAdornment")
		dot.Radius = (look and 0.7 or 0.55) / 2; dot.Color3 = Color3.fromRGB(255, 90, 150); dot.Transparency = 0.1
		dot.AlwaysOnTop = true; dot.ZIndex = 5; dot.Adornee = tgt; dot.Parent = tgt
		tgt.Parent = workspace
		local ik = Instance.new("IKControl")
		ik.Type = look and Enum.IKControlType.LookAt or Enum.IKControlType.Position
		ik.ChainRoot, ik.EndEffector, ik.Target, ik.Weight, ik.Enabled = root, eff, tgt, 1, false
		local parts = { tgt, ik }
		if not look then
			local mid = char:FindFirstChild(side .. ((k:find("leg") or k:find("foot")) and "LowerLeg" or "LowerArm"))
			local pole = ball("RCIKPole", 0.2, 1)
			local cf = hrp.CFrame
			if k:find("leg") or k:find("foot") then pole.Position = (mid and mid.Position or eff.Position) + cf.LookVector * 3
			else pole.Position = (mid and mid.Position or eff.Position) - cf.LookVector * 2 - cf.UpVector + cf.RightVector * (side == "Left" and -1 or 1) end
			pole.Parent = workspace
			ik.Pole = pole
			table.insert(parts, pole)
		end
		ik.Parent = hum
		System._ikParts = parts
		System._giz3dConns = {}
		local dragging = false
		System._ikBegin = function()
			if dragging then return end
			dragging = true
			for _, j in ipairs(chain) do
				pcall(_giz3dNormalize, j)
				System._editPush({ j = j })
			end
			if not System._giz3dIsClone then pcall(function() hrp.Anchored = true end) end
			ik.Enabled = true
		end
		System._ikEnd = function()
			if not dragging then return end
			dragging = false
			local baked = {}
			for _, j in ipairs(chain) do local ok, t = pcall(function() return j.Transform end); if ok and typeof(t) == "CFrame" then baked[j] = t end end
			ik.Enabled = false
			for j, t in pairs(baked) do pcall(function() _jSetC0(j, _jGetC0(j) * t) end) end
			pcall(function() hrp.Anchored = System._giz3dIsClone and true or false end)
		end



		local UIS = game:GetService("UserInputService")
		local cam = workspace.CurrentCamera
		local grab, plane, off, camType





		local midP = (not look) and char:FindFirstChild(side .. ((k:find("leg") or k:find("foot")) and "LowerLeg" or "LowerArm"))


		local function jPos(j) if j:IsA("Motor6D") then return (j.Part1.CFrame * j.C1).Position end local a = j.Attachment1; return a and a.WorldPosition end
		local jBy = {}
		for _, j in ipairs(chain) do local p = _jPart(j); if p then jBy[p] = j end end
		local rootJ, midJ, effJ = jBy[root], midP and jBy[midP], jBy[eff]
		local function pivot()
			if look then return eff.Position end
			return (rootJ and jPos(rootJ)) or root.Position
		end
		local maxR = 10
		if not look then
			local a, m, w = rootJ and jPos(rootJ), midJ and jPos(midJ), effJ and jPos(effJ)
			maxR = (a and m and w) and (((a - m).Magnitude + (m - w).Magnitude + (w - eff.Position).Magnitude) * 0.97)
				or ((root.Size.Y + (midP and midP.Size.Y or 0) + eff.Size.Y * 0.5) * 0.75)
		end
		local rel = hrp.CFrame:PointToObjectSpace(tgt.Position)
		local poleRel = ik.Pole and hrp.CFrame:PointToObjectSpace(ik.Pole.Position)
		local function setBall(pos)
			local c = pivot()
			local d = pos - c
			if d.Magnitude > maxR then pos = c + d.Unit * maxR end
			tgt.CFrame = CFrame.new(pos)
			rel = hrp.CFrame:PointToObjectSpace(pos)
		end
		setBall(tgt.Position)
		table.insert(System._giz3dConns, game:GetService("RunService").Heartbeat:Connect(function()
			if grab or ik.Enabled or not (tgt.Parent and hrp.Parent) then return end
			tgt.CFrame = CFrame.new(hrp.CFrame:PointToWorldSpace(rel))
			if poleRel and ik.Pole and ik.Pole.Parent then ik.Pole.Position = hrp.CFrame:PointToWorldSpace(poleRel) end
		end))
		local function onPlane(p)
			local r = cam:ScreenPointToRay(p.X, p.Y)
			local n = cam.CFrame.LookVector
			local den = r.Direction:Dot(n)
			if math.abs(den) < 1e-4 then return nil end
			return r.Origin + r.Direction * ((plane - r.Origin):Dot(n) / den)
		end
		local function release()
			if not grab then return end
			grab = nil
			if camType then pcall(function() cam.CameraType = camType end); camType = nil end
			System._ikGrabbing = false; System._ikGrabEnd = os.clock()
			if System._ikEnd then System._ikEnd() end
		end
		table.insert(System._giz3dConns, UIS.InputBegan:Connect(function(io, gp)
			if gp or grab or not tgt.Parent then return end
			if io.UserInputType ~= Enum.UserInputType.MouseButton1 and io.UserInputType ~= Enum.UserInputType.Touch then return end
			local sp, onScreen = cam:WorldToScreenPoint(tgt.Position)
			if not onScreen or (Vector2.new(sp.X, sp.Y) - Vector2.new(io.Position.X, io.Position.Y)).Magnitude > 44 then return end
			grab, plane = io, tgt.Position
			local hit = onPlane(io.Position); off = hit and (tgt.Position - hit) or Vector3.zero
			camType = cam.CameraType; pcall(function() cam.CameraType = Enum.CameraType.Scriptable end)
			System._ikGrabbing = true
			System._ikBegin()
		end))
		table.insert(System._giz3dConns, UIS.InputChanged:Connect(function(io)
			if not grab then return end
			local touch = grab.UserInputType == Enum.UserInputType.Touch
			if (touch and io ~= grab) or ((not touch) and io.UserInputType ~= Enum.UserInputType.MouseMovement) then return end
			local hit = onPlane(io.Position)
			if hit then setBall(hit + off) end
		end))
		table.insert(System._giz3dConns, UIS.InputEnded:Connect(function(io)
			if grab and (io == grab or io.UserInputType == Enum.UserInputType.MouseButton1) then release() end
		end))
		tgt.AncestryChanged:Connect(function() if not tgt.Parent then release() end end)
		local h = tgt
		System._giz3dHandle = h
		return true
	end
	System.lookAtCamera = function()
		local key = System.getGizmoTarget and System.getGizmoTarget()
		if not key then
			local list = System.getGizmoTargets(); for _, t in ipairs(list) do if t.key == "Head" then key = "Head" end end
			if not key then return false end
			System.setGizmoTarget(key)
		end

		if System._lookBusy then return false end
		System._lookBusy = true
		local prev = System._giz3dMode
		local okRun, res = pcall(function()
			System._giz3dMode = "Look"
			local ok = System.showGizmo3D()
			local cam = workspace.CurrentCamera
			if not (ok and cam and System._ikParts and System._ikBegin) then return false end
			System._ikParts[1].CFrame = CFrame.new(cam.CFrame.Position)
			System._ikBegin()
			task.wait(); task.wait(); task.wait()
			if System._ikEnd then System._ikEnd() end
			return true
		end)
		System._lookBusy = false
		System._giz3dMode = prev
		if okRun and res then pcall(System.showGizmo3D) end
		return okRun and res or false
	end
	System.setGizmoMode3D = function(mode)
		System._giz3dMode = (mode == "Rot" or mode == "Size" or mode == "Reach" or mode == "Look") and mode or "Pos"
		System.showGizmo3D()
		return System._giz3dMode
	end

	System.resetGizmoPose = function()

		local tgt = System._giz3dFrozeChar or _giz3dChar()
		local function mine(j) return typeof(j) == "Instance" and (tgt == nil or j:IsDescendantOf(tgt)) end
		for joint, o in pairs(System._giz3dOrig) do
			if typeof(joint) ~= "Instance" or not joint.Parent then
				System._giz3dOrig[joint] = nil
			elseif mine(joint) then
				pcall(function() _jSetC0(joint, o.C0); _jSetC1(joint, o.C1) end)
				System._giz3dOrig[joint] = nil
			end
		end
		local function keep(stack)
			local o = {}
			for _, e in ipairs(stack or {}) do if not (type(e) == "table" and e.j and mine(e.j)) then o[#o + 1] = e end end
			return o
		end
		System._editUndo, System._editRedo = keep(System._editUndo), keep(System._editRedo)
		do
			local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
			local pd = PlayerData[sp]
			if pd then pd.MyEdits = nil end
			for k, go in pairs(pd and pd.GizmoOffsets or {}) do
				if type(k) == "string" and k:sub(1, 4) == "acc:" and type(go) == "table" then
					go.PosX, go.PosY, go.PosZ, go.RotX, go.RotY, go.RotZ, go.RotCF, go.Scale = 0, 0, 0, 0, 0, 0, CFrame.new(), 1
				end
			end
		end
		do
			local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
			if System._clonePoseSnaps then System._clonePoseSnaps[sp] = nil end
		end
		_giz3dSetAnims(System._giz3dFrozeChar or _giz3dChar(), true)
		local hrp = System._giz3dFrozeChar and System._giz3dFrozeChar:FindFirstChild("HumanoidRootPart")
		if hrp and not System._giz3dIsClone then pcall(function() hrp.Anchored = false end) end
		System._giz3dFrozeChar = nil
	end




	System._clonePoseSnaps = System._clonePoseSnaps or {}
	local function _clonePoseKey(j)
		local p1 = j:IsA("Motor6D") and j.Part1 or (j.Attachment1 and j.Attachment1.Parent)
		return j.Name .. "|" .. (p1 and p1.Name or "?")
	end
	System._clonePoseCapture = function(key, rig)
		if not (key and typeof(rig) == "Instance") then return end
		local snap
		for joint, o in pairs(System._giz3dOrig) do
			if typeof(joint) == "Instance" and joint:IsDescendantOf(rig) then
				local ok, d = pcall(function() return (o.C0 * o.C1:Inverse()):Inverse() * (_jGetC0(joint) * _jGetC1(joint):Inverse()) end)
				if ok then snap = snap or {}; snap[_clonePoseKey(joint)] = d end
			end
		end

		if snap then
			local old = System._clonePoseSnaps[key] or {}
			for k, d in pairs(snap) do old[k] = d end
			System._clonePoseSnaps[key] = old
		end
	end
	System._clonePoseRestore = function(key)
		local t0 = os.clock()
		local function apply(late)

			if late and (System._lastEditT or 0) > t0 then return end
			local snap = System._clonePoseSnaps[key]
			local rig = (System.NPCs and System.NPCs[key]) or (key == Player.Name and Player.Character) or nil
			if not (snap and rig) then return end
			for _, j in ipairs(rig:GetDescendants()) do
				local d = (j:IsA("Motor6D") or j:IsA("AnimationConstraint")) and snap[_clonePoseKey(j)]
				if d then
					pcall(function()
						local o = System._giz3dOrig[j]
						if not o then o = { C0 = _jGetC0(j), C1 = _jGetC1(j) }; System._giz3dOrig[j] = o end
						local want = (o.C0 * o.C1:Inverse()) * d * _jGetC1(j)
						_jKinematic(j)
						if not _jGetC0(j):FuzzyEq(want, 1e-4) then _jSetC0(j, want) end
					end)
				end
			end

			if key == Player.Name and System._isPosed and System._isPosed(rig) then
				pcall(_giz3dSetAnims, rig, false); System._giz3dFrozeChar = rig
			end
		end

		apply(); task.delay(1, apply, true); task.delay(3, apply, true)
	end
