							pcall(Function._sbTune, part, pdx)
							pcall(function() cs:RemoveTag(part, System._sbTag) end)
							task.defer(function() if part.Parent then pcall(function() cs:AddTag(part, System._sbTag) end) end end)
							n += 1
						end
					end
					return n
				end
			end
			for _, p in ipairs(cloneRoot:GetDescendants()) do
				if p:IsA("BasePart") and p:FindFirstChildOfClass("Bone") then

					local _hasRoots = p:GetAttribute("Roots") ~= nil
					if not _hasRoots then
						local rootNames = {}
						for _, c in ipairs(p:GetChildren()) do
							if c:IsA("Bone") then
								table.insert(rootNames, c.Name)
							end
						end
						if #rootNames > 0 then
							p:SetAttribute("Roots", table.concat(rootNames, ","))
							_hasRoots = true
						end
					end
					if _hasRoots then


						if _sbEnabled then
							pcall(Function._sbTune, p, _pd)
							pcall(function() CS:AddTag(p, System._sbTag) end)
						else
							pcall(function() CS:RemoveTag(p, System._sbTag) end)
