	function Function._cockSizing(DataDetail, SCALE, NAME, Parent, SIZE, CFRAME, CFRAME1)
		if SCALE ~= "CockScale" or type(NAME) ~= "string" or typeof(SIZE) ~= "Vector3" then return nil end
		local L, G = DataDetail.CockLength or 1, DataDetail.CockGirth or 1
		local H, B = DataDetail.CockHead or 1, DataDetail.CockBalls or 1
		if L == 1 and G == 1 and H == 1 and B == 1 then return nil end
		local function axisOf(v) if v.X >= v.Y and v.X >= v.Z then return "X" elseif v.Y >= v.Z then return "Y" end return "Z" end
		local function mul(ax, l, g) return { X = ax == "X" and l or g, Y = ax == "Y" and l or g, Z = ax == "Z" and l or g } end
		local nm = NAME:lower()
		local isBalls = nm:find("ball") ~= nil
		local isHead = (nm:find("tip") or nm:find("head")) ~= nil
		local onShaft = Parent and Parent:GetAttribute("RCCockAxis")
		if onShaft and typeof(CFRAME) == "CFrame" then CFRAME = Function.CFrameMultiply(CFRAME, mul(onShaft, L, G)) end
		local own, axis
		if isBalls then own = { X = B, Y = B, Z = B }
		elseif isHead then local a = axisOf(SIZE); own = mul(a, H, H * G)
		else axis = axisOf(SIZE); own = mul(axis, L, G) end
		SIZE = Function.Vector3Multiply(SIZE, own)
		if typeof(CFRAME1) == "CFrame" then CFRAME1 = Function.CFrameMultiply(CFRAME1, own) end
		return { size = SIZE, c0 = CFRAME, c1 = CFRAME1, axis = axis }
	end

