					LoadedAvatar:Destroy()
					AccessoryLoaderModel:Destroy()
					HumanoidDescription:Destroy()
					return
				end

				if not _refreshDD() then
					LoadedAvatar:Destroy()
					AccessoryLoaderModel:Destroy()
					HumanoidDescription:Destroy()
					return
				end

				if not PlayerData[Data] then
					LoadedAvatar:Destroy()
					AccessoryLoaderModel:Destroy()
					HumanoidDescription:Destroy()
					return
				end

				local charHead = Character:FindFirstChild("Head")
				local OldFC = charHead:FindFirstChildOfClass("Decal")
				local OldSM = charHead:FindFirstChildOfClass("SpecialMesh")


				local _dynPre
				do
					local _sm = head:FindFirstChildOfClass("SpecialMesh")
					if _sm and _sm.MeshType == Enum.MeshType.FileMesh and (charHead:IsA("MeshPart") or _Method ~= 2 or oChar) then
						_dynPre = Function.RCDynamicHeadFor(HumanoidDescription, _sm)
						if Function.IsStaleOrGone(Data, RequestID) or not _refreshDD() or not PlayerData[Data] or not charHead.Parent then
