					newHead.Name = "RCFake"..v.Name
					newHead.CanCollide = false
					newHead.CanQuery = false
					newHead.CanTouch = false
					newHead.Massless = true
					newHead.CustomPhysicalProperties = System.Physics.DefaultProperties
					newHead.Color = v.Color
					newHead.Material = v.Material
					newHead.Reflectance = v.Reflectance
					DataDetail.CurrentPartList.Organ["Head"] = newHead
					DataDetail.CurrentPartList.Link[newHead] = {T=v, Color=v}

					newHead.CFrame = v.CFrame
					local Weld = Instance.new("Weld", newHead)
					Weld.Part0 = v
					Weld.Part1 = newHead

					if DataDetail.Face == true then
						if head:FindFirstChildOfClass("Decal") then
							if OldFC then
								OldFC:Destroy()
							end
							local newDC=head:FindFirstChildOfClass("Decal"):Clone()
							newDC.Parent = newHead
							DataDetail.CurrentPartList.Link[newDC] = {T=newHead}
						elseif OldFC then
							OldFC.Parent = newHead
						end
					elseif OldFC then
						OldFC:Destroy()
					end
					if head:FindFirstChildOfClass("SpecialMesh") then
						DataDetail.CurrentPartList.ParentTransparency[v] = {v = v.Transparency, T = 1}

						if DataDetail.CurrentPartList.Link[newHead] then DataDetail.CurrentPartList.Link[newHead].NoTrans = true end

						local _dynHead = _dynPre
						_dynPre = nil
						if _dynHead then
							_dynHead.Anchored = false; _dynHead.CanCollide = false; _dynHead.CanQuery = false; _dynHead.CanTouch = false; _dynHead.Massless = true
							_dynHead.CFrame = v.CFrame
							pcall(function() _dynHead:AddTag(System.RCTag) end)
							_dynHead.Parent.Parent = newHead
							local _dw = Instance.new("Weld"); _dw.Part0 = v; _dw.Part1 = _dynHead; _dw.Parent = _dynHead
							newHead.Transparency = 1
							for _, _dc in ipairs(newHead:GetChildren()) do if _dc:IsA("Decal") then _dc.Transparency = 1 end end
						else
						local mesh = head:FindFirstChildOfClass("SpecialMesh"):Clone()
						mesh.Parent = newHead
						if mesh.MeshType == Enum.MeshType.Head then
							mesh.Scale = Vector3.new(1,1,1)
						end
						DataDetail.CurrentPartList.RealtimeUpdateList.SpecialMesh[mesh] = {
							Base=v,
							Size=mesh.Scale,
							CFrame = CFrame.new(0,0,0),
							CFrame1 = CFrame.new(0,0,0),
							Weld = Weld,
						}
						end
					else
						local mesh = Instance.new("SpecialMesh",newHead)
						mesh.MeshId = v.MeshId
					end
				elseif _Method ~= 2 and head:FindFirstChildOfClass("SpecialMesh") and head:FindFirstChildOfClass("SpecialMesh").MeshType == Enum.MeshType.FileMesh then

					local v = charHead
					local _dynHead = _dynPre
					_dynPre = nil
					if _dynHead then
						_dynHead.Anchored = false; _dynHead.CanCollide = false; _dynHead.CanQuery = false; _dynHead.CanTouch = false; _dynHead.Massless = true
						_dynHead.CFrame = v.CFrame
						pcall(function() _dynHead:AddTag(System.RCTag) end)
						DataDetail.ExecutionMaid:Give(_dynHead.Parent)
						_dynHead.Parent.Parent = v
						local _dw = Instance.new("Weld"); _dw.Part0 = v; _dw.Part1 = _dynHead; _dw.Parent = _dynHead
						DataDetail.CurrentPartList.ParentTransparency[v] = {v = v.Transparency, T = 1}
						if OldFC then DataDetail.CurrentPartList.ParentTransparency[OldFC] = {D = OldFC.Transparency, T = 1} end
					end
				elseif _Method == 2 and oChar then
					local h = Character:FindFirstChild("Head")



					local function newhed(id,texture)


						local newHead = Function.CachedCreateMeshPartAsync(id,
							Enum.CollisionFidelity.Box, Enum.RenderFidelity.Performance)
						if not newHead then

							Function._cmpaFallbackChars = Function._cmpaFallbackChars or {}
							Function._cmpaFallbackChars[Data] = true
							newHead = Function.CachedCreateMeshPartAsync("rbxasset://fonts//head.mesh",
								Enum.CollisionFidelity.Box, Enum.RenderFidelity.Automatic)
						end

						if Function.IsStaleOrGone(Data, RequestID) then
							if newHead then pcall(function() newHead:Destroy() end) end
							return nil
						end

						if not _refreshDD() then
							if newHead then pcall(function() newHead:Destroy() end) end
							return nil
						end

						if not newHead then return nil end
						newHead.Parent = h


						local appearance = Instance.new("SurfaceAppearance")
						if pcall(function() appearance.ColorMap = texture end) then
							appearance.Parent = newHead
							newHead:AddTag("ImportantSurfaceAppearance")
						else
							appearance:Destroy()
							pcall(function() newHead.TextureID = texture end)
						end
						newHead:AddTag(System.RCTag)

						newHead.Name = h.Name
						newHead.CanCollide = false
						newHead.CanQuery = false
						newHead.CanTouch = false
						newHead.Massless = true
						newHead.CustomPhysicalProperties = System.Physics.DefaultProperties
						newHead.Color = h.Color
						newHead.Material = h.Material
						newHead.Reflectance = h.Reflectance
						DataDetail.CurrentPartList.Organ["Head"] = newHead

						newHead.CFrame = h.CFrame
						local Weld = Instance.new("Weld", newHead)
						Weld.Part0 = h
						Weld.Part1 = newHead
						DataDetail.CurrentPartList.RealtimeUpdateList.Mesh[newHead] = {Base = h,Size=newHead.Size,CFrame=CFrame.new(0,0,0),CFrame1=CFrame.new(0,0,0),Weld=Weld}
						return newHead
					end

					DataDetail.CurrentPartList.ParentTransparency[h] = {D = 1}
					local _oHead76 = oChar:FindFirstChild("Head")
					if _oHead76 then
					    DataDetail.CurrentPartList.ParentTransparency[_oHead76] = {D = _oHead76.Transparency, T = 1}
					end

					local oHead = oChar:FindFirstChild("Head")
					local OldFC = oHead and oHead:FindFirstChildOfClass("Decal")
					local OldSM = oHead and oHead:FindFirstChildOfClass("SpecialMesh")





					local headMesh = head:FindFirstChildOfClass("SpecialMesh")



					local _dynHead = _dynPre
					_dynPre = nil
					if _dynHead then
						_dynHead.Anchored = false; _dynHead.CanCollide = false; _dynHead.CanQuery = false; _dynHead.CanTouch = false; _dynHead.Massless = true
						_dynHead.CFrame = h.CFrame
						pcall(function() _dynHead:AddTag(System.RCTag) end)
						DataDetail.ExecutionMaid:Give(_dynHead.Parent)
						_dynHead.Parent.Parent = h
						local _dw = Instance.new("Weld"); _dw.Part0 = h; _dw.Part1 = _dynHead; _dw.Parent = _dynHead
						DataDetail.CurrentPartList.Organ["Head"] = _dynHead


						if OldFC then DataDetail.CurrentPartList.ParentTransparency[OldFC] = {D = OldFC.Transparency, T = 1} end
						h = nil
					elseif headMesh then
						h = newhed(headMesh.MeshId, headMesh.TextureId)
					elseif OldSM then
						h = newhed(OldSM.MeshId,OldSM.TextureId)
					end
					if DataDetail.Face == true then

						if h and head:FindFirstChildOfClass("Decal") then
							if OldFC then
								OldFC.Transparency = 1
								DataDetail.CurrentPartList.ParentTransparency[OldFC] = {D = 0,T=1}
							end
							local d = head:FindFirstChildOfClass("Decal"):Clone()
							DataDetail.CurrentPartList.Link[d] = {T=h}
							d.Parent = h
						elseif h and OldFC then
							if OldFC then
								OldFC.Transparency = 1
								DataDetail.CurrentPartList.ParentTransparency[OldFC] = {D = 0,T=1}
							end
							local o = OldFC:Clone()
							DataDetail.CurrentPartList.ParentTransparency[o] = {D = 1}
							DataDetail.CurrentPartList.Link[o] = {T=h}
							o.Parent = h
						end
					elseif OldFC then
						OldFC.Transparency = 1
						DataDetail.CurrentPartList.ParentTransparency[OldFC] = {D = 0,T=1}
					end
				else
					if head:FindFirstChildOfClass("Decal") and DataDetail.Face == true then

						if OldFC and not DataDetail.OldestClothings.HeadDecal then
							DataDetail.OldestClothings.HeadDecal = OldFC:Clone()
						end
						if OldFC then
							OldFC:Destroy()
						end
						head:FindFirstChildOfClass("Decal"):Clone().Parent = Character:FindFirstChild("Head")
					elseif OldFC then

						if not DataDetail.OldestClothings.HeadDecal then
							DataDetail.OldestClothings.HeadDecal = OldFC:Clone()
						end

						if DataDetail.Face == false then
							OldFC:Destroy()
						end
					end
					if head:FindFirstChildOfClass("SpecialMesh") then

						if OldSM and not DataDetail.OldestClothings.HeadSpecialMesh then
							DataDetail.OldestClothings.HeadSpecialMesh = OldSM:Clone()
						end
						if OldSM then
							OldSM:Destroy()
						end
						head:FindFirstChildOfClass("SpecialMesh"):Clone().Parent = Character:FindFirstChild("Head")
					end
				end

				LoadedAvatar:Destroy()
			end
		end

		AccessoryLoaderModel:Destroy()
		HumanoidDescription:Destroy()
	end

_RCR.need("engine/accessory_catalog_loader", { Bundle = Bundle, Function = Function, PlayerData = PlayerData, System = System })
_RCR.need("engine/catalog_fetch", { Function = Function, System = System, _CATALOG_HOST = _CATALOG_HOST, _ECONOMY_HOST = _ECONOMY_HOST, _atomicWriteJSON = _atomicWriteJSON })












	function Function.ClothesOff(pd)
		local r = pd.ClothesOff
		if type(r) ~= "table" then r = {}; pd.ClothesOff = r end
		return r
	end
	function Function.IsNaked(pd)
		local r = pd and pd.ClothesOff
		return type(r) == "table" and r.naked == true
	end


	function Function.NakedBodyItem(name)
		if name == System.COCK_TWITCH then return true end
		if type(System.PUSSY_TYPES) == "table" and table.find(System.PUSSY_TYPES, name) ~= nil then return true end
		return type(System.COCK_TYPES) == "table" and table.find(System.COCK_TYPES, name) ~= nil
	end

	function Function.NakedBodyItems(pd)
		local o = {}
		for _, n in ipairs(pd and pd.CurrentClothes or {}) do if Function.NakedBodyItem(n) then table.insert(o, n) end end
		return o
	end
	function Function.NakedPutBodyItems(pd, body, hp, rc)
		pd.CurrentClothes = pd.CurrentClothes or {}
		pd.ClothesHP = pd.ClothesHP or {}
		pd.ClothesRecolor = pd.ClothesRecolor or {}
		for _, n in ipairs(body) do
			if not table.find(pd.CurrentClothes, n) then table.insert(pd.CurrentClothes, n) end
			if hp and hp[n] ~= nil then pd.ClothesHP[n] = hp[n] end
			if rc and rc[n] ~= nil then pd.ClothesRecolor[n] = rc[n] end
		end
		pd._equippedSetSrc = nil
	end

	Function.NAKED_STRIP_CATS = { Neck = true, Shoulder = true, Front = true, Back = true, Waist = true }
	function Function.NakedStripCats(cats)
		local o = { Hat = false, Hair = false, Face = false }
		if type(cats) == "table" then for k, v in pairs(cats) do o[k] = v end end
		for k in pairs(Function.NAKED_STRIP_CATS) do o[k] = true end
		return o
	end

	Function.NAKED_LAYERED = { TShirt = true, Shirt = true, Pants = true, Jacket = true, Sweater = true, Shorts = true,
		DressSkirt = true, LeftShoe = true, RightShoe = true }
	function Function.NakedLayered(pd, acc)
		if not (Function.IsNaked(pd) and typeof(acc) == "Instance") then return false end
		local at
		pcall(function() at = acc.AccessoryType.Name end)
		return at ~= nil and Function.NAKED_LAYERED[at] == true
	end



	function Function.NakedCloth2D(pd, model)
		if not (pd and typeof(model) == "Instance") then return end
		local st = pd._naked2D
		if type(st) ~= "table" then st = {}; pd._naked2D = st end
		for m, list in pairs(st) do
			if m ~= model and m.Parent == nil then
				for _, c in ipairs(list) do pcall(function() c:Destroy() end) end
				st[m] = nil
			end
		end
		if Function.IsNaked(pd) then
			local list = st[model] or {}
			for _, c in ipairs(model:GetChildren()) do
				if c:IsA("Shirt") or c:IsA("Pants") or c:IsA("ShirtGraphic") then
					table.insert(list, c)
					pcall(function() c.Parent = nil end)
				end
			end
			st[model] = list
		elseif st[model] then
			for _, c in ipairs(st[model]) do
				if model.Parent and not model:FindFirstChildOfClass(c.ClassName) then
					pcall(function() c.Parent = model end)
				else
					pcall(function() c:Destroy() end)
				end
			end
			st[model] = nil
		end
		if next(st) == nil then pd._naked2D = nil end
	end
	Function.NAKED_REFUSED = "Turn off Naked Mode to add clothing."
	function Function.NakedRefuse(pd, name)
		if not Function.IsNaked(pd) or (name and Function.NakedBodyItem(name)) then return false end
		if System.uiToast then pcall(System.uiToast, "Naked Mode is on", Function.NAKED_REFUSED, "warn") end
		return true
	end

	function Function.ClothesOffClearRip(pd)
		local r = Function.ClothesOff(pd)
		r.top = nil
		r.bottom = nil
	end
	function Function._nakedCopy(t)
		if type(t) ~= "table" then return t end
		local o = {}
		for k, v in pairs(t) do o[k] = (type(v) == "table") and Function._nakedCopy(v) or v end
		return o
	end



	function Function.NakedRestoreStrip(pd)
		if not pd then return end
		local r = Function.ClothesOff(pd)
		local s = r.saved
		r.saved = nil
		if type(s) ~= "table" then return end
		if type(s.StripCategories) == "table" then pd.StripCategories = s.StripCategories end
		local cc = pd.CatalogClothes


		local body = Function.NakedBodyItems(pd)
		local untouched = pd.CurrentBundle == s.CurrentBundle and pd.CurrentPreset == nil
			and #(pd.CurrentClothes or {}) == #body and #(pd.CurrentClothingBundles or {}) == 0
			and not (type(cc) == "table" and ((cc.Shirt or "") ~= "" or (cc.Pants or "") ~= "" or (cc.ShirtGraphic or "") ~= ""))
		if not untouched then return end
		local hp, rc = pd.ClothesHP or {}, pd.ClothesRecolor or {}
		pd.CurrentClothes = {}
		for _, n in ipairs(s.CurrentClothes or {}) do
			if #body == 0 or not Function.NakedBodyItem(n) then table.insert(pd.CurrentClothes, n) end
		end
		pd.CurrentPreset = s.CurrentPreset
		pd.CurrentClothingBundles = s.CurrentClothingBundles or {}
		pd.ClothesHP = s.ClothesHP or {}
		pd.ClothesRecolor = s.ClothesRecolor or {}
		Function.NakedPutBodyItems(pd, body, hp, rc)
		if type(s.CatalogClothes) == "table" then
			if type(cc) == "table" then s.CatalogClothes.Face = cc.Face end
			pd.CatalogClothes = s.CatalogClothes
		end
		pd._equippedSetSrc = nil
		return true
	end

	function Function.SetNaked(sp, on)
		local pd = PlayerData[sp]
		if not pd then return end
		if on then
			pcall(Function.StripAllClothes, sp)
		else
			Function.ClothesOff(pd).naked = nil
			local okR, restored = pcall(Function.NakedRestoreStrip, pd)

			local worn = (pd.CurrentBundle ~= nil and pd.CurrentBundle ~= "nil") or pd.CurrentPreset ~= nil
			if not (okR and restored) and worn and System._replayBundleLayers then
				local body, hp, rc = Function.NakedBodyItems(pd), pd.ClothesHP, pd.ClothesRecolor
				pcall(System._replayBundleLayers, sp, pd, nil)
				Function.NakedPutBodyItems(pd, body, hp, rc)
			else
				pcall(Function.CharacterReset, sp)
			end

			local ms = {}
			for m in pairs(pd._naked2D or {}) do table.insert(ms, m) end
			for _, m in ipairs(ms) do pcall(Function.NakedCloth2D, pd, m) end
		end
		if System.hotSwap then pcall(System.hotSwap) end
		if System.onNakedChanged and sp == ((System.getSelectPlayer and System.getSelectPlayer()) or Player.Name) then pcall(System.onNakedChanged, Function.IsNaked(pd)) end
	end
	function Function.StripAllClothes(sp)
		local pd = PlayerData[sp]
		if not pd then return end
		local rec = Function.ClothesOff(pd)


		if not rec.naked then
			local cp = Function._nakedCopy
			rec.saved = {
				CurrentBundle = pd.CurrentBundle, CurrentPreset = pd.CurrentPreset,
				CurrentClothes = cp(pd.CurrentClothes or {}), CurrentClothingBundles = cp(pd.CurrentClothingBundles or {}),
				ClothesHP = cp(pd.ClothesHP or {}), ClothesRecolor = cp(pd.ClothesRecolor or {}),
				CatalogClothes = cp(pd.CatalogClothes), StripCategories = cp(pd.StripCategories or {}),
			}
		end
		pd.LastRequestID = (pd.LastRequestID or 0) + 1


		pd.CurrentClothes = {}
		pd.CurrentPreset = nil
		pd.CurrentClothingBundles = {}
		pd.ClothesHP = {}
		pd.ClothesRecolor = {}

		pd._equippedSetSrc = nil



		pd.CatalogClothes = {Shirt = "", Pants = "", ShirtGraphic = "", Face = pd.CatalogClothes and pd.CatalogClothes.Face or ""}




		pd.StripCategories = Function.NakedStripCats(nil)

		rec.naked = true


		pcall(function()
			local _ply = PS:FindFirstChild(sp)
			local _char = (_ply and _ply.Character) or (System.NPCs and System.NPCs[sp])
			if _char then Function.NakedCloth2D(pd, _char) end
			local _real = pd.RealCharacter
			if _real and _real ~= _char then Function.NakedCloth2D(pd, _real) end
		end)


		pcall(Function.CharacterReset, sp)
	end







	local SWAP_PARK = 0.999


	function Function._resetApplyDesc(realHum, DataList)
		local ok, err, done = false, nil, false
		local rid = DataList.LastRequestID
		DataList._resetApplying = true
		task.spawn(function()
			ok, err = pcall(function()
				local d = DataList.OriginalHumanoidDescription:Clone()
				realHum:ApplyDescription(d)
				d:Destroy()
			end)
			done = true
		end)
		local t0 = os.clock()
		while not done and os.clock() - t0 < 8 and DataList.LastRequestID == rid do task.wait(0.05) end
		DataList._resetApplying = nil
		DataList._resetAppliedAt = os.clock()
		if DataList.LastRequestID ~= rid then return "superseded" end
		if not done then return false, "timed out after 8 s" end
		return ok, err
	end
	function Function._swapStash(DataList)
		local st = DataList._swapStash
		if not st then
			st = { parts = {}, unhide = {}, at = os.clock() }
			DataList._swapStash = st
			local resetAt = os.clock()


			local function _flushIfIdle()
				if DataList._swapStash ~= st or (DataList._swapBuildAt or 0) >= resetAt then return end
				if DataList._resetApplying or os.clock() - (DataList._resetAppliedAt or -1) < 0.25 then task.delay(0.1, _flushIfIdle); return end
				Function._swapFlush(DataList)
			end
			task.delay(0.25, _flushIfIdle)
			task.delay(25, function() if DataList._swapStash == st then Function._swapFlush(DataList) end end)


			task.spawn(function()
				while DataList._swapStash == st do
					for i = #st.parts, 1, -1 do
						local v = st.parts[i]
						local loose = true
						pcall(function()
							if not v.Parent then loose = false; return end
							if not v:IsA("BasePart") then loose = false; return end
							for _, j in ipairs(v:GetJoints()) do
								local a, b = j.Part0 or (j:IsA("Constraint") and j.Attachment0 and j.Attachment0.Parent), j.Part1 or (j:IsA("Constraint") and j.Attachment1 and j.Attachment1.Parent)
								local other = (a == v) and b or a
								if other and other.Parent and other:IsDescendantOf(workspace) then loose = false; return end
							end
							if v.Anchored then loose = false end
						end)
						if loose then pcall(function() v:Destroy() end); table.remove(st.parts, i) end
					end
					task.wait(0.1)
				end
			end)
		end
		return st
	end
	function Function._swapFlush(DataList)
		local st = DataList and DataList._swapStash
		if not st then return end
		DataList._swapStash = nil
		for _, v in ipairs(st.parts) do pcall(function() v:Destroy() end) end




		local pl = DataList.CurrentPartList or {}
		local om, ptm = pl.OriginalTransparency or {}, pl.ParentTransparency or {}
		local function parked(x) return type(x) == "number" and math.abs(x - SWAP_PARK) < 1e-3 end
		for _, u in ipairs(st.unhide) do
			pcall(function()
				local o = u[1]
				if parked(om[o]) then om[o] = u[2] end
				if type(ptm[o]) == "table" and parked(ptm[o].D) then ptm[o].D = u[2] end
				if o.Parent and parked(o.Transparency) then
					o.Transparency = u[2]
					if om[o] == nil and ptm[o] == nil then o.LocalTransparencyModifier = u[3] end
				end
			end)
		end
	end




	function Function._dedupeOrphans(DataList)
		local pl = DataList and DataList.CurrentPartList
		if not pl then return 0 end
		local tracked = {}
		for _, key in ipairs({ "Organ", "Clothes", "Accessory" }) do
			for _, v in pairs(pl[key] or {}) do if typeof(v) == "Instance" then tracked[v] = true end end
		end
		local n = 0
		for v in pairs(tracked) do
			local par = v.Parent
			if par and v:IsA("BasePart") then
				for _, sib in ipairs(par:GetChildren()) do
					if sib ~= v and sib.Name == v.Name and sib:IsA("BasePart") and not tracked[sib] then
						pcall(function() sib:Destroy() end); n += 1
					end
				end
			end
		end
		return n
	end

	local function swapShow(st, obj, value, ltm)
		if st and value < 0.99 and obj.Transparency >= 0.99 then
			obj.Transparency = SWAP_PARK
			obj.LocalTransparencyModifier = ltm
			st.unhide[#st.unhide + 1] = { obj, value, ltm }
		else
			obj.Transparency = value
			obj.LocalTransparencyModifier = ltm
		end
	end

	function Function.CharacterReset(PlayerName,NPCClear)

		do
			local _name = (typeof(PlayerName) == "Instance") and PlayerName.Name or PlayerName
			local _pd = _name and PlayerData[_name]
			if _pd then

				_pd._lastH, _pd._lastMaxH = nil, nil
				_pd._lastTop, _pd._lastBot = nil, nil
				_pd._lastSTop, _pd._lastSBot = nil, nil
				_pd._lastHC = nil
			end
		end

		local ExecutePlayer
		if typeof(PlayerName) ~= "Instance" then


			if System.NPCs and System.NPCs[PlayerName] then
				PlayerName = System.NPCs[PlayerName]
			else
				ExecutePlayer = PS:FindFirstChild(PlayerName)
			end
		end

		local DataList = nil
		local PartListPlayer = nil

		if not PlayerName then
			if GUIObject.PlayerExecute.Text == "Self" then
				ExecutePlayer = Player
				DataList = PlayerData[ExecutePlayer.Name]
				if not DataList then return end
				PartListPlayer = DataList.CurrentPartList
			end
		elseif ExecutePlayer then
			if PlayerData[ExecutePlayer.Name] == nil then
				return
			end
			DataList = PlayerData[ExecutePlayer.Name]
			PartListPlayer = DataList.CurrentPartList
		end
		if type(PlayerName) ~= "string" and Function.IsCharacter(PlayerName) then
			local npcIdx = Function.TableFind(System.NPCs, PlayerName)
			if npcIdx == nil or not PlayerData[npcIdx] then
				return
			else
				DataList = PlayerData[npcIdx]
				PartListPlayer = DataList.CurrentPartList
				if NPCClear == true then

					if DataList and DataList.ExecutionMaid then
						pcall(function() DataList.ExecutionMaid:DoCleaning() end)
					end
					PlayerData[npcIdx] = nil

					if System.NPCs then System.NPCs[npcIdx] = nil end
				end
			end
		end

		if PartListPlayer then

			if NPCClear == true then Function._swapFlush(DataList) end


			local foreign = ExecutePlayer ~= nil and ExecutePlayer ~= Player
			local swap = (NPCClear ~= true and not foreign) and Function._swapStash(DataList) or nil
			local function drop(v)
				if swap and typeof(v) == "Instance" and v.Parent then
					pcall(function() v.Name = v.Name .. "_rcold" end)
					if DataList.ExecutionMaid then pcall(function() DataList.ExecutionMaid:Release(v) end) end
					swap.parts[#swap.parts + 1] = v
				else
					pcall(function() v:Destroy() end)
				end
			end
			local SpecialList = PartListPlayer.RealtimeUpdateList and PartListPlayer.RealtimeUpdateList["Special"]
			local OrganList = PartListPlayer["Organ"]
			local ClothesList = PartListPlayer["Clothes"]
			local AccessoryList = PartListPlayer["Accessory"]
			local ParentTransparencyList = PartListPlayer["ParentTransparency"]

			if SpecialList then
				for _, v in pairs(SpecialList) do
					drop(v)
				end
			end

			if OrganList then
				for _, v in pairs(OrganList) do
					drop(v)
				end
			end

			if ClothesList then
				for _, v in pairs(ClothesList) do
					drop(v)
				end
			end

			if AccessoryList then
				for _, v in pairs(AccessoryList) do
					drop(v)
				end
			end

			if ParentTransparencyList then
				for Object, Property in pairs(ParentTransparencyList) do
					pcall(function()
						local D = Property.D
						if D ~= nil then
							swapShow(swap, Object, D, D)
						end
					end)
				end
			end

			if PartListPlayer.OriginalTransparency then
				for i, v in pairs(PartListPlayer.OriginalTransparency) do
					pcall(function()

						swapShow(swap, i, v, 0)
					end)
				end
			end

			local char = DataList.Character

			if not char or not char.Parent then
				char = nil
				if type(PlayerName) ~= "string" and Function.IsCharacter(PlayerName) then
					char = PlayerName
				elseif PS:FindFirstChild(PlayerName) then
					char = PS:FindFirstChild(PlayerName).Character
				end
			end



			local realChar = DataList.RealCharacter
			if not realChar or not realChar.Parent then
				realChar = char
			end
			local bodyParts = {
				"Torso", "Left Arm", "Right Arm", "Left Leg", "Right Leg",
				"UpperTorso", "LowerTorso", "LeftUpperArm", "LeftLowerArm", "LeftHand",
				"RightUpperArm", "RightLowerArm", "RightHand", "LeftUpperLeg", "LeftLowerLeg",
				"LeftFoot", "RightUpperLeg", "RightLowerLeg", "RightFoot"
			}
			if realChar then
				for _, partName in ipairs(bodyParts) do
					local p = realChar:FindFirstChild(partName)
					if p and p:IsA("BasePart") then
						swapShow(swap, p, 0, 0)
					end
				end
			end
			if char and char ~= realChar then
				for _, partName in ipairs(bodyParts) do
					local p = char:FindFirstChild(partName)
					if p and p:IsA("BasePart") then
						swapShow(swap, p, 0, 0)
					end
				end
			end




			for _, c in ipairs({ realChar, char }) do
				local h = c and c:FindFirstChild("Head")
				if h and h:IsA("BasePart") then
					pcall(function()
						h.LocalTransparencyModifier = 0
						for _, d in ipairs(h:GetChildren()) do if d:IsA("Decal") then d.LocalTransparencyModifier = 0 end end
					end)
				end
			end


			local restoreTarget = DataList.RealCharacter or char
			if DataList.OriginalBodyColors and restoreTarget then
				local BodyColors = restoreTarget:FindFirstChildOfClass("BodyColors")
				if not BodyColors and DataList.IsClone then


					BodyColors = Instance.new("BodyColors")
					BodyColors.Parent = restoreTarget
				end
				if BodyColors then
					for prop, color in pairs(DataList.OriginalBodyColors) do
						BodyColors[prop] = color
					end
					Function.BodyColorSet(restoreTarget, BodyColors)
				end

				if char and char ~= restoreTarget then
					local proxyBC = char:FindFirstChildOfClass("BodyColors")
					if proxyBC then
						for prop, color in pairs(DataList.OriginalBodyColors) do
							proxyBC[prop] = color
						end
						Function.BodyColorSet(char, proxyBC)
					end
				end


				if not DataList.IsClone then
					DataList.OriginalBodyColors = nil
				end
			end
			DataList.RealCharacter = nil

			if DataList.NippleColorFromBundle then
				DataList.NippleColor = nil
				DataList.NippleColorFromBundle = false
			end


			if DataList.OriginalAttachmentCFrames then
				for attachment, cframe in pairs(DataList.OriginalAttachmentCFrames) do
					if attachment and attachment.Parent ~= nil then
						attachment.CFrame = cframe
					end
				end
				DataList.OriginalAttachmentCFrames = {}
			end


			if DataList.ConvertedPart then
				for name, entry in pairs(DataList.ConvertedPart) do
					if entry and entry.Part and entry.Part.Parent ~= nil then
						entry.Part:Destroy()
					end
					DataList.ConvertedPart[name] = nil
				end
			end

			local targetName = PlayerName
			if targetName == "Self" then
				targetName = Player.Name
			end

			if Method2CharacterFolder then
				for _, child in pairs(Method2CharacterFolder:GetChildren()) do
					if child.Name == (targetName or "NIL_FALLBACK") then





						local _holds = false


						if DataList and DataList._swapStash and NPCClear ~= true and DataList.Cooldown ~= true then
							for _, p in ipairs(DataList._swapStash.parts) do
								if typeof(p) == "Instance" and p:IsDescendantOf(child) then _holds = true; break end
							end
						end
						if _holds then
							pcall(function() child.Name = child.Name .. "_rcold" end)


							for _, r in ipairs(child:GetChildren()) do
								if r:IsA("Model") and r.Name:sub(1, 7) == "RC_VNS_" then
									local _own = false
									for _, d in ipairs(r:GetDescendants()) do if d.Name:sub(-6) == "_rcold" then _own = true; break end end
									if not _own then pcall(function() r:Destroy() end) end
								end
							end
							table.insert(DataList._swapStash.parts, child)
						else
							child:Destroy()
						end
					end
				end
			end

			DataList.CurrentPartList.BodyPartPhysics = {}





			if DataList.CurrentPartList["TrueMeshSize"] then
				pcall(function() DataList.CurrentPartList["TrueMeshSize"].Part:Destroy() end)
				DataList.CurrentPartList["TrueMeshSize"] = nil
			end
			DataList.CurrentPartList["TrueMeshSizePending"] = nil
			DataList.CurrentPartList.TrueMeshSizeRequest = nil
			DataList.CurrentPartList.TrueMeshSizeFailure = nil


			if DataList.CurrentPartList.RealtimeUpdateList and DataList.CurrentPartList.RealtimeUpdateList.Mesh then
				for _, Property in pairs(DataList.CurrentPartList.RealtimeUpdateList.Mesh) do
					if Property and Property.transparencyConn then
						pcall(function() Property.transparencyConn:Disconnect() end)
						Property.transparencyConn = nil
						Property._connectedBase = nil
					end
				end
			end

			DataList.CurrentPartList = Function.CurrentPartListDefault()


			local char = DataList.Character
			if not char then
				if type(PlayerName) ~= "string" and Function.IsCharacter(PlayerName) then
					char = PlayerName
				elseif game:GetService("Players"):FindFirstChild(PlayerName) then
					char = game:GetService("Players"):FindFirstChild(PlayerName).Character
				end
			end
			for i, v in pairs(game:GetService("CollectionService"):GetTagged("Visibility")) do

				if not (v:IsA("BasePart") and type(v:GetAttribute("Visibility")) == "number") then continue end
				v.Transparency = v:GetAttribute("Visibility")
				v.LocalTransparencyModifier = v:GetAttribute("Visibility")
				v:SetAttribute("Visibility",nil)
				v:RemoveTag("Visibility")
			end

			if char and ((DataList.MethodAtBuild or Method) ~= 2) then

				if DataList.OriginalHumanoidDescription then
					local realHum = char:FindFirstChildOfClass("Humanoid")
					if realHum then
						local _applyOk, _err = Function._resetApplyDesc(realHum, DataList)
						if _applyOk == "superseded" then return end
						if _applyOk then
							pcall(Function.diag, "hd.original_restored", { player = tostring(PlayerName) })
						else
							pcall(Function.diag, "hd.original_restore_failed", { player = tostring(PlayerName), err = tostring(_err) })
						end
					end
				else
					pcall(Function.diag, "hd.original_restore_skip_no_snapshot", { player = tostring(PlayerName) })
				end
				if DataList.OldestClothings.Shirt then
					if char:FindFirstChildOfClass("Shirt") then
						char:FindFirstChildOfClass("Shirt"):Destroy()
					end
					DataList.OldestClothings.Shirt:Clone().Parent = char
					DataList.OldestClothings.Shirt = nil
				else
					local _cur = char:FindFirstChildOfClass("Shirt")
					if _cur and _cur:GetAttribute("_RC_AppliedClothing") then _cur:Destroy() end
				end
				if DataList.OldestClothings.Pants then
					if char:FindFirstChildOfClass("Pants") then
						char:FindFirstChildOfClass("Pants"):Destroy()
					end
					DataList.OldestClothings.Pants:Clone().Parent = char
					DataList.OldestClothings.Pants = nil
				else
					local _cur = char:FindFirstChildOfClass("Pants")
					if _cur and _cur:GetAttribute("_RC_AppliedClothing") then _cur:Destroy() end
				end
				if DataList.OldestClothings.ShirtGraphic then
					if char:FindFirstChildOfClass("ShirtGraphic") then
						char:FindFirstChildOfClass("ShirtGraphic"):Destroy()
					end
					DataList.OldestClothings.ShirtGraphic:Clone().Parent = char
					DataList.OldestClothings.ShirtGraphic = nil
				else
					local _cur = char:FindFirstChildOfClass("ShirtGraphic")
					if _cur and _cur:GetAttribute("_RC_AppliedClothing") then _cur:Destroy() end
				end

				local _restoreHead = char and char:FindFirstChild("Head")
				if DataList.OldestClothings.HeadDecal and _restoreHead then
					local _existing = _restoreHead:FindFirstChildOfClass("Decal")
					if _existing then _existing:Destroy() end
					DataList.OldestClothings.HeadDecal:Clone().Parent = _restoreHead
					DataList.OldestClothings.HeadDecal = nil
				elseif _restoreHead then


					local _existing = _restoreHead:FindFirstChildOfClass("Decal")
					if _existing and _existing:GetAttribute("_RC_CatalogFace") then _existing:Destroy() end
				end
				if DataList.OldestClothings.HeadSpecialMesh and _restoreHead then
					local _existing = _restoreHead:FindFirstChildOfClass("SpecialMesh")
					if _existing then _existing:Destroy() end
					DataList.OldestClothings.HeadSpecialMesh:Clone().Parent = _restoreHead
					DataList.OldestClothings.HeadSpecialMesh = nil
				end
			else


				DataList.OldestClothings.Shirt = nil
				DataList.OldestClothings.Pants = nil
				DataList.OldestClothings.ShirtGraphic = nil

				DataList.OldestClothings.HeadDecal = nil
				DataList.OldestClothings.HeadSpecialMesh = nil
			end

		end
	end

_RCR.need("engine/physics_rod", { DefaultProperties = DefaultProperties, Function = Function, PlayerData = PlayerData, R15Transparency = R15Transparency, System = System })


	function Function._cdFree(dd, tok)
		if dd and (dd._cdOwner == nil or dd._cdOwner == tok) then dd.Cooldown = false; dd._cdOwner = nil end
	end
	function Function.CharacterExecute(Character, Data, bool, RequestID)
		local completion = {done = false, ok = false}
		local DataDetail = PlayerData[Data]
		if not DataDetail then completion.done = true; completion.error = "missing PlayerData"; return completion end
		if _RCA and Data == _RCA.me and not _RCA.gate() then completion.done = true; completion.error = "access"; return completion end
		if DataDetail._loadupPack then
			local _lp = DataDetail._loadupPack; DataDetail._loadupPack = nil
			if Data == Player.Name and DataDetail.CurrentBundle == _lp and type(Bundle[_lp]) == "table" and type(Bundle[_lp].Preset) == "table" and System._applyBundleAnimPack then
				pcall(System._applyBundleAnimPack, Bundle[_lp].Preset)
			end
		end


		if Data ~= "_rc_bundle_preview" then
			System._realBuilds = (System._realBuilds or 0) + 1; System._realBuildStart = os.clock()
			if System._cancelBundleLook then pcall(System._cancelBundleLook) end
		end


		DataDetail._catalogAppliedBodyColor = nil
		DataDetail._catBodyIds = nil


		local _MethodAtExec = (DataDetail and DataDetail.IsClone) and 1 or Method

		DataDetail.MethodAtBuild = _MethodAtExec

		if DataDetail.ExecutionMaid then
			DataDetail.ExecutionMaid:DoCleaning()
		end
		DataDetail.ExecutionMaid = Maid.new()

		task.defer(function()
			local _ceOk, _ceErr = pcall(function()
			if Function.IsStaleOrGone(Data, RequestID) then return end


			if UIS and UIS.TouchEnabled and not UIS.KeyboardEnabled then
				task.wait()
			end

			if not Character or not Function.CharacterIsBuilt(Character) then

				local count = 0
				repeat
					task.wait(0.05)
					count = count + 1
				until Function.CharacterIsBuilt(Character) or count > 100
					or Function.IsStaleOrGone(Data, RequestID)
				if Function.IsStaleOrGone(Data, RequestID) then return end
				if not Function.CharacterIsBuilt(Character) then

					warn("[RoClothes] CharacterExecute: character not fully built after 5s (streaming race); bundle apply skipped. Try clicking the bundle again.")
					return
				end
			end

			if Function.IsStaleOrGone(Data, RequestID) then return end

			local Human = Character:FindFirstChildOfClass("Humanoid")
			if not Human then return end

			Function.PlayerDataAdd(Data)

			local DataDetail = PlayerData[Data]


			if not DataDetail.OriginalHumanoidDescription then
				local _hdOk, _hd = pcall(function() return Human:GetAppliedDescription() end)
				if _hdOk and _hd then
					local _cloneOk, _clone = pcall(function() return _hd:Clone() end)
					if _cloneOk and _clone then
						DataDetail.OriginalHumanoidDescription = _clone
						pcall(Function.diag, "hd.original_captured", { player = tostring(Data) })
					else
						pcall(Function.diag, "hd.original_clone_failed", { player = tostring(Data), err = tostring(_clone) })
					end
				else
					pcall(Function.diag, "hd.original_capture_failed", { player = tostring(Data), err = tostring(_hd) })
				end
			end



			do
				local waitCount = 0
				DataDetail._ceInflight = DataDetail.Cooldown == true
				while DataDetail.Cooldown == true and waitCount < 30 do
					if Function.IsStaleOrGone(Data, RequestID) then return end
					task.wait()
					waitCount = waitCount + 1
				end
				if DataDetail.Cooldown == true then DataDetail.Cooldown = false end
			end

			if Function.IsStaleOrGone(Data, RequestID) then return end

			DataDetail["Cooldown"] = true; DataDetail._cdOwner = completion



			local function _bailIfStale()
				local _pd = PlayerData[Data]
				if not _pd then return true end
				if RequestID and RequestID ~= _pd.LastRequestID then
					if _pd.Cooldown == true then Function._cdFree(_pd, completion) end
					return true
				end
				return false
			end

			DataDetail._swapBuildAt = os.clock()



			local _preReset = RequestID ~= nil and DataDetail._preResetRid == RequestID and not DataDetail._ceInflight
				and DataDetail._swapStash ~= nil
			DataDetail._preResetRid = nil
			if not _preReset then pcall(Function.CharacterReset, Data) end

			if _bailIfStale() then return end


				if _MethodAtExec == 2 and Character and Character.Parent ~= nil then
					for _, v in pairs(Character:GetChildren()) do
						if v:IsA("BasePart") and v.Name ~= "Head" and (table.find(Method2BodyPart, v.Name) or v.Name == "HumanoidRootPart") then
							v.LocalTransparencyModifier = 1
						end
					end
				end

			DataDetail["Character"] = Character

			local _convOk, _convErr = pcall(Function.Converter, Character, Data, RequestID, _MethodAtExec)
			if not _convOk then
				warn("[RoClothes] Converter error (mesh load failed):", _convErr)
				Function._cdFree(DataDetail, completion) return
			end
			if PlayerData[Data] ~= DataDetail then Function._cdFree(DataDetail, completion) return end
			if _bailIfStale() then return end
			Function.AttachmentCreate(Character)

			local CharacterAttachment = Function.CharacterFunction(Character, Data)

			if Human then
				DataDetail.SavedPreviousHP = Human.Health
				if DataDetail.TopHP ~= "" then
					DataDetail.SavedTopHP = tonumber(DataDetail.TopHP) or 0
				end
				if DataDetail.BottomHP ~= "" then
					DataDetail.SavedBottomHP = tonumber(DataDetail.BottomHP) or 0
				end
			end
			Function.ClothesOffClearRip(DataDetail)
			local OldCharacter
			if _MethodAtExec == 2 then
				OldCharacter = Character
				DataDetail.RealCharacter = Character



				for _, _old in ipairs(Character:GetChildren()) do
					if _old:IsA("Model") and _old.Name:sub(1, 7) == "RC_VNS_" then pcall(function() _old:Destroy() end) end
				end

				if _bailIfStale() then return end

				Character = Method2CharacterFolder:FindFirstChild(Data)

				if Character then
					Character:Destroy()
					Character = nil
				end

				if not Character then
					Character = Instance.new("Model", Method2CharacterFolder)
					Character:AddTag(System.RCTag)
					Character.Archivable = not hidden
					Character.Name = Data
					local CharacterValue = Instance.new("ObjectValue", Character)
					CharacterValue.Value = OldCharacter

					for _, v in pairs(CharacterValue.Value:GetChildren()) do

						if _bailIfStale() then
							Character:Destroy()
							return
						end

						if v:IsA("BasePart") and (table.find(Method2BodyPart, v.Name) or v.Name == "HumanoidRootPart") then
							if v.Name ~= "Head" then
								DataDetail.CurrentPartList.ParentTransparency[v] = {D = v.Transparency,T = 1}
							end

							local Part = Instance.new("Part", Character)
							Part.Size = v.Size
							Part.Name = v.Name
							Part.Transparency = 1
							Part.CanCollide = false
							Part.CanQuery = false
							Part.CanTouch = false
							Part.Massless = true
							Part.CustomPhysicalProperties = DefaultProperties
							Part.Color = v.Color

							Part.CFrame = v.CFrame
							local Weld = Instance.new("Weld", Part)
							Weld.Part0 = v
							Weld.Part1 = Part

							if Part.Name == "HumanoidRootPart" then
								local RootWeldTarget = CharacterValue.Value:FindFirstChild("Torso") or CharacterValue.Value:FindFirstChild("UpperTorso")
								if RootWeldTarget then
									Weld.Part0 = RootWeldTarget
								else
									Weld.Part0 = v
								end
								Character.PrimaryPart = Part
							else
								Weld.Part0 = v
							end

							local detectRemoval
							detectRemoval = Part.ChildRemoved:Connect(function(c)


								if Part:IsDescendantOf(game) then
									if c:IsA("Weld") and c.Part0 == v then
										Function.TryRecloneWeld(Part, c)
									end
								else
									GlobalMaid:Remove(detectRemoval)
								end
							end)
							GlobalMaid:Give(detectRemoval)
							pcall(function() Part.Destroying:Once(function() pcall(GlobalMaid.Remove, GlobalMaid, detectRemoval) end) end)
						end
					end
				end
				if OldCharacter:FindFirstChildOfClass("Shirt") then
					if _bailIfStale() then Character:Destroy() return end
					if Character:FindFirstChildOfClass("Shirt") then
						Character:FindFirstChildOfClass("Shirt"):Destroy()
					end
					OldCharacter:FindFirstChildOfClass("Shirt"):Clone().Parent = Character
				end
				if OldCharacter:FindFirstChildOfClass("Pants") then
					if _bailIfStale() then Character:Destroy() return end
					if Character:FindFirstChildOfClass("Pants") then
						Character:FindFirstChildOfClass("Pants"):Destroy()
					end
					OldCharacter:FindFirstChildOfClass("Pants"):Clone().Parent = Character
				end
			end


			DataDetail.HPClothes.Shirt = ""
			DataDetail.HPClothes.Pants = ""
			if Bundle[DataDetail.CurrentBundle] and Bundle[DataDetail.CurrentBundle]["TClothes"] then
				for i, v in pairs(Bundle[DataDetail.CurrentBundle]["TClothes"]) do
					DataDetail.HPClothes[i] = v
				end
			end

			if type(DataDetail.HPClothesTemplates) == "table" then
				for _, _k in ipairs({ "Shirt", "Pants" }) do
					local _id = tonumber(DataDetail.HPClothesTemplates[_k])
					if _id then DataDetail.HPClothes[_k] = _id end
				end
			end

			if type(DataDetail.HPClothesUser) == "table" then
				for _k, _id in pairs(DataDetail.HPClothesUser) do
					if tonumber(_id) then DataDetail.HPClothes[_k] = tonumber(_id) end
				end
			end

			if DataDetail.NippleColorFromBundle then
				DataDetail.NippleColor = nil
				DataDetail.NippleColorFromBundle = false
			end
			if Bundle[DataDetail.CurrentBundle] and Bundle[DataDetail.CurrentBundle]["NippleColor"] and DataDetail.Tone == "Use NippleColor" then
				DataDetail.NippleColor = Bundle[DataDetail.CurrentBundle]["NippleColor"]
				DataDetail.NippleColorFromBundle = true
			end

			local TShirt = Character:FindFirstChildOfClass("ShirtGraphic")
			local Shirt = Character:FindFirstChildOfClass("Shirt")
			local Pants = Character:FindFirstChildOfClass("Pants")

			local function applyBundleClothesNuke()

				if TShirt then
					if DataDetail.OldestClothings.ShirtGraphic == nil and not TShirt:GetAttribute("_RC_AppliedClothing") then
						DataDetail.OldestClothings.ShirtGraphic = TShirt:Clone()
					end
					TShirt:Destroy()
					TShirt = nil
				end
				if Shirt then
					if DataDetail.OldestClothings.Shirt == nil and not Shirt:GetAttribute("_RC_AppliedClothing") then
						DataDetail.OldestClothings.Shirt = Shirt:Clone()
					end
					Shirt:Destroy()
					Shirt = nil
				end
				if Pants then
					if DataDetail.OldestClothings.Pants == nil and not Pants:GetAttribute("_RC_AppliedClothing") then
						DataDetail.OldestClothings.Pants = Pants:Clone()
					end
					Pants:Destroy()
					Pants = nil
				end
				if DataDetail.CurrentBundle ~= "Bald" then




					pcall(Function.BodyColorsFunction, Character, DataDetail.CurrentBundle, Data)
					Function.AccessoryLoaderFunction(Character, CharacterAttachment, DataDetail.CurrentBundle, Data, RequestID, _MethodAtExec)

					if _bailIfStale() then return true end
					Function.BodyColorsFunction(Character, DataDetail.CurrentBundle, Data)
				end
				return false
			end

			if DataDetail.CurrentBundle ~= "nil" and Bundle[DataDetail.CurrentBundle] and (not Bundle[DataDetail.CurrentBundle]["Override"] or Bundle[DataDetail.CurrentBundle]["Override"] == false) then
				if applyBundleClothesNuke() then return end
			end

			Function.CatalogLoader(Character, CharacterAttachment, Data, OldCharacter, RequestID, _MethodAtExec)
			if PlayerData[Data] ~= DataDetail then Function._cdFree(DataDetail, completion) return end
			if _bailIfStale() then return end
			local _bundleHasBodyColor = DataDetail.CurrentBundle and DataDetail.CurrentBundle ~= "nil"
				and Bundle[DataDetail.CurrentBundle] and Bundle[DataDetail.CurrentBundle]["Body Color"] ~= nil
				and DataDetail.BundleBodyColor

			local _catalogAppliedBC = DataDetail._catalogAppliedBodyColor == true
			DataDetail._catalogAppliedBodyColor = nil
			if DataDetail.SkinTone ~= nil and not _bundleHasBodyColor and not _catalogAppliedBC then

				Function.SnapshotOriginalBodyColors(DataDetail, Character)
				Function.BodyColorForceSet(Character, DataDetail.SkinTone)
				if OldCharacter and OldCharacter ~= Character then
					Function.BodyColorForceSet(OldCharacter, DataDetail.SkinTone)
				end
			end

			if DataDetail.CurrentBundle ~= "nil" and Bundle[DataDetail.CurrentBundle] and Bundle[DataDetail.CurrentBundle]["Override"] == true then
				if applyBundleClothesNuke() then return end
			end

			TShirt = Character:FindFirstChildOfClass("ShirtGraphic")
			Shirt = Character:FindFirstChildOfClass("Shirt")
			Pants = Character:FindFirstChildOfClass("Pants")

			local Extra = {["TShirt"] = TShirt, ["Shirt"] = Shirt, ["Pants"] = Pants, ["Tone"] = DataDetail.Tone, ["SkinTone"] = DataDetail.SkinTone, ["NippleColor"] = DataDetail.NippleColor}




			local _hpFast = false
			if (DataDetail.HPClothes.Shirt ~= "" or DataDetail.HPClothes.Pants ~= "") and Function._clothTplGet then
				local _syn, _all = {}, true
				for Type, Id in pairs(DataDetail.HPClothes) do
					if Id ~= "" and (type(Id) == "string" or type(Id) == "number") then
						local tpl = (Type == "Shirt" or Type == "Pants") and Function._clothTplGet(Id) or nil
						if tpl then local o = Instance.new(Type); o[Type .. "Template"] = tpl; _syn[Type] = o else _all = false end
					end
				end
				if _all and next(_syn) then
					for T, o in pairs(_syn) do DataDetail.HPClothes[T] = o end
					_hpFast = true
				else
					for _, o in pairs(_syn) do o:Destroy() end
				end
			end
			if not _hpFast and (DataDetail.HPClothes.Shirt ~= "" or DataDetail.HPClothes.Pants ~= "") then
				local HumanoidDescription = Instance.new("HumanoidDescription")
				for Type, Id in pairs(DataDetail.HPClothes) do
					if Id ~= "" and (type(Id) == "string" or type(Id) == "number") then
						if Type == "Shirt" then
							HumanoidDescription.Shirt = Id
						elseif Type == "Pants" then
							HumanoidDescription.Pants = Id
						elseif Type == "ShirtGraphic" then
							HumanoidDescription.GraphicTShirt = Id
						end
					end
				end
				local AccessoryLoaderModel = Instance.new("Model", workspace)
				AccessoryLoaderModel:AddTag(System.RCTag)
				AccessoryLoaderModel.Archivable = not hidden
				

				local headLoader = Instance.new("Part", AccessoryLoaderModel)
				headLoader.Name = "Head"
				headLoader.Transparency = 1
				headLoader.CanCollide = false
				headLoader.Anchored = true

				local HumanoidAccessoryLoader = Instance.new("Humanoid", AccessoryLoaderModel)




				local _applyOkCU, _applyErrCU, _hdDoneCU = false, nil, false
				task.spawn(function()
					_applyOkCU, _applyErrCU = pcall(function() HumanoidAccessoryLoader:ApplyDescription(HumanoidDescription) end)
					_hdDoneCU = true
				end)
				local _hdT0 = os.clock()
				while not _hdDoneCU and os.clock() - _hdT0 < 8 do task.wait(0.1) end
				if not _hdDoneCU then _applyOkCU, _applyErrCU = false, "timed out after 8 s" end
				if not _applyOkCU then


					warn("[RoClothes] ripped clothes ApplyDescription threw - likely content-deleted or rate-limited clothing ID, ripped clothes skipped: " .. tostring(_applyErrCU))
				end
				if _bailIfStale() then
					AccessoryLoaderModel:Destroy() HumanoidDescription:Destroy()
					return
				end



				local function convertId(id)
					local success, decalObject = pcall(function()
						local decalObject = game:GetObjects("rbxassetid://"..id)[1]
						return decalObject
					end)
					if success and decalObject and decalObject:IsA("Decal") then
						return decalObject.Texture
					elseif string.gsub(tostring(id), "%D", "") == tostring(id) then
						return "rbxassetid://".. id
					else
						return id
					end
				end
				for _, v in pairs(AccessoryLoaderModel:GetChildren()) do
					if v:IsA("Shirt") or v:IsA("Pants") or v:IsA("ShirtGraphic") then
						if v:IsA("Shirt") and string.gsub(v.ShirtTemplate,"%D","") == "855777285" and HumanoidDescription.Shirt then
							v.ShirtTemplate = convertId(HumanoidDescription.Shirt)
						elseif v:IsA("Pants") and string.gsub(v.PantsTemplate,"%D","") == "867826313" and HumanoidDescription.Pants then
							v.PantsTemplate = convertId(HumanoidDescription.Pants)
						elseif v:IsA("Shirt") and Function._clothTplPut then
							Function._clothTplPut(HumanoidDescription.Shirt, v.ShirtTemplate)
						elseif v:IsA("Pants") and Function._clothTplPut then
							Function._clothTplPut(HumanoidDescription.Pants, v.PantsTemplate)
						end
						local _hpClone = v:Clone()
						_hpClone.Parent = nil
						DataDetail.HPClothes[v.ClassName] = _hpClone
					end
				end
				AccessoryLoaderModel:Destroy()
				HumanoidDescription:Destroy()
			end

			local PartListData = (System.Community and System.Community.overlayPartList(DataDetail.PartList, DataDetail)) or DataDetail.PartList


			local PhysicsRotationOffset = {
				X = "Z",
				Y = "X",
				Z = "Y",
			}
			local Rotation = {
				X = 5,
				Y = -5,
				Z = 5
			}

			local TORSO
			local LEFTLEG
			local RIGHTLEG
			local LEFTARM
			local RIGHTARM
			local LEFTBUTT
			local RIGHTBUTT

			local LEFTBREAST
			local RIGHTBREAST


			local _hideLiveLimbs = function(_names)
				if _MethodAtExec == 2 then return end
				if not Character then return end
				local _origMap = DataDetail.CurrentPartList and DataDetail.CurrentPartList.OriginalTransparency
				if not _origMap then return end
				for _, _n in ipairs(_names) do
					local _bp = Character:FindFirstChild(_n)
					if _bp and _bp:IsA("BasePart") then
						if _origMap[_bp] == nil then
							_origMap[_bp] = _bp.Transparency
						end
						pcall(function() _bp.LocalTransparencyModifier = 1 end)
					end
				end
			end


			local function _paintSBOverlay(_part, _template, _marker)
				if not (_part and _template and _template ~= "") then return end
				local _sa = _part:FindFirstChildOfClass("SurfaceAppearance")

				if _sa then
					local _isOurs = false
					pcall(function()
						_isOurs = _sa:GetAttribute("RoClothesShirt") or _sa:GetAttribute("RoClothesPants")
							or _sa:GetAttribute("RoClothesTShirt") or _sa:GetAttribute("KrulHosted")
							or _sa:GetAttribute(_marker)
					end)
					if not _isOurs then return end
				end


				local _mode = _setOrCreateSA(_part, _template, Enum.AlphaMode.Overlay, _marker)
				_part.Transparency = (_mode == "tex") and 0.011 or 0
			end
			local _shirtTpl = (Extra.Shirt and Extra.Shirt.ShirtTemplate)
				or (Extra.Pants and Extra.Pants.PantsTemplate)
			local _pantsTpl = Extra.Pants and Extra.Pants.PantsTemplate
			local _hasShirtToggle = DataDetail.CurrentClothes
				and (table.find(DataDetail.CurrentClothes, "Roblox Shirt") ~= nil)
			local _hasPantsToggle = DataDetail.CurrentClothes
				and (table.find(DataDetail.CurrentClothes, "Roblox Pants") ~= nil)



			if Function.FullBodySkip(DataDetail, "TorsoType") then
			elseif DataDetail.TorsoType == 1 then
				TORSO = Function.Weld(PartListData["Torso"], Character, Extra, Data, RequestID)
			elseif DataDetail.TorsoType == 9 then
				local _, parts = Function.RigVnsModel("RClothesContent/_vns/model/torso/1/model.rbxm", Character, RequestID, nil, Data)
				if _bailIfStale() then return end
				TORSO = parts["Torso"] or parts["Torso Mesh"] or parts["1"]
				if not TORSO then
					warn("[RoClothes] TorsoType 9: RigVnsModel returned no parts - falling back to Function.Weld.")
					TORSO = Function.Weld(PartListData["Torso9"], Character, Extra, Data, RequestID)
				end
				_hideLiveLimbs({"Torso", "UpperTorso", "LowerTorso"})
			else
				TORSO = Function.Weld(PartListData["Torso".. DataDetail.TorsoType], Character, Extra, Data, RequestID)
			end
			if TORSO then DataDetail.CurrentPartList["Organ"]["Torso"] = TORSO end
			if DataDetail.TorsoType == 9 and TORSO then
				if _hasShirtToggle then _paintSBOverlay(TORSO, _shirtTpl, "RoClothesShirt") end
				if _hasPantsToggle then _paintSBOverlay(TORSO, _pantsTpl, "RoClothesPants") end
			end


			if Function.FullBodySkip(DataDetail, "ArmType") then
			elseif DataDetail.ArmType == 1 then
				LEFTARM = Function.Weld(PartListData["Left Arm"], Character, Extra, Data, RequestID)
				RIGHTARM = Function.Weld(PartListData["Right Arm"], Character, Extra, Data, RequestID)
			elseif DataDetail.ArmType == 5 then
				local _, parts = Function.RigVnsModel("RClothesContent/_vns/model/arm/1/model.rbxm", Character, RequestID, nil, Data)
				if _bailIfStale() then return end
				LEFTARM  = parts["Left Arm"]
				RIGHTARM = parts["Right Arm"]
				if not LEFTARM then
					warn("[RoClothes] ArmType 5: RigVnsModel returned no parts - falling back to Function.Weld.")
					LEFTARM  = Function.Weld(PartListData["Left Arm5"],  Character, Extra, Data, RequestID)
					RIGHTARM = Function.Weld(PartListData["Right Arm5"], Character, Extra, Data, RequestID)
				end
				_hideLiveLimbs({
					"Left Arm", "Right Arm",
					"LeftUpperArm", "LeftLowerArm", "LeftHand",
					"RightUpperArm", "RightLowerArm", "RightHand",
				})
			else
				LEFTARM = Function.Weld(PartListData["Left Arm".. DataDetail.ArmType], Character, Extra, Data, RequestID)
				RIGHTARM = Function.Weld(PartListData["Right Arm".. DataDetail.ArmType], Character, Extra, Data, RequestID)
			end
			if LEFTARM then DataDetail.CurrentPartList["Organ"]["Left Arm"] = LEFTARM end
			if RIGHTARM then DataDetail.CurrentPartList["Organ"]["Right Arm"] = RIGHTARM end
			if DataDetail.ArmType == 5 and _hasShirtToggle and _shirtTpl then
				if LEFTARM  then _paintSBOverlay(LEFTARM,  _shirtTpl, "RoClothesShirt") end
				if RIGHTARM then _paintSBOverlay(RIGHTARM, _shirtTpl, "RoClothesShirt") end
			end


			if Function.FullBodySkip(DataDetail, "LegsType") then
			elseif DataDetail.LegsType == 1 then
				LEFTLEG = Function.Weld(PartListData["Left Leg"], Character, Extra, Data, RequestID)
				RIGHTLEG = Function.Weld(PartListData["Right Leg"], Character, Extra, Data, RequestID)
			elseif DataDetail.LegsType == 8 then
				local _, parts = Function.RigVnsModel("RClothesContent/_vns/model/leg/1/model.rbxm", Character, RequestID, nil, Data)
				if _bailIfStale() then return end
				LEFTLEG  = parts["Left Leg"]
				RIGHTLEG = parts["Right Leg"]
				if not LEFTLEG then
					warn("[RoClothes] LegsType 8: RigVnsModel returned no parts - falling back to Function.Weld.")
					LEFTLEG  = Function.Weld(PartListData["Left Leg8"],  Character, Extra, Data, RequestID)
					RIGHTLEG = Function.Weld(PartListData["Right Leg8"], Character, Extra, Data, RequestID)
				end
				_hideLiveLimbs({
					"Left Leg", "Right Leg",
					"LeftUpperLeg", "LeftLowerLeg", "LeftFoot",
					"RightUpperLeg", "RightLowerLeg", "RightFoot",
				})
			else
				LEFTLEG = Function.Weld(PartListData["Left Leg".. DataDetail.LegsType], Character, Extra, Data, RequestID)
				RIGHTLEG = Function.Weld(PartListData["Right Leg".. DataDetail.LegsType], Character, Extra, Data, RequestID)
			end
			if LEFTLEG then DataDetail.CurrentPartList["Organ"]["Left Leg"] = LEFTLEG end
			if RIGHTLEG then DataDetail.CurrentPartList["Organ"]["Right Leg"] = RIGHTLEG end
			if DataDetail.LegsType == 8 and _hasPantsToggle and _pantsTpl then
				if LEFTLEG  then _paintSBOverlay(LEFTLEG,  _pantsTpl, "RoClothesPants") end
				if RIGHTLEG then _paintSBOverlay(RIGHTLEG, _pantsTpl, "RoClothesPants") end
			end


			if DataDetail._catBodyIds then
				local _cbOk, _cbErr = pcall(Function.CatalogBodyBuild, Character, OldCharacter, Data, RequestID, _MethodAtExec, Extra)
				if not _cbOk then warn("[RoClothes] catalog Full Body build failed:", _cbErr) end
				if _bailIfStale() then return end
			elseif DataDetail.TorsoType == 0 or DataDetail.ArmType == 0 or DataDetail.LegsType == 0 then
				pcall(Function.TypeZeroShow, OldCharacter or Character, Data)
			end

			if DataDetail.ButtType == 0 then
			elseif DataDetail.ButtType == 1 then
				LEFTBUTT = Function.Weld(PartListData["Left Butt"], Character, Extra, Data, RequestID)
				RIGHTBUTT = Function.Weld(PartListData["Right Butt"], Character, Extra, Data, RequestID)
			elseif DataDetail.ButtType >= 2 and DataDetail.ButtType <= 3 then

				LEFTBUTT  = Function.Weld(PartListData["Left Butt"  .. DataDetail.ButtType], Character, Extra, Data, RequestID)
				RIGHTBUTT = Function.Weld(PartListData["Right Butt" .. DataDetail.ButtType], Character, Extra, Data, RequestID)
			elseif DataDetail.ButtType == 6 then

				local _, parts = Function.RigVnsModel("RClothesContent/_vns/model/butt/1/model.rbxm", Character, RequestID, nil, Data)
				if _bailIfStale() then return end
				LEFTBUTT  = parts["Left Butt"]
				RIGHTBUTT = parts["Right Butt"]
				if not LEFTBUTT then
					warn("[RoClothes] ButtType 6: RigVnsModel returned no parts - falling back to Function.Weld(SB1).")
					LEFTBUTT  = Function.Weld(PartListData["Left Butt SB1"],  Character, Extra, Data, RequestID)
					RIGHTBUTT = Function.Weld(PartListData["Right Butt SB1"], Character, Extra, Data, RequestID)
				end
			else

				LEFTBUTT  = Function.Weld(PartListData["Left Butt"],  Character, Extra, Data, RequestID)
				RIGHTBUTT = Function.Weld(PartListData["Right Butt"], Character, Extra, Data, RequestID)
			end
			if LEFTBUTT then DataDetail.CurrentPartList["Organ"]["Left Butt"] = LEFTBUTT end
			if RIGHTBUTT then DataDetail.CurrentPartList["Organ"]["Right Butt"] = RIGHTBUTT end
			if DataDetail.ButtType == 6 and _hasPantsToggle and _pantsTpl then
				if LEFTBUTT  then _paintSBOverlay(LEFTBUTT,  _pantsTpl, "RoClothesPants") end
				if RIGHTBUTT then _paintSBOverlay(RIGHTBUTT, _pantsTpl, "RoClothesPants") end
			end


			if DataDetail.BreastsType == 1 then
				LEFTBREAST = Function.Weld(PartListData["Left Breast"], Character, Extra, Data, RequestID)
				RIGHTBREAST = Function.Weld(PartListData["Right Breast"], Character, Extra, Data, RequestID)
				if LEFTBREAST then DataDetail.CurrentPartList["Organ"]["Left Breast"] = LEFTBREAST end
				if RIGHTBREAST then DataDetail.CurrentPartList["Organ"]["Right Breast"] = RIGHTBREAST end

				local LEFTNIPPLE = Function.Weld(PartListData["Left Nipple"], Character, Extra, Data, RequestID)
				local RIGHTNIPPLE = Function.Weld(PartListData["Right Nipple"], Character, Extra, Data, RequestID)
				if LEFTNIPPLE then DataDetail.CurrentPartList["Organ"]["Left Nipple"] = LEFTNIPPLE end
				if RIGHTNIPPLE then DataDetail.CurrentPartList["Organ"]["Right Nipple"] = RIGHTNIPPLE end
			elseif DataDetail.BreastsType == 2 then
				LEFTBREAST = Function.Weld(PartListData["Left Breast Type 2"], Character, Extra, Data, RequestID)
				RIGHTBREAST = Function.Weld(PartListData["Right Breast Type 2"], Character, Extra, Data, RequestID)
				if LEFTBREAST then DataDetail.CurrentPartList["Organ"]["Left Breast"] = LEFTBREAST end
				if RIGHTBREAST then DataDetail.CurrentPartList["Organ"]["Right Breast"] = RIGHTBREAST end


				PhysicsRotationOffset = {
					X = "Y",
					Y = "X",
					Z = "Z",
				}

			elseif DataDetail.BreastsType == 3 then
				LEFTBREAST = Function.Weld(PartListData["Left Breast Type 3"], Character, Extra, Data, RequestID)
				RIGHTBREAST = Function.Weld(PartListData["Right Breast Type 3"], Character, Extra, Data, RequestID)
				if LEFTBREAST then DataDetail.CurrentPartList["Organ"]["Left Breast"] = LEFTBREAST end
				if RIGHTBREAST then DataDetail.CurrentPartList["Organ"]["Right Breast"] = RIGHTBREAST end

				local LEFTNIPPLE = Function.Weld(PartListData["Left Nipple Type 3"], Character, Extra, Data, RequestID)
				local RIGHTNIPPLE = Function.Weld(PartListData["Right Nipple Type 3"], Character, Extra, Data, RequestID)
				if LEFTNIPPLE then DataDetail.CurrentPartList["Organ"]["Left Nipple"] = LEFTNIPPLE end
				if RIGHTNIPPLE then DataDetail.CurrentPartList["Organ"]["Right Nipple"] = RIGHTNIPPLE end


				Rotation = {X=5, Y=5, Z=5}
			elseif DataDetail.BreastsType == 4 then
				LEFTBREAST = Function.Weld(PartListData["Left Breast Type 4"], Character, Extra, Data, RequestID)
				RIGHTBREAST = Function.Weld(PartListData["Right Breast Type 4"], Character, Extra, Data, RequestID)
				if LEFTBREAST then DataDetail.CurrentPartList["Organ"]["Left Breast"] = LEFTBREAST end
				if RIGHTBREAST then DataDetail.CurrentPartList["Organ"]["Right Breast"] = RIGHTBREAST end

				local LEFTAREOLA = Function.Weld(PartListData["Left Areola Type 4"], Character, Extra, Data, RequestID)
				local RIGHTAREOLA = Function.Weld(PartListData["Right Areola Type 4"], Character, Extra, Data, RequestID)
				local LEFTNIPPLE = Function.Weld(PartListData["Left Nipple Type 4"], Character, Extra, Data, RequestID)
				local RIGHTNIPPLE = Function.Weld(PartListData["Right Nipple Type 4"], Character, Extra, Data, RequestID)
				if LEFTAREOLA and LEFTNIPPLE then DataDetail.CurrentPartList.Link[LEFTAREOLA] = {T=LEFTNIPPLE} end
				if RIGHTAREOLA and RIGHTNIPPLE then DataDetail.CurrentPartList.Link[RIGHTAREOLA] = {T=RIGHTNIPPLE} end
				if LEFTAREOLA then DataDetail.CurrentPartList["Organ"]["Left Areola"] = LEFTAREOLA end
				if RIGHTAREOLA then DataDetail.CurrentPartList["Organ"]["Right Areola"] = RIGHTAREOLA end
				if LEFTNIPPLE then DataDetail.CurrentPartList["Organ"]["Left Nipple"] = LEFTNIPPLE end
				if RIGHTNIPPLE then DataDetail.CurrentPartList["Organ"]["Right Nipple"] = RIGHTNIPPLE end
			elseif DataDetail.BreastsType == 5 then
				LEFTBREAST = Function.Weld(PartListData["Left Breast Type 5"], Character, Extra, Data, RequestID)
				RIGHTBREAST = Function.Weld(PartListData["Right Breast Type 5"], Character, Extra, Data, RequestID)
				if LEFTBREAST then DataDetail.CurrentPartList["Organ"]["Left Breast"] = LEFTBREAST end
				if RIGHTBREAST then DataDetail.CurrentPartList["Organ"]["Right Breast"] = RIGHTBREAST end

				local LEFTNIPPLE = Function.Weld(PartListData["Left Nipple Type 5"], Character, Extra, Data, RequestID)
				local RIGHTNIPPLE = Function.Weld(PartListData["Right Nipple Type 5"], Character, Extra, Data, RequestID)
				if LEFTNIPPLE then DataDetail.CurrentPartList["Organ"]["Left Nipple"] = LEFTNIPPLE end
				if RIGHTNIPPLE then DataDetail.CurrentPartList["Organ"]["Right Nipple"] = RIGHTNIPPLE end


				PhysicsRotationOffset = {X="Y", Y="X", Z="Z"}
				Rotation = {X=5, Y=5, Z=5}

			elseif DataDetail.BreastsType == 6 then


				local _rvOk, _rvA, _rvB = pcall(Function.RigVnsModel, "RClothesContent/_vns/model/breast/1/model.rbxm", Character, RequestID, nil, Data)
				if not _rvOk then
					warn("[RoClothes] BreastsType 6: RigVnsModel threw - " .. tostring(_rvA))
				end
				local parts = (_rvOk and _rvB) or {}
				if _bailIfStale() then return end

				if not parts["Left Breast"] then
					task.wait(0.5)
					if _bailIfStale() then return end
					local _rv2Ok, _rv2A, _rv2B = pcall(Function.RigVnsModel, "RClothesContent/_vns/model/breast/1/model.rbxm", Character, RequestID, nil, Data)
					if _rv2Ok and _rv2B and _rv2B["Left Breast"] then parts = _rv2B end
					if _bailIfStale() then return end
				end
				LEFTBREAST  = parts["Left Breast"]
				RIGHTBREAST = parts["Right Breast"]
				local _sb1Nipples = {}
				if not LEFTBREAST then
					warn("[RoClothes] BreastsType 6: RigVnsModel returned no parts - falling back to Function.Weld(SB1).")
					LEFTBREAST  = Function.Weld(PartListData["Left Breast SB1"],  Character, Extra, Data, RequestID)
					RIGHTBREAST = Function.Weld(PartListData["Right Breast SB1"], Character, Extra, Data, RequestID)
					local LN = Function.Weld(PartListData["Left Nipple SB1"],  Character, Extra, Data, RequestID)
					local RN = Function.Weld(PartListData["Right Nipple SB1"], Character, Extra, Data, RequestID)
					if LN then DataDetail.CurrentPartList["Organ"]["Left Nipple"]  = LN; _sb1Nipples[#_sb1Nipples+1] = LN end
					if RN then DataDetail.CurrentPartList["Organ"]["Right Nipple"] = RN; _sb1Nipples[#_sb1Nipples+1] = RN end
				else
					if parts["Left Nipple"]  then DataDetail.CurrentPartList["Organ"]["Left Nipple"]  = parts["Left Nipple"]  end
					if parts["Right Nipple"] then DataDetail.CurrentPartList["Organ"]["Right Nipple"] = parts["Right Nipple"] end
				end
				if LEFTBREAST  then DataDetail.CurrentPartList["Organ"]["Left Breast"]  = LEFTBREAST  end
				if RIGHTBREAST then DataDetail.CurrentPartList["Organ"]["Right Breast"] = RIGHTBREAST end






				local _rvFPBase = Character:FindFirstChild("Torso") or Character:FindFirstChild("UpperTorso")
				if _rvFPBase and DataDetail.CurrentPartList.RealtimeUpdateList and DataDetail.CurrentPartList.RealtimeUpdateList.Mesh then
					for _, _rvNm in ipairs({ "Left Breast", "Right Breast", "Left Nipple", "Right Nipple" }) do
						local _rvbp = parts[_rvNm]
						if _rvbp and _rvbp:IsA("BasePart") then DataDetail.CurrentPartList.RealtimeUpdateList.Mesh[_rvbp] = { Base = _rvFPBase, FPOnly = true } end
					end
				end

				if not LEFTBREAST and not RIGHTBREAST then
					warn("[RoClothes] BreastsType 6: BOTH RigVnsModel AND Function.Weld(SB1) failed - breast will be missing. Check that RClothesContent/_vns/model/breast/1/ exists on disk and that the executor's getcustomasset / game:GetObjects work. As a workaround, switch to BreastsType 1-5.")
				end

				PhysicsRotationOffset = {X="Y", Y="X", Z="Z"}


				for _, _show in ipairs({"Left Breast","Right Breast","Left Nipple","Right Nipple"}) do
					local _bp = parts and parts[_show]
					if _bp and _bp:IsA("BasePart") then _bp.Transparency = 0; _bp:SetAttribute("MaxTransparencyRC", nil) end
				end
				for _, _p in pairs({LEFTBREAST, RIGHTBREAST, table.unpack(_sb1Nipples)}) do
					if _p and _p:IsA("BasePart") then _p.Transparency = 0; _p:SetAttribute("MaxTransparencyRC", nil) end
				end

				local _rcBreastClean = Character:FindFirstChild("RC_VNS_breast")
				if _rcBreastClean then
					for _, _c in ipairs(_rcBreastClean:GetChildren()) do
						if _c.Name == "BreastClothes" then _c:Destroy() end
					end
				end
			elseif DataDetail.BreastsType == 7 then

				warn("[RoClothes] BreastsType 7 deprecated as of V4.3.414 - falling back to SB1 weld.")
				LEFTBREAST  = Function.Weld(PartListData["Left Breast SB1"],  Character, Extra, Data, RequestID)
				RIGHTBREAST = Function.Weld(PartListData["Right Breast SB1"], Character, Extra, Data, RequestID)
				local LN = Function.Weld(PartListData["Left Nipple SB1"],  Character, Extra, Data, RequestID)
				local RN = Function.Weld(PartListData["Right Nipple SB1"], Character, Extra, Data, RequestID)

				if _bailIfStale() then return end
				if LN then DataDetail.CurrentPartList["Organ"]["Left Nipple"]  = LN end
				if RN then DataDetail.CurrentPartList["Organ"]["Right Nipple"] = RN end
				if LEFTBREAST  then DataDetail.CurrentPartList["Organ"]["Left Breast"]  = LEFTBREAST  end
				if RIGHTBREAST then DataDetail.CurrentPartList["Organ"]["Right Breast"] = RIGHTBREAST end
				PhysicsRotationOffset = {X="Y", Y="X", Z="Z"}
			end

			if DataDetail.BodyPartPhysics then
				local Torso = Character:FindFirstChild("Torso")

				if Torso then

					if DataDetail.ButtType ~= 6 then
						if RIGHTBUTT then Function.SpringCreate(
							RIGHTBUTT,
							Torso,
							Vector3.new(0,0,0),
							Vector3.new(0,0,0),
							DataDetail.ButtsStiffness or SpringConfigs.Buttocks.Speed,
							DataDetail.ButtsDamping or SpringConfigs.Buttocks.Damper,
							{X="X", Y="Y", Z="Z"},
							PhysicsPosition.Buttocks,
							{X="Y", Y="X", Z="Z"},
							PhysicsRotation.Buttocks,
							Data
						)
						end
						if LEFTBUTT then Function.SpringCreate(
							LEFTBUTT,
							Torso,
							Vector3.new(0,0,0),
							Vector3.new(0,0,0),
							DataDetail.ButtsStiffness or SpringConfigs.Buttocks.Speed,
							DataDetail.ButtsDamping or SpringConfigs.Buttocks.Damper,
							{X="X", Y="Y", Z="Z"},
							PhysicsPosition.Buttocks,
							{X="Y", Y="X", Z="Z"},
							PhysicsRotation.Buttocks,
							Data
						) end
					end




					if DataDetail.BreastsType ~= 6 then
						if RIGHTBREAST then Function.SpringCreate(
							RIGHTBREAST,
							Torso,
							Vector3.new(0,0,0),
							Vector3.new(0,0,0),
							DataDetail.BreastsStiffness or SpringConfigs.Breasts.Speed,
							DataDetail.BreastsDamping or SpringConfigs.Breasts.Damper,
							{X="X", Y="Y", Z="Z"},
							{X=0, Y=0, Z=0},
							PhysicsRotationOffset,
							Rotation,
							Data
						) end
						if LEFTBREAST then Function.SpringCreate(
							LEFTBREAST,
							Torso,
							Vector3.new(0,0,0),
							Vector3.new(0,0,0),
							DataDetail.BreastsStiffness or SpringConfigs.Breasts.Speed,
							DataDetail.BreastsDamping or SpringConfigs.Breasts.Damper,
							{X="X", Y="Y", Z="Z"},
							{X=0, Y=0, Z=0},
							PhysicsRotationOffset,
							Rotation,
							Data
						) end
					end
				end
			end

			if DataDetail.MeshBasePartInvisible then
				for _, part in pairs({TORSO, LEFTLEG, RIGHTLEG, LEFTARM, RIGHTARM}) do
					if part then
						part.Transparency = 1
						DataDetail.CurrentPartList.ParentTransparency[part] = {D = 0, T = 1}
					end
				end
			end


			pcall(function()
				local function sweepMeshPart(meshPart)
					for _, child in ipairs(meshPart:GetChildren()) do
						if (child:IsA("SurfaceAppearance") or child:IsA("SpecialMesh") or child:GetAttribute("RCClothingLayer")) and child:GetAttribute("KrulHosted") then
							child:Destroy()
						elseif child:IsA("MeshPart") then
							sweepMeshPart(child)
						end
					end
				end
				local function sweepTable(t)
					if not t then return end
					for _, meshPart in pairs(t) do
						if typeof(meshPart) == "Instance" and meshPart:IsA("MeshPart") then
							sweepMeshPart(meshPart)
						end
					end
				end
				sweepTable(DataDetail.CurrentPartList["Organ"])
				sweepTable(DataDetail.CurrentPartList["Clothes"])
			end)

			if not Function._ceClothingPass1(Character, Data, RequestID, DataDetail, Extra, PartListData, _bailIfStale, _hasShirtToggle) then return end

			if not Function._ceClothingPass2AndHP(Character, Data, RequestID, DataDetail, Extra, PartListData, _bailIfStale, completion) then return end
			return true
			end)
			completion.ok = _ceOk and _ceErr == true and not Function.IsStaleOrGone(Data, RequestID)
			if not completion.ok then completion.error = _ceOk and "build aborted or character unavailable" or tostring(_ceErr) end
			completion.done = true


			local _willRetry = false
			if PlayerData[Data] == DataDetail and (not RequestID or RequestID == DataDetail.LastRequestID) then
				_willRetry = not completion.ok and Data == SelectPlayer and not DataDetail._ceRetried and System._sessionAlive ~= false
					and DataDetail._swapStash ~= nil and Character and Character.Parent ~= nil and System.hotSwap ~= nil
				if _willRetry then
					DataDetail._ceRetried = true
					task.delay(1.5, function()
						if PlayerData[Data] ~= DataDetail or (RequestID and RequestID ~= DataDetail.LastRequestID) or System._sessionAlive == false then return end
						Function._cdFree(DataDetail, completion)
						System.hotSwap()
					end)
				else
					pcall(Function._swapFlush, DataDetail)
					if completion.ok then DataDetail._ceRetried = nil; pcall(Function._dedupeOrphans, DataDetail) end
				end
			end
			if Data ~= "_rc_bundle_preview" then System._realBuilds = math.max(0, (System._realBuilds or 1) - 1); System._realBuildEnd = os.clock() end
			if _RCA and completion.ok and Data == _RCA.me then pcall(_RCA.logLook, "exec", (DataDetail.CurrentBundle ~= "nil" and DataDetail.CurrentBundle) or "", Character, System._rcaLookText and System._rcaLookText(DataDetail, Character)) end
			if not completion.ok and not _willRetry then pcall(Function._ceReportFailure, Character, Data, RequestID, DataDetail) end
			if not _ceOk then
				warn("[RoClothes] CharacterExecute error:", _ceErr)
				Function._cdFree(DataDetail, completion)
			end
		end)








		local function _cooldownNet(waited)


			if not _isActiveSession() then return end
			if not (DataDetail and DataDetail["Cooldown"] == true) then return end
			if RequestID and DataDetail.LastRequestID ~= RequestID then return end
			if not completion.done and waited < 60 then
				task.delay(5, _cooldownNet, waited + 5)
				return
			end
			Function._cdFree(DataDetail, completion)
		end
		task.delay(5, _cooldownNet, 5)
		return completion
	end



	function Function._ceReportFailure(Character, Data, RequestID, DataDetail)
		if Data == "_rc_bundle_preview" or (type(Data) == "string" and Data:sub(1, 11) == "_rc_review_") or (Data ~= Player.Name and not DataDetail.IsClone) then return false end
		if System._sessionAlive == false or not _isActiveSession() then return false end
		if PlayerData[Data] ~= DataDetail or (RequestID and RequestID ~= DataDetail.LastRequestID) then return false end
		if not (Character and Character.Parent) then return false end
		Function.diag("build.failed", { clone = DataDetail.IsClone and true or false })
		if System.uiToast then System.uiToast("Outfit didn't finish", "Something went wrong while building it. Press Execute to try again.", "warn") end
		return true
	end



	function Function._ceClothingPass1(Character, Data, RequestID, DataDetail, Extra, PartListData, _bailIfStale, _hasShirtToggle)


		local _clothingBuildOrder = {}
		for _, name in ipairs(DataDetail.CurrentClothes) do
			if name == "Breast Clothes SB1" or name == "Breast Clothes SB2" then table.insert(_clothingBuildOrder, name) end
		end
		for _, name in ipairs(DataDetail.CurrentClothes) do
			if name ~= "Breast Clothes SB1" and name ~= "Breast Clothes SB2" then table.insert(_clothingBuildOrder, name) end
		end
		if System.Community then System.Community.appendClothing(_clothingBuildOrder, DataDetail) end
		for _, SelectClothes in ipairs(_clothingBuildOrder) do
			if _bailIfStale() then return end
			if SelectClothes ~= "nil" then


				if SelectClothes == "Breast Clothes SB1" or SelectClothes == "Breast Clothes SB2" then

					if DataDetail.BreastsType ~= 6 then continue end
					local _bcPath = (SelectClothes == "Breast Clothes SB1")
						and "RClothesContent/_vns/model/breastclothes/1/model.rbxm"
						or  "RClothesContent/_vns/model/breastclothes/2/model.rbxm"
					local _root, _parts = Function.RigVnsModel(_bcPath, Character, RequestID, nil, Data)


					if not _root then
						for _try = 1, 3 do
							task.wait(0.5)
							if _bailIfStale() then return end
							_root, _parts = Function.RigVnsModel(_bcPath, Character, RequestID, nil, Data)
							if _root then break end
						end
						if not _root then warn("[RoClothes] " .. SelectClothes .. ": the bra mesh failed to load after 3 retries - breasts stay uncovered. Re-wear the bundle.") end
					end
					if _root then
						local _cmap = DataDetail.CurrentPartList["Clothes"]



						local _rcBreast = Character:FindFirstChild("RC_VNS_breast")
						if _rcBreast then
							for _, _c in ipairs(_rcBreast:GetChildren()) do
								if _c.Name == "BreastClothes" then _c:Destroy() end
							end
						end

						for _, _other in ipairs({"Breast Clothes SB1","Breast Clothes SB2"}) do
							if _other ~= SelectClothes then _cmap[_other] = nil end
						end
						local _braMP = _root:FindFirstChild("BreastClothes", true)
						if _braMP and _braMP:IsA("MeshPart") and _rcBreast then
							_braMP.Parent = _rcBreast
							_cmap[SelectClothes] = _braMP


							local _braFPBase = Character:FindFirstChild("Torso") or Character:FindFirstChild("UpperTorso")
							local _rul = DataDetail.CurrentPartList.RealtimeUpdateList
							if _braFPBase and _rul and _rul.Mesh then _rul.Mesh[_braMP] = { Base = _braFPBase, FPOnly = true } end
						else
							_cmap[SelectClothes] = _root
						end

						if _braMP and _braMP:IsA("MeshPart") and _hasShirtToggle and Extra.Shirt and Extra.Shirt.ShirtTemplate then
							local _braPaintMode = _setOrCreateSA(_braMP, Extra.Shirt.ShirtTemplate, Enum.AlphaMode.Transparency, "RoClothesShirt")
							_braMP.Transparency = (_braPaintMode == "tex") and 0.011 or 0
						end


					end
					continue
				end

				local function weldClothes(w)


					local ClothesPartMap = DataDetail.CurrentPartList["Clothes"]
					local recolorEntry = DataDetail.ClothesRecolor[SelectClothes]
					local _noAnchor = {}


					for _pass = 1, 2 do
					for i, v in pairs(w) do
						if ClothesPartMap[v] then continue end
						if _bailIfStale() then return end
						local partMeta = PartListData[v]
						if not partMeta then
							warn("[RoClothes] Missing PartList entry for clothing part:", v, "- skipping")
							continue
						end
						Function._weldChainMiss = false
						local ClothesPart = Function.Weld(partMeta, Character, Extra, Data, RequestID)
						if not ClothesPart and Function._weldChainMiss then _noAnchor[v] = true end
						if ClothesPart then
							ClothesPartMap[v] = ClothesPart
							if recolorEntry and partMeta.Recolor then
								local slot = partMeta.Recolor
								if slot == "Primary" then
									if typeof(recolorEntry.Primary) == "Color3" then
										ClothesPart.Color = recolorEntry.Primary
									end
								elseif slot == "Secondary" then
									if typeof(recolorEntry.Secondary) == "Color3" then
										ClothesPart.Color = recolorEntry.Secondary
									end
								elseif slot == "Tertiary" then
									if typeof(recolorEntry.Tertiary) == "Color3" then
										ClothesPart.Color = recolorEntry.Tertiary
									end
								end
							end
						else

							if _bailIfStale() then return end

						end
					end
					end
					local _miss, _total = 0, 0
					for _, v in pairs(w) do _total += 1; if _noAnchor[v] and not ClothesPartMap[v] then _miss += 1 end end
					if _miss > 0 and Data == Player.Name and Function._warnUnattached then Function._warnUnattached(SelectClothes, _miss, _total, DataDetail) end
				end

				if Clothes[SelectClothes] and Clothes[SelectClothes]["Weld"] then
					if Clothes[SelectClothes].Alternative and Clothes[SelectClothes].Alternative.Condition then
						local _condFn = Function[Clothes[SelectClothes].Alternative.Condition]
						local a = false
						if _condFn then local _ok, _r = pcall(_condFn, Data); if _ok then a = _r end end
						if a and a == true then
							weldClothes(Clothes[SelectClothes].Alternative["Weld"])
						else
							weldClothes(Clothes[SelectClothes]["Weld"])
						end
					else
						local metCondition = false
						if Clothes[SelectClothes].Alternative then
							for i, alts in ipairs(Clothes[SelectClothes].Alternative) do
								if metCondition == false then
									local _altFn = alts.Condition and Function[alts.Condition]
									local a = false
									if _altFn then local _ok, _r = pcall(_altFn, Data); if _ok then a = _r end end
									if a and a == true then
										metCondition = true
										weldClothes(alts["Weld"])
									end
								end
							end
						end
						if metCondition == false then
							weldClothes(Clothes[SelectClothes]["Weld"])
						end
					end
				end

				if Clothes[SelectClothes] and Clothes[SelectClothes]["Unvisible"] ~= nil then
					for i, v in pairs(Clothes[SelectClothes]["Unvisible"]) do
						local UnvisiblePart = DataDetail.CurrentPartList["Organ"][v]

						if UnvisiblePart then

							UnvisiblePart:SetAttribute("MaxTransparencyRC", 1)
							UnvisiblePart.Transparency = 1
						elseif string.find(string.lower(v),"areola") then
							for areola, parent in pairs(DataDetail.CurrentPartList["AreolaDecal"]) do

								if parent and (
									(string.find(string.lower(v),"left")  and string.find(string.lower(parent.Name),"left"))
									or (string.find(string.lower(v),"right") and string.find(string.lower(parent.Name),"right"))
								) then


									if areola:IsA("Decal") then
										areola.Transparency = 1
									elseif areola:IsA("SurfaceAppearance") then

										areola:Destroy()
										DataDetail.CurrentPartList["AreolaDecal"][areola] = nil
									end
								end
							end
						end
					end
				end


				if Clothes[SelectClothes] and Clothes[SelectClothes].KrulHosted then
					local cDef = Clothes[SelectClothes]
					local okA, assetUrl = pcall(System.getcustomasset, cDef.LocalPath)
					if okA and type(assetUrl) == "string" and #assetUrl > 5 then
						local organs = DataDetail.CurrentPartList["Organ"]
					local resolvedType = _krulClothTypes[SelectClothes] or cDef.ClothType
					local function applyKrulTex(meshPart, preserveAlpha)
						if not meshPart or not meshPart:IsA("MeshPart") then return end
						if meshPart:GetAttribute("RCClothingLayer") then return end
						local existing = meshPart:FindFirstChildOfClass("SurfaceAppearance")
						if existing and existing:GetAttribute("KrulHosted") then existing:Destroy() end
						local sa = Instance.new("SurfaceAppearance")
						sa:SetAttribute("KrulHosted", true)
						local marker = resolvedType == "Shirt" and "RoClothesShirt" or "RoClothesPants"
						sa:SetAttribute(marker, true)

						local okCM = System._saCMW ~= false and pcall(function() sa.ColorMap = assetUrl end)
						System._saCMW = okCM and true or false
						if preserveAlpha and okCM then sa.AlphaMode = Enum.AlphaMode.Transparency end
						local ok2 = okCM and pcall(function() sa.Parent = meshPart end)
						if not ok2 then
							sa:Destroy()
							if not okCM then
								local mode = _setOrCreateSA(meshPart, assetUrl, preserveAlpha and Enum.AlphaMode.Transparency or Enum.AlphaMode.Overlay, marker)
								local painted = mode == "layer" and meshPart:FindFirstChild("RCClothingTextureLayer")
									or mode == "sa" and meshPart:FindFirstChildOfClass("SurfaceAppearance") or meshPart
								if painted then painted:SetAttribute("KrulHosted", true) end
							else
								local sm = meshPart:FindFirstChildOfClass("SpecialMesh")
								if not sm then sm = Instance.new("SpecialMesh", meshPart) end
								sm:SetAttribute("KrulHosted", true)
								sm:SetAttribute(marker, true)
								if sm:GetAttribute("_RC_ClothingBaseTexture") == nil then
									sm:SetAttribute("_RC_ClothingBaseTexture", sm.TextureId)
								end
								pcall(function() sm.TextureId = assetUrl end)
							end
						end
						if preserveAlpha then meshPart.Transparency = ok2 and 0 or 0.011 end

						for _, child in ipairs(meshPart:GetChildren()) do
							if child:IsA("MeshPart") then applyKrulTex(child, preserveAlpha) end
						end
					end




					if resolvedType == "Shirt" then
						for _, n in ipairs({"Left Arm","Right Arm"}) do
							applyKrulTex(organs and organs[n])
						end
						local clothesParts = DataDetail.CurrentPartList["Clothes"]
						if clothesParts then
							for _, n in ipairs({"Torso Shirt","Breasts Shirt","Breasts Shirt 2","Breasts Shirt 3"}) do
								local mp = clothesParts[n]
								if typeof(mp) == "Instance" then
									if mp:IsA("MeshPart") then
										applyKrulTex(mp)
									else
										for _, _d in ipairs(mp:GetDescendants()) do
											if _d:IsA("MeshPart") then applyKrulTex(_d) end
										end
									end
								end
							end


							for _, n in ipairs({ "Breast Clothes SB1", "Breast Clothes SB2" }) do
								local mp = clothesParts[n]
								if typeof(mp) == "Instance" then
									if mp:IsA("MeshPart") then
										applyKrulTex(mp, true)
									else
										for _, _d in ipairs(mp:GetDescendants()) do
											if _d:IsA("MeshPart") then applyKrulTex(_d, true) end
										end
									end
								end
							end
						end

						if not (clothesParts and clothesParts["Torso Shirt"]) then
							applyKrulTex(organs and organs["Torso"])
						end
					else
						for _, n in ipairs({"Torso","Left Leg","Right Leg","Left Butt","Right Butt","Breasts Pants","Breasts Pants 2","Breasts Pants 3"}) do
							applyKrulTex(organs and organs[n])
						end

						local _bpClothes = DataDetail.CurrentPartList["Clothes"]
						if _bpClothes then
							for _, n in ipairs({"Breasts Pants","Breasts Pants 2","Breasts Pants 3"}) do
								local mp = _bpClothes[n]
								if typeof(mp) == "Instance" and mp:IsA("MeshPart") then applyKrulTex(mp) end
							end
						end
					end
					end
				end
			end
		end
		if _bailIfStale() then return end
		return true
	end



	function Function._ceClothingPass2AndHP(Character, Data, RequestID, DataDetail, Extra, PartListData, _bailIfStale, _cdTok)





		do
			local ClothesPartMap = DataDetail.CurrentPartList["Clothes"]
			for _, SelectClothes in ipairs(DataDetail.CurrentClothes) do
				if _bailIfStale() then return end
				if SelectClothes == "nil" then continue end

				if SelectClothes == "Breast Clothes SB1" or SelectClothes == "Breast Clothes SB2" then continue end
				local cDef = Clothes[SelectClothes]
				if not cDef or not cDef["Weld"] then continue end

				local weldList = cDef["Weld"]
				if cDef.Alternative then
					if cDef.Alternative.Condition then
						local _fn = Function[cDef.Alternative.Condition]
						local _r2 = false
						if _fn then local _ok, _rv = pcall(_fn, Data); if _ok then _r2 = _rv end end
						if _r2 == true then weldList = cDef.Alternative["Weld"] end
					else
						for _, alts in pairs(cDef.Alternative) do
							if alts.Condition then
								local _fn = Function[alts.Condition]
								local _r2 = false
								if _fn then local _ok, _rv = pcall(_fn, Data); if _ok then _r2 = _rv end end
								if _r2 == true then weldList = alts["Weld"]; break end
							end
						end
					end
				end
				if not weldList then continue end
				local hasMissing = false
				for _, v in pairs(weldList) do
					if not ClothesPartMap[v] and PartListData[v] then hasMissing = true; break end
				end
				if hasMissing then
					for _, v in pairs(weldList) do
						if ClothesPartMap[v] or not PartListData[v] then continue end
						if _bailIfStale() then return end
						local ClothesPart = Function.Weld(PartListData[v], Character, Extra, Data, RequestID)
						if ClothesPart then ClothesPartMap[v] = ClothesPart end
					end
				end
			end
		end

		local function transparent(o,v)
			if v >= 1 and o.Material == Enum.Material.Glass then
				o:AddTag("RCGlassMat")
				o.Material = Enum.Material.Neon
			elseif v < 1 and o.Material == Enum.Material.Neon and o:HasTag("RCGlassMat") then
				o:RemoveTag("RCGlassMat")
				o.Material = Enum.Material.Glass
			end
			o:SetAttribute("MaxTransparencyRC",v)
			o.Transparency = v
		end

		local function processHPClothes(hpType)
			local clothesPartMap = DataDetail.CurrentPartList["Clothes"]
			local organMap = DataDetail.CurrentPartList["Organ"]
			for c, set in pairs(DataDetail.ClothesHP) do
				if set["HP"] ~= hpType then continue end
				if not table.find(DataDetail.CurrentClothes,c) then continue end
				local clothesC = Clothes[c]
				if not clothesC then continue end
				local w = clothesC.Weld or {}
				if clothesC.Alternative and clothesC.Alternative.Condition then
					local _hpCondFn = Function[clothesC.Alternative.Condition]
					local a = false
					if _hpCondFn then local _ok, _rv = pcall(_hpCondFn, Data); if _ok then a = _rv end end
					if a == true then
						w = clothesC.Alternative.Weld
					end
				elseif clothesC.Alternative then
					local metCondition = false
					for i, alts in ipairs(clothesC.Alternative) do
						if metCondition == false then
							local _hpAltFn = alts.Condition and Function[alts.Condition]
							local a = false
							if _hpAltFn then local _ok, _r = pcall(_hpAltFn, Data); if _ok then a = _r end end
							if a == true then
								metCondition = true
								w = alts["Weld"]
							end
						end
					end
				end
				local inverse = (set["Inverse"] == true)
				local hpFlag = not inverse
				for i, v in pairs(w or {}) do
					local cp = clothesPartMap[v]
					if cp then
						if inverse then
							transparent(cp, 1)
						else
							local t = cp:GetAttribute("Alpha") or 0
							transparent(cp, t)
						end
					end
				end
				if clothesC.Unvisible then
					for i, v in pairs(clothesC.Unvisible) do
						local op = organMap[v]
						if op then
							if inverse then
								local t = op:GetAttribute("Alpha") or 0
								transparent(op, t)
							else
								transparent(op, 1)
							end
						end
					end
				end
				if clothesC.HPFunction then
					local hpFn = clothesC.HPFunction
					if typeof(hpFn) == "string" then
						if Function[hpFn] then pcall(Function[hpFn], hpFlag,Character,Data,c) end
					elseif typeof(hpFn) == "table" then
						for i, v in pairs(hpFn) do
							if Function[v] then pcall(Function[v], hpFlag,Character,Data,c) end
						end
					end
				end
			end
		end
		if DataDetail.TopHP ~= "" then
			processHPClothes("TopHP")
		end
		if DataDetail.BottomHP ~= "" then
			processHPClothes("BottomHP")
		end

		Function.ClothesOffClearRip(DataDetail)
		DataDetail._lastH = nil


		local FaceDecal = Character and Character:FindFirstChildWhichIsA("Decal", true)
		if FaceDecal and DataDetail.Face == false then
			FaceDecal.Transparency = 1
			DataDetail.CurrentPartList.ParentTransparency[FaceDecal] = {D = 0, T = 1}
		end
		if System.Community and Data ~= "_rc_bundle_preview" then pcall(System.Community.afterBuildPD, DataDetail, Character) end
		task.wait()
		Function._cdFree(DataDetail, _cdTok)
		return true
	end

local _sanitizeClothesRecolor, _sanitizeGizmoOffsets, _validatePresetValue; do local M = _RCR.need("engine/character_connection", { Clothes = Clothes, Function = Function, GlobalMaid = GlobalMaid, MaxArmType = MaxArmType, MaxBreastsType = MaxBreastsType, MaxButtType = MaxButtType, MaxLegsType = MaxLegsType, MaxTorsoType = MaxTorsoType, Player = Player, PlayerData = PlayerData, System = System, _PEER_ALLOWED_PRESET_KEYS = _PEER_ALLOWED_PRESET_KEYS }); _sanitizeClothesRecolor, _sanitizeGizmoOffsets, _validatePresetValue = M._sanitizeClothesRecolor, M._sanitizeGizmoOffsets, M._validatePresetValue end
