System.StaffThemes.TAGS.ninelives = function(K, head, C1, C2)
	local W = Color3.new(1, 1, 1)
	local BROWN, PINK = Color3.fromRGB(95, 58, 32), Color3.fromRGB(255, 170, 185)
	local NS, NK, CS, NR = NumberSequence.new, NumberSequenceKeypoint.new, ColorSequence.new, NumberRange.new
	local function c01(x) return math.clamp(x, 0, 1) end
	local function outB(x) x = c01(x) local c = 1.7 return 1 + (c + 1) * (x - 1) ^ 3 + c * (x - 1) ^ 2 end
	local function L_outB(x) return math.min(outB(x), 1) end
	local FONT = Font.new("rbxasset://fonts/families/FredokaOne.json", Enum.FontWeight.Regular)
	local ch = System.StaffThemes._tagCh or {}
	local Wd, Hd = 7, 3.8
	local bb = K.board(head, Wd, Hd, 3.8)
	bb:SetAttribute("RCBadgeTop", 0.55)
	local DY = 0.58

	local PY, PH, PW = 1.75, 1.25, 5.8
	local plate = K.frame(bb, { BackgroundTransparency = 0, BackgroundColor3 = C2, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, PY / Hd),
		Size = UDim2.fromScale(PW / Wd, PH / Hd), ZIndex = 4 })
	K.new("UICorner", { CornerRadius = UDim.new(0.5, 0) }, plate)
	local pst = K.new("UIStroke", { Color = C1, Thickness = 2.5, ApplyStrokeMode = Enum.ApplyStrokeMode.Border }, plate)
	local nm = K.text(plate, { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromScale(0.86, 0.62),
		Text = "NINE LIVES", FontFace = FONT, TextColor3 = BROWN, ZIndex = 5 })


	nm.Visible = false
	local BASE = "NINE LIVES"
	local NL = #BASE


	local lgrp = K.new("CanvasGroup", { BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), ZIndex = 5 }, plate)
	local GL, EMx = {}, { en = ch.sEmoteN or 0, beat = ch.sBeat or 0, bk = 0, bt = 0, roll = -1 }
	for i = 1, NL do
		local g = { c = BASE:sub(i, i), fl = -1 }
		g.l = K.text(lgrp, { AnchorPoint = Vector2.new(0.5, 0.5), Text = g.c, FontFace = FONT, TextColor3 = BROWN, ZIndex = 5, TextTransparency = 1 })
		K.new("UIGradient", { Rotation = 90, Color = CS(BROWN:Lerp(W, 0.12), BROWN:Lerp(Color3.new(0, 0, 0), 0.2)) }, g.l)
		GL[i] = g
	end
	local function padP(str)
		str = str:sub(1, NL)
		local l = math.floor((NL - #str) / 2)
		return string.rep(" ", l) .. str .. string.rep(" ", NL - #str - l)
	end

	local UW = math.clamp(#K.NAME * 0.26 + 0.9, 2.2, 5.6)
	local sub = K.frame(bb, { BackgroundTransparency = 1, BackgroundColor3 = BROWN, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, (PY + PH / 2 + 0.3) / Hd),
		Size = UDim2.fromScale(UW / Wd, 0.5 / Hd), ZIndex = 5 })
	K.new("UICorner", { CornerRadius = UDim.new(0.5, 0) }, sub)
	local subT = K.text(sub, { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromScale(0.86, 0.66), Text = K.NAME,
		FontFace = Font.new("rbxasset://fonts/families/Nunito.json", Enum.FontWeight.ExtraBold), TextColor3 = C2:Lerp(W, 0.4), ZIndex = 6, TextTransparency = 1 })

	local ears = {}
	for i, x in ipairs({ 1.55, 5.45 }) do
		local holder = K.frame(bb, { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(x / Wd, (PY - PH / 2 + 0.08) / Hd), Size = UDim2.fromScale(0.01, 0.01), ZIndex = 2 })
		local outer = K.frame(holder, { BackgroundTransparency = 0, BackgroundColor3 = C1, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), ZIndex = 2 })
		local inner = K.frame(holder, { BackgroundTransparency = 0, BackgroundColor3 = PINK, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), ZIndex = 3 })
		K.new("UICorner", { CornerRadius = UDim.new(0.12, 0) }, outer)
		ears[i] = { holder = holder, outer = outer, inner = inner, side = i == 1 and -1 or 1, tw = 0, next = 2 + math.random() * 4 }
	end

	local whk = {}
	for _, side in ipairs({ -1, 1 }) do
		for j = -1, 1 do
			whk[#whk + 1] = { f = K.frame(bb, { BackgroundTransparency = 1, BackgroundColor3 = BROWN, AnchorPoint = Vector2.new(0.5, 0.5), ZIndex = 3 }), side = side, j = j }
		end
	end

	local tail = {}
	for j = 1, 8 do tail[j] = K.frame(bb, { BackgroundTransparency = 0, BackgroundColor3 = C1, AnchorPoint = Vector2.new(0.5, 0.5), ZIndex = 3 }) K.new("UICorner", { CornerRadius = UDim.new(0.5, 0) }, tail[j]) end

	local function paw(parent, col, z)
		local g = K.new("CanvasGroup", { BackgroundTransparency = 1, AnchorPoint = Vector2.new(0.5, 0.5), ZIndex = z, GroupTransparency = 1 }, parent)
		local function dot(x, y, w, h)
			local d = K.frame(g, { BackgroundTransparency = 0, BackgroundColor3 = col, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(x, y), Size = UDim2.fromScale(w, h), ZIndex = z })
			K.new("UICorner", { CornerRadius = UDim.new(0.5, 0) }, d)
		end
		dot(0.5, 0.68, 0.5, 0.4) dot(0.2, 0.36, 0.2, 0.24) dot(0.4, 0.2, 0.2, 0.24) dot(0.6, 0.2, 0.2, 0.24) dot(0.8, 0.36, 0.2, 0.24)
		return g
	end
	local motes = {}
	for i = 1, 3 do motes[i] = { g = paw(bb, i == 2 and C2 or C1, 6), t0 = i * 1.3 } end

	K.emitterAt(Vector3.new(0, 3.9, 0), { Texture = K.T("star.png"), Rate = 2, Lifetime = NR(0.8, 1.3), Speed = NR(0.1, 0.4), SpreadAngle = Vector2.new(180, 180),
		Size = NS({ NK(0, 0), NK(0.5, 0.22), NK(1, 0) }), Color = CS(C2, C1), box = Vector3.new(5, 1.2, 0.3) })
	local function at(x, y, w, h) return UDim2.fromScale(x / Wd, y / Hd), UDim2.fromScale(w / Wd, (h or w) / Hd) end


	local pips = {}
	for i = 1, 9 do pips[i] = { g = paw(bb, C1, 6), x = 2.1 + (i - 1) * 0.3, fly = 0 } end
	local plus = K.text(bb, { AnchorPoint = Vector2.new(0.5, 0.5), Text = "+9", FontFace = FONT, TextColor3 = C1, TextTransparency = 1, ZIndex = 7 })
	local pst2 = K.new("UIStroke", { Color = BROWN, Thickness = 1.5, Transparency = 1 }, plus)
	local lastL, waveT = nil, nil


	local downK, wasDown, perk, wrapK = 0, false, nil, 0
	local downV = 0


	local stK = { walk = 0, jump = 0, emote = 0 }

	local RED = Color3.fromRGB(255, 70, 80)
	local warnG = K.img(bb, { Image = K.T("glowui.png"), ImageColor3 = RED, ImageTransparency = 1, AnchorPoint = Vector2.new(0.5, 0.5), ZIndex = 5 })
	local warnOn = false
	return function(t, dt, it)
		local lv = math.clamp(tonumber(K.bb:GetAttribute("NLLives")) or 9, 0, 9)
		if lastL and lv < lastL then for i = lv + 1, lastL do pips[i].fly = 1 end end
		if lastL and lv > lastL then waveT = 0 end
		lastL = lv
		local down = K.bb:GetAttribute("NLDown") == true
		local sdt = math.min(dt, 1 / 30)
		downV += (((down and 1 or 0) - downK) * 110 - downV * 13) * sdt
		downK = math.clamp(downK + downV * sdt, -0.15, 1.1)
		if wasDown and not down then perk = 0 end
		wasDown = down
		if perk then perk += dt if perk > 0.5 then perk = nil end end
		wrapK += (((lv == 1) and 1 or 0) - wrapK) * math.min(1, dt * 3)
		local st = K.bb:GetAttribute("NLState") or "idle"
		for k in pairs(stK) do stK[k] += (((st == k) and 1 or 0) - stK[k]) * math.min(1, dt * 6) end
		local idleK = math.max(0, 1 - stK.walk - stK.jump - stK.emote)
		local hop = stK.jump * 0.28 + stK.emote * (0.5 - 0.5 * math.cos(t * 14)) * 0.16
		plate.Position = UDim2.fromScale(0.5, (PY - hop) / Hd)
		plate.Rotation = stK.emote * math.sin(t * 3.5) * 6
		if waveT then waveT += dt if waveT > 2 then waveT = nil end end
		for i, p in ipairs(pips) do
			local intro = c01((it - 0.5 - i * 0.04) / 0.2)
			local y, sz, a = 2.72 + DY, 0.26, (i <= lv) and 1 or 0.22
			if p.fly > 0 then
				p.fly = math.max(0, p.fly - dt * 0.8)
				local k = 1 - p.fly
				y, sz, a = y - (1 - (1 - k) ^ 2) * 1.1, sz * (1 + 0.6 * k), 1 - k * k
				p.fx = p.x + math.sin(k * math.pi * 0.5) * 0.35
				p.fr = k * 120
			else p.fx, p.fr = nil, nil end
			if waveT then
				local w = waveT - (i - 1) * 0.07
				if w > 0 and w < 0.4 then sz *= 1 + 0.7 * math.sin(w / 0.4 * math.pi) end
				if w < 0.12 and a > 0.22 then a = 0.22 + (a - 0.22) * c01(w / 0.12) end
			end
			if i == 1 then
				local w = lv == 1
				if w ~= warnOn then
					warnOn = w
					for _, d in ipairs(p.g:GetChildren()) do if d:IsA("Frame") then d.BackgroundColor3 = w and RED or C1 end end
				end
				local pu = 0.5 + 0.5 * math.sin(t * 4.5)
				if w then sz *= 1 + 0.14 * pu end
				warnG.Position, warnG.Size = at(p.x, y, 0.9)
				warnG.ImageTransparency = w and 1 - (0.35 + 0.3 * pu) * intro or 1
			end
			p.g.Position, p.g.Size = at(p.fx or p.x, y, sz)
			p.g.Rotation = -10 + (i % 2) * 20 + (p.fr or 0)
			p.g.GroupTransparency = 1 - a * intro
		end
		local pk = waveT and c01(waveT / 0.15) * (1 - c01((waveT - 1.2) / 0.6)) or 0
		plus.Position, plus.Size = at(5.75, 2.7 + DY - (waveT or 0) * 0.35, 0.9, 0.5)
		plus.TextTransparency, pst2.Transparency = 1 - pk, 1 - pk
		local pa = c01((it - 0.05) / 0.3)
		plate.BackgroundTransparency, pst.Transparency = 1 - pa, 1 - pa
		nm.TextTransparency = 1 - pa
		if (ch.sEmoteN or 0) ~= EMx.en then EMx.en, EMx.roll = ch.sEmoteN or 0, 0 end
		if (ch.sBeat or 0) ~= EMx.beat then EMx.beat, EMx.bk, EMx.bt = ch.sBeat or 0, 1, 0 end
		EMx.bk = math.max(0, EMx.bk - dt * 3)
		EMx.bt += dt
		if EMx.roll >= 0 then EMx.roll += dt if EMx.roll > 1.2 then EMx.roll = -1 end end
		local want = ch.sPhrase and padP(ch.sPhrase) or BASE
		for i, g in ipairs(GL) do
			local wc = want:sub(i, i)
			if g.fl == -1 and wc ~= g.c then g.fl = -(i - 1) * 0.045 - 0.0001 g.to = wc end
			local sy = 1
			if g.fl ~= -1 then
				g.fl += dt
				if g.fl >= 0 then
					local f = g.fl / 0.22
					if f >= 0.5 and g.c ~= g.to then g.c = g.to g.l.Text = g.c end
					sy = math.abs(math.cos(math.min(f, 1) * math.pi))
					if f >= 1 then g.fl = -1 end
				end
			end
			local lIn = c01((it - 0.1 - i * 0.05) / 0.25)
			local pop = 1 + 0.4 * math.sin(lIn * math.pi)
			local wv = math.sin(c01(EMx.bt * 3 - (i - 1) * 0.08) * math.pi) * EMx.bk
			local idle = 0
			g.l.Position = UDim2.fromScale(0.07 + (i - 0.5) * 0.86 / NL, 0.5 - 0.2 * wv + idle)
			g.l.Size = UDim2.fromScale(0.86 / NL * pop * 1.15, 0.62 * pop * sy * (1 + 0.15 * wv))
			g.l.Rotation = (EMx.roll >= 0 and 360 * L_outB(c01((EMx.roll - i * 0.05) / 0.6)) or 0) + 6 * wv * ((i % 2 == 0) and 1 or -1)
			g.l.TextTransparency = 1 - lIn * pa
		end
		local ua = c01((it - 0.3) / 0.3)
		subT.TextTransparency = 1 - ua
		sub.BackgroundTransparency = 1 - 0.9 * ua
		sub.Position = UDim2.fromScale(0.5, (PY + PH / 2 + 0.3 - hop * 0.6) / Hd)

		for i, e in ipairs(ears) do
			local pop = outB((it - 0.25 - i * 0.12) / 0.35)
			e.next -= dt
			if e.next <= 0 then e.next = 2.5 + math.random() * 5 e.tw = 0.35 end
			e.tw = math.max(0, e.tw - dt)
			local tw = e.tw > 0 and math.sin((0.35 - e.tw) / 0.35 * math.pi * 3) * 14 or 0
			local s = 0.95 * pop * (1 - 0.3 * downK) * (1 + 0.25 * stK.jump) * (perk and 1 + 0.35 * math.sin(perk / 0.5 * math.pi) or 1)
			e.holder.Rotation = e.side * (12 + 75 * downK) + tw * (1 - downK)
			e.holder.Position = UDim2.fromScale(e.holder.Position.X.Scale, (PY - PH / 2 + 0.08 - hop) / Hd)
			e.outer.Size = UDim2.fromScale(s / 0.01 / Wd, s / 0.01 / Hd)
			e.inner.Size = UDim2.fromScale(s * 0.55 / 0.01 / Wd, s * 0.55 / 0.01 / Hd)
			e.outer.Rotation, e.inner.Rotation = 45, 45
			e.inner.Position = UDim2.fromScale(0.5, 0.5 + 0.1 * s / 0.01 / Hd)
			e.outer.Visible, e.inner.Visible = pop > 0.01, pop > 0.01
		end

		for _, w in ipairs(whk) do
			local e = ears[w.side < 0 and 1 or 2]
			local tw = e.tw > 0 and math.sin((0.35 - e.tw) / 0.35 * math.pi * 4) * 5 or 0


			local ang = w.j * 13 + 14 * downK + tw
			local len = 1.15 - 0.1 * math.abs(w.j)
			local r = math.rad(ang)
			local ox, oy = 3.5 + w.side * (PW / 2 - 0.35), PY - hop + 0.16
			w.f.Position, w.f.Size = at(ox + w.side * math.cos(r) * len / 2, oy + math.sin(r) * len / 2, len, 0.05)
			w.f.Rotation = w.side * ang
			w.f.BackgroundTransparency = 1 - 0.7 * pa
		end


		EMx.tph = (EMx.tph or 0) + dt * (1.8 + 5 * stK.walk)
		local sw = math.sin(EMx.tph) * (0.5 + 0.3 * stK.walk)
		for j, d in ipairs(tail) do
			local u = (j - 1) / (#tail - 1)
			local ang = -0.3 + u * (2.6 + sw)
			local r = 0.55 * (1 - 0.35 * u)
			local x = 4.9 + 0.4 * u + math.cos(ang) * r * u * 1.6
			local y = PY + PH / 2 + 0.05 + math.sin(ang) * r * u * 1.2 + 0.25 * u
			if wrapK > 0.001 then
				local wx = 4.9 - u * 3.1
				local wy = 3.0 + DY - c01((u - 0.8) / 0.2) * 0.45 + math.sin(t * 2 + u * 4) * 0.02
				x, y = x + (wx - x) * wrapK, y + (wy - y) * wrapK
			end
			d.Position, d.Size = at(x, y, 0.2 - 0.07 * u)
			d.BackgroundTransparency = 1 - pa * c01((it - 0.4 - u * 0.3) / 0.2)
		end
		for i, m in ipairs(motes) do
			local per = 3.9 - 2.2 * stK.walk
			m.ph = ((m.ph or m.t0 / 3.9) + dt / per) % 1
			local a = m.ph
			if not m.x or a < (m.la or 0) then m.x, m.y = (i == 2) and 5.6 + math.random() * 0.8 or (i == 1 and 0.4 or 6.4), 0.3 + math.random() * 0.6 end
			m.la = a
			local x, y = m.x, m.y - a * 0.4
			m.g.Position, m.g.Size = at(x, y, 0.42)
			m.g.Rotation = -20 + i * 15
			m.g.GroupTransparency = 1 - math.sin(a * math.pi) * 0.75 * pa
		end
	end
end

System.StaffThemes.THEMES.ninelives = function(L, C)
	local C1, C2, W = C.c1, C.c2, L.W
	local NS, CS, NR, K = L.NS, L.CS, L.NR, L.K
	local ch, rnd, c01 = L.ch, L.rnd, L.c01
	local SMOOTH, BLK = Enum.Material.SmoothPlastic, Color3.fromRGB(16, 14, 18)
	local V3, CF, A = Vector3.new, CFrame.new, CFrame.Angles
	local function rgb(r, g, b) return Color3.fromRGB(r, g, b) end
	local function ss(x) x = c01(x) return x * x * (3 - 2 * x) end
	local PINK = rgb(255, 160, 178)


	local KINDS = {
		tabby = { col = rgb(236, 140, 62), belly = rgb(252, 222, 180), muz = rgb(252, 228, 196), paw = rgb(252, 222, 180), stripe = rgb(186, 88, 30), eye = rgb(130, 205, 80) },
		black = { col = rgb(34, 32, 38), eye = rgb(245, 200, 60), ein = rgb(110, 70, 80), wh = rgb(150, 150, 150), nose = rgb(70, 50, 56) },
		white = { col = rgb(246, 244, 240), belly = rgb(252, 251, 248), eye = rgb(100, 170, 245), wh = rgb(205, 205, 210) },
		grey = { col = rgb(130, 132, 142), belly = rgb(182, 184, 192), muz = rgb(196, 196, 204), paw = rgb(170, 170, 180), stripe = rgb(98, 100, 110), eye = rgb(215, 195, 70) },
		calico = { col = rgb(248, 244, 236), patch1 = rgb(232, 138, 56), patch2 = rgb(44, 40, 44), headPatch = rgb(232, 138, 56), tail = rgb(232, 138, 56), eye = rgb(215, 160, 55) },
		tuxedo = { col = rgb(30, 30, 36), belly = rgb(246, 244, 240), muz = rgb(246, 244, 240), paw = rgb(246, 244, 240), bib = rgb(246, 244, 240), eye = rgb(150, 215, 90),
			ein = rgb(120, 80, 90), nose = rgb(230, 150, 160) },
		siamese = { col = rgb(238, 226, 204), belly = rgb(246, 238, 224), muz = rgb(92, 64, 52), paw = rgb(92, 64, 52), ear = rgb(92, 64, 52), tail = rgb(110, 80, 64),
			tip = rgb(80, 56, 46), eye = rgb(80, 150, 245), nose = rgb(70, 48, 40) },
		brown = { col = rgb(142, 104, 70), belly = rgb(206, 180, 142), muz = rgb(214, 192, 158), paw = rgb(200, 174, 138), stripe = rgb(66, 46, 32), eye = rgb(160, 205, 80) },
		blue = { col = rgb(112, 124, 142), eye = rgb(95, 205, 115), nose = rgb(90, 96, 110), ein = rgb(170, 140, 160) },
	}
	local ORDER = { "tabby", "black", "white", "grey", "calico", "tuxedo", "siamese", "brown", "blue" }
	local CARD = rgb(176, 130, 84)
	local okM, BOXMAT = pcall(function() return Enum.Material.Cardboard end) if not okM then BOXMAT = SMOOTH end
	local MEOWS = { "meow", "mrrp", "mew", "nya", "mrow" }
	local function sc() return ch.sc or 1 end
	local function yawCF(p, yaw) return CF(p) * A(0, yaw, 0) end
	local function flatYaw(v) return math.atan2(-v.X, -v.Z) end
	local function bulk(parts, cfs)
		if not pcall(workspace.BulkMoveTo, workspace, parts, cfs, Enum.BulkMoveMode.FireCFrameChanged) then
			for i, p in ipairs(parts) do p.CFrame = cfs[i] end
		end
	end


	L.cine.ninelives = { font = L.fam("FredokaOne", Enum.FontWeight.Regular), sub = L.fam("FredokaOne", Enum.FontWeight.Regular), kick = "N I N E   L I V E S",
		subText = "H A S   A R R I V E D", stroke = rgb(95, 58, 32), grad = function(c1, c2) return CS(c2, c1) end,
		card = function(Cd)
			local NP = 10
			local ps = {}
			for i = 1, NP do
				local g = L.new("CanvasGroup", { BackgroundTransparency = 1, AnchorPoint = Vector2.new(0.5, 0.5), GroupTransparency = 1, ZIndex = 5, Rotation = 90 }, Cd.card)
				for _, d in ipairs({ { 0.5, 0.66, 0.46, 0.38 }, { 0.2, 0.36, 0.18, 0.22 }, { 0.4, 0.2, 0.18, 0.22 }, { 0.6, 0.2, 0.18, 0.22 }, { 0.8, 0.36, 0.18, 0.22 } }) do
					local f = L.new("Frame", { BorderSizePixel = 0, BackgroundColor3 = i % 2 == 0 and Cd.c2 or Cd.c1, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(d[1], d[2]),
						Size = UDim2.fromScale(d[3], d[4]), ZIndex = 5 }, g)
					L.new("UICorner", { CornerRadius = UDim.new(0.5, 0) }, f)
				end
				ps[i] = g
			end
			local DROP = 0.42
			return function(tt, a, out)
				local V = L.vp()
				local px = math.floor(0.05 * V.Y)
				for i, g in ipairs(ps) do
					local t0 = (i - 1) * 0.065 + ((i % 2 == 0) and 0.018 or 0)
					local k = tt - t0
					local pop = k > 0 and 1.4 - 0.4 * L.outBack(k / 0.16) or 0
					g.Size = UDim2.fromOffset(px * pop, px * pop)
					g.Rotation = 90 + ((i % 2 == 0) and 7 or -7)
					g.Position = UDim2.fromScale(0.1 + (i - 1) / (NP - 1) * 0.8 + ((i % 2 == 0) and 0.008 or 0), Cd.CY + ((i % 2 == 0) and 0.035 or -0.035))
					g.GroupTransparency = 1 - c01(k / 0.06) * (1 - c01((tt - 1.3 - i * 0.05) / 0.4)) * 0.85 * out
				end
				local k = c01((tt - DROP) / 0.5)
				Cd.box.Position = UDim2.fromScale(0.5, Cd.CY - 0.16 * (1 - L.outBack(k)))
				local na = tt < DROP and 0 or c01((tt - DROP) / 0.12)
				Cd.nm.TextTransparency = 1 - na * a
				Cd.nst.Transparency = 1 - na * a * 0.9
			end
		end }





	local SEGL = 0.18
	local function wedge(size, col)
		if L.dead then return L.part() end
		return L.new("WedgePart", { Anchored = true, CanCollide = false, CanQuery = false, CanTouch = false, CastShadow = false, Size = size, Color = col,
			Material = SMOOTH, Transparency = 0 }, L.root)
	end
	local function newCat(kind, u, simple)
		local D = KINDS[kind] or KINDS.tabby
		local col = D.col
		local function c(k) return D[k] or col end
		local cat = { u = u, kind = kind, list = {}, links = {}, furM = {}, eyeM = {}, pupM = {}, ears = {}, tail = {}, bp = {}, bc = {}, vis = true }
		local function sp(size, cl, key, rel, fur, block)
			local p = L.part({ Size = size * u, Color = cl, Material = SMOOTH, Transparency = 0 })

			local m = (not block) and L.new("SpecialMesh", { MeshType = Enum.MeshType.Brick }, p) or nil
			cat.list[#cat.list + 1] = p
			if key then cat.links[#cat.links + 1] = { p, key, CF(rel.Position * u) * rel.Rotation } end
			if fur and m then cat.furM[#cat.furM + 1] = m end
			return p, m
		end




		sp(V3(0.34, 0.3, 0.46), col, "body", CF(0, 0, -0.17), true)
		sp(V3(0.35, 0.32, 0.38), col, "body", CF(0, 0.005, 0.2), true)
		sp(V3(0.28, 0.03, 0.7), c("belly"), "body", CF(0, -0.15, 0))
		if D.bib then sp(V3(0.26, 0.22, 0.03), D.bib, "body", CF(0, -0.02, -0.4)) end
		if D.stripe then

			for _, z in ipairs({ -0.26, -0.08, 0.1, 0.27 }) do
				sp(V3(0.355, 0.3, 0.055), D.stripe, "body", CF(0, 0.02, z))
			end
		end
		if D.patch1 then
			sp(V3(0.2, 0.03, 0.26), D.patch1, "body", CF(0.075, 0.165, 0.17))
			sp(V3(0.03, 0.18, 0.22), D.patch1, "body", CF(0.175, 0.05, 0.17))
			sp(V3(0.17, 0.03, 0.2), D.patch2, "body", CF(-0.085, 0.16, -0.2))
			sp(V3(0.03, 0.15, 0.18), D.patch2, "body", CF(-0.172, 0.04, -0.2))
		end

		sp(V3(0.36, 0.3, 0.3), col, "head", CF())
		if D.stripe then
			sp(V3(0.05, 0.02, 0.14), D.stripe, "head", CF(-0.06, 0.155, -0.02))
			sp(V3(0.05, 0.02, 0.14), D.stripe, "head", CF(0.06, 0.155, -0.02))
		end
		if D.headPatch then sp(V3(0.18, 0.305, 0.305), D.headPatch, "head", CF(0.092, 0, 0)) end
		sp(V3(0.18, 0.1, 0.07), c("muz"), "head", CF(0, -0.075, -0.175))
		sp(V3(0.06, 0.04, 0.03), D.nose or PINK, "head", CF(0, -0.04, -0.21))

		local _, mm = sp(V3(0.07, 0.05, 0.02), rgb(70, 30, 36), "head", CF(0, -0.12, -0.205))
		cat.mouthM = mm

		for _, side in ipairs({ -1, 1 }) do
			local o = L.part({ Size = V3(0.04, 0.11, 0.1) * u, Color = c("ear"), Material = SMOOTH, Transparency = 0 })
			local i = L.part({ Size = V3(0.02, 0.065, 0.055) * u, Color = D.ein or PINK, Material = SMOOTH, Transparency = 0 })
			cat.list[#cat.list + 1] = o
			cat.list[#cat.list + 1] = i
			cat.ears[#cat.ears + 1] = { o = o, i = i, side = side }
		end

		for _, side in ipairs({ -1, 1 }) do
			local ecf = CF(side * 0.085, 0.03, -0.152)
			local ep, em = sp(V3(0.09, 0.07, 0.012), D.eye, "head", ecf)
			ep.Reflectance = 0.2
			local _, pm = sp(V3(0.026, 0.07, 0.012), BLK, "head", ecf * CF(0, 0, -0.004))
			cat.eyeM[#cat.eyeM + 1] = em
			cat.pupM[#cat.pupM + 1] = pm
			if not simple then
				local _, hm = sp(V3(0.02, 0.02, 0.01), W, "head", ecf * CF(side * -0.022, 0.018, -0.008))
				cat.eyeM[#cat.eyeM + 1] = hm
			end
		end
		if not simple then

			for _, side in ipairs({ -1, 1 }) do
				for j, rz in ipairs({ 0.1, -0.08 }) do
					sp(V3(0.24, 0.01, 0.01), D.wh or rgb(245, 245, 245), "head", CF(side * 0.19, -0.065 - 0.02 * j, -0.17) * A(0, 0, rz * side), false, true)
				end
			end
		end

		for _, n in ipairs({ "legFL", "legFR", "legBL", "legBR" }) do
			sp(V3(0.1, 0.34, 0.1), col, n, CF())
			sp(V3(0.11, 0.06, 0.13), c("paw"), n, CF(0, -0.16, -0.015))
			if not simple and n:sub(4, 4) == "B" then sp(V3(0.12, 0.22, 0.17), col, n, CF(0, 0.09, 0.02), true) end
		end

		for i = 1, 5 do
			local w = 0.085 - 0.004 * (i - 1)
			local cl = (i == 5 and D.tip) or (D.stripe and i % 2 == 0 and D.stripe) or c("tail")
			cat.tail[i] = sp(V3(w, w, 0.24), cl, nil, nil, true)
		end
		function cat.show(on)
			if cat.vis == on then return end
			cat.vis, cat.fa = on, nil
			for _, p in ipairs(cat.list) do p.Transparency = on and 0 or 1 end
		end
		function cat.fade(a)
			a = math.floor(a * 50 + 0.5) / 50
			if cat.fa == a then return end
			cat.vis, cat.fa = nil, a
			for _, p in ipairs(cat.list) do p.Transparency = a end
		end

		function cat.addTrail(tc)
			local chest = cat.list[1]
			local a0 = L.new("Attachment", { Position = V3(0, 0.16 * u, 0) }, chest)
			local a1 = L.new("Attachment", { Position = V3(0, -0.16 * u, 0) }, chest)
			cat.trailE = L.new("Trail", { Attachment0 = a0, Attachment1 = a1, Lifetime = 0.25, FaceCamera = true, MinLength = 0, Enabled = false, LightEmission = 0.6,
				Color = CS(tc), Transparency = NS({ K(0, 0.2), K(0.55, 0.6), K(1, 1) }), WidthScale = NS({ K(0, 1), K(1, 0.15) }) }, chest)
		end
		return cat
	end
	local R90 = math.rad(90)
	local function leg(x, y, z, rx) return CF(x, y, z) * A(rx or 0, 0, 0) * CF(0, -0.17, 0) end


	local POSE = {}
	POSE.stand = function(Q)
		local sw = Q.walk and math.sin(Q.walk) * (0.55 + 0.3 * (Q.stride or 0)) or 0
		local bob = Q.walk and math.abs(math.cos(Q.walk)) * 0.035 or 0
		local tp = Q.walk and -78 or -55
		local hb = Q.walk and math.sin(Q.walk * 2) * 0.025 or 0
		return { body = CF(0, 0.47 + bob, 0) * A(0, 0, sw * 0.06), head = CF(0, 0.76 + bob + hb, -0.5) * A((Q.hp or 0) + hb, Q.hy or 0, 0),
			legFL = leg(-0.11, 0.37, -0.27, sw), legFR = leg(0.11, 0.37, -0.27, -sw), legBL = leg(-0.12, 0.39, 0.27, -sw), legBR = leg(0.12, 0.39, 0.27, sw),
			tail = CF(0, 0.58, 0.44) * A(0, (Q.sway or 0) * (Q.walk and 0.1 or 0.3), 0) * A(math.rad(tp), 0, 0), tb = V3(Q.walk and -0.24 or -0.2, (Q.sway or 0) * (Q.walk and 0.05 or 0.15), 0) }
	end
	POSE.sit = function(Q)
		local lick = Q.lick or 0

		return { body = CF(0, 0.32, 0.1) * A(math.rad(48), 0, 0), head = CF(0, 0.86 - 0.2 * lick, -0.22 - 0.05 * lick) * A((Q.hp or 0) - 0.5 * lick, (Q.hy or 0) * (1 - lick), 0),
			legFL = CF(-0.09, 0.37 + 0.12 * lick, -0.22) * A(1.4 * lick, 0, 0) * CF(0, -0.17, 0), legFR = leg(0.09, 0.37, -0.22, 0),
			legBL = CF(-0.17, 0.1, 0.06) * A(R90, 0, 0), legBR = CF(0.17, 0.1, 0.06) * A(R90, 0, 0),
			tail = CF(0.05, 0.06, 0.3) * A(0, math.rad(70), 0), tb = V3(0, 0.32 + (Q.sway or 0) * 0.05, 0) }
	end
	POSE.sleep = function(Q)
		local br = math.sin((Q.clock or 0) * 1.6) * 0.012
		return { body = CF(0, 0.23 + br, 0), head = CF(0.06, 0.24, -0.42) * A(math.rad(-8), math.rad(20), math.rad(12)),
			legFL = CF(-0.09, 0.06, -0.3) * A(R90, 0, 0), legFR = CF(0.09, 0.06, -0.3) * A(R90, 0, 0),
			legBL = CF(-0.15, 0.08, 0.1) * A(R90, 0, 0), legBR = CF(0.15, 0.08, 0.1) * A(R90, 0, 0),
			tail = CF(-0.08, 0.06, 0.42) * A(0, math.rad(-80), 0), tb = V3(0, -0.38, 0) }
	end

	POSE.crouch = function(Q)
		local wg = math.sin(Q.wig or 0)
		return { body = CF(wg * 0.025, 0.32, 0) * A(-0.12, wg * 0.08, 0), head = CF(0, 0.5, -0.5) * A((Q.hp or 0) - 0.1, Q.hy or 0, 0),
			legFL = leg(-0.11, 0.25, -0.28, 0.75), legFR = leg(0.11, 0.25, -0.28, 0.75), legBL = leg(-0.13, 0.32, 0.27, -0.6), legBR = leg(0.13, 0.32, 0.27, -0.6),
			tail = CF(0, 0.36, 0.44) * A(0, (Q.sway or 0) * 0.4, 0) * A(math.rad(-12), 0, 0), tb = V3(0.02, (Q.sway or 0) * 0.12, 0) }
	end

	POSE.leap = function(Q)
		return { body = CF(0, 0.5, 0) * A(-0.15, 0, 0), head = CF(0, 0.74, -0.55) * A(0.15 + (Q.hp or 0), 0, 0),
			legFL = leg(-0.11, 0.4, -0.3, 1.3), legFR = leg(0.11, 0.4, -0.3, 1.3), legBL = leg(-0.12, 0.42, 0.3, -1.2), legBR = leg(0.12, 0.42, 0.3, -1.2),
			tail = CF(0, 0.55, 0.44) * A(math.rad(-15), 0, 0), tb = V3(0.03, 0, 0) }
	end

	POSE.hiss = function(Q)
		return { body = CF(0, 0.52, 0), head = CF(0, 0.78, -0.52) * A((Q.hp or 0) - 0.1, Q.hy or 0, 0),
			legFL = leg(-0.13, 0.4, -0.27, -0.12), legFR = leg(0.13, 0.4, -0.27, -0.12), legBL = leg(-0.14, 0.42, 0.27, 0.12), legBR = leg(0.14, 0.42, 0.27, 0.12),
			tail = CF(0, 0.62, 0.42) * A(math.rad(-85), 0, 0), tb = V3(0, (Q.sway or 0) * 0.03, 0) }
	end

	POSE.stretch = function(Q)
		return { body = CF(0, 0.36, 0.05) * A(-0.38, 0, 0), head = CF(0, 0.42, -0.52) * A(0.25, 0, 0),
			legFL = leg(-0.1, 0.22, -0.3, 1.2), legFR = leg(0.1, 0.22, -0.3, 1.2), legBL = leg(-0.12, 0.4, 0.27, -0.1), legBR = leg(0.12, 0.4, 0.27, -0.1),
			tail = CF(0, 0.6, 0.42) * A(math.rad(-70), 0, 0), tb = V3(-0.1, 0, 0) }
	end
	local FRAMES = { "body", "head", "legFL", "legFR", "legBL", "legBR" }

	local function place(cat, root, blend, Q)
		if L.dead then return end
		local acc, tb
		for _, b in ipairs(blend) do
			if not acc then acc = POSE[b[1]](Q) tb = acc.tb
			elseif b[2] > 0.001 then
				local p, w = POSE[b[1]](Q), math.min(b[2], 1)
				for n, cf in pairs(p) do if n ~= "tb" then acc[n] = acc[n]:Lerp(cf, w) end end
				tb = tb:Lerp(p.tb, w)
			end
		end
		local u = cat.u
		local F = {}
		for _, n in ipairs(FRAMES) do local cf = acc[n] F[n] = root * (CF(cf.Position * u) * cf.Rotation) end
		local parts, cfs, n = cat.bp, cat.bc, 0
		for _, lk in ipairs(cat.links) do n += 1 parts[n], cfs[n] = lk[1], F[lk[2]] * lk[3] end

		local now = os.clock()
		if not cat.twN then cat.twN = now + rnd(2, 6) end
		if now > cat.twN then cat.twS, cat.twSide, cat.twN = now, math.random(0, 1) * 2 - 1, now + rnd(3, 8) end
		local fl = Q.earFlat or 0
		for _, e in ipairs(cat.ears) do
			local tw = (cat.twS and e.side == cat.twSide and now - cat.twS < 0.3) and math.sin((now - cat.twS) / 0.3 * math.pi * 2) * 0.35 or 0
			local cf = F.head * CF(e.side * 0.115 * u, (0.16 - 0.04 * fl) * u, 0.02 * u) * A(-0.4 * fl, 0, -e.side * (math.rad(10 + 55 * fl) + tw)) * A(0, R90, 0)
			n += 1 parts[n], cfs[n] = e.o, cf
			n += 1 parts[n], cfs[n] = e.i, cf * CF(0.014 * u, -0.022 * u, 0)
		end

		local cf = root * (CF(acc.tail.Position * u) * acc.tail.Rotation)
		local nT = #cat.tail
		local ck = (Q.clock or os.clock()) * 2.4
		local amp = Q.tw or 1
		for j, p in ipairs(cat.tail) do
			local ju = j / nT
			cf = cf * A(tb.X, tb.Y + 0.07 * amp * ju * math.sin(ck - j * 0.55), 0)
			n += 1 parts[n], cfs[n] = p, cf * CF(0, 0, SEGL * 0.5 * u)
			cf = cf * CF(0, 0, SEGL * u)
		end
		bulk(parts, cfs)

		local bl = Q.blink and 0.12 or 1
		local pw = math.floor((1 + 1.6 * (Q.pupil or 0)) * 10 + 0.5) / 10
		if cat.bl ~= bl or cat.pw ~= pw then
			cat.bl, cat.pw = bl, pw
			for _, m in ipairs(cat.eyeM) do m.Scale = V3(1, bl, 1) end
			for _, m in ipairs(cat.pupM) do m.Scale = V3(pw, bl, 1) end
		end
		local mo = (cat.mouthUntil and now < cat.mouthUntil) and math.sin((cat.mouthUntil - now) / 0.45 * math.pi) or 0
		if Q.hissing then mo = 1 end
		mo = math.floor(mo * 10 + 0.5) / 10
		if cat.mouthM and cat.mo ~= mo then cat.mo = mo cat.mouthM.Scale = V3(1 + 0.2 * mo, 0.15 + 0.85 * mo, 1) end
		local pf = math.floor((Q.puff or 1) * 20 + 0.5) / 20
		if cat.pf ~= pf then cat.pf = pf for _, m in ipairs(cat.furM) do m.Scale = V3(pf, pf, 1 + (pf - 1) * 0.6) end end
	end



	local puffP = L.part({ Size = V3(1.2, 0.6, 1.2) })
	local puffE = L.pe(puffP, { Texture = L.T("smoke.png"), Shape = Enum.ParticleEmitterShape.Box, EmissionDirection = Enum.NormalId.Top, Lifetime = NR(0.5, 0.9),
		Speed = NR(1.5, 4), SpreadAngle = Vector2.new(80, 80), Drag = 3, Size = NS({ K(0, 0.8), K(1, 2.2) }), Transparency = NS({ K(0, 0.35), K(1, 1) }),
		Color = CS(C2), LightEmission = 0.1, Rotation = NR(0, 360), RotSpeed = NR(-40, 40), Acceleration = V3(0, 1.2, 0) })
	local function puff(p, n, col)
		puffP.CFrame = CF(p)
		puffE.Color = CS(col or C2)
		puffE:Emit(n)
	end

	local function say(p, text, col, big)
		local s = sc() * (big or 1)
		local a = L.part({ CFrame = CF(p) })
		local bb = L.new("BillboardGui", { Adornee = a, Size = UDim2.new(2.6 * s, 0, 0.8 * s, 0), LightInfluence = 0, AlwaysOnTop = false, MaxDistance = 120,
			ResetOnSpawn = false }, a)
		local lb = L.new("TextLabel", { BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), TextScaled = true, Text = text,
			FontFace = Font.new("rbxasset://fonts/families/FredokaOne.json", Enum.FontWeight.Regular), TextColor3 = col or W, TextTransparency = 1 }, bb)
		local st = L.new("UIStroke", { Color = rgb(60, 36, 20), Thickness = 1.6 }, lb)
		local tilt = rnd(-12, 12)
		L.fx(1.5, function(k, t)
			a.CFrame = CF(p + V3(0, 1.3 * s * L.outQuad(k), 0))
			local al = c01(t / 0.12) * (1 - c01((k - 0.6) / 0.4))
			lb.TextTransparency, st.Transparency = 1 - al, 1 - al
			lb.Rotation = tilt * (1 - k)
			local sc2 = 0.5 + 0.5 * L.outBack(c01(t / 0.22))
			bb.Size = UDim2.new(2.6 * s * sc2, 0, 0.8 * s * sc2, 0)
		end, { a })
	end
	local function meowText() return MEOWS[math.random(1, #MEOWS)] end

	local function meow(cat, p, text, col, big) cat.mouthUntil = os.clock() + 0.45 say(p, text, col, big) end

	local function pawCanvas(parent, col, tr)
		local g = L.new("CanvasGroup", { BackgroundTransparency = 1, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromScale(1, 1),
			GroupTransparency = tr or 0 }, parent)
		local function dot(x, y, w, h)
			local d = L.new("Frame", { BorderSizePixel = 0, BackgroundColor3 = col, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(x, y), Size = UDim2.fromScale(w, h) }, g)
			L.new("UICorner", { CornerRadius = UDim.new(0.5, 0) }, d)
		end
		dot(0.5, 0.66, 0.46, 0.38) dot(0.2, 0.36, 0.18, 0.22) dot(0.4, 0.2, 0.18, 0.22) dot(0.6, 0.2, 0.18, 0.22) dot(0.8, 0.36, 0.18, 0.22)
		return g
	end



	local PF = CFrame.Angles(-math.rad(90), 0, 0)
	local function pawPart(size, col, bright)
		local p = L.part({ Size = V3(size, size, 0.05) })
		local sg = L.new("SurfaceGui", { Face = Enum.NormalId.Back, LightInfluence = 0, Brightness = bright or 1, CanvasSize = Vector2.new(64, 64), AlwaysOnTop = false }, p)
		return p, pawCanvas(sg, col, 1)
	end
	local prints, pi = {}, 0
	for i = 1, 10 do
		local p, g = pawPart(0.6, C1)
		prints[i] = { p = p, g = g, t = 99 }
	end
	local function stamp(pos, yaw, col)
		pi = pi % #prints + 1
		local pr = prints[pi]
		local s = sc()
		if math.abs(pr.p.Size.X - 0.6 * s) > 0.02 then pr.p.Size = V3(0.6 * s, 0.6 * s, 0.05) end
		pr.p.CFrame = CF(pos + V3(0, 0.04, 0)) * A(0, yaw, 0) * PF
		pr.t = 0
		if col and pr.col ~= col then pr.col = col for _, d in ipairs(pr.g:GetChildren()) do if d:IsA("Frame") then d.BackgroundColor3 = col end end end
	end

	local floaters = {}
	for i = 1, 3 do
		local a = L.part()
		local bb = L.new("BillboardGui", { Adornee = a, Size = UDim2.new(0.55, 0, 0.55, 0), LightInfluence = 0, MaxDistance = 120, ResetOnSpawn = false }, a)
		local glow = L.new("ImageLabel", { BackgroundTransparency = 1, Image = L.T("glowui.png") or "", ImageColor3 = C1, ImageTransparency = 1, AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromScale(2, 2) }, bb)
		floaters[i] = { a = a, g = pawCanvas(bb, i == 2 and C2 or C1, 1), glow = glow, t = 99, life = 2.2 }
	end
	local floatT = 0.5

	local notes = {}
	for i = 1, 6 do
		local a = L.part()
		local bb = L.new("BillboardGui", { Adornee = a, Size = UDim2.new(0.6, 0, 0.6, 0), LightInfluence = 0, MaxDistance = 120, ResetOnSpawn = false }, a)
		local g = L.new("CanvasGroup", { BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), GroupTransparency = 1 }, bb)
		local col = i % 2 == 0 and C2 or C1
		local hd = L.new("Frame", { BorderSizePixel = 0, BackgroundColor3 = col, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.38, 0.78), Size = UDim2.fromScale(0.42, 0.3), Rotation = -20 }, g)
		L.new("UICorner", { CornerRadius = UDim.new(0.5, 0) }, hd)
		L.new("Frame", { BorderSizePixel = 0, BackgroundColor3 = col, AnchorPoint = Vector2.new(0.5, 1), Position = UDim2.fromScale(0.56, 0.76), Size = UDim2.fromScale(0.08, 0.66) }, g)
		L.new("Frame", { BorderSizePixel = 0, BackgroundColor3 = col, Position = UDim2.fromScale(0.56, 0.1), Size = UDim2.fromScale(0.26, 0.14), Rotation = 25 }, g)
		notes[i] = { a = a, g = g, t = 99, from = nil, dx = 0 }
	end
	local noteT = 0

	local LASER = rgb(255, 40, 46)
	local dotP = L.part({ Shape = Enum.PartType.Ball, Size = V3(0.16, 0.16, 0.16), Color = LASER, Material = Enum.Material.Neon, Transparency = 1 })
	local dotB = L.new("BillboardGui", { Adornee = dotP, Size = UDim2.new(1, 0, 1, 0), LightInfluence = 0, MaxDistance = 120, ResetOnSpawn = false }, dotP)
	local dotG = L.new("ImageLabel", { BackgroundTransparency = 1, Image = L.T("glowui.png") or "", ImageColor3 = LASER, ImageTransparency = 1, Size = UDim2.fromScale(1, 1) }, dotB)
	local dot = { a = 0, pos = nil, goal = nil, wait = 0, spd = 6, gT = 0 }


	local s0 = sc()
	local sitters = {}
	for i, kind in ipairs({ "black", "calico" }) do
		sitters[i] = { cat = newCat(kind, 1.9 * s0), side = i == 1 and -1 or 1, mode = "sit", pos = nil, yaw = 0, ws = 1, wl = 0, wc = 0, wj = 0, gy = nil, gyT = 0,
			hy = 0, hyT = 0, hyGoal = 0, lick = 0, lickT = rnd(4, 9), meowT = rnd(3, 8), walk = 0, blinkT = rnd(2, 5), hidden = false, mt = 0 }
	end

	local spirit = newCat("white", 2.6 * s0, true)
	for _, p in ipairs(spirit.list) do p.Material = Enum.Material.ForceField p.Color = C1 end
	spirit.fade(1)
	local spiritT = nil
	local landP, landG = pawPart(1.5 * s0, C2, 1.2)
	local landT = 99

	local envP = L.part({ Size = V3(26, 3, 26) })
	local fireE = L.pe(envP, { Texture = L.T("glowui.png"), Shape = Enum.ParticleEmitterShape.Box, Rate = 3, Lifetime = NR(3, 5), Speed = NR(0.2, 0.8),
		SpreadAngle = Vector2.new(180, 180), Size = NS({ K(0, 0), K(0.2, 0.35), K(0.8, 0.3), K(1, 0) }),
		Transparency = NS({ K(0, 1), K(0.2, 0.1), K(0.5, 0.55), K(0.8, 0.1), K(1, 1) }), Color = CS(rgb(220, 255, 120), C1), LightEmission = 1,
		Acceleration = V3(0, 0.1, 0) })
	local fluffE = L.pe(envP, { Texture = L.T("smoke.png"), Shape = Enum.ParticleEmitterShape.Box, Rate = 2, Lifetime = NR(4, 6), Speed = NR(0.3, 1),
		SpreadAngle = Vector2.new(180, 30), Size = NS({ K(0, 0.12), K(1, 0.2) }), Transparency = NS({ K(0, 1), K(0.15, 0.4), K(0.85, 0.5), K(1, 1) }),
		Color = CS(C2), LightEmission = 0.2, Rotation = NR(0, 360), RotSpeed = NR(-60, 60), Acceleration = V3(0.3, -0.05, 0.2) })
	local envT = 0

	System.StaffThemes._tagCh = ch
	local tag = System.StaffThemes.headTag(L, "ninelives", C1, C2, { c1 = C1, c2 = C2, role = "N I N E   L I V E S" })
	System.StaffThemes._tagCh = nil

	local lives = 9
	local function setLives(n)
		lives = n
		if tag.bb then pcall(function() tag.bb:SetAttribute("NLLives", n) end) end
	end
	setLives(9)

	local held = nil
	local function hide(on)
		if on then
			held = held or {}
			for d in pairs(L.bodyParts()) do if not held[d] then held[d] = true d.LocalTransparencyModifier = 1 end end
		elseif held then
			for d in pairs(held) do if d.Parent then pcall(function() d.LocalTransparencyModifier = 0 end) end end
			held = nil
		end
	end

	local function spotOf(sv)
		local f, r = L.facing()
		local s = sc()
		return ch.feet + (r * sv.side * (lives == 1 and 3.6 or 5.8) + f * 1.2) * s
	end
	local function snapSitters()
		for _, sv in ipairs(sitters) do sv.pos = spotOf(sv) sv.gy = nil sv.mode = "sit" sv.ws = 1 end
	end



	local function newBox(s)
		local B = { s = s, parts = {} }
		local w, h, t = 2.6 * s, 2 * s, 0.1 * s
		local function mk(size) local p = L.part({ Size = size, Color = CARD, Material = BOXMAT, Transparency = 0 }) B.parts[#B.parts + 1] = p return p end
		B.bottom = mk(V3(w, t, w))
		B.walls = { mk(V3(w, h, t)), mk(V3(w, h, t)), mk(V3(t, h, w)), mk(V3(t, h, w)) }
		B.flaps = { mk(V3(w / 2, t, w)), mk(V3(w / 2, t, w)) }
		B.tape = mk(V3(0.3 * s, t * 1.2, w * 1.01))
		B.tape.Color = rgb(205, 175, 120)
		B.h = h
		function B.set(root, flap, fall, alpha)
			B.bottom.CFrame = root * CF(0, t / 2, 0)
			local WALL = { { CF(0, 0, -w / 2), V3(-1, 0, 0) }, { CF(0, 0, w / 2), V3(1, 0, 0) }, { CF(-w / 2, 0, 0), V3(0, 0, 1) }, { CF(w / 2, 0, 0), V3(0, 0, -1) } }
			for i, wl in ipairs(B.walls) do
				local base, ax = WALL[i][1], WALL[i][2]

				wl.CFrame = root * base * CFrame.fromAxisAngle(ax, R90 * (fall or 0)) * CF(0, h / 2, 0)
			end


			local a = R90 * 1.3 * (flap or 0)
			B.flaps[1].CFrame = B.walls[3].CFrame * CF(0, h / 2, 0) * A(0, 0, a) * CF(w / 4, 0, 0)
			B.flaps[2].CFrame = B.walls[4].CFrame * CF(0, h / 2, 0) * A(0, 0, -a) * CF(-w / 4, 0, 0)
			B.tape.CFrame = (flap or 0) < 0.05 and root * CF(0, h + t, 0) or root * CF(0, -50, 0)
			B.tape.Transparency = (flap or 0) < 0.05 and (alpha or 0) or 1
			for _, p in ipairs(B.parts) do if p ~= B.tape then p.Transparency = alpha or 0 end end
		end
		return B
	end

	local function leapCat(kind, p0, p1, t0, life, runDir, sitFor)
		local s = sc()
		local cat = newCat(kind, 1.6 * s, true)
		cat.fade(1)
		local yaw = flatYaw(p1 - p0)
		local said, puffed = false, false
		L.fx(t0 + life, function(_, t)
			local u = t - t0
			if u < 0 then return end
			local Q = { sway = math.sin(u * 5) * 0.6, hy = 0 }
			if u < 0.5 then
				local k = u / 0.5
				cat.fade(0)

				place(cat, yawCF(p0:Lerp(p1, k) + V3(0, 2.4 * s * math.sin(k * math.pi), 0), yaw) * A((0.5 - k) * 0.7, 0, 0), { { "stand", 1 }, { "leap", 1 - c01((k - 0.7) / 0.3) } }, Q)
			elseif u < 0.5 + (sitFor or 0.6) then
				if not puffed then puffed = true puff(p1 + V3(0, 0.2, 0), 3, C2) end
				if not said and math.random() < 0.6 then said = true meow(cat, p1 + V3(0, 1.2 * s, 0), meowText()) end
				Q.hy = math.sin(u * 3) * 0.5
				place(cat, yawCF(p1, yaw), { { "stand", 1 }, { "sit", c01((u - 0.5) / 0.2) } }, Q)
			else
				local r = u - 0.5 - (sitFor or 0.6)
				Q.walk, Q.stride = r * 38, 0.8

				local run = 12 * s * (r - 0.25 * (1 - math.exp(-r * 4)))
				place(cat, yawCF(p1 + runDir * run + V3(0, math.abs(math.sin(r * 9)) * 0.12 * s, 0), flatYaw(runDir)), { { "stand", 1 } }, Q)
				cat.fade(L.inQuad(c01((t - (t0 + life - 0.6)) / 0.6)))
			end
		end, cat.list)
		return cat
	end


	local function ghostDrop(dur, onLand)
		local hrp = ch.hrp
		if L.dead or not (hrp and hrp.Parent and ch.char) then if onLand then onLand() end return end
		local s = sc()
		local base = hrp.CFrame
		local m = L.ghost(C1, nil, dur + 0.4, true)
		local ps, rel = {}, {}
		for _, g in ipairs(m:GetChildren()) do
			if g:IsA("BasePart") then ps[#ps + 1] = g rel[#rel + 1] = base:ToObjectSpace(g.CFrame) g.Transparency = 0.2 end
		end
		local fy = ch.fy or -3
		local H = 9 * s
		local landed = false
		local cfs = {}
		L.fx(dur + 0.4, function(_, t)
			local k = c01(t / dur)
			local spin = 1 - L.outQuad(c01(k / 0.85))
			local sq = 1

			if t > dur then local x = c01((t - dur) / 0.45) sq = 1 - 0.32 * math.sin(x * math.pi * 1.6) * (1 - x) end
			local center = (base + V3(0, H * (1 - k * k), 0)) * A(0, spin * 2, spin * math.pi)
			for i, rc in ipairs(rel) do
				local p = rc.Position
				cfs[i] = center * (CF(p.X, fy + (p.Y - fy) * sq, p.Z) * rc.Rotation)
			end
			bulk(ps, cfs)
			local al = 0.2 + 0.8 * c01((t - dur - 0.05) / 0.35)
			for _, g in ipairs(ps) do g.Transparency = al end
			if not landed and t >= dur then landed = true if onLand then onLand() end end
		end, { m })
	end

	local function landDust(o, s, yaw, objs)
		local p, g = pawPart(3.4 * s, C2, 1.5)
		p.CFrame = CF(o + V3(0, 0.05, 0)) * A(0, yaw, 0) * PF
		if objs then objs[#objs + 1] = p end
		L.fx(2.2, function(k, t) g.GroupTransparency = 1 - 0.7 * c01(t / 0.08) * (1 - c01((t - 0.5) / 1.7)) end, { p })
		L.groundWave(o, "ring_c.png", C2, 2 * s, 16 * s, 0.7, 1.4)
		puff(o + V3(0, 0.3, 0), 22, C2)
	end



	local function shortBox()
		local o, s = L.ground(ch.feet, 3, 8), sc()
		local yaw = ch.yaw or 0
		hide(true)
		local B = newBox(s)
		B.set(yawCF(o + V3(0, 12, 0), yaw), 0, 0, 0)
		L.timeline(3.4, function(t, once)
			if held and once("late", 0.2) then hide(true) end
			local root
			if t < 0.4 then root = yawCF(o + V3(0, 12 * (1 - L.inQuad(t / 0.4)), 0), yaw)
			else

				local u = t - 0.4
				local hop = math.abs(math.sin(u * 9)) * 0.3 * s * (1 - c01(u / 0.45)) ^ 2
				local w = math.sin(u * 22) * 0.12 * (1 - c01(u / 0.8))
				root = yawCF(o + V3(0, hop, 0), yaw) * A(w, 0, w * 0.6)
			end
			if once("land", 0.4) then puff(o + V3(0, 0.3, 0), 8, C2) end
			if once("q", 0.55) then say(o + V3(0, 2.6 * s, 0), "mrrp?") end


			local tk = c01((t - 2.0) / 0.35)
			local tip = L.inQuad(tk)
			if tk >= 1 then local u = t - 2.35 tip = 1 - 0.09 * math.abs(math.sin(u * 13)) * (1 - c01(u / 0.5)) end
			local w2 = 1.3 * s
			B.set(root * CF(w2, 0, 0) * A(0, 0, -tip * R90) * CF(-w2, 0, 0), L.outBack(c01((t - 1.1) / 0.22)), 0, L.inQuad(c01((t - 2.6) / 0.7)))
			if once("kick", 1.65) then
				local f2, r2 = L.facing()
				leapCat("tabby", o + V3(0, 2.2 * s, 0), L.ground(o - (r2 * 2.4 + f2 * 0.6) * s, 3, 6), 0, 1.7, -r2, 0.35)
			end
			if once("thunk", 2.35) then

				local hitP = (root * CF(w2 + B.h * 0.55, 0, 0)).Position
				puff(hitP + V3(0, 0.3, 0), 10, C2)
				L.groundWave(hitP, "ring_c.png", C2, 1 * s, 5 * s, 0.45, 0.8)
				say(o + V3(0, 2 * s, 0), "*thunk*")
			end
			if once("pop", 1.15) then
				hide(false)
				puff(o + V3(0, 1.5 * s, 0), 14, C2)
				say(ch.pos + V3(0, 2.5 * s, 0), "nya!", C1)
			end
		end, B.parts, function() hide(false) end)
	end


	local PILE5 = { V3(-0.5, 0, 0.2), V3(0.5, 0, -0.1), V3(0, 0, 0.5), V3(-0.2, 0.55, 0.1), V3(0.25, 1.05, 0) }
	local PILE9 = { V3(-0.7, 0, 0.3), V3(0.7, 0, -0.2), V3(0, 0, 0.75), V3(-0.35, 0, -0.65), V3(0.75, 0, 0.6), V3(-0.35, 0.55, 0.15), V3(0.35, 0.55, 0.1),
		V3(0, 0.55, -0.35), V3(0, 1.1, 0) }
	local function shortPile(nine)
		local o, s = L.ground(ch.feet, 3, 8), sc()
		hide(true)
		local kinds = nine and ORDER or { "white", "grey", "tabby", "black", "calico" }
		local slots = nine and PILE9 or PILE5
		local cats = {}
		for i, k in ipairs(kinds) do

			cats[i] = { cat = newCat(k, 1.6 * s, true), yaw = rnd(0, 6.3), dir = nil, slot = o + slots[i] * 1.75 * s, sy = slots[i].Y * 1.75 * s, j = (i > 1) and rnd(-0.03, 0.05) or 0 }
			cats[i].cat.fade(1)
		end
		local objs = {}
		for _, c in ipairs(cats) do for _, p in ipairs(c.cat.list) do objs[#objs + 1] = p end end
		local DT = nine and 0.09 or 0.14
		local T1 = nine and 1.5 or 1.3
		L.timeline(nine and 3 or 2.6, function(t, once)
			if held and once("late", 0.2) then hide(true) end
			for i, c in ipairs(cats) do
				local t0 = (i - 1) * DT + c.j
				local Q = { sway = math.sin(t * 6 + i) * 0.6, hy = math.sin(t * 4 + i) * 0.4 }
				if t < T1 then
					if t >= t0 then
						local k = c01((t - t0) / 0.3)
						c.cat.fade(0)

						local u = t - t0 - 0.3
						local bounce = u > 0 and math.exp(-u * 7) * math.abs(math.sin(u * 16)) * 0.14 * s or 0
						local wob = math.sin(t * 5.5) * 0.09 * c.sy * c01(u / 0.2)
						if u > 0 and not c.puffed then c.puffed = true puff(c.slot + V3(0, 0.2, 0), 2, C2) end
						place(c.cat, yawCF(c.slot + V3(wob, 6 * s * (1 - L.inQuad(k)) + bounce, 0), c.yaw) * A(0, 0, wob * 0.25), { { "stand", 1 }, { "leap", 1 - k }, { "sit", 0.6 * k } }, Q)
					end
				else
					if not c.dir then
						local a = rnd(0, 6.3)
						c.dir = V3(math.cos(a), 0, math.sin(a))
						c.from = c.slot
						c.g = L.ground(c.slot, 3, 6)
					end
					local r = t - T1
					Q.walk, Q.stride = r * 40, 0.8


					local hk = c01(r / 0.38)
					local gp = L.ground(c.from + c.dir * (r * 11 - 0.9 * (1 - hk)) * s, 3, 6)
					local lift = (c.g.Y + c.sy - gp.Y) * (1 - hk) + math.sin(hk * math.pi) * 0.7 * s
					place(c.cat, yawCF(gp + V3(0, math.max(0, lift), 0), flatYaw(c.dir)), { { "stand", 1 }, { "leap", math.sin(hk * math.pi) } }, Q)
					c.cat.fade(L.inQuad(c01((t - T1 - 0.7) / 0.6)))
				end
			end
			if once("say", T1 - 0.4) then say(o + V3(0, 2.4 * s, 0), meowText()) end
			if once("show", T1) then
				hide(false)
				puff(o + V3(0, 1, 0), nine and 20 or 10, C2)
				for i = 1, nine and 4 or 2 do say(o + V3(rnd(-2, 2), 2 * s, rnd(-2, 2)), meowText()) end
				if nine then
					say(ch.pos + V3(0, 3.2 * s, 0), "+9", C1, 1.6)
					L.groundWave(o, "ring_c.png", C1, 3 * s, 20 * s, 1.1, 2.4)
					setLives(9)
				end
			end
		end, objs, function() hide(false) end)
	end

	local function shortYarn()
		local o, s = L.ground(ch.feet, 3, 8), sc()
		hide(true)
		local f, r = L.facing()
		local from = o + (r * 12 + f * 4) * s
		local YARN = rgb(235, 95, 120)
		local ball = L.part({ Shape = Enum.PartType.Ball, Size = Vector3.one * 1.1 * s, Color = YARN, Material = Enum.Material.Fabric, Transparency = 0 })
		local winder = L.part()
		local wa0 = L.new("Attachment", { Position = V3(0, 0.06 * s, 0) }, winder)
		local wa1 = L.new("Attachment", { Position = V3(0, -0.06 * s, 0) }, winder)
		local thread = L.new("Trail", { Attachment0 = wa0, Attachment1 = wa1, Lifetime = 0.9, FaceCamera = true, Color = CS(YARN), Transparency = NS(0.1), LightEmission = 0,
			MinLength = 0, Enabled = false }, winder)
		local rot, lastBp = CFrame.identity, nil

		local bat = newCat("black", 1.6 * s, true)
		bat.fade(1)
		local objsY = { ball, winder }
		for _, p in ipairs(bat.list) do objsY[#objsY + 1] = p end
		local c0, c1 = o - r * 5 * s, o - r * 1.7 * s
		L.timeline(3.4, function(t, once)
			if held and once("late", 0.2) then hide(true) end

			local k = L.outQuad(t / 1)

			local bk = c01((t - 1.16) / 0.64)
			local bp = from:Lerp(o, k) + r * 1.6 * s * math.sin(bk * math.pi) + V3(0, 0.9 * s * math.sin(c01((t - 1.16) / 0.3) * math.pi), 0)
			local bsz = 1.1 * s * (1 - 0.85 * c01((t - 1.8) / 0.7))

			if lastBp then
				local dv = (bp - lastBp) * V3(1, 0, 1)
				if dv.Magnitude > 1e-4 then rot = CFrame.fromAxisAngle(V3(0, 1, 0):Cross(dv.Unit), dv.Magnitude / (bsz / 2)) * rot end
			end
			lastBp = bp
			if t > 0.3 and t < 3.3 then
				local Q = { sway = math.sin(t * 6) * 0.6, hy = 0 }
				local yawC = flatYaw(r)
				if t < 1.0 then
					bat.fade(1 - c01((t - 0.3) / 0.1))
					Q.walk = t * 20
					place(bat, yawCF(L.ground(c0:Lerp(c1, (t - 0.3) / 0.7), 3, 6), yawC), { { "stand", 1 } }, Q)
				elseif t < 1.35 then
					local k2 = (t - 1.0) / 0.35
					place(bat, yawCF(L.ground(c1 + r * 0.4 * s * c01((k2 - 0.4) / 0.6), 3, 6), yawC),
						{ { "stand", 1 }, { "crouch", 1 - c01((k2 - 0.4) / 0.2) }, { "leap", c01((k2 - 0.4) / 0.2) * (1 - c01((k2 - 0.85) / 0.15)) } }, Q)
				elseif t < 2.6 then
					place(bat, yawCF(L.ground(c1 + r * 0.4 * s, 3, 6), yawC), { { "stand", 1 }, { "sit", c01((t - 1.35) / 0.25) } }, Q)
				else

					local u = t - 2.6
					Q.walk = u * 18
					local back = -r
					place(bat, yawCF(L.ground(c1 + r * 0.4 * s + back * (u * u * 6) * s, 3, 6), flatYaw(back)), { { "stand", 1 }, { "sit", 1 - c01(u / 0.15) } }, Q)
					bat.fade(L.inQuad(c01((t - 2.75) / 0.5)))
				end
			end
			if once("bat", 1.16) then meow(bat, c1 + V3(0, 1.3 * s, 0), "mrrp!") end
			if t < 2.55 then
				ball.CFrame = CF(bp + V3(0, bsz / 2, 0)) * rot
				ball.Transparency = 0
			else ball.Transparency = 1 end

			if t > 1.8 and t < 2.55 then
				thread.Enabled = true
				local u = c01((t - 1.8) / 0.7)


				local ue = L.outQuad(u)
				local a = ue * 6.283 * 3
				local h = (ch.fy or -2.9) + ue * (-(ch.fy or -2.9) + 1.6 * s)
				local rad = (1.0 - 0.45 * ue) * s
				winder.CFrame = CF(o + V3(math.cos(a) * rad, h - (ch.fy or -2.9), math.sin(a) * rad))
			else thread.Enabled = false end
			if once("show", 2.4) then
				hide(false)
				puff(ch.pos + V3(0, 0.5 * s, 0), 8, YARN)
				L.ghost(YARN, Enum.Material.Fabric, 0.6)
				say(ch.pos + V3(0, 2.4 * s, 0), "mrrp", YARN)
			end
		end, objsY, function() hide(false) end)
	end

	local function shortFeet()
		local o, s = L.ground(ch.feet, 3, 8), sc()
		local yaw = ch.yaw or 0
		hide(true)
		local objs = {}
		L.timeline(3.2, function(t, once)
			if held and once("late", 0.2) then hide(true) end
			if once("drop", 0.1) then
				ghostDrop(0.6, function()
					landDust(o, s, yaw, objs)
					say(ch.pos + V3(0, 2.6 * s, 0), "mrrp!", C1)
				end)
			end
			if once("show", 0.95) then hide(false) puff(ch.pos + V3(0, 0.6 * s, 0), 8, C1) end

			if once("ring", 1.0) then
				for i, kd in ipairs(ORDER) do
					local a = (i - 1) / 9 * math.pi * 2
					local dir = V3(math.cos(a), 0, math.sin(a))
					local p, g = pawPart(0.9 * s, KINDS[kd].col, 1.5)
					p.CFrame = CF(L.ground(o + dir * 2.6 * s, 3, 6) + V3(0, 0.06, 0)) * A(0, flatYaw(dir), 0) * PF

					L.fx(2.3, function(_, tt)
						local pk = c01((tt - (i - 1) * 0.07) / 0.12)
						g.GroupTransparency = 1 - 0.85 * pk * (1 - L.inQuad(c01((tt - 1.5) / 0.75)))
						local sz = 1.35 - 0.35 * L.outBack(pk)
						g.Size = UDim2.fromScale(sz, sz)
					end, { p })
				end
			end
		end, objs, function() hide(false) end)
	end
	local shorts = { shortBox, shortPile, shortYarn, shortFeet }






	local function lantern(col, s)
		local Lt = { parts = {} }
		local function mk(props) local p = L.part(props) Lt.parts[#Lt.parts + 1] = p return p end
		local paper = col:Lerp(W, 0.55)
		Lt.body = mk({ Size = V3(1.1, 1.25, 1.1) * s, Color = paper, Material = SMOOTH, Transparency = 1 })
		Lt.bm = L.new("SpecialMesh", { MeshType = Enum.MeshType.Sphere }, Lt.body)
		Lt.core = mk({ Size = V3(0.7, 0.8, 0.7) * s, Color = col:Lerp(W, 0.25), Material = Enum.Material.Neon, Transparency = 1 })
		L.new("SpecialMesh", { MeshType = Enum.MeshType.Sphere }, Lt.core)
		Lt.rims = {}
		for i, y in ipairs({ 0.6, -0.6 }) do
			local r = mk({ Shape = Enum.PartType.Cylinder, Size = V3(0.08, 0.62, 0.62) * s, Color = rgb(70, 44, 30), Material = SMOOTH, Transparency = 1 })
			Lt.rims[i] = { p = r, y = y }
		end
		Lt.ears = {}
		for i, sd in ipairs({ -1, 1 }) do
			local e = mk({ Size = V3(0.3, 0.46, 0.12) * s, Color = paper, Material = SMOOTH, Transparency = 1 })
			L.new("SpecialMesh", { MeshType = Enum.MeshType.Sphere }, e)
			Lt.ears[i] = { p = e, sd = sd }
		end
		Lt.light = L.new("PointLight", { Color = col, Range = 7 * s, Brightness = 0, Shadows = false }, Lt.core)

		function Lt.set(cf, a, pop)
			local sc2 = 1 + 0.45 * (pop or 0)
			Lt.body.CFrame, Lt.core.CFrame = cf, cf
			Lt.bm.Scale = Vector3.one * sc2
			for _, r in ipairs(Lt.rims) do r.p.CFrame = cf * CF(0, r.y * s * sc2, 0) * A(0, 0, R90) end
			for _, e in ipairs(Lt.ears) do e.p.CFrame = cf * CF(e.sd * 0.27 * s * sc2, 0.78 * s * sc2, 0) * A(0, 0, -e.sd * 0.42) end
			local tr = 1 - a
			Lt.body.Transparency = 0.12 + 0.88 * tr
			Lt.core.Transparency = 0.35 + 0.65 * tr
			for _, r in ipairs(Lt.rims) do r.p.Transparency = tr end
			for _, e in ipairs(Lt.ears) do e.p.Transparency = 0.12 + 0.88 * tr end
			Lt.light.Brightness = 1.4 * a * (1 + 3 * (pop or 0))
		end
		return Lt
	end
	local function arriveFull()
		local o, s = L.ground(ch.feet, 3, 8), sc()
		local yaw = ch.yaw or 0
		hide(true)
		local DUR = 14
		local S = L.screen(DUR)
		S.style, S.c1, S.c2 = "ninelives", C1, C2

		local sky = L.worldSky(o, DUR, { dome = rgb(52, 36, 84), atmC = rgb(120, 72, 118), decay = rgb(210, 120, 96), den = 0.3, haze = 0.35, glare = 0,
			oa = rgb(96, 70, 120), am = rgb(80, 60, 110), domeA = 0.9 })
		S.tintFn = function(t) return rgb(70, 36, 80), 0.14 * ss(t / 1.4) * (1 - ss((t - 12.0) / 1.8)) end
		local objs = {}
		for _, x in ipairs(sky.objs) do objs[#objs + 1] = x end
		local RL, RC = 6 * s, 4.7 * s
		local Ls, cats, wisps = {}, {}, {}
		for i, k in ipairs(ORDER) do
			local col = KINDS[k].col
			local a0 = yaw + (i - 1) / 9 * math.pi * 2
			local Lt = lantern(col, s)
			for _, p in ipairs(Lt.parts) do objs[#objs + 1] = p end
			Ls[i] = { Lt = Lt, a = a0, t0 = 0.9 + (i - 1) * 0.22, h = (4.3 + 0.5 * math.sin(i * 2.1)) * s, tp = 5.0 + (i - 1) * 0.36, popped = false }
			local cat = newCat(k, 1.7 * s, true)
			cat.fade(1)
			for _, p in ipairs(cat.list) do objs[#objs + 1] = p end
			local glow = L.new("PointLight", { Color = col:Lerp(C1, 0.3), Range = 4 * s, Brightness = 0, Shadows = false }, cat.list[1])
			cats[i] = { cat = cat, glow = glow, land = L.ground(o + V3(math.cos(a0), 0, math.sin(a0)) * RC, 3, 6), done = false }

			local wp = L.part()
			local w0 = L.new("Attachment", { Position = V3(0, 0.09 * s, 0) }, wp)
			local w1 = L.new("Attachment", { Position = V3(0, -0.09 * s, 0) }, wp)
			local tr = L.new("Trail", { Attachment0 = w0, Attachment1 = w1, Lifetime = 0.55, FaceCamera = true, MinLength = 0, Enabled = false, LightEmission = 1,
				Color = CS(col:Lerp(C1, 0.4), C1), Transparency = NS({ K(0, 0.05), K(0.6, 0.5), K(1, 1) }), WidthScale = NS({ K(0, 1), K(1, 0.2) }) }, wp)
			wisps[i] = { p = wp, tr = tr }
			objs[#objs + 1] = wp
		end
		local APEX = o + V3(0, 8.5 * s, 0)

		local B = newBox(s * 1.6)
		B.set(yawCF(o + V3(0, -60, 0), yaw), 0, 0, 1)
		for _, p in ipairs(B.parts) do objs[#objs + 1] = p end
		local BT = 10.05

		L.camTilt(DUR, function(tt)
			local rise = 1.6 * s * ss((tt - 9.2) / 1.2) * (1 - ss((tt - 11.4) / 1.4))
			local up = 0.16 * ss((tt - 9.3) / 0.8) * (1 - ss((tt - 10.3) / 0.55))
			return CFrame.new(0, rise, 0) * CFrame.Angles(up, 0, 0)
		end)
		L.timeline(DUR, function(t, once)
			if held and once("late", 0.4) then hide(true) end
			sky.set(ss(t / 1.6) * (1 - ss((t - 12.2) / 1.8)))

			for i, l in ipairs(Ls) do
				if t >= l.t0 and not l.popped then
					local u = t - l.t0
					local k = L.outQuad(c01(u / 2.4))
					local bob = math.sin(t * 1.6 + i) * 0.14 * s
					local p = o + V3(math.cos(l.a) * RL, 0.5 * s + (l.h - 0.5 * s) * k + bob, math.sin(l.a) * RL)
					local cf = CF(p) * A(math.sin(t * 1.1 + i) * 0.08, l.a + t * 0.25, math.sin(t * 1.3 + i * 2) * 0.08)
					local pk = c01((t - l.tp) / 0.14)
					l.Lt.set(cf, ss(u / 0.5) * (1 - pk), L.outQuad(pk))
					l.pos = p
					if pk >= 1 then
						l.popped = true
						l.Lt.set(cf, 0, 0)
						puff(p, 10, KINDS[ORDER[i]].col:Lerp(W, 0.4))
					end
				end
			end

			for i, c in ipairs(cats) do
				local l = Ls[i]
				if t >= l.tp then
					local u = t - l.tp
					local cat = c.cat
					local Q = { sway = math.sin(t * 2 + i) * 0.6, hy = 0, clock = t }
					local inYaw = flatYaw((o - c.land) * V3(1, 0, 1))
					local from = l.pos or (c.land + V3(0, 4 * s, 0))
					if u < 0.5 then
						local k = u / 0.5
						cat.fade(0)
						local spin = 1 - L.outQuad(c01(k / 0.8))
						local p = from:Lerp(c.land, k) * V3(1, 0, 1) + V3(0, from.Y + (c.land.Y - from.Y) * k * k, 0)
						place(cat, yawCF(p + V3(0, 0.7 * s, 0), inYaw) * A(0, 0, spin * math.pi) * CF(0, -0.7 * s, 0), { { "stand", 1 }, { "leap", 1 - c01((k - 0.7) / 0.3) } }, Q)
						c.glow.Brightness = 1.2
					else
						if not c.done then c.done = true puff(c.land + V3(0, 0.2, 0), 4, C2) end
						local v = u - 0.5
						local crouch = math.sin(c01(v / 0.3) * math.pi) * (1 - c01(v / 0.3))

						Q.hp = 0.65 * ss((t - 8.7) / 0.35)
						place(cat, yawCF(c.land, inYaw), { { "stand", 1 }, { "crouch", crouch }, { "sit", c01((v - 0.15) / 0.3) } }, Q)
						local out = ss((t - 12.2) / 0.8)
						cat.fade(out)
						c.glow.Brightness = (0.6 + 0.6 * ss((t - 8.7) / 0.4)) * (1 - out)
					end
				end
			end
			if once("call", 8.75) then
				for _, j in ipairs({ 1, 4, 7 }) do say(cats[j].land + V3(0, 1.8 * s, 0), "nya!", C1, 1.3) end
				for _, j in ipairs({ 2, 5, 8 }) do say(cats[j].land + V3(0, 1.6 * s, 0), meowText()) end
			end

			for i, w in ipairs(wisps) do
				local t0 = 8.95 + (i - 1) * 0.03
				if t >= t0 and t < t0 + 1.25 then
					local k = ss((t - t0) / 1.05)
					local c = cats[i]
					local tailP = c.cat.tail[#c.cat.tail]
					local base = (tailP and tailP.Parent and tailP.Position) or (c.land + V3(0, 0.5 * s, 0))
					local a = Ls[i].a + k * 3.4
					local r = RC * (1 - k) ^ 1.3
					local p = o + V3(math.cos(a) * r, 0, math.sin(a) * r)
					w.p.CFrame = CF(p.X, base.Y + (APEX.Y - base.Y) * k, p.Z)
					w.tr.Enabled = true
				else w.tr.Enabled = false end
			end
			if once("apex", BT) then puff(APEX, 18, C1) end
			if t >= BT then
				local u = t - BT
				local root
				if u < 0.25 then

					root = yawCF(APEX - V3(0, B.h / 2, 0), yaw + (0.25 - u) * 3)
				elseif u < 0.7 then
					local k = L.inQuad((u - 0.25) / 0.45)
					root = yawCF(APEX:Lerp(o + V3(0, B.h / 2, 0), k) - V3(0, B.h / 2, 0), yaw)
				else
					local v = u - 0.7
					local hop = math.abs(math.sin(v * 9)) * 0.3 * s * (1 - c01(v / 0.45)) ^ 2
					local w = math.sin(v * 22) * 0.1 * (1 - c01(v / 0.6))
					root = yawCF(o + V3(0, hop, 0), yaw) * A(w, 0, w * 0.6)
				end
				local al = (1 - ss(u / 0.25)) + ss((u - 2.1) / 0.9)
				B.set(root, L.outBack(c01((u - 1.1) / 0.25)), L.outQuad(c01((u - 1.3) / 0.45)), math.min(1, al))
				if once("thud", BT + 0.7) then
					puff(o + V3(0, 0.4, 0), 24, C2)
					L.groundWave(o, "ring_c.png", C1, RC * 0.8, RC * 2.4, 1.0, 2.2)
					S:shake(0.25, 0.3)
				end
			end
			if once("reveal", BT + 1.35) then
				hide(false)
				snapSitters()
				puff(o + V3(0, 1.5 * s, 0), 14, C1)
				say(ch.pos + V3(0, 3 * s, 0), "nya!", C1, 1.3)
			end
			if once("card", BT + 1.65) then S:title(L.name(), C1, C2) end
		end, objs, function() hide(false) sky.release() end)
	end


	local lookAt = nil
	local panicT = nil
	local furGone = false
	local deathGone = nil
	local function ghostCat(kind, u)
		local g = newCat(kind, u, true)
		for _, p in ipairs(g.list) do p.Material = Enum.Material.ForceField p.Color = KINDS[kind].col:Lerp(rgb(220, 235, 255), 0.5) end
		g.fade(1)
		return g
	end

	local function clawTally(pos, n, yaw)
		local s = sc()
		local W2 = n * 0.55 + 0.4
		local p = L.part({ Size = V3(W2 * s, 0.05, 1.3 * s) })
		p.CFrame = CF(L.ground(pos, 3, 6) + V3(0, 0.05, 0)) * A(0, yaw, 0)
		local sg = L.new("SurfaceGui", { Face = Enum.NormalId.Top, LightInfluence = 1, CanvasSize = Vector2.new(math.floor(64 * W2), 83), AlwaysOnTop = false }, p)
		local lines = {}
		for i = 1, n do
			for j = 1, 3 do
				local ln = L.new("Frame", { BorderSizePixel = 0, BackgroundColor3 = rgb(58, 40, 32), BackgroundTransparency = 1, AnchorPoint = Vector2.new(0.5, 0.5),
					Position = UDim2.fromScale(((i - 1) * 0.55 + 0.35 + (j - 2) * 0.11) / W2, 0.5), Size = UDim2.fromScale(0.05 / W2, 0), Rotation = 18 }, sg)
				L.new("UICorner", { CornerRadius = UDim.new(0.5, 0) }, ln)
				lines[#lines + 1] = { f = ln, t0 = 1.25 + (i - 1) * 0.12 + j * 0.03, i = i }
			end
		end
		L.fx(22, function(_, t)
			local fade = ss((t - 16) / 6)
			for _, l in ipairs(lines) do
				local k = L.outQuad(c01((t - l.t0) / 0.14))
				if k > 0 and not l.sp and l.i == n then l.sp = true puff(p.Position + V3(0, 0.15, 0), 1, rgb(120, 96, 80)) end
				l.f.Size = UDim2.fromScale(0.05 / W2, 0.8 * k)
				l.f.BackgroundTransparency = k > 0 and 0.15 + 0.85 * fade or 1
			end
		end, { p })
	end
	local function setDown(on) if tag.bb then pcall(function() tag.bb:SetAttribute("NLDown", on) end) end end
	local function death(preview)
		if not ch.char then return end
		local s = sc()
		local pos = L.ground(ch.feet or ch.pos, 3, 8)
		local top = (ch.torso and ch.torso.Parent and ch.torso.Position) or pos + V3(0, 2.5 * s, 0)
		local lost = math.max(1, lives)
		setLives(math.max(0, lives - 1))
		setDown(true)
		clawTally(pos + L.facing() * 1.8 * s, 9 - lives, ch.yaw or 0)
		local final = lives == 0
		lookAt, panicT = top, 0
		local gone = {}
		deathGone = gone

		local ghosts = {}
		if final then for i, k in ipairs(ORDER) do ghosts[i] = ghostCat(k, 1.3 * s) end
		else ghosts[1] = ghostCat(ORDER[lost], 1.6 * s) end
		local gl = {}
		for _, g in ipairs(ghosts) do for _, p in ipairs(g.list) do gl[#gl + 1] = p end end
		L.timeline(final and 4.8 or 4.5, function(t, once)

			if once("flash", 0.05) then L.ghost(C2:Lerp(W, 0.5), Enum.Material.ForceField, 1.2) end

			if once("fur", 1.2) then
				for d in pairs(L.bodyParts()) do gone[d] = true d.LocalTransparencyModifier = 1 end
				furGone = true
				puff(top, final and 40 or 26, C2:Lerp(KINDS.tabby.col, 0.3))
				say(top + V3(0, 1 * s, 0), "...")
			end
			if once("count", 2.0) then say(top + V3(0, 2.4 * s, 0), final and "0 lives left" or (lives .. (lives == 1 and " life left" or " lives left")), C1, 1.3) end

			if t > 1.3 then
				local life = final and 3.4 or 3.1
				local u = c01((t - 1.3) / life)
				for i, g in ipairs(ghosts) do
					g.fade(0.25 + 0.75 * ss((u - 0.55) / 0.45))
					local Q = { sway = math.sin(t * 5 + i) * 0.8, hy = math.sin(t * 3 + i) * 0.3 }
					if final then
						local ue = ss(u) local a = (i - 1) / 9 * math.pi * 2 + ue * 5
						local r = (1.2 + 1.4 * L.outQuad(u)) * s
						local p = top + V3(math.cos(a) * r, (0.6 * u + 0.4 * ue) * 8 * s, math.sin(a) * r)
						place(g, yawCF(p, flatYaw(V3(-math.sin(a), 0, math.cos(a)))), { { "stand", 1 }, { "leap", 0.6 } }, Q)
					else
						place(g, yawCF(top + V3(math.sin(u * 6) * 0.4 * s, u * 6 * s, 0), (ch.yaw or 0) + u), { { "stand", 1 }, { "sit", 0.7 } }, Q)
					end
				end
			end
		end, gl, function()
			lookAt, panicT = nil, nil
			furGone = false
			if deathGone == gone then deathGone = nil end
			if preview then
				for d in pairs(gone) do if d.Parent then pcall(function() d.LocalTransparencyModifier = 0 end) end end
				if lives == 0 then setLives(9) end
				setDown(false)
			end
		end)

		local f, r = L.facing()
		local seat = L.ground(pos + (r * 1.6 + f * 0.6) * s, 3, 6)
		local mourner = newCat("grey", 1.7 * s, true)
		local mYaw = flatYaw((pos - seat) * V3(1, 0, 1))
		local away = (seat - pos) * V3(1, 0, 1)
		away = away.Magnitude > 0.01 and away.Unit or r
		mourner.fade(1)
		local said = false
		L.fx(10, function(_, t)
			if t < 1.3 then return end
			mourner.fade(0)
			local Q = { sway = math.sin(t * 1.5) * 0.5, hy = 0, hp = 0.15 }
			if t < 8.4 then
				if not said and t > 2 then said = true meow(mourner, seat + V3(0, 1.2 * s, 0), "mew") end
				place(mourner, yawCF(seat, mYaw), { { "stand", 1 }, { "sit", 1 } }, Q)
			else
				local u = t - 8.4
				Q.walk = u * 17
				place(mourner, yawCF(L.ground(seat + away * u * 4 * s, 3, 6), flatYaw(away)), { { "stand", 1 } }, Q)
				mourner.fade(ss((u - 0.8) / 0.8))
			end
		end, mourner.list)
	end


	local dropGift
	local age, travel, side, lastPos, wasSwim = 0, 0, 1, nil, false
	local idleT, sleepy, huntCD = 0, false, 2
	local fallT, fallSaid, falling, running = 0, false, false, false
	local stampN, lastSt = 0, nil
	local movedT, rubCD, giftT = 0, 6, rnd(50, 80)

	dropGift = function(p, yaw)
		local s = sc()
		p = L.ground(p, 3, 6)
		local objs = {}
		if math.random() < 0.5 then
			local body = L.part({ Size = V3(0.18, 0.2, 0.5) * s, Color = rgb(150, 182, 210), Material = SMOOTH, Transparency = 0 })
			L.new("SpecialMesh", { MeshType = Enum.MeshType.Sphere }, body)
			local cf = CF(p + V3(0, 0.09 * s, 0)) * A(0, yaw + R90, R90)
			body.CFrame = cf
			local tail = wedge(V3(0.03, 0.2, 0.16) * s, rgb(120, 150, 185))
			tail.CFrame = cf * CF(0, 0, 0.3 * s) * A(0, R90, 0)
			local eye = L.part({ Size = V3(0.05, 0.05, 0.05) * s, Color = BLK, Material = SMOOTH, Transparency = 0 })
			L.new("SpecialMesh", { MeshType = Enum.MeshType.Sphere }, eye)
			eye.CFrame = cf * CF(0.08 * s, 0.04 * s, -0.17 * s)
			objs = { body, tail, eye }
		else
			local ball = L.part({ Shape = Enum.PartType.Ball, Size = Vector3.one * 0.42 * s, Color = rgb(235, 95, 120), Material = Enum.Material.Fabric, Transparency = 0 })
			ball.CFrame = CF(p + V3(0, 0.21 * s, 0)) * A(0.4, yaw, 0.3)
			objs = { ball }
		end
		puff(p + V3(0, 0.2, 0), 5, C1)
		L.fx(5, function(_, t) local a = c01((t - 4) / 1) for _, o in ipairs(objs) do o.Transparency = a end end, objs)
	end
	local function stepDot(dt, s)
		local want = idleT > 3 and idleT < 9.5 and not ch.dead and not ch.swim and not ch.sit and not furGone and not ch.on
		dot.a += ((want and 1 or 0) - dot.a) * c01(dt * 4)
		if dot.a < 0.01 then dot.pos = nil dotP.Transparency, dotG.ImageTransparency = 1, 1 return end
		local f, r = L.facing()
		if not dot.pos then dot.pos = L.ground(ch.feet + f * 3 * s, 3, 6) dot.goal = nil end
		if not dot.goal then dot.goal = L.ground(ch.feet + (f * rnd(2, 5.5) + r * rnd(-4.5, 4.5)) * s, 3, 6) dot.spd = rnd(3, 8) * s end
		local v = dot.goal - dot.pos
		if v.Magnitude < 0.1 then
			dot.wait -= dt
			if dot.wait <= 0 then dot.goal = nil dot.wait = rnd(0.2, 1.1) end
		else
			dot.pos += v.Unit * math.min(v.Magnitude, dot.spd * dt)
		end
		local jit = V3(math.noise(age * 3, 1) * 0.06, 0, math.noise(age * 3, 2) * 0.06) * s
		dotP.CFrame = CF(dot.pos + jit + V3(0, 0.08, 0))
		dotP.Transparency = 1 - dot.a
		dotG.ImageTransparency = 1 - (0.5 + 0.15 * math.sin(age * 20)) * dot.a
	end



	local NLX = { UIS = game:GetService("UserInputService"), beat = 0, hop = 0, cheer = false, PURR = { "purr", "prrt", "mrrp" },
		PH = { dance = "PURRFECT!", spin = "ZOOMIES!", cheer = "MEOW!", low = "POUNCE!", pose = "PURR...", sway = "MRRP~" }, ANY = { "NYA!", "MEOW!", "MRROW!" } }
	function NLX.targets()
		local t = {}
		for _, sv in ipairs(sitters) do if not sv.hidden then t[#t + 1] = { cat = sv.cat, q = sv } end end
		return t
	end
	function NLX.hit(p2)
		local cam = workspace.CurrentCamera
		if not cam then return end
		local best, bd
		for _, tg in ipairs(NLX.targets()) do
			local b = tg.cat.list and tg.cat.list[1]
			if b and b.Parent then
				local v = cam:WorldToScreenPoint(b.Position)
				if v.Z > 0 then
					local px = cam.ViewportSize.Y / (2 * math.tan(math.rad(cam.FieldOfView) / 2) * v.Z)
					local d = (Vector2.new(v.X, v.Y) - p2).Magnitude
					if d < math.max(32, px * 1.3 * sc()) and (not bd or d < bd) then best, bd = tg, d end
				end
			end
		end
		return best
	end
	L.conns = L.conns or {}
	table.insert(L.conns, NLX.UIS.InputBegan:Connect(function(io, gp)
		if gp or (io.UserInputType ~= Enum.UserInputType.MouseButton1 and io.UserInputType ~= Enum.UserInputType.Touch) then return end
		local tg = NLX.hit(Vector2.new(io.Position.X, io.Position.Y))
		if not tg or ch.dead then return end
		local q = tg.q
		q.petT, q.hold, q.purrT = 0, { io = io, t0 = os.clock() }, 0
		local b = tg.cat.list[1]
		meow(tg.cat, b.Position + V3(0, 0.9 * sc(), 0), NLX.PURR[math.random(1, #NLX.PURR)], C1)
	end))
	table.insert(L.conns, NLX.UIS.InputEnded:Connect(function(io)
		for _, tg in ipairs(NLX.targets()) do
			local h = tg.q.hold
			if h and (h.io == io or (io.UserInputType == Enum.UserInputType.MouseButton1 and h.io.UserInputType == io.UserInputType)) then tg.q.hold = nil tg.q.squint = nil end
		end
	end))
	function NLX.step(dt, s, dead)
		L.motion(dt, s, dead, NLX.PH, NLX.ANY)
		if (ch.sBeat or 0) ~= NLX.beat then NLX.beat, NLX.hop = ch.sBeat or 0, 1 end
		NLX.hop = math.max(0, NLX.hop - dt * 4)
		local cheer = ch.mCur == "cheer"
		if cheer and not NLX.cheer and not dead then
			for _, tg in ipairs(NLX.targets()) do local b = tg.cat.list[1] if b then meow(tg.cat, b.Position + V3(0, 1.1 * s, 0), "MEOW!", C1, true) end end
		end
		NLX.cheer = cheer
		for _, tg in ipairs(NLX.targets()) do
			local q = tg.q
			if q.petT then q.petT += dt if q.petT > 0.5 then q.petT = nil end end
			if q.hold and os.clock() - q.hold.t0 > 0.45 then
				q.squint = true
				q.purrT = (q.purrT or 0) - dt
				if q.purrT <= 0 then
					q.purrT = 1.3
					local b = tg.cat.list[1]
					if b then
						say(b.Position + V3(0, 1 * s, 0), "purrrr~", C1)
						for _, fl in ipairs(floaters) do if fl.t >= fl.life then fl.t, fl.from = 0, b.Position + V3(rnd(-0.4, 0.4), 0.2, rnd(-0.4, 0.4)) * 1 break end end
					end
				end
			end
		end
	end

	function NLX.extra(q, s, dt)
		local w = q.petT and math.sin(q.petT * 30) * (1 - q.petT / 0.5) * 0.25 or 0
		local hop = math.sin(NLX.hop * math.pi) * 0.35 * s
		q.twirl = (q.twirl or 0) + ((ch.mCur == "spin") and dt * 7 or 0)
		return w, hop
	end



	local NLR = { airT = 0 }
	function NLR.near()
		local best, bd
		for _, sv in ipairs(sitters) do
			if not sv.hidden and sv.pos then
				local d = ((sv.pos - ch.feet) * V3(1, 0, 1)).Magnitude
				if not bd or d < bd then best, bd = sv, d end
			end
		end
		return best
	end
	function NLR.step(dt, s, swim, dead, falling)
		if ch.air then NLR.airT += dt end
		if not dead and not furGone and ch.feet then
			if ch.jumped then
				spiritT = 0
				for _, sv in ipairs(sitters) do if not sv.hidden and sv.wl < 0.5 then sv.cj = 0.5 + (sv.side > 0 and 0.12 or 0) end end
				local sv = NLR.near()
				if sv then say(sv.pos + V3(0, 1.4 * s, 0), "!", C1) end
			end
			if falling and not fallSaid and fallT > 0.6 then
				fallSaid = true
				local sv = NLR.near()
				if sv then meow(sv.cat, sv.pos + V3(0, 1.5 * s, 0), "MROWW", C1) end
			end
			if ch.landed then
				landT = 0
				landP.CFrame = CF(L.ground(ch.feet, 2, 4) + V3(0, 0.05, 0)) * A(0, ch.yaw or 0, 0) * PF
				puff(ch.feet + V3(0, 0.3, 0), 6, C2)
				local hard = NLR.airT > 1
				if hard then for _, sv in ipairs(sitters) do if not sv.hidden and (sv.mode == "sit" or sv.mode == "trot") then sv.mode, sv.mt, sv.sniff = "check", 0, nil end end end
				local sv = NLR.near()
				if sv then meow(sv.cat, sv.pos + V3(0, 1.4 * s, 0), hard and "mrrp?!" or "mrow") end
			end
			if swim and not wasSwim then
				local sv = NLR.near()
				if sv then say(sv.pos + V3(0, 1.4 * s, 0), "HISS", rgb(255, 120, 90)) end
			end
		end
		if not ch.air then NLR.airT = 0 end
	end
	local function stepSitter(sv, dt, s, emote)
		local cat = sv.cat

		if ch.swim then
			if not sv.hidden then sv.hidden = true puff(sv.pos or ch.feet, 10, C2) end
			cat.show(false)
			return
		end
		if sv.hidden then sv.hidden = false sv.pos = spotOf(sv) puff(sv.pos + V3(0, 0.5, 0), 10, C2) end
		local hrp = ch.hrp
		if ch.sit and ch.spd > 4 * s and hrp and hrp.Parent and not ch.dead then
			local hcf = hrp.CFrame
			local p = (hcf * CF(sv.side * 1.5 * s, 0, 0.5 * s)).Position
			p = V3(p.X, hrp.Position.Y - 1.6 * s, p.Z)
			if not sv.riding then sv.riding = true puff((sv.pos or p) + V3(0, 0.5, 0), 6, C2) puff(p + V3(0, 0.5, 0), 6, C2) meow(cat, p + V3(0, 1.4 * s, 0), "mrrp!") end
			cat.show(true)
			sv.pos, sv.mode, sv.spd = p, "sit", 0
			sv.yaw = flatYaw(hcf.LookVector * V3(1, 0, 1))
			place(cat, yawCF(p, sv.yaw) * A(0, 0, math.sin(age * 9 + sv.side) * 0.03), { { "stand", 1 }, { "sit", 1 } },
				{ hy = math.sin(age * 0.9 + sv.side * 2) * 0.7, sway = math.sin(age * 3 + sv.side) * 0.7, clock = age, pupil = 0.4 })
			return
		elseif sv.riding then
			sv.riding = false
			sv.pos = spotOf(sv)
			puff(sv.pos + V3(0, 0.5, 0), 8, C2)
		end
		cat.show(true)
		local goal = spotOf(sv)
		sv.pos = sv.pos or goal
		local flat = (goal - sv.pos) * V3(1, 0, 1)
		local d = flat.Magnitude
		if d > 40 * s then sv.pos = goal d = 0 flat = Vector3.zero sv.mode = "sit" end
		local ownerFar = ((ch.feet - sv.pos) * V3(1, 0, 1)).Magnitude
		local hunting = sv.mode == "stalk" or sv.mode == "pounce" or sv.mode == "rest"
		if hunting and (ch.on or ch.dead or dot.a < 0.5) and sv.mode ~= "pounce" then sv.mode = "trot" hunting = false end
		if sv.mode == "sit" and not ch.dead and (ownerFar > 8.5 * s or (ch.on and d > 2.5 * s)) then sv.mode = "trot" end

		if sv.mode == "sit" and dot.pos and dot.a > 0.8 and huntCD <= 0 and not sleepy and not panicT and math.random() < dt * 0.5 then
			sv.mode, sv.mt, huntCD = "stalk", 1.0, rnd(3, 6)
		end
		local wig = 0
		if sv.mode == "stalk" then
			sv.mt -= dt
			wig = age * 16
			local v = ((dot.pos or sv.pos) - sv.pos) * V3(1, 0, 1)
			if v.Magnitude > 0.1 then sv.yaw += ((flatYaw(v) - sv.yaw + math.pi) % (2 * math.pi) - math.pi) * c01(dt * 6) end
			if sv.mt <= 0 and dot.pos then sv.mode, sv.mt, sv.p0, sv.p1 = "pounce", 0.45, sv.pos, dot.pos end
		elseif sv.mode == "pounce" then
			sv.mt -= dt
			local k = 1 - c01(sv.mt / 0.45)
			local v = (sv.p1 - sv.p0) * V3(1, 0, 1)
			if v.Magnitude > 0.1 then sv.yaw = flatYaw(v) end
			sv.pos = sv.p0:Lerp(sv.p1, k)
			if sv.mt <= 0 then
				sv.mode, sv.mt = "rest", 1.1
				local f, r = L.facing()
				dot.goal, dot.spd, dot.wait = L.ground(ch.feet + (f * rnd(3, 6) + r * rnd(-5, 5)) * s, 3, 6), 26 * s, 0.6
				if math.random() < 0.7 then meow(cat, sv.pos + V3(0, 1.1 * s, 0), math.random() < 0.5 and "mrrp!" or "!") end
			end
		elseif sv.mode == "rest" then
			sv.mt -= dt
			if sv.mt <= 0 then sv.mode = "trot" end
		elseif sv.mode == "rub" then

			sv.mt += dt
			local f, r = L.facing()
			local function rp(a) return ch.feet + (f * math.cos(a) + r * sv.side * math.sin(a)) * 0.95 * s end
			local a = math.rad(25 + 130 * c01((sv.mt - 0.5) / 1.6))
			local p = rp(a)
			local dir = sv.mt < 0.5 and (p - sv.pos) or (rp(a + 0.1) - p)
			if sv.mt < 0.5 then sv.pos = sv.pos:Lerp(p, c01(dt * 10)) else sv.pos = p end
			dir *= V3(1, 0, 1)
			if dir.Magnitude > 0.01 then sv.yaw = flatYaw(dir) end
			sv.walk += dt * 9
			if sv.mt > 0.5 and not sv.purr then sv.purr = true say(p + V3(0, 1.2 * s, 0), "prrr", PINK) end
			if sv.mt > 2.2 or ch.on then sv.mode, sv.purr = "trot", nil end
		elseif sv.mode == "gift" then

			sv.mt += dt
			local v = (sv.giftP - sv.pos) * V3(1, 0, 1)
			if not sv.dropped then
				if v.Magnitude > 0.2 * s then
					sv.pos += v.Unit * math.min(v.Magnitude, 6 * s * dt)
					sv.yaw = flatYaw(v)
					sv.walk += dt * 6 * s * 4 / cat.u
				else
					sv.dropped, sv.mt = true, 0
					local tw = (ch.feet - sv.pos) * V3(1, 0, 1)
					if tw.Magnitude > 0.1 then sv.yaw = flatYaw(tw) end
					dropGift(sv.pos + (tw.Magnitude > 0.1 and tw.Unit or V3(0, 0, -1)) * 0.6 * s, sv.yaw)
					meow(cat, sv.pos + V3(0, 1.3 * s, 0), "mrrp!", C1)
				end
				if sv.mt > 6 then sv.mode = "trot" end
			elseif sv.mt > 1.8 or ch.on then sv.mode, sv.dropped = "trot", nil end
		elseif sv.mode == "check" then

			sv.mt += dt
			local away = (sv.pos - ch.feet) * V3(1, 0, 1)
			local tgt = ch.feet + (away.Magnitude > 0.1 and away.Unit or V3(sv.side, 0, 0)) * 1.4 * s
			local v = (tgt - sv.pos) * V3(1, 0, 1)
			if not sv.sniff and v.Magnitude > 0.25 * s and sv.mt < 2.5 then
				sv.pos += v.Unit * math.min(v.Magnitude, 16 * s * dt)
				sv.yaw = flatYaw(v)
				sv.walk += dt * math.min(16 * s * 4 / cat.u, 48)
			elseif not sv.sniff then
				sv.sniff = sv.mt
				say(sv.pos + V3(0, 1.3 * s, 0), "sniff sniff", PINK)
			end
			if (sv.sniff and sv.mt - sv.sniff > 1.6) or sv.mt > 4 or ch.on then sv.mode, sv.sniff = "trot", nil end
		elseif sv.mode == "trot" then
			if d < 0.5 * s then if not ch.on then sv.mode, sv.spd = "sit", 0 end
			else
				local want = math.max(ch.spd * 1.15, 9 * s)
				sv.spd = (sv.spd or 0) + (want - (sv.spd or 0)) * c01(dt * 5)
				local spd = math.max(sv.spd, 2 * s)
				sv.pos += flat.Unit * math.min(d, spd * dt)
				sv.yaw += ((flatYaw(flat) - sv.yaw + math.pi) % (2 * math.pi) - math.pi) * c01(dt * 10)
				sv.walk += dt * math.min(spd * 4 / cat.u, 48) * (1 - 0.45 * (sv.bk or 0))
			end
		end
		sv.gyT -= dt
		if sv.gyT <= 0 or not sv.gy then sv.gyT = 0.15 sv.gy = L.ground(sv.pos, 4, 10).Y end
		local lift = 0
		if sv.mode == "pounce" then lift = math.sin((1 - c01(sv.mt / 0.45)) * math.pi) * 1.1 * s end

		local hopK = nil
		if sv.cj then sv.cj -= dt if sv.cj <= 0 then sv.cj = nil elseif sv.cj < 0.5 then hopK = 1 - sv.cj / 0.5 lift += math.sin(hopK * math.pi) * 0.75 * s end end
		sv.fk = (sv.fk or 0) + ((falling and 1 or 0) - (sv.fk or 0)) * c01(dt * 8)
		sv.pos = V3(sv.pos.X, sv.gy, sv.pos.Z)
		local sitting = sv.mode == "sit" or sv.mode == "rest" or (sv.mode == "gift" and sv.dropped == true) or (sv.mode == "check" and sv.sniff ~= nil)
		local wst = 0
		if sv.stretch then
			sv.stretch -= dt
			wst = math.sin(c01(1 - sv.stretch / 1.8) * math.pi)
			if sv.stretch <= 0 then sv.stretch = nil end
		end
		local ease = c01(dt * 8)
		sv.ws += ((sitting and 1 or 0) - sv.ws) * ease
		sv.wc += ((sv.mode == "stalk" and 1 or 0) - sv.wc) * ease
		sv.wj += (((sv.mode == "pounce" or hopK) and 1 or 0) - sv.wj) * c01(dt * 14)
		sv.wl += (((sitting and (ch.sit or sleepy)) and 1 or 0) - sv.wl) * c01(dt * 1.1)

		local wh, stare = 0, 0
		if panicT then
			wh = c01(panicT / 0.15) * (1 - c01((panicT - 1.2) / 0.3))
			stare = c01((panicT - 1.3) / 0.4)
		end

		local toOwner = (ch.feet - sv.pos) * V3(1, 0, 1)
		if sitting and toOwner.Magnitude > 0.1 then
			local want = flatYaw(toOwner) + sv.side * 0.5
			sv.yaw += ((want - sv.yaw + math.pi) % (2 * math.pi) - math.pi) * c01(dt * 2)
		end
		sv.hyT -= dt
		if sv.hyT <= 0 then sv.hyT = rnd(1.5, 4) sv.hyGoal = rnd(-0.9, 0.9) end
		local hyGoal = sv.hyGoal
		local up = (ch.climb == true or falling or (sv.mode == "check" and sv.sniff ~= nil)) and not lookAt
		local look = lookAt or ((up and ch.head and ch.head.Parent) and ch.head.Position) or ((sv.mode == "sit" and dot.pos and dot.a > 0.5) and dot.pos) or nil
		if look then
			local v = (look - sv.pos) * V3(1, 0, 1)
			if v.Magnitude > 0.1 then hyGoal = ((flatYaw(v) - sv.yaw + math.pi) % (2 * math.pi) - math.pi) end
			hyGoal = math.clamp(hyGoal, -1.3, 1.3)
		end
		if sv.mode == "stalk" or sv.mode == "pounce" then hyGoal = 0 end
		sv.hy += (hyGoal - sv.hy) * c01(dt * 4)
		sv.lickT -= dt
		if sv.lickT <= 0 and sitting and sv.wl < 0.5 and not panicT then sv.lickT = rnd(5, 10) sv.lick = 1.6 end
		sv.lick = math.max(0, sv.lick - dt)
		local lk = sv.lick > 0 and math.sin(sv.lick / 1.6 * math.pi) or 0
		sv.blinkT -= dt
		if sv.blinkT <= -0.12 then sv.blinkT = (math.random() < 0.2) and 0.14 or rnd(2, 5.5) end
		sv.meowT -= dt * (emote and 3 or 1)
		if sv.meowT <= 0 and not ch.dead and not panicT then
			sv.meowT = rnd(6, 14)
			if sv.wl > 0.5 then say(sv.pos + V3(0, 1.5 * s, 0), "zzz") else meow(cat, sv.pos + V3(0, 1.5 * s, 0), meowText()) end
		end
		if panicT and not sv.hissed then sv.hissed = true meow(cat, sv.pos + V3(0, 1.4 * s, 0), "HSSS", rgb(255, 120, 90)) end
		if not panicT then sv.hissed = nil end
		sv.bk = (sv.bk or 0) + (((running and sv.mode == "trot") and 1 or 0) - (sv.bk or 0)) * c01(dt * 5)
		lift += sv.bk * math.abs(math.sin(sv.walk * 0.5)) * 0.35 * s
		local bob = emote and math.abs(math.sin(age * 7 + sv.side)) * 0.25 * s or 0
		local sway2 = emote and math.sin(age * 3.5) or 0
		local pw, hop = NLX.extra(sv, s, dt)
		if ch.mCur ~= "spin" then sv.twirl = (sv.twirl or 0) * (1 - c01(dt * 3)) end
		place(cat, yawCF(sv.pos + V3(0, bob + lift + hop, 0) + A(0, sv.yaw, 0).RightVector * sway2 * 0.25 * s, sv.yaw + sway2 * 0.3 + pw + (sv.twirl or 0)),
			{ { "stand", 1 }, { "sit", sv.ws * (1 - wh) }, { "sleep", sv.wl * (1 - wh) }, { "crouch", sv.wc }, { "leap", math.max(sv.wj, sv.bk * (0.5 + 0.5 * math.sin(sv.walk * 0.5 + 1.2))) }, { "hiss", wh }, { "stretch", wst } },
			{ hy = sv.hy * (1 - sv.wl), hp = 0.6 * stare + ((sv.mode == "gift" and sv.dropped) and 0.3 or 0) + (up and 0.55 or 0), hissing = wh > 0.3, sway = math.sin(age * ((sitting and 1.3) or (sv.mode == "stalk" and 9) or 6) + sv.side) * 0.6,
				walk = (sv.mode == "trot" or sv.mode == "rub" or (sv.mode == "gift" and not sv.dropped) or (sv.mode == "check" and not sv.sniff)) and sv.walk or nil, lick = lk, blink = sv.squint or sv.blinkT < 0 or sv.wl > 0.5 or wst > 0.5, clock = age, wig = wig, tw = 1 - 0.85 * sv.wl,
				stride = math.max(sv.bk, sv.mode == "trot" and c01((sv.spd or 0) / cat.u / 10) or 0),
				earFlat = math.max(wh, 0.7 * sv.fk), puff = 1 + 0.4 * math.max(wh, sv.fk), pupil = math.max((sv.mode == "stalk" or sv.mode == "pounce") and 1 or (wh > 0 and 0.8 or 0), sv.fk) })
	end
	local function step(dt)
		age += dt
		huntCD -= dt
		if panicT then panicT += dt end
		local s, on, swim, sit, dead, emote = sc(), ch.on, ch.swim == true, ch.sit == true, ch.dead == true, ch.emote == true
		NLX.step(dt, s, dead)
		emote = emote or ch.mOn == true

		if ch.iw > 0.5 and not on and not ch.air and not swim and not dead and not sit then idleT += dt else
			if sleepy and not dead then for _, sv in ipairs(sitters) do meow(sv.cat, sv.pos + V3(0, 1.1 * s, 0), "mrrp?") sv.stretch = 1.8 end end
			idleT = 0
		end
		sleepy = idleT > 10
		if ch.air and ch.vel and ch.vel.Y < -6 then fallT += dt else fallT, fallSaid = 0, false end
		falling = fallT > 0.35
		running = on and ch.spd > 19 * s

		rubCD -= dt
		if on then movedT += dt else
			if movedT > 1.5 and rubCD <= 0 and not dead and not swim and not panicT then
				local sv = sitters[math.random(1, #sitters)]
				if sv.mode == "sit" or sv.mode == "trot" then sv.mode, sv.mt, rubCD = "rub", 0, rnd(15, 25) end
			end
			movedT = 0
		end

		giftT -= dt
		if giftT <= 0 and not on and not dead and not swim and not sleepy and not panicT and dot.a < 0.1 then
			local sv = sitters[math.random(1, #sitters)]
			if sv.mode == "sit" then
				local f, r = L.facing()
				sv.mode, sv.mt, sv.dropped = "gift", 0, nil
				sv.giftP = ch.feet + (f * 1.8 + r * sv.side * 0.5) * s
				giftT = rnd(70, 120)
			end
		end
		stepDot(dt, s)

		NLR.step(dt, s, swim, dead, falling)
		wasSwim = swim

		for _, sv in ipairs(sitters) do stepSitter(sv, dt, s, emote) end

		if lastPos and on and not swim and not ch.air and not dead then
			travel += ((ch.pos - lastPos) * V3(1, 0, 1)).Magnitude
			if travel >= (running and 2.9 or 1.7) * s then
				travel = 0
				side = -side
				stampN += 1
				stamp(L.ground(ch.feet + ch.hrp.CFrame.RightVector * side * 0.35 * s, 2, 4), ch.yaw or 0, KINDS[ORDER[(stampN % math.max(1, lives)) + 1]].col)
			end
		end
		lastPos = ch.pos
		for _, pr in ipairs(prints) do
			pr.t += dt
			if pr.t < 1.6 then
				local pk = c01(pr.t / 0.12)
				pr.g.GroupTransparency = 1 - 0.8 * pk * (1 - L.outQuad(c01((pr.t - 0.3) / 1.3)))
				pr.g.Size = UDim2.fromScale(1 + 0.3 * (1 - pk), 1 + 0.3 * (1 - pk))
			elseif pr.g.GroupTransparency < 1 then pr.g.GroupTransparency = 1 end
		end

		floatT -= dt
		if floatT <= 0 and ch.iw > 0.5 and not dead and not swim and not sleepy then
			floatT = rnd(0.8, 1.6)
			for _, fl in ipairs(floaters) do
				if fl.t >= fl.life then
					local a = rnd(0, 6.3)
					fl.t, fl.from = 0, ch.pos + V3(math.cos(a) * 1.6 * s, rnd(-1.5, 0.5) * s, math.sin(a) * 1.6 * s)
					break
				end
			end
		end
		for _, fl in ipairs(floaters) do
			fl.t += dt
			if fl.t < fl.life and fl.from then
				local k = fl.t / fl.life
				fl.a.CFrame = CF(fl.from + V3(0, 1.4 * s * k, 0))
				local al = math.sin(k * math.pi)
				fl.g.GroupTransparency = 1 - 0.8 * al
				fl.glow.ImageTransparency = 1 - 0.35 * al
			else fl.g.GroupTransparency, fl.glow.ImageTransparency = 1, 1 end
		end

		if spiritT then
			spiritT += dt
			local k = spiritT / 0.7
			if k >= 1 or dead or not (ch.hrp and ch.hrp.Parent) then spiritT = nil spirit.fade(1)
			else
				spirit.fade(0.3 + 0.7 * L.inQuad(k))
				place(spirit, yawCF(ch.pos + V3(0, (ch.fy or -3) + 1.0 * s + math.sin(k * math.pi) * 0.6 * s, 0), ch.yaw or 0) * A(0.3 - 0.6 * k, 0, 0), { { "stand", 1 }, { "leap", 1 } }, { sway = 0 })
			end
		end
		landT += dt
		landG.GroupTransparency = landT > 1.3 and 1 or 1 - 0.6 * c01(landT / 0.06) * (1 - c01((landT - 0.2) / 1))

		noteT -= dt
		if emote and not dead and noteT <= 0 then
			noteT = 0.35
			local srcs = {}
			for _, sv in ipairs(sitters) do if not sv.hidden then srcs[#srcs + 1] = sv.cat.list[1] end end
			for _, n in ipairs(notes) do
				if n.t >= 1.6 then
					local src = srcs[math.random(1, #srcs)]
					n.t, n.from, n.dx = 0, src.Position + V3(0, 0.7 * s, 0), rnd(-1, 1)
					break
				end
			end
		end
		for _, n in ipairs(notes) do
			n.t += dt
			if n.t < 1.6 and n.from then
				local k = n.t / 1.6
				n.a.CFrame = CF(n.from + V3(math.sin(n.t * 4) * 0.3 * s + n.dx * n.t * 0.3, 1.6 * k * s, 0))
				n.g.GroupTransparency = 1 - math.sin(k * math.pi) * 0.9
			else n.g.GroupTransparency = 1 end
		end
		local st = (emote and "emote") or ((ch.air and NLR.airT > 0.15) and "jump") or ((on and ch.spd > 1) and "walk") or "idle"
		if st ~= lastSt and tag.bb then lastSt = st pcall(function() tag.bb:SetAttribute("NLState", st) end) end

		envT -= dt
		if envT <= 0 then
			envT = 2
			local ct = game:GetService("Lighting").ClockTime
			local nightK = math.max(1 - ss((ct - 5.6) / 1.4), ss((ct - 17.0) / 1.4))
			fireE.Rate, fluffE.Rate = 2 + 5 * nightK, 2
		end
		local envOn = not dead and not swim and not held and ch.feet ~= nil
		fireE.Enabled, fluffE.Enabled = envOn, envOn
		if envOn then envP.CFrame = CF(ch.feet + V3(0, 1.6 * s, 0)) end
		tag.step(dt)
	end

	local function rebind()
		lastPos = nil
		idleT = 0
		setDown(false)

		snapSitters()
	end

	return {

		arrive = function(short)
			if short then if lives <= 0 then shortPile(true) else shorts[math.random(1, #shorts)]() end
			else arriveFull() end
		end,
		short = function(n) n = math.floor(tonumber(n) or 1) if (n - 1) % 5 + 1 == 5 then shortPile(true) else shorts[(n - 1) % 5 + 1]() end end,
		step = step, rebind = rebind, death = death, backing = false,
		hidden = function() return held or deathGone end,
		stop = function() hide(false) end,
	}
end
