								hardcoreGUITween:Play()
							end
						end)
					end
				end
			end
		end


		System.persistKeybinds = function()
			if not (env and env.writefile and env.isfile and env.readfile and _atomicWriteJSON) then return end
			pcall(function()
				_withSettingsLock(function()
					local merged = System._readJSONSafe("RClothesLerp/Settings.json")
					if not merged then warn("[RoClothes] keybinds not saved: Settings.json could not be read"); return end
					merged.KEYBIND  = (typeof(KEYBIND) == "EnumItem") and KEYBIND.Name or ((KEYBIND == false or KEYBIND == "Off") and "Off") or nil
					merged.hpKEYBIND = (typeof(hpKEYBIND) == "EnumItem") and hpKEYBIND.Name or ((hpKEYBIND == false or hpKEYBIND == "Off") and "Off") or nil
					merged.dpKEYBIND = (typeof(dpKEYBIND) == "EnumItem") and dpKEYBIND.Name or ((dpKEYBIND == false or dpKEYBIND == "Off") and "Off") or nil
					merged.nkKEYBIND = (typeof(nkKEYBIND) == "EnumItem") and nkKEYBIND.Name or ((nkKEYBIND == false or nkKEYBIND == "Off") and "Off") or nil
					_atomicWriteJSON("RClothesLerp/Settings.json", merged)
				end)
			end)
		end


		System.persistLoadup = function()
			if not (env and env.writefile and env.isfile and env.readfile and _atomicWriteJSON) then return false end
			local okAll = false
			pcall(function()
				_withSettingsLock(function()
					local merged = System._readJSONSafe("RClothesLerp/Settings.json")
					if not merged then warn("[RoClothes] loadup settings not saved: Settings.json could not be read"); return end
					merged.loadupClosed = loadupClosed
					merged.loadupExecute = loadupExecute
					merged.loadupFPerson = loadupFPerson
					merged.loadupBundle  = loadupBundle
					_atomicWriteJSON("RClothesLerp/Settings.json", merged)
					okAll = true
				end)
			end)
			return okAll
		end


		System.persistTelem = function()
			if not (env and env.writefile and env.isfile and env.readfile and _atomicWriteJSON) then return end
			local pd = PlayerData[Player.Name]
			pcall(function()
				_withSettingsLock(function()
					local merged = System._readJSONSafe("RClothesLerp/Settings.json")
					if not merged then warn("[RoClothes] diagnostics choice not saved: Settings.json could not be read"); return end
					merged.telemEnabled= (pd and pd._telemEnabled == true) or false
					_atomicWriteJSON("RClothesLerp/Settings.json", merged)
				end)
			end)
		end

