				local cur = System._readJSONSafe("RClothesLerp/MobileButtonPlacement.json")
				if type(cur) ~= "table" then return end
				cur[key] = Function.convertToJSON(gui.Position)
				_atomicWriteJSON("RClothesLerp/MobileButtonPlacement.json", cur)
			end)
		end
		local moveStroke = makeMoveStroke()
		local mobileHeal = {["hold"]=false,["cancel"]=false}
		local healDrag = false


		mobileHealCancel = GUIObject.HealButton.MouseLeave:Connect(function()
			if UIS.TouchEnabled and not UIS.KeyboardEnabled then return end
			if mobileHeal["hold"] == true then
				mobileHeal["cancel"] = true
			end
		end)

		mobileHealInput = GUIObject.HealButton.InputBegan:Connect(function(_input)
			if _input.UserInputType ~= Enum.UserInputType.MouseButton1
			   and _input.UserInputType ~= Enum.UserInputType.Touch then return end
			local LP = game:GetService("Players").LocalPlayer
			local data = PlayerData[LP.Name]
			mobileHeal["hold"] = true
			mobileHeal["cancel"] = false
			local holdTime = 1
			if healDrag == true then
				holdTime = .25
			end
			repeat
				local t = RS.Heartbeat:Wait()
