	Function._fpFollowStop = function()



		if not _isActiveSession() then
			local old = Function._fpFollowState
			if old and old.conn then pcall(function() old.conn:Disconnect() end) end
			if old and old.conn2 then pcall(function() old.conn2:Disconnect() end) end
			if old and old.release then pcall(old.release) end
			Function._fpFollowState = nil
			return
		end
		pcall(function() RS:UnbindFromRenderStep("RCFPFollowPre") end)
		pcall(function() RS:UnbindFromRenderStep("RCFPFollowPost") end)
		local st = Function._fpFollowState
		if st and st.conn then pcall(function() st.conn:Disconnect() end) end
		if st and st.conn2 then pcall(function() st.conn2:Disconnect() end) end
		if st and st.release then pcall(st.release) end
		local cam = workspace.CurrentCamera
		if st and st.applied and cam then pcall(function() cam.CFrame = cam.CFrame * st.applied:Inverse() end) end
		if st and st.focus and cam then pcall(function() cam.Focus = st.focus end) end
		Function._fpFollowState = nil
	end
	Function._fpFollowStart = function()
		Function._fpFollowStop()
		local st = { applied = nil }
		Function._fpFollowState = st
		local EYE = Vector3.new(0, 0.1, -0.35)
		local function undo()
			if not st.applied and not st.focus then return end
			local cam = workspace.CurrentCamera
			if st.applied and cam then cam.CFrame = cam.CFrame * st.applied:Inverse() end
			if st.focus and cam then cam.Focus = st.focus end
			st.applied, st.focus = nil, nil
		end








		local NOTURN = { [Enum.HumanoidStateType.Seated] = true, [Enum.HumanoidStateType.Climbing] = true,
			[Enum.HumanoidStateType.PlatformStanding] = true, [Enum.HumanoidStateType.Ragdoll] = true,
			[Enum.HumanoidStateType.FallingDown] = true, [Enum.HumanoidStateType.GettingUp] = true,
			[Enum.HumanoidStateType.Physics] = true, [Enum.HumanoidStateType.Dead] = true }
		local function release()
			local h = st.arHum
			st.arHum = nil
			if h then pcall(function() if h.Parent and h.AutoRotate == false then h.AutoRotate = true end end) end
		end
		st.release = release
		local function holdBody()
			local w = st.want
			st.want = nil
			if not w then release(); return end
			local hum, root = w[1], w[2]
			local okS, state = pcall(hum.GetState, hum)
			if not okS or NOTURN[state] or hum.Sit or not root.Parent then release(); return end
			if st.arHum ~= hum then
				release()
				if not hum.AutoRotate then return end
				hum.AutoRotate = false
				st.arHum = hum
			end
			local cam = workspace.CurrentCamera
			if not cam then return end
			local _, yaw = cam.CFrame:ToEulerAnglesYXZ()
			root.CFrame = CFrame.new(root.Position) * CFrame.Angles(0, yaw, 0)
		end

		st.conn = RS.Stepped:Connect(function() undo(); if st.want or st.arHum then pcall(holdBody) end end)



		pcall(function() st.conn2 = RS.PreAnimation:Connect(undo) end)
		RS:BindToRenderStep("RCFPFollowPre", Enum.RenderPriority.Camera.Value - 1, undo)


		RS:BindToRenderStep("RCFPFollowPost", Enum.RenderPriority.Last.Value + 10, function(dt)
			local cam = workspace.CurrentCamera
			if not cam or cam.CameraType ~= Enum.CameraType.Custom then st.mean = nil; return end

			local on, k = true, 1
			if System._headCam then local okF, o, v = pcall(System._headCam); if okF then on = o ~= false; k = (tonumber(v) or 100) / 100 end end
			k = math.clamp(k, 0.25, 3)
			local lP = PS.LocalPlayer
			local char = lP and lP.Character
			if not (on and char) then st.mean = nil; return end
			local camCF = cam.CFrame




			local fp = (cam.Focus.Position - camCF.Position).Magnitude <= 0.75
			local hum = char:FindFirstChildOfClass("Humanoid")
			local root = char:FindFirstChild("HumanoidRootPart")
			local head = char:FindFirstChild("Head")
			if not (hum and root and head) or hum.Health <= 0 then st.mean = nil; return end


			if cam.CameraSubject ~= hum then st.mean = nil; return end
			dt = math.min(dt or 1 / 60, 0.1)
			local rootCF, headCF = root.CFrame, head.CFrame

			local delta = rootCF:ToObjectSpace(headCF).Rotation
			if k ~= 1 then
				local axis, ang = delta:ToAxisAngle()
				if ang == ang and axis.Magnitude > 0.5 then delta = CFrame.fromAxisAngle(axis, ang * k) end
			end
			do
				local rx, ry, rz = delta:ToOrientation()
				delta = CFrame.fromOrientation(math.clamp(rx, -1.2, 1.2), math.clamp(ry, -1.2, 1.2), math.clamp(rz, -0.8, 0.8))
			end





			local hs = math.max(head.Size.Y, 0.5)
			local eyeL = rootCF:PointToObjectSpace(headCF:PointToWorldSpace(Vector3.new(0, EYE.Y * hs, 0)))
			if not st.mean or (eyeL - st.mean).Magnitude > 3 then st.mean = eyeL end
			st.mean = st.mean:Lerp(eyeL, 1 - math.exp(-dt / 0.6))
			if not fp then








				local off = (headCF.Position + rootCF:VectorToWorldSpace(Function._camShiftCur or Vector3.zero) - cam.Focus.Position) + rootCF:VectorToWorldSpace((eyeL - st.mean) * (k - 1))
				if off.Magnitude > 8 then off = off.Unit * 8 end
				local final = camCF + off
				st.focus = cam.Focus
				cam.CFrame = final
				cam.Focus = cam.Focus + off
				st.applied = camCF:Inverse() * final
				return
			end
			local eye = rootCF:PointToWorldSpace(st.mean + (eyeL - st.mean) * k)
			local rot = camCF.Rotation * delta
			local final = CFrame.new(eye + rot.LookVector * (-EYE.Z * hs)) * rot



			st.focus = cam.Focus
			st.want = { hum, root }
			cam.CFrame = final
			cam.Focus = CFrame.new(final.Position + final.LookVector * 0.5)
			st.applied = camCF:Inverse() * final
		end)
	end
	pcall(Function._fpFollowStart)

_RCR.need("engine/cam_shift", { Function = Function, PlayerData = PlayerData, System = System, _isActiveSession = _isActiveSession })



	System._themeHide = System._themeHide or {}
	function Function._setIf(inst, prop, v)

		if prop == "LocalTransparencyModifier" and System._themeHide[inst] then return end
		if inst[prop] ~= v then inst[prop] = v end
	end


	Function._stK = { S = { "_stS", "_saS" }, M = { "_stM", "_saM" } }
	function Function._setStable(inst, memo, key, prop, target)
		local k = Function._stK[key]
		if not k then k = { "_st" .. key, "_sa" .. key }; Function._stK[key] = k end
		local kt, ka = k[1], k[2]
		local cur = inst[prop]
		local lt, la = memo[kt], memo[ka]
		if lt and la and (lt - target).Magnitude <= 1e-4 and (la - cur).Magnitude <= 1e-4 then return end
		if (cur - target).Magnitude > 1e-4 then inst[prop] = target end
		memo[kt] = target
		memo[ka] = inst[prop]
	end





	Function._rcFarStuds, Function._rcFarStep = 120, 0.1
	function Function._rcPeerDue(state, dt, dist, always)
		if always or not dist or dist <= Function._rcFarStuds then
			state._rcAcc = 0
			return true, dt
		end
		local acc = (state._rcAcc or 0) + dt
		if acc < Function._rcFarStep then
			state._rcAcc = acc
			return false, 0
		end
		state._rcAcc = acc - Function._rcFarStep
		return true, acc
	end
table.insert(AllConnect, RS.RenderStepped:Connect(function(dt)
		dt = dt or 0

		Function._fallH = workspace.FallenPartsDestroyHeight

		local _sweepNow = os.clock()
		if _sweepNow >= (System._m2SweepT or 0) then
			System._m2SweepT = _sweepNow + 0.25
			for _, v in pairs(Method2CharacterFolder:GetChildren()) do
