								BodySize = BodyPartSize["HeadScale"]
							else
								CalcSize = SM.Scale
								BodySize = BodyPartSize["HeadScale"]
							end
						end

						XMultiply, YMultiply, ZMultiply = Function.MultiplyCalculate(CalcSize, BodySize)
						if specialHead == true then
							local SM:SpecialMesh = Base:FindFirstChildOfClass("SpecialMesh")

							if CalcSize.X > CalcSize.Z then
								CalcSize = Vector3.new(CalcSize.Z,CalcSize.Y,CalcSize.Z)
							end
							if CalcSize.Z > CalcSize.X then
								CalcSize = Vector3.new(CalcSize.X,CalcSize.Y,CalcSize.X)
							end
							XMultiply, YMultiply, ZMultiply = Function.MultiplyCalculate(CalcSize, BodySize)

							local S = SM.Scale
							if S.X > S.Z then
								S = Vector3.new(S.Z,S.Y,S.Z)
							end
							if S.Z > S.X then
								S = Vector3.new(S.X,S.Y,S.X)
							end
							local XMS, YMS, ZMS = Function.MultiplyCalculate(S, vector3New(1.25,1.25,1.25))

							XMultiply = XMultiply*XMS
							YMultiply = YMultiply*YMS
							ZMultiply = ZMultiply*ZMS
						end
						_specScaleCache[Base] = { XMultiply, YMultiply, ZMultiply }
						end

						if DataList.MeshSizeLock == false then

							local _targetScale = Vector3.new(SIZE.X * XMultiply, SIZE.Y * YMultiply, SIZE.Z * ZMultiply)
							Function._setStable(SpecialMesh, Property, "M", "Scale", _targetScale)
						end
					end
				end
			end

			for i, v in pairs(DataList.CurrentPartList.RealtimeUpdateList.Special) do
				local Removed = false

				if v.Parent == nil or Function.IsParentNil(v) then

					pcall(function() v:Destroy() end)
					DataList.CurrentPartList.RealtimeUpdateList.Special[i] = nil

					Removed = true
				end

				if Removed == false then
					if v.Name == "cTrail" then
						local origin = v.Parent
						local particle = v:FindFirstChildOfClass("ParticleEmitter")
						if not particle then
							pcall(function() v:Destroy() end)
							DataList.CurrentPartList.RealtimeUpdateList.Special[i] = nil
							continue
						end
						if particle:GetAttribute("Enabled") ~= false then


							System._cTrailIgnoreCache = System._cTrailIgnoreCache or {}
							local _cache = System._cTrailIgnoreCache
							local _curChar = Player.Character
							local changed = _cache.collisionLen ~= #collisionList
								or _cache.lastChar ~= _curChar or _cache.lastFolder ~= Method2CharacterFolder
								or _cache.dirty or not _cache.list
							if not changed then
								for index, part in ipairs(collisionList) do
									if _cache.list[index] ~= part then changed = true; break end
								end
							end
							if changed then
								local list = _cache.list or {}
								table.clear(list)
								for _, part in ipairs(collisionList) do table.insert(list, part) end
								if _curChar then table.insert(list, _curChar) end
								if Method2CharacterFolder then table.insert(list, Method2CharacterFolder) end
								_cache.list, _cache.collisionLen = list, #collisionList
								_cache.lastChar, _cache.lastFolder = _curChar, Method2CharacterFolder
								_cache.dirty = false
							end
							local ignoreList = _cache.list

							if not System._cTrailGroundParams then
								local _gp = RaycastParams.new()
								_gp.FilterType = Enum.RaycastFilterType.Exclude
								System._cTrailGroundParams = _gp
								System._cTrailDown = Vector3.new(0,-10000,0)
							end


							if changed or not _cache.applied then
								System._cTrailGroundParams.FilterDescendantsInstances = ignoreList
								_cache.applied = true
							end
							local _groundResult = workspace:Raycast(origin.Position, System._cTrailDown, System._cTrailGroundParams)
							local instance = _groundResult and _groundResult.Instance
							local hit = _groundResult and _groundResult.Position
							if hit and instance and instance:IsA("BasePart") then
								if instance.CanCollide == false and not collisionChecks[instance] then

									if #collisionList >= 256 then

										local oldest = table.remove(collisionList, 1)
										if oldest then
											local conn = collisionChecks[oldest]
											if conn then
												local _ci = table.find(AllConnect, conn)
												if _ci then table.remove(AllConnect, _ci) end
												pcall(function() conn:Disconnect() end)
											end
											collisionChecks[oldest] = nil
										end
									end
									table.insert(collisionList,instance)
									_cache.dirty = true

									local collisionChange; collisionChange = instance:GetPropertyChangedSignal("CanCollide"):Connect(function()
										if instance.CanCollide == false and not table.find(collisionList,instance) then
											table.insert(collisionList,instance)
											_cache.dirty = true
										elseif instance.CanCollide == true then
											local idx = table.find(collisionList,instance)
											if idx then table.remove(collisionList,idx) end
											_cache.dirty = true
											local _ci = table.find(AllConnect, collisionChange)
											if _ci then table.remove(AllConnect, _ci) end
											collisionChange:Disconnect()
											collisionChecks[instance] = nil
										end
									end)
									collisionChecks[instance] = collisionChange
									table.insert(AllConnect, collisionChange)
								else
									particle.Enabled = true
									v.WorldCFrame = CFrame.new(hit)
								end
							else
								particle.Enabled = false
							end
						else
							particle.Enabled = false
						end
					elseif v.Name == "nCensor" and v:FindFirstChildOfClass("ObjectValue") then
						local origin = v:FindFirstChildOfClass("ObjectValue")
						if origin.Value and origin.Value.Parent ~= nil then
							local tors = origin.Value.Parent
							local LNipple:MeshPart
							local RNipple:MeshPart

							if tors:FindFirstChild("Left Breast") and tors:FindFirstChild("Left Breast"):FindFirstChild("Nipple") then
								LNipple = tors["Left Breast"]["Nipple"]
							end
							if tors:FindFirstChild("Right Breast") and tors:FindFirstChild("Right Breast"):FindFirstChild("Nipple") then
								RNipple = tors["Right Breast"]["Nipple"]
							end
							if tors and LNipple and RNipple and v:FindFirstChildOfClass("Frame") then
								local angle = math.acos(
									math.clamp(
										currentCFrame.LookVector:Dot(tors.CFrame.LookVector),
										-1, 1)
								)

								if angle > math.pi/2.8 and (LNipple.Transparency < 1 or RNipple.Transparency < 1) then
									local corners = {
										RNipple.CFrame * Vector3.new(-.45, -.3, -.3),
										LNipple.CFrame * Vector3.new(-.45, -.3, .3),
										RNipple.CFrame * Vector3.new(-.45, .3, -.3),
										LNipple.CFrame * Vector3.new(-.45, .3, .3),
										RNipple.CFrame * Vector3.new(.45, -.3, -.3),
										LNipple.CFrame * Vector3.new(.45, -.3, .3),
										RNipple.CFrame * Vector3.new(.45, .3, -.3),
										LNipple.CFrame * Vector3.new(.45, .3, .3)
									}

									local minX, minY = math.huge, math.huge
									local maxX, maxY = -math.huge, -math.huge


									local screenBoundingBox
									if currentCamera then

										for _, corner in ipairs(corners) do
											local screenPos, onScreen = currentCamera:WorldToScreenPoint(corner)
											minX = math.min(minX, screenPos.X)
											minY = math.min(minY, screenPos.Y)
											maxX = math.max(maxX, screenPos.X)
											maxY = math.max(maxY, screenPos.Y)
										end

										screenBoundingBox = {
											x = minX,
											y = minY,
											width = maxX - minX,
											height = maxY - minY
										}
									end

									if screenBoundingBox then
										v.Frame.Position = UDim2.new(0, screenBoundingBox.x, 0, screenBoundingBox.y)
										v.Frame.Size = UDim2.new(0, screenBoundingBox.width, 0, screenBoundingBox.height)
										v.Frame.Visible = true
									else
										v.Frame.Visible = false
									end
								else
									v.Frame.Visible = false
								end
							end
						else
							v:Destroy()
							DataList.CurrentPartList.RealtimeUpdateList.Special[i] = nil
						end
					end
				end
			end

			for Part, Property in pairs(DataList.CurrentPartList.ParentTransparency) do
				local Removed = false

				if Part.Parent == nil or Function.IsParentNil(Part) or Function.FallenPartCheck(Part) then
					DataList.CurrentPartList.ParentTransparency[Part] = nil

					Removed = true
				end

				if Removed == false then
					local T = Property.T

					if T then
						PlayerData[PlayerName].OldTransparency[Part] = Part.Transparency
						if PlayerData[PlayerName].RealtimeBodyTransparency == true then
							Function._setIf(Part, "LocalTransparencyModifier", T)
						else
							if not PlayerData[PlayerName].CurrentPartList.OriginalTransparency[Part] then
								PlayerData[PlayerName].CurrentPartList.OriginalTransparency[Part] = Part.Transparency
							end
							Function._setIf(Part, "Transparency", T)
						end
					end
				end
			end

			for Part, Property in pairs(DataList.CurrentPartList.Link) do
				local Removed = false

				if Part.Parent == nil or Function.IsParentNil(Part) or Function.FallenPartCheck(Part) then
					DataList.CurrentPartList.Link[Part] = nil

					Removed = true
				end

				if Removed == false then
					local T = Property.T.Transparency
					local D = Property.Define or 0
					local _maxTRC = Part:GetAttribute("MaxTransparencyRC")
					if _maxTRC and D < _maxTRC then D = _maxTRC end

					if not Property.NoTrans then
						Function._setIf(Part, "LocalTransparencyModifier", math.clamp(Property.T.LocalTransparencyModifier,D,math.huge))
						Function._setIf(Part, "Transparency", math.clamp(T,D,math.huge))
					end

					if Property.Color and Property.Color.Color then
						Function._setIf(Part, "Color", Property.Color.Color)
					end
				end
			end

			for Decal, Part in pairs(DataList.CurrentPartList.AreolaDecal) do
				local Removed = false

				if Part.Parent == nil or Function.IsParentNil(Part) or Function.FallenPartCheck(Part) then
					DataList.CurrentPartList.AreolaDecal[Decal] = nil

					Removed = true
				end

				if Removed == false then

					if Decal:IsA("Decal") then
						Function._setIf(Decal, "Transparency", Part.Transparency)
						Function._setIf(Decal, "LocalTransparencyModifier", Part.LocalTransparencyModifier)
					end
				end
			end
			end)
		end

		if GUIObject.CharacterPreviewFrame.Visible then
			PreviewRotate += Circle / PreviewRotateSpeed
			GUIObject.ViewportCamera.CFrame = CFrame.lookAt(Vector3.new(math.sin(PreviewRotate)*PreviewRadius, 0, math.cos(PreviewRotate)*PreviewRadius), Vector3.new(0,0,0))
		end
	end))



	local _breathAccum = 0




	table.insert(AllConnect, RS.RenderStepped:Connect(function(d)

		local _frameCamera = workspace.CurrentCamera
		if not _frameCamera then return end
		for PlayerName, DataList in pairs(PlayerData) do



			local _inertiaImpulse = Vector3.zero
			local _landImpulse    = 0
			local _horizSpeed     = 999
			do
				local _char = DataList.Character
				local _root = _char and _char:FindFirstChild("HumanoidRootPart")
				if _root then
					local _curVel = _root.AssemblyLinearVelocity

					local _smooth = DataList._smoothCharVel or _curVel
					_smooth = _smooth + (_curVel - _smooth) * 0.12
					DataList._smoothCharVel = _smooth
					local _prevSmooth = DataList._prevSmooth or _smooth
					DataList._prevSmooth = _smooth
					local _dV = _smooth - _prevSmooth

					local _prevRaw = DataList._prevCharVel or _curVel
					DataList._prevCharVel = _curVel
					if _prevRaw.Y < -6 and _curVel.Y > _prevRaw.Y * 0.35 then
						_landImpulse = math.abs(_prevRaw.Y) * 0.02
					end
					if _dV:Dot(_dV) < 100 then
						_inertiaImpulse = -_dV * 0.08
					end
					_horizSpeed = Vector3.new(_smooth.X, 0, _smooth.Z).Magnitude

					end
			end





			local _bpp = DataList.CurrentPartList.BodyPartPhysics
			if _bpp and not DataList.AnimationsFrozen then

			local _halfPi    = math.pi * 0.5
			local _radMul    = (math.pi / 180) * RotationPhysicsMultiply
			local _radMulOvt = 0.8 * _radMul
			local _physGravity     = DataList.PhysicsObeyGravity == true
			local _breathEnabled   = DataList.BreathingEnabled
			local _breathAmplitude = DataList.BreathingAmplitude or 0.025
			local _overtoneAmp     = DataList.OvertoneAmplitude or 0.4
			local _camPos          = _frameCamera.CFrame.Position


			local _ctx = _physicsTickCtx
			_ctx.DataList            = DataList
			_ctx.Function            = Function
			_ctx.d                   = d
			_ctx._inertiaImpulse     = _inertiaImpulse
			_ctx._landImpulse        = _landImpulse
			_ctx._horizSpeed         = _horizSpeed
			_ctx._halfPi             = _halfPi
			_ctx._radMul             = _radMul
			_ctx._radMulOvt          = _radMulOvt
			_ctx._physGravity        = _physGravity
			_ctx._breathEnabled      = _breathEnabled
			_ctx._breathAmplitude    = _breathAmplitude
			_ctx._overtoneAmp        = _overtoneAmp
			_ctx._camPos             = _camPos
			_ctx._breathAccum        = _breathAccum
			_ctx.PositionPhysicsMultiply = PositionPhysicsMultiply



			do
				local T = _ctx._tune or {}
				_ctx._tune = T
				T.bm, T.um, T.cm = DataList.BreastsMotion or 1, DataList.ButtsMotion or 1, DataList.CockMotion or 1
				T.bb, T.ub, T.cb = DataList.BreastsBounce or 0, DataList.ButtsBounce or 0, DataList.CockBounce or 0
				T.bs, T.us, T.cs = DataList.BreastsSag or 0, DataList.ButtsSag or 0, DataList.CockSag or 0
				T.angle = math.rad(DataList.CockAngle or 0)
				T.cockBase = DataList.CurrentPartList.Organ and DataList.CurrentPartList.Organ["Torso"]
			end


			local _sbBreastsActive = DataList.BreastsType == 6
			local _sbButtsActive   = DataList.ButtType == 6

			local _physOk, _physErr = pcall(function()
			for Part, Property in pairs(_bpp) do

				local _pn = Part.Name
				local _isSBBreastPart = _sbBreastsActive and (_pn == "Left Breast" or _pn == "Right Breast"
					or _pn == "Left Nipple" or _pn == "Right Nipple")
				local _isSBButtPart = _sbButtsActive and (_pn == "Left Butt" or _pn == "Right Butt")
				if _isSBBreastPart or _isSBButtPart or (Property and Property.BreastsType == 6 and (_pn == "Left Breast" or _pn == "Right Breast")) then
					_bpp[Part] = nil
					continue
				end

				_doPhysicsTickPart(_ctx, Part, Property)
			end
			end)
			if not _physOk then
				local errKey = tostring(_physErr)
				local now = os.clock()
				local last = physicsWarnState[errKey]
				if not last or (now - last) > PHYSICS_WARN_COOLDOWN then

					local _n = 0
					for _ in pairs(physicsWarnState) do _n = _n + 1 end
					if _n >= 256 then
						for k in pairs(physicsWarnState) do physicsWarnState[k] = nil; break end
					end
					physicsWarnState[errKey] = now
					warn("[RoClothes] Physics exception (per-player): " .. errKey)
				end
			end
		end
	end
	end))




	local _tailRenderScratch = {}

	local _GLOBAL_TAIL_BUDGET = 100

	table.insert(AllConnect, RS.PreRender:Connect(function(deltaTime)



		_breathAccum = (_breathAccum + deltaTime) % 4
		local _frameTailsUpdated = 0

		local _frameCam = workspace.CurrentCamera

		if not _frameCam then return end
		local _framePreRenderCamPos = _frameCam:GetRenderCFrame().Position
		for PlayerName, DataList in pairs(PlayerData) do

			if not DataList.tailSettings then continue end
			do


				local _tailOn = DataList.tailSettings.tailPhysicsEnabled and not DataList.AnimationsFrozen
				if DataList.tailSettings.isTailCurrentlyEnabled ~= _tailOn then
					DataList.tailSettings.isTailCurrentlyEnabled = _tailOn

					if not _tailOn then


						for _, physicsTail in DataList.CurrentPartList.physicsTails do
							if physicsTail.renderingPhysics then
								physicsTail.renderingPhysics = false
								updatePhysicsTailToStatic(physicsTail)
							end
						end
					end
				end




				if not _tailOn then
					continue
				end


				local scaledDelta = math.min(deltaTime, 0.1) * DataList.tailSettings.timeScale

				if not System.tailVariables[PlayerName] then
					System.tailVariables[PlayerName] = {}
					for i, v in pairs(System.tailVariables.Default)  do
						System.tailVariables[PlayerName][i] = v
					end
				end
				System.tailVariables[PlayerName].tailScaledAnimationTime += scaledDelta * DataList.tailSettings.wagAnimationSpeed
				System.tailVariables[PlayerName].tailScaledTime += scaledDelta
				System.tailVariables[PlayerName].accumulator += scaledDelta


				local stepCount = 0

				while System.tailVariables[PlayerName].accumulator >= timeStep and stepCount < 200 do
					System.tailVariables[PlayerName].accumulator -= timeStep
					stepCount += 1
				end
				if stepCount >= 200 then System.tailVariables[PlayerName].accumulator = 0 end


				local cameraPosition = _framePreRenderCamPos


				local tailsCurrentlyRenderingPhysics:{physicsTail} = _tailRenderScratch
				table.clear(tailsCurrentlyRenderingPhysics)


				DataList._physicsTailsPruneTick = (DataList._physicsTailsPruneTick or 0) + 1
				if DataList._physicsTailsPruneTick >= 30 then
					DataList._physicsTailsPruneTick = 0
					for _accKey, _pt in pairs(DataList.CurrentPartList.physicsTails) do
						if not (_accKey and _accKey.Parent ~= nil and _pt.root and _pt.root.Parent ~= nil) then
							DataList.CurrentPartList.physicsTails[_accKey] = nil
						end
					end


					if DataList.Character and Function.SetUpNativeTails then pcall(Function.SetUpNativeTails, DataList.Character, PlayerName) end
				end


				for _, physicsTail in DataList.CurrentPartList.physicsTails do

					if not physicsTail.root or physicsTail.root.Parent == nil then continue end
					local distanceToCamera = (physicsTail.root.CFrame.Position - cameraPosition).Magnitude

					if distanceToCamera <= 300 then


						physicsTail.distanceToCamera = distanceToCamera

						table.insert(tailsCurrentlyRenderingPhysics, physicsTail)
					elseif physicsTail.renderingPhysics then
						physicsTail.renderingPhysics = false
						updatePhysicsTailToStatic(physicsTail)
					end
				end


				table.sort(tailsCurrentlyRenderingPhysics, physicsTailsDistanceToCameraComparer)



				local interpolate = stepCount == 0
				local interpolationAlpha = System.tailVariables[PlayerName].accumulator * inverseTimeStep



				for _, physicsTail in tailsCurrentlyRenderingPhysics do
					if _frameTailsUpdated > _GLOBAL_TAIL_BUDGET then
						if physicsTail.renderingPhysics then
							physicsTail.renderingPhysics = false
							updatePhysicsTailToStatic(physicsTail)
						end
					else
						if interpolate then


							if not physicsTail.renderingPhysics then continue end


							updatePhysicsTailToInterpolation(physicsTail, interpolationAlpha, PlayerName)
						else


							if not physicsTail.renderingPhysics then

								physicsTail.rootPreviousCFrame = physicsTail.root.CFrame
								physicsTail.rootPreviousDeltaCFrame = CFrame.identity

								local weldOriginalCFrame = physicsTail.weldOriginalCFrame


								physicsTail.weldPreviousCFrame = weldOriginalCFrame
								physicsTail.weldCurrentCFrame = weldOriginalCFrame


								physicsTail.currentAngle = Vector3.zero


								physicsTail.angularVelocity = Vector3.zero


								physicsTail.wagAnimationBlendAlpha = 0


								physicsTail.renderingPhysics = true
							end




							for i=1, stepCount do
								updatePhysicsTail(physicsTail, stepCount == i, interpolationAlpha, PlayerName)
							end
						end


						_frameTailsUpdated += 1
					end
				end
			end
		end
	end))

	local cooldown = false
