				System._overlayBundle = function(pd, bundleData)
					if not pd or type(bundleData) ~= "table" then return end
					Function.ApplyBundleFields(pd, bundleData)
				end


				System._applyBundleAnimPack = function(p)
					local _ap = p.CatalogAnimPack
					if type(_ap) == "table" and type(_ap.id) == "string" then System._replaySawPack = true end
					if type(_ap) == "table" and type(_ap.id) == "string" and _ap.id:match("^%d+$") and #_ap.id <= 20 and System.catalogApplyItem
						and not (Function._catLive and Function._catLive.anim and Function._catLive.anim.id == _ap.id) then
						Function._catAnimFromBundle = _ap.id
						task.spawn(function()



							for _ = 1, 3 do
								local ok = pcall(function() return game:GetService("AssetService"):GetBundleDetailsAsync(tonumber(_ap.id)) end)
								if ok then break end
								task.wait(2)
							end
							pcall(System.catalogApplyItem, { id = _ap.id, itemType = "Bundle", name = tostring(_ap.name or "Animation pack"):sub(1, 64) })
						end)
					end
				end
				System._applySelfModuleGlobals = function(bundleData, skipPack)
					if type(bundleData) ~= "table" or type(bundleData.Preset) ~= "table" then return end
					local p = bundleData.Preset






					local function _num(v) return type(v) == "number" and v == v and v > -1e3 and v < 1e3 end
					for setting, value in pairs(p) do
						if setting == "PositionPhysicsMultiply" then
							if _num(value) then PositionPhysicsMultiply = value end
						elseif setting == "RotationPhysicsMultiply" then
							if _num(value) then RotationPhysicsMultiply = value end


						elseif setting == "includedAccessoryNames" then
							if type(value) == "table" then
								includedAccessoryNames = {}
								for i, v in pairs(value) do
									if type(v) == "string" then table.insert(includedAccessoryNames, v) end
								end
							end
						elseif setting == "excludeAccessoryNames" then
							if type(value) == "table" then
								excludeAccessoryNames = {}
								for i, v in pairs(value) do
									if type(v) == "string" then table.insert(excludeAccessoryNames, v) end
								end
							end
						end
					end


					if not skipPack then System._applyBundleAnimPack(p) end


					includedAccessoryNamesValidationSetNeedsUpdating = true
				end




				System._snapSelfModuleGlobals = function()
					local function cp(t) local o = {}; for i, v in ipairs(type(t) == "table" and t or {}) do o[i] = v end; return o end
					return { pos = PositionPhysicsMultiply, rot = RotationPhysicsMultiply, inc = cp(includedAccessoryNames), exc = cp(excludeAccessoryNames) }
				end
				System._restoreSelfModuleGlobals = function(s)
					if type(s) ~= "table" then return end
					PositionPhysicsMultiply, RotationPhysicsMultiply = s.pos, s.rot
					local function cp(t) local o = {}; for i, v in ipairs(t or {}) do o[i] = v end; return o end
					includedAccessoryNames, excludeAccessoryNames = cp(s.inc), cp(s.exc)
					includedAccessoryNamesValidationSetNeedsUpdating = true
				end












				Function._liftPresetTweaks = function(bd)
					local p = type(bd) == "table" and bd.Preset
					if type(p) ~= "table" then return bd end
					local map = { ClothesRecolor = "Recolor", ClothesHP = "HPClothes", AccessoryHP = "AccessoryHP", GizmoOffsets = "GizmoOffsets", GizmoOffset = "GizmoOffset" }
					local any = false
					for k in pairs(map) do if p[k] ~= nil then any = true; break end end
					if not any then return bd end
					local function revive(v, depth)
						if type(v) ~= "table" or depth > 6 then return v end
						if v.__t then local okR, r = pcall(rehydrate, v); return okR and r or v end
						local conv = Function.convertFromJSON(v)
						if type(conv) ~= "table" then return conv end
						local o = {}
						for k2, v2 in pairs(v) do o[k2] = revive(v2, depth + 1) end
						return o
					end
					local out, preset = {}, {}
					for k, v in pairs(bd) do out[k] = v end
					for k, v in pairs(p) do preset[k] = v end
					for from, to in pairs(map) do
						if preset[from] ~= nil then
							if out[to] == nil and type(preset[from]) == "table" then out[to] = revive(preset[from], 0) end
							preset[from] = nil
						end
					end
					out.Preset = preset
					return out
				end








				System._replayResetDeferrable = function(sp)
					if not hotSwap or not (System.getSelectPlayer and System.getSelectPlayer() == sp) then return false end
					local pd = PlayerData[sp]

					if not pd or pd.Cooldown == true or ((System._realBuilds or 0) > 0 and os.clock() - (System._realBuildStart or 0) < 30) then return false end
					local okC, ch = pcall(function() return Function.ResolveTargetChar and Function.ResolveTargetChar(sp) end)
					if not (okC and typeof(ch) == "Instance") then return false end



					local okG, edited = pcall(function()
						for j in pairs(System._giz3dOrig or {}) do
							if typeof(j) == "Instance" and j:IsDescendantOf(ch) then return true end
						end
						return false
					end)
					return okG and edited == false
				end

				System._replayBundleLayers = function(sp, pd, clickedName, skipReset)
					System._replaySawPack = false



					local _fpKeep
					if sp == Player.Name then
						_fpKeep = { FPerson = pd.FPerson, FPsnap = pd.FPsnap, HeadTracking = pd.HeadTracking,
							LocalTransparency = type(pd.LocalTransparency) == "table" and table.clone(pd.LocalTransparency) or pd.LocalTransparency }
					end
					if not skipReset then pcall(Function.CharacterReset, sp) end
					if Function.ResetBundleSettableFields then pcall(Function.ResetBundleSettableFields, sp) end
					pd.PartList = Function.PartListDefault()
					pd.LastRequestID = (pd.LastRequestID or 0) + 1
					pd.CurrentClothes = {}
					if sp == Player.Name and System._baseGlobals then System._restoreSelfModuleGlobals(System._baseGlobals) end
					local applied = false
					local function layer(name)
						local bd = name and Bundle[name]
						if type(bd) ~= "table" then return end
						bd = Function._liftPresetTweaks(bd)
						if not applied then
							applied = true
							if bd.ClothingBundle == true and pd._baseBody and Function.BodyRestore then
								Function.BodyRestore(pd, pd._baseBody)
								System._overlayBundle(pd, bd)
							else
								Function.ApplyBundleToPeerData(sp, bd)
							end
						else
							System._overlayBundle(pd, bd)
						end
						if sp == Player.Name and System._applySelfModuleGlobals then
							System._applySelfModuleGlobals(bd)
						end
					end
					if pd.CurrentBundle ~= "nil" and pd.CurrentBundle ~= clickedName then layer(pd.CurrentBundle) end
					if pd.CurrentPreset ~= clickedName then layer(pd.CurrentPreset) end
					for _, name in ipairs(pd.CurrentClothingBundles or {}) do
						if name ~= clickedName then layer(name) end
					end
					if clickedName then layer(clickedName) end

					if not applied and pd._baseBody and Function.BodyRestore then
						Function.BodyRestore(pd, pd._baseBody)
						pd._baseBody = nil
					end
					if not applied and sp == Player.Name then System._baseGlobals = nil end
					if _fpKeep then
						if _fpKeep.FPerson == true then pd.FPerson = true; pd.FPsnap = _fpKeep.FPsnap; pd.HeadTracking = _fpKeep.HeadTracking end
						if _fpKeep.LocalTransparency ~= nil then pd.LocalTransparency = _fpKeep.LocalTransparency end
					end




					if sp == Player.Name and not System._replaySawPack and Function._catLive and Function._catLive.anim
						and Function._catAnimFromBundle == Function._catLive.anim.id then
						task.spawn(Function._catAnimOff, Player.Character)
					end

					if sp == Player.Name and Function._catGearDrop then Function._catGearDrop() end
					System._replaySawPack = false


					if Function.MeshPrefetchFor then task.defer(function() pcall(Function.MeshPrefetchFor, pd) end) end
				end



				System._selectLoadupBundle = function(sp, pd, name)
					local bd = type(Bundle) == "table" and Bundle[name]
					if type(bd) ~= "table" or type(pd) ~= "table" then return false end
					if (pd.CurrentBundle ~= nil and pd.CurrentBundle ~= "nil") or pd.CurrentPreset
						or #(pd.CurrentClothingBundles or {}) > 0 then return false end
					if Function.BodySnapshot then
						pd._baseBody = Function.BodySnapshot(pd)
						if sp == Player.Name and System._snapSelfModuleGlobals then System._baseGlobals = System._snapSelfModuleGlobals() end
					end
					if Function.ResetBundleSettableFields then pcall(Function.ResetBundleSettableFields, sp) end
					pd.PartList = Function.PartListDefault()
					Function.ApplyBundleToPeerData(sp, Function._liftPresetTweaks(bd))
					if sp == Player.Name and System._applySelfModuleGlobals then System._applySelfModuleGlobals(bd, true); pd._loadupPack = name end
					pd.CurrentBundle = name
					return true
				end

				System.applyBundle = function(name)
					if type(name) ~= "string" or type(Bundle) ~= "table" then return false end
					if System._cancelBundleLook then System._cancelBundleLook() end
					local bundleData = Bundle[name]
					if type(bundleData) ~= "table" then return false end
					local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
					local pd = PlayerData[sp]
					if not pd then return false end






					local isClothingBundle = bundleData.ClothingBundle == true
					local isPreset = bundleData.IsPreset == true
					local isRegular = not isClothingBundle and not isPreset


					if isRegular and pd.CurrentBundle == name then
						pd.CurrentBundle = "nil"
						pd.CurrentClothes = {}
						_scrubCloth(pd, nil)
						pd.CurrentPreset = nil
						pd.CurrentClothingBundles = {}


						System._replayBundleLayers(sp, pd, nil, System._replayResetDeferrable(sp))
						if hotSwap then hotSwap() end
						if sp == Player.Name and Function.AvatarSyncPublish then pcall(Function.AvatarSyncPublish, true) end
						return "toggled_off"
					elseif isClothingBundle and pd.CurrentClothingBundles and table.find(pd.CurrentClothingBundles, name) then
						if bundleData.Clothing then
							for _, clothName in pairs(bundleData.Clothing) do
								local idx = table.find(pd.CurrentClothes, clothName)
								if idx then table.remove(pd.CurrentClothes, idx) end
								_scrubCloth(pd, clothName)
							end
						end
						local _ci = table.find(pd.CurrentClothingBundles, name)
						if _ci then table.remove(pd.CurrentClothingBundles, _ci) end
						System._replayBundleLayers(sp, pd, nil, System._replayResetDeferrable(sp))
						if hotSwap then hotSwap() end
						if sp == Player.Name and Function.AvatarSyncPublish then pcall(Function.AvatarSyncPublish, true) end
						return "toggled_off"
					elseif isPreset and pd.CurrentPreset == name then
						pd.CurrentPreset = nil
						if type(bundleData.Clothing) == "table" then
							for _, clothName in pairs(bundleData.Clothing) do _scrubCloth(pd, clothName) end
						end


						System._replayBundleLayers(sp, pd, nil, System._replayResetDeferrable(sp))
						if hotSwap then hotSwap() end
						if sp == Player.Name and Function.AvatarSyncPublish then pcall(Function.AvatarSyncPublish, true) end
						return "toggled_off"
					end


					if (pd.CurrentBundle == nil or pd.CurrentBundle == "nil") and not pd.CurrentPreset and #(pd.CurrentClothingBundles or {}) == 0 and Function.BodySnapshot then
						pd._baseBody = Function.BodySnapshot(pd)
						if sp == Player.Name and System._snapSelfModuleGlobals then System._baseGlobals = System._snapSelfModuleGlobals() end
					end


					if isClothingBundle and not table.find(pd.CurrentClothingBundles or {}, name) and Function.NakedRefuse and Function.NakedRefuse(pd) then return false end
					if isRegular and Function.IsNaked and Function.IsNaked(pd) and type(bundleData.Clothing) == "table" and next(bundleData.Clothing) and System.uiToast then
						pcall(System.uiToast, "Naked Mode is on", "This bundle's clothing stays off until you turn Naked Mode off.", "warn")
					end


					if isRegular then
						pd.CurrentBundle = name
						pd.CurrentPreset = nil
						pd.CurrentClothingBundles = {}
						pd.CurrentClothes = {}
						_scrubCloth(pd, nil)
					elseif isPreset then
						pd.CurrentPreset = name
					elseif isClothingBundle then
						pd.CurrentClothingBundles = pd.CurrentClothingBundles or {}
						if not table.find(pd.CurrentClothingBundles, name) then
							table.insert(pd.CurrentClothingBundles, name)
						end
					end


					System._replayBundleLayers(sp, pd, name, System._replayResetDeferrable(sp))

					if hotSwap then hotSwap() end
					if sp == Player.Name and Function.AvatarSyncPublish then pcall(Function.AvatarSyncPublish, true) end
					return "applied"
				end









				System._bundleLookCache = setmetatable({}, { __mode = "k" })






				System._cancelBundleLook = function()
					local job = System._pvJob
					if not job or job.cancelled then return end
					job.cancelled = true
					System._bundleLookCancelledAt = os.clock()
					local pd = PlayerData["_rc_bundle_preview"]
					if pd then pd.LastRequestID = (pd.LastRequestID or 0) + 1 end
				end

				System._realBuildActive = function()
					if (System._realBuilds or 0) > 0 and os.clock() - (System._realBuildStart or 0) < 30 then return true end
					return os.clock() - (System._realBuildEnd or -99) < 3
				end


				System._packIdleCache = System._packIdleCache or {}
				System._packIdle = function(id)
					local c = System._packIdleCache[id]
					if c ~= nil then return c or nil end
					local res
					local ok = pcall(function()
						local d = game:GetService("AssetService"):GetBundleDetailsAsync(tonumber(id))
						for _, it in ipairs(d.Items or {}) do
							local tn = tostring(it and it.Type or "")
							if tn == "UserOutfit" or tn:match("%.UserOutfit$") then
								local slots = Function._catAnimResolve and Function._catAnimResolve(tonumber(it.Id))
								local idle = type(slots) == "table" and slots.idle and slots.idle[1]
								res = idle and idle[2]
								break
							end
						end
					end)
					if ok then System._packIdleCache[id] = res or false end
					return res
				end



				System._bundleLookSig = function(pd)
					return tostring(pd and pd.CurrentBundle) .. "|" .. tostring(pd and pd.CurrentPreset) .. "|" .. table.concat((pd and pd.CurrentClothingBundles) or {}, ",") .. "|" .. tostring(System._lookRev or 0)
				end
				System.bundleLookCached = function(name)
					local def = type(Bundle) == "table" and Bundle[name] or nil
					local hit = def and System._bundleLookCache[def]
					local myPD = PlayerData[Player.Name]
					return hit ~= nil and hit.model ~= nil and hit.sig == (System._bundleLookSig(myPD))
				end



				System.getBundleLook = function(name, opts)
					local bg = type(opts) == "table" and opts.background == true
					local force = type(opts) == "table" and opts.force == true
					local warm = type(opts) == "table" and opts.warm == true
					local def = type(Bundle) == "table" and Bundle[name] or nil
					if type(def) ~= "table" then return nil end


					if System._pvJob and os.clock() - (System._pvJob.t or os.clock()) > 60 then System._cancelBundleLook(); System._pvJob = nil end
					local myPD = PlayerData[Player.Name]
					local sig = System._bundleLookSig(myPD)
					local hit = System._bundleLookCache[def]
					if hit and hit.model and not force then
						if hit.sig == sig then return warm or hit.model:Clone() end
						if not bg then return warm or hit.model:Clone(), "stale" end
					end





					if bg then
						if System._pvJob or (System._pvTaps or 0) > 0 or os.clock() - (System._pvLastTap or -99) < 1 or System._realBuildActive() then return nil, "busy" end
					else
						System._bundleLookWant = name
						System._pvLastTap = os.clock()
						if System._pvJob and System._pvJob.bg then System._cancelBundleLook() end
					end
					System._pvTaps = (System._pvTaps or 0) + (bg and 0 or 1)
					local t0 = os.clock()
					while (System._pvJob or System._realBuildActive()) and os.clock() - t0 < 30 and System._sessionAlive ~= false do
						task.wait(0.05)
						if not bg and System._bundleLookWant ~= name then break end
					end
					if not bg then System._pvTaps = math.max(0, System._pvTaps - 1) end

					if not bg and System._bundleLookWant ~= name then return nil, "superseded" end
					if System._pvJob or System._realBuildActive() or System._sessionAlive == false then return nil, "busy" end
					if bg and ((System._pvTaps or 0) > 0 or os.clock() - (System._pvLastTap or -99) < 1) then return nil, "busy" end
					sig = System._bundleLookSig(PlayerData[Player.Name])
					hit = System._bundleLookCache[def]
					if hit and hit.model and hit.sig == sig and not force then return warm or hit.model:Clone() end
					local job = { name = name, bg = bg, t = os.clock() }
					System._pvJob = job
					local key = "_rc_bundle_preview"
					local snap, idleAnim, myRig
					local sawPack = System._replaySawPack
					local ok, err = pcall(function()
						if System.NPCs[key] then System.removeClone(key) end
						local base = (Player.Character and Player.Character:GetPivot()) or CFrame.new()
						if not System.spawnClone({ key = key, hidden = true, cf = CFrame.new(base.Position + Vector3.new(0, 1500, 0)) }) then return end
						local rig, pd = System.NPCs[key], PlayerData[key]
						myRig = rig
						if not (rig and pd) then return end
						if def.ClothingBundle == true then
							pd.CurrentClothingBundles = pd.CurrentClothingBundles or {}
							if not table.find(pd.CurrentClothingBundles, name) then table.insert(pd.CurrentClothingBundles, name) end
						elseif def.IsPreset == true then
							pd.CurrentPreset = name
						else
							pd.CurrentBundle = name; pd.CurrentPreset = nil; pd.CurrentClothingBundles = {}; pd.CurrentClothes = {}
							_scrubCloth(pd, nil)
						end
						System._replayBundleLayers(key, pd, name)
						System._replaySawPack = sawPack


						do
							local function defines(k)
								for _, n in pairs({ pd.CurrentBundle, pd.CurrentPreset, table.unpack(pd.CurrentClothingBundles or {}) }) do
									local b = type(n) == "string" and Bundle[n]
									if type(b) == "table" and (b[k] ~= nil or (type(b.Preset) == "table" and b.Preset[k] ~= nil)) then return true end
								end
								return false
							end
							for _, k in ipairs({ "StripItems", "StripCategories" }) do
								if not defines(k) and myPD and type(myPD[k]) == "table" then
									local c = {}; for a, v in pairs(myPD[k]) do c[a] = v end
									pd[k] = c
								end
							end
						end


						local hum = rig:FindFirstChildOfClass("Humanoid")
						if hum and myPD and type(myPD._strippedAccessories) == "table" then
							for acc in pairs(myPD._strippedAccessories) do
								pcall(function()
									if typeof(acc) ~= "Instance" or not acc:IsA("Accessory") or acc.Parent ~= nil then return end
									local was = acc.Archivable; acc.Archivable = true
									local c = acc:Clone(); acc.Archivable = was
									if not c then return end
									for _, w in ipairs(c:GetDescendants()) do if w:IsA("JointInstance") or w:IsA("WeldConstraint") then w:Destroy() end end
									hum:AddAccessory(c)
								end)
							end
						end
						pd.Cooldown = false
						if job.cancelled then return end
						local rid = pd.LastRequestID
						if Function._loadFails then Function._loadFails[key] = nil end
						pcall(Function.CharacterReset, rig)



						if PlayerData[key] == pd and pd.LastRequestID == rid then pd._preResetRid = rid end
						local okE, comp = pcall(Function.CharacterExecute, rig, key, nil, rid)
						if not okE then warn("[RoClothes] bundle preview build:", comp); return end



						local t1 = os.clock()


						while type(comp) == "table" and not comp.done and os.clock() - t1 < 25 and System.NPCs[key] == rig and System._sessionAlive ~= false
							and not (job.cancelled and os.clock() - (System._bundleLookCancelledAt or 0) > 3) do task.wait(0.05) end
						if job.cancelled then return end
						do


							local since, t2 = os.clock(), os.clock()
							local function bump() since = os.clock() end
							local ca, cr = rig.DescendantAdded:Connect(bump), rig.DescendantRemoving:Connect(bump)
							while os.clock() - t2 < 3 and System.NPCs[key] == rig and not job.cancelled do
								task.wait(0.05)
								if os.clock() - since >= 0.15 then break end
							end
							ca:Disconnect(); cr:Disconnect()
						end
						if System.NPCs[key] ~= rig or job.cancelled then return end


						local posed = false
						local ap = type(def.Preset) == "table" and def.Preset.CatalogAnimPack
						local hum2 = rig:FindFirstChildOfClass("Humanoid")
						if type(ap) == "table" and type(ap.id) == "string" and ap.id:match("^%d+$") and hum2 and hum2.RigType == Enum.HumanoidRigType.R15 then
							idleAnim = System._packIdle(ap.id)
						end
						local flipped = {}
						for _, d in ipairs(rig:GetDescendants()) do if not d.Archivable then flipped[#flipped + 1] = d; d.Archivable = true end end
						local wasArch = rig.Archivable; rig.Archivable = true
						snap = rig:Clone()
						rig.Archivable = wasArch
						for _, d in ipairs(flipped) do pcall(function() d.Archivable = false end) end



						if snap then
							local function vpath(o, root) local p = o.Name; o = o.Parent; while o and o ~= root do p = o.Name .. "/" .. p; o = o.Parent end; return p end
							local function index(root)
								local t = {}
								for _, d in ipairs(root:GetDescendants()) do
									if d:IsA("BasePart") or d:IsA("Decal") then local p = vpath(d, root); local l = t[p]; if not l then l = {}; t[p] = l end; l[#l + 1] = d end
								end
								return t
							end
							local A, B = index(rig), index(snap)
							for p, la in pairs(A) do
								local lb = B[p]
								if lb then for i = 1, math.min(#la, #lb) do
									local j, k = la[i], lb[i]
									pcall(function()
										local lt = j.LocalTransparencyModifier
										if lt and lt > 0 then k.Transparency = 1 - (1 - j.Transparency) * (1 - lt) end
									end)
								end end
							end
						end


						if posed and snap then

							local function path(o, root) local p = o.Name; o = o.Parent; while o and o ~= root do p = o.Name .. "/" .. p; o = o.Parent end; return p end
							local byPath = {}
							for _, k in ipairs(snap:GetDescendants()) do
								if k:IsA("Motor6D") or k:IsA("AnimationConstraint") then
									local p = path(k, snap); byPath[p] = (byPath[p] == nil) and k or false
								end
							end
							do
								for _, j in ipairs(rig:GetDescendants()) do
									local k = (j:IsA("Motor6D") or j:IsA("AnimationConstraint")) and byPath[path(j, rig)] or nil
									if k and j.ClassName == k.ClassName then
										if j:IsA("Motor6D") then pcall(function() k.C0 = j.C0 * j.Transform end)
										elseif j:IsA("AnimationConstraint") then
											pcall(function() if j.Attachment0 and k.Attachment0 then k.Attachment0.CFrame = j.Attachment0.CFrame * j.Transform end; k.IsKinematic = true end)
										end
									end
								end
							end
						end
					end)

					local stillMine = System._pvJob == job or System._pvJob == nil
					if (myRig and System.NPCs[key] == myRig) or (not myRig and stillMine) then pcall(System.removeClone, key) end
					if stillMine then
						if Function._cmpaFallbackChars then Function._cmpaFallbackChars[key] = nil end
						System._replaySawPack = sawPack
					end
					if System._pvJob == job then System._pvJob = nil end
					if not ok then warn("[RoClothes] bundle preview:", err) end
					if job.cancelled then if snap then pcall(function() snap:Destroy() end) end; return nil, "cancelled" end
					if not snap then return nil, "failed" end
					for _, d in ipairs(snap:GetDescendants()) do
						if d:IsA("LuaSourceContainer") or d:IsA("BillboardGui") or d:IsA("Sound") or d:IsA("ParticleEmitter") or d:IsA("Highlight") then d:Destroy()
						elseif d:IsA("BasePart") then d.Anchored = (d.Name == "HumanoidRootPart") end
					end
					pcall(function() snap:PivotTo(CFrame.new()) end)
					if idleAnim then snap:SetAttribute("rcIdleAnim", idleAnim) end
					local nFail = Function._loadFails and Function._loadFails[key]
					if Function._loadFails then Function._loadFails[key] = nil end
					if nFail and nFail > 0 then snap:SetAttribute("rcLoadFails", nFail) end

					System._bundleLookOrder = System._bundleLookOrder or {}
					local ord = System._bundleLookOrder
					local old = System._bundleLookCache[def]
					if old and old.model then pcall(function() old.model:Destroy() end) end
					for i = #ord, 1, -1 do if ord[i] == def then table.remove(ord, i) end end
					ord[#ord + 1] = def
					local cap = (UIS.TouchEnabled and not UIS.KeyboardEnabled) and 6 or 12
					while #ord > cap do
						local d0 = table.remove(ord, 1); local e0 = System._bundleLookCache[d0]
						if e0 and e0.model then pcall(function() e0.model:Destroy() end) end
						System._bundleLookCache[d0] = nil
					end
					System._bundleLookCache[def] = { sig = sig, model = snap }
					return warm or snap:Clone()
				end


				System.clearBundle = function()
					local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
					local pd = PlayerData[sp]
					if not pd then return false end
					pd.CurrentBundle = "nil"
					pd.CurrentClothes = {}
					pd.CurrentPreset = nil
					pd.CurrentClothingBundles = {}
					_scrubCloth(pd, nil)


					System._replayBundleLayers(sp, pd, nil, System._replayResetDeferrable and System._replayResetDeferrable(sp))
					if hotSwap then hotSwap() end
					if sp == Player.Name and Function.AvatarSyncPublish then pcall(Function.AvatarSyncPublish, true) end
					return true
				end






				System.deleteBundle = function(name)
					if type(name) ~= "string" or type(Bundle) ~= "table" then return false end
					local _bDef = Bundle[name]
					local _isPersonal = _bDef and _bDef.Personal == true

					if _isPersonal then
						pcall(function()
							if env.delfile and env.isfile and env.isfile("RClothesLerp/Bundles/" .. _bsanitize(name) .. ".json") then
								env.delfile("RClothesLerp/Bundles/" .. _bsanitize(name) .. ".json")
							end
						end)
						if Function.compileOvertime then pcall(Function.compileOvertime) end
					end



					if not _isPersonal then pcall(function()
						if not (env.writefile and env.isfolder and env.makefolder) then return end
						if not env.isfolder("RClothesLerp") then pcall(env.makefolder, "RClothesLerp") end
						local _list, _readOk = _readDeleted()
						if not _readOk then
							warn("[RoClothes] DeletedBundles.json could not be read; not rewriting it for '" .. tostring(name) .. "'")
							return
						end
						local _alreadyIn = false
						for _, _n in ipairs(_list) do if _n == name then _alreadyIn = true; break end end
						if not _alreadyIn then table.insert(_list, name) end
						local _wrOk = _atomicWriteJSON("RClothesLerp/DeletedBundles.json", _list)
						if not _wrOk then
							warn("[RoClothes] DeletedBundles persist failed for '" .. tostring(name) .. "' -- bundle may reappear on next execute.")
						end
					end) end

					Bundle[name] = nil
					return true
				end


				System.getDeletedBundles = function()
					local list = _readDeleted()
					local out = {}
					for _, n in ipairs(list) do if type(n) == "string" then out[#out + 1] = n end end
					return out
				end





				System.restoreBundle = function(name)
					if type(name) ~= "string" then return false end
					local _cur, _readOk = _readDeleted()
					if not _readOk then return false end
					local _new = {}
					for _, n in ipairs(_cur) do if n ~= name then table.insert(_new, n) end end
					local _wrOk = _atomicWriteJSON("RClothesLerp/DeletedBundles.json", _new)
					if not _wrOk then return false end
					if _RoClothesData and _RoClothesData.Bundle and _RoClothesData.Bundle[name] then
						Bundle[name] = _RoClothesData.Bundle[name]
						local _subs = _mySubsSet()
						if type(Bundle[name]) == "table" then
							Bundle[name].Personal = _subs[name] == true
						end
						if hotSwap then hotSwap() end
						return true
					else

						pcall(function()
							local _roll, _rollOk = _readDeleted()
							if not _rollOk then return end
							table.insert(_roll, name)
							_atomicWriteJSON("RClothesLerp/DeletedBundles.json", _roll)
						end)
						return "manifest_gone"
					end
				end



				System.clearDeletedBundles = function()
					local _wipeOk = _atomicWriteJSON("RClothesLerp/DeletedBundles.json", {})
					if not _wipeOk then return false end
					local restored = 0
					if _RoClothesData and _RoClothesData.Bundle then
						local _subs = _mySubsSet()
						for _bN, _bV in pairs(_RoClothesData.Bundle) do
							if Bundle[_bN] == nil and type(_bV) == "table" then
								Bundle[_bN] = _bV
								if _bV.IsPreset ~= true and _bV.ClothingBundle ~= true then
									_bV.Personal = _subs[_bN] == true
								end
								restored = restored + 1
							end
						end
					end
					if hotSwap then hotSwap() end
					return restored
				end





				local function _convertTableToString(t, indent)
					indent = indent or 0
					local s = ""
					for i, v in pairs(t) do
						for _ = 1, indent do s = s .. "\t" end
						if typeof(v) == "table" then
							if type(i) == "number" then s = s .. "[" .. tostring(i) .. "] = { \n"
							else s = s .. '["' .. tostring(i) .. '"] = { \n' end
							s = s .. _convertTableToString(v, indent + 1)
							for _ = 1, indent do s = s .. "\t" end
							s = s .. "}, \n"
						else
							if type(i) == "number" then s = s .. Function.toFormatString(v) .. ", \n"
							else s = s .. '["' .. tostring(i) .. '"] = ' .. Function.toFormatString(v) .. ", \n" end
						end
					end
					return s
				end
				local function _toBundleFormat(t, bundleName)
					return "[" .. Function.toFormatString(bundleName) .. "] = { \n"
						.. _convertTableToString(t, 1) .. "},"
				end


				local function _captureLiveScales(bdata)
					local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
					local pd = PlayerData[sp]
					if not pd then return nil end
					local patch = {}
					if pd.BreastsScale and pd.BreastsScale ~= 1 then patch.BreastsScale = pd.BreastsScale end
					if pd.ButtsScale and pd.ButtsScale ~= 1 then patch.ButtsScale = pd.ButtsScale end
					if pd.LegsScale and pd.LegsScale ~= 1 then patch.LegsScale = pd.LegsScale end
					if pd.CockScale and pd.CockScale ~= 1 then patch.CockScale = pd.CockScale end
					if pd.BreastsType and pd.BreastsType ~= 1 then patch.BreastsType = pd.BreastsType end
					if pd.ButtType and pd.ButtType ~= 1 then patch.ButtType = pd.ButtType end
					if pd.TorsoType and pd.TorsoType ~= 1 then patch.TorsoType = pd.TorsoType end
					if pd.ArmType and pd.ArmType ~= 1 then patch.ArmType = pd.ArmType end
					if pd.LegsType and pd.LegsType ~= 1 then patch.LegsType = pd.LegsType end
					local _cf = System.Community and System.Community.bundleField(pd)
					if next(patch) == nil and not _cf and bdata.Community == nil then return nil end
					local out = {}; for k, v in pairs(bdata) do out[k] = v end
					local preset = {}
					if type(bdata.Preset) == "table" then for k, v in pairs(bdata.Preset) do preset[k] = v end end
					for k, v in pairs(patch) do preset[k] = v end
					out.Preset = preset
					out.Community = _cf
					return out
				end




				System._isAutoOutfitName = function(name)
					local n = tostring(name or ""):gsub("^%s+", ""):gsub("%s+$", ""):lower()
					return n == "" or n:match("^outfit_%d+_%d+$") ~= nil or n:match("^outfit_%d+_%d+_%d+$") ~= nil or n:match("^pasted outfit %d+$") ~= nil
				end
				System._rateLimitText = function(res)
					local okJ, j = pcall(HS.JSONDecode, HS, tostring(res and res.Body or ""))
					if not (okJ and type(j) == "table") then j = {} end
					local h = type(res) == "table" and type(res.Headers) == "table" and res.Headers or {}
					local sec = tonumber(j.retryAfterSec) or tonumber(h["Retry-After"]) or tonumber(h["retry-after"])
					local what = ({ userId_hour = "You can submit 20 bundles an hour.", userId_day = "You can submit 100 bundles a day.",
						ip_hour = "Your network can submit 40 bundles an hour.", banned = "Submissions from this account are paused." })[j.scope] or "Too many submissions right now."
					if not sec then return what .. " Try again later." end
					local wait = sec <= 90 and "about a minute" or sec < 3600 and (math.ceil(sec / 60) .. " minutes") or sec < 5400 and "about an hour" or (math.ceil(sec / 3600) .. " hours")
					return what .. " Try again in " .. wait .. "."
				end






				System.exportBundle = function(name, mode)
					mode = mode or "clipboard"
					if type(name) ~= "string" or name == "" then

						local sp = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
						local pd = PlayerData[sp]
						if pd then
							if pd.CurrentBundle and pd.CurrentBundle ~= "nil" then name = pd.CurrentBundle
							elseif pd.CurrentPreset and pd.CurrentPreset ~= "" then name = pd.CurrentPreset
							elseif pd.CurrentClothingBundles and #pd.CurrentClothingBundles > 0 then
								name = pd.CurrentClothingBundles[#pd.CurrentClothingBundles]
							end
						end
					end
					if type(name) ~= "string" or type(Bundle) ~= "table" or type(Bundle[name]) ~= "table" then
						return "No bundle selected -- apply one first, then export."
					end
					local bundleData = Bundle[name]

					local _expData = bundleData
					local _expSp, _expWorn
					do
						local _spx = (System.getSelectPlayer and System.getSelectPlayer()) or Player.Name
						local _pdx = PlayerData[_spx]
						if _pdx and (_pdx.CurrentBundle == name or _pdx.CurrentPreset == name or (type(_pdx.CurrentClothingBundles) == "table" and table.find(_pdx.CurrentClothingBundles, name))) then
							_expData = _captureLiveScales(bundleData) or bundleData
							_expSp, _expWorn = _spx, true
						end
					end
					if mode == "clipboard" then
						local exportString = _toBundleFormat(_expData, name)
						local copyOk = pcall(function()
							if env.copy then env.copy(exportString) else error("no copy") end
						end)
						if not copyOk then print(exportString) end
						return copyOk and "Copied to clipboard!" or "Printed to console (no clipboard API)"
					elseif mode == "community" then
						if System._isAutoOutfitName(name) then return "Not sent: give this outfit a real name first. Everyone will see it." end
						local reqFunc = _reqFn()
						if not reqFunc then

							local exportString = _toBundleFormat(_expData, name)
							local copyOk = pcall(function() if env.copy then env.copy(exportString) else error("no copy") end end)
							if not copyOk then print(exportString) end
							return "No HTTP API -- copied to clipboard instead"
						end
						local _subData = _expData
						if _expWorn and System._submissionBundle then
							local okSb, sb = pcall(System._submissionBundle, PlayerData[_expSp], _expSp)
							if okSb and type(sb) == "table" then _subData = sb end
						else
							_subData = {}; for k, v in pairs(_expData) do _subData[k] = v end
							_subData.Personal = false
						end
						local lp = PS.LocalPlayer
						local payload = {
							name = name,
							bundle = dehydrate(_subData),
							scriptVersion = VersionInternal,
							manifestVersion = System.ManifestVersion or "unknown",
							submitter = {
								userId = lp and lp.UserId or 0,
								displayName = lp and lp.DisplayName or "Unknown",
							},
						}
						local okEnc, body = pcall(HS.JSONEncode, HS, payload)
						if not okEnc then return "Encode failed" end
						if #body > 60000 and type(payload.bundle) == "table" and payload.bundle.AvatarSnapshot ~= nil then
							payload.bundle.AvatarSnapshot = nil
							local okE2, b2 = pcall(HS.JSONEncode, HS, payload)
							if okE2 then body = b2 end
						end
						local ok, res = pcall(reqFunc, {
							Url = "https://krulhub.dev/roclothes/submit",
							Method = "POST",
							Headers = { ["Content-Type"] = "application/json" },
							Body = body,
						})
						if ok and res and tonumber(res.StatusCode) and tonumber(res.StatusCode) >= 200 and tonumber(res.StatusCode) < 300 then
							return "Submitted for review!"
						end
						if ok and res and tonumber(res.StatusCode) == 429 then
							return "Not sent: " .. System._rateLimitText(res)
						end
						warn("[RoClothes] Submit non-2xx/transport: " .. tostring(res and (res.StatusCode or res) or res))


						if not (ok and res) then return "Submit failed -- no connection to KrulHub" end
						local _code = tonumber(res.StatusCode) or 0
						local _okJ, _j = pcall(HS.JSONDecode, HS, tostring(res.Body or ""))
						local _err = (_okJ and type(_j) == "table" and tostring(_j.error or "")) or ""
						local _detail = (_okJ and type(_j) == "table" and _j.detail ~= nil) and tostring(_j.detail):sub(1, 80) or nil
						if _err == "duplicate" then
							local _of = (_okJ and type(_j) == "table" and tostring(_j.existingId or "")) or ""
							if _of:find("^published:") then return "Already in the community list as \"" .. _of:sub(11) .. "\"" end


							return "Not sent: this name (or this exact outfit) is already waiting for review or approved. Deleting your copy does not withdraw it. Rename the bundle and try again."
						elseif _err == "invalid_submission" then
							if #name > 64 then return "Not sent: the bundle name is too long (64 characters max)" end
							if #body > 60000 then return "Not sent: this bundle is too big to upload (" .. math.floor(#body / 1024) .. " KB, max 64 KB)" end
							return "Not sent: the server could not read this bundle"
						elseif _err == "bad_bundle" or _err == "bad_bundle_shape" then
							return "Not sent: this bundle has data the server does not accept" .. (_detail and (" (" .. _detail .. ")") or "")
						elseif _err == "body_too_large" or _code == 413 then
							return "Not sent: this bundle is too big to upload (" .. math.floor(#body / 1024) .. " KB)"
						elseif _err == "version_outdated" then
							return "Not sent: update RoClothes first"
						elseif _err == "submissions_frozen" or _err == "queue_full" or _code == 503 then
							return "Submissions are paused right now -- try again later"
						end
						return "Submit failed (HTTP " .. tostring(_code) .. (_err ~= "" and (", " .. _err) or "") .. ")"
					end
					return "Unknown export mode"
				end











				System._pendingImports = System._pendingImports or {}
				System.importBundle = function(text)
					if type(text) ~= "string" or text == "" then
						return { ok = false, status = "Paste a bundle table or a URL.", pending = 0 }
					end

					System._pendingImports = {}
					local fromURL, urlOutput = false, nil
					if text:sub(1, 4) == "http" then
						local reqFunc = _reqFn()
						if not reqFunc then
							return { ok = false, status = "http_request not supported on this executor", pending = 0 }
						end
						local ok, res = pcall(reqFunc, { Url = text, Method = "GET" })
						if not (ok and res and tonumber(res.StatusCode) == 200) then
							return { ok = false, status = ok and ("HTTP error: " .. tostring(res and res.StatusCode)) or "URL fetch failed", pending = 0 }
						end
						if type(res.Body) ~= "string" or #res.Body > 524288 then
							return { ok = false, status = "Response too large (max 512 KB)", pending = 0 }
						end
						local decodeOk, decoded = pcall(function() return HS:JSONDecode(res.Body) end)
						if not (decodeOk and type(decoded) == "table") then
							return { ok = false, status = "URL response is not valid JSON", pending = 0 }
						end
						pcall(function() decoded = rehydrate(decoded) end)
						fromURL, urlOutput = true, decoded
					end

					local success, output
					if fromURL then
						success, output = true, urlOutput
					else
						if #text > 262144 then
							return { ok = false, status = "Paste too large or empty (max 256 KB)", pending = 0 }
						end

						if not (text:match("^%s*{") or text:match("^%s*return%s+{")
							or text:match("^%s*local%s+import%s*=%s*{") or text:match("^%s*%[")
							or text:match("^%s*[%w_]+%s*=%s*{")) then
							return { ok = false, status = "Paste must be a bundle table literal (starts with '{' or 'return {')", pending = 0 }
						end

						local _ls
						local _gok, _g = pcall(function() return getgenv and getgenv() end)
						_ls = (_gok and type(_g) == "table" and _g.loadstring) or loadstring
						if not _ls then return { ok = false, status = "loadstring unavailable on this executor", pending = 0 } end









						local function _pasteFilterReason(text)
							local out, i, n = {}, 1, #text
							while i <= n do
								local c = text:sub(i, i)
								local lb = text:match("^%[(=*)%[", i)
								if c == "-" and text:sub(i + 1, i + 1) == "-" then
									local clb = text:match("^%-%-%[(=*)%[", i)
									if clb then
										local _, e = text:find("]" .. clb .. "]", i + 4 + #clb, true); i = (e or n) + 1
									else
										local e = text:find("\n", i, true); i = (e or n) + 1
									end
								elseif lb then
									local _, e = text:find("]" .. lb .. "]", i + 2 + #lb, true); i = (e or n) + 1; out[#out + 1] = " 0 "
								elseif c == "`" then
									return "`"
								elseif c == '"' or c == "'" then
									local j, closed = i + 1, false
									while j <= n do
										local d = text:sub(j, j)
										if d == "\\" then j = j + 2 elseif d == c then closed = true; break elseif d == "\n" then break else j = j + 1 end
									end
									if not closed then return "an unterminated string" end
									i = j + 1; out[#out + 1] = " 0 "
								else
									out[#out + 1] = c; i = i + 1
								end
							end
							local code = table.concat(out)
							if code:find("..", 1, true) then return ".." end

							if code:find(":", 1, true) then return ":" end


							if code:find("[%w_%)%]]%s*%[") then return "[" end
							for _, kw in ipairs({ "while", "repeat", "for", "function", "goto", "rep", "format", "concat", "gsub", "pack" }) do
								if code:find("%f[%w_]" .. kw .. "%f[^%w_]") then return kw end
							end
							return nil
						end
						local function _pasteTableOk(root)
							local nodes = 0
							local function walk(node, depth)
								if depth > 64 then return false end
								for _, v in pairs(node) do
									nodes += 1
									if nodes > 200000 then return false end
									if type(v) == "table" and not walk(v, depth + 1) then return false end
								end
								return true
							end
							return walk(root, 1)
						end

						do
							local _why = _pasteFilterReason(text)
							if _why then
								return { ok = false, status = "Paste contains code ('" .. _why .. "'); only bundle tables can be imported.", pending = 0 }
							end
						end
						local function _pick(src, keys) local o = {}; for _, k in ipairs(keys) do o[k] = src[k] end; return o end

						local _sandbox = {
							Color3 = Color3, Vector3 = Vector3, Vector2 = Vector2,
							CFrame = CFrame, UDim = UDim, UDim2 = UDim2,
							Enum = Enum, BrickColor = BrickColor,
							NumberRange = NumberRange, NumberSequence = NumberSequence,
							ColorSequence = ColorSequence,
							NumberSequenceKeypoint = NumberSequenceKeypoint,
							ColorSequenceKeypoint = ColorSequenceKeypoint,
							Rect = Rect, Region3 = Region3,
							tonumber = tonumber, tostring = tostring,
							pairs = pairs, ipairs = ipairs, next = next,
							type = type, typeof = typeof, select = select,
							math = _pick(math, { "abs", "floor", "ceil", "min", "max", "clamp", "huge", "pi", "rad", "deg", "sqrt", "round" }),
							string = _pick(string, { "format", "sub", "char", "byte", "lower", "upper", "len" }),
							table = _pick(table, { "insert", "concat", "unpack", "pack" }),
						}
						success, output = pcall(function()
							local _chunk, _err = _ls(text)
							if not _chunk then error(_err or "loadstring failed") end
							local _sfOk = pcall(setfenv, _chunk, _sandbox)
							if not _sfOk then error("setfenv failed -- refusing to run unsandboxed chunk") end
							return _chunk()
						end)
						if not success then

							local reFormat = "local import = {" .. text .. "} return import"
							success, output = pcall(function()
								local _chunk, _err = _ls(reFormat)
								if not _chunk then error(_err or "loadstring failed") end
								local _sfOk = pcall(setfenv, _chunk, _sandbox)
								if not _sfOk then error("setfenv failed -- refusing to run unsandboxed chunk") end
								return _chunk()
							end)
						end
						if success and type(output) == "table" and not _pasteTableOk(output) then
							return { ok = false, status = "Paste is too large or loops back on itself; only bundle tables can be imported.", pending = 0 }
						end
					end

					if not success then
						return { ok = false, status = tostring(output), pending = 0 }
					end
					if type(output) ~= "table" then
						return { ok = false, status = "Not a bundle. Paste a Lua bundle table.", pending = 0 }
					end
					local _hasAny = false
					for _ in pairs(output) do _hasAny = true; break end
					if not _hasAny then
						return { ok = false, status = "Empty input -- no bundles found in pasted text.", pending = 0 }
					end


					do
						local _renamed, _i = {}, 1
						for k, v in pairs(output) do
							if type(k) ~= "string" then
								local nm
								repeat nm = "Pasted outfit " .. _i; _i = _i + 1 until not Bundle[nm] and output[nm] == nil and _renamed[nm] == nil
								_renamed[nm] = v
								output[k] = nil
							end
						end
						for k, v in pairs(_renamed) do output[k] = v end
					end



					local allBundlesSuccess = true
					local s2 = pcall(function()
						for name, input in pairs(output) do
							if type(input) ~= "table" then
								allBundlesSuccess = false; warn("Bundle '" .. tostring(name) .. "' is not a table -- skipped."); continue
							end
							local invalidBundle = false
							local function bWarn(reason) invalidBundle = true; warn(reason) end
							if input["Clothing"] then
								for _, v in pairs(input["Clothing"]) do
									if not (Clothes and Clothes[v]) then bWarn(name .. ": Could not find " .. tostring(v) .. " as Clothing.") end
								end
							end
							if input["Recolor"] then
								for i, v in pairs(input["Recolor"]) do
									if Clothes and Clothes[i] then
										for cType in pairs(v) do
											if cType ~= "Primary" and cType ~= "Secondary" and cType ~= "Tertiary" then
												bWarn(name .. ": " .. tostring(cType) .. " is not a valid color type.")
											end
										end
									else
										bWarn(name .. ": Recolor could not find " .. tostring(i) .. " as Clothing.")
									end
								end
							end
							if input["MeshEdit"] then
								for i, v in pairs(input["MeshEdit"]) do
									if _RoClothesData and _RoClothesData.PartListDefault and _RoClothesData.PartListDefault[i] then
										for property in pairs(v) do
											if not (MetaClothes and MetaClothes.__index and MetaClothes.__index[property]) then
												bWarn(name .. ": " .. tostring(property) .. " is not a valid property.")
											end
										end
									else
										bWarn(name .. ": MeshEdit does not register " .. tostring(i) .. " as a valid part.")
									end
								end
							end
							if input["HPClothes"] then
								for i, v in pairs(input["HPClothes"]) do
									if Clothes and Clothes[i] then
										for property in pairs(v) do
											if property ~= "HP" and property ~= "Inverse"
												and property ~= "Threshold" and property ~= "Type" then
												bWarn(name .. ": " .. tostring(property) .. " isn't registered. Use HP/Threshold/Inverse/Type only.")
											end
										end
									else
										bWarn(name .. ": HPClothes could not find " .. tostring(i) .. " as Clothing.")
									end
								end
							end

							if not input["Clothing"] and not input["Recolor"] and not input["MeshEdit"]
								and not input["HPClothes"] and not input["Preset"]
								and not input["AccessoryHP"] and not input["GizmoOffsets"]
								and not input["Body Color"] and not input["NippleColor"]
								and not input["SkinTone"] and not input["TClothes"]
								and not input["Accessory"] and not input["Clothes"] then
								bWarn(name .. ": no recognized bundle fields -- not a valid RoClothes bundle.")
							end
							if invalidBundle then
								allBundlesSuccess = false
								warn(" Bundle " .. tostring(name) .. " has been aborted! ")
								continue
							end
							if Bundle[name] then
								allBundlesSuccess = false
								warn("Bundle '" .. tostring(name) .. "' already exists -- skipped. Delete it first to re-import.")
								continue
							end


							local _clash = nil
							local _safe = _bsanitize(name):lower()
							for _bn in pairs(Bundle) do if _bn ~= name and _bsanitize(_bn):lower() == _safe then _clash = _bn; break end end
							for _, _pi in ipairs(System._pendingImports) do if _bsanitize(_pi.name):lower() == _safe then _clash = _clash or _pi.name end end
							if _clash then
								allBundlesSuccess = false
								warn("Bundle '" .. tostring(name) .. "' would overwrite '" .. tostring(_clash) .. "' (same file name) -- skipped. Rename it and import again.")
								continue
							end
							input.Personal = true
							table.insert(System._pendingImports, { name = name, input = input, existing = Bundle[name] })
						end
					end)
					if not s2 then
						return { ok = false, status = "Import failed (see console)", pending = 0 }
					end
					local pendingN = #System._pendingImports
					if pendingN > 0 then
						return {
							ok = true,
							status = allBundlesSuccess and "Bundle(s) parsed -- choose where to save"
								or "Some errors found. Choose where to save the rest",
							pending = pendingN,
						}
					elseif allBundlesSuccess then
						return { ok = true, status = "Nothing new to import (all duplicates?)", pending = 0 }
					else
						return { ok = false, status = "Errors found. Check Developer Console.", pending = 0 }
					end
				end



				local function _writeImportedToDisk(name, input)
					if not (env and env.writefile) then return false end
					local t = {}
					local function transfer(n, isNested)
						local newT = {}
						for i, v in pairs(n) do
							if isNested then
								if typeof(v) == "table" then newT[i] = transfer(v, true) else newT[i] = v end
							else
								if typeof(v) == "table" then t[i] = transfer(v, true) else t[i] = v end
							end
						end
						return newT
					end
					transfer(input)
					local function convert(inp)
						for i, v in pairs(inp) do
							if typeof(v) == "table" then convert(v)
							else inp[i] = Function.convertToJSON(v) end
						end
					end
					convert(t)
					t["BundleName"] = name
					local _safe = _bsanitize(name)
					local _wrOk = _atomicWriteJSON("RClothesLerp/Bundles/" .. _safe .. ".json", t)
					if not _wrOk then return false end

					pcall(function()
						local _list, _readOk = _readDeleted()
						if not _readOk or #_list == 0 then return end
						local _filtered, _removed = {}, false
						for _, _n in ipairs(_list) do
							if _n ~= name then table.insert(_filtered, _n) else _removed = true end
						end
						if _removed then _atomicWriteJSON("RClothesLerp/DeletedBundles.json", _filtered) end
					end)
					return _wrOk
				end



				local function _registerImport(name, input)
					Bundle[name] = input
				end



				local function _submitImported(name, input)
					if System._isAutoOutfitName(name) then return false, "Give it a real name first." end
					local reqFunc = _reqFn()
					if not reqFunc then return false end
					local lp = PS.LocalPlayer
					local payload = {
						name = name,
						bundle = dehydrate(input),
						scriptVersion = VersionInternal,
						manifestVersion = System.ManifestVersion or "unknown",
						submitter = { userId = lp and lp.UserId or 0, displayName = lp and lp.DisplayName or "Unknown" },
					}
					local okEnc, body = pcall(HS.JSONEncode, HS, payload)
					if not okEnc then return false end
					local ok, res = pcall(reqFunc, {
						Url = "https://krulhub.dev/roclothes/submit", Method = "POST",
						Headers = { ["Content-Type"] = "application/json" }, Body = body,
					})
					if ok and res and tonumber(res.StatusCode) == 429 then return false, System._rateLimitText(res) end
					return ok and res and tonumber(res.StatusCode) and tonumber(res.StatusCode) >= 200 and tonumber(res.StatusCode) < 300 or false
				end



				System._importClash = function(p)
					if p.registered or type(Bundle) ~= "table" then return nil end
					if Bundle[p.name] ~= nil and Bundle[p.name] ~= p.existing then return p.name end
					local key = _bsanitize(p.name):lower()
					for bn in pairs(Bundle) do if bn ~= p.name and _bsanitize(bn):lower() == key then return bn end end
					return nil
				end


				System.finalizeImportPrivate = function()
					local pending = System._pendingImports or {}
					local n = 0
					local skipped = 0
					local failed = {}
					for _, p in ipairs(pending) do
						local _clash = System._importClash(p)
						if _clash then
							skipped = skipped + 1
							warn("Import of '" .. tostring(p.name) .. "' skipped: a bundle named '" .. tostring(_clash) .. "' already exists.")
							continue
						end
						_registerImport(p.name, p.input)
						p.registered = true
						if _writeImportedToDisk(p.name, p.input) then
							n = n + 1
						else
							table.insert(failed, p)
						end
					end
					if Function.compileOvertime then pcall(Function.compileOvertime) end
					System._pendingImports = failed
					if hotSwap then hotSwap() end
					if #failed > 0 then
						return "Saved " .. n .. " private; " .. #failed .. " memory-only: disk write FAILED. Retry Save Private."
					end
					if skipped > 0 then
						return "Saved " .. n .. " private; " .. skipped .. " skipped: that name is already used by another bundle."
					end
					return n > 0 and ("Saved " .. n .. " private!") or "Nothing to save"
				end



				System.finalizeImportCommunity = function()
					local pending = System._pendingImports or {}
					local remaining = {}
					local ok, fail, diskFail, indexFail, skipped = 0, 0, 0, 0, 0
					for _, p in ipairs(pending) do
						local _clash = System._importClash(p)
						if _clash then
							skipped = skipped + 1
							warn("Import of '" .. tostring(p.name) .. "' skipped: a bundle named '" .. tostring(_clash) .. "' already exists.")
							continue
						end
						_registerImport(p.name, p.input)
						p.registered = true
						local diskOK = _writeImportedToDisk(p.name, p.input)
						if not diskOK then diskFail = diskFail + 1 end
						local _submit = {}
						for k, vv in pairs(p.input) do _submit[k] = vv end
						_submit.Personal = false
						local _subOk = p.communitySubmitted
						if not _subOk then _subOk, System._importSubmitWhy = _submitImported(p.name, _submit) end
						if _subOk then
							p.communitySubmitted = true
							ok = ok + 1

							local indexOK, indexSaved = pcall(function()
								if not (env and env.writefile) then return false end




								local _list = {}
								if env.isfile and env.readfile and System._readJSONSafe then
									_list = System._readJSONSafe("RClothesLerp/MySubmissions.json")
									if _list == nil then return false end
								end
								local _seen = false
								for _, _n in ipairs(_list) do if _n == p.name then _seen = true; break end end
								if not _seen then
									table.insert(_list, p.name)
									return _atomicWriteJSON("RClothesLerp/MySubmissions.json", _list)
								end
								return true
							end)
							p.communityIndexed = indexOK and indexSaved == true
							if not p.communityIndexed then indexFail = indexFail + 1 end
						else
							fail = fail + 1
						end
						if not diskOK or not p.communitySubmitted or not p.communityIndexed then table.insert(remaining, p) end
					end
					System._pendingImports = remaining
					if Function.compileOvertime then pcall(Function.compileOvertime) end
					if hotSwap then hotSwap() end
					if diskFail > 0 then
						return "Submitted " .. ok .. ", " .. fail .. " submission failed; " .. diskFail .. " memory-only: disk write FAILED. Retry Submit Community."
					end
					if indexFail > 0 then
						return "Submitted " .. ok .. ", " .. fail .. " submission failed; " .. indexFail .. " submission index write FAILED. Retry Submit Community."
					end
					if fail == 0 then
						if skipped > 0 then return "Submitted " .. ok .. " for review; " .. skipped .. " skipped: that name is already used by another bundle." end
						return "Submitted " .. ok .. " for review!" end
					return "Submitted " .. ok .. ", " .. fail .. " failed" .. (System._importSubmitWhy and (". " .. System._importSubmitWhy) or " (see console)")
				end


				System.cancelImport = function()
					System._pendingImports = {}
					return "Import cancelled"
				end










				System.redownloadBundles = function()

					pcall(function()
						if env.delfile and env.isfile and env.isfile("RClothesLerp/BundleLoader.json") then
							env.delfile("RClothesLerp/BundleLoader.json")
						end
					end)


					local restored = 0
					if _RoClothesData and _RoClothesData.Bundle and type(Bundle) == "table" then
						local _subs = _mySubsSet()
						local _deletedSet = {}
						for _, n in ipairs(_readDeleted()) do _deletedSet[n] = true end
						for _bN, _bV in pairs(_RoClothesData.Bundle) do
							if Bundle[_bN] == nil and type(_bV) == "table" and not _deletedSet[_bN] then
								Bundle[_bN] = _bV
								if _bV.IsPreset ~= true and _bV.ClothingBundle ~= true then
									_bV.Personal = _subs[_bN] == true
								end
								restored = restored + 1
							end
						end
					end
					return "Bundle list refreshed (" .. restored .. " re-added). Restart to re-read disk."
				end





				do

					local _CB_CATS = {
						{label = "All",                 cat = 1,  sub = nil, ats = nil},
						{label = "All Body",            cat = 18, sub = nil, ats = {41}, bts = {4, 1}},
						{label = "Full Bodies",         cat = 18, sub = 37, ats = nil, bts = {1}},
						{label = "Heads",               cat = 18, sub = 66, ats = nil, bts = {4}},
						{label = "Hair",                cat = 18, sub = 20, ats = {41}},
						{label = "All Clothing",        cat = 3,  sub = nil, ats = {11, 2, 12, 64, 65, 68, 67, 66, 69, 72}, bts = {3}},
						{label = "Classic Shirts",      cat = 3,  sub = 56, ats = {11}},
						{label = "Classic Pants",       cat = 3,  sub = 57, ats = {12}},
						{label = "Classic T-Shirts",    cat = 3,  sub = 55, ats = {2}},
						{label = "Layered T-Shirts",    cat = 3,  sub = 58, ats = {64}},
						{label = "Layered Shirts",      cat = 3,  sub = 59, ats = {65}},
						{label = "Layered Pants",       cat = 3,  sub = 60, ats = {66}},
						{label = "Jackets",             cat = 3,  sub = 61, ats = {67}},
						{label = "Sweaters",            cat = 3,  sub = 62, ats = {68}},
						{label = "Shorts",              cat = 3,  sub = 63, ats = {69}},
						{label = "Dresses & Skirts",    cat = 3,  sub = 65, ats = {72}},
						{label = "Shoes",               cat = 3,  sub = 64, ats = nil, bts = {3}},

						{label = "Accessories",         cat = 11, sub = nil, ats = {8, 42, 43, 44, 45, 46, 47}},
						{label = "Hats",                cat = 11, sub = 54, ats = {8}},
						{label = "Face Accessories",    cat = 11, sub = 21, ats = {42}},
						{label = "Neck Accessories",    cat = 11, sub = 22, ats = {43}},
						{label = "Shoulder Accessories", cat = 11, sub = 23, ats = {44}},
						{label = "Front Accessories",   cat = 11, sub = 24, ats = {45}},
