				if _ok_genv and _genv then _genv._RC_krul_manifest_task = System._krulManifestTask end
			end
		end
	end


	if not _isActiveSession() then

		if BREAKER and BREAKER.Parent then pcall(function() BREAKER:Destroy() end)
		elseif System._sessionTeardown then pcall(System._sessionTeardown) end
		return
	end

	Function.RunInitialization()




end
end

if RS:IsStudio() then
	if _RCA.boot() then RoClothes(PS.LocalPlayer); _rawPcall(_RCA.booted) end
else
	if RS:IsClient() then
		if not PS.LocalPlayer then
			PS.PlayerAdded:Wait()
		end
		if _RCA.boot() then RoClothes(PS.LocalPlayer); _rawPcall(_RCA.booted) end
	elseif RS:IsServer() then


	end
end
return nil
