				local w = wg[i]
				local sweep = (1 - open) * math.rad(80) + math.rad(18)
				local pivot = cf * CFrame.new(w.side * 0.25, majestic and -0.3 or -0.6, 0.6) * CFrame.Angles(0, w.side == 1 and 0 or math.pi, 0)
					* CFrame.Angles(0, -w.side * sweep, 0) * CFrame.Angles(0, 0, lift + (majestic and math.rad(-8) or math.rad(-10)) + (1 - open) * math.rad(-25))
				w.p.CFrame = pivot * CFrame.Angles(math.rad(-90), 0, 0) * CFrame.new(rx * S, 0, rz * S)
				w.m.Scale = Vector3.new(S, 1, S)
				w.p.Transparency = tr
				if col then L.tint(w.m, col, g or 2.2) end
				if w.bp and tr < 0.95 then bigUntil = os.clock() + 0.1 end
				if w.bp then
					local bS = S * 1.06
					local bpiv = pivot - cf.LookVector * 0.12
					w.bp.CFrame = bpiv * CFrame.Angles(math.rad(-90), 0, 0) * CFrame.new(rx * bS, 0, rz * bS)
					w.bm.Scale = Vector3.new(bS, 1, bS)
					w.bp.Transparency = math.min(1, tr + 0.25)
					w.sp.CFrame = pivot * CFrame.new(S * 0.3, S * 0.15, 0)
					w.sp.Size = Vector3.new(S * 0.6, S * 0.4, 0.4)
					local on = tr < 0.6
					w.mo.Rate = on and 40 or 0
					w.fe.Rate = on and 6 or 0
				end
			end
		end
		wg.objs = {}
		for i = 1, 2 do local w = wg[i] for _, x in ipairs({ w.p, w.bp, w.sp }) do wg.objs[#wg.objs + 1] = x end end
		return wg
	end

	local function shaft(top, bot, w)
		local a, b = L.att(top), L.att(bot)
		local soft = L.beam(a, b, { Width0 = w, Width1 = w, Brightness = 2.5, Segments = 2, Color = CS(C1, C2), Transparency = NS({ K(0, 1), K(0.4, 0.5), K(1, 0.3) }) })
		local core = L.beam(a, b, { Width0 = w * 0.3, Width1 = w * 0.3, Brightness = 6, Segments = 2, Color = CS(W), Transparency = NS({ K(0, 1), K(0.4, 0.3), K(1, 0) }) })
		return { a = a, b = b, soft = soft, core = core, objs = { a, b, soft, core } }
	end
	local function vring(pos, col, from, to, life, gain)
		local p, m = L.mesh("disc.mesh", "ring_c.png", col, gain or 2.6)
		L.fx(life, function(k) local s = from + (to - from) * L.outQuad(k) m.Scale = Vector3.new(s, 1, s)
			p.CFrame = CFrame.new(pos + Vector3.new(0, 0.2 + 5 * L.outQuad(k), 0)) p.Transparency = 0.1 + 0.9 * k end, { p })
	end


