	local rig, light, hl = {}, nil, nil
	local function rebind()
		for _, o in ipairs(rig) do o:Destroy() end
		rig = {}
		local hrp = ch.hrp
		local function att(pos) local a = L.new("Attachment", { Position = pos }, hrp) rig[#rig + 1] = a return a end
		local function trail(a0, a1, props) local t = L.new("Trail", props, hrp) t.Attachment0, t.Attachment1 = a0, a1 rig[#rig + 1] = t return t end
		rig.main = trail(att(Vector3.new(0, 1.2, 0.3)), att(Vector3.new(0, -1.5, 0.3)), { Texture = L.T("beamb.png"), LightEmission = 1, Brightness = 3,
			Lifetime = 0.45, FaceCamera = true, Enabled = false, Color = CS({ CK(0, W), CK(0.4, C2), CK(1, C1) }),
			Transparency = NS({ K(0, 0.2), K(1, 1) }), WidthScale = NS({ K(0, 1), K(1, 0.3) }) })
		local back = att(Vector3.new(0, 0.6, 0.6))
		rig.feath = featherE(back, { Speed = NR(1, 3), Lifetime = NR(1.5, 2.2), EmissionDirection = Enum.NormalId.Back })
		rig.motes = moteE(att(Vector3.new(0, -1, 0.4)), { Speed = NR(1, 3), Lifetime = NR(0.6, 1) })
		for _, e in ipairs({ rig.feath, rig.motes }) do rig[#rig + 1] = e end
		light = L.new("PointLight", { Color = C2, Range = 16, Brightness = 0, Shadows = false }, hrp) rig[#rig + 1] = light
		hl = L.new("Highlight", { FillTransparency = 1, OutlineColor = C2, Adornee = ch.char, DepthMode = Enum.HighlightDepthMode.Occluded }, L.root)
		rig[#rig + 1] = hl
