	local savedLTM, hideChar, hideOwner, hideGen, dashTok = nil, nil, nil, 0, nil
	local function setHidden(on, tok)
		if on then
			hideGen += 1
			local my = hideGen
			hideOwner = my
			task.delay(15, function() setHidden(false, my) end)
			if savedLTM and hideChar == ch.char then return my end
			if not ch.char then return my end
			savedLTM, hideChar = {}, ch.char
			for _, d in ipairs(ch.char:GetDescendants()) do
				if d:IsA("BasePart") or d:IsA("Decal") then savedLTM[d] = d.LocalTransparencyModifier d.LocalTransparencyModifier = 1 end
			end
			return my
		elseif savedLTM then
			if tok and tok ~= hideOwner then return end
			for d, v in pairs(savedLTM) do if d.Parent then d.LocalTransparencyModifier = v end end
			if tok and tok ~= dashTok then L.punch(1.1, 0.3) end
			savedLTM, hideChar, hideOwner = nil, nil, nil
		end
	end
	local function camBasis() return L.facing() end

	local function figure(col)
		local m = Instance.new("Model")
		local rel = {}
		local root = ch.hrp.CFrame
		for _, p in ipairs(ch.char:GetDescendants()) do
			local ltm = savedLTM and savedLTM[p] or (p:IsA("BasePart") and p.LocalTransparencyModifier) or 1
			if p:IsA("BasePart") and p.Name ~= "HumanoidRootPart" and p.Transparency < 1 and ltm < 1 then
				local g = p:Clone()
				for _, d in ipairs(g:GetChildren()) do if not d:IsA("DataModelMesh") then d:Destroy() end end
				g.Anchored, g.CanCollide, g.CanQuery, g.CanTouch, g.CastShadow = true, false, false, false, false
				g.Material, g.Color = Enum.Material.Neon, col
				if g:IsA("MeshPart") then g.TextureID = "" end
				g.Transparency = 1
				g.Parent = m
				rel[g] = root:ToObjectSpace(p.CFrame)
			end
		end
		m.Parent = L.root
		local f = { model = m, rel = rel }
		function f.set(cf, tr, c)
			for g, r in pairs(rel) do
				if g.Parent then g.CFrame = cf * r g.Transparency = tr if c then g.Color = c end end
			end
		end
		return f
	end
	local function appear(col, tok)
		setHidden(false, tok)
		bodyFlare(col)
	end



	local function arriveFull()
		local o = ch.feet
		local DUR, STAIR0, DOOR, WALK0, HIT = 10.6, 1.3, 3.15, 3.8, 6.8
		L.after(DUR - 2.6, function() L.handoff(o, "glyph.png", C1, 30, 8, 2.4, 1.8) end)
		local fwd, right = camBasis()
		local hipH = ch.hrp.Position.Y - o.Y
		local fig = figure(W)
		local hideTok = setHidden(true)
		task.delay(DUR + 0.1, function() setHidden(false, hideTok) end)
		local S = L.screen(DUR)
		S.dimFn = function(t) return 0.25 * c01(t / 1) * (1 - c01((t - HIT) / 1)) end
		S.style, S.c1, S.c2 = "lightborn", C1, C2 S.boxFn = function(t) return c01((t - 0.2) / 0.6) * (1 - c01((t - (DUR - 1)) / 0.8)) end
		S.tintFn = function(t) return C1:Lerp(W, 0.35), 0.5 * c01(t / 1.5) * (1 - c01((t - HIT - 1.5) / 2.5)) end
		L.after(HIT + 0.5, function() S:title(L.name(), C1, C2) end)

		local T = o - fwd * 26 + Vector3.new(0, 30, 0)
		local B = o - fwd * 2.6
		local dirH = Vector3.new(B.X - T.X, 0, B.Z - T.Z).Unit
		local side = Vector3.new(-dirH.Z, 0, dirH.X)
		local N = 16
		local run = Vector3.new(B.X - T.X, 0, B.Z - T.Z).Magnitude / (N - 1)
		local steps, objs = {}, {}
		for i = 1, N do
			local pos = T:Lerp(B, (i - 1) / (N - 1)) - Vector3.new(0, 0.2, 0)

			local p = L.part({ Material = Enum.Material.Glass, Color = C2:Lerp(W, 0.7), Transparency = 1, Size = Vector3.new(0.1, 0.3, run * 1.05) })
			p.CFrame = CFrame.lookAt(pos, pos + dirH)
			local edge = L.part({ Material = Enum.Material.Neon, Color = W, Transparency = 1, Size = Vector3.new(0.1, 0.12, 0.18) })
			edge.CFrame = p.CFrame * CFrame.new(0, 0.2, -run * 0.52)
			local ed, edm = L.mesh("disc.mesh", "glowui.png", C1, 1.6)
			ed.CFrame = CFrame.new(pos - Vector3.new(0, 0.2, 0))
			steps[i] = { p = p, edge = edge, pos = pos, at = STAIR0 + (i - 1) * 0.12, ed = ed, edm = edm, hitT = -9 }
			objs[#objs + 1] = p objs[#objs + 1] = ed objs[#objs + 1] = edge
		end
		local stepMote = L.part({ Size = Vector3.new(4, 0.2, 4) })
		local sm = moteE(stepMote, { Shape = Enum.ParticleEmitterShape.Box, Rate = 0, Speed = NR(1, 3), Lifetime = NR(0.6, 1), EmissionDirection = Enum.NormalId.Top })
		objs[#objs + 1] = stepMote

		local gate = {}
		for i, s in ipairs({ 1, -1 }) do
			local p = L.part({ Material = Enum.Material.Neon, Color = C2:Lerp(W, 0.4), Transparency = 1, Size = Vector3.new(0.8, 0.1, 0.8) })
			gate[i] = { p = p, base = T + side * s * 4.2 }
			objs[#objs + 1] = p
		end
		local arch, archM = L.mesh("disc.mesh", "ring_c.png", C2, 3)
		local door, doorM = L.mesh("disc.mesh", "glowui.png", C2, 2.2)
		local doorG, doorGM = L.mesh("disc.mesh", "glyph.png", C1, 2)
		objs[#objs + 1] = arch objs[#objs + 1] = door objs[#objs + 1] = doorG
		local gateCF = CFrame.lookAt(T + Vector3.new(0, 6.5, 0), T + Vector3.new(0, 6.5, 0) + dirH) * CFrame.Angles(math.rad(90), 0, 0)

		local cTop = Vector3.new(T.X, o.Y + 72, T.Z)
		local cl1, cl1M = L.mesh("swirl.mesh", "smoke.png", C1:Lerp(W, 0.35), 1.4)
		local cl2, cl2M = L.mesh("disc.mesh", "smoke.png", C1:Lerp(W, 0.2), 1.2)
		local gap, gapM = L.mesh("disc.mesh", "glowui.png", C2, 3.6)
		local gapR, gapRM = L.mesh("disc.mesh", "ring_c.png", W, 3)
		objs[#objs + 1] = cl1 objs[#objs + 1] = cl2 objs[#objs + 1] = gap objs[#objs + 1] = gapR

		local coneA, coneB = L.att(cTop - Vector3.new(0, 1, 0)), L.att(T + Vector3.new(0, 0.5, 0))
		local cone = L.beam(coneA, coneB, { Texture = L.T("softbeam.png"), TextureMode = Enum.TextureMode.Stretch, Width0 = 0.1, Width1 = 0.1, Brightness = 2.2, Segments = 2, Color = CS(W, C2), Transparency = NS(1) })
		local coneC = L.beam(coneA, coneB, { Texture = L.T("softbeam.png"), TextureMode = Enum.TextureMode.Stretch, Width0 = 0.1, Width1 = 0.1, Brightness = 3, Segments = 2, Color = CS(W), Transparency = NS(1) })
		objs[#objs + 1] = coneA objs[#objs + 1] = coneB objs[#objs + 1] = cone objs[#objs + 1] = coneC

		local pool, poolM = L.mesh("disc.mesh", "glowui.png", C2, 1.8)
		objs[#objs + 1] = pool
		local fp = L.part({ Size = Vector3.new(30, 0.2, 30), CFrame = CFrame.new(cTop - Vector3.new(0, 2, 0)) })

		local sparkle = moteE(fp, { Shape = Enum.ParticleEmitterShape.Box, EmissionDirection = Enum.NormalId.Bottom, Rate = 0, Speed = NR(3, 6),
			Lifetime = NR(5, 7), Acceleration = Vector3.new(0, -0.6, 0), Drag = 0.3, Color = CS(W, C1), Size = NS({ K(0, 0), K(0.1, 0.35), K(0.8, 0.3), K(1, 0) }),
			Transparency = NS({ K(0, 1), K(0.1, 0), K(0.85, 0.2), K(1, 1) }) })
		local gapLight = L.new("PointLight", { Color = C2, Range = 60, Brightness = 0, Shadows = false }, fp)
		local fall = featherE(fp, { Shape = Enum.ParticleEmitterShape.Box, EmissionDirection = Enum.NormalId.Bottom, Speed = NR(2, 4), Lifetime = NR(5, 6),
			Size = NS({ K(0, 0.8), K(1, 0.6) }), Acceleration = Vector3.new(0.3, -0.8, 0) })
		objs[#objs + 1] = fp

		local sg, sgm = L.mesh("disc.mesh", "glyph.png", C1, 2)
		local sg2, sg2m = L.mesh("disc.mesh", "ring_c.png", C2, 2.4)
		objs[#objs + 1] = sg objs[#objs + 1] = sg2
		local figLight = L.new("PointLight", { Color = C2, Range = 22, Brightness = 0, Shadows = false }, stepMote)

		local G = CFrame.lookAt(T, T + dirH)
		local lintel = L.part({ Material = Enum.Material.Neon, Color = C2:Lerp(W, 0.4), Transparency = 1, Size = Vector3.new(10.4, 0.9, 1.3) })
		objs[#objs + 1] = lintel
		local leaves = {}
		for i, s in ipairs({ 1, -1 }) do
			local p = L.part({ Material = Enum.Material.Neon, Color = C1:Lerp(W, 0.35), Transparency = 1, Size = Vector3.new(3.9, 12.3, 0.3) })
			local gl, glm = L.mesh("disc.mesh", "glyph.png", W, 2.6)
			leaves[i] = { p = p, s = s, gl = gl, glm = glm }
			objs[#objs + 1] = p objs[#objs + 1] = gl
		end

		local spillA, spillB = L.att(T + Vector3.new(0, 4, 0)), L.att(B + Vector3.new(0, 1, 0))
		local spill = L.beam(spillA, spillB, { Width0 = 0.1, Width1 = 0.1, Brightness = 3, Segments = 2, Color = CS(W, C2), Transparency = NS({ K(0, 0.2), K(1, 0.8) }) })
		objs[#objs + 1] = spillA objs[#objs + 1] = spillB objs[#objs + 1] = spill

		local rails = {}
		for i, s in ipairs({ 1, -1 }) do
			local a0, a1 = L.att(T + side * s * 3.1 + Vector3.new(0, 0.6, 0)), L.att(T + side * s * 3.1 + Vector3.new(0, 0.6, 0))
			local b = L.beam(a0, a1, { Width0 = 0.35, Width1 = 0.35, Brightness = 4, Segments = 2, Color = CS(W, C1), Transparency = NS(1) })
			rails[i] = { a0 = a0, a1 = a1, b = b, s = s }
			objs[#objs + 1] = a0 objs[#objs + 1] = a1 objs[#objs + 1] = b
		end

		local puffs = {}
		for i = 1, 10 do
			local a = i / 10 * 6.28
			local p = L.part({ Size = Vector3.new(10, 3, 10), CFrame = CFrame.new(cTop + Vector3.new(math.cos(a) * 26, rnd(-2, 2), math.sin(a) * 26)) })
			puffs[i] = L.pe(p, { Texture = L.T("smoke.png"), Color = CS(C1:Lerp(W, 0.55)), LightEmission = 0.3, Brightness = 1.5, Rate = 0,
				Shape = Enum.ParticleEmitterShape.Box, Transparency = NS({ K(0, 1), K(0.3, 0.45), K(1, 1) }), Size = NS({ K(0, 10), K(1, 18) }),
				Lifetime = NR(2.5, 3.5), Speed = NR(0.5, 1.5), Rotation = NR(0, 360), RotSpeed = NR(-15, 15) })
			objs[#objs + 1] = p
		end

		local figW = wings(2.2)
		for _, x in ipairs(figW.objs) do objs[#objs + 1] = x end
		local doorOpened = false

		local riseP = L.part({ Size = Vector3.new(6, 0.4, 2) })
		local riseE = moteE(riseP, { Shape = Enum.ParticleEmitterShape.Box, Rate = 0, Speed = NR(2, 5), Lifetime = NR(1, 1.8), Acceleration = Vector3.new(0, 3, 0),
			EmissionDirection = Enum.NormalId.Top, Color = CS(W, C1) })
		objs[#objs + 1] = riseP
		local gateGone = false

		local function choirHalo(pos)
			local h, hm = L.mesh("disc.mesh", "ring_c.png", C2, 3.2)
			local hg, hgm = L.mesh("disc.mesh", "glowui.png", C1, 1.4)
			L.fx(3.2, function(k, tt)
				local a = c01(tt / 0.3) * (1 - c01((k - 0.6) / 0.4))
				local p = pos + Vector3.new(0, 0.6 * tt + 0.15 * math.sin(tt * 3), 0)
				hm.Scale = Vector3.new(1.4, 1, 1.4) h.CFrame = CFrame.new(p) * CFrame.Angles(0, tt * 1.5, 0)
				h.Transparency = math.max(0.06, 1 - 0.95 * a)
				hgm.Scale = Vector3.new(2.6, 1, 2.6) hg.CFrame = CFrame.new(p + Vector3.new(0, 0.02, 0))
				hg.Transparency = 1 - 0.5 * a
			end, { h, hg })
		end

		local armRel, shoulder = {}, nil
		do
			local arm = ch.char:FindFirstChild("Right Arm") or ch.char:FindFirstChild("RightUpperArm")
			if arm then
				shoulder = ch.hrp.CFrame:ToObjectSpace(CFrame.new(arm.Position + arm.CFrame.UpVector * arm.Size.Y * 0.45))
				for g in pairs(fig.rel) do
					local src = g.Name
					if src:find("Right") and (src:find("Arm") or src:find("Hand")) then armRel[g] = true end
				end
			end
		end
		local reachA, reachB = L.att(o), L.att(o)
		local reachBeam = L.beam(reachA, reachB, { Texture = L.T("softbeam.png"), Width0 = 0.6, Width1 = 2.5, Brightness = 4, Segments = 2, Color = CS(W, C2), Transparency = NS(1) })
		objs[#objs + 1] = reachA objs[#objs + 1] = reachB objs[#objs + 1] = reachBeam
		local lastStep = 0
		local armLen = 1.9
		local function setFig(cf, tr, c, reach)
			local rot = shoulder and (shoulder * CFrame.Angles(math.rad(85) * reach, 0, math.rad(-8) * reach) * shoulder:Inverse()) or CFrame.identity
			for g, r in pairs(fig.rel) do
				if g.Parent then
					g.CFrame = armRel[g] and (cf * rot * r) or (cf * r)
					g.Transparency = tr
					if c then g.Color = c end
				end
			end
			if not shoulder then return cf.Position end
			return (cf * shoulder * CFrame.Angles(math.rad(85) * reach, 0, math.rad(-8) * reach) * CFrame.new(0, -armLen, 0)).Position
		end

		local function featherSpiral()
			local ps, os_ = {}, {}
			for i = 1, 10 do
				local p = L.part({ Size = Vector3.new(0.5, 0.5, 0.5) })
				ps[i] = { p = p, h = (i - 1) / 9, ph = i * 2.5, f = featherE(p, { Rate = 0, Speed = NR(0.5, 1.5), Lifetime = NR(0.6, 1), SpreadAngle = Vector2.new(180, 180) }) }
				os_[#os_ + 1] = p
			end
			L.fx(1.8, function(k, tt)
				local out = c01((tt - 1.1) / 0.5)
				for _, q in ipairs(ps) do
					local y = q.h * 9 * L.outQuad(c01(tt / 0.6)) + tt * 1.5
					local r = (1.5 + q.h * 1.5) * (1 + out * 4)
					local a = q.ph - tt * 7
					q.p.CFrame = CFrame.new(o + Vector3.new(math.cos(a) * r, y + 0.3, math.sin(a) * r))
					q.f.Rate = tt < 1.3 and 30 or 0
				end
			end, os_)
		end
		local wg = wings(2.4, true)
		for _, x in ipairs(wg.objs) do objs[#objs + 1] = x end

		local Lt = game:GetService("Lighting")
		local GOLD = Color3.fromRGB(255, 196, 60)

		local wsky = L.worldSky(o, DUR, { dome = Color3.fromRGB(225, 120, 45), atmC = Color3.fromRGB(255, 160, 80), decay = Color3.fromRGB(200, 90, 30),
			den = 0.3, haze = 0.8, glare = 1.2, oa = Color3.fromRGB(200, 150, 95), am = Color3.fromRGB(150, 110, 70), domeA = 0.7 })
		for _, x in ipairs(wsky.objs) do objs[#objs + 1] = x end
		local scr = L.scr()
		local sunR = scr and Lt:FindFirstChildOfClass("SunRaysEffect") or nil
		local sunNew = scr and sunR == nil
		if sunNew then sunR = L.new("SunRaysEffect", { Intensity = 0, Spread = 1 }, Lt) end
		if not scr then sunR = { Intensity = 0, Spread = 1 } end
		local srI, srS = sunR.Intensity, sunR.Spread
		local function sunBack()
			if sunNew then pcall(function() sunR:Destroy() end) else pcall(function() sunR.Intensity, sunR.Spread = srI, srS end) end
		end
		task.delay(DUR + 0.3, sunBack)
		if scr then L.onEnd(sunBack) end
		local dustP = L.part({ Size = Vector3.new(260, 60, 260), CFrame = CFrame.new(o + Vector3.new(0, 30, 0)) })
		local dust = L.pe(dustP, { Texture = L.T("star.png"), Shape = Enum.ParticleEmitterShape.Box, Rate = 0, Speed = NR(0.5, 2),
			SpreadAngle = Vector2.new(180, 180), Lifetime = NR(3, 5), Size = NS({ K(0, 0), K(0.3, 0.35), K(1, 0) }), Color = CS(C1, W),
			LightEmission = 1, Brightness = 3, Acceleration = Vector3.new(0, -0.6, 0), Rotation = NR(0, 360), RotSpeed = NR(-60, 60) })
		objs[#objs + 1] = dustP
		local function skyA(t) return c01(t / 1.5) * (1 - c01((t - HIT - 1.5) / 2)) end

		local SH = o + Vector3.new(0, 150, 0)
		local FLIP = CFrame.Angles(math.pi, 0, 0)
		local h1, h1M = L.mesh("disc.mesh", "runering.png", C1, 2.6, Vector3.new(1, 1, 1))
		local h2, h2M = L.mesh("disc.mesh", "glyphs.png", C2:Lerp(W, 0.3), 2.2, Vector3.new(1, 1, 1))
		local h3, h3M = L.mesh("disc.mesh", "ring_c.png", W, 2.4, Vector3.new(1, 1, 1))
		h1.Transparency, h2.Transparency, h3.Transparency = 1, 1, 1
		objs[#objs + 1] = h1 objs[#objs + 1] = h2 objs[#objs + 1] = h3

		local angels = {}
		local fwdA = math.atan2(fwd.Z, fwd.X)
		for i = 1, 8 do
			local a = fwdA + (i - 0.5) / 8 * math.pi * 2
			local pos = o + Vector3.new(math.cos(a) * 85, rnd(30, 44), math.sin(a) * 85)
			local at = L.att(pos)
			local bb = L.new("BillboardGui", { Adornee = at, Size = UDim2.new(20, 0, 40, 0), LightInfluence = 0, Brightness = 5,
				AlwaysOnTop = false, MaxDistance = 4000, ResetOnSpawn = false }, L.root)
			local function lay(img) return L.new("ImageLabel", { Image = L.T(img), BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1),
				ImageColor3 = W:Lerp(C1, 0.25), ImageTransparency = 1 }, bb) end
			angels[i] = { up = lay("angel_up.png"), bow = lay("angel_bow.png"), t0 = 1.6 + i * 0.09 }
			objs[#objs + 1] = at objs[#objs + 1] = bb
		end

		local function pillar()
			local core = L.part({ Shape = Enum.PartType.Cylinder, Material = Enum.Material.Neon, Color = W, Transparency = 1 })
			local glow = L.part({ Shape = Enum.PartType.Cylinder, Material = Enum.Material.Neon, Color = Color3.fromRGB(255, 214, 150), Transparency = 1 })
			local fp = L.part({ Size = Vector3.new(7, 40, 7), CFrame = CFrame.new(o + Vector3.new(0, 20, 0)) })
			local fe = L.pe(fp, { Texture = L.T("feather.png"), Shape = Enum.ParticleEmitterShape.Box, Rate = 0, Speed = NR(6, 14),
				EmissionDirection = Enum.NormalId.Top, Lifetime = NR(2, 3), Size = NS({ K(0, 0.6), K(1, 1.2) }), Color = CS(W, C1),
				LightEmission = 0.7, Brightness = 2, Rotation = NR(0, 360), RotSpeed = NR(-90, 90), Transparency = NS({ K(0, 0), K(0.8, 0.2), K(1, 1) }) })
			local H = 1000
			L.fx(3.4, function(_, tt)
				local drop = L.outQuad(c01(tt / 0.25))
				local len = math.max(0.1, H * drop)
				local a = (1 - c01((tt - 1.6) / 1.8))
				local w = (12 + 6 * c01(1 - math.abs(tt - 0.3) / 0.3)) * (0.4 + 0.6 * a)
				core.Size = Vector3.new(len, w * 0.4, w * 0.4)
				glow.Size = Vector3.new(len, w, w)
				local cf = CFrame.new(o + Vector3.new(0, H - len / 2, 0)) * CFrame.Angles(0, 0, math.pi / 2)
				core.CFrame, glow.CFrame = cf, cf
				core.Transparency = 1 - 0.45 * a * drop
				glow.Transparency = 1 - 0.35 * a * drop
				fe.Rate = (tt > 0.3 and a > 0.3) and 45 or 0
			end, { core, glow, fp })
		end

		local function bloomWave(j)
			local rr = 12 + j * 28
			L.groundWave(o, "runering.png", C1, rr * 2 - 8, rr * 2 + 24, 1.1, 2.2)
			L.groundWave(o, "ring_c.png", GOLD:Lerp(W, 0.3), rr * 2 - 4, rr * 2 + 30, 0.8, 2.6)
			local n = 8 + j * 4
			for q = 1, n do
				local a = q / n * math.pi * 2 + rnd(-0.15, 0.15)
				local pos = o + Vector3.new(math.cos(a) * rr, 0.08, math.sin(a) * rr)
				local g, gm = L.mesh("disc.mesh", "glyph.png", GOLD, 3, Vector3.new(0.1, 1, 0.1))
				local sz = rnd(5, 9)
				L.fx(1.6, function(kk)
					local s2 = sz * L.outBack(c01(kk / 0.25))
					gm.Scale = Vector3.new(s2, 1, s2)
					g.CFrame = CFrame.new(pos) * CFrame.Angles(0, kk * 2 + a, 0)
					L.tint(gm, GOLD:Lerp(W, 0.6 * (1 - c01(kk / 0.3))), 1.5 + 2.5 * (1 - kk))
					g.Transparency = 1 - 0.9 * (1 - c01((kk - 0.4) / 0.6))
				end, { g })
			end
		end
		local hit, an_pillar = false, false
		L.fx(DUR, function(k, t)
			local open = L.outQuad(c01(t / 1.4))
			local fade = c01((t - HIT - 1.2) / 2.4)

			local sa = skyA(t)
			wsky.set(sa)
			sunR.Intensity = srI + (0.3 - srI) * sa
			sunR.Spread = srS + (1 - srS) * sa
			dust.Rate = 160 * sa

			local hf = L.outQuad(c01((t - 0.6) / 1.8))
			local flare = t >= HIT and (1 - c01((t - HIT) / 1.2)) or 0
			local hs = 260 * hf * (1 + 0.15 * L.outQuad(c01((t - HIT) / 0.6)))
			local ha = hf * (1 - c01((t - HIT - 1.5) / 2))
			h1M.Scale = Vector3.new(hs, 1, hs) h1.CFrame = CFrame.new(SH) * FLIP * CFrame.Angles(0, t * 0.12, 0)
			h2M.Scale = Vector3.new(hs * 0.72, 1, hs * 0.72) h2.CFrame = CFrame.new(SH - Vector3.new(0, 1, 0)) * FLIP * CFrame.Angles(0, -t * 0.2, 0)
			h3M.Scale = Vector3.new(hs * 1.08, 1, hs * 1.08) h3.CFrame = CFrame.new(SH + Vector3.new(0, 1, 0)) * FLIP
			L.tint(h1M, C1:Lerp(W, flare * 0.6), 2.6 + 2 * flare)
			h1.Transparency, h2.Transparency, h3.Transparency = 1 - 0.85 * ha, 1 - 0.75 * ha, 1 - 0.6 * ha

			local bow = c01((t - WALK0) / 0.6) * (1 - c01((t - HIT) / 0.3))
			for _, an in ipairs(angels) do
				local aa = c01((t - an.t0) / 0.6) * (1 - c01((t - HIT - 1.5) / 2))
				an.up.ImageTransparency = 1 - aa * (1 - bow) * (0.85 + 0.15 * flare)
				an.bow.ImageTransparency = 1 - aa * bow * 0.85
			end

			if not an_pillar and t >= HIT - 0.25 then an_pillar = true pillar() end

			local cs = 40 + 60 * open
			cl1M.Scale = Vector3.new(cs, 9, cs)
			cl1.CFrame = CFrame.new(cTop) * CFrame.Angles(0, -t * 0.25, 0)
			cl1.Transparency = 1 - 0.85 * open * (1 - fade)
			cl2M.Scale = Vector3.new(cs * 4, 1, cs * 4)
			cl2.CFrame = CFrame.new(cTop + Vector3.new(0, 3, 0)) * CFrame.Angles(0, t * 0.1, 0)
			cl2.Transparency = 1 - 0.7 * open * (1 - fade)
			local gs = 6 + 30 * L.outQuad(c01((t - 0.4) / 1.2))
			gapM.Scale = Vector3.new(gs, 1, gs) gap.CFrame = CFrame.new(cTop - Vector3.new(0, 1, 0))
			gap.Transparency = 1 - 0.97 * c01((t - 0.4) / 0.6) * (1 - fade)
			gapRM.Scale = Vector3.new(gs * 0.7, 1, gs * 0.7) gapR.CFrame = CFrame.new(cTop - Vector3.new(0, 1.2, 0)) * CFrame.Angles(0, t * 0.6, 0)
			gapR.Transparency = 1 - 0.8 * c01((t - 0.4) / 0.6) * (1 - fade)

			local ca = c01((t - 0.6) / 0.9) * (1 - fade) * (0.85 + 0.15 * math.sin(t * 2.2))
			local boost = c01((t - DOOR) / 0.3) * (1 - c01((t - DOOR - 0.3) / 1))
			cone.Width0, cone.Width1 = 14 * ca + 0.1, 30 * ca + 0.1
			cone.Transparency = NS({ K(0, 1 - 0.75 * ca), K(0.7, 1 - 0.55 * ca - 0.2 * boost), K(1, 1 - 0.35 * ca) })
			coneC.Width0, coneC.Width1 = 6 * ca + 0.1, 13 * ca + 0.1
			coneC.Transparency = NS({ K(0, 1 - 0.6 * ca), K(1, 1 - 0.3 * ca - 0.2 * boost) })
			poolM.Scale = Vector3.new(26 * ca, 1, 26 * ca)
			pool.CFrame = CFrame.new(T + Vector3.new(0, 0.05, 0))
			pool.Transparency = 1 - 0.6 * ca
			sparkle.Rate = 45 * open * (1 - fade)
			gapLight.Brightness = 3 * open * (1 - fade)
			fall.Rate = 25 * open * (1 - c01((t - HIT - 1) / 1.5))

			local gu = L.outQuad(c01((t - 0.9) / 0.8))
