				g.p.Size = Vector3.new(1.1, math.max(h, 0.1), 1.1)
				g.p.CFrame = CFrame.new(g.base + Vector3.new(0, h / 2, 0))
				g.p.Transparency = gu > 0.02 and (0.06 + 0.94 * fade) or 1
			end
			archM.Scale = Vector3.new(9.2 * gu, 1, 9.2 * gu) arch.CFrame = gateCF * CFrame.new(0, 0, -6) * CFrame.Angles(0, t * 0.8, 0)
			arch.Transparency = 1 - 0.9 * gu * (1 - fade)
			local dOpen = c01((t - 1.6) / 0.8)
			doorM.Scale = Vector3.new(8 * dOpen, 1, 13) door.CFrame = gateCF
