			lintel.CFrame = G * CFrame.new(0, 13 * gu + 0.45, 0)
			lintel.Transparency = gu > 0.95 and (0.06 + 0.94 * fade) or 1
			local lo = L.outBack and L.outBack(c01((t - DOOR) / 0.55)) or L.outQuad(c01((t - DOOR) / 0.55))
			for _, lf in ipairs(leaves) do
				local th = -lf.s * lo * math.rad(105)
				local cf = G * CFrame.new(lf.s * 3.65, 0, 0) * CFrame.Angles(0, th, 0) * CFrame.new(-lf.s * 1.95, 6.3 * gu, 0)
				lf.p.Size = Vector3.new(3.9, math.max(12.3 * gu, 0.1), 0.3)
				lf.p.CFrame = cf
				lf.p.Transparency = gu > 0.05 and (0.08 + 0.92 * fade) or 1
				lf.glm.Scale = Vector3.new(3.2, 1, 3.2) * gu
				lf.gl.CFrame = cf * CFrame.new(0, 1.5, -0.2) * CFrame.Angles(math.rad(90), 0, 0)
				lf.gl.Transparency = gu > 0.05 and (0.2 + 0.8 * math.max(fade, c01((t - DOOR) / 0.4))) or 1
			end
			if not doorOpened and t >= DOOR then
				doorOpened = true
				S:flash(C2:Lerp(W, 0.6), 0.45) S:shake(0.8, 0.5)
				stepMote.CFrame = CFrame.new(T + Vector3.new(0, 4, 0)) sm:Emit(40)
				L.groundWave(T + Vector3.new(0, 0.2, 0), "ring_c.png", W, 2, 18, 0.6)

				local wv, wvm = L.mesh("disc.mesh", "glowui.png", W, 2.4)
				L.fx(0.9, function(kk)
					local p = (T + Vector3.new(0, 5, 0)):Lerp(B + Vector3.new(0, 1.5, 0), L.outQuad(kk))
					wv.CFrame = CFrame.lookAt(p, p + dirH) * CFrame.Angles(math.rad(90), 0, 0)
					wvm.Scale = Vector3.new(9 + 4 * kk, 1, 11 - 6 * kk)
					wv.Transparency = 0.25 + 0.75 * kk
				end, { wv })
			end

			if not gateGone and fade > 0.02 then
				gateGone = true
				riseP.Size = Vector3.new(9, 13, 1.5) riseP.CFrame = G * CFrame.new(0, 6.5, 0) riseE:Emit(70)
			end
			local sp = c01((t - DOOR) / 0.4) * (1 - c01((t - HIT) / 0.8))
			spill.Width0, spill.Width1 = 7 * sp + 0.1, 5 * sp + 0.1
			spill.Transparency = NS({ K(0, 1 - 0.8 * sp), K(1, 1 - 0.25 * sp) })

			local built = 0
			for i, s in ipairs(steps) do if t >= s.at then built = i end end
			local rgone = c01((t - HIT - 0.4) / 1.2)
			for _, r in ipairs(rails) do
				local endP = built > 0 and steps[built].pos or T
				r.a1.WorldPosition = endP + side * r.s * 3.1 + Vector3.new(0, 0.6, 0)
				r.a0.WorldPosition = T:Lerp(B, rgone) + side * r.s * 3.1 + Vector3.new(0, 0.6, 0)
				r.b.Transparency = NS(built > 1 and (0.1 + 0.9 * rgone) or 1)
			end

			for i, s in ipairs(steps) do
				local u = c01((t - s.at) / 0.25)
				local gone = c01((t - HIT - 0.4 - (i - 1) * 0.06) / 0.4)
				local wd = 6 * L.outQuad(u) + 0.1
				local lift = Vector3.new(0, 2 * gone, 0)
				local pcf = CFrame.lookAt(s.pos, s.pos + dirH) + lift
				local press = c01(1 - (t - s.hitT) / 0.5)
				s.p.Size = Vector3.new(wd, 0.4, run * 1.05)
				s.p.CFrame = pcf
				s.p.Transparency = u > 0 and (0.3 + 0.7 * gone) or 1
				s.p.Color = W:Lerp(C2:Lerp(W, 0.7), u * (1 - press))
				s.edge.Size = Vector3.new(wd, 0.12, 0.18)
				s.edge.CFrame = pcf * CFrame.new(0, 0.2, -run * 0.52)
				s.edge.Transparency = u > 0 and (0.06 + 0.94 * gone) or 1
				local es = (8 + 5 * press) * u * (1 - gone)
				s.edm.Scale = Vector3.new(es, 1, es)
				s.ed.CFrame = CFrame.new(s.pos - Vector3.new(0, 0.2, 0) + lift)
				s.ed.Transparency = u > 0 and (1 - (0.6 + 0.35 * press) * (1 - u * 0.5) * (1 - gone)) or 1
				if u > 0 and u < 1 and t - s.at < 0.03 then stepMote.CFrame = CFrame.new(s.pos) sm:Emit(8) end

				if not s.halo and i % 2 == 0 and t >= s.at + 0.2 then
					s.halo = true
					choirHalo(s.pos + side * (i % 4 == 0 and 3.1 or -3.1) + Vector3.new(0, 2.6, 0))
				end

				if gone > 0 and not s.shed then
					s.shed = true
					riseP.Size = Vector3.new(6, 0.4, run) riseP.CFrame = pcf riseE:Emit(10)
				end
			end

			if not hit then
				local wu = c01((t - WALK0) / (HIT - WALK0))

				local wk = c01(wu / 0.8)
				local pos = (T + dirH * 0.5):Lerp(B, wk)
				local bob = wk < 1 and math.abs(math.sin(wk * N * math.pi)) * 0.25 or 0
				local reach = L.outQuad(c01((wu - 0.8) / 0.12))
				local toO = Vector3.new(o.X - B.X, 0, o.Z - B.Z)
				local face = (toO.Magnitude > 0.1) and dirH:Lerp(toO.Unit, reach) or dirH
				local hp = pos + Vector3.new(0, hipH + bob, 0)
				local figCF = CFrame.lookAt(hp, hp + face)
				local fin = c01((t - WALK0 + 0.3) / 0.5)
				local hand = setFig(figCF, t > WALK0 - 0.3 and (1 - 0.85 * fin) or 1, W:Lerp(C2, 0.3 + 0.2 * math.sin(t * 6)), reach)
				figW.set(figCF, 0.25 + 0.15 * math.sin(t * 3) + 0.3 * reach, math.sin(t * 2.5) * math.rad(6), 4.4, t > WALK0 - 0.3 and (1 - 0.8 * fin) or 1, C2:Lerp(W, 0.4), 2.4)

				reachA.WorldPosition = hand
				reachB.WorldPosition = o + Vector3.new(0, hipH, 0)
				local rb = c01((wu - 0.86) / 0.08)
