					stepMote.CFrame = CFrame.new(st.pos) sm:Emit(6)
				end
				if t > WALK0 - 0.3 then stepMote.CFrame = CFrame.new(pos) figLight.Brightness = 4 sm.Rate = 30 end
				local sgu = c01((t - WALK0) / (HIT - WALK0))
				sgm.Scale = Vector3.new(22 * sgu, 1, 22 * sgu) sg.CFrame = CFrame.new(o + Vector3.new(0, 0.07, 0)) * CFrame.Angles(0, t * 0.25, 0)
				sg.Transparency = 1 - 0.85 * sgu
				sg2m.Scale = Vector3.new(25 * sgu, 1, 25 * sgu) sg2.CFrame = CFrame.new(o + Vector3.new(0, 0.09, 0)) * CFrame.Angles(0, -t * 0.5, 0)
				sg2.Transparency = 1 - 0.8 * sgu
				if t > WALK0 then S:shake(0.05 + 0.25 * wu, 0.2) end
				if t >= HIT then
					hit = true
					setFig(ch.hrp.CFrame, 1, nil, 0)
					figW.set(ch.hrp.CFrame, 1, 0, 4.4, 1)
					reachBeam.Transparency = NS(1)
					riseP.Size = Vector3.new(3, 5, 2) riseP.CFrame = CFrame.new(B + Vector3.new(0, hipH, 0)) riseE:Emit(40)
					featherSpiral()
					sm.Rate, figLight.Brightness = 0, 0

					appear(GOLD, hideTok)
					hl.FillTransparency = 0
					S.cc.Saturation, S.cc.Contrast, S.cc.Brightness, S.cc.TintColor = -0.92, 0.25, -0.08, W
					L.hitStop(0.5)
					task.delay(0.5, function() S:flash(GOLD:Lerp(W, 0.55), 0.9) S:shake(2.4, 1.1) end)
					L.after(0.02, function()
						blessFlash(o, 1.3)
						L.groundWave(o, "ring_c.png", C1, 10, 1400, 5.4, 2.6)
						local fb = L.part({ Transparency = 0, Material = Enum.Material.Neon, Color = W, CFrame = CFrame.new(o + Vector3.new(0, 2.5, 0)) })
						local fbm = L.new("SpecialMesh", { MeshType = Enum.MeshType.Sphere }, fb)
						L.fx(0.6, function(kk) local s = (1 + 26 * L.outQuad(kk)) * 10 fbm.Scale = Vector3.one * s fb.Color = W:Lerp(C2, kk) fb.Transparency = c01(kk * 1.3) end, { fb })
						for j = 0, 3 do L.after(j * 0.12, function() vring(o, j % 2 == 0 and W or C1, 6 + j * 2, 12 + j * 3, 1.1) end) end
						for j = 0, 5 do L.after(j * 0.18, function() bloomWave(j) end) end
					end)
				end
			else
				sg.Transparency = 1 - 0.85 * (1 - fade) sg2.Transparency = 1 - 0.8 * (1 - fade)
				L.tint(sgm, C1:Lerp(W, (1 - fade) * 0.5), 3)
				local w = t - HIT
				local openW = L.outQuad(c01(w / 0.35))
				local beat = math.sin(c01(w / 1.6) * math.pi * 2) * math.rad(18) * (1 - c01(w / 2.4))
				wg.set(ch.hrp.CFrame, openW, beat, 13 * (1 - 0.3 * fade), 0.06 + 0.94 * fade, C2:Lerp(W, 1 - c01(w / 0.6)), 2.4 + 2 * (1 - c01(w / 0.6)))
				hl.FillTransparency = math.min(1, hl.FillTransparency + 0.012)
			end
		end, objs)
		for i = #L.live, 1, -1 do
			if L.live[i].objs == objs then L.live[i].done = function() wsky.set(0) sunBack() end break end
		end
		L.fx(DUR, function() end, { fig.model })
	end


	local shorts = {}

	shorts[1] = function()
		local o = ch.feet
		local DUR, LAND = 2.6, 1.15
		local rr, rrm = L.mesh("disc.mesh", "runering.png", C1, 2.6)
		local rg, rgm = L.mesh("disc.mesh", "glyphs2.png", C2, 2.4)
		local rc, rcm = L.mesh("disc.mesh", "ring_c.png", W, 3.2)
		local rgl, rglm = L.mesh("disc.mesh", "glowui.png", C1, 1.4)
		local trailP = L.part({ Size = Vector3.new(1, 0.2, 1) })
		local tm = moteE(trailP, { Shape = Enum.ParticleEmitterShape.Box, Rate = 0, Speed = NR(0, 0.6), Lifetime = NR(0.5, 0.9), Acceleration = Vector3.new(0, -1, 0) })
		local beamA, beamB = L.att(o), L.att(o)
		local bm = L.beam(beamA, beamB, { Texture = L.T("softbeam.png"), Width0 = 0.5, Width1 = 0.5, Brightness = 3, Segments = 2, Color = CS(C2, W), Transparency = NS(1) })
		local landed = false
		L.fx(DUR, function(k, t)
			local head = ch.head.Position + Vector3.new(0, 1.15, 0)
			local d = c01(t / LAND)
			local e = d * d * (3 - 2 * d)
			local h = 18 * (1 - e)
			local pos = head + Vector3.new(0, h, 0)
			local s = 2.3 + 15 * (1 - e) ^ 1.4
			local after = c01((t - LAND - 0.25) / 0.9)
			local spin = t * (0.6 + 4 * e)
			local a = c01(t / 0.3)
			rrm.Scale = Vector3.new(s, 1, s) rr.CFrame = CFrame.new(pos) * CFrame.Angles(0, spin, 0)
			rr.Transparency = 1 - 0.85 * a * (1 - c01((t - LAND + 0.15) / 0.2))
			local gs = s * 0.78
			rgm.Scale = Vector3.new(gs, 1, gs) rg.CFrame = CFrame.new(pos + Vector3.new(0, 0.02, 0)) * CFrame.Angles(0, -spin * 1.3, 0)
			rg.Transparency = 1 - 0.8 * a * (1 - c01((t - LAND + 0.25) / 0.25))
			local cs = landed and 2.3 + 1.6 * (1 - L.outQuad(c01((t - LAND) / 0.25))) or s * 1.04
			rcm.Scale = Vector3.new(cs, 1, cs) rc.CFrame = CFrame.new(pos + Vector3.new(0, 0.04, 0))
			rc.Transparency = 1 - (0.35 + 0.6 * e) * a * (1 - after)
			L.tint(rcm, C2:Lerp(W, landed and 1 - c01((t - LAND) / 0.6) or 0.4 * e), 3.2)
