			rgl.Transparency = 1 - 0.5 * a * (1 - after)
			trailP.CFrame = CFrame.new(pos) trailP.Size = Vector3.new(math.max(1, s * 0.7), 0.2, math.max(1, s * 0.7))
			tm.Rate = landed and 0 or 60
			beamA.WorldPosition, beamB.WorldPosition = pos, head
			bm.Transparency = NS(landed and 1 or 1 - 0.5 * a * c01((t - 0.4) / 0.4))
			if not landed and t >= LAND then
				landed = true
				bodyFlare(W) blessFlash(o, 0.8)
				burstP.CFrame = CFrame.new(head) burst:Emit(30)
				L.groundWave(o, "runering.png", C1, 4, 46, 1.1, 2.6)
				L.after(0.12, function() L.groundWave(o, "glyphs2.png", C2, 3, 34, 1.2, 2.4) end)
				L.punch(1.08, 0.25)
			end
			if landed then hl.FillTransparency = math.min(1, hl.FillTransparency + 0.025) end
		end, { rr, rg, rc, rgl, trailP, beamA, beamB, bm })
