	shorts[2] = function()
		local o = ch.feet
		local DUR, PEAK = 2.9, 1.3
		local fwd = camBasis()
		local base = o + fwd * 7
		local sunD, sunM = L.mesh("disc.mesh", "glowui.png", C1, 2.4)
		local core, coreM = L.mesh("disc.mesh", "glowui.png", W, 3.2)
		local fl, flM = L.mesh("disc.mesh", "flare.png", C2, 2.6)
		local center = L.att(base)
		local rays = {}
		for i = 1, 12 do
			local tip = L.att(base)
			local b = L.beam(center, tip, { Texture = L.T("softbeam.png"), Width0 = 1.6, Width1 = 0.1, Brightness = 2.4, Segments = 2,
				Color = CS(C2:Lerp(W, 0.4), C1), Transparency = NS({ K(0, 0.3), K(1, 1) }) })
			rays[i] = { tip = tip, b = b, ph = (i - 1) / 12 * math.pi * 2, len = i % 2 == 0 and 1 or 0.65 }
		end
		local horizon, hm = L.mesh("disc.mesh", "glowui.png", C1, 1.6)
		local mp = L.part({ Size = Vector3.new(6, 0.2, 6), CFrame = CFrame.new(base) })
		local mo = moteE(mp, { Shape = Enum.ParticleEmitterShape.Box, Rate = 0, Speed = NR(1, 3), Lifetime = NR(0.8, 1.4) })
		local objs = { sunD, core, fl, center, horizon, mp }
		for _, r in ipairs(rays) do objs[#objs + 1] = r.tip objs[#objs + 1] = r.b end
		local peaked = false
		L.fx(DUR, function(k, t)
			local cam = workspace.CurrentCamera.CFrame
			local rise = L.outQuad(c01(t / PEAK))
			local set = c01((t - PEAK - 0.5) / 1.1)
			local y = -3 + 9 * rise + 2 * set
			local p = base + Vector3.new(0, y, 0)
			local a = c01(t / 0.25) * (1 - set)
			local pulse = peaked and 1 + 0.6 * (1 - L.outQuad(c01((t - PEAK) / 0.4))) or 1
			local s = (5 + 5 * rise) * pulse
			sunM.Scale = Vector3.new(s * 2, 1, s * 2) sunD.CFrame = faceCam(p) sunD.Transparency = 1 - 0.7 * a
			coreM.Scale = Vector3.new(s * 0.8, 1, s * 0.8) core.CFrame = faceCam(p + (cam.Position - p).Unit * 0.1) core.Transparency = 1 - 0.95 * a
			flM.Scale = Vector3.new(s * 1.6, 1, s * 1.6) fl.CFrame = faceCam(p + (cam.Position - p).Unit * 0.05) * CFrame.Angles(0, t * 0.4, 0)
			fl.Transparency = 1 - 0.6 * a * rise

			local hs = 10 + 22 * rise
			hm.Scale = Vector3.new(hs, 1, hs) horizon.CFrame = CFrame.new(base + Vector3.new(0, 0.08, 0))
			horizon.Transparency = 1 - 0.55 * c01(t / 0.3) * (1 - c01((t - PEAK) / 1))
			center.WorldPosition = p

			local reach = (6 + 26 * rise) * pulse
			for _, r in ipairs(rays) do
				local th = r.ph + t * 0.5
				r.tip.WorldPosition = p + (cam.RightVector * math.cos(th) + cam.UpVector * math.sin(th)) * reach * r.len
				local w = 1 + 2.5 * rise
				r.b.Width0 = w
				r.b.Transparency = NS({ K(0, 1 - 0.75 * a * rise), K(1, 1) })
			end
			mp.CFrame = CFrame.new(p - Vector3.new(0, 1, 0))
			mo.Rate = t < PEAK and 60 or 0
			if not peaked and t >= PEAK then
				peaked = true
				bodyFlare(C2:Lerp(W, 0.6)) blessFlash(o, 0.8)
				L.groundWave(o, "ring_c.png", C2, 3, 60, 1, 2.6)
				L.punch(1.06, 0.25)
			end
			if peaked then hl.FillTransparency = math.min(1, hl.FillTransparency + 0.025) end
		end, objs)
	end

