	shorts[4] = function()
		local o = ch.feet
		local DUR, FALL0, FILL = 2.9, 0.1, 1.45

		local pts = {}
		for _, p in ipairs(ch.char:GetDescendants()) do
			if p:IsA("BasePart") and p.Name ~= "HumanoidRootPart" and p.Transparency < 1 and ((savedLTM and savedLTM[p]) or p.LocalTransparencyModifier) < 1 and p.Size.Magnitude > 1.2 then
				if p.Size.Y > 1.5 then local u = p.CFrame.UpVector * p.Size.Y * 0.38 pts[#pts + 1] = p.Position + u pts[#pts + 1] = p.Position - u else pts[#pts + 1] = p.Position end
			end
		end
		if #pts < 2 then pts = { o + Vector3.new(0, 4.5, 0), o + Vector3.new(0, 3, 0), o + Vector3.new(0, 1, 0) } end
		local links, inTree = {}, { [1] = true }
		for _ = 2, #pts do
			local bi, bj, bd = nil, nil, math.huge
			for i in pairs(inTree) do
				for j = 1, #pts do
					if not inTree[j] then
						local d = (pts[i] - pts[j]).Magnitude
						if d < bd then bi, bj, bd = i, j, d end
					end
				end
			end
			inTree[bj] = true
			links[#links + 1] = { bi, bj }
		end
		local fig = figure(C2)
		local hideTok = setHidden(true)
		task.delay(DUR + 0.1, function() setHidden(false, hideTok) end)
		local stars, objs = {}, { fig.model }
		for i, p in ipairs(pts) do
			local from = p + Vector3.new(rnd(-14, 14), rnd(30, 45), rnd(-14, 14))
			local s = L.part({ Shape = Enum.PartType.Ball, Material = Enum.Material.Neon, Color = W, Transparency = 1, Size = Vector3.one * 0.35 })
			local a0 = L.new("Attachment", { Position = Vector3.new(0, 0.15, 0) }, s)
			local a1 = L.new("Attachment", { Position = Vector3.new(0, -0.15, 0) }, s)
			L.pe(s, { Texture = L.T("star.png"), Color = CS(W, C2), LightEmission = 1, Brightness = 5, Rate = 40, Speed = NR(0, 0.4), Lifetime = NR(0.25, 0.45),
				Size = NS({ K(0, 0.35), K(1, 0) }), Rotation = NR(0, 90), RotSpeed = NR(-200, 200), Transparency = NS({ K(0, 0), K(1, 1) }) })
			L.new("Trail", { Attachment0 = a0, Attachment1 = a1, Texture = L.T("beamb.png"), LightEmission = 1, Brightness = 5, Lifetime = 0.35,
				FaceCamera = true, Color = CS(W, C2), Transparency = NS(0, 1), WidthScale = NS(1, 0.2) }, s)
			local g, gm = L.mesh("disc.mesh", "star.png", C2, 3)
			local at = L.att(p)
			stars[i] = { s = s, g = g, gm = gm, from = from, to = p, t0 = FALL0 + (i - 1) * 0.045, at = at }
			objs[#objs + 1] = s objs[#objs + 1] = g objs[#objs + 1] = at
		end
		local beams = {}
		for i, l in ipairs(links) do
			local b = L.beam(stars[l[1]].at, stars[l[2]].at, { Width0 = 0.12, Width1 = 0.12, Brightness = 5, Segments = 2, Color = CS(W, C2), Transparency = NS(1) })
			beams[i] = { b = b, a = l[1], c = l[2] }
			objs[#objs + 1] = b
		end
		local filled = false

		local hiY, loY = -math.huge, math.huge
		for _, rel in pairs(fig.rel) do hiY = math.max(hiY, rel.Position.Y) loY = math.min(loY, rel.Position.Y) end
		local span = math.max(0.5, hiY - loY)
		local driftP = L.part({ Size = Vector3.one * 0.5 })
		local drift = moteE(driftP, { Rate = 0, Speed = NR(0.5, 1.5), Lifetime = NR(1.4, 2.2), Acceleration = Vector3.new(0, 2.5, 0), Size = NS({ K(0, 0), K(0.2, 0.45), K(1, 0) }) })
		objs[#objs + 1] = driftP
		L.fx(DUR + 2.2, function() end, { driftP })
		objs[#objs] = nil
		L.fx(DUR, function(k, t)
			local after = c01((t - FILL) / 0.8)
			for _, st in ipairs(stars) do
				local u = c01((t - st.t0) / 0.5)
				local landed = u >= 1
				st.s.CFrame = CFrame.new(st.from:Lerp(st.to, u * u))
				st.s.Transparency = (u > 0 and not landed) and 0 or 1
				st.landedAt = st.landedAt or (landed and t or nil)
				local pop = st.landedAt and c01((t - st.landedAt) / 0.15) or 0
				local sz = (0.6 + 1.6 * (1 - pop) + 0.15 * math.sin(t * 12 + st.t0 * 40)) * (1 - after)
				st.gm.Scale = Vector3.new(sz, 1, sz)
				st.g.CFrame = faceCam(st.to) * CFrame.Angles(0, t * 2, 0)
				st.g.Transparency = landed and math.max(0.06, after) or 1
			end
			for _, b in ipairs(beams) do
				local la, lc = stars[b.a].landedAt, stars[b.c].landedAt
				local on = (la and lc) and c01((t - math.max(la, lc)) / 0.15) or 0
				b.b.Transparency = NS(1 - 0.85 * on * (1 - after))
			end

			local root = ch.hrp.CFrame
			for g, rel in pairs(fig.rel) do
				if g.Parent then
					local h = (hiY - rel.Position.Y) / span
					local fu = c01((t - (FILL - 0.45) - h * 0.3) / 0.15)
					g.CFrame = root * rel
					g.Transparency = 1 - 0.9 * fu * (1 - after)
					g.Color = C2:Lerp(W, fu)
				end
			end
			if not filled and t >= FILL then
				filled = true
				appear(W, hideTok)
				blessFlash(o, 0.7)
				for i, st in ipairs(stars) do if i % 2 == 1 then driftP.CFrame = CFrame.new(st.to) drift:Emit(2) end end
			end
			if filled then hl.FillTransparency = math.min(1, hl.FillTransparency + 0.025) end
		end, objs)
	end

	shorts[5] = function()
		local o = ch.feet
		local DUR, POP = 2.6, 1.25
		local pts, objs = {}, {}
		for i = 1, 18 do
