				f = featherE(p, { Rate = 0, Speed = NR(0.5, 1.5), Lifetime = NR(0.4, 0.7), SpreadAngle = Vector2.new(180, 180) }),
				m = moteE(p, { Rate = 0, Speed = NR(0, 1), Lifetime = NR(0.3, 0.5) }) }
