			Lifetime = NR(2.2, 3), Acceleration = Vector3.new(0, -0.8, 0) })

		local rainP = L.part({ Size = Vector3.new(14, 0.5, 14), CFrame = CFrame.new(o + Vector3.new(0, 14, 0)) })
		local rain = featherE(rainP, { Rate = 0, Shape = Enum.ParticleEmitterShape.Box, EmissionDirection = Enum.NormalId.Bottom, Speed = NR(0.5, 1.5),
			Lifetime = NR(3.5, 4.5), Acceleration = Vector3.new(0, -1.2, 0), Drag = 0.6 })
		L.fx(DUR + 4.5, function() end, { rainP, burstP })
		local popped = false
		L.fx(DUR, function(k, t)
			local grow = L.outQuad(c01(t / 0.4))
			local out = c01((t - POP) / 0.4)
			for _, q in ipairs(pts) do
				local y = q.h * 10 * grow
				local r = (2.2 + q.h * 2.6) * (1 - 0.45 * c01(t / POP)) * (1 + out * 3)
				local a = q.ph - t * (5 + 7 * c01(t / POP))
				q.p.CFrame = CFrame.new(o + Vector3.new(math.cos(a) * r, y + 0.4, math.sin(a) * r))
				local on = t < POP
				q.f.Rate = on and 18 or 0
				q.m.Rate = on and 40 or 0
			end
			local cw = popped and 7 * (1 - L.outQuad(c01((t - POP) / 0.9))) or 2.4 * c01((t - 0.5) / (POP - 0.5))

			col.a.WorldPosition = o + Vector3.new(0, popped and 30 + 170 * L.outQuad(c01((t - POP) / 0.2)) or 30, 0)
			rain.Rate = (popped and t < POP + 1.1) and 30 or 0
			col.soft.Width0, col.soft.Width1, col.core.Width0, col.core.Width1 = cw, cw, cw * 0.3, cw * 0.3
			if not popped and t >= POP then
				popped = true
				fb:Emit(60)
				bodyFlare(W)
				blessFlash(o, 0.8)
				for j = 0, 2 do L.after(j * 0.1, function() vring(o, j % 2 == 0 and W or C1, 4 + j, 7 + j * 2, 0.9) end) end
			end
			if popped then hl.FillTransparency = math.min(1, hl.FillTransparency + 0.025) end
		end, objs)
	end
	local cur = 1
	local function arrive(short)
		if short then return shorts[cur]() end
		return arriveFull(false)
	end


	local travel, ghostT, boomT, blessT, age, side = 0, 0, 0, 0, 0, 1
	local lastPos
	local function step(dt)
		age += dt
		local iw, on, sprint = ch.iw, ch.on, ch.sprint
		rig.main.Enabled = on
		rig.main.Lifetime = 0.3 + 0.4 * c01(ch.spd / 30)
