				local nIn = c01((it - 0.5) / 0.4)
				if t >= nextG then gEnd = t + 0.14 nextG = t + rnd(2.5, 4.5) end
				local glitch = t < gEnd or (nIn > 0 and nIn < 1 and math.random() < 0.5)
				nm.TextTransparency = nIn >= 1 and 0 or (glitch and 0.2 or 1 - nIn)
				role.TextTransparency = 1 - c01((it - 0.8) / 0.3)
				if glitch then
					local j = rnd(-0.015, 0.015)
					nm.Position = UDim2.fromScale(j, rnd(-0.04, 0.04))
					gh1.Position, gh2.Position = UDim2.fromScale(j - 0.012, 0), UDim2.fromScale(j + 0.012, 0)
					gh1.TextTransparency, gh2.TextTransparency = 0.2, 0.3
				else
					nm.Position = UDim2.fromScale(0, 0)
					gh1.TextTransparency, gh2.TextTransparency = 1, 1
				end
			end
		end




		TAGS.vampire = function(K, head, C1, C2)
			local frame, text, img, new, T, NAME = K.frame, K.text, K.img, K.new, K.T, K.NAME
			local bb = K.board(head, 11, 4.4, 4.0)
			local Wd, Hd = 11, 4.4
			local A = Wd / Hd
			local MY = Hd * 0.42
			local moonGlow = img(bb, { Image = T("glowui.png"), ImageColor3 = C1, ImageTransparency = 0.35, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, MY / Hd), Size = UDim2.fromScale(0.55, 1.1), ZIndex = 0 })
			local moon = frame(bb, { BackgroundTransparency = 0, BackgroundColor3 = W, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, MY / Hd), ZIndex = 1 })
			new("UICorner", { CornerRadius = UDim.new(1, 0) }, moon)
			new("UIGradient", { Rotation = 60, Color = CS({ CK(0, C2:Lerp(W, 0.25)), CK(0.5, C1), CK(1, C1:Lerp(BLACK, 0.55)) }) }, moon)
			local MD = 2.5

			local CELLS = { Vector2.new(0, 0), Vector2.new(256, 0), Vector2.new(0, 256), Vector2.new(256, 256) }
			local BW = 9.2
			local bat = img(bb, { Image = T("bat_fb.png"), ImageRectSize = Vector2.new(256, 256), ImageColor3 = Color3.fromRGB(26, 0, 6), AnchorPoint = Vector2.new(0.5, 0.46),
				Position = UDim2.fromScale(0.5, (MY + 0.15) / Hd), ZIndex = 2 })
			local box = frame(bb, { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, (MY + 0.55) / Hd), Size = UDim2.fromScale(0.66, 0.2) })
			local nm = text(box, { Size = UDim2.fromScale(1, 1), Text = NAME, FontFace = fam("GrenzeGotisch", Enum.FontWeight.Heavy), TextColor3 = W, ZIndex = 5 })
			new("UIGradient", { Rotation = 90, Color = CS({ CK(0, C2:Lerp(W, 0.5)), CK(0.5, C2), CK(1, C1) }) }, nm)
			new("UIStroke", { Color = Color3.fromRGB(8, 0, 2), Thickness = 2, Transparency = 0 }, nm)
			local ry = MY + 1.2
			local role = text(bb, { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, ry / Hd), Size = UDim2.fromScale(0.13, 0.09), Text = "STAFF",
				FontFace = fam("GrenzeGotisch", Enum.FontWeight.Bold), TextColor3 = C2:Lerp(W, 0.35), ZIndex = 5 })
			new("UIStroke", { Color = Color3.fromRGB(8, 0, 2), Thickness = 1.2, Transparency = 0.1 }, role)

			for sd = -1, 1, 2 do
				local f = frame(bb, { BackgroundTransparency = 0, BackgroundColor3 = Color3.fromRGB(245, 238, 225), AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.fromScale((Wd / 2 + sd * 0.95) / Wd, (ry - 0.16) / Hd),
					Size = UDim2.fromScale(0.08 / Wd, 0.36 / Hd), Rotation = -sd * 10, ZIndex = 5 })
				new("UIGradient", { Rotation = 90, Transparency = NS({ NK(0, 0), NK(0.75, 0.15), NK(1, 1) }) }, f)
				new("UICorner", { CornerRadius = UDim.new(0.5, 0) }, f)
			end
			local drips = {}
			for i = 1, 6 do drips[i] = K.dripper(bb, A, 0.22, 0.78, (MY + 0.55 + 0.38) / Hd, Color3.fromRGB(150, 0, 18), nil, 2.6) end
			local smalls = {}
			for i = 1, 3 do
				smalls[i] = { l = img(bb, { Image = T("bat_fb.png"), ImageRectSize = Vector2.new(256, 256), ImageColor3 = Color3.fromRGB(40, 0, 8), AnchorPoint = Vector2.new(0.5, 0.5), ZIndex = 3,
					ImageTransparency = 1 }), t0 = rnd(0, 6), dur = rnd(1.6, 2.4), sd = i % 2 == 0 and 1 or -1, y0 = rnd(0.25, 0.6), ph = rnd(0, 6) }
			end
			local LOOP = { 1, 2, 3, 4 }
			return function(t, dt, it)
				local rise = outQ(it / 0.6)
				local d = MD * (0.6 + 0.4 * rise)
				moon.Size = UDim2.fromScale(d / Wd, d / Hd)
				moon.BackgroundTransparency = 1 - rise
				moonGlow.ImageTransparency = 1 - 0.65 * rise * (0.85 + 0.15 * math.sin(t * 1.5))

				local open = outB((it - 0.35) / 0.4)
				local cell = (it < 0.35) and 3 or LOOP[math.floor(t * 4.5) % 4 + 1]
				bat.ImageRectOffset = CELLS[cell]
				local bw = BW * (0.25 + 0.75 * math.max(open, 0))
				bat.Size = UDim2.fromScale(bw / Wd, bw / Hd)
				bat.ImageTransparency = it < 0.3 and 1 or 0.05
				bat.Position = UDim2.fromScale(0.5, (MY + 0.15 + 0.08 * math.sin(t * 4.5 * math.pi / 2)) / Hd)
				nm.TextTransparency = 1 - c01((it - 0.5) / 0.35)
				role.TextTransparency = 1 - c01((it - 0.8) / 0.3)
				if it > 1 then for _, dd in ipairs(drips) do dd(t) end end
				for _, s in ipairs(smalls) do
					local a = (t - s.t0) % 7
					if a < s.dur then
						local u = a / s.dur
						s.l.ImageRectOffset = CELLS[math.floor(t * 12 + s.ph) % 4 + 1]
						s.l.Position = UDim2.fromScale(0.5 + s.sd * (0.05 + 0.55 * u), s.y0 - 0.35 * u + 0.05 * math.sin(u * 12))
						local sz = 0.7 * (0.6 + 0.4 * u)
						s.l.Size = UDim2.fromScale(sz / Wd, sz / Hd)
						s.l.ImageTransparency = c01((u - 0.7) / 0.3)
					else s.l.ImageTransparency = 1 end
				end
			end
		end




		TAGS.inferno = function(K, head, C1, C2)
			local frame, text, img, new, T, NAME = K.frame, K.text, K.img, K.new, K.T, K.NAME
			local bb = K.board(head, 10.5, 4.2, 4.2)
			local Wd, Hd = 10.5, 4.2
			local A = Wd / Hd
			local NY = Hd * 0.56

			img(bb, { Image = T("glowui.png"), ImageColor3 = Color3.fromRGB(70, 12, 0), ImageTransparency = 0.15, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromScale(1.0, 1.15), ZIndex = 0 })
			img(bb, { Image = T("glowui.png"), ImageColor3 = C1, ImageTransparency = 0.45, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.48), Size = UDim2.fromScale(0.8, 0.9), ZIndex = 0 })
			local flames = {}
			local function layer(n, hMin, hMax, col0, col1, z, wMul)
				for i = 1, n do
					local u = (i - 1) / (n - 1)
					local d = math.abs(u - 0.5) * 2
					for _ = 1, 2 do
						local f = img(bb, { Image = T("flame.png"), ImageColor3 = W, AnchorPoint = Vector2.new(0.5, 1), ZIndex = z })
						new("UIGradient", { Rotation = 90, Color = CS({ CK(0, col1), CK(0.6, col0), CK(1, col0:Lerp(BLACK, 0.2)) }), Transparency = NS({ NK(0, 0.15), NK(0.7, 0), NK(1, 0.3) }) }, f)
						flames[#flames + 1] = { f = f, x = 0.12 + u * 0.76 + rnd(-0.015, 0.015), h = (hMin + (hMax - hMin) * (1 - d * d)) * rnd(0.8, 1.15), w = wMul * rnd(0.85, 1.15),
							ph = rnd(0, 6), sp = rnd(7, 12), d = d }
					end
				end
			end
			layer(12, 1.0, 2.5, C1, C2, 1, 0.5)
			layer(10, 0.7, 1.6, C2, Color3.fromRGB(255, 245, 190), 2, 0.42)
			local box = frame(bb, { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, NY / Hd), Size = UDim2.fromScale(0.82, 0.26) })
			local nm = text(box, { Size = UDim2.fromScale(1, 1), Text = NAME, FontFace = fam("Sarpanch", Enum.FontWeight.Heavy), TextColor3 = W, ZIndex = 5 })
			local g = new("UIGradient", { Rotation = 90, Color = CS({ CK(0, W), CK(0.3, Color3.fromRGB(255, 244, 170)), CK(0.55, C2), CK(0.8, C1), CK(1, Color3.fromRGB(110, 10, 0)) }) }, nm)
			local st = new("UIStroke", { Color = Color3.fromRGB(30, 3, 0), Thickness = 2.6, Transparency = 0 }, nm)
			local flow = text(box, { Size = UDim2.fromScale(1, 1), Text = NAME, FontFace = fam("Sarpanch", Enum.FontWeight.Heavy), TextColor3 = Color3.fromRGB(255, 250, 215), ZIndex = 6 })
			local flowG = new("UIGradient", { Rotation = 12, Transparency = NS({ NK(0, 1), NK(0.4, 1), NK(0.5, 0.2), NK(0.6, 1), NK(1, 1) }) }, flow)

			local by = NY + 0.68
			local barGlow = img(bb, { Image = T("glowui.png"), ImageColor3 = C2, ImageTransparency = 0.35, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, by / Hd), Size = UDim2.fromScale(0.75, 0.22), ZIndex = 3 })
			local bar = frame(bb, { BackgroundTransparency = 0, BackgroundColor3 = W, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, by / Hd), Size = UDim2.fromScale(0.62, 0.11 / Hd), ZIndex = 4 })
			new("UICorner", { CornerRadius = UDim.new(1, 0) }, bar)
			local barG = new("UIGradient", { Color = CS({ CK(0, C1), CK(0.35, C2), CK(0.5, W), CK(0.65, C2), CK(1, C1) }), Transparency = NS({ NK(0, 1), NK(0.12, 0), NK(0.88, 0), NK(1, 1) }) }, bar)
			local role = text(bb, { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, (by + 0.36) / Hd), Size = UDim2.fromScale(0.2, 0.1), Text = "S T A F F",
				FontFace = fam("Sarpanch", Enum.FontWeight.Bold), TextColor3 = C2:Lerp(W, 0.3), ZIndex = 5 })
			new("UIStroke", { Color = Color3.fromRGB(30, 3, 0), Thickness = 1.4, Transparency = 0.1 }, role)
			local drips = {}
			for i = 1, 4 do drips[i] = K.dripper(bb, A, 0.25, 0.75, (by + 0.04) / Hd, C2:Lerp(W, 0.2), C1, 3.4) end
			local at = Vector3.new(0, 4.2 + 1.4, 0)
			K.emitterAt(at, { box = Vector3.new(8, 0.6, 0.3), Shape = Enum.ParticleEmitterShape.Box, Texture = T("spark.png"), Color = CS(C2:Lerp(W, 0.3), C1),
				Size = NS({ NK(0, 0.15), NK(1, 0) }), Speed = NR(2.5, 4.5), Acceleration = Vector3.new(0, 2, 0), SpreadAngle = Vector2.new(25, 25), Lifetime = NR(0.8, 1.4), Rate = 26, Brightness = 4,
				EmissionDirection = Enum.NormalId.Top })
			K.emitterAt(at + Vector3.new(0, 1, 0), { box = Vector3.new(7, 0.6, 0.3), Shape = Enum.ParticleEmitterShape.Box, Texture = T("smoke.png"), Color = CS(Color3.fromRGB(55, 45, 42)), LightEmission = 0,
				Size = NS({ NK(0, 0.5), NK(1, 1.4) }), Transparency = NS({ NK(0, 1), NK(0.3, 0.6), NK(1, 1) }), Speed = NR(0.8, 1.6), Lifetime = NR(1.4, 2.2), Rate = 6, EmissionDirection = Enum.NormalId.Top })
			return function(t, dt, it)
				local heat = outQ((it - 0.2) / 0.9)
				for _, fl in ipairs(flames) do
					local ign = outQ((it - fl.d * 0.5) / 0.3)
					local n = 0.72 + 0.16 * math.sin(t * fl.sp + fl.ph) + 0.12 * math.sin(t * fl.sp * 2.3 + fl.ph * 2)
					local h = fl.h * n * ign
					fl.f.Position = UDim2.fromScale(fl.x + 0.005 * math.sin(t * 4 + fl.ph), (NY + 0.35) / Hd)
					fl.f.Size = UDim2.fromScale((h * fl.w + 0.15) / Wd, (h + 0.35) / Hd)
					fl.f.Rotation = 5 * math.sin(t * 2.6 + fl.ph)
					fl.f.Visible = ign > 0.01
				end
				nm.Rotation = 0.5 * math.sin(t * 13) * math.sin(t * 3.1)
				g.Offset = Vector2.new(0, 0.85 * (1 - heat) + 0.05 * math.sin(t * 9))
				st.Color = Color3.fromRGB(30, 3, 0):Lerp(C1, 0.15 + 0.15 * math.sin(t * 2.2))
				local fk = (t * 0.45) % 1.6
				flowG.Offset = Vector2.new(-0.8 + fk * 1.25, 0)
				flow.TextTransparency = heat < 1 and 1 or 0
				local bi = c01((it - 0.5) / 0.4)
				barG.Offset = Vector2.new(0.08 * math.sin(t * 1.3), 0)
				bar.Size = UDim2.fromScale(0.62 * bi, 0.11 / Hd)
				barGlow.ImageTransparency = 1 - 0.65 * bi * (0.8 + 0.2 * math.sin(t * 3))
				role.TextTransparency = 1 - c01((it - 0.9) / 0.3)
				for _, d in ipairs(drips) do if bi >= 1 then d(t) end end
			end
		end



		TAGS.storm = function(K, head, C1, C2)
			local frame, text, img, seg, new, T, NAME = K.frame, K.text, K.img, K.seg, K.new, K.T, K.NAME
			local bb = K.board(head, 10, 3.4, 3.7)
			local Wd, Hd = 10, 3.4
			local strip = frame(bb, { BackgroundTransparency = 0.15, BackgroundColor3 = Color3.fromRGB(22, 27, 42), AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.36),
				Size = UDim2.fromScale(0.96, 0.46), ZIndex = 1 })
			new("UIGradient", { Transparency = NS({ NK(0, 1), NK(0.18, 0.1), NK(0.82, 0.1), NK(1, 1) }) }, strip)
			new("UICorner", { CornerRadius = UDim.new(0.5, 0) }, strip)
			local CLOUD = Color3.fromRGB(58, 68, 100)
			local clouds = {}
			for i = 1, 7 do
				clouds[i] = { l = img(bb, { Image = T("smoke.png"), ImageColor3 = CLOUD, ImageTransparency = 0, AnchorPoint = Vector2.new(0.5, 0.5), ZIndex = 1,
					Size = UDim2.fromScale(rnd(0.28, 0.4), rnd(0.75, 1.05)) }), x = 0.08 + (i - 1) / 6 * 0.84, y = (i % 2 == 0) and 0.22 or 0.48, ph = rnd(0, 6) }
			end
			local fglow = img(bb, { Image = T("glowui.png"), ImageColor3 = C1:Lerp(W, 0.5), ImageTransparency = 1, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.36), Size = UDim2.fromScale(1.2, 1.4), ZIndex = 0 })

			local NY, NH = 0.13, 0.46
			local halves = {}
			for hIdx = 0, 1 do
				local clip = frame(bb, { Position = UDim2.fromScale(0.1, NY + hIdx * NH / 2), Size = UDim2.fromScale(0.8, NH / 2), ClipsDescendants = true, ZIndex = 5 })
				local nm = text(clip, { Position = UDim2.fromScale(0, -hIdx), Size = UDim2.fromScale(1, 2), Text = NAME, FontFace = fam("Oswald", Enum.FontWeight.Bold), TextColor3 = W, ZIndex = 5 })
				new("UIGradient", { Rotation = 90, Color = CS({ CK(0, W), CK(0.55, Color3.fromRGB(205, 230, 255)), CK(1, C1) }) }, nm)
				new("UIStroke", { Color = Color3.fromRGB(8, 12, 28), Thickness = 1.6, Transparency = 0.1 }, nm)
				local fl = text(clip, { Position = UDim2.fromScale(0, -hIdx), Size = UDim2.fromScale(1, 2), Text = NAME, FontFace = fam("Oswald", Enum.FontWeight.Bold), TextColor3 = W, TextTransparency = 1, ZIndex = 6 })
				halves[hIdx + 1] = { clip = clip, nm = nm, fl = fl }
			end
			K.roleRow(bb, 0.7, 0.18, C1:Lerp(W, 0.35), fam("Oswald", Enum.FontWeight.Bold))
			local bolt, glow = {}, {}
			for i = 1, 12 do bolt[i] = { seg(bb, Wd, Hd, W, 0, 8) } glow[i] = { seg(bb, Wd, Hd, C1, 0.4, 7) } end
			K.emitterAt(Vector3.new(0, 3.7 + 3, 0), { box = Vector3.new(9, 0.2, 2), Shape = Enum.ParticleEmitterShape.Box, Texture = T("spark.png"), Color = CS(Color3.fromRGB(200, 220, 255)),
				Orientation = Enum.ParticleOrientation.VelocityParallel, Squash = NS(-3), Size = NS(0.07), Transparency = NS(0.35), Speed = NR(16, 20), SpreadAngle = Vector2.new(4, 4),
				Lifetime = NR(0.35, 0.45), Rate = 40, Brightness = 2, EmissionDirection = Enum.NormalId.Bottom })
			local nextZ, zT, mode = 3, -9, "split"
			local function lay(pts)
				for i = 1, 12 do
					local a, b = pts[i], pts[i + 1]
					if a and b then
						bolt[i][2](a.X, a.Y, b.X, b.Y, 0.07) glow[i][2](a.X, a.Y, b.X, b.Y, 0.24)
						bolt[i][1].Visible, glow[i][1].Visible = true, true
					else bolt[i][1].Visible, glow[i][1].Visible = false, false end
				end
			end
			local pts = {}
			local function across()
				local y = Hd * (NY + NH / 2)
				for i = 1, 13 do pts[i] = Vector2.new(Wd * (0.05 + (i - 1) / 12 * 0.9), y + ((i == 1 or i == 13) and 0 or rnd(-0.12, 0.12))) end
			end
			local function down()
				local x = Wd * rnd(0.4, 0.6)
				for i = 1, 9 do pts[i] = Vector2.new(x + ((i == 1) and 0 or rnd(-0.35, 0.35)), (i - 1) / 8 * Hd * (NY + NH * 0.6) - 0.6) end
				for i = 10, 13 do pts[i] = nil end
			end
			local lastIt = 99
			return function(t, dt, it)
				for _, c in ipairs(clouds) do c.l.Position = UDim2.fromScale(c.x + 0.025 * math.sin(t * 0.5 + c.ph), c.y + 0.03 * math.sin(t * 0.8 + c.ph)) end
				if it < lastIt then down() zT = t mode = "intro" end
				lastIt = it
				if t >= nextZ and it > 1 then across() zT = t mode = "split" nextZ = t + rnd(2.2, 3.4) end
				local a = t - zT
				local on = (a < 0.07) or (a > 0.1 and a < 0.2)
				if on then lay(pts) else for i = 1, 12 do bolt[i][1].Visible, glow[i][1].Visible = false, false end end
				local fl = c01(1 - a / 0.35)
				local shear = (mode == "split") and c01(1 - a / 0.45) or 0
				local nIn = mode == "intro" and c01((it - 0.05) / 0.05) or 1
				for hIdx, h in ipairs(halves) do
					local sd = hIdx == 1 and -1 or 1
					h.nm.Position = UDim2.fromScale(sd * 0.025 * shear, -(hIdx - 1) + (sd * 0.04 * shear))
					h.fl.Position = h.nm.Position
					h.nm.TextTransparency = 1 - nIn
					h.fl.TextTransparency = 1 - fl * 0.9 * nIn
				end
				fglow.ImageTransparency = 1 - fl * 0.6
				for _, c in ipairs(clouds) do c.l.ImageColor3 = CLOUD:Lerp(Color3.fromRGB(170, 190, 245), fl * 0.6) end
			end
		end




		TAGS.lightborn = function(K, head, C1, C2)
			local frame, text, img, new, T, NAME = K.frame, K.text, K.img, K.new, K.T, K.NAME
			local bb = K.board(head, 12, 4.2, 4.1)
			local Wd, Hd = 12, 4.2
			local OX, OY = Wd / 2, Hd * 0.52
			local GOLD = C1:Lerp(W, 0.2)
			img(bb, { Image = T("glowui.png"), ImageColor3 = C1, ImageTransparency = 0.35, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.42), Size = UDim2.fromScale(0.9, 1.1), ZIndex = 0 })
			local rays = {}
			local NRAYS = 17
			for i = 1, NRAYS do
				local u = (i - 1) / (NRAYS - 1) * 2 - 1
				local long = i % 2 == 1
				local f = frame(bb, { BackgroundTransparency = 0, BackgroundColor3 = long and GOLD or C2:Lerp(W, 0.5), AnchorPoint = Vector2.new(0.5, 0.5), ZIndex = 1 })
				new("UIGradient", { Transparency = NS({ NK(0, 0.15), NK(0.6, 0.6), NK(1, 1) }) }, f)
				rays[i] = { f = f, u = u, len = (long and 2.3 or 1.55) * (1 - 0.25 * math.abs(u)), w = long and 0.11 or 0.06, ph = rnd(0, 6) }
			end
			local wl = K.wingAt(bb, "wing_mx.png", Vector2.new(0.96, 0.63), UDim2.fromScale(2.05 / Wd, OY * 0.82 / Hd), 0.2, GOLD:Lerp(W, 0.35), 2)
			local wr = K.wingAt(bb, "wing_m.png", Vector2.new(0.04, 0.63), UDim2.fromScale((Wd - 2.05) / Wd, OY * 0.82 / Hd), 0.2, GOLD:Lerp(W, 0.35), 2)
			local box = frame(bb, { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.45), Size = UDim2.fromScale(0.6, 0.27) })
			local nm = text(box, { Size = UDim2.fromScale(1, 1), Text = NAME, FontFace = fam("Merriweather", Enum.FontWeight.Heavy), TextColor3 = W, ZIndex = 5 })
			new("UIGradient", { Rotation = 90, Color = CS({ CK(0, W), CK(0.55, Color3.fromRGB(255, 236, 170)), CK(1, C1) }) }, nm)
			new("UIStroke", { Color = C1:Lerp(BLACK, 0.55), Thickness = 1.4, Transparency = 0.15 }, nm)
