				Size = UDim2.fromScale(0.86, PH), ZIndex = 1 })
			new("UICorner", { CornerRadius = UDim.new(0.12, 0) }, plate)
			new("UIGradient", { Rotation = 90, Transparency = NS({ NK(0, 0.2), NK(0.5, 0.6), NK(1, 0.3) }) }, plate)
			frame(plate, { BackgroundTransparency = 0.2, BackgroundColor3 = W, Position = UDim2.fromScale(0.05, 0.04), Size = UDim2.fromScale(0.9, 0.035), ZIndex = 2 })
			local spikes = {}

			for _, x in ipairs({ 0.09, 0.115, 0.15, 0.21, 0.26, 0.33, 0.41, 0.47, 0.55, 0.61, 0.68, 0.74, 0.8, 0.85, 0.885, 0.91 }) do
				local e = math.abs(x - 0.5) * 2
				local sp = { x = x + rnd(-0.006, 0.006), len = (0.1 + 0.42 * e * e) * rnd(0.55, 1.2) / Hd, wd = rnd(0.008, 0.015), ph = rnd(0, 6), parts = {} }
