			end

			local icicles = {}
			local ICX = { 0.16, 0.19, 0.27, 0.34, 0.37, 0.45, 0.5, 0.53, 0.6, 0.67, 0.71, 0.79, 0.83 }
			for i, x in ipairs(ICX) do
				local mid = 1 - math.abs(x - 0.5) * 1.6
				local ic = { x = x + rnd(-0.008, 0.008), len = (0.05 + 0.17 * mid) * rnd(0.55, 1.25), wd = rnd(0.008, 0.015), ph = rnd(0, 6), parts = {} }
				for k = 1, 3 do
