				ic.drop = img(bb, { Image = T("drop.png"), ImageColor3 = C1:Lerp(W, 0.5), AnchorPoint = Vector2.new(0.5, 0.3), ImageTransparency = 1, ZIndex = 2 })
				ic.dt0 = rnd(0, 4)
				icicles[i] = ic
			end
			local box = frame(bb, { AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.fromScale(0.5, PY + 0.04), Size = UDim2.fromScale(0.78, PH - 0.08) })
			local nm = text(box, { Size = UDim2.fromScale(1, 1), Text = NAME, FontFace = fam("Michroma", Enum.FontWeight.Regular), TextColor3 = W, ZIndex = 5 })
			local g = new("UIGradient", { Rotation = 30, Color = CS({ CK(0, W), CK(0.4, Color3.fromRGB(225, 245, 255)), CK(0.55, W), CK(0.8, C1:Lerp(W, 0.6)), CK(1, W) }) }, nm)
			new("UIStroke", { Color = C1, Thickness = 1.8, Transparency = 0.35 }, nm)
			local frost = text(box, { Size = UDim2.fromScale(1, 1), Text = NAME, FontFace = fam("Michroma", Enum.FontWeight.Regular), TextColor3 = W, TextTransparency = 1, ZIndex = 6 })
			new("UIStroke", { Color = W, Thickness = 2.5, Transparency = 0.2 }, frost)
			local fg = new("UIGradient", { Transparency = NS({ NK(0, 0), NK(0.46, 0), NK(0.54, 1), NK(1, 1) }) }, frost)
			local rime = img(box, { Image = T("hex.png"), ImageColor3 = W, ImageTransparency = 1, ScaleType = Enum.ScaleType.Tile, TileSize = UDim2.fromScale(0.08, 0.3), Size = UDim2.fromScale(1.04, 1.1),
				Position = UDim2.fromScale(-0.02, -0.05), ZIndex = 7 })
			local rg = new("UIGradient", { Transparency = NS({ NK(0, 0), NK(0.46, 0), NK(0.54, 1), NK(1, 1) }) }, rime)
			local shards = {}
			for i = 1, 22 do
				shards[i] = { f = frame(bb, { BackgroundTransparency = 1, BackgroundColor3 = W:Lerp(C1, rnd(0, 0.4)), AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromScale(rnd(0.004, 0.007), rnd(0.05, 0.1)), ZIndex = 8 }) }
			end
			K.roleRow(bb, 0.74, 0.16, C1:Lerp(W, 0.35), fam("Michroma", Enum.FontWeight.Regular))
			K.emitterAt(Vector3.new(0, 3.8 + 0.2, 0), { box = Vector3.new(8, 1.8, 0.3), Shape = Enum.ParticleEmitterShape.Box, Texture = T("snow.png"), Color = CS(W, C2),
				Size = NS({ NK(0, 0.12), NK(1, 0.08) }), Speed = NR(0.3, 0.8), Acceleration = Vector3.new(0, -1.2, 0), Lifetime = NR(1.4, 2.2), Rate = 8, Brightness = 2,
				RotSpeed = NR(-60, 60), EmissionDirection = Enum.NormalId.Bottom })
			local CYC = 7

			local MASK_L = NS({ NK(0, 0), NK(0.46, 0), NK(0.54, 1), NK(1, 1) })
			local MASK_R = NS({ NK(0, 1), NK(0.46, 1), NK(0.54, 0), NK(1, 0) })
			local function shatter(sa)
				for _, s in ipairs(shards) do
					if sa >= 0 and sa < 0.75 then
						if not s.v then s.p = Vector2.new(rnd(0.12, 0.88), rnd(PY + 0.05, PY + PH - 0.05)) s.v = Vector2.new(rnd(-0.45, 0.45), rnd(-0.6, -0.1)) s.r0 = rnd(0, 180) s.r = rnd(-500, 500) end
						local p = s.p + s.v * sa + Vector2.new(0, 1.5 * sa * sa)
						s.f.Position = UDim2.fromScale(p.X, p.Y) s.f.Rotation = s.r0 + s.r * sa
						s.f.BackgroundTransparency = 0.05 + 0.95 * c01(sa / 0.75)
					else s.f.BackgroundTransparency = 1 s.v = nil end
				end
			end
			return function(t, dt, it)
				g.Offset = Vector2.new(math.sin(t * 0.5) * 0.3, 0)
				for _, sp in ipairs(spikes) do
					local L0 = sp.len * (0.92 + 0.08 * math.sin(t * 1.3 + sp.ph)) * outQ((it - 0.3) / 0.6)
					for k, f in ipairs(sp.parts) do f.Position, f.Size = UDim2.fromScale(sp.x, PY + 0.008), UDim2.fromScale(sp.wd * (1 - (k - 1) * 0.33), L0 * (0.45 + (k - 1) * 0.275)) end
				end
				local by = PY + PH
				for _, ic in ipairs(icicles) do
					local L0 = ic.len * (0.9 + 0.1 * math.sin(t * 0.7 + ic.ph)) * outQ((it - 0.6) / 0.8)
					for k, f in ipairs(ic.parts) do
						local w = ic.wd * (1 - (k - 1) * 0.33)
						f.Position, f.Size = UDim2.fromScale(ic.x, by), UDim2.fromScale(w, L0 * (0.45 + (k - 1) * 0.275))
					end
					local a = (t - ic.dt0) % 4
					local fy = by + L0 + 1.4 * a * a
					ic.drop.Position, ic.drop.Size = UDim2.fromScale(ic.x, fy), UDim2.fromScale(0.01, 0.01 * A * 1.4)
					ic.drop.ImageTransparency = a < 0.55 and (0.1 + 0.9 * c01((fy - 0.85) / 0.2)) or 1
				end

				local creep, held, sa
				if it < 1.6 then
					creep = 1 - c01((it - 0.4) / 1.0) held = true sa = -1
					fg.Transparency = MASK_R rg.Transparency = MASK_R
					fg.Offset, rg.Offset = Vector2.new(-0.5 + (1 - creep), 0), Vector2.new(-0.5 + (1 - creep), 0)
				else
					fg.Transparency = MASK_L rg.Transparency = MASK_L
					local c = (t % CYC)
					creep = c01(c / 1.2) held = c < 2.0 sa = c - 2.0
					fg.Offset, rg.Offset = Vector2.new(creep - 0.5, 0), Vector2.new(creep - 0.5, 0)
				end
				frost.TextTransparency = held and 0.15 or 1
				rime.ImageTransparency = held and 0.45 or 1
				shatter(sa)
			end
		end



		TAGS.mage = function(K, head, C1, C2)
			local frame, text, img, seg, new, T, NAME = K.frame, K.text, K.img, K.seg, K.new, K.T, K.NAME
			local bb = K.board(head, 10, 3.6, 3.8)
			local Wd, Hd = 10, 3.6
			local CX, CY = Wd / 2, Hd * 0.34
			local ring = img(bb, { Image = T("runering.png"), ImageColor3 = C1, ImageTransparency = 0.25, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.34), Size = UDim2.fromScale(0.34, 0.34), ZIndex = 1 })
			new("UIAspectRatioConstraint", { AspectRatio = 1, DominantAxis = Enum.DominantAxis.Width }, ring)
			img(bb, { Image = T("glowui.png"), ImageColor3 = C1, ImageTransparency = 0.45, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.34), Size = UDim2.fromScale(1, 1), ZIndex = 0 })

			local band = img(bb, { Image = T("runering.png"), ImageColor3 = C2:Lerp(W, 0.2), ImageTransparency = 0.2, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.36),
				Size = UDim2.fromScale(0.98, 0.5), ZIndex = 2 })
			local bandG = new("UIGradient", { Transparency = NS({ NK(0, 0.6), NK(0.45, 0.6), NK(0.5, 0), NK(0.55, 0.6), NK(1, 0.6) }) }, band)
			local RX, RY, NSEG = 4.9, 0.95, 36
			local dash = {}
			for i = 1, NSEG do dash[i] = { seg(bb, Wd, Hd, C2, 0, 2) } end
			local glyphs = {}
			for i = 1, 6 do
				local cell = (i * 3) % 16
				glyphs[i] = img(bb, { Image = T("glyphs.png"), ImageRectSize = Vector2.new(128, 128), ImageRectOffset = Vector2.new((cell % 4) * 128, math.floor(cell / 4) * 128),
					ImageColor3 = C2:Lerp(W, 0.4), AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromScale(0.05, 0.14), ZIndex = 2 })
			end
			local box = frame(bb, { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.34), Size = UDim2.fromScale(0.7, 0.3) })
			local nm = text(box, { Size = UDim2.fromScale(1, 1), Text = NAME, FontFace = fam("Fondamento", Enum.FontWeight.Regular), TextColor3 = W, ZIndex = 5 })
			new("UIGradient", { Color = CS({ CK(0, C2:Lerp(W, 0.3)), CK(0.5, W), CK(1, C1:Lerp(W, 0.4)) }) }, nm)
			new("UIStroke", { Color = C1:Lerp(BLACK, 0.6), Thickness = 1.6, Transparency = 0.1 }, nm)
			local role = text(bb, { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.75), Size = UDim2.fromScale(0.24, 0.13), Text = "S T A F F", RichText = true,
				FontFace = fam("RobotoMono", Enum.FontWeight.Bold), TextColor3 = W, ZIndex = 6 })
			K.emitterAt(Vector3.new(0, 3.8 + 0.6, 0), { box = Vector3.new(9, 2.4, 1), Shape = Enum.ParticleEmitterShape.Box, Texture = T("star.png"), Color = CS(C2, C1),
				Size = NS({ NK(0, 0), NK(0.5, 0.12), NK(1, 0) }), Speed = NR(0.2, 0.5), Lifetime = NR(1, 1.8), Rate = 14, Brightness = 3, RotSpeed = NR(-120, 120) })
			local WORD, JUNK = "S T A F F", "#%*+=?@$/"
			local hexC = string.format("#%02X%02X%02X", math.floor(C2.R * 255), math.floor(C2.G * 255), math.floor(C2.B * 255))
			local function ep(a) return Vector2.new(CX + RX * math.cos(a), CY + 0.08 * Hd + RY * math.sin(a)) end
			return function(t, dt, it)
				local draw = c01(it / 0.8)
				ring.Rotation = t * 18
				bandG.Offset = Vector2.new(((t * 0.3) % 2) - 1, 0)
				band.ImageTransparency = 1 - 0.8 * draw
				for i, d in ipairs(dash) do
					local a0 = (i - 1) / NSEG * math.pi * 2 + t * 0.6
					local a1 = a0 + math.pi * 2 / NSEG * 0.55
					local p0, p1 = ep(a0), ep(a1)
					d[2](p0.X, p0.Y, p1.X, p1.Y, 0.05)
					local front = math.sin(a0 + 0.05) > 0
					d[1].ZIndex = front and 6 or 2
					d[1].BackgroundTransparency = front and 0 or 0.55
					d[1].Visible = (i - 1) / NSEG < draw
				end
				for i, gl in ipairs(glyphs) do
					local a = t * 0.8 + (i - 1) / 6 * math.pi * 2
					local p = ep(a)
					local front = math.sin(a) > 0
					gl.Position = UDim2.fromScale(p.X / Wd, (p.Y - 0.05) / Hd)
					gl.ZIndex = front and 7 or 2
					gl.ImageTransparency = draw < 1 and 1 or (front and 0 or 0.55)
					gl.Rotation = math.sin(t * 2 + i) * 15
				end
				nm.TextTransparency = 1 - c01((it - 0.4) / 0.4)
				local c = (it < 5) and it or (t % 5)
				local done = math.floor(c01((c - 0.6) / 1.0) * #WORD + 0.5)
				local s = {}
				for k = 1, #WORD do
					local ch = WORD:sub(k, k)
					if k <= done or ch == " " then s[k] = ch else local j = math.random(1, #JUNK) s[k] = '<font color="' .. hexC .. '">' .. JUNK:sub(j, j) .. "</font>" end
				end
				role.Text = table.concat(s)
			end
		end




		TH.headTag = function(L, id, C1, C2, o)
			local T = { t = 0, it = 0, was = true }
			local D = TAGS[id]
			local head = L.ch.head
			if not L.dead and type(D) == "function" and head then
				local K = kit(L)
				local ok, up = pcall(D, K, head, C1, C2)
				if ok and type(up) == "function" and K.bb then
					T.bb, T.bespoke = K.bb, true
					local warned = false
					T.step = function(dt)
						local bb, h = K.bb, L.ch.head
						if h and bb.Adornee ~= h then bb.Adornee = h T.it = 0 end
						local en = bb.Enabled
						if en and not T.was then T.it = 0 end
						T.was = en
						T.t += dt
						T.it += dt


						local rt = L.ch.hrp
						if id ~= "seraph" and h and rt and h.Parent and rt.Parent then
							T.emoT = L.ch.emote and 0.8 or math.max(0, (T.emoT or 0) - dt)
							local loc = rt.CFrame:PointToObjectSpace(h.Position)
							local want = Vector3.zero
							if T.emoT > 0 and T.rest then want = rt.CFrame:VectorToWorldSpace(T.rest - loc)
							else T.rest = T.rest and T.rest:Lerp(loc, math.clamp(dt * 4, 0, 1)) or loc end
							T.off = (T.off or Vector3.zero):Lerp(want, math.clamp(dt * 12, 0, 1))
							if (T.off - bb.StudsOffsetWorldSpace).Magnitude > 0.003 then bb.StudsOffsetWorldSpace = T.off end
						end
						if h and h.Parent and #K.ems > 0 then
							local cam = workspace.CurrentCamera
							local yaw = cam and select(2, cam.CFrame:ToEulerAnglesYXZ()) or 0
							local turn = CFrame.Angles(0, yaw, 0)
							local so = T.off or Vector3.zero
							for _, e in ipairs(K.ems) do e.p.CFrame = CFrame.new(h.Position + e.off + so) * turn end
						end
						if not en then return end
						local ok2, err = pcall(up, T.t, dt, T.it)
						if not ok2 and not warned then warned = true warn("tag " .. id .. ": " .. tostring(err)) end
					end
					return T
				end
				K.drop()
				warn("tag " .. id .. ": " .. tostring(up))
			end

			local g = L.tag(o or { c1 = C1, c2 = C2 })
			g.bb.Adornee = head
			T.bb = g.bb
			T.step = function(dt)
				T.t += dt
				if L.ch.head and g.bb.Adornee ~= L.ch.head then g.bb.Adornee = L.ch.head end
				g.grad.Offset = Vector2.new(((T.t * 0.2) % 2) - 1, 0)
				g.sweep(T.t, 3, 0.7)
			end
			return T
		end
	end)()
end
end)()
end
