				li.Parent = part
				it = { part = part, light = li, shape = l.sh, seed = math.random() * 10 }
				rig.inst[l] = it
				part.CFrame = cfAt(rig, l, now()) or oldCF or CFrame.new()
				part.Parent = rig.folder
			end
			local col = color3(l)
			it.col = col
			local part, li = it.part, it.light
			local ghost = (not l.bu) and L.ghostOn and rig == L.me
			setIf(part, "Size", l.sh == "Panel" and Vector3.new(l.sz, l.sz, 0.1) or (ghost and Vector3.new(0.5, 0.5, 0.5) or Vector3.new(0.8, 0.8, 0.8)))
			setIf(part, "Transparency", l.bu and (l.sh == "Panel" and 0.3 or 0) or (ghost and 0.75 or 1))
			setIf(part, "Color", col)
			setIf(li, "Color", col)
			setIf(li, "Brightness", l.b)
			setIf(li, "Range", l.r)
			setIf(li, "Shadows", l.sd)
			if l.sh ~= "Point" then setIf(li, "Angle", l.a) end
			local cf = cfAt(rig, l, now())
			if cf then part.CFrame = cf end

			if l.be and l.sh ~= "Point" then
				if not it.beam then
					local a0, a1 = Instance.new("Attachment"), Instance.new("Attachment")
					a0.Parent, a1.Parent = part, part
					local bm = Instance.new("Beam")
					bm.Attachment0, bm.Attachment1 = a0, a1
					bm.FaceCamera, bm.Segments, bm.LightEmission, bm.LightInfluence = true, 1, 1, 0
					bm.Transparency = NumberSequence.new(0.72, 1)
					bm.Parent = part
					it.beam, it.a1 = bm, a1
				end
				local len = math.max(l.r, 2) * 0.9
				setIf(it.a1, "CFrame", CFrame.new(0, 0, -len))
				setIf(it.beam, "Width0", l.sh == "Panel" and l.sz or 0.4)
				setIf(it.beam, "Width1", math.min(2 * len * math.tan(math.rad(math.min(l.a, 170) / 2)), 80))
				it.beam.Color = ColorSequence.new(col)
			elseif it.beam then
				pcall(function() it.beam:Destroy(); it.a1:Destroy() end)
				for _, a in ipairs(part:GetChildren()) do if a:IsA("Attachment") then a:Destroy() end end
				it.beam, it.a1 = nil, nil
			end
			if regiz and rig == L.me and L.selected() == l then pcall(L.gizmo, regiz) end
			return it
		end

		local function setLights(rig, list)
			local old = rig.lights
			rig.lights = list
			for i, l in ipairs(list) do
				local o = old[i]


				if o and o ~= l and rig.inst[o] and not rig.inst[l] and not table.find(list, o) then rig.inst[l] = rig.inst[o]; rig.inst[o] = nil end
				pcall(render, rig, l, i)
			end
			for l, it in pairs(rig.inst) do
				if not table.find(list, l) then dropInst(it); rig.inst[l] = nil end
			end
			L.ensureTick()
		end
		L._setLights = setLights
		local function dropRig(rig)
			if not rig then return end
			for _, it in pairs(rig.inst) do dropInst(it) end
			rig.inst, rig.lights = {}, {}
			pcall(function() rig.folder:Destroy() end)
		end


		local function tickRig(rig, t)
			for _, l in ipairs(rig.lights) do
				local it = rig.inst[l]
				if it then
					local cf = cfAt(rig, l, t)
					if cf and ((it.part.Position - cf.Position).Magnitude > 1e-3 or it.part.CFrame.LookVector:Dot(cf.LookVector) < 0.99999) then it.part.CFrame = cf end
					if l.an ~= "None" then
						local m, r, g, b = L.animAt(l.an, t, l.as, it.seed)
						setIf(it.light, "Brightness", l.b * m)
						local col = r and Color3.fromRGB(r, g, b) or it.col
						if it.light.Color ~= col then
							it.light.Color = col
							it.part.Color = col
							if it.beam then it.beam.Color = ColorSequence.new(col) end
						end
						if l.bu then setIf(it.part, "Transparency", (l.sh == "Panel" and 0.3 or 0) + (1 - m) * 0.6) end
					end
				end
			end
		end
		local watchT = 0
		L.ensureTick = function()
			if L._conn then return end
			L._conn = RunS.Heartbeat:Connect(function(dt)
				local t = now()
				if L.me then pcall(tickRig, L.me, t) end
				for _, rig in pairs(L.peers) do pcall(tickRig, rig, t) end
				watchT += dt
				if watchT >= 1 then
					watchT = 0
					local AS = System.AvatarSync
					for uid in pairs(L.peers) do
						if not (AS and AS.enabled) or not PS:GetPlayerByUserId(uid) then L.dropPeer(uid) end
					end
					if L.giz and L.giz.part and not L.giz.part.Parent then L.gizmo(nil) end
					if not next(L.peers) and not (L.me and #L.me.lights > 0) then L._conn:Disconnect(); L._conn = nil end
				end
			end)
		end


		L.peers = {}
		L.sel = 0
		local function mine()
			if not L.me or not L.me.folder.Parent then
				if L.me then dropRig(L.me) end
				L.me = newRig("RCLights_" .. Player.Name, nil)
			end
			return L.me
		end
		L.list = function() return L.me and L.me.lights or {} end
		L.selected = function() local list = L.list(); return list[L.sel], L.sel end
		L.select = function(i)
			local n = #L.list()
			L.sel = (n == 0) and 0 or math.clamp(tonumber(i) or 1, 1, n)
			if L.giz then L.gizmo(L.giz.mode) end
			if L.uiRefresh then pcall(L.uiRefresh) end
		end

		L.snapshot = function()
			local s = {}
			for _, l in ipairs(L.list()) do
				local c = L.clean(l)
				if c then c.sub = l.sub; s[#s + 1] = c end
			end
			return { lights = s, sel = L.sel }
		end
		L.restore = function(snap)
			if type(snap) ~= "table" then return end
			local list = {}
			for _, l in ipairs(type(snap.lights) == "table" and snap.lights or {}) do
				local c = L.clean(l)
				if c then c.sub = type(l) == "table" and l.sub or nil; list[#list + 1] = c end
			end
			setLights(mine(), list)
			L.presetName = nil
			L.sel = math.clamp(tonumber(snap.sel) or 0, #list > 0 and 1 or 0, #list)
			if L.giz then L.gizmo(L.giz.mode) end
			L.changed()
			if L.uiRefresh then pcall(L.uiRefresh) end
		end


		local lastPush, lastKey = 0, nil
		L.pushUndo = function(softKey)
			L.presetName = nil
			local t = os.clock()
			if softKey ~= nil and softKey == lastKey and t - lastPush < 0.8 then lastPush = t; return end
			lastPush, lastKey = t, softKey
			if System._editPush then pcall(System._editPush, { lr = true }) end
		end

		L.changed = function()
			local AS = System.AvatarSync
			if AS and AS.enabled and Function.AvatarSyncPublish then pcall(Function.AvatarSyncPublish, true, AS.forceClear == true) end
		end
		L.wire = function()
			local list = L.list()
			if #list == 0 then return nil end
			local w = {}
			for i, l in ipairs(list) do w[i] = L.toWire(l) end
			return w
		end
		local function subjectCF(sub)
			local r = L.subjectRoot({ uid = nil }, { sub = sub })
			if not r then return nil end
			local lv = r.CFrame.LookVector
			return r.Position, math.deg(math.atan2(-lv.X, -lv.Z))
		end
		L.subject = nil
		L.spawn = function()
			local list = L.list()
			if #list >= L.MAX then return false, "Up to " .. L.MAX .. " lights" end
			local pos = subjectCF(L.subject)
			if not pos then return false, "No character" end

			local cam = workspace.CurrentCamera
			local toCam = cam and (cam.CFrame.Position - pos) or Vector3.new(0, 0, 1)
			local ag = (Vector3.new(toCam.X, 0, toCam.Z).Magnitude > 0.1) and math.deg(math.atan2(toCam.Z, toCam.X)) or 90
			local l = L.clean({ sh = "Spot", k = 5600, b = 3, r = 24, a = 60, ag = ag, ds = 6, ht = 2 })
			return L.add(l)
		end
		L.add = function(l)
			local list = L.list()
			if not l then return false end
			if #list >= L.MAX then return false, "Up to " .. L.MAX .. " lights" end
			L.pushUndo()
			l.sub = L.subject
			local nl = {}
			for i, x in ipairs(list) do nl[i] = x end
			nl[#nl + 1] = l
			setLights(mine(), nl)
			L.select(#nl)
			L.changed()
			return true
		end
		L.spawnRole = function(name)
			local pos, yaw = subjectCF(L.subject)
			if not pos then return false, "No character" end
			local l = L.roleLight(name, yaw)
			if not l then return false, "Unknown role" end
			return L.add(l)
		end
		L.applyPreset = function(name)
			local pos, yaw = subjectCF(L.subject)
			if not pos then return false, "No character" end
			local list = L.presetRig(name, yaw)
			if not list then return false, "Unknown preset" end
			for _, l in ipairs(list) do l.sub = L.subject end
			L.pushUndo()
			L.presetName = name
			setLights(mine(), list)
			L.select(1)
			L.changed()
			return true
		end

		L.edit = function(fn, i, softKey)
			local list = L.list()
			i = i or L.sel
			local l = list[i]
			if not l then return false end
			L.pushUndo(softKey)
			pcall(fn, l)
			local c = L.clean(l)
			if not c then return false end
			for k in pairs(l) do if k ~= "sub" then l[k] = nil end end
			for k, v in pairs(c) do l[k] = v end
			pcall(render, mine(), l, i)
			L.ensureTick()
			L.changed()
			return true
		end

		local function keepAngle(l, on, speed)
			local t = now()
			local a = L.angleAt(l, t)
			l.o, l.os = on, speed
			l.ag = (a - (on and t * speed or 0)) % 360
		end
		L.setOrbit = function(on)
			return L.edit(function(l) keepAngle(l, on == true, l.os) end)
		end
		L.setOrbitSpeed = function(v)
			return L.edit(function(l) keepAngle(l, l.o, L.num(v, -90, 90, l.os)) end, nil, "Orbit speed")
		end

		L.place = function(ag, ds, ht, key)
			return L.edit(function(l)
				if ag then l.ag = (ag - (l.o and now() * l.os or 0)) % 360 end
				if ds then l.ds = ds end
				if ht then l.ht = ht end
			end, nil, key or "Placement")
		end
		L.nudge = function(kind)
			if not L.NUDGE[kind] then return false end
			return L.edit(function(l) l.ag, l.ds, l.ht = L.nudgeValues(l, kind) end)
		end
		L.setAim = function(on)
			return L.edit(function(l)
				local it = L.me.inst[l]
				if not on and it then
					local lv = it.part.CFrame.LookVector
					l.d = { L.yawPitchFromDir(lv.X, lv.Y, lv.Z) }
				end
				l.ai = on
			end)
		end
		L.duplicate = function()
			local l = L.selected()
			local list = L.list()
			if not l or #list >= L.MAX then return false end
			local c = L.clean(l)
			if not c then return false end
			L.pushUndo()
			c.sub = l.sub
			c.ag = L.dupOffset(l)
			local nl = {}
			for i, x in ipairs(list) do nl[i] = x end
			nl[#nl + 1] = c
			setLights(mine(), nl)
			L.select(#nl)
			L.changed()
			return true
		end
		L.delete = function(all)
			local list = L.list()
			if #list == 0 then return false end
			L.pushUndo()
			local nl = {}
			if not all then for i, x in ipairs(list) do if i ~= L.sel then nl[#nl + 1] = x end end end
			setLights(mine(), nl)
			if #nl == 0 then L.gizmo(nil) end
			L.select(math.min(L.sel, #nl))
			L.changed()
			return true
		end


		L.giz = nil
		L.gizmo = function(mode)
			if L.giz then
				for _, c in ipairs(L.giz.conns) do pcall(function() c:Disconnect() end) end
				for _, o in ipairs(L.giz.objs) do pcall(function() o:Destroy() end) end
				L.giz = nil
			end
			local l = L.selected()
			local it = l and L.me and L.me.inst[l]
			if not (mode and it) then if L.uiRefresh then pcall(L.uiRefresh) end; return end
			local host = (Player and Player:FindFirstChildOfClass("PlayerGui")) or ((gethui and gethui()) or game:GetService("CoreGui"))
			local g = { mode = mode, part = it.part, conns = {}, objs = {} }
			L.giz = g
			local box = Instance.new("SelectionBox")
			box.Adornee, box.LineThickness, box.Color3, box.SurfaceTransparency = it.part, 0.04, Color3.fromRGB(255, 200, 80), 1
			box.Parent = host
			g.objs[#g.objs + 1] = box
			local h
			if mode == "Rotate" then
				h = Instance.new("ArcHandles")

				h.Axes = Axes.new(Enum.Axis.X, Enum.Axis.Y)
			else
				h = Instance.new("Handles")
				h.Style = Enum.HandlesStyle.Movement
				h.Faces = Faces.new(Enum.NormalId.Right, Enum.NormalId.Left, Enum.NormalId.Top, Enum.NormalId.Bottom, Enum.NormalId.Front, Enum.NormalId.Back)
			end
			h.Color3 = Color3.fromRGB(255, 200, 80)
			h.Adornee = it.part
			h.Parent = host
			g.objs[#g.objs + 1] = h
			local H0
			local function finish()
				if not H0 then return end
				H0 = nil
				L.changed()
			end
			table.insert(g.conns, h.MouseButton1Down:Connect(function()
				local cur = L.selected()
				if cur ~= l then return end
				L.pushUndo()

				if mode ~= "Rotate" and l.o then keepAngle(l, false, l.os) end
				if mode == "Rotate" and l.ai then local lv = it.part.CFrame.LookVector; l.d = { L.yawPitchFromDir(lv.X, lv.Y, lv.Z) }; l.ai = false end
				H0 = it.part.CFrame
				if L.uiRefresh then pcall(L.uiRefresh) end
			end))
			if mode == "Rotate" then
				table.insert(g.conns, h.MouseDrag:Connect(function(axis, ang)
					if not H0 then return end
					local lv = (H0 * CFrame.fromAxisAngle(Vector3.FromAxis(axis), ang or 0)).LookVector
					l.d = { L.yawPitchFromDir(lv.X, lv.Y, lv.Z) }
				end))
			else
				table.insert(g.conns, h.MouseDrag:Connect(function(face, dist)
					if not H0 then return end
					local p = H0.Position + H0:VectorToWorldSpace(Vector3.FromNormalId(face) * (dist or 0))
					local root = L.subjectRoot(L.me, l)
					if not root then return end
					local dv = p - root.Position
					local ag, ds, ht = L.placeFrom(dv.X, dv.Y, dv.Z, now(), l)
					l.ag, l.ds, l.ht = ag, math.clamp(ds, 0.5, 60), math.clamp(ht, -10, 30)
				end))
			end
			table.insert(g.conns, h.MouseButton1Up:Connect(finish))

			table.insert(g.conns, game:GetService("UserInputService").InputEnded:Connect(function(io)
				if io.UserInputType == Enum.UserInputType.MouseButton1 or io.UserInputType == Enum.UserInputType.Touch then finish() end
			end))
			if L.uiRefresh then pcall(L.uiRefresh) end
		end





		L.dragging, L.drag, L.PICK_PX = false, nil, 36

		L.pick = function(pos)
			local cam = workspace.CurrentCamera
			if not (cam and L.me) or (typeof(pos) ~= "Vector3" and typeof(pos) ~= "Vector2") then return nil end
			local inset = game:GetService("GuiService"):GetGuiInset()
			local px, py = pos.X + inset.X, pos.Y + inset.Y
			local best, bd
			for i, l in ipairs(L.me.lights) do
				local it = L.me.inst[l]
				if it and it.part.Parent and L.pickable(l, L.ghostOn) then
					local v, on = cam:WorldToViewportPoint(it.part.Position)
					if on and v.Z > 0 then
						local d = math.sqrt((v.X - px) ^ 2 + (v.Y - py) ^ 2)
						if d <= L.PICK_PX and (not bd or d < bd) then best, bd = i, d end
					end
				end
			end
			return best
		end
		L.endDrag = function()
			local d = L.drag
			if not d then return end
			L.drag, L.dragging = nil, false
			if d.camType then pcall(function() d.cam.CameraType = d.camType end) end
			if d.pending then if L.uiRefresh then pcall(L.uiRefresh) end; return end
			local i = table.find(L.list(), d.l)
			if i then pcall(render, mine(), d.l, i) end
			L.changed()
			if L.uiRefresh then pcall(L.uiRefresh) end
		end
		local startDrag
		startDrag = function(i, io)
			L.select(i)
			local l = L.list()[i]
			if not l then return end

			local d = { l = l, input = io, touch = io.UserInputType == Enum.UserInputType.Touch, last = Vector2.new(io.Position.X, io.Position.Y), pending = true }
			d.start = d.last
			local cam = workspace.CurrentCamera
			if cam and cam.CameraType ~= Enum.CameraType.Scriptable then d.cam, d.camType = cam, cam.CameraType; cam.CameraType = Enum.CameraType.Scriptable end
			L.drag, L.dragging = d, true
			if L.uiRefresh then pcall(L.uiRefresh) end
		end
		L.worldEdit = function(on)
			local CAS = game:GetService("ContextActionService")
			if L._we then for _, c in ipairs(L._we) do pcall(function() c:Disconnect() end) end; L._we = nil end
			pcall(function() CAS:UnbindAction("RCLightWheel") end)
			L.endDrag()
			if not on then return end
			local UIS = game:GetService("UserInputService")
			local MB1, TOUCH = Enum.UserInputType.MouseButton1, Enum.UserInputType.Touch
			local c = {}
			L._we = c
			c[1] = UIS.InputBegan:Connect(function(io, gp)
				if gp or L.dragging or (io.UserInputType ~= MB1 and io.UserInputType ~= TOUCH) then return end
				local i = L.pick(io.Position)
				if i then startDrag(i, io) end
			end)
			c[2] = UIS.InputChanged:Connect(function(io)
				local d = L.drag
				if not d then return end
				if (d.touch and io ~= d.input) or (not d.touch and io.UserInputType ~= Enum.UserInputType.MouseMovement) then return end
				if not table.find(L.list(), d.l) then return L.endDrag() end
				if d.pending then
					if not L.dragMoved(d.start.X, d.start.Y, io.Position.X, io.Position.Y) then return end
					d.pending = false
					L.pushUndo()
					if d.l.o then keepAngle(d.l, false, d.l.os) end
				end
				local dx, dy = io.Position.X - d.last.X, io.Position.Y - d.last.Y
				d.last = Vector2.new(io.Position.X, io.Position.Y)


				local cam, a = workspace.CurrentCamera, math.rad(L.angleAt(d.l, now()))
				local side = cam and cam.CFrame.RightVector:Dot(Vector3.new(-math.sin(a), 0, math.cos(a))) or 0
				if math.abs(side) > 0.15 then d.sign = side > 0 and 1 or -1 end
				d.l.ag = (d.l.ag + (d.sign or 1) * dx * 0.4) % 360
				d.l.ht = math.clamp(d.l.ht - dy * 0.03, -10, 30)
			end)
			c[3] = UIS.InputEnded:Connect(function(io)
				local d = L.drag
				if not d then return end
				if (d.touch and io == d.input) or (not d.touch and io.UserInputType == MB1) then L.endDrag() end
			end)

			c[4] = UIS.WindowFocusReleased:Connect(function() L.endDrag() end)
			pcall(function()
				CAS:BindActionAtPriority("RCLightWheel", function(_, _, io)
					local i = io and L.pick(io.Position)
					if not i then return Enum.ContextActionResult.Pass end
					if L.sel ~= i then L.select(i) end
					L.edit(function(l) l.ds = math.clamp(l.ds - (io.Position.Z > 0 and 0.5 or -0.5), 0.5, 60) end, i)
					if L.uiRefresh then pcall(L.uiRefresh) end
					return Enum.ContextActionResult.Sink
				end, false, 3000, Enum.UserInputType.MouseWheel)
			end)
		end

		L.ghostOn = false
		L.ghost = function(on)
			on = on == true
			if L.ghostOn == on then return end
			L.ghostOn = on
			if L.me then for i, l in ipairs(L.me.lights) do pcall(render, L.me, l, i) end end
		end





		L.view = nil
		local function assign(l, src) for k in pairs(l) do if k ~= "sub" and src[k] == nil then l[k] = nil end end; for k, v in pairs(src) do l[k] = v end end
		local function viewHide(l, hidden, it)
			it = it or (L.me and L.me.inst[l])
			if not it then return end
			if hidden and L.view then L.view.it = it end
			pcall(function() it.part.LocalTransparencyModifier = hidden and 1 or 0 end)
			if it.beam then pcall(function() it.beam.Enabled = not hidden end) end
		end

		L.viewStart = function(i)
			if L.view then L.viewEnd(false) end
			local l = L.list()[i or L.sel]
			local it = l and L.me and L.me.inst[l]
			local orig = l and L.clean(l)
			if not (it and it.part.Parent and orig) then return nil end
			L.endDrag()
			if L.giz then pcall(L.gizmo, nil) end
			L.view = { l = l, orig = orig, pub = 0 }
			viewHide(l, true)
			return it.part.CFrame
		end

		L.viewApply = function(cf)
			local v = L.view
			if not (v and typeof(cf) == "CFrame" and table.find(L.list(), v.l)) then return false end
			local root = L.subjectRoot(L.me, v.l)
			if not root then return false end
			local dv, lv = cf.Position - root.Position, cf.LookVector
			local ag, ds, ht, yaw, pitch = L.viewPlace(dv.X, dv.Y, dv.Z, lv.X, lv.Y, lv.Z)
			local l = v.l
